let chatSuppressNextChatMessageAnimations = false;
/** 编辑落盘后下一轮 render 强制重建该行（避免 DOM 复用仍显示旧文案） */
let chatForceRebuildMsgIdx = -1;
/** 仅助手本轮新回复落盘后：允许最新一条分段入场动画（一次性，render 后清除） */
let chatAnimateLatestAssistantReply = false;
/** 红包详情弹层关层延迟 hidden，须在再次打开前 clearTimeout */
let redpackPeekCloseTimer = 0;
/** 用于局部更新：下一次 render 保留滚动位置，不强制滚到底（距底锚定） */
let chatPreserveScrollAnchorFromBottom = null;

/** GIF/表情包解码撑高后反复贴底，截止时间戳（ms） */
let chatStickBottomFollowUpUntil = 0;
/** @type {ResizeObserver | null} */
let chatLastMsgResizeRo = null;
/** 与 {@link renderChatMessages} 滚动锚定配合：`maskId+threadId+壳(im/offline)` 变化视为切换上下文，下一帧强制钉底（不看 nearBottom）；同壳内再上滑才用距底锚定 */
let chatMessagesListScrollThreadKey = "";
/** {@link bindChatLastMessageResizeForStick}：距底锚定跟进窗口与像素距离 */
let chatResizeStickAnchorDist = null;
let chatResizeStickAnchorUntil = 0;
/** 用户主动上滑离开底部（由列表 scroll 监听维护；程序钉底触发的 scroll 不计入） */
let chatUserScrolledAwayFromBottom = false;
/** 下一次 {@link renderChatMessages} 强制贴底，不用距底锚定 */
let chatForceStickBottomNextRender = false;
/** 此前为程序改 scrollTop，忽略 scroll 事件以免误判「在看历史」 */
let chatProgrammaticScrollUntil = 0;
/** 语音点按展开/收起：短暂屏蔽末尾 ResizeObserver 贴底，避免整页闪一下 */
let chatVoiceRevealScrollGuardUntil = 0;
/** {@link forceBumpChatMessagesScrollToBottom} 等延迟贴底任务，用户手动滑动时可取消 */
/** @type {number[]} */
let chatScrollStickTimeoutIds = [];

function cancelChatScrollStickFollowUps() {
  for (const id of chatScrollStickTimeoutIds) window.clearTimeout(id);
  chatScrollStickTimeoutIds = [];
}

/** @param {() => void} fn @param {number} ms */
function scheduleChatScrollStick(fn, ms) {
  const id = window.setTimeout(fn, ms);
  chatScrollStickTimeoutIds.push(id);
  return id;
}

function markChatProgrammaticScroll(ms = 420) {
  chatProgrammaticScrollUntil = Date.now() + Math.max(80, ms);
}

/** 发送 / 收到新回复等：下次渲染贴底并视为在跟读最新 */
function requestChatStickBottomNextRender() {
  chatUserScrolledAwayFromBottom = false;
  chatForceStickBottomNextRender = true;
}

function onChatMessagesScrollStickTracking() {
  const scrollEl = document.getElementById("chat-messages");
  if (!(scrollEl instanceof HTMLElement)) return;
  if (Date.now() < chatProgrammaticScrollUntil) return;
  chatUserScrolledAwayFromBottom = !isChatMessagesListNearBottom(scrollEl);
}

/** 用户主动 wheel / 触摸滑动：立刻取消程序贴底并更新「是否在看历史」 */
function onChatMessagesUserScrollIntent() {
  cancelChatScrollStickFollowUps();
  chatProgrammaticScrollUntil = 0;
  chatStickBottomFollowUpUntil = 0;
  chatLastMsgResizeRo?.disconnect();
  const scrollEl = document.getElementById("chat-messages");
  if (!(scrollEl instanceof HTMLElement)) return;
  chatUserScrolledAwayFromBottom = !isChatMessagesListNearBottom(scrollEl);
}

function ensureChatMessagesScrollStickListener() {
  const el = document.getElementById("chat-messages");
  if (!el || el.dataset.scrollStickBound === "1") return;
  el.dataset.scrollStickBound = "1";
  el.addEventListener("scroll", onChatMessagesScrollStickTracking, { passive: true });
  el.addEventListener("wheel", onChatMessagesUserScrollIntent, { passive: true });
  el.addEventListener("touchmove", onChatMessagesUserScrollIntent, { passive: true });
}

/**
 * 是否贴近列表底部（用户是否在「跟读最新」）。slack 略大以覆盖 iOS 取整与工具栏。
 * @param {HTMLElement | null} scrollEl
 * @param {number} [slackPx]
 */
function isChatMessagesListNearBottom(scrollEl, slackPx = 120) {
  if (!(scrollEl instanceof HTMLElement)) return true;
  try {
    const slack = Math.max(8, slackPx);
    const dist = scrollEl.scrollHeight - scrollEl.scrollTop - scrollEl.clientHeight;
    return dist <= slack;
  } catch (_) {
    return true;
  }
}

function preserveChatMessagesScrollForNextRender() {
  const scrollEl = document.getElementById("chat-messages");
  if (!(scrollEl instanceof HTMLElement)) return;
  const dist = Math.max(0, scrollEl.scrollHeight - scrollEl.scrollTop - scrollEl.clientHeight);
  if (dist <= 120) return;
  chatPreserveScrollAnchorFromBottom = dist;
}

function flushChatMessagesScrollToBottom(scrollEl) {
  if (!scrollEl) return;
  if (!isChatMessagesListNearBottom(scrollEl)) return;
  markChatProgrammaticScroll();
  try {
    scrollEl.scrollTop = scrollEl.scrollHeight;
  } catch (_) {
    /* ignore */
  }
}

/**
 * 滚到列表底部并多次补偿（iOS WebKit 上图高度滞后）。
 * @param {HTMLElement} scrollEl
 */
function bumpChatMessagesScrollToBottom(scrollEl) {
  if (!scrollEl) return;
  markChatProgrammaticScroll(900);
  const apply = () => flushChatMessagesScrollToBottom(scrollEl);
  apply();
  window.requestAnimationFrame(() => {
    apply();
    window.requestAnimationFrame(apply);
  });
  for (const ms of [40, 90, 160, 280, 420, 650]) {
    scheduleChatScrollStick(apply, ms);
  }
}

/** 切线程 / 切 im↔offline 壳层后强制钉底（无视「是否在底部」门闩；清空 innerHTML 后 scrollTop 常为 0，nearBottom 会误判）。 */
function forceBumpChatMessagesScrollToBottom(scrollEl) {
  if (!scrollEl) return;
  markChatProgrammaticScroll(1200);
  const apply = () => {
    try {
      scrollEl.scrollTop = scrollEl.scrollHeight;
    } catch (_) {
      /* ignore */
    }
  };
  apply();
  window.requestAnimationFrame(() => {
    apply();
    window.requestAnimationFrame(apply);
  });
  for (const ms of [40, 90, 160, 280, 420, 650, 1000, 1600]) {
    scheduleChatScrollStick(apply, ms);
  }
}

/** 监听末尾气泡尺寸（表情包解码后变高），在跟进窗口内持续钉底 */
function bindChatLastMessageResizeForStick(scrollEl) {
  const rows = scrollEl.querySelectorAll(".chat-msg");
  const last = rows.length ? rows[rows.length - 1] : null;
  if (!last) {
    chatLastMsgResizeRo?.disconnect();
    return;
  }
  if (!chatLastMsgResizeRo) {
    chatLastMsgResizeRo = new ResizeObserver(() => {
      const el = document.getElementById("chat-messages");
      if (!el) return;
      if (Date.now() < chatVoiceRevealScrollGuardUntil) return;
      if (
        chatResizeStickAnchorDist != null &&
        Number.isFinite(chatResizeStickAnchorDist) &&
        Date.now() <= chatResizeStickAnchorUntil
      ) {
        markChatProgrammaticScroll(520);
        try {
          el.scrollTop = Math.max(0, el.scrollHeight - el.clientHeight - chatResizeStickAnchorDist);
        } catch (_) {
          /* ignore */
        }
        return;
      }
      if (Date.now() > chatStickBottomFollowUpUntil) return;
      flushChatMessagesScrollToBottom(el);
    });
  } else {
    chatLastMsgResizeRo.disconnect();
  }
  try {
    chatLastMsgResizeRo.observe(last);
  } catch (_) {
    /* ignore */
  }
}

/** 捕获阶段：列表内任意 img load 后再贴底（动图首帧常晚于首次 layout） */
function ensureChatMessagesImgLoadStickDelegate() {
  const el = document.getElementById("chat-messages");
  if (!el || el.dataset.imgStickBound === "1") return;
  el.dataset.imgStickBound = "1";
  el.addEventListener(
    "load",
    (ev) => {
      const t = ev.target;
      if (!(t instanceof HTMLImageElement)) return;
      if (!el.contains(t)) return;
      if (
        chatResizeStickAnchorDist != null &&
        Number.isFinite(chatResizeStickAnchorDist) &&
        Date.now() <= chatResizeStickAnchorUntil
      ) {
        markChatProgrammaticScroll(520);
        try {
          el.scrollTop = Math.max(0, el.scrollHeight - el.clientHeight - chatResizeStickAnchorDist);
        } catch (_) {
          /* ignore */
        }
        return;
      }
      if (Date.now() > chatStickBottomFollowUpUntil) return;
      flushChatMessagesScrollToBottom(el);
    },
    true
  );
}

/** 聊天气泡过多时折叠更早记录：默认保留尾部条数（不宜太小以免「折太多」） */
const CHAT_RENDER_COLLAPSE_KEEP_LAST = 42;
/** 每次点击「展开更早」多渲染的条数（适中，避免一次卡顿） */
const CHAT_RENDER_COLLAPSE_EXPAND_STEP = 24;
/** 开聊首屏从分表灌入末尾条数；超过此条数的长聊走稀疏 uiEntries */
const CHAT_UI_HYDRATE_PAGE = 96;
/** 离聊后内联 messages 超过此数则外置分表，减轻 inbox 内存（最近 {@link CHAT_UI_FULL_MESSAGES_LRU} 个密谈保留全量） */
const CHAT_MEMORY_TRIM_MIN = 200;
/** 最近打开的密谈保留全量 messages，其余长聊离聊后外置分表 */
const CHAT_UI_FULL_MESSAGES_LRU = 3;
/** 长聊默认走稀疏 uiEntries（不全表 build）；人设折叠 / 晤面场次折叠仍用全量 */
function shouldUseSparseChatUiEntries(logLen, offlineFoldBlocksSparse, personaFoldBlocksSparse) {
  if (offlineFoldBlocksSparse || personaFoldBlocksSparse) return false;
  return Math.floor(Number(logLen) || 0) > CHAT_UI_HYDRATE_PAGE;
}

/** @param {object[]} log @param {"im"|"offline"} uiSurface @param {"im"|"offline"} shellSurface @param {object} [th] */
function resolveChatRenderUiEntriesForLog(log, uiSurface, shellSurface, th) {
  const offlineFoldBlocksSparse =
    shellSurface === "offline" &&
    offlineFoldPriorSessions &&
    offlineSessionStartLogIdx >= 0 &&
    !offlinePriorSessionsRevealed;
  const charItem = th?.charId ? getCharPersonaItemById(th.charId) : null;
  const personaFoldBlocksSparse = Boolean(
    charItem && charHasAltPersona(charItem) && isThreadPersonaFoldOtherEnabled(th)
  );
  if (!shouldUseSparseChatUiEntries(log.length, offlineFoldBlocksSparse, personaFoldBlocksSparse)) {
    return resolveChatRenderUiEntries(log, uiSurface);
  }
  return resolveChatRenderUiEntriesSparse(log, uiSurface, th);
}

/** @param {object} [th] */
function invalidateThreadUiVisibleEntryCount(th) {
  if (!th || typeof th !== "object") return;
  delete th._uiVisibleLen;
  delete th._uiVisibleLenKey;
  delete th._uiSparseEntriesKey;
  delete th._uiSparseEntries;
}

/** @param {object[]} log @param {"im"|"offline"} uiSurface */
function uiVisibleCountCacheKey(log, uiSurface) {
  const arr = Array.isArray(log) ? log : [];
  const last = arr.length ? arr[arr.length - 1] : null;
  return `${uiSurface}\t${arr.length}\t${last?.at ?? ""}\t${last?.role ?? ""}`;
}
let chatUiFullMessagesLru = [];
/** 已从顶部多展开出来的消息条数（仅影响渲染切片，不改日志） */
let chatHistoryOlderRevealCount = 0;
let chatHistoryCollapseLastLogLen = 0;
let chatHistoryCollapseThreadKey = "";
/** 渲染用 uiEntries 增量缓存（用户发尾消息 +1 时避免 O(n) 重建） */
let chatUiEntriesRenderCache = { baseKey: "", uiSurface: "", logLen: 0, entries: null };
/** 人设折叠窗缓存（尾 append +1 时可复用上一帧） */
let chatPersonaFoldWindowsRenderCache = { key: "", windows: null, L: 0 };
/** 仅用户发尾消息时跳过 render 前全 log normalize（勿绑 suppressAnim，assistant 刷新仍须 normalize） */
let chatSkipLogNormalizeNextRender = false;
/** 进入密谈首帧：心声/小剧场面板未打开时不阻塞首绘 */
let chatDeferInnerVoiceSyncNextRender = false;

/** 轻量渲染调度：先让输入框清空等 UI 画一帧，再全量渲染气泡，减轻发送瞬间卡顿感。 */
let chatRenderScheduleTid = 0;
/** 已有渲染在排队时若又收到刷新请求，完成后补渲一次，避免「输入中」占位被后续落盘覆盖后界面不更新。 */
let chatRenderScheduleDirty = false;
function scheduleRenderChatMessages() {
  if (chatRenderScheduleTid) {
    chatRenderScheduleDirty = true;
    return;
  }
  chatRenderScheduleDirty = false;
  chatRenderScheduleTid = window.requestAnimationFrame(() => {
    chatRenderScheduleTid = window.requestAnimationFrame(() => {
      chatRenderScheduleTid = 0;
      renderChatMessages();
      if (chatRenderScheduleDirty) {
        chatRenderScheduleDirty = false;
        scheduleRenderChatMessages();
      }
    });
  });
}

/** 用户主动发消息/图/表情后：立刻重绘并抑制历史气泡重播入场动画（取消排队 rAF，避免晚一拍）。 */
/** @param {{ stickBottom?: boolean, skipLogNormalize?: boolean }} [opts] stickBottom 默认 true；编辑历史气泡等请传 false 以保留滚动位置 */
function scheduleRenderChatMessagesAfterUserSend(opts) {
  if (opts?.stickBottom !== false) requestChatStickBottomNextRender();
  chatSuppressNextChatMessageAnimations = true;
  if (opts?.skipLogNormalize !== false) chatSkipLogNormalizeNextRender = true;
  chatRenderScheduleDirty = false;
  if (chatRenderScheduleTid) {
    window.cancelAnimationFrame(chatRenderScheduleTid);
    chatRenderScheduleTid = 0;
  }
  invalidateChatLogViewCache();
  invalidateChatUiEntriesRenderCache();
  renderChatMessages();
}

/** 编辑气泡后落盘：抑制动画并刷新当前密谈（不碰 thread list）。 */
function finishComposerPatchSaveAndRefresh(msgIdx) {
  if (Number.isFinite(Number(msgIdx))) chatForceRebuildMsgIdx = Math.floor(Number(msgIdx));
  scheduleRenderChatMessagesAfterUserSend({ stickBottom: false, skipLogNormalize: false });
  scheduleChatContextTokenLabelUpdate();
  scheduleChatProactiveTimer();
}

/** 该 log 行会渲染成带 data-chat-msg-idx 的气泡行（非纯时间条 notice）。 */
function chatRenderEntryNeedsMsgRow(m) {
  if (!m || typeof m !== "object") return false;
  if (m.role === "user" || m.role === "assistant") return true;
  return isChatNoticeCallEndedMessage(m);
}

/**
 * @param {HTMLElement|null} root
 * @returns {Set<number>}
 */
function chatCollectDomMsgIdxSet(root) {
  const existingIdx = new Set();
  if (!root) return existingIdx;
  for (const wrap of root.querySelectorAll(".chat-msg[data-chat-msg-idx]")) {
    const idx = Number(wrap.dataset.chatMsgIdx);
    if (Number.isFinite(idx)) existingIdx.add(idx);
  }
  return existingIdx;
}

/**
 * renderEntries[startIdx..tailJ) 中需要展示的行是否都已在 DOM。
 * @param {Set<number>} existingIdx
 * @param {{ realIdx: number, m: object }[]} entries
 * @param {number} startIdx
 * @param {number} tailJ
 * @param {object} [opts]
 */
function chatRenderPriorRowsPresentInDom(existingIdx, entries, startIdx, tailJ, opts) {
  if (!existingIdx.size) return false;
  const foldWindows = opts?.personaFoldWindows;
  for (let j = startIdx; j < tailJ; j++) {
    const entry = entries[j];
    if (!entry) continue;
    const em = entry.m;
    if (isPersonaFoldBoundaryMessage(em)) continue;
    const foldContentWin = foldWindows ? inactivePersonaFoldContentAt(foldWindows, j) : null;
    const foldBoundaryWin = foldWindows ? inactivePersonaFoldBoundaryAt(foldWindows, j) : null;
    const foldWin = foldContentWin || foldBoundaryWin;
    if (foldWin) {
      const foldKey = chatPersonaFoldExpandKey(
        String(opts?.maskId || ""),
        String(opts?.threadId || ""),
        foldWin.startRealIdx
      );
      if (foldKey && !chatPersonaFoldExpandedKeys.has(foldKey) && foldContentWin) continue;
    }
    if (!chatRenderEntryNeedsMsgRow(em)) continue;
    if (!existingIdx.has(entry.realIdx)) return false;
  }
  return true;
}

/**
 * 用户发尾消息后：DOM 已含此前可见气泡时，仅 append 最新 user 行，避免整表重绘闪旧 char 图。
 * @returns {number} renderEntries 下标，或 -1
 */
function detectChatTailAppendJ(root, renderEntries, startIdx, opts) {
  if (!root || !opts?.suppressAnim || opts?.threadJustChanged || opts?.multiSelect) return -1;
  if (opts?.offlineSessionFoldActive) return -1;
  const entries = Array.isArray(renderEntries) ? renderEntries : [];
  const L = entries.length;
  if (L <= 0 || startIdx >= L) return -1;
  const tailJ = L - 1;
  const tail = entries[tailJ]?.m;
  if (
    !tail ||
    (tail.role !== "user" && !(tail.role === "assistant" && !tail.restoring))
  ) {
    return -1;
  }
  const existingIdx = chatCollectDomMsgIdxSet(root);
  if (!existingIdx.size) return -1;
  const tailIdx = entries[tailJ].realIdx;
  if (existingIdx.has(tailIdx)) return -1;
  if (!chatRenderPriorRowsPresentInDom(existingIdx, entries, startIdx, tailJ, opts)) return -1;
  return tailJ;
}

/**
 * 尾部增量 append 时裁掉折叠窗以上的旧气泡 DOM，避免消息多了以后 querySelector 越来越慢。
 * @param {HTMLElement} root
 * @param {{ realIdx: number, m: object }[]} renderEntries
 * @param {number} startIdx
 */
function pruneChatMessagesDomAboveCollapseWindow(root, renderEntries, startIdx) {
  if (!root || !Array.isArray(renderEntries) || startIdx <= 0) return;
  const minRealIdx = renderEntries[startIdx]?.realIdx;
  if (!Number.isFinite(minRealIdx)) return;
  for (const wrap of root.querySelectorAll(".chat-msg[data-chat-msg-idx]")) {
    if (!(wrap instanceof HTMLElement)) continue;
    const idx = Number(wrap.dataset.chatMsgIdx);
    if (Number.isFinite(idx) && idx < minRealIdx) wrap.remove();
  }
}

/**
 * IM 流式/逐条气泡：末条 assistant.restoring 时仅重绘最后一行，避免整表 innerHTML 清空导致历史 char 图/表情闪动。
 * @returns {number} renderEntries 下标，或 -1
 */
function detectRestoringImTailOnlyRender(root, renderEntries, startIdx, opts) {
  if (!root || !opts?.suppressAnim || opts?.threadJustChanged || opts?.multiSelect) return -1;
  if (opts?.offlineSessionFoldActive) return -1;
  if (opts?.shellSurface !== "im") return -1;
  const entries = Array.isArray(renderEntries) ? renderEntries : [];
  const L = entries.length;
  if (L <= 0 || startIdx >= L) return -1;
  const tailJ = L - 1;
  const tail = entries[tailJ]?.m;
  if (!tail || tail.role !== "assistant" || !tail.restoring) return -1;
  const existingIdx = chatCollectDomMsgIdxSet(root);
  if (!existingIdx.size) return -1;
  const tailIdx = entries[tailJ].realIdx;
  if (!existingIdx.has(tailIdx)) return -1;
  if (!chatRenderPriorRowsPresentInDom(existingIdx, entries, startIdx, tailJ, opts)) return -1;
  return tailJ;
}

function explainModelEmptyReply(data, parsedRaw) {
  const hasChoices = Array.isArray(data?.choices) && data.choices.length > 0;
  const hasMsg = Boolean(data?.choices?.[0]?.message);
  const hasText = typeof data?.choices?.[0]?.text === "string";
  const finish = String(data?.choices?.[0]?.finish_reason ?? "").trim();
  const rawLen = String(parsedRaw || "").trim().length;
  const bits = [];
  bits.push("模型返回为空");
  bits.push(
    rawLen === 0
      ? "接口没有返回可用 content"
      : "返回内容解析后为空（可能被截断/格式不符）"
  );
  if (!hasChoices) bits.push("choices 缺失");
  else if (!hasMsg && !hasText) bits.push("message/text 缺失");
  if (finish === "content_filter") bits.push("finish_reason=content_filter（多被审核拦截，可换模型或略改措辞）");
  else if (finish === "length") bits.push("finish_reason=length（输出被截断，可换更长上下文模型或减记忆条数）");
  bits.push("常见原因：中转不支持 JSON 模式、被过滤、超时或网关返回空 message");
  return bits.join("；");
}

const CHAT_INVISIBLE_ASSISTANT_REPLY_PREFIX = "CHAT_INVISIBLE_REPLY:";

function isChatInvisibleAssistantReplyError(err) {
  const msg = err instanceof Error ? err.message : String(err || "");
  return String(msg).startsWith(CHAT_INVISIBLE_ASSISTANT_REPLY_PREFIX);
}

function chatInvisibleAssistantReplyExplainText() {
  return "回复已收到，但聊天区没有可显示的文字，请重试或点「重 roll」";
}

function throwChatInvisibleAssistantReplyError() {
  throw new Error(CHAT_INVISIBLE_ASSISTANT_REPLY_PREFIX + chatInvisibleAssistantReplyExplainText());
}

/** 主聊天列表里是否至少有一项可展示（气泡/表情/图/旁白/语音/红包/仅译文等）。 */
function assistantEntryHasVisibleMainChat(entry, dmSurface, thread) {
  if (!entry || typeof entry !== "object" || entry.role !== "assistant") return false;
  const surf = dmSurface === "offline" ? "offline" : "im";
  const th = thread && typeof thread === "object" ? thread : null;
  if (entry.sticker && typeof entry.sticker === "object" && String(entry.sticker.url || "").trim()) return true;
  if (
    Array.isArray(entry.stickerPlacements) &&
    entry.stickerPlacements.some((p) => p && String(p.url || "").trim())
  ) {
    return true;
  }
  if (chatMessageHasBubbleImageCard(entry)) return true;
  if (surf !== "offline" && window.XXJ_InlineHtml?.messageHasInlineHtmlCards?.(entry)) return true;
  if (surf !== "offline" && isThreadNarratorModeEnabled(th) && String(entry.narration || "").trim()) return true;
  if (surf !== "offline" && Array.isArray(entry.voiceLines) && entry.voiceLines.some(Boolean)) return true;
  const raw = String(entry.content || "");
  for (const seg of raw.split(/\|\|\|/)) {
    if (parseRedpackMessageText(String(seg || "").trim())) return true;
  }
  const transOn = isThreadCharTranslationEnabled(th);
  if (transOn && translationJoinedHasAnyVisible(String(entry.translation || ""))) {
    const mains = raw.split(/\|\|\|/);
    const trans = String(entry.translation || "").split(/\|\|\|/);
    const n = Math.max(mains.length, trans.length);
    for (let i = 0; i < n; i++) {
      const mTrim = String(mains[i] !== undefined ? mains[i] : "")
        .replace(/\u00A0/g, " ")
        .trim();
      const tRaw = trans[i] !== undefined ? String(trans[i]) : "";
      const tTrim = tRaw.trim();
      if (mTrim) return true;
      if (tTrim && !isTranslationSegmentSkipped(tRaw)) return true;
    }
  }
  for (const seg of raw.split(/\|\|\|/)) {
    const t = String(seg || "")
      .replace(/\u00A0/g, " ")
      .trim();
    if (t) return true;
  }
  return false;
}

function logHasVisibleAssistantFromIndex(log, fromIdx, dmSurface, thread) {
  const arr = Array.isArray(log) ? log : [];
  const start = Math.max(0, Math.floor(Number(fromIdx)) || 0);
  for (let j = arr.length - 1; j >= start; j--) {
    const m = arr[j];
    if (m && m.role === "assistant" && assistantEntryHasVisibleMainChat(m, dmSurface, thread)) return true;
  }
  return false;
}

/** @param {unknown[]} log @param {number} fromIdx */
function resolveAssistantVisibleAssertStart(log, fromIdx) {
  const arr = Array.isArray(log) ? log : [];
  let start = Math.max(0, Math.floor(Number(fromIdx)) || 0);
  if (start < arr.length) return start;
  for (let i = arr.length - 1; i >= 0; i--) {
    if (arr[i] && typeof arr[i] === "object" && arr[i].role === "assistant") return i;
  }
  return start;
}

function assertAssistantRoundAddsVisibleMainChat(log, fromIdx, dmSurface, thread, rawReply) {
  const arr = Array.isArray(log) ? log : [];
  const start = resolveAssistantVisibleAssertStart(arr, fromIdx);
  const salv = coalesceAssistantDisplayReply("", rawReply, dmSurface);
  if (salv) {
    for (let i = start; i < arr.length; i++) {
      const e = arr[i];
      if (!e || e.role !== "assistant") continue;
      const bare = String(e.content || "")
        .replace(/\u00A0/g, " ")
        .trim();
      if (!bare) e.content = salv;
    }
  }
  if (logHasVisibleAssistantFromIndex(log, start, dmSurface, thread)) return;
  throwChatInvisibleAssistantReplyError();
}

/**
 * 从 chat/completions 响应取出助手文本（OpenAI choices、Gemini candidates 等）。
 * 密谈/IM：**只用 message.content**，不把 reasoning / 思维链当正文（与漫游 IM 一致）。
 * @param {unknown} data
 * @returns {string}
 */
function readChatCompletionChoiceText(data) {
  if (!data || typeof data !== "object") return "";
  const ch0 = data.choices?.[0];
  if (ch0) {
    if (typeof ch0.text === "string" && ch0.text.trim()) return ch0.text.trim();
    const msg = ch0.message;
    if (msg && typeof msg === "object") {
      const c = msg.content;
      if (typeof c === "string" && c.trim()) return c.trim();
      if (Array.isArray(c)) {
        const bits = [];
        for (const part of c) {
          if (!part || typeof part !== "object") continue;
          const typ = String(part.type || "").toLowerCase();
          if (
            typ === "reasoning" ||
            typ === "thinking" ||
            typ === "reasoning_content" ||
            typ === "chain_of_thought" ||
            typ === "thought"
          ) {
            continue;
          }
          if (typ && typ !== "text" && typ !== "output_text") continue;
          if (typeof part.text === "string") bits.push(part.text);
          else if (typeof part.content === "string") bits.push(part.content);
        }
        const joined = bits.join("").trim();
        if (joined) return joined;
      }
    }
  }
  const cand0 = data.candidates?.[0];
  if (cand0 && typeof cand0 === "object") {
    const parts = cand0.content?.parts;
    if (Array.isArray(parts)) {
      const bits = [];
      for (const part of parts) {
        if (!part || typeof part !== "object") continue;
        const typ = String(part.type || "").toLowerCase();
        if (typ === "thought" || typ === "thinking") continue;
        if (typeof part.text === "string") bits.push(part.text);
      }
      const joined = bits.join("").trim();
      if (joined) return joined;
    }
    if (typeof cand0.output === "string" && cand0.output.trim()) return cand0.output.trim();
  }
  const top =
    (typeof data.output_text === "string" && data.output_text.trim()) ||
    (typeof data.text === "string" && data.text.trim()) ||
    "";
  return String(top || "").trim();
}

/** 从 completion 响应取出助手原文；choices 为空时再从整包 JSON 松散抢救 */
function readChatCompletionSalvagedText(data) {
  let raw = readChatCompletionChoiceText(data);
  if (String(raw || "").trim()) return raw;
  const salv = salvageAssistantDisplayReplyFromRaw(JSON.stringify(data), { maxItems: 12 });
  return salv ? String(salv).trim() : "";
}

/** @param {unknown} data */
function chatCompletionOutputTruncated(data) {
  const r = String(data?.choices?.[0]?.finish_reason ?? "").trim();
  return r === "length" || r === "max_tokens";
}

/** @param {number|null|undefined} maxTok */
function spreadOptionalMaxTokens(maxTok) {
  if (maxTok == null || !Number.isFinite(Number(maxTok))) return {};
  const n = Math.floor(Number(maxTok));
  return n > 0 ? { max_tokens: Math.max(256, n) } : {};
}

/**
 * 聊天补全：可选 JSON；网关不支持 JSON 时回退纯文本。
 * 线上 IM 传 max_tokens；当面晤面不传，走网关/模型默认输出上限。
 * @param {object} ai
 * @param {{ messages: object[], max_tokens?: number, response_format?: { type: string }, signal?: AbortSignal }} opts
 */
function isChatAssistAbortError(err) {
  if (!err) return false;
  if (err.name === "AbortError") return true;
  const msg = err instanceof Error ? err.message : String(err);
  return /abort|aborted|cancel/i.test(msg);
}

async function requestChatAssistantCompletion(ai, opts) {
  const rf = opts.response_format;
  const fetchOpts = {};
  if (opts.signal) fetchOpts.signal = opts.signal;
  if (opts.completionConfig && typeof opts.completionConfig === "object") {
    fetchOpts.completionConfig = opts.completionConfig;
  }
  /** @type {unknown} */
  let lastData = null;
  const payload0 = { messages: opts.messages, ...spreadOptionalMaxTokens(opts.max_tokens) };
  if (rf) payload0.response_format = rf;
  try {
    lastData = await ai.chatCompletions(payload0, fetchOpts);
  } catch (e) {
    if (rf) {
      if (isChatAssistAbortError(e)) throw e;
      const retry = { ...payload0 };
      delete retry.response_format;
      lastData = await ai.chatCompletions(retry, fetchOpts);
    } else throw e;
  }
  if (chatCompletionOutputTruncated(lastData)) {
    showToast("回复可能不完整，可换更长上下文模型或减少记忆条数");
  }
  if (rf && !readChatCompletionChoiceText(lastData)) {
    try {
      showToast("接口无正文，正在去掉 JSON 约束重试…");
      const retry2 = { ...payload0 };
      delete retry2.response_format;
      lastData = await ai.chatCompletions(retry2, fetchOpts);
    } catch (e) {
      if (isChatAssistAbortError(e)) throw e;
      /* 保留上一轮 data 供 explainModelEmptyReply */
    }
  }
  return lastData;
}

function isChatAssistStreamUnsupportedError(err) {
  const msg = err instanceof Error ? err.message : String(err || "");
  return /\b(streaming|stream\s+mode|event.?stream|text\/event-stream)\b|stream.*(?:not\s+support|unsupported)|(?:not\s+support|unsupported).*\bstream\b/i.test(
    msg
  );
}

/** 流式失败且可 silent 回退非流式（鉴权/余额类错误除外）。 */
function isChatAssistStreamFallbackError(err) {
  if (!err) return false;
  if (isChatAssistAbortError(err)) return false;
  const msg = err instanceof Error ? err.message : String(err || "");
  if (isChatAssistStreamUnsupportedError(err)) return true;
  if (/当前环境不支持流式响应/.test(msg)) return true;
  if (/流式|不支持.*stream|stream.*不支持|非流式|non.?stream/i.test(msg)) return true;
  const status = Number(err.__httpStatus);
  if (status === 400 || status === 404 || status === 405 || status === 422) {
    if (/stream|流式/i.test(msg)) return true;
  }
  return false;
}

function resolveChatAssistStreamCapConfig(ai, opts) {
  if (opts?.completionConfig && typeof opts.completionConfig === "object") return opts.completionConfig;
  return ai?.getConfig?.() || {};
}

/** 晤面流式：从尚未闭合的 JSON 里抽出可读的 lines 正文预览。 */
function extractOfflineAssistantStreamPreview(partialRaw) {
  const raw = String(partialRaw || "");
  if (!raw.trim()) return "";
  try {
    const strip = stripCharLockPlainProtocolBlocksFromText(raw);
    const parsed = parseAssistantPayloadForDmSurface(strip.text, "offline", raw);
    const reply = stripOfflineMeetupTagFromAssistantReply(parsed.reply);
    if (String(reply || "").trim()) {
      return normalizeOfflineProseForDisplayJoined(reply);
    }
  } catch (_) {
    /* 半段 JSON */
  }
  const looseLines = extractLooseAssistantLinesFromRaw(raw, 12, true);
  if (looseLines.length) {
    return normalizeOfflineProseForDisplayJoined(looseLines.join("|||"));
  }
  return "";
}

let chatOfflineStreamUiRaf = 0;

/** @param {string} joined */
function splitImAssistantReplyLines(joined) {
  return String(joined || "")
    .split(/\|\|\|/)
    .map((s) => s.trim())
    .filter(Boolean);
}

/** @param {string} lineText @param {number} index */
function computeImBubbleRevealDelayMs(lineText, index) {
  const len = String(lineText || "").length;
  const base = 420;
  const perChar = 32;
  return Math.min(2400, Math.max(480, base + Math.min(len, 48) * perChar + Math.max(0, index) * 36));
}

/** @param {unknown} entry */
function clearAssistantEntryRestoringUiFlags(entry) {
  if (!entry || typeof entry !== "object") return;
  delete entry.restoring;
  delete entry.restoringSegIdx;
  delete entry.restoringTypingHold;
}

/** @param {unknown} raw @returns {"R"|"S"|"OFF"} */
function normalizeChatImHumanPaceToken(raw) {
  const m = String(raw ?? "R").trim().toUpperCase();
  if (m === "OFF" || m === "0" || m === "FALSE") return "OFF";
  if (m === "S" || m === "SLOW") return "S";
  return "R";
}

/** 设置 · 全局密谈多泡打字节奏（R / S / off）。 */
function readGlobalChatImHumanPaceRaw() {
  const D = window.XXJ_DB;
  const raw = D?.getKv?.(D.K?.CHAT_IM_HUMAN_PACE);
  if (raw == null || raw === "") return "R";
  const t = normalizeChatImHumanPaceToken(raw);
  return t === "OFF" ? "off" : t;
}

/** @param {unknown} [thread] @returns {string} 空串=跟随全局；否则 R | S | off */
function readThreadChatImHumanPaceOverrideRaw(thread) {
  if (!thread || typeof thread !== "object" || thread.chatImHumanPace == null) return "";
  const p = String(thread.chatImHumanPace).trim();
  if (!p) return "";
  const t = normalizeChatImHumanPaceToken(p);
  return t === "OFF" ? "off" : t;
}

/** 单密谈 `chatImHumanPace` 优先，否则读全局设置。 @param {unknown} [thread] @returns {"R"|"S"|"OFF"} */
function resolveChatImHumanPace(thread) {
  const ov = readThreadChatImHumanPaceOverrideRaw(thread);
  if (ov) return normalizeChatImHumanPaceToken(ov);
  return normalizeChatImHumanPaceToken(readGlobalChatImHumanPaceRaw());
}

function computeImHumanBubblePacing(lineText, prevLineText, bubbleIndex, thread) {
  if (bubbleIndex <= 0) return { thinkingPauseMs: 0, typingPauseMs: 0 };
  const pace = resolveChatImHumanPace(thread);
  if (pace === "OFF") {
    const prev = String(prevLineText != null ? prevLineText : lineText || "");
    return {
      thinkingPauseMs: 0,
      typingPauseMs: computeImBubbleRevealDelayMs(prev, Math.max(0, bubbleIndex - 1))
    };
  }
  const len = String(lineText || "").length;
  let thinkingPause = 0;
  let typingPause = 0;
  if (pace === "S") {
    thinkingPause = 950 + Math.floor(950 * Math.random());
    typingPause = Math.min(2500, 200 + 130 * len);
  } else {
    thinkingPause = 40 + Math.floor(160 * Math.random());
    typingPause = Math.min(1700, 120 + 85 * len);
  }
  if (len > 0 && len <= 2) typingPause = Math.max(typingPause, 250);
  return { thinkingPauseMs: thinkingPause, typingPauseMs: typingPause };
}

/**
 * @param {{ entry: object, lineText: string, prevLineText?: string, bubbleIndex: number, thread?: object, maskId: string, threadId: string, log: unknown[], signal?: AbortSignal }} opts
 */
async function awaitImBubbleHumanPacingBeforeReveal(opts) {
  const entry = opts && opts.entry && typeof opts.entry === "object" ? opts.entry : null;
  if (!entry) return;
  const { thinkingPauseMs, typingPauseMs } = computeImHumanBubblePacing(
    opts.lineText,
    opts.prevLineText,
    opts.bubbleIndex,
    opts.thread
  );
  if (thinkingPauseMs <= 0 && typingPauseMs <= 0) return;
  const maskId = String(opts.maskId || "").trim();
  const threadId = String(opts.threadId || "").trim();
  const log = opts.log;
  const signal = opts.signal;
  const flush = () => {
    if (!maskId || !threadId || !Array.isArray(log)) return;
    saveChatLogForMaskThread(maskId, threadId, log);
    scheduleChatUiRefreshForRound(maskId, threadId, { flush: true });
  };
  if (thinkingPauseMs > 0) {
    entry.restoringTypingHold = true;
    flush();
    await new Promise((r) => window.setTimeout(r, thinkingPauseMs));
    if (signal && signal.aborted) {
      delete entry.restoringTypingHold;
      return;
    }
    delete entry.restoringTypingHold;
  }
  if (typingPauseMs > 0) {
    entry.restoring = true;
    flush();
    await new Promise((r) => window.setTimeout(r, typingPauseMs));
    if (signal && signal.aborted) return;
  }
}

/** 流式 JSON 里 lines 数组是否尚未闭合（后面可能还有气泡）。 */
function imAssistantStreamLinesArrayLikelyOpen(partialRaw) {
  const s = String(partialRaw || "");
  const idx = s.search(/"lines"\s*:/i);
  if (idx < 0) return true;
  const after = s.slice(idx);
  const lb = after.indexOf("[");
  if (lb < 0) return true;
  let depth = 0;
  let inStr = false;
  let esc = false;
  for (let i = lb; i < after.length; i++) {
    const c = after[i];
    if (inStr) {
      if (esc) {
        esc = false;
        continue;
      }
      if (c === "\\") {
        esc = true;
        continue;
      }
      if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') {
      inStr = true;
      continue;
    }
    if (c === "[") depth++;
    else if (c === "]") {
      depth--;
      if (depth === 0) return false;
    }
  }
  return true;
}

/**
 * @param {string} maskId
 * @param {string} threadId
 * @param {{ content?: string, restoringSegIdx?: number }} patch
 */
function patchAssistantStreamPreviewRow(maskId, threadId, patch) {
  const mid = String(maskId || "").trim();
  const tid = String(threadId || "").trim();
  if (!mid || !tid) return;
  const content = String(patch?.content ?? "");
  const found = findChatThreadInInbox(mid, tid);
  if (!found || !Array.isArray(found.thread.messages)) return;
  const msgs = found.thread.messages;
  let row = null;
  for (let i = msgs.length - 1; i >= 0; i--) {
    const m = msgs[i];
    if (m && m.role === "assistant" && m.restoring) {
      row = m;
      break;
    }
  }
  if (!row) return;
  const segIdx =
    patch && Number.isFinite(Number(patch.restoringSegIdx)) ? Math.max(0, Math.floor(Number(patch.restoringSegIdx))) : -1;
  const sameContent = String(row.content || "") === content;
  const sameSeg = Number(row.restoringSegIdx) === segIdx || (segIdx < 0 && row.restoringSegIdx == null);
  if (sameContent && sameSeg) return;
  row.content = content;
  if (segIdx >= 0) row.restoringSegIdx = segIdx;
  else delete row.restoringSegIdx;
  invalidateChatLogViewCache();
  updateChatAssistAbortCommitState(chatAssistRoundSlotKey(mid, tid), { reply: content });
  if (chatOfflineStreamUiRaf) return;
  chatOfflineStreamUiRaf = window.requestAnimationFrame(() => {
    chatOfflineStreamUiRaf = 0;
    scheduleChatUiRefreshForRound(mid, tid);
  });
}

/** @param {string} maskId @param {string} threadId @param {string} previewText */
function patchOfflineAssistantStreamRow(maskId, threadId, previewText) {
  patchAssistantStreamPreviewRow(maskId, threadId, { content: String(previewText || "").trim() });
}

/** IM 流式：从半段 JSON 抽出已闭合 lines，逐泡预览。 */
function patchImAssistantStreamRow(maskId, threadId, partialRaw) {
  const complete = extractLooseAssistantLinesFromRaw(partialRaw, 12, false);
  const joined = complete.join("|||");
  const linesOpen = imAssistantStreamLinesArrayLikelyOpen(partialRaw);
  patchAssistantStreamPreviewRow(maskId, threadId, {
    content: joined,
    restoringSegIdx: linesOpen ? complete.length : -1
  });
}

/**
 * IM 多泡：逐条露出剩余 bubbles（流式已露出的从下一泡继续）。
 * @param {{ log: unknown[], entry: object, maskId: string, threadId: string, thread?: object, fullContent?: string, fullTranslation?: string, transOn?: boolean, forceRevealFromStart?: boolean, signal?: AbortSignal }} opts
 */
async function revealImAssistantEntryBubbleStagger(opts) {
  const log = opts && Array.isArray(opts.log) ? opts.log : null;
  const entry = opts && opts.entry && typeof opts.entry === "object" ? opts.entry : null;
  if (!log || !entry) return;
  const maskId = String(opts.maskId || "").trim();
  const threadId = String(opts.threadId || "").trim();
  if (!maskId || !threadId) return;
  const lines = splitImAssistantReplyLines(opts.fullContent ?? entry.content);
  if (lines.length <= 1) {
    clearAssistantEntryRestoringUiFlags(entry);
    return;
  }
  const transOn = Boolean(opts.transOn);
  const fullTrans = transOn ? String(opts.fullTranslation ?? entry.translation ?? "") : "";
  const transLines = transOn ? fullTrans.split(/\|\|\|/) : [];
  let visible = splitImAssistantReplyLines(String(entry.content || ""));
  if (opts.forceRevealFromStart || visible.length >= lines.length) {
    entry.content = lines[0];
    if (transOn && transLines.length) entry.translation = String(transLines[0] ?? "").trim();
    visible = [lines[0]];
  }
  let startIdx = Math.max(1, visible.length);
  if (startIdx >= lines.length) {
    entry.content = lines.join("|||");
    if (transOn) {
      entry.translation = transLines
        .slice(0, lines.length)
        .map((s) => String(s ?? "").trim())
        .join("|||");
    }
    clearAssistantEntryRestoringUiFlags(entry);
    return;
  }
  entry.restoring = true;
  entry.restoringSegIdx = startIdx;
  saveChatLogForMaskThread(maskId, threadId, log);
  scheduleChatUiRefreshForRound(maskId, threadId, { flush: true });
  for (let i = startIdx; i < lines.length; i++) {
    if (opts.signal && opts.signal.aborted) break;
    await awaitImBubbleHumanPacingBeforeReveal({
      entry,
      lineText: lines[i],
      prevLineText: lines[i - 1],
      bubbleIndex: i,
      thread: opts.thread,
      maskId,
      threadId,
      log,
      signal: opts.signal
    });
    if (opts.signal && opts.signal.aborted) break;
    entry.content = lines.slice(0, i + 1).join("|||");
    if (transOn) {
      entry.translation = transLines
        .slice(0, i + 1)
        .map((s) => String(s ?? "").trim())
        .join("|||");
    }
    entry.restoring = i < lines.length - 1;
    if (entry.restoring) entry.restoringSegIdx = i + 1;
    else delete entry.restoringSegIdx;
    saveChatLogForMaskThread(maskId, threadId, log);
    scheduleChatUiRefreshForRound(maskId, threadId, { flush: true });
  }
  entry.content = lines.join("|||");
  if (transOn) {
    entry.translation = transLines
      .slice(0, lines.length)
      .map((s) => String(s ?? "").trim())
      .join("|||");
  }
  clearAssistantEntryRestoringUiFlags(entry);
}

/** IM 密谈默认开流式（拇指动前逐泡预览）；`chatImStreamReply === false` 可关。 */
function isThreadImStreamReplyEnabled(thread) {
  if (!thread || typeof thread !== "object") return true;
  return thread.chatImStreamReply !== false;
}

/**
 * 晤面流式补全；流式阶段不传 response_format（多数网关会在 json_object 下缓冲整段）。
 * 不支持流式 / 空流式 / 已记忆 bad 线路 → 回退普通请求（仍带 response_format）。
 * @param {object} ai
 * @param {{ messages: object[], max_tokens?: number, response_format?: { type: string }, signal?: AbortSignal, completionConfig?: object, onStreamDelta?: (full: string) => void }} opts
 */
async function requestChatAssistantCompletionStream(ai, opts) {
  if (!ai || typeof ai.chatCompletionsStream !== "function") {
    return requestChatAssistantCompletion(ai, opts);
  }
  const capCfg = resolveChatAssistStreamCapConfig(ai, opts);
  if (typeof ai.getStreamCapability === "function" && ai.getStreamCapability(capCfg) === "bad") {
    return requestChatAssistantCompletion(ai, opts);
  }
  const fetchOpts = {};
  if (opts.signal) fetchOpts.signal = opts.signal;
  if (opts.completionConfig && typeof opts.completionConfig === "object") {
    fetchOpts.completionConfig = opts.completionConfig;
  }
  const streamPayload = { messages: opts.messages, ...spreadOptionalMaxTokens(opts.max_tokens) };
  if (opts.response_format && !opts.streamOmitResponseFormat) {
    streamPayload.response_format = opts.response_format;
  }

  const markStreamBad = () => {
    if (typeof ai.setStreamCapability === "function") ai.setStreamCapability(capCfg, "bad");
  };
  const markStreamOk = () => {
    if (typeof ai.setStreamCapability === "function") ai.setStreamCapability(capCfg, "ok");
  };

  try {
    const streamed = await ai.chatCompletionsStream(streamPayload, fetchOpts, {
      onDelta: (_delta, full) => {
        if (typeof opts.onStreamDelta === "function") opts.onStreamDelta(String(full || ""));
      }
    });
    const content = String(streamed?.content || "").trim();
    if (!content) {
      markStreamBad();
      return requestChatAssistantCompletion(ai, opts);
    }
    markStreamOk();
    return {
      choices: [{ message: { content }, finish_reason: streamed?.finishReason || "stop" }],
      usage: streamed?.usage || undefined
    };
  } catch (e) {
    if (isChatAssistAbortError(e)) throw e;
    if (!isChatAssistStreamFallbackError(e)) throw e;
    markStreamBad();
    return requestChatAssistantCompletion(ai, opts);
  }
}

/** 晤面是否启用流式输出（默认关；仅 `chatOfflineStreamReply === true` 为开；入口 UI 已隐藏）。 */
function isThreadOfflineStreamReplyEnabled(thread) {
  return Boolean(thread && thread.chatOfflineStreamReply === true);
}

/** 朋友圈发圈：只用 message 正文，不把 reasoning 当动态（避免空正文）。 */
function readMomentsPostCompletionText(data) {
  const ch0 = data?.choices?.[0];
  if (!ch0) return "";
  let t = "";
  if (typeof ch0.text === "string" && ch0.text.trim()) t = ch0.text.trim();
  else {
    const msg = ch0.message;
    if (msg && typeof msg === "object") {
      const c = msg.content;
      if (typeof c === "string" && c.trim()) t = c.trim();
      else if (Array.isArray(c)) {
        const bits = [];
        for (const part of c) {
          if (!part || typeof part !== "object") continue;
          const typ = String(part.type || "").toLowerCase();
          if (typ === "text") {
            if (typeof part.text === "string") bits.push(part.text);
            else if (typeof part.content === "string") bits.push(part.content);
          }
        }
        t = bits.join("").trim();
      }
    }
  }
  if (t.length >= 4) return t;
  const full = readChatCompletionChoiceText(data);
  if (!full || full === t) return t;
  const stripped = stripMomentsPostTagsOnly(
    full.replace(/[\s\S]*?<\/think>/gi, "").replace(/<\|[^|]+\|>/g, "").trim()
  );
  if (stripped.length > t.length) return stripped.slice(0, 4000);
  return t;
}

/** JSON 里 heartVoice 类字段可能是 string / string[] / { text } */
function normalizeJsonHeartVoiceField(v) {
  if (v == null) return "";
  if (typeof v === "string") return v.trim();
  if (Array.isArray(v)) {
    return v
      .map((x) => String(x ?? "").trim())
      .filter(Boolean)
      .join("\n")
      .trim();
  }
  if (typeof v === "object") {
    const t = String(
      /** @type {Record<string, unknown>} */ (v).text ??
        /** @type {Record<string, unknown>} */ (v).content ??
        /** @type {Record<string, unknown>} */ (v).body ??
        /** @type {Record<string, unknown>} */ (v).value ??
        ""
    ).trim();
    return t;
  }
  const s = String(v).trim();
  return s === "[object Object]" ? "" : s;
}

/** 心声面板嵌套对象（mind / heartVoicePanel / psyche / 心声）；平铺键仍兼容。 */
function pickAssistantMindPanelObject(o) {
  if (!o || typeof o !== "object") return null;
  const rec = /** @type {Record<string, unknown>} */ (o);
  for (const k of ["mind", "heartVoicePanel", "psyche", "心声"]) {
    const sub = rec[k];
    if (sub && typeof sub === "object" && !Array.isArray(sub)) {
      return /** @type {Record<string, unknown>} */ (sub);
    }
  }
  return null;
}

/**
 * 从助手 JSON 对象取心声正文（顶层多键名 + 常见一层包装如 result.data）。
 * @param {unknown} o
 * @param {number} [depth]
 * @returns {string}
 */
function extractHeartVoiceDeepFromAssistantJson(o, depth = 0) {
  if (!o || typeof o !== "object" || depth > 5) return "";
  const rec = /** @type {Record<string, unknown>} */ (o);
  const keyList = [
    "heartVoice",
    "heart_voice",
    "innerVoice",
    "inner_voice",
    "mindVoice",
    "roundVoice",
    "心声",
    "独白"
  ];
  for (const k of keyList) {
    if (!Object.prototype.hasOwnProperty.call(rec, k)) continue;
    const s = normalizeJsonHeartVoiceField(rec[k]);
    if (s) return s.slice(0, 80_000);
  }
  const mindPanel = pickAssistantMindPanelObject(rec);
  if (mindPanel) {
    const fromMind = extractHeartVoiceDeepFromAssistantJson(mindPanel, depth + 1);
    if (fromMind) return fromMind.slice(0, 80_000);
  }
  const nestKeys = ["response", "data", "result", "output", "payload", "assistant", "message"];
  for (const nk of nestKeys) {
    const sub = rec[nk];
    if (sub && typeof sub === "object" && !Array.isArray(sub)) {
      const inner = extractHeartVoiceDeepFromAssistantJson(sub, depth + 1);
      if (inner) return inner.slice(0, 80_000);
    }
  }
  return "";
}

/** 长按「编辑」收回后：下一条非空发送插入到该下标（-1 表示末尾追加） */
let chatComposerResendUserAtIdx = -1;
