let chatComposerPatchImageDesc = false;

function onChatBubbleScrollClose() {
  if (isChatBubbleActionSheetOpen()) closeChatBubbleActionSheet();
}

function onChatBubbleSheetResize() {
  if (!isChatBubbleActionSheetOpen() || !chatBubbleActionAnchorEl) return;
  window.clearTimeout(chatBubbleSheetResizeTimer);
  chatBubbleSheetResizeTimer = window.setTimeout(() => {
    layoutChatBubbleActionSheet(chatBubbleActionAnchorEl);
  }, 80);
}

/** @param {Element} bubbleEl */
function layoutChatBubbleActionSheet(bubbleEl) {
  const root = document.getElementById("chat-bubble-actions");
  const sheet = root?.querySelector(".chat-bubble-actions-sheet");
  if (!root || !sheet || !bubbleEl || typeof bubbleEl.getBoundingClientRect !== "function") return;
  const rootRect = root.getBoundingClientRect();
  const br = bubbleEl.getBoundingClientRect();
  const gap = 8;
  const pad = 8;
  sheet.style.position = "absolute";
  sheet.style.right = "auto";
  sheet.style.bottom = "auto";
  const maxW = Math.min(320, Math.max(240, rootRect.width - pad * 2));
  sheet.style.width = `${Math.round(maxW)}px`;
  const h = sheet.offsetHeight || 0;
  let top = br.bottom - rootRect.top + gap;
  let left = br.left + br.width * 0.5 - rootRect.left - maxW * 0.5;
  left = Math.max(pad, Math.min(left, rootRect.width - maxW - pad));
  const spaceBelow = rootRect.bottom - br.bottom - gap;
  const effH = h > 8 ? h : 240;
  if (effH > spaceBelow - 6 && br.top - rootRect.top > effH + gap + pad) {
    top = br.top - rootRect.top - effH - gap;
  }
  const maxTop = rootRect.height - effH - pad;
  top = Math.max(pad, Math.min(top, maxTop));
  sheet.style.left = `${Math.round(left)}px`;
  sheet.style.top = `${Math.round(top)}px`;
}

function bindChatBubbleSheetDismissOnScroll() {
  document.getElementById("chat-messages")?.addEventListener("scroll", onChatBubbleScrollClose, { passive: true });
}

function unbindChatBubbleSheetDismissOnScroll() {
  document.getElementById("chat-messages")?.removeEventListener("scroll", onChatBubbleScrollClose);
}

function clearChatBubbleSheetLayoutStyles() {
  const sheet = document.querySelector("#chat-bubble-actions .chat-bubble-actions-sheet");
  if (!sheet) return;
  sheet.style.position = "";
  sheet.style.top = "";
  sheet.style.left = "";
  sheet.style.width = "";
  sheet.style.right = "";
  sheet.style.bottom = "";
}

