let activePhotoSlot = 0;

/** 读取当前套序号 0..n-1；兼容旧版存的是 0–14（多套 ×3 墙纸线性槽） */
function readDesktopPaletteIndex() {
  const D = window.XXJ_DB;
  if (!D) return 0;
  const raw = D.getKv(D.K.DESKTOP_STYLE_SLOT);
  const n = Number(raw);
  const len = DESKTOP_PALETTES.length;
  if (!Number.isFinite(n) || n < 0) return 0;
  if (n >= len) {
    return Math.floor(n / WALLS_PER_PALETTE) % len;
  }
  return n % len;
}

function writeDesktopPaletteIndex(pi) {
  const D = window.XXJ_DB;
  if (!D) return;
  D.setKv(D.K.DESKTOP_STYLE_SLOT, String(pi % DESKTOP_PALETTES.length));
}

/** 若库里仍是旧版大数字，折叠成当前套数范围，避免以后误读 */
function normalizeDesktopPaletteStorage() {
  const D = window.XXJ_DB;
  if (!D) return;
  const n = Number(D.getKv(D.K.DESKTOP_STYLE_SLOT));
  const len = DESKTOP_PALETTES.length;
  if (!Number.isFinite(n) || n < len) return;
  writeDesktopPaletteIndex(Math.floor(n / WALLS_PER_PALETTE) % len);
}

function applyDesktopStyleFromSlot() {
  normalizeDesktopPaletteStorage();
  const pi = readDesktopPaletteIndex();
  const pal = DESKTOP_PALETTES[pi];
  const wi = 0;
  const dark = document.body.classList.contains("dark");
  const vars = dark ? pal.dark : pal.light;
  const root = document.documentElement;
  for (const [key, val] of Object.entries(vars)) {
    root.style.setProperty(key, val);
  }
  applyDesktopCustomWallpaper(pal, wi, dark);
  if (phoneEl && document.getElementById("desktop-wallpaper")) {
    phoneEl.style.background = "";
  } else if (phoneEl) {
    phoneEl.style.background = pal.walls[wi];
  }
}

function applyDesktopCustomWallpaper(pal, wi, dark) {
  const wallEl = document.getElementById("desktop-wallpaper");
  if (!wallEl) return;
  const p = pal || DESKTOP_PALETTES[readDesktopPaletteIndex()];
  const wallIndex = wi != null ? wi : 0;
  const isDark = dark != null ? dark : document.body.classList.contains("dark");
  const custom = String(readDesktopWallpaperBgFromKv().src || "").trim();
  if (custom) {
    const overlay = isDark
      ? "linear-gradient(180deg, rgba(0,0,0,0.45) 0%, rgba(0,0,0,0.06) 42%, rgba(0,0,0,0.24) 100%)"
      : "linear-gradient(180deg, rgba(255,255,255,0.42) 0%, rgba(255,255,255,0.05) 36%, rgba(0,0,0,0.075) 100%)";
    wallEl.style.background = `${overlay}, ${cssBackgroundImageUrl(custom)} center/cover no-repeat`;
  } else {
    wallEl.style.background = p.walls[wallIndex];
  }
}

const GLOBAL_UI_TYPO_MIN_PX = 12;
const GLOBAL_UI_TYPO_MAX_PX = 22;
const GLOBAL_UI_TYPO_FONT_FILE_MAX = 5 * 1024 * 1024;
/** 与 body 默认无衬线栈一致，接在用户 font-family 之后 */
const GLOBAL_UI_TYPO_FALLBACK_SANS = `"DM Sans", "Noto Sans SC", system-ui, sans-serif`;

/**
 * 聊天壳内 UI 元在 style.css 单独写过 font-family 时需与用户装扮栈对齐。
 * 气泡正文默认用 --chat-msg-content-font（系统 UI 字体，非 body 的 DM Sans）；本表为装扮上传字体覆盖目标。
 */
const GLOBAL_UI_TYPO_CHAT_REL_SELECTORS = [
  ".settings-masthead-title",
  ".chat-scene-pull",
  ".chat-header-initial",
  ".chat-header-initial--user",
  ".chat-msg-bubble",
  ".chat-input",
  ".chat-photo-polaroid-line",
  ".chat-photo-polaroid-inner--desc",
  ".chat-memo-eyebrow",
  ".chat-memo-title-main",
  ".chat-memo-lead",
  ".chat-memo-panel-label",
  ".chat-more-grid-label",
  ".chat-more-quick-label",
  ".chat-more-list-title",
  ".chat-more-list-desc",
  ".chat-more-sheet-theme",
  ".chat-more-sheet-title",
  ".chat-more-sheet-sub",
  ".chat-more-sheet-label",
  ".chat-more-bento-title",
  ".chat-more-bento-desc",
  ".chat-send-choice-title",
  ".char-incoming-call-name",
  ".char-incoming-call-slab .chat-slab-spine-idx",
  ".chat-bubble-actions-card .chat-bubble-actions-title",
  ".chat-inner-voice-loading-title",
  ".chat-inner-voice-cap-title",
  ".chat-inner-voice-bubble-label",
  ".chat-inner-voice-bubble-text",
  "summary.chat-memo-tl-sum"
];

/** @param {string} stackExpr 已转义的 font-family 列表片段（可含引号字体名） */
function buildGlobalUiTypographyChatScopedRules(stackExpr) {
  const full = `${stackExpr}, ${GLOBAL_UI_TYPO_FALLBACK_SANS}`;
  const roots = ["#chat-screen", "#chat-call-screen", "#chat-video-call-screen", "#chat-offline-screen"];
  const lines = [];
  for (const r of roots) {
    for (const s of GLOBAL_UI_TYPO_CHAT_REL_SELECTORS) {
      lines.push(`${r} ${s}`);
    }
  }
  return `${lines.join(",\n")} {\n  font-family: ${full} !important;\n}`;
}

/** @param {unknown} raw */
function normalizeGlobalUiTypo(raw) {
  const base = {
    v: 1,
    rootSizePx: /** @type {number|null} */ (null),
    linkUrl: "",
    fontStack: "",
    faceFamily: "",
    faceSrcUrl: "",
    faceSrcDataUrl: ""
  };
  if (!raw || typeof raw !== "object") return base;
  const n = Number(/** @type {Record<string, unknown>} */ (raw).rootSizePx);
  if (Number.isFinite(n) && n >= GLOBAL_UI_TYPO_MIN_PX && n <= GLOBAL_UI_TYPO_MAX_PX) {
    base.rootSizePx = Math.round(n);
  }
  base.linkUrl = String(/** @type {Record<string, unknown>} */ (raw).linkUrl || "").trim();
  base.fontStack = String(/** @type {Record<string, unknown>} */ (raw).fontStack || "").trim();
  base.faceFamily = String(/** @type {Record<string, unknown>} */ (raw).faceFamily || "").trim();
  base.faceSrcUrl = String(/** @type {Record<string, unknown>} */ (raw).faceSrcUrl || "").trim();
  const du = String(/** @type {Record<string, unknown>} */ (raw).faceSrcDataUrl || "");
  base.faceSrcDataUrl = du.startsWith("data:") ? du : "";
  return base;
}

/** @param {ReturnType<typeof normalizeGlobalUiTypo>} t */
function isGlobalUiTypoKvEmpty(t) {
  return (
    !t.linkUrl &&
    !t.fontStack &&
    !t.faceFamily &&
    !t.faceSrcUrl &&
    !t.faceSrcDataUrl &&
    t.rootSizePx == null
  );
}

/** 写入 KV；全无有效项时删键，避免留下空对象 */
function persistGlobalUiTypo(raw) {
  const D = window.XXJ_DB;
  if (!D) return;
  const next = normalizeGlobalUiTypo(raw);
  if (isGlobalUiTypoKvEmpty(next)) D.delKv(D.K.GLOBAL_UI_TYPO);
  else D.setKv(D.K.GLOBAL_UI_TYPO, next);
  applyGlobalUiTypography();
}

function guessFontFileFormatFromUrl(url) {
  const u = String(url || "")
    .split("?")[0]
    .toLowerCase();
  if (u.endsWith(".woff2")) return "woff2";
  if (u.endsWith(".woff")) return "woff";
  if (u.endsWith(".ttf")) return "truetype";
  if (u.endsWith(".otf")) return "opentype";
  return "woff2";
}

function guessFontFormatFromDataUrl(dataUrl) {
  const head = String(dataUrl || "")
    .slice(0, 120)
    .toLowerCase();
  if (head.includes("font/woff2") || head.includes("woff2")) return "woff2";
  if (head.includes("font/woff")) return "woff";
  if (head.includes("font/ttf") || head.includes("truetype")) return "truetype";
  if (head.includes("font/otf") || head.includes("opentype")) return "opentype";
  return "woff2";
}

function cssEscapeForSingleQuotedUrl(s) {
  return String(s || "").replace(/\\/g, "\\\\").replace(/'/g, "\\'");
}

/** 应用装扮页的全局字体 / 根字号（含外链样式表、@font-face、body font-family） */
function applyGlobalUiTypography() {
  const D = window.XXJ_DB;
  const t = normalizeGlobalUiTypo(D ? D.getKv(D.K.GLOBAL_UI_TYPO) : undefined);

  let linkEl = document.getElementById("xxj-global-font-stylesheet");
  if (t.linkUrl && (t.linkUrl.startsWith("http://") || t.linkUrl.startsWith("https://"))) {
    if (!linkEl) {
      linkEl = document.createElement("link");
      linkEl.id = "xxj-global-font-stylesheet";
      linkEl.rel = "stylesheet";
      document.head.appendChild(linkEl);
    }
    linkEl.href = t.linkUrl;
  } else if (linkEl) {
    linkEl.remove();
  }

  const pieces = [];
  if (t.rootSizePx != null) {
    pieces.push(`html { font-size: ${t.rootSizePx}px !important; }`);
  }

  const fam = t.faceFamily.trim();
  const srcFile = (t.faceSrcDataUrl || t.faceSrcUrl || "").trim();
  if (fam && srcFile) {
    const fmt = t.faceSrcDataUrl ? guessFontFormatFromDataUrl(t.faceSrcDataUrl) : guessFontFileFormatFromUrl(srcFile);
    const famCss = cssEscapeForSingleQuotedUrl(fam);
    const srcCss = cssEscapeForSingleQuotedUrl(srcFile);
    pieces.push(
      `@font-face { font-family: '${famCss}'; src: url('${srcCss}') format('${fmt}'); font-display: swap; }`
    );
  }

  let stack = t.fontStack.trim();
  if (!stack && fam && srcFile) stack = `'${cssEscapeForSingleQuotedUrl(fam)}'`;
  if (stack) {
    const bodyStack = `${stack}, ${GLOBAL_UI_TYPO_FALLBACK_SANS}`;
    pieces.push(`body { font-family: ${bodyStack} !important; }`);
    pieces.push(buildGlobalUiTypographyChatScopedRules(stack));
  }

  let styleEl = document.getElementById("xxj-global-typography-style");
  if (!pieces.length) {
    if (styleEl) styleEl.textContent = "";
    return;
  }
  if (!styleEl) {
    styleEl = document.createElement("style");
    styleEl.id = "xxj-global-typography-style";
    document.head.appendChild(styleEl);
  }
  styleEl.textContent = pieces.join("\n");
}

/** 装扮 · 主屏 #app-grid（与 data-app 一致） */
const WARD_DESKTOP_HOME_ICON_APPS = [
  ["聊天", "主屏"],
  ["查岗", "主屏"],
  ["关系", "主屏"],
  ["人设", "主屏"],
  ["漫游", "主屏"],
  ["我的", "主屏"]
];

/** 装扮 · Dock 底栏（可与主屏分开；未设则沿用主屏同名片图标） */
const WARD_DESKTOP_DOCK_ICON_APPS = [
  ["我的", "Dock"],
  ["主线", "Dock"],
  ["消息", "Dock"],
  ["角色库", "Dock"]
];

/** 主屏「剧情」格已改为「查岗」；装扮 byApp 键名需迁移 */
const DESKTOP_APP_LEGACY_PLOT_SLOT = "剧情";
const DESKTOP_APP_CHECKUP_SLOT = "查岗";
/** 主屏「音乐」格已改为「漫游」 */
const DESKTOP_APP_LEGACY_MUSIC_SLOT = "音乐";
const DESKTOP_APP_ROAM_SLOT = "漫游";

/** @param {{ v: number, byApp: Record<string, string> }} pack */
function migratePlotSlotToCheckupInDesktopPack(pack) {
  const legacy = String(pack.byApp[DESKTOP_APP_LEGACY_PLOT_SLOT] || "").trim();
  if (!legacy) return false;
  const checkup = String(pack.byApp[DESKTOP_APP_CHECKUP_SLOT] || "").trim();
  if (!checkup) pack.byApp[DESKTOP_APP_CHECKUP_SLOT] = legacy;
  delete pack.byApp[DESKTOP_APP_LEGACY_PLOT_SLOT];
  return true;
}

/** @param {{ v: number, byApp: Record<string, string> }} pack */
function migrateMusicSlotToRoamInDesktopPack(pack) {
  const legacy = String(pack.byApp[DESKTOP_APP_LEGACY_MUSIC_SLOT] || "").trim();
  if (!legacy) return false;
  const roam = String(pack.byApp[DESKTOP_APP_ROAM_SLOT] || "").trim();
  if (!roam) pack.byApp[DESKTOP_APP_ROAM_SLOT] = legacy;
  delete pack.byApp[DESKTOP_APP_LEGACY_MUSIC_SLOT];
  return true;
}

/** 清除主屏/Dock 图标或格底图时：查岗须连同旧键「剧情」一并删，否则 normalize 会再次灌回。 */
function deleteDesktopDecorAppEntry(pack, app) {
  delete pack.byApp[app];
  if (app === DESKTOP_APP_CHECKUP_SLOT) delete pack.byApp[DESKTOP_APP_LEGACY_PLOT_SLOT];
  if (app === DESKTOP_APP_ROAM_SLOT) delete pack.byApp[DESKTOP_APP_LEGACY_MUSIC_SLOT];
}

/** 写入查岗等格装饰时去掉残留「剧情」键，避免与查岗并存。 */
function setDesktopDecorAppEntry(pack, app, url) {
  if (app === DESKTOP_APP_CHECKUP_SLOT) delete pack.byApp[DESKTOP_APP_LEGACY_PLOT_SLOT];
  if (app === DESKTOP_APP_ROAM_SLOT) delete pack.byApp[DESKTOP_APP_LEGACY_MUSIC_SLOT];
  pack.byApp[app] = url;
}

/** 启动 / 导入后：迁移并落盘清理 KV 里残留的旧主屏格键（剧情→查岗、音乐→漫游） */
function persistPlotToCheckupDecorMigrationIfNeeded() {
  const D = window.XXJ_DB;
  if (!D?.K) return;
  const writers = [
    [D.K.DESKTOP_APP_ICONS, writeDesktopAppIconsToKv],
    [D.K.DESKTOP_DOCK_APP_ICONS, writeDesktopDockAppIconsToKv],
    [D.K.DESKTOP_APP_TILE_BGS, writeDesktopAppTileBgsToKv]
  ];
  for (const [key, writeFn] of writers) {
    const raw = D.getKv(key);
    if (raw === undefined) continue;
    const rawBy =
      raw && typeof raw === "object" && !Array.isArray(raw) && raw.byApp && typeof raw.byApp === "object"
        ? /** @type {Record<string, unknown>} */ (raw.byApp)
        : {};
    const hasPlot = !!String(rawBy[DESKTOP_APP_LEGACY_PLOT_SLOT] || "").trim();
    const hasMusic = !!String(rawBy[DESKTOP_APP_LEGACY_MUSIC_SLOT] || "").trim();
    if (!hasPlot && !hasMusic) continue;
    writeFn(normalizeDesktopAppIcons(raw));
  }
}

/** @param {string} key @param {unknown} val */
function migratePlotDecorKvValue(key, val) {
  const K = window.XXJ_DB?.K;
  if (
    !K ||
    (key !== K.DESKTOP_APP_ICONS && key !== K.DESKTOP_DOCK_APP_ICONS && key !== K.DESKTOP_APP_TILE_BGS)
  ) {
    return val;
  }
  return normalizeDesktopAppIcons(val);
}

/** @param {HTMLSelectElement | null} sel @param {string[][]} apps */
function wardFillDesktopIconUrlSelect(sel, apps) {
  if (!sel || !apps.length) return;
  if (sel.dataset.built) return;
  sel.dataset.built = "1";
  sel.replaceChildren(new Option("选择应用…", ""));
  for (const [app] of apps) sel.appendChild(new Option(app, app));
}

function ensureWardDesktopIconEditorsBuilt() {
  const fillMount = (mountId, apps) => {
    const mount = document.getElementById(mountId);
    if (mount && !mount.dataset.built) {
      mount.dataset.built = "1";
      mount.innerHTML = apps
        .map(
          ([app, hint]) =>
            `<div class="ward-desktop-icon-row" data-desktop-icon-app="${app}" role="listitem">` +
            `<div class="ward-desktop-icon-meta"><span class="ward-desktop-icon-name">${app}</span>` +
            `<span class="ward-desktop-icon-hint">${hint}</span></div>` +
            `<img class="ward-desktop-icon-preview is-empty" alt="" width="40" height="40" decoding="async" />` +
            `<input class="ward-desktop-icon-file" type="file" accept="image/*" hidden />` +
            `<button type="button" class="chip ghost chip-xs ward-desktop-icon-pick">上传</button>` +
            `<button type="button" class="chip ghost chip-xs ward-desktop-icon-clear">清除</button></div>`
        )
        .join("");
    }
  };
  fillMount("ward-desktop-home-icons-mount", WARD_DESKTOP_HOME_ICON_APPS);
  fillMount("ward-dock-icons-mount", WARD_DESKTOP_DOCK_ICON_APPS);
  const selH = document.getElementById("ward-desktop-home-icon-url-app");
  if (selH instanceof HTMLSelectElement) wardFillDesktopIconUrlSelect(selH, WARD_DESKTOP_HOME_ICON_APPS);
  const selD = document.getElementById("ward-dock-icon-url-app");
  if (selD instanceof HTMLSelectElement) wardFillDesktopIconUrlSelect(selD, WARD_DESKTOP_DOCK_ICON_APPS);
}

/** @param {unknown} raw */
function normalizeDesktopAppIcons(raw) {
  /** @type {{ v: number, byApp: Record<string, string> }} */
  const base = { v: 1, byApp: {} };
  if (!raw || typeof raw !== "object") return base;
  const o = /** @type {Record<string, unknown>} */ (raw);
  const by = o.byApp;
  if (!by || typeof by !== "object") return base;
  for (const [k, v] of Object.entries(by)) {
    const s = String(v || "").trim();
    if (!s) continue;
    if (s.startsWith("data:image/") || s.startsWith("https://") || s.startsWith("http://")) {
      base.byApp[String(k)] = s;
    }
  }
  migratePlotSlotToCheckupInDesktopPack(base);
  migrateMusicSlotToRoamInDesktopPack(base);
  return base;
}

function readDesktopAppIconsFromKv() {
  const D = window.XXJ_DB;
  return normalizeDesktopAppIcons(D ? D.getKv(D.K.DESKTOP_APP_ICONS) : undefined);
}

/** @param {{ v: number, byApp: Record<string, string> }} pack */
function writeDesktopAppIconsToKv(pack) {
  const D = window.XXJ_DB;
  if (!D) return;
  D.setKv(D.K.DESKTOP_APP_ICONS, normalizeDesktopAppIcons(pack));
}

function readDesktopDockAppIconsFromKv() {
  const D = window.XXJ_DB;
  return normalizeDesktopAppIcons(D ? D.getKv(D.K.DESKTOP_DOCK_APP_ICONS) : undefined);
}

/** @param {{ v: number, byApp: Record<string, string> }} pack */
function writeDesktopDockAppIconsToKv(pack) {
  const D = window.XXJ_DB;
  if (!D) return;
  D.setKv(D.K.DESKTOP_DOCK_APP_ICONS, normalizeDesktopAppIcons(pack));
}

function refreshDesktopAppIconsUi() {
  applyDesktopAppIcons();
  syncWardDesktopIconForms();
}

/** @param {"home" | "dock"} scope @param {(pack: { v: number, byApp: Record<string, string> }) => void} fn */
function mutateDesktopAppIconsKv(scope, fn) {
  const pack = scope === "dock" ? readDesktopDockAppIconsFromKv() : readDesktopAppIconsFromKv();
  fn(pack);
  if (scope === "dock") writeDesktopDockAppIconsToKv(pack);
  else writeDesktopAppIconsToKv(pack);
  refreshDesktopAppIconsUi();
}

function applyDesktopAppIcons() {
  const homePack = readDesktopAppIconsFromKv();
  const dockPack = readDesktopDockAppIconsFromKv();
  const paint = (btn, src) => {
    if (!(btn instanceof HTMLElement)) return;
    const ic = btn.querySelector(":scope > i.ph");
    let img = btn.querySelector(":scope > img.home-app-icon");
    if (src) {
      if (!img) {
        img = document.createElement("img");
        img.className = "home-app-icon";
        img.alt = "";
        img.loading = "eager";
        img.decoding = "async";
        img.referrerPolicy = "no-referrer";
        img.onerror = () => {
          img.remove();
          btn.classList.remove("has-home-app-icon");
        };
        if (ic) btn.insertBefore(img, ic);
        else btn.appendChild(img);
      }
      if (String(img.getAttribute("src") || "") !== src) img.src = src;
      btn.classList.add("has-home-app-icon");
    } else {
      img?.remove();
      btn.classList.remove("has-home-app-icon");
    }
  };
  document.querySelectorAll("#app-grid [data-app]").forEach((btn) => {
    const app = btn instanceof HTMLElement ? btn.dataset.app : "";
    if (!app) return;
    paint(btn, homePack.byApp[app]);
  });
  document.querySelectorAll(".dock-stack footer.dock [data-app]").forEach((btn) => {
    const app = btn instanceof HTMLElement ? btn.dataset.app : "";
    if (!app) return;
    const src = dockPack.byApp[app] || homePack.byApp[app];
    paint(btn, src);
  });
}

