function syncWardDesktopIconForms() {
  const home = readDesktopAppIconsFromKv();
  const dock = readDesktopDockAppIconsFromKv();
  const fillPreview = (row, url) => {
    const prev = row.querySelector(".ward-desktop-icon-preview");
    if (!(prev instanceof HTMLImageElement)) return;
    if (url) {
      prev.src = url;
      prev.classList.remove("is-empty");
    } else {
      prev.removeAttribute("src");
      prev.classList.add("is-empty");
    }
  };
  document.querySelectorAll("#ward-desktop-home-icons-panel .ward-desktop-icon-row[data-desktop-icon-app]").forEach((row) => {
    const app = row.getAttribute("data-desktop-icon-app");
    if (!app) return;
    fillPreview(row, home.byApp[app]);
  });
  document.querySelectorAll("#ward-dock-icons-panel .ward-desktop-icon-row[data-desktop-icon-app]").forEach((row) => {
    const app = row.getAttribute("data-desktop-icon-app");
    if (!app) return;
    const effective = dock.byApp[app] || home.byApp[app];
    fillPreview(row, effective || "");
  });
}

