function readGlobalUiTypoFromKv() {
  const D = window.XXJ_DB;
  return normalizeGlobalUiTypo(D ? D.getKv(D.K.GLOBAL_UI_TYPO) : undefined);
}

function readGlobalUiTypoPresetsFromKv() {
  const D = window.XXJ_DB;
  if (!D) return [];
  const arr = D.getKv(D.K.GLOBAL_UI_TYPO_PRESETS);
  return Array.isArray(arr) ? arr : [];
}

function writeGlobalUiTypoPresetsToKv(presets) {
  const D = window.XXJ_DB;
  if (!D) return;
  D.setKv(D.K.GLOBAL_UI_TYPO_PRESETS, presets);
}

/** @param {unknown} raw */
function normalizeGlobalUiTypoPresetEntry(raw) {
  if (!raw || typeof raw !== "object") return null;
  const id = String(/** @type {Record<string, unknown>} */ (raw).id || "").trim();
  if (!id) return null;
  const t = normalizeGlobalUiTypo(raw);
  const name = String(/** @type {Record<string, unknown>} */ (raw).name || "").trim() || "未命名";
  return {
    id,
    name,
    linkUrl: t.linkUrl,
    fontStack: t.fontStack,
    faceFamily: t.faceFamily,
    faceSrcUrl: t.faceSrcUrl,
    faceSrcDataUrl: t.faceSrcDataUrl,
    rootSizePx: t.rootSizePx
  };
}

function applyGlobalUiTypoPresetEntry(pr) {
  if (!pr || typeof pr !== "object") return;
  const snap = normalizeGlobalUiTypoPresetEntry(pr);
  if (!snap || isGlobalUiTypoKvEmpty(snap)) return;
  persistGlobalUiTypo({
    v: 1,
    linkUrl: snap.linkUrl,
    fontStack: snap.fontStack,
    faceFamily: snap.faceFamily,
    faceSrcUrl: snap.faceSrcUrl,
    faceSrcDataUrl: snap.faceSrcDataUrl,
    rootSizePx: snap.rootSizePx
  });
  syncWardrobeTypoForm();
  showToast(`已套用「${snap.name}」`);
}

function renderGlobalUiTypoPresetListInto(containerId) {
  const root = document.getElementById(containerId);
  if (!root) return;
  root.replaceChildren();
  const presets = readGlobalUiTypoPresetsFromKv();
  if (!presets.length) {
    const p = document.createElement("p");
    p.className = "settings-ai-key-note";
    p.textContent = "暂无预设";
    p.style.margin = "0";
    root.appendChild(p);
    return;
  }
  for (const raw of presets) {
    const pr = normalizeGlobalUiTypoPresetEntry(raw);
    if (!pr) continue;
    const { id, name } = pr;
    const row = document.createElement("div");
    row.className = "chat-ui-css-preset-row";
    const lab = document.createElement("span");
    lab.className = "chat-ui-css-preset-name";
    const sizeHint = pr.rootSizePx != null ? ` · ${pr.rootSizePx}px` : "";
    lab.textContent = `${name}${sizeHint}`;
    lab.title = name;
    const actions = document.createElement("div");
    actions.className = "chat-ui-css-preset-actions";
    const useBtn = document.createElement("button");
    useBtn.type = "button";
    useBtn.className = "chip ghost chip-xs";
    useBtn.textContent = "套用";
    useBtn.addEventListener("click", () => applyGlobalUiTypoPresetEntry(pr));
    const delBtn = document.createElement("button");
    delBtn.type = "button";
    delBtn.className = "chip ghost chip-xs";
    delBtn.textContent = "删除";
    delBtn.addEventListener("click", () => {
      if (!window.confirm(`确定删除预设「${name}」？`)) return;
      const next = readGlobalUiTypoPresetsFromKv().filter((x) => String(x?.id || "") !== id);
      writeGlobalUiTypoPresetsToKv(next);
      renderGlobalUiTypoPresetListInto("ward-typo-presets");
      showToast("已删除");
    });
    actions.append(useBtn, delBtn);
    row.append(lab, actions);
    root.appendChild(row);
  }
}

function saveWardrobeTypoPresetFromForm() {
  const useEl = document.getElementById("ward-font-use-size");
  const useSize = useEl && useEl instanceof HTMLInputElement ? useEl.checked : false;
  const snap = collectGlobalUiTypoFromWardrobeForm({ useCustomSize: useSize });
  if (isGlobalUiTypoKvEmpty(snap)) {
    showToast("请先填写字体或启用字号后再存为预设");
    return;
  }
  const hasFile = Boolean(snap.faceSrcUrl || snap.faceSrcDataUrl);
  if (snap.faceFamily && !hasFile) {
    showToast("填写了自定义字体名时，请提供直链或上传文件");
    return;
  }
  if (hasFile && !snap.faceFamily) {
    showToast("使用字体文件时请填写「自定义字体名」");
    return;
  }
  if (snap.linkUrl && !snap.linkUrl.startsWith("http://") && !snap.linkUrl.startsWith("https://")) {
    showToast("字体样式表链接需为 http(s) URL");
    return;
  }
  const nameRaw = window.prompt("预设名称", "我的字体");
  if (nameRaw == null) return;
  const name = String(nameRaw).trim();
  if (!name) {
    showToast("名称不能为空");
    return;
  }
  const presets = readGlobalUiTypoPresetsFromKv().filter(Boolean);
  presets.push({
    id: `typo_${Date.now()}`,
    name,
    linkUrl: snap.linkUrl,
    fontStack: snap.fontStack,
    faceFamily: snap.faceFamily,
    faceSrcUrl: snap.faceSrcUrl,
    faceSrcDataUrl: snap.faceSrcDataUrl,
    rootSizePx: snap.rootSizePx
  });
  writeGlobalUiTypoPresetsToKv(presets);
  renderGlobalUiTypoPresetListInto("ward-typo-presets");
  showToast("已保存预设");
}

function syncWardrobeTypoForm() {
  const t = readGlobalUiTypoFromKv();
  const link = document.getElementById("ward-font-link");
  const stack = document.getElementById("ward-font-stack");
  const face = document.getElementById("ward-font-face-name");
  const srcUrl = document.getElementById("ward-font-src-url");
  const range = document.getElementById("ward-font-size-range");
  const val = document.getElementById("ward-font-size-val");
  if (link && link instanceof HTMLInputElement) link.value = t.linkUrl;
  if (stack && stack instanceof HTMLInputElement) stack.value = t.fontStack;
  if (face && face instanceof HTMLInputElement) face.value = t.faceFamily;
  if (srcUrl && srcUrl instanceof HTMLInputElement) srcUrl.value = t.faceSrcUrl;
  const fi = document.getElementById("ward-font-file-input");
  if (fi && fi instanceof HTMLInputElement) fi.value = "";
  const hint = document.getElementById("ward-font-file-hint");
  if (hint) {
    hint.textContent = t.faceSrcDataUrl ? "已缓存本机上传的字体文件" : "未上传";
  }
  const sz = t.rootSizePx != null ? t.rootSizePx : 16;
  if (range && range instanceof HTMLInputElement) {
    range.value = String(sz);
  }
  const useSz = document.getElementById("ward-font-use-size");
  if (useSz && useSz instanceof HTMLInputElement) {
    useSz.checked = t.rootSizePx != null;
  }
  if (val) {
    val.textContent =
      t.rootSizePx != null
        ? `当前根字号 ${t.rootSizePx}px（聊天消息气泡、输入栏等 rem 会联动）`
        : "未启用：跟随浏览器默认（通常 16px）";
  }
}

function collectGlobalUiTypoFromWardrobeForm(opts) {
  const useSize = Boolean(opts && opts.useCustomSize);
  const linkEl = document.getElementById("ward-font-link");
  const stackEl = document.getElementById("ward-font-stack");
  const faceEl = document.getElementById("ward-font-face-name");
  const srcUrlEl = document.getElementById("ward-font-src-url");
  const range = document.getElementById("ward-font-size-range");
  const linkUrl = linkEl && linkEl instanceof HTMLInputElement ? linkEl.value.trim() : "";
  const fontStack = stackEl && stackEl instanceof HTMLInputElement ? stackEl.value.trim() : "";
  const faceFamily = faceEl && faceEl instanceof HTMLInputElement ? faceEl.value.trim() : "";
  const faceSrcUrl = srcUrlEl && srcUrlEl instanceof HTMLInputElement ? srcUrlEl.value.trim() : "";
  let rootSizePx = null;
  if (useSize && range && range instanceof HTMLInputElement) {
    const n = Math.floor(Number(range.value));
    if (Number.isFinite(n) && n >= GLOBAL_UI_TYPO_MIN_PX && n <= GLOBAL_UI_TYPO_MAX_PX) {
      rootSizePx = n;
    }
  }
  const prev = readGlobalUiTypoFromKv();
  return normalizeGlobalUiTypo({
    v: 1,
    rootSizePx,
    linkUrl,
    fontStack,
    faceFamily,
    faceSrcUrl,
    faceSrcDataUrl: prev.faceSrcDataUrl
  });
}

function saveWardrobeTypoFromForm() {
  const D = window.XXJ_DB;
  if (!D) return;
  const useEl = document.getElementById("ward-font-use-size");
  const useSize = useEl && useEl instanceof HTMLInputElement ? useEl.checked : false;
  const next = collectGlobalUiTypoFromWardrobeForm({ useCustomSize: useSize });
  if (next.linkUrl && !next.linkUrl.startsWith("http://") && !next.linkUrl.startsWith("https://")) {
    showToast("字体样式表链接需为 http(s) URL");
    return;
  }
  const hasFile = Boolean(next.faceSrcUrl || next.faceSrcDataUrl);
  if (next.faceFamily && !hasFile) {
    showToast("填写了自定义字体名时，请提供直链或上传文件");
    return;
  }
  if (hasFile && !next.faceFamily) {
    showToast("使用字体文件时请填写「自定义字体名」");
    return;
  }
  persistGlobalUiTypo(next);
  if (next.linkUrl && !next.fontStack && !hasFile) {
    showToast("已保存外链；若页面字体未变，请填写「font-family」列表");
    return;
  }
  showToast("已保存并应用");
}

function resetWardrobeTypoToDefault() {
  if (!window.XXJ_DB) return;
  persistGlobalUiTypo(undefined);
  syncWardrobeTypoForm();
  showToast("已恢复默认");
}

function clearWardrobeFontFileCache() {
  if (!window.XXJ_DB) return;
  const prev = readGlobalUiTypoFromKv();
  persistGlobalUiTypo({ ...prev, faceSrcDataUrl: "" });
  syncWardrobeTypoForm();
  showToast("已清除本机上传的字体缓存");
}

const WARDROBE_CHAT_CSS_PREVIEW_STYLE_ID = "xxj-wardrobe-chat-css-preview-style";
const CHAT_UI_CSS_PRESET_KIND_CLASSIC = "classic";
const CHAT_UI_CSS_PRESET_KIND_GLASS = "glass";
/** @type {"classic" | "glass"} */
let wardrobeChatCssEditKind = CHAT_UI_CSS_PRESET_KIND_CLASSIC;
/** @type {{ v: number, activeKind: string, classicCss: string, glassCss: string } | null} */
let wardrobeChatCssBundleDraft = null;
let wardrobeChatCssPreviewTid = 0;

/** 将装扮里写的 #chat-screen 前缀映射到预览容器，使模板无需手改 */
function rewriteChatScreenRootForWardrobePreview(css) {
  return String(css ?? "")
    .replace(/#chat-screen\.chat-screen--theme-glass/g, "#wardrobe-chat-css-preview.chat-screen--theme-glass")
    .replace(/#chat-screen\b/g, "#wardrobe-chat-css-preview");
}

function mountWardrobeChatCssPreviewFromEditor() {
  const ta = document.getElementById("ward-chat-css-input");
  const css = ta && ta instanceof HTMLTextAreaElement ? String(ta.value || "") : "";
  const head = document.head;
  if (!head) return;
  let el = document.getElementById(WARDROBE_CHAT_CSS_PREVIEW_STYLE_ID);
  if (!el) {
    el = document.createElement("style");
    el.id = WARDROBE_CHAT_CSS_PREVIEW_STYLE_ID;
    head.appendChild(el);
  }
  el.textContent = rewriteChatScreenRootForWardrobePreview(css);
  const preview = document.getElementById("wardrobe-chat-css-preview");
  if (preview instanceof HTMLElement) {
    preview.classList.toggle(
      "chat-screen--theme-glass",
      getWardrobeChatCssEditKind() === CHAT_UI_CSS_PRESET_KIND_GLASS || /@theme-glass\b/.test(css)
    );
  }
}

function getWardrobeChatCssEditKind() {
  return wardrobeChatCssEditKind === CHAT_UI_CSS_PRESET_KIND_GLASS
    ? CHAT_UI_CSS_PRESET_KIND_GLASS
    : CHAT_UI_CSS_PRESET_KIND_CLASSIC;
}

function chatUiCssPresetKindLabel(kind) {
  return kind === CHAT_UI_CSS_PRESET_KIND_GLASS ? "玻璃" : "经典";
}

function inferChatUiCssPresetKindFromCss(css, fallbackKind) {
  if (/@theme-glass\b/.test(String(css || ""))) return CHAT_UI_CSS_PRESET_KIND_GLASS;
  return fallbackKind === CHAT_UI_CSS_PRESET_KIND_GLASS
    ? CHAT_UI_CSS_PRESET_KIND_GLASS
    : CHAT_UI_CSS_PRESET_KIND_CLASSIC;
}

/** @param {unknown} raw */
function normalizeThreadUiCssPresetEntry(raw) {
  if (!raw || typeof raw !== "object") return null;
  const id = String(raw.id || "").trim();
  if (!id || isBuiltinChatUiCssPresetId(id)) return null;
  const css = typeof raw.css === "string" ? raw.css : "";
  const kind = inferChatUiCssPresetKindFromCss(
    css,
    String(raw.kind || "").trim() === CHAT_UI_CSS_PRESET_KIND_GLASS
      ? CHAT_UI_CSS_PRESET_KIND_GLASS
      : CHAT_UI_CSS_PRESET_KIND_CLASSIC
  );
  return {
    id,
    name: String(raw.name || "未命名").trim() || "未命名",
    css,
    kind
  };
}

function readThreadUiCssPresetsFromKv() {
  const D = window.XXJ_DB;
  if (!D) return [];
  const arr = D.getKv(D.K.CHAT_THREAD_UI_CSS_PRESETS);
  if (!Array.isArray(arr)) return [];
  const out = [];
  let migrated = false;
  for (const raw of arr) {
    const pr = normalizeThreadUiCssPresetEntry(raw);
    if (!pr) {
      if (raw && isBuiltinChatUiCssPresetId(String(raw.id || ""))) migrated = true;
      continue;
    }
    if (!raw.kind || raw.kind !== pr.kind) migrated = true;
    out.push(pr);
  }
  if (migrated) writeThreadUiCssPresetsToKv(out);
  return out;
}

function readGlobalChatSurfaceBundleFromKv() {
  const D = window.XXJ_DB;
  const empty = {
    v: 2,
    activeKind: CHAT_UI_CSS_PRESET_KIND_CLASSIC,
    classicCss: "",
    glassCss: ""
  };
  if (!D) return { ...empty };
  const raw = D.getKv(D.K.GLOBAL_CHAT_SURFACE_CSS);
  if (raw && typeof raw === "object" && Number(raw.v) === 2) {
    const activeKind =
      String(raw.activeKind || "").trim() === CHAT_UI_CSS_PRESET_KIND_GLASS
        ? CHAT_UI_CSS_PRESET_KIND_GLASS
        : CHAT_UI_CSS_PRESET_KIND_CLASSIC;
    return {
      v: 2,
      activeKind,
      classicCss: typeof raw.classicCss === "string" ? raw.classicCss : "",
      glassCss: typeof raw.glassCss === "string" ? raw.glassCss : ""
    };
  }
  const legacy =
    raw && typeof raw === "object" && raw.css != null ? String(raw.css) : typeof raw === "string" ? raw : "";
  if (!legacy.trim()) return { ...empty };
  const glass = /@theme-glass\b/.test(legacy);
  return {
    v: 2,
    activeKind: glass ? CHAT_UI_CSS_PRESET_KIND_GLASS : CHAT_UI_CSS_PRESET_KIND_CLASSIC,
    classicCss: glass ? "" : legacy,
    glassCss: glass ? legacy : ""
  };
}

function writeGlobalChatSurfaceBundleToKv(bundle) {
  const D = window.XXJ_DB;
  if (!D) return;
  const b = bundle && typeof bundle === "object" ? bundle : readGlobalChatSurfaceBundleFromKv();
  const activeKind =
    String(b.activeKind || "").trim() === CHAT_UI_CSS_PRESET_KIND_GLASS
      ? CHAT_UI_CSS_PRESET_KIND_GLASS
      : CHAT_UI_CSS_PRESET_KIND_CLASSIC;
  const classicCss = String(b.classicCss || "");
  const glassCss = String(b.glassCss || "");
  /* 双槽可空，但须记住全机 classic/glass 选择（装扮点选即生效） */
  D.setKv(D.K.GLOBAL_CHAT_SURFACE_CSS, {
    v: 2,
    activeKind,
    classicCss,
    glassCss
  });
}

function readWardrobeChatCssBundleDraft() {
  if (!wardrobeChatCssBundleDraft) {
    wardrobeChatCssBundleDraft = readGlobalChatSurfaceBundleFromKv();
  }
  return wardrobeChatCssBundleDraft;
}

function stashWardrobeEditorIntoBundleDraft() {
  const ta = document.getElementById("ward-chat-css-input");
  if (!(ta instanceof HTMLTextAreaElement)) return readWardrobeChatCssBundleDraft();
  const draft = readWardrobeChatCssBundleDraft();
  if (getWardrobeChatCssEditKind() === CHAT_UI_CSS_PRESET_KIND_GLASS) {
    draft.glassCss = String(ta.value || "");
  } else {
    draft.classicCss = String(ta.value || "");
  }
  return draft;
}

/** 保存装扮 CSS 时写入全机 activeKind（与正在编辑的经典/玻璃槽一致） */
function persistGlobalChatSurfaceActiveKind(kind) {
  const next =
    String(kind || "").trim() === CHAT_UI_CSS_PRESET_KIND_GLASS
      ? CHAT_UI_CSS_PRESET_KIND_GLASS
      : CHAT_UI_CSS_PRESET_KIND_CLASSIC;
  const draft = readWardrobeChatCssBundleDraft();
  draft.activeKind = next;
  writeGlobalChatSurfaceBundleToKv(draft);
  return draft;
}

function setWardrobeChatCssEditKind(kind, opts) {
  const next =
    String(kind || "").trim() === CHAT_UI_CSS_PRESET_KIND_GLASS
      ? CHAT_UI_CSS_PRESET_KIND_GLASS
      : CHAT_UI_CSS_PRESET_KIND_CLASSIC;
  if (!opts?.skipStash) stashWardrobeEditorIntoBundleDraft();
  wardrobeChatCssEditKind = next;
  const draft = readWardrobeChatCssBundleDraft();
  const ta = document.getElementById("ward-chat-css-input");
  if (ta instanceof HTMLTextAreaElement) {
    ta.value =
      next === CHAT_UI_CSS_PRESET_KIND_GLASS ? String(draft.glassCss || "") : String(draft.classicCss || "");
  }
  scheduleWardrobeChatCssPreviewUpdate();
}

function scheduleWardrobeChatCssPreviewUpdate() {
  window.clearTimeout(wardrobeChatCssPreviewTid);
  wardrobeChatCssPreviewTid = window.setTimeout(() => {
    wardrobeChatCssPreviewTid = 0;
    mountWardrobeChatCssPreviewFromEditor();
  }, 120);
}

function readWardrobeCombinedGlobalChatCssForEditor() {
  const draft = readWardrobeChatCssBundleDraft();
  const im =
    getWardrobeChatCssEditKind() === CHAT_UI_CSS_PRESET_KIND_GLASS
      ? String(draft.glassCss || "")
      : String(draft.classicCss || "");
  const off = String(readGlobalOfflineChatSurfaceCssFromKv() || "").trim();
  if (!off) return im;
  const imTrim = im.trim();
  if (!imTrim) return readGlobalOfflineChatSurfaceCssFromKv();
  return `${imTrim}\n\n${off}`;
}

function syncWardrobeGlobalChatCssForm() {
  wardrobeChatCssBundleDraft = null;
  const bundle = readGlobalChatSurfaceBundleFromKv();
  wardrobeChatCssEditKind = bundle.activeKind;
  const ta = document.getElementById("ward-chat-css-input");
  if (ta instanceof HTMLTextAreaElement) {
    ta.value = readWardrobeCombinedGlobalChatCssForEditor();
  }
  mountWardrobeChatCssPreviewFromEditor();
}

function saveWardrobeGlobalChatCssFromForm() {
  const ta = document.getElementById("ward-chat-css-input");
  if (!(ta instanceof HTMLTextAreaElement)) return;
  stashWardrobeEditorIntoBundleDraft();
  persistGlobalChatSurfaceActiveKind(getWardrobeChatCssEditKind());
  wardrobeChatCssBundleDraft = null;
  writeGlobalOfflineChatSurfaceCssToKv("");
  mountChatSurfaceCssLayers();
  mountWardrobeChatCssPreviewFromEditor();
  showToast(
    getWardrobeChatCssEditKind() === CHAT_UI_CSS_PRESET_KIND_GLASS
      ? "已保存到玻璃槽（玻璃主题密谈生效）"
      : "已保存到经典槽（经典主题密谈生效）"
  );
}

function clearWardrobeGlobalChatCssFromForm() {
  const draft = stashWardrobeEditorIntoBundleDraft();
  if (getWardrobeChatCssEditKind() === CHAT_UI_CSS_PRESET_KIND_GLASS) {
    draft.glassCss = "";
  } else {
    draft.classicCss = "";
  }
  wardrobeChatCssBundleDraft = draft;
  const ta = document.getElementById("ward-chat-css-input");
  if (ta instanceof HTMLTextAreaElement) ta.value = "";
  scheduleWardrobeChatCssPreviewUpdate();
  showToast(`已清空当前「${chatUiCssPresetKindLabel(getWardrobeChatCssEditKind())}」槽位（点保存后全机生效）`);
}

function saveWardrobeChatCssPresetFromKind(kind) {
  const ta = document.getElementById("ward-chat-css-input");
  if (!(ta instanceof HTMLTextAreaElement)) return;
  const cssStr = String(ta.value || "").trim();
  if (!cssStr) {
    showToast("内容为空");
    return;
  }
  const presetKind =
    String(kind || "").trim() === CHAT_UI_CSS_PRESET_KIND_GLASS
      ? CHAT_UI_CSS_PRESET_KIND_GLASS
      : CHAT_UI_CSS_PRESET_KIND_CLASSIC;
  const defaultName =
    presetKind === CHAT_UI_CSS_PRESET_KIND_GLASS ? "我的玻璃覆盖" : "我的经典密谈壳";
  const nameRaw = window.prompt(`${chatUiCssPresetKindLabel(presetKind)}预设名称`, defaultName);
  if (nameRaw == null) return;
  const name = String(nameRaw).trim();
  if (!name) {
    showToast("名称不能为空");
    return;
  }
  const presets = readThreadUiCssPresetsFromKv();
  presets.push({
    id: `css_${Date.now()}`,
    name,
    css: String(ta.value || ""),
    kind: presetKind
  });
  writeThreadUiCssPresetsToKv(presets);
  refreshChatUiCssPresetLists();
  showToast(`已保存${chatUiCssPresetKindLabel(presetKind)}预设`);
}

function saveWardrobeOfflineChatCssPresetFromForm() {
  const ta = document.getElementById("ward-chat-css-input");
  if (!ta || !(ta instanceof HTMLTextAreaElement)) return;
  const cssStr = String(ta.value || "").trim();
  if (!cssStr) {
    showToast("内容为空");
    return;
  }
  const nameRaw = window.prompt("线下预设名称", "我的晤面壳");
  if (nameRaw == null) return;
  const name = String(nameRaw).trim();
  if (!name) {
    showToast("名称不能为空");
    return;
  }
  const presets = readOfflineThreadUiCssPresetsFromKv().filter(Boolean);
  presets.push({ id: `offcss_${Date.now()}`, name, css: String(ta.value || "") });
  writeOfflineThreadUiCssPresetsToKv(presets);
  refreshChatUiCssPresetLists();
  showToast("已保存线下预设");
}

function closeWardrobeScreen() {
  const ws = document.getElementById("wardrobe-screen");
  ws?.classList.remove("is-open");
  ws?.setAttribute("aria-hidden", "true");
}

function openWardrobeScreen() {
  closeMyScreen();
  closeSettings();
  closeCharScreen();
  closeWorldBookScreen();
  closeChatScreen();
  closeChatListScreen();
  closeStickerScreen();
  closeMinimaxSheet();
  closeImageGenSheet();
  closeChatDetailImageStyleSheet();
  const ws = document.getElementById("wardrobe-screen");
  if (ws) {
    ws.classList.add("is-open");
    ws.setAttribute("aria-hidden", "false");
  }
  requestAnimationFrame(() => {
  ensureWardDesktopIconEditorsBuilt();
  ensureWardDesktopTileBgEditorBuilt();
  syncWardrobeTypoForm();
  syncWardrobeGlobalChatCssForm();
  syncWardDesktopIconForms();
  syncWardDesktopTileBgForm();
  syncWardDesktopWallpaperForm();
  syncWardAppTowerBgForm();
  syncWardDockBgForm();
  syncWardHeroCardForm();
  refreshChatUiCssPresetLists();
  renderGlobalUiTypoPresetListInto("ward-typo-presets");
  });
}

function cycleDesktopPalette() {
  const next = (readDesktopPaletteIndex() + 1) % DESKTOP_PALETTES.length;
  writeDesktopPaletteIndex(next);
  applyDesktopStyleFromSlot();
  showToast(DESKTOP_PALETTES[next].label);
}

function formatTime() {
  const now = new Date();
  const hh = String(now.getHours()).padStart(2, "0");
  const mm = String(now.getMinutes()).padStart(2, "0");
  const timeText = `${hh}:${mm}`;
  timeNode.textContent = timeText;
  if (heroTimeNode) {
    heroTimeNode.textContent = timeText;
  }
}

function showToast(text, durationMs) {
  if (!toast) return;
  toast.textContent = text;
  toast.classList.add("show");
  window.clearTimeout(showToast.timer);
  const ms = Number(durationMs) > 0 ? Number(durationMs) : 1650;
  showToast.timer = window.setTimeout(() => {
    toast.classList.remove("show");
  }, ms);
}

// ============================================================
// KeepAliveModule — 后台保活：静音音视频 / Worker / Web Lock / Wake Lock / Media Session / IDB
// 后台保活：iOS 静音视频环、Periodic Sync 唤醒、媒体重播退避
// ============================================================
const KeepAliveModule = (() => {
  let active = false;
  let onTick = null;
  let lastTick = 0;
  let audioEl = null;
  let audioCtx = null;
  let oscillator = null;
  let gainNode = null;
  let videoEl = null;
  let videoCanvas = null;
  let videoRaf = 0;
  let worker = null;
  let lockResolver = null;
  let wakeLock = null;
  let intervalFast = 0;
  let intervalMaintain = 0;
  let idbInterval = 0;
  let visHandler = null;
  let interactionHandler = null;
  let frozenRecoveryTimerId = 0;
  let lifecycleHandler = null;
  let pageshowHandler = null;
  let mediaRetryCount = 0;
  let mediaRetryWindowStart = 0;
  let replayBackoffMs = 800;

  const MEDIA_RETRY_MAX = 30;
  const MEDIA_RETRY_WINDOW_MS = 60000;
  const REPLAY_BACKOFF_MAX_MS = 30000;

  function isIosKaDevice() {
    return /iPad|iPhone|iPod/i.test(navigator.userAgent || "");
  }

  function resetMediaRetryWindowIfNeeded() {
    const now = Date.now();
    if (now - mediaRetryWindowStart > MEDIA_RETRY_WINDOW_MS) {
      mediaRetryWindowStart = now;
      mediaRetryCount = 0;
      replayBackoffMs = 800;
    }
  }

  function canRetryMediaPlay() {
    resetMediaRetryWindowIfNeeded();
    return mediaRetryCount < MEDIA_RETRY_MAX;
  }

  function noteMediaRetry() {
    resetMediaRetryWindowIfNeeded();
    mediaRetryCount += 1;
    replayBackoffMs = Math.min(REPLAY_BACKOFF_MAX_MS, Math.floor(replayBackoffMs * 1.4));
  }

  function scheduleMediaReplay() {
    if (!active || !canRetryMediaPlay()) return;
    noteMediaRetry();
    window.setTimeout(() => {
      if (!active) return;
      ensureSilentMediaPlaying();
    }, replayBackoffMs);
  }

  function recoverFromFreeze() {
    startSilentAudio();
    startSilentVideo();
    if (audioCtx?.state === "suspended") audioCtx.resume().catch(() => {});
    if (!worker) startWorker();
    setupMediaSession();
  }
  function generateSilentWavUrl() {
    const sampleRate = 8000;
    const numSamples = Math.floor(sampleRate * 0.5);
    const dataSize = numSamples * 2;
    const buffer = new ArrayBuffer(44 + dataSize);
    const view = new DataView(buffer);
    const writeStr = (o, s) => {
      for (let i = 0; i < s.length; i++) view.setUint8(o + i, s.charCodeAt(i));
    };
    writeStr(0, "RIFF");
    view.setUint32(4, 36 + dataSize, true);
    writeStr(8, "WAVE");
    writeStr(12, "fmt ");
    view.setUint32(16, 16, true);
    view.setUint16(20, 1, true);
    view.setUint16(22, 1, true);
    view.setUint32(24, sampleRate, true);
    view.setUint32(28, sampleRate * 2, true);
    view.setUint16(32, 2, true);
    view.setUint16(34, 16, true);
    writeStr(36, "data");
    view.setUint32(40, dataSize, true);
    for (let i = 0; i < numSamples; i++) {
      view.setInt16(44 + i * 2, ((Math.random() * 4 - 2) | 0), true);
    }
    return URL.createObjectURL(new Blob([buffer], { type: "audio/wav" }));
  }

  function startSilentAudio() {
    try {
      if (!audioCtx) {
        audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      }
      if (audioCtx.state === "suspended") audioCtx.resume().catch(() => {});
      if (!oscillator && audioCtx) {
        gainNode = audioCtx.createGain();
        gainNode.gain.value = 0.001;
        gainNode.connect(audioCtx.destination);
        oscillator = audioCtx.createOscillator();
        oscillator.frequency.value = isIosKaDevice() ? 20 : 1;
        oscillator.connect(gainNode);
        oscillator.start();
      }
      if (!audioEl) {
        audioEl = new Audio(generateSilentWavUrl());
        audioEl.loop = true;
        audioEl.volume = 0.01;
        audioEl.setAttribute("playsinline", "");
      }
      audioEl.play().catch(() => {
        setupInteractionUnlock();
      });
    } catch (_) {}
  }

  function isKaStandalonePwa() {
    if (typeof window === "undefined") return false;
    if (window.matchMedia("(display-mode: standalone)").matches) return true;
    if (window.matchMedia("(display-mode: fullscreen)").matches) return true;
    const nav = /** @type {Navigator & { standalone?: boolean }} */ (window.navigator);
    if (nav.standalone === true) return true;
    return false;
  }

  function startSilentVideo() {
    if (!isIosKaDevice() && !isKaStandalonePwa()) return;
    try {
      if (!videoEl) {
        videoCanvas = document.createElement("canvas");
        videoCanvas.width = 4;
        videoCanvas.height = 4;
        const ctx = videoCanvas.getContext("2d");
        const draw = () => {
          if (!videoCanvas || !ctx) return;
          ctx.fillStyle = "#000";
          ctx.fillRect(0, 0, 4, 4);
          videoRaf = window.requestAnimationFrame(draw);
        };
        draw();
        if (typeof videoCanvas.captureStream !== "function") {
          if (videoRaf) {
            window.cancelAnimationFrame(videoRaf);
            videoRaf = 0;
          }
          videoCanvas = null;
          return;
        }
        const stream = videoCanvas.captureStream(1);
        videoEl = document.createElement("video");
        videoEl.muted = true;
        videoEl.defaultMuted = true;
        videoEl.playsInline = true;
        videoEl.setAttribute("playsinline", "");
        videoEl.setAttribute("webkit-playsinline", "");
        videoEl.loop = true;
        videoEl.srcObject = stream;
        videoEl.style.cssText =
          "position:fixed;left:-9999px;top:-9999px;width:1px;height:1px;opacity:0;pointer-events:none;z-index:-1";
        document.body.appendChild(videoEl);
      }
      if (videoEl.paused) {
        videoEl.play().catch(() => {
          setupInteractionUnlock();
          scheduleMediaReplay();
        });
      }
    } catch (_) {}
  }

  function stopSilentVideo() {
    if (videoRaf) {
      window.cancelAnimationFrame(videoRaf);
      videoRaf = 0;
    }
    if (videoEl) {
      try {
        videoEl.pause();
        videoEl.srcObject = null;
        videoEl.remove();
      } catch (_) {}
      videoEl = null;
    }
    videoCanvas = null;
  }

  function setupMediaSession() {
    try {
      if (!("mediaSession" in navigator)) return;
      navigator.mediaSession.metadata = new MediaMetadata({
        title: "没心机",
        artist: "后台保活",
        album: " "
      });
      navigator.mediaSession.playbackState = "playing";
    } catch (_) {}
  }

  function clearMediaSession() {
    try {
      if (!("mediaSession" in navigator)) return;
      navigator.mediaSession.playbackState = "none";
      navigator.mediaSession.metadata = null;
    } catch (_) {}
  }

  function ensureSilentMediaPlaying() {
    if (!active) return;
    try {
      if (audioEl?.paused) {
        audioEl.play().catch(() => {
          setupInteractionUnlock();
          scheduleMediaReplay();
        });
      }
      if (audioCtx?.state === "suspended") audioCtx.resume().catch(() => scheduleMediaReplay());
      if (videoEl?.paused) {
        videoEl.play().catch(() => {
          setupInteractionUnlock();
          scheduleMediaReplay();
        });
      }
    } catch (_) {}
  }

  function stopSilentAudio() {
    if (oscillator) {
      try {
        oscillator.stop();
      } catch (_) {}
      oscillator = null;
    }
    if (gainNode) {
      try {
        gainNode.disconnect();
      } catch (_) {}
      gainNode = null;
    }
    if (audioEl) {
      audioEl.pause();
      audioEl.src = "";
      audioEl = null;
    }
    stopSilentVideo();
    clearMediaSession();
    if (audioCtx) {
      audioCtx.close().catch(() => {});
      audioCtx = null;
    }
  }

  function startWorker() {
    if (worker) return;
    try {
      const code =
        "let a=null,b=null;self.onmessage=function(e){if(e.data==='start'){if(a)clearInterval(a);if(b)clearInterval(b);a=setInterval(()=>self.postMessage('tick'),5000);b=setInterval(()=>self.postMessage('ping'),2000);self.postMessage('tick');}else if(e.data==='stop'){if(a){clearInterval(a);a=null;}if(b){clearInterval(b);b=null;}}};";
      const url = URL.createObjectURL(new Blob([code], { type: "application/javascript" }));
      worker = new Worker(url);
      URL.revokeObjectURL(url);
      worker.onmessage = (e) => {
        if (e.data === "tick" || e.data === "ping") {
          lastTick = Date.now();
          if (e.data === "tick" && onTick) onTick();
          ensureSilentMediaPlaying();
          pingSystemNotificationSw();
        }
      };
      worker.postMessage("start");
    } catch (_) {
      worker = null;
    }
  }

  function stopWorker() {
    if (!worker) return;
    try {
      worker.postMessage("stop");
      worker.terminate();
    } catch (_) {}
    worker = null;
  }

  function acquireWebLock() {
    if (!("locks" in navigator)) return;
    try {
      navigator.locks.request("xxj-keepalive", { mode: "exclusive" }, () => new Promise((resolve) => {
        lockResolver = resolve;
      }));
    } catch (_) {}
  }

  function releaseWebLock() {
    if (lockResolver) {
      lockResolver();
      lockResolver = null;
    }
  }

  async function acquireWakeLock() {
    try {
      if ("wakeLock" in navigator) {
        wakeLock = await navigator.wakeLock.request("screen");
        wakeLock.addEventListener("release", () => {
          wakeLock = null;
        });
      }
    } catch (_) {}
  }

  function releaseWakeLock() {
    if (wakeLock) {
      wakeLock.release().catch(() => {});
      wakeLock = null;
    }
  }

  function idbHeartbeatWrite() {
    try {
      const req = indexedDB.open("keepalive_heartbeat", 1);
      req.onupgradeneeded = () => {
        const db = req.result;
        if (!db.objectStoreNames.contains("hb")) db.createObjectStore("hb");
      };
      req.onsuccess = () => {
        try {
          const db = req.result;
          const tx = db.transaction("hb", "readwrite");
          tx.objectStore("hb").put(Date.now(), "last");
          tx.oncomplete = () => db.close();
        } catch (_) {
          req.result?.close?.();
        }
      };
    } catch (_) {}
  }

  function startIntervals() {
    if (!intervalFast) {
      intervalFast = window.setInterval(() => {
        const now = Date.now();
        if (lastTick > 0 && now - lastTick > 30000) {
          lastTick = now;
          recoverFromFreeze();
          if (onTick) onTick();
          pingSystemNotificationSw();
        }
      }, 1000);
    }
    if (!intervalMaintain) {
      intervalMaintain = window.setInterval(() => {
        if (!active) return;
        lastTick = Date.now();
        ensureSilentMediaPlaying();
        pingSystemNotificationSw();
        void acquireWakeLock();
      }, 10000);
    }
    if (!idbInterval) {
      idbHeartbeatWrite();
      idbInterval = window.setInterval(idbHeartbeatWrite, 20000);
    }
  }

  function stopIntervals() {
    if (intervalFast) {
      window.clearInterval(intervalFast);
      intervalFast = 0;
    }
    if (intervalMaintain) {
      window.clearInterval(intervalMaintain);
      intervalMaintain = 0;
    }
    if (idbInterval) {
      window.clearInterval(idbInterval);
      idbInterval = 0;
    }
  }

  function setupVisibility() {
    if (visHandler) return;
    visHandler = () => {
      if (!active) return;
      if (document.visibilityState === "visible") {
        acquireWakeLock();
        startSilentAudio();
        startSilentVideo();
        setupMediaSession();
        if (audioCtx?.state === "suspended") audioCtx.resume().catch(() => {});
        const gap = Date.now() - lastTick;
        if (gap > 15000) recoverFromFreeze();
        lastTick = Date.now();
        if (frozenRecoveryTimerId) window.clearTimeout(frozenRecoveryTimerId);
        frozenRecoveryTimerId = window.setTimeout(() => {
          frozenRecoveryTimerId = 0;
          if (active && onTick) onTick();
        }, 2000);
      } else {
        if (audioEl?.paused) audioEl.play().catch(() => scheduleMediaReplay());
        if (videoEl?.paused) videoEl.play().catch(() => scheduleMediaReplay());
        if (audioCtx?.state === "suspended") audioCtx.resume().catch(() => scheduleMediaReplay());
        pingSystemNotificationSw();
        idbHeartbeatWrite();
      }
    };
    document.addEventListener("visibilitychange", visHandler);
  }

  function removeVisibility() {
    if (visHandler) {
      document.removeEventListener("visibilitychange", visHandler);
      visHandler = null;
    }
    if (lifecycleHandler) {
      document.removeEventListener("freeze", lifecycleHandler);
      window.removeEventListener("resume", lifecycleHandler);
      lifecycleHandler = null;
    }
    if (pageshowHandler) {
      window.removeEventListener("pageshow", pageshowHandler);
      pageshowHandler = null;
    }
    if (frozenRecoveryTimerId) {
      window.clearTimeout(frozenRecoveryTimerId);
      frozenRecoveryTimerId = 0;
    }
  }

  function setupLifecycle() {
    if (!lifecycleHandler) {
      lifecycleHandler = () => {
        if (!active) return;
        recoverFromFreeze();
      };
      document.addEventListener("freeze", lifecycleHandler);
      window.addEventListener("resume", lifecycleHandler);
    }
    if (!pageshowHandler) {
      pageshowHandler = (e) => {
        if (!active) return;
        if (e.persisted || document.visibilityState === "visible") {
          recoverFromFreeze();
          if (onTick) onTick();
        }
      };
      window.addEventListener("pageshow", pageshowHandler);
    }
  }

  function setupInteractionUnlock() {
    if (interactionHandler) return;
    interactionHandler = () => {
      if (active) recoverFromFreeze();
      document.removeEventListener("touchstart", interactionHandler);
      document.removeEventListener("click", interactionHandler);
      interactionHandler = null;
    };
    document.addEventListener("touchstart", interactionHandler, { once: true, passive: true });
    document.addEventListener("click", interactionHandler, { once: true });
  }

  function start(tickCb) {
    const nextTick = typeof tickCb === "function" ? tickCb : null;
    if (active) {
      if (nextTick) onTick = nextTick;
      return;
    }
    active = true;
    onTick = nextTick;
    lastTick = Date.now();
    mediaRetryCount = 0;
    mediaRetryWindowStart = Date.now();
    replayBackoffMs = 800;
    setupInteractionUnlock();
    setupVisibility();
    setupLifecycle();
    startSilentAudio();
    startSilentVideo();
    setupMediaSession();
    startWorker();
    acquireWebLock();
    void acquireWakeLock();
    startIntervals();
    pingSystemNotificationSw();
  }

  function stop() {
    if (!active) return;
    active = false;
    onTick = null;
    stopSilentAudio();
    stopWorker();
    releaseWebLock();
    releaseWakeLock();
    stopIntervals();
    removeVisibility();
  }

  function nudge() {
    if (!active) return;
    lastTick = Date.now();
    recoverFromFreeze();
    if (onTick) onTick();
    pingSystemNotificationSw();
  }

  return {
    start,
    stop,
    nudge,
    get isRunning() {
      return active;
    }
  };
})();

const XXJ_SYSTEM_NOTIF_KEY = "xxj_system_notifications_enabled";
const XXJ_BG_KEEPALIVE_KEY = "xxj_bg_keepalive_enabled";
function isSystemNotifEnabled() {
  try {
    const v = localStorage.getItem(XXJ_SYSTEM_NOTIF_KEY);
    return v === null ? true : v === "true";
  } catch {
    return true;
  }
}

function setSystemNotifEnabled(on) {
  try {
    localStorage.setItem(XXJ_SYSTEM_NOTIF_KEY, on ? "true" : "false");
  } catch (_) {}
}

function isBgKeepAliveEnabled() {
  try {
    const v = localStorage.getItem(XXJ_BG_KEEPALIVE_KEY);
    if (v === "true") return true;
    if (v === "false") return false;
    /** 未手动设置：手机默认关（减发热）；桌面默认开（兼顾后台通知） */
    return !isMobileLikeDevice();
  } catch {
    return !isMobileLikeDevice();
  }
}

function setBgKeepAliveEnabled(on) {
  try {
    localStorage.setItem(XXJ_BG_KEEPALIVE_KEY, on ? "true" : "false");
  } catch (_) {}
}

/** @param {unknown} dmThread @param {string} maskId */
function resolveLinkedGroupForDmThread(dmThread, maskId) {
  const mid = String(maskId || "").trim();
  const dmId = String(dmThread?.id || "").trim();
  const cid = String(dmThread?.charId || "").trim();
  if (!mid || !dmId || !cid || !dmThread || isChatThreadGroupForUi(dmThread)) return null;

  const linked = String(dmThread.linkedGroupThreadId || "").trim();
  if (linked) {
    const g = findInboxThreadById(mid, linked);
    if (g && isChatThreadGroupForUi(g)) {
      const members = (Array.isArray(g.memberCharIds) ? g.memberCharIds : [])
        .map((x) => String(x || "").trim())
        .filter(Boolean);
      if (members.includes(cid)) return g;
    }
  }

  const inbox = readChatInboxStore();
  const bucket = inbox.byMask[maskBucketKey(mid)];
  if (!bucket) return null;
  for (const g of Array.isArray(bucket.threads) ? bucket.threads : []) {
    if (!g || !isChatThreadGroupForUi(g)) continue;
    const map = g.memberDmThreadIds;
    if (!map || typeof map !== "object" || Array.isArray(map)) continue;
    if (String(map[cid] || "").trim() === dmId) return g;
  }
  return null;
}

/** @param {unknown} dmThread @param {string} maskId */
function isDmThreadGroupMemoryLinked(dmThread, maskId) {
  return !!resolveLinkedGroupForDmThread(dmThread, maskId);
}

function getGroupDrivenProactiveIntervalMs(dmThread) {
  const tid = String(dmThread?.id || "");
  let h = 0;
  for (let i = 0; i < tid.length; i++) h = (Math.imul(31, h) + tid.charCodeAt(i)) | 0;
  const frac = ((((h % 1000) + 1000) % 1000) + 1) / 1001;
  return CHAR_PROACTIVE_RANDOM_MIN_MS + Math.floor(frac * CHAR_PROACTIVE_RANDOM_RANGE_MS);
}

/** @param {unknown} dmThread @param {string} maskId */
function isGroupLinkedDmProactiveDue(dmThread, maskId) {
  if (!isDmThreadGroupMemoryLinked(dmThread, maskId)) return false;
  const log = readChatLogForMaskThread(maskId, String(dmThread?.id || ""));
  if (countTrailingAssistantBubblesInLog(log) >= 2) return false;
  const baseline = computeCharProactiveBaselineMs(log);
  return Date.now() - baseline + 500 >= getGroupDrivenProactiveIntervalMs(dmThread);
}

function hasAnyChatProactiveEnabled() {
  const inbox = readChatInboxStore();
  for (const key of Object.keys(inbox.byMask || {})) {
    const bucket = inbox.byMask[key];
    if (!bucket) continue;
    const maskId = key === "__nomask__" ? "__nomask__" : key;
    for (const th of Array.isArray(bucket.threads) ? bucket.threads : []) {
      if (!th || isChatThreadGroupForUi(th)) continue;
      if (isDmThreadGroupMemoryLinked(th, maskId)) return true;
      if (isThreadCharProactiveEnabled(th) && !isDmThreadGroupMemoryLinked(th, maskId)) return true;
    }
  }
  return false;
}

function syncBgKeepAliveState() {
  if (!isBgKeepAliveEnabled()) {
    KeepAliveModule.stop();
    void unregisterPeriodicKeepAliveSync();
    return;
  }
  void registerPeriodicKeepAliveSync();
  /** 仅切到后台时跑保活；前台聊天时不占音频/定时器，减轻手机发热 */
  if (typeof document !== "undefined" && document.visibilityState !== "hidden") {
    KeepAliveModule.stop();
    return;
  }
  KeepAliveModule.start(() => {
    void runChatProactiveBackgroundScan();
    void runRelationDmProactiveBackgroundScan();
  });
}

const XXJ_KEEPALIVE_PERIODIC_TAG = "xxj-keepalive";

async function registerPeriodicKeepAliveSync() {
  if (!isBgKeepAliveEnabled() || !("serviceWorker" in navigator)) return;
  try {
    const reg = await navigator.serviceWorker.ready;
    if (!reg.periodicSync) return;
    const perm = await navigator.permissions.query({ name: "periodic-background-sync" });
    if (perm.state !== "granted") return;
    await reg.periodicSync.register(XXJ_KEEPALIVE_PERIODIC_TAG, { minInterval: 15 * 60 * 1000 });
  } catch (_) {}
}

async function unregisterPeriodicKeepAliveSync() {
  if (!("serviceWorker" in navigator)) return;
  try {
    const reg = await navigator.serviceWorker.ready;
    if (!reg.periodicSync) return;
    const tags = await reg.periodicSync.getTags();
    if (tags.includes(XXJ_KEEPALIVE_PERIODIC_TAG)) {
      await reg.periodicSync.unregister(XXJ_KEEPALIVE_PERIODIC_TAG);
    }
  } catch (_) {}
}

function handleKeepAliveSwMessage(event) {
  const data = event?.data;
  if (!data || data.type !== "PERIODIC_SYNC_TICK") return;
  if (!isBgKeepAliveEnabled()) return;
  syncBgKeepAliveState();
  if (document.hidden) {
    KeepAliveModule.nudge();
    return;
  }
  void runChatProactiveBackgroundScan();
  void runRelationDmProactiveBackgroundScan();
}

function isThreadChatProactiveDue(th, maskId, now = Date.now()) {
  if (!th || th.kind === "group" || !isThreadCharProactiveEnabled(th)) return false;
  const log = readChatLogForMaskThread(maskId, th.id);
  if (countTrailingAssistantBubblesInLog(log) >= 2) return false;
  const baseline = computeCharProactiveBaselineMs(log);
  const intervalMs = getCharProactiveIntervalMs(th);
  return Date.now() - baseline + 500 >= intervalMs;
}

function listChatProactiveDueAcrossMasks() {
  const inbox = readChatInboxStore();
  const rows = [];
  const seen = new Set();
  const now = Date.now();
  for (const key of Object.keys(inbox.byMask || {})) {
    const bucket = inbox.byMask[key];
    if (!bucket) continue;
    const maskId = key === "__nomask__" ? "__nomask__" : key;
    for (const th of Array.isArray(bucket.threads) ? bucket.threads : []) {
      if (!th || isChatThreadGroupForUi(th)) continue;
      const tid = String(th.id || "").trim();
      if (!tid || !String(th.charId || "").trim()) continue;

      const groupTh = resolveLinkedGroupForDmThread(th, maskId);
      if (groupTh) {
        if (!isGroupLinkedDmProactiveDue(th, maskId)) continue;
        const log = readChatLogForMaskThread(maskId, tid);
        const baseline = computeCharProactiveBaselineMs(log);
        const intervalMs = getGroupDrivenProactiveIntervalMs(th);
        const sk = `${maskId}:${tid}`;
        if (seen.has(sk)) continue;
        seen.add(sk);
        rows.push({
          maskId,
          threadId: tid,
          th,
          groupThread: groupTh,
          groupDriven: true,
          overdue: now - baseline - intervalMs
        });
        continue;
      }

      if (!isThreadCharProactiveEnabled(th)) continue;
      if (!isThreadChatProactiveDue(th, maskId, now)) continue;
      const log = readChatLogForMaskThread(maskId, tid);
      const baseline = computeCharProactiveBaselineMs(log);
      const intervalMs = isThreadCharProactiveAutoMode(th)
        ? CHAR_PROACTIVE_RANDOM_MIN_MS
        : getThreadCharProactiveIntervalSec(th) * 1000;
      const sk = `${maskId}:${tid}`;
      if (seen.has(sk)) continue;
      seen.add(sk);
      rows.push({
        maskId,
        threadId: tid,
        th,
        overdue: now - baseline - intervalMs
      });
    }
  }
  rows.sort((a, b) => b.overdue - a.overdue);
  return rows;
}

function readChatProactiveViewingThreadRef() {
  const cs = getChatScreenEl();
  if (!cs || !cs.classList.contains("is-open")) return null;
  const ref = readChatActiveThreadRef();
  const maskId = String(ref.maskId || getActiveMaskIdForInbox() || "").trim();
  const threadId = String(ref.threadId || "").trim();
  if (!maskId || !threadId) return null;
  return { maskId, threadId };
}

/** 距下一条「非当前密谈页」主动消息还有多久（当前页仍走 scheduleChatProactiveTimer）。 */
function computeNextChatProactivePeerWakeMs() {
  const inbox = readChatInboxStore();
  const viewing = readChatProactiveViewingThreadRef();
  const now = Date.now();
  let minWake = 60000;
  let any = false;
  for (const key of Object.keys(inbox.byMask || {})) {
    const bucket = inbox.byMask[key];
    if (!bucket) continue;
    const maskId = key === "__nomask__" ? "__nomask__" : key;
    for (const th of Array.isArray(bucket.threads) ? bucket.threads : []) {
      if (!th || isChatThreadGroupForUi(th)) continue;
      const tid = String(th.id || "").trim();
      if (!tid) continue;
      const groupTh = resolveLinkedGroupForDmThread(th, maskId);
      const classicOn = isThreadCharProactiveEnabled(th) && !groupTh;
      if (!groupTh && !classicOn) continue;
      if (viewing && viewing.maskId === maskId && viewing.threadId === tid) continue;
      any = true;
      const log = readChatLogForMaskThread(maskId, tid);
      if (countTrailingAssistantBubblesInLog(log) >= 2) {
        minWake = Math.min(minWake, 60000);
        continue;
      }
      const baseline = computeCharProactiveBaselineMs(log);
      const intervalMs = groupTh
        ? getGroupDrivenProactiveIntervalMs(th)
        : isThreadCharProactiveAutoMode(th)
          ? CHAR_PROACTIVE_RANDOM_MIN_MS
          : getThreadCharProactiveIntervalSec(th) * 1000;
      const remaining = Math.max(4000, baseline + intervalMs - now);
      minWake = Math.min(minWake, remaining);
    }
  }
  return any ? minWake : 120000;
}

/**
 * 执行一条到期的主动密谈（绑定 mask/thread，不读当前界面人设）。
 * @param {{ maskId: string, threadId: string, th: object }} row
 */
async function executeChatProactiveForDueRow(row) {
  const ai = window.RP_AI;
  if (!ai || !row) return false;
  const maskId = String(row.maskId || "").trim();
  const threadId = String(row.threadId || "").trim();
  const th = row.th;
  if (!maskId || !threadId || !th) return false;
  const found = findChatThreadInInbox(maskId, threadId);
  if (found) await ensureThreadMessagesForApi(maskId, threadId, found.thread, th);
  const log = readChatLogForMaskThread(maskId, threadId);
  const follow = countTrailingAssistantBubblesInLog(log) > 0;
  const groupTh = row.groupThread || resolveLinkedGroupForDmThread(th, maskId);
  const prompt =
    groupTh && (row.groupDriven || isDmThreadGroupMemoryLinked(th, maskId))
      ? buildGroupDrivenProactiveDmUserPrompt(th, groupTh, maskId, follow)
      : buildCharProactiveApiUserPrompt(follow, th, maskId);
  await executeChatAssistantRound(
    {
      boundMaskId: maskId,
      boundThreadId: threadId,
      boundThread: th,
      boundDmSurface: resolveChatRoundDmSurface(
        { boundMaskId: maskId, boundThreadId: threadId, boundThread: th },
        th,
        maskId,
        threadId
      ),
      emptySendUserContent: prompt,
      allowSilentReply: true
    },
    null
  );
  if (!isUserViewingChatThread(maskId, threadId) && chatListScreen?.classList.contains("is-open")) {
    renderChatThreadList();
  }
  return true;
}

/**
 * 扫描并执行下一条到期的主动密谈。
 * @param {{ skipViewingThread?: boolean, requireKeepAlive?: boolean }} [opts]
 */
async function runChatProactiveScanOnce(opts) {
  const o = opts && typeof opts === "object" ? opts : {};
  if (o.requireKeepAlive && !isBgKeepAliveEnabled()) return false;
  if (chatProactiveInFlight) return false;
  let due = listChatProactiveDueAcrossMasks();
  if (o.skipViewingThread) {
    const viewing = readChatProactiveViewingThreadRef();
    if (viewing) {
      due = due.filter(
        (r) => !(r.maskId === viewing.maskId && r.threadId === viewing.threadId)
      );
    }
  }
  if (!due.length) return false;
  const row = due[0];
  chatProactiveInFlight = true;
  const needKeepAlive = o.requireKeepAlive && isBgKeepAliveEnabled();
  if (needKeepAlive) syncBgKeepAliveState();
  try {
    await executeChatProactiveForDueRow(row);
    return true;
  } finally {
    chatProactiveInFlight = false;
    if (needKeepAlive) syncBgKeepAliveState();
  }
}

async function runChatProactiveBackgroundScan() {
  await runChatProactiveScanOnce({ skipViewingThread: false, requireKeepAlive: true });
}

/**
 * 供关系网后台互动决策：与 user 最近密谈摘要。
 * @param {string} maskId
 * @param {string} threadId
 * @param {object} th
 */
function buildRelationProactiveUserChatHint(maskId, threadId, th) {
  const mid = String(maskId || "").trim();
  const tid = String(threadId || "").trim();
  if (!mid || !tid) return "";
  const log = readChatLogForMaskThread(mid, tid);
  const userName = resolveUserMaskDisplayLabelForInbox(mid);
  const charName = readCharDisplayNameById(String(th?.charId || "").trim()) || "角色";
  const lines = [];
  for (const m of log.slice(-16)) {
    if (!m || typeof m !== "object") continue;
    if (m.role === "system") continue;
    let text = String(m.content || "").trim();
    if (!text && m.narration) text = String(m.narration || "").trim();
    if (!text) continue;
    if (text.startsWith("【红包】")) text = "[红包]";
    const who = m.role === "user" ? userName : charName;
    lines.push(`${who}：${text.slice(0, 140)}`);
  }
  return lines.join("\n").slice(0, 2200);
}

function listRelationBgDueAcrossMasks() {
  const D = window.XXJ_DB;
  if (!D?.K?.RELATION_BG_STORE) return [];
  const raw = D.getKv(D.K.RELATION_BG_STORE);
  const byMask = raw?.byMask && typeof raw.byMask === "object" ? raw.byMask : {};
  /** @type {{ maskId: string, ownerCharId: string, overdue: number }[]} */
  const rows = [];
  const now = Date.now();
  const intervalFn =
    typeof window.relationBgIntervalMsForMask === "function"
      ? window.relationBgIntervalMsForMask
      : null;
  const lastFn =
    typeof window.getRelationBgCharLastAtMs === "function"
      ? window.getRelationBgCharLastAtMs
      : null;
  if (!intervalFn || !lastFn) return [];
  for (const key of Object.keys(byMask)) {
    const bucket = byMask[key];
    if (!bucket?.bgActivityEnabled) continue;
    const maskId = key === "__nomask__" ? "__nomask__" : key;
    for (const ch of listCharsWithRelationNetworkForBg(maskId)) {
      const ownerCharId = String(ch?.charId || "").trim();
      if (!ownerCharId) continue;
      const baseline = lastFn(maskId, ownerCharId);
      const intervalMs = intervalFn(maskId);
      if (now - baseline + 500 >= intervalMs) {
        rows.push({ maskId, ownerCharId, overdue: now - baseline - intervalMs });
      }
    }
  }
  rows.sort((a, b) => b.overdue - a.overdue);
  return rows;
}

function buildRelationProactiveUserChatHintForChar(maskId, charId) {
  const mid = String(maskId || "").trim();
  const cid = String(charId || "").trim();
  if (!mid || !cid) return "";
  const dm = listDmThreadsForChar(mid, cid)[0];
  if (!dm) return "";
  return buildRelationProactiveUserChatHint(mid, String(dm.id || "").trim(), dm);
}

/**
 * @param {{ maskId: string, ownerCharId: string }} row
 */
async function executeRelationBgForDueRow(row) {
  const runFn =
    typeof window.relationRunProactiveSegmentScheduled === "function"
      ? window.relationRunProactiveSegmentScheduled
      : null;
  if (!runFn || !row) return null;
  const maskId = String(row.maskId || "").trim();
  const ownerCharId = String(row.ownerCharId || "").trim();
  if (!maskId || !ownerCharId) return null;
  if (!listRelationPeersForOwnerChar(maskId, ownerCharId).length) return null;
  const userChatSummary = buildRelationProactiveUserChatHintForChar(maskId, ownerCharId);
  const segMeta = await runFn(maskId, ownerCharId, { userChatSummary });
  if (!segMeta) return null;
  if (typeof window.touchRelationBgCharLastAt === "function") {
    window.touchRelationBgCharLastAt(maskId, ownerCharId);
  }
  return {
    maskId,
    ownerCharId,
    ownerName: String(segMeta.ownerName || charDisplayNameById(ownerCharId) || "").trim(),
    peerCharId: String(segMeta.peerCharId || "").trim(),
    peerName: String(segMeta.peerName || "").trim(),
    peerNpcName: String(segMeta.peerNpcName || "").trim(),
    kind: segMeta.kind || (segMeta.peerNpcName ? "npc" : "char"),
    preview: String(segMeta.preview || "").trim()
  };
}

async function runRelationDmProactiveScanOnce(opts) {
  const o = opts && typeof opts === "object" ? opts : {};
  if (o.requireKeepAlive && !isBgKeepAliveEnabled()) return null;
  if (relationBgInFlight) return null;
  let due = listRelationBgDueAcrossMasks();
  if (typeof window.canRunRelationBgForMask === "function") {
    due = due.filter((r) => window.canRunRelationBgForMask(String(r.maskId || "").trim()));
  }
  if (!due.length) return null;
  const row = due[0];
  relationBgInFlight = true;
  const needKeepAlive = o.requireKeepAlive && isBgKeepAliveEnabled();
  if (needKeepAlive) syncBgKeepAliveState();
  try {
    const meta = await executeRelationBgForDueRow(row);
    if (meta && typeof window.markRelationBgActivity === "function") {
      window.markRelationBgActivity(meta.maskId);
    }
    return meta;
  } finally {
    relationBgInFlight = false;
    if (needKeepAlive) syncBgKeepAliveState();
  }
}

async function runRelationDmProactiveBackgroundScan() {
  const meta = await runRelationDmProactiveScanOnce({
    requireKeepAlive: true
  });
  if (meta && typeof window.notifyRelationBgDm === "function") {
    window.notifyRelationBgDm(meta);
  }
}

window.runRelationDmProactiveScanOnce = runRelationDmProactiveScanOnce;
window.listCharsWithRelationNetwork = listCharsWithRelationNetwork;
window.listCharsWithRelationNetworkForBg = listCharsWithRelationNetworkForBg;

function computeNextRelationBgWakeMs() {
  const D = window.XXJ_DB;
  if (!D?.K?.RELATION_BG_STORE) return 120000;
  const raw = D.getKv(D.K.RELATION_BG_STORE);
  const byMask = raw?.byMask && typeof raw.byMask === "object" ? raw.byMask : {};
  const intervalFn =
    typeof window.relationBgIntervalMsForMask === "function"
      ? window.relationBgIntervalMsForMask
      : null;
  const lastFn =
    typeof window.getRelationBgCharLastAtMs === "function"
      ? window.getRelationBgCharLastAtMs
      : null;
  if (!intervalFn || !lastFn) return 120000;
  const now = Date.now();
  let minWake = 60000;
  let any = false;
  for (const key of Object.keys(byMask)) {
    const bucket = byMask[key];
    if (!bucket?.bgActivityEnabled) continue;
    const maskId = key === "__nomask__" ? "__nomask__" : key;
    for (const ch of listCharsWithRelationNetworkForBg(maskId)) {
      const ownerCharId = String(ch?.charId || "").trim();
      if (!ownerCharId) continue;
      any = true;
      const baseline = lastFn(maskId, ownerCharId);
      const intervalMs = intervalFn(maskId);
      const remaining = Math.max(4000, baseline + intervalMs - now);
      minWake = Math.min(minWake, remaining);
    }
  }
  return any ? minWake : 120000;
}

function getSystemNotificationPermissionLabel() {
  if (!isSystemChatNotificationSupported()) return "不支持";
  if (Notification.permission === "granted") return "已开启";
  if (Notification.permission === "denied") return "已拒绝，请到系统设置开启";
  return "未授权";
}

function getNotifyInstallModeHint() {
  if (isPwaStandaloneForNotifications()) return "已从主屏幕打开。";
  return "建议「添加到主屏幕」后从图标打开，避免通知顶栏显示网址。";
}

function renderNotifySettingsSheet() {
  const permEl = document.getElementById("notify-settings-perm-hint");
  if (permEl) permEl.textContent = `权限：${getSystemNotificationPermissionLabel()}`;
  const installEl = document.getElementById("notify-settings-install-hint");
  if (installEl) installEl.textContent = getNotifyInstallModeHint();
  const sysBtn = document.getElementById("notify-settings-system-toggle");
  if (sysBtn) sysBtn.setAttribute("aria-pressed", isSystemNotifEnabled() ? "true" : "false");
  const kaBtn = document.getElementById("notify-settings-keepalive-toggle");
  if (kaBtn) kaBtn.setAttribute("aria-pressed", isBgKeepAliveEnabled() ? "true" : "false");
  const reqBtn = document.getElementById("notify-settings-request-perm");
  if (reqBtn) {
    reqBtn.disabled = !isSystemChatNotificationSupported() || Notification.permission === "granted";
  }
}

function openNotifySettingsSheet() {
  const sheet = document.getElementById("notify-settings-sheet");
  if (!sheet) return;
  cancelBackgroundNotifyTest();
  renderNotifySettingsSheet();
  sheet.hidden = false;
  sheet.setAttribute("aria-hidden", "false");
  window.requestAnimationFrame(() => sheet.classList.add("is-open"));
}

function closeNotifySettingsSheet() {
  const sheet = document.getElementById("notify-settings-sheet");
  if (!sheet) return;
  sheet.classList.remove("is-open");
  sheet.setAttribute("aria-hidden", "true");
  window.setTimeout(() => {
    sheet.hidden = true;
  }, 180);
}

function buildTestChatNotifySnap(preview) {
  const mid = String(getActiveMaskIdForInbox() || "").trim() || "test";
  const tid = String(readChatActiveThreadRef().threadId || "").trim();
  let displayName = "没心机";
  let avatarUrl = "";
  let charId = "";
  let initial = "没";
  if (mid && tid) {
    const found = findChatThreadInInbox(mid, tid);
    if (found) {
      const charP =
        found.thread.kind !== "group"
          ? readCharPersonaStore().items.find((x) => x.id === found.thread.charId) || null
          : null;
      const persona = chatNotifyPersonaFromThread(found.thread, charP);
      displayName = persona.displayName;
      avatarUrl = persona.avatarUrl;
      charId = persona.charId;
      initial = persona.initial;
    }
  }
  /** @type {ChatNotifySnap} */
  return {
    notifyId: newChatNotifyId(),
    maskId: mid,
    threadId: tid,
    charId,
    displayName,
    avatarUrl,
    initial,
    preview: String(preview || "").trim() || "测试通知",
    at: Date.now(),
    kind: "char",
    notifyKind: "chat",
    dismissTimer: 0
  };
}

const BG_NOTIFY_TEST_DELAY_MS = 5000;
const BG_NOTIFY_TEST_TAG = "xxj_bg_notify_test";
let bgNotifyTestTimerId = 0;
/** @type {(() => void) | null} */
let bgNotifyTestVisHandler = null;
/** 仅在一次「切后台延时测试」流程内为 true；结束后必须清零，避免每次切后台重复预约 */
let bgNotifyTestArmed = false;
let bgNotifyTestHideRescheduled = false;

function cancelBackgroundNotifyTest() {
  bgNotifyTestArmed = false;
  bgNotifyTestHideRescheduled = false;
  if (bgNotifyTestTimerId) {
    window.clearTimeout(bgNotifyTestTimerId);
    bgNotifyTestTimerId = 0;
  }
  if (bgNotifyTestVisHandler) {
    document.removeEventListener("visibilitychange", bgNotifyTestVisHandler);
    bgNotifyTestVisHandler = null;
  }
}

/** 把通知任务交给 SW（须已有 controller，否则预约/弹窗会失败） */
async function postNotificationJobToSw(type, payload, delayMs) {
  if (!("serviceWorker" in navigator)) return false;
  warmUpSystemNotificationSw();
  try {
    const reg = await navigator.serviceWorker.ready;
    if (reg) _cachedSwRegistration = reg;
    const msg = { type, payload };
    if (delayMs != null) msg.delayMs = delayMs;
    const ctrl = navigator.serviceWorker.controller;
    if (ctrl) {
      ctrl.postMessage(msg);
      return true;
    }
    return false;
  } catch (_) {
    return false;
  }
}

/**
 * 后台通知：有 controller 时 postMessage；否则由 registration.showNotification 弹出
 * @param {ChatNotifySnap} snap
 * @param {string} [iconOverride]
 */
function sendBackgroundSystemNotification(snap, iconOverride) {
  if (!snap || !document.hidden) return false;
  if (!isSystemChatNotificationSupported()) return false;
  if (!isSystemNotifEnabled()) return false;
  if (Notification.permission !== "granted") return false;

  const payload = buildSystemNotificationPayload(snap);
  const title = payload.title;
  const isIOS = isIosNotificationDevice();
  const safeIcon = safeIconForSystemNotification(
    iconOverride || resolveSystemNotificationIcon(snap.avatarUrl)
  );
  const notifOpts = buildRegNotificationOptions(
    {
      body: payload.body,
      icon: safeIcon,
      badge: payload.badge,
      tag: payload.tag,
      data: payload.data
    },
    true
  );
  const swPostPayload = {
    title,
    body: payload.body,
    icon: safeIcon,
    tag: payload.tag,
    data: payload.data,
    vibrate: !isIOS,
    requireInteraction: !isIOS
  };

  if (navigator.serviceWorker?.controller) {
    try {
      navigator.serviceWorker.controller.postMessage({
        type: "SHOW_CHAT_NOTIFICATION",
        payload: swPostPayload
      });
      return true;
    } catch (_) {
      /* fall through */
    }
  }

  if (_cachedSwRegistration && typeof _cachedSwRegistration.showNotification === "function") {
    try {
      _cachedSwRegistration.showNotification(title, notifOpts).catch(() => {});
      return true;
    } catch (_) {
      /* fall through */
    }
  }

  if ("serviceWorker" in navigator) {
    navigator.serviceWorker.ready
      .then((reg) => {
        if (!reg || typeof reg.showNotification !== "function") return;
        _cachedSwRegistration = reg;
        reg.showNotification(title, notifOpts).catch(() => {});
      })
      .catch(() => {});
    return true;
  }

  return false;
}

/** 通知设置：点按即在 SW 预约，再切后台（勿用页面 setTimeout） */
async function armBackgroundNotifyTest() {
  if (!isSystemChatNotificationSupported()) {
    showToast("当前环境不支持系统通知");
    return;
  }
  if (Notification.permission !== "granted") {
    showToast("请先允许通知");
    return;
  }
  if (!isSystemNotifEnabled()) {
    showToast("请先开启系统通知");
    return;
  }
  cancelBackgroundNotifyTest();
  syncBgKeepAliveState();
  KeepAliveModule.nudge();
  const sec = Math.round(BG_NOTIFY_TEST_DELAY_MS / 1000);
  closeNotifySettingsSheet();

  const testSnap = buildTestChatNotifySnap(`后台延时测试（${sec}秒）`);
  const payload = buildSystemNotificationPayload(testSnap);
  const isIOS = isIosNotificationDevice();
  const swPayload = {
    title: payload.title,
    body: payload.body,
    icon: safeIconForSystemNotification(payload.icon),
    tag: BG_NOTIFY_TEST_TAG,
    data: payload.data,
    vibrate: !isIOS,
    requireInteraction: !isIOS
  };

  bgNotifyTestArmed = true;
  bgNotifyTestHideRescheduled = false;

  const ok = await postNotificationJobToSw(
    "SCHEDULE_CHAT_NOTIFICATION",
    swPayload,
    BG_NOTIFY_TEST_DELAY_MS
  );

  bgNotifyTestVisHandler = () => {
    if (!bgNotifyTestArmed || document.visibilityState !== "hidden" || bgNotifyTestHideRescheduled) return;
    bgNotifyTestHideRescheduled = true;
    void postNotificationJobToSw("SCHEDULE_CHAT_NOTIFICATION", swPayload, BG_NOTIFY_TEST_DELAY_MS);
    pingSystemNotificationSw();
  };
  document.addEventListener("visibilitychange", bgNotifyTestVisHandler);

  // 通知仅由 SW 预约弹出；此处定时器只负责拆除监听，避免与 SW 重复弹两条
  bgNotifyTestTimerId = window.setTimeout(cancelBackgroundNotifyTest, BG_NOTIFY_TEST_DELAY_MS + 800);

  if (ok) {
    showToast(`已预约 ${sec} 秒（Worker+保活），请立刻切到别的 App`);
  } else {
    showToast("Worker 未就绪：请从主屏幕图标打开；仍会用保活尝试");
  }
}

const CHAT_NOTIFY_AUTO_DISMISS_MS = 5200;
/** 同轮多条气泡依次弹出时的间隔（每条先露出，再被下一条盖住） */
const CHAT_NOTIFY_STAGGER_MS = 380;
/** 新条盖住旧条的过渡时长（与 CSS 一致） */
const CHAT_NOTIFY_COVER_MS = 400;
/** 连发时排队上限，超出丢弃最旧待发 */
const CHAT_NOTIFY_MAX_QUEUE = 10;

/** @typedef {{ notifyId: string, maskId: string, threadId: string, charId: string, displayName: string, avatarUrl: string, initial: string, preview: string, at: number, kind: string, notifyKind: string, dismissTimer: number, charRemarkReason?: string }} ChatNotifySnap */

/** @type {ChatNotifySnap[]} 新消息在数组头部（index 0 为当前/最新） */
const chatNotifyQueue = [];
/** @type {string | null} 本轮 render 需播放入场动画的 notifyId */
let chatNotifyAnimateInId = null;
/** @type {string | null} 当前屏幕上的弹条 id */
let chatNotifyVisibleId = null;
/** @type {number} 覆盖过渡收尾定时器 */
let chatNotifyCoverTimer = 0;
/** @type {Map<string, number>} 密谈弹条连弹序号：新批次递增，过期定时器不再弹出 */
const chatNotifyStaggerGenByThread = new Map();

function newChatNotifyId() {
  return `n_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 9)}`;
}

function isChatNotifyGloballySuppressed() {
  return isCharLockFocusScreenOpen() || isChatCallActive() || isCharIncomingCallOpen();
}

/** 用户正在该 mask+thread 的密谈界面（即时或晤面）时不弹条。 */
function isUserViewingChatThread(maskId, threadId) {
  const mid = String(maskId || "").trim();
  const tid = String(threadId || "").trim();
  if (!mid || !tid) return false;
  if (String(getActiveMaskIdForInbox() || "").trim() !== mid) return false;
  const ref = readChatActiveThreadRef();
  if (ref.maskId !== mid || ref.threadId !== tid) return false;
  const cs = getChatScreenEl();
  if (cs && cs.classList.contains("is-open")) return true;
  if (isChatOfflineScreenOpen()) return true;
  const off = document.getElementById("chat-offline-screen");
  if (off && off.classList.contains("is-open")) return true;
  return false;
}

/**
 * @param {ReturnType<typeof readCharPersonaStore>["items"][number] | null} charP
 * @param {ReturnType<typeof readActiveThread>} thread
 */
function chatNotifyPersonaFromThread(thread, charP) {
  const displayName = thread ? threadListDisplayName(thread) : "密谈";
  let avatarUrl = "";
  let initial = displayName.trim().slice(0, 1) || "?";
  if (charP) {
    avatarUrl = String(charP.avatar || "").trim();
    const dn = String(charP.displayName || "").trim();
    if (dn) initial = dn.slice(0, 1);
  }
  const charId = thread && thread.kind !== "group" ? String(thread.charId || "").trim() : "";
  return {
    charId,
    displayName: displayName.slice(0, 48),
    avatarUrl,
    initial: initial.slice(0, 1) || "?",
    kind: thread?.kind === "group" ? "group" : "char"
  };
}

/** @param {unknown} entry */
function buildChatNotifyPreviewFromEntry(entry) {
  if (!entry || typeof entry !== "object") return "新消息";
  const m = /** @type {Record<string, unknown>} */ (entry);
  if (m.sticker && typeof m.sticker === "object" && String(/** @type {{ url?: string }} */ (m.sticker).url || "").trim()) {
    return "[表情]";
  }
  const img = m.image && typeof m.image === "object" ? /** @type {{ url?: string, desc?: string, scenePrompt?: string, imageGenPending?: boolean }} */ (m.image) : null;
  if (img && (String(img.url || "").trim() || img.imageGenPending)) {
    const cap = String(img.desc || img.scenePrompt || "").trim().replace(/\s+/g, " ");
    return cap ? (cap.length > 72 ? `${cap.slice(0, 71)}…` : cap) : "[图片]";
  }
  if (Array.isArray(m.voiceLines) && m.voiceLines.some((x) => String(x || "").trim())) return "[语音]";
  const nar = String(m.narration || "").trim();
  const body = chatMessagePlainLastBubbleSegment(String(m.content ?? ""), m);
  if (body) return body.length > 120 ? `${body.slice(0, 119)}…` : body;
  if (nar) {
    const n = nar.replace(/\s+/g, " ").trim();
    return n.length > 72 ? `旁白 · ${n.slice(0, 68)}…` : `旁白 · ${n}`;
  }
  if (String(m.heartVoice || "").trim()) return "心声";
  return "新消息";
}

/** @param {unknown} m */
function isChatNotifyableAssistantEntry(m) {
  if (!m || typeof m !== "object" || m.role !== "assistant" || m.restoring) return false;
  const c = String(m.content || "").trim();
  if (c.startsWith("（未能回复）")) return false;
  if (
    c === "\u00A0" &&
    !m.sticker &&
    !m.image &&
    !String(m.narration || "").trim() &&
    !String(m.heartVoice || "").trim() &&
    !(Array.isArray(m.voiceLines) && m.voiceLines.some((x) => String(x || "").trim()))
  ) {
    return false;
  }
  return true;
}

/**
 * 单条 assistant 若含 `|||` 多泡，拆成逐条通知用的虚拟条目（晤面整段不拆）。
 * @param {unknown} entry
 * @returns {unknown[]}
 */
function expandChatNotifyAssistantEntry(entry) {
  if (!isChatNotifyableAssistantEntry(entry)) return [];
  if (chatMessageDmSurface(entry) === "offline") return [entry];
  const mo = /** @type {Record<string, unknown>} */ (entry);
  if (mo.sticker && typeof mo.sticker === "object" && String(/** @type {{ url?: string }} */ (mo.sticker).url || "").trim()) {
    return [entry];
  }
  const content = String(mo.content ?? "").trim();
  if (!content) {
    if (mo.image || mo.narration || mo.heartVoice) return [entry];
    return [];
  }
  const segs = content
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean);
  if (segs.length <= 1) return [entry];
  const transParts = mo.translation ? String(mo.translation).split(/\|\|\|/) : [];
  const voiceLines = Array.isArray(mo.voiceLines) ? mo.voiceLines : [];
  const voiceSeconds = Array.isArray(mo.voiceSeconds) ? mo.voiceSeconds : [];
  const baseAt = Number(mo.at);
  const at0 = Number.isFinite(baseAt) ? baseAt : Date.now();
  return segs.map((seg, i) => {
    /** @type {Record<string, unknown>} */
    const virt = { role: "assistant", content: seg, at: at0 + i * 0.001 };
    if (i < transParts.length && String(transParts[i] ?? "").trim()) {
      virt.translation = transParts[i];
    }
    if (voiceLines[i]) {
      virt.voiceLines = [voiceLines[i]];
      if (voiceSeconds[i] != null && Number.isFinite(Number(voiceSeconds[i]))) {
        virt.voiceSeconds = [voiceSeconds[i]];
      }
    }
    if (i === segs.length - 1) {
      if (mo.image) virt.image = mo.image;
      if (mo.narration) virt.narration = mo.narration;
      if (mo.heartVoice) virt.heartVoice = mo.heartVoice;
    }
    return virt;
  });
}

/** 当前密谈角色 id（铃声按角色覆盖用） */
function ringtoneActiveCharId() {
  const th = readActiveThread();
  if (th && th.kind !== "group") {
    const id = String(th.charId || "").trim();
    if (id) return id;
  }
  const p = readCharPersona();
  const pid = p && p.id ? String(p.id).trim() : "";
  return pid || null;
}

/** 仅对本回合新写入 log 的条目弹通知（避免重复弹历史末尾消息） */
/** @param {string} maskId @param {string} threadId @param {unknown[]} log @param {number} fromIndex */
function maybePushChatNotifyNewEntries(maskId, threadId, log, fromIndex) {
  const arr = Array.isArray(log) ? log : [];
  const start = Math.max(0, Math.floor(Number(fromIndex)) || 0);
  /** @type {unknown[]} */
  const news = [];
  for (let i = start; i < arr.length; i++) {
    const m = arr[i];
    if (!isChatNotifyableAssistantEntry(m)) continue;
    news.push(...expandChatNotifyAssistantEntry(m));
  }
  if (!news.length) return;
  const mid = String(maskId || "").trim();
  const tid = String(threadId || "").trim();
  const tk = `${mid}\t${tid}`;
  const gen = (chatNotifyStaggerGenByThread.get(tk) || 0) + 1;
  chatNotifyStaggerGenByThread.set(tk, gen);
  const pushOne = (entry) => {
    if (chatNotifyStaggerGenByThread.get(tk) !== gen) return;
    maybePushChatNotify(mid, tid, entry);
  };
  if (news.length === 1) {
    pushOne(news[0]);
  } else {
    news.forEach((m, idx) => {
      if (idx === 0) pushOne(m);
      else window.setTimeout(() => pushOne(m), idx * CHAT_NOTIFY_STAGGER_MS);
    });
  }
  if (
    news.length &&
    window.Ringtones?.isInChatSoundEnabled?.() &&
    isUserViewingChatThread(mid, tid) &&
    isChatRingtoneSurfaceActive()
  ) {
    window.Ringtones.playSoundForPersona(ringtoneActiveCharId(), "message");
  }
}

function clearChatNotifyDismissTimer(snap) {
  if (!snap || !snap.dismissTimer) return;
  window.clearTimeout(snap.dismissTimer);
  snap.dismissTimer = 0;
}

function cancelChatNotifyCoverTransition() {
  if (!chatNotifyCoverTimer) return;
  window.clearTimeout(chatNotifyCoverTimer);
  chatNotifyCoverTimer = 0;
  document.getElementById("chat-notify-host")?.querySelectorAll(".chat-notify-card.is-being-covered").forEach((el) => el.remove());
}

/** @param {ChatNotifySnap} snap */
function ensureChatNotifyAutoDismiss(snap) {
  if (!snap || snap.dismissTimer) return;
  snap.dismissTimer = window.setTimeout(() => {
    dismissChatNotify(snap.notifyId);
  }, CHAT_NOTIFY_AUTO_DISMISS_MS);
}

function trimChatNotifyQueue() {
  while (chatNotifyQueue.length > CHAT_NOTIFY_MAX_QUEUE) {
    const dropped = chatNotifyQueue.pop();
    clearChatNotifyDismissTimer(dropped);
  }
}

/** @param {HTMLElement | null | undefined} host @param {string} notifyId */
function findChatNotifyCardById(host, notifyId) {
  const id = String(notifyId || "").trim();
  if (!host || !id) return null;
  return host.querySelector(`.chat-notify-card[data-notify-id="${CSS.escape(id)}"]`);
}

/** @param {ChatNotifySnap} snap */
function createChatNotifyCardElement(snap) {
    const card = document.createElement("div");
    card.className = "chat-notify-card";
    card.dataset.notifyId = snap.notifyId;
    card.tabIndex = 0;
    card.setAttribute("role", "button");
    card.setAttribute("aria-label", `${snap.displayName}：${snap.preview}`);

    const visual = document.createElement("div");
    visual.className = "chat-notify-visual";
    const pulse = document.createElement("span");
    pulse.className = "chat-notify-pulse";
    pulse.setAttribute("aria-hidden", "true");
    const av = document.createElement("span");
    av.className = "chat-notify-avatar";
    if (snap.avatarUrl) {
      const im = document.createElement("img");
      im.src = snap.avatarUrl;
      im.alt = "";
      av.appendChild(im);
    } else {
      const ini = document.createElement("span");
      ini.className = "chat-notify-initial";
      ini.textContent = snap.initial;
      av.appendChild(ini);
    }
    visual.append(pulse, av);

    const body = document.createElement("span");
    body.className = "chat-notify-body";
    const eyebrow = document.createElement("span");
    eyebrow.className = "chat-notify-eyebrow";
    eyebrow.textContent =
      snap.notifyKind === "moments"
        ? "朋友圈 · 新动态"
        : snap.kind === "group"
          ? "群聊 · 新消息"
          : "密谈 · 新消息";
    const name = document.createElement("span");
    name.className = "chat-notify-name";
    name.textContent = snap.displayName;
    const preview = document.createElement("span");
    preview.className = "chat-notify-preview";
    preview.textContent = snap.preview;
    body.append(eyebrow, name, preview);

    card.append(visual, body);

    let dragY = 0;
    let dragStartY = 0;
    let dragging = false;
    card.addEventListener("pointerdown", (e) => {
      dragging = true;
      dragStartY = e.clientY;
      dragY = 0;
      try {
        card.setPointerCapture(e.pointerId);
      } catch {
        /* ignore */
      }
    });
    card.addEventListener("pointermove", (e) => {
      if (!dragging) return;
      dragY = Math.min(0, e.clientY - dragStartY);
      card.style.transform = `translateY(${dragY}px)`;
      card.style.opacity = String(Math.max(0.2, 1 + dragY / 120));
    });
    const endDrag = (e) => {
      if (!dragging) return;
      dragging = false;
      card.style.transform = "";
      card.style.opacity = "";
      try {
        card.releasePointerCapture(e.pointerId);
      } catch {
        /* ignore */
      }
      if (dragY < -36) dismissChatNotify(snap.notifyId);
    };
    card.addEventListener("pointerup", endDrag);
    card.addEventListener("pointercancel", endDrag);

    card.addEventListener("click", () => {
      activateChatNotifySnap(snap);
    });
    card.addEventListener("keydown", (e) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        activateChatNotifySnap(snap);
      }
    });

  return card;
}

/** @param {ChatNotifySnap} snap */
function activateChatNotifySnap(snap) {
  const reason = String(snap.charRemarkReason || "").trim();
  if (reason) {
    openCharRemarkForUserReasonModal({
      charName: snap.displayName,
      headline: snap.preview,
      reason
    });
    dismissChatNotify(snap.notifyId);
    return;
  }
  openChatFromNotifySnapshot(snap);
}

/** @param {string} coveredId @param {ChatNotifySnap} newSnap */
function coverChatNotifyWithNew(coveredId, newSnap) {
  const host = document.getElementById("chat-notify-host");
  if (!host) return;
  cancelChatNotifyCoverTransition();
  host.hidden = false;
  host.setAttribute("aria-hidden", "false");

  const coveredIx = chatNotifyQueue.findIndex((s) => s.notifyId === coveredId);
  if (coveredIx >= 0) {
    clearChatNotifyDismissTimer(chatNotifyQueue[coveredIx]);
    chatNotifyQueue.splice(coveredIx, 1);
  }

  const oldCard = findChatNotifyCardById(host, coveredId);
  if (oldCard) oldCard.classList.add("is-being-covered");

  const newCard = createChatNotifyCardElement(newSnap);
  newCard.classList.add("is-cover-in");
  host.appendChild(newCard);
  chatNotifyVisibleId = newSnap.notifyId;
  clearChatNotifyDismissTimer(newSnap);
  ensureChatNotifyAutoDismiss(newSnap);

  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      newCard.classList.add("is-visible");
      if (oldCard) oldCard.classList.add("is-covered-out");
    });
  });

  chatNotifyCoverTimer = window.setTimeout(() => {
    chatNotifyCoverTimer = 0;
    if (oldCard?.parentNode) oldCard.remove();
    newCard.classList.remove("is-cover-in");
  }, CHAT_NOTIFY_COVER_MS);
}

function renderChatNotifyHost() {
  const host = document.getElementById("chat-notify-host");
  if (!host) return;
  cancelChatNotifyCoverTransition();
  const snap = chatNotifyQueue[0] || null;
  if (!snap) {
    host.innerHTML = "";
    host.hidden = true;
    host.setAttribute("aria-hidden", "true");
    chatNotifyVisibleId = null;
    return;
  }
  host.hidden = false;
  host.setAttribute("aria-hidden", "false");
  host.innerHTML = "";
  const animateId = chatNotifyAnimateInId;
  chatNotifyAnimateInId = null;
  chatNotifyVisibleId = snap.notifyId;
  const card = createChatNotifyCardElement(snap);
    host.appendChild(card);
  ensureChatNotifyAutoDismiss(snap);
  if (snap.notifyId === animateId) {
    requestAnimationFrame(() => {
      requestAnimationFrame(() => card.classList.add("is-visible"));
    });
  } else {
    card.classList.add("is-visible");
  }
}

/** 前台：应用内顶部消息条（非系统通知）；新条滑入盖住旧条 */
/** @param {ChatNotifySnap} snap */
function pushInAppChatNotifyBanner(snap) {
  if (!snap || document.hidden) return;
  const notifyCharId = String(snap.charId || "").trim() || null;
  window.Ringtones?.playSoundForPersona?.(notifyCharId, "message");
  const prevVisibleId = chatNotifyVisibleId;
  chatNotifyQueue.unshift(snap);
  trimChatNotifyQueue();
  if (prevVisibleId && prevVisibleId !== snap.notifyId) {
    coverChatNotifyWithNew(prevVisibleId, snap);
    return;
  }
  chatNotifyAnimateInId = snap.notifyId;
  renderChatNotifyHost();
}

/** 角色改主控备注时的内心动机弹层（应用内弹窗 / 聊天记录系统条）。 */
/** @param {{ charName?: string, headline?: string, reason: string }} opts */
function openCharRemarkForUserReasonModal(opts) {
  const reason = String(opts?.reason || "").trim();
  if (!reason) return;
  const overlay = document.getElementById("char-remark-reason-overlay");
  const titleEl = document.getElementById("char-remark-reason-title");
  const headEl = document.getElementById("char-remark-reason-headline");
  const bodyEl = document.getElementById("char-remark-reason-body");
  if (!(overlay instanceof HTMLElement) || !(bodyEl instanceof HTMLElement)) return;
  const nm = String(opts?.charName || "").trim();
  if (titleEl) titleEl.textContent = nm ? `${nm} · 内心动机` : "内心动机";
  if (headEl) {
    const hl = String(opts?.headline || "").trim();
    headEl.textContent = hl || (nm ? `${nm} 改备注时的想法` : "改备注时的想法");
    headEl.hidden = !headEl.textContent;
  }
  bodyEl.textContent = reason;
  overlay.hidden = false;
  overlay.setAttribute("aria-hidden", "false");
  overlay.classList.add("is-open");
  document.getElementById("char-remark-reason-close")?.focus?.();
}

function closeCharRemarkForUserReasonModal() {
  const overlay = document.getElementById("char-remark-reason-overlay");
  if (!(overlay instanceof HTMLElement) || overlay.hidden) return;
  overlay.classList.remove("is-open");
  overlay.hidden = true;
  overlay.setAttribute("aria-hidden", "true");
}

function bindCharRemarkForUserReasonOverlayOnce() {
  if (bindCharRemarkForUserReasonOverlayOnce.done) return;
  bindCharRemarkForUserReasonOverlayOnce.done = true;
  document.getElementById("char-remark-reason-close")?.addEventListener("click", closeCharRemarkForUserReasonModal);
  document.getElementById("char-remark-reason-backdrop")?.addEventListener("click", closeCharRemarkForUserReasonModal);
  document.addEventListener("keydown", (e) => {
    if (e.key !== "Escape") return;
    const overlay = document.getElementById("char-remark-reason-overlay");
    if (overlay instanceof HTMLElement && !overlay.hidden) closeCharRemarkForUserReasonModal();
  });
}
bindCharRemarkForUserReasonOverlayOnce.done = false;
bindCharRemarkForUserReasonOverlayOnce();

/** 角色更新对主控的私人备注：应用内横幅 + 后台系统通知（顶栏不展示）。 */
/** @param {string} maskId @param {string} threadId @param {{ remark?: string, reason?: string }} [opts] */
function maybePushCharRemarkUserNotify(maskId, threadId, opts) {
  const mid = String(maskId || "").trim();
  const tid = String(threadId || "").trim();
  if (!mid || !tid) return;
  if (isChatNotifyGloballySuppressed()) return;
  if (isUserViewingChatThread(mid, tid)) return;
  const found = findChatThreadInInbox(mid, tid);
  if (!found || found.thread.kind === "group") return;
  const thread = found.thread;
  const charId = String(thread.charId || "").trim();
  const charP = charId ? readCharPersonaStore().items.find((x) => x.id === charId) || null : null;
  const persona = chatNotifyPersonaFromThread(thread, charP);
  const remark = String(opts?.remark || thread.charRemarkForUser || "").trim();
  const reason = String(opts?.reason || thread.charRemarkForUserReason || "").trim();
  const preview = remark ? `给你设了备注「${remark}」` : "更新了对你的备注";
  /** @type {ChatNotifySnap} */
  const snap = {
    notifyId: newChatNotifyId(),
    maskId: mid,
    threadId: tid,
    charId: persona.charId,
    displayName: persona.displayName,
    avatarUrl: persona.avatarUrl,
    initial: persona.initial,
    preview,
    at: Date.now(),
    kind: persona.kind,
    notifyKind: "chat",
    dismissTimer: 0
  };
  if (reason) snap.charRemarkReason = reason;
  if (document.hidden) enqueueSystemChatNotification(snap);
  else pushInAppChatNotifyBanner(snap);
}

function maybePushChatNotify(maskId, threadId, entry) {
  const mid = String(maskId || "").trim();
  const tid = String(threadId || "").trim();
  if (!mid || !tid || !entry) return;
  if (isChatNotifyGloballySuppressed()) return;
  if (isUserViewingChatThread(mid, tid)) return;
  const found = findChatThreadInInbox(mid, tid);
  if (!found) return;
  const thread = found.thread;
  const charId = thread.kind === "group" ? "" : String(thread.charId || "").trim();
  const charP = charId ? readCharPersonaStore().items.find((x) => x.id === charId) || null : null;
  const persona = chatNotifyPersonaFromThread(thread, charP);
  const preview = buildChatNotifyPreviewFromEntry(entry);
  const msgAt = Number(entry.at);
  /** @type {ChatNotifySnap} */
  const snap = {
    notifyId: newChatNotifyId(),
    maskId: mid,
    threadId: tid,
    charId: persona.charId,
    displayName: persona.displayName,
    avatarUrl: persona.avatarUrl,
    initial: persona.initial,
    preview,
    at: Number.isFinite(msgAt) ? msgAt : Date.now(),
    kind: persona.kind,
    notifyKind: "chat",
    dismissTimer: 0
  };
  if (document.hidden) enqueueSystemChatNotification(snap);
  else pushInAppChatNotifyBanner(snap);
}

/** @param {string} notifyId */
function dismissChatNotify(notifyId, opts) {
  const id = String(notifyId || "").trim();
  if (!id) return;
  const ix = chatNotifyQueue.findIndex((s) => s.notifyId === id);
  if (ix < 0) return;
  const snap = chatNotifyQueue[ix];
  clearChatNotifyDismissTimer(snap);
  chatNotifyQueue.splice(ix, 1);
  if (snap.notifyId === chatNotifyVisibleId) chatNotifyVisibleId = null;
  if (opts?.skipRender) return;
  const host = document.getElementById("chat-notify-host");
  const card = findChatNotifyCardById(host, id);
  if (card && !opts?.immediate) {
    card.classList.add("is-dismiss");
    window.setTimeout(() => renderChatNotifyHost(), 220);
    return;
  }
  renderChatNotifyHost();
}

/** @param {string} maskId @param {string} threadId @param {{ immediate?: boolean }} [opts] */
function dismissChatNotifyForThread(maskId, threadId, opts) {
  const mid = String(maskId || "").trim();
  const tid = String(threadId || "").trim();
  if (!mid || !tid) return;
  const ids = chatNotifyQueue.filter((s) => s.maskId === mid && s.threadId === tid).map((s) => s.notifyId);
  for (const id of ids) dismissChatNotify(id, { immediate: true, skipRender: true });
  renderChatNotifyHost();
}

function isUserViewingMomentsPanel(maskId) {
  const mid = String(maskId || "").trim();
  if (String(getActiveMaskIdForInbox() || "").trim() !== mid) return false;
  const panel = document.getElementById("chat-list-panel-moments");
  return Boolean(
    panel && !panel.hasAttribute("hidden") && chatListScreen?.classList.contains("is-open")
  );
}

/** @param {ChatNotifySnap} snap */
function openMomentsFromNotifySnapshot(snap) {
  if (!snap) return;
  dismissChatNotify(snap.notifyId, { immediate: true });
  const mid = String(snap.maskId || "").trim();
  if (!mid) return;
  if (mid !== String(getActiveMaskIdForInbox() || "").trim()) {
    activateUserMaskById(mid, { quiet: true });
  }
  const cid = String(snap.charId || "").trim();
  if (cid) activateCharPersonaById(cid, { quiet: true });
  const cs = getChatScreenEl();
  if (cs?.classList.contains("is-open")) closeChatScreen();
  closeChatOfflineScreen();
  openChatListScreen();
  setChatListInboxTab("moments");
}

/** @param {ChatNotifySnap} snap */
function openChatFromNotifySnapshot(snap) {
  if (!snap) return;
  if (snap.notifyKind === "moments") {
    openMomentsFromNotifySnapshot(snap);
    return;
  }
  dismissChatNotifyForThread(snap.maskId, snap.threadId, { immediate: true });
  const mid = String(snap.maskId || "").trim();
  const tid = String(snap.threadId || "").trim();
  if (!mid || !tid) return;
  if (mid !== String(getActiveMaskIdForInbox() || "").trim()) {
    activateUserMaskById(mid, { quiet: true });
  }
  writeChatActiveThreadRef({ maskId: mid, threadId: tid });
  const cid = String(snap.charId || "").trim();
  if (cid) activateCharPersonaById(cid, { quiet: true });
  if (chatListScreen?.classList.contains("is-open")) closeChatListScreen();
  openChatScreen();
}

/** @type {ServiceWorkerRegistration | null} */
let _cachedSwRegistration = null;
let _chatSystemNotifPermAsked = false;

/** 周期性 ping SW，避免后台时 Worker 被回收导致无法弹系统通知 */
function pingSystemNotificationSw() {
  try {
    if ("serviceWorker" in navigator && navigator.serviceWorker.controller) {
      navigator.serviceWorker.controller.postMessage({ type: "keepalive-ping", ts: Date.now() });
    } else if (_cachedSwRegistration?.active) {
      _cachedSwRegistration.active.postMessage({ type: "keepalive-ping", ts: Date.now() });
    }
  } catch (_) {
    /* ignore */
  }
}

function isSystemChatNotificationSupported() {
  return typeof window !== "undefined" && "Notification" in window;
}

let _keepAliveSwMessageBound = false;

function warmUpSystemNotificationSw() {
  if (!("serviceWorker" in navigator)) return;
  if (!_keepAliveSwMessageBound) {
    _keepAliveSwMessageBound = true;
    navigator.serviceWorker.addEventListener("message", handleKeepAliveSwMessage);
  }
  navigator.serviceWorker
    .getRegistration()
    .then((reg) => {
      if (reg?.active) _cachedSwRegistration = reg;
      else {
        navigator.serviceWorker.ready
          .then((r) => {
            _cachedSwRegistration = r;
          })
          .catch(() => {});
      }
    })
    .catch(() => {});
  navigator.serviceWorker.addEventListener("controllerchange", () => {
    navigator.serviceWorker.getRegistration().then((reg) => {
      if (reg) _cachedSwRegistration = reg;
    }).catch(() => {});
  });
}

async function requestChatSystemNotificationPermission() {
  if (!isSystemChatNotificationSupported()) return "unsupported";
  if (Notification.permission === "granted") return "granted";
  if (Notification.permission === "denied") return "denied";
  try {
    return await Notification.requestPermission();
  } catch {
    return new Promise((resolve) => {
      Notification.requestPermission((result) => resolve(result));
    });
  }
}

function maybeAskChatSystemNotificationPermission() {
  if (_chatSystemNotifPermAsked || !isSystemChatNotificationSupported()) return;
  if (Notification.permission !== "default") return;
  _chatSystemNotifPermAsked = true;
  void requestChatSystemNotificationPermission();
}

function isPwaStandaloneForNotifications() {
  if (typeof window === "undefined") return false;
  if (window.matchMedia("(display-mode: standalone)").matches) return true;
  if (window.matchMedia("(display-mode: fullscreen)").matches) return true;
  const nav = /** @type {Navigator & { standalone?: boolean }} */ (window.navigator);
  if (nav.standalone === true) return true;
  if (String(document.referrer || "").includes("android-app://")) return true;
  return false;
}

const NOTIFICATION_ICON_DATA_MAX = 512000;

function defaultNotificationIconUrl() {
  const fallback = "./icons/icon-192.png";
  try {
    return new URL(fallback, window.location.href).href;
  } catch {
    return fallback;
  }
}

function toAbsoluteNotificationAsset(url) {
  const u = String(url || "").trim();
  if (!u) return defaultNotificationIconUrl();
  if (u.startsWith("data:image/")) {
    return u.length <= NOTIFICATION_ICON_DATA_MAX ? u : defaultNotificationIconUrl();
  }
  if (u.startsWith("http://") || u.startsWith("https://") || u.startsWith("blob:")) {
    return u;
  }
  try {
    return new URL(u, window.location.href).href;
  } catch {
    return defaultNotificationIconUrl();
  }
}

/** blob: 仅在主线程有效；缩略后转成 data: 供系统通知大图使用 */
async function resolveBlobNotificationIcon(blobUrl) {
  const u = String(blobUrl || "").trim();
  if (!u.startsWith("blob:")) return u;
  try {
    const res = await fetch(u);
    const blob = await res.blob();
    const bmp = await createImageBitmap(blob);
    const max = 192;
    const scale = Math.min(1, max / Math.max(bmp.width, bmp.height, 1));
    const w = Math.max(1, Math.round(bmp.width * scale));
    const h = Math.max(1, Math.round(bmp.height * scale));
    const canvas = document.createElement("canvas");
    canvas.width = w;
    canvas.height = h;
    const ctx = canvas.getContext("2d");
    if (!ctx) return defaultNotificationIconUrl();
    ctx.drawImage(bmp, 0, 0, w, h);
    bmp.close();
    const dataUrl = canvas.toDataURL("image/jpeg", 0.82);
    return dataUrl.length <= NOTIFICATION_ICON_DATA_MAX ? dataUrl : defaultNotificationIconUrl();
  } catch {
    return defaultNotificationIconUrl();
  }
}

function resolveSystemNotificationIcon(url) {
  return toAbsoluteNotificationAsset(url);
}

function isIosNotificationDevice() {
  return /iPad|iPhone|iPod/i.test(navigator.userAgent || "");
}

/** @type {Map<string, Promise<void>>} 同密谈系统通知串行发送，避免 blob 图标异步乱序 */
const chatSystemNotifySendChainByThread = new Map();

/** @param {ChatNotifySnap} snap */
function chatSystemNotifyThreadKey(snap) {
  if (!snap) return "";
  const mid = String(snap.maskId || "").trim();
  if (!mid) return "";
  if (snap.notifyKind === "moments") {
    return `moments:${mid}:${String(snap.charId || snap.threadId || "").trim()}`;
  }
  return `chat:${mid}:${String(snap.threadId || snap.charId || "").trim()}`;
}

/** @param {ChatNotifySnap} snap */
function enqueueSystemChatNotification(snap) {
  if (!snap) return;
  const tk = chatSystemNotifyThreadKey(snap);
  if (!tk) return;
  const prev = chatSystemNotifySendChainByThread.get(tk) || Promise.resolve();
  const job = prev.then(() => maybeSendSystemChatNotificationAsync(snap)).catch(() => {});
  chatSystemNotifySendChainByThread.set(tk, job);
  void job.finally(() => {
    if (chatSystemNotifySendChainByThread.get(tk) === job) chatSystemNotifySendChainByThread.delete(tk);
  });
}

/** @param {ChatNotifySnap} snap */
function buildSystemNotificationPayload(snap) {
  const title = String(snap.displayName || "").trim() || "没心机";
  const body = String(snap.preview || "").trim() || "新消息";
  const mid = String(snap.maskId || "").trim();
  const tid = String(snap.threadId || "").trim();
  const cid = String(snap.charId || "").trim();
  const tag =
    snap.notifyKind === "moments"
      ? `xxj_moments_${mid}_${cid || tid}`
      : `xxj_chat_${mid}_${tid || cid}`;
  return {
    title,
    body,
    icon: resolveSystemNotificationIcon(snap.avatarUrl),
    badge: toAbsoluteNotificationAsset("./icons/icon-maskable-512.png"),
    /** 同密谈共用 tag + renotify：新气泡替换旧系统通知（非堆叠多条） */
    tag,
    vibrate: !isIosNotificationDevice(),
    silent: false,
    data: {
      maskId: snap.maskId,
      threadId: snap.threadId,
      charId: snap.charId,
      notifyKind: snap.notifyKind || "chat"
    }
  };
}

/** 仅 App 在后台时弹系统通知（前台不弹） */
/** @param {ChatNotifySnap} snap @param {{ force?: boolean }} [opts] */
function shouldSendSystemChatNotification(snap, opts) {
  if (!document.hidden) return false;
  const mid = String(snap?.maskId || "").trim();
  const tid = String(snap?.threadId || "").trim();
  if (snap?.notifyKind === "moments") {
    return mid ? !isUserViewingMomentsPanel(mid) : true;
  }
  if (mid && tid) return !isUserViewingChatThread(mid, tid);
  return true;
}

/** registration.showNotification 可带 actions */
function buildRegNotificationOptions(payload, isBackground) {
  const isIOS = isIosNotificationDevice();
  const notifOpts = {
    body: payload.body,
    icon: payload.icon,
    badge: payload.badge,
    tag: payload.tag,
    data: payload.data,
    silent: false,
    renotify: true
  };
  if (!isIOS) {
    notifOpts.vibrate = [200, 100, 200];
    if (isBackground) notifOpts.requireInteraction = true;
    notifOpts.actions = [{ action: "open", title: "查看" }];
  }
  return notifOpts;
}

/** 短 icon 路径，避免超大 data: 进 postMessage */
function safeIconForSystemNotification(url) {
  const fallback = defaultNotificationIconUrl();
  const u = String(url || "").trim();
  if (!u) return fallback;
  if (u.startsWith("blob:")) return fallback;
  if (u.startsWith("data:")) {
    return u.length <= 2000 ? u : fallback;
  }
  if (u.startsWith("http://") || u.startsWith("https://")) return u;
  if (u.startsWith("./") || u.startsWith("/")) {
    try {
      return new URL(u, window.location.href).href;
    } catch {
      return fallback;
    }
  }
  return toAbsoluteNotificationAsset(u);
}

/** 手机系统通知：仅后台；controller→postMessage，否则 registration.showNotification */
/** @param {ChatNotifySnap} snap @param {{ force?: boolean }} [opts] */
async function maybeSendSystemChatNotificationAsync(snap, opts) {
  if (!snap || !isSystemChatNotificationSupported()) return false;
  if (!isSystemNotifEnabled()) return false;
  if (Notification.permission !== "granted") return false;
  if (!shouldSendSystemChatNotification(snap, opts)) return false;

  const rawIcon = resolveSystemNotificationIcon(snap.avatarUrl);
  if (String(rawIcon || "").startsWith("blob:")) {
    const icon = await resolveBlobNotificationIcon(rawIcon);
    return sendBackgroundSystemNotification(snap, icon);
  }
  return sendBackgroundSystemNotification(snap, rawIcon);
}

function setupSystemNotificationClickHandler() {
  if (!("serviceWorker" in navigator)) return;
  navigator.serviceWorker.addEventListener("message", (event) => {
    const d = event.data;
    if (!d || !d.type) return;
    if (d.type === "AUTO_GITHUB_BACKUP") {
      void tickBackupCloudGithubAutoUpload(true);
      return;
    }
    if (d.type !== "NOTIFICATION_CLICK") return;
    if (d.notifyKind === "backup") {
      openBackupZipModal();
      void tickBackupCloudGithubAutoUpload(true);
      return;
    }
    /** @type {ChatNotifySnap} */
    const snap = {
      notifyId: newChatNotifyId(),
      maskId: String(d.maskId || "").trim(),
      threadId: String(d.threadId || "").trim(),
      charId: String(d.charId || "").trim(),
      displayName: "",
      avatarUrl: "",
      initial: "?",
      preview: "",
      at: Date.now(),
      kind: "char",
      notifyKind: d.notifyKind === "moments" ? "moments" : "chat",
      dismissTimer: 0
    };
    if (!snap.maskId) return;
    if (snap.notifyKind === "moments") openMomentsFromNotifySnapshot(snap);
    else openChatFromNotifySnapshot(snap);
  });
}

/**
 * 角色发朋友圈等：顶部消息弹窗（与密谈新消息同组件，非底部 toast）。
 * @param {{ force?: boolean }} [opts] force：即使当前在朋友圈 tab 也弹条
 */
function maybePushMomentsFeedNotify(maskId, charId, threadId, preview, opts) {
  const mid = String(maskId || "").trim();
  const cid = String(charId || "").trim();
  const tid = String(threadId || "").trim();
  if (!mid || !cid) return;
  if (isChatNotifyGloballySuppressed()) return;
  if (!opts?.force && isUserViewingMomentsPanel(mid)) return;
  const found = tid ? findChatThreadInInbox(mid, tid) : null;
  const thread = found?.thread;
  const charP = readCharPersonaStore().items.find((x) => x.id === cid) || null;
  const persona = thread
    ? chatNotifyPersonaFromThread(thread, charP)
    : {
        charId: cid,
        displayName: charDisplayNameById(cid) || "角色",
        avatarUrl: String(charP?.avatar || "").trim(),
        initial: (charDisplayNameById(cid) || "角").slice(0, 1),
        kind: "char"
      };
  const prev = String(preview || "").trim() || "发了一条朋友圈";
  /** @type {ChatNotifySnap} */
  const snap = {
    notifyId: newChatNotifyId(),
    maskId: mid,
    threadId: tid,
    charId: persona.charId,
    displayName: persona.displayName,
    avatarUrl: persona.avatarUrl,
    initial: persona.initial,
    preview: prev.length > 120 ? `${prev.slice(0, 119)}…` : prev,
    at: Date.now(),
    kind: "char",
    notifyKind: "moments",
    dismissTimer: 0
  };
  if (document.hidden) enqueueSystemChatNotification(snap);
  else pushInAppChatNotifyBanner(snap);
}

function readPhotos() {
  const D = window.XXJ_DB;
  if (!D) return [];
  const raw = D.getKv(D.K.PHOTOS);
  return Array.isArray(raw) ? raw : [];
}

function savePhotos(photos) {
  const D = window.XXJ_DB;
  if (D) D.setKv(D.K.PHOTOS, photos);
}

let heroNoteSaveTimer = 0;

function persistHeroNoteFromDom() {
  const D = window.XXJ_DB;
  if (!D || !heroNoteNode) return;
  const text = String(heroNoteNode.textContent || "").trim();
  D.setKv(D.K.HERO_NOTE, text);
}

function initHeroNote() {
  if (!heroNoteNode) return;
  const D = window.XXJ_DB;
  const saved = D ? D.getKv(D.K.HERO_NOTE) : "";
  if (saved != null && String(saved).trim()) {
    heroNoteNode.textContent = String(saved).trim();
  } else if (!String(heroNoteNode.textContent || "").trim()) {
    heroNoteNode.textContent = HERO_NOTE_DEFAULT;
  }
  if (heroNoteNode.dataset.heroNoteBound === "1") return;
  heroNoteNode.dataset.heroNoteBound = "1";
  const scheduleSave = () => {
    window.clearTimeout(heroNoteSaveTimer);
    heroNoteSaveTimer = window.setTimeout(persistHeroNoteFromDom, 350);
  };
  heroNoteNode.addEventListener("input", scheduleSave);
  heroNoteNode.addEventListener("blur", () => {
    window.clearTimeout(heroNoteSaveTimer);
    persistHeroNoteFromDom();
  });
}

function renderPolaroids() {
  const photos = readPhotos();
  polaroidCards.forEach((card, index) => {
    const img = card.querySelector("img");
    if (!img) return;
    const src = photos[index] || "";
    if (!img.loading) img.loading = index === 0 ? "eager" : "lazy";
    if (!img.decoding) img.decoding = "async";
    if (String(img.src || "") !== src) img.src = src;
    card.classList.toggle("is-empty", !src);
  });
}

function refreshSettingsThemeState() {
  const node = document.getElementById("settings-theme-state");
  if (!node) return;
  node.textContent = document.body.classList.contains("dark") ? "已开启" : "已关闭";
}

function isCloudAuthEnabled() {
  return window.__xxjCloudAuthEnabled !== false;
}

function refreshSettingsAuthStatus() {
  const node = document.getElementById("settings-auth-status");
  const openBtn = document.getElementById("settings-open-auth");
  const D = window.XXJ_DB;
  if (!node || !D) return;
  if (!isCloudAuthEnabled()) {
    node.textContent = "—";
    if (openBtn) openBtn.hidden = true;
    return;
  }
  if (openBtn) openBtn.hidden = false;
  if (D.getKv(D.K.TOKEN)) {
    node.textContent = "已登录";
  } else {
    node.textContent = "未登录";
  }
}

function refreshSettingsPanel() {
  refreshSettingsThemeState();
  refreshSettingsAuthStatus();
}

function setSettingsStatusLine(elementId, text, kind) {
  const el = document.getElementById(elementId);
  if (!el) return;
  el.textContent = text;
  el.classList.remove("is-ok", "is-err");
  if (kind === "ok") el.classList.add("is-ok");
  if (kind === "err") el.classList.add("is-err");
}

