/** @param {unknown} raw @returns {string} 空串表示不传 language_boost */
function normalizeMinimaxLanguageBoostInput(raw) {
  const s = String(raw ?? "").trim();
  if (!s) return "";
  if (MINIMAX_LANGUAGE_BOOST_ALLOWED.has(s)) return s;
  const alias = MINIMAX_LANGUAGE_BOOST_ALIASES[s];
  if (alias) return alias;
  const low = s.toLowerCase();
  if (low === "auto") return "auto";
  for (const [k, v] of Object.entries(MINIMAX_LANGUAGE_BOOST_ALIASES)) {
    if (k.toLowerCase() === low) return v;
  }
  for (const v of MINIMAX_LANGUAGE_BOOST_ALLOWED) {
    if (v.toLowerCase() === low) return v;
  }
  return s;
}

/** 与 index.html 中 minimax-language-boost 下拉选项一致（不含 __custom__） */
const MINIMAX_LANGUAGE_BOOST_IN_SELECT = new Set([
  "auto",
  "Chinese",
  "Chinese,Yue",
  "English",
  "Japanese",
  "Korean",
  "French",
  "German",
  "Spanish",
  "Russian",
  "Portuguese",
  "Arabic",
  "Thai",
  "Vietnamese"
]);

/** @param {string} apiValue */
function syncMinimaxLanguageBoostPanelFromValue(apiValue) {
  const sel = document.getElementById("minimax-language-boost");
  const custom = document.getElementById("minimax-language-boost-custom");
  if (!(sel instanceof HTMLSelectElement)) return;
  const v = normalizeMinimaxLanguageBoostInput(apiValue);
  if (!v) {
    sel.value = "";
    if (custom instanceof HTMLInputElement) {
      custom.hidden = true;
      custom.value = "";
    }
    return;
  }
  if (MINIMAX_LANGUAGE_BOOST_IN_SELECT.has(v)) {
    sel.value = v;
    if (custom instanceof HTMLInputElement) {
      custom.hidden = true;
      custom.value = "";
    }
    return;
  }
  sel.value = "__custom__";
  if (custom instanceof HTMLInputElement) {
    custom.hidden = false;
    custom.value = v;
  }
}

/** @returns {string} */
function readMinimaxLanguageBoostFromPanel() {
  const sel = document.getElementById("minimax-language-boost");
  const custom = document.getElementById("minimax-language-boost-custom");
  if (!(sel instanceof HTMLSelectElement)) return "";
  if (sel.value === "__custom__") {
    return normalizeMinimaxLanguageBoostInput(
      custom instanceof HTMLInputElement ? custom.value : ""
    );
  }
  return normalizeMinimaxLanguageBoostInput(sel.value);
}

/** @param {string} selectId @param {string} customInputId @param {() => void} [onChanged] */
function bindMinimaxSelectCustomToggle(selectId, customInputId, onChanged) {
  document.getElementById(selectId)?.addEventListener("change", (e) => {
    const sel = e.target;
    if (!(sel instanceof HTMLSelectElement)) return;
    const custom = document.getElementById(customInputId);
    if (!(custom instanceof HTMLInputElement)) return;
    const on = String(sel.value || "") === "__custom__";
    custom.hidden = !on;
    if (on) window.setTimeout(() => custom.focus(), 0);
    else custom.value = "";
    if (typeof onChanged === "function") onChanged(sel);
  });
}

/** @param {{ name?: string, voiceId?: string, languageBoost?: string, speed?: number, vol?: number, pitch?: number, id?: string }} p */
function normalizeMinimaxVoicePreset(p) {
  if (!p || typeof p !== "object") return null;
  const voiceId = String(p.voiceId || p.voice_id || "").trim();
  if (!voiceId) return null;
  const speed = Number(p.speed);
  const vol = Number(p.vol);
  const pitch = Number(p.pitch);
  return {
    id: String(p.id || "").trim() || newEntityId(),
    name: String(p.name || "").trim().slice(0, 20) || "未命名",
    voiceId,
    languageBoost: normalizeMinimaxLanguageBoostInput(p.languageBoost ?? p.language_boost ?? ""),
    speed: Number.isFinite(speed) ? Math.max(0.5, Math.min(2, speed)) : null,
    vol: Number.isFinite(vol) ? Math.max(0.1, Math.min(2, vol)) : null,
    pitch: Number.isFinite(pitch) ? Math.max(-12, Math.min(12, Math.round(pitch))) : null
  };
}

/** @param {{ name?: string, voiceId?: string, languageBoost?: string }} p */
function formatMinimaxPresetSummary(p) {
  const bits = [String(p.name || "未命名"), String(p.voiceId || "")];
  const lb = String(p.languageBoost || "").trim();
  if (lb) bits.push(lb);
  const sp = p.speed != null ? Number(p.speed) : NaN;
  if (Number.isFinite(sp) && sp !== 1) bits.push(`速${sp.toFixed(2)}`);
  return bits.filter(Boolean).join(" · ");
}

function normalizeMinimaxTtsConfig(raw) {
  const o = raw && typeof raw === "object" ? raw : {};
  const enabled = Boolean(o.enabled);
  const apiKey = String(o.apiKey ?? "").trim();
  const groupId = String(o.groupId ?? "").trim();
  const legacyDefaultVoiceId = String(o.defaultVoiceId ?? "female-shaonv").trim() || "female-shaonv";
  const defaultVoiceRef = String(o.defaultVoiceRef ?? "").trim() || legacyDefaultVoiceId;
  const srcPresets = Array.isArray(o.voicePresets) ? o.voicePresets : [];
  const voicePresets = [];
  for (const p of srcPresets) {
    const norm = normalizeMinimaxVoicePreset(p);
    if (!norm) continue;
    voicePresets.push(norm);
    if (voicePresets.length >= 48) break;
  }
  const model = resolveMinimaxTtsModel(o.model);
  const proxyUrl = String(o.proxyUrl ?? "").trim();
  const speed = Number(o.speed);
  const vol = Number(o.vol);
  const pitch = Number(o.pitch);
  const defaultLanguageBoost = normalizeMinimaxLanguageBoostInput(
    o.defaultLanguageBoost ?? o.default_language_boost ?? ""
  );
  const defaultVoiceId = resolveMinimaxVoiceRef(defaultVoiceRef, voicePresets) || legacyDefaultVoiceId || "female-shaonv";
  return {
    v: 1,
    enabled,
    apiKey,
    groupId,
    voicePresets,
    defaultVoiceRef,
    defaultVoiceId,
    defaultLanguageBoost,
    model,
    proxyUrl,
    speed: Number.isFinite(speed) ? Math.max(0.5, Math.min(2, speed)) : 1.0,
    vol: Number.isFinite(vol) ? Math.max(0.1, Math.min(2, vol)) : 1.0,
    pitch: Number.isFinite(pitch) ? Math.max(-12, Math.min(12, Math.round(pitch))) : 0
  };
}

/** @param {string} ref @param {ReturnType<typeof readMinimaxTtsConfig>} [cfg] */
function findMinimaxVoicePresetByRef(ref, cfg) {
  const c = cfg || readMinimaxTtsConfig();
  const s = String(ref || "").trim();
  if (!s.startsWith("preset:")) return null;
  const id = s.slice("preset:".length).trim();
  if (!id || id === "__default__") return (c.voicePresets || [])[0] || null;
  return (c.voicePresets || []).find((p) => String(p?.id || "") === id) || null;
}

/**
 * 合成参数：预设内 speed/vol/pitch/language 优先，缺省用全局 cfg。
 * @param {string} voiceIdOrRef
 * @param {ReturnType<typeof readMinimaxTtsConfig>} [cfg]
 */
function resolveMinimaxSynthBundle(voiceIdOrRef, cfg) {
  const c = normalizeMinimaxTtsConfig(cfg || readMinimaxTtsConfig());
  const ref = String(voiceIdOrRef || "").trim();
  const preset = ref.startsWith("preset:") ? findMinimaxVoicePresetByRef(ref, c) : null;
  const effectiveVoiceId = resolveMinimaxVoiceIdForUse(ref, c);
  const pickNum = (presetVal, globalVal, min, max, roundInt) => {
    const n = presetVal != null ? Number(presetVal) : Number(globalVal);
    if (!Number.isFinite(n)) return globalVal;
    const clamped = Math.max(min, Math.min(max, roundInt ? Math.round(n) : n));
    return clamped;
  };
  let languageBoost = String(c.defaultLanguageBoost || "").trim();
  if (preset) {
    const pl = String(preset.languageBoost || "").trim();
    if (pl) languageBoost = pl;
  }
  return {
    effectiveVoiceId,
    speed: pickNum(preset?.speed, c.speed, 0.5, 2, false),
    vol: pickNum(preset?.vol, c.vol, 0.1, 2, false),
    pitch: pickNum(preset?.pitch, c.pitch, -12, 12, true),
    languageBoost: languageBoost || ""
  };
}

function resolveMinimaxVoiceRef(ref, presets) {
  const s = String(ref || "").trim();
  if (!s) return "";
  if (s.startsWith("preset:")) {
    const id = s.slice("preset:".length).trim();
    const hit = Array.isArray(presets) ? presets.find((p) => String(p?.id || "") === id) : null;
    return hit && hit.voiceId ? String(hit.voiceId).trim() : "";
  }
  // raw voiceId
  return s;
}

/** 发给 MiniMax 的最终 voice_id：禁止把 preset:… 原样提交（海外/自定义预设常因此合成失败）。 */
function resolveMinimaxVoiceIdForUse(voiceIdOrRef, cfg) {
  const c = cfg || readMinimaxTtsConfig();
  const fallback = String(c.defaultVoiceId || "female-shaonv").trim() || "female-shaonv";
  const raw = String(voiceIdOrRef || "").trim();
  if (!raw) return fallback;
  const resolved = resolveMinimaxVoiceRef(raw, c.voicePresets || []);
  if (resolved) return resolved;
  if (raw.startsWith("preset:")) return fallback;
  return raw;
}

/** 角色绑定的 MiniMax 音色（兼容旧版小心机 minimaxPresetId）。 */
function getCharBoundMinimaxVoiceRef(row) {
  if (!row || typeof row !== "object") return "";
  const vid = row.minimaxVoiceId != null ? String(row.minimaxVoiceId).trim() : "";
  if (vid) return vid;
  const pid = row.minimaxPresetId != null ? String(row.minimaxPresetId).trim() : "";
  if (!pid) return "";
  return pid.startsWith("preset:") ? pid : `preset:${pid}`;
}

/** t2a_v2：新版 api.minimaxi.com 常用 speech-2.8-*；旧版 speech-01 会报错。 */
function resolveMinimaxTtsModel(model) {
  const m = String(model ?? "").trim();
  if (!m || /^speech-01/i.test(m)) return "speech-2.8-hd";
  if (/^speech-2\.8/i.test(m)) return m;
  if (m === "speech-02" || m === "speech-02-hd") return m;
  if (/^speech-/i.test(m)) return m;
  return "speech-2.8-hd";
}

/** 旧开放平台在 URL 上带 GroupId；新版文档仅 Bearer + JSON，可留空。 */
function minimaxTtsGroupIdQuery(cfg) {
  const gid = String((cfg && cfg.groupId) || "").trim();
  return gid ? `?GroupId=${encodeURIComponent(gid)}` : "";
}

function minimaxTestPhraseForVoice(voiceId, languageBoost) {
  const lb = String(languageBoost || "").trim();
  if (lb === "English" || /^english/i.test(lb)) return "Hello, this is a voice test.";
  if (lb === "Japanese" || /^japanese/i.test(lb)) return "こんにちは。これは音声テストです。";
  if (lb === "Korean" || /^korean/i.test(lb)) return "안녕하세요. 음성 테스트입니다.";
  const v = String(voiceId || "");
  if (/^English_/i.test(v)) return "Hello, this is a voice test.";
  if (/^Japanese_/i.test(v)) return "こんにちは。これは音声テストです。";
  if (/^Korean_/i.test(v)) return "안녕하세요. 음성 테스트입니다.";
  return "你好，这是一段语音测试。";
}

/** lazy KV（KV_LAZY_AT_BOOT）灌入完成：含人设 / 世界书 / 表情等 */
function lazyKvBootReady() {
  return Boolean(window.__xxjKvRestReady && window.__xxjOtherKvReady);
}

function readMinimaxTtsConfig() {
  const D = window.XXJ_DB;
  if (!D) return normalizeMinimaxTtsConfig(null);
  const raw = D.getKv(D.K.MINIMAX_TTS_CONFIG);
  if (raw && raw.v === 1) return normalizeMinimaxTtsConfig(raw);
  if (!lazyKvBootReady()) return normalizeMinimaxTtsConfig(null);
  const init = normalizeMinimaxTtsConfig(null);
  D.setKv(D.K.MINIMAX_TTS_CONFIG, init);
  return init;
}

function writeMinimaxTtsConfig(cfg) {
  const D = window.XXJ_DB;
  if (!D) return;
  D.setKv(D.K.MINIMAX_TTS_CONFIG, normalizeMinimaxTtsConfig(cfg));
}

