/** @param {unknown} raw @returns {"openai"|"novelai"|"custom"} */
function normalizeImageGenProvider(raw) {
  const p = String(raw || "openai").trim().toLowerCase();
  if (p === "custom") return "custom";
  if (p === "novelai") return "novelai";
  return "openai";
}

/** 旧版 provider=gemini → custom（有 Base）或 openai */
function migrateLegacyImageGenProvider(raw) {
  const o = raw && typeof raw === "object" ? raw : {};
  const rawP = String(o.provider || "").trim().toLowerCase();
  if (rawP !== "gemini") return normalizeImageGenProvider(o.provider);
  const t = String(o.geminiTransport || "").trim().toLowerCase();
  if (t === "relay" || t === "openai_compat" || t === "openai-compat") return "custom";
  if (t === "native") return "openai";
  return String(o.baseUrl || "").trim() ? "custom" : "openai";
}

/** @param {ReturnType<typeof normalizeImageGenConfig>} cfg */
function imageGenUsesCustomOpenAiBase(cfg) {
  return cfg.provider === "custom";
}

function getImageGenModelPresets(provider) {
  const p = normalizeImageGenProvider(provider);
  if (p === "novelai") return IMAGE_GEN_MODEL_PRESETS_NOVELAI;
  return IMAGE_GEN_MODEL_PRESETS_OPENAI;
}

/** 最近一次「拉取模型」结果（OpenAI / 自定义 Base），用于合并进下拉 */
let cachedImageGenFetchedIds = [];

/**
 * 从 GET /v1/models 全量 id 中优先筛「图像相关」，避免几百个聊天模型塞满下拉。
 * @param {string[]} ids
 */
function filterModelIdsForImageGenList(ids) {
  const all = ids.map((x) => String(x || "").trim()).filter(Boolean);
  if (!all.length) return [];
  const re =
    /gpt-image|dall-e|dall_e|gemini|image-alpha|text-to-image|flux|sdxl|stable-diffusion|midjourney|imagen|\bimage\b/i;
  const hit = all.filter((id) => re.test(id));
  const cap = 200;
  // 筛出较多时只用命中项；否则把「命中」排在前面再拼上其余 id，避免网关只命中 1～2 个时误以为只有一个生图模型
  if (hit.length >= 3) return hit.slice(0, cap);
  if (!hit.length) return all.slice(0, cap);
  const rest = all.filter((id) => !hit.includes(id));
  return hit.concat(rest).slice(0, cap);
}

/**
 * @param {"openai"|"novelai"|"custom"} provider
 * @param {string} baseFromForm
 */
function resolveImageGenModelsBaseUrlForFetch(provider, baseFromForm) {
  const p = normalizeImageGenProvider(provider);
  if (p === "novelai") return null;
  if (p === "openai") return "https://api.openai.com/v1";
  const b = String(baseFromForm || "").trim().replace(/\/+$/, "");
  if (!b) return null;
  if (/\/v1$/i.test(b)) return b;
  return `${b}/v1`;
}

function resolveImageGenApiKeyForForm() {
  const keyInp = document.getElementById("image-gen-key");
  const fromForm = keyInp instanceof HTMLInputElement ? String(keyInp.value || "").trim() : "";
  if (fromForm) return fromForm;
  return String(readImageGenConfig().apiKey || "").trim();
}

async function fetchImageGenModelsFromUi() {
  const provEl = document.getElementById("image-gen-provider");
  const raw = provEl instanceof HTMLSelectElement ? String(provEl.value || "openai").trim().toLowerCase() : "openai";
  const provider = normalizeImageGenProvider(raw);
  if (provider === "novelai") {
    showToast("NovelAI 图像接口不提供 OpenAI 式 GET /v1/models，请用上方预设");
    return;
  }
  const baseInp = document.getElementById("image-gen-base");
  const baseFromForm = baseInp instanceof HTMLInputElement ? String(baseInp.value || "").trim() : "";
  const baseUrl = resolveImageGenModelsBaseUrlForFetch(provider, baseFromForm);
  if (!baseUrl) {
    showToast(provider === "custom" ? "请先填写 API Base" : "无法解析模型列表地址");
    return;
  }
  const apiKey = resolveImageGenApiKeyForForm();
  if (!apiKey) {
    showToast("请填写 API Key（留空表示沿用已保存的 Key，若从未保存过则需填写）");
    return;
  }
  const ai = window.RP_AI;
  if (!ai || typeof ai.listModels !== "function") {
    showToast("模块未就绪");
    return;
  }
  const btn = document.getElementById("image-gen-fetch-models");
  const prevLabel = btn?.textContent;
  if (btn) {
    btn.disabled = true;
    btn.textContent = "拉取中…";
  }
  try {
    const ids = await ai.listModels({ baseUrl, apiKey });
    const arr = Array.isArray(ids) ? ids : [];
    const use = filterModelIdsForImageGenList(arr);
    cachedImageGenFetchedIds = use.slice();
    const dl = document.getElementById("image-gen-model-custom-datalist");
    if (dl) {
      dl.innerHTML = "";
      for (const id of use.slice(0, 200)) {
        const o = document.createElement("option");
        o.value = id;
        dl.appendChild(o);
      }
    }
    refreshImageGenProviderUi();
    const modelSel = document.getElementById("image-gen-model");
    if (provider === "custom" && modelSel instanceof HTMLSelectElement) {
      const modelCustom = document.getElementById("image-gen-model-custom");
      if (modelCustom instanceof HTMLInputElement) {
        modelCustom.value = String(modelSel.value || modelCustom.value || use[0] || "");
      }
    }
    const note =
      use.length === 0
        ? "未解析到模型 id，请检查 Base 是否为 OpenAI 兼容 /v1"
        : arr.length
          ? `已合并 ${use.length} 个模型进下拉（接口 ${arr.length} 条）`
          : `已合并 ${use.length} 个模型进下拉`;
    showToast(note, use.length ? 2800 : 4200);
    if (use.length) {
      const openPicker = window.__xxjOpenModelIdPicker;
      if (typeof openPicker === "function") {
        openPicker(use, {
          title: "选择生图模型",
          onPick: (id) => {
            if (provider === "custom") {
              const inp = document.getElementById("image-gen-model-custom");
              if (inp instanceof HTMLInputElement) inp.value = id;
            } else if (modelSel instanceof HTMLSelectElement) {
              ensureSelectHasOption(modelSel, id, id);
              modelSel.value = id;
            }
            refreshImageGenProviderUi();
            showToast(`已选择模型：${id}`);
          }
        });
      } else if (modelSel instanceof HTMLElement) {
        try {
          modelSel.scrollIntoView({ block: "nearest", behavior: "smooth" });
        } catch (_) {}
      }
    }
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    const short = msg.length > 52 ? `${msg.slice(0, 52)}…` : msg;
    showToast(`拉取失败：${short}`);
  } finally {
    if (btn) {
      btn.disabled = false;
      if (prevLabel != null) btn.textContent = prevLabel;
    }
  }
}

function rebuildImageGenModelSelect() {
  const sel = document.getElementById("image-gen-model");
  const provEl = document.getElementById("image-gen-provider");
  if (!(sel instanceof HTMLSelectElement) || !(provEl instanceof HTMLSelectElement)) return;
  const raw = String(provEl.value || "openai").trim();
  const provider = normalizeImageGenProvider(raw);
  const cfg = readImageGenConfig();
  const hint = String(sel.value || "").trim();
  const presets = getImageGenModelPresets(provider);
  const presetVals = new Set(presets.map((x) => x.value));

  /** @type {ImageGenModelOpt[]} */
  let opts = presets.map((p) => ({ value: p.value, label: p.label }));
  let skippedExtra = 0;

  if (provider !== "novelai" && cachedImageGenFetchedIds.length) {
    if (provider === "custom") {
      const seen = new Set(presetVals);
      /** @type {ImageGenModelOpt[]} */
      const extra = [];
      for (const id of cachedImageGenFetchedIds) {
        const s = String(id || "").trim();
        if (!s || seen.has(s)) continue;
        seen.add(s);
        extra.push({ value: s, label: s });
      }
      extra.sort((a, b) => a.value.localeCompare(b.value));
      const cap = 150;
      skippedExtra = Math.max(0, extra.length - cap);
      opts = opts.concat(extra.slice(0, cap));
    }
  }

  sel.replaceChildren();
  for (const pr of opts) {
    const o = document.createElement("option");
    o.value = pr.value;
    o.textContent = pr.label;
    sel.appendChild(o);
  }
  if (skippedExtra > 0) {
    const o = document.createElement("option");
    o.disabled = true;
    o.value = "__trunc__";
    o.textContent = `… 另有 ${skippedExtra} 个未展示`;
    sel.appendChild(o);
  }

  const vals = opts.map((x) => x.value).filter((v) => v !== "__trunc__");
  const sameProv = cfg.provider === provider;
  let pick =
    vals.includes(hint) ? hint : sameProv && vals.includes(cfg.model) ? cfg.model : vals[0];
  if (!vals.includes(pick)) pick = vals[0];
  sel.value = pick;
  const modelCustomEl = document.getElementById("image-gen-model-custom");
  if (provider === "custom" && modelCustomEl instanceof HTMLInputElement && !sel.hidden) {
    modelCustomEl.value = pick;
  }
}

function dedupeImageGenSizes(list) {
  const seen = new Set();
  /** @type {ImageGenSizeOpt[]} */
  const out = [];
  for (const it of list) {
    const v = String(it?.value || "").trim();
    if (!v || seen.has(v)) continue;
    seen.add(v);
    out.push({ value: v, label: String(it?.label || v) });
  }
  return out;
}

function getImageGenSizeOptionsForProvider(provider) {
  const p = normalizeImageGenProvider(provider);
  if (p === "novelai") return dedupeImageGenSizes(IMAGE_GEN_SIZE_PRESETS_NOVELAI);
  return dedupeImageGenSizes(IMAGE_GEN_SIZE_PRESETS_OPENAI);
}

/**
 * @param {unknown} raw
 * @returns {{
 *   v: 1,
 *   enabled: boolean,
 *   provider: "openai" | "novelai" | "custom",
 *   baseUrl: string,
 *   apiKey: string,
 *   model: string,
 *   size: string,
 *   stylePrompt: string,
 *   negativePrompt: string,
 *   naiSampler: string,
 *   naiSteps: number,
 *   naiCfgScale: number,
 *   naiSeed: number,
 *   naiSmea: boolean,
 *   openaiQuality: string,
 *   openaiInputFidelity: string
 * }}
 */
function normalizeImageGenConfig(raw) {
  const o = raw && typeof raw === "object" ? raw : {};
  const provider = migrateLegacyImageGenProvider(o);
  const baseUrl = String(o.baseUrl || "").trim().replace(/\/+$/, "");
  const apiKey = String(o.apiKey || "").trim();
  const modelPresets = getImageGenModelPresets(provider);
  const allowedM = modelPresets.map((x) => x.value);
  let model = String(o.model || "").trim();
  if (provider !== "custom" && /^gemini-/i.test(model)) model = "";
  const defaultModel =
    provider === "novelai"
      ? allowedM[0] || "nai-diffusion-4-5-curated"
      : IMAGE_GEN_DEFAULT_OPENAI_MODEL;
  if (provider === "custom") {
    if (!model) model = IMAGE_GEN_DEFAULT_OPENAI_MODEL;
  } else if (!model) {
    model = defaultModel;
  } else if (!allowedM.includes(model)) {
    if (provider === "novelai") {
      model = /^nai-/i.test(model) ? model : allowedM[0] || "nai-diffusion-4-5-curated";
    }
    // openai / custom：允许预设以外的模型 id
  }
  let size = String(o.size || "").trim();
  const allowed = getImageGenSizeOptionsForProvider(provider).map((x) => x.value);
  let defaultSize = "1024x1024";
  if (provider === "novelai") defaultSize = allowed.includes("832x1216") ? "832x1216" : allowed[0] || "832x1216";
  else defaultSize = allowed.includes("1024x1024") ? "1024x1024" : allowed[0] || "1024x1024";
  if (!size || !allowed.includes(size)) size = defaultSize;
  const allowedNaiSamp = new Set(IMAGE_GEN_NAI_SAMPLERS.map((x) => x.value));
  let naiSampler = String(o.naiSampler || "").trim();
  if (!allowedNaiSamp.has(naiSampler)) naiSampler = "k_euler";
  let naiSteps = Number(o.naiSteps);
  if (!Number.isFinite(naiSteps)) naiSteps = 28;
  naiSteps = Math.min(50, Math.max(10, Math.floor(naiSteps)));
  let naiCfgScale = Number(o.naiCfgScale);
  if (!Number.isFinite(naiCfgScale)) naiCfgScale = 5;
  naiCfgScale = Math.round(Math.min(15, Math.max(1, naiCfgScale)) * 10) / 10;
  let naiSeed = Number(o.naiSeed);
  if (!Number.isFinite(naiSeed)) naiSeed = -1;
  naiSeed = naiSeed < 0 ? -1 : Math.min(4294967295, Math.max(0, Math.floor(naiSeed)));
  let naiSmea = o.naiSmea !== undefined ? Boolean(o.naiSmea) : true;
  if (isNovelAiV4ModelId(model)) naiSmea = false;
  return {
    v: 1,
    enabled: Boolean(o.enabled),
    provider,
    baseUrl,
    apiKey,
    model,
    size,
    stylePrompt: String(o.stylePrompt ?? "").trim().slice(0, 2000),
    negativePrompt: String(o.negativePrompt ?? "").trim().slice(0, 2000),
    naiSampler,
    naiSteps,
    naiCfgScale,
    naiSeed,
    naiSmea,
    openaiQuality: normalizeOpenAiImageQuality(o.openaiQuality),
    openaiInputFidelity: normalizeOpenAiInputFidelity(o.openaiInputFidelity)
  };
}

function readImageGenConfig() {
  const D = window.XXJ_DB;
  if (!D) return normalizeImageGenConfig(null);
  const raw = D.getKv(D.K.IMAGE_GEN_CONFIG);
  if (raw && raw.v === 1) return normalizeImageGenConfig(raw);
  if (!lazyKvBootReady()) return normalizeImageGenConfig(null);
  const init = normalizeImageGenConfig(null);
  D.setKv(D.K.IMAGE_GEN_CONFIG, init);
  return init;
}

function writeImageGenConfig(cfg) {
  const D = window.XXJ_DB;
  if (!D) return;
  D.setKv(D.K.IMAGE_GEN_CONFIG, normalizeImageGenConfig(cfg));
}

const IMAGE_GEN_PRESET_MAX = 36;
/** 卷宗「会话生图风格」里「自定义」选项的 select value（勿与真实预设 id 冲突） */
const CHAT_THREAD_IMAGE_STYLE_PRESET_CUSTOM = "__imgstyle_custom__";

/**
 * @param {unknown} raw
 * @returns {{ id: string, name: string, updatedAt: number, includeCredentials: boolean, apiKey: string, provider: "openai"|"novelai"|"custom", baseUrl: string, model: string, size: string, stylePrompt: string, negativePrompt: string, naiSampler: string, naiSteps: number, naiCfgScale: number, naiSeed: number, naiSmea: boolean }}
 */
function normalizeImageGenPreset(raw) {
  const o = raw && typeof raw === "object" ? raw : {};
  const id = String(o.id || "").trim() || `igp_${Date.now()}`;
  const name = String(o.name || "未命名").trim().slice(0, 48);
  const hasInc = Object.prototype.hasOwnProperty.call(o, "includeCredentials");
  /** 旧数据无该字段：视为「整条生图配置」预设（含 Key） */
  const includeCredentials = hasInc ? o.includeCredentials === true : true;

  if (!includeCredentials) {
    const merged = normalizeImageGenConfig({
      v: 1,
      enabled: false,
      stylePrompt: o.stylePrompt,
      negativePrompt: o.negativePrompt,
      openaiQuality: o.openaiQuality,
      openaiInputFidelity: o.openaiInputFidelity
    });
    return {
      id,
      name,
      updatedAt: Number(o.updatedAt) || Date.now(),
      includeCredentials: false,
      apiKey: "",
      provider: merged.provider,
      baseUrl: merged.baseUrl,
      model: merged.model,
      size: merged.size,
      stylePrompt: merged.stylePrompt,
      negativePrompt: merged.negativePrompt,
      naiSampler: merged.naiSampler,
      naiSteps: merged.naiSteps,
      naiCfgScale: merged.naiCfgScale,
      naiSeed: merged.naiSeed,
      naiSmea: merged.naiSmea,
      openaiQuality: merged.openaiQuality,
      openaiInputFidelity: merged.openaiInputFidelity
    };
  }

  const merged = normalizeImageGenConfig({
    v: 1,
    enabled: false,
    apiKey: o.apiKey,
    provider: o.provider,
    baseUrl: o.baseUrl,
    model: o.model,
    size: o.size,
    stylePrompt: o.stylePrompt,
    negativePrompt: o.negativePrompt,
    naiSampler: o.naiSampler,
    naiSteps: o.naiSteps,
    naiCfgScale: o.naiCfgScale,
    naiSeed: o.naiSeed,
    naiSmea: o.naiSmea,
    openaiQuality: o.openaiQuality,
    openaiInputFidelity: o.openaiInputFidelity
  });
  return {
    id,
    name,
    updatedAt: Number(o.updatedAt) || Date.now(),
    includeCredentials: true,
    apiKey: merged.apiKey,
    provider: merged.provider,
    baseUrl: merged.baseUrl,
    model: merged.model,
    size: merged.size,
    stylePrompt: merged.stylePrompt,
    negativePrompt: merged.negativePrompt,
    naiSampler: merged.naiSampler,
    naiSteps: merged.naiSteps,
    naiCfgScale: merged.naiCfgScale,
    naiSeed: merged.naiSeed,
    naiSmea: merged.naiSmea,
    openaiQuality: merged.openaiQuality,
    openaiInputFidelity: merged.openaiInputFidelity
  };
}

function readImageGenPresets() {
  const D = window.XXJ_DB;
  if (!D) return [];
  const raw = D.getKv(D.K.IMAGE_GEN_PRESETS);
  if (!raw || typeof raw !== "object" || raw.v !== 1 || !Array.isArray(raw.items)) return [];
  /** @type {unknown[]} */
  const arr = raw.items;
  const out = [];
  for (const it of arr) {
    try {
      out.push(normalizeImageGenPreset(it));
    } catch (_) {}
    if (out.length >= IMAGE_GEN_PRESET_MAX) break;
  }
  return out;
}

function writeImageGenPresets(items) {
  const D = window.XXJ_DB;
  if (!D) return;
  const list = items.slice(0, IMAGE_GEN_PRESET_MAX).map((x) => normalizeImageGenPreset(x));
  D.setKv(D.K.IMAGE_GEN_PRESETS, { v: 1, items: list });
}

/**
 * 本密谈会话配图末尾的风格后缀：可选预设、或自定义；未设置则跟全局 `cfg.stylePrompt`。
 * @param {unknown} thread
 * @param {ReturnType<typeof normalizeImageGenConfig>} cfg
 */
function resolveThreadSessionImageStyleSuffix(thread, cfg) {
  const base = String(cfg?.stylePrompt || "").trim();
  if (!thread || typeof thread !== "object") return base;
  const pid = String(thread.chatThreadImageStylePresetId || "").trim();
  if (pid === CHAT_THREAD_IMAGE_STYLE_PRESET_CUSTOM) {
    const c = String(thread.chatThreadImageStylePromptCustom || "").trim();
    return (c || base).slice(0, 2000);
  }
  if (pid) {
    const presets = readImageGenPresets();
    const hit = presets.find((x) => String(x.id) === pid);
    if (hit) return String(hit.stylePrompt || "").trim().slice(0, 2000) || base;
  }
  return base;
}

/** 晤面自动生图专用风格后缀（与线上会话后缀分开存；未设则跟全局生图接入）。 */
function resolveThreadOfflineSessionImageStyleSuffix(thread, cfg) {
  const base = String(cfg?.stylePrompt || "").trim();
  if (!thread || typeof thread !== "object") return base;
  const pid = String(thread.chatThreadOfflineImageStylePresetId || "").trim();
  if (pid === CHAT_THREAD_IMAGE_STYLE_PRESET_CUSTOM) {
    const c = String(thread.chatThreadOfflineImageStylePromptCustom || "").trim();
    return (c || base).slice(0, 2000);
  }
  if (pid) {
    const presets = readImageGenPresets();
    const hit = presets.find((x) => String(x.id) === pid);
    if (hit) return String(hit.stylePrompt || "").trim().slice(0, 2000) || base;
  }
  return base;
}

function describeThreadImageStyleSuffixChoice(th, cfg, offline) {
  const presets = readImageGenPresets();
  const pid = offline
    ? String(th?.chatThreadOfflineImageStylePresetId || "").trim()
    : String(th?.chatThreadImageStylePresetId || "").trim();
  const custom = offline
    ? String(th?.chatThreadOfflineImageStylePromptCustom || "").trim()
    : String(th?.chatThreadImageStylePromptCustom || "").trim();
  if (!pid) {
    const g = String(cfg?.stylePrompt || "").trim();
    return g ? `跟随全局（约 ${g.length} 字）` : "跟随全局（未填后缀）";
  }
  if (pid === CHAT_THREAD_IMAGE_STYLE_PRESET_CUSTOM) {
    return custom ? `自定义（${custom.length} 字）` : "自定义（留空则跟全局）";
  }
  const hit = presets.find((x) => String(x.id) === pid);
  return hit ? `预设「${hit.name || "未命名"}」` : "跟随全局";
}

/** @param {unknown} thread */
/** @param {unknown} charItem */
function resolveCharArchiveImageGenPrompt(charItem) {
  if (!charItem || typeof charItem !== "object") return "";
  return normalizeCharImageGenPromptTagLine(String(charItem.charImageGenPrompt || "")).slice(0, 2000);
}

function resolveThreadCharImageGenPrompt(thread) {
  if (!thread || typeof thread !== "object") return "";
  const threadOnly = normalizeCharImageGenPromptTagLine(String(thread.chatThreadCharImagePrompt || "")).slice(
    0,
    2000
  );
  if (threadOnly) return threadOnly;
  const cid = thread.kind === "group" ? "" : String(thread.charId || "").trim();
  if (!cid) return "";
  return resolveCharArchiveImageGenPrompt(getCharPersonaItemById(cid));
}

/** 立绘参考：密谈覆盖优先，否则角色档案默认 */
function resolveThreadCharImageRefDataUrl(thread) {
  if (!thread || typeof thread !== "object") return "";
  const t = String(thread.chatImageRefDataUrl || "").trim();
  if (t) return t;
  const cid = thread.kind === "group" ? "" : String(thread.charId || "").trim();
  if (!cid) return "";
  const it = getCharPersonaItemById(cid);
  return it && typeof it.charImageRefDataUrl === "string" ? String(it.charImageRefDataUrl).trim() : "";
}

/** 视频通话立绘：内置情绪 + 可自定义情绪（charCallIllustCustomMoods / chatCallIllustCustomMoods） */
const CALL_ILLUST_MOODS = [
  { id: "neutral", label: "默认" },
  { id: "happy", label: "开心" },
  { id: "shy", label: "害羞" },
  { id: "sad", label: "难过" },
  { id: "angry", label: "生气" },
  { id: "surprised", label: "惊讶" },
  { id: "soft", label: "温柔" },
  { id: "cold", label: "冷淡" }
];
const CALL_ILLUST_BUILTIN_IDS = new Set(CALL_ILLUST_MOODS.map((m) => m.id));
const CALL_ILLUST_CUSTOM_MOOD_MAX = 20;

/** @param {string} id */
function isValidCallIllustMoodId(id) {
  const s = String(id || "").trim();
  if (!s || s.length > 48) return false;
  if (CALL_ILLUST_BUILTIN_IDS.has(s)) return true;
  return /^custom_[a-z0-9_]{2,40}$/.test(s);
}

/** @param {unknown} raw @returns {{ id: string, label: string }[]} */
function normalizeCallIllustCustomMoods(raw) {
  const out = [];
  const seen = new Set();
  const arr = Array.isArray(raw) ? raw : [];
  for (const x of arr) {
    if (!x || typeof x !== "object") continue;
    const id = String(x.id ?? "").trim();
    const label = String(x.label ?? x.name ?? "").trim().slice(0, 12);
    if (!id.startsWith("custom_") || !isValidCallIllustMoodId(id) || !label || seen.has(id)) continue;
    seen.add(id);
    out.push({ id, label });
    if (out.length >= CALL_ILLUST_CUSTOM_MOOD_MAX) break;
  }
  return out;
}

/** @param {unknown} thread @param {unknown} charItem */
function resolveEffectiveCallIllustCustomMoods(thread, charItem) {
  const charM = normalizeCallIllustCustomMoods(
    charItem && typeof charItem === "object" ? charItem.charCallIllustCustomMoods : null
  );
  const threadM = normalizeCallIllustCustomMoods(
    thread && typeof thread === "object" ? thread.chatCallIllustCustomMoods : null
  );
  const byId = new Map(charM.map((m) => [m.id, m]));
  for (const m of threadM) byId.set(m.id, m);
  return [...byId.values()];
}

/** @param {unknown} thread @param {unknown} charItem */
function getEffectiveCallIllustMoodSlots(thread, charItem) {
  return [...CALL_ILLUST_MOODS, ...resolveEffectiveCallIllustCustomMoods(thread, charItem)];
}

/** @param {string} label */
function newCallIllustCustomMoodId(label) {
  const slug = String(label || "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, "_")
    .replace(/[^a-z0-9_\u4e00-\u9fff]+/gi, "")
    .slice(0, 20);
  const tail =
    typeof crypto !== "undefined" && crypto.randomUUID
      ? crypto.randomUUID().replace(/-/g, "").slice(0, 8)
      : `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
  const mid = slug && /^[a-z]/.test(slug) ? slug : `m${tail}`;
  let id = `custom_${mid}`.slice(0, 48);
  if (!isValidCallIllustMoodId(id)) id = `custom_${tail}`;
  return id;
}

/** @param {unknown} raw @returns {Record<string, string>} */
function normalizeCallIllustsMap(raw) {
  const out = {};
  if (!raw || typeof raw !== "object") return out;
  for (const [k, v] of Object.entries(raw)) {
    const id = String(k).trim();
    if (!isValidCallIllustMoodId(id)) continue;
    const url = String(v ?? "").trim();
    if (url && url.length <= 3_500_000) out[id] = url;
  }
  return out;
}

/** @param {unknown} thread @param {unknown} charItem */
function resolveEffectiveCharCallIllusts(thread, charItem) {
  const charMap = normalizeCallIllustsMap(
    charItem && typeof charItem === "object" ? charItem.charCallIllusts : null
  );
  const threadMap = normalizeCallIllustsMap(
    thread && typeof thread === "object" ? thread.chatCallIllusts : null
  );
  return { ...charMap, ...threadMap };
}

/** @param {string} mood @param {string} state @param {string} [extra] @param {{ id: string, label: string }[]} [customMoods] */
function inferCallIllustMoodKey(mood, state, extra, customMoods) {
  const hay = `${String(mood || "")} ${String(state || "")} ${String(extra || "")}`.toLowerCase();
  const has = (...words) => words.some((w) => hay.includes(w));
  if (has("怒", "生气", "烦", "恼", "凶", "冷淡", "冷漠", "厌", "angry", "cold", "mad"))
    return has("冷淡", "冷漠", "冷", "疏离", "cold") ? "cold" : "angry";
  if (has("哭", "悲", "难过", "伤心", "失落", "丧", "sad")) return "sad";
  if (has("羞", "脸红", "窘", "embarrass", "shy", "blush")) return "shy";
  if (has("惊", "愣", "震惊", "surprise", "surprised")) return "surprised";
  if (has("笑", "开心", "高兴", "乐", "happy", "smile", "grin")) return "happy";
  if (has("温柔", "软", "暖", "柔和", "sweet", "soft")) return "soft";
  const customs = Array.isArray(customMoods) ? customMoods : [];
  for (const m of customs) {
    const lab = String(m.label || "").trim().toLowerCase();
    if (lab && hay.includes(lab)) return m.id;
  }
  return "neutral";
}

/** @param {unknown} thread @param {unknown} charItem @param {string} [moodKey] */
function resolveVideoCallIllustDataUrl(thread, charItem, moodKey) {
  const map = resolveEffectiveCharCallIllusts(thread, charItem);
  const key = String(moodKey || "neutral").trim() || "neutral";
  const pick = String(map[key] || map.neutral || "").trim();
  if (pick) return pick;
  for (const u of Object.values(map)) {
    const hit = String(u || "").trim();
    if (hit) return hit;
  }
  return "";
}

function inferCallIllustMoodKeyFromCallSession() {
  const th = readActiveThread();
  const charItem = th?.charId ? getCharPersonaItemById(th.charId) : null;
  const customs = resolveEffectiveCallIllustCustomMoods(th, charItem);
  const log = Array.isArray(chatCallSessionLog) ? chatCallSessionLog : [];
  for (let i = log.length - 1; i >= 0; i--) {
    const r = log[i];
    if (!r || r.role !== "assistant") continue;
    if (r.callIllustMood && isValidCallIllustMoodId(r.callIllustMood)) return String(r.callIllustMood);
    const mk = inferCallIllustMoodKey(r.hvMood, r.hvState, r.text, customs);
    if (mk !== "neutral" || r.hvMood || r.hvState) return mk;
  }
  return "neutral";
}

/** @param {"char" | "thread"} scope */
function readCallIllustScopeCharItem(scope) {
  if (scope === "thread") {
    const th = readActiveThread();
    return th?.charId ? getCharPersonaItemById(th.charId) : null;
  }
  const st = readCharPersonaStore();
  return st.items.find((x) => x.id === st.activeId) || null;
}

/** @param {Record<string, string>} map @param {Set<string>} allowedCustomIds */
function pruneCallIllustMapToKnownMoods(map, allowedCustomIds) {
  const out = {};
  for (const [k, v] of Object.entries(map)) {
    const id = String(k).trim();
    if (!isValidCallIllustMoodId(id)) continue;
    if (!CALL_ILLUST_BUILTIN_IDS.has(id) && !allowedCustomIds.has(id)) continue;
    const url = String(v ?? "").trim();
    if (url && url.length <= 3_500_000) out[id] = url;
  }
  return out;
}

/** @param {{ id: string, label: string }[]} moods @param {"char" | "thread"} scope */
function persistCallIllustCustomMoods(moods, scope) {
  const list = normalizeCallIllustCustomMoods(moods);
  const allowedCustom = new Set(list.map((m) => m.id));
  if (scope === "thread") {
    return patchActiveThread((th) => {
      if (list.length) th.chatCallIllustCustomMoods = list;
      else delete th.chatCallIllustCustomMoods;
      const pruned = pruneCallIllustMapToKnownMoods(normalizeCallIllustsMap(th.chatCallIllusts), allowedCustom);
      if (Object.keys(pruned).length) th.chatCallIllusts = pruned;
      else delete th.chatCallIllusts;
    });
  }
  const st = readCharPersonaStore();
  const idx = st.items.findIndex((x) => String(x?.id || "") === String(st.activeId || ""));
  if (idx < 0) return false;
  const next = { ...st.items[idx] };
  if (list.length) next.charCallIllustCustomMoods = list;
  else delete next.charCallIllustCustomMoods;
  const pruned = pruneCallIllustMapToKnownMoods(normalizeCallIllustsMap(next.charCallIllusts), allowedCustom);
  if (Object.keys(pruned).length) next.charCallIllusts = pruned;
  else delete next.charCallIllusts;
  st.items[idx] = next;
  writeCharPersonaStore(st);
  return true;
}

/** @param {string} label @param {"char" | "thread"} scope */
function addCallIllustCustomMood(label, scope) {
  const name = String(label || "").trim().slice(0, 12);
  if (!name) {
    showToast("请输入情绪名称");
    return false;
  }
  const charItem = readCallIllustScopeCharItem(scope);
  const th = scope === "thread" ? readActiveThread() : null;
  const cur =
    scope === "thread"
      ? normalizeCallIllustCustomMoods(th?.chatCallIllustCustomMoods)
      : normalizeCallIllustCustomMoods(charItem?.charCallIllustCustomMoods);
  const effective =
    scope === "thread" ? resolveEffectiveCallIllustCustomMoods(th, charItem) : cur;
  const customCount = scope === "char" ? cur.length : effective.length;
  if (customCount >= CALL_ILLUST_CUSTOM_MOOD_MAX) {
    showToast(`最多 ${CALL_ILLUST_CUSTOM_MOOD_MAX} 个自定义情绪`);
    return false;
  }
  if (effective.some((m) => m.label === name)) {
    showToast("该情绪名称已存在");
    return false;
  }
  if (CALL_ILLUST_MOODS.some((m) => m.label === name)) {
    showToast("与内置情绪重名，请换名称");
    return false;
  }
  let id = newCallIllustCustomMoodId(name);
  const ids = new Set(effective.map((m) => m.id));
  while (ids.has(id)) id = newCallIllustCustomMoodId(`${name}_${Date.now()}`);
  const next = scope === "thread" ? [...normalizeCallIllustCustomMoods(th?.chatCallIllustCustomMoods), { id, label: name }] : [...cur, { id, label: name }];
  return persistCallIllustCustomMoods(next, scope);
}

/** @param {string} moodId @param {"char" | "thread"} scope */
function removeCallIllustCustomMood(moodId, scope) {
  const id = String(moodId || "").trim();
  if (!id.startsWith("custom_")) return false;
  persistCallIllustSlot(id, "", scope);
  const charItem = readCallIllustScopeCharItem(scope);
  const th = scope === "thread" ? readActiveThread() : null;
  const cur =
    scope === "thread"
      ? normalizeCallIllustCustomMoods(th?.chatCallIllustCustomMoods)
      : normalizeCallIllustCustomMoods(charItem?.charCallIllustCustomMoods);
  const next = cur.filter((m) => m.id !== id);
  return persistCallIllustCustomMoods(next, scope);
}

/** @param {string} gridId @param {Record<string, string>} map @param {{ scope: "char" | "thread", charItem?: unknown }} opts */
function renderCallIllustGrid(gridId, map, opts) {
  const grid = document.getElementById(gridId);
  if (!grid) return;
  const scope = opts?.scope === "thread" ? "thread" : "char";
  const th = scope === "thread" ? readActiveThread() : null;
  let charItem = opts?.charItem ?? null;
  if (!charItem) charItem = readCallIllustScopeCharItem(scope);
  const moods =
    scope === "char"
      ? [...CALL_ILLUST_MOODS, ...normalizeCallIllustCustomMoods(charItem?.charCallIllustCustomMoods)]
      : getEffectiveCallIllustMoodSlots(th, charItem);
  const displayMap =
    scope === "thread" ? resolveEffectiveCharCallIllusts(th, charItem) : normalizeCallIllustsMap(map);
  const ownMap = normalizeCallIllustsMap(map);
  const threadCustomIds =
    scope === "thread"
      ? new Set(normalizeCallIllustCustomMoods(th?.chatCallIllustCustomMoods).map((x) => x.id))
      : null;
  grid.dataset.callIllustScope = scope;
  grid.innerHTML = "";
  for (const m of moods) {
    const url = String(displayMap[m.id] || "").trim();
    const hasOwn = !!String(ownMap[m.id] || "").trim();
    const isCustom = m.id.startsWith("custom_");
    const slot = document.createElement("div");
    slot.className = `call-illust-slot${isCustom ? " call-illust-slot--custom" : ""}`;
    slot.dataset.mood = m.id;
    const label = document.createElement("span");
    label.className = "call-illust-slot-label";
    label.textContent = m.label;
    const preview = document.createElement("div");
    preview.className = "call-illust-slot-preview";
    const img = document.createElement("img");
    img.className = "call-illust-slot-img";
    img.alt = `${m.label}立绘`;
    img.decoding = "async";
    const ph = document.createElement("span");
    ph.className = "call-illust-slot-ph";
    ph.textContent = scope === "thread" && url && !hasOwn ? "档案" : "未设";
    if (url) {
      img.src = url;
      img.hidden = false;
      ph.hidden = true;
      preview.classList.add("has-img");
    } else {
      img.hidden = true;
      ph.hidden = false;
      preview.classList.remove("has-img");
    }
    preview.append(img, ph);
    const actions = document.createElement("div");
    actions.className = "call-illust-slot-actions";
    const pickBtn = document.createElement("button");
    pickBtn.type = "button";
    pickBtn.className = "chip ghost chip-xs";
    pickBtn.dataset.action = "pick";
    pickBtn.textContent = "上传";
    const clearBtn = document.createElement("button");
    clearBtn.type = "button";
    clearBtn.className = "chip ghost chip-xs";
    clearBtn.dataset.action = "clear";
    clearBtn.textContent = "清除";
    clearBtn.hidden = !hasOwn;
    const fileInp = document.createElement("input");
    fileInp.type = "file";
    fileInp.accept = "image/*";
    fileInp.hidden = true;
    fileInp.className = "call-illust-file";
    actions.append(pickBtn, clearBtn);
    if (isCustom && (scope === "char" || threadCustomIds?.has(m.id))) {
      const delBtn = document.createElement("button");
      delBtn.type = "button";
      delBtn.className = "chip ghost chip-xs";
      delBtn.dataset.action = "delete-mood";
      delBtn.textContent = "删";
      delBtn.title = scope === "thread" ? "删除本密谈自定义情绪" : "删除该自定义情绪";
      actions.append(delBtn);
    }
    actions.append(fileInp);
    slot.append(label, preview, actions);
    grid.appendChild(slot);
  }
  const addWrap = document.createElement("div");
  addWrap.className = "call-illust-add-wrap";
  const addBtn = document.createElement("button");
  addBtn.type = "button";
  addBtn.className = "chip ghost chip-xs call-illust-add-btn";
  addBtn.dataset.action = "add-mood";
  addBtn.textContent = "+ 添加情绪";
  addWrap.appendChild(addBtn);
  grid.appendChild(addWrap);
}

/** @param {string} moodId @param {string} dataUrl @param {"char" | "thread"} scope */
function persistCallIllustSlot(moodId, dataUrl, scope) {
  const id = String(moodId || "").trim();
  if (!isValidCallIllustMoodId(id)) return false;
  const url = String(dataUrl || "").trim();
  if (scope === "thread") {
    return patchActiveThread((th) => {
      const map = normalizeCallIllustsMap(th.chatCallIllusts);
      if (url && url.length <= 3_500_000) map[id] = url;
      else delete map[id];
      th.chatCallIllusts = map;
    });
  }
  const st = readCharPersonaStore();
  const idx = st.items.findIndex((x) => String(x?.id || "") === String(st.activeId || ""));
  if (idx < 0) return false;
  const map = normalizeCallIllustsMap(st.items[idx].charCallIllusts);
  if (url && url.length <= 3_500_000) map[id] = url;
  else delete map[id];
  st.items[idx] = { ...st.items[idx], charCallIllusts: map };
  writeCharPersonaStore(st);
  return true;
}

function clearThreadCallIllustOverrides() {
  return patchActiveThread((th) => {
    delete th.chatCallIllusts;
    delete th.chatCallIllustCustomMoods;
  });
}

/** @param {string} raw @param {{ role: "assistant", text: string, at: number, translation?: string }} entry */
function enrichChatCallAssistantLogEntryFromRaw(entry, raw) {
  const p = parseChatAssistantPayload(String(raw || ""));
  if (!p.fromJson) return entry;
  entry.hvMood = String(p.hvMood || "").trim();
  entry.hvState = String(p.hvState || "").trim();
  const th = readActiveThread();
  const charItem = th?.charId ? getCharPersonaItemById(th.charId) : null;
  const customs = resolveEffectiveCallIllustCustomMoods(th, charItem);
  entry.callIllustMood = inferCallIllustMoodKey(entry.hvMood, entry.hvState, entry.text, customs);
  return entry;
}

/** @param {"char" | "thread"} scope */
function refreshCallIllustUiAfterChange(scope) {
  if (scope === "thread") {
    syncChatDetailCallIllustGrid(readActiveThread());
    if (isChatCallScreenOpen() && chatCallMode === "video") syncChatVideoCallChrome();
  } else {
    syncCharStudioCallIllustGrid();
  }
}

function bindCallIllustGridEvents(gridId) {
  const grid = document.getElementById(gridId);
  if (!grid || grid.dataset.callIllustBound === "1") return;
  grid.dataset.callIllustBound = "1";
  grid.addEventListener("click", (ev) => {
    const t = /** @type {HTMLElement} */ (ev.target);
    const btn = t.closest?.("button[data-action]");
    if (!btn || !grid.contains(btn)) return;
    const scope = grid.dataset.callIllustScope === "thread" ? "thread" : "char";
    const action = String(btn.dataset.action || "");
    if (action === "add-mood") {
      const label = window.prompt("情绪名称（如：委屈、得意、困倦）", "");
      if (label == null) return;
      if (!addCallIllustCustomMood(label, scope)) return;
      refreshCallIllustUiAfterChange(scope);
      showToast("已添加情绪，可上传立绘");
      return;
    }
    const slot = t.closest?.(".call-illust-slot");
    if (!slot || !grid.contains(slot)) return;
    const mood = String(slot.dataset.mood || "").trim();
    if (!mood) return;
    if (action === "pick") {
      const inp = slot.querySelector("input.call-illust-file");
      if (inp instanceof HTMLInputElement) inp.click();
      return;
    }
    if (action === "clear") {
      if (!persistCallIllustSlot(mood, "", scope)) {
        showToast("无法保存");
        return;
      }
      refreshCallIllustUiAfterChange(scope);
      showToast("已清除");
      return;
    }
    if (action === "delete-mood") {
      if (!window.confirm(`删除自定义情绪「${slot.querySelector(".call-illust-slot-label")?.textContent || mood}」？`)) return;
      if (!removeCallIllustCustomMood(mood, scope)) {
        showToast("无法保存");
        return;
      }
      refreshCallIllustUiAfterChange(scope);
      showToast("已删除情绪");
    }
  });
  grid.addEventListener("change", async (ev) => {
    const inp = /** @type {HTMLInputElement} */ (ev.target);
    if (!inp.classList.contains("call-illust-file")) return;
    const slot = inp.closest(".call-illust-slot");
    if (!slot || !grid.contains(slot)) return;
    const scope = grid.dataset.callIllustScope === "thread" ? "thread" : "char";
    const mood = String(slot.dataset.mood || "").trim();
    const f = inp.files?.[0];
    inp.value = "";
    if (!f || !mood) return;
    try {
      const data = await readImageFileAsChatEmbeddedDataUrl(f);
      if (!persistCallIllustSlot(mood, data, scope)) {
        showToast("无法保存");
        return;
      }
      refreshCallIllustUiAfterChange(scope);
      showToast("已上传");
    } catch (err) {
      showToast(err instanceof Error ? err.message : String(err));
    }
  });
}

function describeCallIllustPanelStatus(thread, charItem) {
  const merged = resolveEffectiveCharCallIllusts(thread, charItem);
  const n = Object.keys(merged).length;
  const threadOnly = normalizeCallIllustsMap(thread?.chatCallIllusts);
  const tn = Object.keys(threadOnly).length;
  const customN = resolveEffectiveCallIllustCustomMoods(thread, charItem).length;
  const customHint = customN ? ` · 含 ${customN} 个自定义` : "";
  if (!n) return "未上传通话立绘（视频通话将用角色头像）";
  if (tn > 0) return `本密谈已设 ${tn} 种情绪${n > tn ? `（共 ${n} 张可用）` : ""}${customHint}`;
  return `档案已设 ${n} 种情绪${customHint}`;
}

function syncCharStudioCallIllustGrid() {
  const st = readCharPersonaStore();
  const it = st.items.find((x) => x.id === st.activeId);
  const map = normalizeCallIllustsMap(it?.charCallIllusts);
  renderCallIllustGrid("char-call-illust-grid", map, { scope: "char" });
}

function syncChatDetailCallIllustGrid(th) {
  const charItem = th?.charId ? getCharPersonaItemById(th.charId) : null;
  const threadMap = normalizeCallIllustsMap(th?.chatCallIllusts);
  renderCallIllustGrid("chat-detail-call-illust-grid", threadMap, { scope: "thread" });
  const st = document.getElementById("chat-detail-call-illust-status");
  if (st) st.textContent = describeCallIllustPanelStatus(th, charItem);
}

/** @param {unknown} charItem */
function applyCharImageGenDefaultsToNewThread(thread, charItem) {
  if (!thread || typeof thread !== "object" || !charItem) return;
  const prompt = resolveCharArchiveImageGenPrompt(charItem);
  const ref = String(charItem.charImageRefDataUrl || "").trim();
  if (prompt) thread.chatThreadCharImagePrompt = prompt;
  if (ref && ref.length <= 3_500_000) thread.chatImageRefDataUrl = ref;
  const callIllusts = normalizeCallIllustsMap(charItem.charCallIllusts);
  if (Object.keys(callIllusts).length) thread.chatCallIllusts = { ...callIllusts };
  const callMoods = normalizeCallIllustCustomMoods(charItem.charCallIllustCustomMoods);
  if (callMoods.length) thread.chatCallIllustCustomMoods = callMoods.map((m) => ({ ...m }));
}

/** @param {unknown} th */
function describeThreadCharImageGenPromptChoice(th) {
  const threadOnly =
    th && typeof th === "object" ? String(th.chatThreadCharImagePrompt || "").trim() : "";
  const s = resolveThreadCharImageGenPrompt(th);
  if (!s) return "未设置（从人设摘要/tags 推断）";
  if (threadOnly) return `本密谈已设（${threadOnly.length} 字）`;
  return `档案默认（${s.length} 字）`;
}

/** @param {string} raw */
function normalizeCharImageGenPromptTagLine(raw) {
  return String(raw || "")
    .replace(/\s*·\s*/g, ", ")
    .replace(/\s*;\s*/g, ", ")
    .replace(/\s+/g, " ")
    .replace(/,\s*,/g, ",")
    .replace(/^,\s*|\s*,$/g, "")
    .trim();
}

/**
 * 本密谈自定义角色外貌 tag；无则回退自动从人设推断。
 * @param {ReturnType<typeof readActiveThread>} thread
 * @param {ReturnType<typeof resolveImageGenPlan>} plan
 * @param {boolean} omitChar
 * @param {{ offline?: boolean }} [opts]
 */
function resolveCharImageGenAppearanceForPrompt(thread, plan, omitChar, opts) {
  if (omitChar || (!plan.includeCharStrong && !plan.includeCharWeak)) return "";
  const offline = Boolean(opts && opts.offline);
  const mo = opts && typeof opts === "object" ? opts.msg : undefined;
  const ch = readThreadBoundCharPersonaForImageGen(thread, mo);
  const fanLead = ch ? resolveCharFanworkImageGenTags(ch) : "";
  const mergeFanLead = (body) => {
    const b = String(body || "").trim();
    if (!fanLead) return b;
    if (!b) return fanLead;
    return mergeImageGenCommaTags(fanLead, b);
  };
  let custom = normalizeCharImageGenPromptTagLine(resolveThreadCharImageGenPrompt(thread));
  if (!custom && ch) {
    custom = deriveCharImageGenPromptFromPersonaBody(ch);
  }
  if (custom) {
    let tg = mergeFanLead(custom);
    const g = inferCharPersonaGenderForImageGen(ch);
    if (g === "female" && !/\b1girl\b/i.test(tg)) tg = `1girl, ${tg}`;
    else if (g === "male" && !/\b1boy\b/i.test(tg)) tg = `1boy, ${tg}`;
    const totalMax = offline ? OFFLINE_IMAGE_GEN_CHAR_TAGS_TOTAL_MAX : 400;
    return tg.slice(0, totalMax);
  }
  return mergeFanLead(novelAiCharacterAppearanceTagsFromPersona(thread, plan, omitChar, opts));
}

/**
 * 从角色人设规则推导生图外貌 tag（离线兜底；档案内推荐用 API 生成）。
 * @param {ReturnType<typeof emptyCharPersona>} body
 */
function deriveCharImageGenPromptFromPersonaBody(body) {
  if (!body || typeof body !== "object") return "";
  const ch = { ...emptyCharPersona(), ...pickCharPersonaBody(body) };
  const fan = resolveCharFanworkImageGenTags(ch);
  const auto = collectCharImageGenAppearanceTagsFromPersona(ch, { tagMax: 400, zhKwMax: 22 });
  let tags = mergeImageGenCommaTags(fan, auto);
  const g = inferCharPersonaGenderForImageGen(ch);
  if (g === "female" && !/\b1girl\b/i.test(tags)) tags = mergeImageGenCommaTags("1girl", tags);
  else if (g === "male" && !/\b1boy\b/i.test(tags)) tags = mergeImageGenCommaTags("1boy", tags);
  return normalizeCharImageGenPromptTagLine(tags).slice(0, 2000);
}

/** @param {ReturnType<typeof emptyCharPersona>} body */
function charPersonaHasImageGenGenSource(body) {
  const p = { ...emptyCharPersona(), ...pickCharPersonaBody(body) };
  if (
    [p.summary, p.tags, p.aliases, p.voice, p.boundaries, p.npcRelations].some((x) =>
      String(x || "").trim()
    )
  ) {
    return true;
  }
  return (
    normalizeWorldBookVolumeIdsArray(p.worldBookVolumeIds, p.defaultWorldBookVolumeId).length > 0
  );
}

/** @param {string} raw */
function parseCharImageGenTagsFromModelRaw(raw) {
  let s = String(raw || "").trim();
  s = s.replace(/^```[\w-]*\s*/i, "").replace(/\s*```$/i, "").trim();
  const loose =
    extractJsonStringFieldLoose(s, "tags") ||
    extractJsonStringFieldLoose(s, "appearanceTags") ||
    extractJsonStringFieldLoose(s, "charImageGenPrompt") ||
    extractJsonStringFieldLoose(s, "userImageGenPrompt");
  const tagSrc = loose != null ? String(loose).trim() : s;
  return normalizeCharImageGenPromptTagLine(tagSrc).slice(0, 2000);
}

/**
 * @param {ReturnType<typeof emptyCharPersona>} body
 */
function buildCharImageGenAppearanceTagsGenUserBlock(body) {
  const p = { ...emptyCharPersona(), ...pickCharPersonaBody(body) };
  const name = String(p.displayName || "").trim() || "未命名角色";
  const fan = String(p.charFanworkTags || "").trim();
  const wbIds = normalizeWorldBookVolumeIdsArray(
    p.worldBookVolumeIds,
    p.defaultWorldBookVolumeId
  );
  const wb = buildWorldBookBlockForVolumeIds(wbIds, name, "对方");
  const bits = [`角色名：${name}`];
  if (fan) bits.push(`同人 tag（已单独填写，外貌 tag 勿重复）：${fan.slice(0, 420)}`);
  const pushField = (label, val, max) => {
    const t = String(val || "").trim();
    if (t) bits.push(`${label}：\n${t.slice(0, max)}`);
  };
  pushField("摘要", p.summary, 2400);
  pushField("标签", p.tags, 600);
  pushField("别名", p.aliases, 300);
  pushField("声线/说话方式", p.voice, 900);
  pushField("边界", p.boundaries, 600);
  pushField("NPC 关系", p.npcRelations, 600);
  if (wb) bits.push(wb.slice(0, 6000));
  return bits.join("\n\n");
}

/**
 * 调用聊天 API，从角色人设 + 绑定世界书生成英文外貌 danbooru tag。
 * @param {ReturnType<typeof emptyCharPersona>} body
 * @returns {Promise<string>}
 */
async function generateCharImageGenPromptFromPersonaViaApi(body) {
  const ai = window.RP_AI;
  if (!ai?.chatCompletions) throw new Error("AI 模块未加载");
  const key = String(ai.getConfig()?.apiKey || "").trim();
  if (!key) throw new Error("请先在「我的 → 连接 API」填写 API Key");
  if (!charPersonaHasImageGenGenSource(body)) {
    throw new Error("请先填写人设摘要/标签，或绑定世界书");
  }
  const userBlock = buildCharImageGenAppearanceTagsGenUserBlock(body);
  const system = [
    "你是角色立绘/生图 prompt 助手，为 NovelAI / danbooru 风格接口输出**固定外貌**英文 tag。",
    "根据用户提供的人设与世界书，只提取**长期稳定的外貌特征**：性别（必须 1girl 或 1boy 开头）、发型发色、瞳色、肤色、体型、常服/标志穿着、配饰、显著五官特征。",
    "**不要**写：当下姿势、表情、场景、光线、镜头、道具互动、性格口癖、对白风格、剧情动作。",
    "若用户已填写「同人 tag」，**不要**在外貌 tag 里重复角色名/作品名；若明显是同人角色且未填同人 tag，可把英文角色名与作品名写入 tags。",
    "只输出一个 JSON 对象：{ \"tags\": \"英文逗号分隔 tag，无换行无解释\" }。"
  ].join("\n");
  const data = await ai.chatCompletions({
    messages: [
      { role: "system", content: system },
      { role: "user", content: userBlock }
    ],
    max_tokens: 720,
    temperature: 0.35,
    response_format: { type: "json_object" }
  });
  rememberChatApiUsage(data?.usage);
  const raw = readChatCompletionChoiceText(data);
  const tags = parseCharImageGenTagsFromModelRaw(raw);
  if (!tags) throw new Error(explainModelEmptyReply(data, raw));
  return tags;
}

let charImageGenPromptApiInFlight = false;
let userImageGenPromptApiInFlight = false;

/** @param {ReturnType<typeof emptyUserMask>} body */
function userMaskTextBlobForImageGen(body) {
  const u = { ...emptyUserMask(), ...pickUserMaskBody(body) };
  return [u.persona, u.summary, u.voice, u.boundaries]
    .map((x) => String(x || "").trim())
    .filter(Boolean)
    .join("\n");
}

/** @param {ReturnType<typeof emptyUserMask>} body */
function userMaskHasImageGenGenSource(body) {
  const u = { ...emptyUserMask(), ...pickUserMaskBody(body) };
  return [u.persona, u.summary, u.voice, u.boundaries].some((x) => String(x || "").trim());
}

/**
 * @param {ReturnType<typeof emptyUserMask>} u
 * @param {{ tagMax?: number, zhKwMax?: number }} [opts]
 */
function collectUserImageGenAppearanceTagsFromPersona(u, opts) {
  const o = opts && typeof opts === "object" ? opts : {};
  const tagMax = Number(o.tagMax) > 0 ? Number(o.tagMax) : 220;
  const zhKwMax = Number(o.zhKwMax) > 0 ? Number(o.zhKwMax) : 18;
  const blob = userMaskTextBlobForImageGen(u);
  const tg = mergeImageGenCommaTags(
    extractEmbeddedEnglishImageTagsFromText(blob),
    zhKwMax > 0 ? extractCharAppearanceKeywordsFromChinesePersona(blob, zhKwMax) : ""
  );
  return tg.replace(/\s*·\s*/g, ", ").replace(/\s+/g, " ").trim().slice(0, tagMax);
}

/** @param {ReturnType<typeof emptyUserMask>} body */
function deriveUserImageGenPromptFromPersonaBody(body) {
  if (!body || typeof body !== "object") return "";
  const u = { ...emptyUserMask(), ...pickUserMaskBody(body) };
  let tags = collectUserImageGenAppearanceTagsFromPersona(u, { tagMax: 400, zhKwMax: 22 });
  const g = inferUserMaskGenderForImageGen(u);
  if (g === "female" && !/\b1girl\b/i.test(tags)) tags = mergeImageGenCommaTags("1girl", tags);
  else if (g === "male" && !/\b1boy\b/i.test(tags)) tags = mergeImageGenCommaTags("1boy", tags);
  return normalizeCharImageGenPromptTagLine(tags).slice(0, 2000);
}

/**
 * @param {ReturnType<typeof readUserMask>} [u]
 * @param {ReturnType<typeof resolveImageGenPlan>} plan
 * @param {{ offline?: boolean }} [opts]
 */
function resolveUserImageGenAppearanceForPrompt(u, plan, opts) {
  if (!plan || !plan.includeUser) return "";
  const offline = Boolean(opts && opts.offline);
  const mask = { ...emptyUserMask(), ...pickUserMaskBody(u && typeof u === "object" ? u : readUserMask()) };
  let custom = normalizeCharImageGenPromptTagLine(String(mask.userImageGenPrompt || ""));
  if (!custom) custom = deriveUserImageGenPromptFromPersonaBody(mask);
  if (!custom) return "";
  let tg = custom;
  const g = inferUserMaskGenderForImageGen(mask);
  if (g === "female" && !/\b1girl\b/i.test(tg)) tg = `1girl, ${tg}`;
  else if (g === "male" && !/\b1boy\b/i.test(tg)) tg = `1boy, ${tg}`;
  if (plan.subject === "both") {
    tg = tg
      .replace(/\bsolo\b,?\s*/gi, "")
      .replace(/,\s*,/g, ",")
      .trim();
  } else if (plan.subject === "user" && !/\bsolo\b/i.test(tg)) {
    tg = `solo, ${tg}`;
  }
  const totalMax = offline ? OFFLINE_IMAGE_GEN_CHAR_TAGS_TOTAL_MAX : 400;
  return normalizeCharImageGenPromptTagLine(tg).slice(0, totalMax);
}

/** @param {ReturnType<typeof emptyUserMask>} body */
function buildUserImageGenAppearanceTagsGenUserBlock(body) {
  const u = { ...emptyUserMask(), ...pickUserMaskBody(body) };
  const name = String(u.displayName || "").trim() || "主控";
  const bits = [`主控面具：${name}`];
  const pushField = (label, val, max) => {
    const t = String(val || "").trim();
    if (t) bits.push(`${label}：\n${t.slice(0, max)}`);
  };
  pushField("人设", u.persona, 2400);
  pushField("概要", u.summary, 600);
  pushField("说话方式", u.voice, 900);
  pushField("边界", u.boundaries, 600);
  return bits.join("\n\n");
}

/**
 * @param {ReturnType<typeof emptyUserMask>} body
 * @returns {Promise<string>}
 */
async function generateUserImageGenPromptFromPersonaViaApi(body) {
  const ai = window.RP_AI;
  if (!ai?.chatCompletions) throw new Error("AI 模块未加载");
  const key = String(ai.getConfig()?.apiKey || "").trim();
  if (!key) throw new Error("请先在「我的 → 连接 API」填写 API Key");
  if (!userMaskHasImageGenGenSource(body)) {
    throw new Error("请先填写主控人设或概要");
  }
  const userBlock = buildUserImageGenAppearanceTagsGenUserBlock(body);
  const system = [
    "你是主控/用户立绘生图 prompt 助手，为 NovelAI / danbooru 风格接口输出**固定外貌**英文 tag。",
    "根据用户提供的主控面具人设，只提取**长期稳定的外貌特征**：性别（必须 1girl 或 1boy 开头）、发型发色、瞳色、肤色、体型、常服/标志穿着、配饰、显著五官特征。",
    "**不要**写：当下姿势、表情、场景、光线、镜头、性格口癖、对白风格、剧情动作、关系描述。",
    "只输出一个 JSON 对象：{ \"tags\": \"英文逗号分隔 tag，无换行无解释\" }。"
  ].join("\n");
  const data = await ai.chatCompletions({
    messages: [
      { role: "system", content: system },
      { role: "user", content: userBlock }
    ],
    max_tokens: 720,
    temperature: 0.35,
    response_format: { type: "json_object" }
  });
  rememberChatApiUsage(data?.usage);
  const raw = readChatCompletionChoiceText(data);
  const tags = parseCharImageGenTagsFromModelRaw(raw);
  if (!tags) throw new Error(explainModelEmptyReply(data, raw));
  return tags;
}

async function runUserMaskImageGenPromptGenerate() {
  if (userImageGenPromptApiInFlight) return;
  const ta = document.getElementById("user-mask-image-gen-prompt");
  if (!(ta instanceof HTMLTextAreaElement)) return;
  const body = collectUserMaskFromForm();
  if (!userMaskHasImageGenGenSource(body)) {
    showToast("请先填写主控人设或概要");
    return;
  }
  const btn = document.getElementById("user-mask-image-gen-prompt-generate");
  userImageGenPromptApiInFlight = true;
  if (btn instanceof HTMLButtonElement) {
    btn.disabled = true;
    btn.textContent = "生成中…";
  }
  showToast("正在从主控人设生成外貌 tag…");
  try {
    const out = await generateUserImageGenPromptFromPersonaViaApi(body);
    ta.value = out;
    if (charScreen?.classList.contains("is-open")) setUserPaneDirty(true);
    showToast("已生成外貌 tag，确认后点「保存面具」");
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    showToast(`生成失败：${msg.slice(0, 160)}`);
  } finally {
    userImageGenPromptApiInFlight = false;
    if (btn instanceof HTMLButtonElement) {
      btn.disabled = false;
      btn.textContent = "从人设生成 tag";
    }
  }
}

