/**
 * 供聊天 JSON 生图字段参考：优先读已保存的 charImageGenPrompt。
 * @param {ReturnType<typeof readActiveThread>} thread
 */
function buildCharAppearanceGuideForImageGenCaption(thread) {
  if (!thread || thread.kind === "group") return "";
  const ch = readThreadBoundCharPersonaForImageGen(thread);
  if (!ch) return "";
  const fixed = Boolean(String(resolveThreadCharImageGenPrompt(thread) || "").trim());
  const cached = resolveThreadCharImageGenPrompt(thread);
  const derived = deriveCharImageGenPromptFromPersonaBody(ch);
  const bits = [];
  const nm = String(ch.displayName || "").trim();
  if (nm) bits.push(`角色：${nm.slice(0, 40)}`);
  if (fixed) {
    bits.push(`固定外貌 tag（程序自动拼在每条图最前，caption 勿整段复述）：${cached.slice(0, 420)}`);
  } else if (derived) {
    bits.push(`推断外貌参考（未保存固定 tag，caption 宜含外貌）：${derived.slice(0, 420)}`);
  } else {
    const sum = sliceForImageGenPrompt(ch.summary, 240);
    if (sum) bits.push(`摘要参考（可在角色档案点「从人设生成 tag」或手填后保存）：${sum}`);
  }
  return bits.join("\n");
}

/** @returns {string[]} */
function buildCharImageGenPromptPersonaGuideLines(thread) {
  const guide = buildCharAppearanceGuideForImageGenCaption(thread);
  if (!guide) return [];
  return [
    `[生图 · 外貌 + 场面（程序前缀 + caption 双保险）]`,
    `本机会把档案里的**固定外貌 tag 自动拼在 prompt 最前**作锚点；但生图模型对**本条 caption 也很敏感**，只写空景/光线时容易画错人。`,
    guide,
    `写 **charImage.caption** / **imageSceneCaption** / **innerState** 英文时：**须含当下可见外貌**（1girl/1boy、表情、姿势、这一刻穿搭/发型可见部分、景别）+ **场面**（地点、光线、道具）；**勿整段复述**档案固定 tag 全文，可按本条镜头改写。`,
    `subject=both：caption 须让**两人都在画里**（可用 2people / couple 等）并分别点到外貌与互动；主控外貌见当前面具设定。`,
    `subject=object|scene 且确实无人物：caption 只写可见物与场景。`
  ];
}

