/** @param {{ openaiQuality?: string, openaiInputFidelity?: string }} p */
function fillImageGenOpenAiQualityFieldsFromPreset(p) {
  const oaiQ = document.getElementById("image-gen-openai-quality");
  if (oaiQ instanceof HTMLSelectElement) {
    const qv = normalizeOpenAiImageQuality(p.openaiQuality);
    if ([...oaiQ.options].some((o) => o.value === qv)) oaiQ.value = qv;
  }
  const oaiF = document.getElementById("image-gen-openai-fidelity");
  if (oaiF instanceof HTMLSelectElement) {
    oaiF.value = normalizeOpenAiInputFidelity(p.openaiInputFidelity);
  }
}

function ensureSelectHasOption(sel, value, label) {
  if (!(sel instanceof HTMLSelectElement)) return;
  const v = String(value || "").trim();
  if (!v) return;
  const exists = [...sel.querySelectorAll("option")].some((o) => o.value === v);
  if (!exists) {
    const opt = document.createElement("option");
    opt.value = v;
    opt.textContent = label || v;
    sel.appendChild(opt);
  }
  sel.value = v;
}

function applyImageGenPresetToForm(preset) {
  const p = normalizeImageGenPreset(preset);
  if (p.includeCredentials === false) {
    const style = document.getElementById("image-gen-style");
    const neg = document.getElementById("image-gen-negative");
    if (style instanceof HTMLTextAreaElement) style.value = p.stylePrompt || "";
    if (neg instanceof HTMLTextAreaElement) neg.value = p.negativePrompt || "";
    fillImageGenOpenAiQualityFieldsFromPreset(p);
    refreshImageGenProviderUi();
    return;
  }
  const prov = document.getElementById("image-gen-provider");
  if (prov instanceof HTMLSelectElement) prov.value = p.provider;
  const base = document.getElementById("image-gen-base");
  if (base instanceof HTMLInputElement) {
    if (p.provider === "custom") base.value = p.baseUrl || "https://api.openai.com/v1";
    else if (p.provider === "novelai") base.value = p.baseUrl || "";
    else base.value = p.baseUrl || "";
  }
  const keyInp = document.getElementById("image-gen-key");
  if (keyInp instanceof HTMLInputElement) {
    keyInp.value = p.apiKey || "";
  }
  const style = document.getElementById("image-gen-style");
  if (style instanceof HTMLTextAreaElement) style.value = p.stylePrompt || "";
  const neg = document.getElementById("image-gen-negative");
  if (neg instanceof HTMLTextAreaElement) neg.value = p.negativePrompt || "";
  const naiSamp = document.getElementById("image-gen-nai-sampler");
  if (naiSamp instanceof HTMLSelectElement) naiSamp.value = p.naiSampler || "k_euler";
  const naiSteps = document.getElementById("image-gen-nai-steps");
  if (naiSteps instanceof HTMLInputElement) naiSteps.value = String(p.naiSteps ?? 28);
  const naiCfg = document.getElementById("image-gen-nai-cfg");
  if (naiCfg instanceof HTMLInputElement) naiCfg.value = String(p.naiCfgScale ?? 5);
  const naiSeed = document.getElementById("image-gen-nai-seed");
  if (naiSeed instanceof HTMLInputElement) {
    naiSeed.value = Number(p.naiSeed) >= 0 ? String(p.naiSeed) : "";
  }
  const naiSmea = document.getElementById("image-gen-nai-smea");
  if (naiSmea instanceof HTMLInputElement) {
    naiSmea.checked = isNovelAiV4ModelId(p.model) ? false : Boolean(p.naiSmea);
  }
  refreshImageGenProviderUi();
  const modelSel = document.getElementById("image-gen-model");
  const modelCustom = document.getElementById("image-gen-model-custom");
  if (p.provider === "custom") {
    if (modelCustom instanceof HTMLInputElement) modelCustom.value = p.model;
    if (modelSel instanceof HTMLSelectElement && !modelSel.hidden) {
      ensureSelectHasOption(modelSel, p.model, p.model);
      if (modelCustom instanceof HTMLInputElement) modelCustom.value = String(modelSel.value || p.model);
    }
  } else if (modelSel instanceof HTMLSelectElement) {
    ensureSelectHasOption(modelSel, p.model, p.model);
  }
  const sizeSel = document.getElementById("image-gen-size");
  ensureSelectHasOption(sizeSel, p.size, p.size);
  fillImageGenOpenAiQualityFieldsFromPreset(p);
  syncImageGenNaiLabelsAndSmea();
}

function renderImageGenPresetList() {
  const sel = document.getElementById("image-gen-preset-select");
  const list = document.getElementById("image-gen-preset-list");
  const presets = readImageGenPresets();
  if (sel instanceof HTMLSelectElement) {
    const prev = sel.value;
    sel.replaceChildren();
    const o0 = document.createElement("option");
    o0.value = "";
    o0.textContent = "载入预设…";
    sel.appendChild(o0);
    for (const p of presets) {
      const o = document.createElement("option");
      o.value = p.id;
      o.textContent = p.name;
      sel.appendChild(o);
    }
    sel.value = presets.some((x) => x.id === prev) ? prev : "";
  }
  if (list) {
    list.replaceChildren();
    if (!presets.length) {
      const em = document.createElement("p");
      em.className = "settings-ai-key-note imgen-preset-empty";
      em.textContent = "暂无预设";
      list.appendChild(em);
    } else {
      for (const p of presets) {
        const row = document.createElement("div");
        row.className = "imgen-preset-row";
        const name = document.createElement("span");
        name.className = "imgen-preset-name";
        name.appendChild(document.createTextNode(p.name));
        if (!p.includeCredentials) {
          const tag = document.createElement("span");
          tag.className = "imgen-preset-scope-tag";
          tag.textContent = " · 仅提示词";
          name.appendChild(tag);
        }
        const del = document.createElement("button");
        del.type = "button";
        del.className = "chip ghost chip-xs";
        del.setAttribute("data-imgen-preset-del", p.id);
        del.setAttribute("aria-label", `删除预设 ${p.name}`);
        del.textContent = "删除";
        row.appendChild(name);
        row.appendChild(del);
        list.appendChild(row);
      }
    }
  }
  try {
    syncChatThreadDetailPanelPlaceholders();
    if (isChatDetailImageStyleSheetOpen()) fillChatDetailImageStyleSheetForm();
  } catch {
    /* ignore */
  }
}

function refreshImageGenSizeSelect() {
  const sel = document.getElementById("image-gen-size");
  if (!(sel instanceof HTMLSelectElement)) return;
  const provEl = document.getElementById("image-gen-provider");
  const raw = provEl instanceof HTMLSelectElement ? String(provEl.value || "openai").trim().toLowerCase() : "openai";
  const provider = normalizeImageGenProvider(raw);
  const opts = getImageGenSizeOptionsForProvider(provider);
  const prev = String(sel.value || "");
  const cfg = readImageGenConfig();
  sel.replaceChildren();
  for (const o of opts) {
    const el = document.createElement("option");
    el.value = o.value;
    el.textContent = o.label;
    sel.appendChild(el);
  }
  const vals = opts.map((x) => x.value);
  const fallback =
    provider === "novelai"
      ? vals.includes("832x1216")
        ? "832x1216"
        : vals[0] || "832x1216"
      : vals.includes("1024x1024")
        ? "1024x1024"
        : vals[0] || "1024x1024";
  const want = vals.includes(prev) ? prev : vals.includes(cfg.size) ? cfg.size : fallback;
  sel.value = vals.includes(want) ? want : fallback;
}

function syncImageGenNaiLabelsAndSmea() {
  const steps = document.getElementById("image-gen-nai-steps");
  const stepsLab = document.getElementById("image-gen-nai-steps-val");
  const cfgR = document.getElementById("image-gen-nai-cfg");
  const cfgLab = document.getElementById("image-gen-nai-cfg-val");
  if (steps instanceof HTMLInputElement && stepsLab) stepsLab.textContent = String(steps.value);
  if (cfgR instanceof HTMLInputElement && cfgLab) cfgLab.textContent = Number(cfgR.value).toFixed(1);
  const smea = document.getElementById("image-gen-nai-smea");
  const prov = document.getElementById("image-gen-provider");
  const modEl = document.getElementById("image-gen-model");
  if (!(smea instanceof HTMLInputElement)) return;
  const isNai = prov instanceof HTMLSelectElement && prov.value === "novelai";
  const model = modEl instanceof HTMLSelectElement ? String(modEl.value || "") : "";
  const v4 = isNovelAiV4ModelId(model);
  smea.disabled = !isNai || v4;
  if (v4) smea.checked = false;
}

function refreshImageGenProviderUi() {
  const provEl = document.getElementById("image-gen-provider");
  const baseWrap = document.getElementById("image-gen-base-wrap");
  const baseInp = document.getElementById("image-gen-base");
  const baseLab = document.getElementById("image-gen-base-label");
  const baseNote = document.getElementById("image-gen-base-note");
  const modelSel = document.getElementById("image-gen-model");
  const modelCustom = document.getElementById("image-gen-model-custom");
  const keyInp = document.getElementById("image-gen-key");
  const keyLab = document.getElementById("image-gen-key-label");
  const raw = provEl instanceof HTMLSelectElement ? String(provEl.value || "openai").trim() : "openai";
  const provider = normalizeImageGenProvider(raw);
  const isCustom = provider === "custom";
  const isNovelai = provider === "novelai";
  if (baseWrap) baseWrap.hidden = !isCustom && !isNovelai;
  if (baseLab) {
    baseLab.textContent = isNovelai ? "CORS 代理（可选）" : "API Base";
  }
  if (baseInp instanceof HTMLInputElement) {
    baseInp.placeholder = isNovelai
      ? "https://your-proxy.example.com"
      : "https://api.openai.com/v1";
  }
  if (baseNote) {
    baseNote.hidden = false;
    if (isCustom) {
      baseNote.textContent =
        "填写与 OpenAI SDK 兼容的 Base（含 /v1 或不含均可）。中转站 Gemini/Flux 等生图模型也选此项，填 Base + 模型 id。";
    } else if (isNovelai) {
      baseNote.textContent =
        "与小心机一致：只需填好上方 API Key；此处留空则直连 image.novelai.net。若浏览器报 Failed to fetch / CORS，再填反代根地址（将请求「地址/ai/generate-image」）。";
    } else {
      baseNote.textContent = "使用官方 OpenAI 接口，无需填写 Base；请求将发往 api.openai.com。";
    }
  }
  const showModelSelectForCustom = isCustom && cachedImageGenFetchedIds.length > 0;
  if (modelSel instanceof HTMLSelectElement) {
    modelSel.hidden = isCustom && !showModelSelectForCustom;
  }
  const modelTools = document.getElementById("image-gen-model-tools");
  if (modelTools) modelTools.hidden = isNovelai;
  if (modelCustom instanceof HTMLInputElement) {
    modelCustom.hidden = !isCustom;
    if (isCustom && !String(modelCustom.value || "").trim() && modelSel instanceof HTMLSelectElement) {
      modelCustom.placeholder = `当前：${String(modelSel.value || IMAGE_GEN_DEFAULT_OPENAI_MODEL)}`;
    }
  }
  if (keyLab) {
    keyLab.textContent = isNovelai ? "API Key（NovelAI）" : isCustom ? "API Key（中转）" : "API Key";
  }
  if (keyInp instanceof HTMLInputElement) {
    keyInp.placeholder = isNovelai
      ? "pst-… 或 Access Token；留空沿用已保存"
      : isCustom
        ? "中转 Key；留空沿用已保存"
        : "仅本机保存；留空表示沿用已保存的 Key";
  }
  const naiWrap = document.getElementById("image-gen-nai-wrap");
  if (naiWrap) naiWrap.hidden = !isNovelai;
  const openaiWrap = document.getElementById("image-gen-openai-wrap");
  if (openaiWrap) openaiWrap.hidden = isNovelai;
  const fidField = document.getElementById("image-gen-openai-fidelity-field");
  const modEl2 = document.getElementById("image-gen-model");
  const modelNow =
    modEl2 instanceof HTMLSelectElement && !modEl2.hidden
      ? String(modEl2.value || "")
      : document.getElementById("image-gen-model-custom") instanceof HTMLInputElement
        ? String(document.getElementById("image-gen-model-custom").value || "")
        : "";
  if (fidField) {
    fidField.hidden = isNovelai || !openAiImageEditsSupportsInputFidelity(modelNow);
  }
  const provK = document.getElementById("image-gen-provider-k");
  if (provK) {
    provK.textContent = isNovelai
      ? "下方为 NovelAI 参数"
      : isCustom
        ? "下方为 OpenAI 兼容参数（quality 等，视模型支持）"
        : "下方为 OpenAI 参数";
  }
  const negLab = document.getElementById("image-gen-negative-label");
  const negTa = document.getElementById("image-gen-negative");
  if (negLab) {
    negLab.textContent = isNovelai ? "反向提示词 · Undesired Content" : "反向提示词（OpenAI 可选）";
  }
  if (negTa instanceof HTMLTextAreaElement) {
    negTa.placeholder = isNovelai ? "NovelAI UC…" : "可选";
  }
  rebuildImageGenModelSelect();
  refreshImageGenSizeSelect();
  syncImageGenNaiLabelsAndSmea();
}

function fillImageGenFormFromConfig() {
  const D = window.XXJ_DB;
  const rawKv = D?.getKv?.(D.K.IMAGE_GEN_CONFIG);
  if (rawKv && rawKv.v === 1 && String(rawKv.provider || "").trim().toLowerCase() === "gemini") {
    writeImageGenConfig(normalizeImageGenConfig(rawKv));
    showToast("Gemini 生图已移除；原中转配置已转为「OpenAI 兼容」", 4500);
  }
  const cfg = readImageGenConfig();
  resetImageGenTestPanel();
  const en = document.getElementById("image-gen-enabled");
  const prov = document.getElementById("image-gen-provider");
  const base = document.getElementById("image-gen-base");
  const key = document.getElementById("image-gen-key");
  const modelCustom = document.getElementById("image-gen-model-custom");
  const size = document.getElementById("image-gen-size");
  const style = document.getElementById("image-gen-style");
  const neg = document.getElementById("image-gen-negative");
  if (en instanceof HTMLInputElement) en.checked = !!cfg.enabled;
  if (prov instanceof HTMLSelectElement) prov.value = cfg.provider;
  if (base instanceof HTMLInputElement) {
    if (cfg.provider === "custom") base.value = cfg.baseUrl || "https://api.openai.com/v1";
    else if (cfg.provider === "novelai") base.value = cfg.baseUrl || "";
    else base.value = cfg.baseUrl || "";
  }
  if (key instanceof HTMLInputElement) key.value = "";
  if (modelCustom instanceof HTMLInputElement) {
    modelCustom.value = cfg.provider === "custom" ? cfg.model : "";
  }
  if (style instanceof HTMLTextAreaElement) style.value = cfg.stylePrompt || "";
  if (neg instanceof HTMLTextAreaElement) neg.value = cfg.negativePrompt || "";
  const naiSamp = document.getElementById("image-gen-nai-sampler");
  if (naiSamp instanceof HTMLSelectElement) naiSamp.value = cfg.naiSampler || "k_euler";
  const naiSteps = document.getElementById("image-gen-nai-steps");
  if (naiSteps instanceof HTMLInputElement) naiSteps.value = String(cfg.naiSteps ?? 28);
  const naiCfg = document.getElementById("image-gen-nai-cfg");
  if (naiCfg instanceof HTMLInputElement) naiCfg.value = String(cfg.naiCfgScale ?? 5);
  const naiSeed = document.getElementById("image-gen-nai-seed");
  if (naiSeed instanceof HTMLInputElement) {
    naiSeed.value = Number(cfg.naiSeed) >= 0 ? String(cfg.naiSeed) : "";
  }
  const naiSmea = document.getElementById("image-gen-nai-smea");
  if (naiSmea instanceof HTMLInputElement) {
    naiSmea.checked = isNovelAiV4ModelId(cfg.model) ? false : Boolean(cfg.naiSmea);
  }
  const oaiQ = document.getElementById("image-gen-openai-quality");
  if (oaiQ instanceof HTMLSelectElement) {
    const qv = normalizeOpenAiImageQuality(cfg.openaiQuality);
    if ([...oaiQ.options].some((o) => o.value === qv)) oaiQ.value = qv;
  }
  const oaiF = document.getElementById("image-gen-openai-fidelity");
  if (oaiF instanceof HTMLSelectElement) {
    oaiF.value = normalizeOpenAiInputFidelity(cfg.openaiInputFidelity);
  }
  refreshImageGenProviderUi();
  if (size instanceof HTMLSelectElement) {
    const vals = [...size.querySelectorAll("option")].map((o) => o.value);
    if (vals.includes(cfg.size)) size.value = cfg.size;
  }
  renderImageGenPresetList();
}

function collectImageGenFormToConfig() {
  const prev = readImageGenConfig();
  const en = document.getElementById("image-gen-enabled");
  const prov = document.getElementById("image-gen-provider");
  const base = document.getElementById("image-gen-base");
  const key = document.getElementById("image-gen-key");
  const modelSel = document.getElementById("image-gen-model");
  const modelCustom = document.getElementById("image-gen-model-custom");
  const size = document.getElementById("image-gen-size");
  const style = document.getElementById("image-gen-style");
  const neg = document.getElementById("image-gen-negative");
  const rawProv =
    prov instanceof HTMLSelectElement ? String(prov.value || "openai").trim().toLowerCase() : "openai";
  const provider = normalizeImageGenProvider(rawProv);
  let model = IMAGE_GEN_DEFAULT_OPENAI_MODEL;
  if (provider === "custom") {
    const selVis = modelSel instanceof HTMLSelectElement && !modelSel.hidden;
    if (selVis) {
      model = String(modelSel.value || "").trim() ||
        (modelCustom instanceof HTMLInputElement ? String(modelCustom.value || "").trim() : "") ||
        IMAGE_GEN_DEFAULT_OPENAI_MODEL;
    } else if (modelCustom instanceof HTMLInputElement) {
      model = String(modelCustom.value || "").trim() || IMAGE_GEN_DEFAULT_OPENAI_MODEL;
    }
  } else if (modelSel instanceof HTMLSelectElement) {
    const def = getImageGenModelPresets(provider)[0]?.value || IMAGE_GEN_DEFAULT_OPENAI_MODEL;
    model = String(modelSel.value || "").trim() || def;
  }
  let baseUrl = "";
  if (provider === "custom" && base instanceof HTMLInputElement) {
    baseUrl = String(base.value || "").trim().replace(/\/+$/, "");
  } else if (provider === "novelai" && base instanceof HTMLInputElement) {
    baseUrl = String(base.value || "").trim().replace(/\/+$/, "");
  }
  let apiKey = prev.apiKey;
  if (key instanceof HTMLInputElement) {
    const k = String(key.value || "").trim();
    if (k) apiKey = k;
  }
  let sizeVal = "1024x1024";
  if (size instanceof HTMLSelectElement) sizeVal = String(size.value || "").trim() || "1024x1024";
  const naiSamp = document.getElementById("image-gen-nai-sampler");
  const naiStepsEl = document.getElementById("image-gen-nai-steps");
  const naiCfgEl = document.getElementById("image-gen-nai-cfg");
  const naiSeedInp = document.getElementById("image-gen-nai-seed");
  const naiSmeaInp = document.getElementById("image-gen-nai-smea");
  let naiSampler = prev.naiSampler || "k_euler";
  let naiSteps = prev.naiSteps ?? 28;
  let naiCfgScale = prev.naiCfgScale ?? 5;
  let naiSeed = prev.naiSeed ?? -1;
  let naiSmea = prev.naiSmea !== undefined ? prev.naiSmea : true;
  if (naiSamp instanceof HTMLSelectElement) naiSampler = String(naiSamp.value || "").trim();
  if (naiStepsEl instanceof HTMLInputElement) {
    const n = parseInt(String(naiStepsEl.value || ""), 10);
    if (Number.isFinite(n)) naiSteps = n;
  }
  if (naiCfgEl instanceof HTMLInputElement) {
    const n = parseFloat(String(naiCfgEl.value || ""));
    if (Number.isFinite(n)) naiCfgScale = n;
  }
  if (naiSeedInp instanceof HTMLInputElement) {
    const t = String(naiSeedInp.value || "").trim();
    naiSeed = t === "" ? -1 : Math.max(0, Math.min(4294967295, parseInt(t, 10) || 0));
  }
  if (naiSmeaInp instanceof HTMLInputElement) naiSmea = naiSmeaInp.checked;
  const oaiQ = document.getElementById("image-gen-openai-quality");
  const oaiF = document.getElementById("image-gen-openai-fidelity");
  let openaiQuality = prev.openaiQuality || "auto";
  let openaiInputFidelity = prev.openaiInputFidelity || "high";
  if (oaiQ instanceof HTMLSelectElement) {
    openaiQuality = normalizeOpenAiImageQuality(oaiQ.value);
  }
  if (oaiF instanceof HTMLSelectElement) {
    openaiInputFidelity = normalizeOpenAiInputFidelity(oaiF.value);
  }
  return normalizeImageGenConfig({
    v: 1,
    enabled: !!(en instanceof HTMLInputElement && en.checked),
    provider,
    baseUrl,
    apiKey,
    model,
    size: sizeVal,
    stylePrompt: style instanceof HTMLTextAreaElement ? style.value : "",
    negativePrompt: neg instanceof HTMLTextAreaElement ? neg.value : "",
    naiSampler,
    naiSteps,
    naiCfgScale,
    naiSeed,
    naiSmea,
    openaiQuality,
    openaiInputFidelity
  });
}

let imageGenTestLastObjectUrl = "";

function revokeImageGenTestPreviewUrl() {
  if (imageGenTestLastObjectUrl) {
    try {
      URL.revokeObjectURL(imageGenTestLastObjectUrl);
    } catch (_) {}
    imageGenTestLastObjectUrl = "";
  }
}

function resetImageGenTestPanel() {
  revokeImageGenTestPreviewUrl();
  const wrap = document.getElementById("image-gen-test-wrap");
  const st = document.getElementById("image-gen-test-status");
  const img = document.getElementById("image-gen-test-preview");
  if (wrap) wrap.hidden = true;
  if (st) {
    st.textContent = "";
    st.classList.remove("imgen-test-status--err");
  }
  if (img) {
    img.hidden = true;
    img.removeAttribute("src");
  }
}

function buildImageGenOpenAiGenerationsUrl(cfg) {
  const def = "https://api.openai.com/v1/images/generations";
  if (!imageGenUsesCustomOpenAiBase(cfg)) return def;
  const b = String(cfg.baseUrl || "").trim().replace(/\/+$/, "");
  if (!b) return def;
  if (/\/images\/generations$/i.test(b)) return b;
  if (/\/v1$/i.test(b)) return `${b}/images/generations`;
  return `${b}/v1/images/generations`;
}

function buildImageGenOpenAiEditsUrl(cfg) {
  const def = "https://api.openai.com/v1/images/edits";
  if (!imageGenUsesCustomOpenAiBase(cfg)) return def;
  const b = String(cfg.baseUrl || "").trim().replace(/\/+$/, "");
  if (!b) return def;
  if (/\/images\/edits$/i.test(b)) return b;
  if (/\/images\/generations$/i.test(b)) return b.replace(/\/generations$/i, "/edits");
  if (/\/v1$/i.test(b)) return `${b}/images/edits`;
  return `${b}/v1/images/edits`;
}

/** 密谈立绘参考图是否可走 OpenAI /images/edits（官方与自定义 Base 相同路径） */
function openAiImageModelSupportsReferenceEdits(model) {
  const m = String(model || "").trim().toLowerCase();
  if (isGptImageModelId(m)) return true;
  return m === "dall-e-2";
}

/** gpt-image-1 / 1.5：input_fidelity=high 利于保留脸部 */
function openAiImageEditsSupportsInputFidelity(model) {
  const m = String(model || "").trim().toLowerCase();
  if (m === "gpt-image-1" || m === "gpt-image-1.5") return true;
  if (/^gpt-image-1\.\d/i.test(m) && !/mini/i.test(m)) return true;
  return false;
}

const IMAGE_GEN_OPENAI_QUALITY_VALUES = new Set(["auto", "low", "medium", "high"]);

/** @param {unknown} raw */
function normalizeOpenAiImageQuality(raw) {
  const q = String(raw || "").trim().toLowerCase();
  return IMAGE_GEN_OPENAI_QUALITY_VALUES.has(q) ? q : "auto";
}

/** @param {unknown} raw */
function normalizeOpenAiInputFidelity(raw) {
  const f = String(raw || "").trim().toLowerCase();
  return f === "low" ? "low" : "high";
}

/**
 * @param {Record<string, unknown>} body
 * @param {ReturnType<typeof normalizeImageGenConfig>} cfg
 * @param {{ forEdits?: boolean }} [opts]
 */
function applyOpenAiGptImageFieldsToBody(body, cfg, opts) {
  const isGpt = isGptImageModelId(cfg.model);
  if (!isGpt) return;
  delete body.response_format;
  body.quality = normalizeOpenAiImageQuality(cfg.openaiQuality);
  if (body.output_format == null) body.output_format = "png";
  if (opts?.forEdits && openAiImageEditsSupportsInputFidelity(cfg.model)) {
    body.input_fidelity = normalizeOpenAiInputFidelity(cfg.openaiInputFidelity);
  }
}

/** @param {string} refDataUrl */
async function prepareOpenAiEditsRefDataUrl(refDataUrl) {
  let u = String(refDataUrl || "").trim();
  if (!/^data:image\//i.test(u)) return "";
  try {
    const shrunk = await shrinkDataUrlWithCanvas(u, 1536, 0.92);
    if (shrunk && /^data:image\//i.test(shrunk)) u = shrunk;
  } catch {
    /* keep */
  }
  return u;
}

/** @param {string} dataUrl */
async function blobFromImageDataUrl(dataUrl) {
  const r = await fetch(String(dataUrl));
  const blob = await r.blob();
  if (!blob?.size) throw new Error("参考图为空");
  return blob;
}

function mapOpenAiImageSizeForGenerationsApi(sizeVal, model) {
  const x = String(sizeVal || "")
    .trim()
    .toLowerCase()
    .replace(/×/g, "x");
  if (x === "auto") return "1024x1024";
  const isGpt = isGptImageModelId(model);
  /** @type {Record<string, string>} */
  const fromNovelAi = isGpt
    ? {
        "832x1216": "1024x1536",
        "1216x832": "1536x1024",
        "640x832": "1024x1536",
        "832x640": "1536x1024"
      }
    : {
        "832x1216": "1024x1792",
        "1216x832": "1792x1024",
        "640x832": "1024x1792",
        "832x640": "1792x1024",
        "512x768": "1024x1792",
        "768x512": "1792x1024"
      };
  if (fromNovelAi[x]) return fromNovelAi[x];
  const allowed = ["1024x1024", "1024x1536", "1536x1024", "512x512", "1792x1024", "1024x1792", "256x256"];
  return allowed.includes(x) ? x : "1024x1024";
}

function isGptImageModelId(model) {
  return /^gpt-image-/i.test(String(model || "").trim());
}

function parseImageGenSizeToWh(sizeVal) {
  const s = String(sizeVal || "").replace(/×/g, "x").trim();
  const m = /^(\d+)\s*x\s*(\d+)$/i.exec(s);
  if (m) {
    const w = Math.min(4096, Math.max(64, parseInt(m[1], 10)));
    const h = Math.min(4096, Math.max(64, parseInt(m[2], 10)));
    return [w, h];
  }
  return [1024, 1024];
}

/** data URL → NovelAI img2img 所需的纯 base64（无 data: 前缀） */
function dataUrlToNovelAiRawBase64(dataUrl) {
  const s = String(dataUrl || "").trim();
  const m = /^data:image\/[\w+.-]+;base64,(.+)$/i.exec(s);
  if (!m) return "";
  return String(m[1] || "").replace(/\s/g, "");
}

function buildImageGenNovelAiGenerateJson(cfg, promptText, refDataUrl) {
  const refB64 = dataUrlToNovelAiRawBase64(refDataUrl || "");
  const useImg2img = Boolean(refB64);
  /** 参考立绘时的 img2img：略偏保守，避免完全洗掉构图 */
  const img2Strength = Math.min(0.99, Math.max(0.01, 0.52));
  const img2Noise = Math.min(0.99, Math.max(0, 0.07));
  const [width, height] = parseImageGenSizeToWh(cfg.size);
  const neg =
    String(cfg.negativePrompt || "").trim() ||
    "lowres, bad anatomy, bad hands, text, worst quality, jpeg artifacts, watermark";
  const model = String(cfg.model || "").trim();
  const steps = Number.isFinite(Number(cfg.naiSteps)) ? Math.min(50, Math.max(10, Math.floor(Number(cfg.naiSteps)))) : 28;
  const scale = Number.isFinite(Number(cfg.naiCfgScale)) ? Math.min(15, Math.max(1, Number(cfg.naiCfgScale))) : 5;
  let sampler = String(cfg.naiSampler || "k_euler").trim() || "k_euler";
  const smeaOn = Boolean(cfg.naiSmea);
  let seedUse = Number(cfg.naiSeed);
  if (!Number.isFinite(seedUse) || seedUse < 0) {
    seedUse = Math.floor(Math.random() * 4294967295);
  } else {
    seedUse = Math.min(4294967295, Math.max(0, Math.floor(seedUse)));
  }

  if (isNovelAiV4ModelId(model)) {
    const v4Sampler = mapNovelAiSamplerForV4(sampler);
    const out = {
      input: promptText,
      model,
      action: "generate",
      parameters: {
        params_version: 3,
        width,
        height,
        scale,
        sampler: v4Sampler,
        steps,
        seed: seedUse,
        extra_noise_seed: seedUse,
        n_samples: 1,
        ucPreset: 3,
        qualityToggle: true,
        sm: false,
        sm_dyn: false,
        dynamic_thresholding: false,
        controlnet_strength: 1,
        legacy: false,
        add_original_image: true,
        cfg_rescale: 0,
        noise_schedule: "karras",
        skip_cfg_above_sigma: null,
        negative_prompt: neg,
        use_coords: false,
        v4_prompt: {
          caption: { base_caption: promptText, char_captions: [] },
          use_coords: false,
          use_order: true
        },
        v4_negative_prompt: {
          caption: { base_caption: neg, char_captions: [] },
          use_coords: false,
          use_order: true
        },
        characterPrompts: [],
        negativeCharacterPrompts: [],
        reference_information_extracted_multiple: [],
        reference_strength_multiple: [],
        deliberate_euler_ancestral_bug: false,
        prefer_brownian: true
      }
    };
    if (useImg2img) {
      out.parameters.image = refB64;
      out.parameters.strength = img2Strength;
      out.parameters.noise = img2Noise;
      out.action = "img2img";
    }
    return out;
  }

  const out = {
    input: promptText,
    model,
    action: "generate",
    parameters: {
      params_version: 1,
      width,
      height,
      scale,
      sampler,
      steps,
      seed: seedUse,
      n_samples: 1,
      ucPreset: 0,
      qualityToggle: true,
      sm: smeaOn,
      sm_dyn: false,
      dynamic_thresholding: false,
      controlnet_strength: 1,
      legacy: false,
      add_original_image: true,
      cfg_rescale: 0,
      noise_schedule: "native",
      legacy_v3_extend: false,
      skip_cfg_above_sigma: null,
      negative_prompt: neg
    }
  };
  if (useImg2img) {
    out.parameters.image = refB64;
    out.parameters.strength = img2Strength;
    out.parameters.noise = img2Noise;
    out.action = "img2img";
  }
  return out;
}

function buildImageGenTestPrompt(cfg) {
  const style = String(cfg.stylePrompt || "").trim();
  if (cfg.provider === "novelai") {
    const base =
      "origami fox, wooden desk, soft window light, depth of field, still life, no humans, no text, no watermark";
    if (!style) return base;
    const styleTags = style
      .split(",")
      .map((t) => t.trim())
      .filter(Boolean)
      .map((t) => `[[[${t}]]]`)
      .join(", ");
    return `${base}, ${styleTags}`;
  }
  const base =
    "Small studio test shot: one cute origami fox on a wooden desk, soft window light, shallow depth of field, no text, no watermark.";
  return style ? `${base} ${style}` : base;
}

/** @type {((u: Uint8Array) => Record<string, Uint8Array>) | null} */
let imageGenFflateUnzipSyncCache = null;

function getFflateUnzipSyncFromGlobal() {
  const g = typeof globalThis !== "undefined" ? globalThis : window;
  const f = g.fflate;
  if (f && typeof f.unzipSync === "function") return f.unzipSync;
  return null;
}

/** 优先本地 vendor/fflate.umd.js；未加载时再尝试 esm 兜底。 */
async function ensureImageGenFflateUnzipSync() {
  if (imageGenFflateUnzipSyncCache) return imageGenFflateUnzipSyncCache;
  const fromGlobal = getFflateUnzipSyncFromGlobal();
  if (fromGlobal) {
    imageGenFflateUnzipSyncCache = fromGlobal;
    return fromGlobal;
  }
  try {
    /** @type {{ unzipSync?: (u: Uint8Array) => Record<string, Uint8Array>; default?: { unzipSync?: (u: Uint8Array) => Record<string, Uint8Array> } }} */
    const mod = await import("https://esm.sh/fflate@0.8.2");
    const fn = mod.unzipSync || mod.default?.unzipSync;
    if (typeof fn === "function") {
      imageGenFflateUnzipSyncCache = fn;
      return fn;
    }
  } catch {
    /* ignore */
  }
  return null;
}

/**
 * @param {ArrayBuffer} buf
 * @param {(u: Uint8Array) => Record<string, Uint8Array>} unzipSync
 * @returns {Uint8Array | null}
 */
function novelaiUnzipFirstImageBytes(buf, unzipSync) {
  const files = unzipSync(new Uint8Array(buf));
  const names = Object.keys(files || {}).filter((k) => !k.endsWith("/"));
  const imgKey = names.find((k) => /\.(png|webp)$/i.test(k)) || names[0];
  if (!imgKey || !files[imgKey] || !files[imgKey].length) return null;
  return files[imgKey];
}

/**
 * NovelAI /ai/generate-image 常返回 zip；解压首张 png/webp。
 * @param {ArrayBuffer} buf
 * @returns {Promise<string|null>} object URL or null
 */
async function novelaiZipBufferToPngObjectUrl(buf) {
  try {
    const unzipSync = await ensureImageGenFflateUnzipSync();
    if (!unzipSync) return null;
    const bytes = novelaiUnzipFirstImageBytes(buf, unzipSync);
    if (!bytes) return null;
    const mime = bytes[0] === 0x89 && bytes[1] === 0x50 ? "image/png" : "image/webp";
    const blob = new Blob([bytes], { type: mime });
    return URL.createObjectURL(blob);
  } catch {
    return null;
  }
}

/**
 * @param {ReturnType<typeof normalizeImageGenConfig>} cfg
 * @param {{ preferLongTimeout?: boolean, refDataUrl?: string }} [extras]
 * @param {string} [promptText]
 */
function resolveImageGenFetchTimeoutMs(cfg, extras, promptText) {
  const isNai = cfg && cfg.provider === "novelai";
  const heavy =
    Boolean(extras && extras.preferLongTimeout) ||
    Boolean(extras && String(extras.refDataUrl || "").trim()) ||
    String(promptText || "").length > 1400;
  if (heavy) {
    if (isNai) return IMAGE_GEN_FETCH_TIMEOUT_NAI_HEAVY_MS;
    return IMAGE_GEN_FETCH_TIMEOUT_OPENAI_HEAVY_MS;
  }
  if (isNai) return IMAGE_GEN_FETCH_TIMEOUT_NAI_MS;
  return IMAGE_GEN_FETCH_TIMEOUT_OPENAI_MS;
}

/**
 * @param {string} url
 * @param {RequestInit} init
 * @param {number} timeoutMs
 */
async function fetchImageGenWithTimeout(url, init, timeoutMs) {
  const ms =
    Number(timeoutMs) > 0
      ? Number(timeoutMs)
      : IMAGE_GEN_FETCH_TIMEOUT_NAI_MS;
  const controller = new AbortController();
  const parentSignal = init?.signal;
  if (parentSignal) {
    if (parentSignal.aborted) controller.abort();
    else parentSignal.addEventListener("abort", () => controller.abort(), { once: true });
  }
  const timer = window.setTimeout(() => controller.abort(), ms);
  try {
    return await fetch(url, { ...init, signal: controller.signal });
  } catch (e) {
    if (e instanceof Error && e.name === "AbortError") {
      throw new Error(`生图请求超时（${Math.round(ms / 1000)}s）`);
    }
    throw e;
  } finally {
    window.clearTimeout(timer);
  }
}

async function runImageGenTestFromForm() {
  const cfg = collectImageGenFormToConfig();
  const wrap = document.getElementById("image-gen-test-wrap");
  const st = document.getElementById("image-gen-test-status");
  const img = document.getElementById("image-gen-test-preview");
  const btn = document.getElementById("image-gen-test");
  if (!cfg.enabled) {
    showToast("请先勾选「启用生图」（聊天也要求开启）");
    return;
  }
  if (!cfg.apiKey) {
    showToast("请填写 API Key（或留空沿用已保存的 Key）");
    return;
  }
  if (cfg.provider === "custom" && !String(cfg.baseUrl || "").trim()) {
    showToast("自定义服务商请填写 API Base");
    return;
  }
  const prompt = buildImageGenTestPrompt(cfg);
  revokeImageGenTestPreviewUrl();
  if (wrap) wrap.hidden = false;
  if (st) {
    st.classList.remove("imgen-test-status--err");
    st.textContent = "正在请求…";
  }
  if (img) {
    img.hidden = true;
    img.removeAttribute("src");
  }
  if (btn) btn.disabled = true;
  try {
    const gen = await executeImageGenRequestToDataUrl(cfg, prompt);
    if (!gen.ok || !gen.dataUrl) {
      if (st) {
        st.classList.add("imgen-test-status--err");
        st.textContent = `生成失败：${String(gen.error || "未知错误").slice(0, 220)}`;
      }
      showToast("测试生图失败");
      return;
    }
    imageGenTestLastObjectUrl = "";
    if (img) {
      img.src = gen.dataUrl;
      img.hidden = false;
    }
    if (st) {
      st.textContent =
        cfg.provider === "novelai"
          ? "测试成功（NovelAI）"
          : cfg.provider === "openai"
            ? "测试成功（OpenAI 官方）"
            : "测试成功（OpenAI 兼容 / 中转）";
    }
    showToast(
      imageGenFormMatchesSavedCfg(cfg) ? "测试生图成功" : "测试成功；请点「保存」，聊天才会用此配置"
    );
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    if (st) {
      st.classList.add("imgen-test-status--err");
      st.textContent = `请求异常：${msg.slice(0, 200)}`;
    }
    showToast("测试生图失败");
  } finally {
    if (btn) btn.disabled = false;
  }
}

