function renderSettingsTheaterCustomList() {
  const ul = document.getElementById("settings-theater-custom-list");
  if (!(ul instanceof HTMLElement)) return;
  ul.replaceChildren();
  const custom = readCustomTheaterPresetsFromKv();
  if (!custom.length) {
    const li = document.createElement("li");
    li.className = "theater-preset-sheet-empty";
    li.textContent = "暂无自定义预设；在下方填写后点「保存预设」。";
    ul.appendChild(li);
    return;
  }
  for (const p of custom) {
    const li = document.createElement("li");
    li.className = "theater-preset-sheet-item";
    const meta = document.createElement("div");
    meta.className = "theater-preset-sheet-item-meta";
    const title = document.createElement("strong");
    title.textContent = p.name;
    const sub = document.createElement("span");
    sub.textContent = p.kind === "html" ? "HTML" : "文字";
    meta.appendChild(title);
    meta.appendChild(sub);
    const del = document.createElement("button");
    del.type = "button";
    del.className = "chip ghost chip-xs";
    del.textContent = "删除";
    del.addEventListener("click", () => {
      if (!window.confirm(`删除预设「${p.name}」？`)) return;
      writeCustomTheaterPresetsToKv(custom.filter((x) => x.id !== p.id));
      const defaults = readTheaterDefaultEnabledPresetIds().filter((id) => id !== p.id);
      writeTheaterDefaultEnabledPresetIds(defaults);
      chatTheaterRerollPicksKey = "";
      refreshSettingsTheaterPanel();
      syncChatDetailTheaterPresetUi();
      syncChatTheaterPanelFromLog();
      showToast("已删除");
    });
    li.appendChild(meta);
    li.appendChild(del);
    ul.appendChild(li);
  }
}

