/**
 * 保存 AI：先写入本机 KV（聊天即用），再视情况同步「配置档案」表。
 * - 已选档案 + 有 Key：更新该档并设为当前活跃档案。
 * - 未选档案但填了档案名称 + 有 Key：新建一档并选用。
 * - 仅改表单、不建/不绑档：只写 KV。
 */
function saveAiConfigurationFromUi() {
  const ai = window.RP_AI;
  if (!ai) {
    showToast("AI 模块未加载");
    return false;
  }
  const base =
    document.getElementById("settings-ai-base")?.value?.trim() || ai.DEFAULT_BASE;
  const model =
    document.getElementById("settings-ai-model")?.value?.trim() || ai.DEFAULT_MODEL;
  const keyRaw = document.getElementById("settings-ai-key")?.value;
  const prevHadKey = Boolean(String(ai.getConfig()?.apiKey || "").trim());
  const selId = document.getElementById("settings-ai-profile")?.value || "";
  const nameRaw = document.getElementById("settings-ai-profile-name")?.value?.trim() || "";
  const temp = readAiTemperatureFromUi();
  const patch = { baseUrl: base, model, temperature: temp };
  if (keyRaw != null && String(keyRaw).trim()) patch.apiKey = String(keyRaw).trim();
  ai.saveConfig(patch);

  saveChatImHumanPaceFromUi({ silent: true });

  const key = resolveAiKeyForProfile();
  let statusTail = "";
  if (selId) {
    if (!key) {
      statusTail = "；档案未改（填写或已存 Key 后才可写回该档）";
    } else {
      ai.upsertProfile({
        id: selId,
        name: nameRaw || undefined,
        baseUrl: base,
        model,
        apiKey: key,
        temperature: temp
      });
      ai.setActiveProfileId(selId);
      statusTail = "；已同步到所选档案";
    }
  } else if (nameRaw) {
    if (!key) {
      statusTail = "；未新建档案（需 API Key）";
    } else {
      const newId = ai.upsertProfile({ name: nameRaw, baseUrl: base, model, apiKey: key, temperature: temp });
      ai.setActiveProfileId(newId);
      refreshAiProfileSelect();
      const sel = document.getElementById("settings-ai-profile");
      if (sel) sel.value = newId;
      statusTail = "；已新建并选用档案";
    }
  }

  fillAiFormFromConfig();
  if ((selId && key) || (!selId && nameRaw && key)) refreshAiProfileSelect();
  if (isChatMemoScreenOpen()) refreshChatMemoSummaryProfileSelect();
  const statusErr = statusTail.includes("未改") || statusTail.includes("未新建");
  const line = statusTail ? `本机连接项已写入${statusTail}` : "本机已保存";
  setSettingsStatusLine("settings-ai-status", line, statusErr ? "err" : "ok");
  const keyUpdated = keyRaw != null && String(keyRaw).trim();
  const keyHint = keyUpdated
    ? "Key 已写入本机（新值）"
    : prevHadKey
      ? "Key 沿用本机（未填新 Key）"
      : "尚未保存 Key（本次仅 Base/模型/温度）";
  const core = `Base / 模型「${model}」/ 温度 ${Number(temp).toFixed(2)}；${keyHint}`;
  if (statusErr) {
    showToast(
      statusTail.includes("未改")
        ? `本机已保存（${core}）；档案未更新：请填写 API Key 或先在本机存过 Key`
        : `本机已保存（${core}）；未新建档案：请先填写 API Key`
    );
  } else if (statusTail) {
    showToast(`已保存：${core}${statusTail}`);
  } else {
    showToast(`已保存：${core}（仅本机，未绑定档案）`);
  }
  return true;
}

/**
 * 切换「配置档案」下拉：写入本机 KV 并填满表单（Base / 模型 / 温度 / 档案名；Key 仍不露明文）。
 * @param {string} id 档案 id，空串表示不绑定档案
 */
function applySelectedAiProfile(id) {
  const ai = window.RP_AI;
  if (!ai) {
    showToast("AI 模块未加载");
    return false;
  }
  const nameInput = document.getElementById("settings-ai-profile-name");
  if (!id) {
    if (nameInput) nameInput.value = "";
    ai.setActiveProfileId("");
    fillAiFormFromConfig();
    setSettingsStatusLine("settings-ai-status", "已取消绑定档案；以下为当前本机生效项", "");
    showToast("已切换：仅使用本机当前配置（未绑定命名档案）");
    return true;
  }
  const p = ai.readProfiles().find((x) => x.id === id);
  if (!p) {
    showToast("该档案不存在或已删除");
    refreshAiProfileSelect();
    return false;
  }
  if (!ai.applyProfile(id)) {
    showToast("载入档案失败，请重试");
    return false;
  }
  fillAiFormFromConfig();
  if (nameInput) nameInput.value = String(p.name || "").trim() || "未命名配置";
  const baseInput = document.getElementById("settings-ai-base");
  const modelInput = document.getElementById("settings-ai-model");
  if (baseInput) baseInput.value = String(p.baseUrl || ai.DEFAULT_BASE || "").trim() || ai.DEFAULT_BASE;
  if (modelInput) modelInput.value = String(p.model || ai.DEFAULT_MODEL || "").trim() || ai.DEFAULT_MODEL;
  const pt =
    p.temperature != null && Number.isFinite(Number(p.temperature))
      ? Number(p.temperature)
      : ai.DEFAULT_TEMPERATURE;
  setAiTemperatureUi(pt);
  const note = document.getElementById("settings-ai-key-note");
  if (note) {
    note.textContent =
      p.apiKey && String(p.apiKey).trim()
        ? "已从该档案写入本机；Key 不在输入框显示，保存时可留空不改动"
        : "该档案未存 Key：请在本栏填写；保存后才会写入该档";
  }
  refreshAiProfileSelect();
  const sel = document.getElementById("settings-ai-profile");
  if (sel) sel.value = id;
  resetAiModelDatalist();
  const nm = String(p.name || "").trim() || "未命名配置";
  setSettingsStatusLine("settings-ai-status", `已载入「${nm}」`, "ok");
  showToast(`已自动填入「${nm}」`);
  return true;
}

