/** 叠层页先复位再下一帧加 is-open，避免同步重逻辑抢在同一帧里导致过场不画 */
function playStackScreenEnter(el, onEntered) {
  if (!el) return;
  el.classList.remove("is-open");
  el.setAttribute("aria-hidden", "true");
  void el.offsetWidth;
  requestAnimationFrame(() => {
    el.classList.add("is-open");
    el.setAttribute("aria-hidden", "false");
    if (typeof onEntered === "function") {
      requestAnimationFrame(onEntered);
    }
  });
}

/**
 * @param {{ returnToInbox?: boolean }} [opts]
 * returnToInbox：仅用户点聊天顶栏「返回」时为 true；其它 App 切屏时勿自动打开密谈列表。
 */
function closeChatScreen(opts) {
  const chatEl = document.getElementById("chat-screen");
  const wasChatOpen = Boolean(chatEl?.classList.contains("is-open"));
  const leavingRef = wasChatOpen ? readChatActiveThreadRef() : null;
  clearChatProactiveTimer();
  scheduleChatProactivePeerScanTimer();
  clearChatMsgMultiSelectMode();
  closeCharIncomingCallSheet();
  closeChatBubbleActionSheet();
  closeChatDetailImageStyleSheet();
  closeChatThreadDetailPanel({ skipFocusRestore: true });
  window.XXJ_EXT?.close?.({ skipFocusRestore: true });
  closeChatMemoScreen({ skipReturnToThreadDetail: true });
  closeChatCharInnerVoicePanel();
  closeChatCharRecallPeekPanel();
  closeChatCallTranscriptPeek();
  closeChatPhotoViewer();
  closeChatInnerVoiceHistoryScreen();
  chatEl?.classList.remove("is-open");
  chatEl?.setAttribute("aria-hidden", "true");
  if (leavingRef?.maskId && leavingRef?.threadId) {
    touchChatUiFullMessagesLru(leavingRef.maskId, leavingRef.threadId);
  }
  if (chatListScreen?.classList.contains("is-open")) {
    requestAnimationFrame(() => renderChatThreadList());
    return;
  }
  if (
    opts?.returnToInbox &&
    wasChatOpen &&
    resolveChatCloseBackNavTarget() === "list"
  ) {
    playStackScreenEnter(chatListScreen, () => {
      void ensureChatInboxForUi().then(() => {
        renderChatMaskStrip();
        renderChatThreadList();
      });
    });
  }
}

