async function runBackupCloudGithubUpload(opts) {
  if (backupCloudGithubUploadInFlight) return;
  await ensureDbReadyForBackupCloud();
  const cfg = saveBackupCloudGithubConfig(readBackupCloudGithubConfigFromUi());
  syncBackupCloudGithubConfigToUi();
  if (!cfg.token) {
    if (!opts?.auto) showToast("请先填写 GitHub Token");
    return;
  }
  try {
    assertBackupCloudGithubRepoFields(cfg);
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    setBackupCloudGithubStatus(msg, "err");
    if (!opts?.auto) showToast(msg);
    return;
  }
  const picked = opts?.auto
    ? getPickedBackupZipExportDefs({ useSavedAutoModules: true })
    : getPickedBackupZipExportDefs();
  if (!picked.length) {
    if (!opts?.auto) showToast("请至少勾选一项");
    else setBackupCloudGithubStatus("定时备份：未配置导出模块", "err");
    return;
  }
  backupCloudGithubUploadInFlight = 1;
  setBackupCloudGithubStatus(opts?.auto ? "定时备份：正在打包…" : "正在打包…", "pending");
  try {
    const up = await githubUploadBackupPartsSet(cfg, picked, (msg) => {
      setBackupCloudGithubStatus(opts?.auto ? `定时备份：${msg}` : msg, "pending");
    });
    /** @type {Record<string, unknown>} */
    const savedPartial = {
      ...cfg,
      remoteSha: up.sha,
      lastUploadedAt: new Date().toISOString(),
      lastRemoteBytes: up.bytes,
      lastPartCount: up.partCount
    };
    if (cfg.autoUploadEnabled) {
      savedPartial.nextAutoUploadAt = computeNextBackupAutoUploadAt(cfg, Date.now());
    }
    const saved = saveBackupCloudGithubConfig(savedPartial);
    syncBackupCloudGithubConfigToUi();
    syncBackupCloudGithubAutoSchedule(saved);
    const partNote = up.partCount > 1 ? `（${up.partCount} 个分包）` : "";
    setBackupCloudGithubStatus(`已上传至 ${saved.owner}/${saved.repo}${partNote}`, "ok");
    showToast(
      opts?.auto
        ? up.partCount > 1
          ? `定时备份：已上传 ${up.partCount} 个分包`
          : "定时备份已上传到 GitHub"
        : up.partCount > 1
          ? `已上传 ${up.partCount} 个分包到 GitHub`
          : "已上传到 GitHub"
    );
  } catch (err) {
    const detail = formatGithubApiError(err, cfg);
    setBackupCloudGithubStatus(opts?.auto ? `定时备份失败：${detail}` : detail, "err");
    if (!opts?.auto) {
      showToast(/Bad credentials/i.test(String(err instanceof Error ? err.message : err)) ? "Token 认证失败" : "上传失败");
    }
  } finally {
    backupCloudGithubUploadInFlight = 0;
  }
}

async function runBackupCloudGithubPull() {
  await ensureDbReadyForBackupCloud();
  const cfg = saveBackupCloudGithubConfig(readBackupCloudGithubConfigFromUi());
  syncBackupCloudGithubConfigToUi();
  if (!cfg.token) {
    showToast("请先填写 GitHub Token");
    return;
  }
  try {
    assertBackupCloudGithubRepoFields(cfg);
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    setBackupCloudGithubStatus(msg, "err");
    showToast(msg);
    return;
  }
  const JSZipLib = window.JSZip;
  if (typeof JSZipLib !== "function") {
    showToast("ZIP 模块未加载，请检查网络后刷新");
    return;
  }
  setBackupCloudGithubStatus("正在从 GitHub 下载…", "pending");
  let cloudManifestWrap = null;
  try {
    cloudManifestWrap = await githubTryDownloadCloudManifest(cfg);
  } catch (err) {
    const detail = formatGithubApiError(err, cfg);
    setBackupCloudGithubStatus(detail.startsWith("Token") ? detail : `拉取失败：${detail}`, "err");
    showToast(/Bad credentials/i.test(String(err instanceof Error ? err.message : err)) ? "Token 认证失败" : "拉取失败");
    return;
  }

  const cloudManifest = cloudManifestWrap?.manifest || null;
  const defaultBranch = await githubFetchRepoDefaultBranch(cfg);
  const branchCandidates = githubBackupBranchCandidates(cfg, cloudManifest);
  if (defaultBranch && !branchCandidates.includes(defaultBranch)) branchCandidates.unshift(defaultBranch);
  if (cloudManifestWrap?.branch && !branchCandidates.includes(cloudManifestWrap.branch)) {
    branchCandidates.unshift(cloudManifestWrap.branch);
  }

  const repoLabel = `${cfg.owner}/${cfg.repo}`;
  /** @type {{ zip: *, manifest: *, path: string, index: number, sha?: string, bytes?: number }[]} */
  let loadedParts = [];
  let primarySha = "";
  let totalBytes = 0;

  try {
    if (cloudManifest) {
      const partMeta = [...cloudManifest.parts].sort(
        (a, b) => (Number(a.index) || 0) - (Number(b.index) || 0)
      );
      for (let i = 0; i < partMeta.length; i++) {
        const meta = partMeta[i];
        const path = String(meta.path || "").trim();
        if (!path) throw new Error("云端 manifest 缺少分包路径");
        setBackupCloudGithubStatus(`正在下载 ${i + 1}/${partMeta.length}…`, "pending");
        const remote = await githubDownloadBackupWithBranchRetry(cfg, path, branchCandidates);
        const { zip, manifest } = await loadGithubBackupPartFromRemote(
          JSZipLib,
          remote,
          `分包 ${i + 1}`
        );
        loadedParts.push({
          zip,
          manifest,
          path,
          index: Number(meta.index) || i + 1,
          sha: remote.sha,
          bytes: remote.bytes
        });
        if (!primarySha) primarySha = remote.sha;
        totalBytes += remote.bytes || 0;
      }
    } else {
      const discovered = await githubDiscoverSplitBackupRemotes(cfg, branchCandidates);
      if (discovered && discovered.remotes.length) {
        for (let i = 0; i < discovered.remotes.length; i++) {
          const remote = discovered.remotes[i];
          setBackupCloudGithubStatus(`正在下载 ${i + 1}/${discovered.remotes.length}…`, "pending");
          const { zip, manifest } = await loadGithubBackupPartFromRemote(
            JSZipLib,
            remote,
            `分包 ${i + 1}`
          );
          loadedParts.push({
            zip,
            manifest,
            path: remote.path,
            index: remote.index,
            sha: remote.sha,
            bytes: remote.bytes
          });
          if (!primarySha) primarySha = remote.sha;
          totalBytes += remote.bytes || 0;
        }
      } else {
        let remote = null;
        for (const branch of branchCandidates) {
          try {
            remote = await githubDownloadBackupArrayBuffer(cfg, { branch });
            break;
          } catch (err) {
            const status = err && typeof err === "object" ? /** @type {{ status?: number }} */ (err).status : undefined;
            const msg = String(err instanceof Error ? err.message : err || "");
            if (status === 404 || /404|not found/i.test(msg)) continue;
            throw err;
          }
        }
        if (!remote) {
          throw new Error(
            "未找到 mxj-backup-cloud-manifest.json、mxj-backup-part-*.zip 或 mxj-backup-latest.zip。" +
              "请确认用户名/仓库/Token 与上传时一致；高级选项「分支」留空时会自动尝试仓库默认分支。"
          );
        }
        const { zip, manifest } = await loadGithubBackupPartFromRemote(JSZipLib, remote, "云端备份");
        loadedParts = [
          {
            zip,
            manifest,
            path: remote.path || githubBackupSingleRemotePath(cfg),
            index: 1,
            sha: remote.sha,
            bytes: remote.bytes
          }
        ];
        primarySha = remote.sha;
        totalBytes = remote.bytes || 0;
      }
    }
  } catch (err) {
    const detail = formatGithubApiError(err, cfg);
    const msg = err instanceof Error ? err.message : String(err);
    setBackupCloudGithubStatus(detail.startsWith("Token") ? detail : msg ? `拉取失败：${msg}` : `拉取失败：${detail}`, "err");
    showToast(/Bad credentials/i.test(msg) ? "Token 认证失败" : "拉取失败");
    return;
  }

  const partLabel =
    loadedParts.length > 1
      ? `GitHub · ${repoLabel} · ${loadedParts.length} 个分包`
      : `GitHub · ${repoLabel}/${loadedParts[0]?.path || githubBackupSingleRemotePath(cfg)}`;

  if (loadedParts.length > 1) {
    populateBackupZipImportFromCloudParts(loadedParts, partLabel);
  } else {
    pendingBackupCloudParts = null;
    await populateBackupZipImportFromLoaded(loadedParts[0].zip, loadedParts[0].manifest, partLabel);
  }

  const confirmMsg =
    loadedParts.length > 1
      ? `将从 GitHub 云端恢复 ${loadedParts.length} 个分包（内容与上方勾选一致，保留登录）。确定继续？`
      : "将从 GitHub 云端备份恢复勾选的模块到本机（保留登录）。确定继续？";
  if (!window.confirm(confirmMsg)) {
    resetBackupZipImportUi();
    setBackupCloudGithubStatus("已取消恢复", "");
    return;
  }
  setBackupCloudGithubStatus("正在写入本地…", "pending");
  setBackupZipImportStatus("正在从 GitHub 恢复，请勿关闭页面…", "pending");
  try {
    const result =
      loadedParts.length > 1
        ? await applyBackupCloudGithubPartsImport((msg) => {
            setBackupZipImportStatus(msg, "pending");
            setBackupCloudGithubStatus(msg, "pending");
          })
        : await applyBackupZipImport(loadedParts[0].zip, loadedParts[0].manifest, (msg) => {
            setBackupZipImportStatus(msg, "pending");
            setBackupCloudGithubStatus(msg, "pending");
          });
    if (!result || result.ok === false) {
      const detail = result && result.err ? String(result.err) : "恢复失败";
      setBackupCloudGithubStatus(detail, "err");
      setBackupZipImportStatus(detail, "err");
      showToast("拉取恢复失败");
      pendingBackupCloudParts = null;
      return;
    }
    saveBackupCloudGithubConfig({
      ...cfg,
      remoteSha: primarySha,
      lastRemoteBytes: totalBytes || cfg.lastRemoteBytes,
      lastPartCount: loadedParts.length
    });
    syncBackupCloudGithubConfigToUi();
    const skippedNote =
      Array.isArray(result.skipped) && result.skipped.length
        ? `（已跳过 ${result.skipped.map((s) => s.label).join("、")}）`
        : "";
    const partNote = loadedParts.length > 1 ? ` · ${loadedParts.length} 个分包` : "";
    setBackupCloudGithubStatus(`已从 GitHub 恢复${partNote}${skippedNote}`, "ok");
    setBackupZipImportStatus(`导入成功${skippedNote}`, "ok");
    refreshSurfacesAfterBackupZipImport(result);
    showToast(skippedNote ? `已从 GitHub 恢复${skippedNote}` : "已从 GitHub 恢复");
    window.setTimeout(() => closeBackupZipModal(), 2400);
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    setBackupCloudGithubStatus(msg ? `恢复失败：${msg}` : "恢复失败", "err");
    setBackupZipImportStatus(msg ? `导入失败：${msg}` : "导入失败", "err");
    showToast("拉取恢复失败");
    pendingBackupCloudParts = null;
  }
}

/** @param {string} err */
function backupZipImportFail(err) {
  pendingBackupModulePayloads = null;
  const msg = String(err || "").trim() || "导入失败";
  showToast(msg);
  return { ok: false, err: msg };
}
/** 写入 ZIP 内 manifest.json，与「备份与导入」导出区文案一致 */
