function validateChatMemoAutomationDraftNumbers() {
  const { rawA, rawB, nA, nB } = readChatMemoAutomationDraftNumbers();
  if (
    (rawA !== "" && (!Number.isFinite(nA) || nA < 0 || nA > CHAT_MEMO_AUTO_LOG_EVERY_MAX)) ||
    (rawB !== "" && (!Number.isFinite(nB) || nB < 0 || nB > CHAT_MEMO_SUMMARY_MAX))
  ) {
    showToast("请输入有效数字");
    return null;
  }
  if (rawB !== "" && Number.isFinite(nB) && nB === 1) {
    showToast("自动合并须 ≥2 或留空关闭");
    return null;
  }
  return {
    nA: rawA === "" || !Number.isFinite(nA) || nA <= 0 ? 0 : Math.floor(nA),
    nB: rawB === "" || !Number.isFinite(nB) || nB < 2 ? 0 : Math.floor(nB)
  };
}

function saveChatMemoAutomationSettings() {
  const parsed = validateChatMemoAutomationDraftNumbers();
  if (!parsed) return false;
  const { nA, nB } = parsed;
  const th0 = readActiveThread();
  const mid = String(getActiveMaskIdForInbox() || "").trim();
  const prevEvery = resolveThreadMemoAutoSummaryEveryUser(th0, mid);
  const logLenNow = countChatLogWeightForMemoAutoSummary(readChatLog());
  patchActiveThread((th) => {
    if (nA > 0) {
      th.memoAutoSummaryEveryUser = nA;
      if (prevEvery !== nA) th.memoAutoSummaryLastUserCount = logLenNow;
    } else {
      delete th.memoAutoSummaryEveryUser;
      delete th.memoAutoSummaryLastUserCount;
    }
    if (nB >= 2) th.memoAutoMergeEverySummaries = nB;
    else delete th.memoAutoMergeEverySummaries;
  });
  window.RP_AI?.setMemoSummaryProfileId?.(readMemoSummaryProfileIdFromUi());
  refreshChatMemoSummaryProfileSelect();
  refreshChatMemoStatusPanel();
  showToast("自动化设置已保存");
  return true;
}

function saveChatMemoAutomationDefaultSettings() {
  const parsed = validateChatMemoAutomationDraftNumbers();
  if (!parsed) return false;
  const { nA, nB } = parsed;
  const mid = String(getActiveMaskIdForInbox() || "").trim();
  if (!mid) {
    showToast("没有可用的面具");
    return false;
  }
  const prof = readMemoSummaryProfileIdFromUi();
  const store = readChatMemoAutomationDefaultStore();
  /** @type {{ memoAutoSummaryEveryUser?: number, memoAutoMergeEverySummaries?: number }} */
  const entry = {};
  if (nA > 0) entry.memoAutoSummaryEveryUser = nA;
  if (nB >= 2) entry.memoAutoMergeEverySummaries = nB;
  if (Object.keys(entry).length) store.byMask[mid] = entry;
  else delete store.byMask[mid];
  writeChatMemoAutomationDefaultStore(store);
  window.RP_AI?.setMemoSummaryProfileId?.(prof);
  refreshChatMemoSummaryProfileSelect();
  refreshChatMemoStatusPanel();
  showToast("已设为默认自动化");
  return true;
}

async function runChatMemoMergeSelectedSummariesAi() {
  persistChatMemoScreenToThread();
  const ul = document.getElementById("chat-memo-timeline");
  if (!ul) return;
  const selectedIds = [];
  for (const cb of ul.querySelectorAll("input.chat-memo-tl-cb:checked")) {
    const li = cb.closest("li.chat-memo-tl-li");
    const id = li && li.dataset.id ? String(li.dataset.id).trim() : "";
    if (id) selectedIds.push(id);
  }
  if (selectedIds.length < 2) {
    showToast("请勾选至少 2 条摘要");
    return;
  }
  const th = readActiveThread();
  if (!th) return;
  const rows = readCharThreadMemorySummariesSorted(th);
  const selectedRows = rows.filter((r) => selectedIds.includes(String(r.id)));
  if (selectedRows.length < 2) {
    showToast("所选条目无效，请先保存后再试");
    return;
  }
  const btn = document.getElementById("chat-memo-merge-selected");
  btn?.setAttribute("aria-busy", "true");
  if (btn instanceof HTMLButtonElement) btn.disabled = true;
  try {
    const mergedText = await mergeCharThreadMemorySummariesWithAi(selectedRows);
    const newId =
      typeof crypto !== "undefined" && crypto.randomUUID
        ? crypto.randomUUID()
        : `mem_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 9)}`;
    const selSet = new Set(selectedIds);
    patchActiveThread((t) => {
      const cur = normalizeCharThreadMemorySummariesArray(t.charThreadMemorySummaries);
      const rest = cur.filter((r) => !selSet.has(String(r.id)));
      const mergedEnd = mergedMemorySummaryChatExclusiveEndFromBatch(selectedRows);
      const mergedStart = mergedMemorySummaryInclusiveStartFromBatch(selectedRows);
      /** @type {{ id: string, at: number, text: string, afterChatLogExclusiveEnd?: number, afterChatLogInclusiveStart?: number }} */
      const newRow = { id: newId, at: Date.now(), text: mergedText };
      if (mergedEnd != null) newRow.afterChatLogExclusiveEnd = mergedEnd;
      if (mergedStart != null) newRow.afterChatLogInclusiveStart = mergedStart;
      rest.push(newRow);
      if (!rest.length) delete t.charThreadMemorySummaries;
      else t.charThreadMemorySummaries = normalizeCharThreadMemorySummariesArray(rest);
      if (mergedEnd != null) bumpThreadMemoManualExclusiveEndLogIdx(t, mergedEnd);
    });
    renderChatMemoTimeline();
    syncChatThreadDetailPanelPlaceholders();
    showToast(`已合并为 1 条新摘要（已移除 ${selectedRows.length} 条）`);
    scheduleMemoAutoMergeChain(String(readActiveThread()?.id || ""));
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    showToast(`合并失败：${msg}`);
  } finally {
    btn?.removeAttribute("aria-busy");
    if (btn instanceof HTMLButtonElement) btn.disabled = false;
  }
}

function isTrustedChatInboxShape(raw) {
  return !!(
    raw &&
    typeof raw === "object" &&
    raw.v === CHAT_INBOX_V &&
    raw.byMask &&
    typeof raw.byMask === "object"
  );
}

/** @param {unknown} raw @param {{ strict?: boolean }} [opts] strict：导入等场景强制完整规范化 */
function normalizeChatInboxStore(raw, opts) {
  if (!opts?.strict && isTrustedChatInboxShape(raw)) {
    return raw;
  }
  const byMask = {};
  const src = raw?.byMask && typeof raw.byMask === "object" ? raw.byMask : {};
  for (const [k, v] of Object.entries(src)) {
    if (!k) continue;
    const threads = (Array.isArray(v?.threads) ? v.threads : []).map((t) => {
      const id = String(t?.id || newEntityId());
      const charId = String(t?.charId || "");
      const kind = t?.kind === "group" ? "group" : "dm";
      const messages = Array.isArray(t?.messages)
        ? t.messages
            .filter(
              (m) =>
                m &&
                typeof m === "object" &&
                (m.role === "user" ||
                  m.role === "assistant" ||
                  (m.role === "notice" &&
                    (String(m.kind || "") === "recall_user" ||
                      String(m.kind || "") === "recall_char" ||
                      String(m.kind || "") === "call_end" ||
                      String(m.kind || "") === "offline_end" ||
                      String(m.kind || "") === "char_lock_end" ||
                      String(m.kind || "") === "checkup_finish" ||
                      String(m.kind || "") === "checkup_reverse_finish" ||
                      String(m.kind || "") === "checkup_reverse_refused" ||
                      String(m.kind || "") === "checkup_caught" ||
                      String(m.kind || "") === "char_remark_user" ||
                      String(m.kind || "") === "block_user_char" ||
                      String(m.kind || "") === "unblock_user_char" ||
                      String(m.kind || "") === "block_char_user" ||
                      String(m.kind || "") === "unblock_char_user" ||
                      String(m.kind || "") === "moments_feed")))
            )
            .map((m) => {
              if (m.role === "notice" && String(m.kind || "") === "recall_char") {
                return {
                  role: "notice",
                  kind: "recall_char",
                  at: Number.isFinite(Number(m.at)) ? Number(m.at) : Date.now(),
                  content: "",
                  recalledContent: String(m.recalledContent ?? "").slice(0, 500_000),
                  innerVoice: String(m.innerVoice ?? "").slice(0, 200_000)
                };
              }
              if (m.role === "notice" && String(m.kind || "") === "recall_user") {
                const out = {
                  role: "notice",
                  kind: "recall_user",
                  at: Number.isFinite(Number(m.at)) ? Number(m.at) : Date.now(),
                  content: ""
                };
                const rc = String(m.recalledContent ?? "").trim();
                if (rc) out.recalledContent = rc.slice(0, 500_000);
                const tr = String(m.recalledTranslation ?? "").trim();
                if (tr) out.recalledTranslation = tr.slice(0, 500_000);
                return out;
              }
              if (m.role === "notice" && String(m.kind || "") === "call_end") {
                const initiator = String(m.callInitiator || "") === "assistant" ? "assistant" : "user";
                const out = {
                  role: "notice",
                  kind: "call_end",
                  at: Number.isFinite(Number(m.at)) ? Number(m.at) : Date.now(),
                  content: "",
                  callMode: String(m.callMode || "") === "video" ? "video" : "audio",
                  durationMs: Math.max(0, Math.min(86400000, Number(m.durationMs) || 0)),
                  connected: m.connected === true,
                  callInitiator: initiator
                };
                if (String(m.declinedBy || "") === "user") out.declinedBy = "user";
                const eb = normalizeCallEndedByValue(m.endedBy);
                if (eb) out.endedBy = eb;
                const ecn = String(m.endCallNote || "").trim();
                if (ecn) out.endCallNote = ecn.slice(0, 80);
                const dm = String(m.declineMood || "").trim();
                if (dm) out.declineMood = dm.slice(0, 80);
                if (Array.isArray(m.callTranscript) && m.callTranscript.length) {
                  out.callTranscript = m.callTranscript
                    .map((row) => {
                      if (!row || typeof row !== "object") return null;
                      const o = {
                        role: row.role === "assistant" ? "assistant" : "user",
                        text: String(row.text || ""),
                        at: Number.isFinite(Number(row.at)) ? Number(row.at) : 0
                      };
                      const tr = String(row.translation || "").trim();
                      if (tr) o.translation = tr;
                      return o;
                    })
                    .filter(Boolean);
                }
                return out;
              }
              if (m.role === "notice" && String(m.kind || "") === "offline_end") {
                const out = {
                  role: "notice",
                  kind: "offline_end",
                  at: Number.isFinite(Number(m.at)) ? Number(m.at) : Date.now(),
                  content: ""
                };
                if (m.offlineMeetSummary === true) out.offlineMeetSummary = true;
                if (Array.isArray(m.offlineTranscript) && m.offlineTranscript.length) {
                  out.offlineTranscript = m.offlineTranscript
                    .map((row) => {
                      if (!row || typeof row !== "object") return null;
                      const o = {
                        role: row.role === "assistant" ? "assistant" : "user",
                        text: String(row.text || ""),
                        at: Number.isFinite(Number(row.at)) ? Number(row.at) : 0
                      };
                      const tr = String(row.translation || "").trim();
                      if (tr) o.translation = tr;
                      return o;
                    })
                    .filter(Boolean);
                }
                return out;
              }
              if (m.role === "notice" && String(m.kind || "") === "char_lock_end") {
                const out = {
                  role: "notice",
                  kind: "char_lock_end",
                  at: Number.isFinite(Number(m.at)) ? Number(m.at) : Date.now(),
                  content: "",
                  charLockReport: String(m.charLockReport || "").slice(0, 20_000),
                  charLockExitKind: String(m.charLockExitKind || "").slice(0, 64)
                };
                if (Array.isArray(m.charLockTranscript) && m.charLockTranscript.length) {
                  out.charLockTranscript = m.charLockTranscript
                    .map((row) => {
                      if (!row || typeof row !== "object") return null;
                      const o = {
                        role: row.role === "assistant" ? "assistant" : "user",
                        text: String(row.text || ""),
                        at: Number.isFinite(Number(row.at)) ? Number(row.at) : 0
                      };
                      const tr = String(row.translation || "").trim();
                      if (tr) o.translation = tr;
                      return o;
                    })
                    .filter(Boolean);
                }
                return out;
              }
              if (
                m.role === "notice" &&
                (String(m.kind || "") === "checkup_finish" || String(m.kind || "") === "checkup_caught")
              ) {
                const kind = String(m.kind || "") === "checkup_caught" ? "checkup_caught" : "checkup_finish";
                const out = {
                  role: "notice",
                  kind,
                  at: Number.isFinite(Number(m.at)) ? Number(m.at) : Date.now(),
                  content: "",
                  checkupReport: String(m.checkupReport || "").slice(0, 20_000)
                };
                const cn = String(m.charName || "").trim();
                if (cn) out.charName = cn.slice(0, 32);
                const cr = String(m.checkupReason || "").trim();
                if (cr) out.checkupReason = cr.slice(0, 64);
                const cq = String(m.checkupQuestion || "").trim();
                if (cq) out.checkupQuestion = cq.slice(0, 120);
                if (Array.isArray(m.checkupEvidence) && m.checkupEvidence.length) {
                  out.checkupEvidence = m.checkupEvidence
                    .map((x) => String(x || "").trim())
                    .filter(Boolean)
                    .slice(0, 12);
                }
                if (Array.isArray(m.checkupEvidenceDetail) && m.checkupEvidenceDetail.length) {
                  out.checkupEvidenceDetail = m.checkupEvidenceDetail
                    .map((row) => {
                      if (!row || typeof row !== "object") return null;
                      const appId = String(row.appId || "").trim();
                      const label = String(row.label || "").trim();
                      if (!appId || !label) return null;
                      return {
                        appId: appId.slice(0, 24),
                        label: label.slice(0, 32),
                        excerpt: String(row.excerpt || "").slice(0, 2000)
                      };
                    })
                    .filter(Boolean)
                    .slice(0, 12);
                }
                if (kind === "checkup_finish" && m.caught === true) out.caught = true;
                if (m.kickedOut === true) out.kickedOut = true;
                return out;
              }
              if (m.role === "notice" && String(m.kind || "") === "checkup_reverse_finish") {
                const out = {
                  role: "notice",
                  kind: "checkup_reverse_finish",
                  at: Number.isFinite(Number(m.at)) ? Number(m.at) : Date.now(),
                  content: "",
                  checkupReport: String(m.checkupReport || "").slice(0, 20_000)
                };
                const cn = String(m.charName || "").trim();
                if (cn) out.charName = cn.slice(0, 32);
                const cr = String(m.checkupReason || "").trim();
                if (cr) out.checkupReason = cr.slice(0, 64);
                if (Array.isArray(m.checkupReverseViewed) && m.checkupReverseViewed.length) {
                  out.checkupReverseViewed = m.checkupReverseViewed
                    .map((row) => {
                      if (!row || typeof row !== "object") return null;
                      return {
                        panel: String(row.panel || "").slice(0, 32),
                        target: String(row.target || "").slice(0, 48),
                        excerpt: String(row.excerpt || "").slice(0, 400)
                      };
                    })
                    .filter(Boolean)
                    .slice(0, 16);
                }
                if (Array.isArray(m.checkupReverseActions) && m.checkupReverseActions.length) {
                  out.checkupReverseActions = m.checkupReverseActions.slice(0, 20);
                }
                if (m.userKicked === true) out.userKicked = true;
                const ukn = String(m.userName || "").trim();
                if (ukn) out.userName = ukn.slice(0, 32);
                return out;
              }
              if (m.role === "notice" && String(m.kind || "") === "checkup_reverse_refused") {
                const out = {
                  role: "notice",
                  kind: "checkup_reverse_refused",
                  at: Number.isFinite(Number(m.at)) ? Number(m.at) : Date.now(),
                  content: ""
                };
                const cn = String(m.charName || "").trim();
                if (cn) out.charName = cn.slice(0, 32);
                const un = String(m.userName || "").trim();
                if (un) out.userName = un.slice(0, 32);
                const cr = String(m.checkupReason || "").trim();
                if (cr) out.checkupReason = cr.slice(0, 64);
                return out;
              }
              if (m.role === "notice" && String(m.kind || "") === "char_remark_user") {
                const out = {
                  role: "notice",
                  kind: "char_remark_user",
                  at: Number.isFinite(Number(m.at)) ? Number(m.at) : Date.now(),
                  remark: String(m.remark ?? "").trim().slice(0, 32)
                };
                const cn = String(m.charName || "").trim();
                if (cn) out.charName = cn.slice(0, 64);
                const lb = String(m.label || "").trim();
                if (lb) out.label = lb.slice(0, 120);
                const rs = String(m.reason ?? "").trim();
                if (rs) out.reason = rs.slice(0, 2000);
                return out;
              }
              if (
                m.role === "notice" &&
                (String(m.kind || "") === "block_user_char" ||
                  String(m.kind || "") === "unblock_user_char" ||
                  String(m.kind || "") === "block_char_user" ||
                  String(m.kind || "") === "unblock_char_user")
              ) {
                const kind = String(m.kind || "").trim();
                const out = {
                  role: "notice",
                  kind,
                  at: Number.isFinite(Number(m.at)) ? Number(m.at) : Date.now()
                };
                const cn = String(m.charName || "").trim();
                if (cn) out.charName = cn.slice(0, 64);
                const un = String(m.userName || "").trim();
                if (un) out.userName = un.slice(0, 64);
                const lb = String(m.label || "").trim();
                if (lb) out.label = lb.slice(0, 120);
                return out;
              }
              if (m.role === "notice" && String(m.kind || "") === "moments_feed") {
                const out = {
                  role: "notice",
                  kind: "moments_feed",
                  at: Number.isFinite(Number(m.at)) ? Number(m.at) : Date.now()
                };
                const act = String(m.action || "").trim();
                if (act) out.action = act;
                if (m.authorKind === "user" || m.authorKind === "char") out.authorKind = m.authorKind;
                const dn = String(m.displayName || "").trim();
                if (dn) out.displayName = dn.slice(0, 64);
                if (m.hasImages === true) out.hasImages = true;
                if (m.usedCharChatImage === true) out.usedCharChatImage = true;
                const subImgCid = String(m.sourceImageSubjectCharId || "").trim();
                if (subImgCid) out.sourceImageSubjectCharId = subImgCid;
                if (m.sourceChatImageRole === "assistant" || m.sourceChatImageRole === "user") {
                  out.sourceChatImageRole = m.sourceChatImageRole;
                }
                const srcIdx = Number(m.sourceChatMsgIdx);
                if (Number.isFinite(srcIdx) && srcIdx >= 0) out.sourceChatMsgIdx = Math.floor(srcIdx);
                const momentId = String(m.momentId || "").trim();
                if (momentId) out.momentId = momentId;
                const content = String(m.content || "").trim();
                if (content) out.content = content.slice(0, 500);
                return out;
              }
              return m;
            })
        : [];
      let updatedAt = Number(t?.updatedAt);
      if (!Number.isFinite(updatedAt)) {
        const bubbleMsgs = messages.filter((m) => m.role === "user" || m.role === "assistant");
        const lastAt = bubbleMsgs.length ? Number(bubbleMsgs[bubbleMsgs.length - 1]?.at) : NaN;
        updatedAt = Number.isFinite(lastAt) ? lastAt : Date.now();
      }
      const base = { id, charId, messages, updatedAt, kind };
      if (t?.messagesStore === "split" || t?.messagesStore === (window.XXJ_DB && window.XXJ_DB.CHAT_MSGS_SPLIT_MARK)) {
        base.messagesStore = "split";
        const mc = Number(t.messageCount);
        base.messageCount =
          Number.isFinite(mc) && mc > 0 ? Math.floor(mc) : messages.length;
      }
      if (t && t.pinned === true) base.pinned = true;
      if (Object.prototype.hasOwnProperty.call(t || {}, "scenePrompt") && t.scenePrompt != null) {
        base.scenePrompt = String(t.scenePrompt);
      }
      const charNote = String(t?.charThreadNote ?? "").trim();
      if (charNote) base.charThreadNote = charNote.slice(0, 4000);
      const linkedGroup = String(t?.linkedGroupThreadId ?? "").trim();
      if (linkedGroup) base.linkedGroupThreadId = linkedGroup.slice(0, 120);
      const crn = String(t?.charThreadRemarkName ?? "").trim();
      if (crn) base.charThreadRemarkName = crn.slice(0, 32);
      const crfu = String(t?.charRemarkForUser ?? "").trim();
      if (crfu) base.charRemarkForUser = crfu.slice(0, 32);
      const crfur = String(t?.charRemarkForUserReason ?? "").trim();
      if (crfur) base.charRemarkForUserReason = crfur.slice(0, 2000);
      if (t && t.userBlockedChar === true) base.userBlockedChar = true;
      if (t && t.charBlockedUser === true) base.charBlockedUser = true;
      const memR = Number(t?.memoryUserRounds);
      if (Number.isFinite(memR) && memR > 0) {
        base.memoryUserRounds = Math.floor(memR);
      }
      const memMode = getThreadChatMemoryMode(t);
      base.chatMemoryMode = memMode;
      if (memMode === "summary") {
        const memoTail = Number(t?.memoSummaryRawTail);
        if (Number.isFinite(memoTail) && memoTail > 0) {
          base.memoSummaryRawTail = Math.min(CHAT_MEMO_SUMMARY_RAW_TAIL_MAX, Math.floor(memoTail));
        }
      }
      const memSum = normalizeCharThreadMemorySummariesArray(t?.charThreadMemorySummaries);
      if (memSum.length) base.charThreadMemorySummaries = memSum;
      const emoMem = normalizeCharThreadEmotionalMemoriesArray(t?.charThreadEmotionalMemories);
      if (emoMem.length) base.charThreadEmotionalMemories = emoMem;
      const masU = Number(t?.memoAutoSummaryEveryUser);
      if (Number.isFinite(masU) && masU > 0) {
        base.memoAutoSummaryEveryUser = Math.min(CHAT_MEMO_AUTO_LOG_EVERY_MAX, Math.floor(masU));
      }
      const masL = Number(t?.memoAutoSummaryLastUserCount);
      if (Number.isFinite(masL) && masL >= 0) {
        base.memoAutoSummaryLastUserCount = Math.floor(masL);
      }
      const mex = Number(t?.memoManualSummaryExclusiveEndLogIdx);
      if (Number.isFinite(mex) && mex >= 0) {
        base.memoManualSummaryExclusiveEndLogIdx = Math.floor(mex);
      }
      const mrg = Number(t?.memoAutoMergeEverySummaries);
      if (Number.isFinite(mrg) && mrg >= 2) {
        base.memoAutoMergeEverySummaries = Math.min(CHAT_MEMO_SUMMARY_MAX, Math.floor(mrg));
      }
      const msep = String(t?.memoAutoSummaryExtraPrompt ?? "").trim();
      if (msep) base.memoAutoSummaryExtraPrompt = msep.slice(0, CHAT_MEMO_EXTRA_PROMPT_MAX);
      const mmep = String(t?.memoAutoMergeExtraPrompt ?? "").trim();
      if (mmep) base.memoAutoMergeExtraPrompt = mmep.slice(0, CHAT_MEMO_EXTRA_PROMPT_MAX);
      const rolled = String(t?.charThreadMemoryRolled ?? "").trim();
      if (rolled) base.charThreadMemoryRolled = rolled.slice(0, 4000);
      const wbIdsSrc = Array.isArray(t?.worldBookVolumeIds) ? t.worldBookVolumeIds : [];
      const wbIds = wbIdsSrc
        .map((x) => String(x || "").trim())
        .filter(Boolean)
        .slice(0, 8);
      const wbLegacy = String(t?.worldBookVolumeId || "").trim();
      if (wbIds.length) base.worldBookVolumeIds = wbIds;
      else if (wbLegacy) base.worldBookVolumeIds = [wbLegacy];
      // 旧字段保留读取兼容，但新逻辑统一写入 worldBookVolumeIds
      if (wbLegacy) base.worldBookVolumeId = wbLegacy;
      const offlineWbIds = getThreadOfflineWorldBookVolumeIds(t);
      if (offlineWbIds.length) base.offlineWorldBookVolumeIds = offlineWbIds;
      if (t && t.heartVoiceEnabled === false) base.heartVoiceEnabled = false;
      if (kind !== "group") {
        const pace = String(t?.chatImHumanPace ?? "").trim();
        if (pace === "R" || pace === "S" || pace === "off") base.chatImHumanPace = pace;
      }
      const packOv = normalizeChatPromptPackId(t?.chatPromptPack);
      if (packOv) base.chatPromptPack = packOv;
      if (t && t.charTranslationEnabled === true) base.charTranslationEnabled = true;
      if (t && t.groupTranslationEnabled === true) base.groupTranslationEnabled = true;
      const gTrTone = String(t?.groupTranslationTone || "").trim();
      if (gTrTone === "literal" || gTrTone === "colloquial") base.groupTranslationTone = gTrTone;
      const gTrLang = String(t?.groupTranslationTargetLang || "").trim();
      if (gTrLang) base.groupTranslationTargetLang = gTrLang.slice(0, 40);
      if (t && t.timeAwareEnabled === true) base.timeAwareEnabled = true;
      if (t && t.chatTimestampsHidden === true) base.chatTimestampsHidden = true;
      if (t && t.narratorModeEnabled === true) base.narratorModeEnabled = true;
      const narratorDensity = String(t?.narratorDensity || "").trim();
      if (narratorDensity === "light" || narratorDensity === "rich") base.narratorDensity = narratorDensity;
      if (t && t.narratorIncludeInner === false) base.narratorIncludeInner = false;
      const narratorFontPx = Number(t?.narratorFontPx);
      if (Number.isFinite(narratorFontPx)) {
        const fp = Math.max(12, Math.min(20, Math.round(narratorFontPx)));
        if (fp !== 14) base.narratorFontPx = fp;
      }
      const narratorLh = Number(t?.narratorLineHeight);
      if (Number.isFinite(narratorLh)) {
        const lh = Math.max(1.25, Math.min(2.1, Math.round(narratorLh * 100) / 100));
        if (Math.abs(lh - 1.65) > 0.001) base.narratorLineHeight = lh;
      }
      const offlineDmProseStyle = String(t?.offlineDmProseStyle || "").trim();
      if (offlineDmProseStyle === "sparse" || offlineDmProseStyle === "literary" || offlineDmProseStyle === "playful") {
        base.offlineDmProseStyle = offlineDmProseStyle;
      }
      const offlineDmLength = String(t?.offlineDmLength || "").trim();
      if (offlineDmLength === "short" || offlineDmLength === "long" || offlineDmLength === "xlarge") {
        base.offlineDmLength = offlineDmLength;
      }
      const { charPov, userPov } = resolveThreadOfflineDmCharUserPov(t);
      if (charPov !== OFFLINE_DM_DEFAULT_CHAR_POV) base.offlineDmCharPov = charPov;
      if (userPov !== OFFLINE_DM_DEFAULT_USER_POV) base.offlineDmUserPov = userPov;
      const offlineDmPov = String(t?.offlineDmPov || "").trim();
      if (offlineDmPov === "mixed_narrator" || offlineDmPov === "immersive_you") base.offlineDmPov = offlineDmPov;
      const offlineDmProseStyleText = sliceOfflineDmCustomField(t?.offlineDmProseStyleText);
      if (offlineDmProseStyleText) base.offlineDmProseStyleText = offlineDmProseStyleText;
      const offlineDmLengthText = sliceOfflineDmCustomField(t?.offlineDmLengthText);
      if (offlineDmLengthText) base.offlineDmLengthText = offlineDmLengthText;
      const offlineDmPovText = sliceOfflineDmCustomField(t?.offlineDmPovText);
      if (offlineDmPovText) base.offlineDmPovText = offlineDmPovText;
      if (kind !== "group" && t && t.charProactiveEnabled === true) base.charProactiveEnabled = true;
      if (kind !== "group" && t && t.charReverseSnoopEnabled === true) base.charReverseSnoopEnabled = true;
      if (kind !== "group" && t && t.charProactiveAutoMode === true) base.charProactiveAutoMode = true;
      if (kind !== "group") {
        const sec = Number(t?.charProactiveIntervalSec);
        if (Number.isFinite(sec) && sec >= 0) {
          base.charProactiveIntervalSec = Math.floor(sec);
        }
      }
      if (kind !== "group" && t && t.charMomentsProactiveEnabled === true) {
        base.charMomentsProactiveEnabled = true;
      }
      if (kind !== "group" && base.charMomentsProactiveEnabled && t && t.charMomentsProactiveAutoMode === true) {
        base.charMomentsProactiveAutoMode = true;
      }
      if (kind !== "group") {
        const msec = Number(t?.charMomentsProactiveIntervalSec);
        if (Number.isFinite(msec) && msec >= 60) {
          base.charMomentsProactiveIntervalSec = Math.min(86400, Math.floor(msec));
        }
        const mlast = String(t?.charMomentsProactiveLastAt || "").trim();
        if (mlast) base.charMomentsProactiveLastAt = mlast.slice(0, 40);
      }
      if (kind !== "group" && t && t.charLockPhoneEnabled === true) base.charLockPhoneEnabled = true;
      if (kind !== "group" && t && t.autoOfflineEnabled === false) base.autoOfflineEnabled = false;
      if (kind !== "group") {
        const meetMode = String(t?.offlineMeetMode || "").trim();
        if (meetMode === "summary") base.offlineMeetMode = "summary";
      }
      const tone = String(t?.charTranslationTone || "").trim();
      if (tone === "literal" || tone === "colloquial") base.charTranslationTone = tone;
      const tlang = String(t?.charTranslationTargetLang || "").trim();
      if (tlang) base.charTranslationTargetLang = tlang.slice(0, 40);
      const heroBg = t && typeof t.chatHeroBgImage === "string" ? String(t.chatHeroBgImage).trim() : "";
      if (heroBg && heroBg.length <= 3_500_000) base.chatHeroBgImage = heroBg;
      const threadUserAv =
        t && typeof t.chatThreadUserAvatar === "string" ? String(t.chatThreadUserAvatar).trim() : "";
      if (threadUserAv && threadUserAv.length <= 3_500_000) base.chatThreadUserAvatar = threadUserAv;
      const threadCharAv =
        t && typeof t.chatThreadCharAvatar === "string" ? String(t.chatThreadCharAvatar).trim() : "";
      if (threadCharAv && threadCharAv.length <= 3_500_000) base.chatThreadCharAvatar = threadCharAv;
      const bodyBg = t && typeof t.chatBodyBgImage === "string" ? String(t.chatBodyBgImage).trim() : "";
      if (bodyBg && bodyBg.length <= 3_500_000) base.chatBodyBgImage = bodyBg;
      const offlineBg = t && typeof t.chatOfflineBgImage === "string" ? String(t.chatOfflineBgImage).trim() : "";
      if (offlineBg && offlineBg.length <= 3_500_000) base.chatOfflineBgImage = offlineBg;
      if (t && t.chatMessagesBgFullBleed === true) base.chatMessagesBgFullBleed = true;
      if (t && t.chatHeroBgFullBleed === true) base.chatHeroBgFullBleed = true;
      if (t && t.stickerSuggestEnabled === false) base.stickerSuggestEnabled = false;
      const sbc = String(t?.stickerBindCategory || "").trim();
      const sbcsRaw = Array.isArray(t?.stickerBindCategories) ? t.stickerBindCategories : [];
      const sbcs = sbcsRaw
        .map((x) => String(x || "").trim().slice(0, 20))
        .filter(Boolean)
        .slice(0, 12);
      if (sbcs.length) base.stickerBindCategories = sbcs;
      else if (sbc) base.stickerBindCategories = [sbc.slice(0, 20)];
      const cardBg = t && typeof t.chatIdentityPanelBgImage === "string" ? String(t.chatIdentityPanelBgImage).trim() : "";
      if (cardBg && cardBg.length <= 3_500_000) base.chatIdentityPanelBgImage = cardBg;
      const compBg = t && typeof t.chatComposerBgImage === "string" ? String(t.chatComposerBgImage).trim() : "";
      if (compBg && compBg.length <= 3_500_000) base.chatComposerBgImage = compBg;
      const threadUiPid = String(t?.threadUiCssPresetId || "").trim();
      if (threadUiPid) base.threadUiCssPresetId = threadUiPid.slice(0, 240);
      const offlineThreadUiPid = String(t?.offlineThreadUiCssPresetId || "").trim();
      if (offlineThreadUiPid) base.offlineThreadUiCssPresetId = offlineThreadUiPid.slice(0, 240);
      const chatImgRef = t && typeof t.chatImageRefDataUrl === "string" ? String(t.chatImageRefDataUrl).trim() : "";
      if (chatImgRef && chatImgRef.length <= 3_500_000) base.chatImageRefDataUrl = chatImgRef;
      if (kind !== "group") {
        if (t && t.chatThreadImageEveryRound === true) base.chatThreadImageEveryRound = true;
        if (t && t.chatThreadOfflineImageEveryRound === true) base.chatThreadOfflineImageEveryRound = true;
        if (t && t.chatOfflineStreamReply === true) base.chatOfflineStreamReply = true;
        if (t && t.chatThreadDescImageApiGen === false) base.chatThreadDescImageApiGen = false;
        const imgStylePid = String(t?.chatThreadImageStylePresetId || "").trim();
        if (imgStylePid) base.chatThreadImageStylePresetId = imgStylePid.slice(0, 240);
        const imgStyleCustom = String(t?.chatThreadImageStylePromptCustom || "").trim();
        if (imgStyleCustom) base.chatThreadImageStylePromptCustom = imgStyleCustom.slice(0, 2000);
        const charImgPrompt = String(t?.chatThreadCharImagePrompt || "").trim();
        if (charImgPrompt) base.chatThreadCharImagePrompt = charImgPrompt.slice(0, 2000);
        const offImgStylePid = String(t?.chatThreadOfflineImageStylePresetId || "").trim();
        if (offImgStylePid) base.chatThreadOfflineImageStylePresetId = offImgStylePid.slice(0, 240);
        const offImgStyleCustom = String(t?.chatThreadOfflineImageStylePromptCustom || "").trim();
        if (offImgStyleCustom) base.chatThreadOfflineImageStylePromptCustom = offImgStyleCustom.slice(0, 2000);
      }
      if (kind === "group") {
        const gt = String(t?.groupTitle || "").trim();
        const primary = String(t?.charId || "").trim();
        const rawMembers = Array.isArray(t?.memberCharIds) ? t.memberCharIds : [];
        const memberCharIds = [];
        const seenM = new Set();
        for (const x of rawMembers) {
          const mid = String(x || "").trim();
          if (!mid || seenM.has(mid)) continue;
          seenM.add(mid);
          memberCharIds.push(mid);
        }
        if (primary && !seenM.has(primary)) memberCharIds.unshift(primary);
        if (!memberCharIds.length && primary) memberCharIds.push(primary);
        const gNote = String(t?.groupThreadNote ?? "").trim();
        const out = {
          ...base,
          groupTitle: gt || "群聊",
          memberCharIds: memberCharIds.slice(0, 8),
          heartVoiceEnabled: false
        };
        if (t && t.groupTranslationEnabled === true) out.groupTranslationEnabled = true;
        const gTrTone = String(t?.groupTranslationTone || "").trim();
        if (gTrTone === "literal" || gTrTone === "colloquial") out.groupTranslationTone = gTrTone;
        const gTrLang = String(t?.groupTranslationTargetLang || "").trim();
        if (gTrLang) out.groupTranslationTargetLang = gTrLang.slice(0, 40);
        if (gNote) out.groupThreadNote = gNote.slice(0, 4000);
        if (t && t.chatThreadDescImageApiGen === false) out.chatThreadDescImageApiGen = false;
        const mn = t?.memberNotes;
        if (mn && typeof mn === "object" && !Array.isArray(mn)) {
          const notes = Object.create(null);
          for (const [k, v] of Object.entries(mn)) {
            const cid = String(k || "").trim();
            const txt = String(v || "").trim();
            if (cid && txt) notes[cid] = txt.slice(0, 2000);
          }
          if (Object.keys(notes).length) out.memberNotes = notes;
        }
        const mdm = t?.memberDmThreadIds;
        if (mdm && typeof mdm === "object" && !Array.isArray(mdm)) {
          const dmMap = Object.create(null);
          const memberSet = new Set(memberCharIds);
          for (const [k, v] of Object.entries(mdm)) {
            const key = String(k || "").trim();
            const val = String(v || "").trim();
            if (key && val && memberSet.has(key)) dmMap[key] = val.slice(0, 120);
          }
          if (Object.keys(dmMap).length) out.memberDmThreadIds = dmMap;
        }
        const gn = t?.groupNicknames;
        if (gn && typeof gn === "object" && !Array.isArray(gn)) {
          const nickMap = Object.create(null);
          const memberSet = new Set(memberCharIds);
          memberSet.add("__user__");
          for (const [k, v] of Object.entries(gn)) {
            const key = String(k || "").trim();
            const nick = String(v || "").trim().slice(0, 20);
            if (!key || !nick) continue;
            if (key !== "__user__" && !memberSet.has(key)) continue;
            nickMap[key] = nick;
          }
          if (Object.keys(nickMap).length) out.groupNicknames = nickMap;
        }
        return out;
      }
      return base;
    });
    const moments = Array.isArray(v?.moments)
      ? v.moments.filter((m) => m && typeof m === "object")
      : [];
    const profileDecor = normalizeProfileDecor(v?.profileDecor);
    const momentsProfileBio = normalizeMomentsProfileBio(v?.momentsProfileBio);
    byMask[k] = { threads, moments, profileDecor, momentsProfileBio };
  }
  return { v: CHAT_INBOX_V, byMask };
}

/** 避免每次 readChatInboxStore 都全量 normalize 全部密谈消息（会卡住页面过场） */
let chatInboxMemCache = null;
/** 合并同帧内多次聊天记录写入，避免连打 saveChatLog 时重复落盘 */
function emptyChatInboxStore() {
  return { v: CHAT_INBOX_V, byMask: {} };
}

/** @param {unknown} store */
function chatInboxStoreMessageCount(store) {
  if (!store || typeof store !== "object") return 0;
  const byMask = /** @type {{ byMask?: Record<string, unknown> }} */ (store).byMask;
  if (!byMask || typeof byMask !== "object") return 0;
  let n = 0;
  for (const b of Object.values(byMask)) {
    if (!b || typeof b !== "object") continue;
    const threads = /** @type {{ threads?: unknown[] }} */ (b).threads;
    if (!Array.isArray(threads)) continue;
    for (const t of threads) {
      if (!t || typeof t !== "object") continue;
      const row = /** @type {{ messages?: unknown[], messagesStore?: string, messageCount?: number }} */ (t);
      if (Array.isArray(row.messages) && row.messages.length > 0) n += row.messages.length;
      else if (row.messagesStore === "split" || row.messagesStore === (window.XXJ_DB && window.XXJ_DB.CHAT_MSGS_SPLIT_MARK)) {
        const mc = Number(row.messageCount);
        if (Number.isFinite(mc) && mc > 0) n += Math.floor(mc);
      }
    }
  }
  return n;
}

/** @param {object|undefined} a @param {object|undefined} b */
function pickRicherChatThread(a, b) {
  if (!a) return b;
  if (!b) return a;
  const am = Array.isArray(a.messages)
    ? a.messages.length
    : a.messagesStore === "split" && Number(a.messageCount) > 0
      ? Number(a.messageCount)
      : 0;
  const bm = Array.isArray(b.messages)
    ? b.messages.length
    : b.messagesStore === "split" && Number(b.messageCount) > 0
      ? Number(b.messageCount)
      : 0;
  const au = Number(a.updatedAt) || 0;
  const bu = Number(b.updatedAt) || 0;
  if (bm > am) return b;
  if (am > bm) return a;
  return bu >= au ? b : a;
}

/** inbox 未灌入前 overlay 上的改动并入已加载的库，避免空 store 覆盖 IndexedDB */
function mergeChatInboxStores(base, overlay) {
  const merged = normalizeChatInboxStore(base);
  const ov =
    overlay && typeof overlay === "object" && overlay.v === CHAT_INBOX_V ? overlay : { v: CHAT_INBOX_V, byMask: {} };
  const ob = ov.byMask && typeof ov.byMask === "object" ? ov.byMask : {};
  for (const [mk, oBucket] of Object.entries(ob)) {
    if (!oBucket || typeof oBucket !== "object") continue;
    const key = String(mk);
    if (!merged.byMask[key]) {
      merged.byMask[key] = {
        threads: Array.isArray(oBucket.threads) ? oBucket.threads.slice() : [],
        moments: Array.isArray(oBucket.moments) ? oBucket.moments.slice() : [],
        profileDecor: normalizeProfileDecor(oBucket.profileDecor),
        momentsProfileBio: normalizeMomentsProfileBio(oBucket.momentsProfileBio)
      };
      continue;
    }
    const bucket = merged.byMask[key];
    const tMap = new Map();
    for (const t of bucket.threads || []) {
      if (t && t.id) tMap.set(String(t.id), t);
    }
    for (const t of oBucket.threads || []) {
      if (!t || !t.id) continue;
      const id = String(t.id);
      tMap.set(id, pickRicherChatThread(tMap.get(id), t));
    }
    bucket.threads = Array.from(tMap.values());
    const mMap = new Map();
    for (const m of bucket.moments || []) {
      if (m && m.id) mMap.set(String(m.id), m);
    }
    for (const m of oBucket.moments || []) {
      if (!m || !m.id) continue;
      const id = String(m.id);
      const prev = mMap.get(id);
      if (!prev) mMap.set(id, m);
      else {
        const pt = Date.parse(String(prev.timeIso || ""));
        const ot = Date.parse(String(m.timeIso || ""));
        if (!Number.isFinite(pt) || ot >= pt) mMap.set(id, m);
      }
    }
    bucket.moments = Array.from(mMap.values());
    if (oBucket.momentsProfileBio) {
      bucket.momentsProfileBio = normalizeMomentsProfileBio(oBucket.momentsProfileBio);
    }
    if (Array.isArray(oBucket.profileDecor) && oBucket.profileDecor.length) {
      const baseDecor = normalizeProfileDecor(bucket.profileDecor);
      const overlayDecor = normalizeProfileDecor(oBucket.profileDecor);
      bucket.profileDecor = baseDecor.map((v, i) => {
        const o = String(overlayDecor[i] || "").trim();
        return o || v;
      });
    }
  }
  return normalizeChatInboxStore(merged);
}

/** inbox 未灌入时先 lazy 读 IndexedDB（iOS 启动不预载 inbox，勿误用 inboxReady） */
function ensureInboxDbReady() {
  const D = window.XXJ_DB;
  if (!D) return Promise.resolve();
  if (D.isInboxHydrated) return Promise.resolve();
  if (typeof D.ensureInboxHydrated === "function") {
    return Promise.resolve(D.ensureInboxHydrated());
  }
  return Promise.resolve(D.inboxReady);
}

/** 密谈 inbox 写入 IndexedDB（优先立即 put，避免仅排队后刷新丢失） */
function persistInboxToIndexedDb(store, opts) {
  const D = window.XXJ_DB;
  if (!D || !store) return Promise.resolve();
  if (!D.isInboxHydrated) {
    return ensureInboxDbReady().then(() => persistInboxToIndexedDb(store, opts));
  }
  const prevN = chatInboxStoreMessageCount(D.getKv(D.K.CHAT_INBOX_STORE));
  const nextN = chatInboxStoreMessageCount(store);
  if (nextN === 0 && !opts?.allowEmpty) {
    if (prevN > 0) console.warn("XXJ: refused to persist empty chat inbox");
    return Promise.resolve();
  }
  return D.persistChatInboxNow(store, opts)
    .then(() => {
      const th = readActiveThread();
      if (
        th &&
        (isChatImageBlobRef(th.chatHeroBgImage) ||
          isChatImageBlobRef(th.chatBodyBgImage) ||
          isChatImageBlobRef(th.chatOfflineBgImage) ||
          isChatImageBlobRef(th.chatIdentityPanelBgImage) ||
          isChatImageBlobRef(th.chatComposerBgImage) ||
          isChatImageBlobRef(th.chatThreadUserAvatar) ||
          isChatImageBlobRef(th.chatThreadCharAvatar))
      ) {
        chatThreadSurfaceBgAppliedKey = "";
        applyChatThreadSurfaceBackgrounds();
        updateChatHeaderFaces();
        scheduleRenderChatMessages();
      }
    })
    .catch((err) => {
      console.warn("XXJ: persistChatInboxNow failed", err);
      if (opts && opts.propagateError) throw err;
    });
}

/** iOS PWA：即时串行落盘，避免强杀时会话仍在队列里 */
let iosInboxPersistTail = Promise.resolve();
let chatInboxFastPersistTimer = 0;
/** @type {{ store: object, opts?: object } | null} */
let chatInboxFastPersistPending = null;

function flushChatInboxFastPersistPendingNow() {
  window.clearTimeout(chatInboxFastPersistTimer);
  chatInboxFastPersistTimer = 0;
  const pending = chatInboxFastPersistPending;
  chatInboxFastPersistPending = null;
  if (!pending) return Promise.resolve();
  return persistInboxToIndexedDb(pending.store, pending.opts);
}

function schedulePersistInboxToIndexedDb(store, opts) {
  if (opts && opts.deferPersist) return Promise.resolve();
  const fast = Boolean(opts && opts.fast && !opts.force);
  if (fast) {
    chatInboxFastPersistPending = { store, opts };
    if (!chatInboxFastPersistTimer) {
      chatInboxFastPersistTimer = window.setTimeout(() => {
        chatInboxFastPersistTimer = 0;
        void flushChatInboxFastPersistPendingNow();
      }, 900);
    }
    return Promise.resolve();
  }
  void flushChatInboxFastPersistPendingNow();
  if (!isLikelyIosWebKit()) {
    return persistInboxToIndexedDb(store, opts);
  }
  iosInboxPersistTail = iosInboxPersistTail
    .catch(() => {})
    .then(() => persistInboxToIndexedDb(store, opts));
  return iosInboxPersistTail;
}

function flushChatInboxKvPersist(opts) {
  const D = window.XXJ_DB;
  const s =
    chatInboxMemCache ||
    (D && D.isInboxHydrated ? D.getKv(D.K.CHAT_INBOX_STORE) : null);
  if (!D || !s) return Promise.resolve();
  if (!D.isInboxHydrated) {
    return ensureInboxDbReady().then(() => flushChatInboxKvPersist(opts));
  }
  const prevN = chatInboxStoreMessageCount(D.getKv(D.K.CHAT_INBOX_STORE));
  const nextN = chatInboxStoreMessageCount(s);
  if (nextN === 0 && !opts?.allowEmpty) {
    if (prevN > 0) {
      console.warn("XXJ: refused to persist empty chat inbox over existing data");
    }
    return Promise.resolve();
  }
  return persistInboxToIndexedDb(s, opts);
}

async function flushAllAppDataBeforeUnload() {
  try {
    if (isLikelyIosWebKit()) {
      await iosInboxPersistTail;
    }
    await flushChatInboxFastPersistPendingNow();
    await flushChatInboxKvPersist({ force: true });
  } catch (err) {
    console.warn("[persist] inbox flush failed", err);
  }
  const D = window.XXJ_DB;
  if (D && typeof D.flushAllKvNow === "function") {
    try {
      await D.flushAllKvNow();
    } catch (err) {
      console.warn("[persist] kv flush failed", err);
    }
  }
}

if (typeof window !== "undefined") {
  window.addEventListener("pagehide", () => {
    void flushAllAppDataBeforeUnload();
  }, { capture: true });
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "hidden") {
      void flushAllAppDataBeforeUnload();
    }
  });
}

(function setupIosPeriodicInboxFlush() {
  if (typeof isLikelyIosWebKit === "function" && !isLikelyIosWebKit()) return;
  if (!/iPhone|iPad|iPod/i.test(navigator.userAgent || "")) return;
  const INTERVAL = 10_000;
  setInterval(async () => {
    try {
      await flushChatInboxKvPersist({ force: true });
    } catch (e) {
      console.warn("[ios-flush] periodic flush failed", e);
    }
  }, INTERVAL);
})();

function invalidateChatInboxMemCache(opts) {
  const dropOnly = Boolean(opts && opts.dropOnly);
  if (!dropOnly) flushChatInboxKvPersist();
  chatInboxMemCache = null;
  legacySampleMomentsPurged = false;
  invalidateChatLogViewCache();
}

/**
 * @param {object} store
 * @param {{ fast?: boolean, dirtyThreadKey?: string, force?: boolean, allowEmpty?: boolean, deferPersist?: boolean }} [opts]
 *   fast：跳过全量 normalize；dirtyThreadKey 保留兼容；deferPersist：仅更新内存（等防抖落盘）
 */
function writeChatInboxStore(store, opts) {
  const D = window.XXJ_DB;
  if (!D || !D.isReady) return;
  const runWrite = () => {
    const prevN = chatInboxStoreMessageCount(D.getKv(D.K.CHAT_INBOX_STORE));
    const useFast =
      opts?.fast === true || (opts?.fast !== false && chatInboxMemCache && store === chatInboxMemCache);
    if (useFast) {
      const nextN = chatInboxStoreMessageCount(store);
      if (nextN === 0 && !opts?.allowEmpty) {
        if (prevN > 0) console.warn("XXJ: refused fast write of empty chat inbox");
        return;
      }
      chatInboxMemCache = store;
      if (typeof D.setMemKv === "function") {
        D.setMemKv(D.K.CHAT_INBOX_STORE, store);
      } else {
        D.setKv(D.K.CHAT_INBOX_STORE, store);
      }
      void schedulePersistInboxToIndexedDb(store, opts);
      return;
    }
    const norm = normalizeChatInboxStore(store);
    const nextN = chatInboxStoreMessageCount(norm);
    if (nextN === 0 && !opts?.allowEmpty) {
      if (prevN > 0) console.warn("XXJ: refused write of empty chat inbox");
      return;
    }
    chatInboxMemCache = norm;
    void schedulePersistInboxToIndexedDb(norm, opts);
  };
  if (!D.isInboxHydrated) {
    const pendingStore = store;
    const pendingOpts = opts;
    void ensureInboxDbReady().then(() => {
      const base = warmChatInboxMemCacheFromDb();
      const baseN = chatInboxStoreMessageCount(base);
      const overlayN = chatInboxStoreMessageCount(pendingStore);
      if (overlayN === 0 && baseN > 0) return;
      writeChatInboxStore(mergeChatInboxStores(base, pendingStore), pendingOpts);
    });
    return;
  }
  runWrite();
}

/** 删除面具后清掉该面具下的密谈 / 朋友圈桶，避免 IndexedDB 里残留孤儿数据 */
function pruneChatInboxBucketForMask(maskId) {
  const D = window.XXJ_DB;
  if (!D) return;
  const key = maskBucketKey(maskId);
  const inbox = readChatInboxStore();
  if (inbox.byMask && Object.prototype.hasOwnProperty.call(inbox.byMask, key)) {
    delete inbox.byMask[key];
    writeChatInboxStore(inbox);
  }
}

function migrateLegacyChatIntoInbox(D, partialRaw) {
  const legacy = D.getKv(D.K.CHAT_LOG);
  const um = D.getKv(D.K.USER_MASK_STORE);
  const ch = D.getKv(D.K.CHAR_PERSONA_STORE);

  let maskId = "";
  if (um && um.v === 2 && Array.isArray(um.items) && um.items.length) {
    const aid = String(um.activeId || "");
    maskId = aid && um.items.some((x) => x.id === aid) ? aid : um.items[0].id;
  }

  let charId = "";
  if (ch && ch.v === 2 && Array.isArray(ch.items) && ch.items.length) {
    const aid = String(ch.activeId || "");
    charId = aid && ch.items.some((x) => x.id === aid) ? aid : ch.items[0].id;
  }

  const key = maskBucketKey(maskId);
  const byMask =
    partialRaw && partialRaw.v === CHAT_INBOX_V && partialRaw.byMask && typeof partialRaw.byMask === "object"
      ? { ...partialRaw.byMask }
      : {};

  if (!byMask[key]) {
    const msgs = Array.isArray(legacy)
      ? legacy.filter(
          (m) => m && typeof m === "object" && (m.role === "user" || m.role === "assistant")
        )
      : [];
    const threads = [];
    if (msgs.length) {
      threads.push({
        id: newEntityId(),
        charId: String(charId || ""),
        messages: msgs.slice(),
        updatedAt: Date.now()
      });
    }
    byMask[key] = {
      threads,
      moments: [],
      profileDecor: normalizeProfileDecor([]),
      momentsProfileBio: ""
    };
  } else {
    const b = byMask[key];
    if (!Array.isArray(b.threads)) b.threads = [];
    if (!Array.isArray(b.moments)) b.moments = [];
    if (!Array.isArray(b.profileDecor)) {
      b.profileDecor = normalizeProfileDecor([]);
    }
  }

  const next = { v: CHAT_INBOX_V, byMask };
  const hadValidPartial =
    partialRaw && partialRaw.v === CHAT_INBOX_V && partialRaw.byMask && typeof partialRaw.byMask === "object";
  const hadLegacyMsgs =
    Array.isArray(legacy) &&
    legacy.some((m) => m && typeof m === "object" && (m.role === "user" || m.role === "assistant"));
  const hasAnyMessages = Object.values(byMask).some(
    (b) => b && Array.isArray(b.threads) && b.threads.some((t) => Array.isArray(t.messages) && t.messages.length)
  );
  if (!D.isReady) return next;
  if (hadValidPartial || hadLegacyMsgs || hasAnyMessages) {
    D.setKv(D.K.CHAT_INBOX_STORE, next);
    if (legacy !== undefined) D.delKv(D.K.CHAT_LOG);
  }
  return next;
}

function readChatInboxStore() {
  const D = window.XXJ_DB;
  if (!D) return emptyChatInboxStore();
  if (!D.isReady) return emptyChatInboxStore();
  if (chatInboxMemCache) return chatInboxMemCache;
  if (!D.isInboxHydrated) return emptyChatInboxStore();
  return warmChatInboxMemCacheFromDb();
}

/** 从 DB 灌入 inbox 内存缓存（全量 normalize 仅执行一次） */
function warmChatInboxMemCacheFromDb() {
  if (chatInboxMemCache) return chatInboxMemCache;
  const D = window.XXJ_DB;
  if (!D || !D.isReady) return emptyChatInboxStore();
  if (!D.isInboxHydrated) return emptyChatInboxStore();
  const raw = D.getKv(D.K.CHAT_INBOX_STORE);
  if (isTrustedChatInboxShape(raw)) {
    chatInboxMemCache = normalizeChatInboxStore(raw);
  } else {
    chatInboxMemCache = normalizeChatInboxStore(migrateLegacyChatIntoInbox(D, raw));
  }
  purgeLegacySampleMomentsOnce(chatInboxMemCache);
  return chatInboxMemCache;
}

/** 外部写入 inbox（ZIP 恢复等）后：丢弃旧 cache 并从 DB 重建 */
function rebuildChatInboxMemCacheFromDb() {
  invalidateChatInboxMemCache({ dropOnly: true });
  return warmChatInboxMemCacheFromDb();
}

/** 打开密谈 UI 前确保 inbox 已从 IndexedDB 灌入（启动后可能仍在后台加载） */
function ensureChatInboxForUi() {
  const D = window.XXJ_DB;
  if (!D) return Promise.resolve();
  if (chatInboxMemCache) return Promise.resolve();
  const load =
    !D.isInboxHydrated && typeof D.ensureInboxHydrated === "function"
      ? D.ensureInboxHydrated()
      : D.inboxReady && typeof D.inboxReady.then === "function"
        ? D.inboxReady
        : Promise.resolve();
  return Promise.resolve(load).then(() => {
    warmChatInboxMemCacheFromDb();
  });
}

function ensureMaskBucket(inbox, maskId) {
  const D = window.XXJ_DB;
  const key = maskBucketKey(maskId);
  let dirty = false;
  if (!inbox.byMask[key]) {
    inbox.byMask[key] = {
      threads: [],
      moments: [],
      profileDecor: normalizeProfileDecor([]),
      momentsProfileBio: ""
    };
    dirty = true;
  } else {
    const b = inbox.byMask[key];
    if (!Array.isArray(b.threads)) {
      b.threads = [];
      dirty = true;
    }
    if (!Array.isArray(b.moments)) {
      b.moments = [];
      dirty = true;
    }
    const decorNext = normalizeProfileDecor(b.profileDecor);
    if (
      !Array.isArray(b.profileDecor) ||
      decorNext.length !== MOMENTS_DECOR_SLOTS ||
      decorNext.some((x, i) => x !== String(b.profileDecor[i] || "").trim())
    ) {
      b.profileDecor = decorNext;
        dirty = true;
    }
    const bioNext = normalizeMomentsProfileBio(b.momentsProfileBio);
    if (String(b.momentsProfileBio || "") !== bioNext) {
      b.momentsProfileBio = bioNext;
      dirty = true;
    }
  }
  if (dirty && D && D.isInboxHydrated) writeChatInboxStore(inbox);
  return inbox.byMask[key];
}

/** 资料区装饰图格数（与发动态无关） */
const MOMENTS_DECOR_SLOTS = 3;
/** 单条动态内配图上限 */
const MOMENTS_POST_MAX_IMAGES = 9;
/** 单条评论正文上限（存储与输入框） */
const MOMENTS_COMMENT_MAX_LEN = 500;
/** 角色 AI 发朋友圈最多配图张数 */
const MOMENTS_CHAR_POST_MAX_IMAGES = 1;
/** 主控发动态后自动评/赞：每面具最多尝试人数（实际不超过单聊角色数） */
const MOMENTS_REACTOR_MAX = 5;
/** 有足够角色时至少尝试几人（角色数不足则全员） */
const MOMENTS_REACTOR_MIN = 3;
/** 自动评/赞：每个候选角色实际调用 AI 的概率（其余跳过以省 API） */
const MOMENTS_REACTOR_AI_CHANCE = 0.82;
/** 单次「邀请 NPC 评论」最多尝试人数 */
const MOMENTS_NPC_INVITE_MAX = 4;
/** 密谈提及朋友圈：只参考此时间窗内的动态（毫秒，默认 5 日） */
const MOMENTS_CHAT_RECENT_WINDOW_MS = 5 * 24 * 60 * 60 * 1000;
/** 密谈注入朋友圈近况：至少已有此条数 user/assistant 对白（避免刚开场就提） */
const MOMENTS_CHAT_DIGEST_MIN_DIALOGUE_ROWS = 6;

/** @param {ReturnType<typeof normalizeMoment> | null | undefined} mm */
function momentPostTimestampMs(mm) {
  const t = Date.parse(String(mm?.timeIso || ""));
  return Number.isFinite(t) ? t : 0;
}

/** @param {object | null | undefined} notice @param {ReturnType<typeof normalizeMoment> | null | undefined} [mm] */
function isMomentsFeedNoticeStaleForChat(notice, mm) {
  const now = Date.now();
  const maxAge = MOMENTS_CHAT_RECENT_WINDOW_MS;
  const postAt = momentPostTimestampMs(mm);
  if (postAt > 0 && now - postAt > maxAge) return true;
  const at = Number(notice?.at);
  if (Number.isFinite(at) && at > 0 && now - at > maxAge) return true;
  return false;
}

/** @param {string} maskId @param {string} threadId @param {number} [minRows] */
function chatThreadHasEnoughDialogueForMomentsRef(maskId, threadId, minRows = MOMENTS_CHAT_DIGEST_MIN_DIALOGUE_ROWS) {
  const mid = String(maskId || "").trim();
  const tid = String(threadId || "").trim();
  if (!mid || !tid) return false;
  const need = Math.max(2, Math.floor(Number(minRows) || MOMENTS_CHAT_DIGEST_MIN_DIALOGUE_ROWS));
  const log = readChatLogForMaskThread(mid, tid);
  let n = 0;
  for (let i = log.length - 1; i >= 0; i--) {
    const row = log[i];
    if (!row || (row.role !== "user" && row.role !== "assistant")) continue;
    if (row.charLockSessionOnly) continue;
    n++;
    if (n >= need) return true;
  }
  return false;
}

/** 旧版 buildDefaultMoments 注入的示例文案（从存量数据里剔除，仅迁移一次） */
const LEGACY_SAMPLE_MOMENT_TEXT_SNIPPETS = [
  "路过楼下猫咖，玻璃上全是雾气。没进去，贴着看了一会儿。",
  "今晚决定早睡（第一千次版）。咖啡买成半糖，将就喝完再睡。"
];

function isLegacySampleMoment(m) {
  if (!m || typeof m !== "object") return false;
  const t = String(m.text || "").trim();
  return LEGACY_SAMPLE_MOMENT_TEXT_SNIPPETS.some((s) => s === t);
}

/** @returns {boolean} 是否有条目被删掉 */
function stripLegacySampleMomentsInInbox(inbox) {
  if (!inbox?.byMask || typeof inbox.byMask !== "object") return false;
  let dirty = false;
  for (const b of Object.values(inbox.byMask)) {
    if (!b || !Array.isArray(b.moments) || !b.moments.length) continue;
    const next = b.moments.filter((m) => !isLegacySampleMoment(m));
    if (next.length !== b.moments.length) {
      b.moments = next;
      dirty = true;
    }
  }
  return dirty;
}

let legacySampleMomentsPurged = false;

function purgeLegacySampleMomentsOnce(inbox) {
  if (legacySampleMomentsPurged || !inbox) return inbox;
  legacySampleMomentsPurged = true;
  if (stripLegacySampleMomentsInInbox(inbox)) {
    writeChatInboxStore(inbox, { fast: true });
    invalidateChatLogViewCache();
  }
  return inbox;
}

/** 发动态弹窗内待发布的配图（data URL） */
let momentsComposeDraftImages = [];
let momentsComposeBusy = false;

let momentsDecorPickIdx = -1;
let momentsDecorBusy = false;
let profileDecorBlobMigrateScheduled = false;
let profileDecorBlobMigrationDone = false;

function normalizeProfileDecor(raw) {
  const src = Array.isArray(raw) ? raw : [];
  const out = [];
  for (let i = 0; i < MOMENTS_DECOR_SLOTS; i++) {
    out.push(String(src[i] || "").trim());
  }
  return out;
}

/** 朋友圈顶栏「写几句关于自己」：仅展示，不进主控面具 summary/persona 与聊天提示词 */
function normalizeMomentsProfileBio(raw) {
  return String(raw || "").trim().slice(0, 2000);
}

function getMomentsProfileBio() {
  const { bucket } = getActiveMomentsBucket();
  return normalizeMomentsProfileBio(bucket?.momentsProfileBio);
}

function setMomentsProfileBio(text) {
  const { inbox, maskId, bucket } = getActiveMomentsBucket();
  if (!maskId) return;
  bucket.momentsProfileBio = normalizeMomentsProfileBio(text);
  writeChatInboxStore(inbox);
}

let momentsInlineReply = { momentId: "", commentId: "" };

function normalizeMoment(raw) {
  const m = raw && typeof raw === "object" ? raw : {};
  const id = String(m.id || "").trim() || newEntityId();
  const kind = m.kind === "user" ? "user" : "char";
  const displayName = String(m.displayName || (kind === "user" ? "主控" : "未命名角色")).trim() || (kind === "user" ? "主控" : "未命名角色");
  const timeIso = String(m.timeIso || new Date().toISOString());
  const text = String(m.text || "");
  const imagesSrc = Array.isArray(m.images) ? m.images : [];
  const images = imagesSrc
    .map((x) => sanitizeMomentImageUrl(String(x || "").trim()))
    .filter(Boolean)
    .slice(0, MOMENTS_POST_MAX_IMAGES);
  const imageDescCardsSrc = Array.isArray(m.imageDescCards) ? m.imageDescCards : [];
  const imageDescCards = imageDescCardsSrc
    .map((x) => String(x || "").trim().slice(0, 500))
    .filter(Boolean)
    .slice(0, MOMENTS_POST_MAX_IMAGES);
  const likedByMe = m.likedByMe === true;
  const likeCount = Math.max(0, Math.floor(Number(m.likeCount) || 0));
  const shareCount = Math.max(0, Math.floor(Number(m.shareCount) || 0));
  const charId = kind === "char" ? String(m.charId || "").trim() : "";
  const threadId = kind === "char" ? String(m.threadId || "").trim() : "";
  const threadRemark = kind === "char" ? String(m.threadRemark || "").trim().slice(0, 32) : "";
  const cmtsSrc = Array.isArray(m.comments) ? m.comments : [];
  const comments = cmtsSrc
    .filter((c) => c && typeof c === "object")
    .map((c) => ({
      id: String(c.id || "").trim() || newEntityId(),
      authorKind:
        c.authorKind === "user" ? "user" : c.authorKind === "npc" ? "npc" : "char",
      authorName: String(
        c.authorName ||
          (c.authorKind === "user" ? "主控" : c.authorKind === "npc" ? "NPC" : "未命名角色")
      ).trim() || "—",
      timeIso: String(c.timeIso || new Date().toISOString()),
      text: String(c.text || "").slice(0, MOMENTS_COMMENT_MAX_LEN),
      replyToCommentId: c.replyToCommentId ? String(c.replyToCommentId) : ""
    }))
    .slice(0, 200);

  const changed =
    raw == null ||
    typeof raw !== "object" ||
    raw.id !== id ||
    raw.kind !== kind ||
    raw.displayName !== displayName ||
    raw.timeIso !== timeIso ||
    raw.text !== text ||
    raw.likedByMe !== likedByMe ||
    raw.likeCount !== likeCount ||
    raw.shareCount !== shareCount ||
    images.length !== imagesSrc.length ||
    images.some((u, i) => sanitizeMomentImageUrl(String(imagesSrc[i] || "").trim()) !== u) ||
    raw.imageDescCards !== imageDescCardsSrc ||
    raw.comments !== cmtsSrc ||
    (kind === "char" && String(raw.charId || "").trim() !== charId) ||
    (kind === "char" && String(raw.threadId || "").trim() !== threadId) ||
    (kind === "char" && String(raw.threadRemark || "").trim().slice(0, 32) !== threadRemark);
  if (!changed) return raw;
  const out = { ...m, id, kind, displayName, timeIso, text, images, likedByMe, likeCount, shareCount, comments };
  if (imageDescCards.length) out.imageDescCards = imageDescCards;
  else delete out.imageDescCards;
  if (charId) out.charId = charId;
  if (kind === "char") {
    if (threadId) out.threadId = threadId;
    else delete out.threadId;
    if (threadRemark) out.threadRemark = threadRemark;
    else delete out.threadRemark;
    if (String(m.postPersona || "").trim() === "alt") out.postPersona = "alt";
    else delete out.postPersona;
  } else {
    delete out.postPersona;
    if (m.sourceChatImageRole === "assistant" || m.sourceChatImageRole === "user") {
      out.sourceChatImageRole = m.sourceChatImageRole;
    } else {
      delete out.sourceChatImageRole;
    }
    const subCid = String(m.sourceImageSubjectCharId || "").trim();
    if (subCid) out.sourceImageSubjectCharId = subCid;
    else delete out.sourceImageSubjectCharId;
    const srcCid = String(m.sourceCharId || "").trim();
    if (srcCid) out.sourceCharId = srcCid;
    else delete out.sourceCharId;
    const srcTid = String(m.sourceThreadId || "").trim();
    if (srcTid) out.sourceThreadId = srcTid;
    else delete out.sourceThreadId;
    const fIdx = Number(m.fromChatMsgIdx);
    if (Number.isFinite(fIdx) && fIdx >= 0) out.fromChatMsgIdx = Math.floor(fIdx);
    else delete out.fromChatMsgIdx;
  }
  return out;
}

function getActiveMomentsBucket() {
  const maskId = getActiveMaskIdForInbox();
  const inbox = readChatInboxStore();
  const bucket = ensureMaskBucket(inbox, maskId);
  return { inbox, maskId, bucket };
}

function patchMomentById(momentId, mutator) {
  const mid = String(momentId || "").trim();
  if (!mid || typeof mutator !== "function") return false;
  const { inbox, maskId, bucket } = getActiveMomentsBucket();
  if (!maskId) return false;
  const arr = Array.isArray(bucket.moments) ? bucket.moments : [];
  const i = arr.findIndex((m) => String(m?.id || "") === mid);
  if (i < 0) return false;
  const base = normalizeMoment(arr[i]);
  const next = { ...base };
  mutator(next);
  bucket.moments[i] = normalizeMoment(next);
  writeChatInboxStore(inbox);
  return true;
}

function getProfileDecor() {
  const { bucket } = getActiveMomentsBucket();
  return normalizeProfileDecor(bucket.profileDecor);
}

/** 墙饰固定 3 格：data URL 外置为 xxj-blob，避免 inbox JSON 顶满 IndexedDB 配额。 */
async function externalizeProfileDecorArray(decor) {
  const norm = normalizeProfileDecor(decor);
  const media = window.XXJ_MEDIA;
  if (!media || typeof media.externalizeImageUrl !== "function") return norm;
  for (let i = 0; i < MOMENTS_DECOR_SLOTS; i++) {
    const prev = String(norm[i] || "").trim();
    if (!prev) continue;
    try {
      const next = await media.externalizeImageUrl(prev);
      if (next) norm[i] = String(next).trim() || prev;
    } catch (err) {
      console.warn("[moments-decor] externalize slot failed", i, err);
    }
  }
  return norm;
}

/**
 * 墙饰入库：三格一并外置 blob，再强制落盘（第三张常因 inbox 过大写库失败）。
 * @param {number} slotIdx
 * @param {string} src data URL 或 xxj-blob: 引用
 * @returns {Promise<boolean>}
 */
async function persistProfileDecorSlot(slotIdx, src) {
  const idx = Math.floor(Number(slotIdx));
  if (idx < 0 || idx >= MOMENTS_DECOR_SLOTS) return false;
  const { inbox, maskId, bucket } = getActiveMomentsBucket();
  if (!maskId) {
    showToast("请先创建并选择主控面具");
    return false;
  }
  const url = String(src || "").trim();
  if (!url) return false;
  const prevDecor = normalizeProfileDecor(bucket.profileDecor);
  const decor = normalizeProfileDecor(bucket.profileDecor);
  decor[idx] = url;
  try {
    bucket.profileDecor = await externalizeProfileDecorArray(decor);
    writeChatInboxStore(inbox);
    await flushChatInboxKvPersist({ propagateError: true, force: true });
    return true;
  } catch (err) {
    console.warn("[moments-decor] persist failed", err);
    bucket.profileDecor = prevDecor;
    writeChatInboxStore(inbox);
    showToast("墙饰未能写入本机（存储可能已满），请换小图或清缓存后重试");
    return false;
  }
}

function resolveMomentCharId(mm) {
  const cid = String(mm?.charId || "").trim();
  if (cid) return cid;
  const nm = String(mm?.displayName || "").trim();
  if (!nm) return "";
  const st = readCharPersonaStore();
  const it = st.items.find((x) => String(x?.displayName || "").trim() === nm);
  return it ? String(it.id || "").trim() : "";
}

function listMomentsReactorCharIds(maskId, moment) {
  const inbox = readChatInboxStore();
  const key = maskBucketKey(maskId);
  const bucket = inbox.byMask[key];
  if (!bucket) return [];
  const posterCharId = moment?.kind === "char" ? resolveMomentCharId(moment) : "";
  /** @type {Map<string, number>} */
  const latestByChar = new Map();
  for (const t of Array.isArray(bucket.threads) ? bucket.threads : []) {
    if (!t || t.kind === "group") continue;
    const cid = String(t.charId || "").trim();
    if (!cid) continue;
    if (posterCharId && cid === posterCharId) continue;
    const at = Number(t.updatedAt) || 0;
    const prev = latestByChar.get(cid);
    if (prev == null || at > prev) latestByChar.set(cid, at);
  }
  if (!latestByChar.size) return [];
  const entries = [...latestByChar.entries()]
    .map(([cid, updatedAt]) => ({ cid, updatedAt }))
    .sort((a, b) => b.updatedAt - a.updatedAt);
  const n = entries.length;
  const targetMax = Math.min(MOMENTS_REACTOR_MAX, n);
  const targetMin = Math.min(MOMENTS_REACTOR_MIN, n);
  const picked = new Set();
  const recentSlots = n <= 4 ? 1 : 2;
  const staleSlots = n <= 4 ? 1 : 2;
  for (let i = 0; i < recentSlots; i++) picked.add(entries[i].cid);
  for (let i = 0; i < staleSlots; i++) picked.add(entries[n - 1 - i].cid);
  for (const e of entries) {
    if (picked.size >= targetMax) break;
    picked.add(e.cid);
  }
  const order = entries.map((e) => e.cid);
  let list = [...picked].sort((a, b) => order.indexOf(a) - order.indexOf(b));
  if (list.length > targetMax) list = list.slice(0, targetMax);
  if (list.length < targetMin) {
    for (const cid of order) {
      if (list.length >= targetMin) break;
      if (!list.includes(cid)) list.push(cid);
    }
  }
  return list;
}

/** 角色动态绑定的密谈：优先指定 threadId，否则取该角色最近活跃的密谈 */
function pickThreadForCharMoment(maskId, charId, preferredThreadId = "") {
  const mid = String(maskId || "").trim();
  const cid = String(charId || "").trim();
  if (!mid || !cid) return null;
  const inbox = readChatInboxStore();
  const bucket = inbox.byMask[maskBucketKey(mid)];
  if (!bucket) return null;
  const threads = (Array.isArray(bucket.threads) ? bucket.threads : []).filter(
    (t) => t && t.kind !== "group" && String(t.charId || "").trim() === cid
  );
  if (!threads.length) return null;
  const pref = String(preferredThreadId || "").trim();
  if (pref) {
    const hit = threads.find((t) => String(t.id || "") === pref);
    if (hit) return hit;
  }
  threads.sort((a, b) => (Number(b.updatedAt) || 0) - (Number(a.updatedAt) || 0));
  return threads[0];
}

function getThreadMomentRemarkLabel(thread) {
  if (!thread) return "";
  const al = getThreadCharDisplayAlias(thread);
  if (al) return al.slice(0, 32);
  const rn = String(thread.charThreadRemarkName || "").trim();
  return rn.slice(0, 32);
}

function resolveMomentThreadRemark(mm, maskId) {
  const stored = String(mm?.threadRemark || "").trim();
  if (stored) return stored;
  const mid = String(maskId || "").trim();
  const tid = String(mm?.threadId || "").trim();
  if (tid && mid) {
    const inbox = readChatInboxStore();
    const bucket = inbox.byMask[maskBucketKey(mid)];
    if (bucket) {
      const th = (Array.isArray(bucket.threads) ? bucket.threads : []).find(
        (t) => t && String(t.id || "") === tid
      );
      const fromThread = getThreadMomentRemarkLabel(th);
      if (fromThread) return fromThread;
    }
  }
  const cid = String(mm?.charId || "").trim();
  if (!cid || !mid) return "";
  const inbox = readChatInboxStore();
  const bucket = inbox.byMask[maskBucketKey(mid)];
  if (!bucket) return "";
  const threads = (Array.isArray(bucket.threads) ? bucket.threads : []).filter(
    (t) => t && t.kind !== "group" && String(t.charId || "").trim() === cid
  );
  if (threads.length === 1) return getThreadMomentRemarkLabel(threads[0]);
  return "";
}

/** 朋友圈 AI：最近密谈对白（仅气泡口语，不含旁白/译本字段）。 */
function buildMomentsCharDialogueSnippet(maskId, charId, maxLines = 6, preferredThreadId = "", personaSlot = "") {
  const th = pickThreadForCharMoment(maskId, charId, preferredThreadId);
  if (!th) return "";
  const log = readChatLogForMaskThread(maskId, String(th.id || ""));
  const slot =
    String(personaSlot || "").trim() === "alt"
      ? "alt"
      : String(personaSlot || "").trim() === "main"
        ? "main"
        : getThreadActivePersona(th);
  const charItem = getCharPersonaItemById(charId);
  const hasAlt = charHasAltPersona(charItem);
  const lines = [];
  const cap = Math.min(12, Math.max(1, Math.floor(Number(maxLines) || 6)));
  for (let i = log.length - 1; i >= 0 && lines.length < cap; i--) {
    const row = log[i];
    if (!row || (row.role !== "user" && row.role !== "assistant")) continue;
    let t = "";
    try {
      t = chatMessagePlainLastBubbleSegment(row.content, row) || "";
    } catch {
      t = String(row.content || "").trim();
    }
    if (!t && row.image && typeof row.image === "object") t = "[图片]";
    if (!t) continue;
    const body = t.replace(/\s+/g, " ").trim();
    if (!body || isMomentsPostNarrationOrScriptLine(body) || isMostlyNonChineseMomentLine(body)) continue;
    let who = row.role === "user" ? "用户" : "你";
    if (row.role === "assistant" && hasAlt) {
      const sp = getMessageSpeakerPersona(row);
      who = sp === "alt" ? "你·马甲" : "你·大号";
    }
    lines.unshift(`[${who}] ${body.slice(0, 160)}`);
  }
  if (!lines.length) return "";
  if (hasAlt) {
    const id = resolveMomentsCharIdentity(maskId, charId, preferredThreadId, slot);
    const tag = slot === "alt" ? "马甲" : "大号";
    return `[当前发朋友圈身份：${tag}「${id.displayName}」]\n${lines.join("\n")}`;
  }
  return lines.join("\n");
}

/** 朋友圈 AI / 密谈：本面具时间线上与该角色相关的近况摘要。 */
function buildMomentsMaskFeedDigestForChar(maskId, charId, maxItems = 5, opts = {}) {
  const mid = String(maskId || "").trim();
  const cid = String(charId || "").trim();
  if (!mid || !cid) return "";
  const inbox = readChatInboxStore();
  const bucket = inbox.byMask[maskBucketKey(mid)];
  if (!bucket) return "";
  const st = readUserMaskStore();
  const userLabel =
    (st.items.find((x) => x.id === st.activeId)?.displayName &&
      String(st.items.find((x) => x.id === st.activeId).displayName).trim()) ||
    "主控";
  const charName = charDisplayNameById(cid) || "角色";
  const cap = Math.min(8, Math.max(1, Math.floor(Number(maxItems) || 5)));
  const maxAgeMs = Number(opts.maxAgeMs) > 0 ? Math.floor(Number(opts.maxAgeMs)) : 0;
  const now = Date.now();
  const list = (Array.isArray(bucket.moments) ? bucket.moments : [])
    .map((m) => normalizeMoment(m))
    .filter((mm) => momentRowLooksVisible(mm))
    .filter((mm) => {
      if (!maxAgeMs) return true;
      const t = momentPostTimestampMs(mm);
      return t > 0 && now - t <= maxAgeMs;
    })
    .sort((a, b) => new Date(b.timeIso).getTime() - new Date(a.timeIso).getTime());
  const lines = [];
  for (const mm of list) {
    if (lines.length >= cap) break;
    const txt = String(mm.text || "").trim().replace(/\s+/g, " ");
    const short = txt.length > 100 ? `${txt.slice(0, 99)}…` : txt || "（配图）";
    const posterCid = mm.kind === "char" ? resolveMomentCharId(mm) : "";
    if (mm.kind === "char" && posterCid === cid) {
      lines.push(`${charName} 发朋友圈：${short}`);
      continue;
    }
    if (mm.kind === "user") {
      lines.push(`用户 ${userLabel} 发朋友圈：${short}`);
      continue;
    }
    if (mm.kind === "char" && posterCid && posterCid !== cid) continue;
    const cmts = Array.isArray(mm.comments) ? mm.comments : [];
    for (const c of cmts.slice(-2)) {
      if (lines.length >= cap) break;
      const who = c.authorKind === "user" ? userLabel : String(c.authorName || charName).trim();
      const ct = String(c.text || "").trim().replace(/\s+/g, " ");
      if (!ct) continue;
      if (c.authorKind === "char" && resolveMomentCharId(mm) === cid) {
        lines.push(`${charName} 评论：${ct.slice(0, 80)}`);
      } else if (c.authorKind === "user") {
        lines.push(`用户 ${who} 评论：${ct.slice(0, 80)}`);
      } else if (c.authorKind === "npc") {
        lines.push(`${who} 评论：${ct.slice(0, 80)}`);
      }
    }
    if (mm.likeCount > 0 && mm.kind === "user") {
      lines.push(`${charName} 等 ${mm.likeCount} 次赞（用户那条动态）`);
    }
  }
  return lines.join("\n");
}

/** 密谈 system：近期朋友圈摘要（须已聊开 + 时间窗内才有内容）。 */
function buildMomentsChatFeedDigestBlockForThread(th, maskId, charId, replaceLine = (s) => s) {
  if (!th || th.kind === "group") return "";
  const mid = String(maskId || "").trim();
  const cid = String(charId || "").trim();
  const tid = String(th.id || "").trim();
  if (!mid || !cid || !tid) return "";
  if (!chatThreadHasEnoughDialogueForMomentsRef(mid, tid)) return "";
  const days = Math.max(1, Math.round(MOMENTS_CHAT_RECENT_WINDOW_MS / 86400000));
  const blob = buildMomentsMaskFeedDigestForChar(mid, cid, 4, {
    maxAgeMs: MOMENTS_CHAT_RECENT_WINDOW_MS
  });
  if (!blob) return "";
  const rep = typeof replaceLine === "function" ? replaceLine : (s) => s;
  return `[本密谈相关 · 朋友圈近况（近 ${days} 日内）]\n${rep(blob)}\n（公开时间线；与密谈分开。聊的时候若自然想到、且符合人设，可顺带提一句——主要看人设、当下聊天氛围与动态具体内容，不必硬往剧情上靠，也不必每轮都提；勿翻更早的陈年动态，寒暄刚开场时也别突然提。）`;
}

/** 角色发朋友圈专用上下文：不含情绪手帐，减轻私聊语气渗入公开动态。 */
function buildMomentsCharPostContextForPrompt(maskId, charId, preferredThreadId = "", personaSlot = "") {
  const parts = [];
  const dlg = buildMomentsCharDialogueSnippet(maskId, charId, 3, preferredThreadId, personaSlot);
  if (dlg) {
    parts.push(
      "[近期密谈氛围（公开场所发圈时作参考，勿照抄原话；须符合人设）]\n" + dlg
    );
  }
  const feed = buildMomentsMaskFeedDigestForChar(maskId, charId, 3);
  if (feed) parts.push(`[你此前朋友圈风格参考]\n${feed}`);
  const blob = parts.join("\n\n");
  return blob.length <= 2800 ? blob : `${blob.slice(0, 2800)}\n…（已截断）`;
}

/** 朋友圈发圈/评论 AI：记忆摘要 + 密谈对白 + 朋友圈近况（不含旁白条）。 */
function buildMomentsCharContextForPrompt(maskId, charId, preferredThreadId = "", personaSlot = "") {
  const parts = [];
  const th = pickThreadForCharMoment(maskId, charId, preferredThreadId);
  if (th) {
    const mem = buildCharThreadMemoryTimelineForPrompt(th);
    if (mem) parts.push(mem);
  }
  const dlg = buildMomentsCharDialogueSnippet(maskId, charId, 6, preferredThreadId, personaSlot);
  if (dlg) {
    parts.push(
      `[最近密谈对白（仅供关系与语气参考，勿照抄；旁白/剧本标不要写进朋友圈）]\n${dlg}`
    );
  }
  const feed = buildMomentsMaskFeedDigestForChar(maskId, charId, 5);
  if (feed) parts.push(`[朋友圈近况（公开时间线，与密谈分开）]\n${feed}`);
  const blob = parts.join("\n\n");
  if (blob.length <= 5200) return blob;
  return `${blob.slice(0, 5200)}\n…（参考上下文已截断）`;
}

function safeBuildMomentsCharContextForPrompt(maskId, charId, preferredThreadId = "", personaSlot = "") {
  try {
    return buildMomentsCharContextForPrompt(maskId, charId, preferredThreadId, personaSlot);
  } catch (e) {
    console.warn("[moments] build context failed", e);
    return "";
  }
}

function isChatNoticeMomentsFeedMessage(m) {
  return !!(m && typeof m === "object" && m.role === "notice" && String(m.kind || "") === "moments_feed");
}

function isMomentsFeedPostPublishedNotice(m) {
  return (
    isChatNoticeMomentsFeedMessage(m) && String(m?.action || "").trim() === "post_published"
  );
}

/** 发圈票根写入密谈（仅事件，正文留在时间线库，不进上下文）。 */
function recordMomentsFeedPostPublishedInChatThread(maskId, threadId, opts = {}) {
  const authorKind = opts.authorKind === "user" ? "user" : "char";
  /** @type {Record<string, unknown>} */
  const spec = {
    action: "post_published",
    authorKind,
    displayName: String(opts.displayName || "").trim(),
    hasImages: opts.hasImages === true,
    momentId: String(opts.momentId || "").trim()
  };
  if (opts.usedCharChatImage === true) spec.usedCharChatImage = true;
  const subCid = String(opts.sourceImageSubjectCharId || "").trim();
  if (subCid) spec.sourceImageSubjectCharId = subCid;
  if (opts.sourceChatImageRole === "assistant" || opts.sourceChatImageRole === "user") {
    spec.sourceChatImageRole = opts.sourceChatImageRole;
  }
  const srcIdx = Number(opts.sourceChatMsgIdx);
  if (Number.isFinite(srcIdx) && srcIdx >= 0) spec.sourceChatMsgIdx = Math.floor(srcIdx);
  recordMomentsFeedNoticeInChatThread(maskId, threadId, spec);
}

/** 角色本人发朋友圈 → 注入密谈 API 的固定句式（避免 role:user 下「你」被理解成主控）。 */
function momentsCharSelfPostApiNoticeLine(hasImages) {
  const img = hasImages ? "（带配图）" : "";
  return `[系统记录：你在朋友圈发了一条社交动态${img}（角色本人发帖，不是主控）。]`;
}

/** 无 authorKind 的旧票根：usedCharChatImage 仅出现在用户发圈。 */
function momentsFeedPostPublishedAuthorKind(m) {
  if (m?.authorKind === "user") return "user";
  if (m?.authorKind === "char") return "char";
  return m?.usedCharChatImage === true ? "user" : "char";
}

/** @param {ReturnType<typeof normalizeMoment> | null | undefined} mm */
function momentReactionIsCharOwnPost(mm, reactorCharId, reactorDisplayName) {
  if (mm?.kind !== "char") return false;
  const cid = String(reactorCharId || "").trim();
  const posterCharId = resolveMomentCharId(mm);
  if (posterCharId && posterCharId === cid) return true;
  const postName = String(mm?.displayName || "").trim();
  const rName = String(reactorDisplayName || "").trim();
  return !posterCharId && postName !== "" && rName !== "" && postName === rName;
}

/** @param {ReturnType<typeof normalizeMoment> | null | undefined} mm */
function buildMomentsCharReactionVisionHint(mm, reactorCharId, reactorDisplayName, hasVision) {
  if (!hasVision || !mm) return "";
  const cid = String(reactorCharId || "").trim();
  const tail = "不要复述「我看到图里」这类元叙述。";
  if (mm.kind === "char") {
    if (momentReactionIsCharOwnPost(mm, cid, reactorDisplayName)) {
      return `动态配图来自你自己刚发的这条朋友圈（角色账号发帖，不是主控发的）；可结合正文与画面自然回应，勿说成是用户/主控发的动态。${tail}`;
    }
    const posterCharId = resolveMomentCharId(mm);
    if (posterCharId && posterCharId !== cid) {
      const pn = charDisplayNameById(posterCharId) || String(mm.displayName || "").trim() || "其他角色";
      return `动态配图属于${pn}在朋友圈发的动态，不是你本人发的；评论时不要当成自己的照片或说「这是我」。${tail}`;
    }
    return "";
  }
  if (mm.kind !== "user") return "";
  const subCid = String(mm.sourceImageSubjectCharId || "").trim();
  if (subCid && subCid !== cid) {
    return `动态配图已附上；画面主体偏${charDisplayNameById(subCid) || "其他角色"}，按所见写评论即可，勿当成自己的照片或说「这是我」。${tail}`;
  }
  const photoOfMe =
    (mm.sourceChatImageRole === "assistant" && String(mm.sourceCharId || "").trim() === cid) ||
    (subCid !== "" && subCid === cid);
  if (photoOfMe) {
    return `动态配图已附上；可能与你的外貌或与你相关的场景有关，请结合正文与画面自然回应。${tail}`;
  }
  return `动态配图已附上；请结合正文与画面写评论，语气自然即可，勿酸、盘问或无事吃醋。${tail}`;
}

/** 旧 notice 纯文本 → API 短句（评论/点赞等仍带摘要）。 */
function momentsFeedNoticeLineFromLegacyContent(content) {
  const body = String(content || "").trim().replace(/\s+/g, " ");
  if (!body) return "";
  if (/发了一条朋友圈/.test(body) && !/评论|赞了/.test(body)) {
    const hasImg = /配图|带配图/.test(body);
    if (/^用户\s/.test(body)) {
      const img = hasImg ? "（带配图）" : "";
      return `[系统记忆：用户发了一条社交动态${img}。（私聊接续时自然知晓即可，勿复读本句。）]`;
    }
    return momentsCharSelfPostApiNoticeLine(hasImg);
  }
  if (/评论/.test(body)) {
    return `[系统记忆：${body.slice(0, 200)}。（私聊接续时自然承接，勿机械复述。）]`;
  }
  if (/赞了/.test(body)) {
    return `[系统记忆：${body.slice(0, 120)}。（私聊接续时自然知晓即可。）]`;
  }
  return `[系统记忆：${body.slice(0, 240)}。（朋友圈时间线事件，与密谈气泡分开。）]`;
}

const MOMENTS_CHAT_AWARENESS_TAIL =
  "（你已后台知晓。密谈里**可以**顺带提朋友圈：结合人设、当下聊天氛围与动态具体内容，聊得自然就提，不必硬凑剧情关联，也不必每轮都提；只聊**近期**动态，勿翻很早以前的陈年旧帖；**刚开场寒暄**时不要突然提。语气自然，勿酸、盘问或无事吃醋。勿机械复读本句。）";

/** @param {string} maskId @param {string} momentId */
function lookupMomentForMaskById(maskId, momentId) {
  const mid = String(maskId || "").trim();
  const id = String(momentId || "").trim();
  if (!mid || !id) return null;
  const inbox = readChatInboxStore();
  const bucket = inbox.byMask[maskBucketKey(mid)];
  const raw = (Array.isArray(bucket?.moments) ? bucket.moments : []).find(
    (x) => String(x?.id || "") === id
  );
  return raw ? normalizeMoment(raw) : null;
}

/**
 * @param {object | null | undefined} m
 * @param {string} [maskId]
 * @returns {{ line: string, mm: ReturnType<typeof normalizeMoment> | null } | null}
 */
function resolveMomentsFeedNoticeBundle(m, maskId) {
  if (!m || typeof m !== "object") return null;
  const mid = String(maskId || getActiveMaskIdForInbox() || "").trim();
  const momentId = String(m.momentId || "").trim();
  const mm =
    mid && momentId && isMomentsFeedPostPublishedNotice(m)
      ? lookupMomentForMaskById(mid, momentId)
      : null;
  if (isMomentsFeedNoticeStaleForChat(m, mm)) return null;
  const line = momentsFeedNoticeLineForApiContext(m, mm);
  if (!line) return null;
  return { line, mm };
}

/** 票根 → API 文案；过期动态返回 null（不进主聊天/摘要）。 */
function resolveMomentsFeedNoticeLineForApi(m, maskId) {
  const b = resolveMomentsFeedNoticeBundle(m, maskId);
  return b ? b.line : null;
}

/** @param {object | null | undefined} m @param {ReturnType<typeof normalizeMoment> | null | undefined} [mm] */
function momentsFeedNoticeLineForApiContext(m, mm) {
  if (!m || typeof m !== "object") return "";
  if (isMomentsFeedPostPublishedNotice(m)) {
    const img = m.hasImages ? "（带配图）" : "";
    const body = mm ? String(getMomentPostDisplayText(mm) || "").trim() : "";
    const bodyBit = body ? `正文：「${body.slice(0, 160)}」` : "";
    const visionBit = m.hasImages ? " 若配图随本句附上，请结合识图理解。" : "";
    if (momentsFeedPostPublishedAuthorKind(m) === "user") {
      if (m.usedCharChatImage === true) {
        return `[系统记忆：用户用你在密谈里发过的图发了一条朋友圈${img}。${bodyBit}${visionBit} ${MOMENTS_CHAT_AWARENESS_TAIL}]`;
      }
      const subCid = String(m.sourceImageSubjectCharId || "").trim();
      if (subCid) {
        const nm = charDisplayNameById(subCid) || "其他角色";
        return `[系统记忆：用户发了一条朋友圈${img}（配图偏${nm}）。${bodyBit}${visionBit} ${MOMENTS_CHAT_AWARENESS_TAIL}]`;
      }
      return `[系统记忆：用户发了一条朋友圈${img}。${bodyBit}${visionBit} ${MOMENTS_CHAT_AWARENESS_TAIL}]`;
    }
    return `${momentsCharSelfPostApiNoticeLine(m.hasImages === true)} ${MOMENTS_CHAT_AWARENESS_TAIL}`;
  }
  const legacy = String(m.content || "").trim();
  if (legacy) return `${momentsFeedNoticeLineFromLegacyContent(legacy)} ${MOMENTS_CHAT_AWARENESS_TAIL}`;
  return "";
}

function momentsFeedNoticeApiMapKey(m) {
  const id = String(m?.momentId || "").trim();
  const at = Number(m?.at) || 0;
  return id ? `${id}:${at}` : `legacy:${String(m?.content || "").slice(0, 48)}:${at}`;
}

/** @param {ReturnType<typeof normalizeMoment> | null | undefined} mm */
function buildMomentsChatVisionCompanionLine(mm) {
  const body = mm ? String(getMomentPostDisplayText(mm) || "").trim() : "";
  const bits = [
    "（以上为用户在朋友圈所发配图的实图，不是密谈私聊里刚发来的图。）",
    body ? `配文：「${body.slice(0, 120)}」` : "",
    "结合画面自然理解即可；勿酸、盘问或无事吃醋。"
  ].filter(Boolean);
  return bits.join("");
}

/**
 * 预解析密谈日志里的朋友圈票根：用户带配图的发圈尽量以多模态送入主聊天 API。
 * @param {readonly unknown[]} logSlice
 * @param {string} maskId
 */
async function hydrateMomentsFeedNoticesForApi(logSlice, maskId) {
  const map = new Map();
  const mid = String(maskId || "").trim();
  if (!mid || !Array.isArray(logSlice)) return map;
  for (const row of logSlice) {
    if (!row || typeof row !== "object" || !isChatNoticeMomentsFeedMessage(row)) continue;
    const bundle = resolveMomentsFeedNoticeBundle(row, mid);
    if (!bundle) continue;
    const { line, mm } = bundle;
    const key = momentsFeedNoticeApiMapKey(row);
    if (isMomentsFeedPostPublishedNotice(row) && row.hasImages === true && mm) {
      const urls = await resolveMomentPostImageUrlsForApi(getMomentPostStoredImageUrls(mm));
      if (urls.length) {
        /** @type {Array<{ type: "image_url", image_url: { url: string } } | { type: "text", text: string }>} */
        const parts = urls.slice(0, 3).map((url) => ({
          type: "image_url",
          image_url: { url }
        }));
        parts.push({
          type: "text",
          text: `${line}\n${buildMomentsChatVisionCompanionLine(mm)}`
        });
        map.set(key, { role: "user", content: parts });
        continue;
      }
    }
    map.set(key, { role: "user", content: line });
  }
  return map;
}

/** 用户发朋友圈后，给本面具各单聊密谈写入票根（与评/赞解耦，避免无 AI 时丢失）。 */
function recordUserMomentFeedNoticesForMask(maskId, mm, userLabel) {
  const mid = String(maskId || "").trim();
  if (!mid || !mm || mm.kind !== "user") return;
  const label = String(userLabel || mm.displayName || "").trim() || "主控";
  let charIds = listMomentsReactorCharIds(mid, mm);
  const sourceCharId = String(mm.sourceCharId || "").trim();
  const sourceThreadId = String(mm.sourceThreadId || "").trim();
  const fromCharPhoto = mm.sourceChatImageRole === "assistant";
  if (fromCharPhoto && sourceCharId && !charIds.includes(sourceCharId)) {
    charIds = [sourceCharId, ...charIds].slice(0, MOMENTS_REACTOR_MAX);
  }
  const userHasImg = getMomentPostStoredImageUrls(mm).length > 0;
  const cap = Math.min(MOMENTS_REACTOR_MAX, charIds.length);
  for (let i = 0; i < cap; i++) {
    const cid = String(charIds[i] || "").trim();
    if (!cid) continue;
    const th = pickThreadForCharMoment(
      mid,
      cid,
      fromCharPhoto && sourceCharId && cid === sourceCharId ? sourceThreadId : ""
    );
    if (!th) continue;
    const tid = String(th.id || "").trim();
    if (!tid) continue;
    const log = readChatLogForMaskThread(mid, tid);
    const momentId = String(mm.id || "").trim();
    if (
      momentId &&
      log.some(
        (x) =>
          x &&
          typeof x === "object" &&
          isMomentsFeedPostPublishedNotice(x) &&
          String(x.momentId || "") === momentId &&
          x.authorKind === "user"
      )
    ) {
      continue;
    }
    const isSourceChar = fromCharPhoto && sourceCharId && cid === sourceCharId;
    recordMomentsFeedPostPublishedInChatThread(mid, tid, {
      authorKind: "user",
      displayName: label,
      hasImages: userHasImg,
      momentId,
      usedCharChatImage: isSourceChar,
      ...(mm.sourceChatImageRole === "assistant" || mm.sourceChatImageRole === "user"
        ? { sourceChatImageRole: mm.sourceChatImageRole }
        : {}),
      ...(String(mm.sourceImageSubjectCharId || "").trim()
        ? { sourceImageSubjectCharId: String(mm.sourceImageSubjectCharId).trim() }
        : {}),
      sourceChatMsgIdx:
        isSourceChar && Number.isFinite(Number(mm.fromChatMsgIdx))
          ? Math.floor(Number(mm.fromChatMsgIdx))
          : undefined
    });
  }
}

/**
 * 把朋友圈事件写入对应密谈线程（灰字票根），便于聊天与记忆承接。
 * @param {string} maskId
 * @param {string} threadId
 * @param {string | { action?: string, authorKind?: string, displayName?: string, hasImages?: boolean, momentId?: string, content?: string }} summaryOrSpec
 */
function recordMomentsFeedNoticeInChatThread(maskId, threadId, summaryOrSpec) {
  const mid = String(maskId || "").trim();
  const tid = String(threadId || "").trim();
  if (!mid || !tid) return;
  /** @type {Record<string, unknown>} */
  let row = { role: "notice", kind: "moments_feed", at: Date.now() };
  if (summaryOrSpec && typeof summaryOrSpec === "object") {
    const spec = summaryOrSpec;
    const action = String(spec.action || "event").trim();
    row.action = action;
    if (spec.authorKind === "user" || spec.authorKind === "char") row.authorKind = spec.authorKind;
    const dn = String(spec.displayName || "").trim();
    if (dn) row.displayName = dn.slice(0, 64);
    if (spec.hasImages === true) row.hasImages = true;
    if (spec.usedCharChatImage === true) row.usedCharChatImage = true;
    const subCid = String(spec.sourceImageSubjectCharId || "").trim();
    if (subCid) row.sourceImageSubjectCharId = subCid;
    if (spec.sourceChatImageRole === "assistant" || spec.sourceChatImageRole === "user") {
      row.sourceChatImageRole = spec.sourceChatImageRole;
    }
    const srcIdx = Number(spec.sourceChatMsgIdx);
    if (Number.isFinite(srcIdx) && srcIdx >= 0) row.sourceChatMsgIdx = Math.floor(srcIdx);
    const momentId = String(spec.momentId || "").trim();
    if (momentId) row.momentId = momentId;
    const content = String(spec.content || "").trim().replace(/\s+/g, " ").slice(0, 500);
    if (content) row.content = content;
    if (action === "post_published") {
      /* 发圈票根：界面与上下文均不展示正文 */
    } else if (!content) return;
  } else {
    const line = String(summaryOrSpec || "").trim().replace(/\s+/g, " ").slice(0, 500);
    if (!line) return;
    row.action = "event";
    row.content = line;
  }
  const log = readChatLogForMaskThread(mid, tid);
  const log2 = log.slice();
  log2.push(row);
  saveChatLogForMaskThread(mid, tid, log2);
  const ref = readChatActiveThreadRef();
  if (
    ref.maskId === mid &&
    ref.threadId === tid &&
    (getChatScreenEl()?.classList.contains("is-open") || isChatOfflineScreenOpen())
  ) {
    try {
      invalidateChatLogViewCache();
      requestChatStickBottomNextRender();
      renderChatMessages();
    } catch (e) {
      console.warn("[moments] render feed notice failed", e);
    }
  }
}

function parseMomentsCharReactionResponse(raw) {
  let text = String(raw || "").trim();
  if (!text) return { ignore: true, like: false, commentText: "" };
  if (/\[IGNORE\]/i.test(text)) return { ignore: true, like: false, commentText: "" };
  const like = /\[LIKE\]/i.test(text);
  text = text.replace(/^```[\w]*\n?/gm, "").replace(/```$/g, "").trim();
  text = text
    .replace(/\[LIKE\]/gi, "")
    .replace(/\[IGNORE\]/gi, "")
    .replace(/^\[COMMENT\]\s*/i, "")
    .replace(/\[POST_IMAGE:[^\]]*\]/gi, "")
    .replace(/^\[POST\]\s*/i, "")
    .replace(/\|\|\|/g, " ")
    .replace(/\s*\n+\s*/g, " ")
    .replace(/\s{2,}/g, " ")
    .trim()
    .slice(0, MOMENTS_COMMENT_MAX_LEN);
  if (!text && !like) return { ignore: true, like: false, commentText: "" };
  return { ignore: false, like, commentText: text };
}

/** 一次 AI 回复里同时决定是否点赞与是否写评/回评（勿另起请求）。 */
function buildMomentsCharReactionFormatHint(replyMode = false) {
  const verb = replyMode ? "回复" : "评论";
  return [
    `\n在同一轮回复里同时决定是否点赞这条动态，并写${verb}（只输出一次）：`,
    `- 点赞并${verb}：[LIKE] 后接简体中文${verb}`,
    `- 只${verb}不点赞：直接写简体中文${verb}`,
    `- 只点赞不${verb}：以 [LIKE] 开头，可不再写别的`,
    `- 不${verb}也不赞：[IGNORE]`
  ].join("\n");
}

/** @param {{ type: string, userCommentText?: string, replyToCommentId?: string }} scene @param {string} reactorCharId */
function buildMomentsCharReactionPromptUser(maskId, mm, scene, userLabel, reactorCharId) {
  const cid = String(reactorCharId || "").trim();
  const reactTid = String(mm.threadId || "").trim();
  const reactSlot = cid ? resolveMomentsCharIdentity(maskId, cid, reactTid).slot : "main";
  const ctxBlock = cid
    ? buildMomentsCharContextForPrompt(maskId, cid, reactTid, reactSlot)
    : "";
  const imgNote = momentsPostImageNoteForReactionPrompt(mm);
  const body = `"${getMomentPostDisplayText(mm) || "（无文字）"}"`;
  const sourceCharId = String(mm.sourceCharId || "").trim();
  const sourceImageSubjectCharId = String(mm.sourceImageSubjectCharId || "").trim();
  const userHasImg = getMomentPostStoredImageUrls(mm).length > 0;
  const fromCharChatPhoto =
    mm.sourceChatImageRole === "assistant" && sourceCharId !== "" && sourceCharId === cid;
  const photoOfMe =
    userHasImg &&
    ((mm.sourceChatImageRole === "assistant" && sourceCharId === cid) ||
      (sourceImageSubjectCharId !== "" && sourceImageSubjectCharId === cid));
  const photoOfOtherChar =
    userHasImg && sourceImageSubjectCharId !== "" && sourceImageSubjectCharId !== cid;
  const otherCharName = photoOfOtherChar ? charDisplayNameById(sourceImageSubjectCharId) : "";
  let eventBlock = "";
  let replyMode = false;
  if (scene.type === "user_post") {
    if (fromCharChatPhoto) {
      eventBlock = `[事件] 用户 ${userLabel} 用你在密谈里发的那张图发了一条朋友圈${imgNote}：\n${body}`;
    } else if (photoOfOtherChar) {
      eventBlock = `[事件] 用户 ${userLabel} 发了一条朋友圈${imgNote}：\n${body}\n（配图偏${otherCharName || "其他角色"}；按所见写评论，勿当成自己的照片。）`;
    } else if (mm.sourceChatImageRole === "user" && userHasImg) {
      if (photoOfMe) {
        eventBlock = `[事件] 用户 ${userLabel} 发了一条朋友圈${imgNote}：\n${body}\n（配图可能与你相关；结合正文与画面自然回应。）`;
      } else {
        eventBlock = `[事件] 用户 ${userLabel} 发了一条朋友圈${imgNote}：\n${body}\n（请结合配图与正文写评论，语气自然，勿酸或盘问。）`;
      }
    } else {
      eventBlock = `[事件] 用户 ${userLabel} 发了一条朋友圈${imgNote}：\n${body}`;
    }
  } else if (scene.type === "user_comment") {
    replyMode = true;
    const tgt = String(scene.userCommentText || "").trim();
    eventBlock = [
      `[事件] 这是你在朋友圈发的动态${imgNote}：`,
      body,
      `\n用户 ${userLabel} 评论：`,
      `"${tgt}"`,
      scene.replyToCommentId ? "（这是一条回复评论）" : ""
    ]
      .filter(Boolean)
      .join("\n");
  } else if (scene.type === "invite_comment") {
    const poster =
      mm.kind === "user"
        ? userLabel
        : String(mm.displayName || "").trim() || charDisplayNameById(resolveMomentCharId(mm)) || "对方";
    eventBlock = [
      `[事件] 主控邀请你对这条朋友圈留言${imgNote}：`,
      `${mm.kind === "user" ? `用户 ${poster}` : `角色 ${poster}`} 发：`,
      body
    ].join("\n");
  } else {
    return "";
  }
  return [ctxBlock ? `[连贯参考]\n${ctxBlock}\n` : "", eventBlock, buildMomentsCharReactionFormatHint(replyMode)]
    .filter(Boolean)
    .join("\n");
}

function applyMomentsCharReaction(momentId, charId, reaction, reactMaskId, reactThreadId) {
  const cid = String(charId || "").trim();
  const mid = String(reactMaskId || getActiveMaskIdForInbox() || "").trim();
  const reactIdent = resolveMomentsCharIdentity(mid, cid, String(reactThreadId || ""));
  const charName = reactIdent.displayName || "角色";
  const commentText = String(reaction?.commentText || "").trim();
  const wantLike = reaction?.like === true;
  const replyTo = String(reaction?.replyToCommentId || "").trim();
  let threadIdForNotice = "";
  patchMomentById(momentId, (m) => {
    threadIdForNotice = String(m.threadId || "").trim();
    if (wantLike) {
      m.likeCount = Math.max(0, Math.floor(Number(m.likeCount) || 0) + 1);
    }
    if (commentText) {
      const arr = Array.isArray(m.comments) ? m.comments : [];
      arr.push({
        id: newEntityId(),
        authorKind: "char",
        authorName: charName,
        timeIso: new Date().toISOString(),
        text: commentText,
        replyToCommentId: replyTo
      });
      m.comments = arr;
    }
    if (
      cid &&
      m.kind === "char" &&
      !String(m.charId || "").trim() &&
      momentReactionIsCharOwnPost(m, cid, charName)
    ) {
      m.charId = cid;
    }
  });
  const { maskId } = getActiveMomentsBucket();
  if (maskId && threadIdForNotice && (commentText || wantLike)) {
    const verb = commentText && wantLike ? "赞并评论了朋友圈" : commentText ? "评论了朋友圈" : "赞了一条朋友圈";
    const tail = commentText ? `：${commentText.slice(0, 80)}` : "";
    recordMomentsFeedNoticeInChatThread(maskId, threadIdForNotice, `${charName} ${verb}${tail}`);
  }
}

async function requestMomentsCharReactionAi(charId, promptUser, reactMaskId, reactThreadId, mm) {
  const ai = window.RP_AI;
  if (!ai || typeof ai.chatCompletions !== "function") return "";
  const cid = String(charId || "").trim();
  if (!cid) return "";
  const mid = String(reactMaskId || getActiveMaskIdForInbox() || "").trim();
  const tid = String(reactThreadId || "").trim();
  const ident = resolveMomentsCharIdentity(mid, cid, tid);
  const ch = ident.charItem;
  if (!ch) return "";
  const name = ident.displayName;
  const personaBits = [ident.persona.summary, ident.persona.boundaries, ident.persona.npcRelations]
    .map((x) => String(x || "").trim())
    .filter(Boolean)
    .join("\n");
  const userContent = await buildMomentsCharReactionUserMessageContent(mm, promptUser);
  const hasVision = Array.isArray(userContent);
  const visionHint = buildMomentsCharReactionVisionHint(mm, cid, name, hasVision);
  const system = [
    `你是${name}，在朋友圈时间线里点赞或评论（这是社交动态区，不是密谈聊天）。`,
    personaBits ? `人设：\n${personaBits.slice(0, 1200)}` : "",
    visionHint,
    "用简体中文写评论：口语、一两到三句、单行不换行，把话说完整，不要半句戛然而止；不要 @、不要解释规则、不要 JSON、不要旁白/剧本标注。",
    "严格按用户消息中的格式标记回复（[LIKE] / [IGNORE] / 正文），一次输出完成，不要分两次回答。"
  ]
    .filter(Boolean)
    .join("\n\n");
  try {
    const data = await ai.chatCompletions({
      messages: [
        { role: "system", content: system },
        { role: "user", content: userContent }
      ],
      temperature: 0.88
    });
    return readMomentsPostCompletionText(data);
  } catch (e) {
    console.warn("[moments] char reaction failed", name, e);
    return "";
  }
}

async function runMomentsCharReactionForChar(momentId, charId, scene) {
  const mid = String(momentId || "").trim();
  const cid = String(charId || "").trim();
  if (!mid || !cid) return;
  const { maskId, bucket } = getActiveMomentsBucket();
  if (!maskId) return;
  const raw = (Array.isArray(bucket.moments) ? bucket.moments : []).find((m) => String(m?.id || "") === mid);
  if (!raw) return;
  const mm = normalizeMoment(raw);
  const st = readUserMaskStore();
  const userLabel =
    (st.items.find((x) => x.id === st.activeId)?.displayName &&
      String(st.items.find((x) => x.id === st.activeId).displayName).trim()) ||
    "主控";
  const promptUser = buildMomentsCharReactionPromptUser(maskId, mm, scene, userLabel, cid);
  if (!promptUser) return;
  if (scene.type !== "invite_comment" && Math.random() > MOMENTS_REACTOR_AI_CHANCE) return;
  const reactTid = String(mm.threadId || "").trim();
  const parsed = parseMomentsCharReactionResponse(
    await requestMomentsCharReactionAi(cid, promptUser, maskId, reactTid, mm)
  );
  if (parsed.ignore || (!parsed.like && !parsed.commentText)) return;
  applyMomentsCharReaction(
    mid,
    cid,
    {
      like: parsed.like,
      commentText: parsed.commentText,
      replyToCommentId: scene.type === "user_comment" ? String(scene.replyToCommentId || "").trim() : ""
    },
    maskId,
    reactTid
  );
}

let momentsCharReactChain = Promise.resolve();

function queueMomentsCharReactions(run) {
  momentsCharReactChain = momentsCharReactChain
    .then(() => run())
    .catch((e) => console.warn("[moments] char react queue", e));
}

async function triggerMomentsReactionsOnUserPost(momentId) {
  const ai = window.RP_AI;
  if (!ai?.chatCompletions) return;
  const { maskId, bucket } = getActiveMomentsBucket();
  if (!maskId) return;
  const raw = (Array.isArray(bucket.moments) ? bucket.moments : []).find(
    (m) => String(m?.id || "") === String(momentId)
  );
  if (!raw) return;
  const mm = normalizeMoment(raw);
  if (mm.kind !== "user") return;
  const fromCharPhoto = mm.sourceChatImageRole === "assistant";
  const sourceCharId = String(mm.sourceCharId || "").trim();
  const sourceThreadId = String(mm.sourceThreadId || "").trim();
  let charIds = listMomentsReactorCharIds(maskId, mm);
  if (fromCharPhoto && sourceCharId && !charIds.includes(sourceCharId)) {
    charIds = [sourceCharId, ...charIds].slice(0, MOMENTS_REACTOR_MAX);
  }
  for (const cid of charIds) {
    await runMomentsCharReactionForChar(momentId, cid, { type: "user_post" });
    await new Promise((r) => setTimeout(r, 500 + Math.floor(Math.random() * 900)));
  }
  scheduleMomentsFeedRender(true);
}

async function inviteCharsToCommentOnMoment(momentId) {
  const ai = window.RP_AI;
  if (!ai?.chatCompletions) {
    showToast("AI 未加载");
    return;
  }
  const mid = String(momentId || "").trim();
  if (!mid) return;
  const { maskId, bucket } = getActiveMomentsBucket();
  if (!maskId) return;
  const raw = (Array.isArray(bucket.moments) ? bucket.moments : []).find((m) => String(m?.id || "") === mid);
  if (!raw) return;
  const mm = normalizeMoment(raw);
  let charIds = listMomentsReactorCharIds(maskId, mm);
  if (!charIds.length && mm.kind === "char") {
    const author = resolveMomentCharId(mm);
    if (author) charIds = [author];
  }
  if (!charIds.length) {
    showToast("没有可邀请的角色（请先添加单聊密谈角色）");
    return;
  }
  showToast(`正在邀请 ${charIds.length} 位角色评论…`);
  queueMomentsCharReactions(async () => {
    for (const cid of charIds) {
      await runMomentsCharReactionForChar(mid, cid, { type: "invite_comment" });
      await new Promise((r) => setTimeout(r, 500 + Math.floor(Math.random() * 900)));
    }
    replaceMomentsPostInFeed(mid);
    scheduleMomentsFeedRender(true);
  });
}

/**
 * 从角色卡「NPC 关系」文本解析 NPC 列表。
 * @param {string} raw
 * @returns {{ name: string, note: string }[]}
 */
function parseNpcEntriesFromRelationsText(raw) {
  const text = String(raw || "").trim();
  if (!text) return [];
  /** @type {{ name: string, note: string }[]} */
  const out = [];
  /** @type {Set<string>} */
  const seen = new Set();
  for (let line of text.split(/\n+/).map((s) => String(s || "").trim()).filter(Boolean)) {
    line = line.replace(/^[-*•·\d]+[.)）、\s]*/u, "").trim();
    if (!line) continue;
    let name = "";
    let note = "";
    const m1 = line.match(/^([^:：\-—–|｜]+?)[:：\-—–|｜]\s*(.+)$/u);
    if (m1) {
      name = m1[1].trim();
      note = m1[2].trim();
    } else {
      const m2 = line.match(/^(.+?)（([^）]+)）\s*$/u);
      if (m2) {
        name = m2[1].trim();
        note = m2[2].trim();
      } else if (line.length <= 20 && !/[，,。；;]/u.test(line)) {
        name = line;
      } else {
        continue;
      }
    }
    name = name.replace(/^[@＠]/u, "").trim();
    if (name.length < 2 || name.length > 24) continue;
    if (/^(?:NPC|npc|角色|人物|关系|others?)$/iu.test(name)) continue;
    const key = name.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ name, note: note.slice(0, 200) });
  }
  return out.slice(0, 24);
}

/** @param {ReturnType<typeof normalizeMoment>} mm */
function resolveMomentNpcContextCharId(maskId, mm) {
  if (mm.kind === "char") {
    return resolveMomentCharId(mm);
  }
  const sourceCharId = String(mm.sourceCharId || "").trim();
  if (sourceCharId) return sourceCharId;
  for (const cid of listMomentsPostableCharIds(maskId)) {
    const ch = getCharPersonaItemById(cid);
    if (String(ch?.npcRelations || "").trim()) return cid;
  }
  return "";
}

/**
 * @param {string} name
 * @returns {string}
 */
function findCharPersonaIdByDisplayName(name) {
  const key = String(name || "").trim().toLowerCase();
  if (!key) return "";
  for (const it of readCharPersonaStore().items) {
    const cid = String(it?.id || "").trim();
    if (!cid) continue;
    if (charDisplayNameById(cid).toLowerCase() === key) return cid;
  }
  return "";
}

/**
 * @param {ReturnType<typeof normalizeMoment>} mm
 * @returns {{ charId: string, charName: string, entries: { name: string, note: string, charId: string, kind: "char"|"npc" }[], ident: ReturnType<typeof resolveMomentsCharIdentity> | null }}
 */
function listMomentInviteRelationCandidates(maskId, mm) {
  const mid = String(maskId || "").trim();
  const cid = resolveMomentNpcContextCharId(mid, mm);
  if (!cid) return { charId: "", charName: "", entries: [], ident: null };
  const tid = mm.kind === "char" ? String(mm.threadId || "").trim() : "";
  const slot = getMomentPostPersonaSlot(mm);
  const ident = resolveMomentsCharIdentity(mid, cid, tid, slot);
  const charName = ident.displayName || "角色";
  const userLabel = resolveUserMaskDisplayLabelForInbox(mid);
  const posterCharId = mm.kind === "char" ? String(resolveMomentCharId(mm) || cid).trim() : "";

  /** @type {{ name: string, charId: string, kind: "char"|"npc" }[]} */
  const entries = [];
  /** @type {Set<string>} */
  const seen = new Set();

  const pushEntry = (row) => {
    const name = String(row?.name || "").trim();
    if (name.length < 2) return;
    const linkedId = String(row?.charId || "").trim();
    const key = (linkedId || name).toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    const kind = linkedId && getCharPersonaItemById(linkedId) ? "char" : "npc";
    entries.push({
      name,
      charId: kind === "char" ? linkedId : "",
      kind
    });
  };

  if (typeof window.listCharRelationNetworkEntries === "function") {
    for (const row of window.listCharRelationNetworkEntries(mid, cid)) {
      pushEntry(row);
    }
  }

  const npcRaw = String(ident.persona.npcRelations || ident.charItem?.npcRelations || "").trim();
  for (const n of parseNpcEntriesFromRelationsText(npcRaw)) {
    const matched = findCharPersonaIdByDisplayName(n.name);
    pushEntry({ name: n.name, charId: matched });
  }

  const exclude = new Set([charName, userLabel, "主控", "我"].map((x) => String(x || "").trim().toLowerCase()));
  const cmts = Array.isArray(mm.comments) ? mm.comments : [];
  const commentedNpc = new Set(
    cmts
      .filter((c) => c && c.authorKind === "npc")
      .map((c) => String(c.authorName || "").trim().toLowerCase())
  );
  const commentedChar = new Set(
    cmts
      .filter((c) => c && c.authorKind === "char")
      .map((c) => String(c.authorName || "").trim().toLowerCase())
  );

  const filtered = entries.filter((e) => {
    const nk = e.name.toLowerCase();
    if (exclude.has(nk)) return false;
    if (posterCharId && e.charId && e.charId === posterCharId) return false;
    if (e.kind === "char" && commentedChar.has(nk)) return false;
    if (e.kind === "npc" && commentedNpc.has(nk)) return false;
    return true;
  });

  return { charId: cid, charName, entries: filtered, ident };
}

/** @param {{ name: string, charId?: string, kind?: string }[]} entries @param {number} [max] */
function pickMomentInviteRelationBatch(entries, max = MOMENTS_NPC_INVITE_MAX) {
  const list = entries.slice();
  for (let i = list.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [list[i], list[j]] = [list[j], list[i]];
  }
  return list.slice(0, Math.min(Math.max(1, Math.floor(Number(max) || 4)), list.length));
}

function parseMomentsNpcCommentResponse(raw) {
  let text = String(raw || "").trim();
  if (!text || /\[IGNORE\]/i.test(text)) return { ignore: true, commentText: "" };
  text = text
    .replace(/^```[\w]*\n?/gm, "")
    .replace(/```$/g, "")
    .trim();
  text = text
    .replace(/\[IGNORE\]/gi, "")
    .replace(/^\[COMMENT\]\s*/i, "")
    .replace(/\[POST_IMAGE:[^\]]*\]/gi, "")
    .replace(/\s*\n+\s*/g, " ")
    .replace(/\s{2,}/g, " ")
    .trim()
    .slice(0, MOMENTS_COMMENT_MAX_LEN);
  return text ? { ignore: false, commentText: text } : { ignore: true, commentText: "" };
}

/**
 * @param {string} maskId
 * @param {ReturnType<typeof normalizeMoment>} mm
 * @param {{ charName: string, ident: ReturnType<typeof resolveMomentsCharIdentity> }} ctx
 */
function buildMomentsNpcCommentPromptUser(maskId, mm, ctx) {
  const userLabel = resolveUserMaskDisplayLabelForInbox(maskId);
  const poster =
    mm.kind === "user"
      ? `用户 ${userLabel}`
      : `角色 ${String(mm.displayName || ctx.charName).trim()}`;
  const body = `"${getMomentPostDisplayText(mm) || "（无文字）"}"`;
  const imgNote = momentsPostImageNoteForReactionPrompt(mm);
  return [
    `[事件] 主控邀请你在朋友圈对这条动态留言。`,
    `发帖人：${poster}`,
    `动态${imgNote}：\n${body}`
  ].join("\n");
}

/**
 * @param {string} maskId
 * @param {ReturnType<typeof normalizeMoment>} mm
 * @param {{ name: string }} npcEntry
 * @param {{ charName: string, ident: ReturnType<typeof resolveMomentsCharIdentity> }} ctx
 */
async function requestMomentsNpcCommentAi(maskId, mm, npcEntry, ctx) {
  const ai = window.RP_AI;
  if (!ai || typeof ai.chatCompletions !== "function") return "";
  const { charName, ident } = ctx;
  const th = ident.th;
  const threadWbIds = normalizeWorldBookVolumeIdsArray(
    th?.worldBookVolumeIds,
    th?.defaultWorldBookVolumeId
  );
  const personaWbIds = normalizeWorldBookVolumeIdsArray(
    ident.persona.worldBookVolumeIds,
    ident.persona.defaultWorldBookVolumeId
  );
  const wbIds = Array.from(new Set([...threadWbIds, ...personaWbIds])).slice(0, 4);
  const userLabel = resolveUserMaskDisplayLabelForInbox(maskId);
  const wb = buildWorldBookBlockForVolumeIds(wbIds, charName, userLabel);
  const promptUser = buildMomentsNpcCommentPromptUser(maskId, mm, ctx);
  const userContent = await buildMomentsCharReactionUserMessageContent(mm, promptUser);
  const system = [
    `你是「${npcEntry.name}」，在微信朋友圈时间线里给一条动态写评论。`,
    `你不是密谈角色「${charName}」，也不是主控用户；只以 ${npcEntry.name} 的身份说话。`,
    wb ? `【世界设定参考】\n${wb.slice(0, 2400)}` : "",
    "用简体中文写评论：口语、一两到三句、单行不换行，把话说完整；像普通人随手评一句。",
    "不要在评论里说明或暗示你和发帖人的关系标签（如闺蜜、同事等）。",
    "不想评就输出 [IGNORE]；只输出评论正文或 [IGNORE]，不要 JSON、不要 @、不要旁白/剧本标注。"
  ]
    .filter(Boolean)
    .join("\n\n");
  try {
    const data = await ai.chatCompletions({
      messages: [
        { role: "system", content: system },
        { role: "user", content: userContent }
      ],
      temperature: 0.9
    });
    return readMomentsPostCompletionText(data);
  } catch (e) {
    console.warn("[moments] npc comment failed", npcEntry.name, e);
    return "";
  }
}

function applyMomentsNpcComment(momentId, npcName, commentText) {
  const text = String(commentText || "").trim();
  if (!text) return;
  patchMomentById(momentId, (m) => {
    const arr = Array.isArray(m.comments) ? m.comments : [];
    arr.push({
      id: newEntityId(),
      authorKind: "npc",
      authorName: String(npcName || "NPC").trim().slice(0, 32),
      timeIso: new Date().toISOString(),
      text: text.slice(0, MOMENTS_COMMENT_MAX_LEN),
      replyToCommentId: ""
    });
    m.comments = arr;
  });
}

/**
 * @param {string} momentId
 * @param {string} maskId
 * @param {ReturnType<typeof normalizeMoment>} mm
 * @param {{ name: string }} npcEntry
 * @param {{ charId: string, charName: string, ident: ReturnType<typeof resolveMomentsCharIdentity> }} ctx
 */
async function runMomentsNpcCommentForNpc(momentId, maskId, mm, npcEntry, ctx) {
  const parsed = parseMomentsNpcCommentResponse(
    await requestMomentsNpcCommentAi(maskId, mm, npcEntry, {
      charName: ctx.charName,
      ident: ctx.ident
    })
  );
  if (parsed.ignore || !parsed.commentText) return;
  applyMomentsNpcComment(momentId, npcEntry.name, parsed.commentText);
}

async function inviteNpcsToCommentOnMoment(momentId) {
  const ai = window.RP_AI;
  if (!ai?.chatCompletions) {
    showToast("AI 未加载");
    return;
  }
  const mid = String(momentId || "").trim();
  if (!mid) return;
  const { maskId, bucket } = getActiveMomentsBucket();
  if (!maskId) return;
  const raw = (Array.isArray(bucket.moments) ? bucket.moments : []).find((m) => String(m?.id || "") === mid);
  if (!raw) return;
  const mm = normalizeMoment(raw);
  const ctx = listMomentInviteRelationCandidates(maskId, mm);
  if (!ctx.charId || !ctx.ident) {
    showToast("找不到对应角色");
    return;
  }
  if (!ctx.entries.length) {
    showToast("关系网还没有可邀请的人，或都已评过");
    return;
  }
  const batch = pickMomentInviteRelationBatch(ctx.entries);
  const charN = batch.filter((e) => e.kind === "char" && e.charId).length;
  const npcN = batch.length - charN;
  const hint =
    charN && npcN
      ? `${charN} 位角色、${npcN} 位关系人`
      : charN
        ? `${charN} 位角色`
        : `${npcN} 位关系人`;
  showToast(`正在邀请关系网 · ${hint}…`);
  queueMomentsCharReactions(async () => {
    for (const entry of batch) {
      if (entry.kind === "char" && entry.charId) {
        await runMomentsCharReactionForChar(mid, entry.charId, {
          type: "invite_comment"
        });
      } else {
        await runMomentsNpcCommentForNpc(
          mid,
          maskId,
          mm,
          { name: entry.name },
          ctx
        );
      }
      await new Promise((r) => setTimeout(r, 500 + Math.floor(Math.random() * 900)));
    }
    replaceMomentsPostInFeed(mid);
    scheduleMomentsFeedRender(true);
  });
}

function deleteMomentById(momentId) {
  const mid = String(momentId || "").trim();
  if (!mid) return false;
  const { inbox, maskId, bucket } = getActiveMomentsBucket();
  if (!maskId) return false;
  const arr = Array.isArray(bucket.moments) ? bucket.moments : [];
  const next = arr.filter((m) => String(m?.id || "") !== mid);
  if (next.length === arr.length) return false;
  bucket.moments = next;
  writeChatInboxStore(inbox, { fast: true });
  return true;
}

function deleteMomentWithConfirm(momentId) {
  if (!confirm("删除这条动态？删除后无法恢复。")) return false;
  if (!deleteMomentById(momentId)) {
    showToast("删除失败");
    return false;
  }
  closeAllMomentsPostMoreMenus();
  scheduleMomentsFeedRender(true);
  showToast("已删除");
  return true;
}

/** @param {string} momentId @param {string} commentId */
function deleteMomentCommentById(momentId, commentId) {
  const mid = String(momentId || "").trim();
  const cid = String(commentId || "").trim();
  if (!mid || !cid) return false;
  let removed = false;
  const ok = patchMomentById(mid, (m) => {
    const arr = Array.isArray(m.comments) ? m.comments : [];
    const next = arr.filter((c) => String(c?.id || "") !== cid);
    if (next.length === arr.length) return;
    m.comments = next;
    removed = true;
  });
  if (!ok || !removed) return false;
  if (momentsInlineReply.momentId === mid && momentsInlineReply.commentId === cid) {
    momentsInlineReply = { momentId: "", commentId: "" };
  }
  return true;
}

/** @param {string} momentId @param {string} commentId */
function deleteMomentCommentWithConfirm(momentId, commentId) {
  if (!confirm("删除这条评论？")) return false;
  if (!deleteMomentCommentById(momentId, commentId)) {
    showToast("删除失败");
    return false;
  }
  replaceMomentsPostInFeed(momentId);
  showToast("已删除评论");
  return true;
}

/** @type {HTMLElement | null} */
let momentsPostMoreOpenWrap = null;

function closeAllMomentsPostMoreMenus() {
  if (!momentsPostMoreOpenWrap) return;
  const menu = momentsPostMoreOpenWrap.querySelector(".moments-post-more-menu");
  const btn = momentsPostMoreOpenWrap.querySelector(".moments-post-more-btn");
  if (menu) menu.hidden = true;
  if (btn) btn.setAttribute("aria-expanded", "false");
  momentsPostMoreOpenWrap.classList.remove("is-open");
  momentsPostMoreOpenWrap = null;
}

function toggleMomentsPostMoreMenu(wrap) {
  if (!(wrap instanceof HTMLElement)) return;
  if (momentsPostMoreOpenWrap === wrap) {
    closeAllMomentsPostMoreMenus();
    return;
  }
  closeAllMomentsPostMoreMenus();
  const menu = wrap.querySelector(".moments-post-more-menu");
  const btn = wrap.querySelector(".moments-post-more-btn");
  if (!menu || !btn) return;
  menu.hidden = false;
  btn.setAttribute("aria-expanded", "true");
  wrap.classList.add("is-open");
  momentsPostMoreOpenWrap = wrap;
}

function appendMomentsPostMoreMenu(head, mm) {
  const wrap = document.createElement("div");
  wrap.className = "moments-post-more-wrap";
  wrap.dataset.momentId = String(mm.id || "");
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "moments-post-more-btn";
  btn.setAttribute("aria-label", "更多操作");
  btn.setAttribute("aria-haspopup", "menu");
  btn.setAttribute("aria-expanded", "false");
  btn.innerHTML = '<i class="ph ph-dots-three" aria-hidden="true"></i>';
  const menu = document.createElement("div");
  menu.className = "moments-post-more-menu chat-thread-bead-menu";
  menu.setAttribute("role", "menu");
  menu.hidden = true;
  const inviteBtn = document.createElement("button");
  inviteBtn.type = "button";
  inviteBtn.className = "chat-thread-bead-menu-item";
  inviteBtn.setAttribute("role", "menuitem");
  inviteBtn.dataset.action = "invite-char-comment";
  inviteBtn.textContent = "邀请角色评论";
  const inviteNpcBtn = document.createElement("button");
  inviteNpcBtn.type = "button";
  inviteNpcBtn.className = "chat-thread-bead-menu-item";
  inviteNpcBtn.setAttribute("role", "menuitem");
  inviteNpcBtn.dataset.action = "invite-npc-comment";
  inviteNpcBtn.textContent = "邀请关系网评论";
  const delBtn = document.createElement("button");
  delBtn.type = "button";
  delBtn.className = "chat-thread-bead-menu-item chat-thread-bead-menu-item--danger";
  delBtn.setAttribute("role", "menuitem");
  delBtn.dataset.action = "delete";
  delBtn.textContent = "删除动态";
  menu.append(inviteBtn, inviteNpcBtn, delBtn);
  wrap.append(btn, menu);
  head.appendChild(wrap);
}

/** 当前面具下可发朋友圈的角色（有单聊密谈的人设；否则回退到整个人设库） */
function listMomentsPostableCharIds(maskId) {
  const mid = String(maskId || "").trim();
  if (!mid) return [];
  const inbox = readChatInboxStore();
  const bucket = inbox.byMask[maskBucketKey(mid)];
  const ids = new Set();
  if (bucket) {
    for (const t of Array.isArray(bucket.threads) ? bucket.threads : []) {
      if (!t || t.kind === "group") continue;
      const cid = String(t.charId || "").trim();
      if (cid) ids.add(cid);
    }
  }
  if (!ids.size) {
    for (const it of readCharPersonaStore().items) {
      const id = String(it.id || "").trim();
      if (id) ids.add(id);
    }
  }
  return [...ids];
}

const MOMENTS_POST_NARRATION_LINE_RE =
  /^(?:【\s*旁白\s*】|［旁白］|\[旁白\]|（旁白）|\(旁白\)|旁白[：:·\s])/iu;

function chineseCharRatioInText(s) {
  const t = String(s || "");
  if (!t) return 0;
  const han = (t.match(/[\u4e00-\u9fff]/g) || []).length;
  return han / Math.max(1, t.length);
}

function isMostlyNonChineseMomentLine(line) {
  const t = String(line || "").trim();
  if (t.length < 5) return false;
  const han = chineseCharRatioInText(t);
  const kana = (t.match(/[\u3040-\u30ff]/g) || []).length;
  if (han >= Math.max(4, t.length * 0.28)) return false;
  if (kana >= 6 && han < 3) return true;
  if (/^[\u3040-\u30ff\u31f0-\u31ff\s。、！？.,!?\-]+$/u.test(t) && han < 2) return true;
  return false;
}

function isMomentsPostNarrationOrScriptLine(line) {
  const s = String(line ?? "").trim();
  if (!s) return true;
  return MOMENTS_POST_NARRATION_LINE_RE.test(s);
}

function momentTextLooksPublishable(text) {
  const t = polishMomentsCharPostDisplayText(text);
  if (t.length < 4) return false;
  const han = (t.match(/[\u4e00-\u9fff]/g) || []).length;
  return han >= 2 && han >= Math.floor(t.length * 0.08);
}

/** 发布前清洗正文（去掉配图标记等；无内容则留空，不塞占位文案）。 */
function coerceMomentsPublishBody(raw) {
  const src = String(raw || "").trim();
  let t = stripMomentsPostTagsOnly(src);
  if (!t) t = polishMomentsCharPostDisplayText(src);
  if (!t) t = src.replace(/\[(?:POST_IMAGE|POST_IMG):[^\]]*\]/gi, "").trim();
  return t.slice(0, 2000);
}

/** 发圈 AI 专用：只去掉旁白标记与配图指令，不把整段正文误删空。 */
function polishMomentsCharPostDisplayText(raw) {
  let text = String(raw || "").trim();
  if (!text || /^\[IGNORE\]\s*$/i.test(text)) return "";
  text = text.replace(/^```[\w]*\n?/gm, "").replace(/```$/g, "").trim();
  text = text.replace(/^\[POST\]\s*/i, "").trim();
  text = text.replace(/\[POST_IMAGE:[^\]]*\]/gi, "").trim();
  text = text
    .replace(/^(?:【\s*旁白\s*】|［旁白］|\[旁白\]|（旁白）|\(旁白\))\s*/gu, "")
    .trim();
  text = text.replace(/^旁白[：:·]\s*/u, "").trim();
  const lines = text.split(/\n+/).map((s) => String(s).trim()).filter(Boolean);
  const kept = lines.filter((l) => !isMomentsPostNarrationOrScriptLine(l));
  text = (kept.length ? kept.join("\n") : lines.join("\n")).trim();
  return text.slice(0, 2000);
}

function emptyMomentsCharPostAiResult(ignore = true) {
  return { text: "", imagePlan: { mode: "none", pickIndex: 0, genCaption: "" }, ignore };
}

/**
 * @param {string} maskId
 * @param {string} threadId
 * @param {number} [maxItems]
 * @returns {{ index: number, role: string, label: string, desc: string, url: string, at: number }[]}
 */
function collectMomentsCharImageCandidates(maskId, threadId, maxItems = 10) {
  const mid = String(maskId || "").trim();
  const tid = String(threadId || "").trim();
  if (!mid || !tid) return [];
  const log = readChatLogForMaskThread(mid, tid);
  const cap = Math.min(16, Math.max(1, Math.floor(Number(maxItems) || 10)));
  const rev = [];
  for (let i = log.length - 1; i >= 0 && rev.length < cap; i--) {
    const row = log[i];
    if (!row || (row.role !== "user" && row.role !== "assistant")) continue;
    const im = row.image && typeof row.image === "object" ? row.image : null;
    if (!im) continue;
    if (im.imageGenPending && !String(im.url || "").trim()) continue;
    let url = sanitizeMomentImageUrl(String(im.url || "").trim());
    if (!url) url = sanitizeStickerUrl(String(im.url || "").trim());
    if (!url) {
      const fromContent = String(row.content || "").match(/data:image\/[\w+.-]+;base64,[A-Za-z0-9+/=]+/i);
      if (fromContent) url = sanitizeMomentImageUrl(fromContent[0]);
    }
    if (!url) continue;
    let desc = String(im.desc || "").trim();
    if (row.role === "user" && !desc) {
      desc = userChatImageCaptionFromContent(String(row.content || ""));
    }
    if (row.role === "assistant" && desc) {
      desc = sanitizeCharImageCaptionMeta(desc) || desc;
    }
    if (!desc) desc = row.role === "user" ? "\u7528\u6237\u53d1\u7684\u56fe" : "\u89d2\u8272\u914d\u56fe";
    rev.push({
      index: 0,
      role: row.role,
      label: row.role === "user" ? "\u7528\u6237\u53d1\u7684\u56fe" : "\u4f60\u7684\u914d\u56fe",
      desc: desc.slice(0, 120),
      url,
      at: Number(row.at) || 0
    });
  }
  rev.reverse();
  rev.forEach((x, i) => {
    x.index = i + 1;
  });
  return rev;
}

function buildMomentsCharPostImageCatalogue(candidates) {
  const list = Array.isArray(candidates) ? candidates : [];
  if (!list.length) return "";
  const lines = list.map((c) => `${c.index}. ${c.label} \u00b7 ${c.desc}`);
  return `\n[\u53ef\u9009\u914d\u56fe\u7d20\u6750\uff08pick \u7528\u5e8f\u53f7\uff09]\n${lines.join("\n")}`;
}

/** 发圈 hint 是否在要求带上密谈里用户发的照片。 */
function momentHintRequestsUserChatImage(hint) {
  const h = String(hint || "").trim();
  if (!h) return false;
  return /(?:我|你|咱|刚才|刚刚|上次|那张|这张|上传|发(?:过|的|给你)?).{0,10}(?:图|照片|相片|图片)|(?:图|照片|相片|图片).{0,8}(?:发圈|朋友圈|动态|分享|带上)/i.test(
    h
  );
}

function momentsPublishWantsUserChatImage(momentHint, directText, imagePlan) {
  return (
    momentHintRequestsUserChatImage(momentHint) ||
    momentHintRequestsUserChatImage(directText) ||
    (imagePlan && imagePlan.mode === "pick")
  );
}

/** @param {{ role?: string, url?: string, index?: number }[]} candidates */
function pickLastUserMomentsImageCandidate(candidates) {
  const list = Array.isArray(candidates) ? candidates : [];
  for (let i = list.length - 1; i >= 0; i--) {
    const c = list[i];
    if (c && String(c.role || "") === "user" && String(c.url || "").trim()) return c;
  }
  return null;
}

function sanitizeMomentImageUrl(raw) {
  const s = String(raw || "").trim();
  if (!s) return "";
  if (/^data:image\//i.test(s)) return s;
  if (/^https?:\/\//i.test(s)) return s;
  if (/^\/\/\S+/i.test(s)) return `https:${s}`;
  if (/^blob:/i.test(s)) return s;
  if (isChatImageBlobRef(s)) return s;
  return "";
}

/** @param {ReturnType<typeof normalizeMoment> | null | undefined} mm */
function getMomentPostStoredImageUrls(mm) {
  return (Array.isArray(mm?.images) ? mm.images : [])
    .map((x) => sanitizeMomentImageUrl(String(x || "").trim()))
    .filter(Boolean)
    .slice(0, MOMENTS_POST_MAX_IMAGES);
}

/** @param {string[]} stored */
async function resolveMomentPostImageUrlsForApi(stored) {
  if (!stored.length) return [];
  const map = await hydrateChatImageBlobRefsForApi(stored.filter((u) => isChatImageBlobRef(u)));
  /** @type {string[]} */
  const out = [];
  for (const raw of stored) {
    let url = resolveChatImageUrlForApi(raw, map);
    if (!url && /^blob:/i.test(raw)) {
      try {
        const blob = await (await fetch(raw)).blob();
        const du = await blobToDataUrl(blob);
        if (/^data:image\//i.test(du)) url = du;
      } catch {
        /* ignore */
      }
    }
    if (url && !isChatImageBlobRef(url)) out.push(url);
  }
  return out;
}

/** @param {ReturnType<typeof normalizeMoment> | null | undefined} mm @param {string} promptText */
async function buildMomentsCharReactionUserMessageContent(mm, promptText) {
  const text = String(promptText || "").trim();
  if (!text) return "";
  const apiUrls = await resolveMomentPostImageUrlsForApi(getMomentPostStoredImageUrls(mm));
  if (!apiUrls.length) {
    const descCards = getMomentPostImageDescCards(mm);
    if (descCards.length) {
      return `${text}\n\n[配图暂未能直传模型，仅文字描述：${descCards.slice(0, 3).join("；")}]`;
    }
    return text;
  }
  /** @type {Array<{ type: "image_url", image_url: { url: string } } | { type: "text", text: string }>} */
  const parts = apiUrls.map((url) => ({
    type: "image_url",
    image_url: { url }
  }));
  parts.push({ type: "text", text });
  return parts;
}

/** @param {ReturnType<typeof normalizeMoment> | null | undefined} mm */
function momentsPostImageNoteForReactionPrompt(mm) {
  const imgs = getMomentPostStoredImageUrls(mm);
  const descCards = getMomentPostImageDescCards(mm);
  if (imgs.length) {
    return imgs.length === 1 ? "（带配图）" : `（带 ${imgs.length} 张配图）`;
  }
  if (descCards.length) {
    return `（带文字示意配图：${descCards.slice(0, 3).join("；")}）`;
  }
  return "";
}

function appendMomentsImageDescToText(text, caption) {
  const cap = String(caption || "")
    .trim()
    .replace(/\[(?:POST_IMAGE|POST_IMG):[^\]]*\]/gi, "")
    .slice(0, 160);
  if (!cap) return String(text || "").trim();
  const body = String(text || "").trim();
  if (body.includes(cap.slice(0, Math.min(12, cap.length)))) return body.slice(0, 2000);
  const tag = `\uff08\u914d\u56fe\uff1a${cap}\uff09`;
  return `${body}${body ? "\n" : ""}${tag}`.trim().slice(0, 2000);
}

/** 从正文里拆出「（配图：…）」描述，供拍立得相框展示。 */
function extractMomentsInlineImageDescFromText(raw) {
  const src = String(raw || "").trim();
  if (!src) return { text: "", caption: "" };
  const re = /[（(]\s*配图\s*[：:]\s*([^）)\n]+?)\s*[）)]/g;
  let caption = "";
  let m;
  while ((m = re.exec(src)) !== null) {
    const c = String(m[1] || "").trim();
    if (c) caption = c;
  }
  const text = src
    .replace(re, "")
    .replace(/[ \t]{2,}/g, " ")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
  return { text: text.slice(0, 2000), caption: caption.slice(0, 500) };
}

function getMomentPostImageDescCards(mm) {
  const stored = (Array.isArray(mm?.imageDescCards) ? mm.imageDescCards : [])
    .map((x) => String(x || "").trim())
    .filter(Boolean)
    .slice(0, MOMENTS_POST_MAX_IMAGES);
  if (stored.length) return stored;
  const inline = extractMomentsInlineImageDescFromText(mm?.text);
  return inline.caption ? [inline.caption] : [];
}

function getMomentPostDisplayText(mm) {
  const text = String(mm?.text || "").trim();
  if (!getMomentPostImageDescCards(mm).length) return text;
  return extractMomentsInlineImageDescFromText(text).text;
}

/** 去掉配图指令行/标记，保留完整口语正文（不按 ||| 拆段过滤）。 */
function stripMomentsPostTagsOnly(raw) {
  let text = String(raw || "").trim();
  if (!text) return "";
  text = text.replace(/^```[\w]*\n?/gm, "").replace(/```$/g, "").trim();
  text = text.replace(/\[IGNORE\]/gi, " ").trim();
  text = text.replace(/\[POST_IMG:[\s\S]+?:[\s\S]+?\]/gi, "").trim();
  const lines = text.split(/\n/);
  const kept = lines.filter((ln) => {
    const t = String(ln || "").trim();
    return t && !/^\[(?:POST_IMAGE|POST_IMG):/i.test(t);
  });
  text = (kept.length ? kept.join("\n") : text).trim();
  text = text.replace(/\[(?:POST_IMAGE|POST_IMG):[^\]]*\]/gi, "").trim();
  return text.slice(0, 2000);
}

function extractMomentsImageTagFromLine(line) {
  const ln = String(line || "").trim();
  if (!ln) return null;
  const pickM = ln.match(/\[POST_IMAGE:pick:(\d+)\]/i);
  if (pickM) {
    return { mode: "pick", pickIndex: Math.max(1, Math.floor(Number(pickM[1]) || 0)), genCaption: "" };
  }
  const genM = ln.match(/\[POST_IMAGE:gen:(.+)\]/i);
  if (genM) {
    return { mode: "gen", pickIndex: 0, genCaption: String(genM[1] || "").trim().slice(0, 500) };
  }
  const descM = ln.match(/\[POST_IMAGE:desc:(.+)\]/i);
  if (descM) {
    return { mode: "desc", pickIndex: 0, genCaption: String(descM[1] || "").trim().slice(0, 500) };
  }
  const postImgM = ln.match(/\[POST_IMG:([\s\S]+?):([\s\S]+)\]/i);
  if (postImgM) {
    return {
      mode: "gen",
      pickIndex: 0,
      genCaption: String(postImgM[2] || "").trim().slice(0, 500),
      embeddedPost: String(postImgM[1] || "").trim().slice(0, 2000)
    };
  }
  if (/\[POST_IMAGE:none\]/i.test(ln)) return { mode: "none", pickIndex: 0, genCaption: "" };
  return null;
}

/** 配图指令只从末尾几行解析，避免误吞正文。 */
function splitMomentsCharPostBodyAndImagePlan(rawText) {
  const imagePlan = { mode: "none", pickIndex: 0, genCaption: "", embeddedPost: "" };
  const blob = String(rawText || "").trim();
  if (!blob) return { text: "", imagePlan };
  const lines = String(blob).split(/\n/);
  let tagStart = lines.length;
  for (let i = lines.length - 1; i >= 0; i--) {
    const ln = String(lines[i] || "").trim();
    if (!ln) {
      tagStart = i;
      continue;
    }
    const hit = extractMomentsImageTagFromLine(ln);
    if (hit) {
      tagStart = i;
      if (hit.embeddedPost) imagePlan.embeddedPost = hit.embeddedPost;
      imagePlan.mode = hit.mode;
      imagePlan.pickIndex = hit.pickIndex || 0;
      imagePlan.genCaption = hit.genCaption || "";
    } else {
      break;
    }
  }
  let text = lines.slice(0, tagStart).join("\n");
  text = stripMomentsPostTagsOnly(text);
  if (!text && imagePlan.embeddedPost) text = String(imagePlan.embeddedPost || "").trim();
  return { text, imagePlan };
}

function normalizeMomentsCharPostImagePlan(imagePlan, candidates, genEnabled) {
  const plan =
    imagePlan && typeof imagePlan === "object"
      ? { ...imagePlan }
      : { mode: "none", pickIndex: 0, genCaption: "" };
  const list = Array.isArray(candidates) ? candidates : [];
  if (plan.mode === "gen" && !genEnabled) {
    if (list.length) {
      plan.mode = "pick";
      plan.pickIndex = list[list.length - 1].index;
    } else if (String(plan.genCaption || "").trim()) {
      plan.mode = "desc";
    } else {
      plan.mode = "none";
    }
  }
  const cap = String(plan.genCaption || "").trim();
  if (cap && genEnabled && plan.mode === "desc") {
    plan.mode = "gen";
  }
  return plan;
}

/**
 * @param {string} raw
 * @returns {{ text: string, imagePlan: { mode: "none" | "pick" | "gen", pickIndex: number, genCaption: string }, ignore: boolean }}
 */
function normalizeMomentsCharPostBodyForPublish(raw) {
  let text = stripMomentsPostTagsOnly(String(raw || ""));
  if (!text) return "";
  text = text.replace(/\|\|\|/g, "\n").trim();
  text = text.replace(/[ \t]+\n/g, "\n").replace(/\n{3,}/g, "\n\n").trim();
  return text.slice(0, 2000);
}

function parseMomentsCharPostResponse(raw) {
  const blob = String(raw || "").trim();
  if (!blob) return emptyMomentsCharPostAiResult(true);
  if (/^\[IGNORE\]\s*$/i.test(blob)) {
    return emptyMomentsCharPostAiResult(true);
  }
  const split = splitMomentsCharPostBodyAndImagePlan(blob);
  const imagePlan = split.imagePlan;
  const hasImage =
    imagePlan.mode === "pick" || imagePlan.mode === "gen" || imagePlan.mode === "desc";
  let text = normalizeMomentsCharPostBodyForPublish(split.text);
  if (!text && !hasImage) return emptyMomentsCharPostAiResult(true);
  return {
    text,
    imagePlan,
    ignore: false
  };
}

/** @param {string} url */
async function persistMomentImageDataUrl(url) {
  let u = sanitizeMomentImageUrl(String(url || "").trim());
  if (!u) return "";
  if (/^blob:/i.test(u)) {
    try {
      const blob = await (await fetch(u)).blob();
      const du = await blobToDataUrl(blob);
      if (/^data:image\//i.test(du)) u = du;
      else return "";
    } catch {
      return "";
    }
  }
  if (isChatImageBlobRef(u)) {
    try {
      const hydrated = String((await hydrateChatImageStoredUrl(u)) || "").trim();
      if (/^data:image\//i.test(hydrated)) u = hydrated;
      else if (/^blob:/i.test(hydrated)) {
        const blob = await (await fetch(hydrated)).blob();
        const du = await blobToDataUrl(blob);
        if (/^data:image\//i.test(du)) u = du;
        else return "";
      } else return "";
    } catch {
      return "";
    }
  }
  if (/^data:image\//i.test(u)) {
    try {
      return (await shrinkDataUrlWithCanvas(u, 960, 0.85)) || u;
    } catch {
      return u.length > 3_500_000 ? u.slice(0, 3_500_000) : u;
    }
  }
  if (/^https?:\/\//i.test(u)) return u;
  return "";
}

/**
 * @param {{ mode: string, pickIndex?: number, genCaption?: string }} imagePlan
 * @param {{ index: number, url: string }[]} candidates
 * @param {object | null} thread
 * @param {string} maskId
 * @returns {Promise<string[]>}
 */
async function resolveMomentsCharPostImages(imagePlan, candidates, thread, maskId) {
  try {
    return await resolveMomentsCharPostImagesInner(imagePlan, candidates, thread, maskId);
  } catch (e) {
    console.warn("[moments] resolve post images failed", e);
    return [];
  }
}

/** 朋友圈生图主体：日常分享默认偏场景/静物，避免每条都是人像。 */
function inferMomentsPostImageSubject(caption) {
  const s = String(caption || "").trim();
  if (!s) return "scene";
  if (
    /(?:自拍|人像|半身|大头|肖像|证件照|face|portrait|selfie|1girl|1boy|solo|looking at viewer)/i.test(
      s
    )
  ) {
    return "char";
  }
  if (
    /(?:风景|美食|咖啡|奶茶|餐|饭|猫|狗|宠物|花|天空|日落|夜景|静物|书本|办公桌|工位|路|街|海|山|雨|雪|food|landscape|still life|coffee|meal|cat|dog)/i.test(
      s
    )
  ) {
    return "scene";
  }
  if (/(?:物品|道具|object)/i.test(s)) return "object";
  return "scene";
}

async function resolveMomentsCharPostImagesInner(imagePlan, candidates, thread, maskId) {
  const plan = imagePlan && typeof imagePlan === "object" ? imagePlan : { mode: "none" };
  const list = Array.isArray(candidates) ? candidates : [];
  if (plan.mode === "pick") {
    let hit = list.find((c) => c.index === plan.pickIndex);
    if (!hit && list.length) hit = list[list.length - 1];
    if (!hit) return [];
    const url = await persistMomentImageDataUrl(hit.url);
    return url ? [url] : [];
  }
  if (plan.mode === "desc") {
    const cap = String(plan.genCaption || "").trim();
    if (!cap) return [];
    if (isSessionImageGenConfigured()) {
      plan.mode = "gen";
    } else if (list.length) {
      let hit = list.find((c) => c.index === plan.pickIndex) || list[list.length - 1];
      if (hit) {
        const url = await persistMomentImageDataUrl(hit.url);
        if (url) return [url];
      }
    }
    return [];
  }
  if (plan.mode !== "gen") return [];
  const cap = String(plan.genCaption || "").trim();
  if (!cap || !isSessionImageGenConfigured()) {
    if (list.length) {
      let hit = list.find((c) => c.index === plan.pickIndex);
      if (!hit) hit = list[list.length - 1];
      if (hit) {
        const url = await persistMomentImageDataUrl(hit.url);
        return url ? [url] : [];
      }
    }
    return [];
  }
  const cfg = readImageGenConfig();
  const tid = thread ? String(thread.id || "").trim() : "";
  const mid = String(maskId || "").trim();
  const log = mid && tid ? readChatLogForMaskThread(mid, tid) : [];
  const fakeMsg = {
    role: "assistant",
    image: { desc: cap.replace(/\s+/g, " ").slice(0, 240), scenePrompt: cap.slice(0, 3500) }
  };
  applySessionImageSubjectOnRow(fakeMsg, thread, cap, log, inferMomentsPostImageSubject(cap));
  const sceneApi = getChatImageGenSceneBlockFromMessage(fakeMsg) || cap;
  const imgPlan = resolveImageGenPlan(fakeMsg, thread, sceneApi, log);
  const prompt = buildImageGenPromptForProvider(cfg, thread, sceneApi, {
    plan: imgPlan,
    msg: fakeMsg,
    logArr: log
  });
  let refDataUrl = "";
  if (imageGenPlanAllowsThreadRef(imgPlan) && thread && typeof thread === "object") {
    refDataUrl = resolveThreadCharImageRefDataUrl(thread);
  }
  const r = await executeImageGenRequestToDataUrl(cfg, prompt, {
    ...(refDataUrl ? { refDataUrl } : {}),
    preferLongTimeout: true
  });
  if (r.ok && r.dataUrl) {
    const url = await persistMomentImageDataUrl(r.dataUrl);
    if (url) return [url];
  }
  if (list.length) {
    let hit = list.find((c) => c.index === plan.pickIndex);
    if (!hit) hit = list[list.length - 1];
    if (hit) {
      const url = await persistMomentImageDataUrl(hit.url);
      return url ? [url] : [];
    }
  }
  return [];
}

/** @param {string} text
 * @param {{ mode: string, pickIndex?: number, genCaption?: string }} imagePlan
 * @param {{ index: number, desc?: string, url?: string }[]} candidates
 * @param {boolean} genEnabled
 * @param {boolean} [imagesResolved]
 */
function finalizeMomentsPostTextWithImageFallback(text, imagePlan, candidates, genEnabled, imagesResolved) {
  let out =
    stripMomentsPostTagsOnly(String(text || "").trim()) ||
    polishMomentsCharPostDisplayText(String(text || "").trim());
  const plan = imagePlan && typeof imagePlan === "object" ? imagePlan : { mode: "none" };
  const cap = String(plan.genCaption || "").trim();
  const list = Array.isArray(candidates) ? candidates : [];
  const hasImg = imagesResolved === true;
  out = extractMomentsInlineImageDescFromText(out).text;
  if (!hasImg && plan.mode === "desc" && cap) {
    out = appendMomentsImageDescToText(out, cap);
    if (!out) out = cap.slice(0, 2000);
  }
  if (!hasImg && plan.mode === "gen" && cap && genEnabled) {
    out = appendMomentsImageDescToText(out, cap);
  }
  if (!hasImg && plan.mode === "pick" && list.length) {
    const hit = list.find((c) => c.index === plan.pickIndex) || list[list.length - 1];
    if (hit?.desc) out = appendMomentsImageDescToText(out, hit.desc);
  }
  return coerceMomentsPublishBody(out);
}

/** @param {string} charId */
function getCharPersonaItemById(charId) {
  const cid = String(charId || "").trim();
  if (!cid) return null;
  const st = readCharPersonaStore();
  return st.items.find((x) => String(x.id || "") === cid) || null;
}

/**
 * 从人设摘要/边界推断「爱不爱发朋友圈」（启发式，供程序节流 + 提示 AI）。
 * @param {object | null | undefined} ch
 * @returns {{ level: "rare" | "low" | "normal" | "high", note: string, probeRoll: number, probeMult: number, postMult: number, fallbackMult: number }}
 */
function assessCharMomentsPostingInclination(ch) {
  const raw = [ch?.summary, ch?.boundaries, ch?.npcRelations]
    .map((x) => String(x || ""))
    .join("\n");
  const base = {
    level: "normal",
    note: "人设未写明社交习惯时，按角色常理决定；不必每轮都发。",
    probeRoll: 0.38,
    probeMult: 1,
    postMult: 1,
    fallbackMult: 1
  };
  if (!raw.trim()) return base;
  const reluctant = [
    /不爱发(?:朋友圈|圈|动态)/,
    /(?:很少|几乎不|从不|不怎么|极少|不太)发(?:朋友圈|圈|动态)/,
    /不发朋友圈|不玩朋友圈|不用朋友圈/,
    /(?:讨厌|厌恶|抗拒|排斥).{0,6}(?:朋友圈|发圈|社交软件)/,
    /(?:内向|社恐|低调).{0,12}(?:不爱|不喜|很少).{0,6}(?:分享|晒|发圈|朋友圈)/,
    /注重隐私|保护隐私|不喜.{0,4}炫耀/,
    /潜水(?:党|型)?|深居简出/,
    /(?:很少|几乎不).{0,6}(?:公开|晒)(?:生活|日常)/,
    /(?:rarely|seldom|never|almost never).{0,12}(?:post|share).{0,12}(?:moment|social)/i,
    /(?:hate|dislike|avoid).{0,12}(?:social media|posting online)/i,
    /introvert|private person|keeps? .*private/i
  ];
  const eager = [
    /爱发(?:朋友圈|圈|动态)/,
    /(?:常|经常|乐于|喜欢)发(?:朋友圈|圈|动态)/,
    /喜欢晒|乐于分享|朋友圈活跃/,
    /社交达人|网红|博主|up主/i,
    /(?:posts?|shares?).{0,12}(?:often|frequently|a lot)/i,
    /influencer|content creator/i
  ];
  let r = 0;
  let e = 0;
  for (const re of reluctant) {
    if (re.test(raw)) r += 1;
  }
  for (const re of eager) {
    if (re.test(raw)) e += 1;
  }
  if (r >= 2 || (r >= 1 && e === 0)) {
    return {
      level: "rare",
      note: "人设偏低调/不爱晒：通常极少或不发朋友圈。",
      probeRoll: 0.1,
      probeMult: 2.2,
      postMult: 3.2,
      fallbackMult: 3
    };
  }
  if (r >= 1) {
    return {
      level: "low",
      note: "人设偏内敛：只有很值得公开分享时才适合发圈。",
      probeRoll: 0.38,
      probeMult: 1.5,
      postMult: 1.85,
      fallbackMult: 1.6
    };
  }
  if (e >= 1) {
    return {
      level: "high",
      note: "人设偏外向/爱分享：有合适素材时更可能想发圈，但仍勿硬凑。",
      probeRoll: 0.9,
      probeMult: 0.82,
      postMult: 0.78,
      fallbackMult: 0.72
    };
  }
  return base;
}

/** @param {string} charId */
function getMomentsProactiveTimingForChar(charId) {
  return assessCharMomentsPostingInclination(getCharPersonaItemById(charId));
}

/** 程序侧：按人设概率决定本轮是否值得去问 AI「要不要发圈」。 */
function rollMomentsProactivePersonaProbe(charId) {
  const t = getMomentsProactiveTimingForChar(charId);
  return Math.random() < t.probeRoll;
}

/** @param {object | null | undefined} ch */
function buildMomentsPostingPersonaGuide(ch, opts = {}) {
  const incl = assessCharMomentsPostingInclination(ch);
  const lines = [
    "【是否发圈 · 人设优先】",
    incl.note,
    "违背人设强行发圈 = OOC。拿不准、不想晒、没有公开分享冲动时，必须输出 [IGNORE]。"
  ];
  if (opts?.proactiveFromChat) {
    lines.push("密谈里刚聊过不代表一定要发圈：只有人设里会晒生活的人，且确有想公开说的小事，再写动态。");
  }
  if (incl.level === "rare") {
    lines.push("该角色常态：几乎不发朋友圈；除非人设里罕见的「破例分享」级冲动，否则 [IGNORE]。");
  } else if (incl.level === "low") {
    lines.push("该角色常态：很少发；不值得让熟人看见的内容、工作机密等不要发。");
  } else if (incl.level === "high") {
    lines.push("该角色常态：较爱分享；仍须贴人设，勿照抄私聊原话。");
  }
  lines.push("朋友圈是**公开场所**：写法须像这个人设会在好友面前展示的样子，OOC 比措辞不当更严重。");
  return lines.join("\n");
}

/**
 * @param {string} charId
 * @param {string} [preferredThreadId]
 * @param {{ proactive?: boolean, proactiveFromChat?: boolean, forcePost?: boolean, candidates?: object[], genEnabled?: boolean, momentHint?: string, maskId?: string }} [opts]
 * @returns {Promise<{ text: string, imagePlan: { mode: string, pickIndex: number, genCaption: string }, ignore: boolean }>}
 */
async function requestMomentsCharPostAi(charId, preferredThreadId = "", opts = {}) {
  const ai = window.RP_AI;
  if (!ai || typeof ai.chatCompletions !== "function") return emptyMomentsCharPostAiResult(true);
  const cid = String(charId || "").trim();
  if (!cid) return emptyMomentsCharPostAiResult(true);
  const maskId = String(opts?.maskId || getActiveMaskIdForInbox() || "").trim();
  const tid = String(preferredThreadId || "").trim();
  const ident = resolveMomentsCharIdentity(maskId, cid, tid, String(opts?.personaSlot || ""));
  const ch = ident.charItem;
  if (!ch) return emptyMomentsCharPostAiResult(true);
  const name = ident.displayName;
  const userLabel = resolveUserMaskDisplayLabelForInbox(maskId);
  const personaBits = [ident.persona.summary, ident.persona.boundaries, ident.persona.npcRelations]
    .map((x) => String(x || "").trim())
    .filter(Boolean)
    .join("\n");
  const altNote =
    ident.slot === "alt" && charHasAltPersona(ch)
      ? "你正在用**马甲/小号身份**发朋友圈：语气与内容须符合马甲人设，不要用大号口吻或自称大号名字（除非剧情需要）。"
      : charHasAltPersona(ch)
        ? "你正在用**大号/主身份**发朋友圈。"
        : "";
  const mustPost = opts?.forcePost === true;
  const personaGuide = buildMomentsPostingPersonaGuide(ch, {
    proactiveFromChat: opts?.proactiveFromChat === true
  });
  const system = [
    `你是${name}，在自己的朋友圈账号发一条动态。朋友圈是**公开场所**：好友、熟人划得到都看得见，不是密谈私聊。`,
    altNote,
    personaBits ? `人设：\n${personaBits.slice(0, 1200)}` : "",
    personaGuide,
    "内容、语气、分寸**必须贴人设**；违背人设 = OOC。用这个人设会在朋友圈里发的口吻写（晒日常、吐槽、碎碎念等，按性格来）。",
    "不要 @、不要写信口吻、不要剧本/旁白标注；勿照抄密谈原话。",
    "用简体中文写 1～4 句**完整**口语动态：每句须自然收尾（。！？…）；第一人称；不要用 ||| 或 JSON。",
    "多数动态**纯文字即可**；只有确实想晒画面时再用 pick/gen。",
    "正文写完后，**另起最后一行**只放一个配图标记；不要把配图标记插在句子中间。",
    mustPost
      ? "\u672c\u8f6e\u7528\u6237\u660e\u786e\u8981\u6c42\u53d1\u5708\uff1a\u8bf7\u5199\u4e00\u6761\u53ef\u53d1\u7684\u52a8\u6001\u6b63\u6587\uff08\u4ecd\u987b\u8d34\u4eba\u8bbe\u53e3\u543b\uff09\uff0c\u4e0d\u8981\u8f93\u51fa [IGNORE]\u3002"
      : "\u662f\u5426\u53d1\u5708\u5b8c\u5168\u7531\u4eba\u8bbe\u51b3\u5b9a\uff1b\u4e0d\u60f3\u53d1\u6216\u4e0d\u8be5\u53d1\u65f6\u53ea\u8f93\u51fa [IGNORE]\u3002"
  ]
    .filter(Boolean)
    .join("\n\n");
  const proactiveHint = opts?.proactive
    ? opts?.proactiveFromChat
      ? "\n\u5bc6\u8c08\u91cc\u521a\u804a\u8fc7\u3002\u4ec5\u5f53\u4eba\u8bbe\u91cc\u4f1a\u53d1\u670b\u53cb\u5708\u3001\u4e14\u4f60\u771f\u60f3\u516c\u5f00\u5206\u4eab\u65f6\uff0c\u624d\u5199\u52a8\u6001\uff1b\u5426\u5219 [IGNORE]\u3002"
      : "\n\u5230\u4e86\u53ef\u80fd\u53d1\u5708\u7684\u65f6\u673a\uff1c\u4eba\u8bbe\u4e3b\u5bfc\u662f\u5426\u53d1\uff1b\u4e0d\u60f3\u53d1\u5c31 [IGNORE]\u3002"
    : "";
  const forceHint = opts?.forcePost
    ? "\n\u7528\u6237\u5df2\u8981\u6c42\u4f60\u53d1\u670b\u53cb\u5708\uff1a\u672c\u8f6e\u5fc5\u987b\u5199\u51fa\u53ef\u53d1\u7684\u6b63\u6587\uff0c\u4e0d\u8981\u8f93\u51fa [IGNORE]\u3002"
    : "";
  const shareHint = String(opts?.momentHint || "").trim().slice(0, 400);
  const hintLine = shareHint ? `\n[\u60f3\u5206\u4eab\u7684\u65b9\u5411\uff08\u53ef\u81ea\u7531\u53d1\u6325\uff0c\u52ff\u7167\u6284\u5bc6\u8c08\u539f\u8bdd\uff09]\n${shareHint}` : "";
  const candidates = Array.isArray(opts?.candidates) ? opts.candidates : [];
  const wantUserPic = momentHintRequestsUserChatImage(shareHint);
  const userPicNudge =
    wantUserPic && candidates.some((c) => String(c.role || "") === "user")
      ? "\n[硬性] 用户要求使用密谈里「用户发的图」：最后一行必须写 [POST_IMAGE:pick:对应序号] 附上真图，不要用 desc/gen/none 或正文（配图：…）代替。"
      : "";
  const genEnabled = opts?.genEnabled === true;
  const catalogue = buildMomentsCharPostImageCatalogue(candidates);
  const imageRule = genEnabled
    ? candidates.length
      ? "最后一行任选：[POST_IMAGE:none]（不附图，**常用**）/ [POST_IMAGE:pick:序号]（复用上方素材）/ [POST_IMAGE:gen:画面描述]（新生图，偏风景美食静物日常，勿默认自拍人像）/ [POST_IMG:动态:英文提示词]。勿写 [POST_IMAGE:desc:…]。"
      : "最后一行任选：[POST_IMAGE:none]（不附图，**常用**）/ [POST_IMAGE:gen:画面描述]（偏风景美食静物日常，勿默认自拍人像）/ [POST_IMG:动态:英文提示词]。勿写 [POST_IMAGE:desc:…]。"
    : candidates.length
      ? "最后一行写 [POST_IMAGE:pick:序号] 复用素材图；或 [POST_IMAGE:desc:画面描述]（仅文字示意配图）；不附图则 [POST_IMAGE:none]（常用）。"
      : "最后一行写 [POST_IMAGE:desc:画面描述]（无真图时的文字示意配图）或 [POST_IMAGE:none]（纯文字，常用）。";
  let ctxBlock = "";
  try {
    ctxBlock = buildMomentsCharPostContextForPrompt(maskId, cid, tid, ident.slot);
  } catch (e) {
    console.warn("[moments] build post context failed", e);
  }
  const user = [
    `读者视角：这是${name}发在**公开朋友圈**的一条动态（熟人可见）。请严格按人设写，不要 OOC。`,
    ctxBlock ? `\n[\u8fde\u8d2f\u53c2\u8003]\n${ctxBlock}` : "",
    catalogue,
    "\n\u5148\u5199\u5b8c\u6574\u52a8\u6001\u6b63\u6587\uff08\u0031\uff5e\u0034 \u53e5\uff09\uff0c\u518d\u3010\u53e6\u8d77\u4e00\u{884c}\u3011\u53ea\u5199\u4e00\u4e2a\u914d\u56fe\u6807\u8bb0\uff08\u4e09\u9009\u4e00\uff09\uff1a",
    candidates.length
      ? "[POST_IMAGE:pick:\u5e8f\u53f7] \u2014 \u590d\u7528\u4e0a\u65b9\u7d20\u6750"
      : "",
    imageRule,
    "[POST_IMAGE:none] \u2014 \u4e0d\u9644\u56fe",
    "\u4e0d\u8981\u8f93\u51fa JSON\u3001\u4e0d\u8981\u7528\u4ee3\u7801\u5757\u5305\u88f9\u6574\u6bb5\u3002",
    proactiveHint,
    forceHint,
    hintLine,
    userPicNudge
  ]
    .filter(Boolean)
    .join("\n\n");
  try {
    const data = await ai.chatCompletions({
      messages: [
        { role: "system", content: system },
        { role: "user", content: user }
      ],
      temperature: 0.88
    });
    return parseMomentsCharPostResponse(readMomentsPostCompletionText(data));
  } catch (e) {
    console.warn("[moments] char post failed", name, e);
    return {
      text: "",
      imagePlan: { mode: "none", pickIndex: 0, genCaption: "" },
      ignore: opts?.forcePost !== true && opts?.proactive !== true
    };
  }
}

/**
 * @param {string} charId
 * @param {{ text?: string, images?: string[], threadId?: string }} payload
 * @returns {string | null} new moment id
 */
/**
 * @param {string} maskId
 * @param {string} charId
 * @param {{ text?: string, images?: string[], threadId?: string }} payload
 * @returns {string | null}
 */
function insertCharMomentForMask(maskId, charId, payload) {
  const D = window.XXJ_DB;
  if (!D) return null;
  const mid = String(maskId || "").trim();
  const cid = String(charId || "").trim();
  if (!mid || !cid) return null;
  const inbox = readChatInboxStore();
  const bucket = ensureMaskBucket(inbox, mid);
  const text = String(payload?.text || "").trim();
  const images = (Array.isArray(payload?.images) ? payload.images : [])
    .map((x) => String(x || "").trim())
    .filter(Boolean)
    .slice(0, MOMENTS_CHAR_POST_MAX_IMAGES);
  const imageDescCards = (Array.isArray(payload?.imageDescCards) ? payload.imageDescCards : [])
    .map((x) => String(x || "").trim().slice(0, 500))
    .filter(Boolean)
    .slice(0, MOMENTS_CHAR_POST_MAX_IMAGES);
  if (!text && !images.length && !imageDescCards.length) return null;
  const preferredThreadId = String(payload?.threadId || "").trim();
  const th = pickThreadForCharMoment(mid, cid, preferredThreadId);
  const threadId = th ? String(th.id || "").trim() : preferredThreadId;
  const charItemMom = getCharPersonaItemById(cid);
  const rawPersona = String(payload?.persona || "").trim();
  const postPersona =
    rawPersona === "alt" ? "alt" : rawPersona === "main" ? "main" : getThreadActivePersona(th);
  const name = resolvePersonaDisplayName(charItemMom, postPersona);
  const threadRemark = getThreadMomentRemarkLabel(th);
  const newId = newEntityId();
  const arr = Array.isArray(bucket.moments) ? bucket.moments.slice() : [];
  const row = {
    id: newId,
    kind: "char",
    charId: cid,
    displayName: name,
    timeIso: new Date().toISOString(),
    text,
    images,
    likedByMe: false,
    likeCount: 0,
    shareCount: 0,
    comments: []
  };
  if (imageDescCards.length) row.imageDescCards = imageDescCards;
  if (threadId) row.threadId = threadId;
  if (threadRemark) row.threadRemark = threadRemark;
  if (postPersona === "alt") row.postPersona = "alt";
  arr.unshift(normalizeMoment(row));
  bucket.moments = arr;
  writeChatInboxStore(inbox, { fast: true });
  if (threadId) {
    try {
      recordMomentsFeedPostPublishedInChatThread(mid, threadId, {
        authorKind: "char",
        displayName: name,
        hasImages: images.length > 0 || imageDescCards.length > 0,
        momentId: newId
      });
    } catch (e) {
      console.warn("[moments] feed notice failed", e);
    }
  }
  return newId;
}

function insertCharMoment(charId, payload) {
  const maskId = getActiveMaskIdForInbox();
  if (!maskId) return null;
  return insertCharMomentForMask(maskId, charId, payload);
}

/**
 * 仅从聊天 JSON 读取「想发什么」的倾向（postMomentText），不把 lines/旁白/narration 当朋友圈正文。
 * @param {object | null | undefined} firstParsed
 * @param {string} [rawReply]
 */
function extractMomentShareHintFromChatJson(firstParsed, rawReply) {
  const raw = stripUtf8Bom(String(rawReply || "")).trim();
  const slice = sliceFirstBalancedJsonObject(normalizeAssistantModelJsonText(raw));
  if (!slice) return "";
  try {
    const o = JSON.parse(slice);
    const pm = o.postMoment ?? o.momentsPost ?? o.publishMoment;
    let hint = String(o.postMomentText ?? o.momentText ?? "").trim();
    if (pm && typeof pm === "object") {
      hint =
        String(pm.text ?? pm.caption ?? pm.hint ?? pm.postMomentText ?? "").trim() || hint;
    }
    if (!hint && firstParsed) {
      hint = String(firstParsed.postMomentText ?? firstParsed.momentText ?? "").trim();
    }
    return hint.slice(0, 400);
  } catch {
    return "";
  }
}

let momentsCharPostBusy = false;
const momentsCharPostChatDebounce = new Map();

/** 用户明确要求角色发朋友圈（须含「发朋友圈/发圈」等，避免「发现」等误触）。 */
function userMessageRequestsCharMomentsPost(text) {
  const s = String(text || "").trim();
  if (!s) return false;
  if (/(帮我|请|去|来|能否|可以|要不要)?(发|发个|发一条|发一下|更新|上传)(朋友圈|朋友圏|发圈)/u.test(s)) return true;
  if (/(朋友圈|朋友圏|发圈).{0,8}(发|发一下|发一条|发呗)/u.test(s)) return true;
  if (/(去|来).{0,3}发(朋友圈|朋友圏|发圈)/u.test(s)) return true;
  return false;
}

function readLastUserMessageTextForMaskThread(maskId, threadId) {
  const log = readChatLogForMaskThread(maskId, threadId);
  for (let i = log.length - 1; i >= 0; i--) {
    const row = log[i];
    if (row && row.role === "user") return String(row.content || "").trim();
  }
  return "";
}

/** JSON 根级 postMoment / momentsPost / publishMoment 须为严格 true，才视为要发圈。 */
function assistantJsonExplicitlyRequestsMomentPost(o) {
  if (!o || typeof o !== "object" || Array.isArray(o)) return false;
  const keys = ["postMoment", "momentsPost", "publishMoment"];
  for (const k of keys) {
    const pm = o[k];
    if (pm === true) return true;
    if (/^true$/i.test(String(pm ?? "").trim())) return true;
    if (pm && typeof pm === "object" && (pm.enabled === true || pm.enable === true)) return true;
  }
  return false;
}

/**
 * @param {string} rawReply
 * @param {object | null | undefined} [firstParsed]
 * @returns {{ want: boolean, hint: string, directText: string }}
 */
function parseMomentsPostIntentFromAssistantRaw(rawReply, firstParsed) {
  let want = false;
  let hint = "";
  let directText = "";
  const raw = stripUtf8Bom(String(rawReply || "")).trim();
  if (/\[MOMENT_POST:\s*no\]/i.test(raw) || /\[POST_MOMENT:\s*no\]/i.test(raw)) {
    return { want: false, hint: "", directText: "" };
  }
  const slice = sliceFirstBalancedJsonObject(normalizeAssistantModelJsonText(raw));
  if (slice) {
    try {
      const o = JSON.parse(slice);
      want = assistantJsonExplicitlyRequestsMomentPost(o);
      const pm = o.postMoment ?? o.momentsPost ?? o.publishMoment;
      hint =
        String(o.postMomentText ?? o.momentText ?? "").trim() ||
        (pm && typeof pm === "object"
          ? String(pm.text ?? pm.caption ?? pm.hint ?? pm.postMomentText ?? "").trim()
          : "");
    } catch {
      /* ignore */
    }
  }
  if (!want && firstParsed && typeof firstParsed === "object") {
    want = assistantJsonExplicitlyRequestsMomentPost(firstParsed);
    if (!hint) {
      hint = String(firstParsed.postMomentText ?? firstParsed.momentText ?? "").trim();
    }
  }
  if (!want) return { want: false, hint: "", directText: "" };
  if (!hint) hint = extractMomentShareHintFromChatJson(firstParsed, rawReply);
  hint = hint.slice(0, 400);
  const polishedHint = polishMomentsCharPostDisplayText(hint);
  if (polishedHint && momentTextLooksPublishable(polishedHint)) {
    directText = polishedHint.slice(0, 2000);
  }
  return { want, hint, directText };
}

function canChatTriggerMomentPostNow(threadId) {
  const tid = String(threadId || "").trim();
  if (!tid) return false;
  const until = momentsCharPostChatDebounce.get(tid) || 0;
  return Date.now() > until;
}

const CHAT_MOMENT_POST_DEBOUNCE_USER_MS = 50_000;
/** 模型自行 postMoment 时同密谈节流，避免每轮回复都发一条 */
const CHAT_MOMENT_POST_DEBOUNCE_MODEL_MS = 20 * 60 * 1000;

function markChatTriggerMomentPost(threadId, userAsked) {
  const tid = String(threadId || "").trim();
  if (!tid) return;
  const ms = userAsked ? CHAT_MOMENT_POST_DEBOUNCE_USER_MS : CHAT_MOMENT_POST_DEBOUNCE_MODEL_MS;
  momentsCharPostChatDebounce.set(tid, Date.now() + ms);
}

/**
 * 聊天触发的发圈（非「主动发朋友圈」开关）：仅用户明确要求或 JSON 显式 postMoment。
 * @param {{ firstParsed?: object, rawReply?: string, roundMaskId?: string, roundThreadId?: string, th?: object, roundDmSurface?: string, suppress?: boolean }} ctx
 */
function maybeTriggerCharMomentPostAfterChatRound(ctx) {
  if (ctx?.suppress) return;
  const th = ctx?.th;
  if (!th || th.kind === "group") return;
  if (ctx?.roundDmSurface === "offline") return;
  const cid = String(th.charId || "").trim();
  const tid = String(ctx?.roundThreadId || th.id || "").trim();
  const mid = String(ctx?.roundMaskId || "").trim();
  if (!cid || !mid || !tid) return;
  if (!canChatTriggerMomentPostNow(tid) || momentsCharPostBusy) return;

  const lastU = readLastUserMessageTextForMaskThread(mid, tid);
  const userAsked = userMessageRequestsCharMomentsPost(lastU);
  let intent = parseMomentsPostIntentFromAssistantRaw(ctx?.rawReply || "", ctx?.firstParsed);
  if (!intent.want && userAsked) {
    intent = {
      want: true,
      hint: (lastU || "用户让你发朋友圈").slice(0, 400),
      directText: ""
    };
  }
  if (!intent.want) return;
  /** 模型 postMoment 须开启「主动发朋友圈」；仅用户上一条消息明确要求除外 */
  if (!userAsked && !isThreadCharMomentsProactiveEnabled(th)) return;
  /** 自定义间隔：聊天里模型自发圈也须等到间隔，用户明确要求除外 */
  if (
    !userAsked &&
    isThreadCharMomentsProactiveEnabled(th) &&
    !isThreadCharMomentsProactiveAutoMode(th) &&
    !isThreadMomentsProactiveDue(th, mid)
  ) {
    return;
  }

  markChatTriggerMomentPost(tid, userAsked);
  const speakSlot = parseAssistantSpeakAsFromJson(ctx?.firstParsed || null);
  const personaSlot =
    speakSlot === "alt" || speakSlot === "main"
      ? speakSlot
      : parseAssistantSpeakAsFromRaw(ctx?.rawReply || "");
  void enqueuePublishCharMomentFromAiAfterChat(cid, {
    maskId: mid,
    threadId: tid,
    momentHint: intent.hint,
    directText: intent.directText,
    forcePost: userAsked,
    switchToMoments: false,
    notifySuccess: true,
    personaSlot: personaSlot === "alt" || personaSlot === "main" ? personaSlot : ""
  });
}

/**
 * 随聊天模式：密谈一轮结束后，由角色自己判断要不要发一条朋友圈。
 * @param {{ roundMaskId?: string, roundThreadId?: string, th?: object, roundDmSurface?: string, suppress?: boolean }} ctx
 */
function maybeTriggerCharMomentsProactiveAfterChatRound(ctx) {
  if (ctx?.suppress) return;
  const th = ctx?.th;
  if (!th || th.kind === "group") return;
  if (ctx?.roundDmSurface === "offline") return;
  if (!isThreadCharMomentsProactiveEnabled(th)) return;
  if (!isThreadCharMomentsProactiveAutoMode(th)) return;
  const cid = String(th.charId || "").trim();
  const tid = String(ctx?.roundThreadId || th.id || "").trim();
  const mid = String(ctx?.roundMaskId || "").trim();
  if (!cid || !mid || !tid) return;
  if (momentsCharPostBusy || momentsProactiveInFlight) return;
  if (!canMomentsProactiveProbeFromChat(th, cid)) return;
  if (!rollMomentsProactivePersonaProbe(cid)) return;
  const incl = getMomentsProactiveTimingForChar(cid);
  const lastPost = getThreadCharMomentsProactiveLastPostMs(th, mid);
  if (Date.now() - lastPost < MOMENTS_PROACTIVE_CHAT_POST_MIN_MS * incl.postMult) return;
  if (!threadHasShareableChatForMomentsProactive(mid, cid, tid)) return;
  const momentHint = buildMomentsProactiveHintFromChatLog(mid, cid, tid);
  if (!momentHint) return;
  const thProbe = pickThreadForCharMoment(mid, cid, tid);
  const proactiveSlot = getThreadActivePersona(thProbe);
  void enqueuePublishCharMomentFromAiAfterChat(cid, {
    maskId: mid,
    threadId: tid,
    proactive: true,
    proactiveFromChat: true,
    momentHint,
    forcePost: false,
    quiet: true,
    notifySuccess: true,
    personaSlot: proactiveSlot
  }).then((ok) => {
    touchThreadCharMomentsProactiveProbe(mid, tid);
    if (ok) touchThreadCharMomentsProactiveLastAt(mid, tid);
    scheduleMomentsProactiveTimer();
  });
}

/** 聊天触发的发圈在 busy 时短暂排队，避免静默失败。 */
async function enqueuePublishCharMomentFromAiAfterChat(charId, opts) {
  for (let i = 0; i < 24; i++) {
    if (!momentsCharPostBusy) return await publishCharMomentFromAi(charId, opts);
    await new Promise((r) => window.setTimeout(r, 350));
  }
  return false;
}

/**
 * @param {string} charId
 * @param {{ switchToMoments?: boolean, threadId?: string, quiet?: boolean, proactive?: boolean, momentHint?: string, maskId?: string, forcePost?: boolean, directText?: string, notifySuccess?: boolean }} [opts]
 */
async function publishCharMomentFromAi(charId, opts) {
  if (momentsCharPostBusy) return false;
  const cid = String(charId || "").trim();
  if (!cid) return false;
  const ai = window.RP_AI;
  if (!ai?.chatCompletions) {
    if (!opts?.quiet) showToast("AI \u672a\u52a0\u8f7d");
    return false;
  }
  const maskId = String(opts?.maskId || getActiveMaskIdForInbox() || "").trim();
  if (!maskId) {
    if (!opts?.quiet) showToast("\u8bf7\u5148\u9009\u62e9\u4e3b\u63a7\u9762\u5177");
    return false;
  }
  const threadIdEarly = String(opts?.threadId || "").trim();
  const thEarly = pickThreadForCharMoment(maskId, cid, threadIdEarly);
  if (opts?.proactive === true || opts?.proactiveFromChat === true) {
    if (!thEarly || !isThreadCharMomentsProactiveEnabled(thEarly)) return false;
    if (opts?.proactiveFromChat === true && !isThreadCharMomentsProactiveAutoMode(thEarly)) return false;
  }
  momentsCharPostBusy = true;
  if (!opts?.quiet) closeMomentsCharPostSheet();
  const threadId = String(opts?.threadId || "").trim();
  const forcePost = opts?.forcePost === true;
  const mustPost = forcePost;
  const directText = polishMomentsCharPostDisplayText(String(opts?.directText || "").trim());
  const momentHint = String(opts?.momentHint || "").trim().slice(0, 400);
  try {
    const th = pickThreadForCharMoment(maskId, cid, threadId);
    const tid = th ? String(th.id || "").trim() : threadId;
    const speakAsRaw = String(opts?.personaSlot || "").trim();
    const momentIdent = resolveMomentsCharIdentity(maskId, cid, tid, speakAsRaw);
    const postPersonaSlot = momentIdent.slot;
    const name = momentIdent.displayName || "角色";
    if (!opts?.quiet) showToast(`${name} \u6b63\u5728\u5199\u52a8\u6001\u2026`);
    const candidates = tid ? collectMomentsCharImageCandidates(maskId, tid, 10) : [];
    const genEnabled = isSessionImageGenConfigured();
    let text = "";
    let imagePlan = { mode: "none", pickIndex: 0, genCaption: "" };
    const skipMomentsAi = forcePost && momentTextLooksPublishable(directText);
    let parsed = emptyMomentsCharPostAiResult(!mustPost);
    if (!skipMomentsAi) {
      try {
        parsed = await requestMomentsCharPostAi(cid, threadId, {
          proactive: opts?.proactive === true,
          proactiveFromChat: opts?.proactiveFromChat === true,
          forcePost: mustPost,
          candidates,
          genEnabled,
          momentHint,
          maskId,
          personaSlot: postPersonaSlot
        });
      } catch (e) {
        console.warn("[moments] char post failed", name, e);
        parsed = emptyMomentsCharPostAiResult(!mustPost);
      }
      if (!parsed || typeof parsed !== "object") {
        parsed = emptyMomentsCharPostAiResult(!mustPost);
      }
      imagePlan = normalizeMomentsCharPostImagePlan(parsed.imagePlan || imagePlan, candidates, genEnabled);
      const hasImgPlan =
        imagePlan.mode === "pick" || imagePlan.mode === "gen" || imagePlan.mode === "desc";
      if (!parsed.ignore || hasImgPlan) {
        text = String(parsed.text || "").trim();
      }
      if (mustPost) {
        if (!text) text = directText;
        else if (parsed.ignore && !hasImgPlan) text = directText || text;
      } else if (parsed.ignore && !hasImgPlan) {
        if (opts?.proactive && maskId && tid) touchThreadCharMomentsProactiveProbe(maskId, tid);
        if (!opts?.quiet) showToast("\u8fd9\u6b21\u6ca1\u6709\u53d1\u51fa\u6765");
        return false;
      }
    } else {
      text = directText;
    }
    text = normalizeMomentsCharPostBodyForPublish(
      coerceMomentsPublishBody(text || directText || "")
    );
    imagePlan = normalizeMomentsCharPostImagePlan(imagePlan, candidates, genEnabled);
    const inlineDesc = extractMomentsInlineImageDescFromText(text);
    text = normalizeMomentsCharPostBodyForPublish(inlineDesc.text);
    if (inlineDesc.caption && imagePlan.mode === "none") {
      imagePlan = { ...imagePlan, mode: "desc", genCaption: inlineDesc.caption };
    } else if (inlineDesc.caption && !String(imagePlan.genCaption || "").trim()) {
      imagePlan = { ...imagePlan, genCaption: inlineDesc.caption };
    }
    imagePlan = normalizeMomentsCharPostImagePlan(imagePlan, candidates, genEnabled);
    const capHint = String(imagePlan.genCaption || inlineDesc.caption || "").trim();
    if (imagePlan.mode === "gen" && genEnabled && !opts?.quiet) {
      showToast(`${name} \u6b63\u5728\u914d\u56fe\u2026`);
    }
    let images = [];
    try {
      images = await resolveMomentsCharPostImages(imagePlan, candidates, th, maskId);
    } catch (e) {
      console.warn("[moments] post images failed", name, e);
      images = [];
    }
    if (!images.length && candidates.length && momentsPublishWantsUserChatImage(momentHint, directText, imagePlan)) {
      const userHit = pickLastUserMomentsImageCandidate(candidates);
      if (userHit) {
        try {
          const url = await persistMomentImageDataUrl(String(userHit.url || "").trim());
          if (url) images = [url];
        } catch (e) {
          console.warn("[moments] user image pick fallback failed", name, e);
        }
      }
    }
    if (!images.length && !opts?.quiet) {
      const triedPic =
        imagePlan.mode === "pick" ||
        imagePlan.mode === "gen" ||
        momentHintRequestsUserChatImage(momentHint) ||
        momentHintRequestsUserChatImage(directText);
      if (triedPic && (candidates.length || (imagePlan.mode === "gen" && genEnabled))) {
        showToast(
          imagePlan.mode === "gen" && genEnabled
            ? "配图生成失败；聊天原图也未能载入，已发文字或描述配图"
            : "聊天原图未能载入朋友圈，已发文字或描述配图（不是真图）"
        );
      } else if (imagePlan.mode === "gen" && genEnabled) {
        showToast("配图生成失败，已发文字动态");
      }
    }
    let imageDescCards = [];
    if (!images.length) {
      const cap = String(capHint || inlineDesc.caption || "").trim();
      if (cap) imageDescCards = [cap.slice(0, 500)];
    }
    text = normalizeMomentsCharPostBodyForPublish(
      finalizeMomentsPostTextWithImageFallback(
        text,
        imagePlan,
        candidates,
        genEnabled,
        images.length > 0 || imageDescCards.length > 0
      )
    );
    if (!text && imagePlan.mode === "desc" && String(imagePlan.genCaption || "").trim()) {
      text = String(imagePlan.genCaption || "")
        .trim()
        .slice(0, 2000);
    }
    text = coerceMomentsPublishBody(text);
    if (!text && !images.length && !imageDescCards.length) {
      if (!opts?.quiet) showToast("\u8fd9\u6b21\u6ca1\u6709\u53d1\u51fa\u6765");
      return false;
    }
    let newId = insertCharMomentForMask(maskId, cid, {
      text,
      images,
      imageDescCards,
      threadId: tid,
      persona: postPersonaSlot
    });
    if (!newId) {
      if (!opts?.quiet) {
        showToast(
          window.XXJ_DB ? "\u53d1\u5e03\u5931\u8d25\uff0c\u8bf7\u7a0d\u540e\u518d\u8bd5" : "\u53d1\u5e03\u5931\u8d25\uff1a\u672c\u5730\u5b58\u50a8\u672a\u5c31\u7eea"
        );
      }
      return false;
    }
    flushChatInboxKvPersist();
    try {
      if (!opts?.quiet || opts?.notifySuccess) {
        const preview =
          String(text || "").trim().slice(0, 120) || (images.length ? "（配图动态）" : "发了一条朋友圈");
        if (tid) {
          maybePushMomentsFeedNotify(maskId, cid, tid, preview, {
            force: opts?.notifySuccess === true
          });
        } else if (!opts?.quiet) showToast(`${name} 已发朋友圈`);
      }
      if (opts?.switchToMoments) {
        if (!chatListScreen?.classList.contains("is-open")) openChatListScreen();
        setChatListInboxTab("moments");
      }
      renderMomentsFeed();
      scheduleMomentsFeedRender(true);
    } catch (uiErr) {
      console.warn("[moments] post-publish ui failed", name, uiErr);
      try {
        renderMomentsFeed();
        scheduleMomentsFeedRender(true);
      } catch (_) {
        /* ignore */
      }
      if (!opts?.quiet) showToast(`${name} 已发朋友圈`);
    }
    if (th && tid && isThreadCharMomentsProactiveEnabled(th)) {
      touchThreadCharMomentsProactiveLastAt(maskId, tid);
    }
    return true;
  } catch (e) {
    console.warn("[moments] publish failed", name, e);
    if (!opts?.quiet) showToast("发布失败，请稍后再试");
    return false;
  } finally {
    momentsCharPostBusy = false;
  }
}

let momentsProactiveTimerId = 0;
let momentsProactiveInFlight = false;

function clearMomentsProactiveTimer() {
  if (momentsProactiveTimerId) window.clearTimeout(momentsProactiveTimerId);
  momentsProactiveTimerId = 0;
}

function listThreadsDueForMomentsProactive(maskId) {
  const mid = String(maskId || "").trim();
  if (!mid) return [];
  const inbox = readChatInboxStore();
  const bucket = inbox.byMask[maskBucketKey(mid)];
  if (!bucket) return [];
  const now = Date.now();
  const due = [];
  for (const th of Array.isArray(bucket.threads) ? bucket.threads : []) {
    if (!th || th.kind === "group" || !isThreadCharMomentsProactiveEnabled(th)) continue;
    if (!String(th.charId || "").trim()) continue;
    if (isThreadMomentsProactiveDue(th, mid, now)) {
      const lastPost = getThreadCharMomentsProactiveLastPostMs(th, mid);
      due.push({
        th,
        overdue: now - lastPost - getMomentsProactiveIntervalMs(th, String(th.charId || ""))
      });
    }
  }
  due.sort((a, b) => b.overdue - a.overdue);
  return due.map((x) => x.th);
}

/** @returns {{ maskId: string, th: object, overdue: number }[]} */
function listMomentsProactiveDueAcrossMasks() {
  const inbox = readChatInboxStore();
  const rows = [];
  const now = Date.now();
  for (const key of Object.keys(inbox.byMask || {})) {
    const bucket = inbox.byMask[key];
    if (!bucket) continue;
    const maskId = key === "__nomask__" ? "__nomask__" : key;
    for (const th of Array.isArray(bucket.threads) ? bucket.threads : []) {
      if (!th || th.kind === "group" || !isThreadCharMomentsProactiveEnabled(th)) continue;
      if (!String(th.charId || "").trim()) continue;
      if (isThreadMomentsProactiveDue(th, maskId, now)) {
        const lastPost = getThreadCharMomentsProactiveLastPostMs(th, maskId);
        rows.push({
          maskId,
          th,
          overdue: now - lastPost - getMomentsProactiveIntervalMs(th, String(th.charId || ""))
        });
      }
    }
  }
  rows.sort((a, b) => b.overdue - a.overdue);
  return rows;
}

function computeNextMomentsProactiveWakeMsAnyMask() {
  const inbox = readChatInboxStore();
  const now = Date.now();
  let minWake = 120000;
  let any = false;
  for (const key of Object.keys(inbox.byMask || {})) {
    const bucket = inbox.byMask[key];
    if (!bucket) continue;
    const maskId = key === "__nomask__" ? "__nomask__" : key;
    for (const th of Array.isArray(bucket.threads) ? bucket.threads : []) {
      if (!th || th.kind === "group" || !isThreadCharMomentsProactiveEnabled(th)) continue;
      if (!String(th.charId || "").trim()) continue;
      any = true;
      const lastPost = getThreadCharMomentsProactiveLastPostMs(th, maskId);
      const remaining = Math.max(
        4000,
        lastPost + getMomentsProactiveIntervalMs(th, String(th.charId || "")) - now
      );
      minWake = Math.min(minWake, remaining);
    }
  }
  return any ? minWake : 120000;
}

function computeNextMomentsProactiveWakeMs(maskId) {
  const mid = String(maskId || "").trim();
  if (!mid) return 60000;
  const inbox = readChatInboxStore();
  const bucket = inbox.byMask[maskBucketKey(mid)];
  if (!bucket) return 60000;
  const now = Date.now();
  let minWake = 60000;
  let any = false;
  for (const th of Array.isArray(bucket.threads) ? bucket.threads : []) {
    if (!th || th.kind === "group" || !isThreadCharMomentsProactiveEnabled(th)) continue;
    if (!String(th.charId || "").trim()) continue;
    any = true;
    const lastPost = getThreadCharMomentsProactiveLastPostMs(th, mid);
    const remaining = Math.max(
      4000,
      lastPost + getMomentsProactiveIntervalMs(th, String(th.charId || "")) - now
    );
    minWake = Math.min(minWake, remaining);
  }
  return any ? minWake : 120000;
}

function scheduleMomentsProactiveTimer() {
  clearMomentsProactiveTimer();
  const wake = computeNextMomentsProactiveWakeMsAnyMask();
  momentsProactiveTimerId = window.setTimeout(() => {
    void runMomentsProactiveScan();
  }, wake);
}

async function runMomentsProactiveScan() {
  momentsProactiveTimerId = 0;
  if (momentsProactiveInFlight || momentsCharPostBusy) {
    scheduleMomentsProactiveTimer();
    return;
  }
  if (!window.RP_AI) {
    scheduleMomentsProactiveTimer();
    return;
  }
  const dueRows = listMomentsProactiveDueAcrossMasks();
  if (!dueRows.length) {
    scheduleMomentsProactiveTimer();
    return;
  }
  const { maskId, th } = dueRows[0];
  const cid = String(th.charId || "").trim();
  const tid = String(th.id || "").trim();
  if (!cid || !tid) {
    scheduleMomentsProactiveTimer();
    return;
  }
  if (!rollMomentsProactivePersonaProbe(cid)) {
    touchThreadCharMomentsProactiveProbe(maskId, tid);
    scheduleMomentsProactiveTimer();
    return;
  }
  momentsProactiveInFlight = true;
  const autoChat = isThreadCharMomentsProactiveAutoMode(th);
  try {
    const ok = await publishCharMomentFromAi(cid, {
      maskId,
      threadId: tid,
      quiet: true,
      proactive: true,
      proactiveFromChat: autoChat,
      momentHint: autoChat ? buildMomentsProactiveHintFromChatLog(maskId, cid, tid) : "",
      forcePost: false,
      notifySuccess: true,
      personaSlot: getThreadActivePersona(th)
    });
    touchThreadCharMomentsProactiveProbe(maskId, tid);
    if (ok) touchThreadCharMomentsProactiveLastAt(maskId, tid);
  } finally {
    momentsProactiveInFlight = false;
    scheduleMomentsProactiveTimer();
  }
}

function openMomentsCharPostSheet() {
  const maskId = getActiveMaskIdForInbox();
  if (!maskId) {
    showToast("请先选择主控面具");
    return;
  }
  const sheet = document.getElementById("moments-char-post-sheet");
  const list = document.getElementById("moments-char-post-list");
  if (!sheet || !list) return;
  const ids = listMomentsPostableCharIds(maskId);
  list.replaceChildren();
  if (!ids.length) {
    const li = document.createElement("li");
    li.className = "chat-char-pick-empty";
    li.textContent = "还没有可发朋友圈的角色，请先在密谈里添加单聊。";
    list.appendChild(li);
  } else {
    const st = readCharPersonaStore();
    for (const cid of ids) {
      const it = st.items.find((x) => String(x.id || "") === cid);
      const th = pickThreadForCharMoment(maskId, cid);
      const remark = getThreadMomentRemarkLabel(th);
      const label = (it?.displayName && String(it.displayName).trim()) || "未命名角色";
      const li = document.createElement("li");
      const b = document.createElement("button");
      b.type = "button";
      b.className = "chat-char-pick-item";
      b.dataset.charId = cid;
      if (th) b.dataset.threadId = String(th.id || "");
      b.textContent = remark ? `${label} · ${remark}` : label;
      li.appendChild(b);
      list.appendChild(li);
    }
  }
  sheet.hidden = false;
  sheet.setAttribute("aria-hidden", "false");
}

function closeMomentsCharPostSheet() {
  const sheet = document.getElementById("moments-char-post-sheet");
  if (!sheet) return;
  sheet.hidden = true;
  sheet.setAttribute("aria-hidden", "true");
}

function reconcileActiveThreadRef() {
  const D = window.XXJ_DB;
  if (!D) return;
  if (D.isReady && !D.isInboxHydrated) return;
  const maskId = getActiveMaskIdForInbox();
  const inbox = readChatInboxStore();
  if (D.isInboxHydrated && !chatInboxMemCache) warmChatInboxMemCacheFromDb();
  ensureMaskBucket(inbox, maskId);
  const bucket = inbox.byMask[maskBucketKey(maskId)];
  const ref = readChatActiveThreadRef();
  const ok =
    ref.maskId === maskId &&
    ref.threadId &&
    bucket.threads.some((t) => t.id === ref.threadId);
  if (ok) return;
  if (ref.threadId && !bucket.threads.length) return;
  /* 引用指向的密谈已从列表消失：清空引用，勿自动切到别的角色（否则像「记录没了」） */
  if (ref.threadId && !bucket.threads.some((t) => t.id === ref.threadId)) {
    writeChatActiveThreadRef({ maskId, threadId: "" });
    return;
  }
  const sorted = bucket.threads.slice().sort(sortInboxThreads);
  const pick = sorted[0];
  writeChatActiveThreadRef({ maskId, threadId: pick?.id || "" });
}

function closeChatThreadBeadMenu() {
  if (!chatThreadBeadOpenLi) return;
  const bead = chatThreadBeadOpenLi.querySelector(".chat-thread-bead");
  const menu = chatThreadBeadOpenLi.querySelector(".chat-thread-bead-menu");
  chatThreadBeadOpenLi.classList.remove("is-bead-open");
  if (menu) menu.hidden = true;
  bead?.setAttribute("aria-expanded", "false");
  chatThreadBeadOpenLi = null;
}

/** 置顶 / 取消置顶当前面具下的一条会话 */
function setChatThreadPinned(threadId, pinned) {
  const D = window.XXJ_DB;
  if (!D) return false;
  const tid = String(threadId || "").trim();
  if (!tid) return false;
  const maskId = getActiveMaskIdForInbox();
  const inbox = readChatInboxStore();
  ensureMaskBucket(inbox, maskId);
  const bucket = inbox.byMask[maskBucketKey(maskId)];
  const th = bucket.threads.find((t) => t.id === tid);
  if (!th) return false;
  if (pinned) th.pinned = true;
  else delete th.pinned;
  writeChatInboxStore(inbox);
  return true;
}

/** 从当前面具密谈桶移除一条会话（单聊 / 群聊），并修正活动会话引用 */
function deleteChatThreadById(threadId) {
  const D = window.XXJ_DB;
  if (!D) return false;
  const tid = String(threadId || "").trim();
  if (!tid) return false;
  const maskId = getActiveMaskIdForInbox();
  const inbox = readChatInboxStore();
  ensureMaskBucket(inbox, maskId);
  const bucket = inbox.byMask[maskBucketKey(maskId)];
  const idx = bucket.threads.findIndex((t) => t.id === tid);
  if (idx < 0) return false;
  bucket.threads.splice(idx, 1);
  if (typeof D.chatMsgsDelete === "function") {
    void D.chatMsgsDelete(maskId, tid);
  }
  writeChatInboxStore(inbox);
  const ref = readChatActiveThreadRef();
  if (ref.maskId === maskId && ref.threadId === tid) {
    writeChatActiveThreadRef({ maskId, threadId: "" });
    reconcileActiveThreadRef();
  }
  return true;
}

function charDisplayNameById(charId) {
  const st = readCharPersonaStore();
  const it = st.items.find((x) => x.id === charId);
  return (it?.displayName && String(it.displayName).trim()) || "未命名角色";
}

/** 本密谈在列表 / 顶栏 / 心声等处展示用：优先 charThreadRemarkName，否则取备注正文首行（≤32），再否则空（由调用方回退人设名）。不用于系统提示里的「你是谁」称呼（有备注名时提示词用人设显示名）。 */
function getThreadCharDisplayAlias(thread) {
  if (!thread || typeof thread !== "object") return "";
  const rn = String(thread.charThreadRemarkName || "").trim();
  if (rn) return rn.slice(0, 32);
  const note = String(thread.charThreadNote || "").trim();
  if (!note) return "";
  const first = note.split(/\r?\n/).map((s) => s.trim()).find(Boolean) || "";
  if (!first) return "";
  return first.length > 32 ? `${first.slice(0, 31)}…` : first;
}

function threadListDisplayName(thread) {
  if (isChatThreadGroupForUi(thread)) {
    const fn = window.XXJ_GroupChat?.groupThreadDisplayTitle;
    if (typeof fn === "function") return fn(thread);
    const g = String(thread.groupTitle || "").trim();
    return g || "群聊";
  }
  const al = getThreadCharDisplayAlias(thread);
  if (al) return al;
  return charDisplayNameById(thread.charId);
}

function readActiveThread() {
  reconcileActiveThreadRef();
  const maskId = getActiveMaskIdForInbox();
  const ref = readChatActiveThreadRef();
  const inbox = readChatInboxStore();
  ensureMaskBucket(inbox, maskId);
  const bucket = inbox.byMask[maskBucketKey(maskId)];
  return bucket.threads.find((t) => t.id === ref.threadId) || null;
}

/** 密谈是否启用「心声」手记（默认开；仅 `heartVoiceEnabled === false` 为关）。群聊无此功能。 */
function isThreadHeartVoiceEnabled(thread) {
  if (!thread || typeof thread !== "object") return true;
  if (isChatThreadGroupForUi(thread)) return false;
  return thread.heartVoiceEnabled !== false;
}

/** 密谈是否启用「小剧场」每轮快照（默认开；仅 `theaterEnabled === false` 为关）。群聊无此功能。 */
function isThreadTheaterEnabled(thread) {
  if (!thread || typeof thread !== "object") return false;
  if (isChatThreadGroupForUi(thread)) return false;
  return thread.theaterEnabled !== false;
}

/** 密谈是否启用「中插 HTML 自动」（默认关；仅 `inlineHtmlAutoEnabled === true` 为开）。群聊无此功能。 */
function isThreadInlineHtmlAutoEnabled(thread) {
  if (!thread || typeof thread !== "object") return false;
  if (isChatThreadGroupForUi(thread)) return false;
  return thread.inlineHtmlAutoEnabled === true;
}

/** 主控是否已拉黑本密谈角色（卷宗开关）。 */
function isThreadUserBlockedChar(thread) {
  if (!thread || typeof thread !== "object") return false;
  if (isChatThreadGroupForUi(thread)) return false;
  return thread.userBlockedChar === true;
}

/** 角色是否已拉黑主控（仅剧情 JSON 触发）。 */
function isThreadCharBlockedUser(thread) {
  if (!thread || typeof thread !== "object") return false;
  if (isChatThreadGroupForUi(thread)) return false;
  return thread.charBlockedUser === true;
}

/** @param {"user"|"assistant"} role */
function resolveOutgoingMessageBlockBadge(thread, role) {
  if (!thread || typeof thread !== "object" || isChatThreadGroupForUi(thread)) return "";
  if (role === "user" && isThreadCharBlockedUser(thread)) return "char_blocked_user";
  if (role === "assistant" && isThreadUserBlockedChar(thread)) return "user_blocked_char";
  return "";
}

/** @param {Record<string, unknown>} entry @param {unknown} thread @param {"user"|"assistant"} role */
function tagChatMessageBlockBadgeIfNeeded(entry, thread, role) {
  if (!entry || typeof entry !== "object") return;
  if (entry.dmSurface === "offline") return;
  const badge = resolveOutgoingMessageBlockBadge(thread, role);
  if (badge) entry.blockBadge = badge;
}

const THEATER_GEN_MODE_SEPARATE = "separate";
const THEATER_GEN_MODE_MERGED = "merged";
const THEATER_PROMPT_MIN_GAP_DEFAULT = 6;
const THEATER_PROMPT_MIN_GAP_MAX = 30;

function readTheaterPromptMinGap() {
  const D = window.XXJ_DB;
  if (!D) return THEATER_PROMPT_MIN_GAP_DEFAULT;
  const raw = Number(D.getKv(D.K.THEATER_PROMPT_MIN_GAP));
  if (!Number.isFinite(raw)) return THEATER_PROMPT_MIN_GAP_DEFAULT;
  return Math.max(0, Math.min(THEATER_PROMPT_MIN_GAP_MAX, Math.floor(raw)));
}

function writeTheaterPromptMinGap(n) {
  const D = window.XXJ_DB;
  if (!D) return;
  const v = Math.max(0, Math.min(THEATER_PROMPT_MIN_GAP_MAX, Math.floor(Number(n) || 0)));
  D.setKv(D.K.THEATER_PROMPT_MIN_GAP, v);
}

/** @param {unknown} raw @returns {number | null} */
function normalizeTheaterPromptMinGap(raw) {
  const n = Math.floor(Number(raw));
  if (!Number.isFinite(n)) return null;
  return Math.max(0, Math.min(THEATER_PROMPT_MIN_GAP_MAX, n));
}

/** @param {unknown} thread @returns {number | null} null = 跟随设置默认 */
function getThreadTheaterPromptMinGap(thread) {
  if (!thread || typeof thread !== "object") return null;
  return normalizeTheaterPromptMinGap(/** @type {Record<string, unknown>} */ (thread).theaterPromptMinGap);
}

/** @param {unknown} thread */
function threadUsesTheaterDefaultPromptMinGap(thread) {
  return getThreadTheaterPromptMinGap(thread) == null;
}

/** @param {unknown} [thread] */
function resolveTheaterPromptMinGap(thread) {
  const override = getThreadTheaterPromptMinGap(thread);
  if (override != null) return override;
  return readTheaterPromptMinGap();
}

function readTheaterGenMode() {
  const D = window.XXJ_DB;
  const raw = String(D?.getKv(D.K.THEATER_GEN_MODE) || "").trim();
  if (raw === THEATER_GEN_MODE_SEPARATE) return THEATER_GEN_MODE_SEPARATE;
  return THEATER_GEN_MODE_MERGED;
}

/** @param {"separate"|"merged"} mode */
function writeTheaterGenMode(mode) {
  const D = window.XXJ_DB;
  if (!D) return;
  D.setKv(
    D.K.THEATER_GEN_MODE,
    mode === THEATER_GEN_MODE_MERGED ? THEATER_GEN_MODE_MERGED : THEATER_GEN_MODE_SEPARATE
  );
}

function isTheaterMergedWithChat() {
  return readTheaterGenMode() === THEATER_GEN_MODE_MERGED;
}

/** 手记面板（心声 / 小剧场 Tab）是否至少有一项可用。 */
function isThreadMemoPanelAvailable(thread) {
  return isThreadHeartVoiceEnabled(thread) || isThreadTheaterEnabled(thread);
}

