const THEATER_MAX_ENABLED_PRESETS = 3;

/** 小剧场与 heartVoice 相同：只给中文读者，不受对照翻译 / dialogueLang 影响。 */
function buildTheaterForceChinesePromptLines() {
  return [
    `[小剧场 · 语言 · 强制中文]`,
    `theaterSnaps 内所有 text / html 的可见正文**一律简体中文**（与密谈是否开启「对照翻译」、角色 dialogueLang 无关；**禁止**为配合外文聊天气泡而写成外语）。`,
    `与 heartVoice 相同：小剧场只给中文读者看；需要呈现外语台词时用中文叙述或中文括注即可。`
  ];
}

/** @param {string[]} ids @param {{ allowEmpty?: boolean }} [opts] */
function normalizeTheaterEnabledPresetIds(ids, opts) {
  const all = listAllTheaterPresets();
  const valid = new Set(all.map((p) => p.id));
  const out = [];
  for (const raw of Array.isArray(ids) ? ids : []) {
    const id = String(raw || "").trim();
    if (!id || !valid.has(id) || out.includes(id)) continue;
    out.push(id);
    if (out.length >= THEATER_MAX_ENABLED_PRESETS) break;
  }
  if (out.length) return out;
  if (opts?.allowEmpty) return [];
  return [THEATER_BUILTIN_PRESETS[0]?.id || "builtin-diary"];
}

function readTheaterDefaultEnabledPresetIds() {
  const D = window.XXJ_DB;
  if (!D) return normalizeTheaterEnabledPresetIds([], { allowEmpty: true });
  const raw = D.getKv(D.K.THEATER_DEFAULT_ENABLED);
  return normalizeTheaterEnabledPresetIds(Array.isArray(raw) ? raw : [], { allowEmpty: true });
}

/** @param {string[]} ids */
function writeTheaterDefaultEnabledPresetIds(ids) {
  const D = window.XXJ_DB;
  if (!D) return;
  D.setKv(D.K.THEATER_DEFAULT_ENABLED, normalizeTheaterEnabledPresetIds(ids, { allowEmpty: true }));
}

/** @param {unknown} thread */
function getThreadTheaterEnabledPresetIds(thread) {
  if (thread && typeof thread === "object") {
    const t = /** @type {Record<string, unknown>} */ (thread);
    if (Array.isArray(t.theaterEnabledPresetIds)) {
      return normalizeTheaterEnabledPresetIds(t.theaterEnabledPresetIds, { allowEmpty: true });
    }
    const legacy = String(t.theaterPresetId || "").trim();
    if (legacy && getTheaterPresetById(legacy)) {
      return normalizeTheaterEnabledPresetIds([legacy], { allowEmpty: true });
    }
  }
  return readTheaterDefaultEnabledPresetIds();
}

/** @param {unknown} thread */
function threadUsesTheaterDefaultPresets(thread) {
  if (!thread || typeof thread !== "object") return true;
  const t = /** @type {Record<string, unknown>} */ (thread);
  return !Array.isArray(t.theaterEnabledPresetIds) || !t.theaterEnabledPresetIds.length;
}

/**
 * @param {HTMLElement} root
 * @param {{ ids: string[], checked: string[], max: number, namePrefix: string, onChange?: (checked: string[]) => void, showBuiltinLabel?: boolean }} spec
 */
function renderTheaterPresetCheckboxList(root, spec) {
  if (!(root instanceof HTMLElement)) return;
  root.replaceChildren();
  const checkedSet = new Set(Array.isArray(spec.checked) ? spec.checked : []);
  const presets = listAllTheaterPresets().filter((p) => spec.ids.includes(p.id));
  for (const p of presets) {
    const label = document.createElement("label");
    label.className = "theater-preset-check";
    const input = document.createElement("input");
    input.type = "checkbox";
    input.name = `${spec.namePrefix}-${p.id}`;
    input.value = p.id;
    input.checked = checkedSet.has(p.id);
    const meta = document.createElement("span");
    meta.className = "theater-preset-check-meta";
    const strong = document.createElement("strong");
    strong.textContent = p.name;
    meta.appendChild(strong);
    const sub = document.createElement("span");
    sub.textContent =
      p.kind === "html" ? "HTML" : "文字";
    if (spec.showBuiltinLabel && p.builtin) sub.textContent += " · 内置";
    else if (!p.builtin) sub.textContent += " · 自定义";
    meta.appendChild(sub);
    label.appendChild(input);
    label.appendChild(meta);
    input.addEventListener("change", () => {
      const boxes = [...root.querySelectorAll('input[type="checkbox"]')].filter(
        (el) => el instanceof HTMLInputElement
      );
      let picked = boxes.filter((el) => el.checked).map((el) => el.value);
      if (picked.length > spec.max) {
        input.checked = false;
        picked = boxes.filter((el) => el.checked).map((el) => el.value);
        showToast(`最多勾选 ${spec.max} 个`);
      }
      if (typeof spec.onChange === "function") spec.onChange(picked);
    });
    root.appendChild(label);
  }
}

/** @returns {{ id: string, name: string, kind: "text"|"html", instruction?: string, htmlShell?: string, builtin?: boolean }[]} */
function readCustomTheaterPresetsFromKv() {
  const D = window.XXJ_DB;
  if (!D) return [];
  const arr = D.getKv(D.K.THEATER_PRESETS);
  if (!Array.isArray(arr)) return [];
  const out = [];
  for (const raw of arr) {
    if (!raw || typeof raw !== "object") continue;
    const o = /** @type {Record<string, unknown>} */ (raw);
    const id = String(o.id || "").trim();
    const name = String(o.name || "").trim();
    if (!id || !name) continue;
    const kind = o.kind === "html" ? "html" : "text";
    out.push({
      id,
      name: name.slice(0, 80),
      kind,
      instruction: typeof o.instruction === "string" ? o.instruction : "",
      htmlShell: typeof o.htmlShell === "string" ? o.htmlShell : "",
      updatedAt: Number(o.updatedAt) || Date.now()
    });
  }
  return out;
}

/** @param {ReturnType<typeof readCustomTheaterPresetsFromKv>} list */
function writeCustomTheaterPresetsToKv(list) {
  const D = window.XXJ_DB;
  if (!D) return;
  D.setKv(D.K.THEATER_PRESETS, Array.isArray(list) ? list : []);
}

/** @param {{ name: string, kind?: "text"|"html", instruction?: string, htmlShell?: string }} entry */
function appendCustomTheaterPresetEntry(entry) {
  const name = String(entry?.name || "").trim().slice(0, 80);
  if (!name) return false;
  const kind = entry?.kind === "html" ? "html" : "text";
  const instruction = String(entry?.instruction || "").trim();
  const htmlShell = kind === "html" ? String(entry?.htmlShell || "").trim() : "";
  const list = readCustomTheaterPresetsFromKv();
  list.unshift({
    id: newCustomTheaterPresetId(),
    name,
    kind,
    instruction,
    htmlShell,
    updatedAt: Date.now()
  });
  writeCustomTheaterPresetsToKv(list);
  chatTheaterRerollPicksKey = "";
  refreshSettingsTheaterPanel();
  syncChatDetailTheaterPresetUi();
  syncChatTheaterPanelFromLog();
  return true;
}

function listAllTheaterPresets() {
  return [...THEATER_BUILTIN_PRESETS, ...readCustomTheaterPresetsFromKv()];
}

/** @param {string} id */
function getTheaterPresetById(id) {
  const want = String(id || "").trim();
  if (!want) return THEATER_BUILTIN_PRESETS[0] || null;
  return listAllTheaterPresets().find((p) => p.id === want) || THEATER_BUILTIN_PRESETS[0] || null;
}

function newCustomTheaterPresetId() {
  return `cust${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
}

/** @param {string} raw */
function theaterPrepareProseHtmlSource(raw) {
  let s = String(raw ?? "").trim();
  if (!s) return s;
  if (/&lt;(?:\/?)\s*[a-z]/i.test(s) && !/<\s*\/?\s*[a-z]/i.test(s)) {
    const ta = document.createElement("textarea");
    ta.innerHTML = s;
    s = String(ta.value || "").trim();
  }
  s = s.replace(/<\?xml[\s\S]*?\?>/gi, "").replace(/<!DOCTYPE[^>]*>/gi, "");
  const bodyM = s.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
  if (bodyM) s = bodyM[1];
  return s.trim();
}

/** @param {string} s */
function theaterProseLooksLikeHtml(s) {
  const t = theaterPrepareProseHtmlSource(String(s ?? ""));
  return Boolean(t && /<[a-z][\w:-]*[\s>\/]/i.test(t));
}

/** @param {string} raw */
function theaterStripModelFences(raw) {
  let s = String(raw || "").trim();
  const m = s.match(/^```(?:\w+)?\s*([\s\S]*?)```$/i);
  if (m) s = m[1].trim();
  return s.replace(/^```(?:html|htm|text)?\s*/i, "").replace(/```\s*$/i, "").trim();
}

/** @param {string} raw */
function theaterNormalizeModelHtml(raw) {
  let s = theaterStripModelFences(raw);
  s = s.replace(/^(?:html|htm)\s*/i, "").trim();
  s = theaterPrepareProseHtmlSource(s);
  if (theaterProseLooksLikeHtml(s)) return s;
  const blocks = s.split(/\n{2,}/).map((x) => x.trim()).filter(Boolean);
  if (!blocks.length && s.trim()) blocks.push(s.trim());
  if (!blocks.length) return "";
  return blocks
    .map((b) => {
      const line = theaterPrepareProseHtmlSource(b);
      if (/<[a-z][\w:-]*[\s>\/]/i.test(line)) return line;
      return `<p>${escapeHtml(b)}</p>`;
    })
    .join("\n");
}

/** @param {string} innerHtml */
function theaterWrapHtmlDocument(innerHtml) {
  const body = String(innerHtml || "").trim() || "<p>（空）</p>";
  return `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
body{font-family:system-ui,-apple-system,"Noto Sans SC",sans-serif;margin:0;padding:18px 16px;line-height:1.6;background:#faf8f5;color:#1a1a1a}
</style></head><body>${body}</body></html>`;
}

/** @param {unknown} m @param {string} presetId */
function theaterSnapFromAssistantMessage(m, presetId) {
  const pid = String(presetId || "").trim();
  if (!m || typeof m !== "object" || !pid) return null;
  const box = /** @type {Record<string, unknown>} */ (m).theaterSnaps;
  if (!box || typeof box !== "object") return null;
  const snap = /** @type {Record<string, unknown>} */ (box)[pid];
  if (!snap || typeof snap !== "object") return null;
  const s = /** @type {Record<string, unknown>} */ (snap);
  const text = typeof s.text === "string" ? s.text : "";
  const html = typeof s.html === "string" ? s.html : "";
  if (s.pending === true && !text.trim() && !html.trim()) {
    const preset = getTheaterPresetById(pid);
    return {
      kind: preset?.kind === "html" ? "html" : "text",
      text: "",
      html: "",
      pending: true,
      error: typeof s.error === "string" ? s.error : "",
      at: Number(s.at) || 0
    };
  }
  return {
    kind: s.kind === "html" ? "html" : "text",
    text,
    html,
    pending: false,
    error: typeof s.error === "string" ? s.error : "",
    at: Number(s.at) || 0
  };
}

/** @param {ReturnType<typeof theaterSnapFromAssistantMessage>} snap */
function theaterSnapHasRenderableContent(snap) {
  if (!snap || snap.pending) return false;
  if (snap.kind === "html") return Boolean(String(snap.html || "").trim());
  return Boolean(String(snap.text || "").trim());
}

const theaterGenInflight = new Map();

/** @param {string} maskId @param {string} threadId @param {number} msgIdx @param {string[]} presetIds */
function theaterBundleInflightKey(maskId, threadId, msgIdx, presetIds) {
  const ids = [...presetIds].sort().join(",");
  return `${maskId}:${threadId}:${msgIdx}:bundle:${ids}`;
}

/** @param {unknown} o */
function extractTheaterSnapsRawFromAssistantJson(o) {
  if (!o || typeof o !== "object" || Array.isArray(o)) return null;
  const rec = /** @type {Record<string, unknown>} */ (o);
  const box = rec.theaterSnaps ?? rec.theater_snaps;
  if (!box || typeof box !== "object" || Array.isArray(box)) return null;
  return box;
}

/**
 * @param {ReturnType<typeof getTheaterPresetById>} preset
 * @param {unknown} node
 */
function parseTheaterSnapNode(preset, node) {
  if (!preset || !node || typeof node !== "object" || Array.isArray(node)) return null;
  const n = /** @type {Record<string, unknown>} */ (node);
  if (preset.kind === "html") {
    let html = theaterNormalizeModelHtml(typeof n.html === "string" ? n.html : "");
    if (!html && typeof n.text === "string") html = theaterNormalizeModelHtml(n.text);
    if (!html) {
      const wb = theaterPrepareProseHtmlSource(String(preset.htmlShell || "").trim());
      if (wb) html = wb;
    }
    if (html) return { kind: /** @type {const} */ ("html"), html: html.slice(0, 120_000) };
    return null;
  }
  const text = theaterStripModelFences(
    typeof n.text === "string" ? n.text : typeof n.html === "string" ? n.html : ""
  );
  if (text.trim()) return { kind: /** @type {const} */ ("text"), text: text.trim().slice(0, 80_000) };
  return null;
}

/** @param {unknown} raw @param {string[]} presetIds */
function parseTheaterSnapsFromRawObject(raw, presetIds) {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return {};
  /** @type {Record<string, { kind: "text"|"html", text?: string, html?: string }>} */
  const out = {};
  for (const pid of presetIds) {
    const preset = getTheaterPresetById(pid);
    if (!preset) continue;
    const row = parseTheaterSnapNode(preset, /** @type {Record<string, unknown>} */ (raw)[pid]);
    if (row) out[pid] = row;
  }
  return out;
}

/**
 * @param {Record<string, unknown>} entry
 * @param {Record<string, { kind: "text"|"html", text?: string, html?: string }>} snapMap
 */
function writeTheaterSnapsToAssistantEntry(entry, snapMap) {
  if (!entry || entry.role !== "assistant" || !snapMap || !Object.keys(snapMap).length) return;
  if (!entry.theaterSnaps || typeof entry.theaterSnaps !== "object") entry.theaterSnaps = {};
  const at = Date.now();
  for (const [pid, row] of Object.entries(snapMap)) {
    if (row.kind === "html") entry.theaterSnaps[pid] = { kind: "html", html: row.html || "", at };
    else entry.theaterSnaps[pid] = { kind: "text", text: row.text || "", at };
  }
}

/**
 * @param {Record<string, unknown>} entry
 * @param {ReturnType<typeof parseChatAssistantPayload>} parsed
 * @param {unknown} thread
 */
function applyTheaterSnapsToAssistantEntry(entry, parsed, thread) {
  if (!entry || entry.role !== "assistant" || !parsed?.fromJson || !isThreadTheaterEnabled(thread)) return;
  const raw = parsed.theaterSnapsRaw;
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return;
  const presetIds = getThreadTheaterEnabledPresetIds(thread);
  if (!presetIds.length) return;
  const snapMap = parseTheaterSnapsFromRawObject(raw, presetIds);
  writeTheaterSnapsToAssistantEntry(entry, snapMap);
}

/** @param {Record<string, unknown>} entry @param {ReturnType<typeof parseChatAssistantPayload>} parsed */
function applyInlineHtmlCardsToAssistantEntry(entry, parsed) {
  if (!entry || entry.role !== "assistant" || !parsed?.fromJson) return;
  const cards = parsed.inlineHtmlCards;
  if (Array.isArray(cards) && cards.length) entry.inlineHtmlCards = cards;
  if (typeof window.XXJ_InlineHtml?.materializeInlineHtmlOnMessage === "function") {
    window.XXJ_InlineHtml.materializeInlineHtmlOnMessage(entry);
  }
}

let inlineHtmlCardRerolling = false;

function canRerollAssistantInlineHtmlCards() {
  if (getActiveChatDmSurfaceForContext() === "offline") return false;
  const th = readActiveThread();
  if (!th || isChatThreadGroupForUi(th)) return false;
  return true;
}

/** @param {unknown} msg */
function messageEligibleForInlineHtmlReroll(msg) {
  if (!msg || typeof msg !== "object" || msg.role !== "assistant" || msg.restoring) return false;
  if (!canRerollAssistantInlineHtmlCards()) return false;
  return (
    typeof window.XXJ_InlineHtml?.messageHasInlineHtmlCards === "function" &&
    window.XXJ_InlineHtml.messageHasInlineHtmlCards(msg)
  );
}

/** @param {number} msgIdx */
async function rerollAssistantInlineHtmlCards(msgIdx) {
  const ai = window.RP_AI;
  if (!ai) {
    showToast("AI 模块未加载");
    return;
  }
  if (inlineHtmlCardRerolling) return;
  const pin = await beginChatSendPinAsync();
  if (!pin) {
    showChatThreadUnavailableToast();
    return;
  }
  const idx = Math.floor(Number(msgIdx));
  const log0 = readChatLogForSendPin(pin);
  if (!Number.isFinite(idx) || idx < 0 || idx >= log0.length) {
    showToast("消息已变化，请重试");
    return;
  }
  const m0 = log0[idx];
  if (!messageEligibleForInlineHtmlReroll(m0)) {
    showToast("当前消息无法重 roll 插卡");
    return;
  }
  inlineHtmlCardRerolling = true;
  showToast("正在重 roll 插卡…");
  try {
    const bound = chatRoundBoundFromPin(pin);
    const prefix = log0.slice(0, idx + 1);
    const th = pin.thread;
    const apiLog = sliceChatLogForApiMemoryWindowAnchoredToLastUser(prefix, "im", th);
    const baseMessages = await buildChatApiMessagesFromLogAsync(true, apiLog, bound, "im");
    const rerollHint =
      typeof window.XXJ_InlineHtml?.hintFromRecentInlineHtmlCard === "function"
        ? window.XXJ_InlineHtml.hintFromRecentInlineHtmlCard([m0])
        : "";
    const rerollLines =
      typeof window.XXJ_InlineHtml?.buildRerollPromptLines === "function"
        ? window.XXJ_InlineHtml.buildRerollPromptLines({ lastCardHint: rerollHint })
        : ['请仅输出 JSON：{ "inlineHtmlCards": [ … ] }，重生成一条插卡，不要 lines。'];
    const messages = [...baseMessages, { role: "user", content: rerollLines.join("\n") }];
    const data = await requestChatAssistantCompletion(ai, {
      messages,
      response_format: { type: "json_object" }
    });
    rememberChatApiUsage(data?.usage);
    updateChatContextTokenLabel();
    const raw = readChatCompletionChoiceText(data);
    if (!String(raw || "").trim()) throw new Error(explainModelEmptyReply(data, raw));
    const parsed = parseChatAssistantPayload(raw);
    const cards = parsed.inlineHtmlCards;
    if (!Array.isArray(cards) || !cards.length) {
      throw new Error("模型未返回 inlineHtmlCards");
    }
    const liveLog = readChatLogForSendPin(pin);
    if (idx < 0 || idx >= liveLog.length) throw new Error("消息已变化");
    const liveM = liveLog[idx];
    if (!liveM || liveM.role !== "assistant") throw new Error("消息已变化");
    liveM.inlineHtmlCards = cards;
    if (typeof window.XXJ_InlineHtml?.materializeInlineHtmlOnMessage === "function") {
      window.XXJ_InlineHtml.materializeInlineHtmlOnMessage(liveM);
    }
    saveChatLogForSendPin(pin, liveLog);
    chatSuppressNextChatMessageAnimations = true;
    scheduleChatUiRefreshForRound(pin.maskId, pin.threadId, { flush: true });
    showToast("插卡已重 roll");
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    showToast(`重 roll 失败：${msg}`);
  } finally {
    inlineHtmlCardRerolling = false;
  }
}

window.canRerollAssistantInlineHtmlCards = canRerollAssistantInlineHtmlCards;
window.rerollAssistantInlineHtmlCards = rerollAssistantInlineHtmlCards;

/** @param {unknown} th @param {boolean} [heartOn] */
function buildTheaterMergedChatPromptLines(th, heartOn) {
  const presetIds = getThreadTheaterEnabledPresetIds(th);
  const presets = presetIds.map((id) => getTheaterPresetById(id)).filter(Boolean);
  if (!presets.length) return [];
  const blocks = [];
  for (const preset of presets) {
    const lines = [`· **${preset.id}**（${preset.name}，${preset.kind}）`];
    const hint = String(preset.instruction || "").trim();
    if (hint) lines.push(hint.slice(0, 800));
    if (preset.kind === "html") {
      const wb = theaterPrepareProseHtmlSource(String(preset.htmlShell || "").trim());
      if (wb) lines.push(`【版式参考 — 保留 inline style，按此结构填内容】\n${wb.slice(0, 5000)}`);
    }
    blocks.push(lines.join("\n"));
  }
  const ex = presets[0];
  const exVal = ex?.kind === "html" ? '{"html":"<div>…</div>"}' : '{"text":"…"}';
  return [
    `[小剧场 · 并入本轮 JSON · 本轮必填]`,
    ...buildTheaterForceChinesePromptLines(),
    `本密谈已开启小剧场，且设定为**与聊天同一次输出**。除 lines${
      heartOn ? "、heartVoice 与心声扩展键" : ""
    } 外，**本轮必填** \`theaterSnaps\`：键为 preset id（字符串），值为 \`{ "text": "…" }\` 或 \`{ "html": "…" }\`（html 须为片段，禁止 DOCTYPE/html/head/body，禁止 markdown 围栏）。`,
    `小剧场**不进入**聊天气泡与后续对话上下文，只供用户在手记里阅读；勿把论坛/HTML 正文写进 lines。`,
    `距上次有小剧场内容已隔满间隔轮数——**本轮不要 omit**，**一次写全**下方列出的各项；缺项不会自动再请求 API（用户可稍后在手记里对单项点「重 roll」）。`,
    `待生成 ${presets.length} 项：`,
    blocks.join("\n\n"),
    `示例：\`"theaterSnaps": { "${ex?.id || "preset-id"}": ${exVal} }\``
  ];
}

/** @param {readonly unknown[]} log */
function countAssistantTurnsSinceLastTheaterInLog(log) {
  const arr = Array.isArray(log) ? log : [];
  let n = 0;
  for (let i = arr.length - 1; i >= 0; i--) {
    const m = arr[i];
    if (!m || typeof m !== "object" || m.role !== "assistant") continue;
    if (isAssistantTypingPlaceholder(m)) continue;
    const box = /** @type {{ theaterSnaps?: Record<string, unknown> }} */ (m).theaterSnaps;
    if (box && typeof box === "object") {
      let has = false;
      for (const v of Object.values(box)) {
        if (!v || typeof v !== "object") continue;
        const vo = /** @type {{ text?: string, html?: string }} */ (v);
        if (String(vo.text || vo.html || "").trim()) {
          has = true;
          break;
        }
      }
      if (has) return n;
    }
    n++;
  }
  return n;
}

/** @param {unknown} th @param {readonly unknown[]} [promptLog] @param {{ force?: boolean, forPromptBuild?: boolean }} [opts] */
function shouldRunTheaterByPromptMinGap(th, promptLog, opts) {
  if (opts?.force) return true;
  if (!th || typeof th !== "object" || /** @type {{ kind?: string }} */ (th).kind === "group") return false;
  if (!isThreadTheaterEnabled(th)) return false;
  if (!getThreadTheaterEnabledPresetIds(th).length) return false;
  const gap = resolveTheaterPromptMinGap(th);
  if (gap <= 0) return true;
  const turns = countAssistantTurnsSinceLastTheaterInLog(Array.isArray(promptLog) ? promptLog : []);
  // 并入聊天：构建 prompt 时 log 尚无「本条 assistant」，须 +1 对齐间隔
  if (opts?.forPromptBuild) return turns + 1 >= gap;
  return turns >= gap;
}

/** @param {unknown} th @param {boolean} [heartOn] @param {readonly unknown[]} [promptLog] */
function buildImTheaterChatPromptLines(th, heartOn, promptLog) {
  if (
    !th ||
    typeof th !== "object" ||
    th.kind === "group" ||
    !isThreadTheaterEnabled(th) ||
    !isTheaterMergedWithChat() ||
    !getThreadTheaterEnabledPresetIds(th).length
  ) {
    return [];
  }
  if (shouldRunTheaterByPromptMinGap(th, promptLog, { forPromptBuild: true })) {
    return buildTheaterMergedChatPromptLines(th, heartOn);
  }
  return [
    `[THEATER · 默认 omit]`,
    `小剧场已开（并入 JSON）；**绝大多数轮不要写 theaterSnaps**（省略键或 {}）。完整说明间隔：${resolveTheaterPromptMinGap(th)} 轮你的回复；隔满才再注入完整说明并**要求本轮输出**。`
  ];
}

/** @param {unknown} anchorMsg */
function resolveTheaterGenDmSurface(anchorMsg) {
  if (anchorMsg && typeof anchorMsg === "object") return chatMessageDmSurface(anchorMsg);
  return getActiveChatDmSurfaceForContext();
}

/**
 * 单独小剧场：log 锚定到 assistant 下标 pi（含该条），再按记忆窗口截断。
 * @param {unknown[]} full
 * @param {number} pi
 * @param {"im" | "offline"} surface
 * @param {unknown} [thread]
 */
function sliceChatLogForTheaterSeparateGen(full, pi, surface, thread) {
  const arr = Array.isArray(full) ? full : [];
  const idx = Math.floor(Number(pi));
  const prefix = idx >= 0 && idx < arr.length ? arr.slice(0, idx + 1) : arr;
  return sliceChatLogForApiMemoryWindow(prefix, surface, thread);
}

/** @param {ReturnType<typeof getTheaterPresetById>[]} presets */
function buildTheaterSeparateGenPresetDetailLines(presets) {
  const blocks = [];
  for (const preset of presets) {
    if (!preset) continue;
    const lines = [`· **${preset.id}** · ${preset.name}（${preset.kind}）`];
    const hint = String(preset.instruction || "").trim();
    if (hint) lines.push(hint);
    if (preset.kind === "html") {
      const wbHtml = theaterPrepareProseHtmlSource(String(preset.htmlShell || "").trim());
      if (wbHtml) {
        lines.push(
          `【HTML 模板 — 须以此为版式基准，输出同类型 HTML 片段，勿改成纯文字列表】\n${wbHtml.slice(0, 12000)}`
        );
      }
      lines.push("【该项输出】只输出 HTML 片段（须含标签，禁止 DOCTYPE/html/head/body，禁止 markdown 围栏）。");
    } else {
      lines.push("【该项输出】只输出纯文本正文，不要 markdown 代码围栏。");
    }
    blocks.push(lines.join("\n"));
  }
  return blocks;
}

/** @param {string[]} presetIds */
function buildTheaterSeparateGenSystemOutputLines(presetIds) {
  const presets = presetIds.map((id) => getTheaterPresetById(id)).filter(Boolean);
  if (!presets.length) return [];
  const blocks = buildTheaterSeparateGenPresetDetailLines(presets);
  const ex = presets[0];
  const exVal = ex?.kind === "html" ? '{"html":"<div>…</div>"}' : '{"text":"…"}';
  return [
    `[小剧场 · 单独生成 · 输出协议]`,
    ...buildTheaterForceChinesePromptLines(),
    `上文已给出完整密谈上下文（人设、世界书、记忆、聊天记录等）。**不要**再写聊天气泡 \`lines\`、\`heartVoice\`、\`narration\` 或其它聊天 JSON 键；小剧场**不进入**真实聊天气泡与后续对话。`,
    `只输出**一个** JSON 对象：键为 preset id（字符串），值为 \`{ "text": "…" }\` 或 \`{ "html": "…" }\`（html 须为片段，禁止整页 DOCTYPE/html/head/body，禁止 markdown 围栏）。`,
    `须一次写全下列 ${presets.length} 项；缺项不会自动再请求。`,
    blocks.join("\n\n"),
    `除上述 JSON 外不要其它前言、后记或 markdown 围栏。`,
    `示例：\`{ "${ex?.id || "preset-id"}": ${exVal} }\``
  ];
}

/**
 * 单独小剧场 API：与聊天同套 system + 记忆窗口内 messages，末尾追加生成指令。
 * @param {string} maskId
 * @param {string} threadId
 * @param {number} anchorIdx
 * @param {string[]} presetIds
 */
async function buildTheaterSeparateGenMessagesAsync(maskId, threadId, anchorIdx, presetIds) {
  const mid = String(maskId || "").trim();
  const tid = String(threadId || "").trim();
  const pi = Math.floor(Number(anchorIdx));
  const found = findChatThreadInInbox(mid, tid);
  const th = found?.thread ?? null;
  const full = readChatLogForMaskThread(mid, tid);
  const anchorMsg = full[pi];
  const surface = resolveTheaterGenDmSurface(anchorMsg);
  const apiLog = sliceChatLogForTheaterSeparateGen(full, pi, surface, th);
  const roundOpts = {
    boundMaskId: mid,
    boundThreadId: tid,
    boundThread: th,
    theaterSeparateGen: true,
    theaterSeparatePresetIds: presetIds,
    forceDmSurface: surface
  };
  const msgs = await buildChatApiMessagesFromLogAsync(false, apiLog, roundOpts, surface);
  const presets = presetIds.map((id) => getTheaterPresetById(id)).filter(Boolean);
  msgs.push({
    role: "user",
    content:
      `[小剧场 · 请生成]\n上文最后一轮角色回复已完整给出。请依据全部上下文，**仅**输出一个 JSON 对象，包含系统提示列出的全部 ${presets.length} 个小剧场 preset（键为 preset id），不要输出 lines、heartVoice 或其它聊天字段。`
  });
  return msgs;
}

/** @param {unknown} raw @param {string[]} presetIds */
function normalizeTheaterBundleResponseObject(raw, presetIds) {
  if (!raw || typeof raw !== "object") return raw;
  let root = raw;
  if (Array.isArray(root)) {
    if (presetIds.length === 1 && root.length === 1) root = { [presetIds[0]]: root[0] };
    else return raw;
  }
  const rec = /** @type {Record<string, unknown>} */ (root);
  const keys = Object.keys(rec);
  /** @type {Record<string, unknown>} */
  const mapped = {};
  for (const pid of presetIds) {
    if (rec[pid] != null) {
      mapped[pid] = rec[pid];
      continue;
    }
    const ci = keys.find((k) => String(k).toLowerCase() === pid.toLowerCase());
    if (ci != null) {
      mapped[pid] = rec[ci];
      continue;
    }
    const preset = getTheaterPresetById(pid);
    if (preset) {
      const byName = keys.find((k) => {
        const kn = String(k).trim();
        return kn === preset.name || kn.includes(preset.name) || preset.name.includes(kn);
      });
      if (byName != null) mapped[pid] = rec[byName];
    }
  }
  if (presetIds.length === 1) {
    const lone = presetIds[0];
    if (!mapped[lone] && (typeof rec.text === "string" || typeof rec.html === "string")) {
      mapped[lone] = rec;
    } else if (!mapped[lone] && keys.length === 1) {
      mapped[lone] = rec[keys[0]];
    }
  }
  if (Object.keys(mapped).length) return { ...rec, ...mapped };
  return raw;
}

/** @param {string} raw @param {string[]} presetIds */
function parseTheaterBundleResponse(raw, presetIds) {
  let s = theaterStripModelFences(String(raw || "").trim());
  const jsonM = s.match(/\{[\s\S]*\}/);
  if (jsonM) s = jsonM[0];
  /** @type {Record<string, unknown>} */
  let obj;
  try {
    obj = JSON.parse(s);
  } catch {
    throw new Error("模型未返回有效 JSON");
  }
  if (!obj || typeof obj !== "object" || Array.isArray(obj)) throw new Error("JSON 根须为对象");
  const nested = extractTheaterSnapsRawFromAssistantJson(obj);
  const normalized = normalizeTheaterBundleResponseObject(nested || obj, presetIds);
  const out = parseTheaterSnapsFromRawObject(normalized, presetIds);
  if (!Object.keys(out).length) throw new Error("JSON 中无可用小剧场内容");
  return out;
}

/** 异步小剧场写回：按 at 锚点找回气泡（log 插入/重排后 pi 可能失效）。 */
function resolveTheaterSnapWriteTarget(log, pi, anchorAt) {
  const arr = Array.isArray(log) ? log : [];
  const idx0 = Math.floor(Number(pi));
  const atN = Number(anchorAt);
  if (idx0 >= 0 && idx0 < arr.length) {
    const m = arr[idx0];
    if (m && m.role === "assistant" && (!Number.isFinite(atN) || Number(m.at) === atN)) {
      return { idx: idx0, msg: m };
    }
  }
  if (!Number.isFinite(atN)) return null;
  for (let i = arr.length - 1; i >= 0; i--) {
    const m = arr[i];
    if (m && m.role === "assistant" && Number(m.at) === atN) return { idx: i, msg: m };
  }
  return null;
}

/** 小剧场写入 log 后刷新手记面板（含心声 Tab 内的小剧场面板）。 */
function refreshChatTheaterUiAfterSnapWrite(maskId, threadId, writtenIdx) {
  const mid = String(maskId || "").trim();
  const tid = String(threadId || "").trim();
  const ref = readChatActiveThreadRef();
  if (ref.maskId !== mid || ref.threadId !== tid) return;
  const wi = Math.floor(Number(writtenIdx));
  if (Number.isFinite(wi) && wi >= 0) {
    const log = readChatLogForMaskThread(mid, tid);
    const surface = getActiveChatDmSurfaceForContext();
    const latestAsst = findLastAssistantLogIdxForHeartVoicePanel(log, surface);
    if (chatTheaterBrowseAssistantLogIdx < 0 || wi === latestAsst) {
      chatTheaterBrowseAssistantLogIdx = -1;
    }
  }
  syncChatInnerVoicePanelFromLog();
  syncChatTheaterPanelFromLog();
}

function writeTheaterSnapErrorToAssistant(log, pi, anchorAt, presetIds, errMsg) {
  const arr = Array.isArray(log) ? log : [];
  let target = resolveTheaterSnapWriteTarget(arr, pi, anchorAt);
  if (!target) {
    const idx = Math.floor(Number(pi));
    if (idx >= 0 && idx < arr.length && arr[idx]?.role === "assistant") {
      target = { idx, msg: arr[idx] };
    }
  }
  if (!target) return false;
  const m = target.msg;
  if (!m.theaterSnaps || typeof m.theaterSnaps !== "object") m.theaterSnaps = {};
  const msg = String(errMsg || "未知错误").slice(0, 200);
  for (const pid of presetIds) {
    const preset = getTheaterPresetById(pid);
    m.theaterSnaps[pid] = { kind: preset?.kind === "html" ? "html" : "text", error: msg, at: Date.now() };
  }
  return true;
}

/** 小剧场异步生成开始前写入 pending，便于面板显示「生成中」。 */
function markTheaterSnapsPendingOnAssistant(maskId, threadId, pi, presetIds, anchorAt) {
  const log = readChatLogForMaskThread(maskId, threadId);
  const target = resolveTheaterSnapWriteTarget(log, pi, anchorAt);
  if (!target) return false;
  const m = target.msg;
  if (!m.theaterSnaps || typeof m.theaterSnaps !== "object") m.theaterSnaps = {};
  const at = Date.now();
  for (const pid of presetIds) {
    const preset = getTheaterPresetById(pid);
    m.theaterSnaps[pid] = {
      kind: preset?.kind === "html" ? "html" : "text",
      pending: true,
      at
    };
  }
  saveChatLogForMaskThread(maskId, threadId, log);
  refreshChatTheaterUiAfterSnapWrite(maskId, threadId, target.idx);
  return true;
}

/**
 * @param {string} maskId
 * @param {string} threadId
 * @param {number} msgIdx
 * @param {string[]} [presetIds]
 * @param {{ force?: boolean }} [opts]
 */
async function runTheaterSnapBundleGeneration(maskId, threadId, msgIdx, presetIds, opts) {
  const mid = String(maskId || "").trim();
  const tid = String(threadId || "").trim();
  const pi = Math.floor(Number(msgIdx));
  const thread = findChatThreadInInbox(mid, tid)?.thread ?? null;
  const enabled = getThreadTheaterEnabledPresetIds(thread);
  let ids = Array.isArray(presetIds) && presetIds.length ? presetIds : enabled;
  ids = normalizeTheaterEnabledPresetIds(ids.filter((id) => enabled.includes(id)), { allowEmpty: true });
  if (!mid || !tid || !Number.isFinite(pi) || pi < 0 || !ids.length) return false;
  const inflightKey = theaterBundleInflightKey(mid, tid, pi, ids);
  if (theaterGenInflight.has(inflightKey)) return theaterGenInflight.get(inflightKey);
  const job = (async () => {
    if (!thread || !isThreadTheaterEnabled(thread)) return false;
    const log0 = readChatLogForMaskThread(mid, tid);
    const m0 = log0[pi];
    if (!m0 || m0.role !== "assistant" || isAssistantTypingPlaceholder(m0)) return false;
    if (!opts?.force) {
      const missing = ids.filter((pid) => {
        const snap = theaterSnapFromAssistantMessage(m0, pid);
        return !theaterSnapHasRenderableContent(snap);
      });
      if (!missing.length) return true;
      ids = missing;
    }
    if (opts?.force) {
      chatTheaterRerolling = true;
      syncChatTheaterPanelFromLog();
    }
    const ai = window.RP_AI;
    if (!ai?.chatCompletions) {
      if (opts?.force) {
        chatTheaterRerolling = false;
        syncChatTheaterPanelFromLog();
      }
      const log = readChatLogForMaskThread(mid, tid);
      const m = log[pi];
      if (m) {
        if (!m.theaterSnaps || typeof m.theaterSnaps !== "object") m.theaterSnaps = {};
        for (const pid of ids) {
          const preset = getTheaterPresetById(pid);
          m.theaterSnaps[pid] = { kind: preset?.kind === "html" ? "html" : "text", error: "API 未配置", at: Date.now() };
        }
        saveChatLogForMaskThread(mid, tid, log);
      }
      refreshChatTheaterUiAfterSnapWrite(mid, tid, pi);
      return false;
    }
    const presets = ids.map((id) => getTheaterPresetById(id)).filter(Boolean);
    if (!presets.length) return false;
    markTheaterSnapsPendingOnAssistant(mid, tid, pi, ids, m0.at);
    try {
      const messages = await buildTheaterSeparateGenMessagesAsync(mid, tid, pi, ids);
      if (!messages.length) throw new Error("缺少生成上下文");
      const cc = ai.getTheaterCompletionConfig?.() || ai.getConfig();
      const data = await ai.chatCompletions(
        {
          messages,
          max_tokens: 12000,
          response_format: { type: "json_object" }
        },
        { completionConfig: cc }
      );
      const raw = readChatCompletionChoiceText(data);
      if (!String(raw || "").trim()) {
        throw new Error(explainModelEmptyReply(data, raw));
      }
      const parsed = parseTheaterBundleResponse(raw, ids);
      const log = readChatLogForMaskThread(mid, tid);
      const target = resolveTheaterSnapWriteTarget(log, pi, m0.at);
      if (!target) throw new Error("写回小剧场失败（消息锚点丢失）");
      const m = target.msg;
      if (!m.theaterSnaps || typeof m.theaterSnaps !== "object") m.theaterSnaps = {};
      for (const pid of ids) {
        const row = parsed[pid];
        const preset = getTheaterPresetById(pid);
        if (!row || !preset) {
          m.theaterSnaps[pid] = {
            kind: preset?.kind === "html" ? "html" : "text",
            error: "模型未返回该项",
            at: Date.now()
          };
          continue;
        }
        if (row.kind === "html") {
          m.theaterSnaps[pid] = { kind: "html", html: row.html || "", at: Date.now() };
        } else {
          m.theaterSnaps[pid] = { kind: "text", text: row.text || "", at: Date.now() };
        }
      }
      saveChatLogForMaskThread(mid, tid, log);
      refreshChatTheaterUiAfterSnapWrite(mid, tid, target.idx);
      return true;
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      const log = readChatLogForMaskThread(mid, tid);
      if (writeTheaterSnapErrorToAssistant(log, pi, m0.at, ids, msg)) {
        saveChatLogForMaskThread(mid, tid, log);
        refreshChatTheaterUiAfterSnapWrite(mid, tid, pi);
      }
      return false;
    } finally {
      if (opts?.force) chatTheaterRerolling = false;
      const ref = readChatActiveThreadRef();
      if (ref.maskId === mid && ref.threadId === tid) {
        syncChatInnerVoicePanelFromLog();
        syncChatTheaterPanelFromLog();
      }
    }
  })();
  theaterGenInflight.set(inflightKey, job);
  try {
    return await job;
  } finally {
    theaterGenInflight.delete(inflightKey);
  }
}

/**
 * @param {unknown[]} logArr
 * @param {{ maskId: string, threadId: string }} [threadRef]
 * @param {number} [msgIdx]
 * @param {"im"|"offline"} [dmSurface]
 */
function kickoffTheaterSnapGen(logArr, threadRef, msgIdx, dmSurface) {
  const ref =
    threadRef && String(threadRef.maskId || "").trim() && String(threadRef.threadId || "").trim()
      ? { maskId: String(threadRef.maskId).trim(), threadId: String(threadRef.threadId).trim() }
      : readChatActiveThreadRef();
  const thread = findChatThreadInInbox(ref.maskId, ref.threadId)?.thread ?? null;
  if (!thread || !isThreadTheaterEnabled(thread)) return;
  if (isTheaterMergedWithChat()) return;
  const presetIds = getThreadTheaterEnabledPresetIds(thread);
  if (!presetIds.length) return;
  const arr = Array.isArray(logArr) ? logArr : readChatLogForMaskThread(ref.maskId, ref.threadId);
  const surface =
    dmSurface === "offline" ? "offline" : dmSurface === "im" ? "im" : getActiveChatDmSurfaceForContext();
  let idx = msgIdx;
  if (idx == null || !Number.isFinite(Number(idx))) {
    idx = findLastAssistantLogIdxForHeartVoicePanel(arr, surface);
  }
  if (idx == null || !Number.isFinite(Number(idx)) || Number(idx) < 0) return;
  if (!shouldRunTheaterByPromptMinGap(thread, arr)) return;
  const m = arr[Math.floor(Number(idx))];
  if (!m || m.role !== "assistant" || isAssistantTypingPlaceholder(m)) return;
  const missing = presetIds.filter((pid) => {
    const snap = theaterSnapFromAssistantMessage(m, pid);
    return !theaterSnapHasRenderableContent(snap);
  });
  if (!missing.length) return;
  void runTheaterSnapBundleGeneration(ref.maskId, ref.threadId, Math.floor(Number(idx)), missing);
}

/** 每轮对方主回复后尝试会话生图（默认关；仅 `chatThreadImageEveryRound === true` 为开；仍须全局启用生图且已填 Key）。 */
function isThreadChatEveryRoundSessionImage(thread) {
  return Boolean(thread && thread.chatThreadImageEveryRound === true);
}

/** 仅描述、无真实像素时是否调用生图 API（默认开；`chatThreadDescImageApiGen === false` 为关）。 */
function isThreadDescImageApiGenEnabled(thread) {
  if (!thread) return false;
  return thread.chatThreadDescImageApiGen !== false;
}

/** 每轮线下（晤面）对方回复后自动根据剧情生图（默认关；仅 `chatThreadOfflineImageEveryRound === true` 为开；仍须全局生图已接入）。 */
function isThreadOfflineEveryRoundSessionImage(thread) {
  return Boolean(thread && thread.chatThreadOfflineImageEveryRound === true);
}

/** 旁白模式：仅 `narratorModeEnabled === true` 为开（默认关）。 */
function isThreadNarratorModeEnabled(thread) {
  return Boolean(thread && thread.narratorModeEnabled === true);
}

/** @returns {"light" | "normal" | "rich"} */
function getThreadNarratorDensity(thread) {
  const d = String(thread?.narratorDensity || "").trim();
  if (d === "light" || d === "rich") return d;
  return "normal";
}

/** 旁白中是否允许 *斜体* 内心（默认开）。 */
function isThreadNarratorIncludeInner(thread) {
  if (!thread || typeof thread !== "object") return true;
  return thread.narratorIncludeInner !== false;
}

function getThreadNarratorFontPx(thread) {
  const n = Number(thread?.narratorFontPx);
  if (Number.isFinite(n) && n >= 12 && n <= 20) return Math.round(n);
  return 14;
}

/** 线上 IM 主回复 max_tokens 上限（单次请求给足，避免 finish_reason=length 后再打 API）。 */
const IM_ASSISTANT_COMPLETION_MAX_CAP = 8192;

/** 线上 IM completion max_tokens（旁白模式另加预算）。 */
function imAssistantPrimaryMaxTokens(transOn, thread) {
  const base = transOn ? 6144 : 4096;
  if (!isThreadNarratorModeEnabled(thread)) {
    return Math.min(IM_ASSISTANT_COMPLETION_MAX_CAP, base);
  }
  const extra = { light: 384, rich: 768 }[getThreadNarratorDensity(thread)] ?? 512;
  return Math.min(IM_ASSISTANT_COMPLETION_MAX_CAP, base + extra);
}

/** @param {unknown} raw @returns {{ displayName: string, persona: string, avatar: string, worldBookVolumeIds: string[] } | null} */
function normalizeAltPersona(raw) {
  if (!raw || typeof raw !== "object") return null;
  const displayName = String(raw.displayName || "").trim();
  const persona = String(raw.persona || raw.summary || "").trim();
  const avatar = String(raw.avatar || "").trim();
  const wbRaw = raw.worldBookVolumeIds;
  let worldBookVolumeIds = [];
  if (Array.isArray(wbRaw)) {
    worldBookVolumeIds = wbRaw.map((x) => String(x || "").trim()).filter(Boolean).slice(0, 8);
  }
  if (!displayName && !persona && !avatar && !worldBookVolumeIds.length) return null;
  return { displayName, persona, avatar, worldBookVolumeIds };
}

/** @param {unknown} charItem */
function charHasAltPersona(charItem) {
  if (!charItem || typeof charItem !== "object") return false;
  if (charItem.altPersonaEnabled === false) return false;
  if (charItem.altPersonaEnabled !== true) return false;
  return Boolean(normalizeAltPersona(charItem.altPersona));
}

/** @param {unknown} thread @returns {"main" | "alt"} */
function getThreadActivePersona(thread) {
  if (!thread || typeof thread !== "object" || thread.kind === "group") return "main";
  const charItem = getCharPersonaItemById(thread.charId);
  if (!charHasAltPersona(charItem)) return "main";
  return String(thread.activePersona || "").trim() === "alt" ? "alt" : "main";
}

/** @param {unknown} m @returns {"main" | "alt"} */
function getMessageSpeakerPersona(m) {
  if (!m || typeof m !== "object" || m.role !== "assistant") return "main";
  return String(m.speakerPersona || "").trim() === "alt" ? "alt" : "main";
}

/** 空内容的 assistant 占位（正在输入 / 重回中），不参与马甲切换条判定。 */
function isAssistantTypingPlaceholder(m) {
  return Boolean(
    m &&
      typeof m === "object" &&
      m.role === "assistant" &&
      m.restoring &&
      !String(m.content ?? "").trim()
  );
}

/** 写入 assistant 条目的当前密谈马甲标记（占位气泡与正式回复共用）。 */
function tagAssistantEntrySpeakerPersona(entry, thread) {
  if (!entry || typeof entry !== "object" || entry.role !== "assistant") return;
  const th = thread && typeof thread === "object" ? thread : readActiveThread();
  const charItem = th?.charId ? getCharPersonaItemById(th.charId) : null;
  if (charHasAltPersona(charItem) && getThreadActivePersona(th) === "alt") entry.speakerPersona = "alt";
  else delete entry.speakerPersona;
}

/** @param {unknown} charItem @param {"main" | "alt"} persona */
function resolvePersonaDisplayName(charItem, persona) {
  if (!charItem || typeof charItem !== "object") return "角色";
  if (persona === "alt") {
    const alt = normalizeAltPersona(charItem.altPersona);
    return (alt?.displayName && String(alt.displayName).trim()) || "马甲";
  }
  return (charItem.displayName && String(charItem.displayName).trim()) || "未命名角色";
}

/** @param {unknown} charItem @param {"main" | "alt"} persona */
function resolvePersonaAvatar(charItem, persona) {
  if (!charItem || typeof charItem !== "object") return "";
  if (persona === "alt") {
    const alt = normalizeAltPersona(charItem.altPersona);
    return alt?.avatar ? String(alt.avatar).trim() : "";
  }
  return charItem.avatar ? String(charItem.avatar).trim() : "";
}

/** @param {unknown} thread @param {"main" | "alt"} personaSlot */
function resolveCharPersonaForThreadSlot(thread, personaSlot) {
  const id = thread && typeof thread === "object" && thread.kind !== "group" ? String(thread.charId || "").trim() : "";
  if (!id) return { ...emptyCharPersona() };
  const charItem = getCharPersonaItemById(id);
  if (!charItem) return { ...emptyCharPersona() };
  const base = { ...emptyCharPersona(), ...pickCharPersonaBody(charItem) };
  if (personaSlot !== "alt") return base;
  const alt = normalizeAltPersona(charItem.altPersona);
  if (!alt) return base;
  return {
    ...base,
    displayName: alt.displayName || base.displayName,
    avatar: alt.avatar || base.avatar,
    summary: alt.persona || base.summary
  };
}

/** @param {unknown} m @returns {"main" | "alt"} */
function getMomentPostPersonaSlot(m) {
  if (!m || typeof m !== "object" || m.kind !== "char") return "main";
  return String(m.postPersona || "").trim() === "alt" ? "alt" : "main";
}

/**
 * 朋友圈用：按密谈当前大小号解析展示与 prompt 人设。
 * @param {string} maskId
 * @param {string} charId
 * @param {string} [preferredThreadId]
 * @param {"main"|"alt"|""} [personaOverride]
 */
function resolveMomentsCharIdentity(maskId, charId, preferredThreadId = "", personaOverride = "") {
  const cid = String(charId || "").trim();
  const th = pickThreadForCharMoment(maskId, cid, preferredThreadId);
  const charItem = getCharPersonaItemById(cid);
  let slot = /** @type {"main"|"alt"} */ ("main");
  const ov = String(personaOverride || "").trim();
  if (ov === "alt" || ov === "main") slot = ov;
  else slot = getThreadActivePersona(th);
  const persona = resolveCharPersonaForThreadSlot(th || (cid ? { charId: cid } : null), slot);
  const displayName =
    String(persona.displayName || "").trim() ||
    resolvePersonaDisplayName(charItem, slot) ||
    "角色";
  const avatar = resolvePersonaAvatar(charItem, slot) || String(persona.avatar || "").trim();
  return { th, charItem, slot, persona, displayName, avatar };
}

/** 主控面具展示名（发圈/评论 prompt 用 round 的 maskId，避免与当前选中面具不一致）。 */
function resolveUserMaskDisplayLabelForInbox(maskId) {
  const st = readUserMaskStore();
  const mid = String(maskId || getActiveMaskIdForInbox() || "").trim();
  let it = mid ? st.items.find((x) => String(x.id || "") === mid) : null;
  if (!it && st.activeId) it = st.items.find((x) => String(x.id || "") === st.activeId);
  const nm = it && String(it.displayName || "").trim();
  return nm || "主控";
}

/** @param {unknown} o */
function parseAssistantSpeakAsFromJson(o) {
  if (!o || typeof o !== "object") return "";
  const v = String(o.speakAs ?? o.personaSwitch ?? "")
    .trim()
    .toLowerCase();
  if (v === "alt" || v === "马甲" || v === "vest" || v === "secondary" || v === "alias") return "alt";
  if (v === "main" || v === "primary" || v === "大号" || v === "default") return "main";
  return "";
}

/** @param {string} rawReply @returns {"main" | "alt" | ""} */
function parseAssistantSpeakAsFromRaw(rawReply) {
  const t = stripUtf8Bom(String(rawReply ?? "")).trim();
  const slice = sliceFirstBalancedJsonObject(normalizeAssistantModelJsonText(t));
  if (!slice) return "";
  try {
    return parseAssistantSpeakAsFromJson(JSON.parse(slice));
  } catch {
    return "";
  }
}

/** @param {unknown} thread */
function isThreadPersonaFoldOtherEnabled(thread) {
  if (!thread || typeof thread !== "object") return true;
  return thread.personaFoldOtherEnabled !== false;
}

/** @type {Set<string>} */
const chatPersonaFoldExpandedKeys = new Set();

function chatPersonaFoldExpandKey(maskId, threadId, startRealIdx) {
  return `${String(maskId || "").trim()}\t${String(threadId || "").trim()}\t${Math.floor(Number(startRealIdx) || 0)}`;
}

/** 写入 assistant 条目的 speakerPersona，并按 speakAs 更新密谈 activePersona。 @returns {{ replyPersona: "main"|"alt", foldBoundarySlot: ""|"main"|"alt" }} */
function applyAssistantSpeakAsRound(firstParsed, entry, maskId, threadId) {
  const speakAsFromReply =
    firstParsed && typeof firstParsed === "object"
      ? String(firstParsed.speakAs || parseAssistantSpeakAsFromJson(firstParsed) || "").trim()
      : "";
  const mid = String(maskId || "").trim();
  const tid = String(threadId || "").trim();
  const thCtx = resolveChatPromptThread({ boundMaskId: mid, boundThreadId: tid });
  let replyPersona = getThreadActivePersona(thCtx);
  let foldBoundarySlot = "";
  if (speakAsFromReply === "alt" || speakAsFromReply === "main") {
    const prevActive = getThreadActivePersona(thCtx);
    replyPersona = speakAsFromReply;
    if (mid && tid) {
      patchChatThreadForMask(mid, tid, (t) => {
        if (speakAsFromReply === "alt") t.activePersona = "alt";
        else delete t.activePersona;
      });
    }
    if (prevActive !== replyPersona) {
      foldBoundarySlot = replyPersona;
      clearPersonaFoldExpandedForThread(mid, tid);
    }
    const curRef = readChatActiveThreadRef();
    if (String(curRef.maskId || "").trim() === mid && String(curRef.threadId || "").trim() === tid) {
      syncChatMorePersonaItems();
      updateChatChrome();
    }
  }
  const thRound = resolveChatPromptThread({ boundMaskId: mid, boundThreadId: tid });
  const charItemRound = thRound?.charId ? getCharPersonaItemById(thRound.charId) : null;
  if (charHasAltPersona(charItemRound) && replyPersona === "alt") entry.speakerPersona = "alt";
  else if (entry && typeof entry === "object") delete entry.speakerPersona;
  return { replyPersona, foldBoundarySlot };
}

function clearPersonaFoldExpandedForThread(maskId, threadId) {
  const prefix = `${String(maskId || "").trim()}\t${String(threadId || "").trim()}\t`;
  if (!prefix.trim()) return;
  for (const key of [...chatPersonaFoldExpandedKeys]) {
    if (key.startsWith(prefix)) chatPersonaFoldExpandedKeys.delete(key);
  }
}

/** 主控 outgoing user：写入发送时所在马甲段，供折叠一一对应（大号/马甲均显式标记，避免切号后仍归入旧段被折叠）。 */
function tagOutgoingUserMessagePersonaEpoch(entry, thread) {
  if (!entry || typeof entry !== "object" || entry.role !== "user") return;
  const th = thread && typeof thread === "object" ? thread : readActiveThread();
  const charItem = th?.charId ? getCharPersonaItemById(th.charId) : null;
  if (!charHasAltPersona(charItem)) {
    delete entry.personaEpoch;
    return;
  }
  entry.personaEpoch = getThreadActivePersona(th) === "alt" ? "alt" : "main";
}

/** @param {{ realIdx: number, m: object }[]} entries @returns {Map<number, "main"|"alt">} */
function computePersonaEraByRenderIndex(entries) {
  /** @type {Map<number, "main"|"alt">} */
  const eraByJ = new Map();
  /** @type {"main"|"alt"} */
  let era = "main";
  for (let j = 0; j < entries.length; j++) {
    const m = entries[j]?.m;
    if (!m || typeof m !== "object") continue;
    if (isPersonaFoldBoundaryMessage(m)) {
      era = String(m.personaFoldBoundary) === "alt" ? "alt" : "main";
      continue;
    }
    if (m.role !== "user" && m.role !== "assistant") continue;
    if (m.role === "assistant" && isAssistantTypingPlaceholder(m)) {
      eraByJ.set(j, era);
      continue;
    }
    if (m.role === "user") {
      const pe = String(m.personaEpoch || "").trim();
      if (pe === "alt") era = "alt";
      else era = "main";
      eraByJ.set(j, era);
      continue;
    }
    era = getMessageSpeakerPersona(m);
    eraByJ.set(j, era);
  }
  return eraByJ;
}

/** 更多面板：大号 / 马甲切换（仅当前密谈绑定的角色已启用马甲时显示）。 */
function syncChatMorePersonaItems() {
  const th = readActiveThread();
  const charItem = th?.charId ? getCharPersonaItemById(th.charId) : null;
  const show = Boolean(th && th.kind !== "group" && charHasAltPersona(charItem));
  if (th && th.kind !== "group" && String(th.activePersona || "").trim() === "alt" && !show) {
    patchActiveThread((t) => {
      delete t.activePersona;
    });
  }
  const wrap = document.getElementById("chat-more-persona-wrap");
  const mainBtn = document.getElementById("chat-more-persona-main");
  const altBtn = document.getElementById("chat-more-persona-alt");
  const mainLab = document.getElementById("chat-more-persona-main-label");
  const altLab = document.getElementById("chat-more-persona-alt-label");
  if (wrap) {
    wrap.hidden = !show;
    wrap.style.display = show ? "" : "none";
    wrap.setAttribute("aria-hidden", show ? "false" : "true");
  }
  for (const el of [mainBtn, altBtn]) {
    if (!el) continue;
    el.hidden = !show;
    el.style.display = show ? "" : "none";
    el.setAttribute("aria-hidden", show ? "false" : "true");
    el.classList.remove("is-active");
  }
  if (!show) {
    if (mainLab) mainLab.textContent = "大号";
    if (altLab) altLab.textContent = "马甲";
    return;
  }
  const active = getThreadActivePersona(th);
  const mainNm = resolvePersonaDisplayName(charItem, "main");
  const altNm = resolvePersonaDisplayName(charItem, "alt");
  if (mainLab) mainLab.textContent = mainNm;
  if (altLab) altLab.textContent = altNm;
  if (mainBtn) {
    mainBtn.classList.toggle("is-active", active === "main");
    mainBtn.setAttribute("aria-label", `以 ${mainNm} 身份发言${active === "main" ? "（当前）" : ""}`);
  }
  if (altBtn) {
    altBtn.classList.toggle("is-active", active === "alt");
    altBtn.setAttribute("aria-label", `以 ${altNm} 身份发言${active === "alt" ? "（当前）" : ""}`);
  }
}

/** 手动切换马甲/大号时写入分界（不入气泡，仅用于折叠分段）。 */
function isPersonaFoldBoundaryMessage(m) {
  if (!m || typeof m !== "object" || m.role !== "system") return false;
  const b = String(m.personaFoldBoundary || "").trim();
  return b === "alt" || b === "main";
}

/** @param {string} maskId @param {string} threadId @param {"main" | "alt"} slot */
function makePersonaFoldBoundaryRow(slot) {
  return { role: "system", personaFoldBoundary: slot, content: "", at: Date.now() };
}

/** @param {object[]} logArr @param {"main" | "alt"} slot */
function pushPersonaFoldBoundaryIfNeeded(logArr, slot) {
  if (slot !== "main" && slot !== "alt" || !Array.isArray(logArr)) return;
  const last = logArr.length ? logArr[logArr.length - 1] : null;
  if (last && isPersonaFoldBoundaryMessage(last) && String(last.personaFoldBoundary) === slot) return;
  logArr.push(makePersonaFoldBoundaryRow(slot));
}

/** @param {string} maskId @param {string} threadId @param {"main" | "alt"} slot */
function appendPersonaFoldBoundaryToLog(maskId, threadId, slot) {
  const mid = String(maskId || "").trim();
  const tid = String(threadId || "").trim();
  if (!mid || !tid || (slot !== "main" && slot !== "alt")) return;
  const log = readChatLogForMaskThread(mid, tid);
  pushPersonaFoldBoundaryIfNeeded(log, slot);
  saveChatLogForMaskThread(mid, tid, log);
}

function setThreadActivePersonaForChat(slot) {
  const th = readActiveThread();
  if (!th || th.kind === "group") return;
  if (slot !== "main" && slot !== "alt") return;
  const charItem = getCharPersonaItemById(th.charId);
  if (!charHasAltPersona(charItem)) return;
  const prev = getThreadActivePersona(th);
  if (prev === slot) return;
  const ref = readChatActiveThreadRef();
  patchActiveThread((t) => {
    if (slot === "alt") t.activePersona = "alt";
    else delete t.activePersona;
  });
  appendPersonaFoldBoundaryToLog(ref.maskId, ref.threadId, slot);
  clearPersonaFoldExpandedForThread(ref.maskId, ref.threadId);
  syncChatMorePersonaItems();
  updateChatChrome();
  chatSuppressNextChatMessageAnimations = true;
  renderChatMessages();
  showToast(
    slot === "alt"
      ? `已切为 · ${resolvePersonaDisplayName(charItem, "alt")}`
      : `已切回 · ${resolvePersonaDisplayName(charItem, "main")}`
  );
}

/**
 * 按「当前身份 / 另一身份」一一对应折叠：与当前 activePersona 不同的整段（含 user + assistant）收起。
 * @param {{ realIdx: number, m: object }[]} entries
 * @param {"main" | "alt"} activeSp
 */
function buildInactivePersonaFoldWindows(entries, activeSp) {
  /** @type {Map<number, { startJ: number, endJ: number, foldAtJ: number, persona: "main" | "alt", count: number, startRealIdx: number }>} */
  const map = new Map();
  const L = entries.length;
  if (!L) return map;
  const eraByJ = computePersonaEraByRenderIndex(entries);

  let blockStart = -1;
  /** @type {"main"|"alt"|null} */
  let blockPersona = null;

  const closeBlock = (endJ) => {
    if (blockStart < 0 || endJ < blockStart || !blockPersona || blockPersona === activeSp) {
      blockStart = -1;
      blockPersona = null;
      return;
    }
    let count = 0;
    for (let j = blockStart; j <= endJ; j++) {
      const m = entries[j]?.m;
      if (!m || isPersonaFoldBoundaryMessage(m)) continue;
      if (m.role === "user" || m.role === "assistant") count++;
    }
    if (count < 1) {
      blockStart = -1;
      blockPersona = null;
      return;
    }
    map.set(endJ + 1, {
      startJ: blockStart,
      endJ,
      foldAtJ: endJ + 1,
      persona: blockPersona,
      count,
      startRealIdx: entries[blockStart].realIdx
    });
    blockStart = -1;
    blockPersona = null;
  };

  for (let j = 0; j < L; j++) {
    const m = entries[j]?.m;
    if (isPersonaFoldBoundaryMessage(m)) {
      if (blockStart >= 0) closeBlock(j - 1);
      continue;
    }
    const era = eraByJ.get(j);
    if (!era) continue;
    if (era === activeSp) {
      if (blockStart >= 0) closeBlock(j - 1);
      continue;
    }
    if (blockStart < 0) {
      blockStart = j;
      blockPersona = era;
    } else if (era !== blockPersona) {
      closeBlock(j - 1);
      blockStart = j;
      blockPersona = era;
    }
  }
  if (blockStart >= 0) closeBlock(L - 1);
  return map;
}

/** @param {ReturnType<typeof buildInactivePersonaFoldWindows>} windows @param {number} j */
function inactivePersonaFoldContentAt(windows, j) {
  if (!windows) return null;
  for (const w of windows.values()) {
    if (j >= w.startJ && j <= w.endJ) return w;
  }
  return null;
}

/** @param {ReturnType<typeof buildInactivePersonaFoldWindows>} windows @param {number} j */
function inactivePersonaFoldBoundaryAt(windows, j) {
  if (!windows) return null;
  for (const w of windows.values()) {
    if (w.foldAtJ === j) return w;
  }
  return null;
}

/** @param {unknown} raw @param {unknown} [legacySingleId] @returns {string[]} */
function normalizeWorldBookVolumeIdsArray(raw, legacySingleId) {
  if (Array.isArray(raw)) {
    const ids = raw.map((x) => String(x || "").trim()).filter(Boolean).slice(0, 8);
    if (ids.length) return ids;
  }
  const leg = String(legacySingleId || "").trim();
  return leg ? [leg] : [];
}

/** @param {unknown} charItem */
function getCharMainWorldBookVolumeIds(charItem) {
  if (!charItem || typeof charItem !== "object") return [];
  return normalizeWorldBookVolumeIdsArray(charItem.worldBookVolumeIds, charItem.defaultWorldBookVolumeId);
}

/** @type {string[]} */
let charAltWbDraftIds = [];
/** @type {string[]} */
let charMainWbDraftIds = [];

function setCharAltWorldBookDraftIds(ids) {
  charAltWbDraftIds = normalizeWorldBookVolumeIdsArray(ids);
}

function readCharAltWorldBookDraftIds() {
  return charAltWbDraftIds.slice();
}

function setCharMainWorldBookDraftIds(ids) {
  charMainWbDraftIds = normalizeWorldBookVolumeIdsArray(ids);
}

function readCharMainWorldBookDraftIds() {
  return charMainWbDraftIds.slice();
}

/**
 * @param {{ pickedElId: string, pickerElId: string, summaryElId: string, emptyElId: string, getBound: () => string[], setBound: (ids: string[]) => void, summarySuffix?: string, boundLabel?: string }} cfg
 */
function refreshCharWorldBookBindChipsUi(cfg) {
  const pickedBox = document.getElementById(cfg.pickedElId);
  const pickerBox = document.getElementById(cfg.pickerElId);
  const summaryEl = document.getElementById(cfg.summaryElId);
  const emptyEl = document.getElementById(cfg.emptyElId);
  if (!pickedBox || !pickerBox) return;
  const bound = cfg.getBound();
  const store = readWorldBookStore();
  const vols = Array.isArray(store.volumes) ? store.volumes : [];
  const locals = vols.filter((v) => v && v.scope !== "global");
  const titleById = new Map();
  for (const v of locals) {
    const id = String(v?.id || "").trim();
    if (!id) continue;
    titleById.set(id, String(v?.title || "").trim() || "未命名");
  }
  const keys = locals.map((x) => String(x?.id || "").trim()).filter(Boolean);
  const validBound = bound.filter((c) => keys.includes(c));
  if (validBound.length !== bound.length) cfg.setBound(validBound);
  if (summaryEl) {
    const suffix = cfg.summarySuffix ? ` · ${cfg.summarySuffix}` : "";
    const label = cfg.boundLabel || "选";
    summaryEl.textContent =
      keys.length > 0
        ? `已${label} ${validBound.length} 本 · 可选局部 ${keys.length} 本 · 合计≤8${suffix}`
        : "书架暂无局部卷，请在世界书里新建并设为「局部」";
  }
  pickedBox.replaceChildren();
  for (const id of validBound) {
    const title = titleById.get(id);
    if (!title) continue;
    pickedBox.appendChild(createChatDetailWorldBookBindChip(id, title, true));
  }
  if (emptyEl) emptyEl.hidden = validBound.length > 0;
  pickerBox.replaceChildren();
  for (const v of locals) {
    const id = String(v?.id || "").trim();
    if (!id) continue;
    const title = String(v?.title || "").trim() || "未命名";
    pickerBox.appendChild(createChatDetailWorldBookBindChip(id, title, validBound.includes(id)));
  }
}

/**
 * @param {{ pickerElId: string, toggleElId: string, searchElId: string, applySearch: () => void }} cfg
 */
function setCharWorldBookBindPickerOpen(cfg, open) {
  const picker = document.getElementById(cfg.pickerElId);
  const toggle = document.getElementById(cfg.toggleElId);
  const search = document.getElementById(cfg.searchElId);
  const on = Boolean(open);
  if (picker) picker.hidden = !on;
  if (toggle) {
    toggle.setAttribute("aria-expanded", on ? "true" : "false");
    toggle.textContent = on ? "收起" : "选择世界书";
  }
  if (!on && search instanceof HTMLInputElement) {
    search.value = "";
    cfg.applySearch();
  }
}

/**
 * @param {string} chipsElId
 * @param {string} searchElId
 */
function applyCharWorldBookBindSearchFilter(chipsElId, searchElId) {
  const box = document.getElementById(chipsElId);
  const search = document.getElementById(searchElId);
  if (!box) return;
  const q = search instanceof HTMLInputElement ? String(search.value || "").trim().toLowerCase() : "";
  for (const btn of box.querySelectorAll(".chat-detail-chip")) {
    if (!(btn instanceof HTMLButtonElement)) continue;
    const title = String(btn.dataset.wbTitle || btn.textContent || "").toLowerCase();
    btn.hidden = Boolean(q && !title.includes(q));
  }
}

function setCharAltPanelOpen(open) {
  const panel = document.getElementById("char-alt-panel");
  const toggle = document.getElementById("char-alt-enabled-toggle");
  const on = Boolean(open);
  if (panel) panel.hidden = !on;
  if (toggle) {
    toggle.setAttribute("aria-pressed", on ? "true" : "false");
    toggle.setAttribute("aria-label", on ? "启用马甲：开" : "启用马甲：关");
  }
}

function renderCharAltAvatar(avatarUrl) {
  const wrap = document.getElementById("char-alt-avatar-wrap");
  const img = document.getElementById("char-alt-avatar-img");
  if (!wrap || !img) return;
  const url = avatarUrl && String(avatarUrl).trim();
  if (url) {
    img.src = url;
    img.classList.remove("is-hidden");
    wrap.classList.add("has-photo");
  } else {
    img.removeAttribute("src");
    img.classList.add("is-hidden");
    wrap.classList.remove("has-photo");
  }
}

