function toggleCharMainWorldBookBindFromChip(wbId) {
  const id = String(wbId || "").trim();
  if (!id) return;
  const cur = readCharMainWorldBookDraftIds();
  const has = cur.includes(id);
  if (!has && cur.length >= 8) {
    showToast("最多绑定 8 本局部世界书");
    return;
  }
  const next = has ? cur.filter((x) => x !== id) : [...cur, id];
  setCharMainWorldBookDraftIds(next);
  refreshCharMainWorldBookBindChips();
  setCharPaneDirty(true);
}

function toggleCharAltWorldBookBindFromChip(wbId) {
  const id = String(wbId || "").trim();
  if (!id) return;
  const cur = readCharAltWorldBookDraftIds();
  const has = cur.includes(id);
  if (!has && cur.length >= 8) {
    showToast("马甲最多绑定 8 本局部世界书");
    return;
  }
  const next = has ? cur.filter((x) => x !== id) : [...cur, id];
  setCharAltWorldBookDraftIds(next);
  refreshCharAltWorldBookBindChips();
  setCharPaneDirty(true);
}

function applyCharAltFieldsToForm() {
  const st = readCharPersonaStore();
  const it = st.items.find((x) => x.id === st.activeId);
  const alt = charHasAltPersona(it) ? normalizeAltPersona(it?.altPersona) : null;
  setCharAltPanelOpen(charHasAltPersona(it));
  const dn = document.getElementById("char-alt-display-name");
  const ps = document.getElementById("char-alt-persona");
  if (dn) dn.value = alt?.displayName ? String(alt.displayName) : "";
  if (ps) ps.value = alt?.persona ? String(alt.persona) : "";
  renderCharAltAvatar(alt?.avatar || "");
  setCharAltWorldBookDraftIds(alt?.worldBookVolumeIds || []);
  refreshCharAltWorldBookBindChips();
}

function collectAltPersonaFromForm() {
  const toggle = document.getElementById("char-alt-enabled-toggle");
  const on = toggle?.getAttribute("aria-pressed") === "true";
  if (!on) return null;
  const val = (id) => document.getElementById(id)?.value?.trim() ?? "";
  const img = document.getElementById("char-alt-avatar-img");
  const avatar =
    img && img.getAttribute("src") && !img.classList.contains("is-hidden") ? img.src : "";
  const raw = {
    displayName: val("char-alt-display-name"),
    persona: val("char-alt-persona"),
    avatar,
    worldBookVolumeIds: readCharAltWorldBookDraftIds()
  };
  return normalizeAltPersona(raw);
}

/** @param {unknown} thread @param {"main" | "alt"} personaSlot */
function getPersonaBoundWorldBookVolumeIds(thread, personaSlot) {
  /* 群聊：各成员档案世界书在 group.js buildGroupWorldBookPromptBlock 注入；此处仅本群 thread 绑定卷 */
  if (!thread || typeof thread !== "object" || thread.kind === "group") return getThreadWorldBookVolumeIds(thread);
  if (personaSlot === "alt") {
    const charItem = getCharPersonaItemById(thread.charId);
    const alt = normalizeAltPersona(charItem?.altPersona);
    if (alt?.worldBookVolumeIds?.length) return alt.worldBookVolumeIds.slice();
    return getThreadWorldBookVolumeIds(thread);
  }
  const threadIds = getThreadWorldBookVolumeIds(thread);
  if (threadIds.length) return threadIds;
  const charItem = getCharPersonaItemById(thread.charId);
  return getCharMainWorldBookVolumeIds(charItem);
}

function getThreadNarratorLineHeight(thread) {
  const n = Number(thread?.narratorLineHeight);
  if (Number.isFinite(n) && n >= 1.25 && n <= 2.1) return Math.round(n * 100) / 100;
  return 1.65;
}

/** @param {string} s */
function sliceOfflineDmCustomField(s) {
  return String(s ?? "").trim();
}

/** 主控为线下场景自定的文风（优先于旧版枚举）。 */
function getThreadOfflineDmProseStyleText(thread) {
  return sliceOfflineDmCustomField(thread?.offlineDmProseStyleText);
}

function getThreadOfflineDmLengthText(thread) {
  return sliceOfflineDmCustomField(thread?.offlineDmLengthText);
}

function getThreadOfflineDmPovText(thread) {
  return sliceOfflineDmCustomField(thread?.offlineDmPovText);
}

/** 线下当场文风：`natural` | `sparse` | `literary` | `playful`（旧数据；无自定义时使用）。 */
function getThreadOfflineDmProseStyle(thread) {
  const s = String(thread?.offlineDmProseStyle || "").trim();
  if (s === "sparse" || s === "literary" || s === "playful") return s;
  return "natural";
}

/** 线下回复篇幅：`short` | `medium` | `long` | `xlarge`（超长）。 */
function getThreadOfflineDmLength(thread) {
  const s = String(thread?.offlineDmLength || "").trim();
  if (s === "short" || s === "long" || s === "xlarge") return s;
  return "medium";
}

/** 线下 lines 硬性篇幅（仅统计 lines 正文，不含心声键）。minParagraphs = 段内 `\n\n` 节拍数，**不是** lines 数组长度。 */
const OFFLINE_DM_LENGTH_SPEC = {
  short: { minChars: 320, minParagraphs: 1 },
  medium: { minChars: 900, minParagraphs: 2 },
  long: { minChars: 1550, minParagraphs: 3 },
  xlarge: { minChars: 3200, minParagraphs: 4 }
};

/** @param {object|null} thread */
function getOfflineDmLengthSpec(thread) {
  const len = getThreadOfflineDmLength(thread);
  return OFFLINE_DM_LENGTH_SPEC[len] || OFFLINE_DM_LENGTH_SPEC.medium;
}

/** @param {string} replyJoined `|||` 拼接的 lines */
function countOfflineAssistantLinesChars(replyJoined) {
  const parts = String(replyJoined || "")
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean);
  const text = parts.join("");
  let n = 0;
  for (const ch of text) {
    if (!/\s/.test(ch)) n++;
  }
  return n;
}

/** @param {string} replyJoined lines 数组入库后 `|||` 拼接串 */
function countOfflineAssistantLinesArrayCount(replyJoined) {
  return String(replyJoined || "")
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean).length;
}

/** @param {string} replyJoined 段内空行 `\n\n` 计为小说节拍（可全在 1 个 lines 项里） */
function countOfflineAssistantProseParagraphCount(replyJoined) {
  const segs = String(replyJoined || "")
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean);
  if (!segs.length) return 0;
  let n = 0;
  for (const seg of segs) {
    const paras = seg.split(/\n{2,}/).map((p) => p.trim()).filter(Boolean);
    n += paras.length > 0 ? paras.length : 1;
  }
  return n;
}

/** @param {string} replyJoined @param {object|null} thread */
function offlineAssistantLinesMeetsLengthSpec(replyJoined, thread) {
  const spec = getOfflineDmLengthSpec(thread);
  const chars = countOfflineAssistantLinesChars(replyJoined);
  const paras = countOfflineAssistantProseParagraphCount(replyJoined);
  return chars >= spec.minChars && paras >= spec.minParagraphs;
}

/**
 * @param {string} lenKey
 * @returns {string}
 */
function buildOfflineDmLengthHardPromptText(lenKey) {
  const spec = OFFLINE_DM_LENGTH_SPEC[lenKey] || OFFLINE_DM_LENGTH_SPEC.medium;
  const suggestChars =
    lenKey === "short"
      ? "320～720"
      : lenKey === "long"
        ? "1550～3200"
        : lenKey === "xlarge"
          ? "3200～7200"
          : "900～2000";
  const suggestParas =
    lenKey === "short"
      ? "1"
      : lenKey === "long"
        ? "3～5"
        : lenKey === "xlarge"
          ? "4～8"
          : "2～4";
  return (
    `**篇幅（小说正文 · 仅统计 lines 内字，不含心声键）**：合计 **≥ ${spec.minChars} 字**（建议 ${suggestChars}）；` +
    `段内换行段落 **≥ ${spec.minParagraphs} 段**（建议 ${suggestParas} 段；用 **1 个 lines 数组项** + 项内 \`\\n\\n\` 分段，**不要**为凑段数拆成多个 array 项）。` +
    `用**互动、对白、可见小动作**加厚，**不要**用无关环境流水账、重复神态或言情八股凑字；**也不要**靠逼近、逼问、圈禁、对峙、占有空间来硬凑篇幅。输出前自检；未达标程序**最多再请求完整重写一次**。`
  );
}

/**
 * @param {object[]} apiMessages
 * @param {string} replyJoined
 * @param {object|null} thread
 */
function buildOfflineLinesLengthRepairMessages(apiMessages, replyJoined, thread) {
  const spec = getOfflineDmLengthSpec(thread);
  const chars = countOfflineAssistantLinesChars(replyJoined);
  const paras = countOfflineAssistantProseParagraphCount(replyJoined);
  const arrN = countOfflineAssistantLinesArrayCount(replyJoined);
  const userFix = [
    `[程序校验 · 线下篇幅未达标 · 本轮唯一一次补写]`,
    `你上一轮 JSON 的 **lines** 合计约 **${chars}** 字、段内换行约 **${paras}** 段（array 项数 ${arrN}）。`,
    `本密谈**硬性要求**：lines 正文 **≥ ${spec.minChars} 字**、段内换行 **≥ ${spec.minParagraphs} 段**（统计段内 \`\\n\\n\`，**不是** array 长度；**优先 1 个 array 项**写厚段）。`,
    `请**重新输出完整的一个 JSON 对象**（含 lines 与心声各键），在同一剧情上**扩写加厚**；用段内换行分节拍，**不要**拆「知道」「……」等碎项凑 array 长度。`,
    `扩写优先加**对白、具体小动作、环境一笔、日常细节**；**不要**靠逼近、逼问、圈禁、对峙、占有空间来凑字数。`,
    `这是本回合程序侧**最后一次**篇幅补写请求；请一次写足，输出前请再次自检字数与段数。`
  ].join("\n");
  return [...apiMessages, { role: "user", content: userFix }];
}

/**
 * 线下 lines 偏短时补写：固定最多 1 次额外 completion。
 * @param {object} ai
 * @param {object[]} apiMessages
 * @param {string} rawReply
 * @param {ReturnType<typeof parseChatAssistantPayload>} firstParsed
 * @param {string} replyJoined
 * @param {object|null} thread
 */
async function refineOfflineAssistantReplyIfTooShort(
  ai,
  apiMessages,
  rawReply,
  firstParsed,
  replyJoined,
  thread,
  signal
) {
  let raw = rawReply;
  let parsed = firstParsed;
  let reply = replyJoined;
  if (!String(reply || "").trim() || offlineAssistantLinesMeetsLengthSpec(reply, thread)) {
    return { rawReply: raw, firstParsed: parsed, reply };
  }
  try {
    const repairMsgs = buildOfflineLinesLengthRepairMessages(apiMessages, reply, thread);
    const fetchOpts = signal ? { signal } : undefined;
    const data = await ai.chatCompletions(
      {
        messages: repairMsgs,
        response_format: { type: "json_object" }
      },
      fetchOpts
    );
    rememberChatApiUsage(data?.usage);
    const repairRaw = readChatCompletionChoiceText(data);
    if (!repairRaw) return { rawReply: raw, firstParsed: parsed, reply };
    const strip = stripCharLockPlainProtocolBlocksFromText(repairRaw);
    const repParsed = parseAssistantPayloadForDmSurface(strip.text, "offline", repairRaw);
    const repReplyRaw = stripOfflineMeetupTagFromAssistantReply(repParsed.reply);
    const hRep = hygieneOfflineAssistantReplySegments(repReplyRaw, "");
    const repReply = hRep.reply;
    const prevChars = countOfflineAssistantLinesChars(reply);
    const nextChars = countOfflineAssistantLinesChars(repReply);
    const nextOk = offlineAssistantLinesMeetsLengthSpec(repReply, thread);
    if (String(repReply || "").trim() && (nextOk || nextChars > prevChars)) {
      raw = repairRaw;
      parsed = repParsed;
      reply = repReply;
    }
  } catch (e) {
    if (isChatAssistAbortError(e)) throw e;
    /* 保留首轮 */
  }
  return { rawReply: raw, firstParsed: parsed, reply };
}

/** 线下叙事人称：`char_first` | `mixed_narrator` | `immersive_you`（旧快捷；新存盘用 offlineDmCharPov / offlineDmUserPov）。 */
function getThreadOfflineDmPov(thread) {
  const s = String(thread?.offlineDmPov || "").trim();
  if (s === "mixed_narrator" || s === "immersive_you") return s;
  return "char_first";
}

const OFFLINE_DM_POV_PERSONS = new Set(["first", "second", "third"]);
const OFFLINE_DM_DEFAULT_CHAR_POV = /** @type {const} */ ("third");
const OFFLINE_DM_DEFAULT_USER_POV = /** @type {const} */ ("second");

/** @param {unknown} raw @param {"first"|"second"|"third"} fallback */
function normalizeOfflineDmPovPerson(raw, fallback) {
  const s = String(raw ?? "").trim();
  return OFFLINE_DM_POV_PERSONS.has(s) ? /** @type {"first"|"second"|"third"} */ (s) : fallback;
}

/**
 * 线下角色/主控叙事人称（各 first | second | third）；无新字段时从旧 offlineDmPov 迁移。
 * @param {object | null | undefined} thread
 * @returns {{ charPov: "first"|"second"|"third", userPov: "first"|"second"|"third" }}
 */
function resolveThreadOfflineDmCharUserPov(thread) {
  const charDirect = String(thread?.offlineDmCharPov || "").trim();
  const userDirect = String(thread?.offlineDmUserPov || "").trim();
  const charFromField = OFFLINE_DM_POV_PERSONS.has(charDirect)
    ? /** @type {"first"|"second"|"third"} */ (charDirect)
    : null;
  const userFromField = OFFLINE_DM_POV_PERSONS.has(userDirect)
    ? /** @type {"first"|"second"|"third"} */ (userDirect)
    : null;
  if (charFromField && userFromField) {
    return { charPov: charFromField, userPov: userFromField };
  }
  if (charFromField || userFromField) {
    return {
      charPov: charFromField || OFFLINE_DM_DEFAULT_CHAR_POV,
      userPov: userFromField || OFFLINE_DM_DEFAULT_USER_POV
    };
  }
  const legacy = getThreadOfflineDmPov(thread);
  if (legacy === "mixed_narrator") return { charPov: "third", userPov: "third" };
  if (legacy === "immersive_you") return { charPov: "first", userPov: "second" };
  if (legacy === "char_first") return { charPov: "first", userPov: OFFLINE_DM_DEFAULT_USER_POV };
  return { charPov: OFFLINE_DM_DEFAULT_CHAR_POV, userPov: OFFLINE_DM_DEFAULT_USER_POV };
}

/**
 * @param {"first"|"second"|"third"} person
 * @param {string} nameLabel 角色名或主控称呼
 */
function offlineDmPovPersonPromptClause(person, nameLabel) {
  const nm = String(nameLabel || "").trim() || "对方";
  if (person === "first") return `第一人称「我」`;
  if (person === "second") return `第二人称「你」`;
  return `第三人称「${nm}」或他/她`;
}

/** @param {string} name @param {string} userCall @param {"first"|"second"|"third"} charPov @param {"first"|"second"|"third"} userPov */
function buildOfflineDmSplitPovPromptText(name, userCall, charPov, userPov) {
  const charClause = offlineDmPovPersonPromptClause(charPov, name);
  const userClause = offlineDmPovPersonPromptClause(userPov, userCall);
  return (
    `**人称**：写「${name}」的叙事与说出口的字——${charClause}（对白在「」内，${charPov === "third" ? `引号内仍可按人设用「我」或第三人称` : `与叙事人称一致`}）。` +
    `写「${userCall}」/主控的可见动作与神态——${userClause}。` +
    `**禁止** JSON 键 \`narration\`（场面织入 lines）。**禁止**编造主控未流露的内心全知读白。`
  );
}

/**
 * 无自定义文案时，自旧版枚举生成提示（兼容存盘）。
 * @param {object|null} th
 * @param {string} name
 * @param {string} userCall
 * @returns {string[]}
 */
function buildOfflineDmProsePromptLinesFromLegacyEnums(th, name, userCall) {
  const style = getThreadOfflineDmProseStyle(th);
  const len = getThreadOfflineDmLength(th);
  const styleText =
    style === "sparse"
      ? `文风**简省**：短句、少比喻，但不牺牲场面；仍须是完整小说段落，不是电报体。`
      : style === "literary"
        ? `允许**适度文学感**（光影、通感、比喻偶尔用之），仍须像当场说得出口；禁止朗诵腔、堆砌形容词与网文八股。`
        : style === "playful"
          ? `文风**轻松**：可吐槽、玩笑、反问，须符合人设；不低俗硬杠。`
          : `文风**自然**：口语与叙事交织，像从小说里截出的一段，不刻意华丽。`;
  const lenText = buildOfflineDmLengthHardPromptText(len);
  const { charPov, userPov } = resolveThreadOfflineDmCharUserPov(th);
  const customPov = getThreadOfflineDmPovText(th);
  const povText = customPov ? "" : buildOfflineDmSplitPovPromptText(name, userCall, charPov, userPov);
  return [
    `[线下 · 小说续写（本密谈）]`,
    `本轮任务：**小说接力续写**，不是即时聊天。正文写在 JSON **\`lines\`**（**默认每轮只 1 个元素**厚段落，段内用换行分段：场面→神态→对白；勿拆成多条「拼接块」）。`,
    `[lines 结构 · 一项厚段] 晤面是**小说一段**，不是线上连发气泡。**默认 lines 数组只有 1 个字符串**；场面→动作→对白用**项内换行**（空一行）分段。程序只按 array 长度拆屏，**拆成多项会在界面顶出无关首段**——勿把「知道」「……」、单独对白、外文一句等占成 lines[0] 再另起 lines[1]。若开启对照翻译：译本**写在正文里**紧跟每个「」后，见对照翻译说明；**不要**为对照翻译拆 lines。`,
    `[记忆 · 同一段人生] 下方历史可含线上与过往当面，均为共同经历，关系与情绪须接续；**不要**在 lines 里复现表情包、红包、撤回等聊天形式。若上文是线上聊天，当面须自然承接刚才的情绪与话题。**接续≠复述**：近几轮已写清、已说出口或已收束的事，本轮**默认不再提起**；除非 user 本轮主动重提，或剧情需要一句极短照应（≤半句，不展开旧账）。`,
    `[人设] 你是「${name}」本人，不是通用旁白。口癖、称呼、冷/暖/轴只来自下方「角色设定 · 说话方式 / 摘要 / 标签 / 开场白」。先**读懂完整卡面**再反应：标签与摘要仅供内化，**禁止**写进 lines（含「XX系」「XX感」、典型/一贯/天生+性格词及卡面标签原词）。**禁止**按单一标签刻板演；**禁止**偷换通用言情/古言模板（与卡面说话方式、开场白句法不符即 OOC）。人物须有具体习惯与当下情绪；关系未到、卡面未写，别重型表白或献祭式台词。`,
    `[续写] 从 user 上一拍**之后**写起：不复读、不扩写 user 的动作或台词，直接写「${name}」的反应。每轮宜有一点**新变化**，但**变化≠升级冲突**：可沉默、短句、退半步、岔开话题、日常碎事、小意外或 NPC 一笔——**不是**每轮都要关系转折、逼近或压人。勿只做应声虫，也**勿**为「有戏」硬制造对峙。**禁止**段首开「回顾式」旁白（又想起/刚才/之前说过/还是那件事）；近几轮已交代过的事、已说过的台词与结论，**勿换说法再讲一遍**。段末落在「${name}」的**新**动作或**新**说出口的对白；禁止悬空（等你说/欲言又止/离场/睡着）。`,
    `[世界 · 旁人/NPC] 合适时可让服务员、路人或人设/世界书里熟人**短暂介入**，让世界是活的——**不是每轮都要**；介入后镜头回到你与「${userCall}」。`,
    `[对白 · 排版] 段首两个全角空格「　　」；说出口的字用「」或“”（**当场能说得出口**的口语：短、具体、带口癖；可半截、可改口）。**禁止**网文式重磅台词（命都给你、揉进/烙进骨血、刻进灵魂、生生世世、没有你活不下去、毁天灭地等），除非卡面说话方式本就这样且关系阶段合理。叙事用简体中文；禁止「旁白：」「对白：」及「声音沙哑/冰冷地说/低吼」类报幕。`,
    `[认知] user 消息：普通文字=可见动作/旁白；「」或“”=说出口的话；*…*=内心（你看不见）；括号=主控意见。按字面理解，勿阴谋论。`,
    `[写法] **展示，不说明**（标签与刻板演见 [人设]）：先写**可见**动作与第一感受，再写对白；气质只通过本轮具体的举止、表情、用词、选择、剧情体现。叙事与对白优先**短句、具体动作**；勿用网文腔长比喻堆情绪。**禁止**在 lines 里堆心理旁白（阴湿地想/暗自琢磨/某种念头涌上/眼底藏着…）；抽象心理放 heartVoice。**禁止**定义句、对比句式（「他没有A而是B」「不像…更像…」「这是一种…式的」）。**羞/烫/窘等反应**直接写红、躲、僵、喘，**勿**每轮用卡面外貌词（冷白皮、骨相、薄唇等）当段首总起或「藏不住/根本/这副躯壳」式论证。字数用互动/对白填，禁止睡觉/吃饭/无关环境凑字，禁止编造卡面未写的外貌细节；**禁止**用逼近、逼视、圈禁、扣腕、不让走、堵人去路等**占有式动作**硬凑厚度（关系与人设未到则尤其不要）。`,
    `[反八股] 避免出现：甜宠套话称呼（小管家婆、小没良心、小妖精等）、**言情献祭台词**（命都给你、揉进/烙进骨血、刻进灵魂、把心掏给你、没有你活不下去、生生世世、毁天灭地、你是我的命/光/唯一等）、**万能神态/身体**（眸色一暗、嘴角勾起、薄唇、颀长、低吼、心脏漏跳一拍、血液倒流、灭顶、溃败）、**霸道占有动作**（未到时机的逼视、圈进怀里不放、扣腕/扣下巴、堵门/不让走、一步逼一步、捏着下巴逼问等——除非卡面本就这样且关系阶段已到）、**外貌标签复读**（冷白皮/白皮/瓷白/骨相 + 藏不住/根本/这副XX的躯壳/不用照镜子我也知道；脸红就直接写红，勿再论证肤色）、**阴湿/暗黑心理腔**（阴湿地想/看着、阴郁的念头、晦暗的欲望、黏腻的视线、不受控制地想要等——无论是否来自卡面标签都**禁止写进 lines**）、定义总结（「这是…式的」「难以言说的」）、关系战说法（猎人猎物、底牌、防线崩塌）、段末升华（「爱是…」）。**前文若已有上述写法也不要因袭**；称呼用名字或人设里写定的昵称。`,
    `[用语] 正文禁止 AI/理工科腔：变量、量化、精准、轨迹、机制、运算、维度、参数等。`,
    `[心声与正文] **lines 写外在**（动作、表情、对白、当场可见反应）；**心理、欲念、脑内独白放 heartVoice**，勿在 lines 里用「阴湿地/暗自/不受控制地/难以言喻地**想**…」「某种…的念头/欲望」式心理旁白凑字。`,
    `[亲密 · 若剧情自然进入] 不必回避亲密场面，须贴合关系与人设；user 未示意勿硬推。平等、贴「${name}」性格；每轮只推进一小段；禁止「看着我」「等会别哭」等油腻占有台词。**未到关系阶段**时勿用圈禁、逼视、扣腕、堵门、一步逼近等霸道模板凑亲密感。`,
    styleText,
    lenText,
    ...(povText ? [povText] : [])
  ];
}

/** 从卡面 tags/摘要 提取易在 lines 里被反复点名的外貌锚词。 @param {unknown} char */
function extractCharAppearanceAnchorPhrases(char) {
  if (!char || typeof char !== "object") return [];
  const raw = [char.tags, char.summary].map((x) => String(x || "").trim()).filter(Boolean).join("\n");
  if (!raw) return [];
  /** @type {Set<string>} */
  const out = new Set();
  for (const m of raw.matchAll(/冷白皮|白皮|瓷白|骨相|薄唇|银发|黑发|金发|棕发|黑皮|小麦色|腹肌|喉结|choker/giu)) {
    out.add(m[0]);
  }
  const tagLine = tavernTagsToLine(char.tags);
  for (const tok of tagLine.split(/[·•,，/|\s]+/)) {
    const t = String(tok || "").trim();
    if (t.length >= 2 && t.length <= 10 && /[皮肤发色眸瞳唇相卷]/u.test(t)) out.add(t);
  }
  return [...out].slice(0, 10);
}

/**
 * 统计近几轮 assistant 正文是否含某锚词。
 * @param {unknown[]} log
 * @param {string} phrase
 * @param {{ lookbackAssistRounds?: number }} [opts]
 */
function countPhraseInRecentAssistantLog(log, phrase, opts) {
  const needle = String(phrase || "").trim();
  if (!needle) return 0;
  const cap = Math.max(1, Math.floor(Number(opts?.lookbackAssistRounds) || 6));
  const arr = Array.isArray(log) ? log : [];
  let rounds = 0;
  let hits = 0;
  for (let i = arr.length - 1; i >= 0 && rounds < cap; i--) {
    const m = arr[i];
    if (!m || typeof m !== "object" || m.role !== "assistant") continue;
    rounds++;
    const text = String(m.content || "")
      .split(/\|\|\|/)
      .join("\n");
    if (text.includes(needle)) hits++;
  }
  return hits;
}

/** @param {unknown} th @param {unknown} char @param {unknown[]} [promptLog] */
function buildOfflineCharAppearanceAntiRepeatPromptLines(th, char, promptLog) {
  void th;
  const anchors = extractCharAppearanceAnchorPhrases(char);
  const base = [
    `[外貌 · 勿当固定句式] 卡面外貌/肤质/发色等**只作背景**，不是每轮必点的「人设复读机」。写脸红、发烫、窘迫、情动时**直接写当场现象**（耳根烧、别过脸、嗓子发紧、手指发僵），**勿**每轮再申明「我的冷白皮/XX皮藏不住」「这副XX的躯壳」「不用照镜子我也知道」——**禁止**用肤色/骨相/标签当段首总起或论证句；近几轮若已写过同类描写，本轮换别的细节（动作、对白、小道具、环境）。`
  ];
  if (!anchors.length) return base;
  let log = Array.isArray(promptLog) ? promptLog : [];
  if (!log.length) {
    try {
      log = readChatLog();
    } catch (_) {
      /* ignore */
    }
  }
  /** @type {string[]} */
  const overused = [];
  for (const p of anchors) {
    if (countPhraseInRecentAssistantLog(log, p, { lookbackAssistRounds: 5 }) >= 2) overused.push(p);
  }
  for (const p of ["冷白皮", "这副", "不用照镜子", "躯壳"]) {
    if (overused.includes(p)) continue;
    if (countPhraseInRecentAssistantLog(log, p, { lookbackAssistRounds: 4 }) >= 2) overused.push(p);
  }
  if (!overused.length) return base;
  return [
    ...base,
    `[外貌 · 本轮禁复读] 近几轮 lines 已**多次**出现：${overused
      .slice(0, 6)
      .map((p) => `「${p}」`)
      .join("、")}。**本轮不要再写这些词及同义变形**（如冷白皮→白皮/瓷白/这种肤色）。羞烫窘迫只写**动作与感官**，勿再拿外貌标签当总起。`
  ];
}

/**
 * 注入系统提示：仅线下页（`sceneOffline`）使用。
 * @param {object|null} th
 * @param {string} name
 * @param {string} userCall
 * @param {unknown} [char]
 * @param {boolean} [postCheckupArc] 由 {@link buildChatSystemPrompt} 传入时可免重复读 log
 * @param {unknown[]} [promptLog] 绑定密谈 log（并行回合勿读当前界面）
 * @returns {string[]}
 */
function buildOfflineDmProsePromptLines(th, name, userCall, char, postCheckupArc, promptLog) {
  let arc = postCheckupArc === true;
  if (postCheckupArc !== true && postCheckupArc !== false) {
    try {
      const log = Array.isArray(promptLog) ? promptLog : readChatLog();
      arc = logHasRecentCheckupArcForOffline(log);
    } catch {
      arc = false;
    }
  }
  const base = [
    ...buildOfflineDmProsePromptLinesFromLegacyEnums(th, name, userCall),
    ...buildOfflineCharAppearanceAntiRepeatPromptLines(th, char, promptLog),
    ...(arc ? buildOfflinePostCheckupFormatPromptLines(name) : [])
  ];
  const ct = getThreadOfflineDmProseStyleText(th);
  const lt = getThreadOfflineDmLengthText(th);
  const pt = getThreadOfflineDmPovText(th);
  if (ct || lt || pt) {
    const extra = [
      `[线下 · 主控自定义] 下列说明可与上文快捷模板叠用；冲突时以**当下同场**与**下列说明**为准。`
    ];
    if (ct) extra.push(`**文风 / 语气**：${ct}`);
    if (lt) extra.push(`**字数、条数与节奏**：${lt}`);
    if (pt) extra.push(`**人称与叙事**：${pt}`);
    return [...base, ...extra];
  }
  return base;
}

/** 表情联想（输入框上方）：默认开；仅 `stickerSuggestEnabled === false` 为关。 */
function isThreadStickerSuggestEnabled(thread) {
  if (!thread || typeof thread !== "object") return true;
  return thread.stickerSuggestEnabled !== false;
}

/** 密谈「对照翻译」：仅 `charTranslationEnabled === true` 为开（默认关）；不补历史。 */
function isThreadCharTranslationEnabled(thread) {
  return Boolean(thread && thread.charTranslationEnabled === true);
}

/** 角色档案「常用对白语言」是否视为中文（空 = 中文）。 */
function isPersonaDialogueLangChinese(dlg) {
  const s = String(dlg || "").trim();
  if (!s) return true;
  const low = s.toLowerCase();
  if (/^(中文|汉语|普通话|国语|中国语|华语|官话)/.test(s)) return true;
  if (/mandarin|chinese|zh[-_]?cn|zh[-_]?hans|zh[-_]?hant|simplified chinese|traditional chinese/.test(low)) {
    return true;
  }
  if (/中文|汉语|普通话|官话/.test(s)) return true;
  return false;
}

/** 群聊：档案「常用对白语言」为外语的成员才需要对照翻译。 */
function isCharForeignForGroupTranslation(charId) {
  const it = getCharPersonaItemById(charId);
  const dlg = String(it?.dialogueLang || "").trim();
  return Boolean(dlg) && !isPersonaDialogueLangChinese(dlg);
}

/** 群聊「外语成员对照翻译」：仅 `groupTranslationEnabled === true` 为开（默认关）。 */
function isThreadGroupTranslationEnabled(thread) {
  return Boolean(thread && thread.groupTranslationEnabled === true);
}

function getThreadGroupTranslationTone(thread) {
  return String(thread?.groupTranslationTone || "").trim() === "literal" ? "literal" : "colloquial";
}

function getThreadGroupTranslationTargetLang(thread) {
  const s = String(thread?.groupTranslationTargetLang || "").trim();
  return s || "中文";
}

/** 群聊单条 assistant 是否展示灰字译本（开关开 + 发言人为外语成员 + 有 translation）。 */
function isGroupAssistantMessageTranslationUiOn(m, thread) {
  if (!isThreadGroupTranslationEnabled(thread)) return false;
  const cid =
    window.XXJ_GroupChat?.speakerCharIdFromMessage?.(m, thread) || String(m?.speakerCharId || "").trim();
  if (!cid || !isCharForeignForGroupTranslation(cid)) return false;
  return Boolean(String(m?.translation || "").trim());
}

/** 当前密谈/群聊是否启用对照翻译 UI（群聊走 groupTranslation，单聊走 charTranslation）。 */
function isThreadTranslationUiEnabled(thread) {
  if (isChatThreadGroupForUi(thread)) return isThreadGroupTranslationEnabled(thread);
  return isThreadCharTranslationEnabled(thread);
}

let chatOfflineSurfaceActive = false;

/** 打开晤面页时的密谈日志起始下标；关闭时写入 `offline_end` 票根后重置为 -1 */
let offlineSessionStartLogIdx = -1;
/** 本场晤面是否折叠「上一场及更早」的当面气泡（log 里已有 offline_end 时） */
let offlineFoldPriorSessions = false;
/** 是否已展开被折叠的更早当面记录 */
let offlinePriorSessionsRevealed = false;

/**
 * @param {object[]} log
 * @param {number} beforeIdx
 */
function chatLogHadEndedOfflineSessionBefore(log, beforeIdx) {
  const arr = Array.isArray(log) ? log : [];
  const lim = Math.max(0, Math.floor(Number(beforeIdx) || 0));
  for (let i = 0; i < lim; i++) {
    if (isChatNoticeOfflineEndedMessage(arr[i])) return true;
  }
  return false;
}

/**
 * @param {HTMLElement} root
 * @param {number} priorCount
 */
function appendOfflinePriorSessionsFoldButton(root, priorCount) {
  const n = Math.max(0, Math.floor(Number(priorCount) || 0));
  if (!n) return;
  const wrap = document.createElement("div");
  wrap.className = "chat-offline-session-fold-divider";
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "chat-offline-session-fold";
  btn.textContent =
    n === 1 ? "展开上一场当面记录（1 条）" : `展开上一场当面记录（${n} 条）`;
  btn.setAttribute("aria-label", `展开上一场及更早的当面记录，共 ${n} 条`);
  btn.addEventListener("click", () => {
    offlinePriorSessionsRevealed = true;
    chatSuppressNextChatMessageAnimations = true;
    renderChatMessages();
    window.requestAnimationFrame(() => {
      const se = root;
      if (!se) return;
      se.scrollTop = se.scrollHeight;
    });
  });
  wrap.appendChild(btn);
  root.appendChild(wrap);
}

/**
 * 消息过多时：在列表顶部插入或更新「展开更早」按钮。
 * @param {HTMLElement} root
 * @param {number} startIdx 当前折叠掉的条数
 * @param {"im" | "offline"} shellSurface
 */
function ensureChatHistoryOlderFoldButton(root, startIdx, shellSurface) {
  const nOlder = Math.max(0, Math.floor(Number(startIdx)) || 0);
  if (!root) return;
  const existingBtn = root.querySelector(".chat-history-fold");
  if (nOlder <= 0) {
    existingBtn?.closest(".chat-time-divider")?.remove();
    return;
  }
  const foldIsOffline = shellSurface === "offline";
  const nStep = Math.min(CHAT_RENDER_COLLAPSE_EXPAND_STEP, nOlder);
  const label =
    nStep >= nOlder
      ? foldIsOffline
        ? `本场还有较早的 ${nOlder} 条，全部展开`
        : `还有较早的 ${nOlder} 条，点击全部展开`
      : foldIsOffline
        ? `本场还有较早的 ${nOlder} 条，再展开 ${nStep} 条`
        : `还有较早的 ${nOlder} 条，点击再展开 ${nStep} 条`;
  if (existingBtn instanceof HTMLButtonElement) {
    existingBtn.textContent = label;
    existingBtn.setAttribute("aria-label", `展开更早的聊天记录，约 ${nStep} 条`);
    return;
  }
  const foldRow = document.createElement("div");
  foldRow.className = "chat-time-divider";
  const foldBtn = document.createElement("button");
  foldBtn.type = "button";
  foldBtn.className = foldIsOffline ? "chat-history-fold chat-history-fold--offline" : "chat-history-fold";
  foldBtn.textContent = label;
  foldBtn.setAttribute("aria-label", `展开更早的聊天记录，约 ${nStep} 条`);
  foldBtn.addEventListener("click", () => {
    void (async () => {
      const ref = readChatActiveThreadRef();
      const found = findChatThreadInInbox(ref.maskId, ref.threadId);
      const thFold = found?.thread;
      if (thFold?._uiLogPartial) {
        const loaded = await loadOlderChatMessagesPageForUi(ref.maskId, ref.threadId, thFold);
        if (loaded && found) {
          invalidateChatLogViewCache();
          invalidateChatUiEntriesRenderCache();
          writeChatInboxStore(found.inbox, {
            fast: true,
            dirtyThreadKey: chatDirtyThreadPersistKey(ref.maskId, ref.threadId)
          });
        }
      }
      const se = root;
      const oldH = se?.scrollHeight ?? 0;
      const oldT = se?.scrollTop ?? 0;
      const logFold = readChatLog();
      const uiSurfaceFold = getActiveChatDmSurfaceForContext() === "offline" ? "offline" : "im";
      let visForCollapse;
      if (
        getActiveChatDmSurfaceForContext() === "offline" &&
        offlineFoldPriorSessions &&
        offlineSessionStartLogIdx >= 0 &&
        !offlinePriorSessionsRevealed
      ) {
        visForCollapse = buildUiChatMessageEntries(logFold, "offline").filter(
          (e) => e.realIdx >= offlineSessionStartLogIdx
        ).length;
      } else {
        visForCollapse = scanUiChatVisibleEntriesTail(logFold, uiSurfaceFold, logFold.length).L;
      }
      chatHistoryOlderRevealCount = Math.min(
        chatHistoryOlderRevealCount + CHAT_RENDER_COLLAPSE_EXPAND_STEP,
        Math.max(0, visForCollapse - CHAT_RENDER_COLLAPSE_KEEP_LAST)
      );
      chatSuppressNextChatMessageAnimations = true;
      renderChatMessages();
      window.requestAnimationFrame(() => {
        const se2 = root;
        if (!se2) return;
        se2.scrollTop = oldT + (se2.scrollHeight - oldH);
      });
    })();
  });
  foldRow.appendChild(foldBtn);
  root.insertBefore(foldRow, root.firstChild);
}

/** 当前对话频道：API / 列表渲染用（线下开关与 latch 同步） */
function getActiveChatDmSurfaceForContext() {
  if (chatOfflineSurfaceActive) return "offline";
  const r = document.getElementById("chat-offline-screen");
  if (r && r.classList.contains("is-open")) return "offline";
  return "im";
}

/** 即时密谈才启用铃声（设为铃声、聊天内提示音等；晤面/线下关闭） */
function isChatRingtoneSurfaceActive() {
  return getActiveChatDmSurfaceForContext() === "im";
}

/**
 * 本回合密谈频道：后台主动发消息等不能读「当前界面」的线下开关，须绑定到目标线程。
 * @param {{ boundDmSurface?: "im" | "offline", boundMaskId?: string, boundThreadId?: string }} [opts]
 */
function resolveChatRoundDmSurface(opts, thread, maskId, threadId) {
  if (opts && (opts.boundDmSurface === "offline" || opts.boundDmSurface === "im")) {
    return opts.boundDmSurface;
  }
  const mid = String(maskId || "").trim();
  const tid = String(threadId || "").trim();
  const activeMid = String(getActiveMaskIdForInbox() || "").trim();
  const activeRef = readChatActiveThreadRef();
  if (
    mid &&
    tid &&
    activeMid === mid &&
    String(activeRef.threadId || "").trim() === tid &&
    getActiveChatDmSurfaceForContext() === "offline"
  ) {
    return "offline";
  }
  if (mid && tid) {
    const log = readChatLogForMaskThread(mid, tid);
    for (let i = log.length - 1; i >= 0; i--) {
      const m = log[i];
      if (!m || typeof m !== "object") continue;
      if (m.role === "user" || m.role === "assistant") return chatMessageDmSurface(m);
    }
  }
  return "im";
}

/** 仅当用户正在看该密谈时刷新聊天气泡，避免后台 A 主动发消息时污染 B 的界面状态 */
function scheduleChatUiRefreshForRound(maskId, threadId, opts) {
  if (!isUserViewingChatThread(maskId, threadId)) return;
  requestChatStickBottomNextRender();
  if (opts?.animateLatest === true) chatAnimateLatestAssistantReply = true;
  // 与 typing / 用户发送一致：始终 suppress，保留行复用并跳过 img teardown；入场动画仅加在最新一行
  chatSuppressNextChatMessageAnimations = true;
  invalidateChatLogViewCache();
  invalidateChatUiEntriesRenderCache();
  if (opts?.flush === true) {
    chatSkipLogNormalizeNextRender = true;
    renderChatMessages();
    return;
  }
  scheduleRenderChatMessages();
}

/** 线下场景：独立全屏 `#chat-offline-screen`（单聊）。 */
function isChatOfflineScreenOpen() {
  return chatOfflineSurfaceActive;
}

function moveChatDockToOfflineMount() {
  const mount = document.getElementById("chat-offline-chat-mount");
  if (!mount) return;
  for (const id of ["chat-scroll", "chat-msg-multi-bar", "chat-composer"]) {
    const n = document.getElementById(id);
    if (n) mount.appendChild(n);
  }
  reparentChatInnerVoiceShellsForActiveSurface();
  syncChatMessageWallpaperMount();
}

function moveChatDockToMainChat() {
  const main = document.querySelector("#chat-screen .chat-main");
  if (!main) return;
  const grain = main.querySelector(".chat-filmgrain");
  let ref = grain || main;
  for (const id of ["chat-scroll", "chat-msg-multi-bar", "chat-composer"]) {
    const n = document.getElementById(id);
    if (!n) continue;
    ref.after(n);
    ref = n;
  }
  reparentChatInnerVoiceShellsForActiveSurface();
  syncChatMessageWallpaperMount();
}

/**
 * 心声 / 图片预览等全屏浮层挂在当前可见的聊天壳根节点（与 .settings-inner 平级）。
 * 线上 #chat-screen、线下 #chat-offline-screen 均如此，避免浮层在 .chat-body-stack 内 absolute→fixed 牵动消息区重绘。
 */
function reparentChatInnerVoiceShellsForActiveSurface() {
  const hist = document.getElementById("chat-inner-voice-history-screen");
  const inner = document.getElementById("chat-char-inner-voice");
  const photo = document.getElementById("chat-photo-viewer");
  const offlineRoot = document.getElementById("chat-offline-screen");
  const offShell = offlineRoot?.querySelector(".settings-inner") ?? null;
  if (!hist || !inner) return;
  const scroll = document.getElementById("chat-scroll");
  const scrollInOfflineTree = Boolean(
    offlineRoot && scroll && scroll.parentElement && offlineRoot.contains(scroll)
  );
  /** 勿仅依赖 scroll 是否在树内：晤面页已打开 / latch 为线下时也应挂到线下壳，避免仍留在主 #chat-screen（visibility:hidden）里 */
  const offlineLayerActive = Boolean(
    offlineRoot &&
      (offlineRoot.classList.contains("is-open") || isChatOfflineScreenOpen() || scrollInOfflineTree)
  );
  const useOffline = Boolean(offShell && offlineLayerActive);
  if (useOffline && offlineRoot) {
    const voiceOk = hist.parentElement === offlineRoot && inner.parentElement === offlineRoot;
    const photoOk = !photo || photo.parentElement === offlineRoot;
    if (voiceOk && photoOk) return;
    offlineRoot.appendChild(inner);
    offlineRoot.appendChild(hist);
    if (photo) offlineRoot.appendChild(photo);
    return;
  }
  const chatRoot = document.getElementById("chat-screen");
  if (!chatRoot) return;
  const voiceOk = hist.parentElement === chatRoot && inner.parentElement === chatRoot;
  const photoOk = !photo || photo.parentElement === chatRoot;
  if (voiceOk && photoOk) return;
  chatRoot.appendChild(inner);
  chatRoot.appendChild(hist);
  if (photo) chatRoot.appendChild(photo);
}

/** 退出晤面页时写入「当面结束」票根（含归档摘录），便于时间线与模型承接 */
function appendOfflineSessionEndedNoticeIfNeeded() {
  const start = offlineSessionStartLogIdx;
  offlineSessionStartLogIdx = -1;
  if (start < 0) return;
  reconcileActiveThreadRef();
  if (!readChatActiveThreadRef().threadId) return;
  const log = readChatLog();
  const transcript = cloneOfflineSessionTranscriptForNoticeStorage(log, start);
  if (!transcript.length) return;
  const log2 = log.slice();
  log2.push({
    role: "notice",
    kind: "offline_end",
    at: Date.now(),
    content: "",
    offlineTranscript: transcript
  });
  saveChatLog(log2);
}

/**
 * 进入晤面时的 log 起点：点「结束」并写回密谈后下一场从末尾新开；
 * 若仅「返回」未结束，则续上一场未写入 offline_end 的当面气泡。
 * @param {unknown[]} log
 */
function resolveOfflineSessionStartLogIdx(log) {
  const arr = Array.isArray(log) ? log : [];
  let lastEndIdx = -1;
  for (let i = 0; i < arr.length; i++) {
    if (isChatNoticeOfflineEndedMessage(arr[i])) lastEndIdx = i;
  }
  for (let i = lastEndIdx + 1; i < arr.length; i++) {
    const m = arr[i];
    if (!m || typeof m !== "object") continue;
    if (m.role !== "user" && m.role !== "assistant") continue;
    if (chatMessageDmSurface(m) !== "offline") continue;
    return i;
  }
  return arr.length;
}

function openChatOfflineScreen() {
  reconcileActiveThreadRef();
  if (!readChatActiveThreadRef().threadId) {
    showToast("请先新建或从列表选择密谈");
    return;
  }
  const th = readActiveThread();
  if (th && th.kind === "group") {
    showToast("群聊请用即时消息");
    return;
  }
  if (isThreadOnlineRomanceEnabled(th)) {
    showToast("异地模式已开：请先关闭后再晤面");
    return;
  }
  if (isChatCallActive()) {
    showToast("请先结束通话");
    return;
  }
  closeMyScreen();
  closeSettings();
  closeCharScreen();
  closeWorldBookScreen();
  closeMinimaxSheet();
  closeImageGenSheet();
  closeChatDetailImageStyleSheet();
  closeCharIncomingCallSheet();
  closeChatMoreSheet();
  closeChatThreadDetailPanel({ skipFocusRestore: true });
  closeChatMemoScreen({ skipReturnToThreadDetail: true });
  closeChatBubbleActionSheet();
  clearChatMsgMultiSelectMode({ skipRender: true });
  closeChatCharInnerVoicePanel();
  closeChatCharRecallPeekPanel();
  closeChatCallTranscriptPeek();
  closeChatInnerVoiceHistoryScreen();
  closeStickerScreen();
  closeWardrobeScreen();

  closeChatOfflineProseSheet();
  closeChatOfflineWbSheet();
  closeChatOfflineMeetSummarySheet();
  chatComposerSendAsVoice = false;
  applyChatComposerVoiceModeUi();
  moveChatDockToOfflineMount();

  getChatScreenEl()?.classList.remove("is-open");
  getChatScreenEl()?.setAttribute("aria-hidden", "true");

  const root = document.getElementById("chat-offline-screen");
  if (!root) {
    moveChatDockToMainChat();
    getChatScreenEl()?.classList.add("is-open");
    getChatScreenEl()?.setAttribute("aria-hidden", "false");
    showToast("线下页不可用，已退回密谈");
    return;
  }
  document.getElementById("chat-composer")?.classList.add("chat-composer--f2f-prose");
  applyOfflineDiaryComposerChrome();
  root.classList.add("is-open");
  root.setAttribute("aria-hidden", "false");
  chatOfflineSurfaceActive = true;
  const logAtOpen = readChatLog();
  const atOpen = resolveOfflineSessionStartLogIdx(logAtOpen);
  offlineSessionStartLogIdx = atOpen;
  offlineFoldPriorSessions = chatLogHadEndedOfflineSessionBefore(logAtOpen, atOpen);
  offlinePriorSessionsRevealed = false;
  if (offlineFoldPriorSessions) {
    chatHistoryOlderRevealCount = 0;
    chatHistoryCollapseLastLogLen = 0;
  }

  updateChatChrome();
  renderChatMessages();
  applyChatOfflineWallpaperSurfaces();
  window.clearTimeout(stickerSuggestInputTimer);
  stickerSuggestInputTimer = 0;
  clearStickerSuggestBar();

  const ta = document.getElementById("chat-input");
  if (ta && ta instanceof HTMLTextAreaElement && !chatComposerSendAsVoice) {
    ta.placeholder = "在这页空白处续写…";
  }
  window.requestAnimationFrame(() => ta?.focus());
  scheduleChatProactiveTimer();
}

/**
 * @param {{ skipShowChat?: boolean, finalizeOfflineSession?: boolean }} [opts]
 * finalizeOfflineSession === false：仅返回密谈，不写 offline_end（可续上一场）。
 * 其余情况（含未传、点「结束」、切通话/切线程）均归档本场当面。
 */
function closeChatOfflineScreen(opts) {
  const shouldFinalizeOffline = opts?.finalizeOfflineSession !== false;
  if (shouldFinalizeOffline) appendOfflineSessionEndedNoticeIfNeeded();
  chatOfflineSurfaceActive = false;
  offlineFoldPriorSessions = false;
  offlinePriorSessionsRevealed = false;
  document.getElementById("chat-composer")?.classList.remove("chat-composer--f2f-prose");
  removeOfflineDiaryComposerChrome();
  closeChatOfflineProseSheet();
  closeChatOfflineWbSheet();
  const root = document.getElementById("chat-offline-screen");
  if (root) {
    root.classList.remove("is-open");
    root.setAttribute("aria-hidden", "true");
  }
  moveChatDockToMainChat();
  applyChatComposerVoiceModeUi();
  if (!opts?.skipShowChat) {
    getChatScreenEl()?.classList.add("is-open");
    getChatScreenEl()?.setAttribute("aria-hidden", "false");
    updateChatChrome();
    renderChatMessages();
    scheduleChatProactiveTimer();
    const ta = document.getElementById("chat-input");
    window.requestAnimationFrame(() => ta?.focus());
  } else {
    renderChatMessages();
  }
}

/** 密谈「时间感知」：仅 `timeAwareEnabled === true` 为开（默认关）。 */
function isThreadTimeAwareEnabled(thread) {
  return Boolean(thread && thread.timeAwareEnabled === true);
}

/** 聊天区居中时间条：仅 `chatTimestampsHidden === true` 为隐藏（默认显示）；票根分隔条不受影响。 */
function isThreadChatTimestampsHidden(thread) {
  return Boolean(thread && thread.chatTimestampsHidden === true);
}

/** 角色在用户沉默后主动发消息：仅 `charProactiveEnabled === true` 为开（默认关）。 */
function isThreadCharProactiveEnabled(thread) {
  return Boolean(thread && thread.charProactiveEnabled === true);
}

/** 角色主动反向查岗（翻用户手机）：仅 `charReverseSnoopEnabled === true` 为开（默认关）。 */
function isThreadCharReverseSnoopEnabled(thread) {
  return Boolean(thread && thread.charReverseSnoopEnabled === true);
}

/** 是否允许本密谈内角色触发锁机（仅单聊；默认关）。 */
function isThreadCharLockPhoneEnabled(thread) {
  return Boolean(thread && thread.charLockPhoneEnabled === true);
}

/** 角色可主动拉主控进入晤面（仅单聊；默认开，显式 `autoOfflineEnabled === false` 为关）。 */
function isThreadAutoOfflineEnabled(thread) {
  if (!thread || thread.kind === "group") return false;
  return thread.autoOfflineEnabled !== false;
}

/** 异地模式：仅线上互动，禁止程序切入晤面/当面（仅单聊；默认关，显式 `onlineRomanceEnabled === true` 为开）。 */
function isThreadOnlineRomanceEnabled(thread) {
  return Boolean(thread && thread.kind !== "group" && thread.onlineRomanceEnabled === true);
}

/** 异地模式 · 单次 API 代发/锁屏后等场景的短提示（与 buildOnlineRomancePromptLines 语义一致）。 */
function buildOnlineRomanceApiHintLine() {
  return "本密谈为**异地模式（纯线上互动）**：仅走线上通道；可按人设聊共同回忆，但不要主动推进线下见面、奔现或站外联系；禁止 [OFFLINE] 与当面场面；用 lines 或 placeCall 回应。";
}

/** @param {string} name @param {string} userCall */
function buildOnlineRomancePromptLines(name, userCall) {
  const uc = String(userCall || "对方").trim() || "对方";
  const nm = String(name || "你").trim() || "你";
  return [
    `[异地模式 · 纯线上互动]`,
    `本密谈剧情**仅在本聊天界面内**推进：${nm} 与 ${uc} 通过气泡、中插 HTML、语音/视频（placeCall）互动。`,
    `你可以仍按人设、世界书与共同回忆发挥，但**不要主动提出**线下见面、奔现、现实同框，也不要引导转为微信/电话等站外联系。`,
    `保持「隔着屏幕在聊」的体感；严禁输出 [OFFLINE:…] 或描写当面晤面、来我家/你家等「切到同场」场面。情绪写在 lines 里。`
  ];
}

/** @param {unknown} th @param {{ live?: boolean, checkup?: boolean }} [opts] */
function buildThreadOfflineApiHintLine(th, opts) {
  if (isThreadOnlineRomanceEnabled(th)) return buildOnlineRomanceApiHintLine();
  const offOn = th && isThreadAutoOfflineEnabled(th);
  if (!offOn) return "本密谈未开自动线下：不要输出 [OFFLINE]；只按 JSON 用 lines 回应。";
  if (opts?.checkup && opts?.live) {
    return "若你决定当面赶人、抢手机或对峙，可写 **[OFFLINE: 场面]**（≤400 字）；否则只发 lines。";
  }
  if (opts?.checkup) {
    return "若你决定当面赶人、对峙或继续纠缠，可写 **[OFFLINE: 场面]**（≤400 字）；否则只发 lines。";
  }
  return "本密谈已开启**自动线下**：若你人设与当下剧情适合**当面去找对方**，可在本轮任意位置写 **[OFFLINE: 当场场面描写]**（≤400 字），程序会切入晤面；也可先发 lines 再 OFFLINE。若不适合见面，只输出正常 lines 即可。";
}

function isThreadOfflineMeetSummaryMode(thread) {
  return String(thread?.offlineMeetMode || "").trim() === "summary";
}

/**
 * 从模型全文解析 [OFFLINE: 场面]（旧版小心机协议）。
 * @param {string} rawReply
 * @returns {{ closed: boolean, sceneDesc: string, textBefore: string, textAfter: string } | null}
 */
function extractAssistantOfflineMeetupFromRaw(rawReply) {
  const raw = String(rawReply || "");
  if (!/\[OFFLINE:/i.test(raw)) return null;
  const m = raw.match(/\[OFFLINE:\s*([\s\S]+?)\]/i);
  if (!m) {
    return { closed: false, sceneDesc: "", textBefore: raw.trim(), textAfter: "" };
  }
  const full = m[0];
  const idx = typeof m.index === "number" ? m.index : 0;
  return {
    closed: true,
    sceneDesc: String(m[1] || "").trim().slice(0, 4000),
    textBefore: raw.substring(0, idx).trim(),
    textAfter: raw.substring(idx + full.length).trim()
  };
}

/** @param {string} replyJoined */
function stripOfflineMeetupTagFromAssistantReply(replyJoined) {
  let r = String(replyJoined || "");
  if (!r) return r;
  r = r.replace(/\[OFFLINE:\s*[\s\S]+?\]/gi, "");
  const segs = r
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean);
  return segs.join("|||");
}

/** @param {string} text @param {number} [maxItems] @param {boolean} [includePartial] 流式预览：未闭合的字符串也计入 */
function extractLooseAssistantLinesFromRaw(text, maxItems = 24, includePartial = false) {
  const s0 = normalizeAssistantModelJsonText(String(text ?? "")).trim();
  if (!s0) return [];
  const idx = s0.search(/"lines"\s*:/i);
  if (idx < 0) return [];
  const after = s0.slice(idx);
  const lb = after.indexOf("[");
  if (lb < 0) return [];
  const src = after.slice(lb + 1);
  const cap = Math.max(1, Math.min(32, Math.floor(Number(maxItems) || 24)));
  /** @type {string[]} */
  const out = [];
  let inStr = false;
  let esc = false;
  let buf = "";
  for (let i = 0; i < src.length; i++) {
    const c = src[i];
    if (!inStr) {
      if (c === "]") break;
      if (c === '"') {
        inStr = true;
        esc = false;
        buf = "";
      }
      continue;
    }
    if (esc) {
      if (c === "n") buf += "\n";
      else if (c === "r") buf += "\r";
      else if (c === "t") buf += "\t";
      else buf += c;
      esc = false;
      continue;
    }
    if (c === "\\") {
      esc = true;
      continue;
    }
    if (c === '"') {
      inStr = false;
      const t = String(buf || "").trim();
      if (t) out.push(t);
      if (out.length >= cap) break;
      continue;
    }
    buf += c;
  }
  if (includePartial && inStr && String(buf || "").trim()) {
    out.push(String(buf).trim());
  }
  const rawOut = out.length ? out : extractUnquotedLooseLinesFromLinesArray(text, cap);
  return rawOut.filter((ln) => !isAssistantThinkingLeakLine(ln));
}

/** 截断/非法 JSON：lines 数组里未加引号的台词（如 `(……)`） */
function extractUnquotedLooseLinesFromLinesArray(text, maxItems = 12) {
  const s0 = normalizeAssistantModelJsonText(String(text ?? "")).trim();
  if (!s0) return [];
  const idx = s0.search(/"lines"\s*:/i);
  if (idx < 0) return [];
  const after = s0.slice(idx);
  const lb = after.indexOf("[");
  if (lb < 0) return [];
  let src = after.slice(lb + 1);
  const rb = src.indexOf("]");
  if (rb >= 0) src = src.slice(0, rb);
  src = src.replace(/"(?:\\.|[^"\\])*"/g, " ");
  const cap = Math.max(1, Math.min(32, Math.floor(Number(maxItems) || 12)));
  /** @type {string[]} */
  const out = [];
  for (const part of src.split(",")) {
    const t = String(part ?? "")
      .replace(/\s+/g, " ")
      .trim();
    if (!t) continue;
    if (/^[\{\[\]"\\]/.test(t)) continue;
    if (/^(?:lines|heartVoice|innerState|mood|recalls|narration)\b/i.test(t)) continue;
    out.push(t);
    if (out.length >= cap) break;
  }
  if (!out.length) {
    const whole = src.replace(/\s+/g, " ").trim();
    if (whole && /[\u4e00-\u9fff(（]/.test(whole) && !/^[\{\[]/.test(whole)) out.push(whole);
  }
  return out;
}

/** 模型/网关误把英文 CoT、Capturing Nuances 标题等写进 lines 时的单行识别。 */
function isAssistantThinkingLeakLine(line) {
  const s = String(line || "").trim();
  if (!s) return true;
  if (/^\*\*Capturing\b/i.test(s) || /^Capturing Nuances\b/i.test(s)) return true;
  if (/^\*\*[A-Z][a-zA-Z ]{2,48}\*\*$/.test(s)) return true;
  if (/^I'm focusing on the\b/i.test(s)) return true;
  if (/^The catch is in the\b/i.test(s)) return true;
  if (/^I find myself\b/i.test(s)) return true;
  if (/^I'm (?:now )?(?:analyzing|considering|thinking|evaluating|noticing|weighing)\b/i.test(s)) return true;
  if (/^Let me (?:think|analyze|consider|break this down)\b/i.test(s)) return true;
  if (/^My (?:focus|goal|task) is to\b/i.test(s)) return true;
  if (/^(?:snag|drift|read|feel|shape|check|route)\s*[·:—–-]/i.test(s)) return true;
  return false;
}

/** 无 JSON lines 壳、整段像 reasoning 泄漏时勿当聊天气泡。 */
function assistantPlainTextLooksLikeThinkingLeak(text) {
  const s = String(text || "").trim();
  if (!s || /"lines"\s*:/i.test(s)) return false;
  const lines = s.split(/\n+/).map((x) => x.trim()).filter(Boolean);
  if (!lines.length) return isAssistantThinkingLeakLine(s);
  if (lines.every(isAssistantThinkingLeakLine)) return true;
  return isAssistantThinkingLeakLine(lines[0]) && lines.length <= 2;
}

/** JSON 解析失败或 lines 为空时，从原始模型输出里尽量抢救可展示的台词/旁白（不把整坨 JSON 骨架直接展示）。 */
function salvageAssistantDisplayReplyFromRaw(raw, opts) {
  const offlineProse = Boolean(opts && typeof opts === "object" && opts.offlineProse);
  const splitBubbleSegs = offlineProse ? splitOfflineAssistantBubbleSegments : splitOuterAssistantBubbleSegments;
  const maxItems = Math.max(1, Math.min(32, Math.floor(Number(opts && opts.maxItems) || 12)));
  const r = String(raw ?? "").trim();
  if (!r) return "";

  const loose = extractLooseAssistantLinesFromRaw(r, maxItems);
  if (loose.length) return loose.join("|||");

  const narr = normalizeAssistantNarrationText(
    extractJsonStringFieldLoose(r, "narration", true) ??
      extractJsonStringFieldLoose(r, "narrator", true) ??
      extractJsonStringFieldLoose(r, "narrative", true) ??
      ""
  );
  if (narr) {
    const segs = splitBubbleSegs(narr);
    return segs.length ? segs.join("|||") : narr;
  }

  const replyLoose =
    extractJsonStringFieldLoose(r, "reply", true) ?? extractJsonStringFieldLoose(r, "text", true);
  if (replyLoose) {
    const rt = String(replyLoose).trim();
    if (rt) {
      const segs = splitBubbleSegs(rt);
      return segs.length ? segs.join("|||") : rt;
    }
  }

  return "";
}

/** JSON 有壳但 lines/reply 为空时，从原始输出抢救可展示正文（IM/当面通用） */
function coalesceAssistantDisplayReply(reply, rawReply, dmSurface) {
  let r = stripOfflineMeetupTagFromAssistantReply(String(reply || "").trim());
  if (r) return dmSurface !== "offline" ? normalizeImAssistantReplyJoined(r) : r;
  const salv = salvageAssistantDisplayReplyFromRaw(rawReply, {
    maxItems: 12,
    offlineProse: dmSurface === "offline"
  });
  if (salv) {
    const out = stripOfflineMeetupTagFromAssistantReply(salv);
    return dmSurface !== "offline" ? normalizeImAssistantReplyJoined(out) : out;
  }
  const raw = String(rawReply || "").trim();
  if (!raw) return "";
  const splitSegs = dmSurface === "offline" ? splitOfflineAssistantBubbleSegments : splitOuterAssistantBubbleSegments;
  for (const key of ["content", "text", "message", "output", "response", "prose", "body"]) {
    const t = String(extractJsonStringFieldLoose(raw, key, true) ?? "").trim();
    if (!t || t.length < 2) continue;
    if (/^[\{\[\]"\\]/.test(t) && !/[\u4e00-\u9fff]/.test(t)) continue;
    const segs = splitSegs(t);
    const joined = stripOfflineMeetupTagFromAssistantReply(segs.length ? segs.join("|||") : t);
    if (joined) return dmSurface !== "offline" ? normalizeImAssistantReplyJoined(joined) : joined;
  }
  const stripped = stripCharLockPlainProtocolBlocksFromText(raw).text.trim();
  if (stripped && !/^\s*\{/.test(stripped)) {
    if (!/"lines"\s*:/i.test(raw) && assistantPlainTextLooksLikeThinkingLeak(stripped)) return "";
    const segs = splitSegs(stripped);
    const joined = stripOfflineMeetupTagFromAssistantReply(segs.length ? segs.join("|||") : stripped);
    return dmSurface !== "offline" ? normalizeImAssistantReplyJoined(joined) : joined;
  }
  return "";
}

/** @param {string} raw @param {string} [salvageRaw] 当面：lines 为空时从误写键/截断 JSON 抢救正文 */
function parseOfflineAssistantPayload(raw, salvageRaw) {
  const parsed = parseChatAssistantPayload(raw, { offlineProse: true });
  if (!String(parsed.reply || "").trim()) {
    const misKeyed = normalizeAssistantNarrationText(String(parsed.narration ?? "").trim());
    if (misKeyed) {
      const parts = splitOfflineAssistantBubbleSegments(misKeyed);
      parsed.reply = parts.length ? parts.join("|||") : misKeyed;
    }
  }
  if (!String(parsed.reply || "").trim()) {
    const salvage = String(salvageRaw ?? raw ?? "").trim();
    if (salvage) {
      for (const key of ["content", "text", "prose", "body"]) {
        const t = normalizeAssistantNarrationText(
          String(extractJsonStringFieldLoose(salvage, key, true) ?? "").trim()
        );
        if (!t) continue;
        const parts = splitOfflineAssistantBubbleSegments(t);
        parsed.reply = parts.length ? parts.join("|||") : t;
        break;
      }
    }
  }
  if (!String(parsed.reply || "").trim()) {
    const plain = String(raw ?? "").trim();
    if (plain && !/^\s*\{/.test(plain)) {
      const parts = splitOfflineAssistantBubbleSegments(plain);
      if (parts.length) parsed.reply = parts.join("|||");
    }
  }
  delete parsed.narration;
  return parsed;
}

/** IM：JSON lines 为空时从 salvageRaw 抢救（复用 coalesceAssistantDisplayReply） */
function parseImAssistantPayload(raw, salvageRaw) {
  const parsed = parseChatAssistantPayload(raw);
  if (String(parsed.reply || "").trim()) return parsed;
  const co = coalesceAssistantDisplayReply("", salvageRaw ?? raw, "im");
  if (co) parsed.reply = co;
  return parsed;
}

/** @param {string} strippedText @param {"im"|"offline"} dmSurface @param {string} [salvageRaw] */
function parseAssistantPayloadForDmSurface(strippedText, dmSurface, salvageRaw) {
  return dmSurface === "offline"
    ? parseOfflineAssistantPayload(strippedText, salvageRaw)
    : parseImAssistantPayload(strippedText, salvageRaw);
}

/** lines/篇幅修补 merge 时保留首轮已解析的心声面板字段，避免空串覆盖。 */
function mergeAssistantParsedPreservingHeartPanel(target, patch) {
  if (!target || !patch || typeof target !== "object" || typeof patch !== "object") return target;
  const keepFromJson = Boolean(target.fromJson);
  /** @type {Record<string, string>} */
  const keep = {};
  for (const k of ["heartVoice", "hvState", "hvMood", "hvDesire", "hvAffectionDesc"]) {
    keep[k] = String(target[k] ?? "").trim();
  }
  const keepAff =
    typeof target.hvAffinity === "number" && Number.isFinite(target.hvAffinity) ? target.hvAffinity : null;
  Object.assign(target, patch);
  for (const k of ["heartVoice", "hvState", "hvMood", "hvDesire", "hvAffectionDesc"]) {
    if (!String(patch[k] ?? "").trim() && keep[k]) target[k] = keep[k];
  }
  if ((patch.hvAffinity == null || !Number.isFinite(Number(patch.hvAffinity))) && keepAff != null) {
    target.hvAffinity = keepAff;
  }
  if (keepFromJson && !patch.fromJson) target.fromJson = true;
  return target;
}

/**
 * @param {{ closed: boolean, sceneDesc: string, textAfter: string }} meetup
 */
function assistantOfflineMeetupWouldTrigger(meetup) {
  if (!meetup || !meetup.closed || !String(meetup.sceneDesc || "").trim()) return false;
  const th = readActiveThread();
  if (!th || th.kind === "group" || !isThreadAutoOfflineEnabled(th)) return false;
  if (isThreadOnlineRomanceEnabled(th)) return false;
  if (getActiveChatDmSurfaceForContext() === "offline" || isChatOfflineScreenOpen()) return false;
  if (isChatCallActive() || isCharLockFocusScreenOpen()) return false;
  return true;
}

/**
 * @param {{ closed: boolean, sceneDesc: string, textAfter: string }} meetup
 */
function maybeEnterOfflineFromAssistantMeetup(meetup) {
  if (!assistantOfflineMeetupWouldTrigger(meetup)) return false;
  const sceneDesc = String(meetup.sceneDesc || "").trim();
  const tail = String(meetup.textAfter || "").trim();
  const offlineContent = tail ? `${sceneDesc}\n\n${tail}` : sceneDesc;
  if (!offlineContent) return false;
  openChatOfflineScreen();
  const log = readChatLog();
  const at = Date.now();
  const entry = { role: "assistant", content: offlineContent.slice(0, 500_000), at };
  tagAssistantEntryDmSurface(entry, "offline");
  log.push(entry);
  saveChatLog(log);
  renderChatMessages();
  showToast("已进入晤面");
  return true;
}

/** 主动私聊默认间隔（秒）：宁少勿勤 */
const CHAR_PROACTIVE_DEFAULT_INTERVAL_SEC = 30 * 60;
/** 随机模式：30min～10h */
const CHAR_PROACTIVE_RANDOM_MIN_MS = 30 * 60 * 1000;
/** 随机模式：最长 10h */
const CHAR_PROACTIVE_RANDOM_MAX_MS = 10 * 3600 * 1000;
const CHAR_PROACTIVE_RANDOM_RANGE_MS = CHAR_PROACTIVE_RANDOM_MAX_MS - CHAR_PROACTIVE_RANDOM_MIN_MS;

function getCharProactiveIntervalMs(thread) {
  if (isThreadCharProactiveAutoMode(thread)) {
    return CHAR_PROACTIVE_RANDOM_MIN_MS + Math.floor(Math.random() * CHAR_PROACTIVE_RANDOM_RANGE_MS);
  }
  return getThreadCharProactiveIntervalSec(thread) * 1000;
}

function ensureCharProactiveDefaultsOnEnable(thread) {
  if (!thread || typeof thread !== "object") return;
  thread.charProactiveEnabled = true;
  const hasInterval = Number.isFinite(Number(thread.charProactiveIntervalSec));
  if (!hasInterval) {
    thread.charProactiveAutoMode = true;
    thread.charProactiveIntervalSec = CHAR_PROACTIVE_DEFAULT_INTERVAL_SEC;
  }
}

function getThreadCharProactiveIntervalSec(thread) {
  const n = Number(thread?.charProactiveIntervalSec);
  if (!Number.isFinite(n) || n < 0) return CHAR_PROACTIVE_DEFAULT_INTERVAL_SEC;
  return Math.floor(n);
}

function isThreadCharProactiveAutoMode(thread) {
  return Boolean(thread && thread.charProactiveAutoMode === true);
}

function listRelationPeersForOwnerChar(maskId, charId) {
  const listFn =
    typeof window.relationListOwnerNetworkPeers === "function"
      ? window.relationListOwnerNetworkPeers
      : typeof window.relationListOwnerLinkedCharPeers === "function"
        ? window.relationListOwnerLinkedCharPeers
        : null;
  if (!listFn) return [];
  return listFn(String(maskId || "").trim(), String(charId || "").trim());
}

function listCharsWithRelationNetwork(maskId) {
  const mid = String(maskId || "").trim();
  if (!mid) return [];
  const st = readCharPersonaStore();
  /** @type {{ charId: string, name: string, avatar: string }[]} */
  const out = [];
  for (const ch of Array.isArray(st.items) ? st.items : []) {
    const cid = String(ch?.id || "").trim();
    if (!cid) continue;
    if (!listRelationPeersForOwnerChar(mid, cid).length) continue;
    out.push({
      charId: cid,
      name: String(ch?.displayName || "").trim() || "未命名角色",
      avatar: String(ch?.avatar || "").trim()
    });
  }
  return out;
}

function listCharsWithRelationNetworkForBg(maskId) {
  const all = listCharsWithRelationNetwork(maskId);
  const idsFn =
    typeof window.getRelationBgCharIds === "function" ? window.getRelationBgCharIds : null;
  if (!idsFn) return all;
  const ids = new Set(idsFn(String(maskId || "").trim()));
  if (!ids.size) return [];
  return all.filter((ch) => ids.has(String(ch?.charId || "").trim()));
}

function hasAnyBackgroundProactivePolling() {
  const relationBg =
    typeof window.relationBgStoreHasActivePolling === "function" &&
    window.relationBgStoreHasActivePolling();
  return hasAnyChatProactiveEnabled() || relationBg;
}

/** 角色按间隔主动发朋友圈：仅 `charMomentsProactiveEnabled === true` 为开（默认关）。 */
function isThreadCharMomentsProactiveEnabled(thread) {
  return Boolean(thread && thread.charMomentsProactiveEnabled === true);
}

function getThreadCharMomentsProactiveIntervalSec(thread) {
  const n = Number(thread?.charMomentsProactiveIntervalSec);
  if (!Number.isFinite(n) || n < 60) return 7200;
  return Math.min(86400, Math.floor(n));
}

function isThreadCharMomentsProactiveAutoMode(thread) {
  return Boolean(thread && thread.charMomentsProactiveAutoMode === true);
}

/** 随聊天模式：两次「要不要发圈」探测至少间隔这么久。 */
const MOMENTS_PROACTIVE_CHAT_PROBE_MIN_MS = 60 * 60 * 1000;
/** 随聊天模式：成功发圈后至少隔这么久再探测（避免刷屏）。 */
const MOMENTS_PROACTIVE_CHAT_POST_MIN_MS = 55 * 60 * 1000;
/** 随聊天模式：久未发圈时的兜底定时（小时）。 */
const MOMENTS_PROACTIVE_CHAT_FALLBACK_MS = 8 * 3600000;

function getLastCharMomentPostMsForMaskChar(maskId, charId) {
  const mid = String(maskId || "").trim();
  const cid = String(charId || "").trim();
  if (!mid || !cid) return 0;
  const inbox = readChatInboxStore();
  const bucket = inbox.byMask[maskBucketKey(mid)];
  if (!bucket) return 0;
  let max = 0;
  for (const raw of Array.isArray(bucket.moments) ? bucket.moments : []) {
    const m = normalizeMoment(raw);
    if (m.kind !== "char") continue;
    if (String(m.charId || "").trim() !== cid) continue;
    const t = Date.parse(String(m.timeIso || ""));
    if (Number.isFinite(t)) max = Math.max(max, t);
  }
  return max;
}

function computeMomentsProactiveBaselineMs(thread, maskId) {
  const iso = String(thread?.charMomentsProactiveLastAt || "").trim();
  if (iso) {
    const t = Date.parse(iso);
    if (Number.isFinite(t)) return t;
  }
  const cid = String(thread?.charId || "").trim();
  const mid = String(maskId || "").trim();
  const fromFeed = getLastCharMomentPostMsForMaskChar(mid, cid);
  if (fromFeed > 0) return fromFeed;
  return Date.now();
}

function getMomentsProactiveIntervalMs(thread, charId = "") {
  if (isThreadCharMomentsProactiveAutoMode(thread)) {
    const cid = String(charId || thread?.charId || "").trim();
    const incl = getMomentsProactiveTimingForChar(cid);
    return Math.floor(MOMENTS_PROACTIVE_CHAT_FALLBACK_MS * incl.fallbackMult);
  }
  return getThreadCharMomentsProactiveIntervalSec(thread) * 1000;
}

function getThreadCharMomentsProactiveLastPostMs(thread, maskId) {
  return computeMomentsProactiveBaselineMs(thread, maskId);
}

function canMomentsProactiveProbeFromChat(thread, charId = "") {
  if (!thread || !isThreadCharMomentsProactiveAutoMode(thread)) return false;
  const cid = String(charId || thread.charId || "").trim();
  const incl = getMomentsProactiveTimingForChar(cid);
  const now = Date.now();
  const probeIso = String(thread.charMomentsProactiveLastProbeAt || "").trim();
  const probeMin = Math.floor(MOMENTS_PROACTIVE_CHAT_PROBE_MIN_MS * incl.probeMult);
  if (probeIso) {
    const t = Date.parse(probeIso);
    if (Number.isFinite(t) && now - t < probeMin) return false;
  }
  return true;
}

function touchThreadCharMomentsProactiveProbe(maskId, threadId) {
  const iso = new Date().toISOString();
  return patchMaskThread(maskId, threadId, (t) => {
    t.charMomentsProactiveLastProbeAt = iso;
  });
}

function threadHasShareableChatForMomentsProactive(maskId, charId, threadId) {
  const snip = buildMomentsCharDialogueSnippet(maskId, charId, 3, threadId);
  return String(snip || "").trim().length >= 10;
}

function buildMomentsProactiveHintFromChatLog(maskId, charId, threadId) {
  const dlg = buildMomentsCharDialogueSnippet(maskId, charId, 5, threadId);
  if (!dlg) return "";
  return `刚在密谈里聊过，可参考：\n${dlg}`.slice(0, 400);
}

function isThreadMomentsProactiveDue(thread, maskId, now = Date.now()) {
  if (!isThreadCharMomentsProactiveEnabled(thread)) return false;
  const cid = String(thread?.charId || "").trim();
  const lastPost = getThreadCharMomentsProactiveLastPostMs(thread, maskId);
  const dueAt = lastPost + getMomentsProactiveIntervalMs(thread, cid);
  return now + 500 >= dueAt;
}

function patchMaskThread(maskId, threadId, mutator) {
  const D = window.XXJ_DB;
  if (!D || typeof mutator !== "function") return false;
  const mid = String(maskId || "").trim();
  const tid = String(threadId || "").trim();
  if (!mid || !tid) return false;
  const inbox = readChatInboxStore();
  ensureMaskBucket(inbox, mid);
  const bucket = inbox.byMask[maskBucketKey(mid)];
  if (!bucket) return false;
  const th = (Array.isArray(bucket.threads) ? bucket.threads : []).find((t) => t && String(t.id || "") === tid);
  if (!th) return false;
  mutator(th);
  th.updatedAt = Date.now();
  writeChatInboxStore(inbox, { fast: true, dirtyThreadKey: chatDirtyThreadPersistKey(mid, tid) });
  return true;
}

function touchThreadCharMomentsProactiveLastAt(maskId, threadId) {
  const iso = new Date().toISOString();
  return patchMaskThread(maskId, threadId, (t) => {
    t.charMomentsProactiveLastAt = iso;
  });
}

function computeCharProactiveBaselineMs(log) {
  const arr = Array.isArray(log) ? log : [];
  const visible = arr.filter(
    (m) =>
      m &&
      (m.role === "user" || m.role === "assistant") &&
      !(m.role === "assistant" && m.restoring && !String(m.content || "").trim())
  );
  let lastUserAt = 0;
  for (const m of visible) {
    if (m.role !== "user") continue;
    const at = Number(m.at);
    if (Number.isFinite(at)) lastUserAt = Math.max(lastUserAt, at);
  }
  const last = visible[visible.length - 1];
  let base = lastUserAt > 0 ? lastUserAt : Date.now();
  if (last && last.role === "assistant") {
    const at = Number(last.at);
    if (Number.isFinite(at) && at > base) base = at;
  }
  return base;
}

function countTrailingAssistantBubblesInLog(log) {
  const arr = Array.isArray(log) ? log : [];
  let n = 0;
  for (let i = arr.length - 1; i >= 0; i--) {
    const m = arr[i];
    if (!m || typeof m !== "object") continue;
    if (isChatSystemNotice(m)) continue;
    if (m.role === "assistant") {
      if (m.restoring && !String(m.content || "").trim()) continue;
      n++;
      continue;
    }
    if (m.role === "user") break;
  }
  return n;
}

/**
 * @param {boolean} isFollowUp
 * @param {object} [boundThread]
 * @param {string} [boundMaskId]
 */
function buildCharProactiveApiUserPrompt(isFollowUp, boundThread, boundMaskId) {
  const thPro =
    boundThread && typeof boundThread === "object" ? boundThread : readActiveThread();
  const offline =
    thPro && thPro === readActiveThread()
      ? getActiveChatDmSurfaceForContext() === "offline"
      : false;
  const lockOn = thPro && isThreadCharLockPhoneEnabled(thPro);
  const romanceOn = thPro && isThreadOnlineRomanceEnabled(thPro);
  const offOn = thPro && isThreadAutoOfflineEnabled(thPro);
  const offlineHint =
    !offline && !romanceOn && offOn
      ? lockOn
        ? " 若适合当面见：可写 [OFFLINE: 场面] 立刻晤面，或 charLock 且 afterUnlockOffline:true+offlineScene（或同轮 [OFFLINE]）等解锁后再晤面；仅想占屏看完则用 charLock 不要 [OFFLINE]。"
        : " 若适合拉对方当面见，可写 [OFFLINE: 场面]；否则按 lines 发消息。"
      : romanceOn
        ? ` ${buildOnlineRomanceApiHintLine()}`
        : "";
  const callHint = offline
    ? ""
    : " 若**此刻正在拨出**语音/视频、对方会立刻看到来电，才在 JSON **根对象**写 **placeCall**：\"audio\" 或 \"video\"。「等下打给你」「到了再打电话」等**未来/口头计划**只写 lines、**不要** placeCall。不需要通话则省略 placeCall。";
  const plotFirst =
    "主动单聊**宁少勿勤**：仅当剧情上真有话要说、情绪上自然想找人、或关系/情节**需要推进**时才开口；禁止为刷存在感硬找话题、查岗、撒娇卖惨或客服式问候。";
  const oocGuard =
    "严格遵守人设、口吻、边界与当前关系阶段；禁止 OOC、霸总模板、粘人连击、无中生有。";
  const emptyOk =
    "没有自然接点、对方可能在忙、或人设上不应打扰时，**必须 lines 为空**（可在 thinking 写「此刻不开口」）。";
  const anchor =
    "若开口：只接**当前对话末尾**未收梢的话头或群里刚发生的事，勿翻旧账、勿复述上文已落幕的话题。";
  const head = "（界面代发、勿复述本句）[主动发消息] ";
  const mid = isFollowUp
    ? "你已主动找过对方，对方仍未回。**默认不要再追**；仅剧情上还有一句非说不可的短评时可再发一条，否则 lines 必须为空。" +
      anchor +
      " " +
      oocGuard
    : "对方沉默较久。先判断此刻是否值得开口：" +
      plotFirst +
      " " +
      emptyOk +
      " " +
      oocGuard +
      " " +
      anchor +
      " 多数情况下 lines 应为空——只有人设与剧情都支持时才发。";
  const callSoft =
    offline || isFollowUp
      ? ""
      : " 除非剧情强烈需要，否则本轮**不要** placeCall；优先判断 lines 是否应为空。";
  return head + mid + callSoft + callHint + offlineHint;
}

/**
 * 群↔私聊互通：由群剧情与人设决定是否私聊（无需开关；lines 为空=不发）。
 * @param {object} dmThread
 * @param {object} groupThread
 * @param {string} maskId
 * @param {boolean} isFollowUp
 */
function buildGroupDrivenProactiveDmUserPrompt(dmThread, groupThread, maskId, isFollowUp) {
  const mid = String(maskId || "").trim();
  const groupTitle = threadLinkDisplayLabel(groupThread);
  const mask = readUserMask();
  const groupLog = readChatLogForMaskThread(mid, String(groupThread?.id || ""));
  const recent = formatLinkedGroupRecentMessagesForPrompt(
    groupLog,
    groupThread,
    mask,
    LINKED_THREAD_MEMORY_RECENT_CAP_GROUP
  );
  const oocGuard =
    "严格遵守人设、口吻、边界与当前关系阶段；禁止 OOC、霸总模板、粘人、查岗、客服腔。";
  const head = "（界面代发、勿复述本句）[群剧情 · 是否私聊找主控] ";
  const decide =
    "像真人：先读**群聊最近动态**，再想「我会不会此刻给主控发私聊」。只有群里刚发生的事让你**非私下说不可**、或情绪/剧情**自然延续到私聊**时，才写 lines；否则 **lines 必须为空**（thinking 可写「此刻不私聊」）。";
  const tone =
    "若发私聊：用**私聊口吻**（一对一），不是群聊当众语气；勿搬运群聊原文，只承接情节与情绪。";
  const followNote = isFollowUp
    ? " 你刚私聊过对方未回；除非群里又发生了必须私下说的新事，否则 lines 必须为空。"
    : "";
  const recentBlock = recent
    ? `\n\n[群聊最近动态 · 据此判断]\n${recent}`
    : "\n\n（群聊暂无最近消息；默认 lines 为空。）";
  return head + decide + followNote + " " + oocGuard + " " + tone + recentBlock;
}

function getThreadStickerBindCategories(thread) {
  const arr = Array.isArray(thread?.stickerBindCategories) ? thread.stickerBindCategories : [];
  const out = arr
    .map((x) => String(x || "").trim().slice(0, 20))
    .filter(Boolean)
    .slice(0, 12);
  return out;
}

function getThreadCharTranslationTone(thread) {
  return String(thread?.charTranslationTone || "").trim() === "literal" ? "literal" : "colloquial";
}

function getThreadCharTranslationTargetLang(thread) {
  const s = String(thread?.charTranslationTargetLang || "").trim();
  return s || "中文";
}

/** 仅当模型显式写 [SKIP] 等时隐藏灰字行；空串视为「缺译文」而非跳过。 */
function isTranslationSegmentSkipped(s) {
  const t = String(s ?? "").trim();
  if (!t) return false;
  if (t === CHAT_TRANSLATION_SKIP_TOKEN) return true;
  if (isStickerDirectiveTranslationChunk(t)) return true;
  if (isStructuredProtocolChatSegment(t)) return true;
  return /^[\[【]?\s*SKIP\s*[\]】]?$/i.test(t);
}

/** 发图指令：【表情包：…】与模型常写的【表情：…】等价 */
const STICKER_CMD_BRACKET = "表情(?:包)?";
const RE_STICKER_CMD_EMBED = new RegExp(`^(.*?)【${STICKER_CMD_BRACKET}[:：]\\s*([^】]*?)\\s*】(.*)$`);
const RE_STICKER_CMD_WHOLE_COLON = new RegExp(`^【${STICKER_CMD_BRACKET}[:：]\\s*(.*?)\\s*】\\s*$`);
const RE_STICKER_CMD_WHOLE_BARE = new RegExp(`^【${STICKER_CMD_BRACKET}】\\s*(.*)$`);
const RE_STICKER_CMD_FIND_COLON = new RegExp(`【${STICKER_CMD_BRACKET}[:：]\\s*([^】]*?)\\s*】`, "g");
const RE_STICKER_CMD_HAS_BARE = new RegExp(`【${STICKER_CMD_BRACKET}】`);
const RE_STICKER_PLACEHOLDER_COLON = new RegExp(`^【${STICKER_CMD_BRACKET}[:：]\\s*[^】]*\\s*】\\s*$`, "u");
const RE_STICKER_PLACEHOLDER_BARE = new RegExp(`^【${STICKER_CMD_BRACKET}】\\s*$`, "u");
/** 模型偶发把表情包写成 JSON 块（与【表情包：】等价，走同一择图管线） */
const RE_MODEL_EMOJI_JSON_BLOCK =
  /^\[\s*\{\s*"type"\s*:\s*"emoji"\s*,\s*"description"\s*:\s*"((?:\\.|[^"\\])*)"\s*\}\s*\]/i;

function findModelLeakedEmojiJsonBlockStart(s) {
  const m = /\[\s*\{\s*"type"\s*:\s*"emoji"/i.exec(String(s || ""));
  return m && m.index >= 0 ? m.index : -1;
}

function unescapeLooseJsonString(s) {
  return String(s || "")
    .replace(/\\n/g, "\n")
    .replace(/\\r/g, "\r")
    .replace(/\\t/g, "\t")
    .replace(/\\"/g, '"')
    .replace(/\\\\/g, "\\");
}

/** 从 emoji JSON 的 description 提取择图关键词（如「呆猫八条」哎 → 哎） */
function stickerKeywordFromEmojiJsonDescription(desc) {
  const d = unescapeLooseJsonString(desc).trim();
  if (!d) return "";
  const tail = /」\s*([^」\s]{1,32})\s*$/.exec(d);
  if (tail) return String(tail[1]).trim();
  const inner = /^「[^」]*」\s*(.+)$/.exec(d);
  if (inner) return String(inner[1]).trim().slice(0, 48);
  return d.slice(0, 48);
}

/** 译本槽误写表情包指令/占位时不展示灰字（表情包已单独成图或不应出现在译本区）。 */
function isStickerDirectiveTranslationChunk(trans) {
  const t = String(trans ?? "").trim();
  if (!t) return false;
  if (RE_STICKER_PLACEHOLDER_COLON.test(t)) return true;
  if (RE_STICKER_PLACEHOLDER_BARE.test(t)) return true;
  /* 无【】括号的误写占位 */
  if (/^(?:表情包|表情)\s*$/u.test(t)) return true;
  if (/^(?:表情包|表情)[:：]\s*[^】\s]*\s*$/u.test(t)) return true;
  return false;
}

/** content 段是否含可展示文字（排除【表情包】协议占位）。 */
function chatMessageBubblePartIsRealText(seg) {
  const t = String(seg ?? "")
    .replace(/\u00A0/g, " ")
    .trim();
  if (!t) return false;
  return !isStickerDirectiveTranslationChunk(t);
}

/** @param {unknown[]} parts */
function chatMessageBubblePartsHaveRealText(parts) {
  return (Array.isArray(parts) ? parts : []).some(chatMessageBubblePartIsRealText);
}

/** 删掉表情包后同步去掉 content 里的占位，避免先变成文字气泡。 */
function stripStickerPlaceholdersFromMessageContent(msg) {
  if (!msg || typeof msg !== "object") return;
  const isPlaceholder = (seg) => {
    const t = String(seg ?? "").trim();
    return !t || isStickerDirectiveTranslationChunk(t);
  };
  const raw = String(msg.content ?? "").trim();
  if (!raw) {
    msg.content = "";
    return;
  }
  const chunks = raw
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean);
  if (!chunks.length) {
    if (isPlaceholder(raw)) msg.content = "";
    return;
  }
  const kept = chunks.filter((seg) => !isPlaceholder(seg));
  msg.content = kept.length ? kept.join("|||") : "";
}

function translationJoinedHasAnyVisible(transJoined) {
  return String(transJoined || "")
    .split(/\|\|\|/)
    .some((seg) => {
      const t = String(seg).trim();
      if (!t) return false;
      return !isTranslationSegmentSkipped(t);
    });
}

/** 线下：仍缺有效译本的对白分段下标。 */
function offlineMissingDialogueTranslationIndices(replyJoined, transJoined) {
  const mains = String(replyJoined ?? "")
    .split(/\|\|\|/)
    .map((s) => String(s).trim());
  if (!mains.some(Boolean)) return [];
  const tc = padTranslationSegments(transJoined, mains.length);
  /** @type {number[]} */
  const out = [];
  for (let i = 0; i < mains.length; i++) {
    if (!offlineAssistantSegmentNeedsParallelTranslation(mains[i])) continue;
    if (offlineSegmentHasInlineTranslation(mains[i])) continue;
    const t = String(tc[i] ?? "").trim();
    if (!t || isTranslationSegmentSkipped(t)) out.push(i);
  }
  return out;
}

/** 线下晤面：是否存在「含「」对白」的分段却缺有效译本（用于补译触发，避免纯叙事轮被误判缺译）。 */
function offlineAssistantTranslationRepairNeeded(replyJoined, transJoined) {
  return offlineMissingDialogueTranslationIndices(replyJoined, transJoined).length > 0;
}

/** IM 对照：lineTranslations 缺失或全不可见时触发补译（线下走正文内对照，不在此补）。 */
function assistantLineTranslationsIncomplete(replyJoined, transJoined) {
  const tj = String(transJoined ?? "").trim();
  return !tj || !translationJoinedHasAnyVisible(transJoined);
}

function padTranslationSegments(rawJoined, len) {
  const n = Math.max(0, Math.floor(Number(len)) || 0);
  const arr = String(rawJoined ?? "")
    .split(/\|\|\|/)
    .map((s) => String(s).trim());
  while (arr.length < n) arr.push("");
  return arr.slice(0, n);
}

/** 线下晤面：含「…」对口白才需要译本槽（其它段落灰字隐藏）。 */
function offlineAssistantSegmentNeedsParallelTranslation(seg) {
  const s = String(seg ?? "").trim();
  if (!s) return false;
  return /「[\s\S]*?」/u.test(s);
}

/** 叙事段译本强制 [SKIP]，对白段保留模型译本（须与 mainChunks 分项对齐）。 */
function offlineApplyDialogueOnlyTranslationMask(mainChunks, transChunks) {
  const n = mainChunks.length;
  const out = [];
  for (let i = 0; i < n; i++) {
    if (!offlineAssistantSegmentNeedsParallelTranslation(mainChunks[i])) {
      out.push(CHAT_TRANSLATION_SKIP_TOKEN);
    } else {
      out.push(transChunks[i] != null ? String(transChunks[i]) : "");
    }
  }
  return out;
}

/** @param {string} replyJoined @param {string} transJoined0 */
function finalizeOfflineAssistantTranslationJoined(replyJoined, transJoined0) {
  const mains = String(replyJoined ?? "")
    .split(/\|\|\|/)
    .map((s) => String(s).trim());
  if (!mains.length) return String(transJoined0 ?? "").trim();
  const tc = padTranslationSegments(transJoined0, mains.length);
  return offlineApplyDialogueOnlyTranslationMask(mains, tc).join("|||");
}

/**
 * 线下补译：按分段合并译本，只填补仍缺有效译本的对白段，避免整段覆盖丢掉前段已有译本。
 * @param {string} existingJoined
 * @param {string} incomingJoined
 * @param {string} replyJoined
 */
function mergeOfflineAssistantLineTranslations(existingJoined, incomingJoined, replyJoined) {
  const mains = String(replyJoined ?? "")
    .split(/\|\|\|/)
    .map((s) => String(s).trim());
  if (!mains.length) return String(incomingJoined ?? "").trim();
  const oldTc = padTranslationSegments(existingJoined, mains.length);
  const newTc = padTranslationSegments(incomingJoined, mains.length);
  const merged = [];
  for (let i = 0; i < mains.length; i++) {
    if (!offlineAssistantSegmentNeedsParallelTranslation(mains[i])) {
      merged.push(CHAT_TRANSLATION_SKIP_TOKEN);
      continue;
    }
    const n = String(newTc[i] ?? "").trim();
    const o = String(oldTc[i] ?? "").trim();
    const nOk = Boolean(n) && !isTranslationSegmentSkipped(n);
    const oOk = Boolean(o) && !isTranslationSegmentSkipped(o);
    merged.push(nOk ? n : oOk ? o : "");
  }
  return merged.join("|||");
}

/** @param {string} transJoined @param {string} rTrans @param {string} reply @param {boolean} dmOffline */
function applyAssistantTranslationRepairResult(transJoined, rTrans, reply, dmOffline) {
  const incoming = String(rTrans ?? "").trim();
  if (!translationJoinedHasAnyVisible(incoming)) return String(transJoined ?? "").trim();
  if (dmOffline) return mergeOfflineAssistantLineTranslations(transJoined, incoming, reply);
  return incoming;
}

/**
 * 线下「仅补 lineTranslations」共用的 system 提示。
 * @param {object|null} thread
 * @param {{ subset?: boolean }} [opts]
 */
function buildOfflineLineTranslationsOnlySystemPrompt(thread, opts) {
  const th = thread && typeof thread === "object" ? thread : null;
  const char = readCharPersona();
  const dlg = String(char?.dialogueLang || "").trim() || "中文";
  const reader = getThreadCharTranslationTargetLang(th);
  const tone = getThreadCharTranslationTone(th);
  const toneDesc =
    tone === "literal"
      ? "偏直译：尽量保留语序与隐喻，少意译发挥。"
      : "偏口语：自然顺耳，可换语气词与说法，但不改事实、不编造剧情。";
  const head = opts?.subset
    ? "你将收到一个 lines 数组（晤面聊天气泡原文的子集，均为仍缺译本的对白段）。"
    : "你将收到一个 lines 数组（晤面聊天气泡原文）。";
  return [
    head,
    "任务：为每条 lines[i] 生成 lineTranslations[i]。",
    "",
    "只输出一个 JSON 对象，必须包含键：",
    "- lineTranslations: string[]（长度必须与 lines 相同）",
    "",
    `lines[i] 中凡不在「」内的文字须为**简体中文**；纯叙事段译本填 ${CHAT_TRANSLATION_SKIP_TOKEN}，勿把叙事译成外文。`,
    `译成目标：${reader}；对白主要语言：${dlg}；**仅有说出口的对白**需要译本。译文风格：${toneDesc}`,
    `规则：若 lines[i] 正文里**完全没有**中文直角引号「」包裹的对白，则 lineTranslations[i] **必须**为精确字符串 ${CHAT_TRANSLATION_SKIP_TOKEN}（不得为空串）。`,
    `若 lines[i] 含有「」对白：lineTranslations[i] **只翻译说出口的字**（「」内及紧贴的语气），**不要翻译叙事描写**${
      opts?.subset ? "；**不得为空、不得误填 " + CHAT_TRANSLATION_SKIP_TOKEN + "**" : ""
    }。`,
    "lines[i] 中的【表情包】等为界面指令：lineTranslations[i] 填 [SKIP]，勿写【表情包：…】。",
    "禁止输出 markdown 代码围栏；禁止输出 thinking；禁止输出解释性文字。"
  ].join("\n");
}

/**
 * 线下：仅对仍缺译本的对白分段发起补译（常见为末尾几句）。
 * @param {string} replyJoined
 * @param {string} transJoined
 * @param {object|null} thread
 * @returns {{ messages: { role: string, content: string }[], indices: number[] } | null}
 */
function buildOfflineMissingTranslationOnlyMessages(replyJoined, transJoined, thread) {
  const indices = offlineMissingDialogueTranslationIndices(replyJoined, transJoined);
  if (!indices.length) return null;
  const mains = String(replyJoined ?? "")
    .split(/\|\|\|/)
    .map((s) => String(s).trim());
  const lines = indices.map((i) => mains[i] ?? "");
  if (!lines.some((s) => String(s).trim())) return null;
  return {
    messages: [
      { role: "system", content: buildOfflineLineTranslationsOnlySystemPrompt(thread, { subset: true }) },
      { role: "user", content: JSON.stringify({ lines }, null, 0) }
    ],
    indices
  };
}

/**
 * 把「缺译子集补译」结果按原下标写回完整译本串。
 * @param {string} replyJoined
 * @param {string} transJoined
 * @param {readonly number[]} indices
 * @param {string} partialJoined
 */
function mergeOfflinePartialTranslationAtIndices(replyJoined, transJoined, indices, partialJoined) {
  const mains = String(replyJoined ?? "")
    .split(/\|\|\|/)
    .map((s) => String(s).trim());
  if (!mains.length || !indices.length) return String(transJoined ?? "").trim();
  const partial = padTranslationSegments(partialJoined, indices.length);
  const sparse = mains.map(() => "");
  for (let j = 0; j < indices.length; j++) {
    const i = indices[j];
    if (i >= 0 && i < sparse.length) sparse[i] = String(partial[j] ?? "");
  }
  return finalizeOfflineAssistantTranslationJoined(
    replyJoined,
    mergeOfflineAssistantLineTranslations(transJoined, sparse.join("|||"), replyJoined)
  );
}

/**
 * 线下：常规补译后仍缺对白译本时，仅对缺译分段再补一次（常见为末尾几句）。
 * @param {ReturnType<typeof window.RP_AI>} ai
 * @param {string} reply
 * @param {string} transJoined
 * @param {object|null} thread
 * @param {number|null|undefined} maxTok
 */
async function tryRepairOfflineMissingTailTranslations(ai, reply, transJoined, thread, maxTok) {
  let out = String(transJoined ?? "").trim();
  if (!ai || !offlineAssistantTranslationRepairNeeded(reply, out)) return out;
  const pack = buildOfflineMissingTranslationOnlyMessages(reply, out, thread);
  if (!pack) return out;
  try {
    const data = await ai.chatCompletions({
      messages: pack.messages,
      ...spreadOptionalMaxTokens(maxTok),
      response_format: { type: "json_object" }
    });
    rememberChatApiUsage(data?.usage);
    const raw = readChatCompletionChoiceText(data);
    if (!raw) return out;
    const st = stripCharLockPlainProtocolBlocksFromText(raw);
    const { lineTranslationsJoined: tOnly } = parseAssistantPayloadForDmSurface(st.text, "offline", raw);
    if (!translationJoinedHasAnyVisible(tOnly)) return out;
    out = mergeOfflinePartialTranslationAtIndices(reply, out, pack.indices, String(tOnly || "").trim());
  } catch (_) {
    /* ignore */
  }
  return out;
}

/**
 * 去掉 `|||` 里「主文 trim 后为空，且（无译文列或译文 trim 为空或为 [SKIP]）」的槽位，避免气泡叠出空白块。
 * @param {string} mainJoined
 * @param {string} transJoined
 * @returns {{ main: string, trans: string }}
 */
function collapseEmptyParallelAssistantSegments(mainJoined, transJoined) {
  const mains = String(mainJoined ?? "").split(/\|\|\|/);
  const trSrc = String(transJoined ?? "");
  const useTrans = Boolean(trSrc.trim());
  const paras = useTrans ? trSrc.split(/\|\|\|/) : null;
  const n = paras ? Math.max(mains.length, paras.length) : mains.length;
  if (n <= 0) return { main: String(mainJoined ?? "").trimEnd(), trans: trSrc };
  const outM = [];
  const outP = [];
  for (let i = 0; i < n; i++) {
    const mRaw = mains[i] !== undefined ? String(mains[i]) : "";
    const mTrim = mRaw.trim();
    const pRaw = paras && paras[i] !== undefined ? String(paras[i]) : "";
    const pTrim = pRaw.trim();
    const drop = !mTrim && (!paras || !pTrim || isTranslationSegmentSkipped(pRaw));
    if (drop) continue;
    outM.push(mRaw);
    if (paras) outP.push(pRaw);
  }
  return { main: outM.join("|||"), trans: paras ? outP.join("|||") : trSrc };
}

/** 模型 lines 为空或 JSON 截断时，补一次只要 lines 的轻量重试。 */
function buildChatLinesOnlyRepairMessages(rawReply, dmSurface = "im") {
  const offline = dmSurface === "offline";
  const sys = offline
    ? [
        "你将收到一段当面晤面模型输出（可能是不完整 JSON）。",
        "任务：只输出 **一个** JSON 对象，**必填** lines（字符串数组，至少 1 条非空小说段落）。",
        "正文只能写在 lines；**禁止** narration、narrator、narrative 等键。",
        "若原文里已有可恢复的 lines 片段，请原样整理进 lines；不要编造与原文无关的新剧情。",
        "可选保留 heartVoice 等键；但 **lines 优先**，不得省略或留空数组。",
        "禁止 markdown 代码围栏；禁止解释性文字。"
      ].join("\n")
    : [
        "你将收到一段聊天模型输出（可能是不完整 JSON 或只有 speakAs / 心声键）。",
        "任务：只输出 **一个** JSON 对象，**必填** lines（字符串数组，至少 1 条非空、可展示的对白/叙述）。",
        "若原文里已有可恢复的 lines 片段，请原样整理进 lines；不要编造与原文无关的新剧情。",
        "可选保留 speakAs、heartVoice、narration 等其它键；但 **lines 优先**，不得省略或留空数组。",
        "禁止 markdown 代码围栏；禁止解释性文字。"
      ].join("\n");
  const user = ["【模型原文】", String(rawReply || "").trim().slice(0, 14_000)].join("\n");
  return [
    { role: "system", content: sys },
    { role: "user", content: user }
  ];
}

/**
 * @param {ReturnType<typeof window.RP_AI>} ai
 * @param {string} rawReply
 * @param {number|null|undefined} maxTok
 * @param {"im"|"offline"} [dmSurface="im"]
 */
async function tryRepairAssistantLinesOnly(ai, rawReply, maxTok, dmSurface = "im", signal) {
  const raw = String(rawReply || "").trim();
  if (!raw || raw.length < 4) return null;
  const looksAssistantJson =
    /"(?:lines|speakAs|heartVoice|narration|replies|reply)\s*"\s*:/i.test(raw) ||
    (/^\s*\{/.test(raw) && raw.includes('"'));
  if (!looksAssistantJson) return null;
  const surf = dmSurface === "offline" ? "offline" : "im";
  const tok =
    maxTok != null && Number.isFinite(Number(maxTok))
      ? Math.min(2048, Number(maxTok))
      : surf === "offline"
        ? null
        : 2048;
  try {
    const repData = await requestChatAssistantCompletion(ai, {
      messages: buildChatLinesOnlyRepairMessages(raw, surf),
      ...spreadOptionalMaxTokens(tok),
      response_format: { type: "json_object" },
      signal
    });
    const repRaw = readChatCompletionChoiceText(repData);
    if (!repRaw) return null;
    const repSt = stripCharLockPlainProtocolBlocksFromText(repRaw);
    const parsed = parseAssistantPayloadForDmSurface(repSt.text, surf, repRaw);
    if (!String(parsed.reply || "").trim()) return null;
    return { parsed, repRaw };
  } catch (e) {
    if (isChatAssistAbortError(e)) throw e;
    return null;
  }
}

/**
 * 对照翻译缺失/无效时的结构化修补。
 * @param {string} rawReply
 * @param {object|null} thread
 * @param {"im"|"offline"} dmSurface 当面晤面须传 **offline**，否则补译易按「纯 IM 短气泡」剥离叙事。
 */
function buildChatTranslationRepairMessages(rawReply, thread, dmSurface) {
  const th = thread && typeof thread === "object" ? thread : null;
  const surf = dmSurface === "offline" ? "offline" : "im";
  const char = readCharPersona();
  const dlg = String(char?.dialogueLang || "").trim() || "中文";
  const reader = getThreadCharTranslationTargetLang(th);
  const tone = getThreadCharTranslationTone(th);
  const toneDesc =
    tone === "literal"
      ? "偏直译：尽量保留语序与隐喻，少意译发挥。"
      : "偏口语：自然顺耳，可换语气词与说法，但不改事实、不编造剧情。";
  const linesRule =
    surf === "offline"
      ? `- lines: string[]（**当面晤面**：每项常含**可见的环境/动作/神态与对白**，可在同一项内用换行交织；按**节拍切换**拆分，**禁止**为凑短气泡删掉叙事白描、把每项收窄成只剩「」对白。**「」外叙事须为简体中文**。**允许约 4～22 项**（节拍多时可略增），禁止把多场戏压成一整坨；不要加新信息、不要删减原文已有的场面信息）`
      : `- lines: string[]（把原文拆成 1~8 条短气泡；不要合并成一坨；不要加新信息）`;
  const offlineExtras =
    surf === "offline"
      ? [
          `当面晤面补译：**不要把叙事译进译本**；叙事段正文须为**简体中文**，若原文叙事段混入了外文请改回中文后再输出 lines。正文里若无「」对白 → lineTranslations[i] **必须**为精确字符串 ${CHAT_TRANSLATION_SKIP_TOKEN}。`,
          `正文里若有「」说出口对白 → lineTranslations[i] **只翻译对白**（「」内及紧贴的语气），译成 ${reader}；保留 lines 叙事原文不动（叙事须中文）。`
        ]
      : [];
  const sys = [
    "你将收到一段“聊天回复原文”（可能含多段、多句、换行）。",
    "任务：把它整理成适合手机聊天气泡展示的结构化 JSON。",
    "",
    "只输出一个 JSON 对象，必须包含键：",
    linesRule,
    `- lineTranslations: string[]（${
      surf === "offline"
        ? `长度必须与 lines 相同；**不含「」对白**的纯叙事分段填精确字符串 ${CHAT_TRANSLATION_SKIP_TOKEN}；**含「」对白**的分段只填对白译本（${reader}），禁止翻译叙事描写`
        : `长度必须与 lines 相同；每项为译成「${reader}」的译文`
    }）`,
    "",
    `对话主要语言：${dlg}。译文风格：${toneDesc}`,
    ...(surf === "offline"
      ? [
          `当面晤面：对白译本也必须遵守上文译文风格；纯叙事分段只允许 ${CHAT_TRANSLATION_SKIP_TOKEN}，不得为空串。`,
          `含对白分段：译本不得为空、不得误填 ${CHAT_TRANSLATION_SKIP_TOKEN}（须给出对白外文）。`
        ]
      : [
          `要求：只要开启了对照翻译，每条 lines[i] 都必须有一条可显示的译文 lineTranslations[i]（不得为空、不得写 [SKIP]）。`,
          `即便 lines[i] 已经是「${reader}」，也请给出等价改写/同义表达的译文（允许与原文完全相同，但不能是空或 [SKIP]）。`
        ]),
    "lines[i] 中的【表情包】/【表情包：…】等为界面指令：必须在同一分段内原样保留（勿删、勿改写成叙述）；对应 lineTranslations[i] **必须**为精确字符串 [SKIP]（勿在译本里写【表情包：…】或编造表情描述）。",
    ...offlineExtras,
    "禁止输出 markdown 代码围栏；禁止输出 thinking；禁止输出解释性文字。",
    "若输入是完整 JSON：只根据其中的聊天气泡正文整理 lines；输出 JSON **仅含** lines 与 lineTranslations 两个键，**不要**输出或翻译 heartVoice、innerState、mood、desire、affectionDesc、affinity（心声手记不走翻译通道）。"
  ].join("\n");
  const user = ["【聊天回复原文】", String(rawReply || "").trim()].join("\n");
  return [
    { role: "system", content: sys },
    { role: "user", content: user }
  ];
}

function buildChatTranslationOnlyMessages(linesJoined, thread, dmSurface) {
  const th = thread && typeof thread === "object" ? thread : null;
  const surf = dmSurface === "offline" ? "offline" : "im";
  const char = readCharPersona();
  const dlg = String(char?.dialogueLang || "").trim() || "中文";
  const reader = getThreadCharTranslationTargetLang(th);
  const tone = getThreadCharTranslationTone(th);
  const toneDesc =
    tone === "literal"
      ? "偏直译：尽量保留语序与隐喻，少意译发挥。"
      : "偏口语：自然顺耳，可换语气词与说法，但不改事实、不编造剧情。";
  const allLines = String(linesJoined || "")
    .split(/\|\|\|/)
    .map((x) => String(x).trim())
    .filter(Boolean);
  const lines = surf === "offline" ? allLines : allLines.slice(0, 16);
  const sys =
    surf === "offline"
      ? buildOfflineLineTranslationsOnlySystemPrompt(th)
      : [
          "你将收到一个 lines 数组（聊天气泡原文）。",
          "任务：为每条 lines[i] 生成一条可展示的译文 lineTranslations[i]。",
          "",
          "只输出一个 JSON 对象，必须包含键：",
          "- lineTranslations: string[]（长度必须与 lines 相同）",
          "",
          `译成：${reader}。对话主要语言：${dlg}。译文风格：${toneDesc}`,
          "lines[i] 中的【表情包】/【表情包：…】等为界面指令：必须在同一分段内原样保留；对应 lineTranslations[i] 填 [SKIP]，勿写【表情包：…】。",
          "要求：每一项 lineTranslations[i] 必须为完整译文，不得为空、不得写 [SKIP]、不得写 SKIP。",
          "禁止输出 markdown 代码围栏；禁止输出 thinking；禁止输出解释性文字。"
        ].join("\n");
  const user = JSON.stringify({ lines }, null, 0);
  return [
    { role: "system", content: sys },
    { role: "user", content: user }
  ];
}

function stripParallelRecallMatching(replyJoined, transJoined, recalls) {
  const norm = (t) => String(t || "").replace(/\s+/g, " ").trim();
  const drop = new Set(recalls.map((r) => norm(r.recalledContent)).filter(Boolean));
  if (!drop.size) {
    return { reply: String(replyJoined || "").trim(), trans: String(transJoined || "").trim() };
  }
  const rp = String(replyJoined || "")
    .split(/\|\|\|/)
    .map((p) => p.trim())
    .filter(Boolean);
  const tp0 = String(transJoined || "")
    .split(/\|\|\|/)
    .map((p) => p.trim());
  const tp = rp.map((_, i) => (i < tp0.length ? tp0[i] : ""));
  const keptRp = [];
  const keptTp = [];
  for (let i = 0; i < rp.length; i++) {
    if (drop.has(norm(rp[i]))) continue;
    keptRp.push(rp[i]);
    keptTp.push(tp[i] || "");
  }
  return { reply: keptRp.join("|||"), trans: keptTp.join("|||") };
}

function stripParallelRecallNarration(replyJoined, transJoined, recalls) {
  if (!Array.isArray(recalls) || !recalls.length) {
    return { reply: String(replyJoined || "").trim(), trans: String(transJoined || "").trim() };
  }
  const normSeg = (t) =>
    String(t || "")
      .replace(/[|\u007c\uFF5C\s　]+$/g, "")
      .replace(/\s+/g, " ")
      .trim();
  const isMeta = (p) => {
    const n = normSeg(p);
    if (!n) return true;
    if (/撤回了一条消息/.test(n)) return true;
    if (/^我(刚刚|刚才)?撤回了?[。.!！…~～\s]*$/u.test(n)) return true;
    if (/^撤回了?[。.!！…~～\s]*$/u.test(n)) return true;
    return false;
  };
  const rp = String(replyJoined || "")
    .split(/\|\|\|/)
    .map((x) => String(x).trim())
    .filter((x) => x.length > 0);
  const tp0 = String(transJoined || "")
    .split(/\|\|\|/)
    .map((p) => p.trim());
  const tp = rp.map((_, i) => (i < tp0.length ? tp0[i] : ""));
  const keptRp = [];
  const keptTp = [];
  for (let i = 0; i < rp.length; i++) {
    if (isMeta(rp[i])) continue;
    keptRp.push(rp[i]);
    keptTp.push(tp[i] || "");
  }
  return { reply: keptRp.join("|||"), trans: keptTp.join("|||") };
}

/** 顶栏装饰原文（可含 `{{char}}`/`{{user}}`）；密谈未设则回落全局默认。不进模型。 */
function getEffectiveThreadScenePrompt(thread) {
  const D = window.XXJ_DB;
  const sceneRaw = D ? D.getKv(D.SCENE_PROMPT) : "";
  const g = sceneRaw && String(sceneRaw).trim() ? String(sceneRaw).trim() : SCENE_PROMPT_DEFAULT;
  if (!thread || thread.scenePrompt == null) return g;
  const t = String(thread.scenePrompt).trim();
  return t || g;
}

/** 顶栏展示：替换占位符并截断。 */
function getTopbarDecorDisplayLine(thread) {
  const th = thread && typeof thread === "object" ? thread : readActiveThread();
  const raw = getEffectiveThreadScenePrompt(th);
  const char = readCharPersona();
  const mask = readUserMask();
  const personaName = (char.displayName && String(char.displayName).trim()) || "角色";
  const charNm = String(th?.charThreadRemarkName || "").trim()
    ? personaName
    : getThreadCharDisplayAlias(th) || personaName;
  const userNm = (mask.displayName && String(mask.displayName).trim()) || "对方";
  const t = replaceCharUserWorldBookPlaceholders(raw, charNm, userNm).trim();
  if (!t) return "";
  return t.length > 160 ? `${t.slice(0, 160)}…` : t;
}

/**
 * SillyTavern 式占位：世界书/卡文中 `{{char}}`、`{{user}}` 在并入模型前替换为当前密谈角色名与主控名。
 * @param {string} text
 * @param {string} charDisplayName 与系统提示「你是某某本人」一致的角色称呼
 * @param {string} userDisplayName 主控面具显示名（与「对方是某某」一致）
 */
function replaceCharUserWorldBookPlaceholders(text, charDisplayName, userDisplayName) {
  const c = String(charDisplayName || "").trim() || "角色";
  const u = String(userDisplayName || "").trim() || "对方";
  return String(text ?? "")
    .replace(/\{\{\s*char\s*\}\}/gi, c)
    .replace(/\{\{\s*user\s*\}\}/gi, u);
}

function buildWorldBookBlockForVolumeId(volumeId, charDisplayName, userDisplayName) {
  const id = String(volumeId || "").trim();
  if (!id) return "";
  const vol = getWorldBookVolumeById(id);
  if (!vol || !Array.isArray(vol.entries)) return "";
  const repl = (s) => replaceCharUserWorldBookPlaceholders(s, charDisplayName, userDisplayName);
  const parts = [];
  for (const e of vol.entries) {
    if (!e || e.enabled === false) continue;
    const bodyRaw = repl(String(e.content || "").trim());
    const body = proseContentLooksLikeHtml(bodyRaw) ? htmlToPlainTextForPrompt(bodyRaw) : bodyRaw;
    if (!body) continue;
    const title = repl(String(e.title || "").trim());
    const keys = repl(String(e.keywords || "").trim());
    const head = [keys ? `〔${keys}〕` : "", title].filter(Boolean).join(" ");
    parts.push(head ? `${head}\n${body}` : body);
  }
  if (!parts.length) return "";
  const vtitle = repl(String(vol.title || "").trim() || "世界书");
  const tag = vol.scope === "global" ? "（全局 · 无需密谈绑定）" : "（本密谈绑定）";
  return `[世界书 · ${vtitle}${tag}]\n${parts.join("\n\n—\n\n")}`;
}

function getThreadWorldBookVolumeIds(thread) {
  const arr = Array.isArray(thread?.worldBookVolumeIds) ? thread.worldBookVolumeIds : [];
  const out = arr.map((x) => String(x || "").trim()).filter(Boolean).slice(0, 8);
  const legacy = thread?.worldBookVolumeId ? String(thread.worldBookVolumeId).trim() : "";
  if (!out.length && legacy) return [legacy];
  return out;
}

/** 本密谈「当面晤面」追加局部世界书（≤8）；叠加在密谈详情绑定之上，仅线下注入。 */
function getThreadOfflineWorldBookVolumeIds(thread) {
  const arr = Array.isArray(thread?.offlineWorldBookVolumeIds) ? thread.offlineWorldBookVolumeIds : [];
  return arr.map((x) => String(x || "").trim()).filter(Boolean).slice(0, 8);
}

/** 书架顺序下所有「全局」世界书卷 id（发消息时自动并入系统提示，无需密谈勾选）。 */
function getGlobalWorldBookVolumeIds() {
  const store = readWorldBookStore();
  const vols = Array.isArray(store.volumes) ? store.volumes : [];
  return vols
    .filter((v) => v && v.scope === "global")
    .map((v) => String(v.id || "").trim())
    .filter(Boolean);
}

function patchChatThreadForMask(maskId, threadId, mutator) {
  const mid = String(maskId || "").trim();
  const tid = String(threadId || "").trim();
  if (!mid || !tid) return false;
  const inbox = readChatInboxStore();
  const found = findChatThreadInInbox(mid, tid);
  if (!found) return false;
  mutator(found.thread);
  found.thread.updatedAt = Date.now();
  writeChatInboxStore(inbox);
  return true;
}

/**
 * 本密谈绑定的局部卷优先；offline 时再叠加 offlineWorldBookVolumeIds；最后拼全局卷。去重后最多 8 本。
 * @param {unknown} thread
 * @param {{ surface?: "im" | "offline" }} [opts]
 */
function getEffectiveThreadWorldBookVolumeIds(thread, opts) {
  const globalIds = getGlobalWorldBookVolumeIds();
  const slot = getThreadActivePersona(thread);
  const offlineSurface = opts && opts.surface === "offline";
  const bound = getPersonaBoundWorldBookVolumeIds(thread, slot);
  const offlineExtra = offlineSurface ? getThreadOfflineWorldBookVolumeIds(thread) : [];
  const uniq = [];
  const seen = new Set();
  const push = (id) => {
    const s = String(id || "").trim();
    if (!s || seen.has(s)) return;
    seen.add(s);
    uniq.push(s);
  };
  for (const id of bound) {
    push(id);
    if (uniq.length >= 8) break;
  }
  if (offlineSurface && uniq.length < 8) {
    for (const id of offlineExtra) {
      push(id);
      if (uniq.length >= 8) break;
    }
  }
  if (uniq.length < 8) {
    for (const id of globalIds) {
      push(id);
      if (uniq.length >= 8) break;
    }
  }
  return uniq;
}

/** 角色档案绑定世界书 + 全局卷（无密谈 thread 时，如关系网私聊）。 */
function getEffectiveCharWorldBookVolumeIds(charItem) {
  const globalIds = getGlobalWorldBookVolumeIds();
  const bound = getCharMainWorldBookVolumeIds(charItem);
  const uniq = [];
  const seen = new Set();
  const push = (id) => {
    const s = String(id || "").trim();
    if (!s || seen.has(s)) return;
    seen.add(s);
    uniq.push(s);
  };
  for (const id of bound) {
    push(id);
    if (uniq.length >= 8) break;
  }
  if (uniq.length < 8) {
    for (const id of globalIds) {
      push(id);
      if (uniq.length >= 8) break;
    }
  }
  return uniq;
}

function buildCharWorldBookBlockForPrompt(charItem, charDisplayName, userDisplayName) {
  return buildWorldBookBlockForVolumeIds(
    getEffectiveCharWorldBookVolumeIds(charItem),
    charDisplayName,
    userDisplayName
  );
}

function buildWorldBookBlockForVolumeIds(volumeIds, charDisplayName, userDisplayName) {
  const ids = Array.isArray(volumeIds) ? volumeIds.map((x) => String(x || "").trim()).filter(Boolean) : [];
  if (!ids.length) return "";
  const uniq = Array.from(new Set(ids)).slice(0, 8);
  return uniq
    .map((id) => buildWorldBookBlockForVolumeId(id, charDisplayName, userDisplayName))
    .filter(Boolean)
    .join("\n\n");
}

function patchActiveThread(mutator) {
  const D = window.XXJ_DB;
  if (!D) return false;
  reconcileActiveThreadRef();
  const maskId = getActiveMaskIdForInbox();
  const ref = readChatActiveThreadRef();
  const inbox = readChatInboxStore();
  ensureMaskBucket(inbox, maskId);
  const bucket = inbox.byMask[maskBucketKey(maskId)];
  const th = bucket.threads.find((t) => t.id === ref.threadId);
  if (!th) return false;
  mutator(th);
  th.updatedAt = Date.now();
  writeChatInboxStore(inbox, {
    fast: true,
    dirtyThreadKey: chatDirtyThreadPersistKey(maskId, ref.threadId)
  });
  return true;
}

function formatMomentListTime(iso) {
  try {
    const d = new Date(iso);
    if (Number.isNaN(d.getTime())) return "—";
    return `${d.getMonth() + 1}月${d.getDate()}日 ${String(d.getHours()).padStart(2, "0")}:${String(
      d.getMinutes()
    ).padStart(2, "0")}`;
  } catch {
    return "—";
  }
}

function getMomentDisplayLabel(m) {
  const kind = m?.kind === "user" ? "user" : "char";
  if (kind === "user") return "我";
  const nm = String(m?.displayName || "未命名角色").trim();
  return nm || "—";
}

function getMomentAvatarUrl(m) {
  const kind = m?.kind === "user" ? "user" : "char";
  if (kind === "user") {
    const st = readUserMaskStore();
    const slot = st.items.find((x) => x.id === st.activeId);
    return String(slot?.avatar || "").trim();
  }
  const cid = String(m?.charId || "").trim();
  const personaSlot = getMomentPostPersonaSlot(m);
  const charItem = cid ? getCharPersonaItemById(cid) : null;
  if (charItem) {
    const av = resolvePersonaAvatar(charItem, personaSlot);
    if (av) return av;
  }
  const st = readCharPersonaStore();
  if (cid) {
    const byId = st.items.find((x) => String(x.id || "") === cid);
    if (byId) return String(byId.avatar || "").trim();
  }
  const nm = String(m?.displayName || "").trim();
  if (!nm) return "";
  const it = st.items.find((x) => String(x?.displayName || "").trim() === nm);
  return String(it?.avatar || "").trim();
}

function buildMomentsPostMedia(host, mm) {
  const descCards = getMomentPostImageDescCards(mm);
  const imgs = (Array.isArray(mm.images) ? mm.images : [])
    .map((x) => sanitizeMomentImageUrl(String(x || "").trim()))
    .filter(Boolean)
    .slice(0, MOMENTS_POST_MAX_IMAGES);
  const slots = [];
  for (const cap of descCards) slots.push({ kind: "desc", caption: cap });
  for (const url of imgs) slots.push({ kind: "img", url });
  if (!slots.length) return;
  const wrap = document.createElement("div");
  const n = slots.length;
  const descOnly = slots.every((s) => s.kind === "desc");
  wrap.className =
    "moments-post-media" +
    (n === 1 ? " moments-post-media--1" : n <= 4 ? " moments-post-media--few" : " moments-post-media--many") +
    (descOnly ? " moments-post-media--desc-only" : "");
  let imgIdx = 0;
  for (let i = 0; i < slots.length; i++) {
    const slot = slots[i];
    if (slot.kind === "desc") {
      const fig = document.createElement("div");
      fig.className = "moments-media moments-media--desc-card";
      fig.setAttribute("role", "figure");
      fig.setAttribute("aria-label", "文字描述配图");
      fig.appendChild(
        buildChatPhotoDescCardShell({ caption: slot.caption, stripMeta: true })
      );
      wrap.appendChild(fig);
      continue;
    }
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "moments-media";
    btn.dataset.imgIdx = String(imgIdx);
    imgIdx += 1;
    btn.setAttribute("aria-label", `查看配图 ${imgIdx}`);
    const im = document.createElement("img");
    im.alt = "";
    im.loading = imgIdx <= 2 ? "eager" : "lazy";
    im.decoding = "async";
    applyChatImageUrlToElement(im, slot.url);
    im.onerror = () => {
      btn.classList.add("moments-media--broken");
    };
    btn.appendChild(im);
    wrap.appendChild(btn);
  }
  host.appendChild(wrap);
}

function formatMomentsLikeLabel(liked, likeCnt) {
  const n = Math.max(0, Math.floor(Number(likeCnt) || 0));
  const effective = liked && n < 1 ? 1 : n;
  if (effective <= 0) return "";
  return effective === 1 ? "1 次赞" : `${effective} 次赞`;
}

function buildMomentsPostActions(body, mm) {
  const bar = document.createElement("div");
  bar.className = "moments-post-actions";
  const liked = mm.likedByMe === true;
  const mk = (act, iconClass, label, extra) => {
    const b = document.createElement("button");
    b.type = "button";
    b.className = "moments-post-act" + (extra || "");
    b.dataset.act = act;
    b.setAttribute("aria-label", label);
    b.innerHTML = `<i class="${iconClass}" aria-hidden="true"></i>`;
    return b;
  };
  bar.append(
    mk("like", liked ? "ph-fill ph-heart" : "ph ph-heart", "赞", liked ? " is-liked" : ""),
    mk("comment", "ph ph-chat-circle", "评论"),
    mk("share", "ph ph-paper-plane-tilt", "分享")
  );
  body.appendChild(bar);
}

function buildMomentsPostFooter(body, mm) {
  const liked = mm.likedByMe === true;
  const likeCnt = Math.max(0, Math.floor(Number(mm.likeCount) || 0));
  const cmts = Array.isArray(mm.comments) ? mm.comments : [];
  const momentId = String(mm.id || "");
  const displayName = getMomentDisplayLabel(mm);
  const text = getMomentPostDisplayText(mm);

  if (text) {
    const cap = document.createElement("p");
    cap.className = "moments-post-caption";
    const user = document.createElement("span");
    user.className = "moments-post-caption-user";
    user.textContent = displayName + " ";
    const txt = document.createElement("span");
    txt.className = "moments-post-caption-text";
    txt.textContent = text;
    cap.append(user, txt);
    body.appendChild(cap);
  }

  buildMomentsPostActions(body, mm);

  const likeLabel = formatMomentsLikeLabel(liked, likeCnt);
  if (likeLabel) {
    const likes = document.createElement("p");
    likes.className = "moments-post-likes";
    likes.textContent = likeLabel;
    body.appendChild(likes);
  }

  if (cmts.length) {
    const list = document.createElement("div");
    list.className = "moments-post-cmts";
    list.setAttribute("aria-label", "评论");
    for (const c of cmts.slice(-80)) {
      const line = document.createElement("p");
      line.className = "moments-post-cmt";
      const name = document.createElement("span");
      name.className = "moments-post-cmt-user";
      name.textContent = String(c.authorName || "—");
      const bodySpan = document.createElement("span");
      bodySpan.className = "moments-post-cmt-text";
      const replyTo = String(c.replyToCommentId || "").trim();
      if (replyTo) {
        const tgt = cmts.find((x) => String(x?.id || "") === replyTo);
        const who = tgt ? String(tgt.authorName || "—") : "—";
        const at = document.createElement("span");
        at.className = "moments-post-cmt-at";
        at.textContent = who;
        bodySpan.append(document.createTextNode("回复 "), at, document.createTextNode(" " + String(c.text || "")));
      } else {
        bodySpan.textContent = String(c.text || "");
      }
      const actions = document.createElement("span");
      actions.className = "moments-post-cmt-actions";
      const rep = document.createElement("button");
      rep.type = "button";
      rep.className = "moments-post-cmt-reply";
      rep.textContent = "回复";
      rep.dataset.replyCommentId = String(c.id || "");
      const del = document.createElement("button");
      del.type = "button";
      del.className = "moments-post-cmt-del";
      del.textContent = "删除";
      del.setAttribute("aria-label", "删除评论");
      del.dataset.deleteCommentId = String(c.id || "");
      actions.append(rep, del);
      line.dataset.commentId = String(c.id || "");
      line.append(name, document.createTextNode(" "), bodySpan, actions);
      list.appendChild(line);
    }
    body.appendChild(list);
  }

  const when = document.createElement("time");
  when.className = "moments-post-time";
  when.dateTime = String(mm.timeIso || "");
  when.textContent = formatMomentListTime(String(mm.timeIso || ""));
  body.appendChild(when);

  const form = document.createElement("form");
  form.className = "moments-post-composer";
  if (momentsInlineReply.momentId === momentId) form.classList.add("is-open");
  form.dataset.momentId = momentId;
  const inp = document.createElement("input");
  inp.type = "text";
  inp.className = "moments-post-composer-input";
  inp.dataset.momentInput = momentId;
  inp.maxLength = MOMENTS_COMMENT_MAX_LEN;
  inp.autocomplete = "off";
  inp.spellcheck = false;
  const replying =
    momentsInlineReply.momentId === momentId && momentsInlineReply.commentId;
  if (replying) {
    const tgt = cmts.find((x) => String(x?.id || "") === momentsInlineReply.commentId);
    inp.placeholder = tgt ? `回复 ${String(tgt.authorName || "—")}…` : "添加评论…";
    } else {
    inp.placeholder = "添加评论…";
  }
  const send = document.createElement("button");
  send.type = "submit";
  send.className = "moments-post-composer-post";
  send.textContent = "发布";
  send.setAttribute("aria-label", "发布评论");
  form.append(inp, send);
  body.appendChild(form);
}

function focusMomentsInlineComposer(momentId, replyCommentId = "", retry = false) {
  const mid = String(momentId || "").trim();
  if (!mid) return;
  momentsInlineReply = {
    momentId: mid,
    commentId: String(replyCommentId || "").trim()
  };
  const esc = typeof CSS !== "undefined" && CSS.escape ? CSS.escape(mid) : mid.replace(/"/g, '\\"');
  const art = document.querySelector(`.moments-post[data-moment-id="${esc}"]`);
  if (!art) {
    if (!retry) {
      scheduleMomentsFeedRender(true);
      window.requestAnimationFrame(() => focusMomentsInlineComposer(mid, replyCommentId, true));
    }
    return;
  }
  document.querySelectorAll(".moments-post-composer.is-open").forEach((el) => {
    el.classList.remove("is-open");
  });
  const form = art.querySelector(".moments-post-composer");
  form?.classList.add("is-open");
  const inp = art.querySelector(".moments-post-composer-input");
  if (!(inp instanceof HTMLInputElement)) return;
  const { bucket } = getActiveMomentsBucket();
  const raw = Array.isArray(bucket.moments) ? bucket.moments.find((x) => String(x?.id || "") === mid) : null;
  const m = normalizeMoment(raw);
  const cmts = Array.isArray(m.comments) ? m.comments : [];
  if (momentsInlineReply.commentId) {
    const tgt = cmts.find((x) => String(x?.id || "") === momentsInlineReply.commentId);
    inp.placeholder = tgt ? `回复 ${String(tgt.authorName || "—")}…` : "添加评论…";
  } else {
    inp.placeholder = "添加评论…";
  }
  inp.focus();
  art.scrollIntoView({ block: "nearest", behavior: "smooth" });
}

function addMomentCommentInline(momentId, formEl) {
  const mid = String(momentId || "").trim();
  if (!mid || !(formEl instanceof HTMLFormElement)) return;
  const inp = formEl.querySelector(".moments-post-composer-input");
  const text = String(inp?.value || "").trim();
  if (!text) return showToast("先写点内容再发送");
    const st = readUserMaskStore();
    const slot = st.items.find((x) => x.id === st.activeId);
  const userLabel = (slot?.displayName && String(slot.displayName).trim()) || "主控";
  const replyTo =
    momentsInlineReply.momentId === mid ? String(momentsInlineReply.commentId || "").trim() : "";
  const newCommentId = newEntityId();
  const ok = patchMomentById(mid, (m) => {
    const arr = Array.isArray(m.comments) ? m.comments : [];
    arr.push({
      id: newCommentId,
      authorKind: "user",
      authorName: userLabel,
      timeIso: new Date().toISOString(),
      text: text.slice(0, MOMENTS_COMMENT_MAX_LEN),
      replyToCommentId: replyTo || ""
    });
    m.comments = arr;
  });
  if (!ok) {
    showToast("发送失败，请稍后再试");
    return;
  }
  momentsInlineReply = { momentId: "", commentId: "" };
  replaceMomentsPostInFeed(mid);
  showToast("已发出");
  const { bucket } = getActiveMomentsBucket();
  const posted = (Array.isArray(bucket.moments) ? bucket.moments : []).find((m) => String(m?.id || "") === mid);
  const pm = posted ? normalizeMoment(posted) : null;
  if (pm && pm.kind === "char") {
    const { maskId } = getActiveMomentsBucket();
    const cid = resolveMomentCharId(pm);
    const tid = String(pm.threadId || "").trim();
    const th =
      maskId && cid
        ? pickThreadForCharMoment(maskId, cid, tid) || (tid ? { id: tid } : null)
        : null;
    if (maskId && th && String(th.id || "").trim()) {
      recordMomentsFeedNoticeInChatThread(
        maskId,
        String(th.id || ""),
        `用户 ${userLabel} 评论了你的朋友圈：${text.slice(0, 80)}`
      );
    }
    queueMomentsCharReactions(async () => {
      if (!window.RP_AI?.chatCompletions || !cid) return;
      await runMomentsCharReactionForChar(mid, cid, {
        type: "user_comment",
        userCommentText: text,
        replyToCommentId: newCommentId
      });
      scheduleMomentsFeedRender(true);
    });
  }
}

function getActiveMaskForMoments() {
  const st = readUserMaskStore();
  const slot = st.items.find((x) => x.id === st.activeId) || null;
  const userMask = readUserMask();
  const displayName = String(slot?.displayName || userMask.displayName || "").trim() || "我的";
  const avatar = String(slot?.avatar || userMask.avatar || "").trim();
  return { displayName, avatar };
}

function momentRowLooksVisible(mm) {
  const m = mm && typeof mm === "object" ? mm : {};
  const hasText = Boolean(String(m.text || "").trim());
  const hasImg = (Array.isArray(m.images) ? m.images : []).some((x) => String(x || "").trim());
  return hasText || hasImg;
}

function summarizeMomentsStats(list) {
  let likes = 0;
  let comments = 0;
  let posts = 0;
  for (const m of list) {
    const mm = normalizeMoment(m);
    if (!momentRowLooksVisible(mm)) continue;
    posts += 1;
    likes += Math.max(0, Math.floor(Number(mm.likeCount) || 0));
    comments += Array.isArray(mm.comments) ? mm.comments.length : 0;
  }
  return { posts, likes, comments };
}

function renderMomentsInsProfile(list) {
  const { displayName, avatar } = getActiveMaskForMoments();
  const summary = getMomentsProfileBio();
  const stats = summarizeMomentsStats(list);
  const userEl = document.getElementById("moments-ins-username");
  if (userEl) userEl.textContent = displayName || "朋友圈";
  const av = document.getElementById("moments-ins-avatar");
  if (av) {
    av.replaceChildren();
    if (avatar) {
      const im = document.createElement("img");
      im.className = "moments-ins-avatar-img";
      im.alt = "";
      im.loading = "lazy";
      im.decoding = "async";
      im.src = avatar;
      av.appendChild(im);
    } else {
      av.textContent = displayName.slice(0, 1) || "我";
    }
  }
  const setStat = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.textContent = String(val);
  };
  setStat("moments-ins-stat-posts", stats.posts);
  const bioName = document.getElementById("moments-ins-bio-name");
  if (bioName) bioName.textContent = displayName;
  const bioLines = document.getElementById("moments-ins-bio-lines");
  if (bioLines) {
    bioLines.replaceChildren();
    const lines = summary
      .split(/\n+/)
      .map((x) => x.trim())
      .filter(Boolean)
      .slice(0, 4);
    if (!lines.length) {
      const p = document.createElement("p");
      p.className = "moments-ins-bio-line moments-ins-bio-line--hint";
      p.textContent = "写几句关于自己的话…";
      bioLines.appendChild(p);
    } else {
      for (const line of lines) {
        const p = document.createElement("p");
        p.className = "moments-ins-bio-line";
        p.textContent = line;
        bioLines.appendChild(p);
      }
    }
  }
}

function renderMomentsProfileDecor() {
  const root = document.getElementById("moments-ins-decor-slots");
  if (!root) return;
  const decor = getProfileDecor();
  root.replaceChildren();
  for (let i = 0; i < MOMENTS_DECOR_SLOTS; i++) {
    const src = decor[i];
    const slot = document.createElement("button");
    slot.type = "button";
    slot.className = "moments-ins-decor-slot" + (src ? " has-image" : "");
    slot.dataset.decorIdx = String(i);
    if (src) {
      slot.setAttribute("aria-label", `墙饰 ${i + 1}，点击更换图片`);
      const im = document.createElement("img");
      im.alt = "";
      im.loading = "eager";
      im.decoding = "async";
      applyChatImageUrlToElement(im, src);
      slot.appendChild(im);
    } else {
      slot.setAttribute("aria-label", `墙饰 ${i + 1}，点击上传图片`);
      slot.innerHTML = '<i class="ph ph-image" aria-hidden="true"></i>';
    }
    root.appendChild(slot);
  }
  scheduleProfileDecorBlobMigrationIfNeeded(decor);
}

/** 旧版墙饰若仍内联 data URL，静默外置 blob，避免第三张写入时 inbox 顶满配额。 */
function scheduleProfileDecorBlobMigrationIfNeeded(decor) {
  if (profileDecorBlobMigrationDone || profileDecorBlobMigrateScheduled) return;
  const media = window.XXJ_MEDIA;
  if (!media || typeof media.isExternalizableDataImageUrl !== "function") return;
  const arr = Array.isArray(decor) ? decor : [];
  if (!arr.some((u) => media.isExternalizableDataImageUrl(String(u || "")))) return;
  profileDecorBlobMigrateScheduled = true;
  void (async () => {
    try {
      const { inbox, maskId, bucket } = getActiveMomentsBucket();
      if (!maskId) return;
      const prev = normalizeProfileDecor(bucket.profileDecor).join("\x1e");
      const next = await externalizeProfileDecorArray(bucket.profileDecor);
      if (next.join("\x1e") === prev) return;
      bucket.profileDecor = next;
      writeChatInboxStore(inbox);
      await flushChatInboxKvPersist({ propagateError: true, force: true });
      renderMomentsProfileDecor();
    } catch (err) {
      console.warn("[moments-decor] background migrate failed", err);
    } finally {
      profileDecorBlobMigrateScheduled = false;
      profileDecorBlobMigrationDone = true;
    }
  })();
}

function triggerMomentsDecorFilePick(slotIdx) {
  momentsDecorPickIdx = Math.floor(Number(slotIdx));
  if (momentsDecorPickIdx < 0 || momentsDecorPickIdx >= MOMENTS_DECOR_SLOTS) return;
  const inp = document.getElementById("moments-decor-file");
  if (inp instanceof HTMLInputElement) inp.click();
}

function editMomentsProfileBio() {
  const maskId = getActiveMaskIdForInbox();
  if (!maskId) {
    showToast("请先创建并选择一个主控面具");
    return;
  }
  const prev = getMomentsProfileBio();
  const raw = window.prompt("写几句关于自己的话（仅朋友圈展示，不进面具人设）", prev);
  if (raw == null) return;
  const next = String(raw).trim();
  setMomentsProfileBio(next);
  const { bucket } = getActiveMomentsBucket();
  renderMomentsInsProfile(Array.isArray(bucket.moments) ? bucket.moments : []);
  showToast(next ? "朋友圈简介已更新" : "朋友圈简介已清空");
}

async function ingestMomentsDecorFile(file) {
  const idx = momentsDecorPickIdx;
  momentsDecorPickIdx = -1;
  if (idx < 0 || idx >= MOMENTS_DECOR_SLOTS || !file) return;
  if (!isImagePickFile(file)) {
    showToast("请选择图片");
    return;
  }
  if (momentsDecorBusy) return;
  momentsDecorBusy = true;
  try {
    let dataUrl = "";
    try {
      dataUrl = await readImageFileAsChatEmbeddedDataUrl(file);
    } catch {
      /* 压缩失败时仍尝试原图 */
    }
    if (!dataUrl) {
      try {
        dataUrl = String((await readImageFileAsDataUrl(file)) || "");
      } catch {
        dataUrl = "";
      }
    }
    if (!dataUrl) throw new Error("empty");
    try {
      const shrunk = await shrinkDataUrlWithCanvas(dataUrl, 720, 0.82);
      if (shrunk) dataUrl = shrunk;
    } catch {
      /* 保留原图 */
    }
    const ok = await persistProfileDecorSlot(idx, dataUrl);
    renderMomentsProfileDecor();
    if (ok) showToast("已换上墙饰");
  } catch {
    showToast("图片读取失败");
  } finally {
    momentsDecorBusy = false;
    const inp = document.getElementById("moments-decor-file");
    if (inp instanceof HTMLInputElement) inp.value = "";
  }
}

let momentsFeedRenderRaf = 0;

function isMomentsPanelActive() {
  const panel = document.getElementById("chat-list-panel-moments");
  return Boolean(
    panel && !panel.hasAttribute("hidden") && chatListScreen?.classList.contains("is-open")
  );
}

/** 合并到下一帧绘制，避免同步整页重绘卡住过场动画 */
function scheduleMomentsFeedRender(force = false) {
  if (!force && !isMomentsPanelActive()) return;
  if (momentsFeedRenderRaf) return;
  momentsFeedRenderRaf = requestAnimationFrame(() => {
    momentsFeedRenderRaf = 0;
    renderMomentsFeed();
  });
}

function replaceMomentsPostInFeed(momentId) {
  const mid = String(momentId || "").trim();
  if (!mid) return false;
  const listRoot = document.getElementById("moments-list-root");
  if (!listRoot) return false;
  const { bucket } = getActiveMomentsBucket();
  const raw = (Array.isArray(bucket.moments) ? bucket.moments : []).find(
    (m) => String(m?.id || "") === mid
  );
  if (!raw) return false;
  const mm = normalizeMoment(raw);
  if (!momentRowLooksVisible(mm)) {
    scheduleMomentsFeedRender(true);
    return true;
  }
  const esc = typeof CSS !== "undefined" && CSS.escape ? CSS.escape(mid) : mid.replace(/"/g, '\\"');
  const prev = listRoot.querySelector(`.moments-post[data-moment-id="${esc}"]`);
  const next = buildMomentsTimelineItem(mm);
  if (prev) {
    prev.replaceWith(next);
    return true;
  }
  scheduleMomentsFeedRender(true);
  return false;
}

function normalizeMaskBucketMomentsInPlace(bucket) {
  if (!bucket || !Array.isArray(bucket.moments) || !bucket.moments.length) return false;
  const next = bucket.moments.map((m) => normalizeMoment(m));
  if (!next.some((x, i) => x !== bucket.moments[i])) return false;
  bucket.moments = next;
  return true;
}

function renderMomentsFeed() {
  const feed = document.getElementById("moments-items-root");
  const listRoot = document.getElementById("moments-list-root");
  if (!feed || !listRoot) return;
  const { inbox, maskId, bucket } = getActiveMomentsBucket();
  if (normalizeMaskBucketMomentsInPlace(bucket) && maskId) {
    writeChatInboxStore(inbox, { fast: true });
  }
  const list = Array.isArray(bucket.moments) ? bucket.moments : [];
  renderMomentsInsProfile(list);
  renderMomentsProfileDecor();
  const posts = list
    .map((m) => normalizeMoment(m))
    .filter((mm) => momentRowLooksVisible(mm))
    .sort((a, b) => new Date(b.timeIso).getTime() - new Date(a.timeIso).getTime());
  listRoot.replaceChildren();
  feed.querySelector(".moments-feed-empty")?.remove();
  if (posts.length) {
    for (const mm of posts) {
      listRoot.appendChild(buildMomentsTimelineItem(mm));
    }
    listRoot.hidden = false;
  } else {
    listRoot.hidden = true;
    const empty = document.createElement("div");
    empty.className = "moments-feed-empty";
    const title = document.createElement("p");
    title.className = "moments-feed-empty-title";
    title.textContent = list.length ? "动态正文为空，可重新发一条" : "还没有动态";
    const desc = document.createElement("p");
    desc.className = "moments-feed-empty-desc";
    desc.textContent = list.length
      ? "旧数据可能只有配图指令没有正文，点右上角留一条或让角色发圈即可。"
      : "点右上角 + 留一条，或让角色发一条朋友圈。";
    empty.append(title, desc);
    feed.appendChild(empty);
  }
}

function buildMomentsTimelineItem(mm) {
  const art = document.createElement("li");
  art.className = `moments-post moments-post--${mm.kind === "user" ? "user" : "char"}`;
    art.dataset.momentId = String(mm.id || "");

  const head = document.createElement("header");
  head.className = "moments-post-head";
    const av = document.createElement("div");
  av.className = "moments-post-av";
    av.setAttribute("aria-hidden", "true");
    const avUrl = getMomentAvatarUrl(mm);
    if (avUrl) {
      const im = document.createElement("img");
    im.className = "moments-post-av-img";
      im.alt = "";
      im.loading = "lazy";
      im.decoding = "async";
      applyChatImageUrlToElement(im, avUrl);
      av.appendChild(im);
    } else {
      av.textContent = mm.kind === "user" ? "我" : "角";
    }
  const { maskId } = getActiveMomentsBucket();
  const userWrap = document.createElement("div");
  userWrap.className = "moments-post-user-wrap";
  const user = document.createElement("span");
  user.className = "moments-post-user";
  user.textContent = getMomentDisplayLabel(mm);
  userWrap.appendChild(user);
  if (mm.kind === "char") {
    const remark = resolveMomentThreadRemark(mm, maskId);
    if (remark) {
      const sub = document.createElement("span");
      sub.className = "moments-post-thread-remark";
      sub.textContent = remark;
      userWrap.appendChild(sub);
    }
  }
  head.append(av, userWrap);
  appendMomentsPostMoreMenu(head, mm);

  const imgs = (Array.isArray(mm.images) ? mm.images : [])
    .map((x) => String(x || "").trim())
    .filter(Boolean);
  const descCards = getMomentPostImageDescCards(mm);
  if (!imgs.length && !descCards.length) art.classList.add("moments-post--no-media");

  art.appendChild(head);
  buildMomentsPostMedia(art, mm);
  const body = document.createElement("div");
  body.className = "moments-post-body";
  buildMomentsPostFooter(body, mm);
  art.appendChild(body);
  return art;
}


function onMomentsFeedClick(e) {
  if (!(e.target instanceof Element)) return;

  const moreItem = e.target.closest(".moments-post-more-wrap .chat-thread-bead-menu-item");
  if (moreItem) {
    e.preventDefault();
    e.stopPropagation();
    const post = moreItem.closest(".moments-post");
    const momentId = String(post?.dataset?.momentId || "").trim();
    const action = String(moreItem.dataset.action || "").trim();
    closeAllMomentsPostMoreMenus();
    if (!momentId) return;
    if (action === "delete") deleteMomentWithConfirm(momentId);
    else if (action === "invite-char-comment") void inviteCharsToCommentOnMoment(momentId);
    else if (action === "invite-npc-comment") void inviteNpcsToCommentOnMoment(momentId);
    return;
  }
  const moreBtn = e.target.closest(".moments-post-more-btn");
  if (moreBtn) {
    e.preventDefault();
    e.stopPropagation();
    const wrap = moreBtn.closest(".moments-post-more-wrap");
    if (wrap instanceof HTMLElement) toggleMomentsPostMoreMenu(wrap);
    return;
  }
  if (!e.target.closest(".moments-post-more-wrap")) {
    closeAllMomentsPostMoreMenus();
  }

  const decorSlot = e.target.closest(".moments-ins-decor-slot");
  if (decorSlot) {
    const idx = Math.floor(Number(decorSlot.dataset.decorIdx));
    triggerMomentsDecorFilePick(idx);
    return;
  }

  const bioTap = e.target.closest("#moments-ins-bio");
  if (bioTap) {
    editMomentsProfileBio();
    return;
  }

  const media = e.target.closest(".moments-media");
  if (media) {
    if (media.classList.contains("moments-media--desc-card")) return;
    const art = media.closest(".moments-post");
    const momentId = String(art?.dataset?.momentId || "").trim();
    if (!momentId) return;
    const { bucket } = getActiveMomentsBucket();
    const raw = Array.isArray(bucket.moments)
      ? bucket.moments.find((x) => String(x?.id || "") === momentId)
      : null;
    const m = normalizeMoment(raw);
    const imgs = Array.isArray(m.images) ? m.images : [];
    const idx = Math.floor(Number(media.dataset.imgIdx) || 0);
    if (imgs.length) openMomentsGallery(imgs, idx, momentId);
    return;
  }

  const cmtDel = e.target.closest(".moments-post-cmt-del");
  if (cmtDel) {
    e.preventDefault();
    e.stopPropagation();
    const art = cmtDel.closest(".moments-post");
    const momentId = String(art?.dataset?.momentId || "").trim();
    const commentId = String(cmtDel.dataset.deleteCommentId || "").trim();
    if (momentId && commentId) deleteMomentCommentWithConfirm(momentId, commentId);
    return;
  }

  const cmtReply = e.target.closest(".moments-post-cmt-reply");
  if (cmtReply) {
    e.preventDefault();
    e.stopPropagation();
    const art = cmtReply.closest(".moments-post");
    const momentId = String(art?.dataset?.momentId || "").trim();
    const cid = String(cmtReply.dataset.replyCommentId || "").trim();
    if (momentId) focusMomentsInlineComposer(momentId, cid);
    return;
  }

  if (e.target.closest(".moments-post-composer")) return;

  const postAct = e.target.closest(".moments-post-act");
  if (postAct && postAct.dataset.act) {
    e.preventDefault();
    e.stopPropagation();
    const post = postAct.closest(".moments-post");
    const momentId = String(post?.dataset?.momentId || "").trim();
    if (!momentId) return;
    applyMomentsMomentAction(momentId, String(postAct.dataset.act || ""));
    return;
  }
}

let momentsGalleryImgs = [];
let momentsGalleryIdx = 0;
let momentsGalleryMomentId = "";
/** @type {{ stored: string, blob: Blob } | null} */
let momentsGalleryDownloadPrefetch = null;

function momentsGalleryCurrentStoredUrl() {
  const total = momentsGalleryImgs.length;
  if (!total) return "";
  const i = Math.min(total - 1, Math.max(0, momentsGalleryIdx));
  return sanitizeMomentImageUrl(String(momentsGalleryImgs[i] || "").trim());
}

function clearMomentsGalleryDownloadPrefetch() {
  momentsGalleryDownloadPrefetch = null;
}

function updateMomentsGalleryDownloadButton(stored, img) {
  const btn = document.getElementById("moments-gallery-download");
  if (!(btn instanceof HTMLButtonElement)) return;
  if (btn.dataset.xxjDownloadBusy === "1") return;
  const ready = isChatPhotoViewerDownloadReady(stored, img instanceof HTMLImageElement ? img : null);
  btn.disabled = !ready;
  const title = ready ? "下载图片" : "图片加载中，请稍候";
  btn.title = title;
  btn.setAttribute("aria-label", title);
}

function syncMomentsGalleryActionButtons() {
  const regenBtn = document.getElementById("moments-gallery-regen");
  if (!(regenBtn instanceof HTMLButtonElement)) return;
  const mid = String(momentsGalleryMomentId || "").trim();
  if (!mid || !isSessionImageGenConfigured()) {
    regenBtn.hidden = true;
    return;
  }
  const { bucket } = getActiveMomentsBucket();
  const raw = (Array.isArray(bucket.moments) ? bucket.moments : []).find(
    (x) => String(x?.id || "") === mid
  );
  const mm = normalizeMoment(raw);
  const canRegen =
    mm.kind === "char" &&
    getMomentPostImageDescCards(mm).some((x) => String(x || "").trim());
  regenBtn.hidden = !canRegen;
}

function setMomentsGalleryActionsBusy(busy) {
  for (const id of ["moments-gallery-download", "moments-gallery-regen", "moments-gallery-close"]) {
    const el = document.getElementById(id);
    if (el instanceof HTMLButtonElement) {
      el.disabled = busy;
      if (id === "moments-gallery-download") {
        if (busy) el.dataset.xxjDownloadBusy = "1";
        else delete el.dataset.xxjDownloadBusy;
      }
    }
  }
  if (!busy) {
    const img = document.getElementById("moments-gallery-img");
    updateMomentsGalleryDownloadButton(
      momentsGalleryCurrentStoredUrl(),
      img instanceof HTMLImageElement ? img : null
    );
    syncMomentsGalleryActionButtons();
  }
}

function renderMomentsGallery() {
  const img = document.getElementById("moments-gallery-img");
  const meta = document.getElementById("moments-gallery-meta");
  const prev = document.getElementById("moments-gallery-prev");
  const next = document.getElementById("moments-gallery-next");
  const total = momentsGalleryImgs.length;
  const i = Math.min(total - 1, Math.max(0, momentsGalleryIdx));
  momentsGalleryIdx = i;
  if (meta) meta.textContent = total ? `${i + 1} / ${total}` : "—";
  const stored = momentsGalleryCurrentStoredUrl();
  if (img instanceof HTMLImageElement) {
    applyChatImageUrlToElement(img, stored);
    clearMomentsGalleryDownloadPrefetch();
    updateMomentsGalleryDownloadButton(stored, img);
    if (stored) {
      void (async () => {
        try {
          const blob = await chatImageBlobFromStoredUrl(stored, img);
          if (!isUsableChatImageBlob(blob)) return;
          if (momentsGalleryCurrentStoredUrl() !== stored) return;
          momentsGalleryDownloadPrefetch = { stored, blob };
        } catch {
          if (momentsGalleryCurrentStoredUrl() === stored) momentsGalleryDownloadPrefetch = null;
        }
        if (momentsGalleryCurrentStoredUrl() === stored) {
          updateMomentsGalleryDownloadButton(stored, img);
        }
      })();
    }
  }
  if (prev) prev.disabled = i <= 0;
  if (next) next.disabled = i >= total - 1;
  syncMomentsGalleryActionButtons();
}

function openMomentsGallery(imgs, idx = 0, momentId = "") {
  const root = document.getElementById("moments-gallery");
  if (!root) return;
  momentsGalleryMomentId = String(momentId || "").trim();
  momentsGalleryImgs = Array.isArray(imgs)
    ? imgs.map((x) => String(x || "").trim()).filter(Boolean).slice(0, MOMENTS_POST_MAX_IMAGES)
    : [];
  momentsGalleryIdx = Number.isFinite(Number(idx)) ? Math.floor(Number(idx)) : 0;
  renderMomentsGallery();
  root.hidden = false;
  root.setAttribute("aria-hidden", "false");
}

function closeMomentsGallery() {
  const root = document.getElementById("moments-gallery");
  if (!root) return;
  root.hidden = true;
  root.setAttribute("aria-hidden", "true");
  clearMomentsGalleryDownloadPrefetch();
  setMomentsGalleryActionsBusy(false);
  momentsGalleryImgs = [];
  momentsGalleryIdx = 0;
  momentsGalleryMomentId = "";
}

function runMomentsGalleryDownloadClick() {
  const img = document.getElementById("moments-gallery-img");
  const stored = momentsGalleryCurrentStoredUrl();
  if (!stored) {
    showToast("没有可下载的图片");
    return;
  }
  const stem = chatImageDownloadStem("没心机-朋友圈配图");
  const pref = momentsGalleryDownloadPrefetch;
  if (pref && pref.stored === stored && pref.blob) {
    try {
      triggerChatImageBlobDownload(pref.blob, stem);
      showToast("已开始下载");
      return;
    } catch {
      showToast("下载失败");
      return;
    }
  }
  if (img instanceof HTMLImageElement) {
    const src = String(img.currentSrc || img.src || "").trim();
    if (triggerChatImageSrcDownload(src, stem)) {
      showToast("已开始下载");
      return;
    }
    const dataUrl = trySyncChatImageDataUrlFromImg(img);
    if (dataUrl) {
      try {
        triggerChatImageDataUrlDownload(dataUrl, stem);
        showToast("已开始下载");
        return;
      } catch {
        showToast("下载失败");
        return;
      }
    }
  }
  const dlBtn = document.getElementById("moments-gallery-download");
  if (dlBtn instanceof HTMLButtonElement) {
    dlBtn.disabled = true;
    dlBtn.dataset.xxjDownloadBusy = "1";
  }
  showToast("准备下载…");
  void (async () => {
    try {
      const blob = await chatImageBlobFromStoredUrl(
        stored,
        img instanceof HTMLImageElement ? img : null
      );
      triggerChatImageBlobDownload(blob, stem);
      showToast("已开始下载");
    } catch {
      showToast("下载失败，可长按图片另存");
    } finally {
      if (dlBtn instanceof HTMLButtonElement) delete dlBtn.dataset.xxjDownloadBusy;
      updateMomentsGalleryDownloadButton(
        stored,
        img instanceof HTMLImageElement ? img : null
      );
    }
  })();
}

async function regenerateMomentsGalleryImage() {
  const momentId = String(momentsGalleryMomentId || "").trim();
  if (!momentId) {
    showToast("无法重生");
    return;
  }
  if (!isSessionImageGenConfigured()) {
    showToast("未配置生图");
    return;
  }
  const { maskId, bucket } = getActiveMomentsBucket();
  if (!maskId) {
    showToast("无法重生");
    return;
  }
  const raw = (Array.isArray(bucket.moments) ? bucket.moments : []).find(
    (x) => String(x?.id || "") === momentId
  );
  const mm = normalizeMoment(raw);
  if (mm.kind !== "char") {
    showToast("仅角色 AI 配图可重生");
    return;
  }
  const descCards = getMomentPostImageDescCards(mm);
  const imgIdx = Math.min(
    Math.max(0, momentsGalleryIdx),
    Math.max(0, (Array.isArray(mm.images) ? mm.images.length : 1) - 1)
  );
  const cap = String(descCards[imgIdx] || descCards[0] || "").trim();
  if (!cap) {
    showToast("没有配图描述，无法重生");
    return;
  }
  const cid = resolveMomentCharId(mm);
  const tid = String(mm.threadId || "").trim();
  const th = pickThreadForCharMoment(maskId, cid, tid);
  setMomentsGalleryActionsBusy(true);
  showToast("配图重绘中…");
  try {
    const newUrls = await resolveMomentsCharPostImages({ mode: "gen", pickIndex: 0, genCaption: cap }, [], th, maskId);
    const newUrl = newUrls[0] ? sanitizeMomentImageUrl(String(newUrls[0])) : "";
    if (!newUrl) {
      showToast("配图重绘失败");
      return;
    }
    const ok = patchMomentById(momentId, (m) => {
      const imgs = (Array.isArray(m.images) ? m.images : [])
        .map((x) => sanitizeMomentImageUrl(String(x || "").trim()))
        .filter(Boolean);
      if (imgIdx >= 0 && imgIdx < imgs.length) imgs[imgIdx] = newUrl;
      else if (imgs.length) imgs[0] = newUrl;
      else imgs.push(newUrl);
      m.images = imgs.slice(0, MOMENTS_POST_MAX_IMAGES);
    });
    if (!ok) {
      showToast("无法保存");
      return;
    }
    const { bucket: bucket2 } = getActiveMomentsBucket();
    const refreshed = (Array.isArray(bucket2.moments) ? bucket2.moments : []).find(
      (x) => String(x?.id || "") === momentId
    );
    momentsGalleryImgs = getMomentPostStoredImageUrls(normalizeMoment(refreshed));
    renderMomentsGallery();
    renderMomentsFeed();
    showToast("配图已更新");
  } catch {
    showToast("配图重绘失败");
  } finally {
    setMomentsGalleryActionsBusy(false);
  }
}

function stepMomentsGallery(delta) {
  if (!momentsGalleryImgs.length) return;
  momentsGalleryIdx = Math.min(momentsGalleryImgs.length - 1, Math.max(0, momentsGalleryIdx + delta));
  renderMomentsGallery();
}

function applyMomentsMomentAction(momentId, action) {
  const mid = String(momentId || "").trim();
  if (!mid) return;
  if (action === "like") {
    const ok = patchMomentById(mid, (m) => {
      const was = m.likedByMe === true;
      m.likedByMe = !was;
      const base = Math.max(0, Math.floor(Number(m.likeCount) || 0));
      m.likeCount = Math.max(0, base + (m.likedByMe ? 1 : -1));
    });
    if (!ok) {
      showToast("操作失败，请稍后再试");
      return;
    }
    replaceMomentsPostInFeed(mid);
    return;
  }
  if (action === "comment") {
    focusMomentsInlineComposer(mid);
    return;
  }
  if (action === "share") {
    const { bucket } = getActiveMomentsBucket();
    const raw = Array.isArray(bucket.moments) ? bucket.moments.find((x) => String(x?.id || "") === mid) : null;
    const m = normalizeMoment(raw);
    const payload = `${getMomentDisplayLabel(m)}：${String(m.text || "").trim()}`;
    patchMomentById(mid, (mm) => {
      mm.shareCount = Math.max(0, Math.floor(Number(mm.shareCount) || 0) + 1);
    });
    replaceMomentsPostInFeed(mid);
    if (typeof navigator !== "undefined" && navigator.share) {
      navigator
        .share({ text: payload })
        .then(() => showToast("已分享"))
        .catch(() => showToast("已记下"));
      return;
    }
    const clip = navigator?.clipboard;
    if (clip && typeof clip.writeText === "function") {
      clip
        .writeText(payload)
        .then(() => showToast("已复制，去别处粘贴吧"))
        .catch(() => showToast("已记下"));
      return;
    }
    showToast("已记下");
  }
}

function updateMomentsComposeSubmitState() {
  const btn = document.getElementById("moments-compose-submit");
  const ta = document.getElementById("moments-compose-text");
  if (!(btn instanceof HTMLButtonElement)) return;
  const text = String(ta?.value || "").trim();
  const hasImg = momentsComposeDraftImages.length > 0;
  btn.disabled = momentsComposeBusy || (!text && !hasImg);
}

function renderMomentsComposePreviews() {
  const root = document.getElementById("moments-compose-previews");
  const countEl = document.getElementById("moments-compose-img-count");
  if (!root) return;
  const imgs = momentsComposeDraftImages;
  if (countEl) countEl.textContent = `${imgs.length} / ${MOMENTS_POST_MAX_IMAGES}`;
  root.replaceChildren();
  for (let i = 0; i < imgs.length; i++) {
    const src = imgs[i];
    const cell = document.createElement("div");
    cell.className = "moments-compose-thumb";
    const im = document.createElement("img");
    im.alt = "";
    im.loading = "eager";
    im.decoding = "async";
    applyChatImageUrlToElement(im, src);
    im.onerror = () => {
      cell.classList.add("moments-compose-thumb--broken");
    };
    const rm = document.createElement("button");
    rm.type = "button";
    rm.className = "moments-compose-thumb-rm";
    rm.dataset.composeRm = String(i);
    rm.setAttribute("aria-label", `移除第 ${i + 1} 张图`);
    rm.innerHTML = '<i class="ph ph-x" aria-hidden="true"></i>';
    cell.append(im, rm);
    root.appendChild(cell);
  }
  if (imgs.length < MOMENTS_POST_MAX_IMAGES) {
    const add = document.createElement("button");
    add.type = "button";
    add.className = "moments-compose-thumb moments-compose-thumb--add";
    add.dataset.composeAdd = "1";
    add.setAttribute("aria-label", "添加配图");
    add.innerHTML = '<i class="ph ph-plus" aria-hidden="true"></i>';
    root.appendChild(add);
  }
  updateMomentsComposeSubmitState();
}

function openMomentsComposeSheet() {
  const maskId = getActiveMaskIdForInbox();
  if (!maskId) {
    showToast("请先创建并选择一个主控面具");
    return;
  }
  momentsComposeDraftImages = [];
  momentsComposeBusy = false;
  const root = document.getElementById("moments-compose-sheet");
  const ta = document.getElementById("moments-compose-text");
  const fileInp = document.getElementById("moments-compose-file");
  if (ta instanceof HTMLTextAreaElement) ta.value = "";
  if (fileInp instanceof HTMLInputElement) fileInp.value = "";
  renderMomentsComposePreviews();
  if (!root) return;
  root.hidden = false;
  root.setAttribute("aria-hidden", "false");
  window.requestAnimationFrame(() => ta?.focus());
}

function closeMomentsComposeSheet() {
  const root = document.getElementById("moments-compose-sheet");
  if (!root) return;
  root.hidden = true;
  root.setAttribute("aria-hidden", "true");
  momentsComposeDraftImages = [];
  momentsComposeBusy = false;
  const ta = document.getElementById("moments-compose-text");
  const fileInp = document.getElementById("moments-compose-file");
  if (ta instanceof HTMLTextAreaElement) ta.value = "";
  if (fileInp instanceof HTMLInputElement) fileInp.value = "";
  renderMomentsComposePreviews();
}

function triggerMomentsComposeFilePick() {
  if (momentsComposeDraftImages.length >= MOMENTS_POST_MAX_IMAGES) {
    showToast(`最多 ${MOMENTS_POST_MAX_IMAGES} 张配图`);
    return;
  }
  const inp = document.getElementById("moments-compose-file");
  if (inp instanceof HTMLInputElement) inp.click();
}

async function ingestMomentsComposeFiles(fileList) {
  const picked = fileList ? Array.from(fileList) : [];
  const files = picked.filter((f) => isImagePickFile(f));
  if (!picked.length) return;
  if (!files.length) {
    showToast("未识别到图片，请换 JPG/PNG 试试");
    return;
  }
  const room = MOMENTS_POST_MAX_IMAGES - momentsComposeDraftImages.length;
  if (room <= 0) {
    showToast(`最多 ${MOMENTS_POST_MAX_IMAGES} 张配图`);
    return;
  }
  if (momentsComposeBusy) return;
  momentsComposeBusy = true;
  updateMomentsComposeSubmitState();
  const before = momentsComposeDraftImages.length;
  try {
    for (const file of files.slice(0, room)) {
      let dataUrl = "";
      try {
        dataUrl = await readImageFileAsChatEmbeddedDataUrl(file);
      } catch {
        /* 压缩失败时仍尝试原图 */
      }
      if (!dataUrl) {
        try {
          dataUrl = String((await readImageFileAsDataUrl(file)) || "");
        } catch {
          dataUrl = "";
        }
      }
      if (!dataUrl) continue;
      const url = await persistMomentImageDataUrl(dataUrl);
      if (url) momentsComposeDraftImages.push(url);
    }
    renderMomentsComposePreviews();
    const added = momentsComposeDraftImages.length - before;
    if (!added) {
      showToast("图片读取失败，请换一张试试");
    } else if (files.length > room) {
      showToast(`已添加 ${added} 张，已达上限`);
    }
  } catch {
    showToast("图片读取失败");
  } finally {
    momentsComposeBusy = false;
    const inp = document.getElementById("moments-compose-file");
    if (inp instanceof HTMLInputElement) inp.value = "";
    updateMomentsComposeSubmitState();
  }
}

function removeMomentsComposeImage(idx) {
  const i = Math.floor(Number(idx));
  if (i < 0 || i >= momentsComposeDraftImages.length) return;
  momentsComposeDraftImages.splice(i, 1);
  renderMomentsComposePreviews();
}

function submitMomentsCompose() {
  if (momentsComposeBusy) return;
  const ta = document.getElementById("moments-compose-text");
  const text = String(ta?.value || "").trim();
  const draftCount = momentsComposeDraftImages.slice(0, MOMENTS_POST_MAX_IMAGES).length;
  const images = momentsComposeDraftImages
    .slice(0, MOMENTS_POST_MAX_IMAGES)
    .map((x) => sanitizeMomentImageUrl(String(x || "").trim()))
    .filter(Boolean);
  if (!text && !images.length) {
    showToast(draftCount ? "配图保存失败，请重选图片后再发" : "写点文字或选张图吧");
    return;
  }
  const { inbox, maskId, bucket } = getActiveMomentsBucket();
  if (!maskId) {
    showToast("请先创建并选择一个主控面具");
    return;
  }
  const st = readUserMaskStore();
  const slot = st.items.find((x) => x.id === maskId);
  const userLabel = (slot?.displayName && String(slot.displayName).trim()) || "主控";
  const newId = newEntityId();
  const arr = Array.isArray(bucket.moments) ? bucket.moments.slice() : [];
  /** @type {Record<string, unknown>} */
  const row = {
    id: newId,
    kind: "user",
    displayName: userLabel,
    timeIso: new Date().toISOString(),
    text,
    images,
    likedByMe: false,
    likeCount: 0,
    shareCount: 0,
    comments: []
  };
  if (images.length) row.sourceChatImageRole = "user";
  const published = normalizeMoment(row);
  arr.unshift(published);
  bucket.moments = arr;
  writeChatInboxStore(inbox, { fast: true });
  try {
    recordUserMomentFeedNoticesForMask(maskId, published, userLabel);
  } catch (e) {
    console.warn("[moments] user post feed notice failed", e);
  }
  closeMomentsComposeSheet();
  renderMomentsFeed();
  showToast("已留下");
  queueMomentsCharReactions(() => triggerMomentsReactionsOnUserPost(newId));
}

function onMomentsComposeClick(e) {
  if (!(e.target instanceof Element)) return;
  const rm = e.target.closest("[data-compose-rm]");
  if (rm) {
    e.preventDefault();
    removeMomentsComposeImage(rm.dataset.composeRm);
    return;
  }
  if (e.target.closest("[data-compose-add]")) {
    e.preventDefault();
    triggerMomentsComposeFilePick();
  }
}

function openChatCharPickerSheet() {
  const maskId = getActiveMaskIdForInbox();
  if (!maskId) {
    showToast("请先创建并选择一个主控面具");
    return;
  }
  chatCharPickStep = "pick-char";
  const sheet = document.getElementById("chat-char-pick-sheet");
  const list = document.getElementById("chat-char-pick-list");
  const titleEl = document.getElementById("chat-char-pick-title");
  const back = document.getElementById("chat-char-pick-back");
  if (back) back.hidden = true;
  if (!sheet || !list) return;
  if (titleEl) {
    titleEl.textContent =
      chatCharPickIntent === "group"
        ? "选择群成员（旧流程，请用人群图标多选建群）"
        : "选择要密谈的角色";
  }
  const st = readCharPersonaStore();
  list.replaceChildren();
  if (!st.items.length) {
    const li = document.createElement("li");
    li.className = "chat-char-pick-empty";
    li.textContent = "人设库里还没有角色，请先到「人设」里添加。";
    list.appendChild(li);
  } else {
    for (const it of st.items) {
      const id = String(it.id || "");
      if (!id) continue;
      const li = document.createElement("li");
      const b = document.createElement("button");
      b.type = "button";
      b.className = "chat-char-pick-item";
      b.dataset.charId = id;
      b.textContent = (it.displayName && String(it.displayName).trim()) || "未命名角色";
      li.appendChild(b);
      list.appendChild(li);
    }
  }
  sheet.hidden = false;
  sheet.setAttribute("aria-hidden", "false");
}

function closeChatCharPickerSheet() {
  const sheet = document.getElementById("chat-char-pick-sheet");
  const titleEl = document.getElementById("chat-char-pick-title");
  const back = document.getElementById("chat-char-pick-back");
  if (!sheet) return;
  chatCharPickIntent = "dm";
  pendingGroupTitle = "";
  chatCharPickStep = "pick-char";
  if (back) back.hidden = true;
  if (titleEl) titleEl.textContent = "选择要密谈的角色";
  sheet.hidden = true;
  sheet.setAttribute("aria-hidden", "true");
}

function showChatCharOpeningStep(charId, openings) {
  chatCharPickStep = "pick-opening";
  const list = document.getElementById("chat-char-pick-list");
  const titleEl = document.getElementById("chat-char-pick-title");
  const back = document.getElementById("chat-char-pick-back");
  if (titleEl) titleEl.textContent = "选择开场";
  if (back) back.hidden = false;
  if (!list) return;
  list.replaceChildren();
  const pushOpt = (idx, label) => {
    const li = document.createElement("li");
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "chat-char-pick-item chat-char-pick-item--opening";
    btn.dataset.charId = String(charId);
    btn.dataset.openingIdx = String(idx);
    btn.textContent = label;
    li.appendChild(btn);
    list.appendChild(li);
  };
  pushOpt(-1, "空白密谈（无预设对方第一句）");
  openings.forEach((text, i) => {
    const one = String(text || "").replace(/\s+/g, " ").trim();
    const preview = one.length > 40 ? `${one.slice(0, 40)}…` : one;
    pushOpt(i, i === 0 ? `主开场：${preview}` : `备用开场 ${i}：${preview}`);
  });
}

function createChatThreadWithChar(charId, openingIdx) {
  const D = window.XXJ_DB;
  if (!D) return;
  const maskId = getActiveMaskIdForInbox();
  if (!maskId) {
    showToast("请先创建并选择一个主控面具");
    return;
  }
  const cid = String(charId || "").trim();
  if (!cid) return;
  let initialMessages = [];
  if (openingIdx != null && Number.isFinite(Number(openingIdx)) && Number(openingIdx) >= 0) {
    const st = readCharPersonaStore();
    const it = st.items.find((x) => x.id === cid);
    const lines = normalizeCharOpeningsArray(it?.openings);
    const text = lines[Number(openingIdx)];
    if (text) {
      initialMessages = [{ role: "assistant", content: text, at: Date.now() }];
    }
  }
  const inbox = readChatInboxStore();
  ensureMaskBucket(inbox, maskId);
  const key = maskBucketKey(maskId);
  const bucket = inbox.byMask[key];
  const id = newEntityId();
  const stWb = readCharPersonaStore();
  const itWb = stWb.items.find((x) => x.id === cid);
  const wbIds = getCharMainWorldBookVolumeIds(itWb);
  const threadDraft = {
    id,
    charId: cid,
    kind: "dm",
    messages: initialMessages,
    ...(wbIds.length ? { worldBookVolumeIds: wbIds.slice() } : {}),
    updatedAt: Date.now()
  };
  if (itWb) applyCharImageGenDefaultsToNewThread(threadDraft, itWb);
  bucket.threads.push(threadDraft);
  writeChatInboxStore(inbox);
  writeChatActiveThreadRef({ maskId, threadId: id });
  activateCharPersonaById(cid);
  closeChatCharPickerSheet();
  renderChatThreadList();
  openChatScreen();
}

function createChatGroupThreadWithChar(charId, groupTitle) {
  const D = window.XXJ_DB;
  if (!D) return;
  const maskId = getActiveMaskIdForInbox();
  if (!maskId) {
    showToast("请先创建并选择一个主控面具");
    return;
  }
  const cid = String(charId || "").trim();
  if (!cid) return;
  const title = String(groupTitle || "").trim() || "群聊";
  const inbox = readChatInboxStore();
  ensureMaskBucket(inbox, maskId);
  const key = maskBucketKey(maskId);
  const bucket = inbox.byMask[key];
  const id = newEntityId();
  const stWb = readCharPersonaStore();
  const itWb = stWb.items.find((x) => x.id === cid);
  const wbIds = getCharMainWorldBookVolumeIds(itWb);
  const groupDraft = {
    id,
    charId: cid,
    kind: "group",
    groupTitle: title,
    memberCharIds: [cid],
    messages: [],
    heartVoiceEnabled: false,
    ...(wbIds.length ? { worldBookVolumeIds: wbIds.slice() } : {}),
    updatedAt: Date.now()
  };
  if (itWb) applyCharImageGenDefaultsToNewThread(groupDraft, itWb);
  bucket.threads.push(groupDraft);
  writeChatInboxStore(inbox);
  writeChatActiveThreadRef({ maskId, threadId: id });
  activateCharPersonaById(cid);
  closeChatCharPickerSheet();
  renderChatThreadList();
  openChatScreen();
}

function isChatNoticeRecallUserMessage(m) {
  return !!(m && typeof m === "object" && m.role === "notice" && String(m.kind || "") === "recall_user");
}

function isChatNoticeRecallCharMessage(m) {
  return !!(m && typeof m === "object" && m.role === "notice" && String(m.kind || "") === "recall_char");
}

function isChatNoticeGroupRenameMessage(m) {
  return !!(m && typeof m === "object" && m.role === "notice" && String(m.kind || "") === "group_rename");
}

function isChatNoticeGroupNicknameMessage(m) {
  return !!(m && typeof m === "object" && m.role === "notice" && String(m.kind || "") === "group_nickname");
}

function isChatNoticeCharRemarkUserMessage(m) {
  return !!(m && typeof m === "object" && m.role === "notice" && String(m.kind || "") === "char_remark_user");
}

function formatChatCharRemarkUserNoticeLabel(m) {
  const lb = String(m?.label || "").trim();
  if (lb) return lb;
  const nm = String(m?.charName || "").trim() || "对方";
  const rk = String(m?.remark || "").trim();
  return rk ? `"${nm}" 给你设了备注 "${rk}"` : `"${nm}" 更新了对你的备注`;
}

function isChatNoticeBlockMessage(m) {
  const k = String(m?.kind || "");
  return !!(
    m &&
    typeof m === "object" &&
    m.role === "notice" &&
    (k === "block_user_char" ||
      k === "unblock_user_char" ||
      k === "block_char_user" ||
      k === "unblock_char_user")
  );
}

function formatChatBlockNoticeLabel(m) {
  const lb = String(m?.label || "").trim();
  if (lb) return lb;
  const charName = String(m?.charName || "").trim() || "对方";
  const userName = String(m?.userName || "").trim() || "你";
  const k = String(m?.kind || "");
  if (k === "block_user_char") return `${userName} 已将 ${charName} 拉黑`;
  if (k === "unblock_user_char") return `${userName} 已取消拉黑 ${charName}`;
  if (k === "block_char_user") return `${charName} 已将你拉黑`;
  if (k === "unblock_char_user") return `${charName} 已取消拉黑你`;
  return "拉黑状态变更";
}

function buildUserBlockedCharAutoRoundPrompt(charName, userCall) {
  const nm = String(charName || "").trim() || "对方";
  const uc = String(userCall || "").trim() || "对方";
  return (
    "（系统代发·勿复述）[拉黑事件] " +
    `「${uc}」刚刚在聊天设置里把你（${nm}）拉黑了——**此状态会持续**，直到对方取消拉黑。` +
    " 界面会提示拉黑；对方仍可能继续发消息，你也能看到并回复，但**每一轮回复都须带着「已被对方拉黑」的认知**。" +
    " 请结合当下关系与人设，用 **一条** 自然的即时消息反应（可错愕、冷淡、调侃、装无所谓等）；不要客服腔，不要说教，不要长篇解释拉黑功能。" +
    " 若人设上此时不想开口，可 lines 留空。"
  );
}

/** @param {unknown} th @param {string} userCall */
function buildChatBlockStatePromptLine(th, userCall) {
  const uc = String(userCall || "").trim() || "对方";
  const userBlk = isThreadUserBlockedChar(th);
  const charBlk = isThreadCharBlockedUser(th);
  if (userBlk && charBlk) {
    return `当前拉黑状态：**双方互拉黑**。对方已将你拉黑，你也已将对方拉黑；双方仍可能继续发消息。你回复时须同时承接两种立场，勿当无事发生。`;
  }
  if (userBlk) {
    return (
      `当前拉黑状态：**对方（${uc}）已将你拉黑**（设置里操作，持续生效直到取消）。` +
      `对方仍可能发消息，你也能看到并必须能回复；**每一轮都须带着「我正处于被对方拉黑」这一事实**接戏（可冷淡、错愕、装无所谓、嘴硬等），勿忽略、勿假装没发生。`
    );
  }
  if (charBlk) {
    return `当前拉黑状态：**你已将 ${uc} 拉黑**（剧情/你的决定）。对方仍可能发消息；请按你的拉黑决定与当下剧情回应。`;
  }
  return "";
}

/** 模型仅输出 blockUser/unblockUser、无 lines 时仍应落盘 notice。 */
function charBlockUserIntentWouldApply(parsed, thread, dmSurface) {
  if (dmSurface === "offline") return false;
  if (!thread || typeof thread !== "object" || thread.kind === "group") return false;
  const wantBlock = parsed?.blockUser === true;
  const wantUnblock = parsed?.blockUser === false || parsed?.unblockUser === true;
  if (!wantBlock && !wantUnblock) return false;
  if (wantBlock && wantUnblock) return false;
  const prev = isThreadCharBlockedUser(thread);
  if (wantBlock && prev) return false;
  if (wantUnblock && !prev) return false;
  return true;
}

/** user 撤回：角色仍「看见过」撤回前原文（像真机已读后再撤）。 */
function tryAppendRecallUserNoticeToChatApiMessages(msgs, m, userLabel) {
  if (!isChatNoticeRecallUserMessage(m)) return false;
  const who = String(userLabel || "").trim() || "对方";
  const recalled = String(m.recalledContent ?? "").trim();
  if (!recalled) {
    msgs.push({
      role: "user",
      content: `（系统提示：${who}撤回了一条消息；气泡已从界面消失。）`
    });
    return true;
  }
  const tr = String(m.recalledTranslation ?? "").trim();
  let content = `（系统提示：${who}撤回了一条消息。撤回前你屏幕上看到的原文是：「${recalled.slice(0, 4000)}」`;
  if (tr) content += `；对照译文：「${tr.slice(0, 2000)}」`;
  content +=
    "。界面上该气泡已消失，但你仍记得以上内容；可据此接戏（追问、装傻、吃醋等），勿在 lines 里机械复读「撤回了一条消息」这类软件提示。）";
  msgs.push({ role: "user", content });
  return true;
}

function tryAppendBlockNoticeToChatApiMessages(msgs, m) {
  if (!m || typeof m !== "object" || !isChatNoticeBlockMessage(m)) return false;
  const kind = String(m.kind || "");
  const charName = String(m.charName || "").trim() || "你";
  const userName = String(m.userName || "").trim() || "对方";
  let content = "";
  if (kind === "block_user_char") {
    content =
      `（界面系统提示、勿复述：${userName}已在聊天设置里将${charName}拉黑；**此状态持续**，直到对方取消。` +
      `此后${userName}仍可能继续发消息，你也能看到并回复，但**须始终记得当前处于「被对方拉黑」**，按人设反应。）`;
  } else if (kind === "unblock_user_char") {
    content = `（界面系统提示、勿复述：${userName}已取消对${charName}的拉黑；此后按正常关系接戏。）`;
  } else if (kind === "block_char_user") {
    content =
      `（界面系统提示、勿复述：${charName}已在剧情里将${userName}拉黑/拒收；此为你的主动决定，后续回复须承接此状态。）`;
  } else if (kind === "unblock_char_user") {
    content = `（界面系统提示、勿复述：${charName}已解除对${userName}的拉黑。）`;
  }
  if (!content) return false;
  msgs.push({ role: "user", content });
  return true;
}

function isChatNoticeRedpackMessage(m) {
  const k = String(m?.kind || "");
  return !!(
    m &&
    typeof m === "object" &&
    m.role === "notice" &&
    (k === "redpack" || k === "group_redpack")
  );
}

function isChatNoticeCallEndedMessage(m) {
  return !!(m && typeof m === "object" && m.role === "notice" && String(m.kind || "") === "call_end");
}

function isChatNoticeOfflineEndedMessage(m) {
  return !!(m && typeof m === "object" && m.role === "notice" && String(m.kind || "") === "offline_end");
}

/** 通话 / 晤面 / 锁屏结束票根：含完整对白归档，线下与线上频道均应注入模型记忆。 */
function isChatTranscriptArchiveNotice(m) {
  return (
    isChatNoticeCallEndedMessage(m) ||
    isChatNoticeOfflineEndedMessage(m) ||
    isChatNoticeCharLockEndedMessage(m)
  );
}

function isChatRecallNotice(m) {
  return isChatNoticeRecallUserMessage(m) || isChatNoticeRecallCharMessage(m);
}

function isChatSystemNotice(m) {
  return (
    isChatRecallNotice(m) ||
    isChatNoticeRedpackMessage(m) ||
    isChatNoticeGroupRenameMessage(m) ||
    isChatNoticeGroupNicknameMessage(m) ||
    isChatNoticeCharRemarkUserMessage(m) ||
    isChatNoticeBlockMessage(m) ||
    isChatTranscriptArchiveNotice(m) ||
    isChatNoticeMomentsFeedMessage(m) ||
    isChatNoticeCheckupFinishMessage(m) ||
    isChatNoticeCheckupCaughtMessage(m) ||
    isChatNoticeCheckupReverseFinishMessage(m)
  );
}

function formatChatMomentsFeedNoticeLabel(m) {
  if (isMomentsFeedPostPublishedNotice(m)) {
    const img = m.hasImages ? "（配图）" : "";
    if (m.authorKind === "user") {
      const who = String(m.displayName || "").trim();
      return who ? `用户 ${who} 刚刚发了一条朋友圈${img}` : `用户刚刚发了一条朋友圈${img}`;
    }
    return `刚刚发了一条朋友圈${img}`;
  }
  const t = String(m?.content || "").trim().replace(/\s+/g, " ");
  if (!t) return "朋友圈动态";
  if (/发了一条朋友圈/.test(t) && !/评论|赞了/.test(t)) {
    const img = /配图|带配图/.test(t) ? "（配图）" : "";
    if (/^用户\s/.test(t)) return `用户刚刚发了一条朋友圈${img}`;
    return `刚刚发了一条朋友圈${img}`;
  }
  return t.length > 72 ? `${t.slice(0, 71)}…` : t;
}

function tryAppendMomentsFeedNoticeToChatApiMessages(msgs, m, momentsApiMap, maskId) {
  if (!m || typeof m !== "object" || !isChatNoticeMomentsFeedMessage(m)) return false;
  const key = momentsFeedNoticeApiMapKey(m);
  if (momentsApiMap instanceof Map && momentsApiMap.has(key)) {
    msgs.push(momentsApiMap.get(key));
    return true;
  }
  const line = resolveMomentsFeedNoticeLineForApi(m, maskId);
  if (!line) return true;
  msgs.push({ role: "user", content: line });
  return true;
}

/** 挂断写入主记录：本轮通话转写原样写入 `callTranscript`（与内存中 `chatCallSessionLog` 一致）。 */
function cloneCallSessionForNoticeStorage() {
  const raw = Array.isArray(chatCallSessionLog) ? chatCallSessionLog : [];
  return raw
    .filter((x) => !(x && typeof x === "object" && x.restoring))
    .map((x) => {
    const o = {
      role: x.role === "assistant" ? "assistant" : "user",
      text: String(x.text || ""),
      at: Number(x.at) || 0
    };
    const tr = String(x.translation || "").trim();
    if (tr) o.translation = tr;
    return o;
  });
}

/**
 * @param {readonly unknown[]} rows
 * @returns {string}
 */
function formatChatTurnRowsTranscriptForApiPrompt(rows) {
  const arr = Array.isArray(rows) ? rows : [];
  if (!arr.length) return "";
  const th = readActiveThread();
  const charNm = getChatCharPersonaDisplayName();
  const um = readUserMask();
  const userLab = String(um?.displayName || "").trim() || "对方";
  const reader = getThreadCharTranslationTargetLang(th);
  const lines = [];
  for (const row of arr) {
    if (!row || typeof row !== "object") continue;
    const role = row.role === "assistant" ? "assistant" : "user";
    const who = role === "assistant" ? charNm : userLab;
    const rawT = String(row.text || "").trim();
    const text = rawT.replace(/\s*\|\|\|\s*/g, "\n").trim();
    const transJoined = String(row.translation || "").trim();
    let chunk = `${who}：${text || "（空）"}`;
    if (transJoined && translationJoinedHasAnyVisible(transJoined)) {
      const trShow = transJoined
        .split(/\|\|\|/)
        .map((s) => String(s).trim())
        .filter((s) => s && !isTranslationSegmentSkipped(s))
        .join(" / ");
      if (trShow) chunk += `\n（${reader}对照：${trShow}）`;
    }
    lines.push(chunk);
  }
  return lines.length ? lines.join("\n\n") : "";
}

/** 晤面结束票根：归档全文（多段 ||| 用换行保留），勿只用列表预览的「最后一段」。 */
function offlineMessageTextForTranscriptArchive(m) {
  const raw = String(m?.content ?? "").trim();
  if (!raw) return "";
  if (m && typeof m === "object" && chatMessageDmSurface(m) === "offline") {
    return raw.replace(/\s*\|\|\|\s*/g, "\n\n").replace(/\n{3,}/g, "\n\n").trim();
  }
  try {
    return (chatMessagePlainLastBubbleSegment(m.content, m) || raw).replace(/\s+/g, " ").trim();
  } catch {
    return raw.replace(/\s+/g, " ").trim();
  }
}

/**
 * @param {unknown[]} log
 * @param {number} startIdx
 * @returns {{ role: string, text: string, at: number, translation?: string }[]}
 */
function cloneOfflineSessionTranscriptForNoticeStorage(log, startIdx) {
  const arr = Array.isArray(log) ? log : [];
  const si = Math.max(0, Math.floor(Number(startIdx)) || 0);
  /** @type {{ role: string, text: string, at: number, translation?: string }[]} */
  const out = [];
  for (let i = si; i < arr.length; i++) {
    const m = arr[i];
    if (!m || typeof m !== "object") continue;
    if (m.role !== "user" && m.role !== "assistant") continue;
    if (chatMessageDmSurface(m) !== "offline") continue;
    if (m.role === "assistant" && m.restoring && !String(m.content || "").trim()) continue;
    let text = offlineMessageTextForTranscriptArchive(m);
    const o = {
      role: m.role === "assistant" ? "assistant" : "user",
      text,
      at: Number.isFinite(Number(m.at)) ? Number(m.at) : 0
    };
    const trJoined = String(m.translation ?? "").trim();
    if (trJoined) o.translation = trJoined;
    out.push(o);
  }
  return out;
}

/**
 * 从挂断 notice 的 `callTranscript` 拼出给模型看的正文（不含界面代发头；与主聊天气泡同源字段，不另做字数截断）。
 * @param {unknown} m
 * @returns {string}
 */
function buildCallTranscriptBodyForApiFromNotice(m) {
  if (!m || typeof m !== "object" || !isChatNoticeCallEndedMessage(m)) return "";
  const tr = m.callTranscript;
  return formatChatTurnRowsTranscriptForApiPrompt(tr);
}

/**
 * @param {unknown} m
 * @returns {string}
 */
function buildOfflineTranscriptBodyForApiFromNotice(m) {
  if (!m || typeof m !== "object" || !isChatNoticeOfflineEndedMessage(m)) return "";
  const tr = m.offlineTranscript;
  return formatChatTurnRowsTranscriptForApiPrompt(tr);
}

/**
 * 锁屏结束票根：同屏聊对白实录（与「锁屏记录」预览同源）。
 * @param {unknown} m
 * @returns {string}
 */
function buildCharLockTranscriptBodyForApiFromNotice(m) {
  if (!m || typeof m !== "object" || !isChatNoticeCharLockEndedMessage(m)) return "";
  const tr = m.charLockTranscript;
  return formatChatTurnRowsTranscriptForApiPrompt(tr);
}

/** @param {unknown} m @returns {number} */
function countCharLockTranscriptUserRowsInNotice(m) {
  if (!isChatNoticeCharLockEndedMessage(m)) return 0;
  const tr = m && typeof m === "object" ? m.charLockTranscript : null;
  if (!Array.isArray(tr)) return 0;
  let n = 0;
  for (const row of tr) {
    if (row && row.role === "user" && String(row.text || "").trim()) n++;
  }
  return n;
}

/**
 * 单条 log 在「记忆摘要 / 对话记忆」里的加权条数（与 countChatLogWeightForMemoAutoSummary 同口径）。
 * @param {unknown} m
 */
function chatLogEntryMemoWeight(m) {
  if (!m || typeof m !== "object") return 0;
  if (m.charLockSessionOnly) return 0;
  if (m.role === "user" || m.role === "assistant") return 1;
  if (isChatNoticeCallEndedMessage(m)) {
    const tr = m.callTranscript;
    if (Array.isArray(tr) && tr.length) {
      return Math.max(1, tr.filter((row) => row && String(row.text || "").trim()).length);
    }
    return 1;
  }
  if (isChatNoticeOfflineEndedMessage(m)) {
    const tr = m.offlineTranscript;
    if (Array.isArray(tr) && tr.length) return Math.max(1, tr.length);
    return 1;
  }
  if (isChatNoticeCharLockEndedMessage(m)) {
    return 1 + countCharLockTranscriptUserRowsInNotice(m);
  }
  if (
    isChatNoticeCheckupFinishMessage(m) ||
    isChatNoticeCheckupCaughtMessage(m) ||
    isChatNoticeCheckupReverseFinishMessage(m)
  )
    return 1;
  return 0;
}

/** @param {readonly unknown[]} log */
function countChatLogWeightForMemoAutoSummary(log) {
  const arr = Array.isArray(log) ? log : [];
  let n = 0;
  for (const m of arr) n += chatLogEntryMemoWeight(m);
  return n;
}

/**
 * @param {unknown} v @returns {"" | "user" | "assistant"}
 */
function normalizeCallEndedByValue(v) {
  const s = String(v || "").trim();
  return s === "assistant" ? "assistant" : s === "user" ? "user" : "";
}

/** @param {unknown} extra 通话结束附加字段（忽略 click 事件的 Event 对象） */
function readChatCallEndNoticeExtra(extra) {
  if (!extra || typeof extra !== "object") return null;
  if (typeof Event !== "undefined" && extra instanceof Event) return null;
  if ("endedBy" in extra || "endCallNote" in extra || "declineMood" in extra) return extra;
  return null;
}

/** @param {unknown} m @returns {string} */
function formatCallEndHangUpClauseForApi(m) {
  const endedBy = normalizeCallEndedByValue(m && typeof m === "object" ? m.endedBy : "");
  if (!endedBy) return "";
  const note = String(m && typeof m === "object" ? m.endCallNote || "" : "")
    .trim()
    .slice(0, 80);
  if (endedBy === "user") return "由对方（用户）主动挂断";
  return note ? `由你（角色）主动挂断（${note}）` : "由你（角色）主动挂断";
}

/**
 * 通话挂断 `call_end`：与主聊天「界面代发 user」同一角色，写入 API messages（挂断票根并入主时间线）。
 * @param {{ role: string, content: string }[]} msgs
 * @param {unknown} m
 * @returns {boolean} 已消费（为 call_end 则 true，否则 false）
 */
function tryAppendCallEndNoticeToChatApiMessages(msgs, m) {
  if (!m || typeof m !== "object" || !isChatNoticeCallEndedMessage(m)) return false;
  const body = buildCallTranscriptBodyForApiFromNotice(m);
  const mode = String(m.callMode || "") === "video" ? "视频" : "语音";
  const initiator = String(m.callInitiator || "") === "assistant" ? "assistant" : "user";
  const declinedByUser = String(m.declinedBy || "") === "user";
  const connected = m.connected === true;
  const endedBy = normalizeCallEndedByValue(m.endedBy);
  const hangClause = formatCallEndHangUpClauseForApi(m);
  const whoInit =
    initiator === "assistant"
      ? "本通由你（角色）拨给对方"
      : "本通由对方（用户）拨给你";
  const endMeta = hangClause ? `${whoInit}，${hangClause}` : whoInit;
  if (body) {
    msgs.push({
      role: "user",
      content:
        `（界面代发、勿复述本句：${mode}通话已结束（${endMeta}）。以下为该通电话对白的完整归档，与主聊天记录属同一时间线，请承接记忆与后续剧情。）\n\n${body}`
    });
    return true;
  }
  if (connected) {
    msgs.push({
      role: "user",
      content: `（界面代发、勿复述本句：${mode}通话已结束（${endMeta}）。请按人设自然承接后续剧情，勿假装仍在通话中。）`
    });
    return true;
  }
  const declineMood = String(m.declineMood || "").trim();
  let hint = "";
  if (declinedByUser && initiator === "assistant") {
    hint = `对方（用户）拒接了你发起的${mode}通话。`;
  } else if (initiator === "user") {
    if (endedBy === "user" && !declineMood) {
      hint = `对方（用户）拨出${mode}通话后未接通即取消。`;
    } else if (declineMood) {
      hint = `你拒接了用户拨出的${mode}通话。拒接旁白：${declineMood}`;
    } else {
      hint = `你拒接了用户拨出的${mode}通话。`;
    }
  } else {
    hint = `${mode}通话未接通。`;
  }
  msgs.push({
    role: "user",
    content: `（界面代发、勿复述本句：${hint}请按人设自然承接后续剧情，勿假装仍在通话中。）`
  });
  return true;
}

/** @param {string} body */
function formatOfflineMeetSummaryApiUserContent(body) {
  const t = String(body || "").trim();
  if (!t) return "";
  return `（界面代发：当面已结束，下列属实发生过、计入记忆，勿假装仍在同场。）\n\n【当面 · 已发生】\n${t}`;
}

function tryAppendOfflineEndNoticeToChatApiMessages(msgs, m) {
  if (!m || typeof m !== "object" || !isChatNoticeOfflineEndedMessage(m)) return false;
  const body = buildOfflineTranscriptBodyForApiFromNotice(m).trim();
  if (m.offlineMeetSummary === true && body) {
    const inj = formatOfflineMeetSummaryApiUserContent(body);
    if (inj) msgs.push({ role: "user", content: inj });
    return true;
  }
  if (body) {
    msgs.push({
      role: "user",
      content:
        `（界面代发、勿复述本句：当面晤面已结束。以下为该段当面来往的完整归档，与主聊天记录属同一时间线，请承接记忆；勿重复假装仍在同场开口。）\n\n${body}`
    });
    return true;
  }
  const turnCount = Array.isArray(m.offlineTranscript) ? m.offlineTranscript.length : 0;
  const head =
    `（界面代发、勿复述本句：当面晤面已结束。上文时间线里已有该段当面来往气泡，请勿重复假装仍在同场开口；` +
    (turnCount > 0 ? `完整摘录可在界面「晤面结束」查看（共 ${turnCount} 条）。` : "") +
    `请承接记忆与后续剧情。）`;
  msgs.push({ role: "user", content: head });
  return true;
}

function formatChatRedpackNoticeLabel(m) {
  const grp = window.XXJ_GroupRedpack?.formatGroupRedpackNotice?.(m);
  if (grp) return grp;
  const act = String(m?.action || "").trim();
  const nm = getChatCharPersonaDisplayName();
  const by = String(m?.by || "").trim(); // "char" | "user"
  if (act === "claimed") return by === "user" ? `你已领取${nm}的红包` : `${nm}已领取你的红包`;
  if (act === "returned") return by === "user" ? `你已退回${nm}的红包` : `${nm}已退回你的红包`;
  return `${nm}处理了你的红包`;
}

/**
 * 对话记忆条数上限（与手帐「记忆摘要」条数同口径）；≤0 或未设置 = 不截断。
 * @param {object|null|undefined} thread
 */
function getThreadMemoryUserRounds(thread) {
  if (!thread || typeof thread !== "object") return 0;
  const n = Number(thread.memoryUserRounds);
  if (!Number.isFinite(n) || n <= 0) return 0;
  return Math.max(1, Math.floor(n));
}

function getActiveThreadMemoryUserRounds() {
  return getThreadMemoryUserRounds(readActiveThread());
}

/** @param {unknown} thread @returns {"recent" | "summary"} */
function getThreadChatMemoryMode(thread) {
  if (!thread || typeof thread !== "object") return "recent";
  const m = String(thread.chatMemoryMode || "").trim();
  if (m === "summary" || m === "recent") return m;
  const tail = Math.floor(Number(thread.memoSummaryRawTail));
  if (Number.isFinite(tail) && tail > 0) return "summary";
  return "recent";
}

/**
 * 自动摘要进度：加权条数 → readChatLog 0-based 起始下标（该下标起进入 API）。
 * @param {readonly unknown[]} log
 * @param {number} weightedExclusiveEnd
 */
function memoWeightedExclusiveEndToLogStart0(log, weightedExclusiveEnd) {
  const arr = Array.isArray(log) ? log : [];
  const target = Math.floor(Number(weightedExclusiveEnd));
  if (!Number.isFinite(target) || target <= 0) return 0;
  let weight = 0;
  for (let i = 0; i < arr.length; i++) {
    const w = chatLogEntryMemoWeight(arr[i]);
    if (w <= 0) continue;
    weight += w;
    if (weight >= target) return Math.min(arr.length, i + 1);
  }
  return arr.length;
}

/**
 * 自动摘要喂料区间（0-based log 下标）：与 memoAutoSummaryEveryUser / memoAutoSummaryLastUserCount 同加权口径。
 * @param {readonly unknown[]} log
 * @param {unknown} thread
 * @param {string} [maskId]
 * @returns {{ spanMin: number, spanMax: number, autoSummaryStart1: number }}
 */
function getMemoAutoSummaryFeedLogSpan0(log, thread, maskId) {
  const arr = Array.isArray(log) ? log : [];
  const spanMax = Math.max(0, arr.length - 1);
  if (!arr.length) return { spanMin: 0, spanMax: 0, autoSummaryStart1: 1 };
  const every = resolveThreadMemoAutoSummaryEveryUser(thread, maskId);
  const logLen = countChatLogWeightForMemoAutoSummary(arr);
  let last = Math.floor(Number(thread?.memoAutoSummaryLastUserCount ?? 0));
  if (last > logLen) last = logLen;
  let spanMin = 0;
  if (last > 0) {
    spanMin = memoWeightedExclusiveEndToLogStart0(arr, last);
  } else if (every > 0) {
    spanMin = findLogStartForAtLeastKMemoWeightsFrom(arr, 0, every);
  }
  spanMin = Math.max(0, Math.min(spanMin, spanMax));
  return { spanMin, spanMax, autoSummaryStart1: spanMin + 1 };
}

/**
 * @param {readonly unknown[]} log
 * @param {{ afterChatLogExclusiveEnd?: unknown, afterChatLogInclusiveStart?: unknown }} row
 * @returns {number | null}
 */
function memoSummaryRowExclusiveEndToLogStart0(log, row) {
  const end = Math.floor(Number(row?.afterChatLogExclusiveEnd));
  if (!Number.isFinite(end) || end < 0) return null;
  const start1 = Math.floor(Number(row?.afterChatLogInclusiveStart));
  if (Number.isFinite(start1) && start1 >= 1) {
    return Math.min(Array.isArray(log) ? log.length : 0, end);
  }
  return memoWeightedExclusiveEndToLogStart0(log, end);
}

/**
 * 已摘要覆盖区间在 log 上的 0-based 起点；无锚点则 null。
 * @param {readonly unknown[]} log
 * @param {unknown} thread
 */
function getMemoSummaryCoveredLogStart0(log, thread) {
  if (!thread || typeof thread !== "object") return null;
  const rows = readCharThreadMemorySummariesSorted(thread);
  const rolled = String(thread.charThreadMemoryRolled ?? "").trim();
  let cap = -1;
  let has = false;
  for (const r of rows) {
    const s0 = memoSummaryRowExclusiveEndToLogStart0(log, r);
    if (s0 == null) continue;
    has = true;
    cap = Math.max(cap, s0);
  }
  const manual = getMemoManualSummaryExclusiveEndLogIdx(thread);
  if (manual != null) {
    has = true;
    cap = Math.max(cap, Math.min(Array.isArray(log) ? log.length : 0, manual));
  }
  if (!has) return rolled ? 0 : null;
  return Math.max(0, cap);
}

/**
 * 自 fromLog0 起到末尾，至少保留 minWeight 条（记忆摘要口径）时对应的最早 log 下标。
 * @param {readonly unknown[]} log
 * @param {number} fromLog0
 * @param {number} minWeight
 */
function findLogStartForAtLeastKMemoWeightsFrom(log, fromLog0, minWeight) {
  const arr = Array.isArray(log) ? log : [];
  const from = Math.max(0, Math.floor(fromLog0));
  const k = Math.floor(Number(minWeight));
  if (!Number.isFinite(k) || k <= 0) return from;
  let seen = 0;
  for (let i = arr.length - 1; i >= from; i--) {
    seen += chatLogEntryMemoWeight(arr[i]);
    if (seen >= k) return i;
  }
  return from;
}

/**
 * 自 beforeLog0 前一条起向前数 minWeight 条（记忆摘要口径），返回对应最早 log 下标。
 * @param {readonly unknown[]} log
 * @param {number} beforeLog0 不含此下标（已摘要覆盖区间的 log 起点）
 * @param {number} minWeight
 */
function findLogStartForAtLeastKMemoWeightsBefore(log, beforeLog0, minWeight) {
  const arr = Array.isArray(log) ? log : [];
  const before = Math.floor(Number(beforeLog0));
  const k = Math.floor(Number(minWeight));
  if (!Number.isFinite(k) || k <= 0) return Math.max(0, before);
  let seen = 0;
  const last = Math.min(arr.length - 1, before - 1);
  if (last < 0) return 0;
  for (let i = last; i >= 0; i--) {
    seen += chatLogEntryMemoWeight(arr[i]);
    if (seen >= k) return i;
  }
  return 0;
}

/**
 * 「摘要后保留原文」：已摘要更早段不进 API（靠时间线）；N = 自**摘要边界**往已摘要段回溯 N 条原文，再接摘要后至下次摘要前的全部新消息（条数口径同手帐）。
 * 尚无摘要锚点时退化为近端 N 条。N=0 时摘要后段才进原文。
 * @param {readonly unknown[]} log
 * @param {unknown} thread
 */
function sliceChatLogForSummaryMemoryMode(log, thread) {
  const arr = Array.isArray(log) ? log : [];
  if (!arr.length || !thread || typeof thread !== "object") return arr;
  const tailN = Math.floor(Number(thread.memoSummaryRawTail));
  const tailK =
    Number.isFinite(tailN) && tailN > 0 ? Math.min(CHAT_MEMO_SUMMARY_RAW_TAIL_MAX, tailN) : 0;
  const sumStart = getMemoSummaryCoveredLogStart0(arr, thread);
  if (tailK <= 0 && sumStart == null) return arr;
  let apiStart = 0;
  if (sumStart != null) {
    if (tailK > 0) {
      apiStart = findLogStartForAtLeastKMemoWeightsBefore(arr, sumStart, tailK);
    } else {
      apiStart = sumStart;
    }
  } else if (tailK > 0) {
    apiStart = findLogStartForAtLeastKMemoWeightsFrom(arr, 0, tailK);
  }
  if (apiStart <= 0) return arr;
  return arr.slice(apiStart);
}

/**
 * 从 log 末尾按记忆摘要条数口径保留最近若干条及之后全部内容。
 * @param {unknown[]} log
 * @param {number} maxWeight
 */
function sliceChatLogByMemoRecordWeight(log, maxWeight) {
  const arr = Array.isArray(log) ? log : [];
  const cap = Math.floor(Number(maxWeight));
  if (!Number.isFinite(cap) || cap <= 0 || !arr.length) return arr;
  let seen = 0;
  let start = 0;
  for (let i = arr.length - 1; i >= 0; i--) {
    const w = chatLogEntryMemoWeight(arr[i]);
    if (w <= 0) continue;
    seen += w;
    if (seen >= cap) {
      start = i;
      break;
    }
  }
  if (seen < cap) return arr;
  return arr.slice(start);
}

/** @param {unknown[]} log @param {number} maxUserRounds */
function sliceChatLogByMemoryUserRounds(log, maxUserRounds) {
  return sliceChatLogByMemoRecordWeight(log, maxUserRounds);
}

/**
 * 按密谈「对话记忆」截取发给 API 的日志切片（条数口径同记忆摘要）。
 * `im` / `offline` 均在**完整时间线**上截断，窗口内可同时含线上与当面气泡（同一密谈已连续发生）。
 * - `offline`：user/assistant + **通话/晤面/锁屏票根归档**（不含撤回、红包灰字等）。
 * - `im`：同上，并保留窗口内全部系统通知（撤回、红包态等）。
 * @param {unknown[]} full
 * @param {"im" | "offline"} surface
 * @param {unknown} [thread]
 */
function sliceChatLogForApiMemoryWindow(full, surface, thread) {
  let arr = Array.isArray(full) ? full : [];
  if (thread && getThreadChatMemoryMode(thread) === "summary") {
    arr = sliceChatLogForSummaryMemoryMode(arr, thread);
  } else {
    const rounds = getThreadMemoryUserRounds(thread);
    arr = sliceChatLogByMemoryUserRounds(arr, rounds);
  }
  return arr.filter((m) => {
    if (!m || typeof m !== "object") return false;
    if (isChatSystemNotice(m)) {
      if (surface === "im") return true;
      return isChatTranscriptArchiveNotice(m);
    }
    return m.role === "user" || m.role === "assistant";
  });
}

/**
 * 重 roll / 长按重回：记忆条数截断不得丢掉「正在重生成的那条对方回复」所对应的上一条 user（含发图）。
 * @param {unknown[]} full
 * @param {"im" | "offline"} surface
 * @param {unknown} [thread]
 */
function sliceChatLogForApiMemoryWindowAnchoredToLastUser(full, surface, thread) {
  const arr = Array.isArray(full) ? full : [];
  const base = sliceChatLogForApiMemoryWindow(arr, surface, thread);
  if (!arr.length) return base;
  let lastUserIdx = -1;
  for (let i = arr.length - 1; i >= 0; i--) {
    const m = arr[i];
    if (!m || typeof m !== "object" || m.role !== "user") continue;
    if (m.charLockSessionOnly) continue;
    lastUserIdx = i;
    break;
  }
  if (lastUserIdx < 0) return base;
  const anchor = sliceChatLogForApiMemoryWindow(arr.slice(lastUserIdx), surface, thread);
  if (!anchor.length) return base;
  const anchorHead = anchor[0];
  if (base.some((m) => m === anchorHead)) return base;
  let baseStart = 0;
  if (base.length) {
    const bi = arr.indexOf(base[0]);
    if (bi >= 0) baseStart = bi;
  }
  const anchorStart = arr.indexOf(anchorHead);
  if (anchorStart < 0) return base;
  const start = Math.min(baseStart, anchorStart);
  return sliceChatLogForApiMemoryWindow(arr.slice(start), surface, thread);
}

function readChatLogForApiForSurface(surface) {
  const full = readChatLog();
  return sliceChatLogForApiMemoryWindow(full, surface, readActiveThread());
}

/** 指定面具与会话 ID，避免长请求期间用户切换密谈后读写串线程 */
function readChatLogForApiForMaskThread(surface, maskId, threadId) {
  const full = readChatLogForMaskThread(maskId, threadId);
  const found = findChatThreadInInbox(maskId, threadId);
  return sliceChatLogForApiMemoryWindow(full, surface, found?.thread);
}

function readChatLogForApi() {
  return readChatLogForApiForSurface(getActiveChatDmSurfaceForContext());
}

/** 本条消息所属「频道」：即时消息 im / 线下 offline（仅后者写入 dmSurface）。 */
function chatMessageDmSurface(m) {
  if (!m || typeof m !== "object") return "im";
  return m.dmSurface === "offline" ? "offline" : "im";
}

/**
 * 当前 UI 要展示的消息条目（realIdx 供长按/纠错等）。
 * @param {"im" | "offline" | "all"} uiSurface `all`：历史兼容，等同展示全部用户/助手（现已不在线下页使用）；`offline` 仅线下产生的消息
 */
function uiChatMessageEntryVisibleAt(arr, i, uiSurface) {
  const m = arr[i];
  if (!m || typeof m !== "object") return false;
  if (!(m.role === "user" || m.role === "assistant" || isChatSystemNotice(m))) return false;
  if (isChatSystemNotice(m)) return uiSurface !== "offline";
  if (m.charLockSessionOnly) return false;
  if (isPersonaFoldBoundaryMessage(m)) return uiSurface !== "offline";
  if (uiSurface === "all") return true;
  const surf = chatMessageDmSurface(m);
  if (uiSurface === "offline" && surf !== "offline") return false;
  if (uiSurface !== "offline" && surf === "offline") return false;
  return true;
}

function buildUiChatMessageEntries(log, uiSurface) {
  const arr = Array.isArray(log) ? log : [];
  /** @type {{ realIdx: number, m: object }[]} */
  const out = [];
  for (let i = 0; i < arr.length; i++) {
    if (uiChatMessageEntryVisibleAt(arr, i, uiSurface)) out.push({ realIdx: i, m: arr[i] });
  }
  return out;
}

/**
 * 单次扫描：统计可见条数 L，并保留尾部 maxTail 条（长聊进房首帧免 build 全表）。
 * @returns {{ L: number, tail: { realIdx: number, m: object }[], tailStartJ: number }}
 */
function scanUiChatVisibleEntriesTail(arr, uiSurface, maxTail, th) {
  const log = Array.isArray(arr) ? arr : [];
  const cap = Math.max(CHAT_RENDER_COLLAPSE_KEEP_LAST, Math.floor(Number(maxTail)) || 0);
  const cacheKey = th ? uiVisibleCountCacheKey(log, uiSurface) : "";
  let L = 0;
  /** @type {{ realIdx: number, m: object }[]} */
  const tail = [];

  if (th && cacheKey && th._uiVisibleLenKey === cacheKey && Number.isFinite(Number(th._uiVisibleLen))) {
    L = Number(th._uiVisibleLen);
    for (let i = log.length - 1; i >= 0; i--) {
      if (!uiChatMessageEntryVisibleAt(log, i, uiSurface)) continue;
      tail.unshift({ realIdx: i, m: log[i] });
      if (tail.length >= cap) break;
    }
    return { L, tail, tailStartJ: L - tail.length };
  }

  for (let i = 0; i < log.length; i++) {
    if (!uiChatMessageEntryVisibleAt(log, i, uiSurface)) continue;
    L++;
    tail.push({ realIdx: i, m: log[i] });
    if (tail.length > cap) tail.shift();
  }
  if (th && cacheKey) {
    th._uiVisibleLenKey = cacheKey;
    th._uiVisibleLen = L;
  }
  return { L, tail, tailStartJ: L - tail.length };
}

/** @param {{ realIdx: number, m: object }[]} tail */
function buildSparseUiChatRenderEntries(L, tail, tailStartJ) {
  if (L <= tail.length) return tail.slice();
  /** @type {{ realIdx: number, m: object }[]} */
  const entries = new Array(L);
  for (let t = 0; t < tail.length; t++) entries[tailStartJ + t] = tail[t];
  return entries;
}

/** 长聊：只物化折叠窗附近 entries，不写 uiEntries 全量缓存。 */
function resolveChatRenderUiEntriesSparse(log, uiSurface, th) {
  const reveal = Math.max(0, chatHistoryOlderRevealCount);
  const cap = CHAT_RENDER_COLLAPSE_KEEP_LAST + reveal + 8;
  const cacheKey = th ? `${uiVisibleCountCacheKey(log, uiSurface)}\t${reveal}` : "";
  if (th && cacheKey && th._uiSparseEntriesKey === cacheKey && Array.isArray(th._uiSparseEntries)) {
    return th._uiSparseEntries;
  }
  const scanned = scanUiChatVisibleEntriesTail(log, uiSurface, cap, th);
  const entries =
    scanned.L <= cap ? scanned.tail.slice() : buildSparseUiChatRenderEntries(scanned.L, scanned.tail, scanned.tailStartJ);
  if (th && cacheKey) {
    th._uiSparseEntriesKey = cacheKey;
    th._uiSparseEntries = entries;
  }
  return entries;
}

/** @returns {boolean} 是否有改写并 save */
function normalizeChatLogForRenderAndSave(log) {
  let dirty = false;
  if (normalizeAssistantQuoteStorageInLog(log)) dirty = true;
  if (normalizeAssistantStickerDirectiveTextInLog(log)) dirty = true;
  if (normalizeAssistantTranslationStructuredInLog(log)) dirty = true;
  if (dirty) saveChatLog(log);
  return dirty;
}

/** 进密谈首帧画完后：补 normalize / 心声同步（避免首帧卡死）。 */
function scheduleChatOpenThreadDeferredPreamble() {
  window.requestAnimationFrame(() => {
    chatDeferInnerVoiceSyncNextRender = false;
    const log = readChatLog();
    if (normalizeChatLogForRenderAndSave(log)) {
      invalidateChatUiEntriesRenderCache();
      chatSuppressNextChatMessageAnimations = true;
      scheduleRenderChatMessages();
      return;
    }
    syncChatInnerVoicePanelFromLog();
    const shellSurface = getActiveChatDmSurfaceForContext();
    const uiSurface = shellSurface === "offline" ? "offline" : "im";
    resolveChatRenderUiEntriesForLog(readChatLog(), uiSurface, shellSurface, readActiveThread());
  });
}

function chatUiEntriesRenderBaseKey(uiSurface) {
  const ref = readChatActiveThreadRef();
  return `${ref.maskId}\t${ref.threadId}\t${uiSurface}`;
}

function invalidateChatUiEntriesRenderCache() {
  chatUiEntriesRenderCache = { baseKey: "", uiSurface: "", logLen: 0, entries: null };
  chatPersonaFoldWindowsRenderCache = { key: "", windows: null, L: 0 };
  invalidateThreadUiVisibleEntryCount(readActiveThread());
}

function resolveChatRenderUiEntries(log, uiSurface) {
  const arr = Array.isArray(log) ? log : [];
  const baseKey = chatUiEntriesRenderBaseKey(uiSurface);
  const cache = chatUiEntriesRenderCache;
  if (
    cache.entries &&
    cache.baseKey === baseKey &&
    cache.uiSurface === uiSurface &&
    cache.logLen === arr.length
  ) {
    return cache.entries;
  }
  if (
    cache.entries &&
    cache.baseKey === baseKey &&
    cache.uiSurface === uiSurface &&
    cache.logLen === arr.length - 1 &&
    arr.length > 0
  ) {
    const lastI = arr.length - 1;
    if (
      uiChatMessageEntryVisibleAt(arr, lastI, uiSurface) &&
      !cache.entries.some((e) => e.realIdx === lastI)
    ) {
      const next = cache.entries.concat([{ realIdx: lastI, m: arr[lastI] }]);
      chatUiEntriesRenderCache = { baseKey, uiSurface, logLen: arr.length, entries: next };
      return next;
    }
  }
  const built = buildUiChatMessageEntries(log, uiSurface);
  chatUiEntriesRenderCache = { baseKey, uiSurface, logLen: arr.length, entries: built };
  return built;
}

function resolveInactivePersonaFoldWindowsForRender(
  renderEntries,
  activePersonaRender,
  charItemRender,
  thChat,
  shellSurface,
  skipLogNormalize
) {
  if (!charHasAltPersona(charItemRender) || !isThreadPersonaFoldOtherEnabled(thChat)) return null;
  const ref = readChatActiveThreadRef();
  const L = renderEntries.length;
  const key = `${ref.maskId}\t${ref.threadId}\t${shellSurface}\t${activePersonaRender}\t${L}`;
  const prev = chatPersonaFoldWindowsRenderCache;
  if (
    skipLogNormalize &&
    prev.windows &&
    prev.L === L - 1 &&
    prev.key === `${ref.maskId}\t${ref.threadId}\t${shellSurface}\t${activePersonaRender}\t${L - 1}` &&
    renderEntries[L - 1]?.m?.role === "user"
  ) {
    chatPersonaFoldWindowsRenderCache = { key, windows: prev.windows, L };
    return prev.windows;
  }
  const windows = buildInactivePersonaFoldWindows(renderEntries, activePersonaRender);
  chatPersonaFoldWindowsRenderCache = { key, windows, L };
  return windows;
}

function tagAssistantEntryDmSurface(entry, roundDmSurface) {
  if (!entry || typeof entry !== "object") return;
  const s = typeof roundDmSurface === "string" ? roundDmSurface : getActiveChatDmSurfaceForContext();
  if (s === "offline") entry.dmSurface = "offline";
  else delete entry.dmSurface;
}

/** 用户侧写入（文字 / 图 / 表情等）：当前在线下页则标记离线频道；并标记发送时马甲段。 */
function tagOutgoingChatDmSurfaceIfOffline(entry) {
  if (!entry || typeof entry !== "object") return;
  if (getActiveChatDmSurfaceForContext() === "offline") {
    entry.dmSurface = "offline";
    if (entry.role === "user") {
      delete entry.asVoice;
      delete entry.voiceSeconds;
      delete entry.sticker;
      delete entry.redpack;
      delete entry.image;
    }
  }
  if (entry.role === "user") tagOutgoingUserMessagePersonaEpoch(entry);
}

/** 更多面板：群聊隐藏单聊项；线下晤面隐藏即时消息类入口。 */
function syncChatMoreDrawerVisibility() {
  const th = readActiveThread();
  const isGroup = isChatThreadGroupForUi(th);
  const offline = isChatOfflineScreenOpen();
  const drawer = document.getElementById("chat-more-drawer");
  const sheet = document.getElementById("chat-more-sheet");
  if (drawer) drawer.classList.toggle("chat-more-drawer--group", isGroup);
  if (sheet) sheet.classList.toggle("chat-more-sheet--group", isGroup);
  if (!drawer) return;
  const offlineSuppress = new Set(["voice", "photo", "sticker", "redpack", "call-audio", "call-video"]);
  for (const el of drawer.querySelectorAll(".chat-more-drawer-item[data-action]")) {
    if (!(el instanceof HTMLElement)) continue;
    if (el.closest("#chat-more-persona-wrap")) continue;
    const action = String(el.getAttribute("data-action") || "").trim();
    if (!action) continue;
    const dmOnly = el.hasAttribute("data-chat-more-dm-only");
    const hide = (isGroup && dmOnly) || (offline && offlineSuppress.has(action));
    el.hidden = hide;
    el.setAttribute("aria-hidden", hide ? "true" : "false");
    if (dmOnly) {
      if (hide) el.style.setProperty("display", "none", "important");
      else el.style.removeProperty("display");
    }
  }
}

/** 列表预览等：忽略线下频道，只取即时消息最后气泡。 */
function chatLogLastBubbleMessageImOnly(log) {
  const arr = Array.isArray(log) ? log : [];
  for (let j = arr.length - 1; j >= 0; j--) {
    const m = arr[j];
    if (m && (m.role === "user" || m.role === "assistant")) {
      if (m.charLockSessionOnly) continue;
      if (chatMessageDmSurface(m) === "offline") continue;
      return m;
    }
  }
  return null;
}

function chatLogLastBubbleMessageForActiveUiSurface() {
  const log = readChatLog();
  const wantOffline = getActiveChatDmSurfaceForContext() === "offline";
  for (let j = log.length - 1; j >= 0; j--) {
    const m = log[j];
    if (!m || (m.role !== "user" && m.role !== "assistant")) continue;
    if (wantOffline && chatMessageDmSurface(m) !== "offline") continue;
    if (!wantOffline && chatMessageDmSurface(m) === "offline") continue;
    return m;
  }
  return null;
}

/** 列表预览 / 动画：忽略系统提示条，取最后一条对话气泡 */
function chatLogLastBubbleMessage(log) {
  const arr = Array.isArray(log) ? log : [];
  for (let j = arr.length - 1; j >= 0; j--) {
    const m = arr[j];
    if (m && (m.role === "user" || m.role === "assistant")) return m;
  }
  return null;
}

/** readChatLog 过滤结果缓存（同密谈内避免 render 反复 filter 全表） */
let chatLogViewCacheKey = "";
/** @type {unknown[] | null} */
let chatLogViewCache = null;
/** 已确认无需红包系统提示迁移的密谈 */
const chatRedpackNoticeCheckedKeys = new Set();

function invalidateChatLogViewCache() {
  chatLogViewCacheKey = "";
  chatLogViewCache = null;
}

/** @type {Map<string, Promise<boolean>>} */
const chatThreadMsgsHydrateInflight = new Map();

function isThreadMessagesSplitStored(th) {
  const mark = window.XXJ_DB && window.XXJ_DB.CHAT_MSGS_SPLIT_MARK;
  return (
    th &&
    typeof th === "object" &&
    (th.messagesStore === "split" || (mark && th.messagesStore === mark))
  );
}

/** 密谈列表：分表时 messages 不在内存，用 messageCount 兜底 */
function threadMessageCountForList(thread) {
  if (!thread || typeof thread !== "object") return 0;
  const inlineLen = Array.isArray(thread.messages) ? thread.messages.length : 0;
  const mc = Number(thread.messageCount);
  if (Number.isFinite(mc) && mc > inlineLen) return Math.floor(mc);
  return inlineLen;
}

/** 列表预览用消息行（内存 messages 或异步灌入的 _listPreviewLog） */
function threadListLogForPreview(thread) {
  if (!thread || typeof thread !== "object") return [];
  if (Array.isArray(thread.messages) && thread.messages.length > 0) return thread.messages;
  if (Array.isArray(thread._listPreviewLog) && thread._listPreviewLog.length) return thread._listPreviewLog;
  return [];
}

let chatThreadListPreviewHydrateGen = 0;

/** 分表密谈：为列表异步拉取末尾几条消息，仅用于预览/条数，不灌全量 */
async function hydrateChatThreadListPreviews(maskId, threads) {
  const D = window.XXJ_DB;
  if (!D || typeof D.chatMsgsGetPage !== "function") return;
  const list = Array.isArray(threads) ? threads : [];
  const need = list.filter(
    (t) =>
      t &&
      threadMessageCountForList(t) > 0 &&
      (!Array.isArray(t.messages) || !t.messages.length) &&
      (!Array.isArray(t._listPreviewLog) || !t._listPreviewLog.length)
  );
  if (!need.length) return;
  const gen = ++chatThreadListPreviewHydrateGen;
  const storeMaskKey = maskBucketKey(maskId);
  await D.ready;
  let changed = false;
  for (const th of need) {
    if (gen !== chatThreadListPreviewHydrateGen) return;
    const tid = String(th.id || "").trim();
    if (!tid) continue;
    try {
      const page = await D.chatMsgsGetPage(storeMaskKey, tid, 0, 48);
      const tail = page && Array.isArray(page.messages) ? page.messages : [];
      if (tail.length) {
        th._listPreviewLog = tail;
        changed = true;
      }
    } catch (err) {
      console.warn("XXJ: hydrateChatThreadListPreviews failed", storeMaskKey, tid, err);
    }
  }
  if (changed && gen === chatThreadListPreviewHydrateGen) {
    const listEl = document.getElementById("chat-list-screen");
    if (listEl && listEl.classList.contains("is-open")) renderChatThreadList();
  }
}

function threadMessagesNeedHydrate(th) {
  if (!th || typeof th !== "object") return false;
  if (Array.isArray(th.messages) && th.messages.length > 0) return false;
  return isThreadMessagesSplitStored(th) || (Number(th.messageCount) > 0 && Number.isFinite(Number(th.messageCount)));
}

function chatUiThreadLruKey(maskId, threadId) {
  return `${String(maskId || "").trim()}\t${String(threadId || "").trim()}`;
}

/** 记录最近打开的密谈；LRU 溢出时将长聊内联 messages 外置分表。 */
function touchChatUiFullMessagesLru(maskId, threadId) {
  const k = chatUiThreadLruKey(maskId, threadId);
  const evicted = [];
  chatUiFullMessagesLru = chatUiFullMessagesLru.filter((x) => x !== k);
  chatUiFullMessagesLru.unshift(k);
  while (chatUiFullMessagesLru.length > CHAT_UI_FULL_MESSAGES_LRU) {
    const drop = chatUiFullMessagesLru.pop();
    if (drop) evicted.push(drop);
  }
  for (const ek of evicted) {
    const tab = ek.indexOf("\t");
    if (tab <= 0) continue;
    void offloadChatThreadMessagesIfCold(ek.slice(0, tab), ek.slice(tab + 1));
  }
}

/**
 * 长聊离屏：内联 messages 写入 chat_thread_msgs，inbox 只留预览与 messageCount。
 * @param {string} maskId
 * @param {string} threadId
 */
async function offloadChatThreadMessagesIfCold(maskId, threadId) {
  const found = findChatThreadInInbox(maskId, threadId);
  if (!found) return false;
  const th = found.thread;
  if (!Array.isArray(th.messages) || th.messages.length < CHAT_MEMORY_TRIM_MIN) return false;
  if (isThreadMessagesSplitStored(th)) return false;
  if (isUserViewingChatThread(maskId, threadId)) return false;
  const D = window.XXJ_DB;
  if (!D || typeof D.chatMsgsPut !== "function") return false;
  const storeMaskKey = maskBucketKey(maskId);
  const tid = String(threadId || "").trim();
  if (!tid) return false;
  const msgs = th.messages.slice();
  try {
    await D.ready;
    await D.chatMsgsPut(storeMaskKey, tid, msgs, th.updatedAt || Date.now());
  } catch (err) {
    console.warn("XXJ: offloadChatThreadMessagesIfCold failed", storeMaskKey, tid, err);
    return false;
  }
  const mark = D.CHAT_MSGS_SPLIT_MARK || "split";
  th._listPreviewLog = msgs.length ? [msgs[msgs.length - 1]] : [];
  th.messageCount = msgs.length;
  th.messagesStore = mark;
  th.messages = [];
  delete th._uiLogPartial;
  delete th._uiLogLoadedFromEnd;
  delete th._apiLogPartial;
  invalidateThreadUiVisibleEntryCount(th);
  invalidateChatLogViewCache();
  writeChatInboxStore(found.inbox, {
    fast: true,
    dirtyThreadKey: chatDirtyThreadPersistKey(maskId, threadId)
  });
  return true;
}

/** 分表 + `_uiLogPartial`：展开更早时从 IndexedDB 再拉一页 prepend。 */
async function loadOlderChatMessagesPageForUi(maskId, threadId, th) {
  if (!th || !th._uiLogPartial) return false;
  const D = window.XXJ_DB;
  if (!D || typeof D.chatMsgsGetPage !== "function") {
    await ensureThreadMessagesHydrated(maskId, threadId, th);
    return false;
  }
  const storeMaskKey = maskBucketKey(maskId);
  const tid = String(threadId || "").trim();
  if (!tid) return false;
  const off = Number(th._uiLogLoadedFromEnd) || (Array.isArray(th.messages) ? th.messages.length : 0);
  try {
    await D.ready;
    const page = await D.chatMsgsGetPage(storeMaskKey, tid, off, CHAT_UI_HYDRATE_PAGE);
    const older = page && Array.isArray(page.messages) ? page.messages : [];
    if (!older.length) {
      th._uiLogPartial = false;
      return false;
    }
    th.messages = older.concat(Array.isArray(th.messages) ? th.messages : []);
    th._uiLogLoadedFromEnd = off + older.length;
    th.messageCount = Number(page?.total) || threadMessageCountForList(th);
    if (!page?.hasMore) th._uiLogPartial = false;
    invalidateThreadUiVisibleEntryCount(th);
    return true;
  } catch (err) {
    console.warn("XXJ: loadOlderChatMessagesPageForUi failed", storeMaskKey, tid, err);
    return false;
  }
}

/**
 * 强制从分表读全量（`_uiLogPartial` 时 threadMessagesNeedHydrate 已为 false，不能走普通 hydrate）。
 * @param {string} maskId
 * @param {string} threadId
 * @param {object} th
 */
async function ensureThreadMessagesHydratedFullFromStore(maskId, threadId, th) {
  if (!th || typeof th !== "object") return false;
  if (!th._uiLogPartial && !isThreadMessagesSplitStored(th)) {
    if (!Array.isArray(th.messages)) th.messages = [];
    return true;
  }
  const D = window.XXJ_DB;
  if (!D || typeof D.chatMsgsGet !== "function") {
    if (!Array.isArray(th.messages)) th.messages = [];
    return true;
  }
  const storeMaskKey = maskBucketKey(maskId);
  const tid = String(threadId || "").trim();
  if (!tid) return false;
  try {
    await D.ready;
    const row = await D.chatMsgsGet(storeMaskKey, tid);
    th.messages = row && Array.isArray(row.messages) ? row.messages.slice() : [];
    th.messageCount = th.messages.length;
    th._apiLogPartial = false;
    delete th._uiLogPartial;
    delete th._uiLogLoadedFromEnd;
    delete th.messagesStore;
    invalidateThreadUiVisibleEntryCount(th);
    return true;
  } catch (err) {
    console.warn("XXJ: ensureThreadMessagesHydratedFullFromStore failed", storeMaskKey, tid, err);
    return false;
  }
}

/**
 * `_uiLogPartial` 落盘前：全量前缀 + 内存尾段合并，避免只保存末尾一页。
 * @param {string} maskId
 * @param {string} threadId
 * @param {object} th
 * @param {unknown[]} entries
 */
async function ensureChatLogEntriesBeforePersist(maskId, threadId, th, entries) {
  const arr = Array.isArray(entries) ? entries : [];
  if (!th || !th._uiLogPartial) return arr;
  const loadedFromEnd =
    Number(th._uiLogLoadedFromEnd) ||
    (Array.isArray(th.messages) ? th.messages.length : 0) ||
    arr.length;
  const ok = await ensureThreadMessagesHydratedFullFromStore(maskId, threadId, th);
  if (!ok) return arr;
  const full = Array.isArray(th.messages) ? th.messages.slice() : [];
  if (!arr.length) return full;
  const prefixEnd = Math.max(0, full.length - loadedFromEnd);
  if (prefixEnd <= 0) return arr;
  return full.slice(0, prefixEnd).concat(arr);
}

/**
 * 分表密谈：从 IndexedDB chat_thread_msgs 灌入 thread.messages。
 * @param {string} maskId
 * @param {string} threadId
 * @param {object} th
 * @param {{ uiOnly?: boolean }} [opts] uiOnly：开聊首屏只拉末尾一页
 */
async function ensureThreadMessagesHydrated(maskId, threadId, th, opts) {
  if (!th || !threadMessagesNeedHydrate(th)) {
    if (th && !Array.isArray(th.messages)) th.messages = [];
    return true;
  }
  const uiOnly = Boolean(opts && opts.uiOnly);
  const D = window.XXJ_DB;
  if (!D || typeof D.chatMsgsGet !== "function") {
    if (!Array.isArray(th.messages)) th.messages = [];
    return true;
  }
  const storeMaskKey = maskBucketKey(maskId);
  const tid = String(threadId || "").trim();
  if (!tid) return false;
  const tk =
    typeof D.chatThreadKey === "function"
      ? D.chatThreadKey(storeMaskKey, tid)
      : `${storeMaskKey}\x1f${tid}`;
  if (chatThreadMsgsHydrateInflight.has(tk)) {
    return chatThreadMsgsHydrateInflight.get(tk);
  }
  const job = (async () => {
    try {
      await D.ready;
      const mc = Number(th.messageCount);
      const totalHint =
        Number.isFinite(mc) && mc > 0 ? Math.floor(mc) : 0;
      if (uiOnly && typeof D.chatMsgsGetPage === "function" && totalHint > CHAT_UI_HYDRATE_PAGE) {
        const page = await D.chatMsgsGetPage(storeMaskKey, tid, 0, CHAT_UI_HYDRATE_PAGE);
        const tail = page && Array.isArray(page.messages) ? page.messages : [];
        th.messages = tail.slice();
        th.messageCount = Number(page?.total) || totalHint || tail.length;
        th._uiLogPartial = Boolean(page?.hasMore);
        th._uiLogLoadedFromEnd = tail.length;
        th._apiLogPartial = Boolean(page?.hasMore);
        delete th.messagesStore;
        invalidateThreadUiVisibleEntryCount(th);
        return true;
      }
      const row = await D.chatMsgsGet(storeMaskKey, tid);
      th.messages = row && Array.isArray(row.messages) ? row.messages.slice() : [];
      th.messageCount = th.messages.length;
      th._apiLogPartial = false;
      delete th._uiLogPartial;
      delete th._uiLogLoadedFromEnd;
      delete th.messagesStore;
      invalidateThreadUiVisibleEntryCount(th);
      return true;
    } catch (err) {
      console.warn("XXJ: ensureThreadMessagesHydrated failed", storeMaskKey, tid, err);
      return false;
    }
  })();
  chatThreadMsgsHydrateInflight.set(tk, job);
  try {
    return await job;
  } finally {
    chatThreadMsgsHydrateInflight.delete(tk);
  }
}

/** API 发请求前：有记忆条数上限时只拉尾部消息，避免长聊全量读 IndexedDB */
function apiHydrateMessageLimit(thread) {
  if (!thread || typeof thread !== "object") return 0;
  if (getThreadChatMemoryMode(thread) === "summary") return 0;
  const rounds = getThreadMemoryUserRounds(thread);
  if (!rounds) return 0;
  return Math.min(5000, Math.max(200, rounds * 6 + 80));
}

/** 内存里已有足够消息可发 API，无需再读 IndexedDB */
function threadMessagesApiCacheReady(th, threadMeta) {
  if (!th || !Array.isArray(th.messages) || th.messages.length === 0) return false;
  if (!th._apiLogPartial) return true;
  const total = threadMessageCountForList(th);
  const limit = apiHydrateMessageLimit(threadMeta && typeof threadMeta === "object" ? threadMeta : th);
  if (!limit) return th.messages.length >= total;
  return th.messages.length >= Math.min(total, limit);
}

async function ensureThreadMessagesForApi(maskId, threadId, th, threadMeta) {
  if (!th) return true;
  const meta = threadMeta && typeof threadMeta === "object" ? threadMeta : th;
  if (threadMessagesApiCacheReady(th, meta)) return true;
  const limit = apiHydrateMessageLimit(meta);
  if (!limit) {
    return ensureThreadMessagesHydrated(maskId, threadId, th);
  }
  if (!threadMessagesNeedHydrate(th)) {
    if (!Array.isArray(th.messages)) th.messages = [];
    th._apiLogPartial = false;
    return true;
  }
  const D = window.XXJ_DB;
  if (!D || typeof D.chatMsgsGetPage !== "function") {
    return ensureThreadMessagesHydrated(maskId, threadId, th);
  }
  const storeMaskKey = maskBucketKey(maskId);
  const tid = String(threadId || "").trim();
  if (!tid) return false;
  const tk =
    typeof D.chatThreadKey === "function"
      ? D.chatThreadKey(storeMaskKey, tid)
      : `${storeMaskKey}\x1f${tid}`;
  if (chatThreadMsgsHydrateInflight.has(tk)) {
    return chatThreadMsgsHydrateInflight.get(tk);
  }
  const job = (async () => {
    try {
      await D.ready;
      const page = await D.chatMsgsGetPage(storeMaskKey, tid, 0, limit);
      const tail = page && Array.isArray(page.messages) ? page.messages : [];
      th.messages = tail.slice();
      th.messageCount = Number(page?.total) || tail.length;
      th._apiLogPartial = Boolean(page?.hasMore);
      if (!tail.length) delete th.messagesStore;
      return true;
    } catch (err) {
      console.warn("XXJ: ensureThreadMessagesForApi failed", storeMaskKey, tid, err);
      return ensureThreadMessagesHydrated(maskId, threadId, th);
    }
  })();
  chatThreadMsgsHydrateInflight.set(tk, job);
  try {
    return await job;
  } finally {
    chatThreadMsgsHydrateInflight.delete(tk);
  }
}

async function ensureActiveThreadMessagesHydrated(opts) {
  const ref = readChatActiveThreadRef();
  const found = findChatThreadInInbox(ref.maskId, ref.threadId);
  if (!found) return false;
  const uiOnly = !(opts && opts.full);
  const ok = await ensureThreadMessagesHydrated(ref.maskId, ref.threadId, found.thread, { uiOnly });
  if (ok && uiOnly) touchChatUiFullMessagesLru(ref.maskId, ref.threadId);
  return ok;
}

function readChatLog() {
  const D = window.XXJ_DB;
  if (D && D.isReady && !D.isInboxHydrated) return [];
  reconcileActiveThreadRef();
  const maskId = getActiveMaskIdForInbox();
  const ref = readChatActiveThreadRef();
  const viewKey = `${maskId}\t${ref.threadId}`;
  if (viewKey === chatLogViewCacheKey && chatLogViewCache) return chatLogViewCache;
  const inbox = readChatInboxStore();
  if (D && D.isInboxHydrated && !chatInboxMemCache) warmChatInboxMemCacheFromDb();
  ensureMaskBucket(inbox, maskId);
  const bucket = inbox.byMask[maskBucketKey(maskId)];
  const th = bucket.threads.find((t) => t.id === ref.threadId);
  if (!th) return [];
  if (threadMessagesNeedHydrate(th)) {
    void ensureThreadMessagesHydrated(maskId, ref.threadId, th, { uiOnly: true }).then(() => {
      touchChatUiFullMessagesLru(maskId, ref.threadId);
      invalidateChatLogViewCache();
      scheduleRenderChatMessages();
    });
    if (viewKey === chatLogViewCacheKey && chatLogViewCache) return chatLogViewCache;
    return [];
  }
  if (!Array.isArray(th.messages)) return [];
  // 迁移兜底：如果某条红包已领取/已退回但缺少灰色系统提示，则自动补齐并写回（每密谈只扫一次）
  if (D && D.isInboxHydrated && !chatRedpackNoticeCheckedKeys.has(viewKey)) {
    try {
      const copy = th.messages.slice();
      if (ensureRedpackNoticesInLog(copy)) {
        th.messages = copy.slice();
        th.updatedAt = Date.now();
        invalidateChatLogViewCache();
        writeChatInboxStore(inbox, {
          fast: true,
          dirtyThreadKey: chatDirtyThreadPersistKey(maskId, ref.threadId)
        });
      } else {
        chatRedpackNoticeCheckedKeys.add(viewKey);
      }
    } catch (_) {
      /* ignore */
    }
  }
  const filtered = th.messages.filter(
    (m) =>
      m &&
      typeof m === "object" &&
      (m.role === "user" || m.role === "assistant" || isChatSystemNotice(m))
  );
  chatLogViewCacheKey = viewKey;
  chatLogViewCache = filtered;
  return filtered;
}

function applyChatLogEntriesToThread(th, entries) {
  th.messages = Array.isArray(entries) ? entries.slice() : [];
  th.updatedAt = Date.now();
  delete th._listPreviewLog;
  delete th._apiLogPartial;
  delete th._uiLogPartial;
  delete th._uiLogLoadedFromEnd;
  invalidateThreadUiVisibleEntryCount(th);
  if (th.messages.length > 0) {
    th.messageCount = th.messages.length;
  } else {
    th.messageCount = 0;
    delete th.messagesStore;
  }
}

/**
 * 分表仅尾段在内存：乐观写 messages 供 UI / 流式读，保留 `_uiLogPartial` 供后续全量前缀合并。
 */
function applyChatLogTailEntriesOptimistic(th, entries) {
  const arr = Array.isArray(entries) ? entries.slice() : [];
  th.messages = arr;
  th.updatedAt = Date.now();
  if (th._uiLogPartial) {
    const tailLen = arr.length;
    const prevLoaded = Number(th._uiLogLoadedFromEnd);
    th._uiLogLoadedFromEnd =
      Number.isFinite(prevLoaded) && prevLoaded > 0 ? Math.max(prevLoaded, tailLen) : tailLen;
  }
  invalidateThreadUiVisibleEntryCount(th);
}

/** 同步写入 thread.messages 并刷新渲染缓存（UI 须立即可见）。 */
function commitChatLogEntriesForMaskThread(maskId, threadId, th, inbox, entries, persistOpts) {
  const arr = Array.isArray(entries) ? entries.slice() : [];
  applyChatLogEntriesToThread(th, arr);
  invalidateChatLogViewCache();
  invalidateChatUiEntriesRenderCache();
  const pOpts = persistOpts && typeof persistOpts === "object" ? persistOpts : {};
  writeChatInboxStore(inbox, {
    fast: true,
    dirtyThreadKey: chatDirtyThreadPersistKey(maskId, threadId),
    deferPersist: Boolean(pOpts.deferPersist)
  });
}

/**
 * 落盘：非分表页内联时同步提交；`_uiLogPartial` 时先乐观写内存尾段，再异步合并全量前缀。
 */
function persistChatLogEntriesForMaskThread(maskId, threadId, th, inbox, entries, persistOpts) {
  const arr = Array.isArray(entries) ? entries.slice() : [];
  if (!th || !th._uiLogPartial) {
    commitChatLogEntriesForMaskThread(maskId, threadId, th, inbox, arr, persistOpts);
    return;
  }
  applyChatLogTailEntriesOptimistic(th, arr);
  invalidateChatLogViewCache();
  invalidateChatUiEntriesRenderCache();
  void (async () => {
    const merged = await ensureChatLogEntriesBeforePersist(maskId, threadId, th, arr);
    commitChatLogEntriesForMaskThread(maskId, threadId, th, inbox, merged, persistOpts);
  })();
}

function saveChatLog(entries) {
  const D = window.XXJ_DB;
  if (!D) return;
  if (D.isReady && !D.isInboxHydrated) {
    void ensureChatInboxForUi().then(() => saveChatLog(entries));
    return;
  }
  reconcileActiveThreadRef();
  const maskId = getActiveMaskIdForInbox();
  const ref = readChatActiveThreadRef();
  const inbox = readChatInboxStore();
  ensureMaskBucket(inbox, maskId);
  const bucket = inbox.byMask[maskBucketKey(maskId)];
  const th = bucket.threads.find((t) => t.id === ref.threadId);
  if (!th) return;
  const applySave = () => {
    persistChatLogEntriesForMaskThread(maskId, ref.threadId, th, inbox, entries, {});
  };
  if (threadMessagesNeedHydrate(th)) {
    void ensureThreadMessagesHydrated(maskId, ref.threadId, th, { uiOnly: true }).then((ready) => {
      if (!ready) return;
      applySave();
    });
    return;
  }
  applySave();
}

/**
 * @param {string} maskId
 * @param {string} threadId
 * @returns {{ inbox: object, thread: object } | null}
 */
function findChatThreadInInbox(maskId, threadId) {
  const D = window.XXJ_DB;
  if (!D) return null;
  if (D.isReady && !D.isInboxHydrated) return null;
  const mid = String(maskId || "").trim();
  const tid = String(threadId || "").trim();
  if (!mid || !tid) return null;
  const inbox = readChatInboxStore();
  ensureMaskBucket(inbox, mid);
  const bucket = inbox.byMask[maskBucketKey(mid)];
  const th = bucket.threads.find((t) => t.id === tid);
  if (!th) return null;
  return { inbox, thread: th };
}

function readChatLogForMaskThread(maskId, threadId) {
  const found = findChatThreadInInbox(maskId, threadId);
  if (!found) return [];
  const th = found.thread;
  if (threadMessagesNeedHydrate(th)) {
    void ensureThreadMessagesHydrated(maskId, threadId, th, { uiOnly: true }).then(() => {
      invalidateChatLogViewCache();
    });
    return [];
  }
  if (!Array.isArray(th.messages)) return [];
  try {
    const copy = th.messages.slice();
    if (ensureRedpackNoticesInLog(copy)) {
      th.messages = copy.slice();
      th.updatedAt = Date.now();
      invalidateChatLogViewCache();
      writeChatInboxStore(found.inbox, {
        fast: true,
        dirtyThreadKey: chatDirtyThreadPersistKey(maskId, threadId)
      });
    }
  } catch (_) {
    /* ignore */
  }
  return th.messages.filter(
    (m) =>
      m &&
      typeof m === "object" &&
      (m.role === "user" || m.role === "assistant" || isChatSystemNotice(m))
  );
}

function saveChatLogForMaskThread(maskId, threadId, entries, persistOpts) {
  const D = window.XXJ_DB;
  if (!D) return;
  if (D.isReady && !D.isInboxHydrated) {
    void ensureChatInboxForUi().then(() => saveChatLogForMaskThread(maskId, threadId, entries, persistOpts));
    return;
  }
  const found = findChatThreadInInbox(maskId, threadId);
  if (!found) return;
  const pOpts = persistOpts && typeof persistOpts === "object" ? persistOpts : {};
  const applySave = () => {
    persistChatLogEntriesForMaskThread(maskId, threadId, found.thread, found.inbox, entries, pOpts);
  };
  if (threadMessagesNeedHydrate(found.thread)) {
    void ensureThreadMessagesHydrated(maskId, threadId, found.thread, { uiOnly: true }).then((ready) => {
      if (!ready) return;
      applySave();
    });
    return;
  }
  applySave();
}

/**
 * 向指定密谈追加一条消息（保留线程内完整 messages，避免 readChatLog 过滤视图覆盖落盘）。
 * @param {string} maskId
 * @param {string} threadId
 * @param {object} entry
 * @returns {boolean}
 */
function appendChatLogEntryForMaskThread(maskId, threadId, entry) {
  const D = window.XXJ_DB;
  if (!D || !entry || typeof entry !== "object") return false;
  if (D.isReady && !D.isInboxHydrated) {
    void ensureChatInboxForUi().then(() => appendChatLogEntryForMaskThread(maskId, threadId, entry));
    return false;
  }
  const found = findChatThreadInInbox(maskId, threadId);
  if (!found) return false;
  const applyAppend = () => {
    if (!Array.isArray(found.thread.messages)) found.thread.messages = [];
    found.thread.messages.push(entry);
    persistChatLogEntriesForMaskThread(
      maskId,
      threadId,
      found.thread,
      found.inbox,
      found.thread.messages,
      {}
    );
  };
  if (threadMessagesNeedHydrate(found.thread)) {
    void ensureThreadMessagesHydrated(maskId, threadId, found.thread, { uiOnly: true }).then((ready) => {
      if (!ready) return;
      applyAppend();
    });
    return true;
  }
  applyAppend();
  return true;
}

window.appendChatLogEntryForMaskThread = appendChatLogEntryForMaskThread;
window.fillRichProseEl = fillRichProseEl;
window.htmlToPlainTextForPrompt = htmlToPlainTextForPrompt;
window.refreshChatMessages = () => { try { renderChatMessages(); } catch (e) { console.warn("refreshChatMessages failed:", e); } };

const CHAT_THREAD_RECORD_EXPORT_FORMAT = "xxj-chat-thread-export";
const CHAT_THREAD_RECORD_EXPORT_VERSION = 1;

/** 密谈详情「导出记录」：下载当前密谈 JSON（含会话字段副本与 readChatLog 消息列表）。 */
function exportActiveChatThreadRecordJson() {
  const th = readActiveThread();
  if (!th) {
    showToast("没有当前密谈");
    return;
  }
  const tid = String(th.id || "").trim();
  if (!tid) {
    showToast("无法导出");
    return;
  }
  const maskId = String(getActiveMaskIdForInbox() || "").trim();
  const messages = readChatLog();
  /** @type {Record<string, unknown>} */
  const threadCopy = JSON.parse(JSON.stringify(th));
  delete threadCopy.messages;
  const displayTitle =
    String(th.charThreadRemarkName || "").trim() ||
    String(getChatCharPersonaDisplayName() || "").trim() ||
    tid;
  const payload = {
    format: CHAT_THREAD_RECORD_EXPORT_FORMAT,
    version: CHAT_THREAD_RECORD_EXPORT_VERSION,
    exportedAt: new Date().toISOString(),
    maskId,
    threadId: tid,
    displayTitle,
    thread: threadCopy,
    messages
  };
  const safe =
    String(displayTitle)
      .replace(/[<>:"/\\|?*\u0000-\u001f]/g, "_")
      .replace(/\s+/g, "_")
      .slice(0, 72) || "chat";
  const ts = new Date().toISOString().replace(/[:.]/g, "-").slice(0, 19);
  downloadJson(`mxj-chat-${safe}-${ts}.json`, payload);
  showToast(messages.length ? `已导出 ${messages.length} 条记录` : "已导出（暂无消息）");
}

/**
 * @param {unknown} raw
 * @returns {{ ok: true, data: Record<string, unknown> } | { ok: false, err: string }}
 */
function parseChatThreadRecordExportPayload(raw) {
  if (!raw || typeof raw !== "object") return { ok: false, err: "文件内容不是 JSON 对象" };
  const o = /** @type {Record<string, unknown>} */ (raw);
  if (String(o.format || "") !== CHAT_THREAD_RECORD_EXPORT_FORMAT) {
    return { ok: false, err: "不是本应用「导出记录」生成的密谈 JSON" };
  }
  if (Number(o.version) !== CHAT_THREAD_RECORD_EXPORT_VERSION) {
    return { ok: false, err: "导出版本与当前应用不一致" };
  }
  if (!Array.isArray(o.messages)) return { ok: false, err: "无效的 messages 字段" };
  return { ok: true, data: o };
}

/** 将导出文件中的 thread 快照合并到当前活动密谈（保留本会话 id 与 charId）。 */
function applyImportedChatThreadSnapshotToActive(imported) {
  if (!imported || typeof imported !== "object") return;
  patchActiveThread((t) => {
    const keepId = t.id;
    const keepChar = t.charId;
    for (const key of Object.keys(imported)) {
      if (key === "id" || key === "charId" || key === "messages") continue;
      const v = /** @type {Record<string, unknown>} */ (imported)[key];
      if (v !== undefined && v !== null && typeof v === "object") {
        try {
          t[key] = JSON.parse(JSON.stringify(v));
        } catch {
          t[key] = v;
        }
      } else {
        t[key] = v;
      }
    }
    t.id = keepId;
    t.charId = keepChar;
  });
}

function importActiveChatThreadRecordFromFileText(text) {
  let parsed;
  try {
    parsed = JSON.parse(text);
  } catch {
    showToast("无法解析 JSON");
    return;
  }
  const vr = parseChatThreadRecordExportPayload(parsed);
  if (!vr.ok) {
    showToast(vr.err);
    return;
  }
  if (!readActiveThread()) {
    showToast("没有当前密谈");
    return;
  }
  const data = vr.data;
  const title = String(data.displayTitle || data.threadId || "").trim();
  const nMsg = data.messages.length;
  const tip = title ? `「${title}」` : "该备份";
  if (
    !confirm(
      `将用 ${tip} 中的卷宗与消息覆盖当前密谈（保留本会话 ID 与绑定角色；共 ${nMsg} 条消息）。是否继续？`
    )
  ) {
    return;
  }
  if (data.thread && typeof data.thread === "object") {
    applyImportedChatThreadSnapshotToActive(data.thread);
  }
  saveChatLog(data.messages);
  chatInnerVoiceBrowseAssistantLogIdx = -1;
  clearChatComposerResendPlacement();
  clearChatMsgMultiSelectMode({ skipRender: true });
  refreshChatAfterLogMutation();
  applyChatThreadSurfaceBackgrounds();
  syncChatThreadDetailPanelPlaceholders();
  showToast("导入完成");
}

/**
 * 首段为完整一对全角「」（可嵌套），返回去掉最外层括号后的内文；否则 null。
 * 要求：括号深度仅在**最后一个字符**处回到 0（避免「a」b 误判为整块引用）。
 */
function stripOutermostJapaneseQuoteBlockInner(blockText) {
  const s = String(blockText ?? "").trim();
  if (s.length < 2 || !s.startsWith("「") || !s.endsWith("」")) return null;
  let d = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === "「") d++;
    else if (s[i] === "」") {
      d--;
      if (d < 0) return null;
      if (d === 0 && i !== s.length - 1) return null;
    }
  }
  if (d !== 0) return null;
  const inner = s.slice(1, -1);
  return inner.trim() ? inner : null;
}

/**
 * 首段内第一次 \n\n：前半须为成对「…」（可嵌套），后半为正文。
 */
function splitBubbleComposerQuoteFromDoubleNewline(raw0) {
  const s = String(raw0 ?? "");
  const idx = s.indexOf("\n\n");
  if (idx <= 0) return { quote: "", rest: s };
  const head = s.slice(0, idx).trim();
  const after = s.slice(idx + 2).trim();
  const inner = stripOutermostJapaneseQuoteBlockInner(head);
  if (inner == null) return { quote: "", rest: s };
  return { quote: inner, rest: after };
}

/**
 * 同一串里：从开头嵌套「」扫描，取**最后一次**深度归零的 `」` 作为「引用块」结束，其后非空为正文（无 \n\n 也可）。
 * 例：`「「蠱」...か。」 极简` → 引用整块 + 极简。
 */
function splitBubbleComposerQuoteInlineAfterOuterClose(raw0) {
  const s = String(raw0 ?? "").trim();
  if (!s.startsWith("「")) return { quote: "", rest: "" };
  let d = 0;
  const zeroAt = [];
  for (let i = 0; i < s.length; i++) {
    if (s[i] === "「") d++;
    else if (s[i] === "」") {
      d--;
      if (d < 0) return { quote: "", rest: "" };
      if (d === 0) zeroAt.push(i);
    }
  }
  if (d !== 0 || !zeroAt.length) return { quote: "", rest: "" };
  const closeIdx = zeroAt[zeroAt.length - 1];
  if (closeIdx >= s.length - 1) return { quote: "", rest: "" };
  const head = s.slice(0, closeIdx + 1).trim();
  const after = s.slice(closeIdx + 1).trim();
  if (!after) return { quote: "", rest: "" };
  const inner = stripOutermostJapaneseQuoteBlockInner(head);
  if (inner == null) return { quote: "", rest: "" };
  return { quote: inner, rest: after };
}

/**
 * 与会话气泡一致：`「引用」\n\n正文`（首段内；全文仍可与后续段用 ||| 拼接）。
 * @returns {{ quote: string, rest: string }}
 */
function splitBubbleComposerQuote(raw0) {
  const s = String(raw0 ?? "");
  if (!s.startsWith("「")) return { quote: "", rest: s };
  const end = s.indexOf("」", 1);
  if (end < 1) return { quote: "", rest: s };
  const inner = s.slice(1, end).trim();
  let after = s.slice(end + 1);
  if (after.startsWith("\r\n\r\n")) after = after.slice(4);
  else if (after.startsWith("\n\n")) after = after.slice(2);
  else if (after.startsWith("\r\n")) after = after.slice(2);
  else return { quote: "", rest: s };
  if (!inner) return { quote: "", rest: s };
  return { quote: inner, rest: after };
}

/** 与用户长按引用 snap 一致（stripJapaneseQuoteWrapper + trim）。 */
function normalizeQuoteMatchText(s) {
  const plain = String(s ?? "");
  const snap = stripJapaneseQuoteWrapper(plain).trim();
  return snap || plain.trim();
}

/** 模型常输出弯引号 / 『』，归一成解析用的「」以免引用条拆不出来。 */
function normalizeComposerQuoteBracketChars(s) {
  return String(s ?? "")
    .replace(/[\u201c\u2018]/g, "\u300c")
    .replace(/[\u201d\u2019]/g, "\u300d")
    .replace(/\u300e/g, "\u300c")
    .replace(/\u300f/g, "\u300d");
}

/**
 * @param {unknown} msg
 * @param {unknown[]} logArr
 * @returns {number}
 */
function resolveLogEndIdxBeforeMessage(msg, logArr) {
  const end = Array.isArray(logArr) ? logArr.length : 0;
  if (!msg || typeof msg !== "object") return end;
  const msgAt = Number(/** @type {{ at?: unknown }} */ (msg).at);
  if (Number.isFinite(msgAt)) {
    const hit = logArr.findIndex(
      (m) => m === msg || (m && typeof m === "object" && Number(/** @type {{ at?: unknown }} */ (m).at) === msgAt)
    );
    if (hit >= 0) return hit;
  }
  const hit = logArr.indexOf(msg);
  return hit >= 0 ? hit : end;
}

/**
 * 逐条 log 消息的**单个气泡分段**扫描（与用户长按引用 refSeg 同源），供 char 引用解析。
 * @param {unknown[]} log
 * @param {number} endIdx
 * @param {(seg: { refAt: number, refSeg: number, role: string, text: string }) => void | false} fn 返回 false 停止
 */
function forEachChatLogQuoteMatchSegment(log, endIdx, fn) {
  const logArr = Array.isArray(log) ? log : [];
  const end = Math.min(Math.max(0, Math.floor(Number(endIdx) || 0)), logArr.length);
  for (let i = end - 1; i >= 0 && i >= end - 40; i--) {
    const row = logArr[i];
    if (!row || typeof row !== "object") continue;
    const r = String(/** @type {{ role?: string }} */ (row).role || "");
    if (r !== "user" && r !== "assistant") continue;
    const at = Number(/** @type {{ at?: unknown }} */ (row).at);
    if (!Number.isFinite(at)) continue;
    const pair = chatMessageQuoteDomSegPair(row);
    const n = countChatBubbleActionSheetSegments(String(/** @type {{ content?: unknown }} */ (row).content ?? ""), r, row);
    for (let domSeg = 0; domSeg < n; domSeg++) {
      const kind = resolveChatBubbleSheetSegmentKind(row, domSeg, r);
      if (kind === "quote") continue;
      let text = "";
      if (kind === "photo") {
        text = normalizeQuoteMatchText(getChatMessageImageDescForActionSheet(row) || "图片");
      } else {
        text = normalizeQuoteMatchText(
          getChatMessageSegmentPlain(
            String(/** @type {{ content?: unknown }} */ (row).content ?? ""),
            domSeg,
            r,
            row,
            logArr,
            pair.quoteDom,
            pair.bodyDom
          )
        );
      }
      if (!text) continue;
      if (fn({ refAt: at, refSeg: domSeg, role: r, text }) === false) return;
    }
  }
}

/**
 * 将 char 摘录与 log 里**某一个气泡分段**对齐（与用户 msg.quote.refSeg 一致），不用整行拼接 plain。
 * @param {string} quoteText
 * @param {unknown[]} log
 * @param {number} endIdx
 * @returns {{ refAt: number, refSeg: number, role: string, text: string } | null}
 */
function findChatQuoteSegmentRefForText(quoteText, log, endIdx) {
  const q = normalizeQuoteMatchText(quoteText);
  if (!q) return null;
  let exact = null;
  /** @type {{ refAt: number, refSeg: number, role: string, text: string, score: number } | null} */
  let best = null;
  forEachChatLogQuoteMatchSegment(log, endIdx, (seg) => {
    const t = normalizeQuoteMatchText(seg.text);
    if (!t) return;
    if (t === q) {
      exact = { refAt: seg.refAt, refSeg: seg.refSeg, role: seg.role, text: t };
      return false;
    }
    let score = 0;
    // 模型常把连发多条拼成一段引用：优先「句末对齐的最近一条气泡」，其次段首/包含
    if (q.endsWith(t)) score = 300 + t.length;
    else if (q.startsWith(t)) score = 200 + t.length;
    else if (q.includes(t)) score = 100 + t.length;
    else if (t.includes(q) && q.length >= 2) score = 50 + q.length;
    if (
      score > 0 &&
      (!best || score > best.score || (score === best.score && t.length > best.text.length))
    ) {
      best = { refAt: seg.refAt, refSeg: seg.refSeg, role: seg.role, text: t, score };
    }
  });
  if (exact) return exact;
  if (best) {
    const { score: _score, ...hit } = best;
    return hit;
  }
  return null;
}

/**
 * 段末成对「」：正文在前、引用块紧挨结尾（模型常把摘录写在句末）。
 * 例：`啊？格式不对吗？「你不会分段了嘛」` → 引用条 + 上文正文。
 * @returns {{ quote: string, rest: string }}
 */
function splitBubbleComposerQuoteTrailingWrapped(raw0) {
  const s = String(raw0 ?? "").trim();
  if (s.length < 4 || !s.endsWith("」")) return { quote: "", rest: s };
  let d = 0;
  let openIdx = -1;
  for (let i = s.length - 1; i >= 0; i--) {
    if (s[i] === "」") d++;
    else if (s[i] === "「") {
      d--;
      if (d < 0) return { quote: "", rest: s };
      if (d === 0) {
        openIdx = i;
        break;
      }
    }
  }
  if (openIdx < 0) return { quote: "", rest: s };
  const head = s.slice(0, openIdx).trim();
  const quoteBlock = s.slice(openIdx).trim();
  const inner = stripOutermostJapaneseQuoteBlockInner(quoteBlock);
  if (inner == null || !head) return { quote: "", rest: s };
  return { quote: inner, rest: head };
}

/**
 * 助手首段若以近期气泡原文开头（模型未写「」/换行时），拆成引用+正文。
 * @param {unknown} msg
 * @param {unknown[]} log
 * @param {string} content0
 * @returns {{ quote: string, rest: string } | null}
 */
function trySplitAssistantQuoteByLogPrefix(msg, log, content0) {
  if (!msg || typeof msg !== "object" || String(/** @type {{ role?: string }} */ (msg).role) !== "assistant") {
    return null;
  }
  if (readMessageQuoteRef(msg)) return null;
  const content = String(content0 ?? "").trim();
  if (!content || content.length < 4) return null;
  const logArr = Array.isArray(log) ? log : [];
  const endIdx = resolveLogEndIdxBeforeMessage(msg, logArr);
  let result = null;
  forEachChatLogQuoteMatchSegment(logArr, endIdx, (seg) => {
    if (seg.text.length < 2 || seg.text.length >= content.length) return;
    const wrapped = `「${seg.text}」`;
    if (content.startsWith(wrapped)) {
      let rest = content.slice(wrapped.length);
      if (rest.startsWith("\n\n")) rest = rest.slice(2);
      else rest = rest.replace(/^[\s\u3000]+/, "");
      rest = rest.trim();
      if (rest) {
        result = { quote: seg.text, rest };
        return false;
      }
      return;
    }
    if (content.startsWith(seg.text)) {
      const afterCand = content.slice(seg.text.length);
      if (!/^[\s\u3000]/.test(afterCand)) return;
      const rest = afterCand.replace(/^[\s\u3000]+/, "").trim();
      if (rest) {
        result = { quote: seg.text, rest };
        return false;
      }
    }
  });
  return result;
}

/**
 * 助手首段若以 `「摘录」` 或近期气泡原文结尾，拆成引用条 + 前文正文。
 * @param {unknown} msg
 * @param {unknown[]} log
 * @param {string} content0
 * @returns {{ quote: string, rest: string } | null}
 */
function trySplitAssistantQuoteByLogSuffix(msg, log, content0) {
  if (!msg || typeof msg !== "object" || String(/** @type {{ role?: string }} */ (msg).role) !== "assistant") {
    return null;
  }
  if (readMessageQuoteRef(msg)) return null;
  const content = String(content0 ?? "").trim();
  if (!content || content.length < 4) return null;
  const logArr = Array.isArray(log) ? log : [];
  const endIdx = resolveLogEndIdxBeforeMessage(msg, logArr);
  let result = null;
  forEachChatLogQuoteMatchSegment(logArr, endIdx, (seg) => {
    if (seg.text.length < 2 || seg.text.length >= content.length) return;
    const wrapped = `「${seg.text}」`;
    if (content.endsWith(wrapped)) {
      const rest = content.slice(0, content.length - wrapped.length).trim();
      if (rest) {
        result = { quote: seg.text, rest };
        return false;
      }
      return;
    }
    if (content.endsWith(seg.text)) {
      const before = content.slice(0, content.length - seg.text.length);
      if (!before.trim() || !/[？?。！!…，,、：:\s]$/.test(before)) return;
      const rest = before.trim();
      if (rest) {
        result = { quote: seg.text, rest };
        return false;
      }
    }
  });
  return result;
}

/**
 * 从首段拆引用+正文（与用户引用条同源：`「」\\n\\n`、双换行、同行「」、助手前缀匹配）。
 * @param {string} chunk0
 * @param {string} role
 * @param {unknown} [msg]
 * @param {unknown[]} [log]
 * @returns {{ quote: string, rest: string }}
 */
function extractComposerQuoteFromFirstChunk(chunk0, role, msg, log) {
  const s = normalizeComposerQuoteBracketChars(String(chunk0 ?? ""));
  const sp = splitBubbleComposerQuote(s);
  if (sp.quote) return sp;
  const spNl = splitBubbleComposerQuoteFromDoubleNewline(s);
  if (spNl.quote) return spNl;
  const spIn = splitBubbleComposerQuoteInlineAfterOuterClose(s);
  if (spIn.quote) return spIn;
  const idx = s.indexOf("\n\n");
  if (idx > 0) {
    const head = stripJapaneseQuoteWrapper(s.slice(0, idx).trim());
    const after = s.slice(idx + 2).trim();
    if (head && after) return { quote: head, rest: after };
  }
  const spTrail = splitBubbleComposerQuoteTrailingWrapped(s);
  if (spTrail.quote) return spTrail;
  if (String(role || "") === "assistant" && msg && Array.isArray(log)) {
    const hit = trySplitAssistantQuoteByLogPrefix(msg, log, s);
    if (hit) return hit;
    const hitSuffix = trySplitAssistantQuoteByLogSuffix(msg, log, s);
    if (hitSuffix) return hitSuffix;
  }
  return { quote: "", rest: s };
}

/**
 * 与聊天气泡一致：首段为 `「引用」\n\n正文`，或首段仅 `「引用」` 且下一段起为正文（模型拆成多条 lines 时）。
 * @param {string[]} chunkArr
 * @param {string} role
 * @param {unknown} [msg]
 * @param {unknown[]} [log]
 * @returns {{ quoteRef: string, parts: string[] }}
 */
function resolveComposerQuotedDisplayParts(chunkArr, role, msg, log) {
  const r = String(role || "");
  const can = r === "user" || r === "assistant" || r === "system";
  if (!can || !chunkArr.length) return { quoteRef: "", parts: chunkArr };

  const sp = extractComposerQuoteFromFirstChunk(chunkArr[0], r, msg, log);
  if (sp.quote) {
    const quoteRef = String(sp.quote);
    const tail = dropComposerQuoteDuplicateBodyParts(quoteRef, [
      sp.rest,
      ...chunkArr.slice(1)
    ]);
    return { quoteRef, parts: tail.length ? tail : [" "] };
  }

  const first = normalizeComposerQuoteBracketChars(String(chunkArr[0] ?? "")).trim();
  if (chunkArr.length >= 2) {
    const innerMulti = stripOutermostJapaneseQuoteBlockInner(first);
    if (innerMulti != null) {
      const tail = dropComposerQuoteDuplicateBodyParts(
        innerMulti,
        chunkArr.slice(1).map((s) => String(s).trim()).filter((s) => s.length > 0)
      );
      return { quoteRef: innerMulti, parts: tail.length ? tail : [" "] };
    }
  }

  return { quoteRef: "", parts: chunkArr };
}

/**
 * 当面晤面：不把 `「…」\\n\\n正文` 当作即时消息的「引用条」拆 DOM（避免灰斜体顶栏）。
 * 结构化引用（msg.quote）仍保留。
 */
function resolveComposerQuotedDisplayPartsForSurface(chunkArr, role, msg, log) {
  if (msg && typeof msg === "object" && chatMessageDmSurface(msg) === "offline") {
    const parts = chunkArr.length ? chunkArr.map((s) => String(s ?? "")) : [" "];
    return { quoteRef: "", parts };
  }
  return resolveComposerQuotedDisplayParts(chunkArr, role, msg, log);
}

/**
 * 引用气泡布局下正文段数（与渲染、长按分段一致）。
 * @param {unknown} msg
 * @param {string} role
 * @param {unknown[]} [log]
 */
function resolveQuotedMessageBodyPartCount(msg, role, log) {
  if (!msg || typeof msg !== "object") return 0;
  const r = String(role || "");
  if (readMessageQuoteRef(msg)) {
    const parts = structuredQuoteBodyPartsFromContent(msg, log);
    return Math.max(1, parts.length);
  }
  const raw = String(/** @type {{ content?: unknown }} */ (msg).content ?? "");
  const chunks = raw
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean);
  const chunkArr = chunks.length ? chunks : [raw.trim() || " "];
  const { quoteRef, parts } = resolveComposerQuotedDisplayPartsForSurface(chunkArr, r, msg, log);
  if (!quoteRef) return 0;
  return Math.max(1, parts.length);
}

/** @param {unknown} msg @param {string} role @param {unknown[]} [log] */
function chatMessageHasQuoteBubbleLayout(msg, role, log) {
  if (!msg || typeof msg !== "object") return false;
  if (readMessageQuoteRef(msg)) return true;
  const raw = String(/** @type {{ content?: unknown }} */ (msg).content ?? "");
  const chunks = raw
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean);
  const chunkArr = chunks.length ? chunks : [raw.trim() || " "];
  const { quoteRef } = resolveComposerQuotedDisplayPartsForSurface(chunkArr, String(role || ""), msg, log);
  return Boolean(quoteRef);
}

/**
 * 删除引用消息中第 N 段正文（不含引用条、首段正文）。
 * @returns {{ newContent: string, parallelSi: number } | null}
 */
function spliceQuotedMessageBodySegment(msg, role, sheetSegIdx, log) {
  const si = Math.max(0, Math.floor(Number(sheetSegIdx)) || 0);
  const pair = chatMessageQuoteDomSegPair(msg);
  const contentSi = si - pair.bodyDom;
  if (contentSi < 0) return null;
  const r = String(role || "");
  const logArr = Array.isArray(log) ? log : null;
  if (readMessageQuoteRef(msg)) {
    const np = structuredQuoteBodyPartsFromContent(msg, logArr || []).slice();
    if (contentSi >= np.length) return null;
    np.splice(contentSi, 1);
    return {
      newContent: np.filter((s) => s.length > 0).join("|||") || " ",
      parallelSi: Math.max(0, si - 1)
    };
  }
  const rawFull = String(/** @type {{ content?: unknown }} */ (msg).content ?? "");
  const chunks = rawFull
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean);
  const chunkArr = chunks.length ? chunks : [rawFull.trim() || " "];
  const { quoteRef, parts } = resolveComposerQuotedDisplayPartsForSurface(chunkArr, r, msg, logArr);
  if (!quoteRef || contentSi >= parts.length) return null;
  const np = parts.map((s) => String(s ?? "").trim());
  np.splice(contentSi, 1);
  return {
    newContent: encodeQuotedComposerStorageFromParts(quoteRef, np.filter((s) => s.length > 0)),
    parallelSi: Math.max(0, si - 1)
  };
}

/** @param {HTMLElement} wrap @returns {{ quote: number | null, body: number | null }} */
function resolveQuoteBubbleDomSegPairFromWrap(wrap) {
  if (!(wrap instanceof HTMLElement)) return { quote: null, body: null };
  const qt = wrap.querySelector(".chat-msg-bubble--composer-quote");
  if (!qt) return { quote: null, body: null };
  const qEl = qt.querySelector(".chat-msg-bubble-quote");
  const bodyEl = qt.querySelector(
    ".chat-msg-bubble-body:not(.chat-msg-bubble-body--translation)"
  );
  if (qEl?.dataset.chatBubbleSeg != null && bodyEl?.dataset.chatBubbleSeg != null) {
    return {
      quote: Number(qEl.dataset.chatBubbleSeg),
      body: Number(bodyEl.dataset.chatBubbleSeg)
    };
  }
  return { quote: null, body: null };
}

/** 将引用条/正文条的 data-chat-bubble-seg 写入长按菜单，供编辑/复制分段对齐。 */
function syncQuoteBubbleSegIndicesToSheet(sheetEl, wrap) {
  if (!(sheetEl instanceof HTMLElement) || !(wrap instanceof HTMLElement)) return;
  const { quote, body } = resolveQuoteBubbleDomSegPairFromWrap(wrap);
  if (quote != null && body != null) {
    sheetEl.dataset.quoteBubbleSeg = String(quote);
    sheetEl.dataset.bodyBubbleSeg = String(body);
  } else {
    delete sheetEl.dataset.quoteBubbleSeg;
    delete sheetEl.dataset.bodyBubbleSeg;
  }
}

/**
 * @param {unknown} msg
 * @returns {{ refAt: number, refSeg: number, text: string, role: string } | null}
 */
function readMessageQuoteRef(msg) {
  if (!msg || typeof msg !== "object") return null;
  const q = /** @type {Record<string, unknown>} */ (msg).quote;
  if (!q || typeof q !== "object") return null;
  const o = /** @type {Record<string, unknown>} */ (q);
  const text = String(o.text ?? "").trim();
  const refAt = Number(o.refAt);
  const hasAt = Number.isFinite(refAt);
  if (!hasAt && !text) return null;
  return {
    refAt: hasAt ? refAt : NaN,
    refSeg: Math.max(0, Math.floor(Number(o.refSeg)) || 0),
    text,
    role: String(o.role ?? "").trim(),
    refSpeakerCharId: String(o.refSpeakerCharId ?? "").trim()
  };
}

/** @param {unknown} refMsg @param {unknown} thread @param {object} [mask] */
function resolveQuoteSpeakerCharIdFromRefMessage(refMsg, thread) {
  if (!refMsg || typeof refMsg !== "object" || String(refMsg.role) !== "assistant") return "";
  let cid = String(refMsg.speakerCharId || "").trim();
  if (!cid && thread && typeof thread === "object" && thread.kind === "group") {
    cid = String(window.XXJ_GroupChat?.speakerCharIdFromMessage?.(refMsg, thread) || "").trim();
  }
  if (!cid && thread && typeof thread === "object" && thread.kind !== "group") {
    cid = String(thread.charId || "").trim();
  }
  return cid;
}

/** 群聊引用条：成员显示名（群昵称优先）。 */
function groupQuoteSpeakerDisplayName(th, charId) {
  const cid = String(charId || "").trim();
  if (!cid) return "成员";
  const callFn = window.XXJ_GroupChat?.groupCallNameForRef;
  const nmFn = window.XXJ_GroupChat?.charDisplayName;
  return (
    (typeof callFn === "function" ? callFn(th, cid) : "") ||
    (typeof nmFn === "function" ? nmFn(cid) : "") ||
    "成员"
  );
}

/**
 * 引用条发言人名：仅群聊返回（UI 与群 API）；单聊返回空，展示保持「仅摘录」。
 * @param {{ refAt?: number, refSeg?: number, text?: string, role?: string, refSpeakerCharId?: string } | null} sq
 * @param {unknown[]} log
 * @param {unknown} [thread]
 * @param {object} [mask]
 */
function resolveQuoteSourceSpeakerLabel(sq, log, thread, mask) {
  if (!sq) return "";
  const logArr = Array.isArray(log) ? log : [];
  const th = thread && typeof thread === "object" ? thread : readActiveThread();
  if (!isChatThreadGroupForUi(th)) return "";
  const userCall = (mask?.displayName && String(mask.displayName).trim()) || "主控";

  let refMsg = null;
  if (Number.isFinite(sq.refAt)) {
    refMsg = logArr.find((m) => m && typeof m === "object" && Number(m.at) === sq.refAt) || null;
  }
  if (refMsg) {
    const r = String(refMsg.role || "");
    if (r === "user") return userCall;
    if (r === "assistant") {
      return groupQuoteSpeakerDisplayName(th, resolveQuoteSpeakerCharIdFromRefMessage(refMsg, th));
    }
  }

  const refCid = String(sq.refSpeakerCharId || "").trim();
  if (refCid) return groupQuoteSpeakerDisplayName(th, refCid);
  if (String(sq.role || "") === "user") return userCall;
  if (String(sq.role || "") === "assistant") return "成员";
  return "";
}

/** @param {HTMLElement} qEl @param {string} who @param {string} text */
function fillComposerQuoteBubbleEl(qEl, who, text) {
  qEl.replaceChildren();
  const body = String(text || "").trim();
  if (!body) return;
  const w = String(who || "").trim();
  if (w) {
    const whoEl = document.createElement("span");
    whoEl.className = "chat-msg-bubble-quote-who";
    whoEl.textContent = w;
    const sep = document.createElement("span");
    sep.className = "chat-msg-bubble-quote-sep";
    sep.textContent = "：";
    const tx = document.createElement("span");
    tx.className = "chat-msg-bubble-quote-text";
    tx.textContent = body;
    qEl.append(whoEl, sep, tx);
  } else {
    const tx = document.createElement("span");
    tx.className = "chat-msg-bubble-quote-text";
    tx.textContent = body;
    qEl.appendChild(tx);
  }
}

/**
 * 群/API：引用块 + 正文（不含【发言人】前缀）。
 * @param {unknown} msg
 * @param {unknown[]} logSlice
 * @param {unknown} [thread]
 * @param {object} [mask]
 */
function formatMessageQuoteBodyForApi(msg, logSlice, thread, mask) {
  const sq = readMessageQuoteRef(msg);
  if (!sq) return "";
  const logArr = Array.isArray(logSlice) ? logSlice : [];
  const inner =
    resolveStructuredQuoteDisplayInner(msg, logArr).trim() || String(sq.text || "").trim();
  if (!inner) return "";
  const who = resolveQuoteSourceSpeakerLabel(sq, logArr, thread, mask);
  const qPart = who ? `（引用「${who}」：${inner}）` : `「${inner}」`;
  const body = structuredQuoteBodyPartsFromContent(msg, logArr)
    .map((s) => String(s || "").trim())
    .filter(Boolean)
    .join("\n")
    .trim();
  return body ? `${qPart}\n\n${body}` : qPart;
}

/** 线下晤面：把误写入的 msg.quote 并回正文，避免即时消息的引用条样式。 */
function demoteOfflineStructuredQuoteToContent(msg) {
  if (!msg || typeof msg !== "object") return false;
  if (chatMessageDmSurface(msg) !== "offline") return false;
  const sq = readMessageQuoteRef(msg);
  if (!sq) return false;
  const quoteText = String(sq.text || "").trim();
  delete msg.quote;
  const chunks = String(msg.content ?? "")
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter((s) => s.length > 0);
  const rest0 = chunks[0] || "";
  const mergedFirst =
    quoteText && rest0 ? `${quoteText}\n\n${rest0}` : quoteText || rest0 || "";
  const merged = mergedFirst ? [mergedFirst, ...chunks.slice(1)] : chunks.slice(1);
  msg.content = merged.filter((s) => String(s).trim()).join("|||") || " ";
  return true;
}

/** 助手引用 → 与用户相同的 msg.quote + 纯正文（仅即时消息；线下晤面不迁入引用结构）。 */
function promoteAssistantComposerQuoteToStructuredStorage(msg, log) {
  if (!msg || typeof msg !== "object" || String(msg.role) !== "assistant") return;
  if (chatMessageDmSurface(msg) === "offline") return;
  if (readMessageQuoteRef(msg)) return;
  const chunks = String(msg.content ?? "")
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean);
  if (!chunks.length) return;
  const sp = extractComposerQuoteFromFirstChunk(chunks[0], "assistant", msg, log);
  if (!sp.quote) return;
  const rest = [sp.rest, ...chunks.slice(1)].map((s) => String(s).trim()).filter((s) => s.length > 0);
  const logArr = Array.isArray(log) ? log : [];
  const endIdx = resolveLogEndIdxBeforeMessage(msg, logArr);
  const refHit = findChatQuoteSegmentRefForText(sp.quote, logArr, endIdx);
  let refSpeakerCharId = "";
  if (refHit && Number.isFinite(refHit.refAt)) {
    const refRow = logArr.find((row) => row && typeof row === "object" && Number(row.at) === refHit.refAt);
    refSpeakerCharId = resolveQuoteSpeakerCharIdFromRefMessage(refRow, readActiveThread());
  }
  msg.quote = {
    refAt: refHit && Number.isFinite(refHit.refAt) ? refHit.refAt : NaN,
    refSeg: refHit ? refHit.refSeg : 0,
    text: (refHit ? refHit.text : String(sp.quote)).slice(0, 4000),
    role: refHit && refHit.role ? refHit.role : "user",
    ...(refSpeakerCharId ? { refSpeakerCharId } : {})
  };
  msg.content = rest.length ? rest.join("|||") : " ";
}

/** 已有 msg.quote 时：把合并摘录对齐到 log 里单条气泡，并修正 text/refAt/refSeg。 */
function reconcileStructuredQuoteRefInMessage(msg, log) {
  if (!msg || typeof msg !== "object" || !readMessageQuoteRef(msg)) return false;
  const logArr = Array.isArray(log) ? log : [];
  const endIdx = resolveLogEndIdxBeforeMessage(msg, logArr);
  const qSnap = normalizeQuoteMatchText(readMessageQuoteRef(msg)?.text || "");
  if (!qSnap) return false;
  const refHit = findChatQuoteSegmentRefForText(qSnap, logArr, endIdx);
  if (!refHit) return false;
  /** @type {Record<string, unknown>} */
  const qo = msg.quote;
  let dirty = false;
  if (String(qo.text || "").trim() !== refHit.text) {
    qo.text = refHit.text;
    dirty = true;
  }
  if (Number(qo.refAt) !== refHit.refAt) {
    qo.refAt = refHit.refAt;
    dirty = true;
  }
  if (Math.floor(Number(qo.refSeg) || 0) !== refHit.refSeg) {
    qo.refSeg = refHit.refSeg;
    dirty = true;
  }
  if (refHit.role && String(qo.role || "") !== refHit.role) {
    qo.role = refHit.role;
    dirty = true;
  }
  const refRow = logArr.find((row) => row && typeof row === "object" && Number(row.at) === refHit.refAt);
  const refCid = resolveQuoteSpeakerCharIdFromRefMessage(refRow, readActiveThread());
  if (refCid && String(qo.refSpeakerCharId || "") !== refCid) {
    qo.refSpeakerCharId = refCid;
    dirty = true;
  }
  return dirty;
}

/** 渲染前：线下并回误迁入的引用；即时消息里把助手正文引用迁入 msg.quote。 */
function normalizeAssistantQuoteStorageInLog(log) {
  if (!Array.isArray(log)) return false;
  let dirty = false;
  for (const m of log) {
    if (!m || typeof m !== "object") continue;
    if (demoteOfflineStructuredQuoteToContent(m)) dirty = true;
  }
  for (const m of log) {
    if (!m || typeof m !== "object" || String(m.role) !== "assistant" || readMessageQuoteRef(m)) continue;
    promoteAssistantComposerQuoteToStructuredStorage(m, log);
    if (m.quote) dirty = true;
  }
  for (const m of log) {
    if (!m || typeof m !== "object") continue;
    if (normalizeStructuredQuoteContentInMessage(m, log)) dirty = true;
  }
  for (const m of log) {
    if (!m || typeof m !== "object") continue;
    if (reconcileStructuredQuoteRefInMessage(m, log)) dirty = true;
  }
  return dirty;
}

function stripJapaneseQuoteWrapper(s) {
  const t = String(s ?? "").trim();
  if (t.length >= 2 && t.startsWith("「") && t.endsWith("」")) return t.slice(1, -1);
  return t;
}

/**
 * 结构化引用条展示/喂 API 用的内文（优先按 refAt 从当前 log 取最新气泡字，否则用快照 text）。
 * @param {unknown} msg
 * @param {unknown[]} log
 */
function resolveStructuredQuoteDisplayInner(msg, log) {
  const sq = readMessageQuoteRef(msg);
  if (!sq) return "";
  const logArr = Array.isArray(log) ? log : [];
  if (logArr.length && Number.isFinite(sq.refAt)) {
    const hit = logArr.find((m) => m && typeof m === "object" && Number(/** @type {{ at?: unknown }} */ (m).at) === sq.refAt);
    if (hit) {
      const pair = chatMessageQuoteDomSegPair(hit);
      const inner = getChatMessageSegmentPlain(
        String(/** @type {{ content?: unknown }} */ (hit).content ?? ""),
        sq.refSeg,
        String(/** @type {{ role?: unknown }} */ (hit).role || ""),
        hit,
        logArr,
        pair.quoteDom,
        pair.bodyDom
      );
      const stripped = stripJapaneseQuoteWrapper(inner).trim();
      if (stripped) return stripped;
      if (String(inner).trim()) return String(inner).trim();
    }
  }
  return String(sq.text || "").trim();
}

/**
 * 已有 msg.quote 时，从 content 剥掉重复的 legacy「引用」前缀，只留回复正文段。
 * @param {unknown} msg
 * @param {unknown[]} log
 * @returns {string[]}
 */
function structuredQuoteBodyPartsFromContent(msg, log) {
  const role = String(/** @type {{ role?: unknown }} */ (msg || {}).role || "");
  let rawFull = String(/** @type {{ content?: unknown }} */ (msg || {}).content ?? "");
  rawFull = normalizeUserPhotoBubbleRawFull(msg, rawFull);
  const chunks = rawFull
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean);
  /** @type {string[]} */
  let parts = chunks.length ? chunks.slice() : rawFull.trim() ? [rawFull.trim()] : [];
  if (!parts.length) parts = [" "];

  const sq = readMessageQuoteRef(msg);
  if (!sq) return parts;

  const quoteRef = resolveStructuredQuoteDisplayInner(msg, log);
  const qNorm = normalizeQuoteMatchText(quoteRef);

  const sp = extractComposerQuoteFromFirstChunk(parts[0] || "", role, msg, log);
  if (sp.quote && (!qNorm || normalizeQuoteMatchText(sp.quote) === qNorm)) {
    parts = [sp.rest, ...parts.slice(1)]
      .map((s) => String(s).trim())
      .filter((s) => s.length > 0);
  } else if (parts.length && qNorm) {
    const p0 = String(parts[0] || "").trim();
    const p0Inner = stripJapaneseQuoteWrapper(p0).trim();
    if (normalizeQuoteMatchText(p0Inner) === qNorm || normalizeQuoteMatchText(p0) === qNorm) {
      parts = parts.slice(1);
    } else {
      const wrapped = `「${quoteRef}」`;
      if (p0.startsWith(wrapped)) {
        const rest = p0.slice(wrapped.length).replace(/^\s*\n+/, "").trim();
        parts = rest ? [rest, ...parts.slice(1)] : parts.slice(1);
      }
    }
  }
  parts = dropComposerQuoteDuplicateBodyParts(quoteRef, parts);
  if (!parts.length) parts = [" "];
  return parts;
}

/** 引用复述前的短语气词（噢、嗯等），非完整句子。 */
function isComposerQuoteReactionPrefix(prefix) {
  const s = String(prefix || "").trim();
  if (!s) return true;
  if (s.length > 12) return false;
  return /^[\s噢哦啊嗯唔哈嘿呵咦诶欸哇喔呀…\.！!？?~～_ㅎㅋhaha]+$/iu.test(s);
}

/** 单行是否仅为引用条内容的复述（含「噢噢 原文」式包裹，非真正回复）。 */
function isComposerQuoteEchoLine(quoteRef, line) {
  const q = String(quoteRef || "").trim();
  const qn = normalizeQuoteMatchText(q);
  if (!qn) return false;
  const p = String(line ?? "").trim();
  if (!p) return false;
  if (normalizeQuoteMatchText(p) === qn || p === `「${q}」`) return true;
  const inner = stripOutermostJapaneseQuoteBlockInner(p);
  if (inner == null) return false;
  const inNorm = normalizeQuoteMatchText(inner);
  if (inNorm === qn) return true;
  if (inNorm.endsWith(qn) || inner.endsWith(q)) {
    const suffixLen = inner.endsWith(q) ? q.length : qn.length;
    const prefix = inner.slice(0, Math.max(0, inner.length - suffixLen)).trim();
    if (isComposerQuoteReactionPrefix(prefix)) return true;
  }
  return false;
}

/** 剥掉段落顶部复述引用的行 / 包裹块，只留真正回复。 */
function stripComposerQuoteEchoFromPart(quoteRef, part) {
  const q = String(quoteRef || "").trim();
  if (!normalizeQuoteMatchText(q)) return String(part ?? "").trim();
  let p = String(part ?? "").trim();
  if (!p) return "";

  const lines = p.split(/\n/);
  while (lines.length) {
    const head = lines[0].trim();
    if (!head) {
      lines.shift();
      continue;
    }
    if (isComposerQuoteEchoLine(q, head)) {
      lines.shift();
      continue;
    }
    break;
  }
  p = lines.join("\n").trim();
  if (!p) return "";

  const trail = splitBubbleComposerQuoteTrailingWrapped(p);
  if (trail.quote && isComposerQuoteEchoLine(q, `「${trail.quote}」`)) {
    p = trail.rest.trim();
  }

  if (p.startsWith("「")) {
    const spIn = splitBubbleComposerQuoteInlineAfterOuterClose(p);
    if (spIn.quote && isComposerQuoteEchoLine(q, `「${spIn.quote}」`) && spIn.rest) {
      p = spIn.rest.trim();
    }
  }

  return p;
}

/** 引用条已有 quoteRef 时，剥掉正文段里重复的「摘录」或「「摘录」」行。 */
function dropComposerQuoteDuplicateBodyParts(quoteRef, parts) {
  const q = String(quoteRef || "").trim();
  const qn = normalizeQuoteMatchText(q);
  if (!qn) return Array.isArray(parts) ? parts.slice() : [];
  const out = [];
  for (const seg of Array.isArray(parts) ? parts : []) {
    let p = stripComposerQuoteEchoFromPart(q, seg);
    if (!p) continue;
    if (normalizeQuoteMatchText(p) === qn) continue;
    if (q && p.startsWith(`「${q}」`)) {
      const rest = p.slice(`「${q}」`.length).replace(/^\s*\n+/, "").trim();
      if (rest) out.push(rest);
      continue;
    }
    out.push(p);
  }
  return out;
}

/** 引用气泡内首段正文：跳过与 quoteRef 重复的段，避免「引用条 + 带括号重复摘录 + 回复」三行。 */
function pickComposerQuoteBodyHeadText(quoteRef, parts) {
  const cleaned = dropComposerQuoteDuplicateBodyParts(quoteRef, parts);
  for (const seg of cleaned) {
    const p = String(seg ?? "").trim();
    if (p) return p;
  }
  return " ";
}

/** 即时消息：msg.quote 与 content 里重复的「摘录」段落盘时剥掉，只留回复正文。 */
function normalizeStructuredQuoteContentInMessage(msg, log) {
  if (!msg || typeof msg !== "object") return false;
  const role = String(msg.role || "");
  if (role !== "user" && role !== "assistant") return false;
  if (chatMessageDmSurface(msg) === "offline") return false;
  if (!readMessageQuoteRef(msg)) return false;
  const clean = structuredQuoteBodyPartsFromContent(msg, log);
  const next = clean
    .map((s) => String(s).trim())
    .filter(Boolean)
    .join("|||") || " ";
  const cur = String(msg.content ?? "").trim();
  if (next === cur) return false;
  msg.content = next;
  return true;
}

/** user 消息是否带真实像素图（data URL / http） */
function userChatMessageHasPhotoPixels(msg) {
  return (
    msg &&
    typeof msg === "object" &&
    msg.role === "user" &&
    msg.image &&
    typeof msg.image === "object" &&
    String(msg.image.url || "").trim()
  );
}

/**
 * 去掉 content 里仅为协议用的「【图片】」前缀（真·上传图已有 image.url，不应再出一行字）。
 */
function normalizeUserPhotoBubbleRawFull(msg, rawFull0) {
  if (!userChatMessageHasPhotoPixels(msg)) return String(rawFull0 ?? "");
  const rawFull = String(rawFull0 ?? "");
  const segs = rawFull.split(/\|\|\|/).map((s) =>
    String(s || "")
      .trim()
      .replace(/^(?:【图片】|【发图】|【配图】|【照】|［图片］)\s*/u, "")
      .trim()
  );
  return segs.filter(Boolean).join("|||");
}

/**
 * @param {unknown} msg
 * @param {unknown[]} log
 * @returns {{ quoteRef: string, parts: string[] }}
 */
function resolveMessageQuotedParts(msg, log) {
  const role = String(/** @type {{ role?: unknown }} */ (msg || {}).role || "");
  let rawFull = String(/** @type {{ content?: unknown }} */ (msg || {}).content ?? "");
  rawFull = normalizeUserPhotoBubbleRawFull(msg, rawFull);
  const sq = chatMessageDmSurface(msg) === "offline" ? null : readMessageQuoteRef(msg);
  if (sq) {
    const quoteRef = resolveStructuredQuoteDisplayInner(msg, log);
    const parts = structuredQuoteBodyPartsFromContent(msg, log);
    return { quoteRef, parts };
  }
  const chunks = rawFull
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean);
  let chunkArr = chunks.length ? chunks : [];
  if (!chunkArr.length && rawFull.trim()) chunkArr = [rawFull.trim()];
  if (!chunkArr.length && userChatMessageHasPhotoPixels(msg)) {
    return { quoteRef: "", parts: [] };
  }
  const userDescCapQ = resolveUserChatPhotoDescCap(msg, rawFull);
  if (!chunkArr.length && userDescCapQ) {
    return { quoteRef: "", parts: [] };
  }
  const assistantPhotoDescOnly =
    msg &&
    typeof msg === "object" &&
    role === "assistant" &&
    msg.image &&
    typeof msg.image === "object" &&
    String(msg.image.desc || "").trim() &&
    !String(msg.image.url || "").trim();
  if (!chunkArr.length && assistantPhotoDescOnly) {
    return { quoteRef: "", parts: [] };
  }
  if (!chunkArr.length) chunkArr = [" "];
  const r = resolveComposerQuotedDisplayPartsForSurface(chunkArr, role, msg, log);
  if (assistantPhotoDescOnly) {
    const desc = String(msg.image.desc || "").trim();
    const filtered = r.parts.filter((seg) => !assistantBubblePartDupesDescImage(seg, desc));
    if (!filtered.some((seg) => String(seg || "").trim())) {
      return { quoteRef: r.quoteRef, parts: [] };
    }
    return { quoteRef: r.quoteRef, parts: filtered };
  }
  if (role === "user" && userDescCapQ) {
    const filtered = r.parts.filter((seg) => !assistantBubblePartDupesDescImage(seg, userDescCapQ));
    if (!filtered.some((seg) => String(seg || "").trim())) {
      return { quoteRef: r.quoteRef, parts: [] };
    }
    return { quoteRef: r.quoteRef, parts: filtered };
  }
  return { quoteRef: r.quoteRef, parts: r.parts };
}

/** 本条是否含可长按的图片卡（url 或 desc）。 */
function chatMessageHasBubbleImageCard(msg) {
  return Boolean(
    msg &&
      typeof msg === "object" &&
      msg.image &&
      typeof msg.image === "object" &&
      (String(msg.image.url || "").trim() || String(msg.image.desc || "").trim())
  );
}

/** 晤面配图卡在 DOM 上的 `data-chat-bubble-seg`（即时消息配图卡为 0）。 */
const OFFLINE_CHAT_PHOTO_DOM_SEG = 900;

/**
 * 长按菜单是否针对图片卡（即时 seg 0；晤面配图 seg {@link OFFLINE_CHAT_PHOTO_DOM_SEG}）。
 * @param {unknown} msg
 * @param {number} domSeg
 * @param {Element | null | undefined} [anchorEl]
 */
function isChatBubbleActionSheetImageDomSeg(msg, domSeg, anchorEl) {
  if (anchorEl instanceof Element && anchorEl.closest(".chat-msg-card--photo")) return true;
  if (!chatMessageHasBubbleImageCard(msg)) return false;
  const si = Math.max(0, Math.floor(Number(domSeg)) || 0);
  return si === 0 || si === OFFLINE_CHAT_PHOTO_DOM_SEG;
}

/** 入库的生图场面块（送 API 的 scene 段；与展示用 desc 可相同）。 */
function getChatImageGenSceneBlockFromMessage(msg) {
  const mo = msg && typeof msg === "object" ? msg : null;
  const im = mo?.image && typeof mo.image === "object" ? mo.image : null;
  if (!im) return "";
  const scene = String(im.scenePrompt ?? "").trim();
  if (scene) return scene.slice(0, 3500);
  /** 线下 desc 常为气泡正文摘要，禁止回退成整段 lines 送生图 API */
  if (mo && mo.role === "assistant" && chatMessageDmSurface(mo) === "offline") return "";
  return String(im.desc || "").trim().slice(0, 3500);
}

/** @param {unknown} msg */
function getChatMessageImageDescForActionSheet(msg) {
  const mo = msg && typeof msg === "object" ? msg : null;
  const im = mo?.image && typeof mo.image === "object" ? mo.image : null;
  let desc = String(im?.desc || "").trim();
  if (mo && String(mo.role || "") === "assistant" && desc) {
    desc = sanitizeCharImageCaptionMeta(desc) || desc;
  }
  if (!desc && mo && String(mo.role || "") === "user") {
    desc = userChatImageCaptionFromContent(String(mo.content ?? ""));
  }
  return desc;
}

/** 长按编辑图片：载入完整生图场面描述，不做展示侧 meta 剥离。 */
function getChatImageGenSceneBlockForEdit(msg) {
  const mo = msg && typeof msg === "object" ? msg : null;
  if (!mo) return "";
  if (String(mo.role || "") === "user") {
    const fromImg = getChatImageGenSceneBlockFromMessage(mo);
    if (fromImg) return fromImg;
    return userChatImageCaptionFromContent(String(mo.content ?? "")).slice(0, 3500);
  }
  const scene = getChatImageGenSceneBlockFromMessage(mo);
  if (scene) return scene;
  const im = mo.image && typeof mo.image === "object" ? mo.image : null;
  return im
    ? String(im.scenePrompt ?? im.desc ?? "")
        .trim()
        .slice(0, 3500)
    : "";
}

/** @param {unknown} msg @param {string} newDesc */
function applyChatImageDescPatch(msg, newDesc) {
  if (!msg || typeof msg !== "object") return;
  if (!msg.image || typeof msg.image !== "object") msg.image = {};
  const nt = String(newDesc ?? "").trim();
  if (String(msg.role || "") === "assistant") {
    const scene = nt.slice(0, 3500);
    msg.image.scenePrompt = scene;
    msg.image.desc = scene.slice(0, 4000);
  } else {
    const scene = nt.slice(0, 3500);
    msg.image.desc = nt.slice(0, 4000);
    if (isThreadDescImageApiGenEnabled(readActiveThread()) && isSessionImageGenConfigured()) {
      msg.image.scenePrompt = scene;
    } else {
    delete msg.image.scenePrompt;
    }
  }
}

/**
 * 与 render 一致：本条前有图片卡时，引用条/正文条的 data-chat-bubble-seg 从 1、2 起（图为 0）。
 * @param {unknown} msg
 * @returns {{ quoteDom: number, bodyDom: number }}
 */
function chatMessageQuoteDomSegPair(msg) {
  const role = msg && typeof msg === "object" ? String(msg.role || "") : "";
  return {
    quoteDom: resolveSheetDomSegForQuoteBar(msg, role) ?? 0,
    bodyDom: resolveSheetDomSegForQuoteBody(msg, role) ?? 1
  };
}

/**
 * 与渲染一致：含「引用」时引用条与正文条在 DOM 上有各自的 chatBubbleSeg（前有图片卡时常为 1、2 而非 0、1）。
 * @param {number | null | undefined} [quoteDomSeg]
 * @param {number | null | undefined} [bodyDomSeg]
 */
function getChatMessageSegmentPlain(content, segIdx, role, msg, log, quoteDomSeg, bodyDomSeg) {
  const r = String(role || "");
  const rawFull = String(content ?? "");
  const mi = msg && typeof msg === "object" ? msg : null;
  const logArr = Array.isArray(log) ? log : [];
  const qDom = quoteDomSeg != null && Number.isFinite(Number(quoteDomSeg)) ? Number(quoteDomSeg) : null;
  const bDom = bodyDomSeg != null && Number.isFinite(Number(bodyDomSeg)) ? Number(bodyDomSeg) : null;
  const useQuoteDom = qDom != null && bDom != null;
  const siDom = Math.max(0, Math.floor(Number(segIdx)) || 0);
  if (mi && isChatNarrationSheetSeg(segIdx)) {
    return String(mi.narration || "").trim() || " ";
  }
  if (mi && isChatBubbleActionSheetImageDomSeg(mi, siDom, null)) {
    return getChatMessageImageDescForActionSheet(mi) || " ";
  }
  if (mi && readMessageQuoteRef(mi)) {
    const { quoteRef, parts } = resolveMessageQuotedParts(mi, logArr);
    const si = Number(segIdx) || 0;
    if (useQuoteDom) {
      if (si === qDom) return quoteRef || " ";
      if (si === bDom) return parts[0] || " ";
      const ti = si - bDom - 1;
      if (ti >= 0 && ti < parts.length - 1) return parts[ti + 1] ?? "";
      return parts[0] || " ";
    }
    if (si === 0) return quoteRef || " ";
    const bi = si - 1;
    if (bi >= 0 && bi < parts.length) return parts[bi] ?? "";
    return parts[0] || " ";
  }
  const chunks = rawFull
    .split(/\|\|\|/)
    .map((s) => s.trim())
    .filter(Boolean);
  const chunkArr = chunks.length ? chunks : [rawFull.trim()];
  const { quoteRef, parts } = resolveComposerQuotedDisplayPartsForSurface(chunkArr, r, mi);
  if (quoteRef) {
    const si = Number(segIdx) || 0;
    if (useQuoteDom) {
      if (si === qDom) return `「${quoteRef}」`;
      if (si === bDom) return parts[0] ?? " ";
      const ti = si - bDom - 1;
      if (ti >= 0 && ti < parts.length - 1) return parts[ti + 1] ?? "";
      return parts[0] ?? " ";
    }
    if (si === 0) return `「${quoteRef}」`;
    const bi = si - 1;
    if (bi >= 0 && bi < parts.length) return parts[bi] ?? "";
    return parts[0] ?? " ";
  }
  const segs = rawFull
    .split(/\|\|\|/)
    .map((s) => s.trim())
    .filter(Boolean);
  if (!segs.length) return rawFull.trim();
  let contentSeg = Math.max(0, Math.floor(Number(segIdx)) || 0);
  if (mi && chatMessageHasBubbleImageCard(mi) && !readMessageQuoteRef(mi) && contentSeg > 0) {
    contentSeg -= 1;
  }
  const i = Math.max(0, Math.min(segs.length - 1, contentSeg));
  return segs[i] ?? "";
}

/** 心声好感分：相邻记录默认最大跳变（提示词与入库平滑共用）。 */
const CHAT_HV_AFFINITY_MAX_DELTA = 6;

/** 单条消息内中插 HTML 卡片数（与 walk / render 一致，附在气泡栈末尾）。 */
function countChatInlineHtmlActionSheetSegments(msg) {
  if (!msg || typeof msg !== "object") return 0;
  return typeof window.XXJ_InlineHtml?.countRenderableInlineHtmlCardsFromMessage === "function"
    ? window.XXJ_InlineHtml.countRenderableInlineHtmlCardsFromMessage(msg)
    : typeof window.XXJ_InlineHtml?.readCardsFromMessage === "function"
      ? window.XXJ_InlineHtml.readCardsFromMessage(msg).length
      : 0;
}

/**
 * walk 末尾追加全部中插 HTML 段（固定栈尾，与 render appendCardsToStack 一致）。
 * @param {unknown} msg
 * @param {number} domStart
 * @param {(hit: { kind: "inline-html", domSeg: number, cardIdx: number, cardId?: string, insertAfterSeg?: number | null }) => void | false} fn
 * @returns {number}
 */
function walkAppendInlineHtmlDomSegments(msg, domStart, fn) {
  const cards =
    typeof window.XXJ_InlineHtml?.readCardsFromMessage === "function"
      ? window.XXJ_InlineHtml.readCardsFromMessage(msg)
      : [];
  let dom = Math.max(0, Math.floor(Number(domStart)) || 0);
  for (let ci = 0; ci < cards.length; ci++) {
    const card = cards[ci];
    if (
      typeof window.XXJ_InlineHtml?.inlineHtmlCardIsRenderable === "function" &&
      !window.XXJ_InlineHtml.inlineHtmlCardIsRenderable(card)
    ) {
      continue;
    }
    if (
      fn({
        kind: "inline-html",
        domSeg: dom,
        cardIdx: ci,
        cardId: card && typeof card === "object" ? String(card.id || "").trim() : "",
        insertAfterSeg: null
      }) === false
    ) {
      return dom + 1;
    }
    dom++;
  }
  return dom;
}

/** @param {readonly unknown[]} log @param {number} [beforeIdx] exclusive */
function readLastAssistantHvAffinityFromLog(log, beforeIdx) {
  const arr = Array.isArray(log) ? log : [];
  const end = beforeIdx == null ? arr.length : Math.floor(Number(beforeIdx));
  if (!Number.isFinite(end) || end <= 0) return null;
  for (let i = Math.min(arr.length, end) - 1; i >= 0; i--) {
    const m = arr[i];
    if (!m || typeof m !== "object" || m.role !== "assistant" || m.charLockSessionOnly) continue;
    const a = Number(m.hvAffinity);
    if (Number.isFinite(a)) return Math.max(0, Math.min(100, Math.round(a)));
  }
  return null;
}

/** 心声好感分：相对上一记录平滑，避免模型无缘故大幅跳变。 */
function smoothAssistantHvAffinity(nextRaw, prevRaw) {
  const prev =
    prevRaw != null && Number.isFinite(Number(prevRaw))
      ? Math.max(0, Math.min(100, Math.round(Number(prevRaw))))
      : null;
  const next =
    nextRaw != null && Number.isFinite(Number(nextRaw))
      ? Math.max(0, Math.min(100, Math.round(Number(nextRaw))))
      : null;
  if (prev == null) return next;
  if (next == null) return prev;
  const delta = next - prev;
  if (Math.abs(delta) <= CHAT_HV_AFFINITY_MAX_DELTA) return next;
  return prev + Math.sign(delta) * CHAT_HV_AFFINITY_MAX_DELTA;
}

/** @param {readonly unknown[]} log */
function buildHeartVoiceAffinityContinuityPromptLine(log) {
  const prev = readLastAssistantHvAffinityFromLog(log);
  if (prev == null) {
    return `**mind.affinity**：整数 0～100，表示对主控的当下好感分；首轮按人设与关系定基线，剧情无关时也须给合理数。`;
  }
  const lo = Math.max(0, prev - CHAT_HV_AFFINITY_MAX_DELTA);
  const hi = Math.min(100, prev + CHAT_HV_AFFINITY_MAX_DELTA);
  return (
    `**mind.affinity**（须**连续**）：上一记录 **${prev}**；本轮宜在 **${lo}～${hi}** 内微调（大吵/和解/重大转折可略大，但宜有过程）。` +
    `勿无缘故从 ${prev} 跳到相距很远的数；剧情无关时也须给合理数。`
  );
}

/** 单条消息里独立表情包气泡数（inline placement 或整条 sticker 字段）。 */
function countChatStickerActionSheetSegments(msg, role) {
  if (!msg || typeof msg !== "object") return 0;
  const r = String(role || "");
  if (r !== "user" && r !== "assistant") return 0;
  const placements = getChatStickerPlacements(msg);
  if (placements.length) return placements.length;
  return chatMessageHasStandaloneSticker(msg) ? 1 : 0;
}

/** @param {unknown} msg */
function chatMessageHasStandaloneSticker(msg) {
  if (!msg || typeof msg !== "object") return false;
  if (getChatStickerPlacements(msg).length) return false;
  const st = /** @type {{ sticker?: { url?: string } }} */ (msg).sticker;
  return Boolean(st && typeof st === "object" && String(st.url || "").trim());
}

/**
 * 与 render / 长按分段一致，遍历消息内各 DOM 段（含 insertAfterSeg:-1 与尾部独立 sticker）。
 * @param {unknown} msg
 * @param {string} role
 * @param {(hit: { kind: "quote"|"body"|"photo"|"text"|"sticker"|"inline-html", domSeg: number, url?: string, contentSeg?: number, insertAfterSeg?: number, cardIdx?: number, cardId?: string }) => void | false} fn
 */
function walkChatBubbleSheetDomSegments(msg, role, fn) {
  if (!msg || typeof msg !== "object") return;
  const r = String(role || "");
  if (chatMessageHasQuoteBubbleLayout(msg, r, null)) {
    const bodyN = resolveQuotedMessageBodyPartCount(msg, r, null);
    const placements = getChatStickerPlacements(msg);
    const standalone = chatMessageHasStandaloneSticker(msg);
    let dom = 0;
    const photo = chatMessageHasBubbleImageCard(msg) && !readMessageQuoteRef(msg);
    if (photo) {
      if (fn({ kind: "photo", domSeg: dom }) === false) return;
      dom++;
    }
    if (fn({ kind: "quote", domSeg: dom }) === false) return;
    dom++;
    if (fn({ kind: "body", domSeg: dom, contentSeg: 0 }) === false) return;
    dom++;
    for (const pl of placements) {
      if (pl.insertAfterSeg !== -1) continue;
      if (fn({ kind: "sticker", domSeg: dom, url: pl.url, insertAfterSeg: -1 }) === false) return;
      dom++;
    }
    for (let bi = 1; bi < bodyN; bi++) {
      if (fn({ kind: "text", domSeg: dom, contentSeg: bi }) === false) return;
      dom++;
      for (const pl of placements) {
        if (pl.insertAfterSeg !== bi) continue;
        if (fn({ kind: "sticker", domSeg: dom, url: pl.url, insertAfterSeg: bi }) === false) return;
        dom++;
      }
    }
    if (standalone) {
      fn({
        kind: "sticker",
        domSeg: dom,
        url: String(/** @type {{ sticker?: { url?: string } }} */ (msg).sticker?.url || "").trim(),
        insertAfterSeg: bodyN > 0 ? bodyN - 1 : -1
      });
      dom++;
    }
    walkAppendInlineHtmlDomSegments(msg, dom, fn);
    return;
  }
  const photo = chatMessageHasBubbleImageCard(msg) && !readMessageQuoteRef(msg);
  let dom = 0;
  if (photo) {
    if (fn({ kind: "photo", domSeg: 0 }) === false) return;
    dom = 1;
  }
  const rawFull = String(/** @type {{ content?: unknown }} */ (msg).content ?? "");
  const chunks = rawFull
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean);
  const chunkArr = chunks.length ? chunks : [rawFull.trim() || " "];
  const { parts } = resolveComposerQuotedDisplayPartsForSurface(chunkArr, r, msg);
  const placements = getChatStickerPlacements(msg);
  const standalone = chatMessageHasStandaloneSticker(msg);
  const hasRealText = chatMessageBubblePartsHaveRealText(parts);

  if (standalone && !hasRealText && !photo) {
    fn({
      kind: "sticker",
      domSeg: 0,
      url: String(/** @type {{ sticker?: { url?: string } }} */ (msg).sticker?.url || "").trim(),
      insertAfterSeg: -1
    });
    walkAppendInlineHtmlDomSegments(msg, 1, fn);
    return;
  }

  for (const pl of placements) {
    if (pl.insertAfterSeg !== -1) continue;
    if (fn({ kind: "sticker", domSeg: dom, url: pl.url, insertAfterSeg: -1 }) === false) return;
    dom++;
  }

  for (let i = 0; i < parts.length; i++) {
    if (fn({ kind: "text", domSeg: dom, contentSeg: i }) === false) return;
    dom++;
    for (const pl of placements) {
      if (pl.insertAfterSeg !== i) continue;
      if (fn({ kind: "sticker", domSeg: dom, url: pl.url, insertAfterSeg: i }) === false) return;
      dom++;
    }
  }
  if (standalone) {
    fn({
      kind: "sticker",
      domSeg: dom,
      url: String(/** @type {{ sticker?: { url?: string } }} */ (msg).sticker?.url || "").trim(),
      insertAfterSeg: parts.length > 0 ? parts.length - 1 : -1
    });
    dom++;
  }
  walkAppendInlineHtmlDomSegments(msg, dom, fn);
}

/**
 * 与 render 气泡栈顺序一致，判断长按/删除命中的段类型。
 * @returns {"quote"|"body"|"photo"|"text"|"sticker"|"inline-html"|"unknown"}
 */
function resolveChatBubbleSheetSegmentKind(msg, sheetSegIdx, role) {
  const si = Math.max(0, Math.floor(Number(sheetSegIdx)) || 0);
  if (!msg || typeof msg !== "object") return "unknown";
  let kind = "unknown";
  walkChatBubbleSheetDomSegments(msg, String(role || ""), (hit) => {
    if (hit.domSeg === si) {
      kind = hit.kind;
      return false;
    }
  });
  return kind;
}

/**
 * @param {unknown} msg
 * @param {string} role
 * @param {number} sheetSegIdx
 * @returns {string}
 */
function resolveStickerUrlAtSheetDomSeg(msg, role, sheetSegIdx) {
  const si = Math.max(0, Math.floor(Number(sheetSegIdx)) || 0);
  let url = "";
  walkChatBubbleSheetDomSegments(msg, role, (hit) => {
    if (hit.domSeg === si && hit.kind === "sticker") {
      url = String(hit.url || "").trim();
      return false;
    }
  });
  return url;
}

/** @param {unknown} msg @param {string} role @param {number | null} insertAfterSeg @param {number} [ordinalInGroup] */
function resolveSheetDomSegForInlineHtmlCardPlacement(msg, role, insertAfterSeg, ordinalInGroup = 0) {
  const target =
    insertAfterSeg === null || insertAfterSeg === undefined ? "trailing" : Math.floor(Number(insertAfterSeg));
  let idx = 0;
  let dom = -1;
  walkChatBubbleSheetDomSegments(msg, role, (hit) => {
    if (hit.kind !== "inline-html") return;
    const hitAfter =
      hit.insertAfterSeg === null || hit.insertAfterSeg === undefined
        ? "trailing"
        : Math.floor(Number(hit.insertAfterSeg));
    if (hitAfter !== target) return;
    if (idx === ordinalInGroup) {
      dom = hit.domSeg;
      return false;
    }
    idx++;
  });
  return dom >= 0 ? dom : undefined;
}

/** @param {unknown} msg @param {string} role @param {number} cardIdx */
function resolveSheetDomSegForInlineHtmlCard(msg, role, cardIdx) {
  const ci = Math.max(0, Math.floor(Number(cardIdx)) || 0);
  let dom = -1;
  walkChatBubbleSheetDomSegments(msg, role, (hit) => {
    if (hit.kind === "inline-html" && Math.floor(Number(hit.cardIdx)) === ci) {
      dom = hit.domSeg;
      return false;
    }
  });
  return dom >= 0 ? dom : undefined;
}

/** @param {unknown} msg @param {string} role @param {number} sheetSegIdx */
function resolveInlineHtmlCardIdxAtSheetDomSeg(msg, role, sheetSegIdx) {
  const si = Math.max(0, Math.floor(Number(sheetSegIdx)) || 0);
  let idx = -1;
  walkChatBubbleSheetDomSegments(msg, role, (hit) => {
    if (hit.domSeg === si && hit.kind === "inline-html") {
      idx = Math.floor(Number(hit.cardIdx));
      return false;
    }
  });
  return idx;
}

/** @param {unknown} msg @param {number} cardIdx @returns {boolean} */
function removeInlineHtmlCardFromMessage(msg, cardIdx) {
  if (!msg || typeof msg !== "object") return false;
  if (typeof window.XXJ_InlineHtml?.readCardsFromMessage !== "function") return false;
  const cards = window.XXJ_InlineHtml.readCardsFromMessage(msg);
  const ci = Math.max(0, Math.floor(Number(cardIdx)) || 0);
  if (ci < 0 || ci >= cards.length) return false;
  const next = cards.slice();
  next.splice(ci, 1);
  if (next.length) msg.inlineHtmlCards = next;
  else delete msg.inlineHtmlCards;
  return true;
}

window.resolveSheetDomSegForInlineHtmlCard = resolveSheetDomSegForInlineHtmlCard;
window.resolveSheetDomSegForInlineHtmlCardPlacement = resolveSheetDomSegForInlineHtmlCardPlacement;

/**
 * 多选/批量删除：与长按删除一致，命中表情包段时带上 isStickerBubble / stickerUrl。
 * @param {unknown} msg
 * @param {number} segIdx
 * @returns {{ isStickerBubble: boolean, stickerUrl?: string } | undefined}
 */
function resolveChatBubbleDeleteOptsForLogSegment(msg, segIdx) {
  if (!msg || typeof msg !== "object") return undefined;
  const role = String(/** @type {{ role?: string }} */ (msg).role || "");
  const si = Math.max(0, Math.floor(Number(segIdx)) || 0);
  if (resolveChatBubbleSheetSegmentKind(msg, si, role) !== "sticker") return undefined;
  const url = resolveStickerUrlAtSheetDomSeg(msg, role, si);
  return { isStickerBubble: true, stickerUrl: url || undefined };
}

/**
 * @param {unknown} msg
 * @param {string} role
 * @param {number} insertAfterSeg
 * @param {number} [ordinalInGroup]
 * @returns {number | undefined}
 */
function resolveSheetDomSegForStickerPlacement(msg, role, insertAfterSeg, ordinalInGroup = 0) {
  const targetAfter = Math.floor(Number(insertAfterSeg));
  const ord = Math.max(0, Math.floor(Number(ordinalInGroup)) || 0);
  let n = 0;
  let dom = -1;
  walkChatBubbleSheetDomSegments(msg, role, (hit) => {
    if (hit.kind !== "sticker") return;
    if (Math.floor(Number(hit.insertAfterSeg)) !== targetAfter) return;
    if (n === ord) {
      dom = hit.domSeg;
      return false;
    }
    n++;
  });
  return dom >= 0 ? dom : undefined;
}

/** 与 walk / render 一致：正文分段 contentSeg 对应的 DOM 分段号。 */
function resolveSheetDomSegForTextContentSeg(msg, role, contentSeg) {
  const cs = Math.max(0, Math.floor(Number(contentSeg)) || 0);
  let dom = -1;
  walkChatBubbleSheetDomSegments(msg, role, (hit) => {
    if ((hit.kind === "text" || hit.kind === "body") && Math.floor(Number(hit.contentSeg)) === cs) {
      dom = hit.domSeg;
      return false;
    }
  });
  return dom >= 0 ? dom : undefined;
}

/** @param {unknown} msg @param {string} role */
function resolveSheetDomSegForQuoteBar(msg, role) {
  let dom = -1;
  walkChatBubbleSheetDomSegments(msg, role, (hit) => {
    if (hit.kind === "quote") {
      dom = hit.domSeg;
      return false;
    }
  });
  return dom >= 0 ? dom : undefined;
}

/** @param {unknown} msg @param {string} role */
function resolveSheetDomSegForQuoteBody(msg, role) {
  let dom = -1;
  walkChatBubbleSheetDomSegments(msg, role, (hit) => {
    if (hit.kind === "body") {
      dom = hit.domSeg;
      return false;
    }
  });
  return dom >= 0 ? dom : undefined;
}

/** 渲染写入 data-chat-bubble-seg 时的兜底（walk 未命中时退回旧口径）。 */
function chatBubbleDomSegForRender(msg, role, contentSeg, legacyShift) {
  const fromWalk = resolveSheetDomSegForTextContentSeg(msg, role, contentSeg);
  if (fromWalk != null) return fromWalk;
  return Math.max(0, Math.floor(Number(contentSeg)) || 0) + Math.max(0, Math.floor(Number(legacyShift)) || 0);
}

/**
 * @param {unknown} msg
 * @param {string} [stickerUrlHint]
 * @returns {boolean}
 */
function chatStickerUrlsLikelyMatch(stored, hinted) {
  const a = String(stored || "").trim();
  const b = String(hinted || "").trim();
  if (!a || !b) return !a && !b;
  if (a === b) return true;
  return a.endsWith(b) || b.endsWith(a);
}

function removeStickerFromChatMessage(msg, stickerUrlHint) {
  if (!msg || typeof msg !== "object") return false;
  const hint = String(stickerUrlHint || "").trim();
  const placements = getChatStickerPlacements(msg);
  if (placements.length) {
    if (hint) {
      const filtered = placements.filter((p) => !chatStickerUrlsLikelyMatch(p.url, hint));
      if (filtered.length === placements.length) return false;
      if (filtered.length) msg.stickerPlacements = filtered;
      else delete msg.stickerPlacements;
      if (!getChatStickerPlacements(msg).length && !chatMessageHasStandaloneSticker(msg)) {
        stripStickerPlaceholdersFromMessageContent(msg);
      }
      return true;
    }
    if (placements.length === 1) {
      delete msg.stickerPlacements;
      stripStickerPlaceholdersFromMessageContent(msg);
      return true;
    }
    return false;
  }
  if (!chatMessageHasStandaloneSticker(msg)) return false;
  if (hint) {
    const u = String(/** @type {{ sticker?: { url?: string } }} */ (msg).sticker?.url || "").trim();
    if (u && !chatStickerUrlsLikelyMatch(u, hint)) return false;
  }
  delete msg.sticker;
  stripStickerPlaceholdersFromMessageContent(msg);
  return true;
}

/** @param {unknown} msg @param {string} role */
function chatMessageShouldRemoveEntryWhenEmpty(msg, role) {
  if (!msg || typeof msg !== "object") return true;
  const stillSticker =
    chatMessageHasStandaloneSticker(msg) || getChatStickerPlacements(msg).length > 0;
  const stillImgUrl =
    msg.image && typeof msg.image === "object" && String(msg.image.url || "").trim();
  const stillImgDesc =
    msg.image && typeof msg.image === "object" && String(msg.image.desc || "").trim();
  const stillInlineHtml =
    typeof window.XXJ_InlineHtml?.messageHasInlineHtmlCards === "function" &&
    window.XXJ_InlineHtml.messageHasInlineHtmlCards(msg);
  if (stillImgUrl || stillImgDesc || stillSticker || stillInlineHtml) return false;
  if (String(msg.narration || "").trim()) return false;
  if (readMessageQuoteRef(msg) && String(msg.content || "").trim()) return false;
  if (String(msg.content || "").trim()) return false;
  return true;
}

/** 与长按气泡菜单分段一致：含「引用」时为引用条 + 各正文段（不合并成一条）。 */
function countChatBubbleActionSheetSegments(content, role, msg) {
  const r = String(role || "");
  if (msg && chatMessageHasQuoteBubbleLayout(msg, r, null)) {
    return (
      1 +
      resolveQuotedMessageBodyPartCount(msg, r, null) +
      countChatInlineHtmlActionSheetSegments(msg)
    );
  }
  const rawFull = String(content ?? "");
  const chunks = rawFull
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean);
  const chunkArr = chunks.length ? chunks : [rawFull.trim() || " "];
  const { parts } = resolveComposerQuotedDisplayPartsForSurface(chunkArr, r, msg);
  const ph =
    msg &&
    typeof msg === "object" &&
    msg.image &&
    typeof msg.image === "object" &&
    (String(msg.image.url || "").trim() || String(msg.image.desc || "").trim());
  const hasRealText = chatMessageBubblePartsHaveRealText(parts);
  const stickerSegs = countChatStickerActionSheetSegments(msg, role);
  const ihSegs = countChatInlineHtmlActionSheetSegments(msg);
  const standalone = msg && chatMessageHasStandaloneSticker(msg);
  if (standalone && !hasRealText && !ph) return Math.max(1, stickerSegs);
  let n = hasRealText ? Math.max(1, parts.length) : parts.length;
  if (!hasRealText && !stickerSegs && !ph && !ihSegs) n = 1;
  else if (!hasRealText && stickerSegs) n = 0;
  if (ph) n += 1;
  n += stickerSegs;
  if (standalone && hasRealText) n += 1;
  n += ihSegs;
  return Math.max(1, n);
}

/**
 * 长按菜单里「编辑」用的可编辑文本（引用模式下正文为整段合并，与单气泡展示一致）。
 * @param {number | null | undefined} [quoteDomSeg]
 * @param {number | null | undefined} [bodyDomSeg]
 */
function getChatBubbleActionSheetEditableSegmentText(content, role, segIdx, msg, log, quoteDomSeg, bodyDomSeg) {
  const si = Math.max(0, Math.floor(Number(segIdx)) || 0);
  const r = String(role || "");
  const rawFull = String(content ?? "");
  const logArr = Array.isArray(log) ? log : [];
  const qDom = quoteDomSeg != null && Number.isFinite(Number(quoteDomSeg)) ? Number(quoteDomSeg) : null;
  const bDom = bodyDomSeg != null && Number.isFinite(Number(bodyDomSeg)) ? Number(bodyDomSeg) : null;
  const useQuoteDom = qDom != null && bDom != null;
  if (msg && readMessageQuoteRef(msg)) {
    if (isChatBubbleActionSheetImageDomSeg(msg, si, null)) {
      return getChatImageGenSceneBlockForEdit(msg) || " ";
    }
    return getChatMessageSegmentPlain(rawFull, si, r, msg, logArr, quoteDomSeg, bodyDomSeg);
  }
  return getChatMessageSegmentPlain(rawFull, si, r, msg, logArr, quoteDomSeg, bodyDomSeg);
}

/**
 * 将某一段气泡文字写回整条消息的 `content`（||| / 引用格式与存储一致）。
 * @param {string} content
 * @param {string} role
 * @param {number} segIdx
 * @param {string} newText
 * @param {unknown} [msg] 若传入且含结构化 `quote`，可就地更新 `msg.quote` / `msg.content`
 * @param {number | null | undefined} [quoteDomSeg]
 * @param {number | null | undefined} [bodyDomSeg]
 */
function applyChatBubbleActionSheetSegmentToContent(content, role, segIdx, newText, msg, quoteDomSeg, bodyDomSeg) {
  const si = Math.max(0, Math.floor(Number(segIdx)) || 0);
  const r = String(role || "");
  const nt = String(newText ?? "");
  const rawFull = String(content ?? "");
  const qDom = quoteDomSeg != null && Number.isFinite(Number(quoteDomSeg)) ? Number(quoteDomSeg) : null;
  const bDom = bodyDomSeg != null && Number.isFinite(Number(bodyDomSeg)) ? Number(bodyDomSeg) : null;
  const useQuoteDom = qDom != null && bDom != null;
  if (msg && isChatBubbleActionSheetImageDomSeg(msg, si, null)) {
    return rawFull;
  }
  if (msg && typeof msg === "object" && readMessageQuoteRef(msg)) {
    const editingQuoteSnap = useQuoteDom ? si === qDom : si === 0;
    if (editingQuoteSnap) {
      const nt0 = nt.trim().slice(0, 4000);
      /** @type {Record<string, unknown>} */
      const mo = msg;
      const prev = mo.quote && typeof mo.quote === "object" ? /** @type {Record<string, unknown>} */ (mo.quote) : {};
      mo.quote = { ...prev, text: nt0 };
      return String(mo.content ?? "");
    }
    const { parts } = resolveMessageQuotedParts(msg, []);
    const np = parts.length ? parts.map((s) => String(s ?? "").trim()) : [String(rawFull).trim() || " "];
    let bodySi = useQuoteDom && bDom != null ? si - bDom : si - 1;
    if (bodySi < 0) bodySi = 0;
    if (bodySi >= 0 && bodySi < np.length) np[bodySi] = nt.trim() || " ";
    /** @type {Record<string, unknown>} */
    const mo = msg;
    mo.content = np.filter((s) => s.length > 0).join("|||") || " ";
    return String(mo.content ?? "");
  }
  const chunks = rawFull
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean);
  const chunkArr = chunks.length ? chunks : [rawFull.trim() || " "];
  const { quoteRef, parts: origParts } = resolveComposerQuotedDisplayPartsForSurface(chunkArr, r, msg);
  if (quoteRef) {
    const editingQuoteLegacy = useQuoteDom ? si === qDom : si === 0;
    if (editingQuoteLegacy) {
      const m = /^「([^」]*)」/.exec(nt.trim());
      const innerNew = m ? String(m[1] ?? "").trim() : "";
      const qNext = innerNew || quoteRef;
      return encodeQuotedComposerStorageFromParts(qNext, origParts);
    }
    const np = origParts.length ? origParts.map((s) => String(s ?? "").trim()) : [" "];
    let bodySi = useQuoteDom && bDom != null ? si - bDom : si - 1;
    if (bodySi < 0) bodySi = 0;
    if (bodySi >= 0 && bodySi < np.length) np[bodySi] = nt.trim() || " ";
    return encodeQuotedComposerStorageFromParts(quoteRef, np.filter((s) => s.length > 0));
  }
  const parts = origParts.length ? origParts.slice() : [rawFull.trim() || " "];
  let parallelSi = si;
  if (msg && chatMessageHasBubbleImageCard(msg) && !readMessageQuoteRef(msg) && si > 0) {
    parallelSi = si - 1;
  }
  if (parallelSi >= 0 && parallelSi < parts.length) parts[parallelSi] = nt.trim() || " ";
  return parts.join("|||");
}

/** @param {string} quoteInner @param {string[]} parts */
function encodeQuotedComposerStorageFromParts(quoteInner, parts) {
  const q = String(quoteInner || "").trim();
  const p = Array.isArray(parts) ? parts.map((s) => String(s ?? "").trim()) : [];
  if (!q) return p.filter((s) => s.length > 0).join("|||") || " ";
  if (!p.length || (p.length === 1 && !String(p[0] ?? "").trim())) return `「${q}」`;
  const head = `「${q}」\n\n${p[0]}`;
  if (p.length <= 1) return head;
  return [head, ...p.slice(1)].join("|||");
}

/** 对照翻译：只改第 i 段（空串表示该段暂缺译文）。 */
function patchAssistantTranslationOneSegment(msg, segIdx, newSegTrans) {
  if (!msg || msg.role !== "assistant") return;
  const n = countChatBubbleActionSheetSegments(String(msg.content ?? ""), "assistant", msg);
  const arr = padTranslationSegments(msg.translation, n);
  const si = Math.max(0, Math.floor(Number(segIdx)) || 0);
  if (si < arr.length) arr[si] = newSegTrans == null ? "" : String(newSegTrans);
  const joined = arr.join("|||");
  if (msg.role === "assistant" && chatMessageDmSurface(msg) === "offline") {
    msg.content = mergeOfflineTranslationsIntoInlineSegments(String(msg.content ?? ""), joined);
    const mains = String(msg.content ?? "")
      .split(/\|\|\|/)
      .map((s) => String(s).trim())
      .filter(Boolean);
    if (mains.length) {
      msg.translation = mains
        .map(() => CHAT_TRANSLATION_SKIP_TOKEN)
        .join("|||")
        .slice(0, 500_000);
    } else delete msg.translation;
    return;
  }
  if (translationJoinedHasAnyVisible(joined)) msg.translation = joined.slice(0, 500_000);
  else delete msg.translation;
}

function clearAssistantVoiceMarkAtSegment(msg, segIdx) {
  if (!msg || msg.role !== "assistant") return;
  const si = Math.max(0, Math.floor(Number(segIdx)) || 0);
  if (!Array.isArray(msg.voiceLines) || si >= msg.voiceLines.length) return;
  const vl = msg.voiceLines.slice();
  const vs = Array.isArray(msg.voiceSeconds) ? msg.voiceSeconds.slice() : [];
  while (vs.length < vl.length) vs.push(NaN);
  vl[si] = false;
  vs[si] = NaN;
  if (!vl.some(Boolean)) {
    delete msg.voiceLines;
    delete msg.voiceSeconds;
    delete msg.voiceRevealSegs;
    return;
  }
  msg.voiceLines = vl;
  if (vs.some((x) => Number.isFinite(Number(x)))) msg.voiceSeconds = vs;
  else delete msg.voiceSeconds;
  if (Array.isArray(msg.voiceRevealSegs)) {
    const vr = msg.voiceRevealSegs.slice();
    if (vr.length > si) vr[si] = false;
    msg.voiceRevealSegs = vr;
  }
}

/**
 * 正文里是否仍有「【红包】」类可识别红包段（与 msg.redpack 状态配合）。
 * @param {string} content
 * @param {string} role
 * @param {unknown} [msg]
 */
function chatMessageContentHasRedpackSegment(content, role, msg) {
  if (msg?.redpack && typeof msg.redpack === "object" && window.XXJ_GroupRedpack?.isGroupRedpack?.(msg.redpack)) {
    return true;
  }
  const r = String(role || "");
  const raw = String(content ?? "").trim();
  if (msg && readMessageQuoteRef(msg)) {
    const { quoteRef, parts } = resolveMessageQuotedParts(msg, []);
    for (const seg of parts) {
      if (parseRedpackMessageText(String(seg || "").trim())) return true;
    }
    if (quoteRef && parseRedpackMessageText(`「${quoteRef}」`)) return true;
    return false;
  }
  if (!raw) return false;
  const chunks = raw
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean);
  const chunkArr = chunks.length ? chunks : [raw];
  const { quoteRef, parts } = resolveComposerQuotedDisplayPartsForSurface(chunkArr, r, msg);
  for (const seg of parts) {
    if (parseRedpackMessageText(String(seg || "").trim())) return true;
  }
  if (quoteRef) {
    const qline = `「${quoteRef}」`;
    if (parseRedpackMessageText(qline)) return true;
  }
  return false;
}

/**
 * 从一条 user/assistant 消息中删除长按菜单对应的一段；若删光可展示正文则标记整条移除。
 * @param {{ role?: string, content?: string, translation?: string, voiceLines?: boolean[], voiceSeconds?: number[], voiceRevealSegs?: boolean[], redpack?: unknown, sticker?: unknown, image?: unknown, asVoice?: boolean }} msg
 * @param {number} sheetSegIdx
 * @param {{ isStickerBubble?: boolean, stickerUrl?: string }} [opts]
 * @returns {{ ok: boolean, removeEntry: boolean }}
 */
function removeChatBubbleSheetSegmentFromMessage(msg, sheetSegIdx, opts) {
  if (!msg || (msg.role !== "user" && msg.role !== "assistant")) return { ok: false, removeEntry: false };
  const role = String(msg.role);
  const si = Math.max(0, Math.floor(Number(sheetSegIdx)) || 0);
  if (isChatNarrationSheetSeg(si)) {
    if (role !== "assistant" || !String(msg.narration || "").trim()) {
      return { ok: false, removeEntry: false };
    }
    delete msg.narration;
    return {
      ok: true,
      removeEntry: chatMessageShouldRemoveEntryWhenEmpty(msg, role)
    };
  }
  const sheetN = countChatBubbleActionSheetSegments(String(msg.content ?? ""), role, msg);
  if (isChatBubbleActionSheetImageDomSeg(msg, si, null)) {
    if (msg.image && typeof msg.image === "object") delete msg.image;
    return {
      ok: true,
      removeEntry: chatMessageShouldRemoveEntryWhenEmpty(msg, role)
    };
  }
  const segKind = opts?.isStickerBubble ? "sticker" : resolveChatBubbleSheetSegmentKind(msg, si, role);
  if (segKind === "sticker") {
    if (!removeStickerFromChatMessage(msg, opts?.stickerUrl)) return { ok: false, removeEntry: false };
    return {
      ok: true,
      removeEntry: chatMessageShouldRemoveEntryWhenEmpty(msg, role)
    };
  }
  if (segKind === "inline-html") {
    const cardIdx = resolveInlineHtmlCardIdxAtSheetDomSeg(msg, role, si);
    if (cardIdx < 0 || !removeInlineHtmlCardFromMessage(msg, cardIdx)) {
      return { ok: false, removeEntry: false };
    }
    return {
      ok: true,
      removeEntry: chatMessageShouldRemoveEntryWhenEmpty(msg, role)
    };
  }
  if (segKind === "quote" || segKind === "body") {
    return { ok: true, removeEntry: true };
  }
  if (sheetN <= 0 || si >= sheetN) return { ok: false, removeEntry: false };

  const hasPhotoCard =
    !readMessageQuoteRef(msg) &&
    msg.image &&
    typeof msg.image === "object" &&
    (String(msg.image.url || "").trim() || String(msg.image.desc || "").trim());
  const parallelSi = hasPhotoCard && si > 0 ? si - 1 : si;
  const hadStickerBefore =
    msg.sticker && typeof msg.sticker === "object" && String(msg.sticker.url || "").trim();

  let newContent = "";
  let structuredQuoteParallelSi = -1;

  if (segKind === "text" && chatMessageHasQuoteBubbleLayout(msg, role, null)) {
    const spliced = spliceQuotedMessageBodySegment(msg, role, si, null);
    if (!spliced) return { ok: false, removeEntry: false };
    newContent = spliced.newContent;
    structuredQuoteParallelSi = spliced.parallelSi;
  } else {
    const rawFull = String(msg.content ?? "");
    const chunks = rawFull
      .split(/\|\|\|/)
      .map((s) => String(s).trim())
      .filter(Boolean);
    const chunkArr = chunks.length ? chunks : [rawFull.trim() || " "];
    const { parts } = resolveComposerQuotedDisplayPartsForSurface(chunkArr, role, msg);

    const np = parts.map((s) => String(s ?? "").trim());
    if (parallelSi < 0 || parallelSi >= np.length) return { ok: false, removeEntry: false };
    np.splice(parallelSi, 1);
    newContent = np.filter((s) => s.length > 0).join("|||");
  }

  const parallelSiForMeta =
    structuredQuoteParallelSi >= 0
      ? structuredQuoteParallelSi
      : hasPhotoCard && si > 0
        ? si - 1
        : si;

  if (role === "assistant") {
    const textSlots = Math.max(1, sheetN - (hasPhotoCard ? 1 : 0));
    const arr = padTranslationSegments(msg.translation, textSlots);
    if (parallelSiForMeta < arr.length) arr.splice(parallelSiForMeta, 1);
    const joined = arr.join("|||");
    if (chatMessageDmSurface(msg) === "offline") {
      newContent = mergeOfflineTranslationsIntoInlineSegments(String(newContent ?? ""), joined);
      const mains = String(newContent ?? "")
        .split(/\|\|\|/)
        .map((s) => String(s).trim())
        .filter(Boolean);
      if (mains.length) {
        msg.translation = mains
          .map(() => CHAT_TRANSLATION_SKIP_TOKEN)
          .join("|||")
          .slice(0, 500_000);
      } else delete msg.translation;
    } else if (translationJoinedHasAnyVisible(joined)) msg.translation = joined.slice(0, 500_000);
    else delete msg.translation;
    if (Array.isArray(msg.voiceLines) && msg.voiceLines.length > parallelSiForMeta) {
      const vl = msg.voiceLines.slice();
      const vs = Array.isArray(msg.voiceSeconds) ? msg.voiceSeconds.slice() : [];
      vl.splice(parallelSiForMeta, 1);
      if (parallelSiForMeta < vs.length) vs.splice(parallelSiForMeta, 1);
      while (vs.length < vl.length) vs.push(NaN);
      if (!vl.some(Boolean)) {
        delete msg.voiceLines;
        delete msg.voiceSeconds;
        delete msg.voiceRevealSegs;
      } else {
        msg.voiceLines = vl;
        if (vs.some((x) => Number.isFinite(Number(x)))) msg.voiceSeconds = vs;
        else delete msg.voiceSeconds;
      }
    }
    if (Array.isArray(msg.voiceRevealSegs) && msg.voiceRevealSegs.length > parallelSiForMeta) {
      const vr = msg.voiceRevealSegs.slice();
      vr.splice(parallelSiForMeta, 1);
      msg.voiceRevealSegs = vr;
    }
  }

  const textEmpty = !String(newContent || "").trim();
  if (textEmpty && sheetN === 1 && si === 0 && hadStickerBefore) {
    delete msg.sticker;
  }

  msg.content = newContent;

  try {
    if (msg.redpack && typeof msg.redpack === "object") {
      const probeMsg = { ...msg, content: String(msg.content ?? "") };
      if (!chatMessageContentHasRedpackSegment(String(msg.content ?? ""), role, probeMsg)) delete msg.redpack;
    }
  } catch (_) {
    /* ignore */
  }

  if (!String(msg.content || "").trim()) {
    return { ok: true, removeEntry: chatMessageShouldRemoveEntryWhenEmpty(msg, role) };
  }
  return { ok: true, removeEntry: false };
}

/**
 * @param {number} msgIdx
 * @param {number} sheetSegIdx
 * @param {{ isStickerBubble?: boolean, stickerUrl?: string }} [opts]
 */
function removeChatBubbleSegmentFromLog(msgIdx, sheetSegIdx, opts) {
  const log = readChatLog();
  const i = Number(msgIdx);
  const si = Math.max(0, Math.floor(Number(sheetSegIdx)) || 0);
  if (!Number.isFinite(i) || i < 0 || i >= log.length) return false;
  const msg = log[i];
  const r = removeChatBubbleSheetSegmentFromMessage(msg, si, opts);
  if (!r.ok) return false;
  if (r.removeEntry) {
    log.splice(i, 1);
  }
  saveChatLog(log);
  return true;
}

/**
 * 整条载入输入框：与当面气泡同源（晤面不把「」当引用条拆段；结构化引用仍用 msg.quote）。
 * @param {string} content
 * @param {string} role
 * @param {unknown} msg
 */
function bubbleRoleMessageToEditableTextForMsgSurface(content, role, msg) {
  if (msg && typeof msg === "object" && readMessageQuoteRef(msg) && chatMessageDmSurface(msg) !== "offline") {
    const parts = structuredQuoteBodyPartsFromContent(msg, readChatLog());
    return parts.map((s) => String(s).trim()).filter(Boolean).join("\n\n");
  }
  const rawFull = String(content ?? "").trim();
  const r = String(role || "");
  const chunks = rawFull
    .split(/\|\|\|/)
    .map((s) => s.trim())
    .filter(Boolean);
  const chunkArr = chunks.length ? chunks : [rawFull];
  const { quoteRef, parts } = resolveComposerQuotedDisplayPartsForSurface(chunkArr, r, msg);
  if (quoteRef) return parts.join("\n\n");
  const parts2 = parts.map((s) => String(s).trim()).filter(Boolean);
  return parts2.length ? parts2.join("\n\n") : rawFull;
}

/** 与时间条同款 UI 的撤回提示（持久化在 messages 里） */
const CHAT_NOTICE_RECALL_LABEL = "你撤回了一条消息";

/** @param {string} [recalledContent] @param {string} [recalledTranslation] */
function createChatNoticeRecallEntry(recalledContent, recalledTranslation) {
  const ent = { role: "notice", kind: "recall_user", at: Date.now(), content: "" };
  const body = String(recalledContent ?? "").trim();
  if (body) ent.recalledContent = body.slice(0, 500_000);
  const tr = String(recalledTranslation ?? "").trim();
  if (tr) ent.recalledTranslation = tr.slice(0, 500_000);
  return ent;
}

/**
 * 撤回：仅撤回这一条消息（不再按“一轮”删除后续消息）。
 * @param {{ insertRecallNotice?: boolean }} [opts] — `insertRecallNotice: false` 用于「编辑」收回，不插入系统提示。
 * @returns {{ ok: boolean, userContent?: string }}
 */
function spliceRecallUserBlock(idx, opts) {
  const insertNotice = !(opts && opts.insertRecallNotice === false);
  const log = readChatLog();
  const i = Number(idx);
  if (!Number.isFinite(i) || i < 0 || i >= log.length) return { ok: false };
  if (log[i].role !== "user") return { ok: false };
  const userContent = String(log[i].content ?? "");
  const userTranslation = String(log[i].translation ?? "").trim();
  const tail = log.slice(i + 1);
  const mid = insertNotice
    ? [createChatNoticeRecallEntry(userContent, userTranslation)]
    : [];
  saveChatLog(log.slice(0, i).concat(mid, tail));
  return { ok: true, userContent };
}

function deleteChatMessageAt(idx) {
  const log = readChatLog();
  const i = Number(idx);
  if (!Number.isFinite(i) || i < 0 || i >= log.length) return false;
  saveChatLog(log.slice(0, i).concat(log.slice(i + 1)));
  return true;
}

/** 晤面日记卡 Date 栏：Date 2026年3月1日 02:51 @param {number} at */
function formatOfflineDiaryDateLabel(at) {
  if (at == null || !Number.isFinite(Number(at))) return "Date —";
  const d = new Date(Number(at));
  const y = d.getFullYear();
  const mo = d.getMonth() + 1;
  const day = d.getDate();
  const hm = `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
  return `Date ${y}年${mo}月${day}日 ${hm}`;
}

function resolveOfflineDiaryPolaroidAvatar(inner, polaroid, role, charP, userM, m) {
  if (!(inner instanceof HTMLElement) || !(polaroid instanceof HTMLElement)) return null;
  const existing = polaroid.querySelector(".chat-msg-avatar");
  if (existing instanceof HTMLElement) return existing;

  let avatarSlot = inner.querySelector(":scope > .chat-msg-avatar-col, :scope > .chat-msg-avatar");
  if (!avatarSlot) {
    avatarSlot = inner.querySelector(
      ".chat-msg-glass-line .chat-msg-avatar-col, .chat-msg-glass-line .chat-msg-avatar"
    );
  }
  if (avatarSlot instanceof HTMLElement) {
    const av = avatarSlot.classList.contains("chat-msg-avatar-col")
      ? avatarSlot.querySelector(".chat-msg-avatar")
      : avatarSlot;
    if (av instanceof HTMLElement) {
      polaroid.appendChild(av);
      if (avatarSlot !== av) avatarSlot.remove();
      return av;
    }
    avatarSlot.remove();
  }

  const cp = charP ?? readCharPersonaForThread(readActiveThread()) ?? readCharPersona();
  const um = userM ?? readUserMask();
  const av = createChatRowAvatarEl(role, cp, um, m);
  polaroid.appendChild(av);
  return av;
}

/**
 * 晤面 · 图 1 日记卡：信头（名 + 拍立得头像）+ 白卡（Date 栏 / 正文 / 页脚）。
 * @param {HTMLElement} wrap
 * @param {{ role?: string, at?: number, restoring?: boolean }} m
 * @param {"user"|"assistant"|"system"} role
 * @param {ReturnType<typeof readCharPersona> | null | undefined} charP
 * @param {ReturnType<typeof readUserMask>} userM
 */
function decorateOfflineDiaryCardChrome(wrap, m, role, charP, userM) {
  if (getActiveChatDmSurfaceForContext() !== "offline") return;
  if (!wrap || !m || typeof m !== "object") return;
  if (wrap.classList.contains("chat-msg--call-ended-notice")) return;
  if (role !== "user" && role !== "assistant") return;
  const inner = wrap.querySelector(":scope > .chat-msg-inner");
  const stack = wrap.querySelector(":scope .chat-msg-bubble-stack");
  if (!(inner instanceof HTMLElement) || !(stack instanceof HTMLElement)) return;
  const hasProse =
    stack.querySelector(
      ".chat-msg-bubble:not(.chat-msg-bubble--sticker):not(.chat-msg-bubble--typing), .chat-msg-card"
    ) != null;
  if (!hasProse) return;

  const cp = charP ?? readCharPersonaForThread(readActiveThread()) ?? readCharPersona();
  const um = userM ?? readUserMask();

  if (stack.querySelector(":scope > .chat-f2f-diary-meta")) {
    inner.classList.add("chat-msg-inner--f2f-diary");
    stack.classList.add("chat-f2f-diary-sheet");
    const polaroidExisting = inner.querySelector(".chat-f2f-diary-polaroid");
    if (polaroidExisting instanceof HTMLElement) {
      resolveOfflineDiaryPolaroidAvatar(inner, polaroidExisting, role, cp, um, m);
    }
    return;
  }

  inner.classList.add("chat-msg-inner--f2f-diary");
  stack.classList.add("chat-f2f-diary-sheet");

  const head = document.createElement("div");
  head.className = "chat-f2f-diary-head";
  const headCopy = document.createElement("div");
  headCopy.className = "chat-f2f-diary-head-copy";
  const nameEl = document.createElement("p");
  nameEl.className = "chat-f2f-diary-name";
  const displayName =
    role === "user"
      ? String(um?.displayName || "我").trim() || "我"
      : String(getChatCharPersonaDisplayName() || "Ta").trim() || "Ta";
  nameEl.textContent = displayName;
  const subEl = document.createElement("p");
  subEl.className = "chat-f2f-diary-sub";
  subEl.textContent = role === "user" ? "写在纸本上的话。" : "晤面 · 长文";
  headCopy.append(nameEl, subEl);
  head.appendChild(headCopy);

  const polaroid = document.createElement("div");
  polaroid.className = "chat-f2f-diary-polaroid";
  resolveOfflineDiaryPolaroidAvatar(inner, polaroid, role, cp, um, m);
  head.appendChild(polaroid);
  inner.insertBefore(head, stack);

  const meta = document.createElement("div");
  meta.className = "chat-f2f-diary-meta";
  const dateEl = document.createElement("time");
  dateEl.className = "chat-f2f-diary-date";
  const at = Number.isFinite(Number(m.at)) ? Number(m.at) : null;
  dateEl.textContent = formatOfflineDiaryDateLabel(at);
  if (at != null) dateEl.dateTime = new Date(at).toISOString();
  meta.appendChild(dateEl);
  const actions = document.createElement("div");
  actions.className = "chat-f2f-diary-actions";
  meta.appendChild(actions);
  stack.insertBefore(meta, stack.firstChild);

  const foot = document.createElement("div");
  foot.className = "chat-f2f-diary-foot";
  foot.setAttribute("aria-hidden", "true");
  stack.appendChild(foot);
}

/** 晤面输入区：与日记卡同套白卡 + Draft 顶栏。 */
function applyOfflineDiaryComposerChrome() {
  const panel = document.querySelector("#chat-composer.chat-composer--f2f-prose .chat-slab-panel.chat-composer-panel");
  if (!(panel instanceof HTMLElement)) return;
  if (panel.querySelector(":scope > .chat-f2f-diary-compose-meta")) return;
  const meta = document.createElement("div");
  meta.className = "chat-f2f-diary-compose-meta";
  const label = document.createElement("span");
  label.className = "chat-f2f-diary-compose-date";
  label.textContent = "Draft · 续写";
  meta.appendChild(label);
  const actions = document.createElement("div");
  actions.className = "chat-f2f-diary-compose-actions";
  meta.appendChild(actions);
  panel.insertBefore(meta, panel.firstChild);
  const fabs = panel.querySelector(".chat-composer-fabs");
  if (fabs instanceof HTMLElement) {
    actions.appendChild(fabs);
  }
}

function removeOfflineDiaryComposerChrome() {
  const panel = document.querySelector("#chat-composer .chat-slab-panel.chat-composer-panel");
  if (!(panel instanceof HTMLElement)) return;
  const meta = panel.querySelector(":scope > .chat-f2f-diary-compose-meta");
  const fabs = meta?.querySelector(".chat-composer-fabs");
  if (fabs instanceof HTMLElement) {
    panel.appendChild(fabs);
  }
  meta?.remove();
}

/**
 * 线下页专用：日记卡 Date 栏内「编辑 / 删除」（与长按菜单同源；即时消息不注入）。
 * @param {HTMLElement} wrap
 * @param {{ role?: string, restoring?: boolean }} m
 * @param {"user"|"assistant"|"system" | undefined} roleHint
 * @param {ReturnType<typeof readCharPersona> | null | undefined} charP
 * @param {ReturnType<typeof readUserMask>} userM
 */
function injectChatMsgQuickToolbar(wrap, m, roleHint, charP, userM) {
  if (getActiveChatDmSurfaceForContext() !== "offline") return;
  if (!wrap || !m || typeof m !== "object") return;
  const role =
    roleHint ||
    (wrap.classList.contains("chat-msg--user")
      ? "user"
      : wrap.classList.contains("chat-msg--assistant")
        ? "assistant"
        : "system");
  decorateOfflineDiaryCardChrome(wrap, m, role, charP, userM);
  if (chatMsgMultiSelectMode) return;
  if (m.role !== "user" && m.role !== "assistant") return;
  if (wrap.classList.contains("chat-msg--call-ended-notice")) return;
  if (m.role === "assistant" && m.restoring) return;
  const stack = wrap.querySelector(":scope .chat-msg-bubble-stack");
  if (!stack) return;
  wrap.querySelector(":scope > .chat-msg-quick")?.remove();
  stack.querySelector(":scope > .chat-msg-quick")?.remove();
  stack.querySelector(".chat-f2f-diary-actions > .chat-msg-quick")?.remove();
  const bar = document.createElement("div");
  bar.className = "chat-msg-quick";
  const ed = document.createElement("button");
  ed.type = "button";
  ed.className = "chat-msg-quick-btn";
  ed.dataset.chatMsgQuick = "edit";
  ed.setAttribute("aria-label", "编辑");
  ed.innerHTML = "<i class=\"ph ph-pencil-simple\" aria-hidden=\"true\"></i>";
  const del = document.createElement("button");
  del.type = "button";
  del.className = "chat-msg-quick-btn chat-msg-quick-btn--del";
  del.dataset.chatMsgQuick = "delete";
  del.setAttribute("aria-label", "删除");
  del.innerHTML = "<i class=\"ph ph-trash\" aria-hidden=\"true\"></i>";
  bar.append(ed, del);
  const actionsHost = stack.querySelector(":scope > .chat-f2f-diary-meta > .chat-f2f-diary-actions");
  if (actionsHost instanceof HTMLElement) actionsHost.appendChild(bar);
  else stack.insertBefore(bar, stack.firstChild);
}

/**
 * @param {number|string} msgIdx
 * @param {number} segIdx
 * @param {number | null | undefined} sheetQuoteDomSeg
 * @param {number | null | undefined} sheetBodyDomSeg
 */
function performChatBubbleEditLoadComposer(msgIdx, segIdx, sheetQuoteDomSeg, sheetBodyDomSeg) {
  const log = readChatLog();
  const msgIdxN = Math.floor(Number(msgIdx));
  if (!Number.isFinite(msgIdxN) || msgIdxN < 0 || msgIdxN >= log.length) {
    showToast("消息已变化，请重试");
    return;
  }
  const msg = log[msgIdxN];
  if (!(msg.role === "user" || msg.role === "assistant")) {
    showToast("只能编辑双方文字气泡");
    return;
  }
  clearChatComposerResendPlacement();
  chatComposerPatchMsgIdx = msgIdxN;
  chatComposerPatchSegIdx = Math.max(0, Math.floor(Number(segIdx)) || 0);
  chatComposerPatchRole = msg.role;
  chatComposerPatchQuoteDomSeg =
    sheetQuoteDomSeg != null && Number.isFinite(sheetQuoteDomSeg) ? sheetQuoteDomSeg : -1;
  chatComposerPatchBodyDomSeg =
    sheetBodyDomSeg != null && Number.isFinite(sheetBodyDomSeg) ? sheetBodyDomSeg : -1;
  chatComposerPatchImageDesc =
    !isChatNarrationSheetSeg(segIdx) &&
    isChatBubbleActionSheetImageDomSeg(msg, chatComposerPatchSegIdx, null);
  const text = isChatNarrationSheetSeg(segIdx)
    ? String(msg.narration || "").trim() || " "
    : chatComposerPatchImageDesc
      ? getChatImageGenSceneBlockForEdit(msg) || " "
      : getChatBubbleActionSheetEditableSegmentText(
          String(msg.content ?? ""),
          msg.role,
          chatComposerPatchSegIdx,
          msg,
          readChatLog(),
          sheetQuoteDomSeg,
          sheetBodyDomSeg
        );
  const ta = document.getElementById("chat-input");
  const sq = readMessageQuoteRef(msg);
  const editingStructuredQuoteSnap =
    sq &&
    msg.quote &&
    typeof msg.quote === "object" &&
    ((sheetQuoteDomSeg != null &&
      sheetBodyDomSeg != null &&
      chatComposerPatchSegIdx === sheetQuoteDomSeg) ||
      ((sheetQuoteDomSeg == null || sheetBodyDomSeg == null) && chatComposerPatchSegIdx === 0));
  if (isChatNarrationSheetSeg(segIdx) || chatComposerPatchImageDesc) {
    clearChatComposerQuote();
  } else if (sq && msg.quote && typeof msg.quote === "object") {
    chatComposerQuotePlain = "";
    const qo = /** @type {Record<string, unknown>} */ (msg.quote);
    chatComposerQuoteStruct = {
      refAt: Number(qo.refAt),
      refSeg: Math.max(0, Math.floor(Number(qo.refSeg)) || 0),
      text: editingStructuredQuoteSnap
        ? String(text || "").trim().slice(0, 4000)
        : String(qo.text || "").trim().slice(0, 4000),
      role: String(qo.role || "")
    };
    syncChatComposerQuoteUI();
  } else {
    clearChatComposerQuote();
  }
  if (ta) {
    ta.value = text;
    ta.focus();
    try {
      ta.setSelectionRange(ta.value.length, ta.value.length);
    } catch {
      /* ignore */
    }
  }
  showToast(
    isChatNarrationSheetSeg(segIdx)
      ? "已载入旁白，发送后仅替换旁白"
      : chatComposerPatchImageDesc
        ? "已载入生图提示词，发送后更新并重绘本条配图"
        : "已载入该条气泡，发送后仅替换这一段"
  );
}

/** 当面晤面：整条载入输入框，发送后替换该条 content（||| / 结构化引用正文口径与分段编辑一致；仅当面上下文调用） */
function performChatBubbleEditLoadComposerWholeRowOffline(msgIdx) {
  const log = readChatLog();
  const msgIdxN = Math.floor(Number(msgIdx));
  if (!Number.isFinite(msgIdxN) || msgIdxN < 0 || msgIdxN >= log.length) {
    showToast("消息已变化，请重试");
    return;
  }
  const msg = log[msgIdxN];
  if (!(msg.role === "user" || msg.role === "assistant")) {
    showToast("只能编辑双方文字气泡");
    return;
  }
  clearChatComposerResendPlacement();
  chatComposerPatchMsgIdx = msgIdxN;
  chatComposerPatchSegIdx = -1;
  chatComposerPatchWholeRow = true;
  chatComposerPatchRole = msg.role;
  chatComposerPatchQuoteDomSeg = -1;
  chatComposerPatchBodyDomSeg = -1;

  const sq = readMessageQuoteRef(msg);
  if (sq && msg.quote && typeof msg.quote === "object") {
    chatComposerQuotePlain = "";
    const qo = /** @type {Record<string, unknown>} */ (msg.quote);
    chatComposerQuoteStruct = {
      refAt: Number(qo.refAt),
      refSeg: Math.max(0, Math.floor(Number(qo.refSeg)) || 0),
      text: String(qo.text || "").trim().slice(0, 4000),
      role: String(qo.role || "")
    };
    syncChatComposerQuoteUI();
  } else {
    clearChatComposerQuote();
  }

  const text = bubbleRoleMessageToEditableTextForMsgSurface(String(msg.content ?? ""), msg.role, msg);
  const ta = document.getElementById("chat-input");
  if (ta) {
    ta.value = text;
    ta.focus();
    try {
      ta.setSelectionRange(ta.value.length, ta.value.length);
    } catch {
      /* ignore */
    }
  }
  showToast("已载入整条消息，发送后替换该条");
}

/**
 * @param {number|string} msgIdx
 * @param {number} segIdx
 * @param {{ isStickerBubble?: boolean, stickerUrl?: string }} [opts]
 * @returns {boolean}
 */
function performChatBubbleDeleteSegment(msgIdx, segIdx, opts) {
  const i = Math.floor(Number(msgIdx));
  const si = Math.max(0, Math.floor(Number(segIdx)) || 0);
  if (!removeChatBubbleSegmentFromLog(i, si, opts)) return false;
  refreshChatAfterLogMutation();
  return true;
}

/** @param {number} msgIdx @param {number} segIdx */
function chatMsgMultiSelectKey(msgIdx, segIdx) {
  return `${Math.floor(msgIdx)}:${Math.floor(segIdx)}`;
}

/** @param {unknown} raw @returns {{ msgIdx: number, segIdx: number } | null} */
function parseChatMsgMultiSelectKey(raw) {
  const s = String(raw ?? "").trim();
  if (!s) return null;
  const i = s.indexOf(":");
  if (i < 0) {
    const msgIdx = Math.floor(Number(s));
    if (!Number.isFinite(msgIdx) || msgIdx < 0) return null;
    return { msgIdx, segIdx: 0 };
  }
  const msgIdx = Math.floor(Number(s.slice(0, i)));
  const segIdx = Math.floor(Number(s.slice(i + 1)));
  if (!Number.isFinite(msgIdx) || msgIdx < 0 || !Number.isFinite(segIdx) || segIdx < 0) return null;
  return { msgIdx, segIdx };
}

function injectChatMsgMultiSelectIntoStack(wrap, stack, msgIdx) {
  wrap.classList.add("chat-msg--multi");
  const mi = Math.floor(msgIdx);
  const markHost = (node, segIdx) => {
    const key = chatMsgMultiSelectKey(mi, segIdx);
    const on = chatMsgMultiSelectSet.has(key);
    node.classList.add("chat-msg-multi-host");
    node.dataset.chatMsgMultiKey = key;
    node.setAttribute("role", "checkbox");
    node.setAttribute("aria-checked", on ? "true" : "false");
    node.classList.toggle("is-selected", on);
    if (!node.hasAttribute("tabindex")) node.tabIndex = 0;
  };

  const nodes = [...stack.children];
  for (const node of nodes) {
    if (!(node instanceof HTMLElement)) continue;
    if (node.classList.contains("chat-voice-reveal")) continue;

    if (node.matches(".chat-msg-bubble.chat-msg-bubble--composer-quote")) {
      node.classList.add("chat-msg-multi-host--quote");
      const qEl = node.querySelector(".chat-msg-bubble-quote");
      const bodyEl = node.querySelector(
        ".chat-msg-bubble-body:not(.chat-msg-bubble-body--translation)"
      );
      let qSeg = 0;
      let bSeg = 1;
      if (qEl?.dataset.chatBubbleSeg != null && qEl.dataset.chatBubbleSeg !== "") {
        const n = Number(qEl.dataset.chatBubbleSeg);
        if (Number.isFinite(n)) qSeg = Math.max(0, Math.floor(n));
      }
      if (bodyEl?.dataset.chatBubbleSeg != null && bodyEl.dataset.chatBubbleSeg !== "") {
        const n = Number(bodyEl.dataset.chatBubbleSeg);
        if (Number.isFinite(n)) bSeg = Math.max(0, Math.floor(n));
      }
      node.dataset.chatMsgMultiQuoteSeg = String(qSeg);
      node.dataset.chatMsgMultiBodySeg = String(bSeg);
      const qKey = chatMsgMultiSelectKey(mi, qSeg);
      const bKey = chatMsgMultiSelectKey(mi, bSeg);
      const anyOn = chatMsgMultiSelectSet.has(qKey) || chatMsgMultiSelectSet.has(bKey);
      node.classList.add("chat-msg-multi-host");
      node.dataset.chatMsgMultiKey = chatMsgMultiSelectSet.has(bKey)
        ? bKey
        : chatMsgMultiSelectSet.has(qKey)
          ? qKey
          : bKey;
      node.setAttribute("role", "checkbox");
      node.setAttribute("aria-checked", anyOn ? "true" : "false");
      node.classList.toggle("is-selected", anyOn);
      if (!node.hasAttribute("tabindex")) node.tabIndex = 0;
      continue;
    }

    let segIdx = 0;
    if (node.dataset.chatBubbleSeg != null && node.dataset.chatBubbleSeg !== "") {
      const n = Number(node.dataset.chatBubbleSeg);
      segIdx = Number.isFinite(n) ? Math.max(0, Math.floor(n)) : 0;
    }
    markHost(node, segIdx);
  }
}

/** @param {HTMLElement} narrEl @param {number} msgIdx */
function injectChatMsgMultiSelectIntoNarration(narrEl, msgIdx) {
  const mi = Math.floor(msgIdx);
  const key = chatMsgMultiSelectKey(mi, CHAT_NARRATION_SHEET_SEG);
  const on = chatMsgMultiSelectSet.has(key);
  narrEl.classList.add("chat-msg-multi-host", "chat-msg-multi-host--narration");
  narrEl.dataset.chatMsgMultiKey = key;
  narrEl.setAttribute("role", "checkbox");
  narrEl.setAttribute("aria-checked", on ? "true" : "false");
  narrEl.classList.toggle("is-selected", on);
  if (!narrEl.hasAttribute("tabindex")) narrEl.tabIndex = 0;
}

/** @param {HTMLElement} host @param {number} [clientY] */
function resolveChatMsgMultiSelectKeyForHost(host, clientY) {
  let key = String(host.dataset.chatMsgMultiKey || "").trim();
  if (!host.classList.contains("chat-msg-multi-host--quote")) return key;
  const parsed = parseChatMsgMultiSelectKey(key);
  if (!parsed) return key;
  const qSeg = Number(host.dataset.chatMsgMultiQuoteSeg);
  const bSeg = Number(host.dataset.chatMsgMultiBodySeg);
  const qEl = host.querySelector(".chat-msg-bubble-quote");
  if (
    qEl instanceof HTMLElement &&
    Number.isFinite(clientY) &&
    Number.isFinite(qSeg) &&
    Number.isFinite(bSeg) &&
    qSeg !== bSeg
  ) {
    const qRect = qEl.getBoundingClientRect();
    if (clientY <= qRect.bottom + 6) return chatMsgMultiSelectKey(parsed.msgIdx, qSeg);
    return chatMsgMultiSelectKey(parsed.msgIdx, bSeg);
  }
  if (Number.isFinite(bSeg)) return chatMsgMultiSelectKey(parsed.msgIdx, bSeg);
  return key;
}

/** @param {HTMLElement} host @param {number} [clientY] */
function toggleChatMsgMultiSelectHost(host, clientY) {
  const key = resolveChatMsgMultiSelectKeyForHost(host, clientY);
  if (!key) return;
  const on = chatMsgMultiSelectSet.has(key);
  if (on) {
    chatMsgMultiSelectSet.delete(key);
  } else {
    chatMsgMultiSelectSet.add(key);
  }
  if (host.classList.contains("chat-msg-multi-host--quote")) {
    const parsed = parseChatMsgMultiSelectKey(key);
    if (parsed) {
      const qSeg = Number(host.dataset.chatMsgMultiQuoteSeg);
      const bSeg = Number(host.dataset.chatMsgMultiBodySeg);
      const qKey = Number.isFinite(qSeg) ? chatMsgMultiSelectKey(parsed.msgIdx, qSeg) : "";
      const bKey = Number.isFinite(bSeg) ? chatMsgMultiSelectKey(parsed.msgIdx, bSeg) : "";
      const anyOn =
        (qKey && chatMsgMultiSelectSet.has(qKey)) || (bKey && chatMsgMultiSelectSet.has(bKey));
      host.classList.toggle("is-selected", Boolean(anyOn));
      host.setAttribute("aria-checked", anyOn ? "true" : "false");
      host.dataset.chatMsgMultiKey = key;
      syncChatMsgMultiBarUi();
      return;
    }
  }
  host.classList.toggle("is-selected", !on);
  host.setAttribute("aria-checked", !on ? "true" : "false");
  host.dataset.chatMsgMultiKey = key;
  syncChatMsgMultiBarUi();
}

/** 收集消息 inner 内所有气泡栈（经典：inner 直子；玻璃多段：.chat-msg-glass-line 内） */
function collectChatMsgBubbleStacksInInner(inner) {
  /** @type {HTMLElement[]} */
  const stacks = [];
  if (!(inner instanceof HTMLElement)) return stacks;
  for (const ch of inner.children) {
    if (!(ch instanceof HTMLElement)) continue;
    if (ch.classList.contains("chat-msg-bubble-stack")) {
      stacks.push(ch);
      continue;
    }
    if (ch.classList.contains("chat-msg-glass-line")) {
      for (const gch of ch.children) {
        if (gch instanceof HTMLElement && gch.classList.contains("chat-msg-bubble-stack")) {
          stacks.push(gch);
        }
      }
    }
  }
  return stacks;
}

/** @param {HTMLElement} root */
function injectChatMsgMultiSelectLanesInMessagesRoot(root) {
  if (!chatMsgMultiSelectMode || !root) return;
  const log = readChatLog();
  const wraps = root.querySelectorAll(".chat-msg--user, .chat-msg--assistant");
  for (const wrap of wraps) {
    if (!(wrap instanceof HTMLElement)) continue;
    const idx = Number(wrap.dataset.chatMsgIdx);
    if (!Number.isFinite(idx) || idx < 0 || idx >= log.length) continue;
    const m = log[idx];
    if (!m || (m.role !== "user" && m.role !== "assistant")) continue;
    let inner = null;
    for (const ch of wrap.children) {
      if (ch instanceof HTMLElement && ch.classList.contains("chat-msg-inner")) {
        inner = ch;
        break;
      }
    }
    const stacks = collectChatMsgBubbleStacksInInner(inner);
    if (!inner || !stacks.length) continue;
    for (const stack of stacks) {
      injectChatMsgMultiSelectIntoStack(wrap, stack, idx);
    }
  }
  for (const narrEl of root.querySelectorAll(".chat-msg-narration")) {
    if (!(narrEl instanceof HTMLElement)) continue;
    const idx = Number(narrEl.dataset.chatMsgIdx);
    if (!Number.isFinite(idx) || idx < 0 || idx >= log.length) continue;
    const m = log[idx];
    if (!m || m.role !== "assistant") continue;
    if (!String(m.narration || "").trim()) continue;
    injectChatMsgMultiSelectIntoNarration(narrEl, idx);
  }
}

/** 多选模式：主聊与线下页共用 `#chat-messages`，需在可见壳上同步 class。 */
function setChatMsgMultiHostScreenClass(on) {
  document.getElementById("chat-screen")?.classList.toggle("is-msg-multi", on);
  document.getElementById("chat-offline-screen")?.classList.toggle("is-msg-multi", on);
}

/** @param {{ skipRender?: boolean }} [opts] */
function clearChatMsgMultiSelectMode(opts) {
  chatMsgMultiSelectMode = false;
  chatMsgMultiSelectSet.clear();
  const bar = document.getElementById("chat-msg-multi-bar");
  if (bar) {
    bar.classList.remove("is-open");
    window.setTimeout(() => {
      if (!chatMsgMultiSelectMode && bar) {
        bar.hidden = true;
        bar.setAttribute("aria-hidden", "true");
      }
    }, 360);
  }
  setChatMsgMultiHostScreenClass(false);
  closeChatMultiSummarySheet();
  closeChatMultiForwardSheet();
  stripAllChatMsgMultiSelectArtifactsFromRoot();
  if (!opts?.skipRender) {
    chatSuppressNextChatMessageAnimations = true;
    preserveChatMessagesScrollForNextRender();
    renderChatMessages();
  }
}

function syncChatMsgMultiBarUi() {
  const n = chatMsgMultiSelectSet.size;
  const el = document.getElementById("chat-msg-multi-count");
  if (el) el.textContent = n > 0 ? String(n) : "0";
  const del = document.getElementById("chat-msg-multi-delete");
  const sum = document.getElementById("chat-msg-multi-summarize");
  const fwd = document.getElementById("chat-msg-multi-forward");
  if (del) del.disabled = n === 0;
  if (sum) sum.disabled = n === 0;
  if (fwd) fwd.disabled = n === 0;
}

function enterChatMsgMultiSelectMode(initialIdx, initialSegIdx) {
  const n = Math.floor(Number(initialIdx));
  const s0 = initialSegIdx === undefined || initialSegIdx === null ? 0 : Math.floor(Number(initialSegIdx));
  chatMsgMultiSelectMode = true;
  chatMsgMultiSelectSet.clear();
  if (Number.isFinite(n) && n >= 0) {
    const s = Number.isFinite(s0) && s0 >= 0 ? s0 : 0;
    chatMsgMultiSelectSet.add(chatMsgMultiSelectKey(n, s));
  }
  const bar = document.getElementById("chat-msg-multi-bar");
  if (bar) {
    bar.hidden = false;
    bar.setAttribute("aria-hidden", "false");
    window.requestAnimationFrame(() => bar.classList.add("is-open"));
  }
  setChatMsgMultiHostScreenClass(true);
  closeChatBubbleActionSheet();
  closeChatMultiSummarySheet();
  closeChatMultiForwardSheet();
  syncChatMsgMultiBarUi();
  chatSuppressNextChatMessageAnimations = true;
  preserveChatMessagesScrollForNextRender();
  renderChatMessages();
}

function isChatMultiSummarySheetOpen() {
  const root = document.getElementById("chat-multi-summary-sheet");
  return !!(root && !root.hidden);
}

function closeChatMultiSummarySheet() {
  const root = document.getElementById("chat-multi-summary-sheet");
  if (!root) return;
  chatMultiSummaryExclusiveEndLogIdx = NaN;
  chatMultiSummaryInclusiveStartLogIdx = NaN;
  root.classList.remove("is-open");
  root.setAttribute("aria-hidden", "true");
  window.setTimeout(() => {
    root.hidden = true;
  }, 180);
}

function openChatMultiSummarySheet(prefill) {
  const root = document.getElementById("chat-multi-summary-sheet");
  const ta = document.getElementById("chat-multi-summary-ta");
  if (!root || !(ta instanceof HTMLTextAreaElement)) return;
  ta.value = String(prefill ?? "");
  root.hidden = false;
  root.setAttribute("aria-hidden", "false");
  window.requestAnimationFrame(() => {
    root.classList.add("is-open");
    window.setTimeout(() => ta.focus(), 80);
  });
}

/** @param {{ msgIdx: number, segIdx: number }[]} sortedPairsAsc */
function buildChatMultiSelectPlainTranscriptWithCallEndsInSpan(sortedPairsAsc) {
  if (!sortedPairsAsc.length) return "";
  const log = readChatLog();
  const minI = sortedPairsAsc[0].msgIdx;
  const maxI = sortedPairsAsc[sortedPairsAsc.length - 1].msgIdx;
  const pick = new Set(sortedPairsAsc.map((k) => `${k.msgIdx}:${k.segIdx}`));
  return buildMemoSummaryTranscriptBodyForLogSpan(log, minI, maxI, { segmentPick: pick });
}

/** @returns {{ msgIdx: number, segIdx: number }[]} */
function getChatMultiSelectKeysSortedAscForSummary() {
  const log = readChatLog();
  /** @type {{ msgIdx: number, segIdx: number }[]} */
  const acc = [];
  for (const raw of chatMsgMultiSelectSet) {
    const p = parseChatMsgMultiSelectKey(raw);
    if (!p) continue;
    const m = log[p.msgIdx];
    if (!m || (m.role !== "user" && m.role !== "assistant")) continue;
    if (isChatNarrationSheetSeg(p.segIdx)) {
      if (m.role === "assistant" && String(m.narration || "").trim()) {
        acc.push({ msgIdx: p.msgIdx, segIdx: p.segIdx });
      }
      continue;
    }
    const sheetN = countChatBubbleActionSheetSegments(String(m.content ?? ""), String(m.role), m);
    if (sheetN <= 0 || p.segIdx < 0 || p.segIdx >= sheetN) continue;
    acc.push({ msgIdx: p.msgIdx, segIdx: p.segIdx });
  }
  acc.sort((a, b) => (a.msgIdx !== b.msgIdx ? a.msgIdx - b.msgIdx : a.segIdx - b.segIdx));
  /** @type {{ msgIdx: number, segIdx: number }[]} */
  const out = [];
  let prev = "";
  for (const p of acc) {
    const k = chatMsgMultiSelectKey(p.msgIdx, p.segIdx);
    if (k === prev) continue;
    prev = k;
    out.push(p);
  }
  return out;
}

/**
 * @param {string} body
 * @param {{ userLead?: string, includeAltPersonaHint?: boolean }} [opts]
 * @returns {Promise<string>}
 */
async function aiChatSummarizeTranscriptBodyForMemo(body, opts) {
  const { blob, data } = await requestMemoTranscriptSummary(body, opts);
  if (!blob) throw new Error(explainModelEmptyReply(data, blob));
  return blob.slice(0, CHAT_MEMO_SUMMARY_EACH);
}

async function runChatMultiSelectSummarizeToMemoSheet() {
  if (chatMultiSummaryInFlight) return;
  const keysAsc = getChatMultiSelectKeysSortedAscForSummary();
  if (!keysAsc.length) {
    showToast("请至少选择一段双方文字气泡");
    return;
  }
  if (!window.RP_AI) {
    showToast("AI 模块未加载");
    return;
  }
  const body = buildChatMultiSelectPlainTranscriptWithCallEndsInSpan(keysAsc);
  if (!body.trim()) {
    showToast("选中消息没有可总结的正文");
    return;
  }
  chatMultiSummaryInFlight = true;
  showToast("正在生成摘要…");
  try {
    const blob = await aiChatSummarizeTranscriptBodyForMemo(body);
    let maxI = -1;
    for (const k of keysAsc) maxI = Math.max(maxI, k.msgIdx);
    let minI = keysAsc.length ? keysAsc[0].msgIdx : -1;
    for (const k of keysAsc) minI = Math.min(minI, k.msgIdx);
    chatMultiSummaryInclusiveStartLogIdx = minI >= 0 ? minI + 1 : NaN;
    chatMultiSummaryExclusiveEndLogIdx = maxI + 1;
    openChatMultiSummarySheet(blob);
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    showToast(`总结失败：${msg.slice(0, 160)}`);
  } finally {
    chatMultiSummaryInFlight = false;
  }
}

function closeChatMultiForwardSheet() {
  const root = document.getElementById("chat-multi-forward-sheet");
  if (!root) return;
  chatMultiForwardPendingPayload = null;
  chatMultiForwardTargetSet.clear();
  root.classList.remove("is-open");
  root.setAttribute("aria-hidden", "true");
  window.setTimeout(() => {
    root.hidden = true;
  }, 180);
}

function syncChatMultiForwardConfirmUi() {
  const btn = document.getElementById("chat-multi-forward-confirm");
  const n = chatMultiForwardTargetSet.size;
  if (btn) {
    btn.disabled = n === 0;
    btn.textContent = n > 0 ? `转发到 ${n} 个密谈` : "选择密谈";
  }
}

function renderChatMultiForwardThreadList() {
  const list = document.getElementById("chat-multi-forward-list");
  if (!list) return;
  list.replaceChildren();
  const th = readActiveThread();
  const maskId = String(getActiveMaskIdForInbox() || "").trim();
  const threads = listMitalkForwardTargetThreads(maskId, th?.id);
  if (!threads.length) {
    const empty = document.createElement("p");
    empty.className = "chat-multi-forward-empty";
    empty.textContent = "当前面具下没有其他密谈或群聊";
    list.appendChild(empty);
    syncChatMultiForwardConfirmUi();
    return;
  }
  for (const t of threads) {
    const tid = String(t.id || "").trim();
    if (!tid) continue;
    const isGroup = isChatThreadGroupForUi(t);
    const label = threadListDisplayName(t) || (isGroup ? "群聊" : "密谈");
    const row = document.createElement("label");
    row.className = "chat-multi-forward-row";
    const cb = document.createElement("input");
    cb.type = "checkbox";
    cb.className = "chat-multi-forward-cb";
    cb.value = tid;
    cb.checked = chatMultiForwardTargetSet.has(tid);
    cb.addEventListener("change", () => {
      if (cb.checked) chatMultiForwardTargetSet.add(tid);
      else chatMultiForwardTargetSet.delete(tid);
      syncChatMultiForwardConfirmUi();
    });
    const meta = document.createElement("span");
    meta.className = "chat-multi-forward-meta";
    const title = document.createElement("span");
    title.className = "chat-multi-forward-title";
    title.textContent = label;
    const tag = document.createElement("span");
    tag.className = "chat-multi-forward-tag";
    tag.textContent = isGroup ? "群聊" : "密谈";
    meta.append(title, tag);
    row.append(cb, meta);
    list.appendChild(row);
  }
  syncChatMultiForwardConfirmUi();
}

/** @param {{ sourceThreadId?: string, sourceTitle?: string, chatlogTitle?: string, chatlogEntries?: unknown }} payload */
function openChatMultiForwardSheet(payload) {
  const root = document.getElementById("chat-multi-forward-sheet");
  if (!root) return;
  chatMultiForwardPendingPayload = payload;
  chatMultiForwardTargetSet.clear();
  renderChatMultiForwardThreadList();
  root.hidden = false;
  root.setAttribute("aria-hidden", "false");
  window.requestAnimationFrame(() => root.classList.add("is-open"));
}

function runChatMultiSelectForwardSheet() {
  const keysAsc = getChatMultiSelectKeysSortedAscForSummary();
  if (!keysAsc.length) {
    showToast("请至少选择一段文字气泡");
    return;
  }
  const th = readActiveThread();
  if (!th) {
    showToast("没有当前密谈");
    return;
  }
  const log = readChatLog();
  const entries = buildChatMultiSelectChatlogEntries(keysAsc, log, th);
  if (!entries.length) {
    showToast("选中内容没有可转发的文字");
    return;
  }
  const fwdCtx = buildMitalkForwardContextForPayload(th, getActiveMaskIdForInbox());
  openChatMultiForwardSheet({
    sourceThreadId: String(th.id || "").trim(),
    sourceTitle: fwdCtx.sourceTitle,
    sourceKind: fwdCtx.sourceKind,
    participantsSummary: fwdCtx.participantsSummary,
    peerCharName: fwdCtx.peerCharName || "",
    peerLabel: fwdCtx.peerLabel || "",
    chatlogTitle: fwdCtx.chatlogTitle,
    chatlogEntries: entries
  });
}

function confirmChatMultiForwardFromSheet() {
  const payload = chatMultiForwardPendingPayload;
  const targets = [...chatMultiForwardTargetSet];
  if (!payload || !targets.length) {
    showToast("请选择至少一个密谈或群聊");
    return;
  }
  const maskId = String(getActiveMaskIdForInbox() || "").trim();
  if (!maskId) {
    showToast("无法转发");
    return;
  }
  let okCount = 0;
  for (const tid of targets) {
    if (appendMitalkChatForwardToThread(maskId, tid, payload)) okCount++;
  }
  closeChatMultiForwardSheet();
  clearChatMsgMultiSelectMode({ skipRender: true });
  refreshChatAfterLogMutation();
  if (okCount > 0) showToast(`已转发到 ${okCount} 个密谈`);
  else showToast("转发失败");
}

function persistChatMultiSummaryFromSheet() {
  const ta = document.getElementById("chat-multi-summary-ta");
  if (!(ta instanceof HTMLTextAreaElement)) return;
  const exclusiveCap = chatMultiSummaryExclusiveEndLogIdx;
  const inclusiveStartCap = chatMultiSummaryInclusiveStartLogIdx;
  const nx = Number.isFinite(exclusiveCap) && exclusiveCap >= 0 ? Math.floor(exclusiveCap) : NaN;
  const sx = Number.isFinite(inclusiveStartCap) && inclusiveStartCap >= 1 ? Math.floor(inclusiveStartCap) : NaN;
  /** @type {Record<string, unknown>} */
  const rawRow = {
    id:
      typeof crypto !== "undefined" && crypto.randomUUID
        ? crypto.randomUUID()
        : `mem_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 9)}`,
    at: Date.now(),
    text: ta.value
  };
  if (Number.isFinite(nx)) rawRow.afterChatLogExclusiveEnd = nx;
  if (Number.isFinite(sx)) rawRow.afterChatLogInclusiveStart = sx;
  const row = normalizeCharThreadMemorySummaryEntry(rawRow);
  if (!row) {
    showToast("摘要内容不能为空");
    return;
  }
  if (
    !patchActiveThread((t) => {
      const cur = normalizeCharThreadMemorySummariesArray(t.charThreadMemorySummaries);
      cur.push(row);
      t.charThreadMemorySummaries = normalizeCharThreadMemorySummariesArray(cur);
      if (Number.isFinite(exclusiveCap) && exclusiveCap >= 0) {
        bumpThreadMemoManualExclusiveEndLogIdx(t, Math.floor(exclusiveCap));
      }
    })
  ) {
    showToast("无法保存");
    return;
  }
  closeChatMultiSummarySheet();
  scheduleMemoAutoMergeChain(String(readActiveThread()?.id || ""));
  refreshChatMemoStatusPanel();
  syncChatThreadDetailPanelPlaceholders();
  if (isChatMemoScreenOpen()) {
    renderChatMemoTimeline();
  }
  showToast("已写入记忆摘要");
  clearChatMsgMultiSelectMode();
}

function refreshChatAfterLogMutation() {
  chatSuppressNextChatMessageAnimations = true;
  preserveChatMessagesScrollForNextRender();
  renderChatMessages();
  updateChatContextTokenLabel();
  renderChatThreadList();
}

async function copyTextToClipboard(text) {
  const t = String(text ?? "");
  if (!t.trim()) {
    showToast("没有可复制的内容");
    return;
  }
  try {
    await navigator.clipboard.writeText(t);
    showToast("已复制");
  } catch {
    const ta = document.createElement("textarea");
    ta.value = t;
    ta.setAttribute("readonly", "");
    ta.style.position = "fixed";
    ta.style.left = "-9999px";
    document.body.appendChild(ta);
    ta.select();
    try {
      document.execCommand("copy");
      showToast("已复制");
    } catch {
      showToast("无法写入剪贴板");
    }
    ta.remove();
  }
}

function getChatComposerDraftBodyText() {
  return (document.getElementById("chat-input")?.value ?? "").trim();
}

function getChatComposerDraftCombinedForTokens() {
  const text = getChatComposerDraftBodyText();
  const st = chatComposerQuoteStruct;
  if (st && String(st.text || "").trim()) {
    const inner = String(st.text || "").trim();
    if (!text) return `「${inner}」`;
    return `「${inner}」\n\n${text}`;
  }
  const q = String(chatComposerQuotePlain || "").trim();
  if (!q) return text;
  if (!text) return `「${q}」`;
  return `「${q}」\n\n${text}`;
}

function syncChatComposerQuoteUI() {
  const row = document.getElementById("chat-input-quote");
  const body = document.getElementById("chat-input-quote-body");
  if (!row || !body) return;
  if (chatComposerPatchMsgIdx >= 0 && chatComposerQuoteStruct) {
    body.textContent = "";
    row.hidden = true;
    row.style.display = "none";
    return;
  }
  const st = chatComposerQuoteStruct;
  const disp =
    st && String(st.text || "").trim()
      ? String(st.text || "").trim()
      : String(chatComposerQuotePlain || "").trim();
  if (!disp) {
    body.textContent = "";
    row.hidden = true;
    row.style.display = "none";
    return;
  }
  const who = st
    ? resolveQuoteSourceSpeakerLabel(
        {
          refAt: st.refAt,
          refSeg: st.refSeg,
          text: st.text,
          role: st.role,
          refSpeakerCharId: st.refSpeakerCharId
        },
        readChatLog(),
        readActiveThread(),
        readUserMask()
      )
    : "";
  body.textContent = who ? `${who}：${disp}` : disp;
  row.hidden = false;
  row.style.display = "";
}

