/**
 * 长按「引用」：写入结构化引用元数据，正文仅来自输入框（发送时写入 msg.quote）。
 * @param {unknown[]} log
 * @param {number} msgIdx
 * @param {number} segIdx
 * @param {number | null} [sheetQuoteDomSeg]
 * @param {number | null} [sheetBodyDomSeg]
 */
function insertStructuredQuoteFromBubble(log, msgIdx, segIdx, sheetQuoteDomSeg, sheetBodyDomSeg) {
  const logArr = Array.isArray(log) ? log : [];
  if (!Number.isFinite(msgIdx) || msgIdx < 0 || msgIdx >= logArr.length) return;
  const msg = logArr[msgIdx];
  if (!msg || typeof msg !== "object") return;
  const at = Number(/** @type {{ at?: unknown }} */ (msg).at);
  if (!Number.isFinite(at)) return;
  const role = String(/** @type {{ role?: unknown }} */ (msg).role || "");
  const si = Math.max(0, Math.floor(Number(segIdx)) || 0);
  if (isChatBubbleActionSheetImageDomSeg(msg, si, null)) {
    chatComposerQuotePlain = "";
    chatComposerQuoteStruct = {
      refAt: at,
      refSeg: si,
      text: "图片",
      role
    };
    syncChatComposerQuoteUI();
    const taImg = document.getElementById("chat-input");
    if (taImg) {
      taImg.focus();
      try {
        taImg.setSelectionRange(taImg.value.length, taImg.value.length);
      } catch {
        /* ignore */
      }
    }
    updateChatContextTokenLabel();
    return;
  }
  const pair = chatMessageQuoteDomSegPair(msg);
  const qDom =
    sheetQuoteDomSeg != null && Number.isFinite(Number(sheetQuoteDomSeg))
      ? Number(sheetQuoteDomSeg)
      : pair.quoteDom;
  const bDom =
    sheetBodyDomSeg != null && Number.isFinite(Number(sheetBodyDomSeg))
      ? Number(sheetBodyDomSeg)
      : pair.bodyDom;
  const plain = getChatMessageSegmentPlain(
    String(/** @type {{ content?: unknown }} */ (msg).content ?? ""),
    segIdx,
    role,
    msg,
    logArr,
    qDom,
    bDom
  );
  const snap0 = stripJapaneseQuoteWrapper(plain).trim() || String(plain).trim();
  const cap = 320;
  const text = snap0.length > cap ? `${snap0.slice(0, cap)}…` : snap0;
  if (!text) return;
  const th = readActiveThread();
  let refSpeakerCharId = "";
  if (role === "assistant") {
    refSpeakerCharId = resolveQuoteSpeakerCharIdFromRefMessage(msg, th);
  }
  chatComposerQuotePlain = "";
  chatComposerQuoteStruct = {
    refAt: at,
    refSeg: si,
    text,
    role,
    ...(refSpeakerCharId ? { refSpeakerCharId } : {})
  };
  syncChatComposerQuoteUI();
  const ta = document.getElementById("chat-input");
  if (ta) {
    ta.focus();
    try {
      ta.setSelectionRange(ta.value.length, ta.value.length);
    } catch {
      /* ignore */
    }
  }
  updateChatContextTokenLabel();
}

/**
 * 从 DOM 气泡写入输入栏结构化引用（长按菜单「引用」与左滑引用共用）。
 * @param {HTMLElement} wrap
 * @param {Element} bubbleEl
 * @param {Element | null} [pointerTargetEl]
 * @returns {boolean}
 */
function quoteChatBubbleFromDom(wrap, bubbleEl, pointerTargetEl) {
  if (!(wrap instanceof HTMLElement) || wrap.dataset.chatMsgIdx == null) return false;
  if (wrap.classList.contains("chat-msg--call-ended-notice")) return false;
  const log = readChatLog();
  const msgIdx = Math.floor(Number(wrap.dataset.chatMsgIdx));
  if (!chatBubbleActionMsgIdxMatchesWrap(wrap, msgIdx, log)) return false;
  const segIdx = resolveBubbleSheetSegIdxFromTarget(
    wrap,
    bubbleEl instanceof Element ? bubbleEl : null,
    pointerTargetEl instanceof Element ? pointerTargetEl : null
  );
  const { quote: sheetQuoteDomSeg, body: sheetBodyDomSeg } =
    resolveQuoteBubbleDomSegPairFromWrap(wrap);
  insertStructuredQuoteFromBubble(log, msgIdx, segIdx, sheetQuoteDomSeg, sheetBodyDomSeg);
  showToast("已插入引用");
  return true;
}

function clearChatBubbleSwipeQuoteVisualFromAnchor(anchor) {
  if (!anchor) return;
  const bubble = anchor.bubble;
  if (bubble instanceof HTMLElement) {
    bubble.style.transform = "";
    bubble.style.transition = "";
  }
  if (anchor.wrap instanceof HTMLElement) {
    anchor.wrap.classList.remove("is-swipe-quote-active");
  }
}

function resetChatBubblePressState() {
  window.clearTimeout(chatBubbleLongPressTid);
  chatBubbleLongPressTid = 0;
  unbindChatBubblePressDocListeners();
  if (chatBubblePressAnchor) {
    clearChatBubbleSwipeQuoteVisualFromAnchor(chatBubblePressAnchor);
  }
  chatBubblePressAnchor = null;
}

function syncChatBubbleSwipeQuoteVisual(anchor, dx) {
  const bubble = anchor?.bubble;
  if (!(bubble instanceof HTMLElement)) return;
  const shift = Math.max(dx, -80);
  bubble.style.transition = "none";
  bubble.style.transform = shift < -8 ? `translateX(${shift * 0.38}px)` : "";
  anchor.wrap?.classList.toggle("is-swipe-quote-active", shift <= -20);
}

function bindChatBubblePressDocListeners() {
  if (chatBubblePressDocListenersBound) return;
  chatBubblePressDocListenersBound = true;
  document.addEventListener("pointermove", onChatBubblePressDocPointerMove, { passive: false });
  document.addEventListener("pointerup", onChatBubblePressDocPointerEnd);
  document.addEventListener("pointercancel", onChatBubblePressDocPointerEnd);
}

function unbindChatBubblePressDocListeners() {
  if (!chatBubblePressDocListenersBound) return;
  chatBubblePressDocListenersBound = false;
  document.removeEventListener("pointermove", onChatBubblePressDocPointerMove);
  document.removeEventListener("pointerup", onChatBubblePressDocPointerEnd);
  document.removeEventListener("pointercancel", onChatBubblePressDocPointerEnd);
}

/** @param {NonNullable<typeof chatBubblePressAnchor>} anchor @param {number} dx @param {number} dy */
function maybeLockChatBubbleSwipeQuote(anchor, dx, dy) {
  if (anchor.swipeQuoteLock) return;
  const adx = Math.abs(dx);
  const ady = Math.abs(dy);
  if (dx <= -CHAT_BUBBLE_SWIPE_QUOTE_LOCK_PX && adx > ady + 2) {
    anchor.swipeQuoteLock = true;
    window.clearTimeout(chatBubbleLongPressTid);
    chatBubbleLongPressTid = 0;
  }
}

function onChatBubblePressDocPointerMove(e) {
  const anchor = chatBubblePressAnchor;
  if (!anchor || e.pointerId !== anchor.pointerId) return;
  const dx = e.clientX - anchor.clientX;
  const dy = e.clientY - anchor.clientY;
  maybeLockChatBubbleSwipeQuote(anchor, dx, dy);
  const adx = Math.abs(dx);
  const ady = Math.abs(dy);
  if (anchor.swipeQuoteLock) {
    if (dx < 0) {
      e.preventDefault();
      syncChatBubbleSwipeQuoteVisual(anchor, dx);
    }
    return;
  }
  if (ady > CHAT_BUBBLE_MOVE_CANCEL_PX && ady > adx) {
    resetChatBubblePressState();
    return;
  }
  if (adx > CHAT_BUBBLE_MOVE_CANCEL_PX || ady > CHAT_BUBBLE_MOVE_CANCEL_PX) {
    window.clearTimeout(chatBubbleLongPressTid);
    chatBubbleLongPressTid = 0;
  }
  if (dx < 0 && adx > ady && ady <= CHAT_BUBBLE_SWIPE_QUOTE_MAX_VERTICAL_PX) {
    syncChatBubbleSwipeQuoteVisual(anchor, dx);
    return;
  }
  if (adx > CHAT_BUBBLE_MOVE_CANCEL_PX || ady > CHAT_BUBBLE_MOVE_CANCEL_PX) {
    clearChatBubbleSwipeQuoteVisualFromAnchor(anchor);
  }
}

function onChatBubblePressDocPointerEnd(e) {
  const anchor = chatBubblePressAnchor;
  window.clearTimeout(chatBubbleLongPressTid);
  chatBubbleLongPressTid = 0;
  unbindChatBubblePressDocListeners();
  if (anchor && (!e || e.pointerId === anchor.pointerId)) {
    const endX = Number.isFinite(e?.clientX) ? e.clientX : anchor.clientX;
    const endY = Number.isFinite(e?.clientY) ? e.clientY : anchor.clientY;
    const dx = endX - anchor.clientX;
    const dy = endY - anchor.clientY;
    const adx = Math.abs(dx);
    const ady = Math.abs(dy);
    const swipeOk =
      anchor.swipeQuoteLock ||
      (dx < 0 && adx >= CHAT_BUBBLE_SWIPE_QUOTE_PX && ady <= CHAT_BUBBLE_SWIPE_QUOTE_MAX_VERTICAL_PX && adx > ady);
    if (swipeOk && dx < 0 && adx >= CHAT_BUBBLE_SWIPE_QUOTE_PX) {
      quoteChatBubbleFromDom(anchor.wrap, anchor.bubble, anchor.pointerTarget);
      try {
        navigator.vibrate?.(12);
      } catch {
        /* ignore */
      }
    }
    clearChatBubbleSwipeQuoteVisualFromAnchor(anchor);
  }
  chatBubblePressAnchor = null;
}

