  const at = last?.at ?? (Number.isFinite(Number(thread.updatedAt)) ? Number(thread.updatedAt) : undefined);
  const timeStr = formatThreadListTime(at);

  const li = document.createElement("li");
  li.className = `chat-thread-li${listIndex % 2 === 0 ? " chat-thread-li--tilt-a" : " chat-thread-li--tilt-b"}`;
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = `chat-thread-card${isGroup ? " chat-thread-card--group" : ""}`;
  btn.dataset.threadId = thread.id;
  btn.dataset.charId = thread.charId || "";
  btn.dataset.threadKind = isGroup ? "group" : "dm";

  const deck = document.createElement("div");
  deck.className = "chat-thread-slab chat-slab";

  const spine = document.createElement("div");
  spine.className = "chat-slab-spine";
  spine.setAttribute("aria-hidden", "true");
  const spineNo = String(listIndex + 1).padStart(2, "0");
  spine.innerHTML = `<span class="chat-slab-spine-line"></span><span class="chat-slab-spine-idx">${spineNo}</span>`;

  const stack = document.createElement("div");
  stack.className = "chat-slab-stack";

  const top = document.createElement("div");
  top.className = "chat-thread-top";
  const stamp = document.createElement("span");
  stamp.className = "chat-thread-stamp";
  stamp.textContent = isGroup ? "群聊" : "单聊";
  const pill = document.createElement("span");
