function chatWorldBookBindDomPrefix(offline) {
  return offline ? "chat-offline-wb-bind" : "chat-detail-wb-bind";
}

function setChatDetailWorldBookBindPickerOpen(open, opts) {
  const offline = Boolean(opts && opts.offline);
  const prefix = chatWorldBookBindDomPrefix(offline);
  const picker = document.getElementById(`${prefix}-picker`);
  const toggle = document.getElementById(`${prefix}-toggle`);
  const search = document.getElementById(`${prefix}-search`);
  const on = Boolean(open);
  if (picker) picker.hidden = !on;
  if (toggle) {
    toggle.setAttribute("aria-expanded", on ? "true" : "false");
    toggle.textContent = on ? "收起" : "选择世界书";
  }
  if (!on && search instanceof HTMLInputElement) {
    search.value = "";
    applyChatDetailWorldBookBindSearchFilter({ offline });
  }
}

function createChatDetailWorldBookBindChip(id, title, active) {
  const b = document.createElement("button");
  b.type = "button";
  b.className = `chat-detail-chip${active ? " is-active" : ""}`;
  b.dataset.wbId = id;
  b.dataset.wbTitle = title;
  b.setAttribute("role", "option");
  b.setAttribute("aria-selected", active ? "true" : "false");
  b.textContent = title;
  return b;
}

function applyChatDetailWorldBookBindSearchFilter(opts) {
  const offline = Boolean(opts && opts.offline);
  const prefix = chatWorldBookBindDomPrefix(offline);
  const box = document.getElementById(`${prefix}-chips`);
  const search = document.getElementById(`${prefix}-search`);
  if (!box) return;
  const q = search instanceof HTMLInputElement ? String(search.value || "").trim().toLowerCase() : "";
  for (const btn of box.querySelectorAll(".chat-detail-chip")) {
    if (!(btn instanceof HTMLButtonElement)) continue;
    const title = String(btn.dataset.wbTitle || btn.textContent || "").toLowerCase();
    btn.hidden = Boolean(q && !title.includes(q));
  }
}

/** @param {{ offline?: boolean }} [opts] */
function refreshChatDetailWorldBookBindChipsFor(opts) {
  const offline = Boolean(opts && opts.offline);
  const prefix = chatWorldBookBindDomPrefix(offline);
  const th = readActiveThread();
  let summarySuffix = "";
  if (offline) {
    const threadSharedIds = th ? getPersonaBoundWorldBookVolumeIds(th, getThreadActivePersona(th)) : [];
    summarySuffix = threadSharedIds.length
      ? `密谈共用 ${threadSharedIds.length} 本（详情页绑定）`
      : "密谈详情未绑局部卷";
  } else if (th) {
    const bound = getThreadWorldBookVolumeIds(th);
    const charItem = th.charId ? getCharPersonaItemById(th.charId) : null;
    const charDefaultIds = bound.length ? [] : getCharMainWorldBookVolumeIds(charItem);
    if (!bound.length && charDefaultIds.length) {
      summarySuffix = `本密谈未单独绑定，使用角色档案默认 ${charDefaultIds.length} 本`;
    }
  }
  refreshCharWorldBookBindChipsUi({
    pickedElId: `${prefix}-picked`,
    pickerElId: `${prefix}-chips`,
    summaryElId: `${prefix}-summary`,
    emptyElId: `${prefix}-picked-empty`,
    boundLabel: offline ? "追加" : "绑定",
    summarySuffix,
    getBound: () => {
      const t = readActiveThread();
      return offline ? getThreadOfflineWorldBookVolumeIds(t) : getThreadWorldBookVolumeIds(t);
    },
    setBound: (ids) => {
      patchActiveThread((t) => {
        if (offline) {
          if (!ids.length) delete t.offlineWorldBookVolumeIds;
          else t.offlineWorldBookVolumeIds = ids;
        } else {
          if (!ids.length) delete t.worldBookVolumeIds;
          else t.worldBookVolumeIds = ids;
          delete t.worldBookVolumeId;
        }
      });
    }
  });
  applyChatDetailWorldBookBindSearchFilter({ offline });
}

function refreshChatDetailWorldBookBindChips() {
  refreshChatDetailWorldBookBindChipsFor({ offline: false });
}

function refreshOfflineWorldBookBindChips() {
  refreshChatDetailWorldBookBindChipsFor({ offline: true });
}

function toggleChatDetailWorldBookBindFromChip(wbId, opts) {
  if (!readActiveThread()) return;
  const offline = Boolean(opts && opts.offline);
  const id = String(wbId || "").trim();
  if (!id) return;
  const readIds = offline ? getThreadOfflineWorldBookVolumeIds : getThreadWorldBookVolumeIds;
  const cur = readIds(readActiveThread());
  const has = cur.includes(id);
  if (!has && offline) {
    const th = readActiveThread();
    const shared = getPersonaBoundWorldBookVolumeIds(th, getThreadActivePersona(th));
    if (shared.includes(id)) {
      showToast("该卷已在密谈详情绑定，当面会自动带上");
      return;
    }
    if (getEffectiveThreadWorldBookVolumeIds(th, { surface: "offline" }).length >= 8) {
      showToast("注入合计已达 8 本上限");
      return;
    }
  }
  if (!has && cur.length >= 8) {
    showToast("最多绑定 8 本局部世界书");
    return;
  }
  const next = has ? cur.filter((x) => x !== id) : [...cur, id];
  patchActiveThread((t) => {
    if (offline) {
      if (!next.length) delete t.offlineWorldBookVolumeIds;
      else t.offlineWorldBookVolumeIds = next;
    } else {
      if (!next.length) delete t.worldBookVolumeIds;
      else t.worldBookVolumeIds = next;
      delete t.worldBookVolumeId;
    }
  });
  if (offline) {
    refreshOfflineWorldBookBindChips();
    syncChatOfflineMoreMenuWbDesc(readActiveThread());
  } else {
    syncChatThreadDetailPanelPlaceholders();
  }
}

