function refreshChatDetailStickerBindChips() {
  const box = document.getElementById("chat-detail-sticker-bind-chips");
  if (!box) return;
  const th = readActiveThread();
  const curArr = getThreadStickerBindCategories(th);
  const { bucket } = ensureStickerGlobalBucket();
  const items = Array.isArray(bucket.items) ? bucket.items : [];
  const cats = new Map();
  for (const it of items) {
    const c = String(it?.category || "默认").trim() || "默认";
    cats.set(c, (cats.get(c) || 0) + 1);
  }
  const keys = Array.from(cats.keys()).sort((a, b) => a.localeCompare(b, "zh-Hans-CN"));
  box.innerHTML = "";
  for (const k of keys) {
    const b = document.createElement("button");
    b.type = "button";
    b.className = `chat-detail-chip${curArr.includes(k) ? " is-active" : ""}`;
    b.dataset.cat = k;
    b.setAttribute("role", "option");
    b.setAttribute("aria-selected", curArr.includes(k) ? "true" : "false");
    b.textContent = `${k} (${cats.get(k) || 0})`;
    box.appendChild(b);
  }
  // 清理无效绑定
  if (curArr.some((c) => !keys.includes(c))) {
    patchActiveThread((t) => {
      t.stickerBindCategories = curArr.filter((c) => keys.includes(c));
      delete t.stickerBindCategory;
    });
  }
}

function refreshChatDetailNarratorPreview() {
  const el = document.getElementById("chat-detail-narrator-preview-narr");
  if (!el) return;
  const fontR = document.getElementById("chat-detail-narrator-font-range");
  const lhR = document.getElementById("chat-detail-narrator-lh-range");
  const fontVal = document.getElementById("chat-detail-narrator-font-val");
  const lhVal = document.getElementById("chat-detail-narrator-lh-val");
  const innerBtn = document.getElementById("chat-detail-narrator-inner-toggle");
  const innerOn = innerBtn ? innerBtn.getAttribute("aria-pressed") !== "false" : true;
  const fs =
    fontR && fontR instanceof HTMLInputElement
      ? Math.max(12, Math.min(20, Math.floor(Number(fontR.value))))
      : 14;
  const lhCent =
    lhR && lhR instanceof HTMLInputElement ? Math.floor(Number(lhR.value)) : 165;
  const lh = Math.max(125, Math.min(210, lhCent)) / 100;
  el.style.fontSize = `${fs}px`;
  el.style.lineHeight = String(lh);
  if (fontVal) fontVal.textContent = String(fs);
  if (lhVal) lhVal.textContent = lh.toFixed(2);
  const sampleInner = innerOn
    ? "灯色落在桌面。*指尖在杯柄上顿了半拍* 才把视线抬起来。"
    : "灯色落在桌面。指尖在杯柄上停了一瞬，才把视线抬起来。";
  const sample = `咖啡厅角落很安静。\n${sampleInner}`;
  fillChatNarrationElWithItalicFromAst(el, sample);
}

function syncChatDetailNarratorSheetControlsFromThread() {
  const th = readActiveThread();
  const d = getThreadNarratorDensity(th);
  const box = document.getElementById("chat-detail-narrator-density-chips");
  if (box) {
    const btns = [...box.querySelectorAll(".chat-detail-chip")];
    for (const b of btns) {
      const v = String(b.dataset.narratorDensity || "");
      const active =
        (v === "light" && d === "light") || (v === "rich" && d === "rich") || (v === "normal" && d === "normal");
      b.classList.toggle("is-active", active);
      b.setAttribute("aria-selected", active ? "true" : "false");
    }
  }
  const innerBtn = document.getElementById("chat-detail-narrator-inner-toggle");
  if (innerBtn) {
    const on = isThreadNarratorIncludeInner(th);
    innerBtn.setAttribute("aria-pressed", on ? "true" : "false");
    innerBtn.setAttribute("aria-label", on ? "旁白内心斜体：开" : "旁白内心斜体：关");
  }
  const fontR = document.getElementById("chat-detail-narrator-font-range");
  if (fontR && fontR instanceof HTMLInputElement) {
    fontR.value = String(getThreadNarratorFontPx(th));
  }
  const lhR = document.getElementById("chat-detail-narrator-lh-range");
  if (lhR && lhR instanceof HTMLInputElement) {
    lhR.value = String(Math.round(getThreadNarratorLineHeight(th) * 100));
  }
  refreshChatDetailNarratorPreview();
}

function openChatDetailNarratorSheet() {
  const root = document.getElementById("chat-detail-narrator-sheet");
  if (!root) return;
  syncChatDetailNarratorSheetControlsFromThread();
  root.hidden = false;
  root.setAttribute("aria-hidden", "false");
  window.requestAnimationFrame(() => {
    root.classList.add("is-open");
    document.getElementById("chat-detail-narrator-save")?.focus();
  });
}

function closeChatDetailNarratorSheet() {
  const root = document.getElementById("chat-detail-narrator-sheet");
  if (!root) return;
  root.classList.remove("is-open");
  root.setAttribute("aria-hidden", "true");
  window.setTimeout(() => {
    root.hidden = true;
  }, 160);
}

function resetChatDetailNarratorSheetDraft() {
  const box = document.getElementById("chat-detail-narrator-density-chips");
  if (box) {
    const btns = [...box.querySelectorAll(".chat-detail-chip")];
    for (const b of btns) {
      const v = String(b.dataset.narratorDensity || "");
      const active = v === "normal";
      b.classList.toggle("is-active", active);
      b.setAttribute("aria-selected", active ? "true" : "false");
    }
  }
  const innerBtn = document.getElementById("chat-detail-narrator-inner-toggle");
  if (innerBtn) {
    innerBtn.setAttribute("aria-pressed", "true");
    innerBtn.setAttribute("aria-label", "旁白内心斜体：开");
  }
  const fontR = document.getElementById("chat-detail-narrator-font-range");
  if (fontR && fontR instanceof HTMLInputElement) fontR.value = "14";
  const lhR = document.getElementById("chat-detail-narrator-lh-range");
  if (lhR && lhR instanceof HTMLInputElement) lhR.value = "165";
  refreshChatDetailNarratorPreview();
}

function saveChatDetailNarratorSheetToThread() {
  const box = document.getElementById("chat-detail-narrator-density-chips");
  let density = "normal";
  const activeChip = box?.querySelector(".chat-detail-chip.is-active");
  if (activeChip?.dataset.narratorDensity) density = String(activeChip.dataset.narratorDensity);
  const innerBtn = document.getElementById("chat-detail-narrator-inner-toggle");
  const innerOn = innerBtn ? innerBtn.getAttribute("aria-pressed") !== "false" : true;
  const fontR = document.getElementById("chat-detail-narrator-font-range");
  const lhR = document.getElementById("chat-detail-narrator-lh-range");
  const fontPx = fontR && fontR instanceof HTMLInputElement ? Math.floor(Number(fontR.value)) : 14;
  const lhCent = lhR && lhR instanceof HTMLInputElement ? Math.floor(Number(lhR.value)) : 165;
  const ok = patchActiveThread((t) => {
    if (density === "light" || density === "rich") t.narratorDensity = density;
    else delete t.narratorDensity;
    if (innerOn) delete t.narratorIncludeInner;
    else t.narratorIncludeInner = false;
    const fp = Math.max(12, Math.min(20, fontPx));
    const lh = Math.max(125, Math.min(210, lhCent)) / 100;
    if (fp !== 14) t.narratorFontPx = fp;
    else delete t.narratorFontPx;
    if (Math.abs(lh - 1.65) > 0.001) t.narratorLineHeight = lh;
    else delete t.narratorLineHeight;
  });
  if (!ok) {
    showToast("无法保存");
    return;
  }
  showToast("旁白设置已保存");
  closeChatDetailNarratorSheet();
  renderChatMessages();
}

/** 相册选图：兼容 iOS/Android 上 type 为空但实为图片的文件 */
function isImagePickFile(file) {
  if (!file || typeof file.size !== "number" || file.size <= 0) return false;
  const type = String(file.type || "").toLowerCase();
  if (type.startsWith("image/")) return true;
  const name = String(file.name || "").toLowerCase();
  return /\.(jpe?g|png|gif|webp|bmp|heic|heif|avif|jfif)$/i.test(name);
}

function readImageFileAsDataUrl(file) {
  return new Promise((resolve, reject) => {
    if (!file || !file.size) {
      reject(new Error("empty"));
      return;
    }
    const fr = new FileReader();
    fr.onload = () => resolve(String(fr.result || ""));
    fr.onerror = () => reject(new Error("read"));
    fr.readAsDataURL(file);
  });
}

/** 与聊天内发送图片一致：读入后按最长边 960、JPEG 0.82 压成 data URL（大图不致爆存储/序列化）。 */
async function readImageFileAsChatEmbeddedDataUrl(file) {
  const dataUrl = await readImageFileAsDataUrl(file);
  return shrinkDataUrlWithCanvas(String(dataUrl || ""), 960, 0.82);
}

/** 密谈背景图上传：压缩失败时退回原图 data URL。 */
async function readChatThreadBgFromFile(file) {
  if (!file || !file.size || !isImagePickFile(file)) throw new Error("bad");
  try {
    const shrunk = await readImageFileAsChatEmbeddedDataUrl(file);
    if (shrunk) return shrunk;
  } catch {
    /* 压缩失败时仍尝试原图 */
  }
  const raw = String((await readImageFileAsDataUrl(file)) || "").trim();
  if (!raw) throw new Error("empty");
  return raw;
}

/** 本密谈头像：较小尺寸即可（顶栏与气泡复用）。 */
async function readChatThreadAvatarFromFile(file) {
  if (!file || !file.size || !isImagePickFile(file)) throw new Error("bad");
  try {
    const dataUrl = await readImageFileAsDataUrl(file);
    const shrunk = await shrinkDataUrlWithCanvas(String(dataUrl || ""), 512, 0.82);
    if (shrunk) return shrunk;
  } catch {
    /* 压缩失败时仍尝试原图 */
  }
  const raw = String((await readImageFileAsDataUrl(file)) || "").trim();
  if (!raw) throw new Error("empty");
  return raw;
}

/** @param {unknown} th @param {ReturnType<typeof readUserMask>} userM */
function resolveChatThreadUserAvatarUrl(th, userM) {
  const o = th && typeof th.chatThreadUserAvatar === "string" ? String(th.chatThreadUserAvatar).trim() : "";
  const ok = o ? sanitizeStickerUrl(o) : "";
  if (ok) return ok;
  const g = userM?.avatar && String(userM.avatar).trim();
  return g ? String(g).trim() : "";
}

/**
 * @param {unknown} th
 * @param {unknown} charItem
 * @param {"main"|"alt"|""} slot
 * @param {ReturnType<typeof readCharPersona>} charP
 */
function resolveChatThreadCharAvatarUrl(th, charItem, slot, charP) {
  const speakerItem =
    charItem && typeof charItem === "object" ? String(charItem.id || "").trim() : "";
  const groupSpeakerBound = th?.kind === "group" && !!speakerItem;
  if (!groupSpeakerBound) {
  const o = th && typeof th.chatThreadCharAvatar === "string" ? String(th.chatThreadCharAvatar).trim() : "";
  const ok = o ? sanitizeStickerUrl(o) : "";
  if (ok) return ok;
  }
  if (charItem && typeof charItem === "object") {
    if (!groupSpeakerBound && charHasAltPersona(charItem)) {
    const av = resolvePersonaAvatar(charItem, slot);
      if (av) return String(av).trim();
    }
    const fromItem = charItem.avatar ? String(charItem.avatar).trim() : "";
    if (fromItem) return fromItem;
  }
  const fromP = charP?.avatar && String(charP.avatar).trim();
  return fromP || "";
}

/** @param {HTMLImageElement} img @param {string} url */
function applyChatAvatarUrlToImg(img, url) {
  const s = sanitizeStickerUrl(String(url || "").trim());
  if (!s || !img) return false;
  applyChatImageUrlToElement(img, s);
  return true;
}

let chatThreadSurfaceBgAppliedKey = "";
let chatThreadSurfaceBgApplyGen = 0;

function applyChatThreadSurfaceBackgrounds() {
  const gen = ++chatThreadSurfaceBgApplyGen;
  void applyChatThreadSurfaceBackgroundsAsync(gen);
}

/** 晤面壁纸变更后强制重刷（避免 surfaceKey 缓存导致换图不生效） */
function applyChatOfflineWallpaperSurfaces() {
  chatThreadSurfaceBgAppliedKey = "";
  applyChatThreadSurfaceBackgrounds();
}

/** 玻璃 + 消息区背景：壁纸挂 #chat-screen 根层铺满，避免 stack 内被 overflow 裁切 */
function syncChatMessageWallpaperMount() {
  const screen = getChatScreenEl();
  const stack = document.getElementById("chat-messages-stack");
  const wall = document.getElementById("chat-messages-wallpaper");
  if (!screen || !stack || !(wall instanceof HTMLElement)) return;

  const screenFill =
    computeChatScreenThemeGlassOn() &&
    getActiveChatDmSurfaceForContext() !== "offline" &&
    stack.classList.contains("chat-messages-stack--custom-bg");
  wall.classList.toggle("chat-messages-wallpaper--screen-fill", screenFill);

  const targetParent = screenFill ? screen : stack;
  if (wall.parentElement === targetParent) return;

  if (screenFill) {
    const inner = screen.querySelector(".settings-inner");
    if (inner) screen.insertBefore(wall, inner);
    else screen.prepend(wall);
  } else {
    stack.insertBefore(wall, stack.firstChild);
  }
}

/** @param {HTMLImageElement} img @param {string} storedRef @param {string} displayUrl @param {(() => void) | null} [onError] */
function applyChatSurfaceBgToImg(img, storedRef, displayUrl, onError) {
  const stored = String(storedRef || "").trim();
  const disp = String(displayUrl || "").trim();
  if (!stored || !disp) {
    img.removeAttribute("src");
    delete img.dataset.chatBgSrc;
    img.classList.remove("is-loaded");
    return;
  }
  const markLoaded = () => {
    img.classList.add("is-loaded");
  };
  const unchanged = img.dataset.chatBgSrc === stored;
  if (!unchanged) {
    img.onload = null;
    img.onerror = null;
    img.classList.remove("is-loaded");
    img.dataset.chatBgSrc = stored;
    img.onload = () => {
      markLoaded();
    };
    img.onerror = () => {
      img.classList.remove("is-loaded");
      delete img.dataset.chatBgSrc;
      if (onError) onError();
    };
    img.src = disp;
  } else if (img.src !== disp) {
    img.src = disp;
  }
  if (img.complete && img.naturalWidth > 0) {
    markLoaded();
  } else if (typeof img.decode === "function") {
    img.decode().then(markLoaded).catch(() => {});
  }
}

async function applyChatThreadSurfaceBackgroundsAsync(gen) {
  const th0 = readActiveThread();
  const heroStored = th0?.chatHeroBgImage && String(th0.chatHeroBgImage).trim();
  const bodyStored = th0?.chatBodyBgImage && String(th0.chatBodyBgImage).trim();
  const offlineStored = th0?.chatOfflineBgImage && String(th0.chatOfflineBgImage).trim();
  const cardStored = th0?.chatIdentityPanelBgImage && String(th0.chatIdentityPanelBgImage).trim();
  const compStored = th0?.chatComposerBgImage && String(th0.chatComposerBgImage).trim();
  const surfaceKey = [
    heroStored,
    bodyStored,
    offlineStored,
    cardStored,
    compStored,
    th0?.chatHeroBgFullBleed ? "1" : "0",
    th0?.chatMessagesBgFullBleed ? "1" : "0"
  ].join("\t");
  if (surfaceKey === chatThreadSurfaceBgAppliedKey) return;

  const [heroDisp, bodyDisp, offlineDisp, cardDisp, compDisp] = await Promise.all([
    hydrateChatImageStoredUrl(heroStored || ""),
    hydrateChatImageStoredUrl(bodyStored || ""),
    hydrateChatImageStoredUrl(offlineStored || ""),
    hydrateChatImageStoredUrl(cardStored || ""),
    hydrateChatImageStoredUrl(compStored || "")
  ]);
  if (gen !== chatThreadSurfaceBgApplyGen) return;

  chatThreadSurfaceBgAppliedKey = surfaceKey;
  const th = readActiveThread();
  const offlineBleedStored = offlineStored || bodyStored || heroStored || "";
  const offlineBleedDisp =
    (offlineStored && offlineDisp) || (bodyStored && bodyDisp) || (heroStored && heroDisp) || "";
  const iw = document.querySelector(".chat-identity-wrap");
  const msgStack = document.getElementById("chat-messages-stack");
  const msgWall = document.getElementById("chat-messages-wallpaper");
  const msgWallImg = document.getElementById("chat-messages-wallpaper-img");
  const idPanel = document.getElementById("chat-identity-panel");
  const composer = document.getElementById("chat-composer");
  const urlCss = (u) => (u ? `url(${JSON.stringify(u)})` : "");
  if (iw) {
    iw.classList.toggle("chat-identity-wrap--custom-bg", Boolean(heroStored));
    iw.style.backgroundImage = urlCss(heroDisp);
    iw.classList.toggle(
      "chat-identity-wrap--full-bleed",
      Boolean(heroStored) && Boolean(th?.chatHeroBgFullBleed)
    );
  }
  /* 消息区：独立层 + img；入库可能是 xxj-blob:，须先 resolve 再设 src */
  if (msgStack && msgWall && msgWallImg) {
    msgStack.classList.toggle("chat-messages-stack--custom-bg", Boolean(bodyStored));
    msgStack.classList.toggle(
      "chat-messages-stack--full-bleed",
      Boolean(bodyStored) && Boolean(th?.chatMessagesBgFullBleed)
    );
    if (bodyStored && bodyDisp) {
      applyChatSurfaceBgToImg(msgWallImg, bodyStored, bodyDisp, () => {
        showToast("消息区背景无法显示，请换一张 JPG/PNG 试试");
      });
    } else {
      msgWallImg.removeAttribute("src");
      delete msgWallImg.dataset.chatBgSrc;
      msgWallImg.classList.remove("is-loaded");
    }
  }
  if (idPanel) {
    idPanel.classList.toggle("chat-identity-panel--custom-bg", Boolean(cardStored));
    idPanel.style.backgroundImage = urlCss(cardDisp);
  }
  if (composer) {
    const glassComposerBg = computeChatScreenThemeGlassOn();
    const offlineOpen = Boolean(
      chatOfflineSurfaceActive || document.getElementById("chat-offline-screen")?.classList.contains("is-open")
    );
    const offlineFullBleed = Boolean(offlineOpen && offlineBleedStored && offlineBleedDisp);
    composer.classList.toggle(
      "chat-composer--custom-bg",
      Boolean(compStored) && !glassComposerBg && !offlineFullBleed
    );
    composer.style.backgroundImage =
      glassComposerBg || offlineFullBleed ? "" : urlCss(compDisp);
  }
  const chatScroll = document.getElementById("chat-scroll");
  if (chatScroll) {
    chatScroll.classList.toggle(
      "chat-scroll--surface-bg",
      Boolean(heroStored || bodyStored || cardStored || compStored)
    );
  }
  /** 线下晤面：专用壁纸优先，否则消息区/顶栏图，整屏 cover 固定铺满 */
  const offlineRoot = document.getElementById("chat-offline-screen");
  const offlineBgImg = document.getElementById("chat-offline-thread-bg-img");
  if (offlineRoot && offlineBgImg) {
    const threadBgWrap = document.getElementById("chat-offline-thread-bg");
    if (offlineBleedStored && offlineBleedDisp) {
      const wallCss = urlCss(offlineBleedDisp);
      offlineRoot.classList.add("chat-offline--thread-bg");
      offlineRoot.style.setProperty("--chat-offline-wallpaper-image", wallCss);
      offlineRoot.style.backgroundImage = wallCss;
      offlineRoot.style.backgroundSize = "cover";
      offlineRoot.style.backgroundPosition = "center center";
      offlineRoot.style.backgroundRepeat = "no-repeat";
      if (threadBgWrap instanceof HTMLElement) {
        threadBgWrap.style.setProperty("--chat-offline-wallpaper-image", wallCss);
      }
      applyChatSurfaceBgToImg(offlineBgImg, offlineBleedStored, offlineBleedDisp, () => {
        offlineRoot.classList.remove("chat-offline--thread-bg");
        offlineRoot.style.removeProperty("--chat-offline-wallpaper-image");
        offlineRoot.style.backgroundImage = "";
        offlineRoot.style.backgroundSize = "";
        offlineRoot.style.backgroundPosition = "";
        offlineRoot.style.backgroundRepeat = "";
        if (threadBgWrap instanceof HTMLElement) {
          threadBgWrap.style.removeProperty("--chat-offline-wallpaper-image");
        }
      });
    } else {
      offlineRoot.classList.remove("chat-offline--thread-bg");
      offlineRoot.style.removeProperty("--chat-offline-wallpaper-image");
      offlineRoot.style.backgroundImage = "";
      offlineRoot.style.backgroundSize = "";
      offlineRoot.style.backgroundPosition = "";
      offlineRoot.style.backgroundRepeat = "";
      if (threadBgWrap instanceof HTMLElement) {
        threadBgWrap.style.removeProperty("--chat-offline-wallpaper-image");
        threadBgWrap.style.backgroundImage = "";
      }
      offlineBgImg.removeAttribute("src");
      delete offlineBgImg.dataset.chatBgSrc;
      offlineBgImg.classList.remove("is-loaded");
    }
  }
  syncChatMessageWallpaperMount();
}

function saveThreadSceneFromDetailInput() {
  const el = document.getElementById("chat-detail-scene-input");
  if (!el) return false;
  const g = getEffectiveThreadScenePrompt(null);
  const v = String(el.value || "").trim();
  const ok = patchActiveThread((th) => {
    if (!v || v === g) delete th.scenePrompt;
    else th.scenePrompt = String(el.value || "");
  });
  if (ok) updateChatChrome();
  return ok;
}

function saveThreadRemarkNameFromDetailInput() {
  const th = readActiveThread();
  if (th && th.kind === "group") return false;
  const nameEl = document.getElementById("chat-detail-char-remark-name-input");
  if (!nameEl || !(nameEl instanceof HTMLInputElement)) return false;
  const remarkName = String(nameEl.value || "").trim().slice(0, 32);
  const ok = patchActiveThread((th) => {
    if (!remarkName) delete th.charThreadRemarkName;
    else th.charThreadRemarkName = remarkName;
  });
  if (ok) {
    updateChatChrome();
    if (chatListScreen?.classList.contains("is-open")) renderChatThreadList();
    syncChatInnerVoicePanelFromLog();
    if (isChatCharInnerVoiceOpen()) syncChatInnerVoicePanelTitle();
  }
  return ok;
}

/** @param {"recent" | "summary"} mode */
function applyChatDetailMemoryModeDisabledState(mode) {
  const memInput = document.getElementById("chat-detail-memory-rounds-input");
  const tailInput = document.getElementById("chat-detail-memo-summary-raw-tail-input");
  if (memInput instanceof HTMLInputElement) memInput.disabled = mode !== "recent";
  if (tailInput instanceof HTMLInputElement) tailInput.disabled = mode !== "summary";
}

/** @param {unknown} th */
function syncChatDetailMemoryModeUi(th) {
  const mode = getThreadChatMemoryMode(th);
  const recentRadio = document.getElementById("chat-detail-memory-mode-recent");
  const summaryRadio = document.getElementById("chat-detail-memory-mode-summary");
  const memInput = document.getElementById("chat-detail-memory-rounds-input");
  const tailInput = document.getElementById("chat-detail-memo-summary-raw-tail-input");
  if (recentRadio instanceof HTMLInputElement) recentRadio.checked = mode === "recent";
  if (summaryRadio instanceof HTMLInputElement) summaryRadio.checked = mode === "summary";
  if (memInput instanceof HTMLInputElement) {
    const mr = th && th.memoryUserRounds != null ? Number(th.memoryUserRounds) : NaN;
    memInput.value = Number.isFinite(mr) && mr > 0 ? String(Math.floor(mr)) : "";
  }
  if (tailInput instanceof HTMLInputElement) {
    const tailN = th && th.memoSummaryRawTail != null ? Number(th.memoSummaryRawTail) : NaN;
    tailInput.value =
      mode === "summary" && Number.isFinite(tailN) && tailN > 0 ? String(Math.floor(tailN)) : "";
  }
  applyChatDetailMemoryModeDisabledState(mode);
}

function readChatDetailMemoryModeFromUi() {
  const summaryRadio = document.getElementById("chat-detail-memory-mode-summary");
  if (summaryRadio instanceof HTMLInputElement && summaryRadio.checked) return "summary";
  return "recent";
}

/** @param {string} raw @returns {number | null} null = 无效 */
function parseChatDetailMemoryCountInput(raw) {
  const t = String(raw ?? "").trim();
  if (t === "") return 0;
  const n = Math.floor(Number(t));
  if (!Number.isFinite(n) || n < 0) return null;
  return n;
}

function saveThreadMemoryRoundsFromDetailInput() {
  const mode = readChatDetailMemoryModeFromUi();
  const memEl = document.getElementById("chat-detail-memory-rounds-input");
  const tailEl = document.getElementById("chat-detail-memo-summary-raw-tail-input");
  if (!(memEl instanceof HTMLInputElement) || !(tailEl instanceof HTMLInputElement)) return false;
  const memN = mode === "recent" ? parseChatDetailMemoryCountInput(memEl.value) : 0;
  const tailN = mode === "summary" ? parseChatDetailMemoryCountInput(tailEl.value) : 0;
  if (memN === null || tailN === null) return false;
  return patchActiveThread((th) => {
    th.chatMemoryMode = mode;
    if (mode === "recent") {
      delete th.memoSummaryRawTail;
      if (!memN) delete th.memoryUserRounds;
      else th.memoryUserRounds = memN;
    } else {
      delete th.memoryUserRounds;
      if (!tailN) delete th.memoSummaryRawTail;
      else th.memoSummaryRawTail = Math.min(CHAT_MEMO_SUMMARY_RAW_TAIL_MAX, tailN);
    }
  });
}

function saveThreadCharProactiveIntervalFromDetailInput() {
  const el = document.getElementById("chat-detail-char-proactive-interval-minutes");
  if (!el) return false;
  const raw = String(el.value ?? "").trim();
  const n = Math.floor(Number(raw));
  if (!Number.isFinite(n) || n < 0) return false;
  const sec = n * 60;
  return patchActiveThread((th) => {
    th.charProactiveIntervalSec = sec;
    delete th.charProactiveAutoMode;
  });
}

function saveThreadTheaterPromptMinGapFromDetailInput() {
  const el = document.getElementById("chat-detail-theater-prompt-min-gap");
  if (!(el instanceof HTMLInputElement)) return false;
  const v = normalizeTheaterPromptMinGap(el.value);
  if (v == null) return false;
  return patchActiveThread((t) => {
    if (v === readTheaterPromptMinGap()) delete t.theaterPromptMinGap;
    else t.theaterPromptMinGap = v;
  });
}

/** @param {{ skipCloseMemo?: boolean }} [opts] */
