    const isFullRestoringMsg = Boolean(
      isRestoring && restoringSegIdxUi < 0 && !String(m.content || "").trim()
    );
    const stUrlEarly =
      m && typeof m === "object" && m.sticker && typeof m.sticker === "object"
        ? String(m.sticker.url || "").trim()
        : "";
    const stDescEarly =
      m && typeof m === "object" && m.sticker && typeof m.sticker === "object"
        ? String(m.sticker.description || m.sticker.desc || "").trim()
        : "";
    let rawFull = String(m.content || "");
    let displayTransJoined = String(m.translation || "");
    /** @type {string} 本轮从 JSON 解析出的 charImage.caption（用于展示；可与已入库的 m.image.desc 合并） */
    let assistantParsedCharCap = "";
    /** 展示兜底：勿写入 m，避免 chatRowFp 与下轮 log 指纹漂移导致整表重绘闪动 */
    let assistantParsedTransJoined = "";
    /** @type {boolean[] | null} */
