/** 从一条 assistant 消息构建心声快照（含扩展面板字段）。 */
function heartVoiceSnapFromAssistantMessage(m) {
  const t = String(m.heartVoice ?? "").trim();
  const st = String(m.hvState ?? "").trim();
  const mood = String(m.hvMood ?? "").trim();
  const d = String(m.hvDesire ?? "").trim();
  const ad = String(m.hvAffectionDesc ?? "").trim();
  let aff = m.hvAffinity;
  if (typeof aff !== "number" || !Number.isFinite(aff)) aff = null;
  else aff = Math.max(0, Math.min(100, Math.round(aff)));
  return {
    thought: t,
    state: st,
    desire: d,
    mood: mood,
    affinity: aff,
    affectionDesc: ad
  };
}

/** 心声快照是否已有任意可展示字段（与历史列表「有内容」判定一致）。 */
function heartVoiceSnapHasRenderableContent(s) {
  if (!s || typeof s !== "object") return false;
  const t = String(s.thought ?? "").trim();
  const st = String(s.state ?? "").trim();
  const mood = String(s.mood ?? "").trim();
  const d = String(s.desire ?? "").trim();
  const ad = String(s.affectionDesc ?? "").trim();
  const aff = s.affinity;
  const hasAff = typeof aff === "number" && Number.isFinite(aff);
  return Boolean(t || st || mood || d || ad || hasAff);
}

/** 是否已有用户发出的聊天（无则心声主面板显示「暂无」）。 */
function chatLogHasUserChatForHeartVoice(log, surface) {
  const arr = Array.isArray(log) ? log : [];
  const surf = surface === "offline" ? "offline" : "im";
  return arr.some((m) => m && m.role === "user" && chatMessageDmSurface(m) === surf);
}

let chatInnerVoiceLastAppliedSnapKey = "";
let chatInnerVoiceSnapContextKey = "";

/** @param {unknown} m @param {"im" | "offline"} surface */
function assistantMatchesHeartVoiceSurface(m, surface) {
  if (!m || typeof m !== "object" || m.role !== "assistant") return false;
  const dm = chatMessageDmSurface(m);
  return surface === "offline" ? dm === "offline" : dm !== "offline";
}

/** @param {ChatInnerVoiceSnap | null | undefined} snap */
function heartVoiceSnapDomKey(snap) {
  if (!snap || typeof snap !== "object") return "";
  if (snap.__emptyNoMessages) return "__emptyNoMessages";
  return [
    String(snap.thought ?? "").trim(),
    String(snap.state ?? "").trim(),
    String(snap.mood ?? "").trim(),
    String(snap.desire ?? "").trim(),
    String(snap.affectionDesc ?? "").trim(),
    snap.affinity == null ? "" : String(Math.round(Number(snap.affinity)))
  ].join("\u0001");
}

/** @param {readonly unknown[]} log @param {"im"|"offline"} surface */
function findLastAssistantLogIdxForHeartVoicePanel(log, surface) {
  const arr = Array.isArray(log) ? log : [];
  for (let i = arr.length - 1; i >= 0; i--) {
    const m = arr[i];
    if (!assistantMatchesHeartVoiceSurface(m, surface)) continue;
    if (isAssistantTypingPlaceholder(m)) continue;
    return i;
  }
  return -1;
}

/** @param {ChatInnerVoiceSnap | null | undefined} snap @param {number} logIdx */
function tagHeartVoiceSnapSourceLogIdx(snap, logIdx) {
  const i = Number(logIdx);
  if (!snap || typeof snap !== "object" || !Number.isFinite(i) || i < 0) return snap;
  return { ...snap, __sourceLogIdx: Math.floor(i) };
}

/** 取心声面板当前应展示的独白（可浏览历史某轮，或默认最近一条有内容的对方回复）。 */
function readChatInnerVoiceSnapshotForActiveThread() {
  if (!isThreadHeartVoiceEnabled(readActiveThread())) return null;
  const ref = readChatActiveThreadRef();
  if (!ref.maskId || !ref.threadId) return null;
  const surface = getActiveChatDmSurfaceForContext();
  const log = readChatLog();
  const b = chatInnerVoiceBrowseAssistantLogIdx;
  if (Number.isFinite(b) && b >= 0 && b < log.length) {
    const m = log[b];
    if (m && m.role === "assistant" && assistantMatchesHeartVoiceSurface(m, surface)) {
      return tagHeartVoiceSnapSourceLogIdx(heartVoiceSnapFromAssistantMessage(m), b);
    }
  }
  if (!chatLogHasUserChatForHeartVoice(log, surface)) {
    return { __emptyNoMessages: true };
  }
  for (let i = log.length - 1; i >= 0; i--) {
    const m = log[i];
    if (!assistantMatchesHeartVoiceSurface(m, surface)) continue;
    if (isAssistantTypingPlaceholder(m)) continue;
    const snap = heartVoiceSnapFromAssistantMessage(m);
    if (heartVoiceSnapHasRenderableContent(snap)) {
      return tagHeartVoiceSnapSourceLogIdx(snap, i);
    }
  }
  const lastAi = findLastAssistantLogIdxForHeartVoicePanel(log, surface);
  if (lastAi < 0) return null;
  return tagHeartVoiceSnapSourceLogIdx(heartVoiceSnapFromAssistantMessage(log[lastAi]), lastAi);
}

function findPrecedingUserBubblePlainForHeartReroll(log, assistantIdx) {
  const arr = Array.isArray(log) ? log : [];
  const i0 = Number(assistantIdx);
  if (!Number.isFinite(i0) || i0 <= 0) return "";
  for (let j = i0 - 1; j >= 0; j--) {
    const m = arr[j];
    if (m && m.role === "user") {
      const raw = String(m.content || "").trim();
      return raw.length > 6000 ? `${raw.slice(0, 6000)}…` : raw;
    }
  }
  return "";
}

/**
 * 仅重写心声：独立 API 轮次，要求模型只返回 `{"heartVoice":"..."}`。
 * @param {number} assistantLogIdx
 * @returns {{ role: string, content: string }[]}
 */
function buildHeartVoiceRerollApiMessages(assistantLogIdx) {
  const log = readChatLog();
  const i = Number(assistantLogIdx);
  if (!Number.isFinite(i) || i < 0 || i >= log.length) throw new Error("无效消息");
  const m = log[i];
  if (!m || m.role !== "assistant") throw new Error("只能对对方发言重 roll 心声");
  const name = getChatCharPersonaDisplayName();
  const um = readUserMask();
  const userCall = (um.displayName && String(um.displayName).trim()) || "对方";
  const bubble = String(m.content || "").trim();
  const prevHv = String(m.heartVoice || "").trim();
  const userBefore = findPrecedingUserBubblePlainForHeartReroll(log, i);
  const sys = [
    `你是「${name}」，正在与「${userCall}」线上聊天。`,
    `任务：在**绝不改变已发出聊天气泡字面**的前提下，为该条气泡写一版新的内心独白（心声）。`,
    `只输出 **一个** JSON 对象。允许且**必须**包含：\`heartVoice\`、\`innerState\`、\`mood\`、\`desire\`、\`affinity\`、\`affectionDesc\`（与主聊天协议相同含义）。**不要**输出 lines、thinking、recalls、markdown 代码围栏。`,
    `各键与每轮主回复协议一致；heartVoice 为 2～8 句独白，**一律中文**（与密谈是否开启「对照翻译」无关，**禁止**为配合外文气泡而写成外语）。`,
    buildHeartVoiceAffinityContinuityPromptLine(log.slice(0, i)),
    `**innerState**、**mood**、**desire**、**affectionDesc** 与 heartVoice 相同：**全部中文**，不走翻译、不写成目标外语。其中 **innerState** 以「现场画面」为主：此刻在做什么、身体姿势/动作、穿着与细节（可一句带环境），少写抽象情绪词；情绪交给 mood / heartVoice。`
  ].join("\n");
  const user = [
    `【对方上一条（节选，可无）】`,
    userBefore || "（无）",
    "",
    `【你这条已发出的气泡（不可改字，只供对照）】`,
    bubble.length > 12000 ? `${bubble.slice(0, 12000)}…` : bubble,
    "",
    `【旧心声（可参考后重写）】`,
    prevHv ? (prevHv.length > 8000 ? `${prevHv.slice(0, 8000)}…` : prevHv) : "（无，可自由写）"
  ].join("\n");
  return [
    { role: "system", content: sys },
    { role: "user", content: user }
  ];
}

function patchChatLogAssistantHeartPanelAt(logIdx, parsed) {
  const log = readChatLog();
  const i = Number(logIdx);
  if (!Number.isFinite(i) || i < 0 || i >= log.length) return false;
  const m = log[i];
  if (!m || m.role !== "assistant") return false;
  const p = /** @type {ReturnType<typeof parseChatAssistantPayload>} */ (parsed);
  const next = { ...m };
  const hv = String(p.heartVoice || "").trim().slice(0, 80_000);
  if (hv) next.heartVoice = hv;
  const prevAff =
    m.hvAffinity != null && Number.isFinite(Number(m.hvAffinity))
      ? Math.max(0, Math.min(100, Math.round(Number(m.hvAffinity))))
      : readLastAssistantHvAffinityFromLog(log, i);
  applyHvPanelFieldsToAssistantEntry(
    next,
    p,
    isThreadHeartVoiceEnabled(readActiveThread()) && p.fromJson,
    prevAff
  );
  log[i] = next;
  saveChatLog(log);
  return true;
}

function isChatInnerVoiceHistoryScreenOpen() {
  const el = document.getElementById("chat-inner-voice-history-screen");
  return !!(el && !el.hidden);
}

function closeChatInnerVoiceHistoryScreen() {
  const root = document.getElementById("chat-inner-voice-history-screen");
  if (!root || root.hidden) return;
  root.classList.remove("is-open");
  root.hidden = true;
  root.setAttribute("aria-hidden", "true");
  reparentChatInnerVoiceShellsForActiveSurface();
  syncChatScreenOverlayOpenClass();
}

/** 从历史列表打开主手记面板并定位到该轮 assistant 心声。 */
function openHistoryInnerVoiceInMemoSheet(logIdx) {
  const log = readChatLog();
  const i = Number(logIdx);
  if (!Number.isFinite(i) || i < 0 || i >= log.length) return;
  const m = log[i];
  if (!m || m.role !== "assistant") return;
  const snap = heartVoiceSnapFromAssistantMessage(m);
  if (!heartVoiceSnapHasRenderableContent(snap)) {
    showToast("该轮无保存的心声");
    return;
  }
  const face = document.getElementById("chat-header-char-face");
  openChatCharInnerVoicePanel(face instanceof HTMLElement ? face : null, { browseAssistantLogIdx: Math.floor(i) });
}

function openChatInnerVoiceHistoryScreen() {
  if (!isThreadHeartVoiceEnabled(readActiveThread())) {
    showToast("本密谈已关闭心声");
    return;
  }
  reparentChatInnerVoiceShellsForActiveSurface();
  closeChatBubbleActionSheet();
  const root = document.getElementById("chat-inner-voice-history-screen");
  if (!root) return;
  renderChatInnerVoiceHistoryList();
  root.classList.add("is-open");
  root.hidden = false;
  root.setAttribute("aria-hidden", "false");
  syncChatScreenThemeGlassClass();
  window.requestAnimationFrame(() => {
    document.getElementById("chat-inner-voice-history-screen-dismiss")?.focus();
  });
}

function renderChatInnerVoiceHistoryList() {
  const ul = document.getElementById("chat-inner-voice-history-screen-list");
  if (!ul) return;
  ul.replaceChildren();
  if (!isThreadHeartVoiceEnabled(readActiveThread())) return;
  const surface = getActiveChatDmSurfaceForContext();
  const log = readChatLog();

  // 列表仅展示心声正文；若无 heartVoice，再退到心情/状态等单行摘要以便仍能从列表打开手记。
  /** @param {ReturnType<typeof heartVoiceSnapFromAssistantMessage>} s */
  const listVoicePlain = (s) => {
    const thought = String(s.thought ?? "").trim();
    if (thought) return thought;
    const mood = String(s.mood ?? "").trim();
    const st = String(s.state ?? "").trim();
    if (mood && st) return `${mood}\n${st}`;
    if (mood || st) return mood || st;
    const ad = String(s.affectionDesc ?? "").trim();
    const aff = s.affinity;
    if (typeof aff === "number" && Number.isFinite(aff)) {
      const n = Math.round(aff);
      return ad ? `好感 ${n} · ${ad}` : `好感 ${n}`;
    }
    return ad || "…";
  };

  // 最新在最上
  for (let i = log.length - 1; i >= 0; i--) {
    const m = log[i];
    if (!assistantMatchesHeartVoiceSurface(m, surface)) continue;
    const s = heartVoiceSnapFromAssistantMessage(m);
    if (!heartVoiceSnapHasRenderableContent(s)) continue;
    const li = document.createElement("li");
    li.className = "chat-inner-voice-history-screen-item";
    li.setAttribute("role", "option");
    li.dataset.logIdx = String(i);
    if (i === chatInnerVoiceBrowseAssistantLogIdx) li.classList.add("is-active");
    const voiceEl = document.createElement("span");
    voiceEl.className = "chat-inner-voice-history-screen-voice";
    voiceEl.textContent = listVoicePlain(s);
    li.appendChild(voiceEl);
    li.addEventListener("click", () => {
      openHistoryInnerVoiceInMemoSheet(i);
    });
    ul.appendChild(li);
  }
}

async function rerollChatInnerVoiceForBrowseTarget() {
  if (!isThreadHeartVoiceEnabled(readActiveThread())) {
    showToast("本密谈已关闭心声");
    return;
  }
  const ai = window.RP_AI;
  if (!ai) {
    showToast("AI 模块未加载");
    return;
  }
  const log0 = readChatLog();
  const surface = getActiveChatDmSurfaceForContext();
  let ti = chatInnerVoiceBrowseAssistantLogIdx;
  if (
    !(
      Number.isFinite(ti) &&
      ti >= 0 &&
      ti < log0.length &&
      assistantMatchesHeartVoiceSurface(log0[ti], surface)
    )
  ) {
    ti = -1;
    for (let j = log0.length - 1; j >= 0; j--) {
      if (assistantMatchesHeartVoiceSurface(log0[j], surface)) {
        ti = j;
        break;
      }
    }
  }
  if (ti < 0 || !log0[ti] || log0[ti].role !== "assistant") {
    showToast("没有可重 roll 的对方气泡");
    return;
  }
  const capRoot = document.getElementById("chat-char-inner-voice");
  const btn = document.getElementById("chat-inner-voice-reroll");
  capRoot?.classList.add("is-inner-voice-rerolling");
  capRoot?.setAttribute("aria-busy", "true");
  if (btn) btn.disabled = true;
  try {
    const msgs = buildHeartVoiceRerollApiMessages(ti);
    let data;
    try {
      data = await ai.chatCompletions({
        messages: msgs,
        max_tokens: 1536,
        response_format: { type: "json_object" }
      });
    } catch (_) {
      data = await ai.chatCompletions({
        messages: msgs,
        max_tokens: 1536
      });
    }
    rememberChatApiUsage(data?.usage);
    updateChatContextTokenLabel();
    let raw = readChatCompletionChoiceText(data);
    if (!raw.trim()) {
      try {
        const data2 = await ai.chatCompletions({
          messages: msgs,
          max_tokens: 1536
        });
        rememberChatApiUsage(data2?.usage);
        updateChatContextTokenLabel();
        raw = readChatCompletionChoiceText(data2);
      } catch (_) {
        /* ignore */
      }
    }
    if (!raw.trim()) throw new Error(explainModelEmptyReply(data, raw));
    const p = parseChatAssistantPayload(raw);
    if (!String(p.heartVoice || "").trim()) throw new Error("模型未返回 heartVoice");
    if (!patchChatLogAssistantHeartPanelAt(ti, p)) throw new Error("无法写入本地记录");
    chatInnerVoiceBrowseAssistantLogIdx = ti;
    applyChatInnerVoiceSnapshot(readChatInnerVoiceSnapshotForActiveThread());
    renderChatInnerVoiceHistoryList();
    refreshChatAfterLogMutation();
    showToast("心声已重 roll");
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    showToast(`重 roll 失败：${msg}`);
  } finally {
    capRoot?.classList.remove("is-inner-voice-rerolling");
    capRoot?.setAttribute("aria-busy", "false");
    if (btn) {
      const snapAfter = readChatInnerVoiceSnapshotForActiveThread();
      btn.disabled = !!(snapAfter && snapAfter.__emptyNoMessages);
    }
  }
}

function animateAffinityNumberLabel(numEl, to) {
  if (!(numEl instanceof HTMLElement)) return;
  const next = Number(to);
  if (!Number.isFinite(next)) return;
  const prev = Number(numEl.dataset.affPrev);
  const from = Number.isFinite(prev) ? prev : next;
  numEl.dataset.affPrev = String(next);
  if (from === next) {
    numEl.textContent = `${next} / 100`;
    return;
  }
  const start = performance.now();
  const dur = 520;
  const easeOutCubic = (t) => 1 - Math.pow(1 - t, 3);
  const tick = (now) => {
    const p = Math.min(1, Math.max(0, (now - start) / dur));
    const v = Math.round(from + (next - from) * easeOutCubic(p));
    numEl.textContent = `${v} / 100`;
    if (p < 1) window.requestAnimationFrame(tick);
  };
  window.requestAnimationFrame(tick);
}

/**
 * @param {ChatInnerVoiceSnap | null | undefined} snap
 */
function applyChatInnerVoiceSnapshot(snap) {
  const ref = readChatActiveThreadRef();
  const surface = getActiveChatDmSurfaceForContext();
  const browse = chatInnerVoiceBrowseAssistantLogIdx;
  const srcIdx =
    snap && typeof snap === "object" && Number.isFinite(Number(snap.__sourceLogIdx))
      ? Math.floor(Number(snap.__sourceLogIdx))
      : -1;
  const ctxKey = `${ref.maskId}\t${ref.threadId}\t${surface}\t${browse >= 0 ? browse : srcIdx}`;
  const snapKey = heartVoiceSnapDomKey(snap);
  if (ctxKey === chatInnerVoiceSnapContextKey && snapKey === chatInnerVoiceLastAppliedSnapKey) return;
  chatInnerVoiceSnapContextKey = ctxKey;
  chatInnerVoiceLastAppliedSnapKey = snapKey;

  const capRoot = document.getElementById("chat-char-inner-voice");
  const thoughtEl = document.getElementById("chat-inner-voice-thought");
  const stateEl = document.getElementById("chat-inner-voice-state");
  const desireEl = document.getElementById("chat-inner-voice-desire");
  const moodEl = document.getElementById("chat-inner-voice-mood");
  const numEl = document.getElementById("chat-inner-voice-affinity-num");
  const fillEl = document.getElementById("chat-inner-voice-aff-fill");
  const meterEl = document.getElementById("chat-inner-voice-aff-meter");
  const affDescEl = document.getElementById("chat-inner-voice-affinity-desc");
  const rr = document.getElementById("chat-inner-voice-reroll");

  if (snap && snap.__emptyNoMessages) {
    resetChatInnerVoiceDeepReveal();
    const empty = "暂无";
    if (thoughtEl) thoughtEl.textContent = empty;
    if (stateEl) stateEl.textContent = empty;
    if (desireEl) desireEl.textContent = empty;
    if (moodEl) {
      moodEl.textContent = empty;
      moodEl.hidden = false;
    }
    if (numEl) numEl.textContent = "—";
    if (fillEl) fillEl.style.width = "0%";
    if (meterEl) {
      meterEl.setAttribute("data-aff-unknown", "1");
      meterEl.removeAttribute("data-aff-tier");
      meterEl.setAttribute("aria-valuenow", "0");
      meterEl.setAttribute("aria-valuetext", "暂无");
    }
    if (affDescEl) {
      affDescEl.textContent = "";
      affDescEl.hidden = true;
    }
    if (rr && !capRoot?.classList.contains("is-inner-voice-rerolling")) rr.disabled = true;
    return;
  }

  const s = snap && typeof snap === "object" ? snap : {};
  const t = String(s.thought ?? "").trim();
  const st = String(s.state ?? "").trim();
  const d = String(s.desire ?? "").trim();
  const mood = String(s.mood ?? "").trim();
  const hasRealThought = Boolean(t);
  if (thoughtEl) thoughtEl.textContent = t || getChatInnerVoiceThoughtPlaceholder();
  if (stateEl) stateEl.textContent = st || (hasRealThought ? "—" : CHAT_INNER_VOICE_PLACEHOLDER.state);
  if (desireEl) desireEl.textContent = d || (hasRealThought ? "—" : CHAT_INNER_VOICE_PLACEHOLDER.desire);
  if (moodEl) {
    if (mood) moodEl.textContent = mood;
    else if (hasRealThought) moodEl.textContent = "—";
    else moodEl.textContent = CHAT_INNER_VOICE_MOOD_PLACEHOLDER;
    moodEl.hidden = false;
  }
  const aff = s.affinity;
  const hasAff = typeof aff === "number" && Number.isFinite(aff);
  if (hasAff && numEl && fillEl && meterEl) {
    const clamped = Math.max(0, Math.min(100, Math.round(aff)));
    animateAffinityNumberLabel(numEl, clamped);
    fillEl.style.width = `${clamped}%`;
    meterEl.removeAttribute("data-aff-unknown");
    const tier = clamped >= 80 ? "high" : clamped >= 50 ? "mid" : "low";
    meterEl.setAttribute("data-aff-tier", tier);
    meterEl.setAttribute("aria-valuenow", String(clamped));
    meterEl.setAttribute("aria-valuetext", `${clamped} 分`);
    if (affDescEl) {
      const ad = String(s.affectionDesc ?? "").trim();
      affDescEl.textContent = ad || "未知";
      affDescEl.hidden = false;
    }
  } else {
    if (numEl) numEl.textContent = "—";
    if (fillEl) fillEl.style.width = "0%";
    if (meterEl) {
      meterEl.setAttribute("data-aff-unknown", "1");
      meterEl.removeAttribute("data-aff-tier");
      meterEl.setAttribute("aria-valuenow", "0");
      meterEl.setAttribute("aria-valuetext", "未接入");
    }
    if (affDescEl) {
      affDescEl.textContent = "";
      affDescEl.hidden = true;
    }
  }
  if (rr && !capRoot?.classList.contains("is-inner-voice-rerolling")) {
    rr.disabled = false;
  }
}

/** @param {"voice"|"theater"} tab */
function setChatMemoPanelTab(tab) {
  const want = tab === "theater" ? "theater" : "voice";
  const changed = chatInnerVoiceActiveTab !== want;
  chatInnerVoiceActiveTab = want;
  if (changed) {
    if (want === "theater") chatTheaterRerolling = false;
    const tabsRoot = document.getElementById("chat-inner-voice-tabs");
    if (tabsRoot) {
      for (const b of tabsRoot.querySelectorAll(".chat-inner-voice-tab[data-iv-tab]")) {
        if (!(b instanceof HTMLElement)) continue;
        const on = String(b.getAttribute("data-iv-tab") || "") === want;
        b.classList.toggle("is-active", on);
        b.setAttribute("aria-selected", on ? "true" : "false");
      }
    }
    for (const pane of document.querySelectorAll(".chat-inner-voice-pane[data-iv-pane]")) {
      if (!(pane instanceof HTMLElement)) continue;
      const on = String(pane.getAttribute("data-iv-pane") || "") === want;
      pane.hidden = !on;
    }
    const ivRoot = document.getElementById("chat-char-inner-voice");
    if (ivRoot) ivRoot.classList.toggle("is-theater-tab", want === "theater");
    if (want === "theater") syncChatTheaterPanelFromLog();
  }
  syncChatInnerVoicePanelTitle();
  layoutChatInnerVoicePanel();
}

function syncChatMemoPanelTabsVisibility() {
  const th = readActiveThread();
  const hv = isThreadHeartVoiceEnabled(th);
  const thOn = isThreadTheaterEnabled(th);
  const tabsRoot = document.getElementById("chat-inner-voice-tabs");
  const tabVoice = document.getElementById("chat-inner-voice-tab-voice");
  const tabTheater = document.getElementById("chat-inner-voice-tab-theater");
  if (tabVoice instanceof HTMLElement) tabVoice.hidden = !hv;
  if (tabTheater instanceof HTMLElement) tabTheater.hidden = !thOn;
  if (tabsRoot instanceof HTMLElement) {
    tabsRoot.hidden = !(hv && thOn);
  }
  if (!hv && thOn) setChatMemoPanelTab("theater");
  else if (hv && !thOn) setChatMemoPanelTab("voice");
  else if (chatInnerVoiceActiveTab === "theater" && thOn) setChatMemoPanelTab("theater");
  else setChatMemoPanelTab("voice");
}

function getChatTheaterViewPresetId(thread) {
  const enabled = getThreadTheaterEnabledPresetIds(thread);
  const want = String(chatTheaterViewPresetId || "").trim();
  if (want && enabled.includes(want)) return want;
  return enabled[0] || THEATER_BUILTIN_PRESETS[0]?.id || "builtin-diary";
}

function renderChatTheaterViewChips(thread) {
  const root = document.getElementById("chat-theater-view-chips");
  if (!(root instanceof HTMLElement)) return;
  root.replaceChildren();
  const enabled = getThreadTheaterEnabledPresetIds(thread);
  const active = getChatTheaterViewPresetId(thread);
  for (const id of enabled) {
    const preset = getTheaterPresetById(id);
    if (!preset) continue;
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "chip ghost chip-xs chat-theater-view-chip";
    btn.dataset.presetId = id;
    btn.textContent = preset.name;
    btn.setAttribute("role", "tab");
    btn.setAttribute("aria-selected", id === active ? "true" : "false");
    if (id === active) btn.classList.add("is-active");
    btn.addEventListener("click", () => {
      chatTheaterViewPresetId = id;
      chatTheaterBrowseAssistantLogIdx = -1;
      syncChatTheaterPanelFromLog();
    });
    root.appendChild(btn);
  }
}

function renderChatTheaterRerollPicks(thread) {
  const root = document.getElementById("chat-theater-reroll-picks");
  if (!(root instanceof HTMLElement)) return;
  const enabled = getThreadTheaterEnabledPresetIds(thread);
  const key = enabled.join("|");
  if (chatTheaterRerolling) return;
  if (key === chatTheaterRerollPicksKey && root.childElementCount > 0) return;
  const prevChecked = new Set(
    [...root.querySelectorAll('input[data-theater-reroll-pick]:checked')]
      .map((el) => (el instanceof HTMLInputElement ? String(el.value || "").trim() : ""))
      .filter(Boolean)
  );
  chatTheaterRerollPicksKey = key;
  root.replaceChildren();
  if (!enabled.length) return;
  for (const id of enabled) {
    const preset = getTheaterPresetById(id);
    if (!preset) continue;
    const label = document.createElement("label");
    label.className = "chat-theater-reroll-pick";
    const input = document.createElement("input");
    input.type = "checkbox";
    input.value = id;
    input.checked = prevChecked.size ? prevChecked.has(id) : true;
    input.dataset.theaterRerollPick = "1";
    label.appendChild(input);
    label.appendChild(document.createTextNode(preset.name));
    root.appendChild(label);
  }
}

/** @param {unknown} thread */
function syncChatDetailOnlineRomanceUi(thread) {
  const th = thread && typeof thread === "object" ? thread : readActiveThread();
  const btn = document.getElementById("chat-detail-online-romance-toggle");
  const isGroup = isChatThreadGroupForUi(th);
  const romanceOn = isThreadOnlineRomanceEnabled(th);
  if (btn) {
    btn.setAttribute("aria-pressed", romanceOn ? "true" : "false");
    btn.setAttribute("aria-label", romanceOn ? "异地模式：开" : "异地模式：关");
    const field = btn.closest(".chat-detail-field");
    if (field instanceof HTMLElement) {
      field.hidden = isGroup;
      field.style.display = isGroup ? "none" : "";
    }
  }
  const offlineFields = [
    document.getElementById("chat-detail-auto-offline-field"),
    document.getElementById("chat-detail-offline-meet-mode-field")
  ];
  for (const el of offlineFields) {
    if (!(el instanceof HTMLElement)) continue;
    const hide = isGroup || romanceOn;
    el.hidden = hide;
    el.style.display = hide ? "none" : "";
    el.setAttribute("aria-hidden", hide ? "true" : "false");
  }
  syncChatMoreOfflineTavernItem();
}

