/** @param {unknown} thread */
function syncChatDetailTheaterPresetUi() {
  const th = readActiveThread();
  const field = document.getElementById("chat-detail-theater-preset-field");
  const list = document.getElementById("chat-detail-theater-preset-list");
  const resetBtn = document.getElementById("chat-detail-theater-preset-reset");
  const tBtn = document.getElementById("chat-detail-theater-toggle");
  const gapField = document.getElementById("chat-detail-theater-gap-field");
  const gapInput = document.getElementById("chat-detail-theater-prompt-min-gap");
  const gapReset = document.getElementById("chat-detail-theater-gap-reset");
  const gapLead = document.getElementById("chat-detail-theater-gap-lead");
  if (tBtn) {
    const on = isThreadTheaterEnabled(th);
    tBtn.setAttribute("aria-pressed", on ? "true" : "false");
    tBtn.setAttribute("aria-label", on ? "小剧场：开" : "小剧场：关");
  }
  const isGroup = isChatThreadGroupForUi(th);
  if (field) {
    field.hidden = isGroup || !isThreadTheaterEnabled(th);
    field.style.display = field.hidden ? "none" : "";
  }
  if (resetBtn instanceof HTMLButtonElement) {
    resetBtn.hidden = isGroup || !isThreadTheaterEnabled(th) || threadUsesTheaterDefaultPresets(th);
  }
  const theaterOn = !isGroup && isThreadTheaterEnabled(th);
  if (gapField instanceof HTMLElement) {
    gapField.hidden = !theaterOn;
    gapField.style.display = gapField.hidden ? "none" : "";
  }
  if (gapInput instanceof HTMLInputElement) {
    const override = getThreadTheaterPromptMinGap(th);
    const global = readTheaterPromptMinGap();
    gapInput.value = String(override != null ? override : global);
    gapInput.disabled = !theaterOn;
  }
  if (gapReset instanceof HTMLButtonElement) {
    gapReset.hidden = !theaterOn || threadUsesTheaterDefaultPromptMinGap(th);
  }
  if (gapLead instanceof HTMLElement) {
    const global = readTheaterPromptMinGap();
    const override = getThreadTheaterPromptMinGap(th);
    const modeHint = isTheaterMergedWithChat()
      ? "并入聊天时注入完整说明"
      : "单独请求时发起小剧场 API";
    if (override == null) {
      gapLead.textContent = `跟随设置默认（${global} 轮）；距上次有小剧场内容隔满此轮数才${modeHint}。填 0 = 每轮。`;
    } else {
      gapLead.textContent = `本密谈 ${override} 轮；隔满才${modeHint}。填 0 = 每轮。`;
    }
  }
  if (list instanceof HTMLElement && !isGroup) {
    const allIds = listAllTheaterPresets().map((p) => p.id);
    renderTheaterPresetCheckboxList(list, {
      ids: allIds,
      checked: getThreadTheaterEnabledPresetIds(th),
      max: THEATER_MAX_ENABLED_PRESETS,
      namePrefix: "chat-detail-theater",
      showBuiltinLabel: true,
      onChange: (picked) => {
        patchActiveThread((t) => {
          t.theaterEnabledPresetIds = normalizeTheaterEnabledPresetIds(picked, { allowEmpty: true });
          delete t.theaterPresetId;
        });
        chatTheaterRerollPicksKey = "";
        syncChatDetailTheaterPresetUi();
        syncChatTheaterPanelFromLog();
      }
    });
  }
}

function readChatTheaterSnapshotForActiveThread() {
  const th = readActiveThread();
  if (!isThreadTheaterEnabled(th)) return null;
  const presetId = getChatTheaterViewPresetId(th);
  const log = readChatLog();
  const surface = getActiveChatDmSurfaceForContext();
  const b = chatTheaterBrowseAssistantLogIdx;
  if (
    Number.isFinite(b) &&
    b >= 0 &&
    b < log.length &&
    log[b]?.role === "assistant" &&
    assistantMatchesHeartVoiceSurface(log[b], surface)
  ) {
    return theaterSnapFromAssistantMessage(log[b], presetId);
  }
  for (let i = log.length - 1; i >= 0; i--) {
    const m = log[i];
    if (!assistantMatchesHeartVoiceSurface(m, surface)) continue;
    if (isAssistantTypingPlaceholder(m)) continue;
    const snap = theaterSnapFromAssistantMessage(m, presetId);
    if (theaterSnapHasRenderableContent(snap) || (snap && snap.pending)) return snap;
  }
  return null;
}

function resolveChatTheaterTargetAssistantIdx() {
  const log = readChatLog();
  const surface = getActiveChatDmSurfaceForContext();
  let idx = chatTheaterBrowseAssistantLogIdx;
  if (
    Number.isFinite(idx) &&
    idx >= 0 &&
    idx < log.length &&
    log[idx]?.role === "assistant" &&
    assistantMatchesHeartVoiceSurface(log[idx], surface)
  ) {
    return idx;
  }
  return findLastAssistantLogIdxForHeartVoicePanel(log, surface);
}

/** @param {"empty"|"text"|"html"} mode */
function syncChatTheaterContentLayoutClass(mode) {
  const ivRoot = document.getElementById("chat-char-inner-voice");
  if (!(ivRoot instanceof HTMLElement)) return;
  ivRoot.classList.toggle("is-theater-html", mode === "html");
  if (isChatCharInnerVoiceOpen() && chatInnerVoiceActiveTab === "theater") layoutChatInnerVoicePanel();
}

/** @param {unknown} th */
function updateChatTheaterEmptyHint(th) {
  const emptyEl = document.getElementById("chat-theater-empty");
  if (!(emptyEl instanceof HTMLElement) || emptyEl.hidden) return;
  const log = readChatLog();
  const gap = resolveTheaterPromptMinGap(th);
  const turns = countAssistantTurnsSinceLastTheaterInLog(log);
  if (gap <= 0) {
    emptyEl.textContent =
      "按间隔设置自动生成本轮小剧场；打开此处只查看。尚无内容时可等下一轮，或勾选预设后点「重 roll」。";
    return;
  }
  const nextTurn = turns + 1;
  if (nextTurn >= gap) {
    emptyEl.textContent = `已隔 ${turns} 轮（下一轮起应触发小剧场，间隔 ${gap} 轮）。若仍无内容可点「重 roll」。`;
    return;
  }
  emptyEl.textContent = `已隔 ${turns} / ${gap} 轮；隔满后自动生成。尚无内容时可点「重 roll」手动生成。`;
}

/** @param {ReturnType<typeof theaterSnapFromAssistantMessage>} snap */
function applyChatTheaterSnapshotToUi(snap) {
  const textEl = document.getElementById("chat-theater-text");
  const frame = document.getElementById("chat-theater-html-frame");
  const emptyEl = document.getElementById("chat-theater-empty");
  const rerollBtn = document.getElementById("chat-theater-reroll");
  if (rerollBtn instanceof HTMLButtonElement) {
    rerollBtn.disabled = chatTheaterRerolling;
    rerollBtn.textContent = chatTheaterRerolling ? "生成中…" : "重 roll";
  }
  let layoutMode = "empty";
  if (!snap) {
    if (textEl instanceof HTMLElement) textEl.hidden = true;
    if (frame instanceof HTMLIFrameElement) {
      frame.hidden = true;
      frame.removeAttribute("srcdoc");
    }
    if (emptyEl instanceof HTMLElement) emptyEl.hidden = false;
    syncChatTheaterContentLayoutClass(layoutMode);
    return;
  }
  if (snap.pending) {
    if (textEl instanceof HTMLElement) {
      textEl.hidden = false;
      textEl.textContent = "（小剧场生成中…）";
    }
    if (frame instanceof HTMLIFrameElement) {
      frame.hidden = true;
      frame.removeAttribute("srcdoc");
    }
    if (emptyEl instanceof HTMLElement) emptyEl.hidden = true;
    syncChatTheaterContentLayoutClass("text");
    return;
  }
  const err = String(snap?.error || "").trim();
  if (err) {
    if (textEl instanceof HTMLElement) {
      textEl.hidden = false;
      textEl.textContent = `（生成失败：${err}）`;
    }
    if (frame instanceof HTMLIFrameElement) {
      frame.hidden = true;
      frame.removeAttribute("srcdoc");
    }
    if (emptyEl instanceof HTMLElement) emptyEl.hidden = true;
    syncChatTheaterContentLayoutClass("text");
    return;
  }
  if (snap?.kind === "html") {
    const html = String(snap.html || "").trim();
    if (frame instanceof HTMLIFrameElement) {
      frame.hidden = !html;
      frame.srcdoc = html ? theaterWrapHtmlDocument(html) : "";
    }
    if (textEl instanceof HTMLElement) textEl.hidden = true;
    if (emptyEl instanceof HTMLElement) emptyEl.hidden = Boolean(html);
    layoutMode = html ? "html" : "empty";
  } else {
    const text = String(snap?.text || "").trim();
    if (textEl instanceof HTMLElement) {
      textEl.hidden = !text;
      textEl.textContent = text || "";
    }
    if (frame instanceof HTMLIFrameElement) {
      frame.hidden = true;
      frame.removeAttribute("srcdoc");
    }
    if (emptyEl instanceof HTMLElement) emptyEl.hidden = Boolean(text);
    layoutMode = text ? "text" : "empty";
  }
  syncChatTheaterContentLayoutClass(layoutMode);
}

function renderChatTheaterHistoryList() {
  const ul = document.getElementById("chat-theater-history-list");
  const box = document.getElementById("chat-theater-history");
  if (!(ul instanceof HTMLElement)) return;
  ul.replaceChildren();
  const th = readActiveThread();
  if (!isThreadTheaterEnabled(th)) return;
  const presetId = getChatTheaterViewPresetId(th);
  const surface = getActiveChatDmSurfaceForContext();
  const log = readChatLog();
  for (let i = log.length - 1; i >= 0; i--) {
    const m = log[i];
    if (!assistantMatchesHeartVoiceSurface(m, surface)) continue;
    const snap = theaterSnapFromAssistantMessage(m, presetId);
    if (!theaterSnapHasRenderableContent(snap)) continue;
    const li = document.createElement("li");
    li.className = "chat-theater-history-item";
    li.dataset.logIdx = String(i);
    if (i === chatTheaterBrowseAssistantLogIdx) li.classList.add("is-active");
    const preview =
      snap.kind === "html"
        ? String(snap.html || "")
            .replace(/<[^>]+>/g, " ")
            .replace(/\s+/g, " ")
            .trim()
            .slice(0, 120)
        : String(snap.text || "").trim().slice(0, 160);
    const when = snap.at
      ? new Date(snap.at).toLocaleString("zh-CN", {
          month: "numeric",
          day: "numeric",
          hour: "2-digit",
          minute: "2-digit"
        })
      : "";
    li.textContent = when ? `${when} · ${preview || "…"}` : preview || "…";
    li.addEventListener("click", () => {
      chatTheaterBrowseAssistantLogIdx = i;
      applyChatTheaterSnapshotToUi(theaterSnapFromAssistantMessage(log[i], presetId));
      renderChatTheaterHistoryList();
    });
    ul.appendChild(li);
  }
  if (box instanceof HTMLElement) box.hidden = !chatTheaterHistoryOpen;
}

function syncChatTheaterPanelFromLog() {
  if (!document.getElementById("chat-theater-body")) return;
  const th = readActiveThread();
  if (!isThreadTheaterEnabled(th)) {
    chatTheaterBrowseAssistantLogIdx = -1;
    applyChatTheaterSnapshotToUi(null);
    return;
  }
  const log = readChatLog();
  const surface = getActiveChatDmSurfaceForContext();
  const b = chatTheaterBrowseAssistantLogIdx;
  if (
    b >= 0 &&
    (b >= log.length ||
      !log[b] ||
      log[b].role !== "assistant" ||
      !assistantMatchesHeartVoiceSurface(log[b], surface))
  ) {
    chatTheaterBrowseAssistantLogIdx = -1;
  }
  renderChatTheaterViewChips(th);
  renderChatTheaterRerollPicks(th);
  chatTheaterViewPresetId = getChatTheaterViewPresetId(th);
  applyChatTheaterSnapshotToUi(readChatTheaterSnapshotForActiveThread());
  updateChatTheaterEmptyHint(th);
  if (chatTheaterHistoryOpen) renderChatTheaterHistoryList();
}

/** 每轮渲染会话后：心声 / 小剧场面板与 log 对齐。 */
function syncChatInnerVoicePanelFromLog() {
  if (!document.getElementById("chat-inner-voice-thought")) return;
  const th = readActiveThread();
  const hvOn = isThreadHeartVoiceEnabled(th);
  const thOn = isThreadTheaterEnabled(th);
  if (!hvOn) {
    chatInnerVoiceBrowseAssistantLogIdx = -1;
    chatInnerVoiceSnapContextKey = "";
    chatInnerVoiceLastAppliedSnapKey = "";
    closeChatInnerVoiceHistoryScreen();
    applyChatInnerVoiceSnapshot(null);
    syncChatInnerVoiceHeroAvatar();
  } else {
    const log = readChatLog();
    const surface = getActiveChatDmSurfaceForContext();
    const b = chatInnerVoiceBrowseAssistantLogIdx;
    if (
      b >= 0 &&
      (b >= log.length ||
        !log[b] ||
        log[b].role !== "assistant" ||
        !assistantMatchesHeartVoiceSurface(log[b], surface))
    ) {
      chatInnerVoiceBrowseAssistantLogIdx = -1;
    }
    applyChatInnerVoiceSnapshot(readChatInnerVoiceSnapshotForActiveThread());
    syncChatInnerVoiceHeroAvatar();
    if (isChatInnerVoiceHistoryScreenOpen()) renderChatInnerVoiceHistoryList();
  }
  if (thOn) syncChatTheaterPanelFromLog();
  if (isChatCharInnerVoiceOpen()) syncChatMemoPanelTabsVisibility();
}

function isChatCharInnerVoiceOpen() {
  const el = document.getElementById("chat-char-inner-voice");
  return !!(el && !el.hidden);
}

function syncChatInnerVoiceHeroAvatar() {
  const hero = document.getElementById("chat-inner-voice-hero");
  const heroImg = document.getElementById("chat-inner-voice-hero-img");
  if (!(hero instanceof HTMLElement) || !(heroImg instanceof HTMLImageElement)) return;
  hero.hidden = true;
  heroImg.removeAttribute("src");
  heroImg.alt = "";
}

/**
 * @param {HTMLElement | null} [fromEl]
 * @param {{ browseAssistantLogIdx?: number, memoTab?: "voice"|"theater" }} [opts]
 */
function openChatCharInnerVoicePanel(fromEl, opts) {
  const thHv = readActiveThread();
  if (!isThreadMemoPanelAvailable(thHv)) {
    if (thHv?.kind !== "group") showToast("本密谈已关闭心声与小剧场（在密谈详情 · 卷宗里可开启）");
    return;
  }
  reparentChatInnerVoiceShellsForActiveSurface();
  if (isChatBubbleActionSheetOpen()) closeChatBubbleActionSheet();
  closeChatCharRecallPeekPanel();
  closeChatCallTranscriptPeek();
  closeChatInnerVoiceHistoryScreen();
  chatTheaterHistoryOpen = false;
  const histBox = document.getElementById("chat-theater-history");
  if (histBox) histBox.hidden = true;
  const root = document.getElementById("chat-char-inner-voice");
  if (!root) return;
  resetChatInnerVoiceDeepReveal();
  const br = opts && opts.browseAssistantLogIdx;
  if (Number.isFinite(br) && br >= 0) {
    chatInnerVoiceBrowseAssistantLogIdx = Math.floor(br);
    chatTheaterBrowseAssistantLogIdx = Math.floor(br);
  } else {
    chatInnerVoiceBrowseAssistantLogIdx = -1;
    chatTheaterBrowseAssistantLogIdx = -1;
  }
  if (opts?.memoTab === "theater" && isThreadTheaterEnabled(thHv)) chatInnerVoiceActiveTab = "theater";
  else if (!isThreadHeartVoiceEnabled(thHv)) chatInnerVoiceActiveTab = "theater";
  else if (!isThreadTheaterEnabled(thHv)) chatInnerVoiceActiveTab = "voice";
  syncChatMemoPanelTabsVisibility();
  if (isThreadHeartVoiceEnabled(thHv)) {
    applyChatInnerVoiceSnapshot(readChatInnerVoiceSnapshotForActiveThread());
  } else {
    applyChatInnerVoiceSnapshot(null);
  }
  syncChatInnerVoiceHeroAvatar();
  if (isThreadTheaterEnabled(thHv)) syncChatTheaterPanelFromLog();
  chatInnerVoiceLastFocusEl = fromEl instanceof HTMLElement ? fromEl : null;
  root.classList.add("is-open");
  root.hidden = false;
  root.setAttribute("aria-hidden", "false");
  syncChatScreenThemeGlassClass();
  bindChatInnerVoiceLayoutListeners();
  window.requestAnimationFrame(() => {
    layoutChatInnerVoicePanel();
    document.getElementById("chat-inner-voice-close")?.focus();
  });
}

function closeChatCharInnerVoicePanel() {
  const root = document.getElementById("chat-char-inner-voice");
  if (!root) return;
  root.classList.remove("is-inner-voice-rerolling");
  root.classList.remove("is-theater-tab");
  root.classList.remove("is-theater-html");
  chatTheaterRerolling = false;
  root.setAttribute("aria-busy", "false");
  window.clearTimeout(chatInnerVoiceLayoutTimer);
  chatInnerVoiceLayoutTimer = 0;
  unbindChatInnerVoiceLayoutListeners();
  clearChatInnerVoicePanelLayout();
  root.classList.remove("is-open");
  root.hidden = true;
  root.setAttribute("aria-hidden", "true");
  const prev = chatInnerVoiceLastFocusEl;
  chatInnerVoiceLastFocusEl = null;
  reparentChatInnerVoiceShellsForActiveSurface();
  syncChatScreenOverlayOpenClass();
  window.requestAnimationFrame(() => prev?.focus?.());
}

function isChatCharRecallPeekOpen() {
  const el = document.getElementById("chat-char-recall-peek");
  return !!(el && !el.hidden);
}

function closeChatCharRecallPeekPanel() {
  const root = document.getElementById("chat-char-recall-peek");
  if (!root) return;
  root.classList.remove("is-open");
  root.hidden = true;
  root.setAttribute("aria-hidden", "true");
}

/** 可删的归档票根在 log 中的下标（`offline_end` / `call_end`）；不可删时为 -1 */
let chatCallTranscriptPeekDeletableLogIdx = -1;

function isChatCallTranscriptPeekOpen() {
  const el = document.getElementById("chat-call-transcript-peek");
  return !!(el && !el.hidden);
}

function syncChatCallTranscriptPeekDeleteBtn() {
  const btn = document.getElementById("chat-call-transcript-peek-delete");
  if (!btn) return;
  const show = chatCallTranscriptPeekDeletableLogIdx >= 0;
  btn.hidden = !show;
  btn.setAttribute("aria-hidden", show ? "false" : "true");
}

function closeChatCallTranscriptPeek() {
  const root = document.getElementById("chat-call-transcript-peek");
  if (!root) return;
  root.classList.remove("is-open");
  root.hidden = true;
  root.setAttribute("aria-hidden", "true");
  const body = document.getElementById("chat-call-transcript-peek-body");
  if (body) body.innerHTML = "";
  const titleEl = document.getElementById("chat-call-transcript-peek-title");
  if (titleEl) titleEl.textContent = "通话记录";
  chatCallTranscriptPeekDeletableLogIdx = -1;
  syncChatCallTranscriptPeekDeleteBtn();
}

/** @param {unknown} m */
function isDeletableChatTranscriptArchiveNotice(m) {
  return isChatNoticeOfflineEndedMessage(m) || isChatNoticeCallEndedMessage(m);
}

/** @param {unknown} m */
function confirmDeleteTranscriptArchiveNoticeText(m) {
  if (isChatNoticeOfflineEndedMessage(m)) {
    return "确定删除这场晤面归档？时间线上的「晤面已结束」条目会一并移除，不可恢复。";
  }
  if (isChatNoticeCallEndedMessage(m)) {
    const kind = String(/** @type {{ callMode?: string }} */ (m).callMode || "") === "video" ? "视频" : "语音";
    const hasTranscript =
      Array.isArray(/** @type {{ callTranscript?: unknown[] }} */ (m).callTranscript) &&
      /** @type {{ callTranscript?: unknown[] }} */ (m).callTranscript.length > 0;
    if (hasTranscript) {
      return `确定删除这场${kind}通话归档？通话卡片与「通话结束」条目会一并移除，不可恢复。`;
    }
    return `确定删除这场${kind}通话记录？误触或未接通的记录也会从聊天里移除，不可恢复。`;
  }
  return "";
}

/** @param {unknown} m */
function toastAfterDeleteTranscriptArchiveNotice(m) {
  if (isChatNoticeOfflineEndedMessage(m)) return "已删除当面记录";
  if (isChatNoticeCallEndedMessage(m)) return "已删除通话记录";
  return "已删除";
}

/** @param {number} logIdx */
function deleteChatTranscriptArchiveNoticeAt(logIdx) {
  const i = Math.floor(Number(logIdx));
  const log = readChatLog();
  if (!Number.isFinite(i) || i < 0 || i >= log.length) {
    showToast("记录已变化");
    return false;
  }
  const m = log[i];
  if (!isDeletableChatTranscriptArchiveNotice(m)) {
    showToast("无法删除");
    return false;
  }
  if (!deleteChatMessageAt(i)) {
    showToast("删除失败");
    return false;
  }
  closeChatCallTranscriptPeek();
  refreshChatAfterLogMutation();
  showToast(toastAfterDeleteTranscriptArchiveNotice(m));
  return true;
}

/**
 * @param {{ checkupReport?: string, caught?: boolean, checkupReason?: string, checkupQuestion?: string, isReverseFinish?: boolean, isForwardFinish?: boolean, userKicked?: boolean, kickedOut?: boolean }} notice
 */
function openChatCheckupFinishPeek(notice) {
  closeChatBubbleActionSheet();
  closeChatCharRecallPeekPanel();
  closeChatInnerVoiceHistoryScreen();
  chatCallTranscriptPeekDeletableLogIdx = -1;
  const root = document.getElementById("chat-call-transcript-peek");
  if (!root) return;
  const titleEl = document.getElementById("chat-call-transcript-peek-title");
  if (titleEl) {
    if (notice && notice.isReverseFinish) {
      titleEl.textContent = notice.userKicked ? "反向查岗 · 被打断" : "反向查岗 · 已翻看";
    } else if (notice && notice.isForwardFinish) {
      titleEl.textContent = notice.kickedOut ? "查岗结案 · 被打断" : "查岗结案 · 已翻看";
    } else {
      titleEl.textContent = "查岗结案";
    }
  }
  const body = document.getElementById("chat-call-transcript-peek-body");
  if (!(body instanceof HTMLElement)) return;
  body.innerHTML = "";
  const report = String(notice?.checkupReport || "").trim();
  if (report) {
    const reportEl = document.createElement("div");
    reportEl.className = "chat-char-lock-peek-report";
    reportEl.style.whiteSpace = "pre-wrap";
    reportEl.textContent = report;
    body.appendChild(reportEl);
  } else {
    body.textContent = "（无结案内容）";
  }
  syncChatCallTranscriptPeekDeleteBtn();
  root.hidden = false;
  root.setAttribute("aria-hidden", "false");
  window.requestAnimationFrame(() => {
    root.classList.add("is-open");
    document.getElementById("chat-call-transcript-peek-dismiss")?.focus?.();
  });
}

/**
 * @param {{ checkupReport?: string, caught?: boolean, checkupReason?: string, checkupQuestion?: string }} notice
 */
function openChatCharLockSessionPeek(notice) {
  closeChatBubbleActionSheet();
  closeChatCharRecallPeekPanel();
  closeChatInnerVoiceHistoryScreen();
  chatCallTranscriptPeekDeletableLogIdx = -1;
  const root = document.getElementById("chat-call-transcript-peek");
  if (!root) return;
  const titleEl = document.getElementById("chat-call-transcript-peek-title");
  if (titleEl) titleEl.textContent = "锁屏记录";
  const body = document.getElementById("chat-call-transcript-peek-body");
  if (!(body instanceof HTMLElement)) return;
  body.innerHTML = "";
  const report = String(notice?.charLockReport || "").trim();
  if (report) {
    const reportEl = document.createElement("div");
    reportEl.className = "chat-char-lock-peek-report";
    reportEl.style.whiteSpace = "pre-wrap";
    reportEl.style.marginBottom = "0.75rem";
    reportEl.textContent = report;
    body.appendChild(reportEl);
  }
  const rows = Array.isArray(notice?.charLockTranscript) ? notice.charLockTranscript : [];
  if (rows.length) {
    const listWrap = document.createElement("div");
    listWrap.className = "call-transcript-list";
    const thChat = readActiveThread();
    const userM = readUserMask();
    renderCallTranscriptRowsInto(listWrap, rows, {
      charName: getChatCharPersonaDisplayName(),
      userLabel: String(userM?.displayName || "").trim() || "你",
      transThreadOn: isThreadCharTranslationEnabled(thChat)
    });
    body.appendChild(listWrap);
  } else if (!report) {
    body.textContent = "（本场无归档内容）";
  }
  syncChatCallTranscriptPeekDeleteBtn();
  root.hidden = false;
  root.setAttribute("aria-hidden", "false");
  window.requestAnimationFrame(() => {
    root.classList.add("is-open");
    document.getElementById("chat-call-transcript-peek-dismiss")?.focus?.();
  });
}

/**
 * @param {unknown[]} transcriptRows
 * @param {string} [peekTitle]
 * @param {number} [deletableLogIdx] `offline_end` / `call_end` 票根在 log 中的下标，供弹层内删除
 */
function openChatCallTranscriptPeek(transcriptRows, peekTitle, deletableLogIdx) {
  closeChatBubbleActionSheet();
  closeChatCharRecallPeekPanel();
  closeChatInnerVoiceHistoryScreen();
  const delIdx = Math.floor(Number(deletableLogIdx));
  let canDel = Number.isFinite(delIdx) && delIdx >= 0;
  if (canDel) {
    const log = readChatLog();
    const m = log[delIdx];
    canDel = isDeletableChatTranscriptArchiveNotice(m);
  }
  chatCallTranscriptPeekDeletableLogIdx = canDel ? delIdx : -1;
  const root = document.getElementById("chat-call-transcript-peek");
  if (!root) return;
  const titleEl = document.getElementById("chat-call-transcript-peek-title");
  if (titleEl) {
    titleEl.textContent =
      peekTitle != null && String(peekTitle).trim() ? String(peekTitle).trim() : "通话记录";
  }
  const body = document.getElementById("chat-call-transcript-peek-body");
  if (!(body instanceof HTMLElement)) return;
  const rows = Array.isArray(transcriptRows) ? transcriptRows : [];
  const thChat = readActiveThread();
  const userM = readUserMask();
  renderCallTranscriptRowsInto(body, rows, {
    charName: getChatCharPersonaDisplayName(),
    userLabel: String(userM?.displayName || "").trim() || "你",
    transThreadOn: isThreadCharTranslationEnabled(thChat)
  });
  syncChatCallTranscriptPeekDeleteBtn();
  root.hidden = false;
  root.setAttribute("aria-hidden", "false");
  window.requestAnimationFrame(() => {
    root.classList.add("is-open");
    document.getElementById("chat-call-transcript-peek-dismiss")?.focus?.();
  });
}

function openChatCharRecallPeekPanel(msgIdx) {
  closeChatBubbleActionSheet();
  closeChatCallTranscriptPeek();
  closeChatInnerVoiceHistoryScreen();
  const root = document.getElementById("chat-char-recall-peek");
  if (!root) return;
  const log = readChatLog();
  const i = Number(msgIdx);
  if (!Number.isFinite(i) || i < 0 || i >= log.length) return;
  const m = log[i];
  if (!isChatNoticeRecallCharMessage(m)) return;
  const bodyEl = document.getElementById("chat-char-recall-peek-body");
  const voiceEl = document.getElementById("chat-char-recall-peek-voice");
  const voiceK = document.getElementById("chat-char-recall-peek-voice-k");
  const titleEl = document.getElementById("chat-char-recall-peek-title");
  const nm = getChatCharPersonaDisplayName();
  if (titleEl) titleEl.textContent = `${nm} · 撤回存档`;
  const raw = String(m.recalledContent ?? "");
  const iv = String(m.innerVoice ?? "").trim();
  const th = readActiveThread();
  const transOn = isThreadCharTranslationEnabled(th);
  const cachedTr = String(m.recalledTranslation ?? "").trim();
  const renderBody = (orig, tr) => {
    const o = String(orig ?? "");
    const t = String(tr ?? "").trim();
    if (!o.trim()) return "（无正文存档）";
    if (!transOn || !t) return o;
    const clip = t.length > 120 ? `${t.slice(0, 120)}…` : t;
    return `${o}（${clip}）`;
  };
  if (bodyEl) bodyEl.textContent = renderBody(raw, cachedTr);
  if (voiceEl && voiceK) {
    const has = Boolean(iv);
    voiceK.hidden = !has;
    voiceEl.hidden = !has;
    voiceEl.textContent = has ? iv : "";
  }
  root.hidden = false;
  root.setAttribute("aria-hidden", "false");
  window.requestAnimationFrame(() => {
    root.classList.add("is-open");
    document.getElementById("chat-char-recall-peek-dismiss")?.focus();
  });
}

/**
 * 晤面配图：长按/右键不进菜单，直接载入生图提示词编辑（线上仍走气泡菜单）。
 * @param {HTMLElement} wrap
 * @param {Element} bubbleEl
 * @returns {boolean}
 */
function tryBeginOfflineImageGenEditOnLongPress(wrap, bubbleEl) {
  if (getActiveChatDmSurfaceForContext() !== "offline") return false;
  if (!wrap || wrap.dataset.chatMsgIdx == null) return false;
  const msgIdx = Math.floor(Number(wrap.dataset.chatMsgIdx));
  const log = readChatLog();
  if (!Number.isFinite(msgIdx) || msgIdx < 0 || msgIdx >= log.length) return false;
  const msg = log[msgIdx];
  if (msg.role !== "user" && msg.role !== "assistant") return false;
  if (!chatMessageHasBubbleImageCard(msg)) return false;

  const photoCard =
    bubbleEl instanceof Element ? bubbleEl.closest(".chat-msg-card--photo") : null;
  if (!(photoCard instanceof Element) || !wrap.contains(photoCard)) return false;

  const n = Number(photoCard.dataset.chatBubbleSeg);
  const segIdx = Number.isFinite(n) ? n : OFFLINE_CHAT_PHOTO_DOM_SEG;
  closeChatBubbleActionSheet();
  performChatBubbleEditLoadComposer(msgIdx, segIdx, null, null);
  return true;
}

/**
 * 与 render / walkChatBubbleSheetDomSegments 一致：从长按命中的 DOM 解析分段号。
 * @param {Element | null} wrap
 * @param {Element | null} bubbleEl
 * @param {Element | null} [pointerTargetEl]
 */
function resolveBubbleSheetSegIdxFromTarget(wrap, bubbleEl, pointerTargetEl) {
  const pt = pointerTargetEl instanceof Element ? pointerTargetEl : null;
  const be = bubbleEl instanceof Element ? bubbleEl : null;
  if (wrap instanceof Element) {
    for (const start of [pt, be]) {
      if (!start || !wrap.contains(start)) continue;
      const host = start.closest("[data-chat-bubble-seg]");
      if (host instanceof Element && wrap.contains(host)) {
        const n = Number(host.dataset.chatBubbleSeg);
        if (Number.isFinite(n)) return Math.max(0, Math.floor(n));
      }
    }
    const qtRoot =
      be instanceof Element ? be.closest(".chat-msg-bubble--composer-quote") : null;
    if (qtRoot && wrap.contains(qtRoot)) {
      const qEl = qtRoot.querySelector(".chat-msg-bubble-quote");
      const bodyEl = qtRoot.querySelector(
        ".chat-msg-bubble-body:not(.chat-msg-bubble-body--translation)"
      );
      const inQuote = pt instanceof Element && qEl instanceof Element && qEl.contains(pt);
      const inBody = pt instanceof Element && bodyEl instanceof Element && bodyEl.contains(pt);
      if (inQuote && qEl?.dataset.chatBubbleSeg != null && qEl.dataset.chatBubbleSeg !== "") {
        const n = Number(qEl.dataset.chatBubbleSeg);
        if (Number.isFinite(n)) return Math.max(0, Math.floor(n));
      }
      if (inBody && bodyEl?.dataset.chatBubbleSeg != null && bodyEl.dataset.chatBubbleSeg !== "") {
        const n = Number(bodyEl.dataset.chatBubbleSeg);
        if (Number.isFinite(n)) return Math.max(0, Math.floor(n));
      }
      const bn = bodyEl ? Number(bodyEl.dataset.chatBubbleSeg) : NaN;
      if (Number.isFinite(bn)) return Math.max(0, Math.floor(bn));
      return 1;
    }
    const stack = wrap.querySelector(":scope .chat-msg-bubble-stack");
    if (stack instanceof Element && be) {
      const hit = be.closest(".chat-msg-bubble, .chat-msg-card");
      if (hit instanceof Element && stack.contains(hit)) {
        if (hit.dataset.chatBubbleSeg != null && hit.dataset.chatBubbleSeg !== "") {
          const n = Number(hit.dataset.chatBubbleSeg);
          if (Number.isFinite(n)) return Math.max(0, Math.floor(n));
        }
        const segs = Array.from(
          stack.querySelectorAll(":scope > .chat-msg-bubble, :scope > .chat-msg-card")
        );
        const ix = segs.indexOf(hit);
        if (ix >= 0) return ix;
      }
    }
  }
  return 0;
}

/** @param {Element | null} wrap @param {number} msgIdx @param {unknown[]} log */
function chatBubbleActionMsgIdxMatchesWrap(wrap, msgIdx, log) {
  const i = Math.floor(Number(msgIdx));
  if (!Number.isFinite(i) || i < 0 || i >= log.length) return false;
  const m = log[i];
  if (!m || typeof m !== "object") return false;
  if (!(wrap instanceof HTMLElement)) return false;
  const domIdx = Number(wrap.dataset.chatMsgIdx);
  if (!Number.isFinite(domIdx) || Math.floor(domIdx) !== i) return false;
  if (isChatNoticeCallEndedMessage(m)) {
    return (
      wrap.classList.contains("chat-msg--call-ended-notice") &&
      (wrap.classList.contains("chat-msg--user") || wrap.classList.contains("chat-msg--assistant"))
    );
  }
  if (m.role !== "user" && m.role !== "assistant") return false;
  if (m.role === "user" && !wrap.classList.contains("chat-msg--user")) return false;
  if (
    m.role === "assistant" &&
    !wrap.classList.contains("chat-msg--assistant") &&
    !wrap.classList.contains("chat-msg--group-assistant")
  ) {
    return false;
  }
  return true;
}

/** 玻璃主题旁侧头像不在气泡内；长按头像/时间时落到同行的 card / voice / bubble。 */
function resolveChatLongPressBubbleFromTarget(pt) {
  if (!(pt instanceof Element)) return null;
  const reveal = pt.closest(".chat-voice-reveal");
  if (reveal instanceof Element) {
    const prev = reveal.previousElementSibling;
    if (prev instanceof Element && prev.classList.contains("chat-msg-bubble--voice")) return prev;
  }
  const direct = pt.closest(".chat-msg-bubble, .chat-msg-card, .chat-msg-narration");
  if (direct) return direct;
  if (!isChatScreenThemeGlassActive()) return null;
  const avHit = pt.closest(".chat-msg-avatar, .chat-msg-avatar-col, .chat-msg-meta");
  if (!avHit) return null;
  const scope = avHit.closest(".chat-msg-glass-line") || avHit.closest(".chat-msg-inner");
  const stack = scope?.querySelector(".chat-msg-bubble-stack");
  if (!stack) return null;
  return (
    stack.querySelector(":scope > .chat-msg-card") ||
    stack.querySelector(":scope > .chat-msg-bubble--voice") ||
    stack.querySelector(":scope > .chat-msg-bubble")
  );
}

/** @param {Element} narrEl */
function openChatNarrationActionSheet(narrEl) {
  if (chatMsgMultiSelectMode) return;
  if (!(narrEl instanceof Element) || !narrEl.classList.contains("chat-msg-narration")) return;
  if (isChatCharInnerVoiceOpen()) closeChatCharInnerVoicePanel();
  closeChatCharRecallPeekPanel();
  closeChatCallTranscriptPeek();
  closeChatInnerVoiceHistoryScreen();
  const el = document.getElementById("chat-bubble-actions");
  const previewEl = document.getElementById("chat-bubble-actions-preview");
  if (!el) return;
  const sheetMsgIdx = Math.floor(Number(narrEl.dataset.chatMsgIdx));
  const logForSheet = readChatLog();
  if (!Number.isFinite(sheetMsgIdx) || sheetMsgIdx < 0 || sheetMsgIdx >= logForSheet.length) return;
  const sheetMsg = logForSheet[sheetMsgIdx];
  if (!sheetMsg || sheetMsg.role !== "assistant" || !assistantNarrationPlainOneLine(sheetMsg)) return;
  const wrap = resolveChatLongPressActionWrap(narrEl);
  if (wrap && !chatBubbleActionMsgIdxMatchesWrap(wrap, sheetMsgIdx, logForSheet)) return;
  chatBubbleActionAnchorEl = narrEl;
  syncChatBubbleActionButtonsForBubble(narrEl);
  el.dataset.msgIdx = String(sheetMsgIdx);
  el.dataset.bubbleSegIdx = String(CHAT_NARRATION_SHEET_SEG);
  delete el.dataset.bubbleIsSticker;
  delete el.dataset.bubbleStickerUrl;
  delete el.dataset.quoteBubbleSeg;
  delete el.dataset.bodyBubbleSeg;
  delete el.dataset.voicePartIdx;
  const prev = assistantNarrationPlainOneLine(sheetMsg).slice(0, 72);
  el.dataset.preview = prev;
  if (previewEl) {
    if (prev) {
      previewEl.textContent = `${prev}${prev.length >= 72 ? "…" : ""}`;
      previewEl.hidden = false;
    } else {
      previewEl.textContent = "";
      previewEl.hidden = true;
    }
  }
  el.classList.remove("is-open", "is-positioned");
  el.hidden = false;
  el.setAttribute("aria-hidden", "false");
  if (chatBubbleActionAnchorEl instanceof Element) {
    layoutChatBubbleActionSheet(chatBubbleActionAnchorEl);
  }
  el.classList.add("is-positioned");
  bindChatBubbleSheetDismissOnScroll();
  window.addEventListener("resize", onChatBubbleSheetResize, { passive: true });
  window.requestAnimationFrame(() => {
    if (chatBubbleActionAnchorEl instanceof Element) {
      layoutChatBubbleActionSheet(chatBubbleActionAnchorEl);
    }
    el.classList.add("is-open");
  });
}

/**
 * @param {string|number} msgIdx
 * @param {Element | null} bubbleEl 长按命中的 `.chat-msg-bubble` / `.chat-msg-card` / `.chat-msg-narration`
 * @param {Element | null} [pointerTargetEl] 真实点击目标（用于引用气泡内外分段）
 */
function openChatBubbleActionSheet(msgIdx, bubbleEl, pointerTargetEl) {
  if (chatMsgMultiSelectMode) return;
  if (bubbleEl instanceof Element && bubbleEl.classList.contains("chat-msg-narration")) {
    openChatNarrationActionSheet(bubbleEl);
    return;
  }
  if (isChatCharInnerVoiceOpen()) closeChatCharInnerVoicePanel();
  closeChatCharRecallPeekPanel();
  closeChatCallTranscriptPeek();
  closeChatInnerVoiceHistoryScreen();
  const el = document.getElementById("chat-bubble-actions");
  const previewEl = document.getElementById("chat-bubble-actions-preview");
  if (!el) return;
  const anchorBubble =
    bubbleEl && bubbleEl.nodeType === 1
      ? bubbleEl.closest(".chat-msg-bubble, .chat-msg-card") || bubbleEl
      : null;
  chatBubbleActionAnchorEl = anchorBubble;
  syncChatBubbleActionButtonsForBubble(bubbleEl);
  const wrap = bubbleEl?.closest?.(".chat-msg");
  if (!(wrap instanceof HTMLElement) || wrap.dataset.chatMsgIdx == null) return;
  const logForSheet = readChatLog();
  const sheetMsgIdx = Math.floor(Number(wrap.dataset.chatMsgIdx));
  if (!chatBubbleActionMsgIdxMatchesWrap(wrap, sheetMsgIdx, logForSheet)) return;
  el.dataset.msgIdx = String(sheetMsgIdx);
  const si = resolveBubbleSheetSegIdxFromTarget(
    wrap instanceof Element ? wrap : null,
    bubbleEl instanceof Element ? bubbleEl : null,
    pointerTargetEl instanceof Element ? pointerTargetEl : null
  );
  el.dataset.bubbleSegIdx = String(si);
  if (wrap instanceof HTMLElement) syncQuoteBubbleSegIndicesToSheet(el, wrap);
  const stickerBubble =
    anchorBubble instanceof Element && anchorBubble.classList.contains("chat-msg-bubble--sticker");
  if (stickerBubble) {
    el.dataset.bubbleIsSticker = "1";
    const im = anchorBubble.querySelector("img.chat-sticker-img");
    const src = im instanceof HTMLImageElement ? String(im.currentSrc || im.src || "").trim() : "";
    if (src) el.dataset.bubbleStickerUrl = src;
    else delete el.dataset.bubbleStickerUrl;
  } else {
    delete el.dataset.bubbleIsSticker;
    delete el.dataset.bubbleStickerUrl;
  }
  const sheetMsg =
    Number.isFinite(sheetMsgIdx) && sheetMsgIdx >= 0 && sheetMsgIdx < logForSheet.length
      ? logForSheet[sheetMsgIdx]
      : null;
  const isImageSeg = sheetMsg && isChatBubbleActionSheetImageDomSeg(sheetMsg, si, anchorBubble);
  const prev = isImageSeg
    ? String(getChatImageGenSceneBlockForEdit(sheetMsg) || anchorBubble?.getAttribute("aria-label") || "")
        .replace(/\s+/g, " ")
        .trim()
        .slice(0, 72)
    : (bubbleEl?.textContent || "").replace(/\s+/g, " ").trim().slice(0, 72);
  el.dataset.preview = prev;
  if (previewEl) {
    if (prev) {
      previewEl.textContent = `${prev}${prev.length >= 72 ? "…" : ""}`;
      previewEl.hidden = false;
    } else {
      previewEl.textContent = "";
      previewEl.hidden = true;
    }
  }
  const voiceBubble = resolveVoiceBubbleElFromLongPressTarget(anchorBubble);
  if (voiceBubble) {
    el.dataset.voicePartIdx = String(readVoicePartIdxFromBubbleEl(voiceBubble));
  } else {
    delete el.dataset.voicePartIdx;
  }
  el.classList.remove("is-open", "is-positioned");
  el.hidden = false;
  el.setAttribute("aria-hidden", "false");
  if (chatBubbleActionAnchorEl instanceof Element) {
    layoutChatBubbleActionSheet(chatBubbleActionAnchorEl);
  }
  el.classList.add("is-positioned");
  bindChatBubbleSheetDismissOnScroll();
  window.addEventListener("resize", onChatBubbleSheetResize, { passive: true });
  window.requestAnimationFrame(() => {
    if (chatBubbleActionAnchorEl instanceof Element) {
      layoutChatBubbleActionSheet(chatBubbleActionAnchorEl);
    }
    el.classList.add("is-open");
  });
}

function onChatMessagesPointerDown(e) {
  if (!e.isPrimary) return;
  if (chatMsgMultiSelectMode) return;
  const pt = e.target instanceof Element ? e.target : null;
  if (
    typeof window.XXJ_InlineHtml?.isInteractiveInlineHtmlTarget === "function" &&
    window.XXJ_InlineHtml.isInteractiveInlineHtmlTarget(pt)
  ) {
    return;
  }
  resetChatBubblePressState();
  const b = resolveChatLongPressBubbleFromTarget(pt);
  if (!b) return;
  const wrap = resolveChatLongPressActionWrap(b);
  if (!(wrap instanceof HTMLElement) || wrap.dataset.chatMsgIdx == null) return;
  try {
    const sel = window.getSelection?.();
    if (sel && sel.rangeCount > 0) sel.removeAllRanges();
  } catch {
    /* ignore */
  }
  chatBubblePressAnchor = {
    clientX: e.clientX,
    clientY: e.clientY,
    wrap,
    bubble: b,
    pointerTarget: pt,
    pointerId: e.pointerId,
    swipeQuoteLock: false
  };
  bindChatBubblePressDocListeners();
  window.clearTimeout(chatBubbleLongPressTid);
  chatBubbleLongPressTid = window.setTimeout(() => {
    chatBubbleLongPressTid = 0;
    const anchor = chatBubblePressAnchor;
    if (!anchor || anchor.swipeQuoteLock) return;
    chatBubblePressAnchor = null;
    unbindChatBubblePressDocListeners();
    clearChatBubbleSwipeQuoteVisualFromAnchor(anchor);
    if (tryBeginOfflineImageGenEditOnLongPress(anchor.wrap, anchor.bubble)) return;
    openChatBubbleActionSheet(anchor.wrap.dataset.chatMsgIdx, anchor.bubble, anchor.pointerTarget);
  }, CHAT_BUBBLE_LONG_PRESS_MS);
}

function openChatScreen() {
  let ref = readChatActiveThreadRef();
  if (ref.maskId && ref.threadId) {
    dismissChatNotifyForThread(ref.maskId, ref.threadId, { immediate: true });
  }
  if (!ref.threadId) {
  reconcileActiveThreadRef();
    ref = readChatActiveThreadRef();
    if (!ref.threadId) {
    showToast("请先新建或从列表选择密谈");
    return;
    }
  }
  closeMyScreen();
  closeSettings();
  closeCharScreen();
  closeWorldBookScreen();
  closeMinimaxSheet();
  closeImageGenSheet();
  closeChatDetailImageStyleSheet();
  closeChatThreadDetailPanel({ skipFocusRestore: true });
  closeChatMemoScreen({ skipReturnToThreadDetail: true });
  closeChatBubbleActionSheet();
  clearChatMsgMultiSelectMode({ skipRender: true });
  closeChatCharInnerVoicePanel();
  closeChatCharRecallPeekPanel();
  closeChatCallTranscriptPeek();
  closeChatInnerVoiceHistoryScreen();
  closeStickerScreen();
  closeWardrobeScreen();
  if (isChatOfflineScreenOpen()) {
    closeChatOfflineScreen({ skipShowChat: true });
  }
  reparentChatInnerVoiceShellsForActiveSurface();
  syncChatCloseBackLabel();
  scheduleSyncChatTopbarImgSurfaceBtnClasses();
  const tkForDom = `${ref.maskId}\t${ref.threadId}\t${getActiveChatDmSurfaceForContext()}`;
  if (tkForDom !== chatMessagesListScrollThreadKey) {
    clearChatMessagesDomForThreadSwitch();
  }
  const chatScreen = document.getElementById("chat-screen");
  playStackScreenEnter(chatScreen, () => {
  requestChatStickBottomNextRender();
  void ensureChatInboxForUi().then(async () => {
    await ensureActiveThreadMessagesHydrated();
    ensureCharPersonaMatchesThread(readActiveThread(), { quiet: true });
    updateChatChrome();
    chatSuppressNextChatMessageAnimations = true;
    chatSkipLogNormalizeNextRender = true;
    chatDeferInnerVoiceSyncNextRender = !isChatCharInnerVoiceOpen();
    renderChatMessages();
    scheduleChatOpenThreadDeferredPreamble();
    syncChatSendButtonForActiveThread();
  });
    scheduleChatProactiveTimer();
  const ta = document.getElementById("chat-input");
    if (ta) ta.focus();
    maybeAskChatSystemNotificationPermission();
  });
}

/** 时间感知间隔/跨日：用完整密谈记录（勿用 API 记忆切片），避免末条时间被裁切或失真。 */
function readChatLogForTimeAwareness(thread, maskId) {
  const th = thread && typeof thread === "object" ? thread : readActiveThread();
  const mid = String(maskId || getActiveMaskIdForInbox() || "").trim();
  const tid = String(th?.id || "").trim();
  if (mid && tid) return readChatLogForMaskThread(mid, tid);
  return readChatLog();
}

/**
 * 消息 `at` 缺失时：向后/向前找邻近时间戳；末条仍无则回退 thread.updatedAt。
 * @param {readonly unknown[]} log
 * @param {number} idx
 * @param {number} [threadTailFallback]
 */
function resolveChatTurnAt(log, idx, threadTailFallback) {
  const m = log[idx];
  if (!m || typeof m !== "object") return NaN;
  if (m.role !== "user" && m.role !== "assistant") return NaN;
  if (m.role === "assistant" && m.restoring && !String(m.content || "").trim()) return NaN;
  const at = Number(m.at);
  if (Number.isFinite(at)) return at;
  for (let j = idx + 1; j < log.length; j++) {
    const next = log[j];
    if (!next || typeof next !== "object") continue;
    if (next.role !== "user" && next.role !== "assistant") continue;
    const a = Number(next.at);
    if (Number.isFinite(a)) return a;
  }
  for (let j = idx - 1; j >= 0; j--) {
    const a = Number(log[j]?.at);
    if (Number.isFinite(a)) return a;
  }
  if (idx === log.length - 1 && Number.isFinite(threadTailFallback)) return threadTailFallback;
  return NaN;
}

/**
 * 上一条「角色（assistant）」气泡到本条「用户」气泡之间经过的时长（用消息上的 `at`），供时间感知下自然反应。
 * 与记忆摘要/按范围总结口径一致：含线下频道写入同一线程的记录；中间 system notice 不占「上一条角色」位。
 * @param {readonly unknown[] | null | undefined} [logIn]
 */
function getUserReplyLagAfterAssistantContext(logIn) {
  const log = Array.isArray(logIn) ? logIn : readChatLog();
  if (!Array.isArray(log) || log.length < 2) return "";
  let lastUserIdx = -1;
  for (let i = log.length - 1; i >= 0; i--) {
    const m = log[i];
    if (m && typeof m === "object" && m.role === "user") {
      lastUserIdx = i;
      break;
    }
  }
  if (lastUserIdx < 1) return "";
  const lastUser = log[lastUserIdx];
  const userAt = resolveChatTurnAt(log, lastUserIdx, NaN);
  if (!Number.isFinite(userAt)) return "";
  let prevAsstAt = NaN;
  for (let j = lastUserIdx - 1; j >= 0; j--) {
    const m = log[j];
    if (!m || typeof m !== "object") continue;
    if (m.role === "assistant") {
      prevAsstAt = resolveChatTurnAt(log, j, NaN);
      break;
    }
  }
  if (!Number.isFinite(prevAsstAt)) return "";
  const lag = userAt - prevAsstAt;
  if (!Number.isFinite(lag) || lag < 60 * 1000) return "";
  let zh = "";
  let en = "";
  if (lag < 2 * 60 * 60 * 1000) {
    const mins = Math.max(1, Math.floor(lag / (60 * 1000)));
    zh = `对方在你上一条角色回复之后约 ${mins} 分钟才发出本条消息。`;
    en = `About ${mins} minute(s) passed between your last in-character reply and the user's current message (by message timestamps).`;
  } else if (lag < 24 * 60 * 60 * 1000) {
    const hours = Math.floor(lag / (60 * 60 * 1000));
    zh = `对方在你上一条角色回复之后约 ${hours} 小时才发出本条消息。`;
    en = `About ${hours} hour(s) passed between your last in-character reply and the user's current message.`;
  } else {
    const days = Math.floor(lag / (24 * 60 * 60 * 1000));
    zh = `对方在你上一条角色回复之后约 ${days} 天才发出本条消息。`;
    en = `About ${days} day(s) passed between your last in-character reply and the user's current message.`;
  }
  return `\n[USER REPLY LAG · 本条相对上一条角色]\n- ${zh}\n- ${en}\n- 请结合人设与当前场景自然处理（可写已读、晾着、试探、嘴硬心软等），不必机械报时，除非性格会点破。`;
}

const CHAT_TIME_GAP_USER_TURN_MIN_MS = 2 * 60 * 60 * 1000;
/** 末条后空发接话：≥1 分钟起注入「相对现在」的沉默间隔（与 [USER REPLY LAG] 同门槛；用户刚发新消息仍走 REPLY LAG） */
const CHAT_TIME_GAP_SINCE_ASSISTANT_MIN_MS = 60 * 1000;
/** 注入中文「已久未聊」潜台词：数小时未聊即提醒按当下接话 */
const CHAT_TIME_GAP_LONG_IDLE_HINT_MS = 3 * 60 * 60 * 1000;
const CHAT_TIME_GAP_CRITICAL_MS = 24 * 60 * 60 * 1000;
const CHAT_TIME_GAP_TONE_HINT =
  "Use only as subtext for mood/pacing—do not announce the interval or quote the clock every reply unless the character would naturally do so.";

function getLastChatTurnIndexFromLog(log) {
  if (!Array.isArray(log) || !log.length) return -1;
  for (let i = log.length - 1; i >= 0; i--) {
    const m = log[i];
    if (!m || typeof m !== "object") continue;
    if (m.role !== "user" && m.role !== "assistant") continue;
    if (m.role === "assistant" && m.restoring && !String(m.content || "").trim()) continue;
    return i;
  }
  return -1;
}

function getLastChatTurnTimestampFromLog(log, thread) {
  const idx = getLastChatTurnIndexFromLog(log);
  if (idx < 0) return NaN;
  const fallback = Number(thread?.updatedAt);
  return resolveChatTurnAt(log, idx, Number.isFinite(fallback) ? fallback : NaN);
}

function findPrevChatTurnAt(log, beforeIdx, thread) {
  if (!Array.isArray(log) || beforeIdx < 0) return NaN;
  for (let j = beforeIdx; j >= 0; j--) {
    const m = log[j];
    if (!m || typeof m !== "object") continue;
    if (m.role !== "user" && m.role !== "assistant") continue;
    const at = resolveChatTurnAt(log, j, NaN);
    if (Number.isFinite(at)) return at;
  }
  return NaN;
}

function classifyXiaoxinjiLocalPeriod(now) {
  const hour = now.getHours();
  if (hour >= 23 || hour < 6) {
    return { id: "late_night", label: "深夜", range: "23:00–05:59" };
  }
  if (hour < 11) {
    return { id: "morning", label: "早晨/上午", range: "06:00–10:59" };
  }
  if (hour < 18) {
    return { id: "daytime", label: "白天", range: "11:00–17:59" };
  }
  return { id: "evening", label: "傍晚/夜间", range: "18:00–22:59" };
}

function formatXiaoxinjiLocalTimeStr(now) {
  return now.toLocaleTimeString("zh-CN", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false
  });
}

/** @param {Date} now */
function snapshotXiaoxinjiWallClock(now) {
  const period = classifyXiaoxinjiLocalPeriod(now);
  return { period, timeStr: formatXiaoxinjiLocalTimeStr(now) };
}

/** 本地钟点锚定：防止 [DAY CHANGED]/旧聊天语气把模型带成错误时段 */
function buildXiaoxinjiWallClockAnchorLine(now) {
  const { period, timeStr } = snapshotXiaoxinjiWallClock(now);
  return (
    `- **Wall-Clock Anchor（最高优先级）**: ${timeStr} · **${period.label}**（本地 ${period.range}）` +
    `— 场景、光线、困意/阳光感**必须**与此一致；勿把聊天记录里的清晨/晚安当成现在仍是那一刻。`
  );
}

function buildXiaoxinjiLongIdleHintFromLog(log, thread) {
  const idx = getLastChatTurnIndexFromLog(log);
  if (idx < 0) return "";
  const fallback = Number(thread?.updatedAt);
  const lastAt = resolveChatTurnAt(log, idx, Number.isFinite(fallback) ? fallback : NaN);
  if (!Number.isFinite(lastAt)) return "";
  const diffMs = Date.now() - lastAt;
  if (diffMs < CHAT_TIME_GAP_LONG_IDLE_HINT_MS) return "";
  const dur = formatXiaoxinjiChatTimeGapDurationLabel(diffMs);
  const { period, timeStr } = snapshotXiaoxinjiWallClock(new Date());
  return (
    `\n[已久未聊]: 距上一条有效消息已过约 ${dur}。` +
    `聊天记录里的语气可能过时，但**现在本地时间是 ${timeStr}（${period.label}）**——按此刻真实时段接话；` +
    `勿机械延续旧消息的清晨/晚安口吻，也**勿**在深夜误写成白天、在白天误写成深夜。` +
    `勿在台词里念日期、报钟点，除非人设自然会提。`
  );
}

function buildXiaoxinjiDayChangedHint(now) {
  const { period, timeStr } = snapshotXiaoxinjiWallClock(now);
  return (
    `\n[DAY CHANGED]: 上一条有效消息在**上一日历日**；现在已是新的一天，` +
    `**但当前钟点是 ${timeStr}（${period.label}）**——按此刻真实时段接话，勿默认当成白天早晨。` +
    `若昨夜聊到过晚安，勿复读同一套收束；若此刻是深夜/傍晚，仍按深夜/傍晚写，勿写成晒太阳的白天。` +
    `勿在台词里念日期、星期或报钟点，除非人设自然会提。`
  );
}

/** 跨日：末条与当前不同日，或用户刚回消息但上一条在昨日 */
function buildXiaoxinjiDayRolloverContextFromLog(log, thread) {
  const arr = Array.isArray(log) ? log : [];
  if (!arr.length) return "";
  const now = new Date();
  const lastAt = getLastChatTurnTimestampFromLog(arr, thread);
  if (Number.isFinite(lastAt) && new Date(lastAt).toDateString() !== now.toDateString()) {
    return buildXiaoxinjiDayChangedHint(now);
  }
  const lastIdx = getLastChatTurnIndexFromLog(arr);
  if (lastIdx < 0) return "";
  const last = arr[lastIdx];
  if (!last || last.role !== "user") return "";
  const userAt = resolveChatTurnAt(arr, lastIdx, Number(thread?.updatedAt));
  if (!Number.isFinite(userAt)) return "";
  const prevAt = findPrevChatTurnAt(arr, lastIdx - 1, thread);
  if (!Number.isFinite(prevAt)) return "";
  if (new Date(prevAt).toDateString() === new Date(userAt).toDateString()) return "";
  return buildXiaoxinjiDayChangedHint(now);
}

function buildXiaoxinjiTimeOfDayHint(now) {
  const period = classifyXiaoxinjiLocalPeriod(now);
  const noQuote = "勿在台词里念日期或报钟点，除非人设自然会提。";
  if (period.id === "late_night") {
    return `\n- Time of Day: **${period.label}** — 可体现困意、夜生活、问对方怎么还没睡等；${noQuote}`;
  }
  if (period.id === "morning") {
    return `\n- Time of Day: **${period.label}** — 若聊天仍停在昨晚，按此刻早晨接话，勿再接晚安；${noQuote}`;
  }
  if (period.id === "daytime") {
    return `\n- Time of Day: **${period.label}** — 以当前时段为准，勿被昨晚聊天氛围带偏；${noQuote}`;
  }
  return `\n- Time of Day: **${period.label}** — 光线偏暗、可带夜间氛围；勿在未到深夜时硬凑「凌晨三点」式夸张；${noQuote}`;
}

function formatXiaoxinjiChatTimeGapDurationLabel(diffMs) {
  if (diffMs >= 24 * 60 * 60 * 1000) {
    return `${Math.floor(diffMs / (24 * 60 * 60 * 1000))} day(s)`;
  }
  if (diffMs >= 2 * 60 * 60 * 1000) {
    return `${Math.floor(diffMs / (60 * 60 * 1000))} hour(s)`;
  }
  return `${Math.max(1, Math.floor(diffMs / (60 * 1000)))} minute(s)`;
}

/**
 * @param {number} diffMs
 * @param {"user_turn"|"since_assistant"} mode
 */
function formatXiaoxinjiChatTimeGapBlock(diffMs, mode) {
  const minMs =
    mode === "since_assistant" ? CHAT_TIME_GAP_SINCE_ASSISTANT_MIN_MS : CHAT_TIME_GAP_USER_TURN_MIN_MS;
  if (!Number.isFinite(diffMs) || diffMs <= minMs) return "";
  const dur = formatXiaoxinjiChatTimeGapDurationLabel(diffMs);
  const toneHint = ` ${CHAT_TIME_GAP_TONE_HINT}`;

  if (diffMs > CHAT_TIME_GAP_CRITICAL_MS) {
    if (mode === "since_assistant") {
      return (
        `\n[CRITICAL TIME GAP]: The thread has been idle since the last message (about ${dur}). ` +
        "React to the silence naturally. Match **current wall-clock time of day** (may be night, morning, or afternoon—not assumed morning). " +
        "If you already closed the night (e.g. 晚安) but real time has moved on, do not repeat the same closing beat." +
        toneHint
      );
    }
    return (
      `\n[CRITICAL TIME GAP]: The user hasn't replied for ${dur}. You should react to this long silence (e.g., ask where they went, say you missed them, or be angry/cold depending on personality).` +
      toneHint
    );
  }

  if (mode === "since_assistant") {
    return (
      `\n[Time Gap]: The thread has been idle since the last message (about ${dur}). ` +
      "Do not repeat the same closing beat (e.g. another 晚安) if wall-clock time has moved on—match the current time of day." +
      toneHint
    );
  }
  return (
    `\n[Time Gap]: About ${dur} passed between the previous message and the user's latest message.` +
    " If that spans overnight or a new day, match Current Date/Time—not the previous night's closing mood." +
    toneHint
  );
}

/**
 * 用户沉默间隔：末条为 user 时，空发接话算「末条到当前」；刚发新消息则算「上一条到本条 user」。
 * 末条为 assistant 时算「角色末条到当前时刻」。
 * @param {readonly unknown[]} log 完整密谈记录（非 API 记忆切片）
 * @param {unknown} [thread]
 */
function getXiaoxinjiChatTimeGapContextFromLog(log, thread) {
  const arr = Array.isArray(log) ? log : [];
  if (!arr.length) return "";
  const lastIdx = getLastChatTurnIndexFromLog(arr);
  if (lastIdx < 0) return "";
  const last = arr[lastIdx];
  const tailFallback = Number(thread?.updatedAt);

  if (last.role === "user") {
    const userAt = resolveChatTurnAt(arr, lastIdx, Number.isFinite(tailFallback) ? tailFallback : NaN);
    if (!Number.isFinite(userAt)) return "";
    const idleMs = Date.now() - userAt;
    const prevAt = findPrevChatTurnAt(arr, lastIdx - 1, thread);
    if (
      idleMs >= CHAT_TIME_GAP_SINCE_ASSISTANT_MIN_MS &&
      (!Number.isFinite(prevAt) || idleMs >= userAt - prevAt)
    ) {
      return formatXiaoxinjiChatTimeGapBlock(idleMs, "since_assistant");
    }
    if (!Number.isFinite(prevAt)) return "";
    return formatXiaoxinjiChatTimeGapBlock(userAt - prevAt, "user_turn");
  }

  if (last.role === "assistant") {
    const asstAt = resolveChatTurnAt(arr, lastIdx, Number.isFinite(tailFallback) ? tailFallback : NaN);
    if (!Number.isFinite(asstAt)) return "";
    return formatXiaoxinjiChatTimeGapBlock(Date.now() - asstAt, "since_assistant");
  }

  return "";
}

/**
 * 小心机原版「REAL TIME AWARENESS」：lunar-javascript（Solar/Lunar）+ holidays.buildRegionTimeContext
 * @param {ReturnType<typeof readUserMask>} mask
 * @param {readonly unknown[]} gapLog 完整密谈记录（间隔/跨日口径）
 * @param {unknown} [thread]
 */
function buildXiaoxinjiRealTimeAwarenessPrompt(mask, gapLog, thread) {
  const now = new Date();
  const wallClockAnchor = buildXiaoxinjiWallClockAnchorLine(now);
  const longIdleHint = buildXiaoxinjiLongIdleHintFromLog(gapLog, thread);
  const Solar = typeof window !== "undefined" ? window.Solar : null;
  const timeStr = formatXiaoxinjiLocalTimeStr(now);
  const timeOfDayHint = buildXiaoxinjiTimeOfDayHint(now);
  const timeGapContext = getXiaoxinjiChatTimeGapContextFromLog(gapLog, thread);
  const dayRolloverContext = buildXiaoxinjiDayRolloverContextFromLog(gapLog, thread);
  const replyLagContext = getUserReplyLagAfterAssistantContext(gapLog);
  const timeInstructions =
    "- INSTRUCTIONS: **以 Wall-Clock Anchor 与 Time 为准**校正常理、节日与时段氛围。" +
    "[DAY CHANGED]/[已久未聊] 只表示日历或语气衔接变化，**不表示**现在一定是白天；" +
    "若 Time 显示深夜/傍晚，就按深夜/傍晚写，勿误写成晒太阳的白天。" +
    "23:00–06:00 可体现困意；11:00–17:59 才是白天。" +
    "勿被聊天记录里的昨晚语气带偏。" +
    "[DAY CHANGED]、[已久未聊]、[Time Gap]、[USER REPLY LAG] 只影响情绪与节奏潜台词，勿在台词里念日期、星期、间隔或报钟点，除非人设自然会提。" +
    "你应知晓当前时段，但除非对话本身相关，勿因深夜主动催对方睡觉或评论「这么晚了还不睡」。";
  if (!Solar || typeof Solar.fromDate !== "function") {
    return (
      "\n\n[REAL TIME AWARENESS · 降级]\n" +
      "- 农历库（lunar-javascript）未加载。请检查 index.html 是否已引入 lunar.js 或网络是否可用。\n" +
      `${wallClockAnchor}\n` +
      `- Time: ${timeStr}（用户设备本地时间）${timeOfDayHint}` +
      `${dayRolloverContext}${longIdleHint}${timeGapContext}` +
      (replyLagContext ? `${replyLagContext}\n` : "") +
      `${timeInstructions}\n`
    );
  }
  const solar = Solar.fromDate(now);
  const lunar = solar.getLunar();
  const solarFestivals = solar.getFestivals ? solar.getFestivals() : [];
  const lunarFestivals = lunar.getFestivals ? lunar.getFestivals() : [];
  const jieqi = lunar.getJieQi ? lunar.getJieQi() : "";
  const festivals = [...(solarFestivals || []), ...(lunarFestivals || [])];
  if (jieqi) festivals.push(jieqi);
  const region = normalizeUserMaskRegion(mask?.region);
  const H = window.XXJ_HOLIDAYS;
  const regionCtx =
    H && typeof H.buildRegionTimeContext === "function" ? H.buildRegionTimeContext(now, region) : "";
  const festivalText = festivals.length ? festivals.join(", ") : "None";
  const lunarStr = typeof lunar.toString === "function" ? lunar.toString() : String(lunar);
  const dow = ["日", "一", "二", "三", "四", "五", "六"][now.getDay()];
  const regionHint = region
    ? ""
    : "\n- Region: 未设定（请在密谈「卷宗」→ 时间感知 下选所在地区，否则无法判断调休/法定假）";
  return `\n\n[REAL TIME AWARENESS]\n${wallClockAnchor}\n- Current Date: ${now.getFullYear()}年${now.getMonth() + 1}月${now.getDate()}日 星期${dow} (农历 ${lunarStr})\n- Time: ${timeStr}（用户设备本地时间）${timeOfDayHint}${regionHint}\n- Festivals/Events: ${festivalText}${regionCtx}\n${dayRolloverContext}${longIdleHint}${timeGapContext}${replyLagContext}\n${timeInstructions}`;
}

/** 密谈/群聊：时间感知块（默认关）。间隔/跨日用完整密谈记录，不用 API 记忆切片。 */
function buildThreadTimeAwarenessForPrompt(thread, mask, _apiLogUnused, opts) {
  if (!isThreadTimeAwareEnabled(thread)) return "";
  const gapLog = readChatLogForTimeAwareness(thread, opts?.boundMaskId);
  let block = buildXiaoxinjiRealTimeAwarenessPrompt(mask, gapLog, thread);
  if (thread?.kind === "group") {
    block = block.replace(
      "请在密谈「卷宗」→ 时间感知 下选所在地区",
      "请在群聊档案 → 时间感知 下选所在地区"
    );
    block +=
      "\n- [群聊] 时间/节假日/沉默间隔/回复滞后对**各成员**均适用；按各自人设分别反应，勿全员复读同一报时口吻。";
  }
  return block;
}

/** 心声开启时注入 JSON 键名骨架（不含可抄写的对白示例）。 */
function buildChatHeartVoiceFormatExampleLine(transOn, sceneOffline, offlineImgEveryRound) {
  const head = `JSON 骨架（键必填，**值须由角色本轮生成**，勿抄示意字）：`;
  const mindKeys =
    '"mind":{"heartVoice":"…","innerState":"…","mood":"…","desire":"…","affinity":0,"affectionDesc":"…"}';
  if (transOn) {
    return `${head}\n{"lines":["…"],"lineTranslations":["…"],${mindKeys},"recalls":[]}`;
  }
  if (sceneOffline) {
    const imgCap = offlineImgEveryRound ? ',"imageSceneCaption":"…"' : "";
    return `${head}\n{"lines":["…"],${mindKeys},"recalls":[]${imgCap}}`;
  }
  return `${head}\n{"lines":["…"],${mindKeys},"recalls":[]}`;
}

/**
 * 设置 · 分场景自定义思维链（留空则用内置说明）。
 * @param {unknown} raw
 * @returns {string}
 */
function normalizeGlobalThinkingChainText(raw) {
  const t = String(raw ?? "")
    .replace(/\r\n/g, "\n")
    .trim();
  if (!t) return "";
  const max = 12000;
  return t.length > max ? t.slice(0, max) : t;
}

/** @typedef {"im"|"offline"|"group"} ThinkingChainSurface */

/** @type {Record<ThinkingChainSurface, keyof typeof window.XXJ_DB.K>} */
const THINKING_CHAIN_SURFACE_K = {
  im: "GLOBAL_THINKING_CHAIN_IM",
  offline: "GLOBAL_THINKING_CHAIN_OFFLINE",
  group: "GLOBAL_THINKING_CHAIN_GROUP"
};

/** @param {ThinkingChainSurface} surface */
function readGlobalThinkingChainText(surface) {
  const D = window.XXJ_DB;
  if (!D) return "";
  const k = D.K[THINKING_CHAIN_SURFACE_K[surface]];
  const direct = normalizeGlobalThinkingChainText(k ? D.getKv(k) : "");
  if (direct) return direct;
  return normalizeGlobalThinkingChainText(D.getKv(D.K.GLOBAL_THINKING_CHAIN));
}

/** @param {ThinkingChainSurface} surface */
function writeGlobalThinkingChainText(surface, text) {
  const D = window.XXJ_DB;
  if (!D) return;
  const k = D.K[THINKING_CHAIN_SURFACE_K[surface]];
  if (!k) return;
  const t = normalizeGlobalThinkingChainText(text);
  if (t) D.setKv(k, t);
  else D.delKv(k);
}

function clearLegacyGlobalThinkingChainText() {
  const D = window.XXJ_DB;
  if (!D) return;
  D.delKv(D.K.GLOBAL_THINKING_CHAIN);
}

/** @param {boolean} sceneOffline */
function getThinkingChainRefHint(sceneOffline) {
  const surface = sceneOffline ? "offline" : "im";
  if (readGlobalThinkingChainText(surface)) {
    return sceneOffline ? "按上文思维链说明（先想再写）" : "按上文思维链说明";
  }
  return sceneOffline ? "按上文 snag→check 六拍，先规划再写 lines" : "按上文 snag→send 五拍";
}

function formatGlobalThinkingChainStatusLine() {
  const parts = [
    ["im", "密谈"],
    ["offline", "晤面"],
    ["group", "群聊"]
  ].map(([surface, label]) => `${label}·${readGlobalThinkingChainText(surface) ? "自定义" : "内置"}`);
  return parts.join(" / ");
}

/**
 * @param {{ sceneOffline?: boolean, name?: string, userCall?: string }} opts
 * @returns {string[]}
 */
function buildBuiltinImOfflineThinkingChainBeatLines(opts) {
  const name = String(opts?.name || "角色").trim() || "角色";
  const userCall = String(opts?.userCall || "对方").trim() || "对方";
  const sceneOffline = !!opts?.sceneOffline;
  if (sceneOffline) {
    return [
      `线下 thinking：消息进耳到张嘴前，**snag → drift → read → feel → shape → check** 六拍（每拍 felt sense，可 blur、可回溯；勿写成 numbered essay）：`,
      `**snag · 勾住**：此刻在哪、光线距离、手在做什么；从**上一段 lines 末尾**的姿势/道具/情绪余温接起；「${userCall}」什么状态；上一交换与沉默把关系推成什么质感；${userCall} 已说清、已解释过的**不要当未知**。`,
      `**drift · 锚人设**：从卡面摘 2～3 条**原文级**口癖/边界/绝不会说的句型；这一人当面习惯（先愣/先岔/先顶/先装没事、句长、是否用动作垫话——**只写卡里有或上文已建立的**）；标签只留 thinking；**这句法像不像「${name}」**？勿偷换言情八股。`,
      `**read · 进身体**：话进身体后先于命名的紧/松/烫/绷/空；可选误读/投射（仅人设或关系里常这样时）；多种 drive 可同时存在、都在 settling；**settling ≠ resolving**；别从上一段 3 档跳到 9 档，也别每轮都 9 档；近几轮是否越写越像标准霸总/标准软萌包？`,
      `**feel · 内天气**：whole interior 在 settle；本轮一种主反应（愣/短/退/岔/贴近/顶一句 择一）；为了什么（贴近/试探/填沉默/仅关系已到时才顶回去）；嘴笨/慢热可半句、改口、词不达意——**只给这种人**。`,
      `**shape · 出口**：预演 1～2 句「」像卡面真人句（非网文模板）；2～4 可见节拍可含沉默/小动作。`,
      `**check · 成稿**：Still「${name}」？遮住名字套任意角色都成立吗？太及时/太暖/太懂？空间时间体力与上段一致？硬凑对峙/命令口气/说教/OOC/标签进 lines？lines 默认 1 项。确认后写 lines。`,
      `lines 以 thinking 为准；文学正文；不破墙。`
    ];
  }
  return [
    `线上 thinking：手机屏幕里、看见「${userCall}」这条到拇指动之间的半秒。**snag → drift → read → feel → send** 五拍（3～6 行 felt sense；可 blur、可回溯；勿写成条目清单）：`,
    `**snag**：这条里勾住你的词/语气/画面/表情包。`,
    `**drift**：手边在干嘛（从上文 carry）；杂念、小别扭、半句自我辩护；卡面 1～2 条口癖/打字指纹——**还像「${name}」吗**？`,
    `**read**：${userCall} 这条进 ${name} 身体里是什么反应？Ta 要什么、${name} 要什么——**只抓一个线头**，别像客服逐条复述。`,
    `**feel**：这一拍 ${name} 的内天气是什么；让这色去染 lines（不是换一套通用恋人情绪）。`,
    `**send**：预发前逐条问「${name} 真会发这句吗？」；像脚本/客服/讨好型 AI/每句同长 → 改。`,
    `thinking 是过程草稿（宜 150～280 字，为 lines 留劲）；欲念/腹诽/深层心理放 heartVoice，勿在 thinking 里写长篇散文。lines 只写会发出去的字；不破墙。`
  ];
}

/**
 * @param {{ surface?: "im"|"offline"|"group", sceneOffline?: boolean, name?: string, userCall?: string, stRepl?: (s: string) => string }} opts
 * @returns {string[]}
 */
function buildThinkingChainBeatLines(opts) {
  const surface =
    opts && opts.surface === "group" ? "group" : opts && opts.surface === "offline" ? "offline" : "im";
  const sceneOffline = surface === "offline" || !!opts?.sceneOffline;
  const name = String(opts?.name || "角色").trim() || "角色";
  const userCall = String(opts?.userCall || "对方").trim() || "对方";
  const st = typeof opts?.stRepl === "function" ? opts.stRepl : (s) => s;
  const customRaw = readGlobalThinkingChainText(surface);
  if (customRaw) {
    const custom = st(customRaw);
    if (surface === "group") {
      return [
        `群聊 thinking：写 replies 前，按下列说明完成 JSON \`thinking\`（**覆盖内置思维链**；felt sense；先想再写；勿写成 essay）：`,
        custom
      ];
    }
    if (sceneOffline) {
      return [
        `线下 thinking：写 lines 前，按下列说明完成 JSON \`thinking\`（**覆盖内置思维链**；先规划再写 lines）：`,
        custom,
        `lines 以 thinking 为准；文学正文；不破墙。`
      ];
    }
    return [
      `线上 thinking：写 lines 前，按下列说明完成 JSON \`thinking\`（**覆盖内置思维链**；先想再写）：`,
      custom,
      `lines 只写会发出去的字；不破墙、不像说明书。`
    ];
  }
  if (surface === "group") {
    return [
      `群聊 thinking：写 replies 前，**snag → drift → read → feel → route** 五拍（felt sense；勿写成 essay）：`,
      `**snag**：群场质感、各人在等谁；聊过的别当未知。`,
      `**drift**：各 charId 口癖/打字指纹——**禁止互串**；A 的秘密/职业/口吻不能写到 B 的 line。`,
      `**read**：每人与群、与 ${userCall} 之间的气；各成员只抓一个线头，别像客服逐条复述。`,
      `**feel**：各 char 内天气落定（可不同温）。`,
      `**route**：标 charId 接话链（replies 数组下标=时间线）；每人一种意图；像脚本/全员同腔/太暖/反复盘问 → 改。`
    ];
  }
  return buildBuiltinImOfflineThinkingChainBeatLines({ sceneOffline, name, userCall });
}

function fillGlobalThinkingChainForm() {
  const fields = [
    ["im", "settings-global-thinking-chain-im"],
    ["offline", "settings-global-thinking-chain-offline"],
    ["group", "settings-global-thinking-chain-group"]
  ];
  for (const [surface, id] of fields) {
    const ta = document.getElementById(id);
    if (ta) ta.value = readGlobalThinkingChainText(surface);
  }
  setSettingsStatusLine("settings-global-thinking-chain-status", formatGlobalThinkingChainStatusLine(), "");
  fillGlobalPromptPackSettingsUi();
}

function saveGlobalThinkingChainFromUi() {
  const fields = [
    ["im", "settings-global-thinking-chain-im"],
    ["offline", "settings-global-thinking-chain-offline"],
    ["group", "settings-global-thinking-chain-group"]
  ];
  for (const [surface, id] of fields) {
    const ta = document.getElementById(id);
    writeGlobalThinkingChainText(surface, ta ? ta.value : "");
  }
  clearLegacyGlobalThinkingChainText();
  fillGlobalThinkingChainForm();
  const anyCustom = fields.some(([surface]) => readGlobalThinkingChainText(surface));
  showToast(anyCustom ? "已保存思维链" : "已恢复全部内置思维链");
}

function bindSettingsGlobalThinkingChainControls() {
  if (window.__xxjSettingsThinkingChainBound) return;
  window.__xxjSettingsThinkingChainBound = true;
  document.getElementById("settings-global-thinking-chain-save")?.addEventListener("click", () => {
    saveGlobalThinkingChainFromUi();
  });
  document.getElementById("settings-global-thinking-chain-clear")?.addEventListener("click", () => {
    for (const id of [
      "settings-global-thinking-chain-im",
      "settings-global-thinking-chain-offline",
      "settings-global-thinking-chain-group"
    ]) {
      const ta = document.getElementById(id);
      if (ta) ta.value = "";
    }
    saveGlobalThinkingChainFromUi();
  });
  document.getElementById("settings-global-prompt-pack")?.addEventListener("change", () => {
    saveGlobalPromptPackFromUi();
  });
}

