function buildCharLockPostUnlockApiUserPrompt() {
  const th = readActiveThread();
  const offlineBlock = buildThreadOfflineApiHintLine(th);
  return (
    "（界面代发、勿复述本句）[锁屏结束 · 你的后续]\n" +
    "对方已离开专注锁屏；锁屏程序汇总与同屏对白实录见上一条说明。请根据你的人设、与对方关系及上文剧情，决定接下来怎么办（不要向用户解释规则）：\n" +
    offlineBlock
  );
}

async function charLockRunPostUnlockAssistantRound() {
  if (!window.RP_AI) return;
  reconcileActiveThreadRef();
  if (!readChatActiveThreadRef().threadId) return;
  const th = readActiveThread();
  if (!th || th.kind === "group") return;
  const mid = String(getActiveMaskIdForInbox() || "").trim();
  const tid = String(readChatActiveThreadRef().threadId || "").trim();
  try {
    await executeChatAssistantRound(
      {
        boundMaskId: mid,
        boundThreadId: tid,
        boundThread: th,
        boundDmSurface: resolveChatRoundDmSurface(
          { boundMaskId: mid, boundThreadId: tid, boundThread: th },
          th,
          mid,
          tid
        ),
        emptySendUserContent: buildCharLockPostUnlockApiUserPrompt()
      },
      null
    );
  } catch (_) {
    /* ignore */
  }
}

/** @returns {boolean} */
function readCheckupKickFromLastAssistantLog(maskId, threadId) {
  if (typeof readChatLogForMaskThread !== "function") return false;
  const log = readChatLogForMaskThread(maskId, threadId);
  for (let i = log.length - 1; i >= 0; i--) {
    const m = log[i];
    if (!m || m.role !== "assistant" || m.restoring) continue;
    const t = normalizeAssistantModelJsonText(stripUtf8Bom(String(m.content || "")).trim());
    const slice = sliceFirstBalancedJsonObject(t);
    if (!slice) return false;
    try {
      const o = JSON.parse(slice);
      if (!o || typeof o !== "object") return false;
      return o.checkupKick === true || /^true$/i.test(String(o.checkupKick || "").trim());
    } catch (_) {
      return false;
    }
  }
  return false;
}

/** @returns {string} */
function buildCheckupCaughtApiUserPrompt(th, phase) {
  const live = phase === "live";
  const offlineBlock = buildThreadOfflineApiHintLine(th, { checkup: true, live });
  const liveBlock = live
    ? "对方此刻还在翻你手机，查岗尚未结束。你可质问、发火、抢回手机、装没事、冷战、反将一军等。\n若要程序立即终止对方翻看、将其赶出查岗，JSON 根字段写 \"checkupKick\": true（可与 lines 同条 JSON）。\n若上文有非本人笔迹代发，可结合「对方正在翻你手机」按人设推断或与对方有关；勿编造其他代发者。"
    : "程序归档见上一条（勿复述归档全文）。请按人设决定：质问、发火、赶对方走、抢回手机、装没事、冷战、反将一军等均可。\n归档若列明代发：可结合「你察觉对方翻手机」推断非本人笔迹或与对方有关；勿编造代发者，勿无据指认无关第三者。";
  return (
    "（界面代发、勿复述本句）[查岗 · 被察觉 · 你的反应]\n" +
    (live ? "你刚察觉对方正在翻看你的手机。" : "你刚察觉对方翻看了你的手机；") +
    liveBlock +
    "\n" +
    offlineBlock +
    "\n用 JSON lines 发消息；不要向用户解释规则。"
  );
}

/**
 * 查岗被察觉：在对应密谈触发一轮 char 回复（归档已写入 log，由 API 注入记忆）。
 * @param {string} maskId
 * @param {string} threadId
 * @param {{ phase?: "live"|"finish" }} [opts]
 * @returns {Promise<boolean>} checkupKick — char 是否要求赶主控出查岗
 */
async function runCheckupCaughtAssistantRound(maskId, threadId, opts) {
  if (!window.RP_AI) return false;
  const mid = String(maskId || "").trim();
  const tid = String(threadId || "").trim();
  if (!mid || !tid) return false;
  const found = findChatThreadInInbox(mid, tid);
  if (!found || !found.thread || found.thread.kind === "group") return false;
  const th = found.thread;
  const phase = opts && opts.phase === "live" ? "live" : "finish";
  try {
    await executeChatAssistantRound(
      {
        boundMaskId: mid,
        boundThreadId: tid,
        boundThread: th,
        boundDmSurface: resolveChatRoundDmSurface(
          { boundMaskId: mid, boundThreadId: tid, boundThread: th },
          th,
          mid,
          tid
        ),
        emptySendUserContent: buildCheckupCaughtApiUserPrompt(th, phase)
      },
      null
    );
  } catch (_) {
    /* ignore */
  }
  return readCheckupKickFromLastAssistantLog(mid, tid);
}

