/** @param {HTMLSelectElement} sel @param {HTMLInputElement | null} customInp */
function populateMinimaxVoiceSelectOptions(sel, customInp) {
  if (!sel) return;
  const cfgMm = readMinimaxTtsConfig();
  const prevVal = String(sel.value || "");
  sel.replaceChildren();
  const o0 = document.createElement("option");
  o0.value = "";
  o0.textContent = "跟随全局默认";
  sel.appendChild(o0);
  for (const p of cfgMm.voicePresets || []) {
    const o = document.createElement("option");
    o.value = `preset:${p.id}`;
    o.textContent = formatMinimaxPresetSummary(p);
    sel.appendChild(o);
  }
  const oc = document.createElement("option");
  oc.value = "__custom__";
  oc.textContent = "自定义…";
  sel.appendChild(oc);
  const optVals = [...sel.querySelectorAll("option")].map((o) => o.value);
  if (prevVal && optVals.includes(prevVal)) sel.value = prevVal;
}

/** @param {HTMLSelectElement} sel @param {HTMLInputElement | null} customInp @param {string} voiceRef */
function applyMinimaxVoiceRefToSelect(sel, customInp, voiceRef) {
  if (!sel) return;
  populateMinimaxVoiceSelectOptions(sel, customInp);
  const v = String(voiceRef || "").trim();
  const optVals = [...sel.querySelectorAll("option")].map((o) => o.value);
  const isPreset = v.startsWith("preset:") && optVals.includes(v);
  const isCustom = Boolean(v) && !isPreset;
  sel.value = isPreset ? v : isCustom ? "__custom__" : "";
  if (customInp instanceof HTMLInputElement) {
    customInp.hidden = sel.value !== "__custom__";
    customInp.value = isCustom ? v : "";
  }
}

/** @param {HTMLSelectElement} sel @param {HTMLInputElement | null} customInp */
function readMinimaxVoiceIdFromSelect(sel, customInp) {
  if (!sel) return "";
  if (String(sel.value || "") === "__custom__") {
    return customInp instanceof HTMLInputElement ? String(customInp.value || "").trim() : "";
  }
  return String(sel.value || "").trim();
}

