  if (mmSel instanceof HTMLSelectElement) {
    applyMinimaxVoiceRefToSelect(mmSel, mmCustom instanceof HTMLInputElement ? mmCustom : null, p.minimaxVoiceId);
  }
  const promptTa = document.getElementById("char-image-gen-prompt");
