function setCharPaneDirty(dirty) {
  const hint = document.getElementById("char-save-hint");
  if (!hint) return;
  hint.textContent = dirty ? "未保存" : "已同步";
  hint.classList.toggle("is-dirty", dirty);
  if (dirty) {
    const btn = document.getElementById("char-save");
    const prev = btn?.dataset.saveFlashTimer;
    if (prev) window.clearTimeout(Number(prev));
    if (btn) {
      btn.textContent = "保存角色";
      delete btn.dataset.saveFlashTimer;
    }
  }
}

/** 角色表单是否处于「未保存」编辑态（切换角色前据此决定是否把表单写回 store） */
function isCharPaneDirty() {
  return !!document.getElementById("char-save-hint")?.classList.contains("is-dirty");
}

/** 若用户正在编辑角色表单，先把表单内容写回当前激活角色，避免切换时丢改或用空表单覆盖。 */
function flushCharPersonaFormToActiveIfDirty() {
  const D = window.XXJ_DB;
  if (!D || !isCharPaneDirty()) return;
  const p = collectCharPersonaFromForm();
  const st = readCharPersonaStore();
  if (!st.activeId || !st.items.find((x) => x.id === st.activeId)) return;
  const idx = st.items.findIndex((x) => x.id === st.activeId);
  if (idx < 0) return;
  st.items[idx] = { ...st.items[idx], ...p, id: st.items[idx].id };
  writeCharPersonaStore(st);
  setCharPaneDirty(false);
}

function setUserPaneDirty(dirty) {
  const hint = document.getElementById("user-mask-save-hint");
  if (!hint) return;
  hint.textContent = dirty ? "未保存" : "已同步";
  hint.classList.toggle("is-dirty", dirty);
  if (dirty) {
    const btn = document.getElementById("user-mask-save");
    const prev = btn?.dataset.saveFlashTimer;
    if (prev) window.clearTimeout(Number(prev));
    if (btn) {
      btn.textContent = "保存面具";
      delete btn.dataset.saveFlashTimer;
    }
  }
}

const SAVE_BTN_FLASH_MS = 1800;

/** 保存成功后按钮短暂显示「已保存」，再恢复原标题 */
function flashSaveButtonLabel(btnId, doneText, originalText, ms = SAVE_BTN_FLASH_MS) {
  const el = document.getElementById(btnId);
  if (!el) return;
  const prev = el.dataset.saveFlashTimer;
  if (prev) window.clearTimeout(Number(prev));
  el.textContent = doneText;
  const tid = window.setTimeout(() => {
    el.textContent = originalText;
    delete el.dataset.saveFlashTimer;
  }, ms);
  el.dataset.saveFlashTimer = String(tid);
}

function refreshCharOpeningRowLabels() {
  const rows = document.querySelectorAll("#char-openings-list .char-opening-row");
  rows.forEach((li, idx) => {
    const k = li.querySelector(".char-opening-row-k");
    if (k) k.textContent = idx === 0 ? "主开场" : `备用 ${idx}`;
    const ta = li.querySelector(".char-opening-input");
    if (ta) {
      ta.placeholder =
        idx === 0 ? "对方可能先说的一句话（主开场）…" : "另一条可选开场…";
    }
  });
}

function createCharOpeningRowEl(text) {
  const li = document.createElement("li");
  li.className = "char-opening-row";
  const head = document.createElement("div");
  head.className = "char-opening-row-head";
  const lab = document.createElement("span");
  lab.className = "char-opening-row-k";
  lab.textContent = "—";
  const rm = document.createElement("button");
  rm.type = "button";
  rm.className = "chip ghost chip-xs char-opening-remove";
  rm.setAttribute("aria-label", "删除本条开场白");
  rm.innerHTML = "<i class=\"ph ph-trash\" aria-hidden=\"true\"></i>";
  head.append(lab, rm);
  const ta = document.createElement("textarea");
  ta.className = "char-textarea char-opening-input";
  ta.rows = 2;
  ta.spellcheck = false;
  ta.value = text != null ? String(text) : "";
  li.append(head, ta);
  return li;
}

function renderCharOpeningsEditor(openings) {
  const ul = document.getElementById("char-openings-list");
  if (!ul) return;
  ul.replaceChildren();
  const list = normalizeCharOpeningsArray(openings);
  const rows = list.length ? list : [""];
  for (const line of rows) {
    ul.appendChild(createCharOpeningRowEl(line));
  }
  refreshCharOpeningRowLabels();
}


/**
 * 把角色的 routinePreset 写到表单的 <select>。
 * 选项从 window.XXJ_STATE_PRESETS 动态生成(slug / label),空选项 = 走 __default__。
 */
function applyCharRoutinePresetToForm(p) {
  const sel = document.getElementById("char-routine-preset");
  if (!sel) return;
  // 重建一次(避免外部新增 preset 后下拉选择陈旧)
  const presets = (window.XXJ_STATE_PRESETS && typeof window.XXJ_STATE_PRESETS === "object")
    ? window.XXJ_STATE_PRESETS : {};
  const knownLabels = {
    chenzixi: "陈子奚 (古风医家)",
    "__default__": "通用现代日常"
  };
  const seen = new Set();
  sel.replaceChildren();
  const opt0 = document.createElement("option");
  opt0.value = "";
  opt0.textContent = "跟随全局(通用现代日常)";
  sel.appendChild(opt0);
  seen.add("");
  for (const k of Object.keys(presets)) {
    if (k === "__installed") continue;
    if (seen.has(k)) continue;
    const o = document.createElement("option");
    o.value = String(k);
    o.textContent = knownLabels[k] || String(k);
    sel.appendChild(o);
    seen.add(k);
  }
  // 写入 persona.routinePreset
  const v = (p && p.routinePreset != null) ? String(p.routinePreset) : "";
  sel.value = v;
}

/**
 * 把表单上当前选中的 routinePreset 写回当前编辑中的 persona。
 * 在 flushCharPersonaFormToActiveIfDirty / 等持久化钩子里被调用。
 */
function readCharRoutinePresetFromForm() {
  const sel = document.getElementById("char-routine-preset");
  if (!sel) return "";
  return String(sel.value || "").trim();
}

/** 点"生成专属作息"按钮的处理函数 */
async function onClickCharRoutineGen() {
  const btn = document.getElementById("char-routine-gen-btn");
  const status = document.getElementById("char-routine-gen-status");
  const GEN = window.XXJ_ROUTINE_GEN;
  const ROUTINE = window.XXJ_ROUTINE;
  if (!GEN || typeof GEN.generateFromPersona !== "function") {
    if (status) status.textContent = "生成器未加载";
    return;
  }
  // 当前 persona(从表单实时读)
  let p = readCharPersona();
  // 合并表单上未持久化的 routinePreset(用户可能刚选过)
  const draftPreset = readCharRoutinePresetFromForm();
  if (draftPreset) p.routinePreset = draftPreset;
  // persona 取不到: 兜底到 store 里第一个有显示名的角色(用户可能进了档案页但还没激活)
  if (!p || !p.id) {
    try {
      const D2 = window.XXJ_DB;
      if (D2 && D2.getKv && D2.K && D2.K.CHAR_PERSONA_STORE) {
        const st = D2.getKv(D2.K.CHAR_PERSONA_STORE);
        if (st && Array.isArray(st.items) && st.items.length) {
          const fb = st.items.find(x => x && x.id && (x.displayName || x.summary)) || st.items[0];
          if (fb && fb.id) {
            p = { ...fb, ...p };
            if (typeof showToast === "function") showToast("未检测到激活角色,已使用「" + String(p.displayName || "该角色") + "」");
          }
        }
      }
    } catch { /* ignore */ }
    if (!p || !p.id) {
      if (status) status.textContent = "请先新建一个角色档案";
      return;
    }
  }
  if (!p.displayName && !p.summary) {
    if (status) status.textContent = "请先填写显示名或人设概要";
    return;
  }

  if (btn) btn.disabled = true;
  if (status) status.textContent = "生成中…";

  try {
    // preset hint:如果 persona 选了某个 preset,让 LLM 沿用风格
    const presetSlug = String(p.routinePreset || "").trim();
    let presetHint = null;
    if (presetSlug) {
      const preset = (window.XXJ_STATE_PRESETS || {})[presetSlug];
      if (preset) {
        presetHint = {
          label: preset.meta && preset.meta.label || presetSlug,
          schedule: Array.isArray(preset.schedule) ? preset.schedule.slice(0, 8) : []
        };
      }
    }
    const gen = await GEN.generateFromPersona(p, { presetHint });
    if (!gen || gen.ok !== true || !Array.isArray(gen.schedule)) {
      // 把具体原因 + LLM 实际返回的前 60 字显示出来
      let reason = "unknown";
      let snippet = "";
      if (gen && typeof gen === "object") {
        reason = String(gen.reason || "unknown");
        if (typeof gen.raw === "string") snippet = gen.raw.slice(0, 60).replace(/\s+/g, " ");
        else if (gen.error) snippet = String(gen.error).slice(0, 60);
      } else if (!gen) {
        reason = "null-result";
      }
      const labelMap = {
        "llm-call-failed": "LLM 调用失败",
        "empty-response": "LLM 返回为空",
        "no-json-array": "LLM 没返回 JSON 数组",
        "json-parse-failed": "LLM 返回内容不是有效 JSON",
        "normalize-empty": "LLM 返回的 schedule 校验失败(可能时段不齐)"
      };
      const label = labelMap[reason] || ("失败:" + reason);
      if (status) status.textContent = label + (snippet ? " | " + snippet + "…" : "");
      return;
    }
    // 写到 IndexedDB 里的 routine(用 registry load + setSchedule + save)
    let routine = null;
    if (ROUTINE && typeof ROUTINE.load === "function") {
      routine = await ROUTINE.load(p.id);
    }
    if (!routine) {
      if (status) status.textContent = "生成失败:无法加载角色 routine";
      return;
    }
    const ok = await GEN.applyToRoutine(routine, gen);
    if (!ok) {
      if (status) status.textContent = "生成失败:写入 routine 失败";
      return;
    }
    const segCount = gen.schedule.length;
    if (status) status.textContent = "已生成 " + segCount + " 段作息并应用到当前角色";
    // 给 LI · 位置条一个 re-render 信号
    if (window.XXJ_STATE_EVENTS && window.XXJ_STATE_EVENTS.emit) {
      window.XXJ_STATE_EVENTS.emit("rp-routine-changed", { charId: p.id, source: "自动" });
    }
    if (typeof showToast === "function") {
      showToast("已为「" + String(p.displayName || "该角色") + "」生成专属作息");
    }
  } catch (e) {
    console.warn("[CASE] routine-gen failed:", e);
    if (status) status.textContent = "生成失败:" + (e && e.message || "未知错误");
  } finally {
    if (btn) btn.disabled = false;
  }
}

