/** SillyTavern 卡：JSON 常为 { data: { ... } }；PNG chara 块解码后同结构 */
function unwrapTavernCharRoot(raw) {
  if (!raw || typeof raw !== "object") return {};
  if (raw.data && typeof raw.data === "object") return raw.data;
  return raw;
}

/**
 * 自 PNG 二进制扫描 tEXt / keyword `chara`（与 SillyTavern 一致），返回解析后的 JSON 根对象。
 * @param {ArrayBuffer} buffer
 * @returns {object|null}
 */
function extractCharaJsonFromPngBuffer(buffer) {
  const hit = extractTavernCardFromPngBuffer(buffer);
  return hit?.cardRoot || null;
}

function shrinkDataUrlWithCanvas(dataUrl, maxSide, quality) {
  return new Promise((resolve) => {
    const im = new Image();
    im.onload = () => {
      try {
        let w = im.naturalWidth || im.width;
        let h = im.naturalHeight || im.height;
        if (!w || !h) {
          resolve(dataUrl);
          return;
        }
        const scale = Math.min(1, maxSide / Math.max(w, h));
        const nw = Math.max(1, Math.round(w * scale));
        const nh = Math.max(1, Math.round(h * scale));
        const c = document.createElement("canvas");
        c.width = nw;
        c.height = nh;
        const ctx = c.getContext("2d");
        if (!ctx) {
          resolve(dataUrl);
          return;
        }
        ctx.drawImage(im, 0, 0, nw, nh);
        resolve(c.toDataURL("image/jpeg", quality));
      } catch {
        resolve(dataUrl);
      }
    };
    im.onerror = () => resolve(dataUrl);
    im.src = dataUrl;
  });
}

function tavernTagsToLine(tags) {
  if (tags == null) return "";
  if (Array.isArray(tags)) return tags.map((x) => String(x).trim()).filter(Boolean).join(" · ");
  return String(tags).trim();
}

/** 密谈绑定的角色人设（非「当前正在编辑」的激活角色）。群 assistant 配图优先 speakerCharId。 */
function readThreadBoundCharPersonaForImageGen(thread, msg) {
  let id = "";
  if (msg && typeof msg === "object") {
    const mo = msg;
    if (thread?.kind === "group" && mo.role === "assistant") {
      id = String(mo.speakerCharId || "").trim();
    }
  } else if (typeof msg === "string") {
    id = String(msg).trim();
  }
  if (!id) id = thread && typeof thread === "object" ? String(thread.charId || "").trim() : "";
  if (!id) return null;
  const st = readCharPersonaStore();
  const it = st.items.find((x) => String(x?.id || "") === id);
  if (!it) return null;
  return { ...emptyCharPersona(), ...pickCharPersonaBody(it) };
}

/** 密谈当前 activePersona 对应的人设（大号 / 马甲）。 */
function readCharPersonaForThread(thread) {
  const th = thread && typeof thread === "object" ? thread : readActiveThread();
  return resolveCharPersonaForThreadSlot(th, getThreadActivePersona(th));
}

/** @param {ReturnType<typeof readActiveThread>} thread @param {{ quiet?: boolean }} [opts] */
function ensureCharPersonaMatchesThread(thread, opts) {
  if (!thread || thread.kind === "group") return;
  const cid = String(thread.charId || "").trim();
  if (!cid) return;
  activateCharPersonaById(cid, { quiet: Boolean(opts && opts.quiet) });
}

/**
 * @param {{ boundThread?: object, boundMaskId?: string, boundThreadId?: string }} [opts]
 * @returns {ReturnType<typeof readActiveThread>}
 */
function resolveChatPromptThread(opts) {
  if (!opts || typeof opts !== "object") return readActiveThread();
  const mid = String(opts.boundMaskId || "").trim();
  const tid = String(opts.boundThreadId || "").trim();
  /* 须优先按 id 从 inbox 取最新线程（含 activePersona）；boundThread 可能是 sendPin 时的旧引用，落盘 normalize 后会与 UI 脱节 */
  if (mid && tid) {
    const found = findChatThreadInInbox(mid, tid);
    if (found) return found.thread;
  }
  if (opts.boundThread && typeof opts.boundThread === "object") return opts.boundThread;
  return readActiveThread();
}

/** @returns {string} */
function chatThreadMsgsHydrateKey(maskId, threadId) {
  const storeMaskKey = maskBucketKey(maskId);
  const tid = String(threadId || "").trim();
  const D = window.XXJ_DB;
  return D && typeof D.chatThreadKey === "function"
    ? D.chatThreadKey(storeMaskKey, tid)
    : `${storeMaskKey}\x1f${tid}`;
}

/** 分表消息是否正在从 IndexedDB 灌入（仅 inflight 才算「加载中 UI」）。 */
function isActiveChatMessagesHydrating(maskId, threadId, th) {
  if (!th || !threadMessagesNeedHydrate(th)) return false;
  return chatThreadMsgsHydrateInflight.has(chatThreadMsgsHydrateKey(maskId, threadId));
}

/** @returns {"loading-inbox"|"loading-messages"|"missing-ref"|"missing-thread"|"ready"} */
function resolveActiveChatThreadLoadState() {
  const D = window.XXJ_DB;
  if (D && D.isReady && !D.isInboxHydrated) return "loading-inbox";
  reconcileActiveThreadRef();
  const maskId = String(getActiveMaskIdForInbox() || "").trim();
  const threadId = String(readChatActiveThreadRef().threadId || "").trim();
  if (!maskId || !threadId) return "missing-ref";
  const found = findChatThreadInInbox(maskId, threadId);
  if (!found) return "missing-thread";
  if (isActiveChatMessagesHydrating(maskId, threadId, found.thread)) return "loading-messages";
  return "ready";
}

/** @param {"loading-inbox"|"loading-messages"|"missing-ref"|"missing-thread"|"ready"} [loadState] */
function showChatThreadUnavailableToast(loadState) {
  const st = loadState || resolveActiveChatThreadLoadState();
  if (st === "loading-inbox") {
    showToast("密谈列表加载中，请稍候再试");
    return;
  }
  if (st === "loading-messages") {
    showToast("聊天记录加载中，请稍候再试");
    return;
  }
  if (st === "missing-thread") {
    showToast("找不到这条密谈，请返回列表重新进入");
    return;
  }
  showToast("没有可用的密谈线程");
}

/** @returns {{ maskId: string, threadId: string, thread: object } | null} */
function beginChatSendPin(opts) {
  reconcileActiveThreadRef();
  const maskId = String(getActiveMaskIdForInbox() || "").trim();
  const threadId = String(readChatActiveThreadRef().threadId || "").trim();
  if (!maskId || !threadId) return null;
  const D = window.XXJ_DB;
  const lazyStoresReady =
    D &&
    kvStoreV2ItemsLoaded(D.getKv(D.K.CHAR_PERSONA_STORE)) &&
    worldBookStoreLoaded(D.getKv(D.K.WORLD_BOOK_STORE)) &&
    stickerStoreLoaded(D.getKv(D.K.STICKER_STORE));
  if (!opts?.afterLazyHydrate && !window.__xxjOtherKvReady && !lazyStoresReady) return null;
  const found = findChatThreadInInbox(maskId, threadId);
  if (!found) return null;
  ensureCharPersonaMatchesThread(found.thread, { quiet: true });
  return { maskId, threadId, thread: found.thread };
}

/** inbox / lazy KV 灌入后再取 pin。 */
async function beginChatSendPinAsync() {
  await ensureChatInboxForUi();
  await ensureChatLazyStoresForRound();
  return beginChatSendPin({ afterLazyHydrate: true });
}

/** @param {{ maskId: string, threadId: string }} pin */
function readChatLogForSendPin(pin) {
  return readChatLogForMaskThread(pin.maskId, pin.threadId);
}

/** @param {{ maskId: string, threadId: string }} pin @param {unknown[]} entries */
function saveChatLogForSendPin(pin, entries) {
  saveChatLogForMaskThread(pin.maskId, pin.threadId, entries);
}

/** @param {{ maskId: string, threadId: string, thread?: object }} pin */
function chatRoundBoundFromPin(pin) {
  return {
    boundMaskId: pin.maskId,
    boundThreadId: pin.threadId,
    boundThread: pin.thread
  };
}

function sliceForImageGenPrompt(s, max) {
  const t = String(s || "")
    .trim()
    .replace(/\s+/g, " ");
  if (!t) return "";
  return t.length <= max ? t : `${t.slice(0, Math.max(0, max - 1))}…`;
}

/** @typedef {"auto"|"char"|"user"|"both"|"object"|"scene"|"other"} ImageGenSubject */

/** @param {unknown} raw @returns {ImageGenSubject} */
function normalizeImageSubject(raw) {
  const s = String(raw ?? "")
    .trim()
    .toLowerCase()
    .replace(/-/g, "_");
  if (s === "auto" || s === "char" || s === "user" || s === "both" || s === "object" || s === "scene" || s === "other") {
    return /** @type {ImageGenSubject} */ (s);
  }
  if (s === "item" || s === "prop" || s === "still_life" || s === "stilllife") return "object";
  if (s === "landscape" || s === "environment" || s === "background") return "scene";
  if (s === "selfie" || s === "self" || s === "me") return "user";
  if (s === "together" || s === "duo" || s === "couple") return "both";
  if (s === "npc" || s === "stranger") return "other";
  return "auto";
}

/**
 * 模型 JSON：画面主体（可选）；与 charImage / imageSceneCaption 并列。
 * @param {unknown} o
 * @returns {ImageGenSubject}
 */
function parseImageSubjectFromAssistantJson(o) {
  if (!o || typeof o !== "object") return "auto";
  const rec = /** @type {Record<string, unknown>} */ (o);
  const top = rec.imageSubject ?? rec.image_subject ?? rec.sceneImageSubject ?? rec.scene_image_subject;
  if (top != null && String(top).trim()) return normalizeImageSubject(top);
  for (const ci of iterAssistantJsonImageContainers(o)) {
    const c = /** @type {Record<string, unknown>} */ (ci);
    const sub = c.subject ?? c.imageSubject ?? c.image_subject;
    if (sub != null && String(sub).trim()) return normalizeImageSubject(sub);
  }
  return "auto";
}

/** @param {ReturnType<typeof readActiveThread>} thread */
function charDisplayNamesForImageInfer(thread) {
  const names = [];
  if (thread?.kind === "group" && window.XXJ_GroupChat?.memberCharIds) {
    for (const cid of window.XXJ_GroupChat.memberCharIds(thread)) {
      const it = getCharPersonaItemById(cid);
      if (!it) continue;
      const dn = String(it.displayName || "").trim();
      if (dn && !names.includes(dn)) names.push(dn);
      const al = String(it.aliases || "")
        .split(/[,，、·|/;\s]+/)
        .map((x) => x.trim())
        .filter(Boolean);
      for (const a of al) if (!names.includes(a)) names.push(a);
    }
    return names;
  }
  const ch = readThreadBoundCharPersonaForImageGen(thread);
  if (ch) {
    const dn = String(ch.displayName || "").trim();
    if (dn) names.push(dn);
    const al = String(ch.aliases || "")
      .split(/[,，、·|/;\s]+/)
      .map((x) => x.trim())
      .filter(Boolean);
    for (const a of al) if (!names.includes(a)) names.push(a);
  }
  try {
    const remark = thread && String(thread.charThreadRemarkName || "").trim();
    if (remark && !names.includes(remark)) names.push(remark);
  } catch (_) {
    /* ignore */
  }
  return names;
}

const IMAGE_GEN_USER_SCENE_RE =
  /(?:自拍|镜子|镜面|我\b|我的|本人|主控|mirror\s*selfie|selfie|self[\s-]?portrait|\bmy\s+(?:face|self|photo))/iu;

/** 主控发图：描述里在拍「自己」的场面（优先按主控出图，不套密谈角色立绘）。 */
const USER_SELFIE_SCENE_RE =
  /(?:自拍|镜面|镜子|照镜子|对镜|前置摄像头|本人|我的脸|我的照片|我穿|我站|我坐|我举|我拿|selfie|self[\s-]?portrait|mirror\s*selfie)/iu;

/** 主控发图：明确双人/合影意图（不必写角色名，默认与当前密谈角色同框）。 */
const USER_GROUP_PHOTO_SCENE_RE =
  /(?:我们俩|咱俩|合影|合照|同框|一起拍|双人照|双人合影|情侣照|与.{0,8}一起|和.{0,8}一起|couple\s*photo|group\s*photo|together\s*photo|\b2\s*people\b|\btwo\s*people\b|\b1\s*boy\s*1\s*girl\b)/iu;

/**
 * @param {string} text
 * @param {string[]} charNames
 * @param {{ senderRole?: "user" | "assistant", offlineMeetup?: boolean }} [opts]
 * @returns {Record<Exclude<ImageGenSubject, "auto">, number>}
 */
function scoreImageSubjectFromSceneText(text, charNames, opts) {
  const t = String(text || "").trim();
  const low = t.toLowerCase();
  const senderRole = opts && opts.senderRole === "user" ? "user" : "assistant";
  const offlineMeetup = Boolean(opts && opts.offlineMeetup);
  /** @type {Record<Exclude<ImageGenSubject, "auto">, number>} */
  const s = { char: 0, user: 0, both: 0, object: 0, scene: 0, other: 0 };
  if (!t) return s;

  const objectRe =
    /(?:咖啡|奶茶|外卖|订单|小票|发票|收据|票根|机票|车票|菜单|截图|梗图|表情包|礼物盒|礼盒|戒指|项链|钥匙|手机屏|电脑屏|快递|包裹|盒子|杯子|蛋糕|食物|美食|文件|合同|纸条|明信片|拍立得|手办|模型|still\s*life|food|coffee|ticket|receipt|invoice|screenshot|package|box|gift|no\s+humans|object\s+focus)/iu;
  const sceneRe =
    /(?:窗外|晚霞|夕阳|夜景|天空|雨景|街道|风景|海边|沙滩|森林|雪山|城市天际|室内空镜|空镜|远景|全景|landscape|scenery|cityscape|night\s+sky|sunset|sunrise|wide\s+shot|establishing\s+shot|no\s+humans)/iu;
  const userRe = IMAGE_GEN_USER_SCENE_RE;
  const bothRe =
    /(?:我们俩|咱俩|合影|合照|同框|一起拍|双人|两人|couple|together|2\s*people|two\s*people|1\s*boy\s*1\s*girl|2\s*girls?|2\s*boys?)/iu;
  const otherRe =
    /(?:店员|服务员|路人|陌生人|同事|老板|司机|医生|护士|npc|stranger|bystander|shop\s*clerk)/iu;

  if (objectRe.test(t)) s.object += 3;
  if (sceneRe.test(t)) s.scene += 3;
  if (userRe.test(t)) s.user += 3;
  if (bothRe.test(t)) s.both += 4;
  if (otherRe.test(t)) s.other += 3;
  if (/no\s+humans|still\s*life|object\s+focus|product\s+shot/iu.test(low)) {
    s.object += 4;
    s.char -= 1;
    s.user -= 1;
  }
  if (/\b(?:solo|1\s*girl|1\s*boy|1\s*person)\b/i.test(low) && !bothRe.test(t)) {
    if (senderRole === "assistant") {
      if (offlineMeetup) {
        s.both += 2;
        s.char += 1;
      } else {
        s.char += 2;
      }
    } else {
      s.user += 2;
    }
  }

  if (offlineMeetup && senderRole === "assistant") {
    const meetRe =
      /(?:我们俩|咱俩|合影|合照|同框|对面|相对|并肩|同席|同桌|当面|你\b|你们|两人|双人|对视|牵手|拥抱|并肩坐|face-to-face|facing|together|2\s*people|two\s*people|1\s*boy\s*1\s*girl|couple)/iu;
    if (meetRe.test(t)) s.both += 3;
    if (!/\b(?:solo|only|1girl|1boy|1person)\b/i.test(low) && s.object < 3 && s.scene < 3) {
      s.both += 2;
    }
  }

  for (const nm of charNames) {
    if (!nm || nm.length < 2) continue;
    if (senderRole === "user") continue;
    if (t.includes(nm)) s.char += 2;
  }

  const hasPersonWord = /(?:人|脸|少女|少年|女孩|男孩|她|他|girl|boy|woman|man|person|face)/iu.test(t);
  if (!hasPersonWord && (s.object > 0 || s.scene > 0)) {
    s.object += 1;
    s.scene += 1;
  }
  return s;
}

/**
 * 从画面描述推断主体（不看上一轮聊天；模型/入库显式 imageSubject 由调用方先处理）。
 * @param {string} scene
 * @param {"user"|"assistant"} role
 * @param {ReturnType<typeof readActiveThread>} thread
 * @param {Record<Exclude<ImageGenSubject, "auto">, number>} scores
 */
function resolveImageSubjectFromSceneScores(scene, role, thread, scores) {
  const s = String(scene || "").trim();
  let bestKey = /** @type {Exclude<ImageGenSubject, "auto">} */ (role === "assistant" ? "char" : "scene");
  let bestScore = -1;
  for (const k of /** @type {(keyof typeof scores)[]} */ (Object.keys(scores))) {
    if (scores[k] > bestScore) {
      bestScore = scores[k];
      bestKey = k;
    }
  }

  if (role === "assistant") {
    if (sceneDepictsUserFigureForAssistantImage(s, thread)) {
      return { subject: "user", confidence: "high" };
    }
    if (userImageGenSceneHasExplicitBoth(s, thread)) {
      return { subject: "both", confidence: "high" };
    }
    if (bestScore >= 4) {
      return { subject: bestKey, confidence: "high" };
    }
    if (bestScore >= 2 && (bestKey === "object" || bestKey === "scene" || bestKey === "other")) {
      return { subject: bestKey, confidence: "medium" };
    }
    if (bestKey === "both" && bestScore >= 2) {
      return { subject: "both", confidence: "medium" };
    }
    // 角色发图：场面有人物向信息但未写明主控 → 默认角色本人
    return { subject: "char", confidence: bestScore >= 2 ? "medium" : "low" };
  }

  if (userImageGenSceneHasExplicitBoth(s, thread)) {
    return { subject: "both", confidence: "high" };
  }
  if (userImageGenTreatSceneAsUserPrimary(s, thread)) {
    return { subject: "user", confidence: "high" };
  }
  const namesCharInScene = sceneMentionsCharDisplayName(s, thread);
  if (bestScore >= 4 && (bestKey === "object" || bestKey === "scene" || bestKey === "other" || bestKey === "both")) {
    return { subject: bestKey, confidence: "high" };
  }
  if (bestScore >= 2 && (bestKey === "object" || bestKey === "scene")) {
    return { subject: bestKey, confidence: "medium" };
  }
  if (bestKey === "user" && bestScore >= 3 && IMAGE_GEN_USER_SCENE_RE.test(s)) {
    return { subject: "user", confidence: "high" };
  }
  if (bestKey === "both" && bestScore >= 4) {
    return { subject: "both", confidence: "high" };
  }
  if (namesCharInScene && bestKey === "char" && bestScore >= 2) {
    return { subject: "char", confidence: bestScore >= 4 ? "high" : "medium" };
  }
  return { subject: "scene", confidence: bestScore >= 2 ? "medium" : "low" };
}

/**
 * @param {unknown} msg
 * @param {ReturnType<typeof readActiveThread>} thread
 * @param {string} sceneText
 * @param {unknown[]} [logArr]
 * @returns {{ subject: ImageGenSubject, confidence: "high"|"medium"|"low" }}
 */
function inferImageSubjectFromContext(msg, thread, sceneText, logArr) {
  const mo = msg && typeof msg === "object" ? msg : null;
  const im = mo?.image && typeof mo.image === "object" ? mo.image : null;
  const role = mo && mo.role === "user" ? "user" : "assistant";
  const explicit = im ? normalizeImageSubject(im.imageSubject) : "auto";
  if (explicit !== "auto") {
    return { subject: explicit, confidence: "high" };
  }
  const scene = String(sceneText || (im && (im.scenePrompt || im.desc)) || "").trim();
  const charNames = charDisplayNamesForImageInfer(thread);
  const scores = scoreImageSubjectFromSceneText(scene, charNames, { senderRole: role });
  if (role === "user" && IMAGE_GEN_USER_SCENE_RE.test(scene)) scores.user += 1;
  return resolveImageSubjectFromSceneScores(scene, role, thread, scores);
}

/**
 * @param {unknown} msg
 * @param {ReturnType<typeof readActiveThread>} thread
 * @param {string} sceneText
 * @param {unknown[]} [logArr]
 */
function resolveImageGenPlan(msg, thread, sceneText, logArr) {
  const inf = inferImageSubjectFromContext(msg, thread, sceneText, logArr);
  const role = msg && typeof msg === "object" && msg.role === "user" ? "user" : "assistant";
  /** @type {{ subject: ImageGenSubject, confidence: string, includeCharStrong: boolean, includeCharWeak: boolean, includeUser: boolean, useRef: boolean }} */
  const plan = {
    subject: inf.subject,
    confidence: inf.confidence,
    includeCharStrong: false,
    includeCharWeak: false,
    includeUser: false,
    useRef: false
  };

  if (role === "user") {
    finalizeImageGenPlanForUserSender(plan, inf, thread, sceneText);
    applyStoredUserImageGenPlan(plan, msg, sceneText, thread);
    clampUserDescImageGenPlan(plan, sceneText, thread);
    return plan;
  }

  switch (plan.subject) {
    case "char":
      plan.includeCharStrong = true;
      plan.includeUser = false;
      plan.useRef = inf.confidence !== "low";
      break;
    case "user":
      plan.includeUser = true;
      plan.includeCharStrong = false;
      plan.includeCharWeak = false;
      plan.useRef = false;
      break;
    case "both":
      plan.includeCharStrong = true;
      plan.includeUser = true;
      plan.useRef = inf.confidence !== "low";
      break;
    case "object":
    case "scene":
      plan.includeCharWeak = inf.confidence === "medium";
      break;
    case "other":
      plan.includeCharWeak = true;
      break;
  }

  // assistant 发图：默认画角色本人；仅模型/场面明确指向主控时才 user
  if (role === "assistant" && plan.subject === "user") {
    const storedSub = normalizeImageSubject(
      msg && typeof msg === "object" && msg.image && typeof msg.image === "object"
        ? msg.image.imageSubject
        : "auto"
    );
    const scene = String(sceneText || "").trim();
    if (storedSub === "auto" && !sceneDepictsUserFigureForAssistantImage(scene, thread)) {
      plan.subject = "char";
      plan.includeCharStrong = true;
      plan.includeUser = false;
      plan.includeCharWeak = false;
      plan.useRef = inf.confidence !== "low";
    }
  }

  return plan;
}

/** 线下晤面生图：外貌 tag 略加重（含中文摘要规则抽取） */
const OFFLINE_IMAGE_GEN_CHAR_TAGS_MAX = 320;
const OFFLINE_IMAGE_GEN_CHAR_TAGS_TOTAL_MAX = 480;
const OFFLINE_IMAGE_GEN_SCENE_HEAD_TAGS_MAX = 200;

/** @param {...string} parts */
function mergeImageGenCommaTags(...parts) {
  const seen = new Set();
  /** @type {string[]} */
  const out = [];
  for (const p of parts) {
    for (const t of String(p || "").split(/[,·;]/)) {
      const s = t.trim().replace(/\s+/g, " ");
      if (!s) continue;
      const k = s.toLowerCase();
      if (seen.has(k)) continue;
      seen.add(k);
      out.push(s);
    }
  }
  return out.join(", ");
}

/** @param {ReturnType<typeof readThreadBoundCharPersonaForImageGen>} ch */
function charPersonaTextBlobForImageGen(ch) {
  if (!ch || typeof ch !== "object") return "";
  return [ch.summary, ch.tags, ch.aliases, ch.voice, ch.boundaries, ch.npcRelations]
    .map((x) => String(x || "").trim())
    .filter(Boolean)
    .join("\n");
}

/** @param {string} text */
function extractEmbeddedEnglishImageTagsFromText(text) {
  const src = String(text || "");
  if (!src.trim()) return "";
  /** @type {string[]} */
  const parts = [];
  const seen = new Set();
  const add = (tag) => {
    const s = String(tag || "").trim().replace(/\s+/g, " ");
    if (!s || s.length < 2) return;
    const k = s.toLowerCase();
    if (seen.has(k)) return;
    seen.add(k);
    parts.push(s);
  };
  const re =
    /\b(?:1girl|1boy|2girls|2boys|solo|long\s+hair|short\s+hair|medium\s+hair|twintails|ponytail|side\s+ponytail|braid|hair\s+bun|bangs|blunt\s+bangs|wavy\s+hair|straight\s+hair|black\s+hair|white\s+hair|blonde\s+hair|brown\s+hair|red\s+hair|silver\s+hair|blue\s+hair|pink\s+hair|purple\s+hair|green\s+hair|grey\s+hair|red\s+eyes|blue\s+eyes|green\s+eyes|purple\s+eyes|golden\s+eyes|amber\s+eyes|brown\s+eyes|heterochromia|pale\s+skin|fair\s+skin|dark\s+skin|tanned\s+skin|slender|petite|tall|mature\s+female|office\s+lady|school\s+uniform|sailor\s+uniform|kimono|hanfu|cheongsam|qipao|dress|skirt|pleated\s+skirt|shirt|blouse|sweater|hoodie|jacket|coat|suit|tie|glasses|earrings|necklace|maid|swimsuit|bikini|pajamas|uniform|smile|gentle\s+smile|expressionless|blush)\b/gi;
  let m;
  while ((m = re.exec(src)) !== null) {
    add(m[0]);
    if (parts.length >= 24) break;
  }
  return parts.join(", ");
}

/**
 * 从中文人设摘要/tags 等抽英文外貌 danbooru 式关键词（不调模型）。
 * @param {string} text
 * @param {number} [maxTags]
 */
function extractCharAppearanceKeywordsFromChinesePersona(text, maxTags) {
  const src = String(text || "").trim();
  if (!src || !/[\u4e00-\u9fff]/.test(src)) return "";
  const cap = Number(maxTags) > 0 ? Math.floor(maxTags) : 18;
  const rules = [
    [/美少女|女孩子|少女|女生|女子|小姐姐|姑娘|女主/u, "young woman"],
    [/美少年|男孩子|少年|男生|男子|小哥哥|男主/u, "young man"],
    [/御姐|成熟女|职场女|ol装|ol风/u, "mature female"],
    [/萝莉|幼女|小小只|袖珍/u, "petite"],
    [/黑发|乌黑|墨发|黑长直/u, "black hair"],
    [/金发|亚麻发|浅金/u, "blonde hair"],
    [/银发|白发|雪白长发/u, "white hair"],
    [/棕发|褐发|栗色发/u, "brown hair"],
    [/红发|酒红发|赤发/u, "red hair"],
    [/粉发|樱花发/u, "pink hair"],
    [/蓝发|冰蓝发/u, "blue hair"],
    [/紫发/u, "purple hair"],
    [/绿发/u, "green hair"],
    [/灰发/u, "grey hair"],
    [/长发|及腰|披肩发/u, "long hair"],
    [/中长发/u, "medium hair"],
    [/短发|齐耳/u, "short hair"],
    [/双马尾/u, "twintails"],
    [/单马尾|马尾辫/u, "ponytail"],
    [/侧马尾/u, "side ponytail"],
    [/丸子头|发髻|盘发/u, "hair bun"],
    [/麻花辫|辫子/u, "braid"],
    [/卷发|波浪发/u, "wavy hair"],
    [/直发/u, "straight hair"],
    [/刘海|齐刘海|空气刘海/u, "bangs"],
    [/红眼|赤瞳|红宝石眼/u, "red eyes"],
    [/蓝眼|冰蓝眼|天蓝眼|海蓝眼/u, "blue eyes"],
    [/绿眼|翡翠眼/u, "green eyes"],
    [/金眼|琥珀眼|黄眼/u, "golden eyes"],
    [/紫眼|紫罗兰眼/u, "purple eyes"],
    [/黑眼|深棕眼/u, "brown eyes"],
    [/异色瞳/u, "heterochromia"],
    [/白皙|瓷白|雪白皮肤|冷白皮|白肤/u, "pale skin"],
    [/小麦色|古铜|晒黑/u, "tanned skin"],
    [/深色皮肤|黑皮/u, "dark skin"],
    [/高挑|腿长|颀长/u, "tall"],
    [/娇小|矮个/u, "petite"],
    [/纤细|苗条|清瘦|瘦削/u, "slender"],
    [/丰满|凹凸/u, "curvy"],
    [/肌肉|健壮/u, "muscular"],
    [/校服|学生装|jk制服|jk/u, "school uniform"],
    [/水手服/u, "sailor uniform"],
    [/西装|西服|正装/u, "suit"],
    [/领带/u, "tie"],
    [/和服/u, "kimono"],
    [/汉服|古装/u, "hanfu"],
    [/旗袍/u, "cheongsam"],
    [/连衣裙|连身裙/u, "dress"],
    [/短裙|百褶裙/u, "pleated skirt"],
    [/长裙/u, "long skirt"],
    [/衬衫|白衬衣/u, "shirt"],
    [/女式衬衫|blouse/u, "blouse"],
    [/毛衣|针织/u, "sweater"],
    [/连帽|卫衣|帽衫/u, "hoodie"],
    [/夹克|外套|大衣|风衣/u, "coat"],
    [/马甲|背心/u, "vest"],
    [/休闲装|便装|常服/u, "casual clothes"],
    [/女仆/u, "maid"],
    [/泳装|比基尼/u, "swimsuit"],
    [/睡衣|居家服/u, "pajamas"],
    [/制服/u, "uniform"],
    [/眼镜/u, "glasses"],
    [/耳环|耳饰/u, "earrings"],
    [/项链/u, "necklace"],
    [/冷脸|面无表情|扑克脸/u, "expressionless"],
    [/温柔笑|浅笑|含笑/u, "gentle smile"],
    [/坏笑|邪笑/u, "smirk"],
    [/脸红|羞|耳根红/u, "blush"]
  ];
  /** @type {string[]} */
  const tags = [];
  const seen = new Set();
  const add = (tag) => {
    const k = String(tag || "").trim().toLowerCase();
    if (!k || seen.has(k)) return;
    seen.add(k);
    tags.push(String(tag).trim());
  };
  for (const [re, en] of rules) {
    if (re.test(src)) add(en);
    if (tags.length >= cap) break;
  }
  return tags.slice(0, cap).join(", ");
}

/**
 * 人设是否明确为同人/二创（有专用 tag 字段、摘要声明行、或典型关键词）。
 * @param {ReturnType<typeof readThreadBoundCharPersonaForImageGen>} ch
 */
function isClearlyFanworkCharPersona(ch) {
  if (!ch || typeof ch !== "object") return false;
  if (String(ch.charFanworkTags || "").trim()) return true;
  const blob = charPersonaTextBlobForImageGen(ch);
  if (
    /(?:^|\n)\s*(?:同人(?:\s*(?:tag|生图))?|fanwork(?:\s*tags?)?|IP\s*tags?|生图\s*同人)[：:\s]+\S/im.test(
      blob
    )
  ) {
    return true;
  }
  return /(?:同人(?:向|角色|设定)?|fan\s*character|二创|(?:原著|原作)[：:《「]|出自《|源自(?:于)?|作品[：:《「]|IP[：:])/u.test(
    blob
  );
}

/** @param {string} blob */
function extractInlineFanworkTagsFromPersona(blob) {
  const src = String(blob || "");
  const lineRe =
    /(?:^|\n)\s*(?:同人(?:\s*(?:tag|生图))?|fanwork(?:\s*tags?)?|IP\s*tags?|生图\s*同人)[：:\s]+([^\n]+)/im;
  const m1 = src.match(lineRe);
  if (m1) return normalizeCharImageGenPromptTagLine(m1[1]);
  const pairRe =
    /(?:^|\n)\s*(?:角色(?:名)?|character)\s*[：:]\s*([^\n,，]+)\s*[,，]\s*(?:作品|series|from)\s*[：:]\s*([^\n]+)/im;
  const m2 = src.match(pairRe);
  if (m2) return normalizeCharImageGenPromptTagLine(`${m2[1]}, ${m2[2]}`);
  return "";
}

/**
 * 同人角色：角色名/作品名 danbooru tag（仅「明确同人」且有可解析 tag 时返回）。
 * @param {ReturnType<typeof readThreadBoundCharPersonaForImageGen>} ch
 */
function resolveCharFanworkImageGenTags(ch) {
  if (!isClearlyFanworkCharPersona(ch)) return "";
  const fromField = normalizeCharImageGenPromptTagLine(String(ch.charFanworkTags || ""));
  if (fromField) return fromField.slice(0, 500);
  const inline = extractInlineFanworkTagsFromPersona(charPersonaTextBlobForImageGen(ch));
  if (inline) return inline.slice(0, 500);
  return "";
}

/** NovelAI：同人 IP tag 加权 */
function emphasizeNovelAiFanworkTagLine(fanTags) {
  const parts = String(fanTags || "")
    .split(",")
    .map((t) => t.trim())
    .filter(Boolean);
  if (!parts.length) return "";
  if (parts.length <= 6) return parts.map((t) => `{${t}}`).join(", ");
  return parts.join(", ");
}

/** NovelAI：同人 tag 加 {}，其余外貌 tag 原样 */
function novelAiCharAppearanceTagsWithFanEmphasis(charTags, fanTags) {
  const body = String(charTags || "").trim();
  const fan = String(fanTags || "").trim();
  if (!fan) return body;
  const emph = emphasizeNovelAiFanworkTagLine(fan);
  if (!body) return emph;
  const fanSet = new Set(
    fan
      .split(",")
      .map((t) => t.trim().toLowerCase())
      .filter(Boolean)
  );
  const rest = body
    .split(",")
    .map((t) => t.trim())
    .filter((t) => t && !fanSet.has(t.toLowerCase()));
  return rest.length ? `${emph}, ${rest.join(", ")}` : emph;
}

/**
 * 从角色人设拼外貌 tag（tags + 中文摘要规则抽取 + 内嵌英文 tag）。
 * @param {ReturnType<typeof readThreadBoundCharPersonaForImageGen>} ch
 * @param {{ tagMax?: number, zhKwMax?: number }} [opts]
 */
function collectCharImageGenAppearanceTagsFromPersona(ch, opts) {
  const o = opts && typeof opts === "object" ? opts : {};
  const tagMax = Number(o.tagMax) > 0 ? Number(o.tagMax) : 220;
  const zhKwMax = Number(o.zhKwMax) > 0 ? Number(o.zhKwMax) : 18;
  const blob = charPersonaTextBlobForImageGen(ch);
  let tg = mergeImageGenCommaTags(
    sliceForImageGenPrompt(tavernTagsToLine(ch.tags), tagMax),
    extractEmbeddedEnglishImageTagsFromText(blob),
    zhKwMax > 0 ? extractCharAppearanceKeywordsFromChinesePersona(blob, zhKwMax) : ""
  );
  if (!tg && ch && String(ch.summary || "").trim()) {
    const sumBlob = String(ch.summary || "").trim();
    tg = mergeImageGenCommaTags(
      extractEmbeddedEnglishImageTagsFromText(sumBlob),
      extractCharAppearanceKeywordsFromChinesePersona(sumBlob, zhKwMax)
    );
  }
  return tg.replace(/\s*·\s*/g, ", ").replace(/\s+/g, " ").trim();
}

/**
 * 仅外貌 danbooru / 英文 tags（性别 + 人设），供线下生图加权。
 * @param {ReturnType<typeof readThreadBoundCharPersonaForImageGen>} ch
 * @param {number} [maxLen]
 */
function buildImageGenCharAppearanceTagsOnly(ch, maxLen) {
  if (!ch) return "";
  const bits = [];
  const cg = inferCharPersonaGenderForImageGen(ch);
  if (cg === "female") bits.push("1girl");
  else if (cg === "male") bits.push("1boy");
  const tg = collectCharImageGenAppearanceTagsFromPersona(ch, {
    tagMax: maxLen || OFFLINE_IMAGE_GEN_CHAR_TAGS_MAX,
    zhKwMax: 22
  });
  if (tg) bits.push(tg);
  return mergeImageGenCommaTags(...bits);
}

/** @param {string} blob @returns {"" | "female" | "male"} */
function inferGenderFromPersonaBlob(blob) {
  const text = String(blob || "");
  if (!text.trim()) return "";
  const female = /(?:\b1\s*girl\b|\bfemale\b|\bwoman\b|女性|女生|女孩|女子|少女|小姐姐|美少女|女主|女孩子)/iu.test(
    text
  );
  const male = /(?:\b1\s*boy\b|\bmale\b|\bman\b|男性|男生|男孩|男子|少年|小哥哥|美少年|男主|男孩子)/iu.test(
    text
  );
  if (female && !male) return "female";
  if (male && !female) return "male";
  const she = (text.match(/她/g) || []).length;
  const he = (text.match(/他/g) || []).length;
  if (she > he && she >= 1) return "female";
  if (he > she && he >= 1) return "male";
  if (/女/u.test(text) && !/男/u.test(text)) return "female";
  if (/男/u.test(text) && !/女/u.test(text)) return "male";
  if (/她|女友|女主人|女孩子/u.test(text) && !/(?:他|男友|男主人|男孩子)/u.test(text)) return "female";
  if (/(?:他|男友|男主人|男孩子)/u.test(text) && !/她|女友|女主人/u.test(text)) return "male";
  return "";
}

/** @param {ReturnType<typeof readUserMask>} [u] @returns {"" | "female" | "male"} */
function inferUserMaskGenderForImageGen(u) {
  const m = u && typeof u === "object" ? u : readUserMask();
  const blob = [m.persona, m.summary, m.displayName, m.boundaries]
    .map((x) => String(x || ""))
    .join("\n");
  return inferGenderFromPersonaBlob(blob);
}

/** @param {ReturnType<typeof readThreadBoundCharPersonaForImageGen>} ch @returns {"" | "female" | "male"} */
function inferCharPersonaGenderForImageGen(ch) {
  if (!ch || typeof ch !== "object") return "";
  const blob = [ch.summary, ch.tags, ch.displayName, ch.aliases, ch.boundaries, ch.npcRelations]
    .map((x) => String(x || ""))
    .join("\n");
  return inferGenderFromPersonaBlob(blob);
}

/** 主控自拍/主体为主控时，在场面描述前压 danbooru 性别 tag（模型对前部 tag 更敏感）。 */
function userImageGenGenderTagPrefix(u) {
  const g = inferUserMaskGenderForImageGen(u);
  if (g === "female") return "1girl, solo, female, woman, ";
  if (g === "male") return "1boy, solo, male, man, ";
  return "";
}

/** @param {ReturnType<typeof readUserMask>} [u] @param {{ sentByChar?: boolean }} [opts] */
function userFigureImageGenPromptDirectiveBlock(u, opts) {
  const o = opts && typeof opts === "object" ? opts : {};
  const sentByChar = Boolean(o.sentByChar);
  const g = inferUserMaskGenderForImageGen(u);
  const gender =
    g === "female"
      ? "主控面具为女性。画面主体必须是主控/用户本人，必须为女性，禁止画成男性或未说明性别的默认男角色。"
      : g === "male"
        ? "主控面具为男性。画面主体必须是主控/用户本人，必须为男性，禁止画成女性。"
        : "人物性别以场面描述为准；";
  const lead = sentByChar
    ? "【角色发主控照片】以上方场面 tags 为准出图；主体是主控（用户），不是密谈角色本人。不要套用角色立绘或角色参考图当主控外貌。"
    : "【主控发图】按上方「画面描述」出图，以场景与描述主体为准；不要默认画成密谈角色立绘或角色参考图，除非描述里明确写到该角色或要求合影/自拍。";
  return (
    lead +
    gender +
    (sentByChar
      ? "禁止把密谈角色（发图方）的立绘、参考图或性别特征当成画面主体。"
      : "禁止把密谈角色（对方）的立绘或参考图当成主控外貌。")
  );
}

/** @param {{ meetupBoth?: boolean, userTags?: string }} [opts] */
function buildImageGenUserPersonaBlock(opts) {
  const o = opts && typeof opts === "object" ? opts : {};
  const meetupBoth = Boolean(o.meetupBoth);
  if (String(o.userTags || "").trim()) return "";
  const u = readUserMask();
  const ub = [];
  const g = inferUserMaskGenderForImageGen(u);
  if (g === "female") {
    ub.push("User figure gender (must match): female / woman / 1girl");
    ub.push(
      meetupBoth
        ? "Offline meetup: include BOTH the user figure and the chat character in frame; match the scene tags above."
        : "Do NOT depict the chat character (the other person); this image is the user protagonist only."
    );
  } else if (g === "male") {
    ub.push("User figure gender (must match): male / man / 1boy");
    ub.push(
      meetupBoth
        ? "Offline meetup: include BOTH the user figure and the chat character in frame; match the scene tags above."
        : "Do NOT depict the chat character as the main subject unless the scene explicitly asks for both."
    );
  } else if (meetupBoth) {
    ub.push("Offline meetup: include both the user figure and the chat character when the scene describes two people.");
  }
  const unm = sliceForImageGenPrompt(u.displayName, 80);
  if (unm) ub.push(`User figure name: ${unm}`);
  const up = sliceForImageGenPrompt(u.persona, 500);
  if (up) ub.push(`User appearance / persona: ${up}`);
  const usm = sliceForImageGenPrompt(u.summary, 400);
  if (usm) ub.push(`User figure notes: ${usm}`);
  return ub.join("\n");
}

/** @param {string} scene @param {ReturnType<typeof readActiveThread>} thread */
function userImageGenSceneHasExplicitBoth(scene, thread) {
  const s = String(scene || "").trim();
  if (!s || !USER_GROUP_PHOTO_SCENE_RE.test(s)) return false;
  const namesChar = charDisplayNamesForImageInfer(thread).some(
    (nm) => nm && nm.length >= 2 && s.includes(nm)
  );
  if (namesChar) return true;
  return /(?:我们俩|咱俩|合影|合照|同框|双人|两人|一起拍|couple|2\s*people|two\s*people|1\s*boy\s*1\s*girl)/iu.test(s);
}

/** @param {ReturnType<typeof readUserMask>} [u] */
function userMaskDisplayNamesForImageGen(u) {
  const m = u && typeof u === "object" ? u : readUserMask();
  const names = [];
  const dn = String(m.displayName || "").trim();
  if (dn.length >= 2) names.push(dn);
  return names;
}

/** 场面描述是否出现密谈角色名（不含主控面具名）。 */
function sceneMentionsCharDisplayName(scene, thread) {
  const s = String(scene || "").trim();
  if (!s) return false;
  const userNames = userMaskDisplayNamesForImageGen();
  return charDisplayNamesForImageInfer(thread).some((nm) => {
    if (!nm || nm.length < 2 || !s.includes(nm)) return false;
    return !userNames.some((un) => un === nm);
  });
}

/**
 * 场面描述里是否提到「别的角色」名（相对当前密谈 char / 指定排除 id）。
 * @param {string} scene
 * @param {string} [excludeCharId]
 */
function detectImageDepictsOtherCharIdFromScene(scene, excludeCharId) {
  const s = String(scene || "").trim();
  if (!s) return "";
  const skip = String(excludeCharId || "").trim();
  const userNames = userMaskDisplayNamesForImageGen();
  const st = readCharPersonaStore();
  for (const it of st.items) {
    const cid = String(it?.id || "").trim();
    if (!cid || cid === skip) continue;
    const label = String(it?.displayName || "").trim();
    if (label.length < 2 || !s.includes(label)) continue;
    if (userNames.some((un) => un === label)) continue;
    return cid;
  }
  return "";
}

/**
 * 从密谈消息推断配图主体角色 id（发朋友圈 / 评论归因用）。
 * @param {unknown} m
 * @param {ReturnType<typeof readActiveThread>} thread
 */
function resolveChatImageSubjectCharIdForMoments(m, thread) {
  if (!m || typeof m !== "object" || !thread || thread.kind === "group") return "";
  const threadCharId = String(thread.charId || "").trim();
  if (m.role === "assistant") return threadCharId;
  const im = m.image && typeof m.image === "object" ? m.image : null;
  if (!im) return "";
  const scene = String(im.desc || im.scenePrompt || m.content || "").trim();
  const sub = normalizeImageSubject(im.imageSubject);
  if ((sub === "char" || sub === "both") && threadCharId) return threadCharId;
  const other = detectImageDepictsOtherCharIdFromScene(scene, threadCharId);
  if (other) return other;
  return "";
}

/**
 * 主控发图：描述指向主控本人（自拍 / 我 / 主控面具 displayName）。
 * @param {string} scene
 * @param {ReturnType<typeof readActiveThread>} thread
 */
function userImageGenTreatSceneAsUserPrimary(scene, thread) {
  const s = String(scene || "").trim();
  if (!s || userImageGenSceneHasExplicitBoth(s, thread)) return false;
  if (
    USER_SELFIE_SCENE_RE.test(s) ||
    IMAGE_GEN_USER_SCENE_RE.test(s) ||
    /(?:^|[^\w])我(?:的|在|穿|站|坐|拿|举|对|镜|正)/u.test(s)
  ) {
    return true;
  }
  if (userMaskDisplayNamesForImageGen().some((nm) => nm.length >= 2 && s.includes(nm))) {
    return true;
  }
  return false;
}

/** assistant 配图：场面是否明确在画主控（而非角色本人自拍）。 */
function sceneDepictsUserFigureForAssistantImage(scene, thread) {
  const s = String(scene || "").trim();
  if (!s) return false;
  if (userMaskDisplayNamesForImageGen().some((nm) => nm.length >= 2 && s.includes(nm))) return true;
  if (/(?:主控|这是你的|你的脸|你的样子|给你看看你自己|拍(?:的)?你)/u.test(s)) return true;
  if (
    /(?:^|[^\w])你(?:的)?(?:脸|自拍|照片|样子|穿搭|身影)/u.test(s) &&
    !sceneMentionsCharDisplayName(s, thread)
  ) {
    return true;
  }
  return false;
}

/**
 * @param {ReturnType<typeof resolveImageGenPlan>} plan
 * @param {{ subject: ImageGenSubject, confidence: string }} inf
 * @param {ReturnType<typeof readActiveThread>} thread
 * @param {string} sceneText
 */
function finalizeImageGenPlanForUserSender(plan, inf, thread, sceneText) {
  const scene = String(sceneText || "").trim();

  plan.includeCharWeak = false;
  plan.useRef = false;

  if (userImageGenSceneHasExplicitBoth(scene, thread)) {
    plan.subject = "both";
    plan.includeCharStrong = true;
    plan.includeUser = true;
    return;
  }

  plan.includeCharStrong = false;
  if (userImageGenTreatSceneAsUserPrimary(scene, thread)) {
    plan.subject = "user";
    plan.includeUser = true;
    return;
  }

  plan.includeUser = false;
  plan.includeCharStrong = false;
  if (plan.subject === "char" || plan.subject === "user" || plan.subject === "both") {
    plan.subject =
      inf.subject === "object" && inf.confidence !== "low" ? "object" : "scene";
  }
}

/**
 * 主控消息上已写入的 imageSubject（仅明确合影 / 明确写角色名且非自拍时尊重 char）。
 * @param {ReturnType<typeof resolveImageGenPlan>} plan
 * @param {unknown} msg
 * @param {string} sceneText
 * @param {ReturnType<typeof readActiveThread>} thread
 */
function applyStoredUserImageGenPlan(plan, msg, sceneText, thread) {
  const stored = normalizeImageSubject(
    msg && typeof msg === "object" && msg.image && typeof msg.image === "object"
      ? msg.image.imageSubject
      : "auto"
  );
  if (stored === "auto") return;
  const scene = String(sceneText || "").trim();
  if (userImageGenSceneHasExplicitBoth(scene, thread)) {
    plan.subject = "both";
    plan.includeUser = true;
    plan.includeCharStrong = true;
    plan.includeCharWeak = false;
    plan.useRef = false;
    return;
  }
  if (stored === "char") {
    if (userImageGenTreatSceneAsUserPrimary(scene, thread)) return;
    if (!sceneMentionsCharDisplayName(scene, thread)) return;
  }
  plan.subject = stored;
  plan.useRef = false;
  if (stored === "user") {
    plan.includeUser = true;
    plan.includeCharStrong = false;
    plan.includeCharWeak = false;
  } else if (stored === "both") {
    plan.includeUser = true;
    plan.includeCharStrong = true;
    plan.includeCharWeak = false;
  } else if (stored === "char") {
    plan.includeUser = false;
    plan.includeCharStrong = true;
    plan.includeCharWeak = false;
  } else {
    plan.includeUser = false;
    plan.includeCharStrong = false;
    plan.includeCharWeak = false;
  }
}

/** 主控描述式发图：自拍/主控主体时禁止回落到角色立绘与参考图。 */
function clampUserDescImageGenPlan(plan, sceneText, thread) {
  const scene = String(sceneText || "").trim();
  plan.useRef = false;
  if (userImageGenSceneHasExplicitBoth(scene, thread)) return;
  if (userImageGenTreatSceneAsUserPrimary(scene, thread)) {
    plan.subject = "user";
    plan.includeUser = true;
    plan.includeCharStrong = false;
    plan.includeCharWeak = false;
    return;
  }
  if (plan.subject === "both") return;
  if (plan.subject === "char") {
    if (!sceneMentionsCharDisplayName(scene, thread)) {
      plan.subject = "scene";
      plan.includeCharStrong = false;
      plan.includeUser = false;
    }
    return;
  }
  plan.includeCharStrong = false;
  plan.includeCharWeak = false;
}

/** @param {ReturnType<typeof resolveImageGenPlan>} plan @param {unknown} msg @param {string} scene @param {ReturnType<typeof readActiveThread>} thread */
function userImageGenShouldOmitChar(plan, msg, scene, thread) {
  if (plan.subject === "user") return true;
  if (!msg || msg.role !== "user") return false;
  if (plan.subject === "both" || userImageGenSceneHasExplicitBoth(scene, thread)) return false;
  if (plan.includeCharStrong && plan.subject === "char") return false;
  return userImageGenTreatSceneAsUserPrimary(scene, thread) || plan.includeUser;
}

/** 主控描述式发图写入 imageSubject（与 resolveImageGenPlan 一致）。 */
function resolveUserSessionImageSubjectForStorage(thread, sceneText, logArr) {
  const scene = String(sceneText || "").trim();
  return resolveImageGenPlan({ role: "user", image: { desc: scene } }, thread, scene, logArr).subject;
}

/** 重绘前：纠正历史误存的 char / 自拍误标（不另调 API）。 */
function reconcileUserSessionImageSubject(msg, thread) {
  if (!msg || msg.role !== "user" || !msg.image || typeof msg.image !== "object") return;
  const sub = normalizeImageSubject(msg.image.imageSubject);
  const scene = String(msg.image.scenePrompt || msg.image.desc || msg.content || "").trim();
  if (!scene) return;
  if (userImageGenSceneHasExplicitBoth(scene, thread)) {
    msg.image.imageSubject = "both";
    return;
  }
  if (userImageGenTreatSceneAsUserPrimary(scene, thread)) {
    msg.image.imageSubject = "user";
    return;
  }
  if (sub === "char") {
    if (!sceneMentionsCharDisplayName(scene, thread)) {
      msg.image.imageSubject = "scene";
    }
  }
}

/** NovelAI：去掉会话长 prompt 里的说明段，只留场面 tag 行。 */
function novelAiStripNonTagProse(raw) {
  let s = String(raw || "")
    .replace(/\r\n/g, "\n")
    .trim();
  if (!s) return "";
  const dropLine = (line) => {
    const t = String(line || "").trim();
    if (!t) return true;
    if (/^【/.test(t)) return true;
    if (/^(?:Character gender|User figure|User appearance|Also known as|Visual tone|Other figure in frame|Current story moment)\b/i.test(t)) {
      return true;
    }
    if (/must match|Do NOT|禁止|主控发图|密谈角色|Offline meetup|面向图像模型/i.test(t)) return true;
    return false;
  };
  const paras = s.split(/\n\n+/).map((p) => p.trim()).filter(Boolean);
  if (paras.length > 1) {
    const kept = paras.filter((p) => !dropLine(p.split("\n")[0]));
    if (kept.length) s = kept[0];
  }
  const lines = s
    .split("\n")
    .map((l) => l.trim())
    .filter((l) => l && !dropLine(l));
  if (lines.length) s = lines.join(", ");
  return s.replace(/\s+/g, " ").trim();
}

/** @param {string} scene @param {ReturnType<typeof resolveImageGenPlan>} plan @param {ReturnType<typeof readActiveThread>} thread */
function novelAiGenderLeadForPlan(plan, thread, msg) {
  if (!plan || plan.subject === "object" || plan.subject === "scene") return "";
  if (plan.subject === "user") return userImageGenGenderTagPrefix(readUserMask());
  if (plan.subject === "both") {
    return offlineMeetupImageGenderLead(thread, plan);
  }
  if (plan.subject === "char") {
    const ch = readThreadBoundCharPersonaForImageGen(thread, msg);
    const g = inferCharPersonaGenderForImageGen(ch);
    return g === "female" ? "1girl, solo, " : g === "male" ? "1boy, solo, " : "1person, solo, ";
  }
  return "";
}

/** 主控描述式发图（会话生图 API，role=user）。 */
function isUserDescSessionImageGenMsg(msg) {
  return Boolean(msg && typeof msg === "object" && msg.role === "user");
}

/**
 * 场面描述 → NovelAI 逗号 tag（主控发图中文原样；其余中文走离线关键词表；英文 tag 列表原样规范化）。
 * @param {string} sceneStr
 * @param {ReturnType<typeof readActiveThread>} thread
 * @param {ReturnType<typeof resolveImageGenPlan>} plan
 */
function novelAiSceneBlockToTags(sceneStr, thread, plan, msg) {
  let scene = novelAiStripNonTagProse(sceneStr).slice(0, 2000);
  if (!scene) return "";
  if (textLooksMostlyCjk(scene)) {
    if (isUserDescSessionImageGenMsg(msg)) {
      return scene.replace(/\s+/g, " ").trim().slice(0, 1800);
    }
    const fromZh = extractOfflineVisualKeywordsFromChinese(scene);
    const lead = novelAiGenderLeadForPlan(plan, thread, msg);
    if (fromZh) return `${lead}${fromZh}`.replace(/\s+/g, " ").trim();
    const head = offlineImageScenePromptHead(thread, plan).replace(/,\s*$/, "");
    return head ? `${head}, soft lighting` : "1person, soft lighting";
  }
  if (offlineImageSceneCaptionLooksLikeTagList(scene)) {
    let out = scene.replace(/\s*·\s*/g, ", ").replace(/\s*,\s*/g, ", ");
    if (!offlineScenePromptAlreadyHasSubjectLead(out)) {
      const lead = novelAiGenderLeadForPlan(plan, thread, msg).replace(/,\s*$/, "");
      if (lead) out = `${lead}${out}`.replace(/\s+/g, " ").trim();
    }
    return out.slice(0, 1800);
  }
  scene = scene
    .replace(/\s*·\s*/g, ", ")
    .replace(/[.!?。！？]+\s+/g, ", ")
    .replace(/\s+/g, " ")
    .trim();
  const lead = novelAiGenderLeadForPlan(plan, thread, msg);
  if (lead && !offlineScenePromptAlreadyHasSubjectLead(scene)) scene = `${lead}${scene}`;
  return scene.slice(0, 1800);
}

/**
 * @param {ReturnType<typeof readActiveThread>} thread
 * @param {ReturnType<typeof resolveImageGenPlan>} plan
 * @param {boolean} omitChar
 * @param {{ offline?: boolean }} [opts]
 */
function novelAiCharacterAppearanceTagsFromPersona(thread, plan, omitChar, opts) {
  if (omitChar || (!plan.includeCharStrong && !plan.includeCharWeak)) return "";
  const mo = opts && typeof opts === "object" ? opts.msg : undefined;
  const ch = readThreadBoundCharPersonaForImageGen(thread, mo);
  if (!ch) return "";
  const offline = Boolean(opts && opts.offline);
  const tagMax = offline
    ? plan.includeCharStrong
      ? OFFLINE_IMAGE_GEN_CHAR_TAGS_MAX
      : 200
    : plan.includeCharStrong
      ? 220
      : 120;
  const zhKwMax = plan.includeCharStrong ? 22 : plan.includeCharWeak ? 12 : 0;
  let tg = collectCharImageGenAppearanceTagsFromPersona(ch, { tagMax, zhKwMax });
  if (!tg) return "";
  const g = inferCharPersonaGenderForImageGen(ch);
  if (g === "female" && !/\b1girl\b/i.test(tg)) tg = `1girl, ${tg}`;
  else if (g === "male" && !/\b1boy\b/i.test(tg)) tg = `1boy, ${tg}`;
  const totalMax = offline ? OFFLINE_IMAGE_GEN_CHAR_TAGS_TOTAL_MAX : 400;
  return tg.slice(0, totalMax);
}

function novelAiCharacterAppearanceTags(thread, plan, omitChar, opts) {
  return resolveCharImageGenAppearanceForPrompt(thread, plan, omitChar, opts);
}

/**
 * NovelAI 专用：短 danbooru tag（对齐小心机 novelaiService.generateImage 拼装思路）。
 * @param {ReturnType<typeof normalizeImageGenConfig>} cfg
 * @param {ReturnType<typeof readActiveThread>} thread
 * @param {string} sceneBlockForApi
 * @param {{ offline?: boolean, plan?: ReturnType<typeof resolveImageGenPlan>, msg?: unknown, logArr?: unknown[] }} [opts]
 */
function buildNovelAiSessionImagePrompt(cfg, thread, sceneBlockForApi, opts) {
  const o = opts && typeof opts === "object" ? opts : {};
  const mo = o.msg && typeof o.msg === "object" ? o.msg : null;
  const sceneStr = String(sceneBlockForApi || "").trim();
  const plan =
    o.plan ||
    resolveImageGenPlan(mo || null, thread, sceneStr, Array.isArray(o.logArr) ? o.logArr : undefined);
  const omitChar = userImageGenShouldOmitChar(plan, mo, sceneStr, thread);
  const offline = o.offline === true;

  const parts = [];
  const chForFan = readThreadBoundCharPersonaForImageGen(thread, mo);
  const fanTags = chForFan && !omitChar ? resolveCharFanworkImageGenTags(chForFan) : "";
  const charTagsRaw = novelAiCharacterAppearanceTags(thread, plan, omitChar, { offline, msg: mo });
  const charTags = fanTags ? novelAiCharAppearanceTagsWithFanEmphasis(charTagsRaw, fanTags) : charTagsRaw;
  const pushCharAppearanceTags = () => {
    if (!charTags) return;
    const pieces = charTags
      .split(",")
      .map((t) => t.trim())
      .filter(Boolean);
    const emphasizeLimit = offline ? 14 : 0;
    if (offline && pieces.length > 0 && pieces.length <= emphasizeLimit) {
      parts.push(pieces.map((t) => `{${t}}`).join(", "));
    } else {
      parts.push(charTags);
    }
  };
  const pushSceneTags = () => {
    const sceneTags = novelAiSceneBlockToTags(sceneStr, thread, plan, mo);
    if (!sceneTags) return;
    const pieces = sceneTags
      .split(",")
      .map((t) => t.trim())
      .filter(Boolean);
    if (pieces.length > 0 && pieces.length <= 6) {
      parts.push(pieces.map((t) => `{${t}}`).join(", "));
    } else {
      parts.push(sceneTags);
    }
  };
  const pushUserAppearanceTags = () => {
    if (!plan.includeUser) return;
    const userTags = resolveUserImageGenAppearanceForPrompt(readUserMask(), plan, { offline, msg: mo });
    if (!userTags) return;
    const pieces = userTags
      .split(",")
      .map((t) => t.trim())
      .filter(Boolean);
    if (offline && pieces.length > 0 && pieces.length <= 14) {
      parts.push(pieces.map((t) => `{${t}}`).join(", "));
    } else {
      parts.push(userTags);
    }
  };
  pushCharAppearanceTags();
  pushUserAppearanceTags();
  pushSceneTags();

  let styleLine = "";
  if (omitChar) {
    styleLine = String(cfg?.stylePrompt || "").trim();
  } else {
    styleLine =
      o.offline === true
        ? resolveThreadOfflineSessionImageStyleSuffix(thread, cfg)
        : resolveThreadSessionImageStyleSuffix(thread, cfg);
    if (!styleLine) styleLine = String(cfg?.stylePrompt || "").trim();
  }
  if (styleLine) {
    const styleTags = styleLine
      .split(",")
      .map((t) => t.trim())
      .filter(Boolean)
      .map((t) => `[[[${t}]]]`)
      .join(", ");
    if (styleTags) parts.push(styleTags);
  }

  return parts.filter(Boolean).join(", ").slice(0, 2400);
}

/**
 * 按服务商选择 prompt：NovelAI 短 tag；OpenAI / 自定义亦用英文 tag（避免中文 summary 触发中转空 data[]）。
 * @param {ReturnType<typeof normalizeImageGenConfig>} cfg
 * @param {ReturnType<typeof readActiveThread>} thread
 * @param {string} sceneBlockForApi
 * @param {{ offline?: boolean, plan?: ReturnType<typeof resolveImageGenPlan>, msg?: unknown, logArr?: unknown[] }} [opts]
 */
function buildImageGenPromptForProvider(cfg, thread, sceneBlockForApi, opts) {
  if (cfg && cfg.provider === "novelai") {
    return buildNovelAiSessionImagePrompt(cfg, thread, sceneBlockForApi, opts);
  }
  return buildChatSessionImageGenPrompt(cfg, thread, sceneBlockForApi, opts);
}

/** 风格后缀 → OpenAI 逗号 tag（去掉 NovelAI 的 {} / [[[ ]] 语法）。 */
function openAiImageGenStyleTagsFromSuffix(styleLine) {
  return String(styleLine || "")
    .replace(/\[\[\[|\]\]\]/g, "")
    .replace(/[{}]/g, "")
    .replace(/\s*·\s*/g, ", ")
    .replace(/\s+/g, " ")
    .trim();
}

/** OpenAI 兼容：主控/用户主体图的英文短指令（勿注入中文说明段）。 */
function openAiUserFigureImageGenDirectiveBlock(u, opts) {
  const sentByChar = Boolean(opts && opts.sentByChar);
  const g = inferUserMaskGenderForImageGen(u);
  const gender =
    g === "female"
      ? "female user protagonist (1girl), not the chat character"
      : g === "male"
        ? "male user protagonist (1boy), not the chat character"
        : "user protagonist, not the chat character";
  return sentByChar
    ? `photo of ${gender}, match scene tags`
    : `user photo, ${gender}, match scene tags`;
}

/**
 * OpenAI / 自定义会话生图：英文 danbooru tag 拼装（角色 tag → 场面 tag → 风格）。
 * 不再把中文人设 summary / 长说明段送进 images API，避免部分中转审核失败却回 `{ data: [] }`。
 * @param {ReturnType<typeof normalizeImageGenConfig>} cfg
 * @param {ReturnType<typeof readActiveThread>} thread
 * @param {string} sceneBlockForApi
 * @param {{ offline?: boolean, plan?: ReturnType<typeof resolveImageGenPlan>, msg?: unknown, logArr?: unknown[] }} [opts]
 */
function buildChatSessionImageGenPrompt(cfg, thread, sceneBlockForApi, opts) {
  const o = opts && typeof opts === "object" ? opts : {};
  const mo = o.msg && typeof o.msg === "object" ? o.msg : null;
  const isUserSender = mo?.role === "user";
  const sceneStr = String(sceneBlockForApi || "").trim();
  const plan =
    o.plan ||
    resolveImageGenPlan(mo || null, thread, sceneStr, Array.isArray(o.logArr) ? o.logArr : undefined);
  const omitChar = userImageGenShouldOmitChar(plan, mo, sceneStr, thread);
  const offline = o.offline === true;

  const parts = [];
  const charTags = novelAiCharacterAppearanceTags(thread, plan, omitChar, { offline, msg: mo });
  if (charTags) parts.push(charTags);

  const userTags = plan.includeUser
    ? resolveUserImageGenAppearanceForPrompt(readUserMask(), plan, { offline })
    : "";
  if (userTags) parts.push(userTags);

  const sceneTags = novelAiSceneBlockToTags(sceneStr, thread, plan, mo);
  if (sceneTags) parts.push(sceneTags);

  const meetupBoth = Boolean(plan.includeUser && (plan.includeCharStrong || plan.includeCharWeak));
  if (plan.includeUser || (isUserSender && omitChar)) {
    const ub = buildImageGenUserPersonaBlock({ meetupBoth, userTags });
    if (ub) parts.push(ub);
  }

  if (omitChar && sceneTags) {
    parts.push(
      openAiUserFigureImageGenDirectiveBlock(readUserMask(), {
        sentByChar: mo?.role === "assistant"
      })
    );
  }

  const im = mo?.image && typeof mo.image === "object" ? mo.image : null;
  const hint = im ? String(im.imageSubjectHint || "").trim() : "";
  if (plan.subject === "other" && hint) {
    parts.push(`other person, ${hint.slice(0, 300)}`.replace(/\s+/g, " "));
  }

  const storyBeat =
    offline && mo?.image && typeof mo.image === "object"
      ? String(mo.image.offlineStoryBeat || "").trim()
      : "";
  if (storyBeat) {
    if (!textLooksMostlyCjk(storyBeat)) {
      const beatTags = novelAiStripNonTagProse(storyBeat).slice(0, 450);
      if (beatTags) parts.push(beatTags);
    } else {
      const beatKw = extractOfflineVisualKeywordsFromChinese(storyBeat);
      if (beatKw) parts.push(beatKw);
    }
  }

  let styleLine = "";
  if (omitChar) {
    styleLine = String(cfg?.stylePrompt || "").trim();
  } else {
    styleLine = offline
      ? resolveThreadOfflineSessionImageStyleSuffix(thread, cfg)
      : resolveThreadSessionImageStyleSuffix(thread, cfg);
    if (!styleLine) styleLine = String(cfg?.stylePrompt || "").trim();
  }
  if (styleLine) {
    const st = openAiImageGenStyleTagsFromSuffix(styleLine);
    if (st) parts.push(st);
  }

  if ((plan.subject === "object" || plan.subject === "scene") && plan.confidence !== "low") {
    parts.push("focus on described subject, no unrelated characters");
  }

  let prompt = parts
    .filter(Boolean)
    .join(", ")
    .replace(/\s*,\s*,+/g, ", ")
    .replace(/^,\s*|\s*,$/g, "")
    .trim();

  const neg = String(cfg?.negativePrompt || "").trim();
  if (neg) prompt = `${prompt}\n\nAvoid: ${neg}`;

  const maxLen = isGptImageModelId(cfg?.model) ? 8000 : 4000;
  return prompt.slice(0, maxLen);
}

/** @param {ReturnType<typeof resolveImageGenPlan>} plan */
function imageGenPlanAllowsThreadRef(plan) {
  return Boolean(plan && plan.useRef && (plan.subject === "char" || plan.subject === "both"));
}

/**
 * 写入 `msg.image.imageSubject`（显式 / 模型 / 推断）；供入库与重绘复用。
 * @param {unknown} msg
 * @param {ReturnType<typeof readActiveThread>} thread
 * @param {string} sceneText
 * @param {unknown[]} [logArr]
 * @param {unknown} [modelSubject]
 * @param {string} [offlineReplyText] 线下 assistant 本轮 lines，供晤面主体推断
 */
function applySessionImageSubjectOnRow(msg, thread, sceneText, logArr, modelSubject, offlineReplyText) {
  if (!msg || typeof msg !== "object") return;
  if (!msg.image || typeof msg.image !== "object") msg.image = {};
  const cur = normalizeImageSubject(msg.image.imageSubject);
  if (cur !== "auto") return;
  const fromModel = normalizeImageSubject(modelSubject);
  if (fromModel !== "auto") {
    msg.image.imageSubject = fromModel;
    return;
  }
  const role = msg.role === "user" ? "user" : "assistant";
  const offline = role === "assistant" && chatMessageDmSurface(msg) === "offline";
  const inf = offline
    ? inferOfflineMeetupImageSubject(
        thread,
        sceneText,
        { charImageSubject: modelSubject },
        offlineReplyText
      )
    : inferImageSubjectFromContext(msg, thread, sceneText, logArr);
  if (role === "user") {
    msg.image.imageSubject = resolveUserSessionImageSubjectForStorage(
      thread,
      sceneText,
      logArr
    );
    return;
  }
  msg.image.imageSubject = inf.subject;
}

function blobToDataUrl(blob) {
  return new Promise((resolve, reject) => {
    const fr = new FileReader();
    fr.onload = () => resolve(String(fr.result || ""));
    fr.onerror = () => reject(new Error("read"));
    fr.readAsDataURL(blob);
  });
}

/** 拉图兜底：超过此大小不转 data URL，避免 iOS WebView OOM（与入库前 shrink 配合）。 */
const IMAGE_GEN_REMOTE_URL_MAX_BYTES = 12 * 1024 * 1024;

/** @param {unknown} item */
function pickOpenAiImageB64FromItem(item) {
  if (!item || typeof item !== "object") return "";
  const direct = String(item.b64_json || item.b64 || item.base64 || item.image_base64 || "").trim();
  if (direct) return direct;
  const img = item.image;
  if (img && typeof img === "object") return pickOpenAiImageB64FromItem(img);
  if (typeof img === "string") {
    const s = img.trim();
    if (s.length > 80 && !/^https?:\/\//i.test(s)) {
      return s.replace(/^data:image\/[^;]+;base64,/, "");
    }
  }
  return "";
}

/** @param {unknown} item */
function pickOpenAiImageUrlFromItem(item) {
  if (!item || typeof item !== "object") return "";
  let u = String(item.url || item.image_url || item.imageUrl || "").trim();
  if (!u && item.image_url && typeof item.image_url === "object") {
    u = String(item.image_url.url || "").trim();
  }
  if (!u && typeof item.image === "string" && /^https?:\/\//i.test(item.image)) {
    u = String(item.image).trim();
  }
  if (!u && item.image && typeof item.image === "object") {
    u = pickOpenAiImageUrlFromItem(item.image);
  }
  return u;
}

/** @param {unknown} raw */
function tryParseOpenAiImageJsonBlob(raw) {
  if (raw == null) return null;
  if (typeof raw === "object") return raw;
  const s = String(raw).trim().replace(/^\uFEFF/, "");
  if (!s) return null;
  if (s.startsWith("{") || s.startsWith("[")) {
    try {
      return JSON.parse(s);
    } catch (_) {
      return null;
    }
  }
  return null;
}

/** @param {string} rawText */
function parseOpenAiGenerationsResponseJson(rawText) {
  const t = String(rawText || "").trim().replace(/^\uFEFF/, "");
  if (!t) return null;
  let j = tryParseOpenAiImageJsonBlob(t);
  if (j) return j;
  if (t.includes("data:")) {
    const lines = t.split(/\r?\n/);
    for (let i = lines.length - 1; i >= 0; i--) {
      const line = lines[i].trim();
      if (!line.startsWith("data:") || /\[DONE\]/i.test(line)) continue;
      j = tryParseOpenAiImageJsonBlob(line.replace(/^data:\s*/i, ""));
      if (j) return j;
    }
  }
  return null;
}

/** @param {string} msg */
function isBenignRelayStatusMessage(msg) {
  const m = String(msg || "").trim().toLowerCase();
  return !m || m === "success" || m === "ok" || m === "成功" || m === "succeeded";
}

/** @param {unknown} j */
function extractOpenAiImageApiErrorFromJson(j) {
  if (!j || typeof j !== "object") return "";
  const errObj = j.error;
  let msg = String(
    errObj && typeof errObj === "object"
      ? errObj.message || errObj.type || errObj.code
      : errObj || ""
  ).trim();
  if (!msg) msg = String(j.msg || j.message || j.detail || j.reason || "").trim();
  if (isBenignRelayStatusMessage(msg)) msg = "";
  const code = j.code ?? j.status_code ?? j.status;
  const cn = Number(code);
  if (Number.isFinite(cn) && cn !== 0 && cn !== 200) {
    return msg || `接口返回 code=${cn}`;
  }
  if (typeof code === "string" && code && !/^(0|200|success|ok)$/i.test(code)) {
    return msg || `接口返回 code=${code}`;
  }
  if (j.success === false || j.fail || j.failed === true) {
    return msg || "生图失败";
  }
  if (msg && (errObj || j.error_code != null)) return msg;
  return "";
}

/** @param {unknown} entry */
function openAiImageFieldsFromDataEntry(entry) {
  if (entry && typeof entry === "object") {
    return {
      b64: pickOpenAiImageB64FromItem(entry),
      url: pickOpenAiImageUrlFromItem(entry)
    };
  }
  const s = String(entry ?? "").trim();
  if (!s) return { b64: "", url: "" };
  if (/^https?:\/\//i.test(s) || /^data:image\//i.test(s)) return { b64: "", url: s };
  if (s.length > 80) return { b64: s.replace(/^data:image\/[^;]+;base64,/, ""), url: "" };
  return { b64: "", url: "" };
}

/** @param {unknown} arr */
function openAiImageFieldsFromDataArray(arr) {
  if (!Array.isArray(arr) || !arr.length) return { b64: "", url: "" };
  return openAiImageFieldsFromDataEntry(arr[0]);
}

/**
 * 从 OpenAI 兼容生图 JSON 提取 b64 / url（兼容常见中转嵌套）。
 * @param {unknown} j
 * @param {number} [depth]
 * @returns {{ b64: string, url: string, apiError?: string, emptyHint?: string }}
 */
function extractOpenAiImageFieldsFromGenerationsJson(j, depth = 0) {
  if (depth > 5) return { b64: "", url: "" };
  if (typeof j === "string") {
    const r = openAiImageFieldsFromDataEntry(j);
    return r.b64 || r.url ? r : { b64: "", url: "" };
  }
  if (Array.isArray(j)) {
    const r = openAiImageFieldsFromDataArray(j);
    if (r.b64 || r.url) return r;
    if (!j.length) return { b64: "", url: "", emptyHint: "data 为空数组" };
    return { b64: "", url: "" };
  }
  if (!j || typeof j !== "object") return { b64: "", url: "" };
  const tryMerge = (...parts) => {
    let b64 = "";
    let url = "";
    for (const p of parts) {
      if (!p) continue;
      if (!b64 && p.b64) b64 = p.b64;
      if (!url && p.url) url = p.url;
      if (b64 && url) break;
    }
    return { b64, url };
  };
  let r = openAiImageFieldsFromDataArray(j.data);
  if (r.b64 || r.url) return r;
  if (Array.isArray(j.data) && !j.data.length) {
    const apiErr = extractOpenAiImageApiErrorFromJson(j);
    if (apiErr) return { b64: "", url: "", apiError: apiErr };
    return { b64: "", url: "", emptyHint: "data 为空数组" };
  }
  if (typeof j.data === "string") {
    const inner = tryParseOpenAiImageJsonBlob(j.data);
    if (inner) {
      const nested = extractOpenAiImageFieldsFromGenerationsJson(inner, depth + 1);
      if (nested.b64 || nested.url) return nested;
    }
    const direct = openAiImageFieldsFromDataEntry(j.data);
    if (direct.b64 || direct.url) return direct;
  }
  const dataObj = j.data;
  if (dataObj && typeof dataObj === "object" && !Array.isArray(dataObj)) {
    r = tryMerge(
      openAiImageFieldsFromDataArray(dataObj.data),
      openAiImageFieldsFromDataArray(dataObj.list),
      openAiImageFieldsFromDataArray(dataObj.images),
      openAiImageFieldsFromDataEntry(dataObj)
    );
    if (r.b64 || r.url) return r;
    const innerStr = typeof dataObj.data === "string" ? dataObj.data : "";
    if (innerStr) {
      const inner = tryParseOpenAiImageJsonBlob(innerStr);
      if (inner) {
        const nested = extractOpenAiImageFieldsFromGenerationsJson(inner, depth + 1);
        if (nested.b64 || nested.url) return nested;
      }
    }
  }
  r = tryMerge(
    openAiImageFieldsFromDataArray(j.images),
    openAiImageFieldsFromDataArray(j.output),
    openAiImageFieldsFromDataEntry(j.output),
    openAiImageFieldsFromDataArray(j.result)
  );
  if (r.b64 || r.url) return r;
  if (typeof j.result === "string") {
    const direct = openAiImageFieldsFromDataEntry(j.result);
    if (direct.b64 || direct.url) return direct;
  }
  if (j.output && typeof j.output === "object") {
    r = openAiImageFieldsFromDataArray(j.output.data);
    if (r.b64 || r.url) return r;
  }
  if (j.result && typeof j.result === "object") {
    r = openAiImageFieldsFromDataArray(j.result.data);
    if (r.b64 || r.url) return r;
  }
  const topB64 = String(j.b64_json || j.base64 || j.image_base64 || "").trim();
  const topUrl = String(j.url || j.image_url || "").trim();
  if (topB64) return { b64: topB64, url: "" };
  if (topUrl) return { b64: "", url: topUrl };
  const choice = Array.isArray(j.choices) && j.choices[0] ? j.choices[0] : null;
  const msg = choice && typeof choice.message === "object" ? choice.message : null;
  if (msg) {
    const content = msg.content;
    if (Array.isArray(content)) {
      for (const part of content) {
        if (!part || typeof part !== "object") continue;
        if (part.type === "image_url" && part.image_url) {
          const u = String(part.image_url.url || "").trim();
          if (u) return { b64: "", url: u };
        }
        const b64p = pickOpenAiImageB64FromItem(part);
        const urlp = pickOpenAiImageUrlFromItem(part);
        if (b64p || urlp) return { b64: b64p, url: urlp };
      }
    } else {
      const s = String(content || "").trim();
      const md =
        /!\[[^\]]*]\((https?:\/\/[^)]+)\)/i.exec(s) ||
        /(https?:\/\/\S+\.(?:png|jpe?g|webp|gif)(\?\S*)?)/i.exec(s);
      if (md) return { b64: "", url: md[1] };
      if (/^data:image\//i.test(s)) return { b64: "", url: s };
      const b64Inline = openAiImageFieldsFromDataEntry(s);
      if (b64Inline.b64 || b64Inline.url) return b64Inline;
    }
  }
  const apiErr = extractOpenAiImageApiErrorFromJson(j);
  if (apiErr) return { b64: "", url: "", apiError: apiErr };
  if (j.data && typeof j.data === "object" && !Array.isArray(j.data)) {
    const onlyPrompt = String(j.data.revised_prompt || j.revised_prompt || "").trim();
    if (onlyPrompt && !pickOpenAiImageB64FromItem(j.data) && !pickOpenAiImageUrlFromItem(j.data)) {
      return { b64: "", url: "", emptyHint: "仅有 revised_prompt，无图片字段" };
    }
  }
  return { b64: "", url: "" };
}

/** @param {unknown} j */
function extractOpenAiImageUrlFromGenerationsJson(j) {
  return extractOpenAiImageFieldsFromGenerationsJson(j).url;
}

/** @param {unknown} j */
function describeOpenAiGenerationsJsonForError(j) {
  if (!j || typeof j !== "object") return "";
  const keys = Object.keys(j).slice(0, 8).join(",");
  const data = j.data;
  let extra = "";
  if (Array.isArray(data)) extra = `data.length=${data.length}`;
  else if (data && typeof data === "object") extra = `data.keys=${Object.keys(data).slice(0, 6).join(",")}`;
  return [keys, extra].filter(Boolean).join(" · ");
}

/**
 * 中转只返回临时图片 URL 时：下载一张图转 data URL（与 b64_json 入库形态一致）。
 * @param {string} imageUrl
 * @param {{ timeoutMs?: number, maxBytes?: number }} [opts]
 */
async function fetchImageDataUrlFromRemoteUrl(imageUrl, opts) {
  const u = String(imageUrl || "").trim();
  if (!u) return { ok: false, error: "无图片地址" };
  if (!/^https?:\/\//i.test(u)) return { ok: false, error: "不支持的图片链接" };
  const timeoutMs = Number(opts?.timeoutMs) > 0 ? Number(opts.timeoutMs) : 45_000;
  const maxBytes =
    Number(opts?.maxBytes) > 0 ? Number(opts.maxBytes) : IMAGE_GEN_REMOTE_URL_MAX_BYTES;
  try {
    const controller = new AbortController();
    const timer = window.setTimeout(() => controller.abort(), timeoutMs);
    const resp = await fetch(u, {
      method: "GET",
      mode: "cors",
      credentials: "omit",
      signal: controller.signal
    });
    window.clearTimeout(timer);
    if (!resp.ok) return { ok: false, error: `拉图 HTTP ${resp.status}` };
    const ct = String(resp.headers.get("content-type") || "").toLowerCase();
    if (ct && !ct.startsWith("image/") && !ct.includes("octet-stream")) {
      return { ok: false, error: "链接返回的不是图片" };
    }
    const len = Number(resp.headers.get("content-length"));
    if (Number.isFinite(len) && len > maxBytes) {
      return { ok: false, error: "图片过大（已跳过下载）" };
    }
    const blob = await resp.blob();
    if (!blob?.size) return { ok: false, error: "图片为空" };
    if (blob.size > maxBytes) return { ok: false, error: "图片过大（已跳过下载）" };
    const du = await blobToDataUrl(blob);
    if (!/^data:image\//i.test(du)) return { ok: false, error: "无法转为图片数据" };
    return { ok: true, dataUrl: du };
  } catch (e) {
    const err = e instanceof Error ? e : new Error(String(e));
    if (err.name === "AbortError") return { ok: false, error: "下载图片超时" };
    return { ok: false, error: `下载图片失败：${err.message.slice(0, 120)}` };
  }
}

/** @param {string} rawText */
async function openAiGenerationsResponseToDataUrl(rawText) {
  const j = parseOpenAiGenerationsResponseJson(rawText);
  if (!j) {
    const head = String(rawText || "").trim().slice(0, 120);
    if (head.startsWith("<!") || /^<html/i.test(head)) {
      return { ok: false, error: "响应是 HTML 而非 JSON，请检查 API Base 是否指向 /v1/images/generations" };
    }
    if (/^\s*PK\s/.test(String(rawText || "").slice(0, 4))) {
      return { ok: false, error: "响应是 ZIP/二进制而非 JSON，请确认服务商为 OpenAI 兼容生图" };
    }
    const snippet = head.replace(/\s+/g, " ").slice(0, 80);
    return {
      ok: false,
      error: snippet ? `响应非 JSON（${snippet}）` : "响应非 JSON"
    };
  }
  const fields = extractOpenAiImageFieldsFromGenerationsJson(j);
  if (fields.apiError) return { ok: false, error: fields.apiError.slice(0, 220) };
  const b64 = String(fields.b64 || "").trim();
  if (b64) return { ok: true, dataUrl: `data:image/png;base64,${b64}` };
  const remote = String(fields.url || "").trim();
  if (remote) {
    if (/^data:image\//i.test(remote)) return { ok: true, dataUrl: remote };
    const got = await fetchImageDataUrlFromRemoteUrl(remote);
    if (got.ok && got.dataUrl) return got;
    return { ok: false, error: got.error || "无法从 url 下载图片" };
  }
  const hint = [fields.emptyHint, describeOpenAiGenerationsJsonForError(j)].filter(Boolean).join(" · ");
  return {
    ok: false,
    error: hint ? `响应中无图片数据（${hint}）` : "响应中无 b64_json 或 url"
  };
}

/**
 * @param {ReturnType<typeof normalizeImageGenConfig>} cfg
 * @param {string} prompt
 * @param {Record<string, unknown>} [bodyExtra]
 */
async function postOpenAiImageGenerationsRequest(cfg, prompt, bodyExtra, timeoutMs) {
  const genUrl = buildImageGenOpenAiGenerationsUrl(cfg);
  const isGpt = isGptImageModelId(cfg.model);
  /** @type {Record<string, unknown>} */
  const body = {
    model: cfg.model,
    prompt,
    n: 1,
    size: mapOpenAiImageSizeForGenerationsApi(cfg.size, cfg.model),
    ...(bodyExtra && typeof bodyExtra === "object" ? bodyExtra : {})
  };
  if (isGpt) {
    applyOpenAiGptImageFieldsToBody(body, cfg);
  } else if (body.response_format == null) {
    body.response_format = "b64_json";
  }
  const ms =
    Number(timeoutMs) > 0 ? Number(timeoutMs) : IMAGE_GEN_FETCH_TIMEOUT_OPENAI_MS;
  const resp = await fetchImageGenWithTimeout(
    genUrl,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${cfg.apiKey}`
      },
      body: JSON.stringify(body),
      mode: "cors",
      credentials: "omit"
    },
    ms
  );
  const rawText = await resp.text();
  if (!resp.ok) {
    let msg = `HTTP ${resp.status}`;
    try {
      const ej = parseOpenAiGenerationsResponseJson(rawText) || JSON.parse(rawText);
      const apiErr = extractOpenAiImageApiErrorFromJson(ej);
      msg = apiErr || String(ej?.error?.message || ej?.message || msg).slice(0, 220);
    } catch (_) {
      msg = rawText.slice(0, 180) || msg;
    }
    return { ok: false, error: msg };
  }
  return openAiGenerationsResponseToDataUrl(rawText);
}

/**
 * OpenAI 兼容 /images/edits：上传立绘作参考（input_fidelity 锁脸，仅 gpt-image-1/1.5）。
 * 先 multipart，失败再 JSON（部分中转只支持其一）。
 * @param {ReturnType<typeof normalizeImageGenConfig>} cfg
 * @param {string} prompt
 * @param {string} refDataUrl
 */
async function postOpenAiImageEditsRequest(cfg, prompt, refDataUrl, timeoutMs) {
  const ref = await prepareOpenAiEditsRefDataUrl(refDataUrl);
  if (!ref) return { ok: false, error: "参考图无效或无法读取" };
  const editUrl = buildImageGenOpenAiEditsUrl(cfg);
  const model = String(cfg.model || "").trim();
  const isGpt = isGptImageModelId(model);
  const isDalle2 = String(model).toLowerCase() === "dall-e-2";
  const size = mapOpenAiImageSizeForGenerationsApi(cfg.size, model);
  const ms =
    Number(timeoutMs) > 0 ? Number(timeoutMs) : IMAGE_GEN_FETCH_TIMEOUT_OPENAI_HEAVY_MS;
  const authHdr = { Authorization: `Bearer ${cfg.apiKey}` };

  /** @param {Response} resp @param {string} rawText */
  async function finishEditsResponse(resp, rawText) {
    if (!resp.ok) {
      let msg = `HTTP ${resp.status}`;
      try {
        const ej = parseOpenAiGenerationsResponseJson(rawText) || JSON.parse(rawText);
        const apiErr = extractOpenAiImageApiErrorFromJson(ej);
        msg = apiErr || String(ej?.error?.message || ej?.message || msg).slice(0, 220);
      } catch (_) {
        msg = rawText.slice(0, 180) || msg;
      }
      return { ok: false, error: msg };
    }
    return openAiGenerationsResponseToDataUrl(rawText);
  }

  try {
    const blob = await blobFromImageDataUrl(ref);
    const mime = String(blob.type || "").toLowerCase();
    const ext = mime.includes("jpeg") || mime.includes("jpg") ? "jpg" : mime.includes("webp") ? "webp" : "png";
    const fd = new FormData();
    fd.append("image", blob, `reference.${ext}`);
    fd.append("prompt", prompt);
    fd.append("model", model);
    fd.append("n", "1");
    fd.append("size", size);
    if (isGpt) {
      /** @type {Record<string, unknown>} */
      const gptFields = {};
      applyOpenAiGptImageFieldsToBody(gptFields, cfg, { forEdits: true });
      for (const [k, v] of Object.entries(gptFields)) {
        if (v != null && v !== "") fd.append(k, String(v));
      }
    } else if (isDalle2) {
      fd.append("response_format", "b64_json");
    }
    const respMp = await fetchImageGenWithTimeout(
      editUrl,
      { method: "POST", headers: authHdr, body: fd, mode: "cors", credentials: "omit" },
      ms
    );
    const rawMp = await respMp.text();
    if (respMp.ok) return finishEditsResponse(respMp, rawMp);
    const mpErr = rawMp.slice(0, 120);
    /** @type {Record<string, unknown>} */
    const jsonBody = {
      model,
      prompt,
      n: 1,
      size,
      images: [{ image_url: ref }]
    };
    if (isGpt) {
      applyOpenAiGptImageFieldsToBody(jsonBody, cfg, { forEdits: true });
    } else if (isDalle2) {
      jsonBody.response_format = "b64_json";
    }
    const respJson = await fetchImageGenWithTimeout(
      editUrl,
      {
        method: "POST",
        headers: { ...authHdr, "Content-Type": "application/json" },
        body: JSON.stringify(jsonBody),
        mode: "cors",
        credentials: "omit"
      },
      ms
    );
    const rawJson = await respJson.text();
    const parsed = await finishEditsResponse(respJson, rawJson);
    if (!parsed.ok && mpErr) {
      const tail = parsed.error ? `；multipart：${mpErr.slice(0, 80)}` : "";
      return { ok: false, error: `${parsed.error || "edits 失败"}${tail}`.slice(0, 240) };
    }
    return parsed;
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    return { ok: false, error: msg.slice(0, 200) };
  }
}

/** NovelAI 生图响应（zip 或裸 png）→ 可入库的 data URL */
async function novelaiArrayBufferToPngDataUrl(ab) {
  let objectUrl = await novelaiZipBufferToPngObjectUrl(ab);
  if (!objectUrl) {
    try {
      const u = new Uint8Array(ab, 0, Math.min(12, ab.byteLength));
      let sig = "";
      for (let i = 0; i < u.length; i++) sig += String.fromCharCode(u[i]);
      if (sig.startsWith("\x89PNG")) {
        objectUrl = URL.createObjectURL(new Blob([ab], { type: "image/png" }));
      }
    } catch (_) {
      /* ignore */
    }
  }
  if (!objectUrl) return null;
  try {
    const blob = await (await fetch(objectUrl)).blob();
    const du = await blobToDataUrl(blob);
    return /^data:image/i.test(du) ? du : null;
  } catch {
    return null;
  } finally {
    try {
      URL.revokeObjectURL(objectUrl);
    } catch (_) {
      /* ignore */
    }
  }
}

/**
 * 按当前生图配置请求一张图，返回 data URL（供聊天记录持久化）。
 * @param {ReturnType<typeof normalizeImageGenConfig>} cfg
 * @param {string} prompt
 * @param {{ refDataUrl?: string, preferLongTimeout?: boolean }} [extras] 参考立绘：NAI→img2img；OpenAI 兼容→/images/edits
 * @returns {Promise<{ ok: boolean, dataUrl?: string, error?: string }>}
 */
async function executeImageGenRequestToDataUrl(cfg, prompt, extras) {
  const p = String(prompt || "").trim();
  if (!p) return { ok: false, error: "无提示词" };
  if (!String(cfg.apiKey || "").trim()) return { ok: false, error: "未配置 API Key" };
  const refDataUrl = extras && typeof extras === "object" ? String(extras.refDataUrl || "").trim() : "";
  const timeoutMs = resolveImageGenFetchTimeoutMs(cfg, { ...extras, refDataUrl }, p);
  try {
    if (cfg.provider === "novelai") {
      const url = resolveNovelAiGenerateImageUrl(cfg);
      const resp = await fetchImageGenWithTimeout(
        url,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${cfg.apiKey}`
          },
          body: JSON.stringify(buildImageGenNovelAiGenerateJson(cfg, p, refDataUrl)),
          mode: "cors",
          credentials: "omit"
        },
        timeoutMs
      );
      const buf = await resp.arrayBuffer();
      if (!resp.ok) {
        let msg = `HTTP ${resp.status}`;
        try {
          const t = new TextDecoder().decode(buf.slice(0, 800));
          if (t.trim().startsWith("{")) {
            const j = JSON.parse(t);
            msg = String(j?.message || j?.error || msg).slice(0, 200);
          } else msg = t.slice(0, 160);
        } catch (_) {
          /* ignore */
        }
        return { ok: false, error: msg };
      }
      const dataUrl = await novelaiArrayBufferToPngDataUrl(buf);
      if (!dataUrl) {
        const unzipReady = Boolean(await ensureImageGenFflateUnzipSync());
        return {
          ok: false,
          error: unzipReady ? "未能解析为图片" : "未能解析为图片（解压库未加载）"
        };
      }
      return { ok: true, dataUrl };
    }
    const useOpenAiEdits =
      Boolean(refDataUrl) && openAiImageModelSupportsReferenceEdits(cfg.model);
    let parsed = useOpenAiEdits
      ? await postOpenAiImageEditsRequest(cfg, p, refDataUrl, timeoutMs)
      : await postOpenAiImageGenerationsRequest(cfg, p, {}, timeoutMs);
    if (!parsed.ok && useOpenAiEdits) {
      parsed = await postOpenAiImageGenerationsRequest(cfg, p, {}, timeoutMs);
    }
    if (!parsed.ok) {
      const err = String(parsed.error || "");
      const isGpt = isGptImageModelId(cfg.model);
      const shouldRetry =
        /无图片|非 JSON|HTML|空数组|revised_prompt/i.test(err) || err.startsWith("响应非 JSON");
      if (shouldRetry) {
        if (isGpt) {
          const urlTry = await postOpenAiImageGenerationsRequest(cfg, p, { response_format: "url" }, timeoutMs);
          if (urlTry.ok && urlTry.dataUrl) parsed = urlTry;
          else {
            const b64Try = await postOpenAiImageGenerationsRequest(
              cfg,
              p,
              { response_format: "b64_json" },
              timeoutMs
            );
            if (b64Try.ok && b64Try.dataUrl) parsed = b64Try;
          }
        } else {
          const b64Try = await postOpenAiImageGenerationsRequest(cfg, p, { response_format: "b64_json" }, timeoutMs);
          if (b64Try.ok && b64Try.dataUrl) parsed = b64Try;
          else {
            const urlTry = await postOpenAiImageGenerationsRequest(cfg, p, { response_format: "url" }, timeoutMs);
            if (urlTry.ok && urlTry.dataUrl) parsed = urlTry;
          }
        }
      }
    }
    if (!parsed.ok || !parsed.dataUrl) {
      const tail =
        cfg.provider === "openai"
          ? "（官方 OpenAI 仅支持官方 Key；中转请选「OpenAI 兼容」）"
          : cfg.provider === "custom"
            ? "（请确认 Base 支持 /v1/images/generations，模型 id 与中转站一致）"
            : "";
      return { ok: false, error: `${parsed.error || "未能解析图片"}${tail}`.slice(0, 240) };
    }
    return { ok: true, dataUrl: parsed.dataUrl };
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    return { ok: false, error: msg.slice(0, 200) };
  }
}

function isSessionImageGenConfigured() {
  const cfg = readImageGenConfig();
  return Boolean(cfg.enabled && String(cfg.apiKey || "").trim());
}

/** 当前表单与已保存生图配置是否一致（聊天读已保存）。 */
function imageGenFormMatchesSavedCfg(formCfg) {
  const saved = normalizeImageGenConfig(readImageGenConfig());
  const form = normalizeImageGenConfig(formCfg);
  if (saved.enabled !== form.enabled) return false;
  if (saved.provider !== form.provider) return false;
  if (saved.baseUrl !== form.baseUrl) return false;
  if (saved.model !== form.model) return false;
  if (String(form.apiKey || "").trim() && saved.apiKey !== form.apiKey) return false;
  return true;
}

/** @param {string} s */
function textLooksMostlyCjk(s) {
  const t = String(s || "");
  if (!t.trim()) return false;
  let cjk = 0;
  let lat = 0;
  for (const ch of t) {
    if (/[\u4e00-\u9fff]/.test(ch)) cjk++;
    else if (/[a-zA-Z]/.test(ch)) lat++;
  }
  return cjk > lat;
}

/** @param {string} raw */
function extractOfflineImageTagCaptionFromRaw(raw) {
  const s = String(raw ?? "");
  const m = /\[IMAGE\]\s*([\s\S]*?)(?=\[\/IMAGE\]|\[XXJ_|\{\s*"|\n\n\n|$)/i.exec(s);
  if (m) return String(m[1] || "").trim().split(/\n/)[0].trim();
  const idx = s.lastIndexOf("[IMAGE]");
  if (idx < 0) return "";
  let tail = s.slice(idx + 7).trim();
  const nl = tail.indexOf("\n");
  if (nl > 0) tail = tail.slice(0, nl);
  return tail.replace(/^\]?\s*/, "").trim();
}

/** 英文 caption 是否几乎只有泛化套话、缺少具体场面词。 */
function offlineImageSceneCaptionTooGeneric(cap) {
  const t = String(cap || "")
    .trim()
    .toLowerCase();
  if (!t) return true;
  const parts = t
    .split(/[,，]/)
    .map((s) => s.trim())
    .filter(Boolean);
  const vague =
    /\b(?:indoor|outdoor|inside|room|scene|cinematic\s+lighting|dramatic\s+lighting|face-to-face|portrait|close-up|closeup|headshot|upper\s+body|masterpiece|best\s+quality|high\s+quality|8k|ultra\s+detailed|photorealistic)\b/g;
  const vagueHits = (t.match(vague) || []).length;
  if (parts.length <= 3 && vagueHits >= 2) return true;
  if (parts.length <= 5 && vagueHits >= 3) return true;
  return false;
}

/** 英文 caption 是否像 danbooru 标签列表（而非小说句/场景描写段）。 */
function offlineImageSceneCaptionLooksLikeTagList(cap) {
  const t = String(cap || "").trim();
  if (!t) return false;
  const parts = t
    .split(/[,，]/)
    .map((s) => s.trim())
    .filter(Boolean);
  if (parts.length < 4) return false;
  if (parts.some((p) => p.split(/\s+/).filter(Boolean).length > 7)) return false;
  const words = t.split(/\s+/).filter(Boolean);
  if (words.length > 26) return false;
  if (/(?<=[.!?])\s+\S/.test(t)) return false;
  if (/\b(?:she|he|they|the)\s+(?:is|was|are|were|stood|sat|looks?|walked|turned)\b/i.test(t)) {
    return false;
  }
  return true;
}

/** 是否为可送生图 API 的英文场面（非 lines 全文粘贴、非中文正文、非长段叙述）。 */
function isPlausibleOfflineImageSceneCaption(cap) {
  const t = String(cap || "").trim();
  if (!t) return false;
  if (textLooksMostlyCjk(t)) return false;
  if (t.length > 360) return false;
  if (t.split(/\n\n+/).filter((s) => s.trim()).length > 2) return false;
  if ((t.match(/「|」/g) || []).length > 1) return false;
  if (!offlineImageSceneCaptionLooksLikeTagList(t)) return false;
  if (offlineImageSceneCaptionTooGeneric(t)) return false;
  return true;
}

function stripOfflineLinesDialogueForImageExtract(s) {
  return String(s || "")
    .replace(/「[^」\n]*」/g, " ")
    .replace(/『[^』\n]*』/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

/** 从 lines 摘可见叙事（不含对白），供线下生图兜底；不送全文。 */
function extractOfflineNarrativeSnippetFromLines(linesText, opts) {
  const maxLen =
    opts && Number.isFinite(Number(opts.maxLen))
      ? Math.min(400, Math.max(36, Math.floor(Number(opts.maxLen))))
      : 120;
  const raw = String(linesText || "").trim();
  if (!raw) return "";
  const chunks = raw
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean);
  const body = chunks.length ? chunks[chunks.length - 1] : raw;
  let t = stripOfflineLinesDialogueForImageExtract(body);
  t = t.replace(/^　+/gm, "").trim();
  if (!t) return "";
  const parts = t.split(/(?<=[。！？!?])/);
  let out = "";
  for (const p of parts) {
    const seg = String(p).trim();
    if (!seg) continue;
    if (out.length + seg.length > maxLen) break;
    out += seg;
    if (out.length >= 36) break;
  }
  if (!out) out = t.slice(0, maxLen);
  return out.trim().slice(0, maxLen);
}

/** @param {string} t */
function offlineScenePromptAlreadyHasSubjectLead(t) {
  return /\b(?:1girl|1boy|2girls?|2boys?|1person|2people|solo|portrait)\b/i.test(String(t || ""));
}

/**
 * 从中文场面/innerState/lines 摘句抽英文可视关键词（不调模型）。
 * @param {string} text
 * @returns {string}
 */
function extractOfflineVisualKeywordsFromChinese(text) {
  const src = String(text || "").trim();
  if (!src || !/[\u4e00-\u9fff]/.test(src)) return "";
  const rules = [
    [/吧台|酒柜|调酒/u, "bar counter"],
    [/咖啡馆|咖啡店|咖啡厅/u, "cafe"],
    [/餐厅|饭店|餐桌/u, "restaurant"],
    [/沙发|榻|懒人椅/u, "on sofa"],
    [/床|床头|被褥|被窝/u, "on bed"],
    [/书桌|书桌前|写字台/u, "desk"],
    [/窗边|窗前|落地窗/u, "by window"],
    [/雨|雨檐|雨季|细雨|暴雨/u, "rain"],
    [/雪|飘雪/u, "snow"],
    [/夜|夜色|深夜|霓虹|路灯/u, "night"],
    [/夕阳|晚霞|黄昏/u, "sunset"],
    [/海|沙滩|海岸/u, "beach"],
    [/街|巷|路灯|人行道/u, "street"],
    [/森林|树|林间/u, "forest"],
    [/电梯|楼梯|走廊/u, "indoor hallway"],
    [/浴室|淋浴/u, "bathroom"],
    [/厨房|灶台/u, "kitchen"],
    [/办公室|工位/u, "office"],
    [/教室|课桌/u, "classroom"],
    [/车内|驾驶|副驾|后座/u, "in car"],
    [/地铁|站台/u, "subway"],
    [/伞|撑伞/u, "umbrella"],
    [/手机|屏幕|刷屏/u, "holding phone"],
    [/杯|咖啡|奶茶|酒杯/u, "holding cup"],
    [/烟|点烟|cigarette/u, "cigarette"],
    [/镜|镜面|照镜子/u, "mirror"],
    [/抱|搂|揽/u, "hug"],
    [/吻/u, "kiss"],
    [/握|牵手|十指/u, "holding hands"],
    [/对视|凝视|抬眼|回眸/u, "eye contact"],
    [/笑|嘴角上扬|弯眼/u, "smile"],
    [/哭|泪|眼眶红/u, "tears"],
    [/脸红|耳根红|羞/u, "blush"],
    [/坐|倚坐|蜷|瘫坐/u, "sitting"],
    [/站|起身|伫立/u, "standing"],
    [/躺|侧卧|仰卧|趴/u, "lying"],
    [/跪/u, "kneeling"],
    [/弯腰|俯身|低头/u, "leaning forward"],
    [/靠|倚|半倚/u, "leaning"],
    [/跑|奔/u, "running"],
    [/走|踱/u, "walking"],
    [/外套|大衣|风衣/u, "coat"],
    [/裙|连衣裙/u, "dress"],
    [/制服|校服|西装/u, "uniform"],
    [/帽|帽檐/u, "hat"],
    [/眼镜/u, "glasses"],
    [/围巾/u, "scarf"],
    [/暖光|昏黄|台灯/u, "warm lighting"],
    [/冷光|荧光灯/u, "cool lighting"],
    [/烛光/u, "candlelight"],
    [/昏暗|暗处|阴影/u, "dim lighting"],
    [/明亮|日光|阳光/u, "bright daylight"]
  ];
  /** @type {string[]} */
  const tags = [];
  const seen = new Set();
  const add = (tag) => {
    const k = String(tag || "").trim().toLowerCase();
    if (!k || seen.has(k)) return;
    seen.add(k);
    tags.push(String(tag).trim());
  };
  for (const [re, en] of rules) {
    if (re.test(src)) add(en);
    if (tags.length >= 14) break;
  }
  return tags.slice(0, 14).join(", ");
}

/** @param {"" | "female" | "male"} g */
function danbooruGenderToken(g) {
  if (g === "female") return "1girl";
  if (g === "male") return "1boy";
  return "1person";
}

/**
 * 线下晤面：场面 tag 前压性别（避免仅 2people 时被模型画成两个男）。
 * @param {ReturnType<typeof readActiveThread>} thread
 * @param {ReturnType<typeof resolveImageGenPlan>} plan
 */
function offlineMeetupImageGenderLead(thread, plan) {
  const charG = inferCharPersonaGenderForImageGen(readThreadBoundCharPersonaForImageGen(thread));
  const userG = inferUserMaskGenderForImageGen();
  if (plan.subject === "user") return `${danbooruGenderToken(userG)}, solo, `;
  if (plan.subject === "both") {
    const a = danbooruGenderToken(charG);
    const b = danbooruGenderToken(userG);
    if (a === "1person" && b === "1person") return "2people, ";
    if (a === b) return `${a === "1girl" ? "2girls" : a === "1boy" ? "2boys" : "2people"}, `;
    return `${a}, ${b}, `;
  }
  if (plan.subject === "char") return `${danbooruGenderToken(charG)}, solo, `;
  return "";
}

/**
 * @param {ReturnType<typeof readActiveThread>} thread
 * @param {ReturnType<typeof resolveImageGenPlan>} [plan]
 */
function offlineImageScenePromptHead(thread, plan) {
  const p = plan || offlineAssistantImageGenPlan(thread, undefined, "");
  if (p.subject === "object" || p.subject === "scene") return "";
  const genderLead = offlineMeetupImageGenderLead(thread, p);
  if (genderLead) return genderLead;
  if (p.subject === "user") return "1person, ";
  if (p.subject === "both") return "2people, ";
  const ch = readThreadBoundCharPersonaForImageGen(thread);
  const name =
    ch && String(ch.displayName || "").trim() ? String(ch.displayName).trim().slice(0, 40) : "character";
  const tg = collectCharImageGenAppearanceTagsFromPersona(ch, {
    tagMax: OFFLINE_IMAGE_GEN_SCENE_HEAD_TAGS_MAX,
    zhKwMax: 14
  });
  if (p.subject === "other") return tg ? `${tg}, ` : "";
  return tg ? `1person, ${name}, ${tg},` : `1person, ${name},`;
}

/** 线下晤面生图：仅规范化空白，景别/构图由剧情 tags 自决（模型与程序兜底共用）。 */
function finalizeOfflineSessionImageScenePrompt(scene) {
  return String(scene || "")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 3500);
}

/**
 * @param {string} tags
 * @param {ReturnType<typeof readActiveThread>} thread
 * @param {ReturnType<typeof resolveImageGenPlan>} [plan]
 */
function offlineScenePromptFromEnglishTags(tags, thread, plan) {
  const t = String(tags || "").trim();
  if (!t) return "";
  let out = t;
  if (!offlineScenePromptAlreadyHasSubjectLead(t)) {
    const inf = plan || offlineAssistantImageGenPlan(thread, undefined, t);
    const head = offlineImageScenePromptHead(thread, inf).replace(/,\s*$/, "");
    if (head) out = `${head} ${t}`.replace(/\s+/g, " ").trim();
  }
  return finalizeOfflineSessionImageScenePrompt(out);
}

/**
 * 线下晤面 assistant 配图：同场默认偏双人 both；空镜/物品/明确 solo 再落 char 等。
 * @param {ReturnType<typeof readActiveThread>} thread
 * @param {string} sceneText
 * @param {{ charImageSubject?: string, hvState?: string }} [parsed]
 * @param {string} [replyText]
 * @returns {{ subject: ImageGenSubject, confidence: "high"|"medium"|"low" }}
 */
function inferOfflineMeetupImageSubject(thread, sceneText, parsed, replyText) {
  const sub = normalizeImageSubject(parsed?.charImageSubject);
  if (sub === "object" || sub === "scene" || sub === "both" || sub === "other") {
    return { subject: sub, confidence: "high" };
  }
  if (sub === "char" || sub === "user") {
    return { subject: sub, confidence: "high" };
  }
  const bits = [
    String(sceneText || "").trim(),
    String(parsed?.hvState || "").trim(),
    extractOfflineNarrativeSnippetFromLines(String(replyText || ""))
  ].filter(Boolean);
  const scene = bits.join("\n");
  const charNames = charDisplayNamesForImageInfer(thread);
  const scores = scoreImageSubjectFromSceneText(scene, charNames, {
    senderRole: "assistant",
    offlineMeetup: true
  });
  if (scores.object >= 4 && scores.object >= scores.scene) {
    return { subject: "object", confidence: "high" };
  }
  if (scores.scene >= 4) {
    return { subject: "scene", confidence: "high" };
  }
  if (scores.other >= 4) {
    return { subject: "other", confidence: "high" };
  }
  if (scores.both >= 4) {
    return { subject: "both", confidence: "high" };
  }
  if (scores.both >= 2 && scores.both >= scores.char) {
    return { subject: "both", confidence: "medium" };
  }
  if (scores.char >= 4 && scores.both < 2) {
    return { subject: "char", confidence: "high" };
  }
  if (scores.object < 3 && scores.scene < 3) {
    return { subject: "both", confidence: "medium" };
  }
  return { subject: "char", confidence: "low" };
}

/**
 * @param {ReturnType<typeof readActiveThread>} thread
 * @param {{ charImageSubject?: string, hvState?: string }} [parsed]
 * @param {string} [sceneText]
 * @param {string} [replyText]
 */
function offlineAssistantImageGenPlan(thread, parsed, sceneText, replyText) {
  const sc = String(sceneText || "").trim();
  const inf = inferOfflineMeetupImageSubject(thread, sc, parsed, replyText);
  const plan = resolveImageGenPlan(
    {
      role: "assistant",
      image: { imageSubject: inf.subject }
    },
    thread,
    sc,
    undefined
  );
  plan.confidence = inf.confidence;
  if (plan.subject === "user") {
    return plan;
  }
  if (plan.subject === "object" || plan.subject === "scene") {
    plan.includeCharWeak = true;
    return plan;
  }
  plan.includeCharStrong = true;
  plan.includeCharWeak = false;
  plan.useRef = true;
  if (plan.subject === "both") plan.includeUser = true;
  return plan;
}

/**
 * 从 innerState / lines 叙事块转场面 prompt（与线上 everyRound 共用 novelAiSceneBlockToTags）。
 * @param {string} proseBlock
 * @param {ReturnType<typeof readActiveThread>} thread
 * @param {{ charImageCaption?: string, charImageSubject?: string, hvState?: string }} parsed
 * @param {string} replyText
 */
function offlineSessionImageSceneFromProseBlock(proseBlock, thread, parsed, replyText) {
  const block = String(proseBlock || "").trim();
  if (!block) return "";
  const plan = offlineAssistantImageGenPlan(thread, parsed, block, replyText);
  const tags = novelAiSceneBlockToTags(block, thread, plan);
  if (!tags) return "";
  const tagParts = tags
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  if (tagParts.length < 2) return "";
  if (offlineImageSceneCaptionTooGeneric(tags) && tagParts.length < 4) return "";
  const out = offlineScenePromptFromEnglishTags(tags, thread, plan);
  return out || finalizeOfflineSessionImageScenePrompt(tags);
}

/**
 * 线下每轮生图场面：合格英文 tags → innerState/lines 叙事块（与线上同源转换）→ 关键词兜底。
 * @param {string} replyText
 * @param {{ charImageCaption?: string, charImageSubject?: string, hvState?: string }} parsed
 * @param {string} rawReply
 * @param {ReturnType<typeof readActiveThread>} thread
 */
function resolveOfflineAutoSessionImageScenePrompt(replyText, parsed, rawReply, thread) {
  let cap = String(parsed?.charImageCaption || "").trim();
  if (!cap) cap = extractOfflineImageTagCaptionFromRaw(rawReply);
  const hv = String(parsed?.hvState || "").trim();
  if (isPlausibleOfflineImageSceneCaption(cap)) {
    return offlineScenePromptFromEnglishTags(
      cap,
      thread,
      offlineAssistantImageGenPlan(thread, parsed, cap, replyText)
    );
  }
  if (
    cap &&
    !textLooksMostlyCjk(cap) &&
    offlineImageSceneCaptionLooksLikeTagList(cap) &&
    cap.length <= 360
  ) {
    return offlineScenePromptFromEnglishTags(
      cap,
      thread,
      offlineAssistantImageGenPlan(thread, parsed, cap, replyText)
    );
  }
  if (isPlausibleOfflineImageSceneCaption(hv)) {
    return offlineScenePromptFromEnglishTags(
      hv,
      thread,
      offlineAssistantImageGenPlan(thread, parsed, hv, replyText)
    );
  }
  const proseBlocks = [];
  if (hv) proseBlocks.push(hv.slice(0, 1200));
  const lineSn = extractOfflineNarrativeSnippetFromLines(replyText, { maxLen: 280 });
  if (lineSn) proseBlocks.push(lineSn);
  for (const block of proseBlocks) {
    const fromProse = offlineSessionImageSceneFromProseBlock(block, thread, parsed, replyText);
    if (fromProse) return fromProse;
  }
  const fallPlan = offlineAssistantImageGenPlan(thread, parsed, "", replyText);
  const fallGender = offlineMeetupImageGenderLead(thread, fallPlan).replace(/,\s*$/, "");
  const fallTags =
    fallPlan.subject === "both"
      ? `${fallGender || "2people"}, soft lighting`
      : fallPlan.subject === "char"
        ? `${fallGender || "1person"}, soft lighting`
        : "soft lighting";
  return offlineScenePromptFromEnglishTags(fallTags, thread, fallPlan);
}

/** 本轮 lines / innerState 叙事摘要，供生图 API 对齐剧情（不替代英文场面 tags）。 */
function extractOfflineStoryBeatForImageGen(replyText, parsed) {
  const hv = String(parsed?.hvState || "").trim();
  if (hv && /[\u4e00-\u9fff]/.test(hv)) {
    return (stripOfflineLinesDialogueForImageExtract(hv).slice(0, 450) || hv.slice(0, 450)).trim();
  }
  const lineSn = extractOfflineNarrativeSnippetFromLines(replyText, { maxLen: 280 });
  if (lineSn) return lineSn;
  return "";
}

/**
 * @param {object} entry
 * @param {string} replyText
 * @param {{ charImageCaption?: string, hvState?: string, charImageSubject?: string }} parsed
 * @param {string} rawReply
 * @param {ReturnType<typeof readActiveThread>} thread
 */
function tryAttachOfflineAutoSessionImageOnEntry(entry, replyText, parsed, rawReply, thread) {
  if (!thread || thread.kind === "group") return false;
  if (!isSessionImageGenConfigured()) return false;
  if (!isThreadOfflineEveryRoundSessionImage(thread)) {
    let capOnly = String(parsed?.charImageCaption || "").trim();
    if (!capOnly) capOnly = extractOfflineImageTagCaptionFromRaw(rawReply);
    if (!capOnly) return false;
  }
  const scene = resolveOfflineAutoSessionImageScenePrompt(replyText, parsed, rawReply, thread);
  if (!scene) return false;
  const storyBeat = extractOfflineStoryBeatForImageGen(replyText, parsed);
  attachOfflineSessionImageToAssistantMessage(entry, scene, storyBeat);
  applySessionImageSubjectOnRow(entry, thread, scene, undefined, parsed?.charImageSubject, replyText);
  return true;
}

/** @param {object} msg assistant log row (mutated) @param {string} scenePrompt @param {string} [storyBeat] */
function attachOfflineSessionImageToAssistantMessage(msg, scenePrompt, storyBeat) {
  if (!msg || typeof msg !== "object") return;
  const sc = String(scenePrompt || "").trim().slice(0, 3500);
  if (!sc) return;
  if (!msg.image || typeof msg.image !== "object") msg.image = {};
  msg.image.scenePrompt = sc;
  const beat = String(storyBeat || "").trim().slice(0, 450);
  if (beat) msg.image.offlineStoryBeat = beat;
  else delete msg.image.offlineStoryBeat;
  const desc = sc.replace(/\s+/g, " ").trim() || "scene illustration";
  msg.image.desc = desc.slice(0, 4000);
  delete msg.image.url;
  delete msg.image.omitInlineCaption;
  msg.image.imageGenPending = true;
}

/**
 * 本条 assistant 的会话配图：优先 charImageCaption；每轮生图无 caption 时用 innerState / narration。
 * @param {{ charImageCaption: string, charImgUrl: string, heartVoiceText: string, hvStateText?: string, narrationText?: string, everyRound: boolean, imgCfg: { enabled?: boolean, apiKey?: string } }} p
 * @returns {{ imgDesc: string, deferSessionImg: boolean }}
 */
function planAssistantSessionImageAttachment(p) {
  const cap0 = String(p.charImageCaption || "").trim();
  let imgDesc = cap0.slice(0, 4000);
  if (!imgDesc && p.everyRound) {
    const st = String(p.hvStateText || "").trim().slice(0, 1200);
    const nar = String(p.narrationText || "").trim().slice(0, 800);
    const sceneParts = [];
    if (st) sceneParts.push(st);
    if (nar) sceneParts.push(nar);
    let composed = sceneParts.join("\n\n").trim();
    if (!composed) {
      const hv = String(p.heartVoiceText || "").trim();
      if (hv) composed = hv.slice(0, 4000);
    }
    if (composed) imgDesc = composed.slice(0, 4000);
  }
  const hasUrl = Boolean(String(p.charImgUrl || "").trim());
  const cfg = p.imgCfg;
  const thread = p.thread && typeof p.thread === "object" ? p.thread : null;
  const deferSessionImg = Boolean(
    imgDesc &&
      !hasUrl &&
      cfg &&
      cfg.enabled &&
      String(cfg.apiKey || "").trim() &&
      isThreadDescImageApiGenEnabled(thread)
  );
  return { imgDesc, deferSessionImg };
}

/**
 * 改 `image.desc` / scene 后排队重绘（user / assistant；生图已接入）。
 * @param {{ role?: string, image?: { desc?: string, url?: string, imageGenPending?: boolean } }} msg
 * @returns {boolean}
 */
/** @param {unknown} m @param {ReturnType<typeof readActiveThread>} [thread] */
function chatMessageCanSessionImageRegen(m, thread) {
  if (!m || typeof m !== "object" || (m.role !== "user" && m.role !== "assistant")) return false;
  if (!getChatImageGenSceneBlockFromMessage(m)) return false;
  const cfg = readImageGenConfig();
  if (!cfg.enabled || !String(cfg.apiKey || "").trim()) return false;
  const th = thread && typeof thread === "object" ? thread : readActiveThread();
  if (m.role === "user" && !isThreadDescImageApiGenEnabled(th)) return false;
  return true;
}

function queueSessionImageRegenAfterDescPatch(msg) {
  if (!msg || (msg.role !== "assistant" && msg.role !== "user")) return false;
  if (!msg.image || typeof msg.image !== "object") msg.image = {};
  const desc = String(msg.image.desc || "").trim();
  const scene = String(msg.image.scenePrompt || "").trim();
  if (!desc && !scene) return false;
  const cfg = readImageGenConfig();
  if (!cfg.enabled || !String(cfg.apiKey || "").trim()) return false;
  if (msg.role === "user" && !isThreadDescImageApiGenEnabled(readActiveThread())) return false;
  msg.image.imageGenRev = (Number(msg.image.imageGenRev) || 0) + 1;
  msg.image.imageGenPending = true;
  return true;
}

/**
 * 大图预览与聊天气泡同步（重生成功后仍停留在预览时更新图面）。
 * @param {number} msgIdx
 * @param {unknown[]} [log]
 */
function refreshChatPhotoViewerForMsgIdx(msgIdx, log) {
  const i = Math.floor(Number(msgIdx));
  if (!Number.isFinite(i) || chatPhotoViewerMsgIdx !== i) return;
  const arr = Array.isArray(log) ? log : readChatLog();
  const m = arr[i];
  if (!m || typeof m !== "object" || !m.image || typeof m.image !== "object") return;
  const url = sanitizeStickerUrl(String(m.image.url || "").trim());
  if (!url) return;
  const img = document.getElementById("chat-photo-viewer-img");
  if (!(img instanceof HTMLImageElement)) return;
  syncChatPhotoViewerActionButtons(m);
  applyChatImageUrlToElement(img, url);
  img.alt = String(m.image.desc || "").trim() || "聊天图片";
  clearChatPhotoViewerDownloadPrefetch();
  const onReady = () => {
    updateChatPhotoViewerDownloadButton(url, img);
    void prefetchChatPhotoViewerDownload(url, img);
  };
  if (img.complete && img.naturalWidth) onReady();
  else img.addEventListener("load", onReady, { once: true });
}

/**
 * 已标记 imageGenPending 后执行生图并刷新 UI（编辑提示词 / 预览重生共用）。
 * @param {number} msgIdx
 * @param {{ maskId: string, threadId: string }} [threadRef]
 * @param {{ silent?: boolean }} [opts]
 * @returns {Promise<boolean>}
 */
async function runSessionImageRegenUiFlow(msgIdx, threadRef, opts) {
  const ref = threadRef || readChatActiveThreadRef();
  const maskId = String(ref.maskId || "").trim();
  const threadId = String(ref.threadId || "").trim();
  if (!maskId || !threadId) return false;
  const log = readChatLogForMaskThread(maskId, threadId);
  const i = Math.floor(Number(msgIdx));
  if (!Number.isFinite(i) || i < 0 || i >= log.length) return false;
  const msg = log[i];
  if (
    !msg ||
    (msg.role !== "assistant" && msg.role !== "user") ||
    !msg.image ||
    typeof msg.image !== "object" ||
    !msg.image.imageGenPending
  ) {
    return false;
  }
  const msgAtSnapshot = Number(msg.at);
  saveChatLogForMaskThread(maskId, threadId, log);
  chatSuppressNextChatMessageAnimations = true;
  renderChatMessages();
  syncChatPhotoViewerPendingOverlay(i);
  try {
    await runDeferredSessionImageGenForLogIndex(i, msgAtSnapshot, { maskId, threadId });
    const log2 = readChatLogForMaskThread(maskId, threadId);
    const m2 = log2[i];
    const ok = Boolean(m2?.image?.url && !m2.image.imageGenPending);
    if (ok && !opts?.silent) showToast("已重生");
    return ok;
  } catch {
    if (!opts?.silent) showToast("重生失败");
    return false;
  } finally {
    syncChatPhotoViewerPendingOverlay(Number.NaN);
    setChatPhotoViewerActionsBusy(false);
  }
}

/**
 * 从任意入口发起配图重生（预览按钮 / 长按改描述后等）。
 * @param {number} msgIdx
 * @param {{ threadRef?: { maskId: string, threadId: string }, silent?: boolean }} [opts]
 * @returns {Promise<boolean>}
 */
async function beginSessionImageRegenForMessage(msgIdx, opts) {
  const ref = opts?.threadRef || readChatActiveThreadRef();
  const maskId = String(ref.maskId || "").trim();
  const threadId = String(ref.threadId || "").trim();
  if (!maskId || !threadId) return false;
  const log = readChatLogForMaskThread(maskId, threadId);
  const i = Math.floor(Number(msgIdx));
  if (!Number.isFinite(i) || i < 0 || i >= log.length) return false;
  const msg = log[i];
  if (!msg || (msg.role !== "assistant" && msg.role !== "user") || !msg.image || typeof msg.image !== "object") {
    return false;
  }
  if (!getChatImageGenSceneBlockFromMessage(msg)) {
    if (!opts?.silent) showToast("无画面描述，无法重生");
    return false;
  }
  const cfg = readImageGenConfig();
  if (!cfg.enabled || !String(cfg.apiKey || "").trim()) {
    if (!opts?.silent) showToast("请先在「生图」中开启并填写 API Key");
    return false;
  }
  const th = findChatThreadInInbox(maskId, threadId)?.thread ?? readActiveThread();
  if (msg.role === "user" && !isThreadDescImageApiGenEnabled(th)) {
    if (!opts?.silent) showToast("请先在密谈详情开启「描述式生图」");
    return false;
  }
  if (!queueSessionImageRegenAfterDescPatch(msg)) return false;
  reconcileUserSessionImageSubject(msg, th);
  return runSessionImageRegenUiFlow(i, { maskId, threadId }, opts);
}

/**
 * @param {unknown[]} logArr
 * @param {{ maskId: string, threadId: string }} [threadRef]
 * @param {number} [msgIdx] 指定下标；省略则从末尾找最近一条 pending
 */
function kickoffPendingSessionImageGen(logArr, threadRef, msgIdx) {
  const arr = Array.isArray(logArr) ? logArr : [];
  const ref =
    threadRef && String(threadRef.maskId || "").trim() && String(threadRef.threadId || "").trim()
      ? { maskId: String(threadRef.maskId).trim(), threadId: String(threadRef.threadId).trim() }
      : readChatActiveThreadRef();
  const pending = (row) =>
    row &&
    (row.role === "assistant" || row.role === "user") &&
    row.image &&
    typeof row.image === "object" &&
    row.image.imageGenPending;
  if (msgIdx != null && Number.isFinite(Number(msgIdx))) {
    const i = Math.floor(Number(msgIdx));
    if (pending(arr[i])) void runSessionImageRegenUiFlow(i, ref, { silent: true });
    return;
  }
  for (let i = arr.length - 1; i >= 0; i--) {
    const row = arr[i];
    if (pending(row)) {
      void runSessionImageRegenUiFlow(i, ref, { silent: true });
      break;
    }
  }
}

/**
 * @param {number} msgIdx
 * @param {number} msgAtSnapshot
 * @param {{ maskId: string, threadId: string }} threadRefAtStart
 */
async function runDeferredSessionImageGenForLogIndex(msgIdx, msgAtSnapshot, threadRefAtStart) {
  const ref0 = threadRefAtStart || readChatActiveThreadRef();
  const maskId = String(ref0.maskId || "").trim();
  const threadId = String(ref0.threadId || "").trim();
  const readLog = () => readChatLogForMaskThread(maskId, threadId);
  const saveLog = (log) => saveChatLogForMaskThread(maskId, threadId, log);
  const guardMsgStable = () => {
    const log = readLog();
    const m = log[msgIdx];
    return (
      m &&
      (m.role === "assistant" || m.role === "user") &&
      Number(m.at) === msgAtSnapshot &&
      !m.restoring
    );
  };
  try {
    if (!maskId || !threadId) return;
    if (!guardMsgStable()) return;
    const log = readLog();
    const m = log[msgIdx];
    if (!m || (m.role !== "assistant" && m.role !== "user") || Number(m.at) !== msgAtSnapshot) return;
    if (!m.image || typeof m.image !== "object" || !m.image.imageGenPending) return;
    const capZh = getChatImageGenSceneBlockFromMessage(m);
    if (!capZh) {
      delete m.image.imageGenPending;
      saveLog(log);
      chatSuppressNextChatMessageAnimations = true;
      renderChatMessages();
      showToast("未生图：无有效场面描述");
      return;
    }
    const cfg = readImageGenConfig();
    if (!cfg.enabled || !String(cfg.apiKey || "").trim()) {
      delete m.image.imageGenPending;
      saveLog(log);
      chatSuppressNextChatMessageAnimations = true;
      renderChatMessages();
      showToast(
        !cfg.enabled ? "未生图：请先在生图接入勾选「启用」并保存" : "未生图：请配置并保存 API Key"
      );
      return;
    }
    const thread = findChatThreadInInbox(maskId, threadId)?.thread ?? null;
    let sceneApi = capZh.slice(0, 3500);
    if (m.role === "user") {
      reconcileUserSessionImageSubject(m, thread);
    }
    const offline = chatMessageDmSurface(m) === "offline";
    const plan = offline
      ? offlineAssistantImageGenPlan(
          thread,
          { charImageSubject: m.image?.imageSubject, hvState: "" },
          sceneApi,
          String(m?.content ?? "")
            .split(/\|\|\|/)
            .map((s) => String(s).trim())
            .filter(Boolean)
            .join("\n")
        )
      : resolveImageGenPlan(m, thread, sceneApi, log);
    if (m.role === "user" && m.image && typeof m.image === "object") {
      m.image.imageSubject = plan.subject;
      saveLog(log);
    }
    const prompt = buildImageGenPromptForProvider(cfg, thread, sceneApi, {
      offline,
      plan,
      msg: m,
      logArr: log
    });
    let refDataUrl = "";
    if (
      m.role !== "user" &&
      imageGenPlanAllowsThreadRef(plan) &&
      thread &&
      typeof thread === "object"
    ) {
      refDataUrl = resolveThreadCharImageRefDataUrl(thread);
    }
    const r = await executeImageGenRequestToDataUrl(cfg, prompt, {
      ...(refDataUrl ? { refDataUrl } : {}),
      preferLongTimeout:
        m.role === "assistant" || plan.subject === "both" || plan.includeCharStrong
    });
    if (!guardMsgStable()) {
      showToast("消息已变化，配图未能保存");
      return;
    }
    const log2 = readLog();
    const m2 = log2[msgIdx];
    if (!m2 || (m2.role !== "assistant" && m2.role !== "user") || Number(m2.at) !== msgAtSnapshot) return;
    if (!m2.image || typeof m2.image !== "object" || !m2.image.imageGenPending) return;
    if (!r.ok || !r.dataUrl) {
      delete m2.image.imageGenPending;
      if (r.error) showToast(`生图失败：${String(r.error).slice(0, 80)}`);
      else showToast("生图失败");
      saveLog(log2);
      chatSuppressNextChatMessageAnimations = true;
      renderChatMessages();
      return;
    }
    let out = r.dataUrl;
    try {
      out = await shrinkDataUrlWithCanvas(r.dataUrl, 1280, 0.88);
    } catch {
      /* keep raw */
    }
    const u = sanitizeStickerUrl(String(out || "").trim()) || sanitizeStickerUrl(r.dataUrl);
    m2.image.url = u;
    m2.image.omitInlineCaption = true;
    delete m2.image.imageGenPending;
    saveLog(log2);
    chatSuppressNextChatMessageAnimations = true;
    renderChatMessages();
    refreshChatPhotoViewerForMsgIdx(msgIdx, log2);
  } catch {
    if (!guardMsgStable()) return;
    try {
      const log3 = readLog();
      const m3 = log3[msgIdx];
      if (m3 && m3.image && typeof m3.image === "object" && m3.image.imageGenPending && Number(m3.at) === msgAtSnapshot) {
        delete m3.image.imageGenPending;
        saveLog(log3);
        chatSuppressNextChatMessageAnimations = true;
        renderChatMessages();
      }
    } catch {
      /* ignore */
    }
  }
}

let chatPhotoViewerMsgIdx = -1;
/** 大图预览打开后预取的 blob，供「下载」在同一次点击里触发保存框（避免 await 后丢失用户手势） */
/** @type {{ stored: string, blob: Blob } | null} */
let chatPhotoViewerDownloadPrefetch = null;

/** @param {number} msgIdx 非有限值时仅清除预览区遮罩 */
function syncChatPhotoViewerPendingOverlay(msgIdx) {
  const wrap = document.querySelector(".chat-photo-viewer-img-wrap");
  if (!wrap) return;
  wrap.querySelector(".chat-photo-polaroid-pending-overlay")?.remove();
  wrap.classList.remove("chat-photo-polaroid-mount--pending");
  const i = Math.floor(Number(msgIdx));
  if (!Number.isFinite(i) || chatPhotoViewerMsgIdx !== i) return;
  const root = document.getElementById("chat-photo-viewer");
  if (!root?.classList.contains("is-open")) return;
  const m = readChatLog()[i];
  if (!m?.image?.imageGenPending) return;
  mountChatPhotoPolaroidPendingOverlay(wrap, {
    regen: Boolean(String(m.image.url || "").trim())
  });
}

function setChatPhotoViewerActionsBusy(busy) {
  for (const id of [
    "chat-photo-viewer-regen",
    "chat-photo-viewer-download",
    "chat-photo-viewer-close",
    "chat-photo-viewer-set-char-avatar",
    "chat-photo-viewer-set-user-avatar"
  ]) {
    const el = document.getElementById(id);
    if (el instanceof HTMLButtonElement) {
      el.disabled = busy;
      if (id === "chat-photo-viewer-download") {
        if (busy) el.dataset.xxjDownloadBusy = "1";
        else delete el.dataset.xxjDownloadBusy;
      }
    }
  }
  if (!busy) {
    const img = document.getElementById("chat-photo-viewer-img");
    const i = chatPhotoViewerMsgIdx;
    const log = readChatLog();
    const m =
      Number.isFinite(i) && i >= 0 && i < log.length && log[i]?.image ? log[i] : null;
    const stored = m
      ? sanitizeStickerUrl(String(m.image.url || "").trim())
      : img instanceof HTMLImageElement
        ? String(img.dataset.xxjBlobRef || img.src || "").trim()
        : "";
    updateChatPhotoViewerDownloadButton(stored, img instanceof HTMLImageElement ? img : null);
  }
}

function closeChatPhotoViewer() {
  const root = document.getElementById("chat-photo-viewer");
  if (!root) return;
  syncChatPhotoViewerPendingOverlay(Number.NaN);
  clearChatPhotoViewerDownloadPrefetch();
  setChatPhotoViewerActionsBusy(false);
  root.classList.remove("is-open");
  const img = document.getElementById("chat-photo-viewer-img");
  if (img) {
    img.removeAttribute("src");
    img.removeAttribute("data-xxj-blob-ref");
  }
  chatPhotoViewerMsgIdx = -1;
  window.setTimeout(() => {
    root.hidden = true;
    root.setAttribute("aria-hidden", "true");
  }, 160);
}

/** 大图预览：按消息角色显示「设为头像」等按钮 */
function syncChatPhotoViewerActionButtons(msg) {
  const charBtn = document.getElementById("chat-photo-viewer-set-char-avatar");
  const userBtn = document.getElementById("chat-photo-viewer-set-user-avatar");
  const regenBtn = document.getElementById("chat-photo-viewer-regen");
  const pending = Boolean(msg?.image?.pending);
  const role = String(msg?.role || "");
  const hasUrl = Boolean(sanitizeStickerUrl(String(msg?.image?.url || "").trim()));
  const canUse = hasUrl && !pending && (role === "user" || role === "assistant");
  if (charBtn instanceof HTMLButtonElement) {
    charBtn.hidden = !canUse;
    charBtn.textContent = role === "assistant" ? "设为 Ta 头像" : "给 Ta 当头像";
  }
  if (userBtn instanceof HTMLButtonElement) {
    userBtn.hidden = !(canUse && role === "user");
  }
  if (regenBtn instanceof HTMLButtonElement && msg) {
    regenBtn.hidden = !chatMessageCanSessionImageRegen(msg, readActiveThread());
  }
}

/** @param {number|string} msgIdx @param {"char"|"user"} target */
async function applyChatPhotoAsThreadAvatar(msgIdx, target) {
  const log = readChatLog();
  const i = Math.floor(Number(msgIdx));
  if (!Number.isFinite(i) || i < 0 || i >= log.length) return;
  const m = log[i];
  if (!m?.image?.url) return;
  const url = sanitizeStickerUrl(String(m.image.url || "").trim());
  if (!url) return;
  const img = document.getElementById("chat-photo-viewer-img");
  setChatPhotoViewerActionsBusy(true);
  try {
    const blob = await chatImageBlobFromStoredUrl(url, img instanceof HTMLImageElement ? img : null);
    const dataUrl = await blobToDataUrl(blob);
    const shrunk = await shrinkDataUrlWithCanvas(String(dataUrl || ""), 512, 0.82);
    const data = shrunk || String(dataUrl || "").trim();
    if (!data) throw new Error("empty");
    const field = target === "char" ? "chatThreadCharAvatar" : "chatThreadUserAvatar";
    if (
      !patchActiveThread((th) => {
        th[field] = data;
      })
    ) {
      showToast("无法保存");
      return;
    }
    updateChatHeaderFaces();
    scheduleRenderChatMessages();
    syncChatThreadDetailPanelPlaceholders();
    showToast(target === "char" ? "本密谈角色头像已更新" : "本密谈主控头像已更新");
  } catch {
    showToast("无法读取图片");
  } finally {
    setChatPhotoViewerActionsBusy(false);
  }
}

function openChatPhotoViewerFromMsgIdx(msgIdx) {
  reparentChatInnerVoiceShellsForActiveSurface();
  const log = readChatLog();
  const i = Math.floor(Number(msgIdx));
  if (!Number.isFinite(i) || i < 0 || i >= log.length) return;
  const m = log[i];
  if (!m || typeof m !== "object" || !m.image || typeof m.image !== "object") return;
  const url = sanitizeStickerUrl(String(m.image.url || "").trim());
  if (!url) return;
  const omitCap = Boolean(m.image.omitInlineCaption);
  const cap = omitCap ? "" : String(m.image.desc || "").trim();
  chatPhotoViewerMsgIdx = i;
  const root = document.getElementById("chat-photo-viewer");
  const img = document.getElementById("chat-photo-viewer-img");
  const capEl = document.getElementById("chat-photo-viewer-caption");
  if (!root || !img) return;
  syncChatPhotoViewerActionButtons(m);
  applyChatImageUrlToElement(img, url);
  img.alt = cap || "聊天图片";
  if (capEl) {
    if (cap) {
      capEl.textContent = cap;
      capEl.hidden = false;
    } else {
      capEl.textContent = "";
      capEl.hidden = true;
    }
  }
  clearChatPhotoViewerDownloadPrefetch();
  const dlBtn = document.getElementById("chat-photo-viewer-download");
  if (dlBtn instanceof HTMLButtonElement) {
    dlBtn.disabled = true;
    dlBtn.title = "图片加载中，请稍候";
    dlBtn.setAttribute("aria-label", dlBtn.title);
  }
  const onViewerImgReady = () => {
    updateChatPhotoViewerDownloadButton(url, img);
    void prefetchChatPhotoViewerDownload(url, img);
  };
  if (img.complete && img.naturalWidth) onViewerImgReady();
  else img.addEventListener("load", onViewerImgReady, { once: true });
  root.hidden = false;
  root.setAttribute("aria-hidden", "false");
  window.requestAnimationFrame(() => {
    root.classList.add("is-open");
  });
}

function chatImageExtFromBlobType(type) {
  const t = String(type || "").toLowerCase();
  if (t.includes("png")) return "png";
  if (t.includes("webp")) return "webp";
  if (t.includes("gif")) return "gif";
  return "jpg";
}

function isUsableChatImageBlob(blob) {
  return !!(blob && blob.size >= 64 && String(blob.type || "").toLowerCase().startsWith("image/"));
}

async function chatImageBlobFromLoadedImg(img) {
  if (!(img instanceof HTMLImageElement)) throw new Error("no img");
  if (!img.complete || !img.naturalWidth) {
    await new Promise((resolve, reject) => {
      const done = () => (img.naturalWidth ? resolve() : reject(new Error("empty")));
      if (img.complete) return done();
      img.addEventListener("load", done, { once: true });
      img.addEventListener("error", () => reject(new Error("load")), { once: true });
    });
  }
  const w = img.naturalWidth;
  const h = img.naturalHeight;
  if (!w || !h) throw new Error("empty");
  const canvas = document.createElement("canvas");
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("no ctx");
  ctx.drawImage(img, 0, 0);
  const blob = await new Promise((resolve, reject) => {
    canvas.toBlob((b) => (b && b.size ? resolve(b) : reject(new Error("toBlob"))), "image/jpeg", 0.92);
  });
  return blob;
}

async function chatImageBlobFromUrl(url) {
  const u = String(url || "").trim();
  if (!u) throw new Error("empty");
  if (/^data:image\//i.test(u) || /^blob:/i.test(u)) {
    const resp = await fetch(u);
    const blob = await resp.blob();
    if (isUsableChatImageBlob(blob)) return blob;
    throw new Error("bad blob");
  }
  const resp = await fetch(u, { mode: "cors", credentials: "omit" });
  if (!resp.ok) throw new Error(String(resp.status));
  const blob = await resp.blob();
  if (isUsableChatImageBlob(blob)) return blob;
  throw new Error("not image");
}

function clearChatPhotoViewerDownloadPrefetch() {
  chatPhotoViewerDownloadPrefetch = null;
}

function chatImageDownloadStem(baseName) {
  return String(baseName || "没心机-聊天图片")
    .trim()
    .replace(/[/\\?%*:|"<>]/g, "_")
    .slice(0, 72);
}

/**
 * 已解码的 img → 同步 toDataURL，在同一次点击里触发浏览器「另存为」确认框。
 * @param {HTMLImageElement} img
 */
function trySyncChatImageDataUrlFromImg(img) {
  if (!(img instanceof HTMLImageElement)) return "";
  if (!img.complete || !img.naturalWidth || !img.naturalHeight) return "";
  const src = String(img.currentSrc || img.src || "").trim();
  if (!src || /^data:image\/svg\+xml/i.test(src)) return "";
  const blobRef = String(img.dataset.xxjBlobRef || "").trim();
  if (blobRef && isChatImageBlobRef(blobRef) && (src === blobRef || isChatImageBlobRef(src))) return "";
  try {
    const canvas = document.createElement("canvas");
    canvas.width = img.naturalWidth;
    canvas.height = img.naturalHeight;
    const ctx = canvas.getContext("2d");
    if (!ctx) return "";
    ctx.drawImage(img, 0, 0);
    const dataUrl = canvas.toDataURL("image/jpeg", 0.92);
    return dataUrl && dataUrl.length > 128 ? dataUrl : "";
  } catch {
    return "";
  }
}

function triggerChatImageDataUrlDownload(dataUrl, stem) {
  const a = document.createElement("a");
  a.href = dataUrl;
  a.download = `${stem || "image"}.jpg`;
  a.rel = "noopener";
  document.body.appendChild(a);
  a.click();
  a.remove();
}

function triggerChatImageBlobDownload(blob, stem) {
  const ext = chatImageExtFromBlobType(blob.type);
  const ou = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = ou;
  a.download = `${stem || "image"}.${ext}`;
  a.rel = "noopener";
  document.body.appendChild(a);
  a.click();
  a.remove();
  window.setTimeout(() => {
    try {
      URL.revokeObjectURL(ou);
    } catch (_) {
      /* ignore */
    }
  }, 8000);
}

/** img 已是 blob:/data: 时直接 a.href=src 下载（不画 canvas）。 */
function triggerChatImageSrcDownload(src, stem) {
  const s = String(src || "").trim();
  if (!s || /^data:image\/svg\+xml/i.test(s) || isChatImageBlobRef(s)) return false;
  const a = document.createElement("a");
  a.href = s;
  const ext = /^data:image\/png/i.test(s)
    ? "png"
    : /^data:image\/webp/i.test(s)
      ? "webp"
      : /^data:image\/gif/i.test(s)
        ? "gif"
        : "jpg";
  a.download = `${stem || "image"}.${ext}`;
  a.rel = "noopener";
  document.body.appendChild(a);
  a.click();
  a.remove();
  return true;
}

/** @param {HTMLImageElement | null | undefined} img */
function isChatPhotoViewerImgDisplayReady(img) {
  if (!(img instanceof HTMLImageElement)) return false;
  if (!img.complete || !img.naturalWidth || !img.naturalHeight) return false;
  const src = String(img.currentSrc || img.src || "").trim();
  if (!src || /^data:image\/svg\+xml/i.test(src)) return false;
  if (isChatImageBlobRef(src)) return false;
  return true;
}

/**
 * @param {string} stored
 * @param {HTMLImageElement | null | undefined} img
 */
function isChatPhotoViewerDownloadReady(stored, img) {
  const key = String(stored || "").trim();
  if (!key) return false;
  if (chatPhotoViewerDownloadPrefetch?.stored === key && chatPhotoViewerDownloadPrefetch.blob) return true;
  if (isChatImageBlobRef(key)) return true;
  return isChatPhotoViewerImgDisplayReady(img) || Boolean(trySyncChatImageDataUrlFromImg(img));
}

/**
 * @param {string} stored
 * @param {HTMLImageElement | null | undefined} img
 */
function updateChatPhotoViewerDownloadButton(stored, img) {
  const btn = document.getElementById("chat-photo-viewer-download");
  if (!(btn instanceof HTMLButtonElement)) return;
  if (btn.dataset.xxjDownloadBusy === "1") return;
  const ready = isChatPhotoViewerDownloadReady(stored, img);
  btn.disabled = !ready;
  const title = ready ? "下载图片" : "图片加载中，请稍候";
  btn.title = title;
  btn.setAttribute("aria-label", title);
}

/**
 * @param {string} stored
 * @param {HTMLImageElement | null | undefined} imgEl
 */
async function prefetchChatPhotoViewerDownload(stored, imgEl) {
  const key = String(stored || "").trim();
  if (!key) return;
  try {
    const blob = await chatImageBlobFromStoredUrl(
      key,
      imgEl instanceof HTMLImageElement ? imgEl : null
    );
    if (!isUsableChatImageBlob(blob)) throw new Error("bad blob");
    chatPhotoViewerDownloadPrefetch = { stored: key, blob };
  } catch {
    chatPhotoViewerDownloadPrefetch = null;
  }
  updateChatPhotoViewerDownloadButton(key, imgEl instanceof HTMLImageElement ? imgEl : null);
}

function runChatPhotoViewerDownloadClick() {
  const img = document.getElementById("chat-photo-viewer-img");
  const i = chatPhotoViewerMsgIdx;
  const log = readChatLog();
  const m =
    Number.isFinite(i) && i >= 0 && i < log.length && log[i]?.image ? log[i] : null;
  const stored = m
    ? sanitizeStickerUrl(String(m.image.url || "").trim())
    : img instanceof HTMLImageElement
      ? String(img.dataset.xxjBlobRef || img.src || "").trim()
      : "";
  if (!stored) {
    showToast("没有可下载的图片");
    return;
  }
  const stem = chatImageDownloadStem("没心机-聊天图片");
  const pref = chatPhotoViewerDownloadPrefetch;
  if (pref && pref.stored === stored && pref.blob) {
    try {
      triggerChatImageBlobDownload(pref.blob, stem);
      showToast("已开始下载");
      return;
    } catch {
      showToast("下载失败");
      return;
    }
  }
  if (img instanceof HTMLImageElement) {
    const src = String(img.currentSrc || img.src || "").trim();
    if (triggerChatImageSrcDownload(src, stem)) {
      showToast("已开始下载");
      return;
    }
    const dataUrl = trySyncChatImageDataUrlFromImg(img);
    if (dataUrl) {
      try {
        triggerChatImageDataUrlDownload(dataUrl, stem);
        showToast("已开始下载");
        return;
      } catch {
        showToast("下载失败");
        return;
      }
    }
  }
  const dlBtn = document.getElementById("chat-photo-viewer-download");
  if (dlBtn instanceof HTMLButtonElement) {
    dlBtn.disabled = true;
    dlBtn.dataset.xxjDownloadBusy = "1";
  }
  showToast("准备下载…");
  void (async () => {
    try {
      const blob = await chatImageBlobFromStoredUrl(
        stored,
        img instanceof HTMLImageElement ? img : null
      );
      triggerChatImageBlobDownload(blob, stem);
      showToast("已开始下载");
    } catch {
      showToast("下载失败，可长按图片另存");
    } finally {
      if (dlBtn instanceof HTMLButtonElement) delete dlBtn.dataset.xxjDownloadBusy;
      updateChatPhotoViewerDownloadButton(stored, img instanceof HTMLImageElement ? img : null);
    }
  })();
}

async function regenerateChatMessageImage(msgIdx) {
  const i = Math.floor(Number(msgIdx));
  if (!Number.isFinite(i)) return;
  setChatPhotoViewerActionsBusy(true);
  showToast("配图重绘中…");
  const ok = await beginSessionImageRegenForMessage(i);
  if (ok && chatPhotoViewerMsgIdx === i) {
    /* 预览内已 refresh；可选保持打开 */
  }
}

function stWorldInfoEntryKeywords(e) {
  if (!e || typeof e !== "object") return "";
  if (Array.isArray(e.keys)) return e.keys.map((x) => String(x).trim()).filter(Boolean).join(", ");
  if (typeof e.keys === "string") return e.keys.trim();
  if (typeof e.key === "string") return e.key.trim();
  return "";
}

function findTavernEmbeddedWorldBook(charData) {
  if (!charData || typeof charData !== "object") return null;
  let book = charData.character_book || charData.world_info;
  if (book && Array.isArray(book.entries)) return book.entries;
  const nested = charData.data && typeof charData.data === "object" ? charData.data : null;
  if (nested) {
    book = nested.character_book || nested.world_info;
    if (book && Array.isArray(book.entries)) return book.entries;
  }
  return null;
}

/** @returns {{ count: number, volumeId: string }} */
function importTavernWorldBookEntriesToStore(displayName, entries) {
  if (!entries || !entries.length) return { count: 0, volumeId: "" };
  const store = readWorldBookStore();
  const vid = newWorldBookEntryId();
  const mapped = entries.map((e, idx) => {
    const titleRaw =
      (e && (e.comment || e.name || e.uid)) != null ? String(e.comment || e.name || e.uid).trim() : "";
    return {
      id: newWorldBookEntryId(),
      title: titleRaw || `条目 ${idx + 1}`,
      keywords: stWorldInfoEntryKeywords(e),
      content: e && e.content != null ? String(e.content) : "",
      enabled: e ? e.enabled !== false : true
    };
  });
  const volTitle = `「${String(displayName || "角色").trim() || "角色"}」· 卡内世界书`;
  store.volumes.unshift({
    id: vid,
    title: volTitle,
    entries: mapped
  });
  writeWorldBookStore(store);
  return { count: mapped.length, volumeId: vid };
}

/** 将世界书卷绑定到当前主控面具桶内、指定 charId 的所有密谈（单聊及含该角色的群聊） */
function bindWorldBookVolumeToThreadsForChar(charId, volumeId) {
  const cid = String(charId || "").trim();
  const vid = String(volumeId || "").trim();
  if (!cid || !vid) return 0;
  const D = window.XXJ_DB;
  if (!D) return 0;
  const maskId = getActiveMaskIdForInbox();
  if (!maskId) return 0;
  const inbox = readChatInboxStore();
  ensureMaskBucket(inbox, maskId);
  const bucket = inbox.byMask[maskBucketKey(maskId)];
  let n = 0;
  for (const th of bucket.threads) {
    if (String(th.charId || "").trim() !== cid) continue;
    th.worldBookVolumeIds = [vid].filter(Boolean);
    delete th.worldBookVolumeId;
    th.updatedAt = Date.now();
    n += 1;
  }
  if (n) writeChatInboxStore(inbox);
  return n;
}

function buildSummaryFromTavernChar(charData) {
  const parts = [];
  if (charData.description) parts.push(String(charData.description).trim());
  if (charData.personality) parts.push(`[Personality]\n${String(charData.personality).trim()}`);
  if (charData.mes_example) parts.push(`[Message Examples]\n${String(charData.mes_example).trim()}`);
  if (charData.scenario) parts.push(`[Scenario]\n${String(charData.scenario).trim()}`);
  return parts.filter(Boolean).join("\n\n");
}

function applyTavernCharDataToCharForm(charData, opts) {
  const preferEmbeddedAvatar = Boolean(opts && opts.preferEmbeddedAvatar);
  const name = String(charData.name || "").trim() || "未命名角色";
  const elName = document.getElementById("char-display-name");
  if (elName) elName.value = name;
  const elSum = document.getElementById("char-summary");
  if (elSum) elSum.value = buildSummaryFromTavernChar(charData);
  const elTags = document.getElementById("char-tags");
  if (elTags) elTags.value = tavernTagsToLine(charData.tags);
  const elAliases = document.getElementById("char-aliases");
  if (elAliases) elAliases.value = "";
  const elVoice = document.getElementById("char-voice");
  if (elVoice) elVoice.value = "";
  const elBound = document.getElementById("char-boundaries");
  if (elBound) {
    const cn = charData.creator_notes != null ? String(charData.creator_notes).trim() : "";
    elBound.value = cn ? `[Creator notes]\n${cn}` : "";
  }
  const elNpc = document.getElementById("char-npc-relations");
  if (elNpc) elNpc.value = "";
  const opLines = [];
  if (charData.first_mes) opLines.push(String(charData.first_mes).trim());
  if (Array.isArray(charData.alternate_greetings)) {
    charData.alternate_greetings.forEach((g) => {
      const t = String(g || "").trim();
      if (t) opLines.push(t);
    });
  }
  renderCharOpeningsEditor(opLines);
  const cardAvatar =
    (typeof charData.avatar === "string" && charData.avatar.trim() && charData.avatar) || "";
  if (cardAvatar.startsWith("data:")) {
    void shrinkDataUrlWithCanvas(cardAvatar, 512, 0.82).then((url) => {
      if (preferEmbeddedAvatar || !document.getElementById("char-avatar-img")?.getAttribute("src")) {
        renderCharAvatar(url);
      }
    });
  } else if (cardAvatar.startsWith("http")) {
    if (preferEmbeddedAvatar || !document.getElementById("char-avatar-img")?.getAttribute("src")) {
      renderCharAvatar(cardAvatar);
    }
  }
}

