async function handleCharTavernImportFile(file) {
  if (!file) return;
  const name = file.name || "";
  const type = String(file.type || "");
  const looksJson = type.includes("json") || /\.json$/i.test(name);
  const looksPng = type === "image/png" || /\.png$/i.test(name);
  if (!looksJson && !looksPng) {
    showToast("请选择 PNG 角色卡或 JSON");
    return;
  }
  try {
    let charRoot;
    if (looksJson) {
      const text = await file.text();
      charRoot = JSON.parse(text);
    } else {
      const buf = await file.arrayBuffer();
      charRoot = extractCharaJsonFromPngBuffer(buf);
      if (!charRoot) {
        showToast("PNG 内未找到角色卡数据");
        return;
      }
      const fr = new FileReader();
      const dataUrl = await new Promise((res, rej) => {
        fr.onload = () => res(String(fr.result || ""));
        fr.onerror = () => rej(new Error("read"));
        fr.readAsDataURL(file);
      });
      const shrunk = await shrinkDataUrlWithCanvas(dataUrl, 512, 0.82);
      renderCharAvatar(shrunk);
    }
    const charData = unwrapTavernCharRoot(charRoot);
    if (!charData || typeof charData !== "object") {
      showToast("角色数据无效");
      return;
    }
    applyTavernCharDataToCharForm(charData, { preferEmbeddedAvatar: looksJson });
    const wb = findTavernEmbeddedWorldBook(charRoot) || findTavernEmbeddedWorldBook(charData);
    let nWb = 0;
    let newVolId = "";
    if (wb && wb.length) {
      const disp = String(charData.name || "").trim() || "未命名角色";
      const r = importTavernWorldBookEntriesToStore(disp, wb);
      nWb = r.count;
      newVolId = r.volumeId || "";
    }
    const st = readCharPersonaStore();
    const activeCharId = st.activeId ? String(st.activeId).trim() : "";
    // 绑定策略：
    // 1) 写入“角色默认世界书”，确保之后新建该角色密谈会自动绑定
    // 2) 若当前面具下已有该角色的密谈，则顺便批量绑定到这些密谈
    if (newVolId && activeCharId) {
      const idx = st.items.findIndex((x) => x.id === activeCharId);
      if (idx >= 0) {
        const vid = String(newVolId || "").trim();
        st.items[idx] = {
          ...st.items[idx],
          defaultWorldBookVolumeId: vid,
          worldBookVolumeIds: vid ? [vid] : []
        };
        writeCharPersonaStore(st);
        setCharMainWorldBookDraftIds(vid ? [vid] : []);
        refreshCharMainWorldBookBindChips();
      }
    }
    const nBound =
      newVolId && activeCharId ? bindWorldBookVolumeToThreadsForChar(activeCharId, newVolId) : 0;
    setCharPaneDirty(true);
    if (nWb > 0) {
      if (nBound > 0) {
        showToast(
          `已导入 ST 卡；卡内世界书已入库（${nWb} 条），并已绑定当前面具下 ${nBound} 条密谈。请保存角色`
        );
      } else {
        showToast(`已导入 ST 卡；世界书已追加 ${nWb} 条（书架查看）。请保存角色`);
      }
      updateChatChrome();
      syncChatThreadDetailPanelPlaceholders();
    } else {
      showToast("已导入 SillyTavern 卡，请点「保存角色」");
    }
  } catch (err) {
    console.warn("[Tavern import]", err);
    showToast(looksJson ? "JSON 解析失败" : "导入失败");
  }
}

function collectUserMaskFromForm() {
  const val = (id) => document.getElementById(id)?.value?.trim() ?? "";
  const img = document.getElementById("user-mask-avatar-img");
  const avatar =
    img && img.getAttribute("src") && !img.classList.contains("is-hidden") ? img.src : "";
  const cur = readUserMask();
  const promptRaw = document.getElementById("user-mask-image-gen-prompt");
  const userImageGenPrompt =
    promptRaw instanceof HTMLTextAreaElement
      ? normalizeCharImageGenPromptTagLine(promptRaw.value).slice(0, 2000)
      : "";
  return {
    displayName: val("user-mask-display-name"),
    avatar,
    persona: val("user-mask-persona"),
    summary: val("user-mask-summary"),
    voice: val("user-mask-voice"),
    boundaries: val("user-mask-boundaries"),
    userImageGenPrompt,
    region: normalizeUserMaskRegion(cur.region)
  };
}

