function onAppGridClick(event) {
  const target = event.target.closest("#app-grid [data-app]");
  if (!target) return;
  const appName = target.dataset.app || "应用";
  if (appName === "设置" || appName === "设定") {
    openSettings();
    return;
  }
  if (appName === "我的") {
    openMyScreen();
    return;
  }
  if (appName === "人设") {
    openCharScreen();
    return;
  }
  if (appName === "聊天") {
    openChatListScreen();
    return;
  }
  if (appName === "查岗") {
    if (typeof openCheckupScreen === "function") openCheckupScreen();
    else showToast("查岗模块未加载");
    return;
  }
  if (appName === "漫游") {
    if (typeof openRoamScreen === "function") openRoamScreen();
    else showToast("漫游模块未加载");
    return;
  }
  if (appName === "关系") {
    if (typeof openRelationScreen === "function") openRelationScreen();
    else showToast("关系模块未加载");
    return;
  }
  if (appName === "表情包" || appName === "表情" || appName === "贴纸") {
    openStickerScreen("manage");
    return;
  }
  showToast(`${appName} · 敬请期待`);
}

function bindAppGridClick() {
  const grid = document.getElementById("app-grid");
  if (!grid || grid.dataset.xxjClickBound === "1") return;
  grid.dataset.xxjClickBound = "1";
  grid.addEventListener("click", onAppGridClick);
}

