document.querySelectorAll("#drawer .drawer-item, .dock-btn").forEach((node) => {
  node.addEventListener("click", () => {
    if (node.dataset.app === "设置") {
      openSettings();
      return;
    }
    if (node.dataset.app === "我的") {
      openMyScreen();
      return;
    }
    if (node.dataset.app === "角色库") {
      openCharScreen();
      return;
    }
    if (node.dataset.app === "消息") {
      openChatListScreen();
      return;
    }
    if (node.dataset.app === "世界书") {
      openWorldBookScreen();
      return;
    }
    if (node.dataset.app === "论坛") {
      if (typeof openForumScreen === "function") {
        openForumScreen();
      } else if (typeof window.__xxjScheduleMainApp === "function") {
        window.__xxjPendingAppAction = () => {
          if (typeof openForumScreen === "function") openForumScreen();
          else showToast("论坛模块未加载");
        };
        window.__xxjScheduleMainApp();
      } else {
        showToast("论坛模块未加载");
      }
      drawer.classList.remove("open");
      return;
    }
    if (node.dataset.app === "表情包" || node.dataset.app === "表情" || node.dataset.app === "贴纸") {
      openStickerScreen("manage");
      return;
    }
    showToast(`${node.textContent.trim()} · 敬请期待`);
  });
});

