document.getElementById("backup-zip-import-file")?.addEventListener("change", async (e) => {
  const input = /** @type {HTMLInputElement} */ (e.target);
  const file = input.files?.[0];
  input.value = "";
  if (!file) return;
  const JSZipLib = window.JSZip;
  if (typeof JSZipLib !== "function") {
    showToast("ZIP 模块未加载，请检查网络后刷新");
    return;
  }
  try {
    const ab = await file.arrayBuffer();
    const zip = await JSZipLib.loadAsync(ab);
    const mf = zip.file("manifest.json");
    if (!mf) throw new Error("缺少 manifest.json");
    const manifest = JSON.parse(await mf.async("string"));
    if (manifest.format !== BACKUP_ZIP_FORMAT) throw new Error("不是本应用导出的 ZIP");
    if (Number(manifest.version) !== BACKUP_ZIP_VERSION) throw new Error("备份版本与当前应用不一致，请更新或使用对应版本");
    await populateBackupZipImportFromLoaded(zip, manifest, file.name);
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    showToast(`读取失败：${msg}`);
    resetBackupZipImportUi();
  }
});
document.getElementById("backup-zip-import-run")?.addEventListener("click", async () => {
  if (!pendingBackupZip || !pendingBackupManifest) {
    showToast("请先选择 ZIP");
    return;
  }
  const checked = document.querySelectorAll("#backup-zip-import-checks input[type=checkbox]:checked");
  if (!checked.length) {
    showToast("请至少勾选一项要恢复的内容");
    return;
  }
  const runEl = document.getElementById("backup-zip-import-run");
  const prevRunLabel = runEl?.textContent || "恢复所选";
  if (runEl) {
    runEl.disabled = true;
    runEl.textContent = "正在恢复…";
  }
  setBackupZipImportStatus("正在写入本地数据库，请勿关闭页面…", "pending");
  try {
    const result = await applyBackupZipImport(pendingBackupZip, pendingBackupManifest, (msg) =>
      setBackupZipImportStatus(msg, "pending")
    );
    if (!result || result.ok === false) {
      const detail = result && result.err ? String(result.err) : "导入失败";
      setBackupZipImportStatus(detail, "err");
      return;
    }
    if (!result.moduleLabels.length) {
      setBackupZipImportStatus("未勾选任何模块", "err");
      showToast("导入失败");
      return;
    }
    if (result.inboxImported && result.inboxOk === false) {
      setBackupZipImportStatus("聊天记录写入未完全确认，请勿立即刷新；稍等几秒后重新打开密谈", "err");
      showToast("聊天记录写入未完全确认，请稍等几秒再刷新");
      refreshSurfacesAfterBackupZipImport(result);
      return;
    }
    const skippedNote =
      Array.isArray(result.skipped) && result.skipped.length
        ? `（已跳过 ${result.skipped.map((s) => s.label).join("、")}）`
        : "";
    setBackupZipImportStatus(`导入成功${skippedNote}`, "ok");
    refreshSurfacesAfterBackupZipImport(result);
    showToast(skippedNote ? `导入成功${skippedNote}` : "导入成功");
    window.setTimeout(() => closeBackupZipModal(), 2400);
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    setBackupZipImportStatus(msg ? `导入失败：${msg}` : "导入失败", "err");
    showToast("导入失败");
  } finally {
    if (runEl) {
      runEl.disabled = false;
      runEl.textContent = prevRunLabel;
    }
  }
});
