document.getElementById("chat-thread-list-root")?.addEventListener("click", (e) => {
  const wrap = e.target.closest(".chat-thread-bead-wrap");
  if (wrap) {
    const li = wrap.closest(".chat-thread-li");
    const menuItem = e.target.closest(".chat-thread-bead-menu-item");
    if (menuItem?.dataset.action && li) {
      e.preventDefault();
      e.stopPropagation();
      const tid = String(wrap.dataset.threadId || "");
      const isGr = wrap.dataset.threadKind === "group";
      const act = menuItem.dataset.action;
      if (act === "pin") {
        if (setChatThreadPinned(tid, true)) {
          showToast("已置顶");
          closeChatThreadBeadMenu();
          renderChatThreadList();
        }
        return;
      }
      if (act === "unpin") {
        if (setChatThreadPinned(tid, false)) {
          showToast("已取消置顶");
          closeChatThreadBeadMenu();
          renderChatThreadList();
        }
        return;
      }
      if (act === "delete") {
        const msg = isGr
          ? "确定删除该群聊？群内记录将一并删除且无法恢复。"
          : "确定删除该密谈？聊天记录将一并删除且无法恢复。";
        if (!window.confirm(msg)) return;
        if (!deleteChatThreadById(tid)) return;
        closeChatThreadBeadMenu();
        showToast("已删除");
        renderChatThreadList();
        if (getChatScreenEl()?.classList.contains("is-open")) {
          reconcileActiveThreadRef();
          if (!readChatActiveThreadRef().threadId) {
            closeChatScreen();
          } else {
            updateChatChrome();
            renderChatMessages();
          }
        }
        return;
      }
    }
    const bead = e.target.closest(".chat-thread-bead");
    if (bead && li) {
      e.preventDefault();
      e.stopPropagation();
      const menu = wrap.querySelector(".chat-thread-bead-menu");
      const opening = !li.classList.contains("is-bead-open");
      closeChatThreadBeadMenu();
      if (opening && menu) {
        li.classList.add("is-bead-open");
        menu.hidden = false;
        bead.setAttribute("aria-expanded", "true");
        chatThreadBeadOpenLi = li;
      }
      return;
    }
  }
  const card = e.target.closest(".chat-thread-card");
  if (!card?.dataset.threadId) return;
  const maskId = getActiveMaskIdForInbox();
  writeChatActiveThreadRef({ maskId, threadId: String(card.dataset.threadId) });
  const cid = String(card.dataset.charId || "").trim();
  if (cid) activateCharPersonaById(cid);
  openChatScreen();
  syncChatSendButtonForActiveThread();
});

