const chatBubbleActionLabels = {
  delete: "删除",
  copy: "复制",
  quote: "引用",
  recall: "撤回",
  edit: "编辑",
  restore: "重回",
  multiselect: "多选",
  ringtone: "设为铃声",
  "reroll-inline-html": "重 roll 插卡"
};

/** 语音气泡上的 lines 下标（与 voiceLines[]、content.split 对齐），≠ chatBubbleSeg（前有图/表情会 +1）。 */
function readVoicePartIdxFromBubbleEl(bubbleEl) {
  if (!(bubbleEl instanceof Element)) return 0;
  const v = bubbleEl.dataset.voicePartIdx;
  if (v != null && v !== "") {
    const n = Number(v);
    if (Number.isFinite(n) && n >= 0) return Math.floor(n);
  }
  return Math.max(0, Math.floor(Number(bubbleEl.dataset.chatBubbleSeg ?? "0")));
}

function findChatVoiceBubbleInWrap(wrap, voicePartIdx, isUserVoice, bubbleEl) {
  if (bubbleEl instanceof HTMLElement && bubbleEl.classList.contains("chat-msg-bubble--voice")) {
    return bubbleEl;
  }
  if (!(wrap instanceof HTMLElement)) return null;
  if (isUserVoice) return wrap.querySelector(".chat-msg-bubble--voice");
  const partIdx = Math.max(0, Math.floor(Number(voicePartIdx)) || 0);
  return wrap.querySelector(`.chat-msg-bubble--voice[data-voice-part-idx="${partIdx}"]`);
}

function findChatVoicePrimaryRevealAfterBubble(bubble) {
  if (!(bubble instanceof HTMLElement)) return null;
  const el = bubble.nextElementSibling;
  if (
    el instanceof HTMLElement &&
    el.classList.contains("chat-voice-reveal") &&
    !el.classList.contains("chat-voice-reveal--trans")
  ) {
    return el;
  }
  return null;
}

function removeChatVoiceRevealBlockAfterBubble(bubble) {
  const revealEl = findChatVoicePrimaryRevealAfterBubble(bubble);
  if (!(revealEl instanceof HTMLElement)) return;
  let nx = revealEl.nextElementSibling;
  while (
    nx instanceof HTMLElement &&
    nx.classList.contains("chat-voice-reveal") &&
    nx.classList.contains("chat-voice-reveal--trans")
  ) {
    nx.remove();
    nx = revealEl.nextElementSibling;
  }
  revealEl.remove();
}

function purgeChatUserVoiceRevealsInWrap(wrap) {
  if (!(wrap instanceof HTMLElement)) return;
  for (const bubble of wrap.querySelectorAll(".chat-msg-bubble--voice")) {
    if (bubble instanceof HTMLElement) removeChatVoiceRevealBlockAfterBubble(bubble);
  }
}

/** @param {HTMLElement} wrap @param {object} msg */
function refreshChatMsgRowReuseFingerprintEl(wrap, msg) {
  const idx = Number(wrap.dataset.chatMsgIdx);
  if (!Number.isFinite(idx) || idx < 0) return;
  const fp = chatMsgRowReuseFingerprint(idx, msg);
  if (fp) wrap.dataset.chatRowFp = fp;
  else delete wrap.dataset.chatRowFp;
}

function readChatMessagesDistFromBottom() {
  const scrollEl = document.getElementById("chat-messages");
  if (!scrollEl) return null;
  try {
    return Math.max(0, scrollEl.scrollHeight - scrollEl.scrollTop - scrollEl.clientHeight);
  } catch (_) {
    return null;
  }
}

function restoreChatMessagesDistFromBottom(distFromBottom) {
  if (distFromBottom == null || !Number.isFinite(Number(distFromBottom))) return;
  const scrollEl = document.getElementById("chat-messages");
  if (!scrollEl) return;
  const dist = Math.max(0, Number(distFromBottom));
  markChatProgrammaticScroll(360);
  const apply = () => {
    try {
      scrollEl.scrollTop = Math.max(0, scrollEl.scrollHeight - scrollEl.clientHeight - dist);
    } catch (_) {
      /* ignore */
    }
  };
  apply();
  window.requestAnimationFrame(() => {
    apply();
    window.requestAnimationFrame(apply);
  });
}

/**
 * 行 DOM 复用时按 log 校正语音展开态，避免残留 .chat-voice-reveal 未点按就露出文字。
 * @param {HTMLElement} wrap
 * @param {object} msg
 */
function reconcileChatVoiceRevealDomFromMsg(wrap, msg) {
  if (!(wrap instanceof HTMLElement) || !msg || typeof msg !== "object") return;
  const isUserVoice = msg.role === "user" && msg.asVoice;
  const hasAsstVoice =
    msg.role === "assistant" && Array.isArray(msg.voiceLines) && msg.voiceLines.some(Boolean);
  if (!isUserVoice && !hasAsstVoice) return;
  if (isUserVoice) {
    syncChatVoiceRevealDom(wrap, msg, 0, null, { skipScroll: true });
    return;
  }
  msg.voiceLines.forEach((isVoice, si) => {
    if (isVoice) syncChatVoiceRevealDom(wrap, msg, si, null, { skipScroll: true });
  });
}

/** @param {number | null} distFromBottom @param {boolean} skipScroll */
function finishChatVoiceRevealScroll(distFromBottom, skipScroll) {
  if (skipScroll) return;
  chatVoiceRevealScrollGuardUntil = Date.now() + 480;
  const nearBottom = distFromBottom != null && distFromBottom < 96;
  if (nearBottom && isChatScreenThemeGlassActive()) {
    markChatProgrammaticScroll(400);
    const scrollEl = document.getElementById("chat-messages");
    if (scrollEl) {
      window.requestAnimationFrame(() => {
        try {
          scrollEl.scrollTop = Math.max(0, scrollEl.scrollHeight - scrollEl.clientHeight);
        } catch (_) {
          /* ignore */
        }
      });
    }
    return;
  }
  restoreChatMessagesDistFromBottom(distFromBottom);
}

/**
 * 语音「点按转文字」：只改当前行 DOM，避免整表 render 导致表情包/图片闪动。
 * @param {HTMLElement} wrap
 * @param {object} msg
 * @param {number} voicePartIdx
 * @param {Element | null} bubbleEl
 * @param {{ skipScroll?: boolean } | undefined} [opts]
 */
function syncChatVoiceRevealDom(wrap, msg, voicePartIdx, bubbleEl, opts) {
  if (!(wrap instanceof HTMLElement) || !msg || typeof msg !== "object") return;
  if (!wrap.querySelector(".chat-msg-bubble-stack")) return;
  const skipScroll = Boolean(opts && opts.skipScroll);
  const distFromBottom = skipScroll ? null : readChatMessagesDistFromBottom();
  if (!skipScroll) chatVoiceRevealScrollGuardUntil = Date.now() + 480;
  const isUserVoice = msg.role === "user" && msg.asVoice;
  const partIdx = Math.max(0, Math.floor(Number(voicePartIdx)) || 0);
  const bubble = findChatVoiceBubbleInWrap(wrap, partIdx, isUserVoice, bubbleEl);
  if (isUserVoice) {
    const revealed = Boolean(msg.voiceRevealed);
    wrap.classList.toggle("chat-msg--voice-revealed", revealed);
    const rawFull = String(msg.content || "");
    const s = Number(msg.voiceSeconds);
    const sec = Number.isFinite(s) && s > 0 ? Math.round(s) : estimateVoiceSeconds(rawFull);
    if (bubble instanceof HTMLElement) {
      bubble.setAttribute(
        "aria-label",
        revealed ? `语音 ${sec} 秒（已展开文字）` : `语音 ${sec} 秒（点按转文字）`
      );
    }
    if (revealed) {
      let tx = findChatVoicePrimaryRevealAfterBubble(bubble);
      if (!(tx instanceof HTMLElement) && bubble instanceof HTMLElement) {
        tx = document.createElement("div");
        tx.className = "chat-voice-reveal";
        bubble.insertAdjacentElement("afterend", tx);
      }
      if (tx instanceof HTMLElement) {
        tx.textContent = stripVoiceMetaPrefixLinesForDisplay(rawFull) || "（空）";
      }
    } else if (bubble instanceof HTMLElement) {
      removeChatVoiceRevealBlockAfterBubble(bubble);
    } else {
      purgeChatUserVoiceRevealsInWrap(wrap);
    }
    refreshChatMsgRowReuseFingerprintEl(wrap, msg);
    finishChatVoiceRevealScroll(distFromBottom, skipScroll);
    return;
  }
  if (!(bubble instanceof HTMLElement)) return;
  const revealed = Array.isArray(msg.voiceRevealSegs) && Boolean(msg.voiceRevealSegs[partIdx]);
  const lineSeg = String(
    getChatMessageSegmentPlain(String(msg.content || ""), partIdx, "assistant", msg, readChatLog()) || ""
  ).trim();
  const s = Number(Array.isArray(msg.voiceSeconds) ? msg.voiceSeconds[partIdx] : NaN);
  const sec = Number.isFinite(s) && s > 0 ? Math.round(s) : estimateVoiceSeconds(lineSeg);
  bubble.setAttribute(
    "aria-label",
    revealed ? `语音 ${sec} 秒（已展开文字）` : `语音 ${sec} 秒（点按转文字）`
  );
  if (revealed) {
    const text = stripVoiceMetaPrefixLinesForDisplay(lineSeg) || "（空）";
    let revealEl = findChatVoicePrimaryRevealAfterBubble(bubble);
    if (revealEl instanceof HTMLElement) {
      revealEl.textContent = text;
    } else {
      revealEl = document.createElement("div");
      revealEl.className = "chat-voice-reveal";
      revealEl.textContent = text;
      bubble.insertAdjacentElement("afterend", revealEl);
    }
  } else {
    removeChatVoiceRevealBlockAfterBubble(bubble);
  }
  refreshChatMsgRowReuseFingerprintEl(wrap, msg);
  finishChatVoiceRevealScroll(distFromBottom, skipScroll);
}

/** 本条在图片/表情卡之后是否还应渲染语音气泡。 */
function chatMessageHasVoiceBubbleAfterAttachments(m, role, isVoice) {
  if (isVoice) return true;
  return (
    role === "assistant" &&
    m &&
    typeof m === "object" &&
    Array.isArray(m.voiceLines) &&
    m.voiceLines.some(Boolean)
  );
}

