chatMessagesEl?.addEventListener("pointerdown", onChatMessagesPointerDown);
chatMessagesEl?.addEventListener(
  "click",
  (e) => {
    if (!(e.target instanceof Element)) return;
    if (chatMsgMultiSelectMode) {
      const host = e.target.closest(".chat-msg-multi-host");
      if (host instanceof HTMLElement) {
        e.preventDefault();
        e.stopPropagation();
        toggleChatMsgMultiSelectHost(host, e.clientY);
        return;
      }
    }
    const b = e.target instanceof Element ? e.target.closest(".chat-msg-bubble--voice") : null;
  if (!b) return;
  e.preventDefault();
  e.stopPropagation();
  if (getActiveChatDmSurfaceForContext() === "offline") return;
  const wrap = b.closest(".chat-msg");
  if (!wrap || wrap.dataset.chatMsgIdx == null) return;
  const msgIdx = Number(wrap.dataset.chatMsgIdx);
  if (!Number.isFinite(msgIdx)) return;
  const voicePartIdx = readVoicePartIdxFromBubbleEl(b);
  const log = readChatLog();
  if (msgIdx < 0 || msgIdx >= log.length) return;
  const msg = log[msgIdx];
  if (!(msg && typeof msg === "object")) return;
  const isUserVoice = msg.role === "user" && msg.asVoice;
  const isAsstVoice =
    msg.role === "assistant" &&
    Array.isArray(msg.voiceLines) &&
    msg.voiceLines.some(Boolean) &&
    Boolean(msg.voiceLines[voicePartIdx]);
  if (!isUserVoice && !isAsstVoice) return;

  // MiniMax：仅角色语音泡合成播放；用户自己的语音泡仍「点按转文字」，不用角色声线念用户台词。
  try {
    const cfg = readMinimaxTtsConfig();
    if (isMinimaxTtsActuallyEnabled(cfg) && isAsstVoice) {
      const alreadyRevealed =
        Array.isArray(msg.voiceRevealSegs) && Boolean(msg.voiceRevealSegs[voicePartIdx]);
      if (!alreadyRevealed) {
        revealChatVoiceBubbleForMinimaxPlayback(log, msgIdx, voicePartIdx, false, true);
      }
      void playChatAssistantVoiceMinimax(msg, voicePartIdx, { skipPrime: alreadyRevealed });
      return;
    }
  } catch (_) {
    /* ignore and fall through */
  }

  if (isUserVoice) {
    msg.voiceRevealed = !msg.voiceRevealed;
  } else {
    const arr = Array.isArray(msg.voiceRevealSegs) ? msg.voiceRevealSegs.slice() : [];
    while (arr.length <= voicePartIdx) arr.push(false);
    arr[voicePartIdx] = !arr[voicePartIdx];
    msg.voiceRevealSegs = arr;
  }
  saveChatLog(log);
  syncChatVoiceRevealDom(wrap, msg, voicePartIdx, b, { skipScroll: true });
  },
  true
);

