chatMessagesEl?.addEventListener("click", (e) => {
  if (!(e.target instanceof Element)) return;
  if (chatMsgMultiSelectMode) return;
  if (isChatBubbleActionSheetOpen() || isRedpackPeekOpen()) return;
  const card = e.target.closest(".chat-msg-card--redpack");
  if (!card) return;
  e.preventDefault();
  e.stopPropagation();
  const wrap = card.closest(".chat-msg");
  if (!wrap || wrap.dataset.chatMsgIdx == null) return;
  const msgIdx = Number(wrap.dataset.chatMsgIdx);
  if (!Number.isFinite(msgIdx)) return;
  const log = readChatLog();
  if (msgIdx < 0 || msgIdx >= log.length) return;
  const msg = log[msgIdx];
  if (!(msg && typeof msg === "object")) return;
  if (window.XXJ_GroupRedpack?.handleCardClick?.(msgIdx, msg)) return;
  // 已处理：变灰禁点（单聊）
  if (card.classList.contains("is-processed")) return;
  const rp0 = msg.redpack && typeof msg.redpack === "object" ? msg.redpack : null;
  const rawParts0 = String(msg.content ?? "")
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean);
  const rawParts = expandPartsAndTranslationsForInlineRedpack(rawParts0, []).parts;
  const contentSegRaw = card.dataset.chatContentSeg;
  const rpSegFallback = Math.max(0, findRedpackPartIndex(rawParts));
  const contentSegIdx =
    contentSegRaw != null && contentSegRaw !== "" && Number.isFinite(Number(contentSegRaw))
      ? Math.max(0, Math.floor(Number(contentSegRaw)))
      : rpSegFallback;
  const rpIdxHit = findRedpackPartIndex(rawParts);
  const segText = String(
    rawParts[contentSegIdx] ?? (rpIdxHit >= 0 ? rawParts[rpIdxHit] : "") ?? rawParts[0] ?? msg.content ?? ""
  ).trim();
  const transChunks = padTranslationSegments(msg.translation, rawParts.length || 1);
  const segTrans = String(transChunks[contentSegIdx] ?? "").trim();
  const rpParsed = resolveRedpackFromChatSegment(segText, segTrans, Boolean(segTrans));
  if (!rp0 && !rpParsed) return;
  const rp = {
    ...(rp0 && typeof rp0 === "object" ? rp0 : {}),
    ...(rpParsed && typeof rpParsed === "object" ? rpParsed : {}),
    amt: String(rp0?.amt || rpParsed?.amt || "").trim(),
    note: String(rp0?.note || rpParsed?.note || "").trim() || "恭喜发财",
    status: String(rp0?.status || "sent")
  };
  const st = String(rp.status || "sent");
  if (st !== "sent") return;

  // 祝福语翻译：如果该条消息有 translation，则取同段译文并显示在括号里
  let noteTrans = "";
  try {
    if (segTrans && !isTranslationSegmentSkipped(segTrans)) {
      const rpTrans = resolveRedpackFromChatSegment("", segTrans, true);
      noteTrans = String(rpTrans?.note ?? segTrans).trim();
    }
  } catch (_) {
    noteTrans = "";
  }
  if (noteTrans && noteTrans === String(rp.note || "").trim()) noteTrans = "";

  const root = document.getElementById("redpack-peek-sheet");
  if (root) {
    root.dataset.msgIdx = String(msgIdx);
    root.dataset.segIdx = String(contentSegIdx);
  }
  openRedpackPeek({
    amt: String(rp.amt || ""),
    note: String(rp.note || ""),
    noteTrans,
    mode: msg.role === "assistant" ? "char-sent" : "view"
  });
});
