document.getElementById("chat-bubble-actions-backdrop")?.addEventListener("click", () => {
  closeChatBubbleActionSheet();
});
document.getElementById("chat-bubble-actions-cancel")?.addEventListener("click", () => {
  closeChatBubbleActionSheet();
});
document.getElementById("chat-bubble-actions")?.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-chat-bubble-action]");
  if (!btn) return;
  const sheetRoot = document.getElementById("chat-bubble-actions");
  const action = String(btn.getAttribute("data-chat-bubble-action") || "");
  const msgIdx = Number(sheetRoot?.dataset.msgIdx);
  const segIdx = Number(sheetRoot?.dataset.bubbleSegIdx ?? "0");
  const log = readChatLog();
  if (!Number.isFinite(msgIdx) || msgIdx < 0 || msgIdx >= log.length) {
    showToast("消息已变化，请重试");
    closeChatBubbleActionSheet();
    return;
  }
  const msg = log[msgIdx];
  const qsRaw = sheetRoot?.dataset.quoteBubbleSeg;
  const bsRaw = sheetRoot?.dataset.bodyBubbleSeg;
  const sheetQuoteDomSeg =
    qsRaw != null && qsRaw !== "" && Number.isFinite(Number(qsRaw)) ? Number(qsRaw) : null;
  const sheetBodyDomSeg =
    bsRaw != null && bsRaw !== "" && Number.isFinite(Number(bsRaw)) ? Number(bsRaw) : null;
  const segmentPlain = getChatMessageSegmentPlain(
    String(msg.content ?? ""),
    segIdx,
    msg.role,
    msg,
    log,
    sheetQuoteDomSeg,
    sheetBodyDomSeg
  );

  const run = async () => {
    if (action === "ringtone") {
      if (!isChatRingtoneSurfaceActive()) {
        closeChatBubbleActionSheet();
        return;
      }
      const anchorBubble = chatBubbleActionAnchorEl;
      const voiceFromSheet = Number(sheetRoot?.dataset.voicePartIdx);
      const voicePartIdx = Number.isFinite(voiceFromSheet)
        ? Math.max(0, Math.floor(voiceFromSheet))
        : readVoicePartIdxFromBubbleEl(
            resolveVoiceBubbleElFromLongPressTarget(anchorBubble) || anchorBubble
          );
      closeChatBubbleActionSheet();
      showToast("正在准备语音…");
      const audioUrl = await resolveChatVoiceBubbleMinimaxAudioUrl(msg, voicePartIdx);
      if (!audioUrl) {
        showToast("无法获取语音（请确认 MiniMax 已配置）");
        return;
      }
      const th = readActiveThread();
      let charId = String(th?.charId || "").trim();
      let charName = getChatCharPersonaDisplayName();
      if (th?.kind === "group" && window.XXJ_GroupChat?.resolveVoiceCharId) {
        const sid = window.XXJ_GroupChat.resolveVoiceCharId(msg, th);
        if (sid) {
          charId = sid;
          charName = charDisplayNameById(sid) || charName;
        }
      }
      if (typeof window.VoiceRingtonePicker?.open === "function") {
        window.VoiceRingtonePicker.open({
          audioUrl,
          personaId: charId,
          personaName: charName
        });
      } else {
        showToast("铃声模块未加载");
      }
      return;
    }
    if (action === "copy") {
      await copyTextToClipboard(segmentPlain);
      closeChatBubbleActionSheet();
      return;
    }
    if (action === "quote") {
      const anchorWrap = chatBubbleActionAnchorEl?.closest?.(".chat-msg");
      if (
        !(anchorWrap instanceof HTMLElement) ||
        !quoteChatBubbleFromDom(
          anchorWrap,
          chatBubbleActionAnchorEl || anchorWrap,
          chatBubbleActionAnchorEl
        )
      ) {
        insertStructuredQuoteFromBubble(log, msgIdx, segIdx, sheetQuoteDomSeg, sheetBodyDomSeg);
        showToast("已插入引用");
      }
      closeChatBubbleActionSheet();
      return;
    }
    if (action === "recall") {
      if (msg.role === "user") {
        const r = spliceRecallUserBlock(msgIdx);
        if (!r.ok) {
          showToast("无法撤回");
          closeChatBubbleActionSheet();
          return;
        }
        refreshChatAfterLogMutation();
        showToast("已撤回");
        closeChatBubbleActionSheet();
        return;
      }
      showToast("无法撤回");
      closeChatBubbleActionSheet();
      return;
    }
    if (action === "edit") {
      if (msg.role === "user" || msg.role === "assistant") {
        if (!isChatNarrationSheetSeg(segIdx) && getActiveChatDmSurfaceForContext() === "offline") {
          performChatBubbleEditLoadComposerWholeRowOffline(msgIdx);
        } else {
          performChatBubbleEditLoadComposer(
            msgIdx,
            segIdx,
            sheetQuoteDomSeg,
            sheetBodyDomSeg
          );
        }
        closeChatBubbleActionSheet();
        return;
      }
      showToast("只能编辑双方文字气泡");
      closeChatBubbleActionSheet();
      return;
    }
    if (action === "reroll-inline-html") {
      if (msg.role !== "assistant") {
        showToast("只能对对方消息重 roll 插卡");
        closeChatBubbleActionSheet();
        return;
      }
      closeChatBubbleActionSheet();
      await rerollAssistantInlineHtmlCards(msgIdx);
      return;
    }
    if (action === "restore") {
      // “重回”：仅重生成这一条对方气泡（保留其后的聊天记录）。
      if (msg.role !== "assistant") {
        showToast("只能对对方回复使用重回");
        closeChatBubbleActionSheet();
        return;
      }
      const ai = window.RP_AI;
      if (!ai) {
        showToast("AI 模块未加载");
        closeChatBubbleActionSheet();
        return;
      }
      const cut = Number(msgIdx);
      const sheetSeg = Math.max(0, Math.floor(Number(segIdx)) || 0);
      const restoringImageDomSeg = isChatBubbleActionSheetImageDomSeg(msg, sheetSeg, null);
      const bubbleSegsN = countChatBubbleActionSheetSegments(String(msg?.content ?? ""), "assistant", msg);
      const usePartialRestore = bubbleSegsN > 1 && !restoringImageDomSeg;
      const origSegCount = usePartialRestore
        ? 1
        : Math.max(
            1,
            String(msg?.content ?? "")
              .split(/\|\|\|/)
              .map((s) => String(s).trim())
              .filter(Boolean).length || 1
          );
      const restorePin = await beginChatSendPinAsync();
      if (!restorePin) {
        showChatThreadUnavailableToast();
        closeChatBubbleActionSheet();
        return;
      }
      if (isChatAssistRoundInflightForThread(restorePin.maskId, restorePin.threadId)) {
        showToast("对方正在回复…");
        closeChatBubbleActionSheet();
        return;
      }
      const restoreBound = chatRoundBoundFromPin(restorePin);
      const logPinned = readChatLogForSendPin(restorePin);
      if (cut < 0 || cut >= logPinned.length) {
        showToast("消息已变化，请重试");
        closeChatBubbleActionSheet();
        return;
      }
      const prefix = logPinned.slice(0, Math.max(0, cut));
      const th0 = restorePin.thread;
      const rollSurface = getActiveChatDmSurfaceForContext();
      const maxTokPrimaryRestore = null;
      const apiLog = sliceChatLogForApiMemoryWindowAnchoredToLastUser(prefix, rollSurface, th0);
      closeChatBubbleActionSheet();
      const reasonDlg = await openChatRerollReasonDialog({
        mode: "restore",
        partialSeg: usePartialRestore ? sheetSeg : undefined
      });
      if (!reasonDlg.confirmed) {
        return;
      }
      const reasonApi = buildChatRerollReasonEmptySendContent(reasonDlg, {
        mode: "restore",
        partialSeg: usePartialRestore ? sheetSeg : undefined
      });
      const restoreApiOpts = {
        ...restoreBound,
        ...(reasonApi ? { emptySendUserContent: reasonApi } : {})
      };
      const apiMessages = await buildChatApiMessagesFromLogAsync(
        true,
        apiLog,
        restoreApiOpts,
        rollSurface
      );
      showToast("正在重回此条…");
      // 视觉反馈：将该条替换为“正在输入/重回中”的占位气泡，避免用户以为没触发
      const restoreBackup = msg && typeof msg === "object" ? { ...msg } : null;
      try {
        preserveChatMessagesScrollForNextRender();
        const liveLog = readChatLogForSendPin(restorePin);
        if (cut >= 0 && cut < liveLog.length) {
          const live = liveLog[cut];
          if (live && typeof live === "object" && live.role === "assistant") {
            if (usePartialRestore) {
              live.restoring = true;
              live.restoringSegIdx = sheetSeg;
            } else {
              markAssistantMessageRestoring(live);
            }
          }
          saveChatLogForSendPin(restorePin, liveLog);
          scheduleChatUiRefreshForRound(restorePin.maskId, restorePin.threadId, { flush: true });
        }
      } catch (_) {
        /* ignore */
      }
      try {
        await runChatAssistRoundWithSendUi(restoreBound, async (signal) => {
        const data = await requestChatAssistantCompletion(ai, {
          messages: apiMessages,
          ...spreadOptionalMaxTokens(maxTokPrimaryRestore),
          response_format: { type: "json_object" },
          signal
        });
        rememberChatApiUsage(data?.usage);
        updateChatContextTokenLabel();
        let rawReply = readChatCompletionSalvagedText(data);
        if (!rawReply) throw new Error(explainModelEmptyReply(data, rawReply));
        const charLockStripRestore = stripCharLockPlainProtocolBlocksFromText(rawReply);
        const firstParsed = parseAssistantPayloadForDmSurface(
          charLockStripRestore.text,
          rollSurface,
          rawReply
        );
        const charLockSpecRestore = mergeCharLockAssistantSpecs(
          charLockStripRestore.spec,
          extractCharLockAssistantSpecFromBalancedJson(rawReply)
        );
        let { reply: parsedReply, recalls, lineTranslationsJoined, voiceLines, voiceSeconds } = firstParsed;
        const offlineMeetupRawRestore = extractAssistantOfflineMeetupFromRaw(rawReply);
        const th1 = resolveChatPromptThread(restoreBound);
        const transOn = isThreadCharTranslationEnabled(th1);
        let reply = coalesceAssistantDisplayReply(parsedReply, rawReply, rollSurface);
        if (!String(reply || "").trim() && String(rawReply || "").trim()) {
          const lineRepair = await tryRepairAssistantLinesOnly(
            ai,
            rawReply,
            maxTokPrimaryRestore,
            rollSurface,
            signal
          );
          if (lineRepair) {
            rawReply = lineRepair.repRaw;
            mergeAssistantParsedPreservingHeartPanel(firstParsed, lineRepair.parsed);
            parsedReply = lineRepair.parsed.reply;
            reply = coalesceAssistantDisplayReply(parsedReply, rawReply, rollSurface);
            recalls = firstParsed.recalls;
            lineTranslationsJoined = firstParsed.lineTranslationsJoined;
            voiceLines = firstParsed.voiceLines;
            voiceSeconds = firstParsed.voiceSeconds;
            showToast("正文已补全");
          }
        }
        if (
          rollSurface === "offline" &&
          String(reply || "").trim() &&
          th1 &&
          !offlineAssistantLinesMeetsLengthSpec(reply, th1)
        ) {
          showToast("当面篇幅未达标，正在补写…");
          const refined = await refineOfflineAssistantReplyIfTooShort(
            ai,
            apiMessages,
            rawReply,
            firstParsed,
            reply,
            th1,
            signal
          );
          rawReply = refined.rawReply;
          mergeAssistantParsedPreservingHeartPanel(firstParsed, refined.firstParsed);
          reply = refined.reply;
        }
        let transJoined = String(lineTranslationsJoined || "").trim();
        if (transOn && rollSurface !== "offline" && assistantLineTranslationsIncomplete(reply, transJoined)) {
          try {
            const repairMsgs = buildChatTranslationRepairMessages(
              rawReply,
              th1,
              rollSurface === "offline" ? "offline" : "im"
            );
            const repaired = await ai.chatCompletions(
              {
                messages: repairMsgs,
                ...spreadOptionalMaxTokens(maxTokPrimaryRestore),
                response_format: { type: "json_object" }
              },
              { signal }
            );
            rememberChatApiUsage(repaired?.usage);
            const repRaw = readChatCompletionChoiceText(repaired);
            if (repRaw) {
              const repSt = stripCharLockPlainProtocolBlocksFromText(repRaw);
              const rp2 = parseAssistantPayloadForDmSurface(repSt.text, rollSurface, repRaw);
              const { reply: rReply, lineTranslationsJoined: rTrans } = rp2;
              if (String(rReply || "").trim()) reply = rReply;
              transJoined = applyAssistantTranslationRepairResult(
                transJoined,
                rTrans,
                reply,
                rollSurface === "offline"
              );
              const c2 = String(rp2.charImageCaption || "").trim();
              if (c2) Object.assign(firstParsed, { charImageCaption: c2 });
              const u2 = sanitizeStickerUrl(String(rp2.charImageUrl || "").trim());
              if (u2) Object.assign(firstParsed, { charImageUrl: u2 });
              const pc2 = normalizeAssistantPlaceCallValue(rp2.placeCall);
              if (pc2) Object.assign(firstParsed, { placeCall: pc2 });
              const nar2 = normalizeAssistantNarrationText(String(rp2.narration || "").trim());
              if (rollSurface !== "offline" && nar2) Object.assign(firstParsed, { narration: nar2 });
              mergeStickerIntentFromAssistantRawText(firstParsed, repRaw);
            }
          } catch (_) {
            /* ignore */
          }
        }
        if (
          transOn &&
          rollSurface !== "offline" &&
          assistantLineTranslationsIncomplete(reply, transJoined) &&
          String(reply || "").trim()
        ) {
          try {
            const onlyMsgs = buildChatTranslationOnlyMessages(
              reply,
              th1,
              rollSurface === "offline" ? "offline" : "im"
            );
            const only = await ai.chatCompletions(
              {
                messages: onlyMsgs,
                ...spreadOptionalMaxTokens(maxTokPrimaryRestore),
                response_format: { type: "json_object" }
              },
              { signal }
            );
            rememberChatApiUsage(only?.usage);
            const onlyRaw = readChatCompletionChoiceText(only);
            if (onlyRaw) {
              const onlySt = stripCharLockPlainProtocolBlocksFromText(onlyRaw);
              const { lineTranslationsJoined: tOnly } = parseAssistantPayloadForDmSurface(
                onlySt.text,
                rollSurface,
                onlyRaw
              );
              transJoined = applyAssistantTranslationRepairResult(
                transJoined,
                tOnly,
                reply,
                rollSurface === "offline"
              );
            }
          } catch (_) {
            /* ignore */
          }
        }
        if (transOn && rollSurface === "offline" && offlineAssistantTranslationRepairNeeded(reply, transJoined)) {
          transJoined = await tryRepairOfflineMissingTailTranslations(
            ai,
            reply,
            transJoined,
            th1,
            maxTokPrimaryRestore
          );
        }
        if (transOn) {
          const s1 = stripParallelRecallMatching(reply, transJoined, recalls);
          reply = s1.reply;
          transJoined = s1.trans;
          const s2 = stripParallelRecallNarration(reply, transJoined, recalls);
          reply = s2.reply;
          transJoined = s2.trans;
        } else {
          reply = stripAssistantLinesMatchingRecalls(reply, recalls);
          reply = stripAssistantRecallUiNarrationLines(reply, recalls);
          transJoined = "";
        }
        reply = stripAssistantVoiceMetaPrefixes(reply);
        {
          const c0 = collapseEmptyParallelAssistantSegments(reply, transOn ? transJoined : "");
          reply = c0.main;
          if (transOn) transJoined = c0.trans;
        }

        mergeStickerIntentFromAssistantRawText(firstParsed, rawReply);
        const replyBeforeStickerRestore = reply;
        let stickerPickedRestore = null;
        /** @type {{ keptJoined: string, picked: { url: string, description: string } | null }} */
        let stickerPickRestore = { keptJoined: reply, picked: null };
        if (rollSurface !== "offline") {
          stickerPickRestore = extractAssistantStickerPick(reply, firstParsed, th1, {
            rawAssistantReply: rawReply
          });
          reply = stickerPickRestore.keptJoined;
          stickerPickedRestore = stickerPickRestore.picked;
        }
        if (transOn) {
          transJoined = hygieneAssistantTranslationAfterStickerStrip(
            replyBeforeStickerRestore,
            reply,
            transJoined
          );
        }
        {
          const imH = applyImNarratorModeLineHygiene(firstParsed, reply, transJoined, rollSurface, th1);
          reply = imH.reply;
          transJoined = imH.transJoined;
        }

        // “重回”仅替换这一条消息：为了避免看起来像“重回了一轮”，把本次生成的分段数限制为原消息的分段数。
        const capJoined = (joined, n) =>
          String(joined || "")
            .split(/\|\|\|/)
            .map((s) => String(s).trim())
            .filter(Boolean)
            .slice(0, Math.max(1, n))
            .join("|||");
        reply = capJoined(reply, origSegCount);
        if (transOn && translationJoinedHasAnyVisible(transJoined)) {
          transJoined = capJoined(transJoined, origSegCount);
        } else {
          transJoined = "";
        }
        if (transOn && rollSurface === "offline") {
          const offCap = finalizeOfflineAssistantReplyForStorage(reply, transJoined, true);
          reply = offCap.reply;
          transJoined = offCap.transJoined;
        }
        const capArr = (arr, n, fill) => {
          const a = Array.isArray(arr) ? arr.slice() : [];
          while (a.length < n) a.push(fill);
          return a.slice(0, n);
        };
        const voiceLinesCapped = capArr(voiceLines, origSegCount, false).map((x) => Boolean(x));
        const voiceSecondsCapped = capArr(voiceSeconds, origSegCount, NaN).map((x) => Number(x));

        const hvRaw = String(firstParsed.heartVoice || "").trim();
        const heartOn = isThreadHeartVoiceEnabled(th1);
        const hv = heartOn && hvRaw ? hvRaw.slice(0, 80_000) : "";
        const charImgCap = String(firstParsed.charImageCaption || "").trim();
        let charImgUrl = sanitizeStickerUrl(String(firstParsed.charImageUrl || "").trim());
        const imgCfgRestore = readImageGenConfig();
        const imgPlanRestore = planAssistantSessionImageAttachment({
          charImageCaption: charImgCap,
          charImgUrl,
          heartVoiceText: hv,
          hvStateText: String(firstParsed.hvState || "").trim(),
          narrationText: String(firstParsed.narration || "").trim(),
          everyRound: isThreadChatEveryRoundSessionImage(th1),
          imgCfg: imgCfgRestore,
          thread: th1
        });
        const placeCall = resolveAssistantPlaceCall(firstParsed, reply, rawReply);
        const narStored = narrationStoredForDmSurface(
          narrationTextForStorageFromParsed(firstParsed),
          rollSurface
        );
        const offlineMeetupWillTriggerRestore =
          !usePartialRestore &&
          rollSurface !== "offline" &&
          assistantOfflineMeetupWouldTrigger(offlineMeetupRawRestore);
        if (
          !String(reply || "").trim() &&
          !recalls.length &&
          !hv &&
          !charImgCap &&
          !charImgUrl &&
          !isAssistantPlaceCallActive(placeCall) &&
          !stickerPickedRestore &&
          !narStored &&
          !charLockAssistantSpecHasEffect(charLockSpecRestore) &&
          !offlineMeetupWillTriggerRestore &&
          !charBlockUserIntentWouldApply(firstParsed, th1, rollSurface)
        ) {
          throw new Error(explainModelEmptyReply(data, rawReply));
        }
        const at = Number.isFinite(Number(msg.at)) ? Number(msg.at) : Date.now();
        const next = readChatLogForSendPin(restorePin);
        if (cut >= 0 && cut < next.length) {
          next.splice(cut, 1);
        }
        const insertAt = Math.min(Math.max(0, cut), next.length);
        /** @type {object | null} */
        let restoredEntry = null;
        if (usePartialRestore && restoreBackup) {
          const base = { ...restoreBackup };
          const newSegText =
            String(reply || "")
              .split(/\|\|\|/)
              .map((s) => String(s).trim())
              .filter(Boolean)[0] ||
            (charLockAssistantSpecHasEffect(charLockSpecRestore) ? "\u00A0" : "…");
          const mergedContent = applyChatBubbleActionSheetSegmentToContent(
            String(base.content ?? ""),
            "assistant",
            sheetSeg,
            newSegText,
            base
          );
          const entry = { ...base, content: mergedContent, at };
          delete entry.restoring;
          delete entry.restoringSegIdx;
          const ch0 = String(entry.content ?? "")
            .split(/\|\|\|/)
            .map((s) => String(s).trim())
            .filter(Boolean);
          const chunkArr0 = ch0.length ? ch0 : [String(entry.content ?? "").trim() || " "];
          const { quoteRef: qrf0 } = resolveComposerQuotedDisplayPartsForSurface(chunkArr0, "assistant", entry);
          if (transOn && translationJoinedHasAnyVisible(transJoined)) {
            const newT0 = String(transJoined)
              .split(/\|\|\|/)
              .map((s) => String(s).trim())[0];
            if (qrf0 && sheetSeg === 1) delete entry.translation;
            else patchAssistantTranslationOneSegment(entry, sheetSeg, newT0 ?? "");
          } else if (transOn) {
            if (qrf0 && sheetSeg === 1) delete entry.translation;
            else patchAssistantTranslationOneSegment(entry, sheetSeg, "");
          }
          if (hv) entry.heartVoice = hv;
          applyHvPanelFieldsToAssistantEntry(
            entry,
            firstParsed,
            heartOn && firstParsed.fromJson,
            readLastAssistantHvAffinityFromLog(prefix)
          );
          applyTheaterSnapsToAssistantEntry(entry, firstParsed, th1);
          applyInlineHtmlCardsToAssistantEntry(entry, firstParsed);
          if (rollSurface !== "offline") tagChatMessageBlockBadgeIfNeeded(entry, th1, "assistant");
          if (!firstParsed.speakAs) {
            const speakAsRaw = parseAssistantSpeakAsFromRaw(rawReply);
            if (speakAsRaw) firstParsed.speakAs = speakAsRaw;
          }
          const speakRoundPart = applyAssistantSpeakAsRound(
            firstParsed,
            entry,
            restorePin.maskId,
            restorePin.threadId
          );
          const entryInsertAt = resolveAssistantEntryInsertAt(
            next,
            insertAt,
            speakRoundPart.foldBoundarySlot || ""
          );
          if (rollSurface === "offline") {
            tryAttachOfflineAutoSessionImageOnEntry(
              entry,
              String(entry.content || ""),
              firstParsed,
              rawReply,
              th1
            );
          } else if (rollSurface !== "offline") {
            if (Array.isArray(base.voiceLines) && base.voiceLines.length > sheetSeg) {
              const vl2 = base.voiceLines.slice();
              const vs2 = Array.isArray(base.voiceSeconds) ? base.voiceSeconds.slice() : [];
              while (vs2.length < vl2.length) vs2.push(NaN);
              vl2[sheetSeg] = Boolean(voiceLinesCapped[0]);
              const vs0 = Number(voiceSecondsCapped[0]);
              vs2[sheetSeg] = Number.isFinite(vs0) ? vs0 : NaN;
              if (!vl2.some(Boolean)) {
                delete entry.voiceLines;
                delete entry.voiceSeconds;
                delete entry.voiceRevealSegs;
              } else {
                entry.voiceLines = vl2;
                if (vs2.some((x) => Number.isFinite(Number(x)))) entry.voiceSeconds = vs2;
                else delete entry.voiceSeconds;
              }
            } else if (Boolean(voiceLinesCapped[0]) && Number.isFinite(Number(voiceSecondsCapped[0]))) {
              entry.voiceLines = [Boolean(voiceLinesCapped[0])];
              entry.voiceSeconds = [Number(voiceSecondsCapped[0])];
            }
          }
          promoteAssistantComposerQuoteToStructuredStorage(entry, next);
          tagAssistantEntryDmSurface(entry, rollSurface);
          next.splice(entryInsertAt, 0, entry);
          restoredEntry = entry;
          applyAssistantStickerLayoutToLogEntry(
            next,
            stickerPickRestore,
            entry,
            rollSurface,
            false
          );
        } else if (
            String(reply || "").trim() ||
            hv ||
            charImgCap ||
            charImgUrl ||
            stickerPickedRestore ||
            narStored ||
            charLockAssistantSpecHasEffect(charLockSpecRestore) ||
            offlineMeetupWillTriggerRestore
        ) {
          const entry = {
            role: "assistant",
            content: String(reply || "").trim()
              ? String(reply || "")
              : charLockAssistantSpecHasEffect(charLockSpecRestore) || offlineMeetupWillTriggerRestore
                ? "\u00A0"
                : "",
            at
          };
          if (!firstParsed.speakAs) {
            const speakAsRaw = parseAssistantSpeakAsFromRaw(rawReply);
            if (speakAsRaw) firstParsed.speakAs = speakAsRaw;
          }
          const speakRoundFull = applyAssistantSpeakAsRound(
            firstParsed,
            entry,
            restorePin.maskId,
            restorePin.threadId
          );
          const entryInsertAt = resolveAssistantEntryInsertAt(
            next,
            insertAt,
            speakRoundFull.foldBoundarySlot || ""
          );
          delete entry.restoring;
          delete entry.restoringSegIdx;
          if (narStored) entry.narration = narStored;
          if (imgPlanRestore.imgDesc || charImgUrl) {
            if (rollSurface !== "offline") {
              entry.image = {};
              if (imgPlanRestore.imgDesc) {
                const sc = String(imgPlanRestore.imgDesc).trim().slice(0, 3500);
                entry.image.scenePrompt = sc;
                entry.image.desc = sc.slice(0, 4000);
              }
              if (charImgUrl) entry.image.url = charImgUrl;
              if (imgPlanRestore.deferSessionImg) entry.image.imageGenPending = true;
              applySessionImageSubjectOnRow(
                entry,
                th1,
                String(imgPlanRestore.imgDesc || ""),
                next,
                firstParsed.charImageSubject
              );
            }
          }
          if (hv) entry.heartVoice = hv;
          if (transOn && translationJoinedHasAnyVisible(transJoined)) {
            entry.translation = transJoined.slice(0, 500_000);
            finalizeAssistantEntryTranslation(entry);
          }
          if (rollSurface !== "offline") {
            if (Array.isArray(voiceLinesCapped) && voiceLinesCapped.some(Boolean)) entry.voiceLines = voiceLinesCapped;
            if (Array.isArray(voiceSecondsCapped) && voiceSecondsCapped.some((x) => Number.isFinite(Number(x)))) {
              entry.voiceSeconds = voiceSecondsCapped;
            }
          }
          applyHvPanelFieldsToAssistantEntry(
            entry,
            firstParsed,
            heartOn && firstParsed.fromJson,
            readLastAssistantHvAffinityFromLog(prefix)
          );
          applyTheaterSnapsToAssistantEntry(entry, firstParsed, th1);
          applyInlineHtmlCardsToAssistantEntry(entry, firstParsed);
          if (rollSurface !== "offline") tagChatMessageBlockBadgeIfNeeded(entry, th1, "assistant");
          if (rollSurface === "offline") {
            tryAttachOfflineAutoSessionImageOnEntry(
              entry,
              String(entry.content || ""),
              firstParsed,
              rawReply,
              th1
            );
          }
          if (
            String(reply || "").trim() ||
            hv ||
            charImgCap ||
            charImgUrl ||
            narStored ||
            charLockAssistantSpecHasEffect(charLockSpecRestore) ||
            offlineMeetupWillTriggerRestore
          ) {
            promoteAssistantComposerQuoteToStructuredStorage(entry, next);
            tagAssistantEntryDmSurface(entry, rollSurface);
            next.splice(entryInsertAt, 0, entry);
            restoredEntry = entry;
            applyAssistantStickerLayoutToLogEntry(
              next,
              stickerPickRestore,
              entry,
              rollSurface,
              false
            );
          } else if (stickerPickedRestore && rollSurface !== "offline") {
            next.splice(entryInsertAt, 0, entry);
            restoredEntry = entry;
            applyAssistantStickerLayoutToLogEntry(
              next,
              stickerPickRestore,
              entry,
              rollSurface,
              false
            );
          }
        }
        insertCharRecallsAfterLogEntry(next, restoredEntry, recalls, at, insertAt);
        let charRemarkNoticeRestore = null;
        try {
          charRemarkNoticeRestore = buildCharRemarkForUserChangeNoticeFromAssistant(
            firstParsed,
            restorePin.maskId,
            restorePin.threadId,
            rollSurface,
            th1,
            at
          );
          if (charRemarkNoticeRestore) next.push(charRemarkNoticeRestore);
        } catch (_) {
          /* ignore */
        }
        pushCharBlockUserNoticeFromAssistantIfAny(
          next,
          firstParsed,
          restorePin.maskId,
          restorePin.threadId,
          rollSurface,
          th1,
          at
        );
        clearAssistantRestoringFlagsInLog(next);
        removeChatRestoringPlaceholders(next);
        saveChatLogForSendPin(restorePin, next);
        finalizeCharThreadAvatarFromUserSentImage(
          firstParsed,
          next,
          rawReply,
          restorePin.maskId,
          restorePin.threadId,
          rollSurface
        );
        finalizeCharRemarkForUserFromAssistant(charRemarkNoticeRestore, restorePin.maskId, restorePin.threadId);
        kickoffPendingSessionImageGen(next);
        kickoffTheaterSnapGen(next, restorePin, restoredEntry != null ? next.indexOf(restoredEntry) : undefined, rollSurface);
        scheduleChatUiRefreshForRound(restorePin.maskId, restorePin.threadId, { flush: true });
        showToast(usePartialRestore ? "已重回该条气泡" : "已重回并替换此条");
        if (!usePartialRestore) {
          applyAssistantCharLockOfflineCallSideEffects(
            charLockSpecRestore,
            offlineMeetupWillTriggerRestore ? offlineMeetupRawRestore : null,
            placeCall,
            rollSurface
          );
        } else {
          maybeOpenCharLockFromAssistantSpec(charLockSpecRestore);
        }
        });
      } catch (err) {
        if (isChatAssistAbortError(err)) {
          showToast("已停止重回");
        } else {
          const msg = err instanceof Error ? err.message : String(err);
          showToast(`重回失败：${msg}`);
        }
        // 失败时恢复原消息
        try {
          if (restoreBackup) {
            preserveChatMessagesScrollForNextRender();
            const liveLog = readChatLogForSendPin(restorePin);
            if (cut >= 0 && cut < liveLog.length) {
              liveLog[cut] = restoreBackup;
              clearAssistantRestoringFlagsInLog(liveLog);
              removeChatRestoringPlaceholders(liveLog);
              saveChatLogForSendPin(restorePin, liveLog);
              scheduleChatUiRefreshForRound(restorePin.maskId, restorePin.threadId, { flush: true });
            }
          }
        } catch (_) {
          /* ignore */
        }
      }
      return;
    }
    if (action === "multiselect") {
      closeChatBubbleActionSheet();
      enterChatMsgMultiSelectMode(msgIdx, segIdx);
      showToast("点气泡勾选；底部可删除或总结到手记");
      return;
    }
    if (action === "delete") {
      const isNarrationSheet = isChatNarrationSheetSeg(segIdx);
      if (!isNarrationSheet) {
        const anchorWrap = chatBubbleActionAnchorEl?.closest?.(".chat-msg");
        if (
          anchorWrap instanceof HTMLElement &&
          !chatBubbleActionMsgIdxMatchesWrap(anchorWrap, msgIdx, log)
        ) {
          showToast("消息已变化，请重试");
          closeChatBubbleActionSheet();
          return;
        }
      }
      if (isChatNoticeCallEndedMessage(msg)) {
        const confirmText = confirmDeleteTranscriptArchiveNoticeText(msg);
        if (!confirmText) {
          showToast("无法删除");
          closeChatBubbleActionSheet();
          return;
        }
        if (!window.confirm(confirmText)) return;
        closeChatBubbleActionSheet();
        deleteChatTranscriptArchiveNoticeAt(msgIdx);
        return;
      }
      if (!window.confirm(isNarrationSheet ? "确定要删除这段旁白吗？" : "确定要删除这条消息吗？")) return;
      const isStickerBubble = sheetRoot?.dataset.bubbleIsSticker === "1";
      const stickerUrl = String(sheetRoot?.dataset.bubbleStickerUrl || "").trim();
      if (
        !performChatBubbleDeleteSegment(msgIdx, segIdx, {
          isStickerBubble,
          stickerUrl: stickerUrl || undefined
        })
      ) {
        showToast("无法删除");
        closeChatBubbleActionSheet();
        return;
      }
      showToast("已删除");
      closeChatBubbleActionSheet();
      return;
    }
    const label = chatBubbleActionLabels[action] || action;
    showToast(`${label} · 敬请期待`);
    closeChatBubbleActionSheet();
  };
  void run();
});

document.getElementById("chat-msg-multi-done")?.addEventListener("click", () => {
  clearChatMsgMultiSelectMode();
  showToast("已退出多选");
});
document.getElementById("chat-msg-multi-delete")?.addEventListener("click", () => {
  const n = chatMsgMultiSelectSet.size;
  if (!n) return;
  /** @type {{ msgIdx: number, segIdx: number }[]} */
  const pairs = [];
  const seen = new Set();
  for (const raw of chatMsgMultiSelectSet) {
    const p = parseChatMsgMultiSelectKey(raw);
    if (!p) continue;
    const k = chatMsgMultiSelectKey(p.msgIdx, p.segIdx);
    if (seen.has(k)) continue;
    seen.add(k);
    pairs.push(p);
  }
  if (!pairs.length) return;
  if (!window.confirm(`确定删除已选的 ${n} 段气泡？不可恢复。`)) return;
  pairs.sort((a, b) => (b.msgIdx !== a.msgIdx ? b.msgIdx - a.msgIdx : b.segIdx - a.segIdx));
  for (const p of pairs) {
    const log = readChatLog();
    const msg = log[p.msgIdx];
    const opts = resolveChatBubbleDeleteOptsForLogSegment(msg, p.segIdx);
    removeChatBubbleSegmentFromLog(p.msgIdx, p.segIdx, opts);
  }
  clearChatMsgMultiSelectMode({ skipRender: true });
  refreshChatAfterLogMutation();
  showToast("已删除");
});
document.getElementById("chat-msg-multi-summarize")?.addEventListener("click", () => {
  void runChatMultiSelectSummarizeToMemoSheet();
});
document.getElementById("chat-msg-multi-forward")?.addEventListener("click", () => {
  runChatMultiSelectForwardSheet();
});
document.getElementById("chat-multi-forward-backdrop")?.addEventListener("click", () => {
  closeChatMultiForwardSheet();
});
document.getElementById("chat-multi-forward-close")?.addEventListener("click", () => {
  closeChatMultiForwardSheet();
});
document.getElementById("chat-multi-forward-cancel")?.addEventListener("click", () => {
  closeChatMultiForwardSheet();
});
document.getElementById("chat-multi-forward-confirm")?.addEventListener("click", () => {
  confirmChatMultiForwardFromSheet();
});
document.getElementById("chat-multi-summary-backdrop")?.addEventListener("click", () => {
  closeChatMultiSummarySheet();
});
document.getElementById("chat-multi-summary-close")?.addEventListener("click", () => {
  closeChatMultiSummarySheet();
});
document.getElementById("chat-multi-summary-cancel")?.addEventListener("click", () => {
  closeChatMultiSummarySheet();
});
document.getElementById("chat-multi-summary-save")?.addEventListener("click", () => {
  persistChatMultiSummaryFromSheet();
});

document.getElementById("chat-send")?.addEventListener("click", () => {
  void sendChatFromInput();
});
document.getElementById("chat-more")?.addEventListener("click", () => {
  if (isChatOfflineScreenOpen()) {
    openChatOfflineMoreMenuSheet();
    return;
  }
  openChatMoreSheet();
});

function closeChatMoreSheet() {
  const root = document.getElementById("chat-more-sheet");
  if (!root) return;
  const dr = document.getElementById("chat-more-drawer");
  blurActiveElementInFixedSheet("#chat-more-sheet");
  dr?.classList.remove("open");
  root.classList.remove("is-open");
  root.setAttribute("aria-hidden", "true");
  window.setTimeout(() => {
    root.hidden = true;
    syncChatScreenOverlayOpenClass();
    restoreViewportAfterChatFixedSheet();
  }, 160);
}

/** 专注锁屏：整屏大字 + 题目层；非对话气泡。 */
let charLockTypingTimerId = 0;

/** @param {unknown} sess */
/**
 * @type {{
 *   typingText?: string,
 *   typingDraft?: string,
 *   typingFinal?: string,
 *   leadInReaction?: { mode: "single", text: string } | { mode: "revise", draft: string, final: string, keepPrefix: number },
 *   expectedPin?: string,
 *   pinHint?: string,
 *   charName?: string,
 *   charAvatarUrl?: string,
 *   questionsList?: { prompt: string, a: string, b: string, afterA: string, afterB: string, heartOnA?: string, heartOnB?: string, reactionA?: object, reactionB?: object }[] | null,
 *   quizIdx?: number,
 *   chatAfterQuiz?: boolean,
 *   lockMode?: "charOnUser" | "userOnChar",
 *   charQuizPickBusy?: boolean,
 *   flowPhase?: "leadIn" | "intro" | "quiz" | "quiz-char-picking" | "quiz-typing" | "quiz-reaction-hold" | "chat" | "chat-char-typing" | "chat-reply-hold" | "unlock",
 *   fullscreenChatReply?: boolean,
 *   stageComposing?: boolean,
 *   quizAnswers?: { q: string, pick: "a" | "b", label: string }[],
 *   pinWrongAttempts?: number,
 *   pinWrongGuesses?: string[],
 *   exitKind?: string,
 *   hadLockChat?: boolean,
 *   modelOfflineHint?: { sceneDesc: string, textAfter: string } | null,
 *   modelCharLockRelease?: boolean
 * } | null}
 */
let charLockSession = null;
let charLockTypingTarget = "";
let charLockTypingIdx = 0;
let charLockUseRevise = false;
/** @type {"idle" | "draft" | "pause1" | "delete" | "pause2" | "final" | "single"} */
let charLockPhase = "idle";
let charLockDraft = "";
let charLockFinal = "";
let charLockReviseIdx = 0;
/** 删改时保留的公共前缀长度（0=整段删光再打） */
let charLockReviseKeepPrefix = 0;
/** 0 开场 →1 题目 →2 题后整屏打字 →3 停留(继续) →4 同屏聊 →5 仅口令（与 flowPhase 并用） */
let charLockPreviewStep = 0;

const CHAR_LOCK_PIN_INPUT_PLACEHOLDER_DEFAULT = "输入口令…";
const CHAR_LOCK_TYPING_STATUS_LABEL = "正在输入中";
const CHAR_LOCK_IOS_COMPOSE_HINT = "点一下中央开始输入";

/** iOS Safari / PWA：隐藏 clip 输入框无法稳定唤起系统键盘。 */
function isCharLockIosKeyboardDevice() {
  return isIosNotificationDevice();
}

function charLockSyncStageComposeInputMode(enabled) {
  const stage = document.getElementById("char-lock-stage");
  if (!stage) return;
  stage.classList.toggle(
    "char-lock-stage--ios-input",
    Boolean(enabled) && isCharLockIosKeyboardDevice()
  );
}

/** @param {HTMLTextAreaElement} inp */
function charLockFocusStageInput(inp) {
  if (!(inp instanceof HTMLTextAreaElement)) return;
  try {
    inp.focus({ preventScroll: true });
  } catch {
    inp.focus();
  }
  if (!isCharLockIosKeyboardDevice()) return;
  try {
    const n = inp.value.length;
    inp.setSelectionRange(n, n);
  } catch {
    /* ignore */
  }
}

function charLockSetTypingStatusUi() {
  const st = document.getElementById("char-lock-status");
  const hint = document.getElementById("char-lock-typing-hint");
  if (st) st.textContent = CHAR_LOCK_TYPING_STATUS_LABEL;
  if (hint) hint.textContent = CHAR_LOCK_TYPING_STATUS_LABEL;
}

/** @param {{ expectedPin?: string, pinHint?: string, lockMode?: string } | null} sess */
/** @param {string} hintBody */
function charLockPinClueDisplayText(hintBody) {
  const t = String(hintBody || "")
    .replace(/^给 Ta 的提示[：:]\s*/, "")
    .replace(/^口令提示[：:]\s*/, "")
    .trim();
  return t || String(hintBody || "").trim();
}

/** @param {{ expectedPin?: string, pinHint?: string, lockMode?: string } | null} sess */
function charLockPinHintLine(sess) {
  if (!sess) return "";
  const hint = String(sess.pinHint || "").trim();
  const hasPin = Boolean(String(sess.expectedPin || "").trim());
  if (sess.lockMode === "userOnChar") {
    if (hint) return `给 Ta 的提示：${hint}`;
    if (hasPin) return "Ta 需输入你设的口令才能解锁。";
    return "";
  }
  if (hint) return `口令提示：${hint}`;
  if (hasPin) return "回忆一下 Ta 在锁屏里留给你的线索，点右上角「离开」输入口令。";
  return "";
}

/** @param {{ expectedPin?: string, pinHint?: string, lockMode?: string } | null} sess */
function charLockUnlockStageFootHint(sess) {
  if (!sess) return "点右上角「离开」可退出锁屏。";
  const hasPin = Boolean(String(sess.expectedPin || "").trim());
  if (sess.lockMode === "userOnChar") {
    if (hasPin) {
      const pinLine = charLockPinHintLine(sess);
      return pinLine
        ? `${pinLine} Ta 试解锁点「Ta 试口令」；你收起锁屏点「结束」。`
        : "Ta 试解锁点「Ta 试口令」；你收起锁屏点「结束」。";
    }
    return "点「结束」收起锁屏。";
  }
  const pinLine = charLockPinHintLine(sess);
  if (pinLine) return `${pinLine} 点「离开」输入口令。`;
  if (hasPin) return "点右上角「离开」，按 Ta 的线索输入口令。";
  return "点「离开」即可退出锁屏。";
}

function charLockSetExitSheetErr(msg) {
  const err = document.getElementById("char-lock-exit-sheet-err");
  if (err) err.textContent = String(msg || "").trim();
}

let charLockPinTryToastTimer = 0;

function charLockHideCharPinTryToast() {
  const el = document.getElementById("char-lock-pin-try-toast");
  if (!el) return;
  window.clearTimeout(charLockPinTryToastTimer);
  charLockPinTryToastTimer = 0;
  el.classList.remove("is-show");
  el.hidden = true;
  el.textContent = "";
}

/** userOnChar：Ta 试口令失败时，在锁屏上提示 user Ta 猜了什么 */
function charLockShowCharPinTryToast(attemptPin) {
  const sess = charLockSession;
  if (!sess || sess.lockMode !== "userOnChar") return;
  const nm = String(sess.charName || "").trim() || "Ta";
  const guess = String(attemptPin || "").trim() || "（空）";
  const text = `${nm} 试了解锁口令：「${guess.slice(0, 48)}」· 不对`;
  const el = document.getElementById("char-lock-pin-try-toast");
  if (!el) {
    showToast(text, 3200);
    return;
  }
  el.textContent = text;
  el.hidden = false;
  el.classList.add("is-show");
  window.clearTimeout(charLockPinTryToastTimer);
  charLockPinTryToastTimer = window.setTimeout(() => {
    charLockHideCharPinTryToast();
  }, 3200);
}

function charLockSubmitExitPin() {
  const sess = charLockSession;
  if (!sess) return;
  const pinEl = document.getElementById("char-lock-pin-input");
  const pin =
    pinEl && pinEl instanceof HTMLInputElement
      ? String(pinEl.value || "")
          .trim()
          .replace(/\s+/g, " ")
      : "";
  const exp = String(sess.expectedPin || "").trim().replace(/\s+/g, " ");
  if (!exp) {
    sess.exitKind = "leave_no_pin";
    charLockCompleteUnlockFlow();
    return;
  }
  if (!pin) {
    charLockSetExitSheetErr("请先输入口令");
    return;
  }
  if (pin === exp) {
    sess.exitKind = "pin_ok";
    charLockCompleteUnlockFlow();
    return;
  }
  sess.pinWrongAttempts = Math.max(0, Number(sess.pinWrongAttempts) || 0) + 1;
  if (sess.lockMode === "userOnChar") {
    charLockShowCharPinTryToast(pin);
    charLockSetExitSheetErr("口令不对，Ta 还没解锁");
    return;
  }
  if (!Array.isArray(sess.pinWrongGuesses)) sess.pinWrongGuesses = [];
  sess.pinWrongGuesses.push(pin.slice(0, 64));
  charLockSetExitSheetErr("口令不对，再看看上面的提示");
}

function clearCharLockTypingTimers() {
  if (charLockTypingTimerId) {
    window.clearTimeout(charLockTypingTimerId);
    charLockTypingTimerId = 0;
  }
}

function isCharLockFocusScreenOpen() {
  return Boolean(document.getElementById("char-lock-screen")?.classList.contains("is-open"));
}

/** 锁屏须挂 body 全视口 fixed，避免留在 #phone 叠层内被聊天页透出。 */
function ensureCharLockScreenMounted() {
  const root = document.getElementById("char-lock-screen");
  if (!root || root.parentElement === document.body) return;
  document.body.appendChild(root);
}

function syncCharLockScreenBodyState(open) {
  document.body.classList.toggle("is-char-lock-open", Boolean(open));
  document.getElementById("phone")?.classList.toggle("is-char-lock-active", Boolean(open));
}

/**
 * @param {unknown} list
 * @param {"charOnUser" | "userOnChar" | undefined} [lockMode]
 */
function charLockQuizListIsActive(list, lockMode) {
  const n = Array.isArray(list) ? list.length : 0;
  if (!n) return false;
  if (lockMode === "userOnChar") return n >= 1;
  return n >= CHAR_LOCK_QUIZ_MIN;
}

function charLockSessionHasQuestionLayer() {
  return charLockQuizListIsActive(charLockSession?.questionsList, charLockSession?.lockMode);
}

function charLockGetCurrentQuizRow() {
  const list = charLockSession?.questionsList;
  if (!Array.isArray(list) || !list.length) return null;
  const ix = Math.max(0, Math.min(Number(charLockSession.quizIdx) || 0, list.length - 1));
  return list[ix] || null;
}

function charLockOpenQuestionLayerForRow(row) {
  const layer = document.getElementById("char-lock-q-layer");
  if (!row) {
    layer?.classList.remove("char-lock-q-layer--open-ended");
    charLockOpenQuestionLayer("", "", "");
    return;
  }
  if (charLockQuizRowHasChoices(row)) {
    layer?.classList.remove("char-lock-q-layer--open-ended");
    charLockOpenQuestionLayer(row.prompt, row.a, row.b);
  } else {
    layer?.classList.add("char-lock-q-layer--open-ended");
    charLockOpenQuestionLayer(row.prompt, "", "");
  }
}

function charLockOpenQuestionLayerFromList() {
  const row = charLockGetCurrentQuizRow();
  if (row) {
    charLockOpenQuestionLayerForRow(row);
    if (charLockSession?.lockMode === "userOnChar" && charLockSession.flowPhase === "quiz") {
      window.setTimeout(() => charLockBeginCharQuizTurn(), 320);
    }
    return;
  }
  charLockOpenQuestionLayerForRow(null);
}

function charLockCloseExitSheet() {
  const sheet = document.getElementById("char-lock-exit-sheet");
  if (!sheet) return;
  sheet.hidden = true;
  sheet.setAttribute("aria-hidden", "true");
  sheet.classList.remove("is-open");
  const err = document.getElementById("char-lock-exit-sheet-err");
  if (err) err.textContent = "";
  const forceBtn = document.getElementById("char-lock-exit-force-btn");
  if (forceBtn) forceBtn.hidden = true;
}

function charLockSyncLockTopbarUi() {
  const sess = charLockSession;
  const exitBtn = document.getElementById("char-lock-exit-btn");
  const charUnlockBtn = document.getElementById("char-lock-char-unlock-btn");
  const userLock = sess?.lockMode === "userOnChar";
  const hasPin = Boolean(String(sess?.expectedPin || "").trim());
  if (exitBtn) exitBtn.textContent = userLock ? "结束" : "离开";
  if (charUnlockBtn) {
    charUnlockBtn.hidden = !(userLock && hasPin);
    charUnlockBtn.textContent = "Ta 试口令";
  }
}

function charLockOpenCharUnlockSheet() {
  const sess = charLockSession;
  if (!sess || sess.lockMode !== "userOnChar") return;
  if (!String(sess.expectedPin || "").trim()) {
    showToast("本场未设 Ta 解锁口令");
    return;
  }
  charLockOpenExitSheet();
}

function charLockOpenExitSheet() {
  const sess = charLockSession;
  if (!sess) return;
  const sheet = document.getElementById("char-lock-exit-sheet");
  const title = document.getElementById("char-lock-exit-sheet-title");
  const lead = document.getElementById("char-lock-exit-sheet-lead");
  const clue = document.getElementById("char-lock-exit-sheet-clue");
  const clueText = document.getElementById("char-lock-exit-sheet-clue-text");
  const pin = document.getElementById("char-lock-pin-input");
  const pinLabel = document.querySelector(".char-lock-exit-sheet-field-k");
  const unlockBtn = document.getElementById("char-lock-unlock-btn");
  const err = document.getElementById("char-lock-exit-sheet-err");
  if (!sheet) return;
  if (err) err.textContent = "";
  const hasPin = Boolean(String(sess.expectedPin || "").trim());
  const userLock = sess.lockMode === "userOnChar";
  if (title) title.textContent = userLock ? "Ta 试解锁" : "解锁离开";
  if (lead) {
    if (userLock) {
      lead.textContent =
        "Ta 在试解锁自己的手机。你可代 Ta 输入口令；正确则 Ta 解锁并回到密谈。";
    } else if (!hasPin) {
      lead.textContent = "这场锁屏未设口令，点「解锁离开」即可回到密谈。";
    } else {
      lead.textContent = "输入 Ta 留给你的口令。提示藏在上面锁屏台词里。";
    }
  }
  const hintBody = charLockPinHintLine(sess);
  if (clue && clueText) {
    if (hasPin && hintBody) {
      clueText.textContent = charLockPinClueDisplayText(hintBody);
      clue.hidden = false;
    } else {
      clueText.textContent = "";
      clue.hidden = true;
    }
  }
  if (pin && pin instanceof HTMLInputElement) {
    pin.value = "";
    pin.placeholder = userLock ? "代 Ta 输入解锁口令" : CHAR_LOCK_PIN_INPUT_PLACEHOLDER_DEFAULT;
  }
  if (pinLabel) pinLabel.textContent = userLock ? "Ta 的口令" : "输入口令";
  if (unlockBtn) unlockBtn.textContent = userLock ? "Ta 解锁离开" : "解锁离开";
  const forceBtn = document.getElementById("char-lock-exit-force-btn");
  if (forceBtn) forceBtn.hidden = userLock || !hasPin;
  sheet.hidden = false;
  sheet.setAttribute("aria-hidden", "false");
  sheet.classList.add("is-open");
  if (pin && pin instanceof HTMLInputElement) {
    requestAnimationFrame(() => pin.focus());
  }
}

function charLockForceExitLockScreen() {
  if (!charLockSession) return;
  const ok = window.confirm(
    "确定强制退出锁屏？\n\n无需输入口令即可回到密谈；角色侧会收到「对方强行离开锁屏」的汇总（与输对口令离开不同）。"
  );
  if (!ok) return;
  charLockSession.exitKind = "force_exit";
  charLockCompleteUnlockFlow();
}

function charLockRequestExitLockScreen() {
  if (!charLockSession) return;
  if (charLockSession.lockMode === "userOnChar") {
    charLockSession.exitKind = "user_dismiss";
    charLockCompleteUnlockFlow();
    return;
  }
  const exp = String(charLockSession.expectedPin || "").trim().replace(/\s+/g, " ");
  if (!exp) {
    charLockSession.exitKind = "leave_no_pin";
    charLockCompleteUnlockFlow();
    return;
  }
  charLockOpenExitSheet();
}

function charLockStopStageCompose() {
  const sess = charLockSession;
  if (sess) sess.stageComposing = false;
  const stage = document.getElementById("char-lock-stage");
  const inp = document.getElementById("char-lock-stage-input");
  const caret = document.getElementById("char-lock-typing-caret");
  stage?.classList.remove("char-lock-stage--user-compose");
  charLockSyncStageComposeInputMode(false);
  caret?.classList.remove("char-lock-typing-caret--blink");
  if (inp && inp instanceof HTMLTextAreaElement) {
    inp.value = "";
    inp.blur();
  }
}

function charLockSyncStageComposeDisplay() {
  if (!charLockSession?.stageComposing) return;
  const inp = document.getElementById("char-lock-stage-input");
  const tx = document.getElementById("char-lock-typing-text");
  if (!inp || !tx || !(inp instanceof HTMLTextAreaElement)) return;
  tx.textContent = inp.value;
}

function charLockStartStageCompose() {
  const sess = charLockSession;
  if (!sess || sess.flowPhase !== "chat" || sess.fullscreenChatReply) return;
  charLockStopStageCompose();
  sess.stageComposing = true;
  const st = document.getElementById("char-lock-status");
  const hint = document.getElementById("char-lock-typing-hint");
  const tx = document.getElementById("char-lock-typing-text");
  const stage = document.getElementById("char-lock-stage");
  const caret = document.getElementById("char-lock-typing-caret");
  const inp = document.getElementById("char-lock-stage-input");
  if (tx) tx.textContent = "";
  stage?.classList.add("char-lock-stage--user-compose");
  document.getElementById("char-lock-stage-wrap")?.classList.add("char-lock-stage-wrap--reaction");
  caret?.classList.add("char-lock-typing-caret--blink");
  if (st) st.textContent = "你";
  if (hint) hint.textContent = CHAR_LOCK_TYPING_STATUS_LABEL;
  charLockSyncStageComposeInputMode(true);
  if (inp && inp instanceof HTMLTextAreaElement) {
    inp.value = "";
    if (isCharLockIosKeyboardDevice()) {
      charLockFocusStageInput(inp);
    } else {
      requestAnimationFrame(() => charLockFocusStageInput(inp));
    }
  }
  charLockSyncSkipTypingBtn();
}

function charLockCommitStageCompose() {
  const sess = charLockSession;
  if (!sess || !sess.stageComposing || sess.flowPhase !== "chat" || sess.fullscreenChatReply) return;
  const inp = document.getElementById("char-lock-stage-input");
  const t = inp && inp instanceof HTMLTextAreaElement ? String(inp.value || "").trim() : "";
  if (!t) return;
  const tx = document.getElementById("char-lock-typing-text");
  if (tx) tx.textContent = t;
  sess.stageComposing = false;
  const stage = document.getElementById("char-lock-stage");
  stage?.classList.remove("char-lock-stage--user-compose");
  const inpEl = document.getElementById("char-lock-stage-input");
  if (inpEl && inpEl instanceof HTMLTextAreaElement) {
    inpEl.value = "";
    inpEl.blur();
  }
  document.getElementById("char-lock-typing-caret")?.classList.remove("char-lock-typing-caret--blink");
  void charLockRunLiveModelThenFullscreenTyping(t);
}

function charLockPrepareStageTyping() {
  clearCharLockTypingTimers();
  charLockStopStageCompose();
  charLockCloseQuestionLayer();
  document.getElementById("char-lock-stage")?.classList.add("char-lock-stage--quiz-typing");
  document.getElementById("char-lock-stage-wrap")?.classList.add("char-lock-stage-wrap--reaction");
  charLockSetTypingStatusUi();
  document.getElementById("char-lock-typing-caret")?.classList.add("char-lock-typing-caret--blink");
}

function charLockOnReviseTypingFinished() {
  charLockUseRevise = false;
  charLockPhase = "idle";
  charLockReviseIdx = 0;
  charLockReviseKeepPrefix = 0;
  charLockSetStageDeleting(false);
  const st = document.getElementById("char-lock-status");
  const hint = document.getElementById("char-lock-typing-hint");
  const tx = document.getElementById("char-lock-typing-text");
  document.getElementById("char-lock-typing-caret")?.classList.remove("char-lock-typing-caret--blink");
  const sess = charLockSession;
  if (sess?.flowPhase === "leadIn") {
    charLockOnLeadInTypingFinished();
    return;
  }
  if (sess?.flowPhase === "quiz-typing") {
    charLockOnFullScreenTypingComplete(st, hint);
    return;
  }
  if (sess?.flowPhase === "chat-char-typing") {
    charLockOnChatFullscreenTypingDone(tx);
    return;
  }
  charLockOnIntroTypingFinished();
}

function charLockStartLeadInPhase() {
  const sess = charLockSession;
  if (!sess || !charLockReactionPackHasText(sess.leadInReaction)) return;
  sess.flowPhase = "leadIn";
  charLockPreviewStep = 0;
  charLockArmStageContent(sess.leadInReaction, { allowRevise: false });
}

/**
 * @param {string} holdPhase
 * @param {string} hintText
 * @param {{ previewStep?: number, skipFinalize?: boolean }} [opts]
 */
function charLockEnterStageTypingHold(holdPhase, hintText, opts) {
  const sess = charLockSession;
  if (!sess) return;
  sess.flowPhase = holdPhase;
  if (opts?.previewStep != null) charLockPreviewStep = opts.previewStep;
  charLockPhase = "idle";
  charLockTypingTarget = "";
  charLockTypingIdx = 0;
  document.getElementById("char-lock-stage")?.classList.remove("char-lock-stage--quiz-typing");
  charLockCloseQuestionLayer();
  charLockStopStageCompose();
  document.getElementById("char-lock-typing-caret")?.classList.remove("char-lock-typing-caret--blink");
  charLockSetStageDeleting(false);
  const st = document.getElementById("char-lock-status");
  const hint = document.getElementById("char-lock-typing-hint");
  const tx = document.getElementById("char-lock-typing-text");
  if (!opts?.skipFinalize && tx instanceof HTMLElement) {
    const shown = String(tx.textContent || "").trim();
    if (shown) setCharLockTypingElText(tx, shown, { finalize: true });
  }
  if (st) st.textContent = "说完了";
  if (hint) hint.textContent = hintText;
  charLockSyncSkipTypingBtn();
}

function charLockOnLeadInTypingFinished() {
  const sess = charLockSession;
  if (!sess) return;
  charLockPhase = "idle";
  charLockEnterStageTypingHold("leadIn-hold", "开场已打完。点一下屏幕继续，进入宣读。");
}

function charLockBeginIntroFromSession() {
  const sess = charLockSession;
  if (!sess) return;
  const tx = document.getElementById("char-lock-typing-text");
  if (tx) tx.textContent = "";
  const st = document.getElementById("char-lock-status");
  const hint = document.getElementById("char-lock-typing-hint");
  const draft = normalizeCharLockStageReplyText(sess.typingDraft);
  const fin = normalizeCharLockStageReplyText(sess.typingFinal);
  const single = normalizeCharLockStageReplyText(sess.typingText);
  const hasIntro = Boolean((draft && fin) || single);
  const wantQ = charLockSessionHasQuestionLayer();
  if (!hasIntro) {
    if (wantQ) {
      sess.flowPhase = "quiz";
      charLockPreviewStep = 1;
      charLockPhase = "idle";
      charLockTypingTarget = "";
      if (st) {
        const n = sess.questionsList?.length || 0;
        st.textContent = n > 1 ? `第 1 / ${n} 题` : "选一选";
      }
      if (hint) {
        hint.textContent = charLockQuizPickHintForMode();
      }
      charLockOpenQuestionLayerFromList();
      charLockSyncSkipTypingBtn();
      return;
    }
    if (st) st.textContent = "说完了";
    if (hint) hint.textContent = charLockUnlockStageFootHint(sess);
    sess.flowPhase = "unlock";
    charLockPreviewStep = 5;
    charLockSyncSkipTypingBtn();
    return;
  }
  sess.flowPhase = "intro";
  charLockPreviewStep = 0;
  if (draft && fin) {
    charLockArmStageFullscreenTyping(fin || draft);
    return;
  }
  charLockArmStageFullscreenTyping(single);
}

function charLockAdvanceAfterTypingHold() {
  const sess = charLockSession;
  if (!sess || sess.flowPhase !== "chat-reply-hold") return;
  if (sess.modelCharLockRelease) {
    sess.exitKind = "char_released";
    charLockCompleteUnlockFlow();
    return;
  }
  const tx = document.getElementById("char-lock-typing-text");
  if (tx) tx.textContent = "";
  const st = document.getElementById("char-lock-status");
  const hint = document.getElementById("char-lock-typing-hint");
  charLockEnterChatPhase(st, hint);
}

/**
 * @param {string} draft
 * @param {string} final
 * @param {{ status?: string, hint?: string }} [meta]
 */
function charLockArmStageReviseTyping(draft, final) {
  charLockPrepareStageTyping();
  const tx = document.getElementById("char-lock-typing-text");
  charLockDraft = normalizeCharLockStageReplyText(draft);
  charLockFinal = normalizeCharLockStageReplyText(final);
  let keep = 0;
  const lim = Math.min(charLockDraft.length, charLockFinal.length);
  while (keep < lim && charLockDraft[keep] === charLockFinal[keep]) keep++;
  charLockReviseKeepPrefix = keep;
  charLockUseRevise = true;
  charLockPhase = "draft";
  charLockReviseIdx = 0;
  charLockTypingTarget = "";
  charLockTypingIdx = 0;
  if (tx) tx.textContent = "";
  charLockSyncSkipTypingBtn();
  scheduleCharLockTypingTick();
}

/**
 * @param {{ mode: "single", text: string } | { mode: "revise", draft: string, final: string, keepPrefix: number }} reaction
 * @param {{ allowRevise?: boolean }} [opts]
 */
function charLockArmStageContent(reaction, opts) {
  const allowRevise = opts?.allowRevise !== false;
  if (allowRevise && reaction.mode === "revise" && reaction.draft && reaction.final) {
    charLockArmStageReviseTyping(reaction.draft, reaction.final);
    return;
  }
  const text =
    reaction.mode === "revise"
      ? String(reaction.final || reaction.draft || reaction.text || "")
      : String(reaction.text || "");
  charLockArmStageFullscreenTyping(text);
}

/** @param {string} text */
function charLockArmStageFullscreenTyping(text) {
  charLockPrepareStageTyping();
  const tx = document.getElementById("char-lock-typing-text");
  const full = normalizeCharLockStageReplyText(text);
  charLockTypingTarget = full;
  charLockUseRevise = false;
  charLockPhase = "single";
  if (tx) {
    setCharLockTypingElText(tx, full.length ? full.slice(0, 1) : "", { finalize: false });
    charLockTypingIdx = full.length ? 1 : 0;
  } else {
    charLockTypingIdx = 0;
  }
  charLockSyncSkipTypingBtn();
  scheduleCharLockTypingTick();
}

/** @param {unknown} ent @returns {string} */
function charLockExtractAssistantDisplayFromLogEntry(ent) {
  if (!ent || typeof ent !== "object") return "";
  /** @type {any} */
  const m = ent;
  if (m.role !== "assistant") return "";
  const c = String(m.content ?? "").trim();
  if (!c || c === "\u00A0") {
    const liveFin = normalizeCharLockStageReplyText(String(m.charLockLiveFinal || "").trim());
    if (liveFin) return liveFin;
    const liveDr = normalizeCharLockStageReplyText(String(m.charLockLiveDraft || "").trim());
    if (liveDr) return liveDr;
    return "";
  }
  const joined = normalizeCharLockStageReplyText(c);
  const clean = charLockSanitizeLeakedProtocolDisplayText(joined);
  return clean ? normalizeCharLockStageReplyText(clean) : joined;
}

/**
 * 同屏聊 · 与主聊天同一套 `executeChatAssistantRound`，再整屏逐字展示回复。
 * @param {string} userText
 */
async function charLockRunLiveModelThenFullscreenTyping(userText) {
  const sess = charLockSession;
  if (!sess || sess.flowPhase !== "chat" || sess.fullscreenChatReply) return;
  const st = document.getElementById("char-lock-status");
  const hint = document.getElementById("char-lock-typing-hint");
  const tx = document.getElementById("char-lock-typing-text");
  clearCharLockTypingTimers();
  sess.flowPhase = "chat-char-typing";
  sess.fullscreenChatReply = true;
  if (tx) tx.textContent = "";
  charLockSetTypingStatusUi();
  charLockStopStageCompose();
  charLockSyncSkipTypingBtn();

  if (!window.RP_AI) {
    sess.fullscreenChatReply = false;
    sess.flowPhase = "chat";
    charLockStartStageCompose();
    if (st) st.textContent = "同屏聊";
    if (hint) hint.textContent = "AI 模块未加载，无法请求模型。";
    showToast("AI 模块未加载");
    charLockSyncSkipTypingBtn();
    return;
  }

  reconcileActiveThreadRef();
  if (!readChatActiveThreadRef().threadId) {
    sess.fullscreenChatReply = false;
    sess.flowPhase = "chat";
    charLockStartStageCompose();
    if (st) st.textContent = "同屏聊";
    if (hint) hint.textContent = "没有可用的密谈线程，无法请求模型。";
    showChatThreadUnavailableToast();
    return;
  }

  if (sess) sess.hadLockChat = true;
  const log = readChatLog();
  const markBefore = log.length;
  const entry = {
    role: "user",
    content: String(userText).slice(0, 8000),
    at: Date.now(),
    charLockSessionOnly: true
  };
  tagOutgoingChatDmSurfaceIfOffline(entry);
  log.push(entry);
  saveChatLog(log);
  scheduleRenderChatMessages();
  scheduleChatContextTokenLabelUpdate();
  scheduleChatProactiveTimer();

  const thLock = readActiveThread();
  const midLock = String(getActiveMaskIdForInbox() || "").trim();
  const tidLock = String(readChatActiveThreadRef().threadId || "").trim();
  await executeChatAssistantRound(
    {
      suppressCharLockAndCallSideEffects: true,
      charLockLiveChat: true,
      boundMaskId: midLock,
      boundThreadId: tidLock,
      boundThread: thLock || undefined,
      boundDmSurface: resolveChatRoundDmSurface(
        { boundMaskId: midLock, boundThreadId: tidLock, boundThread: thLock || undefined },
        thLock,
        midLock,
        tidLock
      )
    },
    null
  );
  charLockMarkNewLogRowsAsSessionOnly(markBefore);

  if (!charLockSession?.fullscreenChatReply || charLockSession.flowPhase !== "chat-char-typing") {
    return;
  }

  const live = readChatLog();
  /** @type {any} */
  let lastAs = null;
  const scanFrom = Math.max(0, markBefore);
  for (let i = live.length - 1; i >= scanFrom; i--) {
    const m = live[i];
    if (m && m.role === "assistant" && !m.restoring) {
      lastAs = m;
      break;
    }
  }
  const displayPlain = charLockExtractAssistantDisplayFromLogEntry(lastAs).trim();
  const liveDraft = normalizeCharLockStageReplyText(String(lastAs?.charLockLiveDraft || "").trim());
  const liveFinal =
    normalizeCharLockStageReplyText(String(lastAs?.charLockLiveFinal || "").trim()) || displayPlain;
  const rawFail = String(lastAs?.content || "").trim();
  if (sess.modelCharLockRelease && !displayPlain && !rawFail.startsWith("（未能回复）")) {
    sess.fullscreenChatReply = false;
    charLockEnterStageTypingHold("chat-reply-hold", "Ta 放你离开了，不必再对口令。点一下屏幕回到密谈。", {
      skipFinalize: true
    });
    return;
  }
  if (rawFail.startsWith("（未能回复）") || !displayPlain) {
    sess.fullscreenChatReply = false;
    sess.flowPhase = "chat";
    charLockStartStageCompose();
    if (st) st.textContent = "同屏聊";
    if (hint) hint.textContent = "请求失败或未返回可读正文。可再试一句。";
    if (!rawFail.startsWith("（未能回复）")) showToast("未收到可用于整屏展示的正文");
    charLockSyncSkipTypingBtn();
    return;
  }

  const plainForStage = displayPlain;
  const revDraft = liveDraft;
  const revFinal = liveFinal.trim() ? liveFinal : plainForStage;
  if (revDraft && revFinal && revDraft !== revFinal) {
    charLockArmStageReviseTyping(revDraft, revFinal);
    return;
  }
  charLockArmStageFullscreenTyping(plainForStage);
}

/** @param {HTMLElement | null} tx */
function charLockOnChatFullscreenTypingDone(tx) {
  const sess = charLockSession;
  if (!sess) return;
  const shown = charLockTypingTarget || (tx instanceof HTMLElement ? tx.textContent : "");
  sess.fullscreenChatReply = false;
  charLockTypingTarget = "";
  charLockTypingIdx = 0;
  charLockPhase = "idle";
  document.getElementById("char-lock-stage")?.classList.remove("char-lock-stage--quiz-typing");
  document.getElementById("char-lock-typing-caret")?.classList.remove("char-lock-typing-caret--blink");
  charLockStopStageCompose();
  if (tx instanceof HTMLElement && shown) setCharLockTypingElText(tx, shown, { finalize: true });
  charLockEnterStageTypingHold(
    "chat-reply-hold",
    sess.modelCharLockRelease
      ? "Ta 放你离开了，不必再对口令。点一下屏幕回到密谈。"
      : "整屏回应已打完。点一下屏幕再输入下一句。",
    { skipFinalize: true }
  );
}

function charLockIsStageTapContinuePhase() {
  const fp = charLockSession?.flowPhase;
  return (
    fp === "leadIn-hold" ||
    fp === "intro-hold" ||
    fp === "quiz-reaction-hold" ||
    fp === "chat-reply-hold"
  );
}

function charLockAdvanceFromStageTap() {
  const fp = charLockSession?.flowPhase;
  if (fp === "chat-reply-hold") charLockAdvanceAfterTypingHold();
  else if (fp === "leadIn-hold") charLockBeginIntroFromSession();
  else if (fp === "intro-hold") charLockProceedAfterIntroTyping();
  else if (fp === "quiz-reaction-hold") charLockAdvanceAfterQuizReactionHold();
}

/**
 * @param {"a" | "b"} which
 */
function charLockRecordUserQuizPick(which) {
  const sess = charLockSession;
  if (!sess || sess.flowPhase !== "quiz") return;
  const row = charLockGetCurrentQuizRow();
  if (!row) return;
  if (!Array.isArray(sess.quizAnswers)) sess.quizAnswers = [];
  const pick = which === "b" ? "b" : "a";
  const label = pick === "a" ? String(row.a || "").trim() : String(row.b || "").trim();
  sess.quizAnswers.push({
    q: String(row.prompt || "").trim().slice(0, 500),
    pick,
    label: label.slice(0, 200),
    pickBy: "user"
  });
}

/**
 * @param {"a" | "b"} which
 */
function charLockRecordCharQuizPick(which) {
  const sess = charLockSession;
  if (!sess) return;
  const row = charLockGetCurrentQuizRow();
  if (!row) return;
  if (!Array.isArray(sess.quizAnswers)) sess.quizAnswers = [];
  const pick = which === "b" ? "b" : "a";
  const label = pick === "a" ? String(row.a || "").trim() : String(row.b || "").trim();
  sess.quizAnswers.push({
    q: String(row.prompt || "").trim().slice(0, 500),
    pick,
    label: label.slice(0, 200),
    pickBy: "char"
  });
}

function charLockEnterChatPhase(st, hint) {
  const sess = charLockSession;
  if (!sess) return;
  sess.flowPhase = "chat";
  sess.fullscreenChatReply = false;
  charLockPreviewStep = 4;
  charLockTypingTarget = "";
  charLockTypingIdx = 0;
  charLockPhase = "idle";
  const tx = document.getElementById("char-lock-typing-text");
  if (tx) tx.textContent = "";
  charLockCloseQuestionLayer();
  if (st) st.textContent = "同屏聊";
  const caret = document.getElementById("char-lock-typing-caret");
  caret?.classList.remove("char-lock-typing-caret--blink");
  if (isCharLockIosKeyboardDevice()) {
    if (hint) hint.textContent = CHAR_LOCK_IOS_COMPOSE_HINT;
    charLockSyncSkipTypingBtn();
    return;
  }
  charLockStartStageCompose();
  charLockSyncSkipTypingBtn();
}

/**
 * 题后整屏打完：先完整展示这句，点一下后再进下一题 / 同屏聊（不立刻盖第二题）。
 * @param {HTMLElement | null} st
 * @param {HTMLElement | null} hint
 */
/**
 * 题后进入下一题 / 同屏聊 / 口令区（跳过整屏或点一下继续后共用）。
 * @param {HTMLElement | null} st
 * @param {HTMLElement | null} hint
 */
function charLockAdvanceToNextQuizStep(st, hint) {
  const sess = charLockSession;
  if (!sess) return;
  charLockSetQuizButtonsDisabled(false);
  const list = Array.isArray(sess.questionsList) ? sess.questionsList : [];
  const idx = Number(sess.quizIdx) || 0;
  const next = idx + 1;
  const tx = document.getElementById("char-lock-typing-text");
  charLockTypingTarget = "";
  charLockTypingIdx = 0;
  charLockPhase = "idle";
  if (tx) tx.textContent = "";
  charLockCloseQuestionLayer();
  document.getElementById("char-lock-typing-caret")?.classList.remove("char-lock-typing-caret--blink");
  if (next < list.length) {
    sess.quizIdx = next;
    sess.flowPhase = "quiz";
    charLockPreviewStep = 1;
    if (st) st.textContent = `第 ${next + 1} / ${list.length} 题`;
    if (hint) {
      hint.textContent =
        sess.lockMode === "userOnChar" ? "下一题，等 Ta 回应。" : "点一项作为你的回答";
    }
    charLockOpenQuestionLayerFromList();
    charLockSyncSkipTypingBtn();
    return;
  }
  if (sess.chatAfterQuiz !== false) {
    charLockEnterChatPhase(st, hint);
    return;
  }
  if (st) st.textContent = "说完了";
  if (hint) hint.textContent = charLockUnlockStageFootHint(sess);
  charLockPreviewStep = 5;
  sess.flowPhase = "unlock";
  charLockSyncSkipTypingBtn();
}

function charLockAdvanceAfterQuizReactionHold() {
  if (charLockSession?.flowPhase !== "quiz-reaction-hold") return;
  charLockAdvanceToNextQuizStep(
    document.getElementById("char-lock-status"),
    document.getElementById("char-lock-typing-hint")
  );
}

/**
 * @param {HTMLElement | null} st
 * @param {HTMLElement | null} hint
 */
function charLockOnFullScreenTypingComplete(st, hint) {
  const sess = charLockSession;
  if (!sess) return;
  const list = Array.isArray(sess.questionsList) ? sess.questionsList : [];
  const tx = document.getElementById("char-lock-typing-text");
  if (tx instanceof HTMLElement) {
    const shown = charLockTypingTarget || String(tx.textContent || "").trim();
    if (shown) setCharLockTypingElText(tx, shown, { finalize: true });
  }
  if (list.length && sess.flowPhase === "quiz-typing") {
    const reply = tx
      ? String(tx.textContent || "").trim()
      : String(charLockTypingTarget || "").trim();
    if (reply) {
      const idx = Number(sess.quizIdx) || 0;
      let holdHint = "整屏回应已打完。点一下屏幕继续。";
      if (idx + 1 < list.length) holdHint = "整屏回应已打完。点一下屏幕继续，进入下一题。";
      else if (sess.chatAfterQuiz !== false) holdHint = "整屏回应已打完。点一下屏幕继续，进入同屏聊。";
      else {
        const clue = charLockPinHintLine(sess);
        holdHint = clue
          ? `整屏回应已打完。点一下屏幕继续。${clue}`
          : "整屏回应已打完。点一下屏幕继续；要离开请点右上角「离开」。";
      }
      charLockEnterStageTypingHold("quiz-reaction-hold", holdHint, {
        previewStep: 3,
        skipFinalize: true
      });
      return;
    }
    charLockAdvanceToNextQuizStep(st, hint);
    return;
  }
  if (st) st.textContent = "说完了";
  if (hint) {
    hint.textContent = charLockUnlockStageFootHint(sess);
  }
  charLockPreviewStep = 5;
  sess.flowPhase = "unlock";
  charLockSyncSkipTypingBtn();
}

function charLockSetStageDeleting(on) {
  document.getElementById("char-lock-stage")?.classList.toggle("char-lock-stage--deleting", Boolean(on));
}

function charLockSetQuestionLayerOpen(open) {
  const layer = document.getElementById("char-lock-q-layer");
  const wrap = document.getElementById("char-lock-stage-wrap");
  if (layer) {
    layer.hidden = !open;
    layer.setAttribute("aria-hidden", open ? "false" : "true");
    if (open) {
      layer.style.removeProperty("display");
    } else {
      layer.style.display = "none";
    }
  }
  if (wrap) wrap.classList.toggle("char-lock-stage-wrap--reaction", !open);
}

function charLockOpenQuestionLayer(promptText, labelA, labelB) {
  const p = document.getElementById("char-lock-q-prompt");
  const a = document.getElementById("char-lock-q-a");
  const b = document.getElementById("char-lock-q-b");
  const pt = String(promptText || "").trim();
  const la = String(labelA || "").trim();
  const lb = String(labelB || "").trim();
  if (p) p.textContent = pt;
  if (a) a.textContent = la;
  if (b) b.textContent = lb;
  charLockSetQuestionLayerOpen(true);
}

function charLockCloseQuestionLayer() {
  document.getElementById("char-lock-q-layer")?.classList.remove("char-lock-q-layer--open-ended");
  charLockSetQuestionLayerOpen(false);
}

function charLockProceedAfterIntroTyping() {
  charLockPhase = "idle";
  charLockSyncSkipTypingBtn();
  const st = document.getElementById("char-lock-status");
  const hint = document.getElementById("char-lock-typing-hint");
  const wantQ = charLockSessionHasQuestionLayer();
  if (wantQ) {
    charLockPreviewStep = 1;
    if (charLockSession) charLockSession.flowPhase = "quiz";
    const n = charLockSession?.questionsList?.length || 0;
    if (st) {
      st.textContent = n > 1 ? `第 1 / ${n} 题` : "选一选";
    }
    if (hint) {
      hint.textContent = charLockQuizPickHintForMode();
    }
    charLockOpenQuestionLayerFromList();
    return;
  }
  if (st) st.textContent = "说完了";
  if (hint) {
    hint.textContent = charLockUnlockStageFootHint(charLockSession);
  }
  if (charLockSession) {
    charLockSession.flowPhase = "unlock";
    charLockPreviewStep = 5;
  }
}

function charLockOnIntroTypingFinished() {
  const sess = charLockSession;
  if (!sess) return;
  charLockPhase = "idle";
  const wantQ = charLockSessionHasQuestionLayer();
  charLockEnterStageTypingHold(
    "intro-hold",
    wantQ ? "宣读已打完。点一下屏幕继续，进入选题。" : "宣读已打完。点一下屏幕继续。"
  );
}

function charLockSyncSkipTypingBtn() {
  const skip = document.getElementById("char-lock-skip-typing");
  const onHold = charLockIsStageTapContinuePhase();
  document
    .getElementById("char-lock-stage-wrap")
    ?.classList.toggle("char-lock-stage-wrap--tap-continue", onHold);
  if (!skip) return;
  const inChatIdle =
    charLockSession?.flowPhase === "chat" &&
    !charLockSession?.fullscreenChatReply &&
    !charLockSession?.stageComposing;
  const chatStageTyping =
    charLockSession?.flowPhase === "chat-char-typing" &&
    (charLockPhase === "single" || Boolean(charLockTypingTarget));
  const typingAnim =
    charLockSession?.flowPhase === "quiz-typing" ||
    chatStageTyping ||
    charLockPhase === "draft" ||
    charLockPhase === "pause1" ||
    charLockPhase === "delete" ||
    charLockPhase === "pause2" ||
    charLockPhase === "final" ||
    charLockPhase === "single";
  const onQuestion =
    charLockSession?.flowPhase === "quiz" || charLockSession?.flowPhase === "quiz-char-picking";
  skip.hidden = !(isCharLockFocusScreenOpen() && typingAnim && !onQuestion && !inChatIdle && !onHold);
}

function charLockSkipTypingAnimation() {
  clearCharLockTypingTimers();
  const tx = document.getElementById("char-lock-typing-text");
  const caret = document.getElementById("char-lock-typing-caret");
  const st = document.getElementById("char-lock-status");
  const hint = document.getElementById("char-lock-typing-hint");
  if (!tx || !caret) return;
  if (charLockUseRevise && charLockFinal) {
    setCharLockTypingElText(tx, charLockFinal, { finalize: true });
    charLockUseRevise = false;
    charLockPhase = "idle";
    charLockReviseIdx = 0;
    charLockReviseKeepPrefix = 0;
    caret.classList.remove("char-lock-typing-caret--blink");
    charLockSetStageDeleting(false);
    if (charLockSession?.flowPhase === "leadIn") {
      charLockOnLeadInTypingFinished();
      charLockSyncSkipTypingBtn();
      return;
    }
    charLockOnReviseTypingFinished();
    charLockSyncSkipTypingBtn();
    return;
  } else if (charLockTypingTarget) {
    setCharLockTypingElText(tx, charLockTypingTarget, { finalize: true });
    charLockTypingIdx = charLockTypingTarget.length;
    charLockPhase = "idle";
  }
  caret.classList.remove("char-lock-typing-caret--blink");
  charLockSetStageDeleting(false);
  if (charLockSession?.flowPhase === "chat-char-typing" && charLockSession?.fullscreenChatReply) {
    if (charLockTypingTarget) {
      setCharLockTypingElText(tx, charLockTypingTarget, { finalize: true });
      charLockTypingIdx = charLockTypingTarget.length;
    }
    charLockOnChatFullscreenTypingDone(tx);
    charLockSyncSkipTypingBtn();
    return;
  }
  if (charLockSession?.flowPhase === "leadIn") {
    charLockOnLeadInTypingFinished();
    charLockSyncSkipTypingBtn();
    return;
  }
  if (charLockSession?.flowPhase === "intro") {
    charLockOnIntroTypingFinished();
  } else if (charLockSession?.flowPhase === "quiz-typing") {
    charLockOnFullScreenTypingComplete(st, hint);
  } else {
    if (st) st.textContent = "说完了";
    if (hint) {
      hint.textContent = charLockUnlockStageFootHint(charLockSession);
    }
  }
  charLockSyncSkipTypingBtn();
}

function charLockOnPickQuiz(which) {
  const sess = charLockSession;
  if (!sess || sess.flowPhase !== "quiz") return;
  if (sess.lockMode === "userOnChar") return;
  const st = document.getElementById("char-lock-status");
  const hint = document.getElementById("char-lock-typing-hint");
  const row = charLockGetCurrentQuizRow();
  charLockRecordUserQuizPick(which);
  /** @type {{ mode: "single", text: string } | { mode: "revise", draft: string, final: string, keepPrefix: number }} */
  let reaction = { mode: "single", text: "" };
  if (row) {
    reaction =
      which === "a"
        ? row.reactionA || { mode: "single", text: row.afterA }
        : row.reactionB || { mode: "single", text: row.afterB };
  }
  const hasText =
    reaction.mode === "revise" ? Boolean(reaction.draft && reaction.final) : Boolean(reaction.text);
  if (!hasText) {
    charLockAdvanceToNextQuizStep(st, hint);
    return;
  }
  charLockApplyCharQuizReaction(reaction);
}

function closeCharLockFocusScreen() {
  clearCharLockTypingTimers();
  charLockHideCharPinTryToast();
  charLockSession = null;
  charLockTypingTarget = "";
  charLockTypingIdx = 0;
  charLockUseRevise = false;
  charLockPhase = "idle";
  charLockDraft = "";
  charLockFinal = "";
  charLockReviseIdx = 0;
  charLockReviseKeepPrefix = 0;
  charLockPreviewStep = 0;
  const root = document.getElementById("char-lock-screen");
  const caret = document.getElementById("char-lock-typing-caret");
  const tx = document.getElementById("char-lock-typing-text");
  const st = document.getElementById("char-lock-status");
  const hint = document.getElementById("char-lock-typing-hint");
  const pin = document.getElementById("char-lock-pin-input");
  const exitBtn = document.getElementById("char-lock-exit-btn");
  const skipBtn = document.getElementById("char-lock-skip-typing");
  const stageInp = document.getElementById("char-lock-stage-input");
  if (tx) tx.textContent = "";
  if (caret) caret.classList.remove("char-lock-typing-caret--blink");
  charLockSetTypingStatusUi();
  if (pin && pin instanceof HTMLInputElement) {
    pin.value = "";
    pin.placeholder = CHAR_LOCK_PIN_INPUT_PLACEHOLDER_DEFAULT;
  }
  if (exitBtn) exitBtn.hidden = true;
  if (skipBtn) skipBtn.hidden = true;
  if (stageInp && stageInp instanceof HTMLTextAreaElement) stageInp.value = "";
  charLockStopStageCompose();
  charLockCloseExitSheet();
  document.getElementById("char-lock-stage-wrap")?.classList.remove("char-lock-stage-wrap--tap-continue");
  document.getElementById("char-lock-stage")?.classList.remove("char-lock-stage--quiz-typing", "char-lock-stage--user-compose");
  const qLayer = document.getElementById("char-lock-q-layer");
  if (qLayer) qLayer.style.removeProperty("display");
  document.getElementById("char-lock-stage-wrap")?.classList.remove("char-lock-stage-wrap--reaction");
  charLockSetStageDeleting(false);
  charLockCloseQuestionLayer();
  charLockSetQuizButtonsDisabled(false);
  root?.classList.remove("is-open");
  root?.setAttribute("aria-hidden", "true");
  syncCharLockScreenBodyState(false);
}

function scheduleCharLockTypingTick() {
  clearCharLockTypingTimers();
  const tx = document.getElementById("char-lock-typing-text");
  const caret = document.getElementById("char-lock-typing-caret");
  const st = document.getElementById("char-lock-status");
  const hint = document.getElementById("char-lock-typing-hint");
  if (!tx || !caret) return;

  if (charLockUseRevise) {
    if (!charLockDraft || !charLockFinal) return;
    charLockSetStageDeleting(charLockPhase === "delete");

    if (charLockPhase === "draft") {
      if (charLockReviseIdx >= charLockDraft.length) {
        caret.classList.remove("char-lock-typing-caret--blink");
        charLockSetTypingStatusUi();
        charLockPhase = "pause1";
        charLockTypingTimerId = window.setTimeout(() => {
          charLockPhase = "delete";
          charLockReviseIdx = charLockDraft.length;
          caret.classList.add("char-lock-typing-caret--blink");
          charLockSetTypingStatusUi();
          scheduleCharLockTypingTick();
        }, 380 + Math.floor(Math.random() * 420));
        charLockSyncSkipTypingBtn();
        return;
      }
      const roll = Math.random();
      const chunk = Math.min(
        charLockDraft.length - charLockReviseIdx,
        1 + (roll < 0.42 ? 1 : 0) + (roll < 0.12 ? 1 : 0)
      );
      charLockReviseIdx = Math.min(charLockDraft.length, charLockReviseIdx + chunk);
      tx.textContent = charLockDraft.slice(0, charLockReviseIdx);
      caret.classList.add("char-lock-typing-caret--blink");
      charLockSetTypingStatusUi();
      const delay = 26 + Math.floor(Math.random() * 56);
      charLockTypingTimerId = window.setTimeout(scheduleCharLockTypingTick, delay);
      charLockSyncSkipTypingBtn();
      return;
    }

    if (charLockPhase === "delete") {
      if (charLockReviseIdx <= charLockReviseKeepPrefix) {
        caret.classList.remove("char-lock-typing-caret--blink");
        charLockSetStageDeleting(false);
        charLockSetTypingStatusUi();
        charLockPhase = "pause2";
        charLockTypingTimerId = window.setTimeout(() => {
          charLockPhase = "final";
          charLockReviseIdx = charLockReviseKeepPrefix;
          caret.classList.add("char-lock-typing-caret--blink");
          charLockSetTypingStatusUi();
          scheduleCharLockTypingTick();
        }, 240 + Math.floor(Math.random() * 220));
        charLockSyncSkipTypingBtn();
        return;
      }
      const chunk = 1 + (Math.random() < 0.38 ? 1 : 0) + (Math.random() < 0.12 ? 1 : 0);
      charLockReviseIdx = Math.max(charLockReviseKeepPrefix, charLockReviseIdx - chunk);
      tx.textContent = charLockDraft.slice(0, charLockReviseIdx);
      caret.classList.add("char-lock-typing-caret--blink");
      charLockSetTypingStatusUi();
      const delay = 12 + Math.floor(Math.random() * 22);
      charLockTypingTimerId = window.setTimeout(scheduleCharLockTypingTick, delay);
      charLockSyncSkipTypingBtn();
      return;
    }

    if (charLockPhase === "final") {
      if (charLockReviseIdx >= charLockFinal.length) {
        caret.classList.remove("char-lock-typing-caret--blink");
        charLockSetStageDeleting(false);
        charLockOnReviseTypingFinished();
        return;
      }
      const roll = Math.random();
      const chunk = Math.min(
        charLockFinal.length - charLockReviseIdx,
        1 + (roll < 0.42 ? 1 : 0) + (roll < 0.12 ? 1 : 0)
      );
      charLockReviseIdx = Math.min(charLockFinal.length, charLockReviseIdx + chunk);
      tx.textContent = charLockFinal.slice(0, charLockReviseIdx);
      caret.classList.add("char-lock-typing-caret--blink");
      charLockSetTypingStatusUi();
      const delay = 26 + Math.floor(Math.random() * 56);
      charLockTypingTimerId = window.setTimeout(scheduleCharLockTypingTick, delay);
      charLockSyncSkipTypingBtn();
      return;
    }

    return;
  }

  charLockSetStageDeleting(false);
  if (!charLockTypingTarget) return;
  const full = charLockTypingTarget;
  charLockPhase = "single";
  if (charLockTypingIdx >= full.length) {
    caret.classList.remove("char-lock-typing-caret--blink");
    charLockPhase = "idle";
    if (charLockSession?.fullscreenChatReply && charLockSession?.flowPhase === "chat-char-typing") {
      charLockOnChatFullscreenTypingDone(tx);
      charLockSyncSkipTypingBtn();
      return;
    }
    if (charLockSession?.flowPhase === "leadIn") {
      charLockOnLeadInTypingFinished();
      charLockSyncSkipTypingBtn();
      return;
    }
    const qFlow = charLockSessionHasQuestionLayer();
    if (charLockSession?.flowPhase === "quiz-typing") {
      charLockOnFullScreenTypingComplete(st, hint);
    } else if (charLockSession?.flowPhase === "intro") {
      charLockOnIntroTypingFinished();
    } else {
      if (st) st.textContent = "说完了";
      if (hint) hint.textContent = "说完后，输入 Ta 设的口令即可解锁。";
    }
    charLockSyncSkipTypingBtn();
    return;
  }
  const roll = Math.random();
  const chunk = Math.min(full.length - charLockTypingIdx, 1 + (roll < 0.42 ? 1 : 0) + (roll < 0.12 ? 1 : 0));
  charLockTypingIdx = Math.min(full.length, charLockTypingIdx + chunk);
  setCharLockTypingElText(tx, full.slice(0, charLockTypingIdx), { finalize: false });
  caret.classList.add("char-lock-typing-caret--blink");
  charLockSetTypingStatusUi();
  const delay = 26 + Math.floor(Math.random() * 58);
  charLockTypingTimerId = window.setTimeout(scheduleCharLockTypingTick, delay);
  charLockSyncSkipTypingBtn();
}

/**
 * @param {{ typingText?: string, typingDraft?: string, typingFinal?: string, expectedPin?: string, charName?: string, charAvatarUrl?: string, leadInReaction?: object, leadInText?: string, leadInDraft?: string, leadInFinal?: string, questions?: object[], chatAfterQuiz?: boolean, pinHint?: string, lockMode?: "charOnUser" | "userOnChar" }} [opts]
 */
function openCharLockFocusScreen(opts) {
  const o = opts && typeof opts === "object" ? opts : {};
  const lockMode = o.lockMode === "userOnChar" ? "userOnChar" : "charOnUser";
  ensureCharLockScreenMounted();
  const root = document.getElementById("char-lock-screen");
  if (!root) return;
  closeCharLockFocusScreen();
  try {
    closeChatMoreSheet();
  } catch {
    /* ignore */
  }
  try {
    closeChatThreadDetailPanel({ skipFocusRestore: true });
  } catch {
    /* ignore */
  }
  const charP = readCharPersona();
  const nm = String(o.charName || "").trim() || getChatCharPersonaDisplayName() || "角色";
  const url = String(o.charAvatarUrl || "").trim() || (charP && charP.avatar && String(charP.avatar).trim()) || "";
  const typingRaw = String(o.typingText ?? "").trim();
  const draftIn = String(o.typingDraft || "").trim();
  const finIn = String(o.typingFinal || "").trim();
  const chatAfterQuiz = o.chatAfterQuiz !== false;

  /** @type {ReturnType<typeof normalizeUserLockCharQuizRow>[] | ReturnType<typeof normalizeCharLockQuizRow>[] | null} */
  const questionsList =
    lockMode === "userOnChar"
      ? charLockCollectValidUserLockQuizRows(o.questions)
      : charLockCollectValidQuizRows(o.questions, o.question);

  /** @type {{ mode: "single", text: string } | { mode: "revise", draft: string, final: string, keepPrefix: number } | null} */
  let leadInReaction = null;
  if (o.leadInReaction && charLockReactionPackHasText(o.leadInReaction)) {
    leadInReaction = o.leadInReaction;
  } else {
    const ld = String(o.leadInDraft || "").trim();
    const lf = String(o.leadInFinal || "").trim();
    const lt = String(o.leadInText || "").trim();
    if (ld && lf) leadInReaction = charLockParseRevisePair(ld, lf, "");
    else if (lt) leadInReaction = { mode: "single", text: lt };
  }
  const hasLeadIn = charLockReactionPackHasText(leadInReaction);

  let useRevise = false;
  let draft = "";
  let fin = "";
  let singleText = "";

  if (draftIn && finIn) {
    useRevise = false;
    singleText = normalizeCharLockStageReplyText(finIn || draftIn);
  } else {
    singleText = normalizeCharLockStageReplyText(typingRaw);
  }

  const hasSubstantive =
    hasLeadIn ||
    charLockQuizListIsActive(questionsList, lockMode) ||
    Boolean(draftIn && finIn) ||
    Boolean(singleText);
  if (!hasSubstantive) return;

  const pinForSession = String(o.expectedPin || "")
    .trim()
    .replace(/\s+/g, " ");
  charLockSession = {
    typingText: singleText,
    typingDraft: draft,
    typingFinal: fin,
    leadInReaction: hasLeadIn ? leadInReaction : null,
    expectedPin: pinForSession,
    pinHint: String(o.pinHint || "").trim(),
    charName: nm,
    charAvatarUrl: url,
    questionsList,
    quizIdx: 0,
    chatAfterQuiz,
    lockMode,
    charQuizPickBusy: false,
    flowPhase: hasLeadIn ? "leadIn" : "intro",
    quizAnswers: [],
    pinWrongAttempts: 0,
    pinWrongGuesses: [],
    exitKind: "",
    hadLockChat: false,
    modelOfflineHint: null,
    modelCharLockRelease: false
  };

  charLockUseRevise = useRevise;
  charLockDraft = draft;
  charLockFinal = fin;
  charLockTypingTarget = singleText;
  charLockTypingIdx = 0;
  charLockReviseIdx = 0;
  charLockPhase = useRevise ? "draft" : "single";
  charLockPreviewStep = 0;

  const nameEl = document.getElementById("char-lock-name");
  if (nameEl) nameEl.textContent = nm;
  const img = document.getElementById("char-lock-avatar-img");
  const fb = document.getElementById("char-lock-avatar-fallback");
  const ch = nm.trim().slice(0, 1) || "?";
  if (img && fb) {
    if (url) {
      img.src = url;
      img.classList.remove("is-hidden");
      fb.classList.add("is-hidden");
      fb.textContent = ch;
    } else {
      img.removeAttribute("src");
      img.classList.add("is-hidden");
      fb.classList.remove("is-hidden");
      fb.textContent = ch;
    }
  }
  const exitBtn0 = document.getElementById("char-lock-exit-btn");
  if (exitBtn0) exitBtn0.hidden = false;
  charLockSyncLockTopbarUi();
  charLockCloseExitSheet();
  const st0 = document.getElementById("char-lock-status");
  const hint0 = document.getElementById("char-lock-typing-hint");
  const pinEl0 = document.getElementById("char-lock-pin-input");
  charLockStopStageCompose();
  const tx0 = document.getElementById("char-lock-typing-text");
  const caret0 = document.getElementById("char-lock-typing-caret");

  const skipIntro =
    charLockQuizListIsActive(questionsList, lockMode) &&
    !useRevise &&
    !String(singleText || "").trim() &&
    !hasLeadIn;
  if (skipIntro) {
    charLockSession.flowPhase = "quiz";
    charLockPreviewStep = 1;
    charLockPhase = "idle";
    charLockTypingTarget = "";
    if (st0) {
      st0.textContent = `第 1 / ${questionsList.length} 题`;
    }
    if (hint0) {
      hint0.textContent = charLockQuizPickHintForMode();
    }
    if (pinEl0 && pinEl0 instanceof HTMLInputElement) {
      pinEl0.placeholder = CHAR_LOCK_PIN_INPUT_PLACEHOLDER_DEFAULT;
    }
    if (tx0) tx0.textContent = "";
    caret0?.classList.remove("char-lock-typing-caret--blink");
    charLockSetStageDeleting(false);
    charLockOpenQuestionLayerFromList();
    root.classList.add("is-open");
    root.setAttribute("aria-hidden", "false");
    syncCharLockScreenBodyState(true);
    charLockSyncSkipTypingBtn();
    return;
  }

  charLockSetTypingStatusUi();
  if (pinEl0 && pinEl0 instanceof HTMLInputElement) {
    pinEl0.placeholder = CHAR_LOCK_PIN_INPUT_PLACEHOLDER_DEFAULT;
  }
  if (tx0) tx0.textContent = "";
  caret0?.classList.add("char-lock-typing-caret--blink");
  charLockSetStageDeleting(false);
  charLockCloseQuestionLayer();

  root.classList.add("is-open");
  root.setAttribute("aria-hidden", "false");
  syncCharLockScreenBodyState(true);
  charLockSyncSkipTypingBtn();
  if (hasLeadIn) {
    charLockUseRevise = false;
    charLockPhase = "idle";
    charLockTypingTarget = "";
    charLockTypingIdx = 0;
    charLockStartLeadInPhase();
    return;
  }
  charLockTypingTimerId = window.setTimeout(scheduleCharLockTypingTick, 280);
}

