/** @param {unknown} raw */
function extractOfflineDmProsePayloadFromRecord(raw) {
  if (!raw || typeof raw !== "object") return null;
  const r = /** @type {Record<string, unknown>} */ (raw);
  const { charPov, userPov } = resolveThreadOfflineDmCharUserPov({
    offlineDmPov: r.offlineDmPov ?? r.pov,
    offlineDmCharPov: r.offlineDmCharPov ?? r.charPov,
    offlineDmUserPov: r.offlineDmUserPov ?? r.userPov
  });
  return buildOfflineDmProsePayload(
    r.offlineDmProseStyle ?? r.proseStyle,
    r.offlineDmLength ?? r.length,
    charPov,
    userPov,
    r.offlineDmProseStyleText ?? r.proseStyleText ?? r.styleCustom ?? r.styleText,
    r.offlineDmLengthText ?? r.lengthText ?? r.lengthCustom,
    r.offlineDmPovText ?? r.povText ?? r.povCustom,
    true
  );
}

/** @param {unknown} raw @returns {{ id: string, name: string, body: ReturnType<typeof extractOfflineDmProsePayloadFromRecord> } | null} */
function normalizeOfflineDmProsePresetImportEntry(raw) {
  if (!raw || typeof raw !== "object") return null;
  const r = /** @type {Record<string, unknown>} */ (raw);
  const body = extractOfflineDmProsePayloadFromRecord(r);
  if (!body) return null;
  const name = String(r.name || r.title || "").trim().slice(0, 80) || "导入预设";
  const id = String(r.id || "").trim() || newOfflineDmProsePresetId();
  return { id, name, body };
}

/** @param {unknown[]} arr */
function mergeOfflineDmProsePresetsFromParsedArray(arr) {
  const incoming = [];
  for (const item of arr) {
    const row = normalizeOfflineDmProsePresetImportEntry(item);
    if (row) incoming.push(row);
  }
  if (!incoming.length) return { ok: false, err: "未识别到文风预设" };
  let presets = readOfflineDmProsePresetsFromKv().filter((x) => x && typeof x === "object" && String(x.id || "").trim());
  const room = OFFLINE_DM_PROSE_PRESETS_CAP - presets.length;
  if (room <= 0) {
    return { ok: false, err: `预设已满 ${OFFLINE_DM_PROSE_PRESETS_CAP} 条，请先删除` };
  }
  const take = incoming.slice(0, room);
  if (take.length < incoming.length) {
    showToast(`仅导入前 ${take.length} 条（已达上限）`);
  }
  for (const row of take) {
    presets.push({
      id: row.id,
      name: row.name,
      updatedAt: Date.now(),
      ...row.body
    });
  }
  writeOfflineDmProsePresetsToKv(presets);
  syncChatOfflineProseGlobalPresetSelect(take.length === 1 ? take[0].id : "");
  return { ok: true, mode: "presets", count: take.length };
}

/** @param {unknown} obj */
function applyOfflineDmProseSnippetFromParsed(obj) {
  if (typeof obj === "string") {
    const payload = buildOfflineDmProsePayload("", "", "", "", obj, "", "", true);
    if (!payload) return { ok: false, err: "内容为空" };
    applyOfflineDmProsePresetPayloadToForm(payload);
    return { ok: true, mode: "form" };
  }
  if (Array.isArray(obj)) {
    return mergeOfflineDmProsePresetsFromParsedArray(obj);
  }
  if (!obj || typeof obj !== "object") return { ok: false, err: "无效数据" };
  const o = /** @type {Record<string, unknown>} */ (obj);
  if (typeof o.text === "string" || typeof o.content === "string") {
    return applyOfflineDmProseSnippetFromParsed(typeof o.text === "string" ? o.text : o.content);
  }
  if (Array.isArray(o.presets)) {
    return mergeOfflineDmProsePresetsFromParsedArray(o.presets);
  }
  if (o.name != null && normalizeOfflineDmProsePresetImportEntry(o)) {
    return mergeOfflineDmProsePresetsFromParsedArray([o]);
  }
  const payload = extractOfflineDmProsePayloadFromRecord(o);
  if (payload) {
    applyOfflineDmProsePresetPayloadToForm(payload);
    return { ok: true, mode: "form" };
  }
  return { ok: false, err: "无法识别的 JSON 结构" };
}

async function importOfflineDmProseFromDocxArrayBuffer(buf) {
  const mammoth = /** @type {{ extractRawText?: (o: { arrayBuffer: ArrayBuffer }) => Promise<{ value: string }> }} */ (
    window.mammoth
  );
  if (!mammoth || typeof mammoth.extractRawText !== "function") {
    return { ok: false, err: "Word 解析库未加载" };
  }
  try {
    const res = await mammoth.extractRawText({ arrayBuffer: buf });
    return applyOfflineDmProseSnippetFromParsed(String(res?.value || "").replace(/\u00a0/g, " "));
  } catch {
    return { ok: false, err: "无法解析 docx" };
  }
}

