function saveThreadImageStyleSheetFromForm(offline) {
  const sel = document.getElementById(
    offline ? "chat-offline-imgstyle-preset-select" : "chat-detail-imgstyle-preset-select"
  );
  const ta = document.getElementById(offline ? "chat-offline-imgstyle-ta" : "chat-detail-imgstyle-ta");
  const v = sel instanceof HTMLSelectElement ? String(sel.value || "").trim() : "";
  const text = ta instanceof HTMLTextAreaElement ? ta.value.trim().slice(0, 2000) : "";
  if (
    !patchActiveThread((t) => {
      if (offline) {
        if (!v) {
          delete t.chatThreadOfflineImageStylePresetId;
          delete t.chatThreadOfflineImageStylePromptCustom;
          return;
        }
        if (v === CHAT_THREAD_IMAGE_STYLE_PRESET_CUSTOM) {
          if (text) {
            t.chatThreadOfflineImageStylePromptCustom = text;
            t.chatThreadOfflineImageStylePresetId = CHAT_THREAD_IMAGE_STYLE_PRESET_CUSTOM;
          } else {
            delete t.chatThreadOfflineImageStylePromptCustom;
            delete t.chatThreadOfflineImageStylePresetId;
          }
          return;
        }
        t.chatThreadOfflineImageStylePresetId = v;
        delete t.chatThreadOfflineImageStylePromptCustom;
        return;
      }
      if (!v) {
        delete t.chatThreadImageStylePresetId;
        return;
      }
      if (v === CHAT_THREAD_IMAGE_STYLE_PRESET_CUSTOM) {
        if (text) {
          t.chatThreadImageStylePromptCustom = text;
          t.chatThreadImageStylePresetId = CHAT_THREAD_IMAGE_STYLE_PRESET_CUSTOM;
        } else {
          delete t.chatThreadImageStylePromptCustom;
          delete t.chatThreadImageStylePresetId;
        }
        return;
      }
      t.chatThreadImageStylePresetId = v;
    })
  ) {
    showToast("无法保存");
    return;
  }
  if (offline) closeChatOfflineImageStyleSheet();
  else closeChatDetailImageStyleSheet();
  syncChatThreadDetailPanelPlaceholders();
  if (!v) showToast("已保存：跟随全局");
  else if (v === CHAT_THREAD_IMAGE_STYLE_PRESET_CUSTOM) {
    showToast(text ? (offline ? "已保存：线下自定义后缀" : "已保存：自定义后缀") : "已清空，退回跟随全局");
  } else showToast("已保存：使用该预设");
}

