function persistChatOfflineProseFromForm() {
  const payload = captureOfflineDmProsePresetPayloadFromForm();
  const ok = patchActiveThread((t) => {
    const style = payload.offlineDmProseStyle || "natural";
    const len = payload.offlineDmLength || "medium";
    const charPov = normalizeOfflineDmPovPerson(payload.offlineDmCharPov, OFFLINE_DM_DEFAULT_CHAR_POV);
    const userPov = normalizeOfflineDmPovPerson(payload.offlineDmUserPov, OFFLINE_DM_DEFAULT_USER_POV);
    if (style === "sparse" || style === "literary" || style === "playful") t.offlineDmProseStyle = style;
    else delete t.offlineDmProseStyle;
    if (len === "short" || len === "long" || len === "xlarge") t.offlineDmLength = len;
    else delete t.offlineDmLength;
    if (charPov !== OFFLINE_DM_DEFAULT_CHAR_POV) t.offlineDmCharPov = charPov;
    else delete t.offlineDmCharPov;
    if (userPov !== OFFLINE_DM_DEFAULT_USER_POV) t.offlineDmUserPov = userPov;
    else delete t.offlineDmUserPov;
    if (charPov === "third" && userPov === "third") t.offlineDmPov = "mixed_narrator";
    else if (charPov === "first" && userPov === "second") t.offlineDmPov = "immersive_you";
    else delete t.offlineDmPov;
    const styleT = payload.offlineDmProseStyleText || "";
    const lenT = payload.offlineDmLengthText || "";
    const povT = payload.offlineDmPovText || "";
    if (styleT) t.offlineDmProseStyleText = styleT;
    else delete t.offlineDmProseStyleText;
    if (lenT) t.offlineDmLengthText = lenT;
    else delete t.offlineDmLengthText;
    if (povT) t.offlineDmPovText = povT;
    else delete t.offlineDmPovText;
  });
  if (!ok) {
    showToast("无法保存");
    return;
  }
  closeChatOfflineProseSheet();
  showToast("线下文风已保存");
}

