function sendChatTextImageFromSheet() {
  const ta = document.getElementById("chat-image-desc-input");
  const raw = ta && ta instanceof HTMLTextAreaElement ? String(ta.value || "").trim() : "";
  if (!raw) {
    showToast("先写一下画面描述");
    return;
  }
  reconcileActiveThreadRef();
  const ref = readChatActiveThreadRef();
  if (!ref.threadId) {
    showChatThreadUnavailableToast("missing-ref");
    return;
  }
  try {
    const th = readActiveThread();
    const descApiGen = isThreadDescImageApiGenEnabled(th) && isSessionImageGenConfigured();
    const log = readChatLog();
    const row = {
      role: "user",
      at: Date.now(),
      content: "",
      image: { desc: raw.slice(0, 4000) }
    };
    if (descApiGen) {
      row.image.scenePrompt = raw.slice(0, 3500);
      row.image.imageGenPending = true;
      applySessionImageSubjectOnRow(row, th, raw, log, null);
    }
    tagOutgoingChatDmSurfaceIfOffline(row);
    log.push(row);
    saveChatLog(log);
    if (descApiGen) kickoffPendingSessionImageGen(log, ref, log.length - 1);
    if (ta instanceof HTMLTextAreaElement) ta.value = "";
    closeChatImageSheet();
    scheduleRenderChatMessagesAfterUserSend();
    scheduleChatContextTokenLabelUpdate();
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    showToast(`发送失败：${msg.slice(0, 60)}`);
  }
}

