async function sendStickerToChatAsyncInner(p) {
  reconcileActiveThreadRef();
  if (!readChatActiveThreadRef().threadId) {
    showChatThreadUnavailableToast("missing-ref");
    return;
  }
  let url = sanitizeStickerUrl(p?.url);
  if (!url) {
    showToast("表情 URL 无效");
    return;
  }
  const description = String(p?.description || p?.desc || "").trim().slice(0, 40);
  if (!description) {
    showToast("表情包需要描述");
    return;
  }
  if (/^data:image\//i.test(url) && url.length >= STICKER_CHAT_SHRINK_DATAURL_MIN_CHARS) {
    try {
      url = await shrinkDataUrlWithCanvas(url, 480, 0.82);
    } catch (_) {
      /* 保留原图 */
    }
  }
  const log = readChatLog();
  const row = {
    role: "user",
    at: Date.now(),
    content: `【表情包：${description}】`,
    sticker: { url, description }
  };
  tagOutgoingChatDmSurfaceIfOffline(row);
  log.push(row);
  saveChatLog(log);
  scheduleRenderChatMessagesAfterUserSend();
  scheduleChatContextTokenLabelUpdate();
}

function sendStickerToChatAsync(p) {
  stickerChatSendChain = stickerChatSendChain
    .then(() => sendStickerToChatAsyncInner(p))
    .catch(() => {});
}

