function importStickersFromLegacyArray(arr, categoryOverride) {
  if (!Array.isArray(arr)) return { ok: 0, fail: 0 };
  const { store, bucket, dirty } = ensureStickerGlobalBucket();
  if (dirty) writeStickerStore(store);
  let ok = 0;
  let fail = 0;
  for (const row of arr) {
    if (!row || typeof row !== "object") {
      fail++;
      continue;
    }
    const url = sanitizeStickerUrl(row.url);
    const description = String(row.description || row.desc || "").trim().slice(0, 40);
    const category = String(categoryOverride || row.category || "默认").trim().slice(0, 20) || "默认";
    if (!url || !description) {
      fail++;
      continue;
    }
    if (pushStickerIntoBucketItems(bucket, { url, description, category })) ok++;
    else fail++;
  }
  writeStickerStore(store);
  refreshStickerPickerUi();
  return { ok, fail };
}

function parseStickerBatchUrlLines(raw) {
  const text = String(raw || "");
  const lines = text.split(/[\n,，;；]/);
  /** @type {Array<{ url: string, description: string }>} */
  const out = [];
  for (const l of lines) {
    const line = String(l || "").trim();
    if (!line) continue;
    let description = "";
    let url = "";
    const urlMatch = line.match(/(https?:\/\/\S+)/i) || line.match(/(\/\/\S+\.\S+)/);
    if (urlMatch) {
      url = urlMatch[1];
      if (url.startsWith("//")) url = "https:" + url;
      const ui = line.indexOf(urlMatch[1]);
      const beforeUrl = ui >= 0 ? line.substring(0, ui) : "";
      const afterUrl = ui >= 0 ? line.substring(ui + urlMatch[1].length) : "";
      description = beforeUrl.replace(/[\s:：,，\-]+$/, "").trim();
      if (!description) {
        // 兼容：URL 在前，描述在后（例如：URL 空格 描述）
        const tail = String(afterUrl || "").replace(/^[\s:：,，\-]+/, "").trim();
        // 防呆：避免把 “http/https/第二段链接” 当成描述
        if (tail && !/^https?:\/\//i.test(tail) && !/^\/\//.test(tail)) {
          description = tail;
        }
      }
      if (!description) {
        try {
          const u = new URL(url);
          const segs = u.pathname.split("/");
          let filename = segs[segs.length - 1] || "表情";
          filename = filename.replace(/\.[^/.]+$/, "");
          description = decodeURIComponent(filename) || "表情";
        } catch (_) {
          description = "表情";
        }
      }
    } else {
      const colonMatch = line.match(/^(.+?)[：:](.+)$/);
      if (colonMatch) {
        description = String(colonMatch[1] || "").trim();
        url = String(colonMatch[2] || "").trim();
        if (url.startsWith("//")) url = "https:" + url;
      }
    }
    url = sanitizeStickerUrl(url);
    description = String(description || "").trim().slice(0, 40);
    if (!url || !description) continue;
    out.push({ url, description });
  }
  return out;
}

/** 文字→语音（伪装）时长估算：约 4 字/秒，最短 1 秒，最长 59 秒。 */
function estimateVoiceSeconds(text) {
  const t = String(text || "");
  const n = t.replace(/\s+/g, "").length;
  const raw = Math.round(n / 4);
  return Math.max(1, Math.min(59, raw || 1));
}

