document.querySelectorAll("#chat-more-drawer .drawer-item").forEach((btn) => {
  btn.addEventListener("click", (e) => {
    const el = /** @type {HTMLElement} */ (e.currentTarget);
    const action = String(el.dataset.action || "").trim();
    if (!action) return;
    const offlineOnlyTextToastActions = new Set([
      "voice",
      "photo",
      "sticker",
      "redpack",
      "call-audio",
      "call-video"
    ]);
    if (offlineOnlyTextToastActions.has(action) && getActiveChatDmSurfaceForContext() === "offline") {
      showToast("线下晤面仅支持当面文字剧情");
      closeChatMoreSheet();
      return;
    }
    if (action === "voice") {
      chatComposerSendAsVoice = !chatComposerSendAsVoice;
      applyChatComposerVoiceModeUi();
      showToast(chatComposerSendAsVoice ? "语音输入：开启（文字将伪装成语音）" : "语音输入：关闭");
      closeChatMoreSheet();
      window.requestAnimationFrame(() => document.getElementById("chat-input")?.focus());
      return;
    }
    if (action === "lock-char") {
      if (getActiveChatDmSurfaceForContext() === "offline") {
        showToast("线下晤面请返回即时消息后再锁 Ta 手机");
        closeChatMoreSheet();
        return;
      }
      const thLc = readActiveThread();
      if (!thLc || thLc.kind === "group") {
        showToast("仅单聊密谈可锁 Ta 手机");
        closeChatMoreSheet();
        return;
      }
      closeChatMoreSheet();
      openUserLockCharSheet();
      return;
    }
    if (action === "redpack") {
      openRedpackSheet();
      closeChatMoreSheet();
      return;
    }
    if (action === "sticker") {
      openStickerSheet("pick");
      closeChatMoreSheet();
      return;
    }
    if (action === "photo") {
      openChatImageSheet();
      closeChatMoreSheet();
      return;
    }
    if (action === "call-audio") {
      minimaxPrimeTtsAudioOnUserGesture();
      openChatCallScreen("audio");
      closeChatMoreSheet();
      return;
    }
    if (action === "call-video") {
      minimaxPrimeTtsAudioOnUserGesture();
      openChatCallScreen("video");
      closeChatMoreSheet();
      return;
    }
    if (action === "moments-char-post") {
      const thMp = readActiveThread();
      if (!thMp || thMp.kind === "group") {
        showToast("仅单聊密谈可让当前角色发朋友圈");
        closeChatMoreSheet();
        return;
      }
      const cid = String(thMp.charId || "").trim();
      if (!cid) {
        showToast("未绑定角色");
        closeChatMoreSheet();
        return;
      }
      closeChatMoreSheet();
      const mpMask = String(getActiveMaskIdForInbox() || "").trim();
      void publishCharMomentFromAi(cid, {
        maskId: mpMask,
        switchToMoments: true,
        threadId: String(thMp.id || "").trim(),
        forcePost: true,
        notifySuccess: true,
        personaSlot: getThreadActivePersona(thMp)
      });
      return;
    }
    if (action === "theater") {
      window.XXJ_EXT?.openFromMore?.();
      return;
    }
    if (action === "persona-main" || action === "persona-alt") {
      const thPa = readActiveThread();
      const charPa = thPa?.charId ? getCharPersonaItemById(thPa.charId) : null;
      if (!charHasAltPersona(charPa)) {
        closeChatMoreSheet();
        return;
      }
      setThreadActivePersonaForChat(action === "persona-alt" ? "alt" : "main");
      closeChatMoreSheet();
      return;
    }
    if (action === "offline") {
      const th0 = readActiveThread();
      if (!th0) {
        showToast("没有可用的密谈");
        closeChatMoreSheet();
        return;
      }
      if (th0.kind === "group") {
        showToast("群聊请用即时消息");
        closeChatMoreSheet();
        return;
      }
      if (isThreadOnlineRomanceEnabled(th0)) {
        showToast("异地模式已开：仅线上互动");
        closeChatMoreSheet();
        return;
      }
      if (isThreadOfflineMeetSummaryMode(th0)) {
        closeChatMoreSheet();
        openChatOfflineMeetSummarySheet();
        return;
      }
      if (isChatOfflineScreenOpen()) {
        closeChatOfflineScreen({ finalizeOfflineSession: false });
        closeChatMoreSheet();
        showToast("已返回即时消息");
        return;
      }
      openChatOfflineScreen();
      closeChatMoreSheet();
      showToast("已进入线下");
      return;
    }
    const label = chatMoreActionLabels[action] || action;
    showToast(`${label} · 敬请期待`);
    closeChatMoreSheet();
  });
});

