document.getElementById("chat-offline-prose-import-file")?.addEventListener("change", (e) => {
  const inp = e.target;
  if (!(inp instanceof HTMLInputElement)) return;
  const f = inp.files?.[0];
  inp.value = "";
  if (!f) return;
  const lower = f.name.toLowerCase();
  const isJson = lower.endsWith(".json") || f.type === "application/json";
  const isDocx =
    lower.endsWith(".docx") ||
    f.type === "application/vnd.openxmlformats-officedocument.wordprocessingml.document";
  const isText =
    lower.endsWith(".txt") ||
    lower.endsWith(".md") ||
    lower.endsWith(".markdown") ||
    f.type === "text/plain" ||
    f.type === "text/markdown";
  if (isJson) {
    const reader = new FileReader();
    reader.onload = () => {
      let obj;
      try {
        obj = JSON.parse(String(reader.result || ""));
      } catch {
        showToast("JSON 无法解析");
        return;
      }
      if (
        !window.confirm(
          "导入将填入下方表单，或合并进「全局文风预设」列表；不会自动保存本密谈。是否继续？"
        )
      ) {
        return;
      }
      const r = applyOfflineDmProseSnippetFromParsed(obj);
      if (!r.ok) {
        showToast(r.err || "导入失败");
        return;
      }
      if (r.mode === "presets") {
        showToast(`已导入 ${r.count} 条全局预设`);
      } else {
        showToast("已填入表单；请检查后点「保存」");
      }
    };
    reader.readAsText(f, "utf-8");
    return;
  }
  if (isDocx) {
    const reader = new FileReader();
    reader.onload = () => {
      const buf = reader.result;
      if (!(buf instanceof ArrayBuffer)) {
        showToast("读取失败");
        return;
      }
      void (async () => {
        if (
          !window.confirm(
            "将把 Word 正文填入「主控自定义 · 文风」。不自动保存本密谈。是否继续？"
          )
        ) {
          return;
        }
        const r = await importOfflineDmProseFromDocxArrayBuffer(buf);
        showToast(r.ok ? "已填入文风自定义；请检查后点「保存」" : r.err || "导入失败");
      })();
    };
    reader.readAsArrayBuffer(f);
    return;
  }
  if (isText) {
    const reader = new FileReader();
    reader.onload = () => {
      if (
        !window.confirm(
          "将把文本填入「主控自定义 · 文风」。不自动保存本密谈。是否继续？"
        )
      ) {
        return;
      }
      const r = applyOfflineDmProseSnippetFromParsed(String(reader.result || ""));
      showToast(r.ok ? "已填入文风自定义；请检查后点「保存」" : r.err || "文件为空");
    };
    reader.readAsText(f, "utf-8");
    return;
  }
  showToast("请选择 .json、.txt、.md 或 .docx");
});

