async function sendChatFromCallScreen() {
  const input = getChatCallInputEl();
  if (!(input instanceof HTMLTextAreaElement)) return;
  if (!isChatCallScreenOpen() || chatCallStage !== "connected") return;
  reconcileActiveThreadRef();
  if (!readChatActiveThreadRef().threadId) {
    showChatThreadUnavailableToast("missing-ref");
    return;
  }
  const tailWait = chatCallSessionLog[chatCallSessionLog.length - 1];
  if (tailWait && tailWait.role === "assistant" && tailWait.restoring) {
    showToast("对方正在回复…");
    return;
  }
  const composed = String(input.value || "").trim();
  const emptySend = !composed;
  // 与主聊天一致：非空仅记入会话，不请求模型；空输入再发送才调用 API 让对方开口。
  if (!emptySend) {
    chatCallSessionLog.push({ role: "user", text: composed, at: Date.now() });
    input.value = "";
    renderChatCallTranscript();
    return;
  }
  const lastCallBubble = chatLogLastBubbleMessage(chatCallSessionLog);
  if (lastCallBubble && lastCallBubble.role === "assistant" && !lastCallBubble.restoring) {
    openChatSendChoiceDialog();
    return;
  }
  await executeChatCallAssistantTurn({ emptySend: true });
}

