function bindWardDesktopIconPanelInteractions(panelId, scope) {
  document.getElementById(panelId)?.addEventListener("click", (e) => {
    const t = e.target;
    if (!(t instanceof Element)) return;
    const row = t.closest(".ward-desktop-icon-row");
    if (!row) return;
    const app = row.getAttribute("data-desktop-icon-app");
    if (!app) return;
    if (t.closest(".ward-desktop-icon-pick")) {
      row.querySelector(".ward-desktop-icon-file")?.click();
      return;
    }
    if (t.closest(".ward-desktop-icon-clear")) {
      if (!window.XXJ_DB) return;
      mutateDesktopAppIconsKv(scope, (pack) => {
        deleteDesktopDecorAppEntry(pack, app);
      });
      showToast(scope === "dock" ? `已清除 Dock「${app}」` : `已清除主屏「${app}」`);
    }
  });
  document.getElementById(panelId)?.addEventListener("change", (e) => {
    const t = e.target;
    if (!t || !(t instanceof HTMLInputElement) || !t.classList.contains("ward-desktop-icon-file")) return;
    const row = t.closest(".ward-desktop-icon-row");
    const app = row?.getAttribute("data-desktop-icon-app");
    const f = t.files && t.files[0];
    t.value = "";
    if (!app || !f) return;
    saveWardDesktopIconFromFile(app, f, scope);
  });
}
