document.getElementById("sticker-add-confirm")?.addEventListener("click", async () => {
  if (stickerAddIsProcessing) return;
  stickerAddIsProcessing = true;
  const catEl = document.getElementById("sticker-add-category");
  const category = catEl && catEl instanceof HTMLInputElement ? catEl.value.trim() : "";
  try {
    if (stickerAddMode === "url") {
      const urlEl = document.getElementById("sticker-add-url");
      const descEl = document.getElementById("sticker-add-desc-url");
      const urlRaw = urlEl && urlEl instanceof HTMLInputElement ? urlEl.value : "";
      const description = descEl && descEl instanceof HTMLInputElement ? descEl.value : "";
      const url = sanitizeStickerUrl(urlRaw);
      if (!description.trim()) {
        showToast("请填写描述");
        return;
      }
      if (!url) {
        showToast("URL 无效");
        return;
      }
      const ok = addStickerToStore({ url, description, category });
      if (ok) {
        showToast("已添加");
      } else {
        showToast("添加失败");
      }
      return;
    }
    if (stickerAddMode === "file") {
      const descEl = document.getElementById("sticker-add-desc");
      const description = descEl && descEl instanceof HTMLInputElement ? descEl.value : "";
      if (!description.trim()) {
        showToast("请填写描述");
        return;
      }
      if (!stickerAddSingleFile) {
        showToast("请先选择图片");
        return;
      }
      showToast("处理中…");
      const ok = await addStickerFromFile(stickerAddSingleFile, description, category);
      if (ok) {
        showToast("已添加");
      } else {
        showToast("添加失败");
      }
      return;
    }
    if (stickerAddMode === "batch") {
      const files = stickerAddBatchFiles.slice();
      if (!files.length) {
        showToast("请先选择图片");
        return;
      }
      showToast(`批量处理中：${files.length} 张…`);
      const { store, bucket, dirty } = ensureStickerGlobalBucket();
      if (dirty) writeStickerStore(store);
      let okN = 0;
      for (const f of files) {
        const base = String(f?.name || "").replace(/\.[^/.]+$/, "").trim();
        const name = base || "表情";
        try {
          const dataUrl = await readImageFileAsDataUrl(f);
          const shrunk = await shrinkDataUrlWithCanvas(String(dataUrl || ""), 512, 0.82);
          if (pushStickerIntoBucketItems(bucket, { url: shrunk, description: name, category })) okN++;
        } catch (_) {}
      }
      if (okN) {
        writeStickerStore(store);
        refreshStickerPickerUi();
      }
      showToast(okN ? `已添加 ${okN} 张` : "批量添加失败");
      return;
    }
    if (stickerAddMode === "batch_url") {
      const ta = document.getElementById("sticker-add-batch-url");
      const raw = ta && ta instanceof HTMLTextAreaElement ? ta.value : "";
      const parsed = parseStickerBatchUrlLines(raw);
      if (!parsed.length) {
        showToast("未解析到有效 URL");
        return;
      }
      const { store, bucket, dirty } = ensureStickerGlobalBucket();
      if (dirty) writeStickerStore(store);
      let ok = 0;
      for (const row of parsed) {
        if (pushStickerIntoBucketItems(bucket, { url: row.url, description: row.description, category })) ok++;
      }
      if (ok) {
        writeStickerStore(store);
        refreshStickerPickerUi();
      }
      showToast(ok ? `已导入 ${ok} 个` : "导入失败");
      return;
    }
  } finally {
    stickerAddIsProcessing = false;
  }
});

