function wireStickerJsonExportImport() {
  const onExportClick = () => {
    openStickerExportModal();
  };
  const onImportClick = (inputId) => () => {
    const inp = document.getElementById(inputId);
    if (inp && inp instanceof HTMLInputElement) inp.click();
  };
  /** @param {Event} e */
  const onImportFileChange = (e) => {
    const inp = e.currentTarget;
    if (!(inp instanceof HTMLInputElement)) return;
    const file = inp.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      try {
        const text = String(reader.result || "");
        const parsed = JSON.parse(text);
        const catEl = document.getElementById("sticker-category-input");
        const cat = catEl && catEl instanceof HTMLInputElement ? catEl.value : "";
        const r = importStickersFromLegacyArray(parsed, cat);
        showToast(r.ok ? `已导入 ${r.ok} 个` : "未导入到有效表情");
      } catch (_) {
        showToast("导入失败：JSON 格式错误");
      } finally {
        inp.value = "";
      }
    };
    reader.readAsText(file, "UTF-8");
  };
  for (const id of ["sticker-export-json", "sticker-sheet-export-json"]) {
    document.getElementById(id)?.addEventListener("click", onExportClick);
  }
  for (const [btnId, inputId] of [
    ["sticker-import-json", "sticker-import-input"],
    ["sticker-sheet-import-json", "sticker-sheet-import-input"]
  ]) {
    document.getElementById(btnId)?.addEventListener("click", onImportClick(inputId));
  }
  for (const inputId of ["sticker-import-input", "sticker-sheet-import-input"]) {
    document.getElementById(inputId)?.addEventListener("change", onImportFileChange);
  }
}
wireStickerJsonExportImport();

