function sanitizeRedpackAmount(v) {
  const s = String(v ?? "").trim().replace(/[^\d.]/g, "");
  const n = Number.parseFloat(s);
  if (!Number.isFinite(n) || n <= 0) return "8.88";
  const fixed = Math.round(n * 100) / 100;
  return fixed.toFixed(2);
}

function makeRedpackId() {
  const a = Math.random().toString(16).slice(2, 10);
  const b = Date.now().toString(16).slice(-6);
  return `rp_${b}_${a}`;
}

/**
 * @param {string} replyText
 * @returns {"claimed" | "returned" | null}
 */
function detectRedpackDecisionFromAssistant(replyText) {
  const s = String(replyText || "");
  // 更保守：优先匹配“退回/不收/不领”
  if (
    /(退回|退了|退给你|退给妳|退回去|退回去了|退回给你|退回给妳|不收|不领|不拿|别发|不要红包|还你|还给你|返还|退钱|我退回了|我给你退回)/i.test(
      s
    ) ||
    // 日/英兜底
    /(返す|返した|返します|受け取らない|受け取れない|辞退|return(ed)?|refund|decline)/i.test(s)
  )
    return "returned";
  if (
    /(我领了|领了|已领取|我收下了|收下了|收下|我收了|收了|收到了|谢谢红包|红包我拿了|我就收下|我拿了|我就领了|我先领了|我这就领)/i.test(
      s
    ) ||
    // 日/英兜底
    /(受け取(っ|り)|もら(っ|い)|受領|received|accept(ed)?)/i.test(s)
  )
    return "claimed";
  return null;
}

/**
 * 将最近一条“待处理”的红包标记为 claimed / returned
 * @param {ReturnType<typeof readChatLog>} log
 * @param {"claimed" | "returned"} decision
 */
function applyRedpackDecisionToLatest(log, decision) {
  if (!Array.isArray(log) || !log.length) return;
  for (let i = log.length - 1; i >= 0; i--) {
    const m = log[i];
    if (!m || typeof m !== "object") continue;
    if (m.role !== "user") continue;
    const raw = String(m.content || "");
    const rp0 = m.redpack && typeof m.redpack === "object" ? m.redpack : null;
    const segs = expandPartsAndTranslationsForInlineRedpack(
      raw
        .split(/\|\|\|/)
        .map((s) => String(s).trim())
        .filter(Boolean),
      []
    ).parts;
    let rpFromText = null;
    for (const seg of segs.length ? segs : [raw]) {
      rpFromText = parseRedpackMessageText(seg);
      if (rpFromText) break;
    }
    const rp = rp0 || (rpFromText ? { id: makeRedpackId(), amt: rpFromText.amt, note: rpFromText.note, status: "sent" } : null);
    if (!rp) continue;
    if (!rp.id) rp.id = makeRedpackId();
    const st = String(rp.status || "sent");
    if (st !== "sent") continue;
    rp.status = decision;
    // 写回，确保渲染能读到状态
    m.redpack = rp;
    // 钱包：对方退回你发的红包 → 退款
    if (decision === "returned") {
      const cents = parseMoneyToCents(rp.amt);
      if (adjustWalletCentsBy(cents)) {
        pushWalletBill({ type: "红包退款", note: String(rp.note || "").trim(), deltaCents: cents });
      }
    }
    // 插入灰色系统提示（微信样式）
    try {
      const at = Date.now();
      const notice = {
        role: "notice",
        kind: "redpack",
        action: decision,
        by: "char",
        at,
        content: "",
        redpackId: String(rp.id || "")
      };
      log.splice(i + 1, 0, notice);
    } catch (_) {
      /* ignore */
    }
    return;
  }
}

/**
 * 用户处理“对方发来的红包”：把该 assistant 红包标为 claimed/returned，并插入灰色提示
 * @param {ReturnType<typeof readChatLog>} log
 * @param {number} msgIdx
 * @param {number} segIdx 红包所在段（-1 表示不确定，走兜底）
 * @param {"claimed" | "returned"} decision
 */
function applyUserDecisionToCharRedpackAt(log, msgIdx, segIdx, decision) {
  const i = Number(msgIdx);
  if (!Array.isArray(log) || !Number.isFinite(i) || i < 0 || i >= log.length) return false;
  const m = log[i];
  if (!m || typeof m !== "object" || m.role !== "assistant") return false;
  const rp0 = m.redpack && typeof m.redpack === "object" ? m.redpack : null;
  // 兼容：红包不在第 1 段时，整条 content 不以【红包】开头，会导致解析失败
  const parts = String(m.content ?? "")
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean);
  const expandedParts = expandPartsAndTranslationsForInlineRedpack(parts.length ? parts : [String(m.content ?? "")], [])
    .parts;
  const si = Number.isFinite(Number(segIdx)) ? Math.floor(Number(segIdx)) : -1;
  const rpIdx = findRedpackPartIndex(expandedParts);
  const segText = String(
    (si >= 0 && si < expandedParts.length ? expandedParts[si] : "") ||
      (rpIdx >= 0 ? expandedParts[rpIdx] : "") ||
      ""
  ).trim();
  const rpFromSeg = segText ? parseRedpackMessageText(segText) : null;
  const rp =
    rp0 ||
    (rpFromSeg ? { id: makeRedpackId(), amt: rpFromSeg.amt, note: rpFromSeg.note, status: "sent" } : null);
  if (!rp) return false;
  if (!rp.id) rp.id = makeRedpackId();
  const st = String(rp.status || "sent");
  if (st !== "sent") return false;
  rp.status = decision;
  m.redpack = rp;
  // 钱包：你领取对方红包 → 入账
  if (decision === "claimed") {
    const cents = parseMoneyToCents(rp.amt);
    if (adjustWalletCentsBy(cents)) {
      pushWalletBill({ type: "收红包", note: String(rp.note || "").trim(), deltaCents: cents });
    }
  }
  log.splice(i + 1, 0, {
    role: "notice",
    kind: "redpack",
    action: decision,
    by: "user",
    at: Date.now(),
    content: "",
    redpackId: String(rp.id || "")
  });
  return true;
}

function ensureRedpackNoticesInLog(log) {
  if (!Array.isArray(log) || !log.length) return false;
  let changed = false;
  for (let i = 0; i < log.length; i++) {
    const m = log[i];
    if (!m || typeof m !== "object" || (m.role !== "user" && m.role !== "assistant")) continue;
    const rp = m.redpack && typeof m.redpack === "object" ? m.redpack : null;
    if (!rp) continue;
    const st = String(rp.status || "sent");
    if (st !== "claimed" && st !== "returned") continue;
    if (!rp.id) {
      rp.id = makeRedpackId();
      m.redpack = rp;
      changed = true;
    }
    const next = log[i + 1];
    const has =
      next &&
      typeof next === "object" &&
      next.role === "notice" &&
      String(next.kind || "") === "redpack" &&
      String(next.redpackId || "") === String(rp.id || "");
    if (has) continue;
    log.splice(i + 1, 0, {
      role: "notice",
      kind: "redpack",
      action: st,
      by: m.role === "assistant" ? "user" : "char",
      at: Number.isFinite(Number(m.at)) ? Number(m.at) : Date.now(),
      content: "",
      redpackId: String(rp.id || "")
    });
    changed = true;
    i++;
  }
  return changed;
}

/** 移除聊天中 assistant.restoring 占位；默认仅删空正文，`includeWithContent` 时连流式预览行一并删。 */
function removeChatRestoringPlaceholders(log, opts) {
  if (!Array.isArray(log) || !log.length) return;
  const includeWithContent = Boolean(opts && opts.includeWithContent);
  for (let i = log.length - 1; i >= 0; i--) {
    const m = log[i];
    if (
      m &&
      typeof m === "object" &&
      m.role === "assistant" &&
      m.restoring &&
      (includeWithContent || !String(m.content || "").trim())
    ) {
      log.splice(i, 1);
    }
  }
}

/** 替换落盘后：清 assistant 上的 restoring 标记（不删行）。 */
function clearAssistantRestoringFlagsInLog(log) {
  if (!Array.isArray(log)) return;
  for (const m of log) {
    if (m && typeof m === "object" && m.role === "assistant") {
      clearAssistantEntryRestoringUiFlags(m);
    }
  }
}

/**
 * 马甲切换条 + 计算 entry 插入下标（重回 / 重 roll 共用）。
 * @param {unknown[]} log
 * @param {number} insertAt
 * @param {string} foldSlot
 */
function resolveAssistantEntryInsertAt(log, insertAt, foldSlot) {
  const base = Math.min(Math.max(0, Math.floor(Number(insertAt)) || 0), log.length);
  if (foldSlot !== "main" && foldSlot !== "alt") return base;
  const foldBefore = base > 0 ? log[base - 1] : null;
  if (
    foldBefore &&
    isPersonaFoldBoundaryMessage(foldBefore) &&
    String(foldBefore.personaFoldBoundary) === foldSlot
  ) {
    return base;
  }
  if (
    base < log.length &&
    isPersonaFoldBoundaryMessage(log[base]) &&
    String(log[base].personaFoldBoundary) === foldSlot
  ) {
    return base + 1;
  }
  log.splice(base, 0, makePersonaFoldBoundaryRow(foldSlot));
  return base + 1;
}

/**
 * 在 entry 后插入 char 撤回 notice（顺序对齐 prefix + entry + recalls + suffix）。
 * @param {unknown[]} log
 * @param {unknown} entry
 * @param {unknown[]} recalls
 * @param {number} at
 * @param {number} fallbackAt
 */
function insertCharRecallsAfterLogEntry(log, entry, recalls, at, fallbackAt) {
  if (!Array.isArray(log) || !Array.isArray(recalls) || !recalls.length) return;
  let pos =
    entry && typeof entry === "object" && log.indexOf(entry) >= 0
      ? log.indexOf(entry) + 1
      : Math.min(Math.max(0, Math.floor(Number(fallbackAt)) || 0), log.length);
  const adj = log[pos];
  if (
    entry &&
    adj &&
    typeof adj === "object" &&
    adj.role === "assistant" &&
    adj !== entry &&
    adj.sticker &&
    !String(adj.content || "").trim()
  ) {
    pos++;
  }
  for (const r of recalls) {
    log.splice(pos, 0, {
      role: "notice",
      kind: "recall_char",
      at,
      content: "",
      recalledContent: r.recalledContent,
      innerVoice: r.innerVoice,
      recalledTranslation: r.recalledTranslation
    });
    pos++;
  }
}

function isRedpackPeekOpen() {
  const root = document.getElementById("redpack-peek-sheet");
  return !!(root && !root.hidden);
}
function closeRedpackPeek() {
  const root = document.getElementById("redpack-peek-sheet");
  if (!root) return;
  if (redpackPeekCloseTimer) {
    window.clearTimeout(redpackPeekCloseTimer);
    redpackPeekCloseTimer = 0;
  }
  blurActiveElementInFixedSheet("#redpack-peek-sheet");
  root.classList.remove("is-open");
  root.setAttribute("aria-hidden", "true");
  redpackPeekCloseTimer = window.setTimeout(() => {
    root.hidden = true;
    redpackPeekCloseTimer = 0;
    syncChatScreenOverlayOpenClass();
    restoreViewportAfterChatFixedSheet();
  }, 180);
}
/**
 * @param {{ amt: string, note: string, noteTrans?: string, mode?: ("view" | "char-sent") }} p
 */
function openRedpackPeek(p) {
  const root = document.getElementById("redpack-peek-sheet");
  if (!root) return;
  if (redpackPeekCloseTimer) {
    window.clearTimeout(redpackPeekCloseTimer);
    redpackPeekCloseTimer = 0;
  }
  const amtEl = document.getElementById("redpack-peek-amt");
  const noteEl = document.getElementById("redpack-peek-note");
  const claimBtn = document.getElementById("redpack-peek-claim");
  const retBtn = document.getElementById("redpack-peek-return");
  const okBtn = document.getElementById("redpack-peek-ok");
  if (amtEl) amtEl.textContent = String(p.amt || "—");
  if (noteEl) {
    const note = String(p.note || "—");
    const nt = String(p.noteTrans || "").trim();
    noteEl.textContent = nt ? `${note}（${nt}）` : note;
  }
  const mode = String(p.mode || "view");
  if (claimBtn) claimBtn.hidden = mode !== "char-sent";
  if (retBtn) retBtn.hidden = mode !== "char-sent";
  if (okBtn) {
    okBtn.textContent = "知道了";
    okBtn.hidden = mode === "char-sent";
  }
  root.classList.remove("is-open");
  root.hidden = false;
  root.setAttribute("aria-hidden", "false");
  syncChatScreenOverlayOpenClass();
  void root.offsetWidth;
  window.requestAnimationFrame(() => {
    window.requestAnimationFrame(() => {
      root.classList.add("is-open");
      const focusEl =
        mode === "char-sent"
          ? document.getElementById("redpack-peek-claim")
          : document.getElementById("redpack-peek-ok");
      focusChatFixedSheetControl(focusEl);
    });
  });
}
function buildRedpackMessageText() {
  const amtEl = document.getElementById("redpack-amount-input");
  const noteEl = document.getElementById("redpack-note-input");
  const amt = sanitizeRedpackAmount(amtEl && amtEl instanceof HTMLInputElement ? amtEl.value : "8.88");
  const noteRaw = noteEl && noteEl instanceof HTMLInputElement ? noteEl.value : "恭喜发财";
  const note = String(noteRaw || "").trim() || "恭喜发财";
  return `【红包】¥${amt} ${note}`;
}

