/**
 * 生图 / 重绘：相片区域半透明遮罩 + 圆角提示条（与拍立得相纸风格一致）。
 * @param {HTMLElement} mount `.chat-photo-polaroid-inner` 或 `.chat-photo-polaroid-inner--desc`
 * @param {{ regen?: boolean }} [opts]
 */
function mountChatPhotoPolaroidPendingOverlay(mount, opts) {
  if (!(mount instanceof HTMLElement)) return;
  const regen = Boolean(opts?.regen);
  const label = regen ? "配图重绘中…" : "配图生成中…";
  mount.closest(".chat-photo-polaroid")?.classList.add("chat-photo-polaroid--pending");
  mount.classList.add("chat-photo-polaroid-mount--pending");
  const overlay = document.createElement("div");
  overlay.className = "chat-photo-polaroid-pending-overlay";
  overlay.setAttribute("role", "status");
  overlay.setAttribute("aria-live", "polite");
  overlay.setAttribute("aria-label", label);
  const chip = document.createElement("div");
  chip.className = "chat-photo-polaroid-pending-chip";
  const spin = document.createElement("span");
  spin.className = "chat-photo-polaroid-pending-spin";
  spin.setAttribute("aria-hidden", "true");
  const lab = document.createElement("span");
  lab.className = "chat-photo-polaroid-pending-label";
  lab.textContent = label;
  chip.append(spin, lab);
  overlay.appendChild(chip);
  mount.appendChild(overlay);
}

/**
 * 线下晤面：角色配图挂在正文气泡之后（同一消息 stack 内）。
 * @param {HTMLElement} stack
 * @param {unknown} m
 * @param {number} msgIdx
 * @param {string} [assistantParsedCharCap]
 */
function appendOfflineAssistantImageCardsBelowText(stack, m, msgIdx, assistantParsedCharCap) {
  if (!stack || !m || typeof m !== "object" || !m.image || typeof m.image !== "object") return;
  const imgUrl0 = String(m.image.url || "").trim();
  const charDescCap =
    String(m.image.desc || "").trim() || String(assistantParsedCharCap || "").trim();
  const photoUrl = sanitizeStickerUrl(imgUrl0);
  if (!charDescCap && !photoUrl) return;

  if (charDescCap && !photoUrl) {
    appendChatPhotoDescCardToStack(stack, {
      caption: String(charDescCap).trim(),
      stripMeta: true,
      pending: Boolean(m.image.imageGenPending),
      charDesc: true,
      seg: OFFLINE_CHAT_PHOTO_DOM_SEG
    });
    return;
  }
  if (!photoUrl) return;
  const omitInline = Boolean(m.image.omitInlineCaption);
  const cap = omitInline
    ? ""
    : String(m.image.desc || "").trim() || sanitizeCharImageCaptionMeta(charDescCap);
  const card = document.createElement("div");
  card.className = "chat-msg-card chat-msg-card--photo";
  card.setAttribute("role", "img");
  card.dataset.chatBubbleSeg = String(OFFLINE_CHAT_PHOTO_DOM_SEG);
  const photoPending = Boolean(m.image.imageGenPending);
  const photoPendingRegen = photoPending && Boolean(photoUrl);
  card.setAttribute(
    "aria-label",
    photoPending
      ? photoPendingRegen
        ? "图片：配图重绘中"
        : "图片：配图生成中"
      : cap
        ? `图片：${cap}`
        : "图片"
  );
  card.appendChild(
    buildChatPhotoCardShell({
      url: photoUrl,
      caption: cap,
      role: "assistant",
      msgIdx,
      pending: photoPending,
      pendingRegen: photoPendingRegen
    })
  );
  stack.appendChild(card);
}

/**
 * 聊天气泡里的照片：拍立得相纸 + 轻微倾角（与手帐/密谈气质统一）
 * @param {{ url: string, caption: string, role: string, msgIdx?: number, pending?: boolean, pendingRegen?: boolean }} p
 * @returns {HTMLDivElement}
 */
function buildChatPhotoCardShell(p) {
  const url = sanitizeStickerUrl(String(p.url || "").trim());
  const caption = String(p.caption || "").trim();
  const who = String(p.role || "") === "assistant" ? "assistant" : "user";
  const msgIdx = Number(p.msgIdx);

  const shell = document.createElement("div");
  shell.className = `chat-photo-polaroid chat-photo-polaroid--${who}`;

  const tape = document.createElement("span");
  tape.className = "chat-photo-polaroid-tape";
  tape.setAttribute("aria-hidden", "true");

  const gloss = document.createElement("span");
  gloss.className = "chat-photo-polaroid-gloss";
  gloss.setAttribute("aria-hidden", "true");

  const inner = document.createElement("div");
  inner.className = "chat-photo-polaroid-inner";
  const im = document.createElement("img");
  im.className = "chat-photo-polaroid-img";
  im.alt = caption || "照片";
  im.loading = "lazy";
  im.decoding = "async";
  applyChatImageUrlToElement(im, url);
  inner.appendChild(im);
  if (Number.isFinite(msgIdx) && msgIdx >= 0 && !p.pending) {
    shell.dataset.chatPhotoMsgIdx = String(msgIdx);
    shell.dataset.chatPhotoRole = who;
    inner.classList.add("chat-photo-polaroid-inner--zoomable");
    inner.title = "点击查看大图";
    inner.addEventListener("click", (ev) => {
      ev.preventDefault();
      ev.stopPropagation();
      openChatPhotoViewerFromMsgIdx(msgIdx);
    });
  }

  const foot = document.createElement("div");
  foot.className = "chat-photo-polaroid-footer";
  const stamp = document.createElement("span");
  stamp.className = "chat-photo-polaroid-stamp";
  stamp.textContent = "PHOTO";
  foot.appendChild(stamp);
  if (caption) {
    const line = document.createElement("div");
    line.className = "chat-photo-polaroid-line chat-photo-polaroid-line--filled";
    line.textContent = caption;
    foot.appendChild(line);
  }

  shell.append(tape, gloss, inner, foot);
  if (p.pending) {
    mountChatPhotoPolaroidPendingOverlay(inner, { regen: Boolean(p.pendingRegen) });
  }
  return shell;
}

/**
 * 角色描述式发图：去掉模型爱加的「你发去了一张照片」等元叙事，以及整段外层括号/日式引号，只保留画面描写。
 * @param {string} raw
 */
function sanitizeCharImageCaptionMeta(raw) {
  let s = String(raw ?? "")
    .replace(/\uFEFF/g, "")
    .trim();
  if (!s) return "";
  for (let d = 0; d < 8; d++) {
    const m1 = /^「([\s\S]*)」$/u.exec(s);
    if (m1) {
      s = m1[1].trim();
      continue;
    }
    const m2 = /^（([\s\S]*)）$/u.exec(s);
    if (m2) {
      s = m2[1].trim();
      continue;
    }
    const m3 = /^\(([\s\S]*)\)$/u.exec(s);
    if (m3) {
      s = m3[1].trim();
      continue;
    }
    break;
  }
  const stripOnce = (t) => {
    let u = t;
    for (const re of [
      /^（你(?:发去|发出|发送)了一张(?:照片|图片|图)[。．.!！…]*）\s*/u,
      /^\(你(?:发去|发出|发送)了一张(?:照片|图片|图)[。．.!！…]*\)\s*/u,
      /^你(?:发去|发出|发送)了一张(?:照片|图片|图)[。．.!！…:：\s]+/u,
      /^我(?:发去|发出|发送)了一张(?:照片|图片|图)[。．.!！…:：\s]+/u,
      /^(?:对方|TA|ta)(?:发去|发出|发送|发来)了一张(?:照片|图片|图)[。．.!！…:：\s]+/u,
      /^(?:发去|发来|传来)了一张(?:照片|图片|图)[。．.!！…:：\s]+/u,
      /^发了一张(?:照片|图片|图)[。．.!！…:：\s]+/u
    ]) {
      u = u.replace(re, "").trim();
    }
    return u;
  };
  for (let i = 0; i < 3; i++) {
    const next = stripOnce(s);
    if (next === s) break;
    s = next;
  }
  return s.slice(0, 4000);
}

/**
 * 描述式发图相纸卡（经典 / 玻璃 / 线下共用 DOM）。
 * @param {HTMLElement} stack
 * @param {{ caption: string, pending?: boolean, stripMeta?: boolean, charDesc?: boolean, seg?: number }} opts
 */
function resolveAssistantCharDescImageCap(m, assistantParsedCharCap, parts) {
  let cap =
    String((m?.image && typeof m.image === "object" && m.image.desc) || "").trim() ||
    String(assistantParsedCharCap || "").trim();
  if (!cap && Array.isArray(parts)) {
    for (const seg of parts) {
      const inlineAt = findInlineImageProtocolStart(seg);
      if (inlineAt >= 0) {
        const tail = String(seg || "").slice(inlineAt).trim();
        if (isAssistantImageProtocolLine(tail)) {
          cap = extractAssistantImageCaptionFromProtocolLine(tail);
          if (cap) break;
        }
      }
      if (isAssistantImageProtocolLine(seg)) {
        cap = extractAssistantImageCaptionFromProtocolLine(seg);
        if (cap) break;
      }
    }
  }
  return cap;
}

/** 与描述式发图卡重复的气泡段（协议行或与 desc 同文）不再单独出磨砂气泡 */
function assistantBubblePartDupesDescImage(seg, descCap) {
  const t = String(seg || "").trim();
  if (!t) return true;
  if (isAssistantImageProtocolLine(t)) return true;
  const dc = String(descCap || "").trim();
  if (!dc) return false;
  if (t === dc) return true;
  const a = sanitizeCharImageCaptionMeta(t);
  const b = sanitizeCharImageCaptionMeta(dc);
  return Boolean(a && b && a === b);
}

/** @param {string[]} parts @param {string} descCap */
function filterAssistantPartsAfterDescImageCard(parts, descCap) {
  if (!Array.isArray(parts)) return [];
  return parts.filter((seg) => !assistantBubblePartDupesDescImage(seg, descCap));
}

function appendChatPhotoDescCardToStack(stack, opts) {
  if (!(stack instanceof HTMLElement)) return;
  const cap = String(opts.caption || "").trim();
  const stripMeta = opts.stripMeta === true;
  const capLabel = stripMeta ? sanitizeCharImageCaptionMeta(cap) : cap;
  const pending = Boolean(opts.pending);
  const card = document.createElement("div");
  card.className = opts.charDesc
    ? "chat-msg-card chat-msg-card--photo chat-msg-card--photo-desc chat-msg-card--photo-char-desc"
    : "chat-msg-card chat-msg-card--photo chat-msg-card--photo-desc";
  card.setAttribute("role", "group");
  card.setAttribute(
    "aria-label",
    pending ? "图片：配图生成中" : capLabel ? `图片：${capLabel}` : cap ? `图片：${cap}` : "图片"
  );
  card.dataset.chatBubbleSeg = String(opts.seg ?? 0);
  card.appendChild(
    buildChatPhotoDescCardShell({
      caption: cap,
      stripMeta,
      pending,
      charDesc: Boolean(opts.charDesc)
    })
  );
  stack.appendChild(card);
}

/**
 * 仅文字「【图片】…」：与上传图同一套相纸 DOM + 底部 PHOTO
 * @param {{ caption: string, stripMeta?: boolean, pending?: boolean, pendingRegen?: boolean, charDesc?: boolean }} p
 * @returns {HTMLDivElement}
 */
function buildChatPhotoDescCardShell(p) {
  let caption = String(p.caption || "").trim();
  if (p.stripMeta) caption = sanitizeCharImageCaptionMeta(caption);
  const shell = document.createElement("div");
  shell.className = p.charDesc
    ? "chat-photo-polaroid chat-photo-polaroid--assistant"
    : "chat-photo-polaroid";

  const tape = document.createElement("span");
  tape.className = "chat-photo-polaroid-tape chat-photo-polaroid-tape--tint";
  tape.setAttribute("aria-hidden", "true");

  const gloss = document.createElement("span");
  gloss.className = "chat-photo-polaroid-gloss";
  gloss.setAttribute("aria-hidden", "true");

  const inner = document.createElement("div");
  inner.className = "chat-photo-polaroid-inner chat-photo-polaroid-inner--desc";
  inner.textContent = caption || "（还没写画面）";

  shell.append(tape, gloss, inner);
  if (p.pending) {
    mountChatPhotoPolaroidPendingOverlay(inner, { regen: Boolean(p.pendingRegen) });
  }

  const foot = document.createElement("div");
  foot.className = "chat-photo-polaroid-footer";
  const stamp = document.createElement("span");
  stamp.className = "chat-photo-polaroid-stamp";
  stamp.textContent = "PHOTO";
  foot.appendChild(stamp);

  shell.appendChild(foot);
  return shell;
}

/**
 * 解析红包消息文本（发送/历史里以纯文本存储，渲染时升级为卡片 UI）
 * @param {string} s
 * @returns {{ amt: string, note: string } | null}
 */
/** 去掉 line 里模型误写的【角色名】前缀，便于识别【红包】段。 */
function stripSpeakerBracketsBeforeRedpack(s) {
  let t = String(s || "").trim();
  for (let i = 0; i < 6; i++) {
    const m = t.match(/^【([^】]+)】\s*(.*)$/su);
    if (!m) break;
    const tag = String(m[1] || "").trim();
    if (/^红包/.test(tag) || /^拼手气红包/.test(tag) || /^专属红包/.test(tag)) break;
    t = String(m[2] || "").trim();
  }
  return t;
}

function findInlineRedpackStart(s) {
  const text = String(s || "");
  let best = -1;
  for (const mk of ["【红包】", "【拼手气红包】"]) {
    const i = text.indexOf(mk);
    if (i >= 0 && (best < 0 || i < best)) best = i;
  }
  const ex = /【专属红包·发给[^】]*】/u.exec(text);
  if (ex && ex.index >= 0 && (best < 0 || ex.index < best)) best = ex.index;
  return best;
}

/** 段内夹带「【红包】…」时拆成「正文 + 红包段」，便于渲染红包卡。 */
function expandPartsAndTranslationsForInlineRedpack(parts, transChunks) {
  return expandPartsAndTranslationsForInlineMarker(parts, transChunks, findInlineRedpackStart, (tail) =>
    Boolean(parseRedpackMessageText(tail))
  );
}

function findRedpackPartIndex(parts) {
  const arr = Array.isArray(parts) ? parts : [];
  for (let i = 0; i < arr.length; i++) {
    if (parseRedpackMessageText(String(arr[i] || "").trim())) return i;
    if (parseTransferJsonRedpack(String(arr[i] || ""))) return i;
  }
  return -1;
}

/** @param {unknown} amtRaw @returns {string | null} */
function normalizeTransferJsonRedpackAmount(amtRaw) {
  const n = Number(amtRaw);
  if (!Number.isFinite(n) || n <= 0) {
    const s = String(amtRaw ?? "").trim();
    if (!s) return null;
    const cleaned = sanitizeRedpackAmount(s);
    return cleaned === "8.88" && !s.replace(/[^\d.]/g, "") ? null : cleaned;
  }
  if (Number.isInteger(n) && n >= 100) return sanitizeRedpackAmount(String(n / 100));
  return sanitizeRedpackAmount(String(n));
}

/**
 * 模型偶发把其它产品的 transfer JSON 写进 lines； salvage 为红包卡。
 * @param {string} seg
 * @returns {{ amt: string, note: string, redpackLine: string } | null}
 */
function parseTransferJsonRedpack(seg) {
  const raw = String(seg || "").trim();
  if (!raw || !/transfer|redpack|red_pack|"type"\s*:/i.test(raw)) return null;
  /** @type {string[]} */
  const candidates = [raw];
  const arrM = raw.match(/\[[\s\S]*\]/);
  const objM = raw.match(/\{[\s\S]*\}/);
  if (arrM) candidates.push(arrM[0]);
  if (objM) candidates.push(objM[0]);
  for (const c of candidates) {
    try {
      let parsed = JSON.parse(c);
      if (Array.isArray(parsed)) parsed = parsed[0];
      if (!parsed || typeof parsed !== "object") continue;
      const typ = String(
        /** @type {{ type?: string, kind?: string }} */ (parsed).type ||
          /** @type {{ kind?: string }} */ (parsed).kind ||
          ""
      )
        .trim()
        .toLowerCase();
      if (typ && typ !== "transfer" && typ !== "redpack" && typ !== "red_packet") continue;
      const rec = /** @type {{ note?: string, message?: string, greeting?: string, amount?: unknown, amt?: unknown, money?: unknown }} */ (
        parsed
      );
      const note = String(rec.note || rec.message || rec.greeting || "").trim() || "恭喜发财";
      const amt = normalizeTransferJsonRedpackAmount(rec.amount ?? rec.amt ?? rec.money);
      if (!amt) continue;
      return { amt, note, redpackLine: `【红包】¥${amt} ${note}` };
    } catch (_) {
      /* try next candidate */
    }
  }
  return null;
}

/** @param {string} seg @param {string} [transSeg] @param {boolean} [transUiOn] */
function resolveRedpackFromChatSegment(seg, transSeg, transUiOn) {
  const rp = parseRedpackMessageText(String(seg || "").trim());
  if (rp) return rp;
  const leak = parseTransferJsonRedpack(String(seg || ""));
  if (leak) return { amt: leak.amt, note: leak.note };
  if (transUiOn) {
    const tr = String(transSeg ?? "").trim();
    if (tr && !isTranslationSegmentSkipped(tr)) {
      const rt = parseRedpackMessageText(tr);
      if (rt) return rt;
      const tl = parseTransferJsonRedpack(tr);
      if (tl) return { amt: tl.amt, note: tl.note };
    }
  }
  return null;
}

/** 正文/译本里不应走双语灰字的对照段（红包、transfer JSON、发图协议、表情 JSON 等）。 */
function isStructuredProtocolChatSegment(seg) {
  const t = String(seg ?? "").trim();
  if (!t) return false;
  if (parseRedpackMessageText(t)) return true;
  if (parseTransferJsonRedpack(t)) return true;
  if (isAssistantImageProtocolLine(t)) return true;
  if (isStickerDirectiveTranslationChunk(t)) return true;
  if (RE_MODEL_EMOJI_JSON_BLOCK.test(t)) return true;
  if (/^\[\s*\{[\s\S]*"type"\s*:\s*"(?:transfer|emoji|redpack|red_packet|image|sticker)"/i.test(t)) return true;
  return false;
}

/** @param {string} mainSeg @param {string} transSeg */
function chatBilingualTranslationWorthShowing(mainSeg, transSeg) {
  const trtext = String(transSeg ?? "");
  const trTrim = trtext.trim();
  if (!trTrim || isTranslationSegmentSkipped(trtext)) return false;
  const mainTrim = String(mainSeg ?? "").trim();
  if (isStructuredProtocolChatSegment(mainTrim)) return false;
  if (isStructuredProtocolChatSegment(trTrim)) return false;
  if (mainTrim && trTrim === mainTrim) return false;
  return true;
}

/** 存盘/渲染前：按正文分段掩掉结构化协议段的译本槽。 */
function finalizeAssistantEntryTranslation(entry) {
  if (!entry || typeof entry !== "object" || entry.role !== "assistant") return;
  const tj = String(entry.translation ?? "").trim();
  if (!tj) return;
  const main = String(entry.content ?? "");
  entry.translation = compactTranslationSegmentsToMatchMain(main, tj) || tj;
}

/** @param {object} entry */
function sanitizeTransferJsonLeaksInAssistantEntry(entry) {
  if (!entry || typeof entry !== "object" || entry.role !== "assistant") return;
  const raw = String(entry.content || "").trim();
  if (!raw) return;
  let chunks = raw
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter((s) => s.length > 0);
  if (!chunks.length) chunks = [raw];
  let transChunks = entry.translation
    ? String(entry.translation)
        .split(/\|\|\|/)
        .map((s) => String(s))
    : [];
  let changed = false;
  for (let i = 0; i < chunks.length; i++) {
    const leak = parseTransferJsonRedpack(chunks[i]);
    if (!leak) continue;
    if (!entry.redpack || typeof entry.redpack !== "object") {
      entry.redpack = { id: makeRedpackId(), amt: leak.amt, note: leak.note, status: "sent" };
    }
    chunks[i] = leak.redpackLine;
    while (transChunks.length <= i) transChunks.push("");
    transChunks[i] = CHAT_TRANSLATION_SKIP_TOKEN;
    changed = true;
    break;
  }
  if (!changed) return;
  const expanded = expandPartsAndTranslationsForInlineRedpack(chunks, transChunks);
  entry.content = expanded.parts.join("|||");
  if (entry.translation) {
    entry.translation = padTranslationSegments(expanded.transChunks.join("|||"), expanded.parts.length)
      .map((t, i) =>
        parseRedpackMessageText(String(expanded.parts[i] || "")) ? CHAT_TRANSLATION_SKIP_TOKEN : t
      )
      .join("|||");
  }
}

/** @param {unknown} m */
function assistantEntryNeedsRedpackContentSanitize(m) {
  if (!m || typeof m !== "object" || String(m.role) !== "assistant") return false;
  const c = String(m.content ?? "");
  if (!c.trim()) return false;
  if (/transfer|"type"\s*:\s*"transfer"/i.test(c)) return true;
  return Boolean(parseTransferJsonRedpack(c));
}

/** @param {string} mainJoined @param {string} transJoined */
function translationNeedsStructureMask(mainJoined, transJoined) {
  const mains = String(mainJoined ?? "").split(/\|\|\|/);
  const trans = String(transJoined ?? "").split(/\|\|\|/);
  const n = Math.max(mains.length, trans.length);
  for (let i = 0; i < n; i++) {
    if (isStructuredProtocolChatSegment(String(mains[i] ?? ""))) return true;
    if (isStructuredProtocolChatSegment(String(trans[i] ?? ""))) return true;
  }
  return false;
}

function tryAttachCharRedpackFromContent(entry) {
  if (!entry || typeof entry !== "object" || entry.role !== "assistant") return;
  sanitizeTransferJsonLeaksInAssistantEntry(entry);
  if (entry.redpack && typeof entry.redpack === "object") return;
  const raw = String(entry.content || "").trim();
  if (!raw) return;
  const chunks = String(entry.content || "")
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean);
  const { parts } = expandPartsAndTranslationsForInlineRedpack(chunks.length ? chunks : [raw], []);
  for (const seg of parts) {
    const rp = parseRedpackMessageText(seg);
    if (rp) {
      entry.redpack = { id: makeRedpackId(), amt: rp.amt, note: rp.note, status: "sent" };
      return;
    }
  }
}

function parseRedpackMessageText(s) {
  let raw = stripSpeakerBracketsBeforeRedpack(s);
  if (!raw) return null;
  if (
    !raw.startsWith("【红包】") &&
    !raw.startsWith("【拼手气红包】") &&
    !/^【专属红包·发给[^】]*】/.test(raw)
  ) {
    const inline = findInlineRedpackStart(raw);
    if (inline < 0) return null;
    raw = raw.slice(inline).trim();
  }
  let rest = "";
  if (raw.startsWith("【红包】")) {
    rest = raw.slice("【红包】".length).trim();
  } else if (raw.startsWith("【拼手气红包】")) {
    rest = raw.slice("【拼手气红包】".length).trim();
  } else {
    const ex = raw.match(/^【专属红包·发给[^】]*】\s*(.*)$/u);
    if (!ex) return null;
    rest = String(ex[1] || "").trim();
  }
  // 支持：`【红包】¥8.88 恭喜发财` / `【红包】￥8.88 …` / 群聊拼手气 / 专属红包
  const m = rest.match(/^[¥￥]?\s*([0-9]+(?:\.[0-9]{1,2})?)\s*(.*)$/s);
  if (!m) return null;
  const amt = sanitizeRedpackAmount(m[1] || "0");
  const note = String(m[2] || "").trim() || "恭喜发财";
  return { amt, note };
}

