document.getElementById("redpack-send")?.addEventListener("click", () => {
  const input = document.getElementById("chat-input");
  const composed = buildRedpackMessageText();
  const rp = parseRedpackMessageText(composed);
  const need = rp ? parseMoneyToCents(rp.amt) : 0;
  if (need <= 0) {
    showToast("金额不合法");
    return;
  }
  // 钱包：发红包先扣钱（余额不足则拦截）
  const maskId = getActiveMaskIdForInbox();
  const { store, bucket, dirty } = ensureMyMaskBucket(maskId);
  if (dirty) writeMyStore(store);
  const bal = Number(bucket.walletCents) || 0;
  if (bal < need) {
    showToast(`余额不足（需要 ¥${formatMoneyFromCents(need)}）`);
    return;
  }
  bucket.walletCents = bal - need;
  writeMyStore(store);
  renderMyScreen();
  pushWalletBill({ type: "发红包", note: String(rp?.note || "").trim(), deltaCents: -need, balanceCentsAfter: Number(bucket.walletCents) || 0 });

  if (input && input instanceof HTMLTextAreaElement) {
    input.value = composed;
    input.dispatchEvent(new Event("input", { bubbles: true }));
    void sendChatFromInput();
    closeRedpackSheet();
    return;
  }
  // 找不到输入框：回滚扣款
  bucket.walletCents = bal;
  writeMyStore(store);
  renderMyScreen();
  showToast("发送失败：找不到输入框");
});
