document.getElementById("chat-theater-reroll")?.addEventListener("click", () => {
  if (!isThreadTheaterEnabled(readActiveThread())) {
    showToast("本密谈已关闭小剧场");
    return;
  }
  const root = document.getElementById("chat-theater-reroll-picks");
  const presetIds = root instanceof HTMLElement
    ? [...root.querySelectorAll('input[data-theater-reroll-pick]:checked')]
        .map((el) => (el instanceof HTMLInputElement ? String(el.value || "").trim() : ""))
        .filter(Boolean)
    : [];
  if (!presetIds.length) {
    showToast("请至少勾选一个要重 roll 的小剧场");
    return;
  }
  const ref = readChatActiveThreadRef();
  const idx = resolveChatTheaterTargetAssistantIdx();
  if (idx < 0) {
    showToast("没有可重 roll 的对方回复");
    return;
  }
  void runTheaterSnapBundleGeneration(ref.maskId, ref.threadId, idx, presetIds, { force: true });
});

