document.getElementById("chat-detail-thread-ui-css-preset-bind")?.addEventListener("change", (e) => {
  const sel = e.target;
  if (!(sel instanceof HTMLSelectElement)) return;
  if (!readActiveThread()) return;
  const v = String(sel.value || "").trim();
  const boundPreset = v ? readThreadUiCssPresetsFromKv().find((p) => String(p?.id || "") === v) : null;
  const boundKind = boundPreset ? getThreadUiCssPresetKind(boundPreset) : "";
  if (
    !patchActiveThread((t) => {
      if (!v) {
        delete t.threadUiCssPresetId;
      } else {
        t.threadUiCssPresetId = v;
        if (boundKind === CHAT_UI_CSS_PRESET_KIND_GLASS) {
          t.threadUiThemeKind = "glass";
        } else if (boundKind === CHAT_UI_CSS_PRESET_KIND_CLASSIC) {
          t.threadUiThemeKind = "default";
        }
      }
      if (
        boundKind === CHAT_UI_CSS_PRESET_KIND_GLASS &&
        t.chatBodyBgImage &&
        String(t.chatBodyBgImage).trim()
      ) {
        t.chatMessagesBgFullBleed = true;
      }
    })
  ) {
    showToast("无法保存");
    return;
  }
  syncChatUiThemeSwitchButtons();
  applyChatThreadSurfaceBackgrounds();
  mountChatSurfaceCssLayers();
  if (getActiveChatDmSurfaceForContext() === "im") renderChatMessages();
  showToast(v ? "已绑定预设（本密谈仅用该预设，不叠装扮全局 CSS）" : "已取消绑定（恢复装扮全局 CSS）");
});
