document.getElementById("chat-detail-block-char-toggle")?.addEventListener("click", async () => {
  const th0 = readActiveThread();
  if (!th0 || th0.kind === "group") return;
  const ref = readChatActiveThreadRef();
  const maskId = String(ref.maskId || getActiveMaskIdForInbox() || "").trim();
  const threadId = String(ref.threadId || "").trim();
  if (!maskId || !threadId) return;
  const nextBlocked = !isThreadUserBlockedChar(th0);
  patchActiveThread((t) => {
    if (nextBlocked) t.userBlockedChar = true;
    else delete t.userBlockedChar;
  });
  const th1 = readActiveThread();
  const charName = getCharPersonaDisplayNameForThread(th1);
  const mask = readUserMask();
  const userName = (mask.displayName && String(mask.displayName).trim()) || "你";
  const noticeKind = nextBlocked ? "block_user_char" : "unblock_user_char";
  const notice = {
    role: "notice",
    kind: noticeKind,
    at: Date.now(),
    charName,
    userName,
    label: formatChatBlockNoticeLabel({ kind: noticeKind, charName, userName })
  };
  const log = readChatLogForMaskThread(maskId, threadId);
  log.push(notice);
  saveChatLogForMaskThread(maskId, threadId, log);
  syncChatThreadDetailPanelPlaceholders();
  renderChatMessages();
  showToast(nextBlocked ? "已拉黑" : "已取消拉黑");
  if (nextBlocked) {
    try {
      await executeChatAssistantRound({
        boundMaskId: maskId,
        boundThreadId: threadId,
        boundThread: th1,
        boundDmSurface: "im",
        emptySendUserContent: buildUserBlockedCharAutoRoundPrompt(charName, userName),
        allowSilentReply: true,
        suppressCharLockAndCallSideEffects: true
      });
    } catch (_) {
      /* ignore */
    }
  }
});
