function resetChatDetailImageRefTestPanel() {
  const wrap = document.getElementById("chat-detail-image-ref-test-wrap");
  const st = document.getElementById("chat-detail-image-ref-test-status");
  const img = document.getElementById("chat-detail-image-ref-test-preview");
  if (wrap) wrap.hidden = true;
  if (st) {
    st.textContent = "";
    st.classList.remove("imgen-test-status--err");
  }
  if (img) {
    img.hidden = true;
    img.removeAttribute("src");
  }
}

/** @param {ReturnType<typeof readActiveThread>} th */
function syncChatDetailImageRefTestUi(th) {
  const block = document.getElementById("chat-detail-image-ref-test");
  const thumb = document.getElementById("chat-detail-image-ref-thumb");
  const btn = document.getElementById("chat-detail-image-ref-test-btn");
  const ref = resolveThreadCharImageRefDataUrl(th);
  if (block) block.hidden = !ref;
  if (thumb instanceof HTMLImageElement) {
    if (ref) {
      thumb.src = ref;
      thumb.hidden = false;
    } else {
      thumb.hidden = true;
      thumb.removeAttribute("src");
      resetChatDetailImageRefTestPanel();
    }
  }
  if (btn instanceof HTMLButtonElement) {
    const ok = Boolean(ref) && isSessionImageGenConfigured();
    btn.disabled = !ok;
    btn.title = ok
      ? ""
      : ref
        ? "请先在生图接入里开启并保存 API Key"
        : "请先上传参考立绘";
  }
}

async function runChatDetailImageRefTest() {
  const th = readActiveThread();
  const ref = resolveThreadCharImageRefDataUrl(th);
  if (!ref) {
    showToast("请先上传参考立绘");
    return;
  }
  const cfg = readImageGenConfig();
  if (!cfg.enabled || !String(cfg.apiKey || "").trim()) {
    showToast("请先在生图接入里开启并配置 API Key");
    return;
  }
  const promptInp = document.getElementById("chat-detail-image-ref-test-prompt");
  const defaultPrompt =
    "Same character as the reference image, upper body portrait, soft natural lighting, clean anime illustration, gentle expression, simple background.";
  let prompt = promptInp instanceof HTMLInputElement ? String(promptInp.value || "").trim() : "";
  if (!prompt) prompt = defaultPrompt;
  const wrap = document.getElementById("chat-detail-image-ref-test-wrap");
  const st = document.getElementById("chat-detail-image-ref-test-status");
  const img = document.getElementById("chat-detail-image-ref-test-preview");
  const btn = document.getElementById("chat-detail-image-ref-test-btn");
  if (wrap) wrap.hidden = false;
  if (st) {
    st.classList.remove("imgen-test-status--err");
    st.textContent = "正在生图…";
  }
  if (img) {
    img.hidden = true;
    img.removeAttribute("src");
  }
  if (btn) btn.disabled = true;
  try {
    const r = await executeImageGenRequestToDataUrl(cfg, prompt, {
      refDataUrl: ref,
      preferLongTimeout: true
    });
    if (!r.ok || !r.dataUrl) {
      if (st) {
        st.classList.add("imgen-test-status--err");
        st.textContent = `失败：${String(r.error || "未知").slice(0, 200)}`;
      }
      showToast("参考图测试失败");
      return;
    }
    if (img) {
      img.src = r.dataUrl;
      img.hidden = false;
    }
    if (st) st.textContent = "成功";
    showToast("参考图测试成功");
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    if (st) {
      st.classList.add("imgen-test-status--err");
      st.textContent = `异常：${msg.slice(0, 160)}`;
    }
    showToast("参考图测试失败");
  } finally {
    syncChatDetailImageRefTestUi(readActiveThread());
  }
}

