/** 卷宗内生图两行开关：在面板上委托 click，避免命中伪元素/子节点时漏绑，并绕开部分层叠上下文下透明层抢点问题 */
document.getElementById("chat-thread-detail-panel")?.addEventListener("click", (e) => {
  const t = e.target;
  if (!(t instanceof Element)) return;
  const btn = t.closest("button");
  const bid = btn?.id;
  if (bid !== "chat-detail-image-every-round-toggle") {
    return;
  }
  const th0 = readActiveThread();
  if (!th0) return;
  const nextOn2 = !isThreadChatEveryRoundSessionImage(th0);
  const ok2 = patchActiveThread((t2) => {
    if (nextOn2) t2.chatThreadImageEveryRound = true;
    else delete t2.chatThreadImageEveryRound;
  });
  if (!ok2) {
    showToast("无法保存");
    return;
  }
  syncChatThreadDetailPanelPlaceholders();
  showToast(nextOn2 ? "已开启：每轮对话后生图" : "已关闭：每轮对话后生图");
});

