let chatProactiveTimerId = 0;
let chatProactivePeerScanTimerId = 0;
let chatProactiveInFlight = false;
/** @type {Map<string, number>} */
const chatAssistRoundInflightByThread = new Map();
/** @type {Map<string, Promise<void>>} */
const chatAssistRoundChainByThread = new Map();
/** @type {Map<string, AbortController>} */
const chatActiveAssistAbortControllerByThread = new Map();
/** @type {Map<string, { roundMaskId: string, roundThreadId: string, roundDmSurface: string, reply: string, thSend0: object, typingInserted: boolean }>} */
const chatAssistAbortCommitStateByThread = new Map();

function chatAssistRoundSlotKey(maskId, threadId) {
  const mid = String(maskId || "").trim();
  const tid = String(threadId || "").trim();
  return mid && tid ? `${mid}\t${tid}` : "";
}

/** @param {string} slotKey */
function getChatAssistAbortCommitStateForSlot(slotKey) {
  const key = String(slotKey || "").trim();
  return key ? chatAssistAbortCommitStateByThread.get(key) || null : null;
}

/** @param {string} slotKey */
function clearChatAssistAbortCommitState(slotKey) {
  const key = String(slotKey || "").trim();
  if (key) chatAssistAbortCommitStateByThread.delete(key);
}

/** @param {string} slotKey @param {Partial<{ roundMaskId: string, roundThreadId: string, roundDmSurface: string, reply: string, thSend0: object, typingInserted: boolean }>} patch */
function updateChatAssistAbortCommitState(slotKey, patch) {
  const key = String(slotKey || "").trim();
  if (!key || !patch || typeof patch !== "object") return;
  const prev = chatAssistAbortCommitStateByThread.get(key);
  if (!prev) chatAssistAbortCommitStateByThread.set(key, { ...patch });
  else Object.assign(prev, patch);
}

/** @param {string} slotKey @param {AbortController} controller */
function setChatActiveAssistAbortController(slotKey, controller) {
  const key = String(slotKey || "").trim();
  if (key && controller) chatActiveAssistAbortControllerByThread.set(key, controller);
}

/** @param {string} slotKey @param {AbortController} controller */
function clearChatActiveAssistAbortController(slotKey, controller) {
  const key = String(slotKey || "").trim();
  if (!key) return;
  if (chatActiveAssistAbortControllerByThread.get(key) === controller) {
    chatActiveAssistAbortControllerByThread.delete(key);
  }
}

/** @param {string} maskId @param {string} threadId */
function abortChatAssistRoundForThread(maskId, threadId) {
  const key = chatAssistRoundSlotKey(maskId, threadId);
  if (!key) return;
  try {
    chatActiveAssistAbortControllerByThread.get(key)?.abort();
  } catch (_) {
    /* ignore */
  }
}

function abortActiveChatAssistRound() {
  const mid = String(getActiveMaskIdForInbox() || "").trim();
  const tid = String(readChatActiveThreadRef().threadId || "").trim();
  abortChatAssistRoundForThread(mid, tid);
}

/**
 * @param {string} roundMaskId
 * @param {string} roundThreadId
 * @param {"im"|"offline"} roundDmSurface
 * @param {boolean} typingInserted
 */
function finalizeChatAssistRoundAfterUserAbort(roundMaskId, roundThreadId, roundDmSurface, typingInserted) {
  const slotKey = chatAssistRoundSlotKey(roundMaskId, roundThreadId);
  const st = getChatAssistAbortCommitStateForSlot(slotKey);
  const next = readChatLogForMaskThread(roundMaskId, roundThreadId);
  if (typingInserted) removeChatRestoringPlaceholders(next, { includeWithContent: true });
  const partialReply =
    st &&
    st.roundMaskId === roundMaskId &&
    st.roundThreadId === roundThreadId &&
    String(st.reply || "").trim()
      ? String(st.reply || "").trim()
      : "";
  if (partialReply) {
    const entry = { role: "assistant", content: partialReply, at: Date.now() };
    tagAssistantEntryDmSurface(entry, roundDmSurface);
    tagAssistantEntrySpeakerPersona(entry, st.thSend0 || readActiveThread());
    next.push(entry);
    clearAssistantRestoringFlagsInLog(next);
    showToast("已停止，保留已生成内容");
  } else {
    clearAssistantRestoringFlagsInLog(next);
    showToast("已停止回复");
  }
  saveChatLogForMaskThread(roundMaskId, roundThreadId, next);
  chatSuppressNextChatMessageAnimations = true;
  scheduleChatUiRefreshForRound(roundMaskId, roundThreadId, { flush: true });
  scheduleChatProactiveTimer();
  clearChatAssistAbortCommitState(slotKey);
}

/** @param {{ boundMaskId?: string, boundThreadId?: string, boundThread?: object }} [opts] */
function resolveChatAssistRoundSlotKey(opts) {
  const mid =
    String((opts && opts.boundMaskId) || "").trim() ||
    String(getActiveMaskIdForInbox() || "").trim();
  const tid =
    String((opts && opts.boundThreadId) || "").trim() ||
    String((opts && opts.boundThread && opts.boundThread.id) || "").trim();
  return chatAssistRoundSlotKey(mid, tid);
}

function bumpChatAssistRoundInflight(slotKey, delta) {
  const key = String(slotKey || "").trim();
  if (!key) return;
  const d = Math.floor(Number(delta)) || 0;
  if (!d) return;
  const next = (chatAssistRoundInflightByThread.get(key) || 0) + d;
  if (next <= 0) chatAssistRoundInflightByThread.delete(key);
  else chatAssistRoundInflightByThread.set(key, next);
}

function isChatAssistRoundInflightForThread(maskId, threadId) {
  const key = chatAssistRoundSlotKey(maskId, threadId);
  return key ? (chatAssistRoundInflightByThread.get(key) || 0) > 0 : false;
}

function isChatAssistRoundInflightForActiveThread() {
  const mid = String(getActiveMaskIdForInbox() || "").trim();
  const tid = String(readChatActiveThreadRef().threadId || "").trim();
  return isChatAssistRoundInflightForThread(mid, tid);
}

function syncChatSendButtonForActiveThread() {
  const btn = document.getElementById("chat-send");
  if (!(btn instanceof HTMLButtonElement)) return;
  const busy = isChatAssistRoundInflightForActiveThread();
  btn.disabled = false;
  btn.classList.toggle("chat-send-fab--assist-stop", busy);
  const icon = btn.querySelector("i");
  if (icon instanceof HTMLElement) {
    icon.className = busy ? "ph ph-stop" : "ph ph-paper-plane-tilt";
  }
  btn.setAttribute(
    "aria-label",
    busy ? "停止回复" : "发送；输入框为空时请求对方回复"
  );
  btn.title = busy ? "停止回复" : "";
}

function refreshChatThreadListIfBackgroundRound(maskId, threadId) {
  if (isUserViewingChatThread(maskId, threadId)) return;
  if (!chatListScreen?.classList.contains("is-open")) return;
  renderChatThreadList();
}

/**
 * @param {{ boundMaskId?: string, boundThreadId?: string, boundThread?: object }} [opts]
 * @returns {Promise<() => void>}
 */
function acquireChatAssistRoundSlot(opts) {
  const key = resolveChatAssistRoundSlotKey(opts);
  if (!key) {
    let releaseGlobal;
    const tail = new Promise((resolve) => {
      releaseGlobal = resolve;
    });
    const prev = chatAssistRoundChainByThread.get("") || Promise.resolve();
    chatAssistRoundChainByThread.set("", tail);
    return prev.then(() => releaseGlobal);
  }
  const prev = chatAssistRoundChainByThread.get(key) || Promise.resolve();
  let release;
  const tail = new Promise((resolve) => {
    release = resolve;
  });
  chatAssistRoundChainByThread.set(key, tail);
  return prev.then(() => release);
}

function clearChatProactivePeerScanTimer() {
  if (chatProactivePeerScanTimerId) window.clearTimeout(chatProactivePeerScanTimerId);
  chatProactivePeerScanTimerId = 0;
}

/** 前台：其它 char 的主动密谈（当前页 char 仍走 scheduleChatProactiveTimer）。 */
function scheduleChatProactivePeerScanTimer() {
  clearChatProactivePeerScanTimer();
  if (!hasAnyBackgroundProactivePolling()) return;
  const wakes = [];
  if (hasAnyChatProactiveEnabled()) wakes.push(computeNextChatProactivePeerWakeMs());
  if (
    typeof window.relationBgStoreHasActivePolling === "function" &&
    window.relationBgStoreHasActivePolling()
  ) {
    wakes.push(computeNextRelationBgWakeMs());
  }
  const wake = wakes.length ? Math.min(...wakes) : 120000;
  chatProactivePeerScanTimerId = window.setTimeout(() => {
    chatProactivePeerScanTimerId = 0;
    void runChatProactivePeerScan();
  }, wake);
}

async function runChatProactivePeerScan() {
  try {
    await runChatProactiveScanOnce({ skipViewingThread: true, requireKeepAlive: false });
    await runRelationDmProactiveScanOnce({ requireKeepAlive: false });
  } finally {
    scheduleChatProactivePeerScanTimer();
  }
}

function clearChatProactiveTimer() {
  if (chatProactiveTimerId) window.clearTimeout(chatProactiveTimerId);
  chatProactiveTimerId = 0;
}

function scheduleChatProactiveTimer() {
  clearChatProactiveTimer();
  scheduleChatProactivePeerScanTimer();
  const cs = getChatScreenEl();
  if (!cs || !cs.classList.contains("is-open")) return;
  const th = readActiveThread();
  const mid = String(getActiveMaskIdForInbox() || "").trim();
  if (!th || isChatThreadGroupForUi(th)) return;
  const groupTh = resolveLinkedGroupForDmThread(th, mid);
  const classicOn = isThreadCharProactiveEnabled(th) && !groupTh;
  if (!groupTh && !classicOn) return;
  const log = readChatLog();
  if (countTrailingAssistantBubblesInLog(log) >= 2) {
    chatProactiveTimerId = window.setTimeout(scheduleChatProactiveTimer, 60000);
    return;
  }
  const baseline = computeCharProactiveBaselineMs(log);
  const intervalMs = groupTh ? getGroupDrivenProactiveIntervalMs(th) : getCharProactiveIntervalMs(th);
  const elapsed = Date.now() - baseline;
  const remaining = Math.max(4000, intervalMs - elapsed);
  chatProactiveTimerId = window.setTimeout(() => {
    void runChatProactiveTurn();
  }, remaining);
}

async function runChatProactiveTurn() {
  chatProactiveTimerId = 0;
  const cs = getChatScreenEl();
  if (!cs || !cs.classList.contains("is-open")) return;
  if (chatProactiveInFlight) {
    scheduleChatProactiveTimer();
    return;
  }
  const th = readActiveThread();
  const mid = String(getActiveMaskIdForInbox() || "").trim();
  if (!th || isChatThreadGroupForUi(th)) return;
  const groupTh = resolveLinkedGroupForDmThread(th, mid);
  const classicOn = isThreadCharProactiveEnabled(th) && !groupTh;
  if (!groupTh && !classicOn) return;
  const log = readChatLog();
  if (countTrailingAssistantBubblesInLog(log) >= 2) {
    scheduleChatProactiveTimer();
    return;
  }
  const baseline = computeCharProactiveBaselineMs(log);
  const intervalMs = groupTh ? getGroupDrivenProactiveIntervalMs(th) : getCharProactiveIntervalMs(th);
  if (Date.now() - baseline + 500 < intervalMs) {
    scheduleChatProactiveTimer();
    return;
  }
  const ai = window.RP_AI;
  if (!ai) return;
  chatProactiveInFlight = true;
  const btn = document.getElementById("chat-send");
  try {
    const follow = countTrailingAssistantBubblesInLog(readChatLog()) > 0;
    const tid = String(readChatActiveThreadRef().threadId || "").trim();
    const prompt = groupTh
      ? buildGroupDrivenProactiveDmUserPrompt(th, groupTh, mid, follow)
      : buildCharProactiveApiUserPrompt(follow, th, mid);
    await executeChatAssistantRound(
      {
        boundMaskId: mid,
        boundThreadId: tid,
        boundThread: th,
        boundDmSurface: resolveChatRoundDmSurface(
          { boundMaskId: mid, boundThreadId: tid, boundThread: th },
          th,
          mid,
          tid
        ),
        emptySendUserContent: prompt,
        allowSilentReply: true
      },
      btn
    );
  } finally {
    syncChatSendButtonForActiveThread();
    chatProactiveInFlight = false;
    scheduleChatProactiveTimer();
  }
}

/**
 * 空输入请求对方回复（或主动发消息代发句）。`opts.emptySendUserContent` 非空时替换默认代发句。
 * boundMaskId / boundThreadId / boundThread / boundDmSurface：后台主动发消息等须传入，避免与当前界面密谈串人设。
 * @param {{ emptySendUserContent?: string, allowSilentReply?: boolean, suppressCharLockAndCallSideEffects?: boolean, charLockLiveChat?: boolean, boundMaskId?: string, boundThreadId?: string, boundThread?: object, boundDmSurface?: "im" | "offline" }} opts
 * @param {HTMLButtonElement | null} btn
 */
async function executeChatAssistantRound(opts, btn) {
  const slotKey = resolveChatAssistRoundSlotKey(opts);
  const roundMaskId = slotKey ? slotKey.split("\t")[0] : "";
  const roundThreadId = slotKey ? slotKey.split("\t")[1] : "";
  const releaseSlot = await acquireChatAssistRoundSlot(opts);
  bumpChatAssistRoundInflight(slotKey, 1);
  syncChatSendButtonForActiveThread();
  try {
    await runChatAssistantRoundBody(opts, btn);
  } finally {
    bumpChatAssistRoundInflight(slotKey, -1);
    syncChatSendButtonForActiveThread();
    releaseSlot();
    if (roundMaskId && roundThreadId) {
      refreshChatThreadListIfBackgroundRound(roundMaskId, roundThreadId);
    }
  }
}

/**
 * 重回 / 重 roll 等不走 executeChatAssistantRound 的路径：发送键切「停止」、支持 AbortController。
 * @param {{ boundMaskId?: string, boundThreadId?: string, boundThread?: object }} boundOpts
 * @param {(signal: AbortSignal) => Promise<void>} run
 */
async function runChatAssistRoundWithSendUi(boundOpts, run) {
  const slotKey = resolveChatAssistRoundSlotKey(boundOpts);
  const roundAbortController = new AbortController();
  setChatActiveAssistAbortController(slotKey, roundAbortController);
  clearChatAssistAbortCommitState(slotKey);
  bumpChatAssistRoundInflight(slotKey, 1);
  syncChatSendButtonForActiveThread();
  try {
    await run(roundAbortController.signal);
  } finally {
    clearChatActiveAssistAbortController(slotKey, roundAbortController);
    bumpChatAssistRoundInflight(slotKey, -1);
    syncChatSendButtonForActiveThread();
    clearChatAssistAbortCommitState(slotKey);
  }
}

window.executeChatAssistantRound = executeChatAssistantRound;

async function runChatAssistantRoundBody(opts, btn) {
  const ai = window.RP_AI;
  if (!ai) {
    showToast("AI 模块未加载");
    return;
  }
  const roundMaskId =
    String((opts && opts.boundMaskId) || "").trim() || String(getActiveMaskIdForInbox() || "").trim();
  const roundThreadId =
    String((opts && opts.boundThreadId) || "").trim() ||
    String((opts && opts.boundThread && opts.boundThread.id) || "").trim();
  if (!roundMaskId || !roundThreadId) {
    showChatThreadUnavailableToast("missing-ref");
    return;
  }
  await ensureChatLazyStoresForRound();
  const slotKey = chatAssistRoundSlotKey(roundMaskId, roundThreadId);
  const roundAbortController = new AbortController();
  setChatActiveAssistAbortController(slotKey, roundAbortController);
  clearChatAssistAbortCommitState(slotKey);
  const roundAbortSignal = roundAbortController.signal;
  const aiFetchOpts = { signal: roundAbortSignal };
  const apiExtra =
    opts && String(opts.emptySendUserContent || "").trim()
      ? { emptySendUserContent: String(opts.emptySendUserContent).trim() }
      : undefined;
  const thSend0 = resolveChatPromptThread({
    boundMaskId: roundMaskId,
    boundThreadId: roundThreadId,
    boundThread: opts && opts.boundThread
  });
  if (!thSend0) {
    showChatThreadUnavailableToast("missing-thread");
    clearChatActiveAssistAbortController(slotKey, roundAbortController);
    return;
  }
  const roundThreadFound = findChatThreadInInbox(roundMaskId, roundThreadId);
  if (roundThreadFound) {
    await ensureThreadMessagesForApi(roundMaskId, roundThreadId, roundThreadFound.thread, thSend0);
  }
  if (isChatThreadGroupForUi(thSend0) && typeof window.XXJ_GroupChat?.runAssistantRound === "function") {
    const roundDmSurfaceGroup = resolveChatRoundDmSurface(opts, thSend0, roundMaskId, roundThreadId);
    await window.XXJ_GroupChat.runAssistantRound(opts, btn, {
      thSend0,
      roundMaskId,
      roundThreadId,
      roundDmSurface: roundDmSurfaceGroup
    });
    clearChatActiveAssistAbortController(slotKey, roundAbortController);
    return;
  }
  const roundDmSurface = resolveChatRoundDmSurface(opts, thSend0, roundMaskId, roundThreadId);
  const roundThreadRef = { maskId: roundMaskId, threadId: roundThreadId };
  let typingInserted = false;
  try {
    const charLockLive = !!(opts && opts.charLockLiveChat);
    const transOn0 = charLockLive ? false : isThreadCharTranslationEnabled(thSend0);
    const maxTokPrimary = charLockLive ? 2568 : null;
    const buildLogOpts = {
      ...(apiExtra || {}),
      ...(charLockLive ? { includeCharLockSessionLog: true } : {}),
      boundMaskId: roundMaskId,
      boundThreadId: roundThreadId,
      boundThread: thSend0
    };
    const apiMessages = await buildChatApiMessagesFromLogAsync(
      true,
      readChatLogForApiForMaskThread(roundDmSurface, roundMaskId, roundThreadId),
      Object.keys(buildLogOpts).length ? buildLogOpts : undefined,
      roundDmSurface
    );
    let typingInsertedLocal = false;
    try {
      const liveLog = readChatLogForMaskThread(roundMaskId, roundThreadId);
      const at0 = Date.now();
      const typingRow = { role: "assistant", content: "", at: at0, restoring: true };
      tagAssistantEntrySpeakerPersona(
        typingRow,
        resolveChatPromptThread({
          boundMaskId: roundMaskId,
          boundThreadId: roundThreadId,
          boundThread: thSend0
        })
      );
      if (roundDmSurface === "offline") typingRow.dmSurface = "offline";
      liveLog.push(typingRow);
      saveChatLogForMaskThread(roundMaskId, roundThreadId, liveLog, { deferPersist: true });
      typingInsertedLocal = true;
      typingInserted = true;
      chatInnerVoiceBrowseAssistantLogIdx = -1;
      chatTheaterBrowseAssistantLogIdx = -1;
      scheduleChatUiRefreshForRound(roundMaskId, roundThreadId);
      refreshChatThreadListIfBackgroundRound(roundMaskId, roundThreadId);
    } catch (_) {
      /* ignore */
    }
    updateChatAssistAbortCommitState(slotKey, {
      roundMaskId,
      roundThreadId,
      roundDmSurface,
      reply: "",
      thSend0,
      typingInserted: typingInsertedLocal
    });
    const apiKeepAlive = isBgKeepAliveEnabled() && !KeepAliveModule.isRunning;
    if (apiKeepAlive) KeepAliveModule.start();
    let data;
    const useOfflineStream =
      roundDmSurface === "offline" &&
      !charLockLive &&
      isThreadOfflineStreamReplyEnabled(thSend0);
    const useImStream =
      roundDmSurface !== "offline" && !charLockLive && isThreadImStreamReplyEnabled(thSend0);
    const useStream = useOfflineStream || useImStream;
    try {
      if (useStream) {
        data = await requestChatAssistantCompletionStream(ai, {
          messages: apiMessages,
          ...spreadOptionalMaxTokens(maxTokPrimary),
          response_format: { type: "json_object" },
          streamOmitResponseFormat: useImStream,
          signal: roundAbortSignal,
          onStreamDelta: (full) => {
            if (roundAbortSignal.aborted) return;
            if (useOfflineStream) {
              const preview = extractOfflineAssistantStreamPreview(full);
              if (preview) patchOfflineAssistantStreamRow(roundMaskId, roundThreadId, preview);
            } else {
              patchImAssistantStreamRow(roundMaskId, roundThreadId, full);
            }
          }
        });
      } else {
        data = await requestChatAssistantCompletion(ai, {
          messages: apiMessages,
          ...spreadOptionalMaxTokens(maxTokPrimary),
          response_format: { type: "json_object" },
          signal: roundAbortSignal
        });
      }
    } finally {
      if (apiKeepAlive) KeepAliveModule.stop();
      if (isBgKeepAliveEnabled()) syncBgKeepAliveState();
    }
    rememberChatApiUsage(data?.usage);
    scheduleChatContextTokenLabelUpdate();
    let rawReply = readChatCompletionSalvagedText(data);
    if (!rawReply) throw new Error(explainModelEmptyReply(data, rawReply));
    if (charLockLive && charLockSession) {
      charLockSession.modelCharLockRelease = parseAssistantCharLockReleaseFromRaw(rawReply);
    }
    const charLockStripRound = stripCharLockPlainProtocolBlocksFromText(rawReply);
    const firstParsed = parseAssistantPayloadForDmSurface(
      charLockStripRound.text,
      roundDmSurface,
      rawReply
    );
    const charLockSpecRound = mergeCharLockAssistantSpecs(
      charLockStripRound.spec,
      extractCharLockAssistantSpecFromBalancedJson(rawReply)
    );
    let { reply: parsedReply, recalls, lineTranslationsJoined, voiceLines, voiceSeconds } = firstParsed;
    const offlineMeetupRaw = extractAssistantOfflineMeetupFromRaw(rawReply);
    const transOn = transOn0;
    let reply = coalesceAssistantDisplayReply(parsedReply, rawReply, roundDmSurface);
    updateChatAssistAbortCommitState(slotKey, { reply: String(reply || "") });
    if (!String(reply || "").trim() && String(rawReply || "").trim() && !opts?.allowSilentReply) {
      const lineRepair = await tryRepairAssistantLinesOnly(
        ai,
        rawReply,
        maxTokPrimary,
        roundDmSurface,
        roundAbortSignal
      );
      if (lineRepair) {
        rawReply = lineRepair.repRaw;
        mergeAssistantParsedPreservingHeartPanel(firstParsed, lineRepair.parsed);
        parsedReply = lineRepair.parsed.reply;
        reply = coalesceAssistantDisplayReply(parsedReply, rawReply, roundDmSurface);
        recalls = firstParsed.recalls;
        lineTranslationsJoined = firstParsed.lineTranslationsJoined;
        voiceLines = firstParsed.voiceLines;
        voiceSeconds = firstParsed.voiceSeconds;
        updateChatAssistAbortCommitState(slotKey, { reply: String(reply || "") });
        showToast("正文已补全");
      }
    }
    if (roundAbortSignal.aborted) {
      finalizeChatAssistRoundAfterUserAbort(roundMaskId, roundThreadId, roundDmSurface, typingInserted);
      return;
    }
    if (roundDmSurface === "offline" && String(reply || "").trim() && !offlineAssistantLinesMeetsLengthSpec(reply, thSend0)) {
      showToast("当面篇幅未达标，正在补写…");
      const refined = await refineOfflineAssistantReplyIfTooShort(
        ai,
        apiMessages,
        rawReply,
        firstParsed,
        reply,
        thSend0,
        roundAbortSignal
      );
      rawReply = refined.rawReply;
      mergeAssistantParsedPreservingHeartPanel(firstParsed, refined.firstParsed);
      reply = coalesceAssistantDisplayReply(refined.reply, refined.rawReply, roundDmSurface);
      updateChatAssistAbortCommitState(slotKey, { reply: String(reply || "") });
    }
    if (roundAbortSignal.aborted) {
      finalizeChatAssistRoundAfterUserAbort(roundMaskId, roundThreadId, roundDmSurface, typingInserted);
      return;
    }
    let transJoined = String(lineTranslationsJoined || "").trim();
    if (transOn && roundDmSurface !== "offline" && reply && transJoined) {
      transJoined = compactTranslationSegmentsToMatchMain(reply, transJoined) || transJoined;
    }
    if (transOn && roundDmSurface !== "offline" && assistantLineTranslationsIncomplete(reply, transJoined)) {
      try {
        const repairMsgs = buildChatTranslationRepairMessages(
          rawReply,
          thSend0,
          roundDmSurface === "offline" ? "offline" : "im"
        );
        const repaired = await ai.chatCompletions(
          {
            messages: repairMsgs,
            ...spreadOptionalMaxTokens(maxTokPrimary),
            response_format: { type: "json_object" }
          },
          aiFetchOpts
        );
        rememberChatApiUsage(repaired?.usage);
        const repRaw = readChatCompletionChoiceText(repaired);
        if (repRaw) {
          const repSt = stripCharLockPlainProtocolBlocksFromText(repRaw);
          const rp2 = parseAssistantPayloadForDmSurface(repSt.text, roundDmSurface, repRaw);
          const { reply: rReply, lineTranslationsJoined: rTrans } = rp2;
          if (String(rReply || "").trim()) reply = rReply;
          transJoined = applyAssistantTranslationRepairResult(
            transJoined,
            rTrans,
            reply,
            roundDmSurface === "offline"
          );
          const c2 = String(rp2.charImageCaption || "").trim();
          if (c2) Object.assign(firstParsed, { charImageCaption: c2 });
          const u2 = sanitizeStickerUrl(String(rp2.charImageUrl || "").trim());
          if (u2) Object.assign(firstParsed, { charImageUrl: u2 });
          const pc2 = normalizeAssistantPlaceCallValue(rp2.placeCall);
          if (pc2) Object.assign(firstParsed, { placeCall: pc2 });
          const nar2 = normalizeAssistantNarrationText(String(rp2.narration || "").trim());
          if (roundDmSurface !== "offline" && nar2) Object.assign(firstParsed, { narration: nar2 });
          mergeStickerIntentFromAssistantRawText(firstParsed, repRaw);
        }
      } catch (_) {
        /* ignore */
      }
    }
    if (
      transOn &&
      roundDmSurface !== "offline" &&
      assistantLineTranslationsIncomplete(reply, transJoined) &&
      String(reply || "").trim()
    ) {
      try {
        const onlyMsgs = buildChatTranslationOnlyMessages(
          reply,
          thSend0,
          roundDmSurface === "offline" ? "offline" : "im"
        );
        const only = await ai.chatCompletions(
          {
            messages: onlyMsgs,
            ...spreadOptionalMaxTokens(maxTokPrimary),
            response_format: { type: "json_object" }
          },
          aiFetchOpts
        );
        rememberChatApiUsage(only?.usage);
        const onlyRaw = readChatCompletionChoiceText(only);
        if (onlyRaw) {
          const onlySt = stripCharLockPlainProtocolBlocksFromText(onlyRaw);
          const { lineTranslationsJoined: tOnly } = parseAssistantPayloadForDmSurface(
            onlySt.text,
            roundDmSurface,
            onlyRaw
          );
          transJoined = applyAssistantTranslationRepairResult(
            transJoined,
            tOnly,
            reply,
            roundDmSurface === "offline"
          );
        }
      } catch (_) {
        /* ignore */
      }
    }
    if (transOn && roundDmSurface === "offline" && offlineAssistantTranslationRepairNeeded(reply, transJoined)) {
      transJoined = await tryRepairOfflineMissingTailTranslations(
        ai,
        reply,
        transJoined,
        thSend0,
        maxTokPrimary
      );
    }
    if (transOn) {
      const s1 = stripParallelRecallMatching(reply, transJoined, recalls);
      reply = s1.reply;
      transJoined = s1.trans;
      const s2 = stripParallelRecallNarration(reply, transJoined, recalls);
      reply = s2.reply;
      transJoined = s2.trans;
    } else {
      reply = stripAssistantLinesMatchingRecalls(reply, recalls);
      reply = stripAssistantRecallUiNarrationLines(reply, recalls);
      transJoined = "";
    }
    reply = stripAssistantVoiceMetaPrefixes(reply);
    {
      const c0 = collapseEmptyParallelAssistantSegments(reply, transOn ? transJoined : "");
      reply = c0.main;
      if (transOn) transJoined = c0.trans;
    }
    const hvRaw = String(firstParsed.heartVoice || "").trim();
    const heartOn = isThreadHeartVoiceEnabled(thSend0);
    const hv = heartOn && hvRaw ? hvRaw.slice(0, 80_000) : "";
    let charImgCap = String(firstParsed.charImageCaption || "").trim();
    let charImgUrl = sanitizeStickerUrl(String(firstParsed.charImageUrl || "").trim());
    const imgCfgAssist = readImageGenConfig();
    const placeCall = resolveAssistantPlaceCall(firstParsed, reply, rawReply);
    mergeStickerIntentFromAssistantRawText(firstParsed, rawReply);
    const replyBeforeStickerRound = reply;
    let stickerPicked = null;
    /** @type {{ keptJoined: string, picked: { url: string, description: string } | null, placements?: object[] }} */
    let stickerOut = { keptJoined: reply, picked: null, placements: [] };
    if (roundDmSurface !== "offline") {
      stickerOut = extractAssistantStickerPick(reply, firstParsed, thSend0, { rawAssistantReply: rawReply });
      reply = stickerOut.keptJoined;
      stickerPicked = stickerOut.picked;
    }
    if (transOn) {
      transJoined = hygieneAssistantTranslationAfterStickerStrip(replyBeforeStickerRound, reply, transJoined);
    }
    if (roundDmSurface === "offline") {
      const off = finalizeOfflineAssistantReplyForStorage(reply, transJoined, transOn);
      reply = off.reply;
      if (transOn) transJoined = off.transJoined;
    }
    {
      const imH = applyImNarratorModeLineHygiene(firstParsed, reply, transJoined, roundDmSurface, thSend0);
      reply = imH.reply;
      transJoined = imH.transJoined;
    }
    const narStored = narrationStoredForDmSurface(
      narrationTextForStorageFromParsed(firstParsed),
      roundDmSurface
    );
    if (charLockLive) {
      stickerPicked = null;
      charImgUrl = "";
      charImgCap = "";
    }
    const charLockLiveRevParsed = charLockLive
      ? extractCharLockLiveReplyReviseFromRaw(rawReply)
      : { draft: "", final: "" };
    if (charLockLive && !String(reply || "").trim()) {
      const liveFin = String(charLockLiveRevParsed.final || "").trim();
      const liveDr = String(charLockLiveRevParsed.draft || "").trim();
      if (liveFin) reply = liveFin;
      else if (liveDr) reply = liveDr;
    }
    if (charLockLive && String(reply || "").trim()) {
      const cleaned = charLockSanitizeLeakedProtocolDisplayText(reply);
      if (cleaned) reply = cleaned;
      else if (charLockLooksLikeLeakedProtocolText(reply)) {
        const fromRaw = charLockSanitizeLeakedProtocolDisplayText(rawReply);
        if (fromRaw) reply = fromRaw;
      }
    }
    const imgPlanAssist = charLockLive
      ? { imgDesc: "", deferSessionImg: false }
      : planAssistantSessionImageAttachment({
          charImageCaption: charImgCap,
          charImgUrl,
          heartVoiceText: hv,
          hvStateText: String(firstParsed.hvState || "").trim(),
          narrationText: String(firstParsed.narration || "").trim(),
          everyRound: isThreadChatEveryRoundSessionImage(thSend0),
          imgCfg: imgCfgAssist,
          thread: thSend0
        });
    const hvStored = charLockLive ? "" : hv;
    const narStoredLive = charLockLive ? "" : narStored;
    const offlineMeetupWillTrigger =
      roundDmSurface !== "offline" && assistantOfflineMeetupWouldTrigger(offlineMeetupRaw);
    if (
      !String(reply || "").trim() &&
      !recalls.length &&
      !hvStored &&
      !charImgCap &&
      !charImgUrl &&
      !isAssistantPlaceCallActive(placeCall) &&
      !stickerPicked &&
      !narStoredLive &&
      !charLockAssistantSpecHasEffect(charLockSpecRound) &&
      !offlineMeetupWillTrigger &&
      !charBlockUserIntentWouldApply(firstParsed, thSend0, roundDmSurface) &&
      !(
        charLockLive &&
        (charLockSession?.modelCharLockRelease ||
          String(charLockLiveRevParsed.final || "").trim() ||
          String(charLockLiveRevParsed.draft || "").trim())
      )
    ) {
      if (opts?.allowSilentReply) {
        const silentNext = readChatLogForMaskThread(roundMaskId, roundThreadId);
        if (typingInserted) removeChatRestoringPlaceholders(silentNext, { includeWithContent: true });
        clearAssistantRestoringFlagsInLog(silentNext);
        saveChatLogForMaskThread(roundMaskId, roundThreadId, silentNext);
        scheduleChatUiRefreshForRound(roundMaskId, roundThreadId, { flush: true });
        scheduleChatProactiveTimer();
        return;
      }
      throw new Error(explainModelEmptyReply(data, rawReply));
    }
    const next = readChatLogForMaskThread(roundMaskId, roundThreadId);
    const at = Date.now();
    const imLineParts =
      roundDmSurface !== "offline" && !charLockLive ? splitImAssistantReplyLines(reply) : [];
    const imMultiBubbleReveal = imLineParts.length > 1;
    /** @type {Record<string, unknown> | null} */
    let upgradeImStreamRow = null;
    if (typingInserted) {
      for (let ri = next.length - 1; ri >= 0; ri--) {
        const m = next[ri];
        if (m && typeof m === "object" && m.role === "assistant" && m.restoring) {
          upgradeImStreamRow = /** @type {Record<string, unknown>} */ (m);
          break;
        }
      }
    }
    if (typingInserted && !upgradeImStreamRow) {
      removeChatRestoringPlaceholders(next, { includeWithContent: true });
    }
    const chatNotifyFromIdx = next.length;
    /** @type {Record<string, unknown> | null} */
    let committedAssistantEntry = null;
    if (
      String(reply || "").trim() ||
      hvStored ||
      stickerPicked ||
      charImgCap ||
      charImgUrl ||
      narStoredLive ||
      charLockAssistantSpecHasEffect(charLockSpecRound) ||
      offlineMeetupWillTrigger ||
      (charLockLive &&
        (String(charLockLiveRevParsed.final || "").trim() ||
          String(charLockLiveRevParsed.draft || "").trim()))
    ) {
      const entry = {
        role: "assistant",
        content: String(reply || "").trim()
          ? String(reply || "")
          : charLockAssistantSpecHasEffect(charLockSpecRound) || offlineMeetupWillTrigger
            ? "\u00A0"
            : "",
        at
      };
      if (!firstParsed.speakAs) {
        const speakAsRaw = parseAssistantSpeakAsFromRaw(rawReply);
        if (speakAsRaw) firstParsed.speakAs = speakAsRaw;
      }
      const speakRoundLive = applyAssistantSpeakAsRound(firstParsed, entry, roundMaskId, roundThreadId);
      if (speakRoundLive.foldBoundarySlot) {
        pushPersonaFoldBoundaryIfNeeded(next, speakRoundLive.foldBoundarySlot);
      }
      if (narStoredLive) entry.narration = narStoredLive;
      if (!charLockLive && roundDmSurface === "offline") {
        tryAttachOfflineAutoSessionImageOnEntry(
          entry,
          String(entry.content || ""),
          firstParsed,
          rawReply,
          thSend0
        );
      } else if (!charLockLive && (imgPlanAssist.imgDesc || charImgUrl)) {
        entry.image = {};
        if (imgPlanAssist.imgDesc) {
          const sc = String(imgPlanAssist.imgDesc).trim().slice(0, 3500);
          entry.image.scenePrompt = sc;
          entry.image.desc = sc.slice(0, 4000);
        }
        if (charImgUrl) entry.image.url = charImgUrl;
        if (imgPlanAssist.deferSessionImg) entry.image.imageGenPending = true;
        applySessionImageSubjectOnRow(
          entry,
          thSend0,
          String(imgPlanAssist.imgDesc || ""),
          next,
          firstParsed.charImageSubject
        );
      }
      if (hvStored) entry.heartVoice = hvStored;
      if (transOn && translationJoinedHasAnyVisible(transJoined)) {
        entry.translation = transJoined.slice(0, 500_000);
      }
      if (!charLockLive && roundDmSurface !== "offline") {
        if (Array.isArray(voiceLines) && voiceLines.some(Boolean)) entry.voiceLines = voiceLines.slice();
        if (Array.isArray(voiceSeconds) && voiceSeconds.some((x) => Number.isFinite(Number(x)))) {
          entry.voiceSeconds = voiceSeconds.slice();
        }
      }
      if (!charLockLive) {
        applyHvPanelFieldsToAssistantEntry(
          entry,
          firstParsed,
          heartOn && firstParsed.fromJson,
          readLastAssistantHvAffinityFromLog(next)
        );
        applyTheaterSnapsToAssistantEntry(entry, firstParsed, thSend0);
        applyInlineHtmlCardsToAssistantEntry(entry, firstParsed);
        if (roundDmSurface !== "offline") {
          tryAttachCharRedpackFromContent(entry);
          if (String(entry.translation || "").trim()) finalizeAssistantEntryTranslation(entry);
        }
        if (roundDmSurface !== "offline") tagChatMessageBlockBadgeIfNeeded(entry, thSend0, "assistant");
      }
      if (charLockLive) {
        const liveRev = charLockLiveRevParsed;
        if (liveRev.draft && liveRev.final && liveRev.draft !== liveRev.final) {
          entry.charLockLiveDraft = liveRev.draft;
          entry.charLockLiveFinal = liveRev.final;
        } else if (liveRev.final && !String(entry.content || "").trim()) {
          entry.charLockLiveFinal = liveRev.final;
        }
      }
      if (
        String(reply || "").trim() ||
        hvStored ||
        charImgCap ||
        charImgUrl ||
        narStoredLive ||
        charLockAssistantSpecHasEffect(charLockSpecRound) ||
        offlineMeetupWillTrigger ||
        (Array.isArray(firstParsed?.inlineHtmlCards) && firstParsed.inlineHtmlCards.length > 0) ||
        (charLockLive &&
          (String(charLockLiveRevParsed.final || "").trim() ||
            String(charLockLiveRevParsed.draft || "").trim()))
      ) {
        let visMark = next.length;
        promoteAssistantComposerQuoteToStructuredStorage(entry, next);
        tagAssistantEntryDmSurface(entry, roundDmSurface);
        if (upgradeImStreamRow) {
          const upIdx = next.indexOf(upgradeImStreamRow);
          if (upIdx >= 0) visMark = upIdx;
          const streamVisibleContent = imMultiBubbleReveal
            ? String(upgradeImStreamRow.content || "")
            : "";
          const streamVisibleTrans = imMultiBubbleReveal
            ? String(upgradeImStreamRow.translation || "")
            : "";
          const streamSegIdx = imMultiBubbleReveal ? upgradeImStreamRow.restoringSegIdx : undefined;
          Object.assign(upgradeImStreamRow, entry);
          if (imMultiBubbleReveal) {
            if (streamVisibleContent.trim()) upgradeImStreamRow.content = streamVisibleContent;
            if (transOn && streamVisibleTrans.trim()) {
              upgradeImStreamRow.translation = streamVisibleTrans;
            }
            upgradeImStreamRow.restoring = true;
            if (streamSegIdx != null && Number.isFinite(Number(streamSegIdx))) {
              upgradeImStreamRow.restoringSegIdx = Math.max(0, Math.floor(Number(streamSegIdx)));
            } else {
              upgradeImStreamRow.restoringSegIdx = splitImAssistantReplyLines(
                String(upgradeImStreamRow.content || "")
              ).length;
            }
          }
          committedAssistantEntry = upgradeImStreamRow;
        } else {
          next.push(entry);
          committedAssistantEntry = entry;
        }
        applyAssistantStickerLayoutToLogEntry(
          next,
          stickerOut,
          committedAssistantEntry,
          roundDmSurface,
          charLockLive
        );
        if (!opts?.allowSilentReply && !charLockLive) {
          assertAssistantRoundAddsVisibleMainChat(next, visMark, roundDmSurface, thSend0, rawReply);
        }
      } else if (stickerPicked && roundDmSurface !== "offline" && !charLockLive) {
        const visMark = next.length;
        applyAssistantStickerLayoutToLogEntry(next, stickerOut, entry, roundDmSurface, charLockLive);
        if (!opts?.allowSilentReply) {
          assertAssistantRoundAddsVisibleMainChat(next, visMark, roundDmSurface, thSend0, rawReply);
        }
      }
    }
    try {
      if (roundDmSurface !== "offline") {
        const decRaw =
          firstParsed && typeof firstParsed === "object" ? String(firstParsed.redpackDecision || "").trim() : "";
        const decision =
          decRaw === "claimed" || decRaw === "returned"
            ? decRaw
            : detectRedpackDecisionFromAssistant(String(reply || "")) ||
              detectRedpackDecisionFromAssistant(String(rawReply || ""));
        if (decision === "claimed" || decision === "returned") applyRedpackDecisionToLatest(next, decision);
      }
    } catch (_) {
      /* ignore */
    }
    for (const r of recalls) {
      next.push({
        role: "notice",
        kind: "recall_char",
        at,
        content: "",
        recalledContent: r.recalledContent,
        innerVoice: r.innerVoice,
        recalledTranslation: r.recalledTranslation
      });
    }
    let charRemarkNotice = null;
    if (!charLockLive) {
      try {
        charRemarkNotice = buildCharRemarkForUserChangeNoticeFromAssistant(
          firstParsed,
          roundMaskId,
          roundThreadId,
          roundDmSurface,
          thSend0,
          at
        );
        if (charRemarkNotice) next.push(charRemarkNotice);
      } catch (_) {
        /* ignore */
      }
    }
    if (!charLockLive) {
      pushCharBlockUserNoticeFromAssistantIfAny(
        next,
        firstParsed,
        roundMaskId,
        roundThreadId,
        roundDmSurface,
        thSend0,
        at
      );
    }
    if (imMultiBubbleReveal && committedAssistantEntry) {
      await revealImAssistantEntryBubbleStagger({
        log: next,
        entry: committedAssistantEntry,
        maskId: roundMaskId,
        threadId: roundThreadId,
        thread: thSend0,
        fullContent: reply,
        fullTranslation: transJoined,
        transOn,
        forceRevealFromStart: !useImStream || !upgradeImStreamRow,
        signal: roundAbortSignal
      });
    }
    clearAssistantRestoringFlagsInLog(next);
    removeChatRestoringPlaceholders(next);
    saveChatLogForMaskThread(roundMaskId, roundThreadId, next);
    scheduleChatUiRefreshForRound(roundMaskId, roundThreadId, { animateLatest: true, flush: true });
    finalizeCharThreadAvatarFromUserSentImage(
      firstParsed,
      next,
      rawReply,
      roundMaskId,
      roundThreadId,
      roundDmSurface
    );
    finalizeCharRemarkForUserFromAssistant(charRemarkNotice, roundMaskId, roundThreadId);
    kickoffPendingSessionImageGen(next, roundThreadRef);
    kickoffTheaterSnapGen(
      next,
      roundThreadRef,
      committedAssistantEntry != null ? next.indexOf(committedAssistantEntry) : undefined,
      roundDmSurface
    );
    scheduleChatProactiveTimer();
    try {
      if (!opts?.charLockLive) {
        const ci =
          committedAssistantEntry != null ? next.indexOf(committedAssistantEntry) : -1;
        maybePushChatNotifyNewEntries(
          roundMaskId,
          roundThreadId,
          next,
          ci >= 0 ? ci : chatNotifyFromIdx
        );
      }
    } catch (_) {
      /* ignore */
    }
    maybeTriggerCharMomentPostAfterChatRound({
      firstParsed,
      rawReply,
      roundMaskId,
      roundThreadId,
      th: thSend0,
      roundDmSurface,
      suppress: Boolean(opts?.suppressCharLockAndCallSideEffects || opts?.charLockLive)
    });
    maybeTriggerCharMomentsProactiveAfterChatRound({
      roundMaskId,
      roundThreadId,
      th: thSend0,
      roundDmSurface,
      suppress: Boolean(opts?.suppressCharLockAndCallSideEffects || opts?.charLockLive)
    });
    maybeApplyRelationDmForwardFromAssistant(
      firstParsed,
      roundMaskId,
      roundThreadId,
      thSend0,
      roundDmSurface,
      rawReply
    ).catch((e) => {
      console.warn("[relation-dm-forward] apply failed", e);
    });
    maybeApplyForumCommentFromAssistant(firstParsed, roundMaskId, thSend0);
    if (CHAT_CHAR_FORUM_SHARE_TO_USER_ENABLED) {
      maybeApplyForumShareFromAssistant(firstParsed, roundMaskId, roundThreadId, thSend0);
    }
    {
      const curRef = readChatActiveThreadRef();
      const curMask = String(getActiveMaskIdForInbox() || "").trim();
      const refMask = String(curRef.maskId || curMask || "").trim();
      if (curRef.threadId === roundThreadId && refMask === roundMaskId) {
        if (!opts?.suppressCharLockAndCallSideEffects) {
          applyAssistantCharLockOfflineCallSideEffects(
            charLockSpecRound,
            offlineMeetupWillTrigger ? offlineMeetupRaw : null,
            placeCall,
            roundDmSurface
          );
        }
        maybeMemoAutoAfterAssistantRound();
      }
    }
  } catch (err) {
    if (isChatAssistAbortError(err)) {
      finalizeChatAssistRoundAfterUserAbort(roundMaskId, roundThreadId, roundDmSurface, typingInserted);
      return;
    }
    const msg = err instanceof Error ? err.message : String(err);
    const invisible = isChatInvisibleAssistantReplyError(err);
    const displayMsg = invisible
      ? chatInvisibleAssistantReplyExplainText()
      : msg;
    const next = readChatLogForMaskThread(roundMaskId, roundThreadId);
    removeChatRestoringPlaceholders(next, { includeWithContent: true });
    clearAssistantRestoringFlagsInLog(next);
    const abortSt = getChatAssistAbortCommitStateForSlot(slotKey);
    const partial =
      abortSt &&
      abortSt.roundMaskId === roundMaskId &&
      abortSt.roundThreadId === roundThreadId
        ? String(abortSt.reply || "").trim()
        : "";
    if (invisible && partial) {
      const entry = { role: "assistant", content: partial, at: Date.now() };
      tagAssistantEntryDmSurface(entry, roundDmSurface);
      tagAssistantEntrySpeakerPersona(entry, thSend0 || readActiveThread());
      next.push(entry);
      saveChatLogForMaskThread(roundMaskId, roundThreadId, next);
      chatSuppressNextChatMessageAnimations = true;
      scheduleChatUiRefreshForRound(roundMaskId, roundThreadId, { flush: true });
      showToast("已保留部分回复");
      scheduleChatProactiveTimer();
      return;
    }
    const failEnt = { role: "assistant", content: `（未能回复）${displayMsg}`, at: Date.now() };
    tagAssistantEntryDmSurface(failEnt, roundDmSurface);
    next.push(failEnt);
    saveChatLogForMaskThread(roundMaskId, roundThreadId, next);
    chatSuppressNextChatMessageAnimations = true;
    scheduleChatUiRefreshForRound(roundMaskId, roundThreadId, { flush: true });
    showToast(invisible ? "没有可显示的文字" : "发送失败");
    scheduleChatProactiveTimer();
  } finally {
    clearChatActiveAssistAbortController(slotKey, roundAbortController);
  }
}

async function sendChatFromInput() {
  const input = document.getElementById("chat-input");
  const btn = document.getElementById("chat-send");
  const bodyText = getChatComposerDraftBodyText();
  const stQ = chatComposerQuoteStruct;
  const hasStructQuote = Boolean(stQ && String(stQ.text || "").trim());
  const legacyPlain = String(chatComposerQuotePlain || "").trim();
  const composedTokens = getChatComposerDraftCombinedForTokens().trim();
  const emptySend = !bodyText && !hasStructQuote && !legacyPlain;

  let sendPin = beginChatSendPin();
  if (!sendPin) sendPin = await beginChatSendPinAsync();
  if (!sendPin) {
    showChatThreadUnavailableToast(resolveActiveChatThreadLoadState());
    return;
  }

  if (isChatAssistRoundInflightForThread(sendPin.maskId, sendPin.threadId)) {
    if (emptySend) {
      abortChatAssistRoundForThread(sendPin.maskId, sendPin.threadId);
      return;
    }
    // 有正文：不 abort，user 气泡照常落库（同密谈 API 仍按 slot 排队）
  }

  const roundAssistOpts = {
    boundMaskId: sendPin.maskId,
    boundThreadId: sendPin.threadId,
    boundThread: sendPin.thread,
    boundDmSurface: resolveChatRoundDmSurface(
      { boundMaskId: sendPin.maskId, boundThreadId: sendPin.threadId, boundThread: sendPin.thread },
      sendPin.thread,
      sendPin.maskId,
      sendPin.threadId
    )
  };

  try {
  if (!emptySend) {
    const log = readChatLogForSendPin(sendPin);
    if (chatComposerPatchMsgIdx >= 0 && chatComposerPatchRole) {
      const mi = chatComposerPatchMsgIdx;
      const pr = chatComposerPatchRole;
      if (mi >= 0 && mi < log.length && (pr === "user" || pr === "assistant")) {
        const msg = log[mi];
        if (msg && msg.role === pr) {
          if (chatComposerPatchWholeRow) {
            const patchText =
              readMessageQuoteRef(msg) && pr === "user" ? getChatComposerDraftBodyText() : composedTokens;
            if (pr === "user" && readMessageQuoteRef(msg) && msg.quote && typeof msg.quote === "object") {
              const bodyParts = String(patchText ?? "")
                .split(/\n\n/)
                .map((s) => String(s).trim())
                .filter((s) => s.length > 0);
              msg.content = bodyParts.length ? bodyParts.join("|||") : " ";
            } else {
              const flat = String(patchText ?? "").trim();
              const segs = flat
                .split(/\n\n/)
                .map((s) => String(s).trim())
                .filter((s) => s.length > 0);
              msg.content = segs.length ? segs.join("|||") : flat || " ";
            }
            if (pr === "assistant") {
              delete msg.translation;
              delete msg.voiceLines;
              delete msg.voiceSeconds;
              delete msg.voiceRevealSegs;
            }
            clearChatComposerResendPlacement();
            saveChatLogForSendPin(sendPin, log);
            if (input) input.value = "";
            clearChatComposerQuote();
            finishComposerPatchSaveAndRefresh(mi);
            return;
          }
          if (chatComposerPatchSegIdx >= 0) {
            const si = chatComposerPatchSegIdx;
            const patchText =
              readMessageQuoteRef(msg) && pr === "user" ? getChatComposerDraftBodyText() : composedTokens;
            if (isChatNarrationSheetSeg(si)) {
              const nar = normalizeAssistantNarrationText(patchText);
              if (nar) {
                const thPatch = readActiveThread();
                msg.narration =
                  thPatch && !isThreadNarratorIncludeInner(thPatch)
                    ? stripNarrationInnerAsteriskSpans(nar)
                    : nar;
              } else delete msg.narration;
              clearChatComposerResendPlacement();
              saveChatLogForSendPin(sendPin, log);
              if (input) input.value = "";
              clearChatComposerQuote();
              finishComposerPatchSaveAndRefresh(mi);
              showToast("已更新旁白");
              return;
            }
            if (chatComposerPatchImageDesc) {
              applyChatImageDescPatch(msg, patchText);
              const regenQueued = queueSessionImageRegenAfterDescPatch(msg);
              clearChatComposerResendPlacement();
              saveChatLogForSendPin(sendPin, log);
              if (input) input.value = "";
              clearChatComposerQuote();
              finishComposerPatchSaveAndRefresh(mi);
              if (regenQueued) {
                kickoffPendingSessionImageGen(log, { maskId: sendPin.maskId, threadId: sendPin.threadId }, mi);
              }
              showToast(regenQueued ? "已更新生图提示词，配图重绘中…" : "已更新图片描述");
              return;
            } else {
              msg.content = applyChatBubbleActionSheetSegmentToContent(
                String(msg.content ?? ""),
                pr,
                si,
                patchText,
                msg,
                chatComposerPatchQuoteDomSeg >= 0 ? chatComposerPatchQuoteDomSeg : undefined,
                chatComposerPatchBodyDomSeg >= 0 ? chatComposerPatchBodyDomSeg : undefined
              );
              if (pr === "assistant") {
                const ch0 = String(msg.content ?? "")
                  .split(/\|\|\|/)
                  .map((s) => String(s).trim())
                  .filter(Boolean);
                const chunkArr0 = ch0.length ? ch0 : [String(msg.content ?? "").trim() || " "];
                const { quoteRef: qrf0 } = resolveComposerQuotedDisplayPartsForSurface(chunkArr0, "assistant", msg);
                const bodyDomForTrans =
                  chatComposerPatchBodyDomSeg >= 0 ? chatComposerPatchBodyDomSeg : 1;
                let transSeg = si;
                if (chatMessageHasBubbleImageCard(msg) && !readMessageQuoteRef(msg) && si > 0) {
                  transSeg = si - 1;
                }
                if (qrf0 && si === bodyDomForTrans) delete msg.translation;
                else patchAssistantTranslationOneSegment(msg, transSeg, "");
                clearAssistantVoiceMarkAtSegment(msg, transSeg);
              }
            }
            clearChatComposerResendPlacement();
            saveChatLogForSendPin(sendPin, log);
            if (input) input.value = "";
            clearChatComposerQuote();
            finishComposerPatchSaveAndRefresh(mi);
            return;
          }
        }
      }
      clearChatComposerResendPlacement();
    }
    const insA = chatComposerResendAssistantAtIdx;
    const useAssistantSlot =
      Number.isFinite(insA) && insA >= 0 && insA <= log.length && chatComposerResendAssistantAtIdx >= 0;
    if (useAssistantSlot) {
      const atMs =
        Number.isFinite(chatComposerResendAssistantAt) ? chatComposerResendAssistantAt : Date.now();
      const entry = { role: "assistant", content: composedTokens, at: atMs };
      tagAssistantEntryDmSurface(entry, getActiveChatDmSurfaceForContext());
      log.splice(insA, 0, entry);
      clearChatComposerResendPlacement();
      saveChatLogForSendPin(sendPin, log);
      if (input) input.value = "";
      clearChatComposerQuote();
      scheduleRenderChatMessages();
      scheduleChatContextTokenLabelUpdate();
      scheduleChatProactiveTimer();
      return;
    }
    const ins = chatComposerResendUserAtIdx;
    const useResendSlot =
      Number.isFinite(ins) && ins >= 0 && ins <= log.length && chatComposerResendUserAtIdx >= 0;
    const atMs = useResendSlot && Number.isFinite(chatComposerResendUserAt) ? chatComposerResendUserAt : Date.now();
    const entry = { role: "user", content: "", at: atMs };
    const sendOffline = roundAssistOpts.boundDmSurface === "offline";
    if (hasStructQuote && !sendOffline) {
      entry.content = bodyText;
      entry.quote = {
        refAt: Number(stQ.refAt),
        refSeg: Math.max(0, Math.floor(Number(stQ.refSeg)) || 0),
        text: String(stQ.text || "").trim().slice(0, 4000),
        role: String(stQ.role || ""),
        ...(String(stQ.refSpeakerCharId || "").trim()
          ? { refSpeakerCharId: String(stQ.refSpeakerCharId).trim() }
          : {})
      };
    } else {
      entry.content = composedTokens;
    }
    // 红包：线下晤面不落库即时红包卡片（此处跳过）。
    try {
      if (getActiveChatDmSurfaceForContext() !== "offline") {
        const rpLine = String(entry.content || "").trim() || (hasStructQuote ? String(stQ.text || "").trim() : "");
        const rp = parseRedpackMessageText(rpLine);
        const thRp = sendPin.thread || readActiveThread();
        if (rp && !(thRp && thRp.kind === "group")) {
          entry.redpack = { id: makeRedpackId(), amt: rp.amt, note: rp.note, status: "sent" };
          const rpAt = findInlineRedpackStart(rpLine);
          if (rpAt > 0) {
            const before = rpLine.slice(0, rpAt).trim();
            const after = rpLine.slice(rpAt).trim();
            entry.content = [before, after].filter(Boolean).join("|||");
          }
        }
      }
    } catch (_) {
      /* ignore */
    }
    if (chatComposerSendAsVoice && getActiveChatDmSurfaceForContext() !== "offline") {
      entry.asVoice = true;
      entry.voiceSeconds = estimateVoiceSeconds(composedTokens);
    }
    if (entry.role === "user" && !entry.image && getActiveChatDmSurfaceForContext() !== "offline") {
      const imgPlan = parseUserComposerDescImage(String(entry.content || "").trim());
      if (imgPlan) {
        entry.content = imgPlan.content;
        const thImg = readActiveThread();
        const descApiGen = isThreadDescImageApiGenEnabled(thImg) && isSessionImageGenConfigured();
        entry.image = { desc: imgPlan.cap.slice(0, 4000) };
        if (descApiGen) {
          entry.image.scenePrompt = imgPlan.cap.slice(0, 3500);
          entry.image.imageGenPending = true;
          applySessionImageSubjectOnRow(entry, thImg, imgPlan.cap, log, null);
        }
      }
    }
    tagOutgoingChatDmSurfaceIfOffline(entry);
    const thSendBadge = sendPin.thread || readActiveThread();
    if (!sendOffline) tagChatMessageBlockBadgeIfNeeded(entry, thSendBadge, "user");
    const pushedAt = Date.now();
    let imgGenIdx = -1;
    if (useResendSlot) {
      log.splice(ins, 0, entry);
      imgGenIdx = ins;
      clearChatComposerResendPlacement();
    } else {
      clearChatComposerResendPlacement();
      log.push({ ...entry, at: pushedAt });
      imgGenIdx = log.length - 1;
    }
    if (input) input.value = "";
    clearChatComposerQuote();
    saveChatLogForSendPin(sendPin, log);
    if (entry.image?.imageGenPending && imgGenIdx >= 0) {
      kickoffPendingSessionImageGen(log, { maskId: sendPin.maskId, threadId: sendPin.threadId }, imgGenIdx);
    }
    scheduleRenderChatMessagesAfterUserSend();
    scheduleChatContextTokenLabelUpdate();
    scheduleChatProactiveTimer();
    if (getActiveChatDmSurfaceForContext() === "offline") {
      try {
        await executeChatAssistantRound(roundAssistOpts, btn);
      } finally {
        syncChatSendButtonForActiveThread();
      }
    }
    return;
  }

  clearChatComposerResendPlacement();

  // 空输入点发送：若上一条是对方刚回的气泡，则弹出选择「继续说 / 重 roll」。
  // 继续说：沿用原逻辑（代发一句催对方接话）。
  // 重 roll：重新调用一次 API，替换末尾连续的一段对方回复（支持文字 + 表情包拆条等），不改你方输入，不回滚更早历史。
  const lastBubble = chatLogLastBubbleMessageForActiveUiSurface();
  if (lastBubble && lastBubble.role === "assistant") {
    openChatSendChoiceDialog();
    return;
  }

  try {
    await executeChatAssistantRound(roundAssistOpts, btn);
  } finally {
    syncChatSendButtonForActiveThread();
  }
  } catch (err) {
    console.warn("[chat] sendChatFromInput failed", err);
    showToast("发送失败，请重试");
  }
}

function isChatSendChoiceOpen() {
  const root = document.getElementById("chat-send-choice");
  return !!(root && !root.hidden);
}

function closeChatSendChoiceDialog() {
  const root = document.getElementById("chat-send-choice");
  if (!root) return;
  root.hidden = true;
  root.setAttribute("aria-hidden", "true");
}

function openChatSendChoiceDialog() {
  const root = document.getElementById("chat-send-choice");
  if (!root) return;
  root.hidden = false;
  root.setAttribute("aria-hidden", "false");
  window.requestAnimationFrame(() => {
    document.getElementById("chat-send-choice-continue")?.focus();
  });
}

/**
 * 重 roll：末尾连续对方回复（文字 / 配图 / 表情包拆条等）的起止下标。
 * @param {unknown[]} log
 * @returns {{ runStart: number, idxLastAsst: number } | null}
 */
function findAssistantRerollRunBounds(log) {
  const arr = Array.isArray(log) ? log : [];
  let idxLastAsst = -1;
  for (let i = arr.length - 1; i >= 0; i--) {
    const m = arr[i];
    if (!m || typeof m !== "object" || m.role !== "assistant") continue;
    if (m.charLockSessionOnly) continue;
    idxLastAsst = i;
    break;
  }
  if (idxLastAsst < 0) return null;
  let runStart = idxLastAsst;
  while (runStart > 0) {
    const prev = arr[runStart - 1];
    if (!prev || typeof prev !== "object" || prev.role !== "assistant" || prev.charLockSessionOnly) break;
    runStart--;
  }
  return { runStart, idxLastAsst };
}

/** 重 roll / 重回：整段对方气泡进入占位（清空正文与配图/表情等）。 @param {unknown} m */
function markAssistantMessageRestoring(m) {
  if (!m || typeof m !== "object" || m.role !== "assistant") return;
  /** @type {any} */
  const live = m;
  live.restoring = true;
  delete live.restoringSegIdx;
  live.content = "";
  delete live.translation;
  delete live.voiceLines;
  delete live.voiceSeconds;
  delete live.voiceRevealSegs;
  delete live.heartVoice;
  delete live.hvState;
  delete live.hvMood;
  delete live.hvDesire;
  delete live.hvAffinity;
  delete live.hvAffectionDesc;
  delete live.narration;
  delete live.image;
  delete live.sticker;
  delete live.stickerPlacements;
}

async function rerollLastAssistantMessage() {
  const ai = window.RP_AI;
  if (!ai) {
    showToast("AI 模块未加载");
    return;
  }
  const rerollPin = await beginChatSendPinAsync();
  if (!rerollPin) {
    showChatThreadUnavailableToast();
    return;
  }
  if (isChatAssistRoundInflightForThread(rerollPin.maskId, rerollPin.threadId)) {
    showToast("对方正在回复…");
    return;
  }
  const rerollBound = chatRoundBoundFromPin(rerollPin);
  const log = readChatLogForSendPin(rerollPin);
  const bounds = findAssistantRerollRunBounds(log);
  if (!bounds) {
    showToast("没有可重 roll 的回复");
    return;
  }
  const { runStart, idxLastAsst } = bounds;
  const rerollBackupRun = log.slice(runStart, idxLastAsst + 1).map((m) => (m && typeof m === "object" ? { ...m } : m));
  const prefix = log.slice(0, runStart);
  const th0 = rerollPin.thread;
  const rollSurface = getActiveChatDmSurfaceForContext();
  const reasonDlg = await openChatRerollReasonDialog({ mode: "reroll" });
  if (!reasonDlg.confirmed) return;
  const reasonApi = buildChatRerollReasonEmptySendContent(reasonDlg, { mode: "reroll" });
  const rerollApiOpts = {
    ...rerollBound,
    ...(reasonApi ? { emptySendUserContent: reasonApi } : {})
  };
  const maxTokReroll = null;
  const apiLog = sliceChatLogForApiMemoryWindowAnchoredToLastUser(prefix, rollSurface, th0);
  const apiMessages = await buildChatApiMessagesFromLogAsync(true, apiLog, rerollApiOpts, rollSurface);
  // 视觉反馈：末尾连续的多条对方气泡（文字 + 表情包/发图拆条等）一并进入「重回中」占位，避免只动最后一条
  try {
    preserveChatMessagesScrollForNextRender();
    const liveLog = readChatLogForSendPin(rerollPin);
    if (runStart <= idxLastAsst && idxLastAsst < liveLog.length) {
      for (let i = runStart; i <= idxLastAsst; i++) {
        markAssistantMessageRestoring(liveLog[i]);
      }
      saveChatLogForSendPin(rerollPin, liveLog);
      scheduleChatUiRefreshForRound(rerollPin.maskId, rerollPin.threadId, { flush: true });
    }
  } catch (_) {
    /* ignore */
  }
  try {
    await runChatAssistRoundWithSendUi(rerollBound, async (signal) => {
    const data = await requestChatAssistantCompletion(ai, {
      messages: apiMessages,
      ...spreadOptionalMaxTokens(maxTokReroll),
      response_format: { type: "json_object" },
      signal
    });
    rememberChatApiUsage(data?.usage);
    updateChatContextTokenLabel();
    let rawReply = readChatCompletionSalvagedText(data);
    if (!rawReply) throw new Error(explainModelEmptyReply(data, rawReply));
    const charLockStripReroll = stripCharLockPlainProtocolBlocksFromText(rawReply);
    const firstParsed = parseAssistantPayloadForDmSurface(
      charLockStripReroll.text,
      rollSurface,
      rawReply
    );
    const charLockSpecReroll = mergeCharLockAssistantSpecs(
      charLockStripReroll.spec,
      extractCharLockAssistantSpecFromBalancedJson(rawReply)
    );
    let { reply: parsedReply, recalls, lineTranslationsJoined, voiceLines, voiceSeconds } = firstParsed;
    const offlineMeetupRawReroll = extractAssistantOfflineMeetupFromRaw(rawReply);
    const th1 = resolveChatPromptThread(rerollBound);
    const transOn = isThreadCharTranslationEnabled(th1);
    let reply = coalesceAssistantDisplayReply(parsedReply, rawReply, rollSurface);
    if (!String(reply || "").trim() && String(rawReply || "").trim()) {
      const lineRepair = await tryRepairAssistantLinesOnly(ai, rawReply, maxTokReroll, rollSurface, signal);
      if (lineRepair) {
        rawReply = lineRepair.repRaw;
        mergeAssistantParsedPreservingHeartPanel(firstParsed, lineRepair.parsed);
        parsedReply = lineRepair.parsed.reply;
        reply = coalesceAssistantDisplayReply(parsedReply, rawReply, rollSurface);
        recalls = firstParsed.recalls;
        lineTranslationsJoined = firstParsed.lineTranslationsJoined;
        voiceLines = firstParsed.voiceLines;
        voiceSeconds = firstParsed.voiceSeconds;
        showToast("正文已补全");
      }
    }
    if (
      rollSurface === "offline" &&
      String(reply || "").trim() &&
      th1 &&
      !offlineAssistantLinesMeetsLengthSpec(reply, th1)
    ) {
      showToast("当面篇幅未达标，正在补写…");
      const refined = await refineOfflineAssistantReplyIfTooShort(
        ai,
        apiMessages,
        rawReply,
        firstParsed,
        reply,
        th1,
        signal
      );
      rawReply = refined.rawReply;
      mergeAssistantParsedPreservingHeartPanel(firstParsed, refined.firstParsed);
      reply = coalesceAssistantDisplayReply(refined.reply, refined.rawReply, rollSurface);
    }
    let transJoined = String(lineTranslationsJoined || "").trim();
    if (transOn && rollSurface !== "offline" && assistantLineTranslationsIncomplete(reply, transJoined)) {
      try {
        const repairMsgs = buildChatTranslationRepairMessages(
          rawReply,
          th1,
          rollSurface === "offline" ? "offline" : "im"
        );
        const repaired = await ai.chatCompletions(
          {
            messages: repairMsgs,
            ...spreadOptionalMaxTokens(maxTokReroll),
            response_format: { type: "json_object" }
          },
          { signal }
        );
        rememberChatApiUsage(repaired?.usage);
        const repRaw = readChatCompletionChoiceText(repaired);
        if (repRaw) {
          const repSt = stripCharLockPlainProtocolBlocksFromText(repRaw);
          const rp2 = parseAssistantPayloadForDmSurface(repSt.text, rollSurface, repRaw);
          const { reply: rReply, lineTranslationsJoined: rTrans } = rp2;
          if (String(rReply || "").trim()) reply = rReply;
          transJoined = applyAssistantTranslationRepairResult(
            transJoined,
            rTrans,
            reply,
            rollSurface === "offline"
          );
          const c2 = String(rp2.charImageCaption || "").trim();
          if (c2) Object.assign(firstParsed, { charImageCaption: c2 });
          const u2 = sanitizeStickerUrl(String(rp2.charImageUrl || "").trim());
          if (u2) Object.assign(firstParsed, { charImageUrl: u2 });
          const pc2 = normalizeAssistantPlaceCallValue(rp2.placeCall);
          if (pc2) Object.assign(firstParsed, { placeCall: pc2 });
          const nar2 = normalizeAssistantNarrationText(String(rp2.narration || "").trim());
          if (rollSurface !== "offline" && nar2) Object.assign(firstParsed, { narration: nar2 });
          mergeStickerIntentFromAssistantRawText(firstParsed, repRaw);
        }
      } catch (_) {
        /* ignore */
      }
    }
    if (
      transOn &&
      rollSurface !== "offline" &&
      assistantLineTranslationsIncomplete(reply, transJoined) &&
      String(reply || "").trim()
    ) {
      try {
        const onlyMsgs = buildChatTranslationOnlyMessages(
          reply,
          th1,
          rollSurface === "offline" ? "offline" : "im"
        );
        const only = await ai.chatCompletions(
          {
            messages: onlyMsgs,
            ...spreadOptionalMaxTokens(maxTokReroll),
            response_format: { type: "json_object" }
          },
          { signal }
        );
        rememberChatApiUsage(only?.usage);
        const onlyRaw = readChatCompletionChoiceText(only);
        if (onlyRaw) {
          const onlySt = stripCharLockPlainProtocolBlocksFromText(onlyRaw);
          const { lineTranslationsJoined: tOnly } = parseAssistantPayloadForDmSurface(
            onlySt.text,
            rollSurface,
            onlyRaw
          );
          transJoined = applyAssistantTranslationRepairResult(
            transJoined,
            tOnly,
            reply,
            rollSurface === "offline"
          );
        }
      } catch (_) {
        /* ignore */
      }
    }
    if (transOn && rollSurface === "offline" && offlineAssistantTranslationRepairNeeded(reply, transJoined)) {
      transJoined = await tryRepairOfflineMissingTailTranslations(
        ai,
        reply,
        transJoined,
        th1,
        maxTokReroll
      );
    }
    if (transOn) {
      const s1 = stripParallelRecallMatching(reply, transJoined, recalls);
      reply = s1.reply;
      transJoined = s1.trans;
      const s2 = stripParallelRecallNarration(reply, transJoined, recalls);
      reply = s2.reply;
      transJoined = s2.trans;
    } else {
      reply = stripAssistantLinesMatchingRecalls(reply, recalls);
      reply = stripAssistantRecallUiNarrationLines(reply, recalls);
      transJoined = "";
    }
    reply = stripAssistantVoiceMetaPrefixes(reply);
    {
      const c0 = collapseEmptyParallelAssistantSegments(reply, transOn ? transJoined : "");
      reply = c0.main;
      if (transOn) transJoined = c0.trans;
    }
    mergeStickerIntentFromAssistantRawText(firstParsed, rawReply);
    const replyBeforeStickerReroll = reply;
    let stickerPickedReroll = null;
    /** @type {{ keptJoined: string, picked: { url: string, description: string } | null, placements?: object[] }} */
    let stickerPickRoll = { keptJoined: reply, picked: null, placements: [] };
    if (rollSurface !== "offline") {
      stickerPickRoll = extractAssistantStickerPick(reply, firstParsed, th1, { rawAssistantReply: rawReply });
      reply = stickerPickRoll.keptJoined;
      stickerPickedReroll = stickerPickRoll.picked;
    }
    if (transOn) {
      transJoined = hygieneAssistantTranslationAfterStickerStrip(replyBeforeStickerReroll, reply, transJoined);
    }
    if (rollSurface === "offline") {
      const off = finalizeOfflineAssistantReplyForStorage(reply, transJoined, transOn);
      reply = off.reply;
      if (transOn) transJoined = off.transJoined;
    }
    {
      const imH = applyImNarratorModeLineHygiene(firstParsed, reply, transJoined, rollSurface, th1);
      reply = imH.reply;
      transJoined = imH.transJoined;
    }
    const hvRaw = String(firstParsed.heartVoice || "").trim();
    const heartOn = isThreadHeartVoiceEnabled(th1);
    const hv = heartOn && hvRaw ? hvRaw.slice(0, 80_000) : "";
    const charImgCap = String(firstParsed.charImageCaption || "").trim();
    let charImgUrl = sanitizeStickerUrl(String(firstParsed.charImageUrl || "").trim());
    const imgCfgReroll = readImageGenConfig();
    const imgPlanReroll = planAssistantSessionImageAttachment({
      charImageCaption: charImgCap,
      charImgUrl,
      heartVoiceText: hv,
      hvStateText: String(firstParsed.hvState || "").trim(),
      narrationText: String(firstParsed.narration || "").trim(),
      everyRound: isThreadChatEveryRoundSessionImage(th1),
      imgCfg: imgCfgReroll,
      thread: th1
    });
    const placeCall = resolveAssistantPlaceCall(firstParsed, reply, rawReply);
    const narStored = narrationStoredForDmSurface(
      narrationTextForStorageFromParsed(firstParsed),
      rollSurface
    );
    const offlineMeetupWillTriggerReroll =
      rollSurface !== "offline" && assistantOfflineMeetupWouldTrigger(offlineMeetupRawReroll);
    reply = coalesceAssistantDisplayReply(reply, rawReply, rollSurface);
    if (
      !String(reply || "").trim() &&
      !recalls.length &&
      !hv &&
      !charImgCap &&
      !charImgUrl &&
      !isAssistantPlaceCallActive(placeCall) &&
      !stickerPickedReroll &&
      !narStored &&
      !charLockAssistantSpecHasEffect(charLockSpecReroll) &&
      !offlineMeetupWillTriggerReroll &&
      !charBlockUserIntentWouldApply(firstParsed, th1, rollSurface)
    ) {
      throw new Error(explainModelEmptyReply(data, rawReply));
    }
    const at = Date.now();
    const next = readChatLogForSendPin(rerollPin);
    const rerollDelLen = idxLastAsst - runStart + 1;
    if (runStart >= 0 && runStart + rerollDelLen <= next.length) {
      next.splice(runStart, rerollDelLen);
    }
    const insertAt = Math.min(Math.max(0, runStart), next.length);
    /** @type {object | null} */
    let restoredEntry = null;
    if (
      String(reply || "").trim() ||
      hv ||
      charImgCap ||
      charImgUrl ||
      stickerPickedReroll ||
      narStored ||
      charLockAssistantSpecHasEffect(charLockSpecReroll) ||
      offlineMeetupWillTriggerReroll
    ) {
      const entry = {
        role: "assistant",
        content: String(reply || "").trim()
          ? String(reply || "")
          : charLockAssistantSpecHasEffect(charLockSpecReroll) || offlineMeetupWillTriggerReroll
            ? "\u00A0"
            : "",
        at
      };
      if (!firstParsed.speakAs) {
        const speakAsRaw = parseAssistantSpeakAsFromRaw(rawReply);
        if (speakAsRaw) firstParsed.speakAs = speakAsRaw;
      }
      const speakRoundReroll = applyAssistantSpeakAsRound(
        firstParsed,
        entry,
        rerollPin.maskId,
        rerollPin.threadId
      );
      const entryInsertAt = resolveAssistantEntryInsertAt(
        next,
        insertAt,
        speakRoundReroll.foldBoundarySlot || ""
      );
      if (narStored) entry.narration = narStored;
      if (rollSurface === "offline") {
        tryAttachOfflineAutoSessionImageOnEntry(
          entry,
          String(entry.content || ""),
          firstParsed,
          rawReply,
          th1
        );
      } else if (imgPlanReroll.imgDesc || charImgUrl) {
        entry.image = {};
        if (imgPlanReroll.imgDesc) {
          const sc = String(imgPlanReroll.imgDesc).trim().slice(0, 3500);
          entry.image.scenePrompt = sc;
          entry.image.desc = sc.slice(0, 4000);
        }
        if (charImgUrl) entry.image.url = charImgUrl;
        if (imgPlanReroll.deferSessionImg) entry.image.imageGenPending = true;
        applySessionImageSubjectOnRow(
          entry,
          th1,
          String(imgPlanReroll.imgDesc || ""),
          next,
          firstParsed.charImageSubject
        );
      }
      if (hv) entry.heartVoice = hv;
      if (transOn && translationJoinedHasAnyVisible(transJoined)) {
        entry.translation = transJoined.slice(0, 500_000);
        finalizeAssistantEntryTranslation(entry);
      }
      if (rollSurface !== "offline") {
        if (Array.isArray(voiceLines) && voiceLines.some(Boolean)) entry.voiceLines = voiceLines.slice();
        if (Array.isArray(voiceSeconds) && voiceSeconds.some((x) => Number.isFinite(Number(x)))) {
          entry.voiceSeconds = voiceSeconds.slice();
        }
      }
      applyHvPanelFieldsToAssistantEntry(
        entry,
        firstParsed,
        heartOn && firstParsed.fromJson,
        readLastAssistantHvAffinityFromLog(prefix)
      );
      applyTheaterSnapsToAssistantEntry(entry, firstParsed, th1);
      applyInlineHtmlCardsToAssistantEntry(entry, firstParsed);
      if (rollSurface !== "offline") tagChatMessageBlockBadgeIfNeeded(entry, th1, "assistant");
      delete entry.restoring;
      delete entry.restoringSegIdx;
      if (
        String(reply || "").trim() ||
        hv ||
        charImgCap ||
        charImgUrl ||
        narStored ||
        charLockAssistantSpecHasEffect(charLockSpecReroll) ||
        offlineMeetupWillTriggerReroll ||
        (Array.isArray(firstParsed?.inlineHtmlCards) && firstParsed.inlineHtmlCards.length > 0)
      ) {
        const visMark = entryInsertAt;
        promoteAssistantComposerQuoteToStructuredStorage(entry, next);
        tagAssistantEntryDmSurface(entry, rollSurface);
        next.splice(entryInsertAt, 0, entry);
        restoredEntry = entry;
        applyAssistantStickerLayoutToLogEntry(next, stickerPickRoll, entry, rollSurface, false);
        assertAssistantRoundAddsVisibleMainChat(next, visMark, rollSurface, th1, rawReply);
      } else if (stickerPickedReroll && rollSurface !== "offline") {
        const visMark = entryInsertAt;
        next.splice(entryInsertAt, 0, entry);
        restoredEntry = entry;
        applyAssistantStickerLayoutToLogEntry(next, stickerPickRoll, entry, rollSurface, false);
        assertAssistantRoundAddsVisibleMainChat(next, visMark, rollSurface, th1, rawReply);
      }
    }
    insertCharRecallsAfterLogEntry(next, restoredEntry, recalls, at, insertAt);
    let charRemarkNoticeReroll = null;
    try {
      charRemarkNoticeReroll = buildCharRemarkForUserChangeNoticeFromAssistant(
        firstParsed,
        rerollPin.maskId,
        rerollPin.threadId,
        rollSurface,
        th1,
        at
      );
      if (charRemarkNoticeReroll) next.push(charRemarkNoticeReroll);
    } catch (_) {
      /* ignore */
    }
    pushCharBlockUserNoticeFromAssistantIfAny(
      next,
      firstParsed,
      rerollPin.maskId,
      rerollPin.threadId,
      rollSurface,
      th1,
      at
    );
    clearAssistantRestoringFlagsInLog(next);
    removeChatRestoringPlaceholders(next);
    saveChatLogForSendPin(rerollPin, next);
    finalizeCharThreadAvatarFromUserSentImage(
      firstParsed,
      next,
      rawReply,
      rerollPin.maskId,
      rerollPin.threadId,
      rollSurface
    );
    finalizeCharRemarkForUserFromAssistant(charRemarkNoticeReroll, rerollPin.maskId, rerollPin.threadId);
    kickoffPendingSessionImageGen(next);
    kickoffTheaterSnapGen(next, rerollPin, restoredEntry != null ? next.indexOf(restoredEntry) : undefined, rollSurface);
    scheduleChatUiRefreshForRound(rerollPin.maskId, rerollPin.threadId, { flush: true });
    showToast("已重 roll");
    applyAssistantCharLockOfflineCallSideEffects(
      charLockSpecReroll,
      offlineMeetupWillTriggerReroll ? offlineMeetupRawReroll : null,
      placeCall,
      rollSurface
    );
    });
  } catch (err) {
    if (isChatAssistAbortError(err)) {
      showToast("已停止重 roll");
    } else {
      const errText = err instanceof Error ? err.message : String(err);
      const invisible = isChatInvisibleAssistantReplyError(err);
      showToast(invisible ? "没有可显示的文字" : `重 roll 失败：${errText}`);
    }
    // 失败恢复原消息（整段末尾连续 assistant 一并还原）
    try {
      if (rerollBackupRun.length) {
        preserveChatMessagesScrollForNextRender();
        const liveLog = readChatLogForSendPin(rerollPin);
        const delLen = idxLastAsst - runStart + 1;
        if (runStart >= 0 && runStart + delLen <= liveLog.length) {
          liveLog.splice(runStart, delLen, ...rerollBackupRun);
          clearAssistantRestoringFlagsInLog(liveLog);
          removeChatRestoringPlaceholders(liveLog);
          saveChatLogForSendPin(rerollPin, liveLog);
          scheduleChatUiRefreshForRound(rerollPin.maskId, rerollPin.threadId, { flush: true });
        }
      }
    } catch (_) {
      /* ignore */
    }
  }
}

