async function openCharStUnlockOverlay() {
  const ov = document.getElementById("char-st-unlock-overlay");
  if (!ov) {
    showToast("缺少解锁面板");
    return;
  }
  const nameEl = document.getElementById("char-st-unlock-png-name");
  const err = document.getElementById("char-st-unlock-err");
  charStUnlockPendingFile = null;
  if (nameEl) nameEl.textContent = "未选择文件";
  const fileInput = document.getElementById("char-st-unlock-png-input");
  if (fileInput) fileInput.value = "";
  if (err) err.textContent = "";
  ov.classList.remove("is-open");
  ov.removeAttribute("hidden");
  ov.setAttribute("aria-hidden", "false");
  requestAnimationFrame(() => {
    ov.classList.add("is-open");
  });
}

function closeCharStUnlockOverlay() {
  const ov = document.getElementById("char-st-unlock-overlay");
  if (!ov) return;
  ov.classList.remove("is-open");
  ov.setAttribute("hidden", "");
  ov.setAttribute("aria-hidden", "true");
}

