document.getElementById("char-save")?.addEventListener("click", () => {
  void (async () => {
  const D = window.XXJ_DB;
  if (!D) return;
  await ensureCharPersonaStoreHydrated();
  const p = collectCharPersonaFromForm();
  let st = readCharPersonaStore();
  if (!st.activeId || !st.items.find((x) => x.id === st.activeId)) {
    const id = newEntityId();
    st.items.push({ id, ...p });
    st.activeId = id;
  } else {
    const idx = st.items.findIndex((x) => x.id === st.activeId);
    if (idx >= 0) {
      const next = { ...st.items[idx], ...p, id: st.items[idx].id };
      if (!next.altPersonaEnabled) {
        next.altPersonaEnabled = false;
        delete next.altPersona;
      }
      st.items[idx] = next;
    }
  }
  writeCharPersonaStore(st);
  applyCharStudioFieldsToForm();
  setCharPaneDirty(false);
  flashSaveButtonLabel("char-save", "已保存", "保存角色");
  showToast("角色已保存");
  refreshCharActivePicker();
  renderCharRoster();
  syncChatMorePersonaItems();
  syncChatThreadDetailPanelPlaceholders();
  })();
});

