document.getElementById("char-lib-back")?.addEventListener("click", () => {
  const paneChar = document.getElementById("char-lib-pane-char");
  const paneUser = document.getElementById("char-lib-pane-user");
  const roster = document.getElementById("char-lib-roster");
  const userRoster = document.getElementById("char-lib-user-roster");
  if (paneChar?.classList.contains("is-active")) {
    setCharLibStep("char-roster");
    return;
  }
  if (paneUser?.classList.contains("is-active")) {
    setCharLibStep("user-roster");
    return;
  }
  if (roster?.classList.contains("is-active")) {
    setCharLibStep("pick");
    return;
  }
  if (userRoster?.classList.contains("is-active")) {
    setCharLibStep("pick");
    return;
  }
  setCharLibStep("pick");
});
document.getElementById("char-roster-new")?.addEventListener("click", () => {
  addCharPersona();
  setCharLibStep("char");
});
document.getElementById("char-roster-grid")?.addEventListener("click", (e) => {
  const card = e.target.closest(".char-roster-card");
  const cid = card?.dataset?.charId;
  if (!cid) return;
  activateCharPersonaById(cid, { quiet: true });
  setCharLibStep("char");
});

document.getElementById("user-mask-roster-grid")?.addEventListener("click", (e) => {
  const card = e.target.closest(".char-roster-card");
  const mid = card?.dataset?.maskId;
  if (!mid) return;
  activateUserMaskById(mid, { quiet: true });
  setCharLibStep("user");
});

document.getElementById("user-mask-roster-new")?.addEventListener("click", () => {
  void addUserMask();
  setCharLibStep("user");
});

document.getElementById("settings-close")?.addEventListener("click", closeSettings);

document.getElementById("settings-theme")?.addEventListener("click", () => {
  const isDark = !document.body.classList.contains("dark");
  setTheme(isDark);
});

document.getElementById("settings-trigger-theme-toggle")?.addEventListener("click", () => {
  themeToggle?.click();
});

document.getElementById("settings-open-auth")?.addEventListener("click", () => {
  if (!isCloudAuthEnabled()) {
    showToast("账号登录仅正式版可用");
    return;
  }
  closeSettings();
  document.dispatchEvent(new CustomEvent("rp-open-auth-overlay"));
});

document.getElementById("settings-clear-local")?.addEventListener("click", async () => {
  if (
    !window.confirm(
      "将清除本机 IndexedDB 内桌面数据（照片、便签、主题、世界书、AI 档案与 Key、云登录状态等），并回到登录界面。确定？"
    )
  ) {
    return;
  }
  try {
    await window.XXJ_DB.clearAll();
  } catch {
    showToast("清除失败");
    return;
  }
  writeDesktopPaletteIndex(0);
  applyDesktopStyleFromSlot();
  if (heroNoteNode) heroNoteNode.textContent = HERO_NOTE_DEFAULT;
  setTheme(false);
  savePhotos([]);
  renderPolaroids();
  closeSettings();
  closeWorldBookScreen();
  closeChatScreen();
  closeChatListScreen();
  document.dispatchEvent(new CustomEvent("rp-open-auth-overlay"));
  showToast("已清除");
});

window.addEventListener("rp-auth-changed", refreshSettingsAuthStatus);

(function bindSettingsConnections() {
  /** @type {string[]} */
  let cachedAiModelIds = [];

  function closeAiModelPicker() {
    const ov = document.getElementById("settings-ai-model-picker-overlay");
    if (ov) ov.remove();
    document.documentElement.classList.remove("xxj-model-picker-open");
  }

  /**
   * @param {string[]} ids
   * @param {{ inputId?: string, title?: string, onPick?: (id: string) => void }} [opts]
   */
  function openAiModelPicker(ids, opts) {
    const inputId = String(opts?.inputId || "settings-ai-model").trim() || "settings-ai-model";
    const modelInput = document.getElementById(inputId);
    const list = Array.isArray(ids) ? ids.filter(Boolean) : [];
    if (!list.length) return;
    if (!modelInput && typeof opts?.onPick !== "function") return;

    closeAiModelPicker();

    const ov = document.createElement("div");
    ov.id = "settings-ai-model-picker-overlay";
    ov.className = "settings-ai-model-picker-overlay";
    ov.setAttribute("role", "dialog");
    ov.setAttribute("aria-modal", "true");
    ov.addEventListener("click", (e) => {
      if (e.target === ov) closeAiModelPicker();
    });

    const panel = document.createElement("div");
    panel.className = "settings-ai-model-picker-panel";

    const head = document.createElement("div");
    head.className = "settings-ai-model-picker-head";

    const title = document.createElement("div");
    title.className = "settings-ai-model-picker-title";
    const titleMain = String(opts?.title || "选择模型").trim() || "选择模型";
    const titleStrong = document.createElement("strong");
    titleStrong.textContent = titleMain;
    const titleSub = document.createElement("span");
    titleSub.textContent = `已拉取 ${list.length} 个 · 点一项即可填入`;
    title.append(titleStrong, titleSub);

    const closeBtn = document.createElement("button");
    closeBtn.type = "button";
    closeBtn.className = "chip ghost chip-xs";
    closeBtn.textContent = "关闭";
    closeBtn.addEventListener("click", closeAiModelPicker);

    head.append(title, closeBtn);

    const searchWrap = document.createElement("div");
    searchWrap.className = "settings-ai-model-picker-search";
    const search = document.createElement("input");
    search.type = "text";
    search.placeholder = "搜索模型 id（输入关键词）";
    search.autocomplete = "off";
    search.spellcheck = false;
    searchWrap.appendChild(search);

    const scroller = document.createElement("div");
    scroller.className = "settings-ai-model-picker-scroller";

    const ul = document.createElement("div");
    ul.className = "settings-ai-model-picker-list";
    ul.setAttribute("role", "listbox");

    const hint = document.createElement("div");
    hint.className = "settings-ai-model-picker-hint";

    const makeOptionBtn = (id) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "settings-ai-model-picker-opt";
      btn.setAttribute("role", "option");
      btn.textContent = id;
      btn.addEventListener("click", () => {
        if (typeof opts?.onPick === "function") {
          opts.onPick(id);
        } else if (modelInput instanceof HTMLInputElement || modelInput instanceof HTMLSelectElement) {
          modelInput.value = id;
          try {
            modelInput.focus();
            if (modelInput instanceof HTMLInputElement) {
              modelInput.setSelectionRange(modelInput.value.length, modelInput.value.length);
            }
          } catch (_) {}
          showToast(`已选择模型：${id}`);
        }
        closeAiModelPicker();
      });
      return btn;
    };

    // 大量节点一次性插入会卡：这里分批渲染 + 截断显示，提示用户用搜索过滤。
    const MAX_RENDER = 600;
    const BATCH = 60;
    let currentQuery = "";
    let showMoreFactor = 1;
    let renderToken = 0;

    const renderBatched = (shown, total, truncated) => {
      const token = ++renderToken;
      ul.replaceChildren();
      if (!shown.length) {
        hint.textContent = currentQuery ? "无匹配项" : "无可用模型";
        const empty = document.createElement("div");
        empty.style.padding = "14px 12px";
        empty.style.color = "#777";
        empty.style.fontSize = "13px";
        empty.textContent = "无匹配项";
        ul.appendChild(empty);
        return;
      }
      hint.textContent = truncated
        ? `匹配 ${total} 个，先显示前 ${shown.length} 个（建议继续搜索缩小范围）`
        : `显示 ${shown.length} 个`;

      let i = 0;
      const step = () => {
        if (token !== renderToken) return;
        const frag = document.createDocumentFragment();
        const end = Math.min(shown.length, i + BATCH);
        for (; i < end; i++) frag.appendChild(makeOptionBtn(shown[i]));
        ul.appendChild(frag);
        if (i < shown.length) {
          window.requestAnimationFrame(step);
        } else if (!currentQuery && total > shown.length) {
          const more = document.createElement("button");
          more.type = "button";
          more.className = "chip ghost chip-xs";
          more.style.margin = "8px auto 12px";
          more.style.display = "block";
          more.textContent = `显示更多（已显示 ${shown.length}/${total}）`;
          more.addEventListener("click", () => {
            showMoreFactor = Math.min(10, showMoreFactor + 1);
            render(currentQuery);
            try {
              scroller.scrollTop = 0;
            } catch (_) {}
          });
          ul.appendChild(more);
        }
      };
      window.requestAnimationFrame(step);
    };

    const render = (q) => {
      currentQuery = String(q || "").trim().toLowerCase();
      const kw = currentQuery;
      const total = kw
        ? list.reduce((acc, x) => (String(x).toLowerCase().includes(kw) ? acc + 1 : acc), 0)
        : list.length;
      const cap = MAX_RENDER * (kw ? 1 : showMoreFactor);
      const shown = [];
      if (kw) {
        for (const x of list) {
          if (String(x).toLowerCase().includes(kw)) {
            shown.push(x);
            if (shown.length >= cap) break;
          }
        }
      } else {
        shown.push(...list.slice(0, Math.min(cap, list.length)));
      }
      renderBatched(shown, total, total > shown.length);
    };

    search.addEventListener("input", () => render(search.value));
    render("");

    scroller.appendChild(ul);
    panel.append(head, searchWrap, hint, scroller);
    ov.appendChild(panel);
    document.body.appendChild(ov);
    document.documentElement.classList.add("xxj-model-picker-open");

    window.setTimeout(() => {
      try {
        search.focus({ preventScroll: true });
      } catch (_) {
        try {
          search.focus();
        } catch (_2) {}
      }
    }, 0);
  }

  window.__xxjOpenModelIdPicker = openAiModelPicker;

  function bindSettingsAiControls() {
    if (window.__xxjSettingsAiBound) return;
    const ai = window.RP_AI;
    if (!ai) return;
    window.__xxjSettingsAiBound = true;

    document.getElementById("settings-ai-temperature")?.addEventListener("input", () => {
      setAiTemperatureUi(readAiTemperatureFromUi());
    });

    document.getElementById("settings-ai-im-human-pace")?.addEventListener("change", () => {
      saveChatImHumanPaceFromUi();
    });

    document.getElementById("settings-ai-save")?.addEventListener("click", () => {
      saveAiConfigurationFromUi();
    });

    document.getElementById("settings-ai-test")?.addEventListener("click", async () => {
      saveAiConfigurationFromUi();
      try {
        const reply = await ai.testPing();
        setSettingsStatusLine("settings-ai-status", `回复节选: ${reply.slice(0, 120)}`, "ok");
        showToast("AI 调用成功");
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        setSettingsStatusLine("settings-ai-status", msg, "err");
        showToast("AI 调用失败");
      }
    });

    document.getElementById("settings-ai-clear-stream-cap")?.addEventListener("click", () => {
      if (typeof ai.clearAllStreamCapability === "function") ai.clearAllStreamCapability();
      setSettingsStatusLine("settings-ai-status", "已清除流式线路记忆", "ok");
      showToast("已清除，下次发消息将重新尝试流式");
    });

    document.getElementById("settings-ai-fetch-models")?.addEventListener("click", async () => {
      const base =
        document.getElementById("settings-ai-base")?.value?.trim() || ai.DEFAULT_BASE;
      const key = resolveAiKeyForProfile();
      if (!key) {
        showToast("请先输入或已保存 API Key");
        return;
      }
      const fetchBtn = document.getElementById("settings-ai-fetch-models");
      const prevLabel = fetchBtn?.textContent;
      if (fetchBtn) {
        fetchBtn.disabled = true;
        fetchBtn.textContent = "拉取中…";
      }
      setSettingsStatusLine("settings-ai-status", "正在请求 GET …/models", "");
      try {
        const ids = await ai.listModels({ baseUrl: base, apiKey: key });
        cachedAiModelIds = Array.isArray(ids) ? ids : [];
        const dl = document.getElementById("settings-ai-model-datalist");
        const inp = document.getElementById("settings-ai-model");
        if (dl) {
          dl.innerHTML = "";
          // datalist 节点过多会明显卡顿：这里只保留少量联想，完整列表用自建选择器展示
          const cap = 160;
          const shown = ids.slice(0, Math.min(cap, ids.length));
          for (const id of shown) {
            const o = document.createElement("option");
            o.value = id;
            dl.appendChild(o);
          }
          if (ids.length > shown.length) {
            const o = document.createElement("option");
            o.value = `（已省略 ${ids.length - shown.length} 个，点输入框可打开列表）`;
            dl.appendChild(o);
          }
        }
        if (inp && ids.length) {
          inp.value = ids[0];
          inp.classList.remove("settings-ai-model--just-fetched");
          void inp.offsetWidth;
          inp.classList.add("settings-ai-model--just-fetched");
          try {
            inp.scrollIntoView({ block: "nearest", behavior: "smooth" });
            inp.focus();
          } catch (_) {}
        }
        showToast(
          ids.length
            ? `已拉取 ${ids.length} 个模型，已填入「${ids[0]}」`
            : "接口成功但未解析到模型 id，请检查 Base 是否为 OpenAI 兼容 /v1"
        , ids.length ? 3200 : 4000);
        setSettingsStatusLine(
          "settings-ai-status",
          ids.length ? `GET /v1/models · ${ids.length} 条` : "GET /v1/models · 0 条（响应格式可能不兼容）",
          ids.length ? "ok" : "err"
        );
        if (ids.length) openAiModelPicker(ids);
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        setSettingsStatusLine("settings-ai-status", msg, "err");
        const short = msg.length > 56 ? `${msg.slice(0, 56)}…` : msg;
        showToast(`拉取失败：${short}`);
      } finally {
        if (fetchBtn) {
          fetchBtn.disabled = false;
          if (prevLabel != null) fetchBtn.textContent = prevLabel;
        }
      }
    });

    // datalist 在不少浏览器里无法“点击就展开所有选项”，这里用自建面板兜底。
    document.getElementById("settings-ai-model")?.addEventListener("click", () => {
      const dl = document.getElementById("settings-ai-model-datalist");
      const hasDl = dl && dl.querySelector("option");
      if (cachedAiModelIds.length) openAiModelPicker(cachedAiModelIds);
      else if (hasDl) {
        const ids = [...dl.querySelectorAll("option")]
          .map((o) => String(o.value || "").trim())
          .filter(Boolean);
        cachedAiModelIds = ids;
        if (ids.length) openAiModelPicker(ids);
      }
    });

    document.getElementById("settings-ai-profile")?.addEventListener("change", (ev) => {
      applySelectedAiProfile(String(ev.target.value || ""));
    });

    document.getElementById("settings-ai-profile-delete")?.addEventListener("click", () => {
      const id = document.getElementById("settings-ai-profile")?.value;
      if (!id) {
        showToast("请先选择要删除的档案");
        return;
      }
      if (!window.confirm("确定删除所选档案？（不会清空当前本机已生效的 Key/Base）")) {
        return;
      }
      ai.deleteProfile(id);
      refreshAiProfileSelect();
      if (isChatMemoScreenOpen()) refreshChatMemoSummaryProfileSelect();
      const nameEl = document.getElementById("settings-ai-profile-name");
      if (nameEl) nameEl.value = "";
      showToast("已删除");
    });
  }

  window.__xxjBindSettingsAiControls = bindSettingsAiControls;
  bindSettingsAiControls();
  bindSettingsGlobalThinkingChainControls();

  bindSettingsRangeValueClickEdit("minimax-speed", "minimax-speed-value", { decimals: 2 });
  bindSettingsRangeValueClickEdit("minimax-vol", "minimax-vol-value", { decimals: 2 });
  bindSettingsRangeValueClickEdit("minimax-pitch", "minimax-pitch-value", { roundInt: true });
  bindMinimaxSelectCustomToggle("minimax-voice", "minimax-voice-custom", (sel) => {
    const pick = String(sel.value || "");
    if (!pick.startsWith("preset:") || pick === "preset:__default__") return;
    const preset = findMinimaxVoicePresetByRef(pick, readMinimaxTtsConfig());
    if (preset) applyMinimaxVoicePresetToPanel(preset, readMinimaxTtsConfig());
  });
  bindMinimaxSelectCustomToggle("minimax-language-boost", "minimax-language-boost-custom");
  document.getElementById("minimax-preset-save-current")?.addEventListener("click", () => {
    const ok = saveMinimaxVoicePresetFromCurrentPanel();
    showToast(ok ? "已存为预设" : "保存预设失败");
  });
  document.getElementById("minimax-save")?.addEventListener("click", () => {
    saveMinimaxTtsConfigFromForm();
  });
  document.getElementById("minimax-clear-tts-cache")?.addEventListener("click", () => {
    const db = window.XXJ_DB;
    if (!db || typeof db.minimaxTtsCacheClear !== "function") {
      showToast("缓存未就绪");
      return;
    }
    void db.minimaxTtsCacheClear().then(() => {
      if (window.__MM_TTS_CACHE) window.__MM_TTS_CACHE.clear();
      void syncMinimaxTtsCacheHintUi();
      showToast("已清除语音缓存");
    });
  });
  document.getElementById("minimax-test")?.addEventListener("click", () => {
    saveMinimaxTtsConfigFromForm();
    resetMinimaxProbeLogs();
    const cfg = readMinimaxTtsConfig();
    const ok = Boolean(cfg.apiKey);
    if (!ok) {
      setSettingsStatusLine("minimax-status", "请先填写 API Key", "err");
      return;
    }
    const audioEl = document.getElementById("minimax-audio-preview");
    if (audioEl instanceof HTMLAudioElement) {
      minimaxPrimeTtsAudioOnUserGesture(audioEl);
    } else {
      minimaxPrimeTtsAudioOnUserGesture();
    }
    const btn = document.getElementById("minimax-test");
    if (btn) btn.disabled = true;
    setSettingsStatusLine("minimax-status", "测试中…（正在合成一段短语音）", "");
    if (audioEl instanceof HTMLAudioElement) {
      minimaxRevokeAudioElementBlob(audioEl);
      audioEl.hidden = true;
      audioEl.removeAttribute("src");
    }
    const testRef = String(cfg.defaultVoiceRef || cfg.defaultVoiceId || "").trim();
    const testBundle = resolveMinimaxSynthBundle(testRef, cfg);
    void minimaxSynthesizeSpeech(
      minimaxTestPhraseForVoice(testBundle.effectiveVoiceId, testBundle.languageBoost),
      testRef,
      cfg
    ).then((r) => {
      if (!r || !r.audioUrl) {
        const logs = getMinimaxProbeLogs();
        const msg = logs.length ? logs.join("\n") : "请求失败：API 无响应或被 CORS 拦截";
        setSettingsStatusLine("minimax-status", msg, "err");
        return;
      }
      setSettingsStatusLine("minimax-status", "连接成功！语音合成正常", "ok");
      if (audioEl instanceof HTMLAudioElement) {
        audioEl.hidden = false;
        void minimaxPlayTtsAudio(r.audioUrl, audioEl);
      } else {
        void minimaxPlayTtsAudio(r.audioUrl);
      }
    }).finally(() => {
      if (btn) btn.disabled = false;
    });
  });
  document.getElementById("minimax-sheet-backdrop")?.addEventListener("click", () => {
    closeMinimaxSheet();
  });
  document.getElementById("minimax-close")?.addEventListener("click", () => {
    closeMinimaxSheet();
  });
  document.getElementById("minimax-cancel")?.addEventListener("click", () => {
    closeMinimaxSheet();
  });

  document.getElementById("image-gen-provider")?.addEventListener("change", () => {
    cachedImageGenFetchedIds = [];
    refreshImageGenProviderUi();
  });
  document.getElementById("image-gen-model")?.addEventListener("change", () => {
    const prov = document.getElementById("image-gen-provider");
    const raw = prov instanceof HTMLSelectElement ? String(prov.value || "openai").trim().toLowerCase() : "openai";
    if (raw === "custom") {
      const sel = document.getElementById("image-gen-model");
      const inp = document.getElementById("image-gen-model-custom");
      if (sel instanceof HTMLSelectElement && inp instanceof HTMLInputElement && !sel.hidden) {
        inp.value = String(sel.value || "").trim();
      }
    }
    syncImageGenNaiLabelsAndSmea();
    refreshImageGenProviderUi();
  });
  document.getElementById("image-gen-nai-steps")?.addEventListener("input", () => syncImageGenNaiLabelsAndSmea());
  document.getElementById("image-gen-nai-cfg")?.addEventListener("input", () => syncImageGenNaiLabelsAndSmea());
  document.getElementById("image-gen-nai-seed-rand")?.addEventListener("click", () => {
    const inp = document.getElementById("image-gen-nai-seed");
    if (inp instanceof HTMLInputElement) inp.value = "";
  });
  document.getElementById("image-gen-fetch-models")?.addEventListener("click", () => {
    void fetchImageGenModelsFromUi();
  });
  document.getElementById("image-gen-preset-select")?.addEventListener("change", (e) => {
    const sel = e.target;
    if (!(sel instanceof HTMLSelectElement)) return;
    const id = String(sel.value || "").trim();
    if (!id) return;
    const hit = readImageGenPresets().find((x) => x.id === id);
    if (hit) {
      applyImageGenPresetToForm(hit);
      showToast(`已载入「${hit.name}」`);
    }
    sel.value = "";
  });
  document.getElementById("image-gen-preset-save")?.addEventListener("click", () => {
    const raw = window.prompt("预设名称", "");
    if (raw == null) return;
    const name = String(raw).trim().slice(0, 48);
    if (!name) {
      showToast("请填写名称");
      return;
    }
    const incEl = document.getElementById("image-gen-preset-include-api");
    const includeCredentials = incEl instanceof HTMLInputElement && incEl.checked;
    const cfg = collectImageGenFormToConfig();
    const payload = includeCredentials
      ? { ...collectImageGenPresetPayloadFromForm(), includeCredentials: true }
      : {
          includeCredentials: false,
          stylePrompt: cfg.stylePrompt,
          negativePrompt: cfg.negativePrompt,
          openaiQuality: cfg.openaiQuality,
          openaiInputFidelity: cfg.openaiInputFidelity
        };
    const id = `igp_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`;
    const list = readImageGenPresets();
    if (list.length >= IMAGE_GEN_PRESET_MAX) {
      showToast(`预设最多 ${IMAGE_GEN_PRESET_MAX} 条`);
      return;
    }
    list.push(normalizeImageGenPreset({ ...payload, id, name, updatedAt: Date.now() }));
    writeImageGenPresets(list);
    renderImageGenPresetList();
    showToast(includeCredentials ? `已保存「${name}」（含 API 等）` : `已保存「${name}」（仅提示词）`);
  });
  document.getElementById("image-gen-preset-list")?.addEventListener("click", (e) => {
    const t = e.target;
    if (!(t && t instanceof Element)) return;
    const btn = t.closest("[data-imgen-preset-del]");
    if (!btn) return;
    const id = btn.getAttribute("data-imgen-preset-del");
    if (!id) return;
    if (!window.confirm("删除该预设？")) return;
    const next = readImageGenPresets().filter((x) => x.id !== id);
    writeImageGenPresets(next);
    renderImageGenPresetList();
    showToast("已删除");
  });
  document.getElementById("image-gen-test")?.addEventListener("click", () => {
    void runImageGenTestFromForm();
  });
  document.getElementById("image-gen-save")?.addEventListener("click", () => {
    const cfg = collectImageGenFormToConfig();
    if (cfg.provider === "custom" && !String(cfg.baseUrl || "").trim()) {
      showToast("自定义服务商请填写 API Base");
      return;
    }
    if (cfg.enabled && !cfg.apiKey) {
      showToast("开启生图时请填写 API Key");
      return;
    }
    writeImageGenConfig(cfg);
    closeImageGenSheet();
    showToast("生图配置已保存");
  });
  document.getElementById("image-gen-sheet-backdrop")?.addEventListener("click", () => {
    closeImageGenSheet();
  });
  document.getElementById("image-gen-close")?.addEventListener("click", () => {
    closeImageGenSheet();
  });
  document.getElementById("image-gen-cancel")?.addEventListener("click", () => {
    closeImageGenSheet();
  });
})();

function onChatInboxStoreHydrated() {
  const D = window.XXJ_DB;
  if (isLikelyIosWebKit() && D && !D.isInboxHydrated) return;
  const run = () => {
    warmChatInboxMemCacheFromDb();
    const refreshUi = () => {
      if (chatListScreen?.classList.contains("is-open")) {
        renderChatMaskStrip();
        renderChatThreadList();
      }
      if (chatScreen?.classList.contains("is-open") && readActiveThread()) {
        renderChatMessages();
      }
    };
    if (typeof requestIdleCallback === "function") {
      requestIdleCallback(refreshUi, { timeout: 2500 });
    } else {
      setTimeout(refreshUi, 0);
    }
  };
  if (typeof requestIdleCallback === "function") {
    requestIdleCallback(run, { timeout: 2000 });
  } else {
    setTimeout(run, 0);
  }
}

function isMobileLikeDevice() {
  try {
    if (/Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent || "")) return true;
    return window.matchMedia("(max-width: 520px)").matches;
  } catch (_) {
    return false;
  }
}

function runDesktopDecorPaint() {
  try {
    const pi = readDesktopPaletteIndex();
    const pal = DESKTOP_PALETTES[pi];
    const dark = document.body.classList.contains("dark");
    applyDesktopCustomWallpaper(pal, 0, dark);
    const D = window.XXJ_DB;
    const hasIconKv = D && D.K && D.getKv(D.K.DESKTOP_APP_ICONS) !== undefined;
    if (!isLikelyIosWebKit() || hasIconKv) applyDesktopAppIcons();
    applyDesktopHeroCardBackground();
    const runTypo = () => {
      try {
        applyGlobalUiTypography();
      } catch (err) {
        console.warn("[boot] typography failed", err);
      }
    };
    if (typeof requestIdleCallback === "function") {
      requestIdleCallback(runTypo, { timeout: 2500 });
    } else {
      setTimeout(runTypo, 48);
    }
  } catch (err) {
    console.warn("[boot] desktop decor failed", err);
  }
}

function runDesktopHeavyDecor() {
  const steps = [
    () => applyDesktopAppTileBackgrounds(),
    () => applyDesktopAppTowerBackground(),
    () => applyDesktopDockBackground()
  ];
  let i = 0;
  const runStep = () => {
    if (i >= steps.length) return;
    try {
      steps[i]();
    } catch (err) {
      console.warn("[boot] desktop heavy decor failed", err);
    }
    i += 1;
    if (i < steps.length) {
      if (isMobileLikeDevice()) requestAnimationFrame(runStep);
      else runStep();
    }
  };
  runStep();
}

