function getStickerSuggestQueryFromInput(text) {
  const s = String(text || "").trim();
  if (!s) return "";
  const words = s.split(/[\s，。！？、,!?]+/u).filter(Boolean);
  const lastWord = words.length ? words[words.length - 1] : "";
  return lastWord.length >= 1 ? lastWord : "";
}

/** 联想条：命中时返回优先级 0–3（越小越靠前），未命中返回 -1。 */
function stickerSuggestMatchRank(descRaw, queryRaw) {
  const d = String(descRaw || "").trim().toLowerCase();
  const q = String(queryRaw || "").trim().toLowerCase();
  if (!d || !q || !(d.includes(q) || q.includes(d))) return -1;
  if (d === q) return 0;
  if (d.startsWith(q)) return 1;
  if (d.includes(q)) return 2;
  return 3;
}

function scheduleStickerSuggestFromInput(text) {
  window.clearTimeout(stickerSuggestInputTimer);
  stickerSuggestInputTimer = window.setTimeout(() => {
    stickerSuggestInputTimer = 0;
    const q = getStickerSuggestQueryFromInput(text);
    const th = readActiveThread();
    const renderKey = `${getActiveMaskIdForInbox()}\t${th?.id || ""}\t${q}`;
    if (renderKey === stickerSuggestLastRenderKey) return;
    stickerSuggestLastRenderKey = renderKey;
    renderStickerSuggestFromInput(text);
  }, 160);
}

function clearStickerSuggestBar() {
  stickerSuggestLastRenderKey = "";
  const host = document.getElementById("sticker-suggest");
  if (!host) return;
  host.hidden = true;
  host.innerHTML = "";
}

function renderStickerSuggestFromInput(text) {
  const host = document.getElementById("sticker-suggest");
  if (!host) return;
  if (getActiveChatDmSurfaceForContext() === "offline") {
    clearStickerSuggestBar();
    return;
  }
  if (!isThreadStickerSuggestEnabled(readActiveThread())) {
    clearStickerSuggestBar();
    return;
  }
  const q = getStickerSuggestQueryFromInput(text);
  if (!q) {
    clearStickerSuggestBar();
    return;
  }
  const items = collectStickerPoolItemsForThread(readActiveThread());
  const hits = items
    .filter((it) => stickerSuggestMatchRank(it?.description, q) >= 0)
    .sort((a, b) => {
      const ra = stickerSuggestMatchRank(a?.description, q);
      const rb = stickerSuggestMatchRank(b?.description, q);
      return ra !== rb ? ra - rb : _compareStickerPoolItemsStableTie(a, b);
    })
    .slice(0, 10);
  if (!hits.length) {
    clearStickerSuggestBar();
    return;
  }
  host.hidden = false;
  const frag = document.createDocumentFragment();
  for (const it of hits) {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "sticker-suggest-item";
    btn.setAttribute("aria-label", `发送表情：${String(it?.description || "").trim() || "表情"}`);
    const thumb = document.createElement("span");
    thumb.className = "sticker-suggest-thumb";
    const im = document.createElement("img");
    im.alt = "";
    im.loading = "lazy";
    im.decoding = "async";
    im.src = String(it?.url || "");
    thumb.appendChild(im);
    const name = document.createElement("span");
    name.className = "sticker-suggest-name";
    name.textContent = String(it?.description || "").trim() || "表情";
    btn.appendChild(thumb);
    btn.appendChild(name);
    btn.addEventListener("click", () => {
      void sendStickerToChatAsync({ url: String(it?.url || ""), description: String(it?.description || ""), category: String(it?.category || "") });
      clearStickerSuggestBar();
      window.requestAnimationFrame(() => document.getElementById("chat-input")?.focus());
    });
    frag.appendChild(btn);
  }
  host.replaceChildren(frag);
}

function onChatComposerInput(e) {
  const el = e.currentTarget;
  if (el instanceof HTMLTextAreaElement) {
    scheduleStickerSuggestFromInput(el.value);
  }
}

/** @param {unknown} thread */
function collectStickerPoolItemsForThread(thread) {
  const bindArr = getThreadStickerBindCategories(thread);
  const { bucket } = ensureStickerGlobalBucket();
  const itemsAll = Array.isArray(bucket.items) ? bucket.items : [];
  let items = itemsAll;
  if (bindArr.length) {
    items = items.filter((it) => bindArr.includes(String(it?.category || "默认").trim() || "默认"));
  }
  return items.filter((it) => sanitizeStickerUrl(String(it?.url || "").trim()) && String(it?.description || "").trim());
}

/** 注入系统提示：列出当前密谈可用表情描述，供模型按人设与剧情择关键词。 */
function buildStickerCatalogPromptBlock(thread) {
  const items = collectStickerPoolItemsForThread(thread);
  if (!items.length) {
    return (
      `【当前可用表情包 · 描述清单】\n` +
      `（暂无。请在应用内导入表情包；若已绑定分类，请确认分类与导入分类一致。）`
    );
  }
  const seen = new Set();
  /** @type {string[]} */
  const lines = [];
  let budget = 0;
  const maxBudget = 3400;
  const catsInPool = new Set(items.map((it) => String(it?.category || "默认").trim() || "默认"));
  const showCat = catsInPool.size > 1;
  const header =
    `【当前可用表情包 · 描述清单】\n` +
    `以下为本次对话程序**只会从中择图**的表情描述（每条对应一张你已导入的图）。请结合人设与剧情决定要不要发表情；若要发，关键词尽量**摘自下列某一行的原文**。\n`;
  budget += header.length;
  const uniqDescCount = new Set(items.map((it) => String(it?.description || "").trim()).filter(Boolean)).size;
  for (const it of items) {
    const desc = String(it?.description || "").trim();
    if (!desc || seen.has(desc)) continue;
    seen.add(desc);
    const cat = String(it?.category || "默认").trim() || "默认";
    const line = showCat ? `- 「${cat}」${desc}` : `- ${desc}`;
    if (budget + line.length + 1 > maxBudget) break;
    lines.push(line);
    budget += line.length + 1;
  }
  let tail = "";
  if (lines.length < uniqDescCount) {
    tail = `\n（尚有 ${uniqDescCount - lines.length} 条描述未完整列出；关键词仍请优先引用表中字面或与导入描述一致。）`;
  }
  return header + lines.join("\n") + tail;
}

/** 最近用户发言，用于关键词为空时在库里做情境贴合择图。 */
function buildStickerContextHintFromChatLog(logSlice) {
  const log = Array.isArray(logSlice) ? logSlice : [];
  /** @type {string[]} */
  const chunks = [];
  let nUser = 0;
  for (let i = log.length - 1; i >= 0 && nUser < 8; i--) {
    const m = log[i];
    if (!m || typeof m !== "object" || m.role !== "user") continue;
    if (m.restoring) continue;
    let t = String(m.content ?? "").trim();
    if (m.image && typeof m.image === "object") {
      const cap = String(m.image.desc || "").trim();
      if (cap) t = t ? `${t} ${cap}` : cap;
    }
    if (t) {
      chunks.push(t.replace(/\s+/g, " "));
      nUser++;
    }
  }
  chunks.reverse();
  return chunks.join(" ").slice(-1400);
}

function normalizeStickerMatchText(s) {
  return String(s || "")
    .toLowerCase()
    .replace(/[\s\u3000,.!?;:，。！？；：、""''（）()\[\]【】|`]/g, "");
}

/** @returns {number} */
function scoreStickerTexts(queryNorm, descNorm) {
  if (!queryNorm.length || !descNorm.length) return 0;
  if (queryNorm === descNorm) return 50_000;
  if (descNorm.includes(queryNorm)) return 10_000 + Math.min(queryNorm.length * 12, 800);
  if (queryNorm.includes(descNorm)) return 9800 + Math.min(descNorm.length * 12, 700);
  /** @type {Record<string, boolean>} */
  const uniq = Object.create(null);
  let hits = 0;
  for (const ch of queryNorm) {
    if (uniq[ch]) continue;
    uniq[ch] = true;
    if (descNorm.includes(ch)) hits++;
  }
  const denom = Object.keys(uniq).length || 1;
  return Math.round((hits / denom) * 600);
}

function _compareStickerPoolItemsStableTie(a, b) {
  const da = String(a?.description || "").trim();
  const db = String(b?.description || "").trim();
  const c = da.localeCompare(db, "zh", { sensitivity: "base" });
  if (c !== 0) return c;
  return String(a?.url || "").localeCompare(String(b?.url || ""));
}

/**
 * 结合关键词（模型给出）与上下文（本轮对白 lines + 最近用户消息）在导入池中择图。
 * @param {string | null} query 来自【表情包】或 stickerKeyword；null 表示本轮不发。
 * @param {unknown} thread
 * @param {string} contextHint 归并后的情境字串
 */
function pickStickerForCharFromBoundCategory(query, thread, contextHint) {
  const pool = collectStickerPoolItemsForThread(thread);
  if (!pool.length) return null;

  const qNorm = normalizeStickerMatchText(String(query ?? ""));
  const ctxNorm = normalizeStickerMatchText(String(contextHint || "").slice(-1800));

  /** @type {{ it: (typeof pool)[0], sc: number }[]} */
  const ranked = [];
  for (const it of pool) {
    const descNorm = normalizeStickerMatchText(String(it.description || ""));
    let sc = 0;
    if (qNorm.length) {
      sc = scoreStickerTexts(qNorm, descNorm);
      if (ctxNorm.length >= 2) sc += Math.round(scoreStickerTexts(ctxNorm, descNorm) * 0.22);
    } else if (ctxNorm.length >= 2) {
      sc = scoreStickerTexts(ctxNorm, descNorm);
    } else {
      sc = 1;
    }
    ranked.push({ it, sc });
  }
  ranked.sort((a, b) => (b.sc !== a.sc ? b.sc - a.sc : _compareStickerPoolItemsStableTie(a.it, b.it)));
  const pick = ranked[0].it;
  const url = sanitizeStickerUrl(pick.url);
  const desc = String(pick.description || "").trim();
  if (!url || !desc) return null;
  return { url, description: desc, category: String(pick.category || "默认").trim() || "默认" };
}

/**
 * 剥离表情包分段后，按原 lines 槽位对齐 lineTranslations（去掉仅表情包的译本槽，避免错位）。
 * @param {string} linesJoinedBefore
 * @param {string} linesJoinedAfter
 * @param {string} transJoined
 */
function alignTranslationSegmentsAfterStickerStrip(linesJoinedBefore, linesJoinedAfter, transJoined) {
  const origParts = String(linesJoinedBefore ?? "").split(/\|\|\|/);
  const transParts = String(transJoined ?? "").split(/\|\|\|/);
  const aligned = [];
  for (let i = 0; i < origParts.length; i++) {
    const raw = String(origParts[i] ?? "").trim();
    if (!raw) continue;
    const ref = { q: /** @type {string | null} */ (null) };
    const rest = extractStickerTokensFromSegment(raw, ref);
    if (!rest) continue;
    const tp = i < transParts.length ? String(transParts[i] ?? "") : "";
    aligned.push(tp);
  }
  const n = String(linesJoinedAfter ?? "")
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean).length;
  return padTranslationSegments(aligned.join("|||"), Math.max(n, aligned.length)).join("|||");
}

/**
 * 择图剥指令后：对齐译本槽并掩掉误写的表情包译本。
 * @param {string} replyBefore
 * @param {string} replyAfter
 * @param {string} transJoined
 */
function hygieneAssistantTranslationAfterStickerStrip(replyBefore, replyAfter, transJoined) {
  const src = String(transJoined ?? "").trim();
  if (!src) return "";
  let t = alignTranslationSegmentsAfterStickerStrip(replyBefore, replyAfter, src);
  return compactTranslationSegmentsToMatchMain(replyAfter, t);
}

/**
 * 渲染/存盘兜底：译本分段数多于正文时，跳过「表情包」译本槽再与正文对齐（修复历史错位消息）。
 * @param {string} mainJoined
 * @param {string} transJoined
 */
function compactTranslationSegmentsToMatchMain(mainJoined, transJoined) {
  const mains = String(mainJoined ?? "")
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean);
  const n = mains.length;
  if (!n) return "";
  const src = String(transJoined ?? "").trim();
  if (!src) return "";
  const transParts = src.split(/\|\|\|/).map((s) => String(s).trim());
  const isOrphanTransSlot = (s) =>
    isStickerDirectiveTranslationChunk(s) || isStructuredProtocolChatSegment(s);
  const maskSeg = (mainSeg, transSeg) => {
    const t = String(transSeg ?? "").trim();
    if (!t) return String(transSeg ?? "");
    if (isOrphanTransSlot(t)) return CHAT_TRANSLATION_SKIP_TOKEN;
    if (isStructuredProtocolChatSegment(String(mainSeg ?? "").trim())) return CHAT_TRANSLATION_SKIP_TOKEN;
    return transSeg;
  };

  if (transParts.length === n) {
    return transParts.map((t, i) => maskSeg(mains[i], t)).join("|||");
  }
  if (transParts.length > n) {
    const out = [];
    let ti = 0;
    for (let mi = 0; mi < n; mi++) {
      while (ti < transParts.length && isOrphanTransSlot(transParts[ti])) ti++;
      out.push(ti < transParts.length ? transParts[ti] : "");
      if (ti < transParts.length) ti++;
    }
    return out.map((t, i) => maskSeg(mains[i], t)).join("|||");
  }
  return padTranslationSegments(src, n)
    .map((t, i) => maskSeg(mains[i], t))
    .join("|||");
}

/** @param {unknown} m */
function getChatStickerPlacements(m) {
  if (!m || typeof m !== "object") return [];
  const raw = /** @type {{ stickerPlacements?: unknown[] }} */ (m).stickerPlacements;
  if (!Array.isArray(raw)) return [];
  /** @type {{ insertAfterSeg: number, url: string, description: string }[]} */
  const out = [];
  for (const row of raw) {
    if (!row || typeof row !== "object") continue;
    const url = String(/** @type {{ url?: string }} */ (row).url || "").trim();
    if (!url) continue;
    const insertAfterSeg = Number(/** @type {{ insertAfterSeg?: number }} */ (row).insertAfterSeg);
    out.push({
      insertAfterSeg: Number.isFinite(insertAfterSeg) ? Math.floor(insertAfterSeg) : -1,
      url,
      description: String(/** @type {{ description?: string, desc?: string }} */ (row).description || row.desc || "").trim()
    });
  }
  return out;
}

/**
 * @param {HTMLElement} stack
 * @param {{ insertAfterSeg: number, url: string, description: string }[]} placements
 * @param {number} afterSeg
 * @param {ReturnType<typeof collectChatStickerBubbleReusePool>} stickerReusePool
 * @param {number} msgIdx
 * @param {string} role
 * @param {unknown} [layoutMsg] 传入则按分段规则写入 data-chat-bubble-seg（多选删除用）
 */
function appendInlineChatStickerBubbles(stack, placements, afterSeg, stickerReusePool, msgIdx, role, layoutMsg) {
  let ord = 0;
  for (const pl of placements) {
    if (pl.insertAfterSeg !== afterSeg) continue;
    const bubbleSeg =
      layoutMsg && typeof layoutMsg === "object"
        ? resolveSheetDomSegForStickerPlacement(layoutMsg, role, afterSeg, ord)
        : undefined;
    appendChatStickerBubbleToStack(
      stack,
      stickerReusePool,
      msgIdx,
      role,
      pl.url,
      pl.description,
      bubbleSeg
    );
    ord++;
  }
}

/** 渲染/落盘前：剥掉 assistant 正文里残留的【表情：】/【表情包：】指令字。 */
function normalizeAssistantStickerDirectiveTextInLog(log) {
  if (!Array.isArray(log)) return false;
  let dirty = false;
  for (const m of log) {
    if (!m || typeof m !== "object" || String(m.role) !== "assistant") continue;
    if (chatMessageDmSurface(m) === "offline") continue;
    const before = String(m.content ?? "");
    if (!before.trim()) continue;
    const next = assistantDisplayTextWithoutStickerDirectives(before);
    if (next === before) continue;
    const hasStickerAsset =
      Boolean(m.sticker && typeof m.sticker === "object" && String(m.sticker.url || "").trim()) ||
      (Array.isArray(m.stickerPlacements) && m.stickerPlacements.length > 0);
    m.content = next.trim() ? next : hasStickerAsset ? "" : next;
    dirty = true;
  }
  return dirty;
}

/** 渲染前：仅修正含 transfer JSON / 结构化协议译本错位的历史消息（避免每轮全量扫 log）。 */
function normalizeAssistantTranslationStructuredInLog(log) {
  if (!Array.isArray(log)) return false;
  let dirty = false;
  for (const m of log) {
    if (!m || typeof m !== "object" || String(m.role) !== "assistant") continue;
    if (chatMessageDmSurface(m) === "offline") continue;
    const beforeT = String(m.translation ?? "");
    const beforeC = String(m.content ?? "");
    const needRedpack = assistantEntryNeedsRedpackContentSanitize(m) || Boolean(m.redpack);
    const needTransMask = beforeT.trim() && translationNeedsStructureMask(beforeC, beforeT);
    if (!needRedpack && !needTransMask) continue;
    if (needRedpack) tryAttachCharRedpackFromContent(m);
    if (needTransMask || (needRedpack && beforeT.trim())) finalizeAssistantEntryTranslation(m);
    if (String(m.translation ?? "") !== beforeT || String(m.content ?? "") !== beforeC) dirty = true;
  }
  return dirty;
}

/** @returns {({ kind: "text", text: string } | { kind: "sticker", query: string })[]} */
function parseOneLinePartStickerTokens(seg) {
  let s = String(seg || "").trim();
  if (!s) return [];
  /** @type {({ kind: "text", text: string } | { kind: "sticker", query: string })[]} */
  const items = [];
  let guard = 0;
  while (s && guard++ < 20) {
    const embed = s.match(RE_STICKER_CMD_EMBED);
    if (embed) {
      const before = String(embed[1] || "").trim();
      const kw = String(embed[2] || "").trim();
      const after = String(embed[3] || "").trim();
      if (before) items.push({ kind: "text", text: before });
      items.push({ kind: "sticker", query: kw });
      s = after;
      continue;
    }
    const wholeColon = s.match(RE_STICKER_CMD_WHOLE_COLON);
    if (wholeColon) {
      items.push({ kind: "sticker", query: String(wholeColon[1] || "").trim() });
      return items;
    }
    const wholeBare = s.match(RE_STICKER_CMD_WHOLE_BARE);
    if (wholeBare) {
      items.push({ kind: "sticker", query: "" });
      s = String(wholeBare[1] || "").trim();
      if (s) continue;
      return items;
    }
    const jsonAt = findModelLeakedEmojiJsonBlockStart(s);
    if (jsonAt >= 0) {
      const before = s.slice(0, jsonAt).trim();
      const block = s.slice(jsonAt).match(RE_MODEL_EMOJI_JSON_BLOCK);
      if (block) {
        if (before) items.push({ kind: "text", text: before });
        items.push({ kind: "sticker", query: stickerKeywordFromEmojiJsonDescription(block[1]) });
        s = s.slice(jsonAt + block[0].length).trim();
        continue;
      }
    }
    items.push({ kind: "text", text: s });
    break;
  }
  return items;
}

/** @returns {({ kind: "text", text: string } | { kind: "sticker", query: string })[]} */
function parseAssistantReplyToOrderedSegments(linesJoined) {
  const parts = String(linesJoined || "")
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean);
  /** @type {({ kind: "text", text: string } | { kind: "sticker", query: string })[]} */
  const out = [];
  for (const part of parts) out.push(...parseOneLinePartStickerTokens(part));
  return out;
}

/** 展示/存盘：去掉【表情包】指令，只保留可读正文（与 parseAssistantReplyToOrderedSegments 同源）。 */
function assistantDisplayTextWithoutStickerDirectives(joined) {
  const texts = [];
  for (const seg of parseAssistantReplyToOrderedSegments(joined)) {
    if (seg.kind !== "text") continue;
    const t = String(seg.text || "").trim();
    if (t) texts.push(t);
  }
  return texts.join("|||");
}

/**
 * 按 lines 顺序解析表情包位置（不再固定叠在整轮最后一条）。
 * @returns {{ keptJoined: string, placements: { insertAfterSeg: number, url: string, description: string }[], picked: { url: string, description: string } | null }}
 */
function resolveAssistantStickerLayout(replyJoined, parsed, thread, opts) {
  const extra = String(opts?.contextHint ?? "").trim();
  const lineHint = String(replyJoined || "")
    .trim()
    .replace(/\s*\|\|\|\s*/g, " ");
  const logHint = buildStickerContextHintFromChatLog(readChatLog());
  const contextHint = [lineHint, extra, logHint].filter(Boolean).join(" ").slice(-2200);

  let segments = parseAssistantReplyToOrderedSegments(replyJoined);
  const fk = String(parsed?.modelStickerKeyword ?? "").trim();
  const fs = parsed?.modelSendSticker === true;
  const hasInlineSticker = segments.some((s) => s.kind === "sticker");

  if (!hasInlineSticker) {
    const ex = extractStickerCommandFromAssistantReply(replyJoined);
    let query = ex.query;
    if (query === null && (fs || fk)) query = fk;
    if (query === null) {
      const raw = String(opts?.rawAssistantReply ?? "").trim();
      if (raw) {
        const loose = extractStickerDirectiveHintFromAssistantRaw(raw);
        if (loose !== null) query = loose;
      }
    }
    if (query !== null) segments = segments.concat([{ kind: "sticker", query }]);
  }

  const textParts = [];
  /** @type {{ insertAfterSeg: number, url: string, description: string }[]} */
  const placements = [];
  let textCount = 0;
  for (const seg of segments) {
    if (seg.kind === "text") {
      const t = String(seg.text || "").trim();
      if (t) {
        textParts.push(t);
        textCount++;
      }
    } else {
      const picked = pickStickerForCharFromBoundCategory(seg.query, thread, contextHint);
      if (picked) {
        placements.push({
          insertAfterSeg: textCount > 0 ? textCount - 1 : -1,
          url: picked.url,
          description: picked.description
        });
      }
    }
  }

  const keptJoined = textParts.join("|||");
  const last = placements.length ? placements[placements.length - 1] : null;
  const picked = last ? { url: last.url, description: last.description } : null;
  return { keptJoined, placements, picked };
}

/**
 * @param {unknown[]} next
 * @param {{ keptJoined?: string, picked?: { url: string, description: string } | null, placements?: { insertAfterSeg: number, url: string, description: string }[] }} layout
 * @param {Record<string, unknown>} entry
 * @param {string} roundSurface
 * @param {boolean} charLockLive
 */
function applyAssistantStickerLayoutToLogEntry(next, layout, entry, roundSurface, charLockLive) {
  if (charLockLive || roundSurface === "offline") return;
  const picked = layout.picked;
  const placements = Array.isArray(layout.placements) ? layout.placements : [];
  const kept = String(layout.keptJoined || "").trim();
  if (!picked && !placements.length) return;
  if (!kept) {
    const stEnt = {
      role: "assistant",
      at: Date.now(),
      content: "",
      sticker: { url: picked.url, description: picked.description }
    };
    tagAssistantEntryDmSurface(stEnt, roundSurface);
    const anchorIdx = next.indexOf(entry);
    if (anchorIdx >= 0) next.splice(anchorIdx + 1, 0, stEnt);
    else next.push(stEnt);
    return;
  }
  if (placements.length) {
    entry.stickerPlacements = placements.map((p) => ({
      insertAfterSeg: Number(p.insertAfterSeg),
      url: String(p.url || ""),
      description: String(p.description || "")
    }));
    if (entry.sticker) delete entry.sticker;
    const stripped = assistantDisplayTextWithoutStickerDirectives(String(entry.content || ""));
    const nextContent = kept || stripped;
    if (nextContent) entry.content = nextContent;
  }
}

function extractStickerTokensFromSegment(seg, queryRef) {
  let s = String(seg || "").trim();
  if (!s) return "";
  let guard = 0;
  while (s && guard++ < 12) {
    const embed = s.match(RE_STICKER_CMD_EMBED);
    if (embed) {
      const before = String(embed[1] || "").trim();
      const kw = String(embed[2] || "").trim();
      const after = String(embed[3] || "").trim();
      if (queryRef.q === null) queryRef.q = kw;
      s = [before, after].filter(Boolean).join(" ").replace(/\s+/g, " ").trim();
      continue;
    }
    const wholeColon = s.match(RE_STICKER_CMD_WHOLE_COLON);
    if (wholeColon) {
      if (queryRef.q === null) queryRef.q = String(wholeColon[1] || "").trim();
      return "";
    }
    const wholeBare = s.match(RE_STICKER_CMD_WHOLE_BARE);
    if (wholeBare) {
      if (queryRef.q === null) queryRef.q = String(wholeBare[1] || "").trim();
      return "";
    }
    break;
  }
  return s;
}

/**
 * 从合并后的 lines 剥离表情包指令。
 * `query === null`：本轮 lines 无任何表情包指令；`query === ""`：有指令但无关键词。
 */
function extractStickerCommandFromAssistantReply(linesJoined) {
  const parts = String(linesJoined || "")
    .split(/\|\|\|/)
    .map((s) => String(s).trim())
    .filter(Boolean);
  /** @type {{ q: string | null }} */
  const queryRef = { q: /** @type {string | null} */ (null) };
  const kept = [];
  for (const rawPart of parts) {
    const rest = extractStickerTokensFromSegment(rawPart, queryRef);
    if (rest) kept.push(rest);
  }
  return { keptJoined: kept.join("|||"), query: queryRef.q };
}

/**
 * 开启翻译时 repair 可能改写 lines：从接口原始正文再识别【表情包】声明。
 * @returns {string | null} `null` 未声明；`""` 裸发表情；否则为关键词。
 */
function extractStickerDirectiveHintFromAssistantRaw(rawReply) {
  const s = String(rawReply ?? "");
  if (!s.trim()) return null;
  const colonRe = new RegExp(RE_STICKER_CMD_FIND_COLON.source, "g");
  let kw = /** @type {string | null} */ (null);
  let m;
  while ((m = colonRe.exec(s)) !== null) kw = String(m[1] || "").trim();
  if (kw !== null) return kw;
  if (RE_STICKER_CMD_HAS_BARE.test(s)) return "";
  return null;
}

/**
 * 合并 lines 里的【表情包】指令与 JSON 可选 stickerKeyword / sendSticker，再在表情包库里选图。
 * @param {string} replyJoined
 * @param {ReturnType<typeof parseChatAssistantPayload>} parsed
 * @param {unknown} thread
 * @param {{ quiet?: boolean; contextHint?: string; rawAssistantReply?: string }} [opts]
 */
function extractAssistantStickerPick(replyJoined, parsed, thread, opts) {
  const layout = resolveAssistantStickerLayout(replyJoined, parsed, thread, opts);
  return {
    keptJoined: layout.keptJoined,
    picked: layout.picked,
    placements: layout.placements
  };
}

