/* 装扮页 JSON 导入/导出 */
const WARDROBE_CHAT_CSS_SNIPPET_FORMAT = "xxj-wardrobe-chat-surface-snippet";
const WARDROBE_CHAT_CSS_SNIPPET_VERSION = 2;

/** @param {string} defaultBase 不含 .json；返回 null 表示用户取消 */
function wardrobePromptJsonBasename(defaultBase) {
  const raw = window.prompt("文件名（可改；不必写 .json，取消则不导出）", defaultBase);
  if (raw == null) return null;
  let s = String(raw).trim().replace(/\.json$/i, "");
  s = s.replace(/[/\\?%*:|"<>#\u0000-\u001f]/g, "_").trim();
  if (!s) s = defaultBase;
  return s.length > 180 ? s.slice(0, 180) : s;
}

function fillWardrobeChatCssEditorOnly(css) {
  const ta = document.getElementById("ward-chat-css-input");
  if (!(ta instanceof HTMLTextAreaElement)) {
    return { ok: false, err: "样式输入框不可用" };
  }
  ta.value = String(css ?? "");
  scheduleWardrobeChatCssPreviewUpdate();
  return { ok: true };
}

function exportWardrobeChatCssSnippetJson() {
  const draft = stashWardrobeEditorIntoBundleDraft();
  const kind = getWardrobeChatCssEditKind();
  const payload = {
    format: WARDROBE_CHAT_CSS_SNIPPET_FORMAT,
    version: WARDROBE_CHAT_CSS_SNIPPET_VERSION,
    templateKind: kind,
    activeKind: draft.activeKind,
    classicCss: draft.classicCss,
    glassCss: draft.glassCss,
    css:
      kind === CHAT_UI_CSS_PRESET_KIND_GLASS ? draft.glassCss : draft.classicCss
  };
  const ts = new Date().toISOString().replace(/[:.]/g, "-").slice(0, 19);
  const base = wardrobePromptJsonBasename(
    `没心机-密谈壳-${chatUiCssPresetKindLabel(kind)}-${ts}`
  );
  if (base == null) return;
  downloadJson(`${base}.json`, payload);
  showToast(`已导出 JSON（${chatUiCssPresetKindLabel(kind)} + 双槽备份）`);
}

function applyWardrobeChatCssSnippetFromParsed(obj) {
  if (typeof obj === "string") return fillWardrobeChatCssEditorOnly(obj);
  if (!obj || typeof obj !== "object") return { ok: false, err: "无效数据" };
  const o = /** @type {Record<string, unknown>} */ (obj);
  if (o.format === WARDROBE_CHAT_CSS_SNIPPET_FORMAT && Number(o.version) === 2) {
    const draft = readGlobalChatSurfaceBundleFromKv();
    if (typeof o.classicCss === "string") draft.classicCss = o.classicCss;
    if (typeof o.glassCss === "string") draft.glassCss = o.glassCss;
    const activeKind =
      String(o.activeKind || o.templateKind || "").trim() === CHAT_UI_CSS_PRESET_KIND_GLASS
        ? CHAT_UI_CSS_PRESET_KIND_GLASS
        : CHAT_UI_CSS_PRESET_KIND_CLASSIC;
    draft.activeKind = activeKind;
    wardrobeChatCssBundleDraft = draft;
    setWardrobeChatCssEditKind(
      String(o.templateKind || "").trim() === CHAT_UI_CSS_PRESET_KIND_GLASS
        ? CHAT_UI_CSS_PRESET_KIND_GLASS
        : activeKind,
      { skipStash: true }
    );
    return { ok: true };
  }
  const css =
    typeof o.css === "string"
      ? o.css
      : typeof o.globalCss === "string"
        ? o.globalCss
        : null;
  if (css !== null) {
    const kind = inferChatUiCssPresetKindFromCss(css, CHAT_UI_CSS_PRESET_KIND_CLASSIC);
    setWardrobeChatCssEditKind(kind);
    const r = fillWardrobeChatCssEditorOnly(css);
    if (!r.ok) return r;
    stashWardrobeEditorIntoBundleDraft();
  }
  const offlineCss = typeof o.offlineCss === "string" ? o.offlineCss.trim() : "";
  if (offlineCss) {
    const ta = document.getElementById("ward-chat-css-input");
    if (!(ta instanceof HTMLTextAreaElement)) return { ok: false, err: "样式输入框不可用" };
    const cur = String(ta.value || "").trim();
    ta.value = cur ? `${cur}\n\n${offlineCss}` : offlineCss;
    stashWardrobeEditorIntoBundleDraft();
    scheduleWardrobeChatCssPreviewUpdate();
  }
  if (css !== null || offlineCss) return { ok: true };
  return { ok: false, err: "无法识别的 JSON 结构" };
}

async function importWardrobeChatCssFromDocxArrayBuffer(buf) {
  const mammoth = /** @type {{ extractRawText?: (o: { arrayBuffer: ArrayBuffer }) => Promise<{ value: string }> }} */ (
    window.mammoth
  );
  if (!mammoth || typeof mammoth.extractRawText !== "function") {
    return { ok: false, err: "Word 解析库未加载" };
  }
  try {
    const res = await mammoth.extractRawText({ arrayBuffer: buf });
    const text = String(res?.value || "").replace(/\u00a0/g, " ").trim();
    if (!text) return { ok: false, err: "文档无正文" };
    return fillWardrobeChatCssEditorOnly(text);
  } catch {
    return { ok: false, err: "无法解析 docx" };
  }
}

